  ui_story_1011_10110101_177_dialog_content = "だが、たとえ1匹だろうと第二軍団に近づいた暗鬼がいれば…\nこの俺が必ず、目に物見せてやる！",
  ui_story_1011_10110201_1_dialog_content = "PlayerName、ソラヴァンの進行方向、\n少しおかしくない？",
  ui_story_1011_10110201_15X1_dialog_content = "この方向だと、\nいつも停まってる空き地じゃないみたいだけど？",
  ui_story_1011_10110201_15X2_dialog_content = "うん、その通りだよ。",
  ui_story_1011_10110201_15X3_dialog_content = "自動操縦機能を調べたけど、\n今回の目的地は、天空ノ谷の別の方向にある白い塔になってるんだ。",
  ui_story_1011_10110201_15X4_dialog_content = "白い塔？",
  ui_story_1011_10110201_15X5_dialog_content = "「巨像整備基地」がそこにあるということ？",
  ui_story_1011_10110201_15X6_dialog_content = "自動操縦で設定されたってことは、\nそうなんだと思う。",
  ui_story_1011_10110201_15X7_dialog_content = "その白い塔について、\nあなたたちは何か知っているの？",
  ui_story_1011_10110201_15X8_dialog_content = "ううん…詳しくは知らないわ。\n天空ノ谷に関する記録は、啓光にはそう多くないし…",
  ui_story_1011_10110201_15X9_dialog_content = "私の知ってる限り、あの白い塔は\nごく普通の白い石で作られた、ただの建築物よ。",
  ui_story_1011_10110201_15X10_dialog_content = "僕が知ってることも、\nバイスと大差ないんだ。",
  ui_story_1011_10110201_15X11_dialog_content = "ソラヴァンの天空ノ谷に関する資料でも、\n簡単な紹介程度だし…",
  ui_story_1011_10110201_15X12_dialog_content = "もうちょっとがんばって思い出せない？",
  ui_story_1011_10110201_15X13_dialog_content = "空の末裔が知ってることが、\n啓光より少ないなんてはずないわ。",
  ui_story_1011_10110201_15X14_dialog_content = "がんばってみるよ…",
  ui_story_1011_10110201_16_dialog_content = "あの白い塔、どこか見覚えがあるんだ。",
  ui_story_1011_10110201_17_dialog_content = "ソラヴァンが保存しているデータベースの中に\n記録があったような…",
  ui_story_1011_10110201_18_dialog_content = "あ、思い出した！",
  ui_story_1011_10110201_19_dialog_content = "確か、昔はその辺りに空の末裔がいくらか住んでいたんだけど、\nその後、今の集落に移住して来た、って。",
  ui_story_1011_10110201_20_dialog_content = "その場所でいちばん目を引く建物は、\n何もない、廃墟になった白い塔…",
  ui_story_1011_10110201_21_dialog_content = "だから、白い塔以外には何もない、はず。",
  ui_story_1011_10110201_22_dialog_content = "他には何もない？そんなはずないでしょ…",
  ui_story_1011_10110201_22X1_dialog_content = "「巨像整備基地」っていう名前から想像する限り、\n超大型の遺跡のはずよ。",
  ui_story_1011_10110201_22X2_dialog_content = "ならば…空の末裔が故意に何か隠していた？",
  ui_story_1011_10110201_22X3_dialog_content = "！？",
  ui_story_1011_10110201_23_dialog_content = "何が起こったの！？",
  ui_story_1011_10110201_24_dialog_content = "何ごと？",
  ui_story_1011_10110201_25_dialog_content = "<color=#e8d9bb>「警告、暗鬼の侵入を検知しました」</color>",
  ui_story_1011_10110201_26_dialog_content = "暗鬼！？",
  ui_story_1011_10110201_27_dialog_content = "どういうことなの？\n普通の暗鬼がソラヴァンに追いつけるはずはない。",
  ui_story_1011_10110201_28_dialog_content = "こんなにたくさんの暗鬼が集団で攻撃してくるなんて、\nきっと待ち伏せよ！",
  ui_story_1011_10110201_29_dialog_content = "グオオ――",
  ui_story_1011_10110201_30_dialog_content = "ブリッジまで入られるなんて！？",
  ui_story_1011_10110201_31_dialog_content = "阻止するわよ！",
  ui_story_1011_10110201_32_dialog_content = "暗鬼を近づけさせてはダメ！",
  ui_story_1011_10110201_33_dialog_content = "気を付けて！待ち伏せなんて戦術、\n使える暗鬼はそう多くない…",
  ui_story_1011_10110201_34_dialog_content = "きっと裏で指揮してるヤツがいる！",
  ui_story_1011_10110201_35_dialog_content = "私は左を。バイス、残りはあなたに任せるわ。",
  ui_story_1011_10110201_36_dialog_content = "PlayerName、サポートを！",
  ui_story_1011_10110201_37_dialog_content = "任せて！",
  ui_story_1011_10110202_1_dialog_content = "グオオ――",
  ui_story_1011_10110202_2_dialog_content = "行かせないわよ！",
  ui_story_1011_10110202_3_dialog_content = "グォォ！",
  ui_story_1011_10110202_4_dialog_content = "一体、どれだけの暗鬼が待ち伏せを…？",
  ui_story_1011_10110202_5_dialog_content = "どうして次から次へと！",
  ui_story_1011_10110202_6_dialog_content = "これ以上退けないわ！",
  ui_story_1011_10110202_7_dialog_content = "この先は制御装置よ！",
  ui_story_1011_10110202_8_dialog_content = "グォォ！！！",
  ui_story_1011_10110202_9_dialog_content = "バイス、危ない！",
  ui_story_1011_10110202_10_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_1011_10110202_11_dialog_content = "大変だ、暗鬼が制御装置に！",
  ui_story_1011_10110202_12_dialog_content = "えっ！？",
  ui_story_1011_10110202_13_dialog_content = "墜落する！！",
  ui_story_1011_10110202_14_dialog_content = "うわあぁ！",
  ui_story_1011_10110202_15_dialog_content = "丈夫なものにつかまるのよ！",
  ui_story_1011_10110202_16_dialog_content = "PlayerName、私の手につかまって！",
  ui_story_1011_10110202_17_dialog_content = "『巨像が、墜落した…！？』",
  ui_story_1011_10110202_18_dialog_content = "『役立たずどもが！！！』",
  ui_story_1011_10110202_19_dialog_content = "『も、申し訳ございません！』",
  ui_story_1011_10110202_20_dialog_content = "『私は巨像と空の末裔を奪えと命令したのだ！』",
  ui_story_1011_10110202_21_dialog_content = "『殺せとは言っていない！』",
  ui_story_1011_10110202_22_dialog_content = "『何とか救出します！』",
  ui_story_1011_10110202_23_dialog_content = "『追いかけろ、捕まえるのだ！逃がすな！』",
  ui_story_1011_10110202_24_dialog_content = "『次はないぞ！』",
  ui_story_1011_10110202_25_dialog_content = "『はっ！！』",
  ui_story_1011_10110202_26_dialog_content = "『ま、あなたのおつむじゃ、指揮なんて無理よね。』",
  ui_story_1011_10110202_27_dialog_content = "『ノラ、口をはさむな。』",
  ui_story_1011_10110202_28_dialog_content = "『言ったでしょ、これは私の研究。\n手を出さないで。』",
  ui_story_1011_10110202_29_dialog_content = "『あなたも、能無しの手下も、\n今や私の研究にとって阻害事項でしかないわ。』",
  ui_story_1011_10110202_30_dialog_content = "『外野でじっとしてなさい。』",
  ui_story_1011_10110202_31_dialog_content = "『ちょうど啓光のヤツらがこの先の道を塞いでるから、\nあなたたちは、それでも引き留めておいて。』",
  ui_story_1011_10110202_32_dialog_content = "『これ以上邪魔にならないで。』",
  ui_story_1011_10110202_33_dialog_content = "『ノラ…』",
  ui_story_1011_10110202_34_dialog_content = "『いつか必ず、その傲慢の代償を払うことになるぞ。』",
  ui_story_1011_10110202_40X1_dialog_content = "全員、よく聞け！\n大元帥が俺たち第二軍団に防御を固めろと言うなら――",
  ui_story_1011_10110202_40X2_dialog_content = "俺たちが教えてやろうじゃないか！\n鉄壁の守りってのが一体どんなものかを！",
  ui_story_1011_10110202_40X3_dialog_content = "お前は隊を率いて、防衛設備を全部チェックしろ！\n破損箇所はすぐに修復して、重要な部分は、さらに固めろ！",
  ui_story_1011_10110202_40X4_dialog_content = "暗鬼が山になって来ようが、大地一面を埋めつくそうが、\nこの陣地が微動だにしちゃならねえ！",
  ui_story_1011_10110202_40X5_dialog_content = "了解！",
  ui_story_1011_10110202_40X6_dialog_content = "それから、お前たちは今から見張りを交替しろ。",
  ui_story_1011_10110202_40X7_dialog_content = "これから見張りは全部、6時間交代だ。\n今見張りに付いてる奴らをゆっくり休ませろ。",
  ui_story_1011_10110202_40X8_dialog_content = "勤務中はその目ん玉をしっかり開いて、\n暗鬼の動向を見逃すな！",
  ui_story_1011_10110202_40X9_dialog_content = "了解！",
  ui_story_1011_10110202_40X10_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_1011_10110202_40X11_dialog_content = "何だ！？",
  ui_story_1011_10110202_40X12_dialog_content = "あれは…小僧のソラヴァンか！？",
  ui_story_1011_10110202_40X13_dialog_content = "なんだって、あんな低空飛行してやがんだ…？",
  ui_story_1011_10110202_40X14_dialog_content = "巨像の上にしがみついてる、\n黒い豆粒みてぇのは…暗鬼か！？",
  ui_story_1011_10110202_40X15_dialog_content = "あいつ、何してやがんだ！？\n襲撃されたか！？",
  ui_story_1011_10110202_40X16_dialog_content = "報告！！",
  ui_story_1011_10110202_40X17_dialog_content = "話せ！",
  ui_story_1011_10110202_40X18_dialog_content = "偵察兵が暗鬼の異常な動きを観察しています。\nやつらは今、天空ノ谷の方角へ集結中です！",
  ui_story_1011_10110202_40X19_dialog_content = "通常の暗鬼以外にも、\n上級暗鬼数匹の痕跡が確認されています！",
  ui_story_1011_10110202_40X20_dialog_content = "確認されているのは…ノラともう1匹、\n名称不明の上級暗鬼がいます！",
  ui_story_1011_10110202_40X21_dialog_content = "ノラ…",
  ui_story_1011_10110202_40X22_dialog_content = "こんな時に、天空の谷で何の用だ？",
  ui_story_1011_10110202_40X23_dialog_content = "いや、違うな…",
  ui_story_1011_10110202_40X24_dialog_content = "空の末裔の小僧、暗鬼、それからノラ…",
  ui_story_1011_10110202_40X25_dialog_content = "全員同時に天空ノ谷へ向かうだなんて、\nこりゃ何か、大変なことが起こるに違いねえ。",
  ui_story_1011_10110202_40X26_dialog_content = "命令だ！第二軍団はこれより厳戒態勢に入る！",
  ui_story_1011_10110202_40X27_dialog_content = "偵察兵1部隊を割いて、\n天空ノ谷の動向を全力で監視しろ！",
  ui_story_1011_10110202_40X28_dialog_content = "了解！",
  ui_story_1011_10110202_40X29_dialog_content = "それから――",
  ui_story_1011_10110202_40X30_dialog_content = "<color=#e8d9bb>ダダン…ダダダダ…</color>",
  ui_story_1011_10110202_40X31_dialog_content = "…天空ノ谷の方角か？",
  ui_story_1011_10110202_40X32_dialog_content = "俺たちの部隊が暗鬼と交戦してんのか？",
  ui_story_1011_10110202_40X33_dialog_content = "は、はい！そのようです！",
  ui_story_1011_10110202_40X34_dialog_content = "ノラ率いる暗鬼の部隊に遭遇したとの報告です！",
  ui_story_1011_10110202_40X35_dialog_content = "現在暗鬼と交戦中！\nですが、ノラが戦場を放棄し、天空ノ谷へ単独で向かったとのこと！",
  ui_story_1011_10110202_40X36_dialog_content = "一体何を企んでるかは知らねえが、\nいい事じゃねえのは確かだ。",
  ui_story_1011_10110202_40X37_dialog_content = "このままじゃ、\n遅かれ早かれまずいことになる…",
  ui_story_1011_10110202_40X38_dialog_content = "ヤツらの好きにはさせねえ！",
  ui_story_1011_10110202_40X39_dialog_content = "各部隊に伝達しろ！\n陣地を固め、一歩も退くな！",
  ui_story_1011_10110202_40X40_dialog_content = "啓光の大罪人ノラは、\n俺が直々にとっ捕まえてやる！",
  ui_story_1011_10110202_40X41_dialog_content = "しかし軍団長、上の命令は…",
  ui_story_1011_10110202_40X42_dialog_content = "よく聞け、戦機ってのは一瞬なんだ。",
  ui_story_1011_10110202_40X43_dialog_content = "ノラはきっと何か企んでやがる。\n今のうちに止めなきゃならねえ。",
  ui_story_1011_10110202_40X44_dialog_content = "企みが成功してからじゃ、\n何もかも手遅れなんだよ。",
  ui_story_1011_10110202_40X45_dialog_content = "俺の独断で何か損失が出て、\nレインハトと上が何か言ってきたら、こう伝えろ――",
  ui_story_1011_10110202_40X46_dialog_content = "すべての責任は、第二軍団長のバートンにあるってな！",
  ui_story_1011_10110202_40X47_dialog_content = "分かったか？",
  ui_story_1011_10110202_40X48_dialog_content = "は、はい！",
  ui_story_1011_10110202_40X49_dialog_content = "PlayerName…無事だといいんだが。",
  ui_story_1011_10110202_40X50_dialog_content = "まあ、あいつは運のいいヤツだ。\nきっと大丈夫だろう。",
  ui_story_1011_10110202_40X51_dialog_content = "ちょっくら手を貸してやるとするか…",
  ui_story_1011_10110401_1_dialog_content = "<anim type=Shake><size=50>うわああああ――！！</size></anim>",
  ui_story_1011_10110401_2_dialog_content = "墜ちる！！！",
  ui_story_1011_10110401_3_dialog_content = "PlayerName、方向をしっかり制御して！",
  ui_story_1011_10110401_4_dialog_content = "塔の根元に空間があるわ！！\nソラヴァンを滑り込ませて！",
  ui_story_1011_10110401_7X1_dialog_content = "無理だよ！",
  ui_story_1011_10110401_7X2_dialog_content = "制御装置が壊されてる！\nソラヴァンを制御できない！",
  ui_story_1011_10110401_7X3_dialog_content = "だったら、どこかに\nしっかりつかまっていなさい！",
  ui_story_1011_10110401_7X4_dialog_content = "それから…",
  ui_story_1011_10110401_7X5_dialog_content = "塔に直撃しないことを祈るしかないわね！！",
  ui_story_1011_10110401_7X6_dialog_content = "うっ…！！！",
  ui_story_1011_10110401_8_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_1011_10110401_9_dialog_content = "<color=#e8d9bb>ガラガラ…</color>",
  ui_story_1011_10110401_10_dialog_content = "ゲホ、ゲホッ！すごい土ぼこりだ…",
  ui_story_1011_10110401_11_dialog_content = "私たち…生きてるの？",
  ui_story_1011_10110401_12_dialog_content = "ええ…間違いなく。",
  ui_story_1011_10110401_13_dialog_content = "着陸できたようね。",
  ui_story_1011_10110401_14_dialog_content = "全員無事？ケガはない？",
  ui_story_1011_10110401_15_dialog_content = "僕は大丈夫。少しクラクラするだけ。",
  ui_story_1011_10110401_16_dialog_content = "わ、私も…大丈夫よ。",
  ui_story_1011_10110401_17_dialog_content = "…それで、ここは塔の根元にあった場所？",
  ui_story_1011_10110401_18_dialog_content = "そのようね。\n白い塔の真下に見えた空間に滑り込めたようだわ。",
  ui_story_1011_10110401_19_dialog_content = "<color=#e8d9bb>「目的地――巨像整備基地、駐機場に到着しました」</color>",
  ui_story_1011_10110401_20_dialog_content = "<color=#e8d9bb>「基地制御システムとの接続を開始します」</color>",
  ui_story_1011_10110401_21_option_content = "駐機場？",
  ui_story_1011_10110401_22_dialog_content = "この空間が…駐機場？",
  ui_story_1011_10110401_23_dialog_content = "なるほど、広いわけね。\n巨像が何機も入る余裕がありそうだわ。",
  ui_story_1011_10110401_24_dialog_content = "駐機場に入れたなら、\n墜落とは言わない…のかな？",
  ui_story_1011_10110401_25_dialog_content = "グォ……",
  ui_story_1011_10110401_26_dialog_content = "…",
  ui_story_1011_10110401_27_dialog_content = "…",
  ui_story_1011_10110401_28_dialog_content = "暗鬼だ！",
  ui_story_1011_10110401_29_dialog_content = "グオォォ！！！",
  ui_story_1011_10110401_30_dialog_content = "早く、抑えて！",
  ui_story_1011_10110401_31_dialog_content = "きっとまだ、\nたくさんの暗鬼がソラヴァンの中に残ってる…",
  ui_story_1011_10110401_32_dialog_content = "好き放題させておくわけにはいかない！",
  ui_story_1011_10110402_1_dialog_content = "ふぅ…これで最後の1匹よね？",
  ui_story_1011_10110402_2_dialog_content = "見える範囲内には、もういないわ。",
  ui_story_1011_10110402_3_dialog_content = "他に敵は感知できないよ。\nとりあえず、少し休憩できそうだ…",
  ui_story_1011_10110402_4_dialog_content = "ソラヴァンの状態を見てみるね。",
  ui_story_1011_10110402_5_dialog_content = "<color=#e8d9bb>「巨像整備基地制御システムと接続中…」</color>",
  ui_story_1011_10110402_6_dialog_content = "<color=#e8d9bb>「エラー。駐機場と中央制御システムの接続が中断されました」</color>",
  ui_story_1011_10110402_7_dialog_content = "<color=#e8d9bb>「中央制御システムに向かい、手動で接続を修復してください」</color>",
  ui_story_1011_10110402_8_dialog_content = "中央制御システム…？",
  ui_story_1011_10110402_9_dialog_content = "塔の中にあるのかな？",
  ui_story_1011_10110402_10_dialog_content = "この塔に関するデータの中で、\n関係のありそうなことは書いてなかった？",
  ui_story_1011_10110402_11_dialog_content = "たぶんないと思う…",
  ui_story_1011_10110402_12_dialog_content = "画像データを引っ張り出して\n一通り見てもいいけど、時間はかかっちゃうね。",
  ui_story_1011_10110402_13_dialog_content = "いずれにしても、データだけでは不十分よ。\n実物を見ておかないと。",
  ui_story_1011_10110402_14_dialog_content = "それもそうだね。\nじゃあ、降りて見に行ってみよう。",
  ui_story_1011_10110402_15_dialog_content = "さあ、出発よ！",
  ui_story_1011_10110402_16_dialog_content = "ずいぶん、がらんとしてるのね…",
  ui_story_1011_10110402_17_dialog_content = "話し声がきれいに反響してくるわ。",
  ui_story_1011_10110402_18_dialog_content = "データによると、ここは昔、\n空の末裔の居住地だったって書いてあったけど…",
  ui_story_1011_10110402_19_dialog_content = "今は家らしいものの1件も見当たらないね。\n人が生活してたとは思えないなぁ。",
  ui_story_1011_10110402_20_dialog_content = "ここから人がいなくなって大分経ってるから…",
  ui_story_1011_10110402_21_dialog_content = "その時は痕跡があったとしても、\n時間の経過でなくなってるでしょうね。",
  ui_story_1011_10110402_22_dialog_content = "でも、空の末裔が昔住んでた所に駐機場があるなんて、\n言われるまで考えもしなかったよ。",
  ui_story_1011_10110402_23_dialog_content = "当時の人たちはここに巨像を停めて、\n一緒に暮らしてたのかな？",
  ui_story_1011_10110402_24_dialog_content = "なんだかキャンプみたいね！",
  ui_story_1011_10110402_25_dialog_content = "ここに家屋らしき建物が見当たらないのは、\n巨像を住みかにしていたからかも知れないわね。",
  ui_story_1011_10110402_26_dialog_content = "それなら、この地を離れる時は\n巨像を動かすだけで済んだでしょう。",
  ui_story_1011_10110402_27_dialog_content = "でも、当時の人たちが巨像をここに停めてたってことは、\nここが駐機場だってことは普通に知られてたわけよね？",
  ui_story_1011_10110402_28_dialog_content = "それなら、近くに<color=#FFB400>「巨像整備基地」</color>が\nあることだって、知ってて当然のはず…",
  ui_story_1011_10110402_29_dialog_content = "なんでどこにも一切、情報が残ってないのかしら？",
  ui_story_1011_10110402_30_dialog_content = "確かに、妙な話ね。\n探索の時は、十分に気を付けましょう。",
  ui_story_1011_10110402_31_dialog_content = "そうね。",
  ui_story_1011_10110402_32_dialog_content = "情報も痕跡も残ってない…\n何もない所から突然現れた、とか？",
  ui_story_1011_10110402_33_dialog_content = "近くには巨像を整備するための\n設備や部屋はありそうもないね。",
  ui_story_1011_10110402_34_dialog_content = "分厚く積もったホコリ以外には、何もないわ。",
  ui_story_1011_10110402_35_dialog_content = "中央制御システムっていうのも、\nこの辺りにはなさそうね。",
  ui_story_1011_10110402_36_dialog_content = "なら、上にあるのかしら？",
  ui_story_1011_10110402_37_dialog_content = "PlayerName、この塔の上部には何がある？",
  ui_story_1011_10110402_38_dialog_content = "ええと…",
  ui_story_1011_10110402_39_dialog_content = "ソラヴァンのデータによれば、空の末裔たちはかつて、\nこの白い塔の中で暮らしていた時代があったんだ。",
  ui_story_1011_10110402_40_dialog_content = "でも、その後、今の僕らが知ってるあの場所へ移った。",
  ui_story_1011_10110402_41_dialog_content = "昔の空の末裔たちも、塔の上部も含めて、\nここを詳しく調べたことがあるみたいだけど…",
  ui_story_1011_10110402_42_dialog_content = "外側と同じように紋様が一面に施された白い石以外、\n何も見つからなかったみたいだね。",
  ui_story_1011_10110402_43_dialog_content = "上にも何もないの…？",
  ui_story_1011_10110402_44_dialog_content = "そもそもの座標が間違ってたんじゃないかな？",
  ui_story_1011_10110402_45_dialog_content = "それはないと思うわ。地質変動で建物の位置がズレたとしても、\nもとの座標からそこまでかけ離れることはないもの。",
  ui_story_1011_10110402_46_dialog_content = "塔の上の方に何もないなら…",
  ui_story_1011_10110402_47_dialog_content = "下は？",
  ui_story_1011_10110402_48_dialog_content = "下？",
  ui_story_1011_10110402_49_dialog_content = "つまり…カナン城のように、\nここにも地下空間が隠されているということ？",
  ui_story_1011_10110402_50_dialog_content = "可能性はあるわ！",
  ui_story_1011_10110402_51_dialog_content = "でも、ここはあちこち倒壊してるし、地図もないよ。\nどうやって入口を探すの？",
  ui_story_1011_10110402_52_dialog_content = "まさか、地面を全部掘り返すつもり？",
  ui_story_1011_10110402_53_dialog_content = "数年かけても、簡単には通路など見つからないでしょうね。",
  ui_story_1011_10110402_54_dialog_content = "通路…シェルター…見つける方法…",
  ui_story_1011_10110402_55_dialog_content = "そうだ！",
  ui_story_1011_10110402_56_dialog_content = "大元帥がくださった物資の中に、\n確か金属探知機があったわよね。",
  ui_story_1011_10110402_57_dialog_content = "地下に基地が存在するなら、\n構造物には、高い確率で金属が使われているはずよ。",
  ui_story_1011_10110402_58_dialog_content = "まずは金属探知機で通路のありそうな所を探して、\nそれから掘ってみましょう。",
  ui_story_1011_10110402_59_dialog_content = "…そこまで前もって予測していた、ということ…？",
  ui_story_1011_10110402_60_dialog_content = "啓光連邦の大元帥…聞いていた通り、\n油断ならないようね。",
  ui_story_1011_10110402_60X1_dialog_content = "他の補給物資も、爆薬と一緒に持ってきて。",
  ui_story_1011_10110402_60X2_dialog_content = "地下に埋まった遺跡を探すなら、きっと役に立つわ。",
  ui_story_1011_10110402_61_dialog_content = "そうするしかなさそうだね。",
  ui_story_1011_10110402_62_dialog_content = "すぐに入口が見つかるといいけど…",
  ui_story_1011_10110402_63_dialog_content = "<color=#e8d9bb>白い塔の外、某所</color>",
  ui_story_1011_10110402_64_dialog_content = "あの塔、思った通り。\n見た目ほど単純じゃないようね。",
  ui_story_1011_10110402_65_dialog_content = "空の末裔に握らせた鍵の導きがなければ…\n本当に、中に隠された秘密は永遠に発見しようがないのかもしれないわね。",
  ui_story_1011_10110402_66_dialog_content = "でも、その秘密を実験データにする時がきた。",
  ui_story_1011_10110402_66X1_dialog_content = "逃げんじゃねぇ！",
  ui_story_1011_10110402_66X2_dialog_content = "グオオォ…",
  ui_story_1011_10110402_66X3_dialog_content = "軍団長、近辺の暗鬼はすでに掃討できました！",
  ui_story_1011_10110402_66X4_dialog_content = "よし、今のうちに守りを固めろ！",
  ui_story_1011_10110402_66X5_dialog_content = "了解！",
  ui_story_1011_10110402_66X6_dialog_content = "ここの暗鬼ども、\nどいつもこいつもザコばかりだ…",
  ui_story_1011_10110402_66X7_dialog_content = "ノラのヤツ、一体どこへ行った？",
  ui_story_1011_10110402_66X8_dialog_content = "もう天空ノ谷に入っちまったのか？",
  ui_story_1011_10110402_66X9_dialog_content = "これだけの数の暗鬼も、ノラも、\nPlayerNameを狙って集まってるってのか？",
  ui_story_1011_10110402_66X10_dialog_content = "大した見ものじゃねぇか…",
  ui_story_1011_10110402_66X11_dialog_content = "ノラが一体何を隠してやがるのか、\n見せてもらわないとな。",
  ui_story_1011_10110501_1_dialog_content = "使い道のない空き箱…",
  ui_story_1011_10110501_2_dialog_content = "これは、いらない…",
  ui_story_1011_10110501_3_dialog_content = "字の読めなくなった本…",
  ui_story_1011_10110501_4_dialog_content = "これも、いらない…",
  ui_story_1011_10110501_5_dialog_content = "中身の分からない缶詰…",
  ui_story_1011_10110501_6_dialog_content = "…これも、捨てとこう…",
  ui_story_1011_10110501_7_dialog_content = "待って、もったいないわよ！",
  ui_story_1011_10110501_8_dialog_content = "ちょっと…その缶詰、\nどれだけ前のものか、分かっているの？",
  ui_story_1011_10110501_9_dialog_content = "捨てておきなさいよ…",
  ui_story_1011_10110501_10_dialog_content = "…はあ…",
  ui_story_1011_10110501_11_dialog_content = "こんなに探してるのに、\n役に立たないものしか見つからないなんて…",
  ui_story_1011_10110501_12_dialog_content = "もう少していねいに探してみましょう。\n見落としがあってはならないわ。",
  ui_story_1011_10110501_13_dialog_content = "そうだね、もう少し探そう。",
  ui_story_1011_10110501_14_dialog_content = "この辺りは、まだ調べてなかったよね。",
  ui_story_1011_10110501_15_dialog_content = "近くに散らばってるのは…全部白い石だね。\n白い塔の上の方から落ちてきたみたい？",
  ui_story_1011_10110501_16_dialog_content = "何か埋もれてないかな…",
  ui_story_1011_10110501_17_dialog_content = "金属探知機をかけてみよう。",
  ui_story_1011_10110501_18_dialog_content = "<color=#e8d9bb>ピピピ！</color>",
  ui_story_1011_10110501_19_dialog_content = "反応があった！？",
  ui_story_1011_10110501_20_dialog_content = "石の中かな？",
  ui_story_1011_10110501_21_option_content = "石を叩いてみよう",
  ui_story_1011_10110501_22_dialog_content = "<color=#e8d9bb>トントントン――！</color>",
  ui_story_1011_10110501_23_dialog_content = "中は空洞じゃないみたいだ。\nということは、この後ろかな？",
  ui_story_1011_10110501_24_dialog_content = "うーん、光の差し方が良くないなぁ。\n影になってる場所が多くて…",
  ui_story_1011_10110501_25_dialog_content = "何かあるみたいだけど、よく見えないや。",
  ui_story_1011_10110501_26_dialog_content = "もう少し近づいてみよう、これは…",
  ui_story_1011_10110501_27_dialog_content = "…缶詰の箱を被って、ガラクタのふりをしてる暗鬼！？",
  ui_story_1011_10110501_28_dialog_content = "グォォ――！！！",
  ui_story_1011_10110501_29_dialog_content = "うわぁ！？",
  ui_story_1011_10110501_30_dialog_content = "PlayerName！",
  ui_story_1011_10110501_31_dialog_content = "グォ……",
  ui_story_1011_10110501_32_dialog_content = "あ、危なかった…",
  ui_story_1011_10110501_33_dialog_content = "一体いつの間にこんな所に…？",
  ui_story_1011_10110501_34_dialog_content = "これだけ広いし、死角も多いもの。",
  ui_story_1011_10110501_35_dialog_content = "きっと入口を探してるスキに、\nこっそり近づいてきたんじゃないかしら…",
  ui_story_1011_10110501_36_dialog_content = "グォォ――！",
  ui_story_1011_10110501_37_dialog_content = "大変よ、取り囲まれた！",
  ui_story_1011_10110501_38_dialog_content = "暗鬼が入口から押し寄せて来てるわ！",
  ui_story_1011_10110501_39_dialog_content = "包囲を突破しなきゃ！",
  ui_story_1011_10110501_40_dialog_content = "それはまずい！",
  ui_story_1011_10110501_41_dialog_content = "ここで包囲を抜け出したところで、\n白い塔もソラヴァンも暗鬼に渡すことになっちゃうよ！",
  ui_story_1011_10110501_42_dialog_content = "守り切るしかないわね。\n暗鬼はここで止める！",
  ui_story_1011_10110501_43_dialog_content = "ただ、ここは洞窟と同じよ。\n入口を塞ぐ門はない！",
  ui_story_1011_10110501_44_dialog_content = "門がない…",
  ui_story_1011_10110501_45_dialog_content = "だったら、造ればいい！",
  ui_story_1011_10110501_46_dialog_content = "爆薬を使おう！",
  ui_story_1011_10110501_47_dialog_content = "まさか、入口を爆破して塞ぐつもり！？",
  ui_story_1011_10110501_48_dialog_content = "そうだよ！",
  ui_story_1011_10110501_49_dialog_content = "ここの入口が崩れたって構わないでしょ。\n塔の上の方から出られるだろうし。",
  ui_story_1011_10110501_49X1_dialog_content = "それがダメなら、地下を目指して、\n別の出口を探せばいい！",
  ui_story_1011_10110501_50_dialog_content = "暗鬼にもうここまで侵入されてるんだ。\nとにかく止めて、ソラヴァンと地下遺跡を守らないと！",
  ui_story_1011_10110501_51_dialog_content = "バイスと私で援護するわ。\nPlayerName、スキを狙って入口を爆破しなさい！",
  ui_story_1011_10110501_52_dialog_content = "了解！",
  ui_story_1011_10110501_53_dialog_content = "頼んだよ！",
  ui_story_1011_10110502_1_dialog_content = "グオオ――！！！",
  ui_story_1011_10110502_2_dialog_content = "どきなさい！",
  ui_story_1011_10110502_3_dialog_content = "グォォ――！",
  ui_story_1011_10110502_4_dialog_content = "暗鬼が増えてる。\nこのままじゃ、ソラヴァンに近づくこともできない…",
  ui_story_1011_10110502_5_dialog_content = "入口を爆破するなんて、なおさらだ！",
  ui_story_1011_10110502_6_dialog_content = "目的を果たせなくても、\nまずは包囲を突破しないと。",
  ui_story_1011_10110502_7_dialog_content = "ここで足止めを食らうわけにはいかない！",
  ui_story_1011_10110502_9_dialog_content = "食らいやがれ！！",
  ui_story_1011_10110502_10_dialog_content = "入口の方を見て！あれは――",
  ui_story_1011_10110502_11_dialog_content = "バートン！？",
  ui_story_1011_10110502_12_dialog_content = "どうしてここに！？",
  ui_story_1011_10110502_12X1_dialog_content = "ハハハ…お前らなら無事だと思ってたぜ。",
  ui_story_1011_10110502_12X2_dialog_content = "ずいぶんな数の暗鬼がこっちへ向かってたから、\nおかしいと思って見に来たんだよ。",
  ui_story_1011_10110502_13_dialog_content = "それで、ちょうど通りかかったんだ。\nついでに暗鬼どもをぶっとばして、軽く運動してたってわけさ！",
  ui_story_1011_10110502_14_dialog_content = "お前はお前のやるべきことをやれ！\nここは俺に任せろ！",
  ui_story_1011_10110502_15_dialog_content = "バートン軍団長が暗鬼を足止めしてくれてるわ！\nPlayerName、チャンスよ！",
  ui_story_1011_10110502_16_dialog_content = "バートン、少し離れて！入口を塞ぐよ！",
  ui_story_1011_10110502_17_dialog_content = "塞ぐたって、どうやって？",
  ui_story_1011_10110502_18_dialog_content = "爆破するんだ！",
  ui_story_1011_10110502_19_dialog_content = "爆破するだぁ！？",
  ui_story_1011_10110502_20_dialog_content = "ハハハハ！お前もなかなかイカレてきたな！",
  ui_story_1011_10110502_21_dialog_content = "よし、思いっきり吹っ飛ばしちまえ！！",
  ui_story_1011_10110502_22_dialog_content = "PlayerName、暗鬼の攻撃の勢いが弱まったわ、今のうちよ――！",
  ui_story_1011_10110502_23_dialog_content = "分かった！",
  ui_story_1011_10110502_24_dialog_content = "爆薬はセットしたよ！\nバイス、カレン、離れて！！",
  ui_story_1011_10110502_25_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_1011_10110502_26_dialog_content = "うまくいったの？",
  ui_story_1011_10110502_27_dialog_content = "そのようね。",
  ui_story_1011_10110502_28_dialog_content = "バートンは、まだ外にいるみたいだね？",
  ui_story_1011_10110502_29_dialog_content = "感知を…",
  ui_story_1011_10110502_30_dialog_content = "バートン、大丈夫？ケガはない！？",
  ui_story_1011_10110502_31_dialog_content = "心配いらねえよ、ピンピンしてるぜ！",
  ui_story_1011_10110502_32_dialog_content = "お前らの方は無事か？",
  ui_story_1011_10110502_33_dialog_content = "入口はもう塞げたよ、\nひとまず僕たちは大丈夫！",
  ui_story_1011_10110502_34_dialog_content = "よし…それじゃあ後は、思いっきり暴れるだけだ！",
  ui_story_1011_10110502_35_dialog_content = "気を付けて！",
  ui_story_1011_10110502_36_dialog_content = "今度は私たちの番よ。",
  ui_story_1011_10110502_37_dialog_content = "急いで、遺跡を探しましょう！",
  ui_story_1011_10110502_38_dialog_content = "これでも時間稼ぎにしかならないわ。",
  ui_story_1011_10110502_39_dialog_content = "あの数の暗鬼なら、十分壁を崩せる。\nそれに白い塔を這いあがって、上から入ってくるかも知れないわね。",
  ui_story_1011_10110502_40_dialog_content = "手分けして探そう！",
  ui_story_1011_10110502_41_dialog_content = "この辺りは、もう探したわね。",
  ui_story_1011_10110502_42_dialog_content = "もう一度探したところで、\nガラクタしか見つからないわよね…",
  ui_story_1011_10110502_43_dialog_content = "何か別の方法は…",
  ui_story_1011_10110502_44_dialog_content = "…空の末裔だけが知っているような方法はある？",
  ui_story_1011_10110502_45_dialog_content = "それって…感知能力とか？",
  ui_story_1011_10110502_46_dialog_content = "そうなるわね。",
  ui_story_1011_10110502_47_dialog_content = "感知能力を使って、手がかりを探してみるのはどう？",
  ui_story_1011_10110502_48_dialog_content = "やってみる！",
  ui_story_1011_10110502_49_option_content = "感知！",
  ui_story_1011_10110502_50_dialog_content = "えっ！？",
  ui_story_1011_10110502_51_dialog_content = "頭が！",
  ui_story_1011_10110502_52_dialog_content = "PlayerName！？",
  ui_story_1011_10110502_53_dialog_content = "この辺り、何かおかしい…",
  ui_story_1011_10110502_54_dialog_content = "僕が感知能力で探ろうとしたら、\n何かにジャマされた…",
  ui_story_1011_10110502_55_dialog_content = "空の末裔の感知能力に干渉する…",
  ui_story_1011_10110502_56_dialog_content = "何が隠されているのかしら。",
  ui_story_1011_10110502_57_dialog_content = "ただ、方向は間違っていないということね。",
  ui_story_1011_10110502_58_dialog_content = "でも、PlayerNameの感知能力が使えないんじゃ、\n手がかりはないも同然でしょ？",
  ui_story_1011_10110502_59_dialog_content = "…いや、もう一つ方法があるよ。",
  ui_story_1011_10110502_60_dialog_content = "僕はブレーンパーツに感知能力を使って、\nソラヴァンの意識モジュール修復装置を見つけたんだ。",
  ui_story_1011_10110502_61_dialog_content = "そして、まさにその修復装置の中にあったデータが、\n僕たちをここまで導いた。",
  ui_story_1011_10110502_62_dialog_content = "だったら、修復装置に感知を試してみれば、\n解決方法が見つかるかもしれない！",
  ui_story_1011_10110502_62X1_dialog_content = "さっきバートンを感知した時は、\n何も問題なかったし…",
  ui_story_1011_10110502_62X2_dialog_content = "きっと、近くの具体的な何かを感知するだけなら、\n影響は受けないんじゃないかな。",
  ui_story_1011_10110502_63_dialog_content = "確かに、筋は通るわね。",
  ui_story_1011_10110502_64_dialog_content = "その通りではあるけど…",
  ui_story_1011_10110502_65_dialog_content = "PlayerName、気分が悪くなったら、\nすぐに感知を切るのよ！",
  ui_story_1011_10110502_66_dialog_content = "無理はしないで。",
  ui_story_1011_10110502_67_dialog_content = "うん、安心して。",
  ui_story_1011_10110502_68_option_content = "強制感知！",
  ui_story_1011_10110502_69_dialog_content = "…",
  ui_story_1011_10110502_70_dialog_content = "教えて、中央制御室に通じる通路を開くにはどうすればいいの！？",
  ui_story_1011_10110502_71_dialog_content = "「命令を受信しました。検索中…」",
  ui_story_1011_10110502_72_dialog_content = "「ドアロックシステムがオフラインです。」",
  ui_story_1011_10110502_73_dialog_content = "「蛍灯を派遣し、修復を実行します」",
  ui_story_1011_10110502_74_dialog_content = "ソラヴァンから…蛍灯が飛んできた？",
  ui_story_1011_10110502_75_dialog_content = "「ピピピ…」",
  ui_story_1011_10110502_76_dialog_content = "<color=#e8d9bb>カチャ…</color>",
  ui_story_1011_10110502_77_dialog_content = "「ドアロックシステムのバックアップ電源に接続しました。\nドアロックシステムを起動しています…」",
  ui_story_1011_10110502_78_dialog_content = "「ID認証が必要です。パスワードを入力してください。」",
  ui_story_1011_10110502_79_dialog_content = "え？",
  ui_story_1011_10110502_80_dialog_content = "どこから聞こえて来てるの！？",
  ui_story_1011_10110502_81_dialog_content = "「本システムは巨像整備基地のドアロックシステムです」",
  ui_story_1011_10110502_82_dialog_content = "「警告…ロックシステムと\n中央制御システムの接続中断より…ザザ…日が経過」",
  ui_story_1011_10110502_83_dialog_content = "「ただちに接続を回復してください。\nまたは、パスワードを再設定してください」",
  ui_story_1011_10110502_84_dialog_content = "ドアを開けるシステムみたいだね？",
  ui_story_1011_10110502_85_dialog_content = "しかも音声制御みたいだ！",
  ui_story_1011_10110502_86_dialog_content = "「パスワードが間違っています。残りの入力回数は3回です」",
  ui_story_1011_10110502_87_dialog_content = "え？違うよ、今のは…",
  ui_story_1011_10110502_88_dialog_content = "「パスワードが間違っています。残りの入力回数は2回です」",
  ui_story_1011_10110502_89_dialog_content = "ま、待って！",
  ui_story_1011_10110502_90_dialog_content = "「パスワードが間違っています。残りの入力回数は1回です」",
  ui_story_1011_10110502_91_dialog_content = "「警告…入力エラーが規定回数を超過すると、\n本システムはロックされます。」",
  ui_story_1011_10110502_92_dialog_content = "もう話しちゃダメ！",
  ui_story_1011_10110502_93_dialog_content = "もごもご！！",
  ui_story_1011_10110502_94_dialog_content = "合言葉の再設定はできるの？",
  ui_story_1011_10110502_95_dialog_content = "「エラー。未承認の遺伝子型を検出しました。\n命令は無効です」",
  ui_story_1011_10110502_96_dialog_content = "…",
  ui_story_1011_10110502_97_dialog_content = "（僕にやれってことかな？）",
  ui_story_1011_10110502_98_dialog_content = "これが最後のチャンスよ、PlayerName。\nあなたがやってみて。",
  ui_story_1011_10110502_99_dialog_content = "絶対に間違えないで。",
  ui_story_1011_10110502_100_dialog_content = "（分かった…）",
  ui_story_1011_10110502_101_dialog_content = "…",
  ui_story_1011_10110502_102_option_content = "ドアロックシステムのパスワードをリセットして。",
  ui_story_1011_10110502_103_dialog_content = "「…遺伝子型を検出しました。権限は有効です。\nパスワードの再設定を開始します」",
  ui_story_1011_10110502_104_dialog_content = "「3つの質問に答えてください。身分認証を実行します」",
  ui_story_1011_10110502_105_dialog_content = "ここに来て謎かけでも始めるつもり？",
  ui_story_1011_10110502_106_dialog_content = "仕方ないわ。とりあえず進めてみましょ。",
  ui_story_1011_10110502_107_dialog_content = "PlayerName、緊張することないわ。私も手伝うから。",
  ui_story_1011_10110502_108_dialog_content = "学生時代の期末テスト連続成績優秀者の名誉に賭けて！",
  ui_story_1011_10110502_109_dialog_content = "「あなたは暗鬼ですか？」",
  ui_story_1011_10110502_110_dialog_content = "え…？",
  ui_story_1011_10110502_111_dialog_content = "僕が暗鬼なはずないでしょ！？",
  ui_story_1011_10110502_112_dialog_content = "「回答エラー。」",
  ui_story_1011_10110502_113_dialog_content = "「質問を繰り返します。あなたは暗鬼ですか？」",
  ui_story_1011_10110502_114_dialog_content = "ええと…違うよ！",
  ui_story_1011_10110502_115_dialog_content = "「回答を記録しました」",
  ui_story_1011_10110502_116_dialog_content = "「あなたは光霊ですか？」",
  ui_story_1011_10110502_117_dialog_content = "光霊でもないよ。",
  ui_story_1011_10110502_118_dialog_content = "「回答を記録しました」",
  ui_story_1011_10110502_119_dialog_content = "「表示される映像の中から蛍灯を選んでください」",
  ui_story_1011_10110502_120_dialog_content = "これは…ホログラム？",
  ui_story_1011_10110502_121_dialog_content = "本物みたいね！",
  ui_story_1011_10110502_122_option_content = "蛍灯の映像に触れる",
  ui_story_1011_10110502_123_dialog_content = "「回答を記録しました」",
  ui_story_1011_10110502_124_dialog_content = "「認証完了。空の末裔であることが確認されました」",
  ui_story_1011_10110502_125_dialog_content = "「ドアロックシステムの新しいパスワードを設定してください」",
  ui_story_1011_10110502_126_dialog_content = "ええと…開けゴマ！",
  ui_story_1011_10110502_127_dialog_content = "「再設定が完了しました。新しい合言葉は――『ええと、開けゴマ！』です」",
  ui_story_1011_10110502_128_dialog_content = "「ええと」まで入れないで！？",
  ui_story_1011_10110502_129_dialog_content = "「ドアを開きます」",
  ui_story_1011_10110502_130_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1011_10110502_131_dialog_content = "うわあ！？",
  ui_story_1011_10110502_132_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1011_10110502_133_dialog_content = "壁の石が裂けて…扉が出てきたわ！",
  ui_story_1011_10110502_134_dialog_content = "大きい…！",
  ui_story_1011_10110502_135_dialog_content = "ただ…どうしてもツッコまずにはいられない…",
  ui_story_1011_10110502_136_dialog_content = "この認証方法、まったく意味ないでしょ！？",
  ui_story_1011_10110502_137_dialog_content = "少し知能のある生物なら、\n適当にウソつけば通れちゃうよ！？",
  ui_story_1011_10110502_137X1_dialog_content = "質問そのものは重要でないのかもしれないわ。",
  ui_story_1011_10110502_137X2_dialog_content = "じゃあ、何が重要なの？",
  ui_story_1011_10110502_137X3_dialog_content = "空の末裔かどうかって、\nこんな簡単な質問だけで分かるものなの？",
  ui_story_1011_10110502_137X4_dialog_content = "私が質問した時は、\nシステムに「未承認の遺伝子型」と言われたでしょう…",
  ui_story_1011_10110502_137X5_dialog_content = "他の何らかの方法で…\nおそらく血統を確認していたのだと思うわ。",
  ui_story_1011_10110502_137X6_dialog_content = "あの質問はただ、あなたに「空の末裔だ」と\n答えさせるためだけのものだったのではないかしら。",
  ui_story_1011_10110502_137X7_dialog_content = "そんなことして何になるの？",
  ui_story_1011_10110502_137X8_dialog_content = "機械の思考回路など分からないわ。",
  ui_story_1011_10110502_137X9_dialog_content = "でも、もしそうなら…\nこの遺跡は、非接触で遺伝子検査ができるということ？",
  ui_story_1011_10110502_137X10_dialog_content = "勝手にのぞかれてるみたいで、何だか気分が悪いわね…",
  ui_story_1011_10110502_137X11_dialog_content = "とにかく、過程は重要ではない。\n重要なのは結果よ。",
  ui_story_1011_10110502_137X12_dialog_content = "扉はもう開いたのだから、\nなぜ開いたのかを突き詰める必要はないでしょう。",
  ui_story_1011_10110502_138_dialog_content = "セキュリティの穴に感謝しないとね…",
  ui_story_1011_10110502_139_dialog_content = "この扉…下に通じているわ。\nおそらく、これが地下遺跡の入口ね。",
  ui_story_1011_10110502_140_dialog_content = "これほど大きな扉がずっとここにあったのなら、\n昔の空の末裔たちは、なぜ気付かなかったのかしら？",
  ui_story_1011_10110502_141_dialog_content = "僕にも分からないよ。\nここは謎が多すぎる…",
  ui_story_1011_10110502_142_dialog_content = "とにかく、通路があるってことは、\nこの下にまだ未探索の場所があるってことよ。",
  ui_story_1011_10110502_143_dialog_content = "今いちばん重要なのは、ソラヴァンを修復する方法と、\n暗鬼を避けながら、ここを離れるルートを見つけることよ。",
  ui_story_1011_10110502_144_dialog_content = "その通りね、これ以上時間を無駄にはできない。",
  ui_story_1011_10110502_145_dialog_content = "じゃあ、出発しよう！",
  ui_story_1011_10110601_1_dialog_content = "グアアア――",
  ui_story_1011_10110601_2_dialog_content = "不意打ちもろくにできない下等生物が、\nいっちょ前に兵士気どりか！？",
  ui_story_1011_10110601_3_dialog_content = "一体誰に指示された？てめえらより一回りでけぇ暗鬼か？\nそれとも頭のイカれた科学者の方か？",
  ui_story_1011_10110601_4_dialog_content = "おっと…忘れてた。\nてめえらは話すこともできねぇんだったな。",
  ui_story_1011_10110601_5_dialog_content = "ガァ…",
  ui_story_1011_10110601_6_dialog_content = "フン、ゴミどもが！",
  ui_story_1011_10110601_7_dialog_content = "…チッ、こんなヤツらの死体なんか踏んづけたところで、\n何の達成感もありゃしねえ…日蝕ってのは、この程度か？",
  ui_story_1011_10110601_8_dialog_content = "…",
  ui_story_1011_10110601_10_dialog_content = "誰だ！",
  ui_story_1011_10110601_11_dialog_content = "…",
  ui_story_1011_10110601_12_dialog_content = "本当にてめえだったか。\n<color=#FFB400>デニール</color>…啓光の裏切者め。",
  ui_story_1011_10110601_13_dialog_content = "――ああ、忘れてたぜ。\nお前の存在はもう抹消されてたんだったな。",
  ui_story_1011_10110601_14_dialog_content = "チッ…",
  ui_story_1011_10110601_15_dialog_content = "まったく…結局見つかるなんて、マヌケにもほどがあるぜ。\nザコを目くらましにするなら、せめてもっとうまくやれよ。",
  ui_story_1011_10110601_16_dialog_content = "（ザコ？…フィジェロの手下ね…）",
  ui_story_1011_10110601_17_dialog_content = "（また余計なことを…）",
  ui_story_1011_10110601_18_dialog_content = "あんたたちの争いに付き合うつもりはないわ。\nここの暗鬼どもは、私とは関係ない。",
  ui_story_1011_10110601_19_dialog_content = "ここで戦うなんてバカよ。\n白い塔に何かあったらどうするの？",
  ui_story_1011_10110601_20_dialog_content = "（白い塔？こいつ、PlayerNameたちの後を追うつもりか…）",
  ui_story_1011_10110601_21_dialog_content = "ああ！？戦場ってのは、\nリクツを並べる所じゃねえんだよ！",
  ui_story_1011_10110601_22_dialog_content = "入るってなら、押し通る力を見せな！",
  ui_story_1011_10110601_23_dialog_content = "俺もてめえとごちゃごちゃ話す気はねえ。\n行くぜ、ノラ――",
  ui_story_1011_10110601_24_dialog_content = "鉄顎の力を思い知れ！",
  ui_story_1011_10110601_25_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_1011_10110601_26_dialog_content = "まったく面倒ね…この場所とあなたと、\n何の関係があるの？",
  ui_story_1011_10110601_27_dialog_content = "私、計画が狂うのは大っ嫌いなの。",
  ui_story_1011_10110601_28_dialog_content = "あなたを殺して解決するなら、\nかえって好都合だわ。",
  ui_story_1011_10110601_29_dialog_content = "ハハハハハハハ！\nそう来なくっちゃなぁ！",
  ui_story_1011_10110601_30_dialog_content = "さあ、一緒にヒマつぶしといこうぜ！",
  ui_story_1011_10110601_31_dialog_content = "<color=#e8d9bb>塔の内部、通路</color>",
  ui_story_1011_10110601_32_dialog_content = "<color=#e8d9bb>タッ…タッ…タッ…</color>",
  ui_story_1011_10110601_33_dialog_content = "（ずいぶんと細長い通路ね。\nまるで終わりがないみたい…）",
  ui_story_1011_10110601_34_dialog_content = "（後ろも…ううん、\n入口の光がもうほとんど見えないわ…）",
  ui_story_1011_10110601_35_dialog_content = "<color=#e8d9bb>ガラガラ…</color>",
  ui_story_1011_10110601_36_dialog_content = "バイス、足元に気を付けて！",
  ui_story_1011_10110601_37_dialog_content = "えっ！？",
  ui_story_1011_10110601_38_dialog_content = "<color=#e8d9bb>ドスン！</color>",
  ui_story_1011_10110601_39_dialog_content = "危ない！",
  ui_story_1011_10110601_40_dialog_content = "ゲホ、ゴホゴホッ…",
  ui_story_1011_10110601_41_dialog_content = "すごいホコリ！",
  ui_story_1011_10110601_42_dialog_content = "<color=#e8d9bb><size=35>いホコリ…コリ…コリ…</size></color>",
  ui_story_1011_10110601_43_dialog_content = "え？",
  ui_story_1011_10110601_44_dialog_content = "シッ…静かに。",
  ui_story_1011_10110601_45_dialog_content = "この先まだ、ずいぶん距離がありそうよ。",
  ui_story_1011_10110601_46_dialog_content = "ただまっすぐなトンネルの中で、\n声を聞き付けて何かがやってきたら、避けることもできないわ。",
  ui_story_1011_10110601_47_dialog_content = "ところで、PlayerName…",
  ui_story_1011_10110601_48_dialog_content = "この場所の存在は、\n本当に今まで知らなかったというの？",
  ui_story_1011_10110601_49_dialog_content = "うん…僕だけじゃないよ。\nソラヴァンだって1度もこんな遺跡が隠されてるとは言わなかった。",
  ui_story_1011_10110601_50_dialog_content = "まぁ、ソラヴァンも何でも知ってるワケじゃないし…",
  ui_story_1011_10110601_51_dialog_content = "…",
  ui_story_1011_10110601_52_dialog_content = "（ソラヴァン…）",
  ui_story_1011_10110601_53_dialog_content = "意識モジュールプラグインの指示に従って、\nここに来たんだから…",
  ui_story_1011_10110601_54_dialog_content = "指示通り「中央制御システム」を\n見つけさえすればいいのよ。",
  ui_story_1011_10110601_55_dialog_content = "中にはきっと、\nソラヴァンを修理する方法があるはずよ、PlayerName。",
  ui_story_1011_10110601_56_dialog_content = "そうだね…！ありがとう、バイス。",
  ui_story_1011_10110601_57_dialog_content = "ん？",
  ui_story_1011_10110601_58_dialog_content = "どうしたの？",
  ui_story_1011_10110601_59_dialog_content = "足元のこれ…普通の石じゃなさそうだよ。\nでも、この辺りにたくさんある白い石でもない。",
  ui_story_1011_10110601_60_dialog_content = "少し見せて…",
  ui_story_1011_10110601_61_dialog_content = "…色と材質が確かに珍しいわね。\n学院で読んだ資料には…",
  ui_story_1011_10110601_62_dialog_content = "そう…確かにこれは、古代にしか見られない特殊な素材のはず…",
  ui_story_1011_10110601_63_dialog_content = "（…！？）",
  ui_story_1011_10110601_64_dialog_content = "これは、まさか…",
  ui_story_1011_10110601_65_dialog_content = "<color=#FFB400>巨像の基礎材</color>？",
  ui_story_1011_10110601_66_dialog_content = "！？",
  ui_story_1011_10110601_67_dialog_content = "（細かいがれきをどけたら、\n中にもっとたくさんの破片が…）",
  ui_story_1011_10110601_68_dialog_content = "（ま、まさか…これ、全部巨像の<color=#FFB400>残骸</color>！？）",
  ui_story_1011_10110601_69_dialog_content = "これでここが本当に巨像整備基地の内部だって、\n疑う余地もなくなったわね！",
  ui_story_1011_10110601_70_dialog_content = "この数からして…巨像は当時、珍しい乗り物じゃなかった。\n伝説や史料は正しかったんだわ！",
  ui_story_1011_10110601_71_dialog_content = "あ！PlayerName、通路の端に着きそうよ！",
  ui_story_1011_10110601_72_dialog_content = "あれ…PlayerName、どうしたの？",
  ui_story_1011_10110601_73_dialog_content = "…",
  ui_story_1011_10110601_74_option_content = "少し怖いんだ",
  ui_story_1011_10110601_75_dialog_content = "ぼ、僕は…今までこんな光景、\n見たことがなかった。",
  ui_story_1011_10110601_76_dialog_content = "ソラヴァンは僕にとって…\n家族で、友だちで、先生みたいな存在だったんだ。",
  ui_story_1011_10110601_77_dialog_content = "今まで一緒にいろんな所に行って、\nたくさんの危機を一緒に乗り越えてきた…",
  ui_story_1011_10110601_78_dialog_content = "今まで一度だってソラヴァンもこんな風になるかもなんて、\n考えたことがなかったから…",
  ui_story_1011_10110601_79_option_content = "少し嬉しいんだ",
  ui_story_1011_10110601_80_dialog_content = "アストラ大陸に現存する巨像は少ししかないでしょ？",
  ui_story_1011_10110601_81_dialog_content = "でも、17年前から誰もいない天空ノ谷の中の、\n僕とソラヴァンの足元に…",
  ui_story_1011_10110601_82_dialog_content = "こんなに大量の巨像があったって言う証拠があると思うと…",
  ui_story_1011_10110601_83_dialog_content = "僕にも…故郷があったんだって、改めて感じたんだ。",
  ui_story_1011_10110601_84_dialog_content = "そういうことね。",
  ui_story_1011_10110601_85_dialog_content = "じゃあ、なおさら急いで先に進みましょう。",
  ui_story_1011_10110601_86_dialog_content = "巨像の残骸がどこから来てるのか、\n突き止めないと！",
  ui_story_1011_10110601_87_dialog_content = "ああ…やっと少し広いところに出たわね。",
  ui_story_1011_10110601_88_dialog_content = "もっと薄暗いかと思ってたけど、\n意外に見通しが利くみたいね…",
  ui_story_1011_10110601_89_dialog_content = "うーん…でも、巨像っぽいものの影が\n死角になるわね…",
  ui_story_1011_10110601_90_dialog_content = "そうね。光源はよく分からないけれど、\n少なくとも完全な密室でないことは確かのようね。",
  ui_story_1011_10110601_91_dialog_content = "巨像のきれいに並んだ様子からして…",
  ui_story_1011_10110601_92_dialog_content = "遺跡が倒壊してなければ、\nきっとたくさんの巨像が完全な状態で保存されてたんでしょうね…",
  ui_story_1011_10110601_93_dialog_content = "PlayerName、感知を試してみる？",
  ui_story_1011_10110601_94_dialog_content = "もしここにまだ、意識を持ってる巨像が残っていれば、\n接続できるかもしれないわ。",
  ui_story_1011_10110601_95_dialog_content = "そうだね。じゃあ、試してみよう――",
  ui_story_1011_10110601_96_option_content = "強制感知！",
  ui_story_1011_10110601_97_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1011_10110601_98_dialog_content = "ダメだ…反応はないよ。",
  ui_story_1011_10110601_99_dialog_content = "（それもそうか。こんなボロボロの遺跡に、\n意識のある生命体が存在するなんて、考えづらい…）",
  ui_story_1011_10110601_100_dialog_content = "まぁ、少なくとも、\n古代の巨像の活動の痕跡を見ることができたわ。",
  ui_story_1011_10110601_101_dialog_content = "次は周りの扉を、一つ一つ探ってみましょ。",
  ui_story_1011_10110601_102_dialog_content = "元気だすのよ、PlayerName！",
  ui_story_1011_10110601_103_dialog_content = "よし、じゃあ…",
  ui_story_1011_10110601_104_option_content = "辺りを調べよう",
  ui_story_1011_10110601_105_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_1011_10110601_106_dialog_content = "…うっ！？",
  ui_story_1011_10110601_107_dialog_content = "あいたた…ビクともしないわ！",
  ui_story_1011_10110601_108_dialog_content = "巨像の損傷の具合から見て、\n部屋も無事ということはあり得ないでしょうね。",
  ui_story_1011_10110601_109_dialog_content = "がれきに出入り口を塞がれているのでしょう。\nとなると、先に進むしかないわね。",
  ui_story_1011_10110601_110_option_content = "先に進む",
  ui_story_1011_10110601_111_dialog_content = "そうね！前方は…下の階に続く階段みたい。",
  ui_story_1011_10110601_112_dialog_content = "た、たぶん、歩いて大丈夫よね…\n今まで崩れてないんだから…",
  ui_story_1011_10110601_113_dialog_content = "入口近くにこれだけたくさんの\n巨像が停まっているということは…",
  ui_story_1011_10110601_114_dialog_content = "下にはきっと、巨像の修理やメンテナンスに\n必要な設備があるはずよ。",
  ui_story_1011_10110601_115_dialog_content = "PlayerName、先に進みましょう。",
  ui_story_1011_10110601_116_dialog_content = "<color=#e8d9bb>タッ…タッ…タッ…</color>",
  ui_story_1011_10110601_117_dialog_content = "（この階段、ずいぶん暗いな…\nこういう時に蛍灯がいてくれると助かるんだけど…）",
  ui_story_1011_10110601_118_dialog_content = "（下には何が眠ってるんだろう。\nソラヴァンの役に立つかな…）",
  ui_story_1011_10110601_119_dialog_content = "（やっと着いた、急いで探さないと――）",
  ui_story_1011_10110601_120_dialog_content = "…え？",
  ui_story_1011_10110601_121_dialog_content = "ど、どういうこと！？",
  ui_story_1011_10110601_122_dialog_content = "こんなに広い空間に、\n見渡す限り、大型機器の一つもないなんて…",
  ui_story_1011_10110601_123_dialog_content = "この地下遺跡、\n想像よりもはるかに大きいようね。",
  ui_story_1011_10110601_124_dialog_content = "ただ…この階は一体、\n何に使っていたのかしら…？",
  ui_story_1011_10110601_125_dialog_content = "ホコリの積もった机、何が置かれていたのか分からない石づくりの棚、\nそれから、奇妙なクッション…",
  ui_story_1011_10110601_126_dialog_content = "ガラクタ置き場か何か？",
  ui_story_1011_10110601_127_dialog_content = "ぷっ…アハハハ、今ので確信したわ。",
  ui_story_1011_10110601_128_dialog_content = "たぶん、ここは古代の空の末裔が\n<color=#FFB400>住んでいた</color>所よ。",
  ui_story_1011_10110601_129_dialog_content = "啓光のシェルターの居住区にも、\nこういう日用品が置かれてるわ。",
  ui_story_1011_10110601_130_dialog_content = "ここにあるのは年代も分からないし、\n古くてボロボロだけど、大体見分けがつくわ――",
  ui_story_1011_10110601_131_dialog_content = "テーブル、作業台、食品棚、物置棚、\n予備のベッドマットレス…",
  ui_story_1011_10110601_132_dialog_content = "まぁ、お姫様には\nガラクタに見えても仕方ないわね。",
  ui_story_1011_10110601_133_dialog_content = "そ、それぐらい分かっていたわ！",
  ui_story_1011_10110601_134_dialog_content = "…これは？",
  ui_story_1011_10110601_135_dialog_content = "バイス、見て。\nこのコップ、何かあるわ。",
  ui_story_1011_10110601_136_dialog_content = "ん？どこ？",
  ui_story_1011_10110601_137_dialog_content = "ただの汚れじゃないの？",
  ui_story_1011_10110601_138_dialog_content = "コップの底よ。\nPlayerName、あなたも見て。",
  ui_story_1011_10110601_139_dialog_content = "あれ、本当だ…何か記号のようなものがある！",
  ui_story_1011_10110601_140_dialog_content = "本当だわ！",
  ui_story_1011_10110601_141_dialog_content = "空の末裔と関係のあるマークかな…？",
  ui_story_1011_10110601_142_dialog_content = "そうではないと思うわ。\n周りの小物を見る限り…",
  ui_story_1011_10110601_143_dialog_content = "印があるのはこのコップだけ。",
  ui_story_1011_10110601_144_dialog_content = "そうね。もし空の末裔全体に共通した意味のあるマークなら、\nこういう物には全部ないとおかしいわ。",
  ui_story_1011_10110601_145_dialog_content = "でも、一体何が描いてあるの？\nいくら見ても、よく分からないわ。",
  ui_story_1011_10110601_146_dialog_content = "おそらく…名前か、愛称かしら。ただ…",
  ui_story_1011_10110601_147_dialog_content = "やはりダメね。\n損耗が激しすぎて、具体的なことは分からないわ。",
  ui_story_1011_10110601_148_dialog_content = "だったら、わざわざ時間をかけて\n考える必要もないんじゃない？",
  ui_story_1011_10110601_149_dialog_content = "う～ん…",
  ui_story_1011_10110601_150_dialog_content = "（PlayerNameはそういうけど、\nやっぱり気になるわ…）",
  ui_story_1011_10110601_151_dialog_content = "（昔の人の名前を見るなんて、\nきっと何かの縁だし…）",
  ui_story_1011_10110601_152_dialog_content = "（よし！手がかりを他にも探して見ましょ！）",
  ui_story_1011_10110601_153_dialog_content = "ん？テーブルの上の物は何かしら…",
  ui_story_1011_10110601_154_dialog_content = "どういうことかしら、これって…",
  ui_story_1011_10110601_155_dialog_content = "オウムガイ？",
  ui_story_1011_10110601_156_dialog_content = "しかも、たくさん並んでるわ。",
  ui_story_1011_10110601_157_dialog_content = "ねえ、PlayerName。\nこういうのも空の末裔の…ええと、日用品なの？",
  ui_story_1011_10110601_158_dialog_content = "え？これは…君が見つけたの？",
  ui_story_1011_10110601_159_dialog_content = "こんなの見たことないし、一体何だかも、\n僕にはまったく分からないよ。",
  ui_story_1011_10110601_160_dialog_content = "オウムガイ？\n海にしかいない生き物のはず…",
  ui_story_1011_10110601_161_dialog_content = "ということは…天空ノ谷はかつて海だった？\nそれとも…空の末裔はオウムガイを食べていた？",
  ui_story_1011_10110601_162_dialog_content = "どっちも現実的じゃないね…",
  ui_story_1011_10110601_163_dialog_content = "うーん…このオウムガイ、\n私たちが知っているものと少し違うのかも…",
  ui_story_1011_10110601_164_dialog_content = "小さくてなめらかだし、ずいぶん軽いわ。\nこんなに長い間、完全な形で保存されてるし…",
  ui_story_1011_10110601_165_dialog_content = "きっと携帯用とか、壊れにくいとか、\nそんな理由で何かに使われてたのよ。",
  ui_story_1011_10110601_166_dialog_content = "しかも…あっ！",
  ui_story_1011_10110601_167_dialog_content = "な、中に何か入ってる！？",
  ui_story_1011_10110601_168_dialog_content = "え！？",
  ui_story_1011_10110601_169_dialog_content = "ケガはない？何が出て来たの？",
  ui_story_1011_10110601_170_dialog_content = "ケガはないわ…\n何か出てきたけど、手は大丈夫。",
  ui_story_1011_10110601_171_dialog_content = "クンクン…",
  ui_story_1011_10110601_172_dialog_content = "うーん…無色、無臭、粘性は低い。\nでも、これだけじゃ何の液体か分からないわ。",
  ui_story_1011_10110601_173_dialog_content = "（オウムガイ、液体…流動性？）",
  ui_story_1011_10110601_174_dialog_content = "（もしかして…）",
  ui_story_1011_10110601_175_dialog_content = "…とにかく、慎重になるに越したことはないわ。\nよく分からないものには気を付けないと…",
  ui_story_1011_10110601_176_dialog_content = "そ、そうね…",
  ui_story_1011_10110601_177_dialog_content = "（証拠もないし、今は憶測で何か言うのは控えたほうがよさそうね）",
  ui_story_1011_10110601_178_dialog_content = "（私の推測が正しければ、\nこの遺跡には、まだ証拠になるものがあるはず…）",
  ui_story_1011_10110601_179_dialog_content = "（ひとまずポケットに入れておきましょ…）",
  ui_story_1011_10110601_180_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_1011_10110601_181_dialog_content = "え！？",
  ui_story_1011_10110601_182_dialog_content = "PlayerName、カレン！どうしたの！？",
  ui_story_1011_10110601_183_dialog_content = "あなたが音を立てたのではなかったの？\n待って…",
  ui_story_1011_10110601_184_dialog_content = "…イヤな予感がするわ…",
  ui_story_1011_10110601_185_dialog_content = "まさか、他に誰かいるの？",
  ui_story_1011_10110601_186_dialog_content = "人ならとうの昔に姿を見せているはず。\nおそらく…",
  ui_story_1011_10110601_187_dialog_content = "グァ…",
  ui_story_1011_10110601_188_dialog_content = "グオオォ！！！",
  ui_story_1011_10110601_189_dialog_content = "そんな！？ここにも暗鬼が！？",
  ui_story_1011_10110601_190_dialog_content = "私たちについて来ていた…？",
  ui_story_1011_10110601_191_dialog_content = "PlayerName、準備はいい？",
  ui_story_1011_10110601_192_dialog_content = "もちろん！",
  ui_story_1011_10110702_1_dialog_content = "PlayerName、PlayerName！",
  ui_story_1011_10110702_2_dialog_content = "これは一体、どういうこと…？",
  ui_story_1011_10110702_3_dialog_content = "目を覚ますのよ、PlayerName！",
  ui_story_1011_10110702_4_dialog_content = "（うっ…）",
  ui_story_1011_10110702_5_dialog_content = "（く、苦しい…息ができない…）",
  ui_story_1011_10110702_6_dialog_content = "（バイスとカレンが…僕を呼んでる？\n声が、すごく遠い…）",
  ui_story_1011_10110702_7_dialog_content = "（僕は…）",
  ui_story_1011_10110702_8_dialog_content = "対象を検知…感知能力を有する生命体。\nID認証…空の末裔。",
  ui_story_1011_10110702_9_dialog_content = "精神感知による通信を開始。",
  ui_story_1011_10110702_10_dialog_content = "警告…対象の呼吸器内の酸素量が不足。\n居住エリアの換気システムを起動。",
  ui_story_1011_10110702_11_dialog_content = "<color=#e8d9bb>シュー…</color>",
  ui_story_1011_10110702_12_dialog_content = "（な、何の音だろう…）",
  ui_story_1011_10110702_13_dialog_content = "あれっ…？",
  ui_story_1011_10110702_14_dialog_content = "あっ――PlayerName！",
  ui_story_1011_10110702_15_dialog_content = "PlayerName、気が付いたのね！",
  ui_story_1011_10110702_16_dialog_content = "どう？具合は？",
  ui_story_1011_10110702_17_dialog_content = "ううん…もう大丈夫そうだよ。",
  ui_story_1011_10110702_18_dialog_content = "さっきの戦いはちょっと激しかったし、\nずっと歩いてて体力を消耗してたから、きっとそれで…",
  ui_story_1011_10110702_19_dialog_content = "急に息が苦しくなって…",
  ui_story_1011_10110702_20_dialog_content = "戦いが…激しかった？",
  ui_story_1011_10110702_21_dialog_content = "体力を消耗した？",
  ui_story_1011_10110702_22_dialog_content = "…",
  ui_story_1011_10110702_23_dialog_content = "（黙ったまま、そんな風に僕を見ないで！？）",
  ui_story_1011_10110702_24_dialog_content = "対象の身体状況を分析…",
  ui_story_1011_10110702_25_dialog_content = "状態、正常。体質評価、レベル１、貧弱。",
  ui_story_1011_10110702_26_dialog_content = "！？",
  ui_story_1011_10110702_27_dialog_content = "だ、誰！？誰が話してるの！？",
  ui_story_1011_10110702_28_dialog_content = "まぁ、言ってることは間違ってないわね…",
  ui_story_1011_10110702_29_dialog_content = "サブブレーンの使命は、空の末裔に仕え、\n空の末裔のすべての疑問を解決することです。",
  ui_story_1011_10110702_30_dialog_content = "質問を分析中…",
  ui_story_1011_10110702_31_dialog_content = "回答結果…空の末裔が援助を必要していることを検知しました。\n空の末裔はサブブレーンと会話を行っています。",
  ui_story_1011_10110702_32_dialog_content = "（こんな質問にそんな大げさな分析が必要なの？）",
  ui_story_1011_10110702_33_dialog_content = "でも、そう言えば、さっき僕が気を失っている時…",
  ui_story_1011_10110702_34_dialog_content = "警告…対象の呼吸器内の酸素量が不足。\n居住エリアの換気システムを起動。",
  ui_story_1011_10110702_35_dialog_content = "ここの換気システムをこれが起動してくれたから、\n僕はよくなったんだ。",
  ui_story_1011_10110702_36_dialog_content = "ああ、それでさっき…\n急に涼しい風が吹いたのね。",
  ui_story_1011_10110702_36X_dialog_content = "これは何かしら？\nただの幻影のようだけど…",
  ui_story_1011_10110702_37_dialog_content = "古代の空の末裔の科学技術なのかしら…\nいざという時に助けてくれたということね。",
  ui_story_1011_10110702_38_dialog_content = "わあ！見せて見せて！\n今でも動いてる人工知能があるってことね！？",
  ui_story_1011_10110702_39_dialog_content = "う～ん…",
  ui_story_1011_10110702_40_dialog_content = "…",
  ui_story_1011_10110702_41_dialog_content = "対象を検知：光力を有する生命体。\nID認証、光霊。数、2体。",
  ui_story_1011_10110702_42_dialog_content = "「サブブレーン」、あなたは…\n古代の空の末裔の科学技術なの？",
  ui_story_1011_10110702_43_dialog_content = "情報受理、質問を分析中…エラー。サブブレーンの使命は、\n空の末裔の疑問を解決することです。",
  ui_story_1011_10110702_44_dialog_content = "な、なによそれ！？\n光霊は空の末裔の機械を使っちゃいけないってこと！？",
  ui_story_1011_10110702_45_dialog_content = "質問を分析中…エラー。サブブレーンの使命は、\n空の末裔の疑問を解決することです。",
  ui_story_1011_10110702_46_dialog_content = "今のは質問じゃないわ！！",
  ui_story_1011_10110702_47_dialog_content = "あなた、きっと性格悪いって\n言われたことあるでしょ！",
  ui_story_1011_10110702_48_dialog_content = "まあまあ、抑えて、バイス…僕が聞くから…",
  ui_story_1011_10110702_49_dialog_content = "サ、サブブレーン！\n聞きたいことは、本当にたくさんあるんだけど――",
  ui_story_1011_10110702_50_dialog_content = "情報受理、システム修正中…システムの名称を、\n「サ、サブブレーン」に変更します。",
  ui_story_1011_10110702_51_dialog_content = "え？待って…変更中止！変えないで！",
  ui_story_1011_10110702_52_dialog_content = "変更を中止しました。",
  ui_story_1011_10110702_53_dialog_content = "（だんだん分かってきた…\n古代の人々が残した人工知能みたいだけど…）",
  ui_story_1011_10110702_54_dialog_content = "（あんまり賢くはないみたいだ…）",
  ui_story_1011_10110702_55_dialog_content = "（うまくコミュニケーションを取るには、\n質問を細かく分けないと…）",
  ui_story_1011_10110702_56_dialog_content = "オホン…まずは一つ目の質問だよ。\nこの塔はどういう場所なのか、教えて。",
  ui_story_1011_10110702_57_dialog_content = "質問を分析中…",
  ui_story_1011_10110702_58_dialog_content = "回答が生成されました。\nここは<color=#FFB400>「回帰の塔」</color>です。",
  ui_story_1011_10110702_59_dialog_content = "（回帰の塔？灯台のような、\n巨像の帰路を導く建物ということ…？）",
  ui_story_1011_10110702_60_dialog_content = "回帰って…どういうこと？\nソラヴァンが自動操縦でここまで来たのが、回帰ってこと？",
  ui_story_1011_10110702_61_dialog_content = "申し訳ありません。\nサブブレーンにはデータがありません。",
  ui_story_1011_10110702_62_dialog_content = "（あっさり「分からない」って言われた…）",
  ui_story_1011_10110702_63_dialog_content = "分かった…じゃあ、2つ目の質問だよ。\nこの塔はもともと、どんな構造だったの？",
  ui_story_1011_10110702_64_dialog_content = "僕たちは今、回帰の塔のどの辺りにいるの？",
  ui_story_1011_10110702_65_dialog_content = "サブブレーンの機能紹介を再生します。\nサブブレーンは回帰の塔内部のサービス用人工知能です…",
  ui_story_1011_10110702_66_dialog_content = "サブブレーンは空の末裔の権限と指示に基づき、\n空の末裔に必要なサポートを行います。",
  ui_story_1011_10110702_67_dialog_content = "空の末裔の権限を確認しています…",
  ui_story_1011_10110702_68_dialog_content = "確認が終了しました。サブブレーンは\n以下の情報を提供します。回帰の塔内部の地図です。",
  ui_story_1011_10110702_69_dialog_content = "（助かる！）",
  ui_story_1011_10110702_70_dialog_content = "よかったわ！\nこれでやみくもに探索せずに済むわね！",
  ui_story_1011_10110702_71_dialog_content = "急いでソラヴァンを修復できる場所を探しましょ。",
  ui_story_1011_10110702_72_dialog_content = "（あ、ダメだとは思うけど、\nやっぱり聞くだけ聞いてみよう…）",
  ui_story_1011_10110702_73_dialog_content = "最後の質問だよ。\n「中央制御システム」に入る方法を教えて。",
  ui_story_1011_10110702_74_dialog_content = "…",
  ui_story_1011_10110702_75_dialog_content = "申し訳ありません。\nサブブレーンにはデータがありません。",
  ui_story_1011_10110702_76_dialog_content = "ピーポーピーポーパ～♪",
  ui_story_1011_10110702_77_dialog_content = "（なんのメロディ！？）",
  ui_story_1011_10110702_78_dialog_content = "仕方ないわ、PlayerName。\n先に行きましょう。何もないよりはずっといいわ。",
  ui_story_1011_10110702_79_dialog_content = "内部の地図も手に入れたことだし、\n急いでサブブレーンで位置を確認しましょう。",
  ui_story_1011_10110702_80_dialog_content = "それもそうだね。どれどれ…",
  ui_story_1011_10110702_81_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1011_10110702_82_dialog_content = "なるほど…この回帰の塔には各階にそれぞれ異なる機能があって、\n僕たちはまだ上のエリアにいるんだ。",
  ui_story_1011_10110702_83_dialog_content = "僕たちがさっき入ってきた、\nあの階が「巨像整備基地」。",
  ui_story_1011_10110702_84_dialog_content = "でも、見た通り、壊れてほぼ何も残ってない。",
  ui_story_1011_10110702_85_dialog_content = "今いるこの階は…\nバイスの推測通り、「空の末裔の居住区」だね。",
  ui_story_1011_10110702_86_dialog_content = "ここも、探索し終えてるね。",
  ui_story_1011_10110702_87_dialog_content = "この2つの階、部屋がたくさんあるはずだけど、\n全部崩れた壁の下敷きになってるのが残念だね…",
  ui_story_1011_10110702_88_dialog_content = "「巨像パーツ生産ライン」、「資源生産エリア」、\n「廃棄物処理エリア」…全部下敷きになってる…",
  ui_story_1011_10110702_89_dialog_content = "ソラヴァン…",
  ui_story_1011_10110702_90_dialog_content = "ソラヴァンのことを急ぐ必要はないわ。\nほら、見て。この下にも、まだたくさんの空間がある。",
  ui_story_1011_10110702_91_dialog_content = "私の憶測もあるけれど、下へ進めば進むほど、\n多くの情報を得られていることは確かよ。",
  ui_story_1011_10110702_92_dialog_content = "そうよ、元気出して、PlayerName。\n必ず何か方法があるわ！",
  ui_story_1011_10110702_93_dialog_content = "うん、急いでもっと下層のエリアへ行ってみよう。",
  ui_story_1011_10110702_94_dialog_content = "この下の空間は…<color=#FFB400>「追放区」</color>？",
  ui_story_1011_10110702_95_dialog_content = "追放？",
  ui_story_1011_10110702_96_dialog_content = "どういうことかしら…空の末裔は平和を愛する種族のはずよ。\nどうして、わざわざそんな空間を…",
  ui_story_1011_10110702_97_dialog_content = "…侵入してきた古代の暗鬼を追放するための空間というなら、\n筋の通らないこともないと思うわ。",
  ui_story_1011_10110702_98_dialog_content = "いずれにせよ、\nいい場所ではなさそうだね…気を付けよう。",
  ui_story_1011_10110901_1_dialog_content = "<color=#e8d9bb>回帰の塔、追放区</color>",
  ui_story_1011_10110901_2_dialog_content = "…すーっ…ふぅ…",
  ui_story_1011_10110901_3_dialog_content = "（何か暗い部分のありそうな場所だって分かってると、\nかえって緊張しちゃうわね…）",
  ui_story_1011_10110901_4_dialog_content = "（暗鬼か何かが出てきたら、\nすぐに射たないと…）",
  ui_story_1011_10110901_5_dialog_content = "ピーポーピーポーパ～♪",
  ui_story_1011_10110901_6_dialog_content = "タララララ、ラララ、ラララ、ララ～♪",
  ui_story_1011_10110901_7_dialog_content = "「去りゆくものは、いずれ必ず去り～、\n残るべきものは、永遠に残る～♪」",
  ui_story_1011_10110901_8_dialog_content = "耳障りね…",
  ui_story_1011_10110901_9_dialog_content = "PlayerName、いつ暗鬼が出てくるかも分からない状況よ。\n少し控えてもらうように伝えて。",
  ui_story_1011_10110901_10_dialog_content = "…精神感知を試してみる。",
  ui_story_1011_10110901_11_dialog_content = "精神感知を開始しました。",
  ui_story_1011_10110901_12_dialog_content = "サブブレーンは空の末裔のため、\n安全でお手すきの時間に、いつでも音楽を再生します。",
  ui_story_1011_10110901_13_dialog_content = "お気に入りのものがありましたか？",
  ui_story_1011_10110901_14_dialog_content = "まともな音楽にはとても聞こえなかったけど、\nひとまずそういうものだと思っておくよ…",
  ui_story_1011_10110901_15_dialog_content = "空の末裔はどなたでも、\nサブブレーンの音楽ランダム再生リストを修正できます…",
  ui_story_1011_10110901_16_dialog_content = "空の末裔のお好みに合わせ、自動修正を行うこともできます。\n修正しますか？",
  ui_story_1011_10110901_17_dialog_content = "…いや、このままでいいよ。",
  ui_story_1011_10110901_18_dialog_content = "（この音楽だって、過去からの記憶だ…）",
  ui_story_1011_10110901_19_dialog_content = "でも、サブブレーンは\n安全だって判断してるから音楽を流してるみたいだし…",
  ui_story_1011_10110901_20_dialog_content = "ひとまず、緊張しないでいいってことだね。",
  ui_story_1011_10110901_21_dialog_content = "でも、この階…やっぱり、気分が悪くなるわ。",
  ui_story_1011_10110901_22_dialog_content = "生命体の活動の痕跡はほぼないけれど…",
  ui_story_1011_10110901_23_dialog_content = "この部屋の扉の裏側…",
  ui_story_1011_10110901_24_dialog_content = "つ、爪で引っかいた痕…？",
  ui_story_1011_10110901_25_dialog_content = "部屋がすき間なく連なっている様子からして、\nここはおそらく…",
  ui_story_1011_10110901_26_dialog_content = "監獄ね。白夜城のものと似ているわ。",
  ui_story_1011_10110901_27_dialog_content = "…",
  ui_story_1011_10110901_28_dialog_content = "でも、なんで暗鬼を閉じ込めなきゃいけなかったのかな？\n倒しちゃえばいいんじゃないの？",
  ui_story_1011_10110901_29_dialog_content = "古代の空の末裔も戦闘能力がなかったから…とか？",
  ui_story_1011_10110901_30_dialog_content = "いえ…戦闘能力が本人になかったとしても、\n私たちが今まで見て来た技術があれば…",
  ui_story_1011_10110901_31_dialog_content = "戦闘や防衛用の兵器を作る力は十分にあったはずね…",
  ui_story_1011_10110901_32_dialog_content = "<color=#e8d9bb>チャリン…</color>",
  ui_story_1011_10110901_33_dialog_content = "え？",
  ui_story_1011_10110901_34_dialog_content = "何かを蹴ったようね。",
  ui_story_1011_10110901_35_dialog_content = "何かしら…",
  ui_story_1011_10110901_36_dialog_content = "これは…！？",
  ui_story_1011_10110901_37_dialog_content = "スチール製のネームプレート！？",
  ui_story_1011_10110901_38_dialog_content = "「名前：テノチ、空の末裔」…",
  ui_story_1011_10110901_39_dialog_content = "つ…「<color=#FFB400>追放期間</color>：14年」…",
  ui_story_1011_10110901_40_dialog_content = "ここにもあるわね。\n「名前：ディラン、空の末裔。追放期間：12年」…",
  ui_story_1011_10110901_41_dialog_content = "…閉じ込められていたのは\n全員、あなたの同族のようね、PlayerName。",
  ui_story_1011_10110901_42_dialog_content = "じゃあ、「追放区」っていうのは…\n「空の末裔用の牢獄」ってこと！？",
  ui_story_1011_10110901_43_dialog_content = "でも、どうして…同族を閉じ込めてたの？",
  ui_story_1011_10110901_44_dialog_content = "「平和を愛する」っていうのは、ウソだったの！？",
  ui_story_1011_10110901_45_dialog_content = "落ち着いて、PlayerName。\nまだそうと決まったわけでもないわ。興奮は禁物よ。",
  ui_story_1011_10110901_46_dialog_content = "それに、考えてみることね。\n相当な規模の人口を抱える集団なら…",
  ui_story_1011_10110901_47_dialog_content = "必ず強制力をもって、\n秩序を保つ必要が出てくるものよ。",
  ui_story_1011_10110901_48_dialog_content = "でも、空の末裔なら、お互いの意識を接続すれば、\nそういうことはできるでしょ。",
  ui_story_1011_10110901_49_dialog_content = "同族をわざわざ閉じ込めて、\n苦しめる必要がどこにあるの？",
  ui_story_1011_10110901_50_dialog_content = "サブブレーン、今の質問に答えて。",
  ui_story_1011_10110901_51_dialog_content = "質問を分析中…\nキーワード検出に成功。回答を生成中――",
  ui_story_1011_10110901_52_dialog_content = "<color=#FFB400>フランシス先生</color>によると、\n「あの時から、私たちとあの者たちは同族ではなくなった」からです。",
  ui_story_1011_10110901_53_dialog_content = "！？",
  ui_story_1011_10110901_54_dialog_content = "「同族ではなくなった」ってどういう意味？",
  ui_story_1011_10110901_55_dialog_content = "どういう人たちなの？",
  ui_story_1011_10110901_56_dialog_content = "まさか…数千年前には、空の末裔の間で、\n何か<color=#FFB400>解決出来ないような対立</color>があったってこと？",
  ui_story_1011_10110901_57_dialog_content = "（それが同族を牢屋に閉じ込める理由…？）",
  ui_story_1011_10110901_57X1_dialog_content = "質問を分析中…",
  ui_story_1011_10110901_57X2_dialog_content = "現存するビッグデータによると、\n大多数の空の末裔とフランシス先生との関係は良好ではありませんでした。",
  ui_story_1011_10110901_57X3_dialog_content = "先生もかつて「追放区」に\n送られたことがあります。",
  ui_story_1011_10110901_57X3X1_dialog_content = "なお、「追放区」は空の末裔の\n異端者を監禁する施設です。",
  ui_story_1011_10110901_57X3X2_dialog_content = "フランシス先生および、部下の研究員たちは、\n全員が同一の理由で追放区に送られています。",
  ui_story_1011_10110901_57X3X3_dialog_content = "追放理由は、「扇動的思想、行き過ぎた理念」でした。",
  ui_story_1011_10110901_57X4_dialog_content = "「フランシス」という名前に関連する情報は、すべて閲覧に注意が必要です…\n関連するキーワードを例として再生します…",
  ui_story_1011_10110901_57X5_dialog_content = "変わり者、狂人、\n精神制御の専門家、脳みそ収集家…",
  ui_story_1011_10110901_57X6_dialog_content = "…もういいわ、PlayerName。\n読み上げを止めさせて…",
  ui_story_1011_10110901_57X7_dialog_content = "ええと…ちょっと変わった研究者だったみたいだね…",
  ui_story_1011_10110901_57X8_dialog_content = "フランシス先生は様々な新技術の研究に尽力していました。",
  ui_story_1011_10110901_57X9_dialog_content = "先生の口癖は\n「研究に障害はつきものだ。理解されないのもよくあることだ」でした。",
  ui_story_1011_10110901_57X10_dialog_content = "光線銃以外にも、フランシス先生による重要な発明があり…",
  ui_story_1011_10110901_57X11_dialog_content = "空の末裔のお連れの方の形式からお分かりの通り…\nそれ以降の世界を変えたと言えるでしょう。",
  ui_story_1011_10110901_57X12_dialog_content = "世界を…変えた？",
  ui_story_1011_10110901_57X13_dialog_content = "現在の空の末裔は、\n古代と立場も習慣も変化しています。",
  ui_story_1011_10110901_57X14_dialog_content = "光霊、亜人といった種族と共に、\n同じ敵に立ち向かうことは…",
  ui_story_1011_10110901_57X15_dialog_content = "フランシス先生が存命であれば、\nおそらく喜んだことでしょう。",
  ui_story_1011_10110901_57X16_dialog_content = "「立場と習慣」？だったら…\n古代の空の末裔って、一体どういう人たちだったの？",
  ui_story_1011_10110901_57X17_dialog_content = "その「最も偉大な発明」って、何？",
  ui_story_1011_10110901_58_dialog_content = "空の末裔の権限を確認しています…",
  ui_story_1011_10110901_59_dialog_content = "申し訳ありません。権限が付与されていません。\nサブブレーンは解答できません。",
  ui_story_1011_10110901_60_dialog_content = "そう、分かったよ。\nでも、いくつか簡単な質問には答えてもらえるよね？",
  ui_story_1011_10110901_61_dialog_content = "さっきの話に戻るけど…",
  ui_story_1011_10110901_61X1_dialog_content = "「あの時から、私たちとあの者たちは\n同族ではなくなった」…",
  ui_story_1011_10110901_63_dialog_content = "その人の言った「私たち」って、\n空の末裔を指してるの？",
  ui_story_1011_10110901_64_dialog_content = "回答を生成しました。「私たち」は空の末裔です。",
  ui_story_1011_10110901_65_dialog_content = "…",
  ui_story_1011_10110901_66_dialog_content = "エラー、エラー。サブブレーンは空の末裔ではありません。",
  ui_story_1011_10110901_67_dialog_content = "サブブレーンの機能紹介を再生します。\nサブブレーンは回帰の塔内部のサービス用人工知能です…",
  ui_story_1011_10110901_68_dialog_content = "…僕の質問をちゃんと聞いて！？\n誰も君みたいな機械を空の末裔だなんて思わないよ！",
  ui_story_1011_10110901_69_dialog_content = "サブブレーンは空の末裔の権限と指示に基づき、\n空の末裔に必要なサポートを行います…",
  ui_story_1011_10110901_70_dialog_content = "うーん、面倒臭い人工知能だなぁ…",
  ui_story_1011_10110901_71_dialog_content = "フランシス？",
  ui_story_1011_10110901_72_dialog_content = "PlayerName、上の階で見たコップを覚えている？",
  ui_story_1011_10110901_73_dialog_content = "言われてみれば、\nあのコップの底にあった、読みづらい印は…",
  ui_story_1011_10110901_74_dialog_content = "その人のコップだった…？",
  ui_story_1011_10110901_75_dialog_content = "質問を分析中…\n回答を生成しました。フランシス先生はドリンク剤を常用していました。",
  ui_story_1011_10110901_76_dialog_content = "コップを常に持ち歩いていたようです。",
  ui_story_1011_10110901_77_dialog_content = "（まさか、本当に…）",
  ui_story_1011_10110901_78_dialog_content = "該当のドリンク剤の機能紹介、再生中…\n回帰の塔にしかない特別な飲み物です。リフレッシュ効果があります。",
  ui_story_1011_10110901_79_dialog_content = "（聞いてもいないよ！）",
  ui_story_1011_10110901_80_dialog_content = "空の末裔の居住区、資源生産区、追放区で\n入手可能です…",
  ui_story_1011_10110901_81_dialog_content = "上記エリアの無人販売機で購入することができます。",
  ui_story_1011_10110901_82_dialog_content = "（販売機！？）",
  ui_story_1011_10110901_83_dialog_content = "（じゃあ…間違いないわ！）",
  ui_story_1011_10110901_84_dialog_content = "PlayerName、カレン、付いて来て！",
  ui_story_1011_10110901_85_dialog_content = "<color=#e8d9bb>回帰の塔内部、追放区、販売機の側</color>",
  ui_story_1011_10110901_86_dialog_content = "<color=#e8d9bb>バン！バン！！</color>",
  ui_story_1011_10110901_87_dialog_content = "ふぅ…やった、何回か蹴っただけで動き出したわ！",
  ui_story_1011_10110901_88_dialog_content = "これがサブブレーンの言っていた装置？",
  ui_story_1011_10110901_89_dialog_content = "…見覚えがある気がしてならないわ。",
  ui_story_1011_10110901_90_dialog_content = "そうだね…「人工知能」と「無人販売機」って、\n地下遺跡ならどこにでもあるのかな？",
  ui_story_1011_10110901_91_dialog_content = "ふふふ…これを見て。",
  ui_story_1011_10110901_92_dialog_content = "ジャーン！",
  ui_story_1011_10110901_93_dialog_content = "ああ、あれを持ってきてたの？",
  ui_story_1011_10110901_94_dialog_content = "自分の推測を検証してみたかったのよね。",
  ui_story_1011_10110901_95_dialog_content = "このオウムガイみたいな形と\n中に入ってた液体を見て思ったの…",
  ui_story_1011_10110901_96_dialog_content = "空の末裔には、水を飲むコップみたいな容器が普通にあったし、\nあそこで貝を食べてたわけでもなさそう…",
  ui_story_1011_10110901_97_dialog_content = "だったら、古代の空の末裔は、\nこれを何に使ってたのか…",
  ui_story_1011_10110901_98_dialog_content = "答えが、たぶん分かったの。\nさあ、見てて――",
  ui_story_1011_10110901_99_dialog_content = "オウムガイの中の液体を、\n販売機のこの穴に流し込めば…",
  ui_story_1011_10110901_100_dialog_content = "<color=#e8d9bb>ガチャン！…ガタン！</color>",
  ui_story_1011_10110901_101_dialog_content = "やったわ！",
  ui_story_1011_10110901_102_dialog_content = "ほら、ドリンクが買えたわ！\n…変質しちゃってるだろうし、飲むことはできなさそうだけど。",
  ui_story_1011_10110901_103_dialog_content = "なぜ分かったの？",
  ui_story_1011_10110901_104_dialog_content = "オウムガイを見た時に、\n思いだしたことだけど…",
  ui_story_1011_10110901_105_dialog_content = "オウムガイの形が作る線って、\n特別な意味があるのよ。",
  ui_story_1011_10110901_106_dialog_content = "数学的言語で表された「自然」っていう。",
  ui_story_1011_10110901_107_dialog_content = "「自然」…？よく分からないよ。\nその線と自然と、何の関係があるの？",
  ui_story_1011_10110901_108_dialog_content = "自然っていうのは、\n僕たちの周りにある草花や樹木のことでしょ？",
  ui_story_1011_10110901_109_dialog_content = "ええ、その通り。\n草花も樹木も全部自然よ。",
  ui_story_1011_10110901_110_dialog_content = "でも、オウムガイが示すものは、\nそういうものに通じる自然の摂理なの。",
  ui_story_1011_10110901_111_dialog_content = "要するに…オウムガイの曲線は、\n万物の成長の過程を表しているの。",
  ui_story_1011_10110901_112_dialog_content = "「連続性」って言えばいいかしら。",
  ui_story_1011_10110901_113_dialog_content = "「連続性」？",
  ui_story_1011_10110901_114_dialog_content = "そうよ。1つの種が、\nすぐに大きな樹になることはないでしょ。",
  ui_story_1011_10110901_115_dialog_content = "毎分毎秒、一瞬一瞬、ずっと成長を続けてるものよ。",
  ui_story_1011_10110901_116_dialog_content = "「連続性」っていうのは、\nそうした成長と変化の過程を指すの。",
  ui_story_1011_10110901_117_dialog_content = "うーん、少し分かったような気がする…かも？",
  ui_story_1011_10110901_118_dialog_content = "もし、古代の空の末裔にとって「連続性」が\n科学的な考え方の基本になってるなら…",
  ui_story_1011_10110901_119_dialog_content = "生活の中で使われるものも、\nきっと私たちのものと違うだろうなって思ったの。",
  ui_story_1011_10110901_120_dialog_content = "それがいちばん表に出てるのが…\n価値を保存するもの、つまりお金ってワケ！",
  ui_story_1011_10110901_121_dialog_content = "うーん、僕たちが使ってるコインや紙幣は\n「連続性」がないってこと？",
  ui_story_1011_10110901_122_dialog_content = "そうよ。だから、これが空の末裔にとってのお金。\nこのオウムガイの中身を見るといいわ。",
  ui_story_1011_10110901_123_dialog_content = "…液体？",
  ui_story_1011_10110901_124_dialog_content = "つまり、このオウムガイが、\n古代の空の末裔の財布ってこと？",
  ui_story_1011_10110901_125_dialog_content = "質問を分析中…\n回答を生成しました。貝殻は価値を保存する容器です。",
  ui_story_1011_10110901_126_dialog_content = "回帰の塔内での取引は、\n液体の容量によって、ものの価値を表現します。",
  ui_story_1011_10110901_127_dialog_content = "空の末裔は、貝殻の中の液体で\n取引を行うことができます。",
  ui_story_1011_10110901_128_dialog_content = "なるほど。\nその方面のことはよく分からないけれど…",
  ui_story_1011_10110901_129_dialog_content = "とても美しい価値観に感じられるわね。",
  ui_story_1011_10110901_130_dialog_content = "「自然」を価値のあるものとみなした、\n「連続性」に基づく度量衡…",
  ui_story_1011_10110901_131_dialog_content = "空の末裔という一族の印象と一貫している。",
  ui_story_1011_10110901_132_dialog_content = "すごいね、バイス！君の説明とサブブレーンの説明、\nほとんど同じ…気がする！",
  ui_story_1011_10110901_133_dialog_content = "そ、それほどでもないわ…",
  ui_story_1011_10110901_134_dialog_content = "それより、急いで先に進みましょう。",
  ui_story_1011_10110901_135_dialog_content = "下の階に続く階段は、見当たらないわ。",
  ui_story_1011_10110901_136_dialog_content = "追放区が回帰の塔の最低層だった？",
  ui_story_1011_10110901_137_dialog_content = "そんなはずないよ。サブブレーンの地図では、\n追放区はちょうど真ん中にあるはずだよ。",
  ui_story_1011_10110901_138_dialog_content = "サブブレーン、下の階に行く通路の位置を教えて。",
  ui_story_1011_10110901_139_dialog_content = "質問を分析中…\n回答が生成されました。下の階への通路はすでに崩壊しています。",
  ui_story_1011_10110901_140_dialog_content = "やむを得ず、下の階へ向かう場合は…",
  ui_story_1011_10110901_141_dialog_content = "斜め後ろ方向にある、\n2つの販売機のすき間から進入してください。",
  ui_story_1011_10110901_142_dialog_content = "<color=#e8d9bb>塔内部、すき間の中</color>",
  ui_story_1011_10110901_143_dialog_content = "うう…すごく暗くて狭いわ…\n私たちが入って来た通路より、もっと狭いんじゃないかしら。",
  ui_story_1011_10110901_144_dialog_content = "私も何とか手足を広げられる程度ね。",
  ui_story_1011_10110901_145_dialog_content = "（私たちが入って来たことで、\nこれ以上崩落しないといいけれど…）",
  ui_story_1011_10110901_146_dialog_content = "もう少し急いで、PlayerName。",
  ui_story_1011_10110901_147_dialog_content = "わ、分かったよ…",
  ui_story_1011_10110901_148_dialog_content = "ピピピ…",
  ui_story_1011_10110901_149_dialog_content = "警告、前方50ｍに生命体を検知。",
  ui_story_1011_10110901_150_dialog_content = "警告、前方50ｍ、生命体が接近中。",
  ui_story_1011_10110901_151_dialog_content = "え！？こんな狭い道で…",
  ui_story_1011_10110901_152_dialog_content = "まさか、こんな所に野生の暗鬼でもいるの！？",
  ui_story_1011_10110901_153_dialog_content = "警告、前方40ｍ、生命体が接近中。",
  ui_story_1011_10110901_154_dialog_content = "警告、前方30ｍ…",
  ui_story_1011_10110901_155_dialog_content = "PlayerName、何か方法は！？",
  ui_story_1011_10110901_156_dialog_content = "警告、前方10mに生命体を検知、ID確認中…",
  ui_story_1011_10110901_157_dialog_content = "…感知に反応がない…\n少なくとも空の末裔ではないね。",
  ui_story_1011_10110901_158_dialog_content = "皆、迎撃の準備をして。",
  ui_story_1011_10110901_159_dialog_content = "分析完了、ID…暗鬼。",
  ui_story_1011_10110901_160_dialog_content = "ガァ…",
  ui_story_1011_10110901_161_dialog_content = "グオオォ！！！",
  ui_story_1011_10110901_162_dialog_content = "地形がやっかいだ、\n2人とも気を付けて！",
  ui_story_1011_10110902_1_dialog_content = "グォォ…",
  ui_story_1011_10110902_2_dialog_content = "もう少し注意するべきだったわね…",
  ui_story_1011_10110902_3_dialog_content = "廃墟に戦闘の痕跡が残っている…\n早めに警戒するべきだったわ。",
  ui_story_1011_10110902_4_dialog_content = "追放区…監獄とつながる秘密の通路なら…\n危険があっても不思議はないわね。",
  ui_story_1011_10110902_5_dialog_content = "今さら、後戻りもできないわ。",
  ui_story_1011_10110902_6_dialog_content = "（<color=#FFB400>戦いの痕跡</color>と言えば…）",
  ui_story_1011_10110902_7_dialog_content = "サブブレーン、地上の遺跡をスキャンして…\nどんな情報でもいいから、報告して。",
  ui_story_1011_10110902_8_dialog_content = "スキャン機能起動中…",
  ui_story_1011_10110902_9_dialog_content = "データベースと情報を照合しています…",
  ui_story_1011_10110902_10_dialog_content = "スキャンが完了しました。",
  ui_story_1011_10110902_11_dialog_content = "結果は？",
  ui_story_1011_10110902_12_dialog_content = "現在スキャンレポートを生成しています…\n空の末裔と暗鬼による戦闘の痕跡を確認しました。",
  ui_story_1011_10110902_13_dialog_content = "分析によると、この地の地質成分には、\n約200体の低級暗鬼の死体が含まれ、40体の空の末裔の…",
  ui_story_1011_10110902_14_dialog_content = "うっ…",
  ui_story_1011_10110902_15_dialog_content = "前方およそ10mの位置に、空の末裔の識別票16枚と\n空の末裔が使用していた<color=#FFB400>武器</color>があります。",
  ui_story_1011_10110902_16_dialog_content = "あれは…武器？",
  ui_story_1011_10110902_17_dialog_content = "サブブレーンの言った通りよ。見て。",
  ui_story_1011_10110902_18_dialog_content = "落石の側に銃が2丁…損傷などはないようね。",
  ui_story_1011_10110902_19_dialog_content = "スキャンレポートを生成しています…",
  ui_story_1011_10110902_20_dialog_content = "スキャン結果更新…エネルギー装填されていない銃が1丁、\n空の末裔が使用可能な武器は現在、1丁のみです。",
  ui_story_1011_10110902_21_dialog_content = "これのことね。",
  ui_story_1011_10110902_22_dialog_content = "意外に小さいね…",
  ui_story_1011_10110902_23_dialog_content = "つまり、これが…ええと…\nエネルギー装填済みの、使える銃？",
  ui_story_1011_10110902_24_dialog_content = "質問を分析中…\n光線銃の紹介を再生します…",
  ui_story_1011_10110902_25_dialog_content = "名称：光線銃。発明者：フランシス",
  ui_story_1011_10110902_26_dialog_content = "使用対象：<color=#FFB400>暗鬼に有効</color>、\n使用可能者：空の末裔、一般。",
  ui_story_1011_10110902_27_dialog_content = "使用方法：感知能力により銃身と精神感知を構築することで、\n効率よく小型暗鬼を撃退できます。",
  ui_story_1011_10110902_28_dialog_content = "（銃にも人工知能が使われてるってこと！？）",
  ui_story_1011_10110902_29_dialog_content = "…あれ？",
  ui_story_1011_10110902_30_dialog_content = "銃の持ち手にでこぼこした刻印がある…",
  ui_story_1011_10110902_31_dialog_content = "スキャン結果補足：この武器の所有者はフランシス先生です。",
  ui_story_1011_10110902_32_dialog_content = "また、その人！？",
  ui_story_1011_10110902_33_dialog_content = "（断片的な情報しか知らないけど、\nフランシス先生って、きっとすごい人だったんだろうな…）",
  ui_story_1011_10110902_34_dialog_content = "警告、後方50ｍ、生命体が接近中。",
  ui_story_1011_10110902_35_dialog_content = "ちょうどいいわね。",
  ui_story_1011_10110902_36_dialog_content = "試し撃ちしてみたら？PlayerName。\n私とカレンがカバーするから。",
  ui_story_1011_10110902_37_dialog_content = "ありがとう！",
  ui_story_1011_10110902_38_dialog_content = "（ドキドキ…）",
  ui_story_1011_10110902_39_dialog_content = "（戦いは何度となく指揮してきたけど、\n自分で戦うのは初めてだ。やっぱり緊張するなあ…）",
  ui_story_1011_10110902_40_dialog_content = "ガウッ…",
  ui_story_1011_10110902_41_dialog_content = "グア！！！",
  ui_story_1011_10110902_42_dialog_content = "（今だ！）",
  ui_story_1011_10110902_43_dialog_content = "<color=#e8d9bb>バン！バン！</color>",
  ui_story_1011_10110902_44_dialog_content = "ガァ…",
  ui_story_1011_10110902_45_dialog_content = "た、倒した！",
  ui_story_1011_10110902_46_dialog_content = "致命傷ではないけれど、\n気は失ったようね。",
  ui_story_1011_10110902_47_dialog_content = "1撃で？\nそんなに便利な武器だとは思わなかったわ！",
  ui_story_1011_10110902_48_dialog_content = "それに、PlayerNameの手も震えてなかったし、\nそれだけでもほめてあげないとね。",
  ui_story_1011_10110902_49_dialog_content = "ハハ…どうもありがとう…",
  ui_story_1011_10110902_50_dialog_content = "とにかく、この銃のおかげで、戦力が増えたわ。",
  ui_story_1011_10110902_51_dialog_content = "このまま下へ向かいましょう。",
  ui_story_1011_10111001_1_dialog_content = "グア！！！",
  ui_story_1011_10111001_2_dialog_content = "グォォ！！！",
  ui_story_1011_10111001_3_dialog_content = "ガアアア！！",
  ui_story_1011_10111001_4_dialog_content = "<color=#e8d9bb>バシュン！バシュン！</color>",
  ui_story_1011_10111001_5_dialog_content = "だんだん慣れてきてるわね…PlayerName。",
  ui_story_1011_10111001_6_dialog_content = "強力な武器があると言っても、\nこの数は頭が痛いわね…",
  ui_story_1011_10111001_7_dialog_content = "この暗鬼たち、一体どこから…",
  ui_story_1011_10111001_8_dialog_content = "（まさか、本当に暗鬼が原生しているとでも…？）",
  ui_story_1011_10111001_9_dialog_content = "おかしいわね。\n暗鬼と私たち、同じ方向を目指してるみたい…",
  ui_story_1011_10111001_10_dialog_content = "暗鬼には自分の意識なんてないはずだから、\n何かに引き付けられてるってことなの？",
  ui_story_1011_10111001_11_dialog_content = "（引き付けられる？）",
  ui_story_1011_10111001_12_dialog_content = "（まさか、日蝕が何かやってる？それとも…）",
  ui_story_1011_10111001_13_dialog_content = "<color=#e8d9bb>ゴゴゴ…ゴゴゴ…</color>",
  ui_story_1011_10111001_14_dialog_content = "まずいわね…",
  ui_story_1011_10111001_15_dialog_content = "何かがすごいスピードで近づいてくる！",
  ui_story_1011_10111001_16_dialog_content = "やっぱり、統率してるヤツがいるんだ！",
  ui_story_1011_10111001_17_dialog_content = "警告、前方3…警告、前方2…警告、前方10ｍに生命体を検知！",
  ui_story_1011_10111001_18_dialog_content = "<color=#e8d9bb>ゴゴゴ――</color>",
  ui_story_1011_10111001_19_dialog_content = "グォォ――！！！",
  ui_story_1011_10111001_20_dialog_content = "グォォ…",
  ui_story_1011_10111001_21_dialog_content = "これ、さっきの暗鬼じゃない！？",
  ui_story_1011_10111001_22_dialog_content = "…もう倒したはずじゃ…\nなんでこんなにしぶといの？",
  ui_story_1011_10111001_23_dialog_content = "バイス、カレン！さがって！",
  ui_story_1011_10111001_24_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_1011_10111001_25_dialog_content = "はぁ、はぁ…",
  ui_story_1011_10111001_26_dialog_content = "危なかった…この銃があってよかった。",
  ui_story_1011_10111001_27_dialog_content = "ガァ…",
  ui_story_1011_10111001_28_dialog_content = "グォォ！！！",
  ui_story_1011_10111001_29_dialog_content = "え！？",
  ui_story_1011_10111001_30_dialog_content = "効いてない！？",
  ui_story_1011_10111001_31_dialog_content = "グォォ！！！！！！",
  ui_story_1011_10111001_32_dialog_content = "PlayerName、\n足を止めないで、逃げて！",
  ui_story_1011_10111001_33_dialog_content = "逃げるって、先に進むの？\nでも、何があるか…",
  ui_story_1011_10111001_34_dialog_content = "考えてる余裕はないわ！",
  ui_story_1011_10111001_35_dialog_content = "サブブレーン！\n警報を起動して、何かあったら知らせて！",
  ui_story_1011_10111001_36_dialog_content = "長期持続警報システム、起動しました。\n警告、後方50ｍに生命体を検知。",
  ui_story_1011_10111001_37_dialog_content = "警告、後方10ｍに生命体を検知！",
  ui_story_1011_10111001_38_dialog_content = "警告、後方15ｍに生命体を検知、接近中…",
  ui_story_1011_10111001_39_dialog_content = "警告、後方10ｍに生命体を検知、接近中…",
  ui_story_1011_10111001_40_dialog_content = "ふぅ…ふぅ…まったく引き離せないわ！",
  ui_story_1011_10111001_41_dialog_content = "PlayerName、早く付いて来て！",
  ui_story_1011_10111001_42_dialog_content = "う、うん！！",
  ui_story_1011_10111001_43_dialog_content = "警告、後方30ｍに生命体を検知、接近中…",
  ui_story_1011_10111001_44_dialog_content = "足を止めちゃダメ！",
  ui_story_1011_10111001_45_dialog_content = "<color=#e8d9bb>ドンッ――！</color>",
  ui_story_1011_10111001_46_dialog_content = "あいたた…",
  ui_story_1011_10111001_47_dialog_content = "何でこんな所に…",
  ui_story_1011_10111001_48_dialog_content = "え…？",
  ui_story_1011_10111001_49_dialog_content = "バイス！どうしたの？",
  ui_story_1011_10111001_50_dialog_content = "ぶつかったの！こんなに細い秘密の通路に、\nなんでこんな機械が置いてあるのかしら…？",
  ui_story_1011_10111001_51_dialog_content = "見たところ、何かの操作台ね。\nサブブレーンの形と似てるわ…",
  ui_story_1011_10111001_52_dialog_content = "でも、なんであろうと道のど真ん中に\n物なんて置いたらジャマに…",
  ui_story_1011_10111001_53_dialog_content = "…いや、ジャマするために\n置かれてるとしたら…使えるかも？",
  ui_story_1011_10111001_54_dialog_content = "警告、後方25ｍに生命体を検知…",
  ui_story_1011_10111001_55_dialog_content = "サブブレーン、早く、この機械の使い方を教えて！",
  ui_story_1011_10111001_56_dialog_content = "サブブレーンの長期警戒システムが作動中は、\n指令の変更が出来ません。",
  ui_story_1011_10111001_57_dialog_content = "警告、後方10ｍに生命体を検知…",
  ui_story_1011_10111001_58_dialog_content = "…まったく、肝心な時に…\nでも、見た目は啓光の操作台とほとんど変わりないわ！",
  ui_story_1011_10111001_59_dialog_content = "ただやられるのを待つぐらいなら、\n試してみるしかないわね！",
  ui_story_1011_10111001_60_dialog_content = "PlayerName、あなたなら認証システムは\nなんとかできるはず！頼んだわよ！",
  ui_story_1011_10111001_61_dialog_content = "わ、分かったよ！",
  ui_story_1011_10111001_62_option_content = "強制感知！",
  ui_story_1011_10111001_63_dialog_content = "まず、ロックを外して、起動する…",
  ui_story_1011_10111001_64_dialog_content = "それから…",
  ui_story_1011_10111001_65_dialog_content = "とにかく暗鬼に向けてみましょ！",
  ui_story_1011_10111001_66_dialog_content = "<color=#e8d9bb>バシュン！</color>",
  ui_story_1011_10111001_67_dialog_content = "（この光…銃と同じ、暗鬼に効くもの？）",
  ui_story_1011_10111001_68_dialog_content = "グォォ！！！",
  ui_story_1011_10111001_69_dialog_content = "ガァ…",
  ui_story_1011_10111001_70_dialog_content = "（すごい威力だ！）",
  ui_story_1011_10111001_71_dialog_content = "なるほど…PlayerName、\nこの機械、その銃と似たような仕組みみたいね！",
  ui_story_1011_10111001_72_dialog_content = "いえ、銃よりもずっと強力そうだわ！",
  ui_story_1011_10111001_73_dialog_content = "グォォ！",
  ui_story_1011_10111001_74_dialog_content = "グォォ！！",
  ui_story_1011_10111001_75_dialog_content = "グォォ！！！",
  ui_story_1011_10111001_76_dialog_content = "（暗鬼の注意を引き付けちゃった！？）",
  ui_story_1011_10111001_77_dialog_content = "バイス、危ない！",
  ui_story_1011_10111001_78_dialog_content = "散れ！氷花よ！",
  ui_story_1011_10111001_79_dialog_content = "…うっ！",
  ui_story_1011_10111001_80_dialog_content = "バイス、ムリそうなら早く戻って！",
  ui_story_1011_10111001_81_dialog_content = "（やっとここまで来たのに…\n目の前に、こんなに強力な武器があるのに…）",
  ui_story_1011_10111001_82_dialog_content = "（落ち着いて…必ず方法はあるはず）",
  ui_story_1011_10111001_83_dialog_content = "（これだわ！<color=#FFB400>「全範囲攻撃命令」</color>！）",
  ui_story_1011_10111001_84_dialog_content = "<color=#e8d9bb>ピピピピ…ボン！！！</color>",
  ui_story_1011_10111001_85_dialog_content = "<color=#e8d9bb>バン！！！ドン！！！</color>",
  ui_story_1011_10111001_86_dialog_content = "ふぅ…ふぅ…バイス？",
  ui_story_1011_10111001_87_dialog_content = "バイス！？",
  ui_story_1011_10111001_88_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1011_10111001_89_dialog_content = "バ、バイス！！！",
  ui_story_1011_10111001_90_dialog_content = "（そんなはずはない…意識感知はまだつながってる、\nバイスに何かあるはずが…）",
  ui_story_1011_10111001_91_dialog_content = "バイス！！！",
  ui_story_1011_10111001_92_dialog_content = "ゴホゴホ…ここよ！PlayerName、カレン！",
  ui_story_1011_10111001_93_dialog_content = "よかった！",
  ui_story_1011_10111001_94_dialog_content = "バイス！ビックリさせないでよ。\n君に何かあったかと…",
  ui_story_1011_10111001_95_dialog_content = "<color=#e8d9bb>ピピピピ…</color>",
  ui_story_1011_10111001_96_dialog_content = "…えっ？",
  ui_story_1011_10111001_97_dialog_content = "<color=#e8d9bb>――ドン！！！</color>",
  ui_story_1011_10111001_98_dialog_content = "！？",
  ui_story_1011_10111001_99_dialog_content = "<color=#e8d9bb>ピピピピ…</color>",
  ui_story_1011_10111001_100_dialog_content = "攻撃対象は見つかりません。\n「全範囲攻撃命令」を終了します。",
  ui_story_1011_10111001_101_dialog_content = "ど、どうして…",
  ui_story_1011_10111001_102_dialog_content = "どうして…",
  ui_story_1011_10111001_103_dialog_content = "<size=50>バイス！！！！！！！</size>",
  ui_story_1011_10111001_104_dialog_content = "バイス…バイス！",
  ui_story_1011_10111001_105_dialog_content = "（まずい！）",
  ui_story_1011_10111001_106_dialog_content = "カレン！行っちゃダメだ！",
  ui_story_1011_10111001_107_dialog_content = "何かがおかしい！機械の前に出たらダメだ！",
  ui_story_1011_10111001_108_option_content = "感知切断！",
  ui_story_1011_10111001_109_option_content = "…感知切断…？",
  ui_story_1011_10111001_110_dialog_content = "（機械が反応しない…！？）",
  ui_story_1011_10111001_111_dialog_content = "カレン、隠れて！",
  ui_story_1011_10111001_112_dialog_content = "分かったわ…",
  ui_story_1011_10111001_113_dialog_content = "<color=#e8d9bb>ピピピピ…</color>",
  ui_story_1011_10111001_114_dialog_content = "！？",
  ui_story_1011_10111001_115_dialog_content = "（見つかった！？）",
  ui_story_1011_10111001_116_dialog_content = "（月繭で防げるかどうか…）",
  ui_story_1011_10111001_117_dialog_content = "グォォ！！！",
  ui_story_1011_10111001_118_dialog_content = "<color=#e8d9bb>――ドン！！！</color>",
  ui_story_1011_10111001_119_dialog_content = "（こんな時に、まだ暗鬼まで！）",
  ui_story_1011_10111001_120_option_content = "感知切断！",
  ui_story_1011_10111001_121_dialog_content = "<color=#e8d9bb>ガタン…</color>",
  ui_story_1011_10111001_122_dialog_content = "（やっと止め方が分かった…）",
  ui_story_1011_10111001_123_dialog_content = "PlayerName、まずは暗鬼たちを！\nバイスに近づかせてはダメ！",
  ui_story_1011_10111001_124_dialog_content = "バイスがどうなったか、分からないけれど…\nもたもたしている時間はない！",
  ui_story_1011_10111002_1_dialog_content = "生命体の状態をスキャン中…",
  ui_story_1011_10111002_2_dialog_content = "スキャン結果を生成しています…",
  ui_story_1011_10111002_3_dialog_content = "生命体のスキャン結果…\n鼓動、呼吸などのバイタルサインが一時的に停止しています。",
  ui_story_1011_10111002_4_dialog_content = "<color=#FFB400>「意識消失」</color>状態が確認されました。",
  ui_story_1011_10111002_5_dialog_content = "「意識消失」？",
  ui_story_1011_10111002_6_dialog_content = "PlayerName、現実に向き合いましょう…",
  ui_story_1011_10111002_7_dialog_content = "バイスを助ける方法、急いで考えなければ…",
  ui_story_1011_10111002_8_dialog_content = "わ、分かってる…",
  ui_story_1011_10111002_9_dialog_content = "僕が…サブブレーンと話してみるよ。",
  ui_story_1011_10111002_17_option_content = "「意識消失」って？",
  ui_story_1011_10111002_18_dialog_content = "攻撃装置によって、生命体は「意識消失」状態に陥っています。",
  ui_story_1011_10111002_19_dialog_content = "「意識消失」状態の光霊は、\n特殊な昏睡状態を継続します。",
  ui_story_1011_10111002_20_dialog_content = "昏睡状態？",
  ui_story_1011_10111002_21_dialog_content = "つまり、バイスの目を覚ませばいいだけということ？",
  ui_story_1011_10111002_22_dialog_content = "…もっと詳しく「意識消失」の説明と回復方法を教えて。",
  ui_story_1011_10111002_23_dialog_content = "質問を分析中…",
  ui_story_1011_10111002_24_dialog_content = "回答を生成。「意識消失」状態は通常の\n意識不明な状態とは異なります。",
  ui_story_1011_10111002_25_dialog_content = "「意識消失」した光霊の脈拍と呼吸は、\n無期限に停止します。",
  ui_story_1011_10111002_26_dialog_content = "体内の光子エネルギーも無期限の休眠状態となります。",
  ui_story_1011_10111002_27_dialog_content = "「意識消失」状態の解除方法を検索しています…",
  ui_story_1011_10111002_28_dialog_content = "申し訳ありません。\n該当のデータがありません。サブブレーンには解答できません。",
  ui_story_1011_10111002_29_dialog_content = "データが無いって、どういうこと！？",
  ui_story_1011_10111002_30_dialog_content = "サブブレーンは解決方法を提示できません。",
  ui_story_1011_10111002_31_dialog_content = "…！？",
  ui_story_1011_10111002_32_dialog_content = "それなら、この状態は、つまり…",
  ui_story_1011_10111002_33_dialog_content = "（<color=#FFB400>死んだ</color>も同然…）",
  ui_story_1011_10111002_34_dialog_content = "空の末裔がどうして\nそんなものを開発していたの？",
  ui_story_1011_10111002_36_dialog_content = "そ、そんな…ありえないよ…",
  ui_story_1011_10111002_37_dialog_content = "きっとバイスを回復させる方法があるはず…",
  ui_story_1011_10111002_38_dialog_content = "こ…この遺跡のどこかに、きっと…きっと…",
  ui_story_1011_10111002_39_dialog_content = "でも…",
  ui_story_1011_10111002_40_dialog_content = "私がいち早く暗鬼を全て片付けていれば…",
  ui_story_1011_10111002_41_dialog_content = "あるいはあなたが、\nバイスを止めていれば…",
  ui_story_1011_10111002_41X1_dialog_content = "バイスはこんなことにならなかった…！",
  ui_story_1011_10111002_41X2_dialog_content = "機会はあったはずなのに…",
  ui_story_1011_10111002_42_dialog_content = "カレン…",
  ui_story_1011_10111002_43_dialog_content = "…",
  ui_story_1011_10111002_44_dialog_content = "…ごめんなさい。取り乱したわ。",
  ui_story_1011_10111002_45_dialog_content = "（それにしても…あの機械、なんでバイスを攻撃したんだろう？）",
  ui_story_1011_10111002_46_dialog_content = "（バイスの操作ミス…？\nそれはない…それなら、僕が感知で分かったはず）",
  ui_story_1011_10111002_47_dialog_content = "<color=#e8d9bb>ピピピピ…</color>",
  ui_story_1011_10111002_48_dialog_content = "攻撃対象は見つかりません。\n「全範囲攻撃命令」を終了します。",
  ui_story_1011_10111002_49_dialog_content = "あの時、バイスは「全範囲攻撃命令」を機械に出した。",
  ui_story_1011_10111002_50_dialog_content = "サブブレーン、この機械…\nどうしてバイスを誤射したの？",
  ui_story_1011_10111002_51_dialog_content = "質問を分析中…回答を生成――",
  ui_story_1011_10111002_52_dialog_content = "命令は正確に実行されました。\n誤射は発生していません。",
  ui_story_1011_10111002_53_dialog_content = "え！？",
  ui_story_1011_10111002_54_dialog_content = "バイスが実際、ここに倒れてるんだよ！\n言い逃れはしないで！",
  ui_story_1011_10111002_55_dialog_content = "サブブレーンは正確に回答しています。\n誤射は発生していません…",
  ui_story_1011_10111002_56_dialog_content = "空の末裔、光線銃の照準をサブブレーンから外してください。\n光線銃ではサブブレーンに損傷を与えることはできません。",
  ui_story_1011_10111002_57_dialog_content = "命令は正確に実行されました。\n誤射は発生していません。",
  ui_story_1011_10111002_58_dialog_content = "…",
  ui_story_1011_10111002_59_dialog_content = "…",
  ui_story_1011_10111002_60_dialog_content = "PlayerName、落ち着きなさい…\n有効な情報を得られるよう、質問を変えるのよ。",
  ui_story_1011_10111002_61_dialog_content = "遊んでいるヒマはないわ。",
  ui_story_1011_10111002_62_dialog_content = "バイスが待っている。",
  ui_story_1011_10111002_63_dialog_content = "そうだね…さっきから、\n大事なことをまだ聞いてなかった。",
  ui_story_1011_10111002_64_dialog_content = "サブブレーン、この攻撃装置の<color=#FFB400>使い方</color>を教えて。",
  ui_story_1011_10111002_65_dialog_content = "質問を分析中…回答を生成――",
  ui_story_1011_10111002_66_dialog_content = "攻撃装置の使い方を再生します…",
  ui_story_1011_10111002_67_dialog_content = "攻撃装置は、空の末裔の自衛用設備です。",
  ui_story_1011_10111002_68_dialog_content = "命令に応じて、\n敵のタイプごとに異なる攻撃を行います。",
  ui_story_1011_10111002_69_dialog_content = "有効性が証明されたため、戦闘に使用されるようになりました。\n…再生が終了しました。",
  ui_story_1011_10111002_70_dialog_content = "そんな…ほとんど答えになってないよ！",
  ui_story_1011_10111002_71_dialog_content = "余計に分からないよ。\nそれならなんで、バイスが攻撃されたの？",
  ui_story_1011_10111002_72_dialog_content = "PlayerName…",
  ui_story_1011_10111002_73_dialog_content = "PlayerName…思い至ったことがあるの。",
  ui_story_1011_10111002_74_dialog_content = "今、サブブレーンの言ったことが、\n本当にこの機械の使い方のすべてなら…",
  ui_story_1011_10111002_74X1_dialog_content = "空の末裔の防衛装置が「すべての敵を攻撃する」という命令を受けて、\n光霊であるバイスを攻撃したのなら…",
  ui_story_1011_10111002_75_dialog_content = "つまり、光霊という「空の末裔ではない」存在に\n攻撃をするということが、もしかして…",
  ui_story_1011_10111002_76_dialog_content = "もしかして古代の空の末裔にとっては、\nごく<color=#FFB400>当たり前</color>のことだったのではないかしら…",
  ui_story_1011_10111002_77_dialog_content = "私が幼い頃、この「月繭」の使い方を学んでいる時…",
  ui_story_1011_10111002_78_dialog_content = "先生はランスは暗鬼に向けるものだとは、\nいちいち言わなかった。",
  ui_story_1011_10111002_79_dialog_content = "そもそも説明などされなくても、\n当然のことだから…",
  ui_story_1011_10111002_80_dialog_content = "！？",
  ui_story_1011_10111002_81_dialog_content = "僕には理解できないし、\n認めたくもないけど…",
  ui_story_1011_10111002_82_dialog_content = "君の言うことには一理ある。\n可能性は否定できない…",
  ui_story_1011_10111002_83_dialog_content = "古代の空の末裔が、\n光霊を<color=#FFB400>敵</color>と見なしてたなんて…",
  ui_story_1011_10111101_1_dialog_content = "僕には分からないよ、\n本当に分からなくなってきた…",
  ui_story_1011_10111101_2_dialog_content = "僕たちは今、天空ノ谷にいる。\nそして、天空ノ谷で一番目につく、どこからでも見える白い塔の地下に居る…",
  ui_story_1011_10111101_3_dialog_content = "そのはずなのに、僕には目の前で起こってることが、\nまったく理解できないよ…",
  ui_story_1011_10111101_4_dialog_content = "ここは一体どんな場所だったんだろう？\n一体どんな人たちが生活してたんだろう？",
  ui_story_1011_10111101_5_dialog_content = "どうして滅んで、\nこんな地下に遺跡を残したんだろう…",
  ui_story_1011_10111101_6_dialog_content = "私たちが今経験していることが、\nすべてを物語っているのかもしれないわ。",
  ui_story_1011_10111101_7_dialog_content = "残されているのは、戦いの痕と、暗鬼だけ。",
  ui_story_1011_10111101_8_dialog_content = "…",
  ui_story_1011_10111101_9_dialog_content = "17年前の天空ノ谷と同じことが、ここでも？",
  ui_story_1011_10111101_10_dialog_content = "ここは地上よりもずっと静かだ。\nでも、きっと死に際の声さえ、外には届かなかったはず。",
  ui_story_1011_10111101_11_dialog_content = "…孤独に地下の隅で、死を迎えたんだ…",
  ui_story_1011_10111101_12_dialog_content = "僕たちは、この100年、いや、1000年の間に、\n初めてこの場所に足を踏み入れた人なのかもしれないね…",
  ui_story_1011_10111101_13_dialog_content = "1000年以内の履歴を検索します――",
  ui_story_1011_10111101_14_dialog_content = "その他の人物は発見されませんでした。\n正しい判断です。",
  ui_story_1011_10111101_15_dialog_content = "聞いたわけじゃないよ…",
  ui_story_1011_10111101_16_dialog_content = "サブブレーンの使命は、\n空の末裔のすべての疑問を解決することです。",
  ui_story_1011_10111101_17_dialog_content = "君が肝心な質問の時に、\nもう少し役に立ってくれればよかったんだけど…",
  ui_story_1011_10111101_18_dialog_content = "どうやってバイスを治せばいいのか、\nどうすればソラヴァンを修復できるのか、君は何もしらない…",
  ui_story_1011_10111101_19_dialog_content = "検索しています――",
  ui_story_1011_10111101_20_dialog_content = "「バイスを治す」および「ソラヴァンを修復する」方法は\nみつかりませんでした。",
  ui_story_1011_10111101_21_dialog_content = "正しい判断です。\nサブブレーンにはデータがありません。",
  ui_story_1011_10111101_22_dialog_content = "そんなこと、確認する必要ある！？",
  ui_story_1011_10111101_23_dialog_content = "申し訳ありません。サブブレーンは、「役に立たなかった」という\nフィードバックを収集しました。今後の改善に努めます。",
  ui_story_1011_10111101_24_dialog_content = "…いや、君を責めたつもりはないんだ…",
  ui_story_1011_10111101_25_dialog_content = "廃墟がこれだけ壊れてるんだから、\n君がまともに動くと期待する方が間違ってたんだ。",
  ui_story_1011_10111101_26_dialog_content = "さっきの質問の答えは、僕たちが自分で探すよ。",
  ui_story_1011_10111101_27_dialog_content = "行こう、カレン…もっと地下深くを探そう。",
  ui_story_1011_10111101_28_dialog_content = "それしか方法はない…",
  ui_story_1011_10111101_29_dialog_content = "ええ。バイスは私が背負っていくわ。",
  ui_story_1011_10111101_30_dialog_content = "（必ず助けてみせる…）",
  ui_story_1011_10111101_31_dialog_content = "（だから、持ちこたえるのよ。絶対に）",
  ui_story_1011_10111101_32_dialog_content = "<color=#e8d9bb>タッ…タッ…タッ…</color>",
  ui_story_1011_10111101_33_dialog_content = "今度は…道中に何もないわね。",
  ui_story_1011_10111101_34_dialog_content = "暗鬼もいないし、何も散らかっていない。",
  ui_story_1011_10111101_35_dialog_content = "地下に入ってから見たものの中では、\n一番「きれい」な場所かもしれないわ。",
  ui_story_1011_10111101_36_dialog_content = "そうだね。でも、きれいすぎる。\nなんだかおかしい。",
  ui_story_1011_10111101_37_dialog_content = "今まで見てきた所をあれだけボロボロにした何かがあったはずなのに、\nここだけまるで何もなかったみたいだ。",
  ui_story_1011_10111101_38_dialog_content = "かつての生活も、戦いも全部…\n知ったことじゃない、みたいな。",
  ui_story_1011_10111101_39_dialog_content = "人の温度が感じられない、そういことよね？",
  ui_story_1011_10111101_40_dialog_content = "うん。",
  ui_story_1011_10111101_41_dialog_content = "黎明学院の先生がおっしゃっていたことがあるわ。",
  ui_story_1011_10111101_42_dialog_content = "「人の温度とは世界の最も外側を覆うものである」",
  ui_story_1011_10111101_43_dialog_content = "「奥へ深掘りするほど、人の温度は薄れていくものだ」",
  ui_story_1011_10111101_44_dialog_content = "今の私たちに通じるところがあると思わない？",
  ui_story_1011_10111101_45_dialog_content = "私たちも一歩一歩、\nより深い所へと進んでいる…",
  ui_story_1011_10111101_46_dialog_content = "学院の先生も、自分の言葉がまさか文字通り、\n「地下の奥深く」の意味で使われるとは思ってなかっただろうね、ハハハ…",
  ui_story_1011_10111101_47_dialog_content = "教室で聞いていた時より、よく理解できたわ。\n先生も喜んでくださるはずよ。",
  ui_story_1011_10111101_48_dialog_content = "空の末裔の制限区域への進入を検知しました。\n認証を開始します。",
  ui_story_1011_10111101_49_dialog_content = "ピーピーピーピー！",
  ui_story_1011_10111101_50_dialog_content = "サブブレーン、どうしたの？",
  ui_story_1011_10111101_51_dialog_content = "ピピピピピ！",
  ui_story_1011_10111101_52_dialog_content = "認証に失敗しました。警告、ただちに引き返してください。\n警告、ただちに引き返してください。",
  ui_story_1011_10111101_53_dialog_content = "引き返す？冗談はやめてよ、\n戻って暗鬼と戦えっていうの？",
  ui_story_1011_10111101_54_dialog_content = "それに、突然騒ぎ出すなんて？\n理由ぐらい教えて！",
  ui_story_1011_10111101_55_dialog_content = "PlayerName、前を見て。",
  ui_story_1011_10111101_56_dialog_content = "…これは…<color=#FFB400>石の扉</color>？",
  ui_story_1011_10111101_57_dialog_content = "そのようね。",
  ui_story_1011_10111101_58_dialog_content = "それにしても…大きすぎるよ。\n扉というより城壁だ。",
  ui_story_1011_10111101_59_dialog_content = "開けるのにどれぐらいの力がいるんだろう…",
  ui_story_1011_10111101_60_dialog_content = "一番重い破城槌を持ち出しても、\nびくともしないでしょうね。",
  ui_story_1011_10111101_61_dialog_content = "これほど壮大な石の扉を造り、動かせるような勢力は…\n今の世界には存在しない。",
  ui_story_1011_10111101_62_dialog_content = "僕もそう思う。",
  ui_story_1011_10111101_63_dialog_content = "これほど発達した技術力がありながら、\n結局滅びてしまったというの…？",
  ui_story_1011_10111101_64_dialog_content = "警告、ただちに引き返してください。\n警告、ただちに引き返してください。",
  ui_story_1011_10111101_65_dialog_content = "立ち入りの許可されていないIDです。\n<color=#FFB400>「中枢エリア」</color>への進入は禁じられています。",
  ui_story_1011_10111101_66_dialog_content = "立ち入りの許可？",
  ui_story_1011_10111101_67_dialog_content = "扉は、許可のある者にしか開かれていません。",
  ui_story_1011_10111101_68_dialog_content = "未許可の者は、\n<color=#FFB400>「命令」</color>に基づき、進入できません。",
  ui_story_1011_10111101_69_dialog_content = "開くところを見てみたいわね。\nきっと壮観でしょう。",
  ui_story_1011_10111101_70_dialog_content = "そうだね。\nサブブレーン、力を貸して。",
  ui_story_1011_10111101_71_dialog_content = "君の言う許可って、\nどうしたら得られるの？",
  ui_story_1011_10111101_72_dialog_content = "申し訳ありません。\n「サブブレーン」は一切の支援を行えません。",
  ui_story_1011_10111101_73_dialog_content = "え？\n「空の末裔のすべての疑問を解決します」って言ってたでしょ？",
  ui_story_1011_10111101_74_dialog_content = "最高レベルの「命令」第1号は、\nその使命に優先されます。",
  ui_story_1011_10111101_75_dialog_content = "空の末裔、および、サブブレーンは、\n「命令」に違反することが許可されていません。",
  ui_story_1011_10111101_76_dialog_content = "「命令」…？",
  ui_story_1011_10111101_77_dialog_content = "山のように大きくて高い岩の扉が、\n招かれざる者への態度そのもの、ということ…",
  ui_story_1011_10111101_78_dialog_content = "ずいぶんお高くとまっているようね。",
  ui_story_1011_10111101_79_dialog_content = "そうだね。拒絶って言葉がすごく似合うよ。",
  ui_story_1011_10111101_80_dialog_content = "ただ…",
  ui_story_1011_10111101_81_dialog_content = "昔はそうとう立派だったんだろうけど…",
  ui_story_1011_10111101_82_dialog_content = "今は、その痕が残ってるだけだ。",
  ui_story_1011_10111101_83_dialog_content = "そうね。風化して出来たすき間があるわ。\n人が通るのには十分ではないかしら。",
  ui_story_1011_10111101_84_dialog_content = "まるで、牙が抜け落ちてしまった獅子ね。\nでも、猫に成り下がれないプライドがある…",
  ui_story_1011_10111101_85_dialog_content = "こんなにみすぼらしい姿をさらしてなお、\n侵入者を居丈高に拒んでいる…妙に切なくなるわ。",
  ui_story_1011_10111101_86_dialog_content = "警告、ただちに引き返してください。\n警告、ただちに引き返してください。",
  ui_story_1011_10111101_87_dialog_content = "中に入ってみよう。",
  ui_story_1011_10111101_88_dialog_content = "扉の向こうにどんな秘密が隠されてるのか、\n見てみないと。",
  ui_story_1011_10111101_89_dialog_content = "ええ。まだまだたくさん、\n見つけなければならないものがあるわ。他に道はない。",
  ui_story_1011_10111101_90_dialog_content = "許可なきコアエリアへの進入は禁じられています。",
  ui_story_1011_10111101_91_dialog_content = "サブブレーン、もういいでしょ。",
  ui_story_1011_10111101_92_dialog_content = "「命令」により、扉の通行は許可されていません。",
  ui_story_1011_10111101_93_dialog_content = "空の末裔は「命令」に背くことが許可されていません…",
  ui_story_1011_10111101_94_dialog_content = "（真っ暗なすき間の中に入って初めて分かった。\nこの石の扉は、見た目よりもさらに厚い）",
  ui_story_1011_10111101_95_dialog_content = "（サブブレーンの声もだんだん聞こえなくなってきた。\nこの石の厚さで聞こえないのか、それともあきらめたのか）",
  ui_story_1011_10111101_96_dialog_content = "（僕は想像力をありったけ使って想像した――\n石の扉の向こうに、何が待ってるのか）",
  ui_story_1011_10111101_97_dialog_content = "（いくら想像したって、実際にこの目で見た時には、\nやっぱり驚くだろうと分かってる）",
  ui_story_1011_10111101_98_dialog_content = "（これから僕が見るものが何なのかも、分かってる）",
  ui_story_1011_10111101_99_dialog_content = "（見たことのない、文明だ）",
  ui_story_1011_10111101_100_dialog_content = "これは何だろう？",
  ui_story_1011_10111101_101_dialog_content = "まだ動いているなんて…",
  ui_story_1011_10111101_102_dialog_content = "サブブレーン、聞こえる？",
  ui_story_1011_10111101_103_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1011_10111101_104_dialog_content = "入ること自体が許されていないのだから、\n私たちの問いかけにはもう答えないでしょうね。",
  ui_story_1011_10111101_105_dialog_content = "この装置の役割は、\n私たち自身で探るしかない。",
  ui_story_1011_10111101_106_dialog_content = "宙に浮かぶ石の輪っか…",
  ui_story_1011_10111101_107_dialog_content = "一体どんな機能があるんだろう？\nまったく想像できないよ。",
  ui_story_1011_10111101_108_dialog_content = "似たようなものは見たことある？",
  ui_story_1011_10111101_109_dialog_content = "ないわ。",
  ui_story_1011_10111101_110_dialog_content = "現代の建築物だけではないわ。\n古代遺跡でも、似たようなものは見つかっていない。",
  ui_story_1011_10111101_111_dialog_content = "ただ、そうであってもおかしくはないわ。\nここはそもそも、他の遺跡とは違う。あなたたち空の末裔の遺跡だもの。",
  ui_story_1011_10111101_112_dialog_content = "空の末裔だけの使い方があるのかもしれない…",
  ui_story_1011_10111101_113_dialog_content = "空の末裔だけの使い方？",
  ui_story_1011_10111101_114_dialog_content = "あなたたちに見える世界は、\n光霊の見る世界とは違っている。",
  ui_story_1011_10111101_115_dialog_content = "空の末裔が使うためだけにあるというのなら、\nその機能も、空の末裔でないと見えない所に隠されているのかも。",
  ui_story_1011_10111101_116_dialog_content = "要するに、感知能力と関係があるってこと？",
  ui_story_1011_10111101_117_dialog_content = "推測に過ぎないけれど、\n試してみる価値はあるでしょう。",
  ui_story_1011_10111101_118_dialog_content = "うん、分かった。",
  ui_story_1011_10111101_119_option_content = "強制感知！",
  ui_story_1011_10111101_120_dialog_content = "<color=#e8d9bb>ブーン――</color>",
  ui_story_1011_10111101_121_dialog_content = "え？これは…",
  ui_story_1011_10111101_122_dialog_content = "新生児さん、ようこそ。",
  ui_story_1011_10111101_123_dialog_content = "<color=#FFB400>リングシステム</color>への初回アクセスです。",
  ui_story_1011_10111101_124_dialog_content = "リングシステム？あの装置のこと？",
  ui_story_1011_10111101_125_dialog_content = "僕は今、どこにいるの？\n話しているのは、誰？",
  ui_story_1011_10111101_126_dialog_content = "リングシステムは、\n空の末裔という種族全体の記憶です。",
  ui_story_1011_10111101_127_dialog_content = "あなたはここから世界を知ることになります。",
  ui_story_1011_10111101_128_dialog_content = "…いや、誰かと話をしているわけじゃなさそうだ。",
  ui_story_1011_10111101_129_dialog_content = "音でも文字でもない。\n情報が直接僕の頭の中に入り込んできてる…",
  ui_story_1011_10111101_130_dialog_content = "まずは、この場所を知りましょう。",
  ui_story_1011_10111101_131_dialog_content = "空の末裔という種族はこの地で誕生しました。\nすべての空の末裔がこの地で生まれています。",
  ui_story_1011_10111101_132_dialog_content = "どこへ行こうとも、\nこの場所こそが永遠に空の末裔の故郷なのです。",
  ui_story_1011_10111101_133_dialog_content = "ここは<color=#FFB400>「塔の郷」</color>とも呼ばれています。",
  ui_story_1011_10111101_134_dialog_content = "「塔の郷」…？",
  ui_story_1011_10111101_135_dialog_content = "天空ノ谷が空の末裔の故郷なんじゃなかったの？",
  ui_story_1011_10111101_136_dialog_content = "無数の高い塔から成り立つこの都市の…",
  ui_story_1011_10111101_137_dialog_content = "あなたが今いる場所こそ、まさにその中心部、\n最初の、かつ最高の塔である――",
  ui_story_1011_10111101_138_dialog_content = "「回帰の塔」です。",
  ui_story_1011_10111101_139_dialog_content = "すべての空の末裔は、\n成人になるまでここで教育を受けます。",
  ui_story_1011_10111101_140_dialog_content = "その後、外の世界に触れる機会を得て、\nはるかかなた、世界の隅々まで旅立っていきます。",
  ui_story_1011_10111101_141_dialog_content = "しかし、故郷は…永遠に…ここに…そびえ立っています…",
  ui_story_1011_10111101_142_dialog_content = "旅の終点として…皆の回帰を…待っています…",
  ui_story_1011_10111101_143_dialog_content = "！！！",
  ui_story_1011_10111101_144_dialog_content = "お…終わり？",
  ui_story_1011_10111101_145_dialog_content = "どう、何か分かった？",
  ui_story_1011_10111101_146_dialog_content = "声が聞こえたんだ。\nいや、声じゃないかな…とにかく、情報が頭に入って来たんだ。",
  ui_story_1011_10111101_147_dialog_content = "情報？",
  ui_story_1011_10111101_148_dialog_content = "うん。装置に意識をつないだとたん、\n情報が直接僕の頭の中に流れこんで来たんだ。",
  ui_story_1011_10111101_149_dialog_content = "まるで僕を…教育してるみたいだった。",
  ui_story_1011_10111101_150_dialog_content = "その情報によると、この装置は「リングシステム」って言って、\n空の末裔という種族全体の事を記憶してるみたいなんだ。",
  ui_story_1011_10111101_151_dialog_content = "それから、ここが空の末裔の故郷で…\n「塔の郷」って呼ばれてたみたいだね。",
  ui_story_1011_10111101_152_dialog_content = "僕たちがいるのは「回帰の塔」って言って、\nその中でいちばん高い塔らしいんだ。",
  ui_story_1011_10111101_153_dialog_content = "天空ノ谷については、\n何も聞かされなかったの？",
  ui_story_1011_10111101_154_dialog_content = "うん、僕も不思議に思ってる。",
  ui_story_1011_10111101_155_dialog_content = "名前が後から変わったのかな？",
  ui_story_1011_10111101_156_dialog_content = "可能性はあるわね。かなり古い年代の遺跡だもの。\n文字も言葉も、変わっている可能性がある。",
  ui_story_1011_10111101_157_dialog_content = "それで、この「リングシステム」というものは、\n情報を保存する装置なのかしら？",
  ui_story_1011_10111101_158_dialog_content = "うん、たぶんそうだよ。",
  ui_story_1011_10111101_159_dialog_content = "空の末裔が感知能力を使うことで、\nここから情報を得ることができるんだろうね。",
  ui_story_1011_10111101_160_dialog_content = "でも、どうしてそうする必要があるのかしら？",
  ui_story_1011_10111101_161_dialog_content = "石の輪という形であることに何か意味があるの？",
  ui_story_1011_10111101_162_dialog_content = "それに、この大きさよ。\n情報を保存しているにしては、大きい…",
  ui_story_1011_10111101_163_dialog_content = "これほどの空間であれば、普通に本を並べただけだとしても、\nそうとうな量の情報になるはずよ。",
  ui_story_1011_10111101_164_dialog_content = "本を並べる…",
  ui_story_1011_10111101_165_dialog_content = "そうだ、カレン。\nオウムガイの話を覚えてる？",
  ui_story_1011_10111101_166_dialog_content = "ええ、覚えているわ。",
  ui_story_1011_10111101_167_dialog_content = "あの時バイスが言ってた。\nオウムガイの形と使い方に、古代文明の価値観が現れてるって。",
  ui_story_1011_10111101_168_dialog_content = "「自然」という「連続性」のあるものを重んじる…",
  ui_story_1011_10111101_169_dialog_content = "それがここにも応用されてるんじゃないかな。",
  ui_story_1011_10111101_170_dialog_content = "つまり、輪の形であることは\n「連続性」の象徴だと言いたいの？",
  ui_story_1011_10111101_171_dialog_content = "うん、本が並んだ様子を想像すると…",
  ui_story_1011_10111101_172_dialog_content = "たくさん保存しようとするなら、きっとなるべくすき間が開かないように、\n本をきちんと揃えて並べるよね。",
  ui_story_1011_10111101_173_dialog_content = "そうすると、最後は四角い本の山ができる。",
  ui_story_1011_10111101_174_dialog_content = "でも、四角には角がたくさんあって、\n線が連続してない。",
  ui_story_1011_10111101_175_dialog_content = "それに比べて、輪には角がない…",
  ui_story_1011_10111101_176_dialog_content = "だから、「連続性」の考え方に合致する\n保存の方法にこだわったということ？",
  ui_story_1011_10111101_177_dialog_content = "きっとそういうことだよ！",
  ui_story_1011_10111101_178_dialog_content = "私には…口で簡潔に表現することはできるけど、\nやはり、よく理解できないわ。",
  ui_story_1011_10111101_179_dialog_content = "この古代文明は私たちの想像さえ\nはるかに超えて、発達していた…",
  ui_story_1011_10111101_180_dialog_content = "科学や技術を支える根本的なものの考え方から、\n今の私たちのものとまったく違う。",
  ui_story_1011_10111101_181_dialog_content = "私たちの数学なんて、\n原始人の手遊びくらいに思われていたかもしれないわね。",
  ui_story_1011_10111101_182_dialog_content = "そこまで大げさなものかな…",
  ui_story_1011_10111101_183_dialog_content = "もう一度交信してみて、PlayerName。",
  ui_story_1011_10111101_184_dialog_content = "それほど高度な文明をもっていた人たちが、\nこの膨大な空間を使って、一体どれほどの情報を保存していたのかしら？",
  ui_story_1011_10111101_185_dialog_content = "世界のありとあらゆる問題の答えが、\nこの中にあるのかもしれないわ。",
  ui_story_1011_10111101_186_dialog_content = "うん、もう一度試してみるよ！",
  ui_story_1011_10111101_187_option_content = "強制感知！",
  ui_story_1011_10111101_188_dialog_content = "<color=#e8d9bb>ブーン――</color>",
  ui_story_1011_10111101_189_dialog_content = "また、ここだ…",
  ui_story_1011_10111101_190_dialog_content = "情報を保存してるなら、\n何か自分で見る方法があるはずだ。",
  ui_story_1011_10111101_191_dialog_content = "でも、本棚みたいな一目で分かるものはない…",
  ui_story_1011_10111101_192_dialog_content = "それなら、意識だ！\n自分の意識を動かすしかない…",
  ui_story_1011_10111101_193_dialog_content = "！？",
  ui_story_1011_10111101_194_dialog_content = "宙に浮かんでいる石板が回転し始めた…",
  ui_story_1011_10111101_195_dialog_content = "PlayerName、一体何を…",
  ui_story_1011_10111101_196_dialog_content = "わ！わ！わ…",
  ui_story_1011_10111101_197_dialog_content = "頭がクラクラする…\n僕は今、動いてるの？",
  ui_story_1011_10111101_198_dialog_content = "停まって…\nどうにかして、停めないと。",
  ui_story_1011_10111101_199_dialog_content = "<color=#e8d9bb>ブーン――</color>",
  ui_story_1011_10111101_200_dialog_content = "ふぅ…停まった？",
  ui_story_1011_10111101_201_dialog_content = "巨像…",
  ui_story_1011_10111101_202_dialog_content = "えっ！？",
  ui_story_1011_10111101_203_dialog_content = "巨像は光力で駆動する、\n大型の多機能施設です。",
  ui_story_1011_10111101_204_dialog_content = "空の末裔にとって、生涯で最も信用に値するものです。",
  ui_story_1011_10111101_205_dialog_content = "空の末裔は強大な意識の力を持ちながら、身体は弱い。\n意識の強大さは天の恵みであり、身体の弱さは、その代償です。",
  ui_story_1011_10111101_206_dialog_content = "巨像は空の末裔の欠点を補います。\n身体の延長として、空の末裔の行動がその意識に追いつくことを可能にします。",
  ui_story_1011_10111101_207_dialog_content = "そのため、空の末裔が学ぶべき第一のことは、巨像の操縦です。",
  ui_story_1011_10111101_208_dialog_content = "さっきと同じで、先生みたいな感じだな…",
  ui_story_1011_10111101_209_dialog_content = "今度は僕に巨像の操縦を教えてくれるのかな？",
  ui_story_1011_10111101_210_dialog_content = "空の末裔が操縦できるよう、\n巨像には操縦席が設けられています。",
  ui_story_1011_10111101_211_dialog_content = "空の末裔はそこで自身の意識と巨像を接続します。",
  ui_story_1011_10111101_212_dialog_content = "共鳴が十分な強度に到達すると、巨像が起動します。",
  ui_story_1011_10111101_213_dialog_content = "その通りだ。あの時の僕もそうだった。",
  ui_story_1011_10111101_214_dialog_content = "巨像には、各種モジュールを搭載することができ、\n空の末裔のさまざまな行為をサポートします。",
  ui_story_1011_10111101_215_dialog_content = "巨像の手助けがあれば、\n空の末裔はいかなる生物よりも強い存在になります。",
  ui_story_1011_10111101_216_dialog_content = "しかし、このような力を所有する巨像の操縦者として、\n常に胸に刻んでおいてください。",
  ui_story_1011_10111101_217_dialog_content = "あなた方が生まれた時に刻まれた「命令」を。",
  ui_story_1011_10111101_218_dialog_content = "空の末裔と巨像は、\n永遠に戦争に仕える機械なのです。",
  ui_story_1011_10111101_219_dialog_content = "戦争の機械！？",
  ui_story_1011_10111101_220_dialog_content = "そんなはずはない…\n僕もソラヴァンも、攻撃する能力さえないのに…",
  ui_story_1011_10111101_221_dialog_content = "巨像の身体、空の末裔の知能、\nそして…",
  ui_story_1011_10111101_222_dialog_content = "敵を刺す兵士の刃が、\nその「命令」に従い…",
  ui_story_1011_10111101_223_dialog_content = "一体となって、戦争を行う機械となるのです。",
  ui_story_1011_10111101_224_dialog_content = "えっ！？",
  ui_story_1011_10111101_225_dialog_content = "これは…暗鬼！？",
  ui_story_1011_10111101_226_dialog_content = "続いて、戦争について学びましょう。\nゆっくり学んでください。",
  ui_story_1011_10111101_227_dialog_content = "データ上に戦場が現われました。",
  ui_story_1011_10111101_228_dialog_content = "たった1つの命は戦場ではあまりにも小さく弱いものです。\n力のバランスが崩れれば、一瞬で世界の太平は破壊されます。",
  ui_story_1011_10111101_229_dialog_content = "幸いなことに、\n空の末裔が戦場にいる必要はありません。",
  ui_story_1011_10111101_230_dialog_content = "ここには戦場で戦うために生まれた兵士がいます。\nいかに戦い敵を倒すか、それが彼らの知っていることのすべてです。",
  ui_story_1011_10111101_231_dialog_content = "この不格好な戦士たちが、喜んで戦場におもむき…",
  ui_story_1011_10111101_232_dialog_content = "そして、あなたたちが世界に――",
  ui_story_1011_10111101_233_dialog_content = "戦争をもたらすのです。",
  ui_story_1011_10111201_1_dialog_content = "はぁ…はぁ…",
  ui_story_1011_10111201_2_dialog_content = "PlayerName、どうしたの？",
  ui_story_1011_10111201_3_dialog_content = "汗がひどいわ。",
  ui_story_1011_10111201_4_dialog_content = "はあ、はあ…僕は…",
  ui_story_1011_10111201_5_dialog_content = "わからない…",
  ui_story_1011_10111201_6_dialog_content = "どうして、あんなものが見えたのか…",
  ui_story_1011_10111201_7_dialog_content = "あれは一体どういう意味だったんだろう…\n僕には分からない…",
  ui_story_1011_10111201_8_dialog_content = "一体何を見たの？",
  ui_story_1011_10111201_9_dialog_content = "きょ、巨像が見えたんだ…",
  ui_story_1011_10111201_10_dialog_content = "リングシステムが僕にどうやって\n巨像を操作するのか、教えてくれて…",
  ui_story_1011_10111201_11_dialog_content = "それと…",
  ui_story_1011_10111201_12_dialog_content = "どうやって、巨像の中の暗鬼を操るか…",
  ui_story_1011_10111201_13_dialog_content = "暗鬼を操る！？",
  ui_story_1011_10111201_13X1_dialog_content = "そう…システムが言ってた。\n空の末裔と巨像は戦争の機械だって…",
  ui_story_1011_10111201_14_dialog_content = "どうして…？",
  ui_story_1011_10111201_15_dialog_content = "カレン、どう思う…？",
  ui_story_1011_10111201_16_dialog_content = "私も驚いているわ。\nでも…その情報だけでは、判断できない。",
  ui_story_1011_10111201_17_dialog_content = "ここは古代の遺跡よ。\n今よりずいぶん前の時代の。",
  ui_story_1011_10111201_18_dialog_content = "当時何が起こっていたのかも分からない。\nだから、情報が真実かどうかは断言できないわ。",
  ui_story_1011_10111201_19_dialog_content = "それだけ？",
  ui_story_1011_10111201_20_dialog_content = "でも、もし空の末裔が本当に\nかつて暗鬼を操っていたとしたら…",
  ui_story_1011_10111201_21_dialog_content = "僕は一体、どんな立場に立てばいいんだろう？",
  ui_story_1011_10111201_22_dialog_content = "結局…スーモアみたいになるのが正しかったって事じゃ…",
  ui_story_1011_10111201_23_dialog_content = "あなたの話してくれた情報は考えるに値するものだけれど、\nそれに縛られてはいけない。",
  ui_story_1011_10111201_24_dialog_content = "あなたが実際に経験してきたことこそ真実よ。\nそうでしょう？",
  ui_story_1011_10111201_25_dialog_content = "あなたとソラヴァンが一緒に戦って来たことこそ、\n疑いようもない事実。",
  ui_story_1011_10111201_26_dialog_content = "あなたと一緒に戦って来た\n仲間たちがいるということが、真実なのよ。",
  ui_story_1011_10111201_27_dialog_content = "悩む必要なんてないわ。",
  ui_story_1011_10111201_28_dialog_content = "私も、バイスも、それから、ここにいなくても、\nあなたの友だちは全員――",
  ui_story_1011_10111201_29_dialog_content = "いつだって、あなたを歓迎してくれるでしょう。",
  ui_story_1011_10111201_30_dialog_content = "うん…うっ…",
  ui_story_1011_10111201_31_dialog_content = "カレン…ありがとう…",
  ui_story_1011_10111201_32_dialog_content = "大げさよ…",
  ui_story_1011_10111201_33_dialog_content = "君の言う通りだよ。\n僕にとっては君たちこそが真実だ。",
  ui_story_1011_10111201_34_dialog_content = "今はこんな状態になっちゃったバイスを、\n何とか回復させる方法を見つけないと。",
  ui_story_1011_10111201_35_dialog_content = "もう1回試してみる。",
  ui_story_1011_10111201_36_dialog_content = "まずは休みましょう？",
  ui_story_1011_10111201_37_dialog_content = "二度も交信して、\nだいぶ力を消耗しているでしょう。",
  ui_story_1011_10111201_38_dialog_content = "大丈夫だよ。",
  ui_story_1011_10111201_39_dialog_content = "使い方、分かってきた気がするんだ。",
  ui_story_1011_10111201_40_option_content = "強制感知！",
  ui_story_1011_10111201_41_dialog_content = "<color=#e8d9bb>ブーン――</color>",
  ui_story_1011_10111201_42_dialog_content = "さっきの、意識が動くような感覚…",
  ui_story_1011_10111201_43_dialog_content = "たぶん、ここは情報が詰まった、\n1つの空間になってるんだ。",
  ui_story_1011_10111201_44_dialog_content = "空間の中でどう動くかは、\n僕の思考で決められる…",
  ui_story_1011_10111201_45_dialog_content = "さっきはたぶん、最初の話につられて、\n空の末裔の教育プログラムの中にまた入ってしまったんだ。",
  ui_story_1011_10111201_46_dialog_content = "だったら今度は、\n僕自身で動く方向を決めればいい。",
  ui_story_1011_10111201_47_dialog_content = "バイスの治療に関することを想像して…",
  ui_story_1011_10111201_48_dialog_content = "バイスに起こった「意識消失」という\n特殊な状態を思い浮かべる…",
  ui_story_1011_10111201_49_dialog_content = "<color=#e8d9bb>ブオオン――！</color>",
  ui_story_1011_10111201_50_dialog_content = "せ、成功したのかな？",
  ui_story_1011_10111201_51_dialog_content = "実験データ、コード…",
  ui_story_1011_10111201_52_dialog_content = "権限を…から「公開」に変更、すべての…に公開…",
  ui_story_1011_10111201_53_dialog_content = "変更者：フランシス",
  ui_story_1011_10111201_54_dialog_content = "またその名前だ…",
  ui_story_1011_10111201_55_dialog_content = "情報の損傷が激しいのかな…？\n何か手がかりが残っていればいいけど…",
  ui_story_1011_10111201_56_dialog_content = "実験体…、「意識消失」から未だ目覚めず、身体は…バイタルが後退。",
  ui_story_1011_10111201_57_dialog_content = "実験体…「意識消失」から未だ目覚めず、…現象が現れ、生命が…",
  ui_story_1011_10111201_58_dialog_content = "実験体…、…今だ目覚めず、実験中…",
  ui_story_1011_10111201_59_dialog_content = "何の実験だろう？",
  ui_story_1011_10111201_60_dialog_content = "このデータ…不安になる…",
  ui_story_1011_10111201_61_dialog_content = "実験体…、…今だ目覚めず、その他、異常なし。",
  ui_story_1011_10111201_62_dialog_content = "実験体…、「意識消失」から未だ目覚めず、その他…",
  ui_story_1011_10111201_63_dialog_content = "実験体…、…未だ…",
  ui_story_1011_10111201_64_dialog_content = "どうして、全部…",
  ui_story_1011_10111201_65_dialog_content = "実験…",
  ui_story_1011_10111201_66_dialog_content = "…",
  ui_story_1011_10111201_67_dialog_content = "うーん…やっぱり、\n欠けてる部分が多すぎる…",
  ui_story_1011_10111201_68_dialog_content = "…最後に…を合わせて…試みたところ…",
  ui_story_1011_10111201_69_dialog_content = "実験…",
  ui_story_1011_10111201_70_dialog_content = "身体の…変化を…観測…",
  ui_story_1011_10111201_71_dialog_content = "…",
  ui_story_1011_10111201_72_dialog_content = "…が成功し、「意識消失」から回復。",
  ui_story_1011_10111201_73_dialog_content = "！？",
  ui_story_1011_10111201_74_dialog_content = "成功例があった！",
  ui_story_1011_10111201_75_dialog_content = "でも…この実験で何をしたんだろう？\nそれに、一体どこで？",
  ui_story_1011_10111201_76_dialog_content = "もっと情報が必要だ…\n奥まで見てみないと。",
  ui_story_1011_10111201_77_dialog_content = "警告、目的の情報は…\n権限によりプロテクトされています。",
  ui_story_1011_10111201_78_dialog_content = "これ以上閲覧できません…",
  ui_story_1011_10111201_79_dialog_content = "うっ…見られないのか…",
  ui_story_1011_10111201_80_dialog_content = "どう？収穫は？",
  ui_story_1011_10111201_81_dialog_content = "うん。実験データが見つかって…",
  ui_story_1011_10111201_82_dialog_content = "その中に「意識消失」から目覚めた例があった。",
  ui_story_1011_10111201_83_dialog_content = "でも、その実験で何をしたのか、\nどこで実験してたのかは、分からなかった。",
  ui_story_1011_10111201_84_dialog_content = "それに、成功例もたった1つ…",
  ui_story_1011_10111201_85_dialog_content = "ここへ来るまでに、\n完全な状態の実験装置のたぐいは見かけなかったわ。",
  ui_story_1011_10111201_86_dialog_content = "もっと深い所にあって…\nまだ使えることを願うばかりね。",
  ui_story_1011_10111201_87_dialog_content = "成功率については…試してみるしかなさそうね。",
  ui_story_1011_10111201_88_dialog_content = "そうだね、やってみるしかない。",
  ui_story_1011_10111201_89_dialog_content = "もっと奥へ行ってみよう。",
  ui_story_1011_10111201_90_dialog_content = "実験装置が見つからなくても、\n他の手がかりが見つかるかもしれない。",
  ui_story_1011_10111201_91_dialog_content = "ここに、後どれぐらいの秘密が残されてるかなんて、\n誰にも想像がつくものじゃない…",
  ui_story_1011_10111201_92_dialog_content = "<color=#e8d9bb>タッ…タッ…タッ…</color>",
  ui_story_1011_10111201_93_dialog_content = "「回帰の塔」…",
  ui_story_1011_10111201_94_dialog_content = "今振り返ってみると、\n私たち、ずっと塔の中を探索しているはずよね。",
  ui_story_1011_10111201_95_dialog_content = "地下の遺跡と地上の白い塔は、\nひとつの建物なのかしら？",
  ui_story_1011_10111201_96_dialog_content = "同じものとは考えにくい気がするよ。",
  ui_story_1011_10111201_97_dialog_content = "白い塔は天空ノ谷に長い間立ってて、\n皆よく知ってる。",
  ui_story_1011_10111201_98_dialog_content = "でも、この遺跡の中、\nまったく別世界みたいだし…",
  ui_story_1011_10111201_99_dialog_content = "でも、その両者をつないでいるのが、あなたたち…",
  ui_story_1011_10111201_100_dialog_content = "空の末裔。",
  ui_story_1011_10111201_101_dialog_content = "…",
  ui_story_1011_10111201_102_dialog_content = "時代も文明も、科学技術も変化してきたようだけれど、\n空の末裔の一族だけが、この地の空の下で暮らしていたことは確か…",
  ui_story_1011_10111201_103_dialog_content = "間違いなく、偉大な伝統だと言っていいわ。",
  ui_story_1011_10111201_104_dialog_content = "光霊が誕生したという北境に立った時でさえ、\n私にこんな感覚は起こらなかった。",
  ui_story_1011_10111201_105_dialog_content = "「偉大」か…",
  ui_story_1011_10111201_106_dialog_content = "とても重い、すごく重い言葉だね…",
  ui_story_1011_10111201_107_dialog_content = "そうかしら？",
  ui_story_1011_10111201_108_dialog_content = "その「偉大さ」を引き継ぐべき人は、\n今はもう僕一人しかいない…",
  ui_story_1011_10111201_109_dialog_content = "PlayerName…",
  ui_story_1011_10111201_110_dialog_content = "いや、考えすぎるのはよそう。",
  ui_story_1011_10111201_111_dialog_content = "いいほうに考えれば、\n僕はこの遺跡のたった一人の継承者だ。",
  ui_story_1011_10111201_112_dialog_content = "つまり、ここにある物は全部、\n僕のものってことになるでしょ？",
  ui_story_1011_10111201_113_dialog_content = "フフ…",
  ui_story_1011_10111201_114_dialog_content = "そうね、その通りよ。\nここの主は当然、あなた。",
  ui_story_1011_10111201_115_dialog_content = "やった！これだけたくさん古代の遺物があれば、\nもう生活に困ることなんてないね。",
  ui_story_1011_10111201_116_dialog_content = "戻ったら、バイスの付けてる\n帳簿なんか破っちゃおう！",
  ui_story_1011_10111201_117_dialog_content = "今の言葉、バイスに伝えられるよう、\nしっかり覚えておくわ。",
  ui_story_1011_10111201_118_dialog_content = "そ、それはやめて…",
  ui_story_1011_10111201_119_dialog_content = "<color=#e8d9bb>チ…チ…</color>",
  ui_story_1011_10111201_120_dialog_content = "何かがこすれる音が聞こえた気がする…",
  ui_story_1011_10111201_121_dialog_content = "どこかに動いてる機械があるのかな？",
  ui_story_1011_10111201_122_dialog_content = "ありえるわね。",
  ui_story_1011_10111201_123_dialog_content = "ただ、気になるわ。廃墟になって久しいのに、\nどうして機械が動き続けているのかしら？",
  ui_story_1011_10111201_124_dialog_content = "1000年以上の時間が経ってるのよ。\nエネルギー、摩耗、何をとっても大きな難題になるはず。",
  ui_story_1011_10111201_125_dialog_content = "僕たちにとってはそうだろうけど、\nここを造った人にとってもそうとは、限らないよ。",
  ui_story_1011_10111201_126_dialog_content = "問題の解決法なんて、\n今の僕たちとまったく違うだろうし。",
  ui_story_1011_10111201_127_dialog_content = "それもそうね。",
  ui_story_1011_10111201_128_dialog_content = "近づいて見てみましょう。\nとにかく、音がどこから聞こえてくるのか確かめないと。",
  ui_story_1011_10111201_129_dialog_content = "うん。",
  ui_story_1011_10111201_130_dialog_content = "<color=#e8d9bb>チ…チ…</color>",
  ui_story_1011_10111201_131_dialog_content = "待って！",
  ui_story_1011_10111201_132_dialog_content = "どうしたの？",
  ui_story_1011_10111201_133_dialog_content = "感知したんだ。",
  ui_story_1011_10111201_134_dialog_content = "<color=#e8d9bb>チ…チ…</color>",
  ui_story_1011_10111201_135_dialog_content = "…",
  ui_story_1011_10111201_136_dialog_content = "暗鬼！？",
  ui_story_1011_10111201_137_dialog_content = "まさか、ここまで…",
  ui_story_1011_10111201_138_dialog_content = "でも、ちょっとおかしいね。僕らにはもう気付いてるはずだよ。\nどうして何の反応もないんだろう？",
  ui_story_1011_10111201_139_dialog_content = "…",
  ui_story_1011_10111201_140_dialog_content = "見て、何をしているのかしら？",
  ui_story_1011_10111201_141_dialog_content = "<color=#e8d9bb>チ…チ…</color>",
  ui_story_1011_10111201_142_dialog_content = "石板を…動かしてる？",
  ui_story_1011_10111201_143_dialog_content = "それに一体どんな意味が？",
  ui_story_1011_10111201_144_dialog_content = "こんな暗鬼、見たことがないわ。",
  ui_story_1011_10111201_145_dialog_content = "行動の意味を考えるだけでは、\n説明できないかもしれないわね。",
  ui_story_1011_10111201_145X1_dialog_content = "まさか、上級暗鬼の命令に従っている？",
  ui_story_1011_10111201_145X2_dialog_content = "いえ…違うわね。石板を動かすことは、\n暗鬼にとって何の意味もない。",
  ui_story_1011_10111201_145X3_dialog_content = "けれど…空の末裔にとっては？",
  ui_story_1011_10111201_147_dialog_content = "どういうこと？",
  ui_story_1011_10111201_148_dialog_content = "この遺跡がどうしてまだ動いているのか、\nというさっきの話…",
  ui_story_1011_10111201_149_dialog_content = "今、答えが分かったわ。",
  ui_story_1011_10111201_150_dialog_content = "つまり、暗鬼が？",
  ui_story_1011_10111201_151_dialog_content = "ただの推測に過ぎないわ。",
  ui_story_1011_10111201_152_dialog_content = "私たちには目もくれず、\nただただ石板を動かし続ける暗鬼…",
  ui_story_1011_10111201_153_dialog_content = "機械を動かす部品のように、\n構造の一部分になっているようね。",
  ui_story_1011_10111201_154_dialog_content = "<color=#e8d9bb>チ…チ…</color>",
  ui_story_1011_10111201_155_dialog_content = "そんなことまでできるなんて…",
  ui_story_1011_10111201_156_dialog_content = "リングシステムの中で見たこと、\nやっぱり間違ってなかったみたいだ。",
  ui_story_1011_10111201_157_dialog_content = "古代の空の末裔は…\n暗鬼を従わせる方法を知っていた…",
  ui_story_1011_10111201_158_dialog_content = "どうやって？",
  ui_story_1011_10111201_159_dialog_content = "それも感知かな？",
  ui_story_1011_10111201_160_dialog_content = "ここにはとっくに人が住まなくなっているのよ。\nそれでも、暗鬼は未だに命令に従っている。",
  ui_story_1011_10111201_161_dialog_content = "…止まって。道が無くなったわ。",
  ui_story_1011_10111201_162_dialog_content = "本当だ、ここで行き止まりなの？",
  ui_story_1011_10111201_163_dialog_content = "何もないみたいだけど…\nずいぶんガランとしてるね。",
  ui_story_1011_10111201_164_dialog_content = "真ん中に石づくりの台があるわ。\n見に行ってみましょう。",
  ui_story_1011_10111201_165_dialog_content = "暗鬼が石板を押していたのは、\nきっと何かを機能させるためよ。",
  ui_story_1011_10111201_166_dialog_content = "でも見たところ、ただの石の台だよ。",
  ui_story_1011_10111201_167_dialog_content = "横になにか仕掛けはある？",
  ui_story_1011_10111201_168_dialog_content = "ゴホゴホ…すごいホコリだ…",
  ui_story_1011_10111201_169_dialog_content = "感知能力を使ってみたら？",
  ui_story_1011_10111201_170_dialog_content = "やってみたけど、何の反応もないよ。",
  ui_story_1011_10111201_171_dialog_content = "確実に、ただの石だよ。",
  ui_story_1011_10111201_172_dialog_content = "そんな、どうして…？",
  ui_story_1011_10111201_173_dialog_content = "あるいは、ここにはかつて、\n何かが置かれていたのかも…",
  ui_story_1011_10111201_174_dialog_content = "でも、保存がきかない材質で、\n今はもう壊れたか、失くなってしまった？",
  ui_story_1011_10111201_175_dialog_content = "可能性はあるね。\nこの遺跡の中、どこもボロボロだし…",
  ui_story_1011_10111201_176_dialog_content = "あの巨大な石の扉だって、風化で裂け目があったんだ。\n他の物なら、なおさら…",
  ui_story_1011_10111201_177_dialog_content = "<color=#e8d9bb>ブオオン…</color>",
  ui_story_1011_10111201_178_dialog_content = "サブブレーン、ログイン申請を検知しました。",
  ui_story_1011_10111201_179_dialog_content = "サブブレーンの声！",
  ui_story_1011_10111201_180_dialog_content = "何かの仕掛けが動きだしたようね。\nPlayerName、何かした？",
  ui_story_1011_10111201_181_dialog_content = "ぼ、僕は何もしてないよ！",
  ui_story_1011_10111201_182_dialog_content = "僕の方こそ、君が何かしたのかと思ったよ！",
  ui_story_1011_10111201_183_dialog_content = "IDを確認します。",
  ui_story_1011_10111201_184_dialog_content = "情報を入力してください。",
  ui_story_1011_10111201_185_dialog_content = "僕の？",
  ui_story_1011_10111201_186_dialog_content = "僕はPlayerName。",
  ui_story_1011_10111201_187_dialog_content = "情報を確認します…",
  ui_story_1011_10111201_188_dialog_content = "情報を入力してください。",
  ui_story_1011_10111201_189_dialog_content = "え？PlayerNameだって言ったよ？\nそれじゃダメなの？",
  ui_story_1011_10111201_190_dialog_content = "遺跡の年代からして、PlayerNameという名前では\n同名の人物がいないのかも…",
  ui_story_1011_10111201_191_dialog_content = "じゃあどうすればいいの？",
  ui_story_1011_10111201_192_dialog_content = "そうだ、ここには「フランシス」っていう\n空の末裔がいたはずだ。",
  ui_story_1011_10111201_193_dialog_content = "あの人の名前で試したら、どうだろう？",
  ui_story_1011_10111201_194_dialog_content = "入力を検知しました：「パラ…パラ…パン」。",
  ui_story_1011_10111201_195_dialog_content = "え、「パラパラパン」って…変な名前だなあ。\n僕はそんなこと言ってないよ！",
  ui_story_1011_10111201_196_dialog_content = "ログイン者の識別を開始します。",
  ui_story_1011_10111201_197_dialog_content = "ツーッ…ツーッ…ツーッ…",
  ui_story_1011_10111201_198_dialog_content = "そんなヘンな名前の人、本当にいるのかな？",
  ui_story_1011_10111201_199_dialog_content = "ムダなことをするより、サブブレーン…\nまずはここはどんな場所か教えてくれる？",
  ui_story_1011_10111201_200_dialog_content = "待って、PlayerName！",
  ui_story_1011_10111201_201_dialog_content = "あれを見て…",
  ui_story_1011_10111201_202_dialog_content = "どうしたの？",
  ui_story_1011_10111201_203_dialog_content = "…",
  ui_story_1011_10111201_204_dialog_content = "あ、暗鬼たちが…\nどうして石板を押すのを止めたんだろう？",
  ui_story_1011_10111201_205_dialog_content = "ウソでしょ…",
  ui_story_1011_10111201_206_dialog_content = "グアアッ！",
  ui_story_1011_10111201_207_dialog_content = "カレン！",
  ui_story_1011_10111201_208_dialog_content = "散れ！氷花よ！",
  ui_story_1011_10111401_1_dialog_content = "よかったわ、数が多くなくて…",
  ui_story_1011_10111401_2_dialog_content = "こんな所で急に囲まれたら、\n逃げられなくなる所だったわ。",
  ui_story_1011_10111401_3_dialog_content = "そうだね…",
  ui_story_1011_10111401_4_dialog_content = "サブブレーン、どうしちゃったんだろう。\n前よりおかしくなってるみたいだ。",
  ui_story_1011_10111401_5_dialog_content = "サブブレーン、聞こえる？",
  ui_story_1011_10111401_6_dialog_content = "答えてくれない？何があったの？",
  ui_story_1011_10111401_7_dialog_content = "識別エラー。\n「パラパラパン」は不法侵入者とみなされます。",
  ui_story_1011_10111401_8_dialog_content = "情報を再入力してください。\nまたは、ID認証からログアウトしてください。",
  ui_story_1011_10111401_9_dialog_content = "わけがわからないよ。\nまったく僕の話を聞いてない…",
  ui_story_1011_10111401_10_dialog_content = "サブブレーンの態度が変わっているわね。",
  ui_story_1011_10111401_11_dialog_content = "前はあなたの質問を聞いて、\n質問に答えていた。",
  ui_story_1011_10111401_12_dialog_content = "でも、今はただあなたの入力を\n待っているだけ…",
  ui_story_1011_10111401_13_dialog_content = "そう言われてみれば、確かに…",
  ui_story_1011_10111401_14_dialog_content = "でも、どうして？",
  ui_story_1011_10111401_15_dialog_content = "おそらく、場所が変わったからでしょう。",
  ui_story_1011_10111401_16_dialog_content = "この空間が、\n指令を出される場所だったのかもしれないわ。",
  ui_story_1011_10111401_17_dialog_content = "そうなのかな？",
  ui_story_1011_10111401_18_dialog_content = "サブブレーン、ID認証からログアウトするよ。",
  ui_story_1011_10111401_19_dialog_content = "回帰の塔再起動リクエストを検知しました。",
  ui_story_1011_10111401_20_dialog_content = "申請者はパラパラパン…\n権限がありません。",
  ui_story_1011_10111401_21_dialog_content = "警告…このまま操作を継続する場合、\n<color=#FFB400>「防衛システム」</color>が起動します。",
  ui_story_1011_10111401_22_dialog_content = "またこれだ！",
  ui_story_1011_10111401_23_dialog_content = "そのヘンな名前、僕のことだっていうの？\n僕はリクエストなんて出してないよ！",
  ui_story_1011_10111401_24_dialog_content = "難しく考えすぎかもしれないわね…",
  ui_story_1011_10111401_25_dialog_content = "ただ単純に、壊れたということではないかしら。",
  ui_story_1011_10111401_26_dialog_content = "壊れた？サブブレーンが？",
  ui_story_1011_10111401_27_dialog_content = "サブブレーンではなく…\nあなたの指令を受信する装置ね。",
  ui_story_1011_10111401_28_dialog_content = "啓光のラジオを使ったことはある？",
  ui_story_1011_10111401_29_dialog_content = "ああいうものは壊れると、\n雑音が出るわ。",
  ui_story_1011_10111401_30_dialog_content = "妙な名前にされているのは…\nそういう音を拾っているようなものかも。",
  ui_story_1011_10111401_31_dialog_content = "だったら、大変だよ…",
  ui_story_1011_10111401_32_dialog_content = "回帰の塔、再起動リクエストが確認されました。",
  ui_story_1011_10111401_33_dialog_content = "警告、ただちに指令を取消さなければ、\n「防衛システム」が起動します。",
  ui_story_1011_10111401_34_dialog_content = "取り消す！もちろん、取り消すよ！",
  ui_story_1011_10111401_35_dialog_content = "そもそも、僕は指令なんか出してないって！",
  ui_story_1011_10111401_36_dialog_content = "警告、不法侵入者が\n回帰の塔再起動プログラムを強制実行…",
  ui_story_1011_10111401_37_dialog_content = "リングシステム内の回帰の塔\n再起動プロセスにアクセス中…",
  ui_story_1011_10111401_38_dialog_content = "ツーッ…ツーッ…ツーッ…",
  ui_story_1011_10111401_39_dialog_content = "イヤな予感がする…何かが始まるみたいだ。",
  ui_story_1011_10111401_40_dialog_content = "私もよ。サブブレーンを止められる？",
  ui_story_1011_10111401_41_dialog_content = "ジャマばっかりするなら、\nもういっそ壊しちゃおうか…？",
  ui_story_1011_10111401_42_dialog_content = "どうせもう壊れてるなら、徹底的にやらなきゃ！\n中途半端にしたって意味がない！",
  ui_story_1011_10111401_43_dialog_content = "でも、どこにあるんだろう？\nこの石の台かな？",
  ui_story_1011_10111401_44_dialog_content = "とにかく、まずは試してみよう…えい！",
  ui_story_1011_10111401_45_dialog_content = "<color=#e8d9bb>ガキン！</color>",
  ui_story_1011_10111401_46_dialog_content = "イテテテテ！！！",
  ui_story_1011_10111401_47_dialog_content = "石で出来ているのよ？\n蹴ったって壊せないわ。",
  ui_story_1011_10111401_48_dialog_content = "警告、不法侵入者が回帰の塔再起動プログラムを\n強制実行…",
  ui_story_1011_10111401_49_dialog_content = "エネルギーモジュール回復、\nその他モジュールへのエネルギー供給を開始…",
  ui_story_1011_10111401_50_dialog_content = "ツーッ…ツーッ…ツーッ…",
  ui_story_1011_10111401_51_dialog_content = "カレン、足元から軽い震動が…",
  ui_story_1011_10111401_52_dialog_content = "私も感じるわ。",
  ui_story_1011_10111401_53_dialog_content = "「再起動」というのは…\nもしかして、この遺跡全体に何か変化が起こるということかしら。",
  ui_story_1011_10111401_54_dialog_content = "遺跡全体が？大丈夫かな…",
  ui_story_1011_10111401_55_dialog_content = "もっと心配するべきことがあるわ…",
  ui_story_1011_10111401_56_dialog_content = "サブブレーンは何度も「警告」していた。\n脅かしだけとは思えない。",
  ui_story_1011_10111401_57_dialog_content = "警告、不法侵入者が\n回帰の塔再起動プログラムを強制実行中…",
  ui_story_1011_10111401_58_dialog_content = "指令権限にエラーを発見。\nただちに自動修正を実行します。",
  ui_story_1011_10111401_59_dialog_content = "最終警告です。\nただちに指令を取り消してください。",
  ui_story_1011_10111401_60_dialog_content = "取り消すって、もう言ったでしょ！",
  ui_story_1011_10111401_61_dialog_content = "お願いだよ、取り消して！",
  ui_story_1011_10111401_62_dialog_content = "訳も分からないまま\n古代文明と対立なんてしたくないよ！",
  ui_story_1011_10111401_64_dialog_content = "不法な指令が依然として継続中…",
  ui_story_1011_10111401_65_dialog_content = "修正プログラム、実行準備中…",
  ui_story_1011_10111401_66_dialog_content = "サブブレーン！もうめちゃくちゃだ…",
  ui_story_1011_10111401_67_dialog_content = "「防衛システム」起動。\nクローディアを解放します。",
  ui_story_1011_10111401_68_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_1011_10111401_69_dialog_content = "これは…",
  ui_story_1011_10111401_70_dialog_content = "彫像？それともロボット？",
  ui_story_1011_10111401_71_dialog_content = "これ…動くの？",
  ui_story_1011_10111401_72_dialog_content = "どうせ…壊れてるんじゃ…",
  ui_story_1011_10111401_73_dialog_content = "<color=#e8d9bb>カチャ――カチャ――</color>",
  ui_story_1011_10111401_74_dialog_content = "…動くようね。",
  ui_story_1011_10111401_75_dialog_content = "PlayerName、戦うわよ。",
  ui_story_1011_10111401_76_dialog_content = "…サブブレーン、まだ話せる？",
  ui_story_1011_10111401_77_dialog_content = "「防衛システム」がエラー修正を開始…",
  ui_story_1011_10111401_78_dialog_content = "不法な指令を修正、および\n指令の入力者を修正します。",
  ui_story_1011_10111402_1_dialog_content = "面倒ね…",
  ui_story_1011_10111402_2_dialog_content = "光力術への対処法を知っているようだわ。",
  ui_story_1011_10111402_3_dialog_content = "このままじゃ…",
  ui_story_1011_10111402_4_dialog_content = "カレン、持ちこたえられる？",
  ui_story_1011_10111402_5_dialog_content = "私は問題ない。でも…",
  ui_story_1011_10111402_6_dialog_content = "バイスが側にいるの、\n何かあってはまずいわ。",
  ui_story_1011_10111402_7_dialog_content = "出来るだけ早く片付ける方法はない？",
  ui_story_1011_10111402_8_dialog_content = "回帰の塔、各設備のセルフチェックを開始――",
  ui_story_1011_10111402_9_dialog_content = "警告、損傷が高危険域に到達しています。\n大部分のエリアが正常に使用できません。",
  ui_story_1011_10111402_10_dialog_content = "「損害管理プログラム」を起動し、修復を試みます。",
  ui_story_1011_10111402_11_dialog_content = "！！！",
  ui_story_1011_10111402_12_dialog_content = "カレン、あいつの動きが停まった！",
  ui_story_1011_10111402_13_dialog_content = "今のうちだ！背後に回り込んで！",
  ui_story_1011_10111402_14_dialog_content = "分かったわ！",
  ui_story_1011_10111402_15_dialog_content = "「防衛システム」、正常に起動中…",
  ui_story_1011_10111402_16_dialog_content = "該当部分をスキップし、\n引き続き指令入力システムの修復に移行…。",
  ui_story_1011_10111402_17_dialog_content = "ツーッ…ツーッ…ツーッ…",
  ui_story_1011_10111402_18_dialog_content = "<color=#e8d9bb>ガタン――</color>",
  ui_story_1011_10111402_19_dialog_content = "カレン！また動き出した！\n気を付けて！",
  ui_story_1011_10111402_20_dialog_content = "十分、時間は足りた。",
  ui_story_1011_10111402_21_dialog_content = "古代の兵器よ…\n未来の光力術を見るがいい！",
  ui_story_1011_10111402_22_dialog_content = "ふぅ…片付いたのかな…",
  ui_story_1011_10111402_23_dialog_content = "ええ、行動力を失ったようね。",
  ui_story_1011_10111402_24_dialog_content = "でも、まだ油断できない。",
  ui_story_1011_10111402_25_dialog_content = "今まで見てきた通り、\n回帰の塔には強力な防衛システムがある…",
  ui_story_1011_10111402_26_dialog_content = "それを怒らせてしまった以上、\nどんな面倒ごとが待ってるか知れないわ。",
  ui_story_1011_10111402_27_dialog_content = "まさか…",
  ui_story_1011_10111402_28_dialog_content = "ハハハ…ケンカするほど仲がいいって言うでしょ…\n根に持たないで…",
  ui_story_1011_10111402_29_dialog_content = "ガチャリ――カチン――",
  ui_story_1011_10111402_30_dialog_content = "「損害管理プログラム」が完了しました。\n主要な機能が修復されました。",
  ui_story_1011_10111402_31_dialog_content = "回帰の塔が再起動されました…",
  ui_story_1011_10111402_32_dialog_content = "え？知らない間に終わっちゃった…\n思ったより大したことなかったなぁ…",
  ui_story_1011_10111402_33_dialog_content = "回帰の塔、エネルギー供給システムが回復しました。",
  ui_story_1011_10111402_34_dialog_content = "エネルギー伝動システムが回復しました。",
  ui_story_1011_10111402_35_dialog_content = "センサーシステムが回復しました。",
  ui_story_1011_10111402_36_dialog_content = "<color=#e8d9bb>カラカラカラカラ…</color>",
  ui_story_1011_10111402_37_dialog_content = "カレン！\n機械の動く音があちこちから聞こえてくる！",
  ui_story_1011_10111402_38_dialog_content = "塔が…塔全体が稼働を始めた！",
  ui_story_1011_10111402_39_dialog_content = "なんということ…",
  ui_story_1011_10111402_40_dialog_content = "この遺跡、廃墟などでは無かった…",
  ui_story_1011_10111402_41_dialog_content = "長い間、眠っていただけなのね…",
  ui_story_1011_10111402_42_dialog_content = "回帰の塔内部の状況レポート…",
  ui_story_1011_10111402_43_dialog_content = "巨像整備エリア、現在、巨像1台。ステータス：修理待機中。",
  ui_story_1011_10111402_44_dialog_content = "巨像パーツ生産ライン、完全に損壊、修復に失敗しました。",
  ui_story_1011_10111402_45_dialog_content = "資源生産エリア、現在、人員0名。",
  ui_story_1011_10111402_46_dialog_content = "廃棄物処理エリア、現在、人員0名。",
  ui_story_1011_10111402_47_dialog_content = "空の末裔居住区、現在、人員0名。",
  ui_story_1011_10111402_48_dialog_content = "追放区、現在、人員0名。",
  ui_story_1011_10111402_49_dialog_content = "…",
  ui_story_1011_10111402_50_dialog_content = "ここにはもう、空の末裔はいないんだね…",
  ui_story_1011_10111402_51_dialog_content = "中枢エリア、現在、人員1名",
  ui_story_1011_10111402_52_dialog_content = "僕のことか…",
  ui_story_1011_10111402_53_dialog_content = "塔が長い夢から覚めたんだ。",
  ui_story_1011_10111402_54_dialog_content = "でも…誰もいなくて寂しくなったりしないかな。",
  ui_story_1011_10111402_55_dialog_content = "位置回復プログラム、起動準備中。",
  ui_story_1011_10111402_56_dialog_content = "回帰の塔、位置を回復中…",
  ui_story_1011_10111402_57_dialog_content = "まだ、騒ぐ元気があるの？",
  ui_story_1011_10111402_58_dialog_content = "はぁ…はぁ…",
  ui_story_1011_10111402_59_dialog_content = "まだ終わってねぇぞ！",
  ui_story_1011_10111402_60_dialog_content = "どっちかが倒れるまでやらなきゃ、\n面白くねぇだろが！",
  ui_story_1011_10111402_61_dialog_content = "たった1人で吠えたって、\n敗北は目に見えてるわ…",
  ui_story_1011_10111402_62_dialog_content = "こんなの戦いですらない…\nあなたがだだをこねてるだけよ。",
  ui_story_1011_10111402_63_dialog_content = "（コイツ、強ぇ…この俺が完全に押されてる）",
  ui_story_1011_10111402_64_dialog_content = "（情けねえ話だが…今までやれてるのは、\nあっちに戦う気がねえからだ）",
  ui_story_1011_10111402_65_dialog_content = "（この白い塔の中に一体何があるってんだ？\nそこまで執着するほどのものが…？）",
  ui_story_1011_10111402_66_dialog_content = "（まあ、いい…考えたところで分かりゃしねえ）",
  ui_story_1011_10111402_67_dialog_content = "（ただ、これだけは分かる…\n敵がここまで執着してる以上、何があっても阻止しないとならねぇ）",
  ui_story_1011_10111402_68_dialog_content = "（軍人たる者、敵が強いからって\n怖気づくわけにはいかねぇ！）",
  ui_story_1011_10111402_69_dialog_content = "かかってこい、ノラ！！！",
  ui_story_1011_10111402_70_dialog_content = "ザコどもじゃ相手にならねぇぞ！！",
  ui_story_1011_10111402_71_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_1011_10111402_72_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1011_10111402_73_dialog_content = "おいおいおい、どうした？地震か！？",
  ui_story_1011_10111402_74_dialog_content = "今いい所だろうが！！\n水を差すんじゃねえ！",
  ui_story_1011_10111402_75_dialog_content = "…これはただの地震じゃない…",
  ui_story_1011_10111402_76_dialog_content = "塔が…",
  ui_story_1011_10111402_77_dialog_content = "塔が…動いてる。",
  ui_story_1011_10111402_78_dialog_content = "クソ、すげえ煙だ！ゲホ…ゴホゴホ…",
  ui_story_1011_10111402_79_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1011_10111402_80_dialog_content = "うおおぉぉぉ！？",
  ui_story_1011_10111402_81_dialog_content = "こりゃ地震なんてモンじゃねぇぞ！？",
  ui_story_1011_10111402_82_dialog_content = "当然でしょ。",
  ui_story_1011_10111402_83_dialog_content = "1000年…いえ、10000年に\nたった1度の光景が見られるわよ。",
  ui_story_1011_10111402_84_dialog_content = "こんな場所はこの塔にふさわしくない…",
  ui_story_1011_10111402_85_dialog_content = "この塔は…もっと高みにあるべきもの。",
  ui_story_1011_10111402_86_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴゴ…</color>",
  ui_story_1011_10111402_87_dialog_content = "なんだぁ！？",
  ui_story_1011_10111402_88_dialog_content = "俺の目がおかしくなってやがんのか？\nこんなデケェ塔が…地面から上がって来てんのか！？",
  ui_story_1011_10111402_89_dialog_content = "PlayerNameたちがまだ中にいるんだぞ！？",
  ui_story_1011_10111402_90_dialog_content = "あいつら、一体…何をしでかしたんだ…？",
  ui_story_1011_10111402_91_dialog_content = "本当にこの目で見られるとはね…\n長い時を経て、なお動き始める古代建築…",
  ui_story_1011_10111402_92_dialog_content = "私と壁1枚へだてた向こう側に…",
  ui_story_1011_10111402_93_dialog_content = "別の時代がある…！",
  ui_story_1011_10111402_94_dialog_content = "つまり、どういうことだよ？\nこんなもんの研究、してたことあんのか？",
  ui_story_1011_10111402_95_dialog_content = "答える義理はないわ。",
  ui_story_1011_10111402_96_dialog_content = "『ノラ様！』",
  ui_story_1011_10111402_97_dialog_content = "『上昇した白い塔の外壁にすき間を発見しました！』",
  ui_story_1011_10111402_98_dialog_content = "素晴らしいわ。",
  ui_story_1011_10111402_99_dialog_content = "やっと狂犬に構わなくてすむわね…",
  ui_story_1011_10111402_100_dialog_content = "おい、てめぇ！\n俺から逃げる気か！",
  ui_story_1011_10111402_101_dialog_content = "戦いはまだ終わってねえぞ！",
  ui_story_1011_10111402_101X1_dialog_content = "（こんなハデなことをして…ノラの反応を見る限り、\nPlayerNameのヤツら、きっと何か大事なことをしてるはずだ）",
  ui_story_1011_10111402_101X2_dialog_content = "（ノラにジャマをさせるわけにはいかねえ…絶対に！）",
  ui_story_1011_10111402_102_dialog_content = "ど、どどどど、どうなってるの！？すごい揺れだ！",
  ui_story_1011_10111402_103_dialog_content = "何かにしっかりつかまって！\n上から落ちてくる物に気を付けて！",
  ui_story_1011_10111402_104_dialog_content = "バイスは？",
  ui_story_1011_10111402_105_dialog_content = "心配いらないわ、私が見ている！",
  ui_story_1011_10111402_106_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴゴ――</color>",
  ui_story_1011_10111402_107_dialog_content = "はぁ…はぁ…止まった…",
  ui_story_1011_10111402_108_dialog_content = "カレン、大丈夫？",
  ui_story_1011_10111402_109_dialog_content = "私は大丈夫、バイスも無事よ。\nそれより…",
  ui_story_1011_10111402_110_dialog_content = "いつまで石の台を抱えてるの？\nもう放して大丈夫よ。",
  ui_story_1011_10111402_111_dialog_content = "あ、そうだね…",
  ui_story_1011_10111402_112_dialog_content = "結局、一体何が起こったんだろう？",
  ui_story_1011_10111402_113_dialog_content = "私の感覚では、上昇していたようね。",
  ui_story_1011_10111402_114_dialog_content = "僕もそう感じた。",
  ui_story_1011_10111402_115_dialog_content = "回帰の塔の位置を回復しました。",
  ui_story_1011_10111402_116_dialog_content = "管理者に状況を報告…",
  ui_story_1011_10111402_117_dialog_content = "「回帰の塔の位置を回復」…\n塔全体の位置が変わったということ？",
  ui_story_1011_10111402_118_dialog_content = "そんなこと、どうやって…",
  ui_story_1011_10111402_119_dialog_content = "報告に失敗しました。\n管理者が発見できません。",
  ui_story_1011_10111402_120_dialog_content = "予備プログラムを実行します。\n回帰の塔再起動プログラムの起動者を検索…",
  ui_story_1011_10111402_121_dialog_content = "未承認の侵入者「パラパラパン」と確認。",
  ui_story_1011_10111402_122_dialog_content = "また僕にからむつもり！？",
  ui_story_1011_10111402_123_dialog_content = "予備プログラムを実行中…\n再起動を実行した「パラパラパン」を管理者に昇格。",
  ui_story_1011_10111402_124_dialog_content = "「パラパラパン」にインナーリングまでの権限が開放されます。",
  ui_story_1011_10111402_125_dialog_content = "えっ？",
  ui_story_1011_10111402_126_dialog_content = "今まで不法侵入者扱いされてたのに？\nどうして急に管理者に？",
  ui_story_1011_10111402_127_dialog_content = "…それに、その管理者って何をするの？",
  ui_story_1011_10111402_128_dialog_content = "管理者はサブブレーンを通じ、\n回帰の塔内の大部分の機能を制御、使用することができます。",
  ui_story_1011_10111402_129_dialog_content = "なるほど…",
  ui_story_1011_10111402_130_dialog_content = "いや、待って。\n普通に僕の質問に答えてくれたね？",
  ui_story_1011_10111402_131_dialog_content = "はい。",
  ui_story_1011_10111402_132_dialog_content = "じゃあ、さっきはなんで\n質問に答えてくれなかったの？",
  ui_story_1011_10111402_133_dialog_content = "中枢エリアでは、権限が確認されるまでサブブレーンとの通信は行えず、\n指令を入力することしかできません。",
  ui_story_1011_10111402_134_dialog_content = "管理者のみ、\n常時サブブレーンとの通信権限が与えられています。",
  ui_story_1011_10111402_135_dialog_content = "君って、けっこう人を見るタイプだったんだね。",
  ui_story_1011_10111402_136_dialog_content = "サブブレーンは、今の言葉の意味が理解できませんでした。",
  ui_story_1011_10111402_137_dialog_content = "…いや、いいんだ。",
  ui_story_1011_10111402_138_dialog_content = "でも、指令の入力と言えば、\nさっきはデタラメばっかり入力されてたよ！？",
  ui_story_1011_10111402_139_dialog_content = "おまけに「パラパラパン」なんてヘンな名前をつけられたんだ！",
  ui_story_1011_10111402_140_dialog_content = "指令の入力システムが壊れていたようです。\n現在は修復されています。",
  ui_story_1011_10111402_141_dialog_content = "申し訳ありません、\nご迷惑をおかけしました。",
  ui_story_1011_10111402_142_dialog_content = "まったく、とんでもない大迷惑だったよ…",
  ui_story_1011_10111402_143_dialog_content = "それから、「インナーリングの権限を開放する」って、\nどういうこと？",
  ui_story_1011_10111402_144_dialog_content = "回帰の塔の情報および機能の取り扱い権限は\n3等級に分かれています。",
  ui_story_1011_10111402_145_dialog_content = "<color=#FFB400>「アウターリング」</color>は、\n塔内部にいる一般の者なら誰でもアクセスできます。",
  ui_story_1011_10111402_146_dialog_content = "<color=#FFB400>「インナーリング」</color>は、\n管理者のみアクセスできます。",
  ui_story_1011_10111402_147_dialog_content = "<color=#FFB400>「コアリング」</color>は、\n最古かつ最高の命令に属するものであり、アクセスすることはできません。",
  ui_story_1011_10111402_148_dialog_content = "うーん…ってことは、そもそもアクセスできない「コアリング」を除けば、\n僕は最高権限を持っているということ？",
  ui_story_1011_10111402_149_dialog_content = "その通りです。",
  ui_story_1011_10111402_150_dialog_content = "あなたはすでにインナーリングの権限が確認されています。\nこれから回帰の塔と感知を同期します。",
  ui_story_1011_10111402_151_dialog_content = "え？何？",
  ui_story_1011_10111402_152_dialog_content = "覚えきれないほど\n新しい言葉がどんどん増える…",
  ui_story_1011_10111402_153_dialog_content = "覚える必要はありません。\n意識で感じるだけでいいのです。",
  ui_story_1011_10111402_154_dialog_content = "回帰の塔があなたの目になります。",
  ui_story_1011_10111402_155_dialog_content = "これは…",
  ui_story_1011_10111402_156_dialog_content = "すごく高い…！\nこれが回帰の塔の全体像？",
  ui_story_1011_10111402_157_dialog_content = "あれは…僕たちが爆破した場所だ！",
  ui_story_1011_10111402_158_dialog_content = "やっぱり、白い塔とは一体だったんだ！",
  ui_story_1011_10111402_159_dialog_content = "PlayerName、外の様子が見えるの？",
  ui_story_1011_10111402_160_dialog_content = "そうだよ！",
  ui_story_1011_10111402_161_dialog_content = "不思議だなあ。\nまるで僕自身が塔の外を飛んでるみたいだ…",
  ui_story_1011_10111402_162_dialog_content = "他の場所も見ることが可能です。",
  ui_story_1011_10111402_163_dialog_content = "遠隔リンクを確立中…",
  ui_story_1011_10111501_1_dialog_content = "あっちだ！あっちを調べろ！",
  ui_story_1011_10111501_2_dialog_content = "もう見たぞ！何もない！",
  ui_story_1011_10111501_3_dialog_content = "だったら、あれは一体…",
  ui_story_1011_10111501_4_dialog_content = "早く人を呼ぶんだ！",
  ui_story_1011_10111501_5_dialog_content = "これは俺たちで解決できることじゃない！",
  ui_story_1011_10111501_6_dialog_content = "そうだ！ナイトガーディアンを呼ぶんだ！",
  ui_story_1011_10111501_7_dialog_content = "上層部でないと解決できないぞ！",
  ui_story_1011_10111501_8_dialog_content = "ダモクレスが…",
  ui_story_1011_10111501_9_dialog_content = "ナディーン…もう一度、詳細に説明を。",
  ui_story_1011_10111501_10_dialog_content = "はい、城主様！",
  ui_story_1011_10111501_11_dialog_content = "衛兵の報告によりますと、\n10分程前に「制御室」で異常が発見されました。",
  ui_story_1011_10111501_12_dialog_content = "衛兵たちは同様の事態に対応した前例がなく、\n点検修理の成果も出ないため、混乱しています。",
  ui_story_1011_10111501_13_dialog_content = "現場の報告と状況から推測するに――",
  ui_story_1011_10111501_14_dialog_content = "<color=#FFB400>ダモクレス</color>が\n起動していると思われます。",
  ui_story_1011_10111501_15_dialog_content = "また、ダモクレスですか…？",
  ui_story_1011_10111501_16_dialog_content = "今回は一体誰でしょう？",
  ui_story_1011_10111501_17_dialog_content = "誰もおりません。",
  ui_story_1011_10111501_18_dialog_content = "！？",
  ui_story_1011_10111501_19_dialog_content = "衛兵がコントロールルームの隅々まで捜索しました。\n間違いなく――誰もいないようです。",
  ui_story_1011_10111501_20_dialog_content = "ダモクレスが自分から起動したようです。",
  ui_story_1011_10111501_21_dialog_content = "そんなはずは…！？",
  ui_story_1011_10111501_22_dialog_content = "…ダモクレスの状況は？",
  ui_story_1011_10111501_23_dialog_content = "起動プロセスが進行中です。\n光力を集積しはじめています。",
  ui_story_1011_10111501_24_dialog_content = "分かった。",
  ui_story_1011_10111501_25_dialog_content = "ナディーン、ただちにダモクレスと\n白夜城の光力接続の遮断に向かえ。",
  ui_story_1011_10111501_26_dialog_content = "後の事は考えずともよい。\n一刻を争う。",
  ui_story_1011_10111501_27_dialog_content = "はい、城主様！",
  ui_story_1011_10111501_28_dialog_content = "イルンティ、そなたは部下を連れて制御室を封鎖せよ。\n何人たりとも近づけてはならぬ。",
  ui_story_1011_10111501_29_dialog_content = "…特に元老院の者どもはな。\n危機の迫る時に限って面倒を起こしたがる…",
  ui_story_1011_10111501_30_dialog_content = "承知しました、城主様。",
  ui_story_1011_10111501_31_dialog_content = "ですが、まずは情報をお確かめに\nなってはいかがですか？",
  ui_story_1011_10111501_32_dialog_content = "ダモクレスとの接続を遮断し、制御室を封鎖するとなりますと、\n白夜城全体に大きな影響を及ぼします。",
  ui_story_1011_10111501_33_dialog_content = "状況を正確に把握できなかった衛兵数名の処罰で問題が解決するのなら、\nそれに越したことはない。",
  ui_story_1011_10111501_34_dialog_content = "…だが、そう簡単な事態ではあるまい。",
  ui_story_1011_10111501_35_dialog_content = "いつ暴発するとも分からぬダモクレスを野放しにする危険を冒すより、\n他の面での損失を被る方がよい。",
  ui_story_1011_10111501_36_dialog_content = "はい…承知致しました。",
  ui_story_1011_10111501_37_dialog_content = "四大天使は、余に続け。",
  ui_story_1011_10111501_38_dialog_content = "はっ！",
  ui_story_1011_10111501_39_dialog_content = "<color=#e8d9bb>ブオォォン――！</color>",
  ui_story_1011_10111501_40_dialog_content = "光力パルス、来るよ！",
  ui_story_1011_10111501_41_dialog_content = "でも…ダモクレスの力が弱まった！",
  ui_story_1011_10111501_42_dialog_content = "そうか…そなたら、まだやれるか？",
  ui_story_1011_10111501_43_dialog_content = "まだやれるよ…\nでも、そろそろ限界！",
  ui_story_1011_10111501_44_dialog_content = "みんな、もう一息よ…",
  ui_story_1011_10111501_45_dialog_content = "熱いわ…胸が…燃えるように…",
  ui_story_1011_10111501_46_dialog_content = "…",
  ui_story_1011_10111501_47_dialog_content = "わかった。",
  ui_story_1011_10111501_48_dialog_content = "いっせいに仕掛けるぞ。\nこれで終わらせるのだ。",
  ui_story_1011_10111501_49_dialog_content = "全員、光力を放射して\nダモクレスへの光力転送に干渉せよ！",
  ui_story_1011_10111501_50_dialog_content = "全力をもって\nダモクレスの稼働を停止するのだ！",
  ui_story_1011_10111501_51_dialog_content = "はい！",
  ui_story_1011_10111501_52_dialog_content = "<color=#e8d9bb>ブオオン――！</color>",
  ui_story_1011_10111501_53_dialog_content = "<color=#e8d9bb>ブオン……</color>",
  ui_story_1011_10111501_54_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1011_10111501_55_dialog_content = "はあ…はあ…はあ…",
  ui_story_1011_10111501_56_dialog_content = "う、うまくいったの？止まった？",
  ui_story_1011_10111501_57_dialog_content = "燃え尽きたわ…私たちも…ダモクレスも…",
  ui_story_1011_10111501_58_dialog_content = "…",
  ui_story_1011_10111501_59_dialog_content = "…これで解決でしょうか？",
  ui_story_1011_10111501_60_dialog_content = "この場は、な。",
  ui_story_1011_10111501_61_dialog_content = "しかし…",
  ui_story_1011_10111501_62_dialog_content = "ダモクレス…",
  ui_story_1011_10111501_63_dialog_content = "…どこを狙っていた…？",
  ui_story_1011_10111501_64_dialog_content = "<color=#e8d9bb>ブオン！ブオン！ブオン！</color>",
  ui_story_1011_10111501_65_dialog_content = "うるさいにゃ～！",
  ui_story_1011_10111501_66_dialog_content = "うう…フィリスがお昼寝してるのに…",
  ui_story_1011_10111501_67_dialog_content = "フィリス！！",
  ui_story_1011_10111501_68_dialog_content = "また、仕事中に居眠りしていましたね！？",
  ui_story_1011_10111501_69_dialog_content = "えええ、そんにゃ風に見にゃいで欲しいにゃ～。\nフィリスのおめめはパッチリなのにゃ～！",
  ui_story_1011_10111501_70_dialog_content = "…まあ、いいでしょう。\nその話はまた今度です。",
  ui_story_1011_10111501_71_dialog_content = "それより、この騒音は一体何ですか…？",
  ui_story_1011_10111501_72_dialog_content = "<color=#e8d9bb>ブオン！ブオン！ブオン！</color>",
  ui_story_1011_10111501_73_dialog_content = "やかましい！一体何の音だ！",
  ui_story_1011_10111501_74_dialog_content = "誰だ！？説明しろ！",
  ui_story_1011_10111501_75_dialog_content = "キシローナ長官！",
  ui_story_1011_10111501_76_dialog_content = "あなたまで…",
  ui_story_1011_10111501_77_dialog_content = "ビビアン、何の音か知っているか？",
  ui_story_1011_10111501_78_dialog_content = "いいえ…こんな音、聞いたこともありません…",
  ui_story_1011_10111501_79_dialog_content = "誰も分からないなどということがあるのか…？",
  ui_story_1011_10111501_80_dialog_content = "戦場でもないというのに…\nカナン城で騒音に悩まされるとはもってのほかだ。",
  ui_story_1011_10111501_81_dialog_content = "どこかの設備が故障したのでしょう。\nすぐに調べさせます！",
  ui_story_1011_10111501_82_dialog_content = "<color=#e8d9bb>ブオン！ブオン！ブオン！</color>",
  ui_story_1011_10111501_83_dialog_content = "――報告は以上です。\n現在はカナン城のどこへ行っても、この音が聞こえます…",
  ui_story_1011_10111501_84_dialog_content = "うんうん…",
  ui_story_1011_10111501_85_dialog_content = "検査させたところ、\n音の出所は防壁内部の古い設備だと分かりました。",
  ui_story_1011_10111501_86_dialog_content = "はるか昔に鑑定の後、放棄されていた部分ですが、\nどういうわけか今になって…",
  ui_story_1011_10111501_87_dialog_content = "うんうん…",
  ui_story_1011_10111501_88_dialog_content = "ガルー室長…聞いていますか？",
  ui_story_1011_10111501_89_dialog_content = "うん、聞いてる、聞いてる。",
  ui_story_1011_10111501_90_dialog_content = "あの話でしょ…そうそう、アレね。",
  ui_story_1011_10111501_91_dialog_content = "まったく聞いていませんでしたね！？",
  ui_story_1011_10111501_92_dialog_content = "本を置いてください！\n重大な案件なのです。",
  ui_story_1011_10111501_93_dialog_content = "騒音のせいでシェルター内は大混乱しているのです！",
  ui_story_1011_10111501_94_dialog_content = "ほかの技術者ではなすすべもありませんが、\n室長なら…",
  ui_story_1011_10111501_95_dialog_content = "シーッ――",
  ui_story_1011_10111501_96_dialog_content = "！？",
  ui_story_1011_10111501_97_dialog_content = "<color=#e8d9bb>ウォン！ウォン！ウォン！</color>",
  ui_story_1011_10111501_98_dialog_content = "あ～…そういうことね。",
  ui_story_1011_10111501_99_dialog_content = "分かった。\nあたし、本当に分かったよ。",
  ui_story_1011_10111501_100_dialog_content = "何がですか？",
  ui_story_1011_10111501_101_dialog_content = "イヤな音だけど、よ～く聞いて。",
  ui_story_1011_10111501_102_dialog_content = "これ、ただの騒音じゃないよ…言葉が混じってる。",
  ui_story_1011_10111501_103_dialog_content = "言葉ですか？",
  ui_story_1011_10111501_104_dialog_content = "そう、すっごく古い言葉。",
  ui_story_1011_10111501_105_dialog_content = "ええと…302ページ…564ページ…",
  ui_story_1011_10111501_106_dialog_content = "あった！",
  ui_story_1011_10111501_107_dialog_content = "古代の言語の意味って、\n大体が推測だから、正確かどうかは知らないけど…",
  ui_story_1011_10111501_108_dialog_content = "この言葉が伝えようとしてるのは、たぶん…",
  ui_story_1011_10111501_109_dialog_content = "<color=#FFB400>「急いで隠れて」</color>。",
  ui_story_1011_10111501_110_dialog_content = "おう、ヘール。",
  ui_story_1011_10111501_111_dialog_content = "ふん、覚悟はできたか？",
  ui_story_1011_10111501_112_dialog_content = "覚悟って、負けっぱなしなのはお前だろうが？",
  ui_story_1011_10111501_113_dialog_content = "それも今日限りだ！",
  ui_story_1011_10111501_114_dialog_content = "今日、俺様はみんなの前で、\n正々堂々とお前に勝つ！",
  ui_story_1011_10111501_115_dialog_content = "おお！威勢のいいこった！",
  ui_story_1011_10111501_116_dialog_content = "で…「みんな」ってのは？",
  ui_story_1011_10111501_117_dialog_content = "R・Wの全員を呼んである！！",
  ui_story_1011_10111501_118_dialog_content = "どうだ、全員の前で俺様と戦うんだぜ。\n緊張してきただろうが！？",
  ui_story_1011_10111501_119_dialog_content = "それはいいが…そのみんなは、どこだ？",
  ui_story_1011_10111501_120_dialog_content = "どこにも見えねえぞ？",
  ui_story_1011_10111501_121_dialog_content = "おい！みんな、出てこい！",
  ui_story_1011_10111501_122_dialog_content = "決闘が始まるぜ！",
  ui_story_1011_10111501_123_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1011_10111501_124_dialog_content = "おい！？",
  ui_story_1011_10111501_125_dialog_content = "拍手すればいいか？",
  ui_story_1011_10111501_126_dialog_content = "が、がんばって…",
  ui_story_1011_10111501_127_dialog_content = "お兄ちゃん、絶対勝ってね！",
  ui_story_1011_10111501_128_dialog_content = "なんでオメェら3人だけなんだよ！？",
  ui_story_1011_10111501_129_dialog_content = "何のスリルもないから、\n皆、興味ないってさ…",
  ui_story_1011_10111501_130_dialog_content = "今日は止めとかないか、ヘール？",
  ui_story_1011_10111501_131_dialog_content = "そんなこと出来るわけねぇだろ！",
  ui_story_1011_10111501_132_dialog_content = "お兄ちゃん、カッコよくぶっ飛ばしてね！",
  ui_story_1011_10111501_133_dialog_content = "おう！イブが見たいってぇなら、\n見せてやるさ！",
  ui_story_1011_10111501_134_dialog_content = "どこまで飛ばしてやろうか？",
  ui_story_1011_10111501_135_dialog_content = "あのさ…ボス、\nトラベラーの上でケンカするのはやめてもらえないかな…？",
  ui_story_1011_10111501_136_dialog_content = "フン！人が少ないなら、少ないでいいさ。",
  ui_story_1011_10111501_137_dialog_content = "後で俺様の伝説的な戦いを\n話して聞かせてやればいいだけだ！",
  ui_story_1011_10111501_138_dialog_content = "おう、やってみろ――",
  ui_story_1011_10111501_139_dialog_content = "<color=#e8d9bb>ガタン――！</color>",
  ui_story_1011_10111501_140_dialog_content = "おわあぁぁぁ！？",
  ui_story_1011_10111501_141_dialog_content = "何だ！？",
  ui_story_1011_10111501_142_dialog_content = "バップ、いきなりトラベラーを動かすんじゃねえ！",
  ui_story_1011_10111501_143_dialog_content = "ボス、私はここだよ。",
  ui_story_1011_10111501_144_dialog_content = "トラベラーの上には、\nボス以外誰もいないよ。",
  ui_story_1011_10111501_145_dialog_content = "何？どういうことだ！？",
  ui_story_1011_10111501_146_dialog_content = "おい、サメヤマ！逃げる気か！？",
  ui_story_1011_10111501_147_dialog_content = "誰が逃げるか！\nトラベラーが急に――",
  ui_story_1011_10111501_148_dialog_content = "<color=#e8d9bb>ゴゴゴ…ガタン！ガタン！</color>",
  ui_story_1011_10111501_149_dialog_content = "おわあぁぁ！？\n加速しやがったああああ！！",
  ui_story_1011_10111501_150_dialog_content = "おや？思ってたより面白くなりそうだ。",
  ui_story_1011_10111501_151_dialog_content = "お兄ちゃんが逃げた～！\n意気地なし～！",
  ui_story_1011_10111501_152_dialog_content = "違う！\nトラベラーが自分から動きやがったんだ！",
  ui_story_1011_10111501_153_dialog_content = "見てねえで、さっさと助けてくれ！",
  ui_story_1011_10111501_154_dialog_content = "おい！！",
  ui_story_1011_10111501_155_dialog_content = "<color=#e8d9bb>トントン…</color>",
  ui_story_1011_10111501_156_dialog_content = "こんにちは、イスタバンさん宛ての緊急の手紙です！\n受け取りのサインをお願いします！",
  ui_story_1011_10111501_157_dialog_content = "分かりました。こちらで預かります。",
  ui_story_1011_10111501_158_dialog_content = "…お待ちください。\n差出人はどなたですか？",
  ui_story_1011_10111501_159_dialog_content = "封筒には書いていないようですが…",
  ui_story_1011_10111501_160_dialog_content = "あ、それは…",
  ui_story_1011_10111501_161_dialog_content = "イスタバンさん宛ての緊急の手紙には\n差出人はなくていいって言われてます！",
  ui_story_1011_10111501_162_dialog_content = "イスタバンさんご本人の希望だそうです！",
  ui_story_1011_10111501_163_dialog_content = "そうですか。分かりました。",
  ui_story_1011_10111501_164_dialog_content = "ご苦労様です。",
  ui_story_1011_10111501_165_dialog_content = "では、確かに届けましたよ！\nクーリエ隊のご利用、いつもありがとうございます！さようなら！",
  ui_story_1011_10111501_166_dialog_content = "こんにちは！イスタバンさん宛ての緊急のお手紙どす！\n受け取りのサインをお願いします～。",
  ui_story_1011_10111501_167_dialog_content = "またですか？分かりました。",
  ui_story_1011_10111501_168_dialog_content = "ええと、差出人は書かれとらへんのですけど、それは…",
  ui_story_1011_10111501_169_dialog_content = "本人の希望、ですよね？",
  ui_story_1011_10111501_170_dialog_content = "そないです！",
  ui_story_1011_10111501_171_dialog_content = "私が預かります。\nありがとうございました。",
  ui_story_1011_10111501_172_dialog_content = "かまいません！ほな、おおきに…",
  ui_story_1011_10111501_173_dialog_content = "ああああ！間に合わない、間に合わない！",
  ui_story_1011_10111501_174_dialog_content = "たぶん、そんなに遅れてないよね？\nお給料引かれないよね？",
  ui_story_1011_10111501_175_dialog_content = "ドーヴ先輩！あんさんもですの？",
  ui_story_1011_10111501_176_dialog_content = "あっ、タタ！あなたも…？",
  ui_story_1011_10111501_177_dialog_content = "まあいいや、話は後！\nああ、遅れちゃう！",
  ui_story_1011_10111501_178_dialog_content = "こんにちは、イスタバンさん宛ての緊急のお手紙です！\nこちらに受け取りのサインをお願いします！",
  ui_story_1011_10111501_179_dialog_content = "お義父様、先ほどクーリエ隊から緊急のお手紙が\n立て続けに届きましたが…",
  ui_story_1011_10111501_180_dialog_content = "緊急？見せてくれ。",
  ui_story_1011_10111501_181_dialog_content = "はい。",
  ui_story_1011_10111501_182_dialog_content = "緊急の手紙？一度に、こんなに？",
  ui_story_1011_10111501_183_dialog_content = "一体どこで何が起これば、\nスズメちゃんたちがこんなに大騒ぎするのかしら？",
  ui_story_1011_10111501_184_dialog_content = "…",
  ui_story_1011_10111501_185_dialog_content = "騒いでいるのはスズメだけではないようだ。",
  ui_story_1011_10111501_186_dialog_content = "シェオル、人をできるだけ多く出してくれ。\n白夜城の動向を見張らせろ。",
  ui_story_1011_10111501_187_dialog_content = "兵士1人が剣を抜いたという情報だけでもいい。\n可能な限り早く知らせろ。",
  ui_story_1011_10111501_188_dialog_content = "アハハ、お安い御用よ。\nすぐに動くわ…",
  ui_story_1011_10111501_189_dialog_content = "…でも、他の準備は要らないの？",
  ui_story_1011_10111501_190_dialog_content = "白夜城が動いてからじゃ、\n遅いんじゃない？",
  ui_story_1011_10111501_191_dialog_content = "このままでいい。",
  ui_story_1011_10111501_192_dialog_content = "俺たちは白夜城の影の中で生きている。",
  ui_story_1011_10111501_193_dialog_content = "影には影の、態度がある。",
  ui_story_1011_10111501_194_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ…</color>",
  ui_story_1011_10111501_195_dialog_content = "ビクトリア様、いかがなさいましたか？",
  ui_story_1011_10111501_196_dialog_content = "…",
  ui_story_1011_10111501_197_dialog_content = "おかしい。やはり反応がない…",
  ui_story_1011_10111501_198_dialog_content = "中に入ってみる？",
  ui_story_1011_10111501_199_dialog_content = "ビクトリア様のさっきの様子…心配だわ…",
  ui_story_1011_10111501_200_dialog_content = "いけません…そのようなことは絶対に…",
  ui_story_1011_10111501_201_dialog_content = "お許しもなくビクトリア様の部屋に入るなど、\nなんとおそれ多い…",
  ui_story_1011_10111501_202_dialog_content = "そこまで心配することないでしょ。\n疲れてただけかもしれないわ。",
  ui_story_1011_10111501_203_dialog_content = "それにしてもあんたたち、\nビクトリア様について回る以外、他にやることないの？",
  ui_story_1011_10111501_204_dialog_content = "もう一度、ノックしてみよう…",
  ui_story_1011_10111501_205_dialog_content = "<color=#e8d9bb>トントン…</color>",
  ui_story_1011_10111501_206_dialog_content = "ビクトリア様、何かございましたか？",
  ui_story_1011_10111501_207_dialog_content = "…",
  ui_story_1011_10111501_208_dialog_content = "これは一体…",
  ui_story_1011_10111501_209_dialog_content = "入りなさい、ファウスト。",
  ui_story_1011_10111501_210_dialog_content = "！！！",
  ui_story_1011_10111501_211_dialog_content = "あなた1人でいいわ。\n教典の邪魔をしたくないの。",
  ui_story_1011_10111501_212_dialog_content = "はい。",
  ui_story_1011_10111501_213_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_1011_10111501_214_dialog_content = "ビクトリア様…",
  ui_story_1011_10111501_215_dialog_content = "ごらんなさい。",
  ui_story_1011_10111501_216_dialog_content = "鮮血が紅血の教典の上を流れている…",
  ui_story_1011_10111501_217_dialog_content = "先ほどから今まで、ずっと。",
  ui_story_1011_10111501_218_dialog_content = "これは…新たな啓示でしょうか？",
  ui_story_1011_10111501_219_dialog_content = "いつもより時間がかかっているわね。",
  ui_story_1011_10111501_220_dialog_content = "血がすでに部屋のじゅうたんを浸しきっているというのに…\n教典には一言も浮かび上がらない。",
  ui_story_1011_10111501_221_dialog_content = "一体何が「真理」までをも黙らせているのかしら…？",
  ui_story_1011_10111501_222_dialog_content = "なぜ、このようなことが…",
  ui_story_1011_10111501_223_dialog_content = "今までにこのようなことはございましたか？",
  ui_story_1011_10111501_224_dialog_content = "シーッ――",
  ui_story_1011_10111501_225_dialog_content = "来るわ。",
  ui_story_1011_10111501_226_dialog_content = "ようやく…",
  ui_story_1011_10111501_227_dialog_content = "！！！",
  ui_story_1011_10111501_228_dialog_content = "「■■」",
  ui_story_1011_10111501_229_dialog_content = "「■■■■■■■■■■」",
  ui_story_1011_10111501_230_dialog_content = "どういうことです…！？",
  ui_story_1011_10111501_231_dialog_content = "見たこともない文字だ！\nビクトリア様、これは一体？",
  ui_story_1011_10111501_232_dialog_content = "ああ、紅血の教典…",
  ui_story_1011_10111501_233_dialog_content = "この啓示は、私たちに見せるためのものでは\nないということね？",
  ui_story_1011_10111501_234_dialog_content = "文字を読める者…啓示を受ける資格のある者…\nいったい誰なのかしら？",
  ui_story_1011_10111501_235_dialog_content = "うわあ！すっごくまぶしい！",
  ui_story_1011_10111501_236_dialog_content = "あれ？でも、太陽はさっき\n沈んだばかりじゃなかったっけ？",
  ui_story_1011_10111501_237_dialog_content = "あれは太陽じゃないよ！",
  ui_story_1011_10111501_238_dialog_content = "あれは、海辺の…灯台？",
  ui_story_1011_10111501_239_dialog_content = "そうみたいだね！",
  ui_story_1011_10111501_240_dialog_content = "でも灯台って、\nいつもこんなに明るかったかな？",
  ui_story_1011_10111501_241_dialog_content = "ノーヴィオ、女王陛下は氷の宮殿に？",
  ui_story_1011_10111501_242_dialog_content = "ええ、宮殿にいらっしゃいます。",
  ui_story_1011_10111501_243_dialog_content = "ひどい汗です。\n何かあったのですか？",
  ui_story_1011_10111501_244_dialog_content = "灯台が異常に明るく光っているの…",
  ui_story_1011_10111501_245_dialog_content = "北境を守る力に何か問題が起こっていないか、\n心配になったのよ。",
  ui_story_1011_10111501_246_dialog_content = "そうでしたか…\n確かに、重大な問題です。",
  ui_story_1011_10111501_247_dialog_content = "私も女王陛下のもとへ参りましょう。",
  ui_story_1011_10111501_248_dialog_content = "<color=#e8d9bb>タッ…タッ…タッ…</color>",
  ui_story_1011_10111501_249_dialog_content = "女王陛下、ナシリスが至急お会いしたいと…",
  ui_story_1011_10111501_250_dialog_content = "彼女が申しますには…",
  ui_story_1011_10111501_251_dialog_content = "見ている…",
  ui_story_1011_10111501_252_dialog_content = "今、なんと…？",
  ui_story_1011_10111501_253_dialog_content = "見ている…あれが…",
  ui_story_1011_10111501_254_dialog_content = "女王陛下、眠っていらっしゃるようね。",
  ui_story_1011_10111501_255_dialog_content = "起こした方がいいかしら…？",
  ui_story_1011_10111501_256_dialog_content = "灯台に異常が発生したとあらば、\n女王陛下はできるだけ早く状況をお知りになりたいはずです。",
  ui_story_1011_10111501_257_dialog_content = "陛下のお耳元でお話しになるとよいでしょう。",
  ui_story_1011_10111501_258_dialog_content = "わかったわ。",
  ui_story_1011_10111501_259_dialog_content = "女王陛下…",
  ui_story_1011_10111501_260_dialog_content = "灯台が太陽のごとく明るく輝いております…",
  ui_story_1011_10111501_261_dialog_content = "皆、恐れおののいております。\n一体何が北境の夜を奪おうとしているのでしょう？",
  ui_story_1011_10111501_262_dialog_content = "あれが…見ている…空の彼方から…",
  ui_story_1011_10111501_263_dialog_content = "塔が…はるか高き所にある、目が…",
  ui_story_1011_10111501_264_dialog_content = "女王陛下？",
  ui_story_1011_10111501_265_dialog_content = "逃げるのだ…身を隠せ…できる限り…遠くへ…",
  ui_story_1011_10111501_266_dialog_content = "山脈の頂に…海の孤島に…",
  ui_story_1011_10111501_267_dialog_content = "ノーヴィオ、女王陛下の顔色がおかしいわ。",
  ui_story_1011_10111501_268_dialog_content = "そのようですね…",
  ui_story_1011_10111501_269_dialog_content = "女王陛下、起きてくださいませ。",
  ui_story_1011_10111501_270_dialog_content = "…離れるのだ…",
  ui_story_1011_10111501_271_dialog_content = "塔から…",
  ui_story_1011_10111501_272_dialog_content = "いと高き…塔から…",
  ui_story_1011_10111501_273_dialog_content = "…女王陛下！？",
  ui_story_1011_10111501_274_dialog_content = "女王陛下！！！",
  ui_story_1011_10111501_275_dialog_content = "…",
  ui_story_1011_10111501_276_dialog_content = "女王陛下、どうされましたか…？",
  ui_story_1011_10111501_277_dialog_content = "<color=#FFB400>PlayerName、そなたか…！</color>",
  ui_story_1011_10111501_278_dialog_content = "！！！",
  ui_story_1011_10111501_279_dialog_content = "ち、違います！僕は…",
  ui_story_1011_10111501_280_dialog_content = "…えっ？",
  ui_story_1011_10111501_281_dialog_content = "どうして…何が起こってるの…？",
  ui_story_1011_10111501_282_dialog_content = "PlayerName、どうしたの？",
  ui_story_1011_10111501_283_dialog_content = "ええと、僕は一体…？",
  ui_story_1011_10111501_284_dialog_content = "言っても、信じてもらえないかもしれないけど…",
  ui_story_1011_10111501_285_dialog_content = "今、僕は確かに、この目で見たんだ…",
  ui_story_1011_10111501_286_dialog_content = "何を？",
  ui_story_1011_10111501_287_dialog_content = "<color=#FFB400>世界</color>を…",
  ui_story_1012_10120101_1_dialog_content = "…世界全体が見えたんだ。",
  ui_story_1012_10120101_2_dialog_content = "啓光から白夜城…",
  ui_story_1012_10120101_3_dialog_content = "北境に、R・W砂漠…",
  ui_story_1012_10120101_4_dialog_content = "一瞬で…すべてをこの目で見たんだ。",
  ui_story_1012_10120101_5_dialog_content = "まるで僕が僕自身じゃなくて…",
  ui_story_1012_10120101_6_dialog_content = "僕がこの回帰の塔になったみたいに…",
  ui_story_1012_10120101_7_dialog_content = "おかしいよ。過去の記録にある限り、\n空の末裔がこんな技術を持ってたなんて見たこともない。",
  ui_story_1012_10120101_8_dialog_content = "それは後回しにしましょう。",
  ui_story_1012_10120101_9_dialog_content = "塔の中核に隠された情報が知れるようになったのなら、\nバイスを助ける方法も分かるはずよ！",
  ui_story_1012_10120101_10_dialog_content = "そうだ！サブブレーン、\n「意識消失」状態から復活した事例の詳細を教えて！",
  ui_story_1012_10120101_11_dialog_content = "権限認証…クリア。\n報告を生成中…",
  ui_story_1012_10120101_12_dialog_content = "「意識消失」状態の実験体を<color=#FFB400>ハーモナイザー</color>に投入し、\n「同調」機能を併用して試験したところ…",
  ui_story_1012_10120101_13_dialog_content = "予想を上回る治療効果が確認されました。",
  ui_story_1012_10120101_14_dialog_content = "実験体の意識に回復の兆しが見られ、\n同時に肉体にも変化が起こりました。",
  ui_story_1012_10120101_15_dialog_content = "肉体への副作用は不明です。",
  ui_story_1012_10120101_16_dialog_content = "最終的に実験体は「同調」が完了するとともに、\n「意識消失」状態から復活しました。",
  ui_story_1012_10120101_17_dialog_content = "「ハーモナイザー」…？",
  ui_story_1012_10120101_18_dialog_content = "それは何なの？",
  ui_story_1012_10120101_19_dialog_content = "「ハーモナイザー」に関する情報を検索しています…",
  ui_story_1012_10120101_20_dialog_content = "…",
  ui_story_1012_10120101_21_dialog_content = "…",
  ui_story_1012_10120101_22_dialog_content = "#*%￥&￥#&*！",
  ui_story_1012_10120101_23_dialog_content = "サブブレーン！？",
  ui_story_1012_10120101_24_dialog_content = "エラー。プログラムを強制終了しました。",
  ui_story_1012_10120101_25_dialog_content = "「ハーモナイザー」に関する実験データは\n特別なエリアに保存されており、通常は公開されていません。",
  ui_story_1012_10120101_26_dialog_content = "今までの情報以上に\n厳重に保護されているということ？",
  ui_story_1012_10120101_27_dialog_content = "重要なもののようね。",
  ui_story_1012_10120101_28_dialog_content = "もしかして、リングシステムは\nこの白い塔で一番重要なものなんかじゃなくて…",
  ui_story_1012_10120101_29_dialog_content = "その「ハーモナイザー」こそが大事、ってこと？",
  ui_story_1012_10120101_30_dialog_content = "サブブレーン、その場所の詳しいデータはある？",
  ui_story_1012_10120101_31_dialog_content = "サブブレーンと該当エリアのリンクが切断されています。\nデータを読み込めません。",
  ui_story_1012_10120101_32_dialog_content = "ローカルデータベース内にある、\n当該装置に関する説明を再生――",
  ui_story_1012_10120101_33_dialog_content = "「ハーモナイザー」は傷の治療のほか、\n光霊の肉体の一部を改造することで、潜在能力を解放することができます。",
  ui_story_1012_10120101_34_dialog_content = "これにより、\n空の末裔との連携が最適化されます。",
  ui_story_1012_10120101_35_dialog_content = "そのような…体を造り替えてしまう装置が？",
  ui_story_1012_10120101_36_dialog_content = "…いえ、どこかつじつまが合わないわね。\n太古の空の末裔が光霊を敵と見なしていたのなら…",
  ui_story_1012_10120101_37_dialog_content = "光霊を空の末裔と連携しやすくする\n装置などというものが、なぜここにあるの？",
  ui_story_1012_10120101_38_dialog_content = "その通りだね。何かおかしい。",
  ui_story_1012_10120101_39_dialog_content = "PlayerName、記録をうのみにはできないわ。",
  ui_story_1012_10120101_40_dialog_content = "先に「ハーモナイザー」とやらの正体をはっきりさせないと、\nバイスに害が及ぶかもしれない。",
  ui_story_1012_10120101_41_dialog_content = "わかってる。",
  ui_story_1012_10120101_42_dialog_content = "サブブレーン、「ハーモナイザー」にはどんな副作用があるの？",
  ui_story_1012_10120101_43_dialog_content = "バイスに何か悪影響を及ぼす可能性はある？",
  ui_story_1012_10120101_44_dialog_content = "サブブレーンと該当エリアのリンクが切断されているため、\nデータを読み込めません。",
  ui_story_1012_10120101_45_dialog_content = "切断されたままで、\n直そうとはしないの？",
  ui_story_1012_10120101_46_dialog_content = "サブブレーンは空の末裔を\nサポートするためのシステムです。",
  ui_story_1012_10120101_47_dialog_content = "修理はサブブレーンの行うべきタスクではありません。\n実行を強制しないでください。",
  ui_story_1012_10120101_48_dialog_content = "役に立つ情報はなさそうね…",
  ui_story_1012_10120101_49_dialog_content = "仕方ない…",
  ui_story_1012_10120101_50_dialog_content = "多少の危険があっても、試してみるしかないよ。",
  ui_story_1012_10120101_51_dialog_content = "バイスは僕のせいでこうなってしまったんだ…",
  ui_story_1012_10120101_52_dialog_content = "この責任は僕がとるよ。たとえ…",
  ui_story_1012_10120101_53_dialog_content = "…",
  ui_story_1012_10120101_54_dialog_content = "僕が先にその装置を使ってみるよ。",
  ui_story_1012_10120101_55_dialog_content = "僕が大丈夫だったら、\nそれを使ってバイスを助けよう。",
  ui_story_1012_10120101_56_dialog_content = "大丈夫じゃなかったら、その時は…カレン、お願いだよ。\nバイスを啓光に連れて帰って、助けてもらって。",
  ui_story_1012_10120101_57_dialog_content = "心意気は認めるけれど、ハーモナイザーは光霊に使うもの…\nあなたは空の末裔であって、光霊ではないわ。",
  ui_story_1012_10120101_58_dialog_content = "バイスは私の友達でもあるの。\n助けるためなら私も全力を尽くす…",
  ui_story_1012_10120101_59_dialog_content = "やむを得ない事態になったら、\n私が実験体になるわ。",
  ui_story_1012_10120101_60_dialog_content = "サブブレーンにその装置の場所へ\n連れて行ってもらいましょう。",
  ui_story_1012_10120101_61_dialog_content = "ルートを計算しています――",
  ui_story_1012_10120101_62_dialog_content = "通路の大部分が崩落していることを検知しました。\n追放区から迂回する必要があります。",
  ui_story_1012_10120101_63_dialog_content = "該当エリアとサブブレーンのリンクが切断されているため、\nリンク経由でゲートを開放することはできません。",
  ui_story_1012_10120101_64_dialog_content = "最新の設定にしたがい、ドアロックを解錠する\n管理者用の秘密鍵が生成されました。",
  ui_story_1012_10120101_65_dialog_content = "システムの最終変更者は…フランシス、です。",
  ui_story_1012_10120101_66_dialog_content = "またフランシス先生？",
  ui_story_1012_10120101_67_dialog_content = "その人、一体何を企んでいたのかしら…？",
  ui_story_1012_10120101_68_dialog_content = "何となくだけど、企んでいたというより…",
  ui_story_1012_10120101_69_dialog_content = "後から来る誰かのために、\nお膳立てをしてたんだと思う。",
  ui_story_1012_10120101_70_dialog_content = "たとえば…僕たちとかね。",
  ui_story_1012_10120101_71_dialog_content = "管理者はサブブレーンの案内に従ってください。\nサブブレーンがドアロックシステムを解錠します。",
  ui_story_1012_10120101_72_dialog_content = "…追放区の隣にあるの…？",
  ui_story_1012_10120101_73_dialog_content = "イヤな感じしかしない…",
  ui_story_1012_10120101_74_dialog_content = "どうであれ、そこが私たちの唯一の希望よ。",
  ui_story_1012_10120101_75_dialog_content = "行きましょう。バイスを連れていくのよ。",
  ui_story_1012_10120101_76_dialog_content = "サブブレーン、案内をお願い。",
  ui_story_1012_10120101_77_dialog_content = "承知しました。\nサブブレーンの後に続いてください。",
  ui_story_1012_10120101_78_dialog_content = "「ハーモナイザー」…？",
  ui_story_1012_10120101_79_dialog_content = "それがここに隠されている技術？",
  ui_story_1012_10120101_80_dialog_content = "光霊の体を改造できる…",
  ui_story_1012_10120101_81_dialog_content = "まさに、私が求めていたものだわ。",
  ui_story_1012_10120101_82_dialog_content = "『ノラ様、啓光の奴がしつこく追ってきます…』",
  ui_story_1012_10120101_83_dialog_content = "『我々では食い止められません。強すぎます…』",
  ui_story_1012_10120101_84_dialog_content = "啓光の連中はどいつもこいつもおかしいわね。",
  ui_story_1012_10120101_85_dialog_content = "止められないのなら、\n違う道に誘導しなさい。",
  ui_story_1012_10120101_86_dialog_content = "あんな野蛮人を\n貴重な科学技術の結晶に近づけさせないで。",
  ui_story_1012_10120101_87_dialog_content = "頭の中に戦いと破壊しかない奴は、\nこれだから…",
  ui_story_1012_10120101_88_dialog_content = "『はっ。』",
  ui_story_1012_10120101_89_dialog_content = "ええい、邪魔立てするな！",
  ui_story_1012_10120101_90_dialog_content = "元老院はダモクレスが起動された理由を知る権利がある！",
  ui_story_1012_10120101_91_dialog_content = "城主様直々のご命令です。\n何人たりとも制御室には立ち入れません。",
  ui_story_1012_10120101_92_dialog_content = "城主の命令はすなわち、白夜城の法。\n貴方もご存知でしょう。",
  ui_story_1012_10120101_93_dialog_content = "たとえ元老院の一員であろうと、\n法を破ってはなりません。",
  ui_story_1012_10120101_94_dialog_content = "元老院の権利も白夜城の法の一部だ！",
  ui_story_1012_10120101_95_dialog_content = "イルンティ裁判長、\n言っておくが、お前は今――",
  ui_story_1012_10120101_96_dialog_content = "…ダモクレスが止まった？",
  ui_story_1012_10120101_97_dialog_content = "（城主様と四大天使たちがうまくやったようですね）",
  ui_story_1012_10120101_98_dialog_content = "ソルラド…",
  ui_story_1012_10120101_99_dialog_content = "教えろ、コントロールルームの中で何が起きた？\nなぜダモクレスが急に起動した？",
  ui_story_1012_10120101_100_dialog_content = "落ち着くがいい、オットー。\nあわてる必要はない。",
  ui_story_1012_10120101_101_dialog_content = "確かにダモクレスは何の前触れもなく起動した。\nしかし、余が止めた。",
  ui_story_1012_10120101_102_dialog_content = "事態はすでに白夜城の管理下にある。",
  ui_story_1012_10120101_103_dialog_content = "勝手に起動したと…？\nそんなバカな…",
  ui_story_1012_10120101_104_dialog_content = "ダモクレスは強力な兵器だが、\n所詮は兵器だ。",
  ui_story_1012_10120101_105_dialog_content = "誰も操縦していないのに、\n勝手に動くなどと言うことがあるか？",
  ui_story_1012_10120101_106_dialog_content = "1つ、お前の見落としを指摘せねばならん。",
  ui_story_1012_10120101_107_dialog_content = "ダモクレスは白夜城の兵器だ。\nしかし…",
  ui_story_1012_10120101_108_dialog_content = "完全に白夜城のものでもない。",
  ui_story_1012_10120101_109_dialog_content = "…",
  ui_story_1012_10120101_110_dialog_content = "つまるところ、あれは我らが見たこともない古代の民の遺産であり、\n我ら白夜城が本来、最も拒絶するべきものなのだ。",
  ui_story_1012_10120101_111_dialog_content = "己の物でない力である以上、\n己の手に負えないものとなる可能性は常にある。",
  ui_story_1012_10120101_112_dialog_content = "…ダモクレスの担当者に総点検させ、\n暴走の理由を調べさせる。",
  ui_story_1012_10120101_113_dialog_content = "明日までには結果を出させる。",
  ui_story_1012_10120101_114_dialog_content = "ご苦労なことだ。",
  ui_story_1012_10120101_115_dialog_content = "当然のことだ。\n白夜城の安全と繁栄こそが最重要だ。",
  ui_story_1012_10120101_116_dialog_content = "…",
  ui_story_1012_10120101_117_dialog_content = "ダモクレス…",
  ui_story_1012_10120101_118_dialog_content = "この方角は…",
  ui_story_1012_10120101_119_dialog_content = "…",
  ui_story_1012_10120101_120_dialog_content = "ラファエル。",
  ui_story_1012_10120101_121_dialog_content = "は…はい！",
  ui_story_1012_10120101_122_dialog_content = "何でしょう、城主様？",
  ui_story_1012_10120101_123_dialog_content = "ベルタに伝えよ。\n騎士の一隊を率いて、天空ノ谷へ急行するように。",
  ui_story_1012_10120101_124_dialog_content = "は、はい…でも、何をしてもらえばいいですか？",
  ui_story_1012_10120101_125_dialog_content = "臨機応変な対処だ。",
  ui_story_1012_10120101_126_dialog_content = "え？",
  ui_story_1012_10120101_127_dialog_content = "行け。",
  ui_story_1012_10120101_128_dialog_content = "は、はい！",
  ui_story_1012_10120101_129_dialog_content = "女王陛下、どうされましたか…？",
  ui_story_1012_10120101_130_dialog_content = "…何でもない。",
  ui_story_1012_10120101_131_dialog_content = "…心配をかけたな。",
  ui_story_1012_10120101_132_dialog_content = "ご報告しなければならないことがあります。\n灯台が…これまでにない強い光を放っております。",
  ui_story_1012_10120101_133_dialog_content = "分かった。",
  ui_story_1012_10120101_134_dialog_content = "この件は私が預かる。心配は無用だ。",
  ui_story_1012_10120101_135_dialog_content = "かしこまりました…",
  ui_story_1012_10120101_136_dialog_content = "陛下、夢の中で空の末裔の名前を\nお呼びになっていたようでした。",
  ui_story_1012_10120101_137_dialog_content = "偶然ということは無いと思いますが…",
  ui_story_1012_10120101_138_dialog_content = "…",
  ui_story_1012_10120101_139_dialog_content = "あの空の末裔がいと高き塔から、\n世界を見下ろしている様を見た。",
  ui_story_1012_10120101_140_dialog_content = "塔の存在は私にも知り得ないものだった…",
  ui_story_1012_10120101_141_dialog_content = "太古の昔に造られ、由来も分からぬもの…",
  ui_story_1012_10120101_142_dialog_content = "しかし、あの塔と北境を守る灯台は、\n相容れない、ということだろう。",
  ui_story_1012_10120101_143_dialog_content = "…敵になったということでしょうか？",
  ui_story_1012_10120101_144_dialog_content = "いや、敵意はまったく感じなかった。",
  ui_story_1012_10120101_145_dialog_content = "以前と変わっておらぬ。\n善良で単純なままだ。",
  ui_story_1012_10120101_146_dialog_content = "だが、あの者がこれまでにない苦境に\n立たされていることを感じた。",
  ui_story_1012_10120101_147_dialog_content = "おそらくは、アストラの命運をも左右するであろう。",
  ui_story_1012_10120101_148_dialog_content = "北境が選ぶ時が来た…",
  ui_story_1012_10120101_149_dialog_content = "馬車の用意を。",
  ui_story_1012_10120101_150_dialog_content = "天空ノ谷へ向かう。\n我らが転機をもたらすのだ。",
  ui_story_1012_10120101_151_dialog_content = "ただちに！",
  ui_story_1012_10120101_152_dialog_content = "陛下、馬車の支度が整いました。",
  ui_story_1012_10120101_153_dialog_content = "出るとしよう。",
  ui_story_1012_10120101_154_dialog_content = "陛下、私もお供いたします…",
  ui_story_1012_10120101_155_dialog_content = "いや、そなたは留まれ。",
  ui_story_1012_10120101_156_dialog_content = "私の留守をそなたに守ってもらいたい。\n暗鬼の動向には目を配っておくように。",
  ui_story_1012_10120101_157_dialog_content = "他ごとについても、\n私の不在を理由に遅らせてはならん。",
  ui_story_1012_10120101_158_dialog_content = "代わりに、ティアラを連れていく。",
  ui_story_1012_10120101_159_dialog_content = "…",
  ui_story_1012_10120101_160_dialog_content = "ティアラ、参上しました。",
  ui_story_1012_10120101_161_dialog_content = "あなたが…",
  ui_story_1012_10120101_162_dialog_content = "…では、陛下のことはお任せするわ。\n北境の希望の火を、必ず守って。",
  ui_story_1012_10120101_163_dialog_content = "ほ、報告ですにゃ！",
  ui_story_1012_10120101_164_dialog_content = "カナン城の各地で異常な音が発生していますにゃ！",
  ui_story_1012_10120101_165_dialog_content = "ガルー室長によれば、\nシェルターの防壁の中にある、古代の装置の警報だそうですにゃ。",
  ui_story_1012_10120101_166_dialog_content = "分かった。カナン城内部の状況は確認を継続せよ。",
  ui_story_1012_10120101_167_dialog_content = "それから、他のシェルターに\n同様の現象が起きていないか確認を。",
  ui_story_1012_10120101_168_dialog_content = "分かりましたにゃあ！",
  ui_story_1012_10120101_169_dialog_content = "大元帥、偵察部隊が\n暗鬼の異常な動きを察知しました…",
  ui_story_1012_10120101_170_dialog_content = "アストラ全体の暗鬼がすべて、\n天空ノ谷に集結しているようです。",
  ui_story_1012_10120101_171_dialog_content = "分かった。\n各シェルターの防衛態勢を維持し、注視を続けるように。",
  ui_story_1012_10120101_172_dialog_content = "承知。",
  ui_story_1012_10120101_173_dialog_content = "暗鬼の集結、天空ノ谷、\nそしてカナン城にある古代の設備の異常…",
  ui_story_1012_10120101_174_dialog_content = "…あの空の末裔が、\nまた面倒ごとに巻き込まれたようだな…",
  ui_story_1012_10120101_175_dialog_content = "フ、よりにもよって、今か…",
  ui_story_1012_10120101_176_dialog_content = "申し上げます。",
  ui_story_1012_10120101_177_dialog_content = "やれやれ…やはり、まだ有ったか。",
  ui_story_1012_10120101_178_dialog_content = "今度は何だ？",
  ui_story_1012_10120101_179_dialog_content = "委員会が受けた報告によると、\n天空ノ谷にある白い塔が…起動した、とのことです。",
  ui_story_1012_10120101_180_dialog_content = "その後、各地にある古代の遺物が\n一斉に異常な反応を示したそうです。",
  ui_story_1012_10120101_181_dialog_content = "ほう？",
  ui_story_1012_10120101_182_dialog_content = "確認している限り、北境の灯台、白夜城のダモクレス、\nR・Wが占有するトラベラーなど…",
  ui_story_1012_10120101_183_dialog_content = "委員会は、カナン城内の異状も\nこれと関係しているのではないかと強く疑っております。",
  ui_story_1012_10120101_184_dialog_content = "灯台に、ダモクレスまで…？",
  ui_story_1012_10120101_185_dialog_content = "PlayerName…一体何を掘り当てた…？",
  ui_story_1012_10120101_186_dialog_content = "大元帥、指示をお願いたします。",
  ui_story_1012_10120101_187_dialog_content = "そうだな…",
  ui_story_1012_10120101_188_dialog_content = "天空ノ谷付近の各小隊に、\n起動した白い塔の付近で集結するよう伝えろ。",
  ui_story_1012_10120101_189_dialog_content = "移動中に暗鬼と遭遇した場合は、\nその場で妨害作戦を展開し、暗鬼の集結を阻止させろ。",
  ui_story_1012_10120101_190_dialog_content = "それから…ただちに精鋭部隊を編成せよ。\n天空ノ谷へ状況の究明に向かう。",
  ui_story_1012_10120101_191_dialog_content = "了解。ただちに――",
  ui_story_1012_10120101_192_dialog_content = "大元帥、はばかりながら…80号シェルターで受けた傷がまだ癒えておりません。\n自ら出撃されるのはいかがなものかと。",
  ui_story_1012_10120101_193_dialog_content = "…",
  ui_story_1012_10120101_194_dialog_content = "アナトリア、命令に変更はない。",
  ui_story_1012_10120101_195_dialog_content = "了解しました。",
  ui_story_1012_10120101_196_dialog_content = "大元帥、まだ委員会の審査中であることをお忘れなく。",
  ui_story_1012_10120101_197_dialog_content = "不用意な行動は大元帥に対する委員会の評価に関わります。",
  ui_story_1012_10120101_198_dialog_content = "紙切れに書かれた私の評価と啓光の安全、\n重要なのはどちらだ？",
  ui_story_1012_10120101_199_dialog_content = "…啓光の安全です。",
  ui_story_1012_10120101_200_dialog_content = "それが分かっているなら、\n自分の仕事をするがいい。",
  ui_story_1012_10120101_201_dialog_content = "私も大元帥としての務めを果たす。",
  ui_story_1012_10120101_202_dialog_content = "報告書には書かせていただきますよ。",
  ui_story_1012_10120101_203_dialog_content = "フン、好きにしろ。",
  ui_story_1012_10120101_204_dialog_content = "決断の是非は啓光の民が評価する。",
  ui_story_1012_10120201_1_dialog_content = "グオオォ――",
  ui_story_1012_10120201_2_dialog_content = "こいつが最後の1匹か？",
  ui_story_1012_10120201_3_dialog_content = "まったく…",
  ui_story_1012_10120201_4_dialog_content = "ザコの分際で道を塞ぎやがって。\nジャマくせぇ…",
  ui_story_1012_10120201_5_dialog_content = "ノラの奴、どこに行きやがった？",
  ui_story_1012_10120201_6_dialog_content = "チッ…急いで探さないと…",
  ui_story_1012_10120201_7_dialog_content = "…ん？この場所、見覚えがあるな？",
  ui_story_1012_10120201_8_dialog_content = "どこもかしこも同じような造りをしやがって…",
  ui_story_1012_10120201_9_dialog_content = "まるで迷宮みたいだな。",
  ui_story_1012_10120201_10_dialog_content = "まさか…あの暗鬼どもに誘い込まれてたってことか？",
  ui_story_1012_10120201_11_dialog_content = "…ノラにハメられたか！",
  ui_story_1012_10120201_12_dialog_content = "チッ、迷宮に閉じこめる気なら、\n壁ごとぶち抜いてやるよ！",
  ui_story_1012_10120201_13_dialog_content = "<color=#e8d9bb>ガキン――！</color>",
  ui_story_1012_10120201_14_dialog_content = "――！",
  ui_story_1012_10120201_15_dialog_content = "スゥ…",
  ui_story_1012_10120201_16_dialog_content = "アイテ！？",
  ui_story_1012_10120201_17_dialog_content = "この壁、どれだけ硬いんだ？\n一体何で作られてやがる！？",
  ui_story_1012_10120201_18_dialog_content = "刀でキズ一つつかねぇどころか、\n俺の手がビリビリしてきやがった…",
  ui_story_1012_10120201_19_dialog_content = "これをシェルターの壁とか戦車の装甲とかに使えりゃ、\n暗鬼どもも簡単にぶちのめせそうだ…",
  ui_story_1012_10120201_20_dialog_content = "…だが、壁を抜く作戦はダメみたいだな。",
  ui_story_1012_10120201_21_dialog_content = "チッ、大人しく通路に従うしかないか…",
  ui_story_1012_10120201_22_dialog_content = "まぁ、ノラがあの暗鬼どもの親玉なら、\n暗鬼が多い場所に行きゃあ、そのうち会えるってこった。",
  ui_story_1012_10120201_23_dialog_content = "ザコ掃除に少し時間がかかるだけだな。",
  ui_story_1012_10120201_24_dialog_content = "<color=#e8d9bb>天空ノ谷・巨像整備基地深部</color>",
  ui_story_1012_10120201_25_dialog_content = "この先の分かれ道、右折です。",
  ui_story_1012_10120201_26_dialog_content = "この塔、やっぱりすごく大きいね…",
  ui_story_1012_10120201_27_dialog_content = "サブブレーンの案内がなければ、\n通路で迷って何日もムダにしちゃうところだったよ。",
  ui_story_1012_10120201_28_dialog_content = "すでに崩落した部分を含めたら、\n天空ノ谷全体に広がっていたのかもしれないわね。",
  ui_story_1012_10120201_29_dialog_content = "ここも、普通の通路というより…",
  ui_story_1012_10120201_30_dialog_content = "幅も高さも、明らかに\n人が通るためだけのものではないはず。",
  ui_story_1012_10120201_31_dialog_content = "ここに来たばかりの時は\n分からなかったけれど、今考えてみれば…",
  ui_story_1012_10120201_32_dialog_content = "巨像が通るためのものだったのかもしれないわね。",
  ui_story_1012_10120201_33_dialog_content = "…",
  ui_story_1012_10120201_34_dialog_content = "そして、あなたたちが世界に――",
  ui_story_1012_10120201_35_dialog_content = "戦争をもたらすのです。",
  ui_story_1012_10120201_36_dialog_content = "でも、ここを通っていく巨像と空の末裔は、\n平和のためどころか…",
  ui_story_1012_10120201_37_dialog_content = "…空の末裔って、一体何なんだろう？",
  ui_story_1012_10120201_38_dialog_content = "PlayerName。",
  ui_story_1012_10120201_39_dialog_content = "あなたは空の末裔である前に、\nあなた自身なのよ。",
  ui_story_1012_10120201_40_dialog_content = "えっ…？",
  ui_story_1012_10120201_41_dialog_content = "今の私たちにとって、あなたはあなた。",
  ui_story_1012_10120201_42_dialog_content = "バイスが地底から助け出した空の末裔。",
  ui_story_1012_10120201_43_dialog_content = "白夜城に協力して、\nスーモアや黒い巨像に立ち向かった仲間。",
  ui_story_1012_10120201_44_dialog_content = "そして、私たちと一緒に数々の冒険をしてきた仲間。",
  ui_story_1012_10120201_45_dialog_content = "あなたがあなたのまま、善良な人である限り、\n空の末裔か光霊かなんてことは、誰も気にしないわ。",
  ui_story_1012_10120201_46_dialog_content = "生まれついた身分は自分で選べないもの。\nそこに罪悪感を抱く必要なんてないの。",
  ui_story_1012_10120201_47_dialog_content = "カレン…",
  ui_story_1012_10120201_48_option_content = "慰めてくれてありがとう",
  ui_story_1012_10120201_49_dialog_content = "でも、この問題はうやむやにしたくないんだ。",
  ui_story_1012_10120201_50_dialog_content = "僕は最後の空の末裔で…",
  ui_story_1012_10120201_51_dialog_content = "天空ノ谷の秘密を明らかにできるのは、\nこの世界で、たぶん僕だけだ。",
  ui_story_1012_10120201_52_dialog_content = "もし、本当に昔、空の末裔が\n世界に戦争を引き起こす機械だったのなら…",
  ui_story_1012_10120201_53_dialog_content = "天空ノ谷にしても空の末裔にしても、\nまたこの世界の脅威になるかもしれない。",
  ui_story_1012_10120201_54_dialog_content = "徹底的に調べて、可能性を完全に取り除くまで、\n安心して眠れないよ。",
  ui_story_1012_10120201_55_dialog_content = "僕は友達を危険にさらすような存在になんて、なりたくない。",
  ui_story_1012_10120201_56_dialog_content = "…",
  ui_story_1012_10120201_57_dialog_content = "無理をすることはないわ。",
  ui_story_1012_10120201_58_dialog_content = "うん…",
  ui_story_1012_10120201_59_dialog_content = "安心して。自分のことはよく分かってる。",
  ui_story_1012_10120201_60_dialog_content = "<size=30>その辺にいる暗鬼にだって\n勝てないぐらいひ弱なんだし…</size>",
  ui_story_1012_10120201_61_dialog_content = "君たちに頼らないといけない時は、\nちゃんとお願いするよ…",
  ui_story_1012_10120201_62_dialog_content = "それがいいわ。",
  ui_story_1012_10120201_63_dialog_content = "<color=#e8d9bb>ガキン――！！！</color>",
  ui_story_1012_10120201_64_dialog_content = "何の音！？",
  ui_story_1012_10120201_65_dialog_content = "まさか、大きな暗鬼が突っ込んできたとか？",
  ui_story_1012_10120201_66_dialog_content = "ここからそう遠くなさそうね。",
  ui_story_1012_10120201_67_dialog_content = "早くここを離れて、前に進みましょう。",
  ui_story_1012_10120201_68_dialog_content = "動けないバイスがいるもの。\n戦いはできる限り避けないと。",
  ui_story_1012_10120201_69_dialog_content = "待って！",
  ui_story_1012_10120201_70_dialog_content = "どうしたの？",
  ui_story_1012_10120201_71_dialog_content = "暗鬼を…感知したみたい！",
  ui_story_1012_10120201_72_dialog_content = "後ろだ！",
  ui_story_1012_10120201_73_dialog_content = "グオオォ――",
  ui_story_1012_10120201_74_dialog_content = "――！",
  ui_story_1012_10120201_75_dialog_content = "一体どこから！？",
  ui_story_1012_10120201_76_dialog_content = "PlayerName、援護を！",
  ui_story_1012_10120201_77_dialog_content = "うん！",
  ui_story_1012_10120202_1_dialog_content = "どうして急にこんなにたくさんの暗鬼が…",
  ui_story_1012_10120202_2_dialog_content = "それに、さっきまでは何も感知できなかったのに…",
  ui_story_1012_10120202_3_dialog_content = "廃墟になってから\nどれだけ経っているのかも分からないし…",
  ui_story_1012_10120202_4_dialog_content = "きっと、数えきれないほどの隠し通路があるのでしょうね。\n元からあったのか、崩落してできたのかは分からないけれど…",
  ui_story_1012_10120202_5_dialog_content = "私たちが知らない隠し通路から出てきたのかもしれないわ。",
  ui_story_1012_10120202_6_dialog_content = "そうだね…",
  ui_story_1012_10120202_7_dialog_content = "地形が複雑すぎるし、僕の感知能力でも、\nすべての暗鬼を感知できるとは限らない…",
  ui_story_1012_10120202_8_dialog_content = "なら、やっぱり先を急ごう。\nここにいるのはよくない！",
  ui_story_1012_10120202_9_dialog_content = "ここには分かれ道もないんだ。\n前後から挟み撃ちにされたら、逃げられなくなるよ。",
  ui_story_1012_10120202_10_dialog_content = "…",
  ui_story_1012_10120202_11_dialog_content = "空の末裔の感知能力…\n確かに、とても面倒ね。",
  ui_story_1012_10120202_12_dialog_content = "ま、暗鬼ならいくらでもいるわ。",
  ui_story_1012_10120202_13_dialog_content = "実験結果っていうのは、\n数えきれないほどの犠牲の上に得られるものよ。",
  ui_story_1012_10120202_14_dialog_content = "…今の物音は？",
  ui_story_1012_10120202_15_dialog_content = "『あの啓光のやからが壁の破壊を試みたようです。』",
  ui_story_1012_10120202_16_dialog_content = "『そのために空の末裔が驚いて感知能力を使い、\n我々の存在を察知されたようです。』",
  ui_story_1012_10120202_17_dialog_content = "『引き続き足止めしなさい。』",
  ui_story_1012_10120202_18_dialog_content = "空の末裔が目標に近づいているの…",
  ui_story_1012_10120202_19_dialog_content = "あんな野蛮人に私の計画を邪魔されるわけにいかない…",
  ui_story_1012_10120202_20_dialog_content = "『死体を積み上げてでも、\nあいつの通る道を塞ぎなさい。』",
  ui_story_1012_10120202_21_dialog_content = "『はっ！』",
  ui_story_1012_10120202_22_dialog_content = "まったく…ザコども、どんどん増えて来やがる！",
  ui_story_1012_10120202_23_dialog_content = "ここで俺を足止めしようってか？\nナメやがって…！",
  ui_story_1012_10120202_24_dialog_content = "どきやがれ――！",
  ui_story_1012_10120202_25_dialog_content = "…暗鬼どもがこっちから来てる。\nってこたぁ…",
  ui_story_1012_10120202_26_dialog_content = "ノラもあっちにいるってことだな。",
  ui_story_1012_10120202_27_dialog_content = "やっと尻尾をつかんだぜ、ノラ…",
  ui_story_1012_10120401_1_dialog_content = "『ノ、ノラ様！』",
  ui_story_1012_10120401_2_dialog_content = "『あの啓光の怪物め、どこから力が出て来るのか…\nとても食い止められません！』",
  ui_story_1012_10120401_3_dialog_content = "『まっすぐこちらに向かっています！』",
  ui_story_1012_10120401_4_dialog_content = "つけあがるにも程があるわね。",
  ui_story_1012_10120401_5_dialog_content = "それとも、バカの理解力に期待した\n私がバカだったのかしら。",
  ui_story_1012_10120401_6_dialog_content = "あんたたちも行きなさい。\nあいつを食い止めるの。",
  ui_story_1012_10120401_7_dialog_content = "『ま、まだ戦うのですか…？』",
  ui_story_1012_10120401_8_dialog_content = "二度も言わせないで。",
  ui_story_1012_10120401_9_dialog_content = "『はい…』",
  ui_story_1012_10120401_10_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1012_10120401_11_dialog_content = "何の音？",
  ui_story_1012_10120401_12_dialog_content = "<color=#e8d9bb>ドドドドド…</color>",
  ui_story_1012_10120401_13_dialog_content = "ノラ――！",
  ui_story_1012_10120401_14_dialog_content = "本当に、バカバカしいほどしつこいわね。",
  ui_story_1012_10120401_15_dialog_content = "あなたのような生物じゃ、\n実験体にも不適格だわ。",
  ui_story_1012_10120401_16_dialog_content = "お前のすることなんて、\nどうせろくでもないことに決まってやがる！",
  ui_story_1012_10120401_17_dialog_content = "そんなに実験がしたけりゃ、\nカナン城の牢獄の中でやるんだな！",
  ui_story_1012_10120401_18_dialog_content = "あいつを止めなさい。",
  ui_story_1012_10120401_19_dialog_content = "グオォォ――！",
  ui_story_1012_10120401_20_dialog_content = "お前のお付きの暗鬼でこの程度か？",
  ui_story_1012_10120401_21_dialog_content = "なら、お前も大したことなさそうだな！",
  ui_story_1012_10120401_22_dialog_content = "レインハトの妹だっていうなら、\nせめてあいつの半分ぐらいは強いんだろうな？",
  ui_story_1012_10120401_23_dialog_content = "…",
  ui_story_1012_10120401_24_dialog_content = "あんな失敗作と比べないでもらえる？",
  ui_story_1012_10120401_25_dialog_content = "ん？怒ったか？",
  ui_story_1012_10120401_26_dialog_content = "いいだろう。かかって来いよ！",
  ui_story_1012_10120401_27_dialog_content = "実験に集中するには…\n本気で黙らせないといけないみたいね。",
  ui_story_1012_10120401_28_dialog_content = "あなた、私を怒らせたわ。",
  ui_story_1012_10120401_29_dialog_content = "望むところだ！",
  ui_story_1012_10120401_30_dialog_content = "やっとここに戻ってきたけど…",
  ui_story_1012_10120401_31_dialog_content = "何度見ても、ここの雰囲気には慣れないよ。",
  ui_story_1012_10120401_32_dialog_content = "私も好きになれないわ。",
  ui_story_1012_10120401_33_dialog_content = "早く、ゲートを探しましょう。",
  ui_story_1012_10120401_34_dialog_content = "ハーモナイザー管理区のゲートに到着しました。",
  ui_story_1012_10120401_35_dialog_content = "ロックシステムの解除を始めます…\n解除中はサブブレーンに他の指令を行うことができなくなります。",
  ui_story_1012_10120401_36_dialog_content = "1%…2%…5%…",
  ui_story_1012_10120401_37_dialog_content = "しばらくかかりそうね。",
  ui_story_1012_10120401_38_dialog_content = "うん、じゃあ僕は…",
  ui_story_1012_10120401_39_dialog_content = "！！",
  ui_story_1012_10120401_40_dialog_content = "どうしたの？",
  ui_story_1012_10120401_41_dialog_content = "ノラの気配だ…塔の中に入ってきてる！",
  ui_story_1012_10120401_42_dialog_content = "<color=#e8d9bb>ドカン！ドン！！</color>",
  ui_story_1012_10120401_43_dialog_content = "何の音！？",
  ui_story_1012_10120401_44_dialog_content = "さっきからずっと続いてる…",
  ui_story_1012_10120401_45_dialog_content = "ノラかしら？",
  ui_story_1012_10120401_46_dialog_content = "まさかノラが、塔の中の暗鬼を操って、\n辺りを破壊してるとか？",
  ui_story_1012_10120401_47_dialog_content = "それとも、この塔のどこかが崩れてるとか？",
  ui_story_1012_10120401_48_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_1012_10120401_49_dialog_content = "うわっ！砂煙が！？",
  ui_story_1012_10120401_50_dialog_content = "気をつけて！\n何かが中から飛び出してきたわ！",
  ui_story_1012_10120401_51_dialog_content = "<color=#e8d9bb>ガキン――！</color>",
  ui_story_1012_10120401_52_dialog_content = "…邪魔よ。",
  ui_story_1012_10120401_53_dialog_content = "よそ見してんじゃねぇ、ノラ――！",
  ui_story_1012_10120401_54_dialog_content = "てめぇの相手はこの俺だ！",
  ui_story_1012_10120401_55_dialog_content = "バートン！？",
  ui_story_1012_10120401_56_dialog_content = "よう、PlayerName！\nお前もいたのか！",
  ui_story_1012_10120401_57_dialog_content = "バイスはどうしたんだ？\n気絶してんのか？",
  ui_story_1012_10120401_58_dialog_content = "バイスは…ケガをしてるんだ！\nこのゲートを開けて、どうにか助けようとしてるところだよ！",
  ui_story_1012_10120401_59_dialog_content = "バートン、ノラを食い止めて！",
  ui_story_1012_10120401_60_dialog_content = "時間を稼ぐだけでいいのか？\n任せとけ！",
  ui_story_1012_10120401_61_dialog_content = "俺の後ろのザコどもは任せる！",
  ui_story_1012_10120401_62_dialog_content = "威勢がいいわね。",
  ui_story_1012_10120401_63_dialog_content = "でも、あきらめた方が身のためよ。",
  ui_story_1012_10120401_64_dialog_content = "力の差ははっきりと分かっているでしょう。",
  ui_story_1012_10120401_65_dialog_content = "私は時間をムダにしたくないし、\nあなたたちも命を失いたくはないでしょう。",
  ui_story_1012_10120401_66_dialog_content = "その機械の権限を渡して、\nさっさと失せなさい。",
  ui_story_1012_10120401_67_dialog_content = "命だけは助けてあげるわ。",
  ui_story_1012_10120401_68_dialog_content = "寝ボケてんのか？\n自分のツラでも殴ってみたらどうだ！",
  ui_story_1012_10120401_69_dialog_content = "…で、あなたはどうするの？空の末裔。",
  ui_story_1012_10120401_70_dialog_content = "野蛮人と同じで悪あがきをするつもり？",
  ui_story_1012_10120401_71_dialog_content = "…",
  ui_story_1012_10120401_72_option_content = "お前の言うことなんて信じない！",
  ui_story_1012_10120401_73_dialog_content = "へえ？",
  ui_story_1012_10120401_74_dialog_content = "今まで、あまりに多くの人をだましてきてる…",
  ui_story_1012_10120401_75_dialog_content = "グスド、スイェート、スーモア…",
  ui_story_1012_10120401_76_dialog_content = "他人の命なんて気にも留めず、\n自分のことだけ考えてる！",
  ui_story_1012_10120401_77_dialog_content = "信用なんてできっこない！",
  ui_story_1012_10120401_78_dialog_content = "…",
  ui_story_1012_10120401_79_dialog_content = "私のガマンにも限度があるわ…",
  ui_story_1012_10120401_80_dialog_content = "権限を渡しなさい。\nそうすれば楽に死なせてあげる。",
  ui_story_1012_10120401_81_dialog_content = "絶対に…渡さない！",
  ui_story_1012_10120401_82_dialog_content = "むなしい抵抗ね。",
  ui_story_1012_10120401_83_dialog_content = "それなら…",
  ui_story_1012_10120401_84_dialog_content = "さよなら。",
  ui_story_1012_10120402_1_dialog_content = "PlayerName、危ない！",
  ui_story_1012_10120402_2_dialog_content = "うわぁ――！",
  ui_story_1012_10120402_3_dialog_content = "――！",
  ui_story_1012_10120402_4_dialog_content = "ぐはっ！！！",
  ui_story_1012_10120402_5_dialog_content = "戦ってる時はよそ見をしない…",
  ui_story_1012_10120402_6_dialog_content = "自分で言ったことよね？",
  ui_story_1012_10120402_7_dialog_content = "バートン！",
  ui_story_1012_10120402_8_dialog_content = "チッ…",
  ui_story_1012_10120402_9_dialog_content = "その程度か？\nメシでも抜いてきてんのか？",
  ui_story_1012_10120402_10_dialog_content = "塔の外からここまで、休まず戦い続けて…",
  ui_story_1012_10120402_11_dialog_content = "あなたこそ、そろそろ限界でしょう。",
  ui_story_1012_10120402_12_dialog_content = "…",
  ui_story_1012_10120402_13_dialog_content = "悪あがきはやめなさい。",
  ui_story_1012_10120402_14_dialog_content = "ケッ、しゃらくせぇ！",
  ui_story_1012_10120402_15_dialog_content = "まだだ――！",
  ui_story_1012_10120402_16_dialog_content = "あなたが戦いに費やしてきた時間の半分でも勉強に使っていれば、\nみじめなことにはならなかったでしょうに。",
  ui_story_1012_10120402_17_dialog_content = "勉強だぁ？",
  ui_story_1012_10120402_18_dialog_content = "世の中にはなぁ…てめぇみたいに\n顔を見ただけで殴りたくなる奴がいるんだ！",
  ui_story_1012_10120402_19_dialog_content = "勉強なんかしてられっかよ！",
  ui_story_1012_10120402_20_dialog_content = "愚かさのツケを払うことになるわよ。",
  ui_story_1012_10120402_21_dialog_content = "ぐっ！？",
  ui_story_1012_10120402_22_dialog_content = "右腕の関節を砕いたわ。",
  ui_story_1012_10120402_23_dialog_content = "その身体でどうやって剣を持つのかしらね？",
  ui_story_1012_10120402_24_dialog_content = "それとも…",
  ui_story_1012_10120402_25_dialog_content = "命乞いでもする？",
  ui_story_1012_10120402_26_dialog_content = "やめるんだ、ノラ！",
  ui_story_1012_10120402_27_dialog_content = "うるさいわ。",
  ui_story_1012_10120402_28_dialog_content = "あなたに発言権なんてないの。\n軟弱で無能な空の末裔。",
  ui_story_1012_10120402_29_dialog_content = "啓光の軍人は…",
  ui_story_1012_10120402_30_dialog_content = "へえ…？",
  ui_story_1012_10120402_31_dialog_content = "啓光の軍人は…絶対にてめぇみたいな奴に屈しない！",
  ui_story_1012_10120402_32_dialog_content = "！！！",
  ui_story_1012_10120402_33_dialog_content = "腕が一本あれば、\nお前の相手には十分だ！",
  ui_story_1012_10120402_34_dialog_content = "バートン、足が！",
  ui_story_1012_10120402_35_dialog_content = "カレン、手を貸してあげて！",
  ui_story_1012_10120402_36_dialog_content = "散れ！氷花よ！",
  ui_story_1012_10120402_37_dialog_content = "…無理ね…暗鬼が多すぎる！",
  ui_story_1012_10120402_38_dialog_content = "俺に構うな！",
  ui_story_1012_10120402_39_dialog_content = "お前らはゲートのことだけを考えろ！\nノラは俺が倒す！",
  ui_story_1012_10120402_40_dialog_content = "でも、バートン！\nもう――",
  ui_story_1012_10120402_41_dialog_content = "！！！",
  ui_story_1012_10120402_42_dialog_content = "早く行け！",
  ui_story_1012_10120402_43_dialog_content = "でも！",
  ui_story_1012_10120402_44_dialog_content = "退路を探せ！",
  ui_story_1012_10120402_45_dialog_content = "俺が間に合わなかったら、墓に書いておけ！",
  ui_story_1012_10120402_46_dialog_content = "「栄えある啓光の軍人は、\n最期の瞬間まで暗鬼と戦い続けた」ってな！",
  ui_story_1012_10120402_47_dialog_content = "PlayerName、撤退するにも場所がないわ！",
  ui_story_1012_10120402_48_dialog_content = "ここに閉じこめられたままでは、助からない！",
  ui_story_1012_10120402_49_dialog_content = "…！",
  ui_story_1012_10120402_50_dialog_content = "サブブレーン、解錠まであとどれくらい！？",
  ui_story_1012_10120402_51_dialog_content = "現在の解錠進行度は96%です。しばらくお待ちください。",
  ui_story_1012_10120402_52_dialog_content = "…もう少しだ、持ちこたえて！",
  ui_story_1012_10120402_53_dialog_content = "97%",
  ui_story_1012_10120402_54_dialog_content = "98%",
  ui_story_1012_10120402_55_dialog_content = "99%",
  ui_story_1012_10120402_56_dialog_content = "100%、解錠完了…",
  ui_story_1012_10120402_57_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1012_10120402_58_dialog_content = "ゲートが…開いた！",
  ui_story_1012_10120402_59_dialog_content = "カレン、バートン、撤退だ！",
  ui_story_1012_10120501_1_dialog_content = "氷花よ！",
  ui_story_1012_10120501_2_dialog_content = "急いで。すぐにノラが追ってくる。\n長くは足止めできないわよ！",
  ui_story_1012_10120501_3_dialog_content = "こっちよ！\nバートン、PlayerNameを守って！",
  ui_story_1012_10120501_4_dialog_content = "安心しな！こんなザマだが、指一本触れさせねぇよ！",
  ui_story_1012_10120501_5_dialog_content = "サブブレーン、あとどれくらい？",
  ui_story_1012_10120501_6_dialog_content = "直進してください。200メートル先が目的地です。",
  ui_story_1012_10120501_7_dialog_content = "ふぅ…ふぅ…あと少しだ！",
  ui_story_1012_10120501_8_dialog_content = "前方に別のゲートが見えたわ！",
  ui_story_1012_10120501_9_dialog_content = "僕、もう、ダメ――",
  ui_story_1012_10120501_10_dialog_content = "ここの通路、移動するだけで\nなんでこんなに面倒なの！？",
  ui_story_1012_10120501_11_dialog_content = "サブブレーンの推測では、地形が変化したことにより、\n通路の状態も変化していると思われます。",
  ui_story_1012_10120501_12_dialog_content = "サブブレーンが算出したルートは正確です。\nご安心下さい。",
  ui_story_1012_10120501_13_dialog_content = "引き続き、前進してください。",
  ui_story_1012_10120501_14_dialog_content = "僕は…諦めない！！！",
  ui_story_1012_10120501_15_dialog_content = "PlayerName、止まっちゃダメ！",
  ui_story_1012_10120501_16_dialog_content = "走り続けろ！",
  ui_story_1012_10120501_17_dialog_content = "ここで立ち止まってみろ！\n戻ったらカナン城を100周させるからな！",
  ui_story_1012_10120501_18_dialog_content = "励ましてるにしてもひどくない！？",
  ui_story_1012_10120501_19_dialog_content = "あっ――！",
  ui_story_1012_10120501_20_dialog_content = "サブブレーン！",
  ui_story_1012_10120501_21_dialog_content = "「サブブレーン」がサポートいたします…",
  ui_story_1012_10120501_22_dialog_content = "僕たちがゲートに入ったら、すぐに閉めて――！",
  ui_story_1012_10120501_23_dialog_content = "暗鬼たちを入れないようにして！",
  ui_story_1012_10120501_24_dialog_content = "了解しました。",
  ui_story_1012_10120501_25_dialog_content = "管理者は足下の装置に注意してください。",
  ui_story_1012_10120501_26_option_content = "装置？",
  ui_story_1012_10120501_27_dialog_content = "なんでそんなものがあるの！？",
  ui_story_1012_10120501_28_option_content = "装置ってなんの！？",
  ui_story_1012_10120501_29_dialog_content = "どういう装置！？",
  ui_story_1012_10120501_30_dialog_content = "ハーモナイザー管理区域の\n独立した防衛装置です。",
  ui_story_1012_10120501_31_dialog_content = "該当区域とサブブレーンの接続が切断されているため、\nサブブレーンは装置を制御できません。",
  ui_story_1012_10120501_32_dialog_content = "現在、これらの装置は\n無差別攻撃を行うものと推測されます。",
  ui_story_1012_10120501_33_dialog_content = "管理者は適当に…\n訂正、ご自分の力で回避してください。",
  ui_story_1012_10120501_34_dialog_content = "そういうことは早く言ってよ！！！",
  ui_story_1012_10120501_35_dialog_content = "この区域に防衛装置が存在することは、\n教科書に記載されています。",
  ui_story_1012_10120501_36_dialog_content = "お忘れのようであれば、\n学校への再入学を推奨します。",
  ui_story_1012_10120501_37_dialog_content = "PlayerName、足下に気を付けて！",
  ui_story_1012_10120501_38_dialog_content = "えっ？",
  ui_story_1012_10120501_39_dialog_content = "<color=#e8d9bb>ガタン――</color>",
  ui_story_1012_10120501_40_dialog_content = "PlayerName、避けて！",
  ui_story_1012_10120501_41_dialog_content = "うっ…！！！",
  ui_story_1012_10120501_42_dialog_content = "…",
  ui_story_1012_10120501_43_dialog_content = "管理者はご自分の力で回避してください！",
  ui_story_1012_10120501_44_dialog_content = "こいつ、戦えるのか？",
  ui_story_1012_10120501_45_dialog_content = "戦えるなら外に放り投げちまえ。\n少しはノラの足止めができるだろ！",
  ui_story_1012_10120501_46_dialog_content = "サブブレーンは投影されたイメージです。\n戦闘能力はありません。",
  ui_story_1012_10120501_47_dialog_content = "サブブレーンに本来のタスクではない\n戦闘を行わせないでください。",
  ui_story_1012_10120501_48_dialog_content = "それなら、\n装置の位置を教えなさい！",
  ui_story_1012_10120501_49_dialog_content = "防衛装置に関するデータを検索中――",
  ui_story_1012_10120501_50_dialog_content = "検索完了…",
  ui_story_1012_10120501_51_dialog_content = "この先、右側に避けてください。",
  ui_story_1012_10120501_52_dialog_content = "まずいわね。暗鬼に追いつかれるわ！",
  ui_story_1012_10120501_53_dialog_content = "装置を利用して、倒すのよ！",
  ui_story_1012_10120502_1_dialog_content = "まもなく目的地に到着します…",
  ui_story_1012_10120502_2_dialog_content = "ゲートの封鎖を開始…",
  ui_story_1012_10120502_3_dialog_content = "ゲートが封鎖される前に\nエリア内へ進入してください。",
  ui_story_1012_10120502_4_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1012_10120502_5_dialog_content = "待って！早すぎない！？",
  ui_story_1012_10120502_6_dialog_content = "間に合わないよ！",
  ui_story_1012_10120502_7_dialog_content = "ここであいつらを足止めしなさい。\n中の装置を破壊されるわけにはいかないの。",
  ui_story_1012_10120502_8_dialog_content = "PlayerName、方法を考えて！",
  ui_story_1012_10120502_9_dialog_content = "暗鬼の群れと距離を離さないと！",
  ui_story_1012_10120502_10_dialog_content = "方法…！？どうすれば…",
  ui_story_1012_10120502_11_dialog_content = "前方に爆発トラップがあります。\n回避してください。",
  ui_story_1012_10120502_12_dialog_content = "爆発トラップ？",
  ui_story_1012_10120502_13_dialog_content = "そいつだ！そいつを踏むぞ！",
  ui_story_1012_10120502_14_dialog_content = "えっ！？",
  ui_story_1012_10120502_15_dialog_content = "俺を信じろ！とにかく踏め！",
  ui_story_1012_10120502_16_dialog_content = "逃がさないわよ。",
  ui_story_1012_10120502_17_dialog_content = "信じるのは今回だけだよ！！！",
  ui_story_1012_10120502_18_dialog_content = "<color=#e8d9bb>カチ…</color>",
  ui_story_1012_10120502_19_dialog_content = "つかまれ！！！",
  ui_story_1012_10120502_20_dialog_content = "<color=#e8d9bb>バン！バン！</color>",
  ui_story_1012_10120502_21_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_1012_10120502_22_dialog_content = "！！",
  ui_story_1012_10120502_23_dialog_content = "うわっ！飛ばされる――！",
  ui_story_1012_10120502_24_dialog_content = "<color=#e8d9bb>ゴゴゴゴ…ズン！</color>",
  ui_story_1012_10120502_25_dialog_content = "…さすがは啓光の化け物と言うべきかしらね。",
  ui_story_1012_10120502_26_dialog_content = "命知らずなことばかり…",
  ui_story_1012_10120502_27_dialog_content = "『ゲートを突き破りなさい。』",
  ui_story_1012_10120502_28_dialog_content = "『はっ！』",
  ui_story_1012_10120502_29_dialog_content = "…うまくいったの？",
  ui_story_1012_10120502_30_dialog_content = "少なくとも、生きてはいるようね…",
  ui_story_1012_10120502_31_dialog_content = "バイスも大事無いわ。",
  ui_story_1012_10120502_32_dialog_content = "よかった…待って、バートンは！？",
  ui_story_1012_10120502_33_dialog_content = "俺は…大丈夫だ…",
  ui_story_1012_10120502_34_dialog_content = "ぜぇ…はぁ…しっかし…空の末裔の爆弾、\nとんでもない威力だったな。",
  ui_story_1012_10120502_35_dialog_content = "少し早めに爆発させてなかったら、\n俺たち全員オダブツだったぜ…",
  ui_story_1012_10120502_36_dialog_content = "バートン！？\nどう見ても大丈夫じゃないよね！？",
  ui_story_1012_10120502_37_dialog_content = "心配すんな…ゲホッ、ゴホッ…",
  ui_story_1012_10120502_38_dialog_content = "啓光のヤツらは、これぐらい誰でも経験してるさ…\n包帯を巻いて一晩寝れば、どうってことねぇよ…",
  ui_story_1012_10120502_39_dialog_content = "かすり傷ぐらいで衛生兵のところに行ったら、\nエリをつかまれて医務室から蹴り出されちまうんだぜ。",
  ui_story_1012_10120502_40_dialog_content = "俺のことはいい…\nお前たちが探してたもの、これだろ？",
  ui_story_1012_10120502_41_dialog_content = "サブブレーン、これが「ハーモナイザー」？",
  ui_story_1012_10120502_42_dialog_content = "サブブレーンはそう推測します。",
  ui_story_1012_10120502_43_dialog_content = "君の推測ってアテにしていいのかな…",
  ui_story_1012_10120502_44_dialog_content = "この装置に関する記録はある？",
  ui_story_1012_10120502_45_dialog_content = "「ハーモナイザー」は\n専用の管理区域に配置されている、主要装置です。",
  ui_story_1012_10120502_46_dialog_content = "管理者の目の前にある装置が\n「ハーモナイザー」だと推定されます。",
  ui_story_1012_10120502_47_dialog_content = "<color=#e8d9bb>ドン――！</color>",
  ui_story_1012_10120502_48_dialog_content = "暗鬼がゲートを突き破ろうとしているようね…",
  ui_story_1012_10120502_49_dialog_content = "とりあえずは心配いらねぇだろうよ。",
  ui_story_1012_10120502_50_dialog_content = "ここのゲートも壁も、とんでもなく頑丈だ。\n俺もずいぶん試したが、破れなかった。",
  ui_story_1012_10120502_51_dialog_content = "<color=#e8d9bb>ドン――！</color>",
  ui_story_1012_10120502_52_dialog_content = "…ゲート、変形してない！？",
  ui_story_1012_10120502_53_dialog_content = "サブブレーン、ゲートを補強する方法はない？",
  ui_story_1012_10120502_54_dialog_content = "ロックシステム強化機能を起動しています…",
  ui_story_1012_10120502_55_dialog_content = "<color=#e8d9bb>ガチャン…ガチャン…</color>",
  ui_story_1012_10120502_56_dialog_content = "ずいぶんたくさんシャッターがあるのね…",
  ui_story_1012_10120502_57_dialog_content = "もうしばらくは持ちこたえられそうね。",
  ui_story_1012_10120502_58_dialog_content = "<color=#e8d9bb>ドンッ…ドンッ…</color>",
  ui_story_1012_10120502_59_dialog_content = "攻撃が止まった？",
  ui_story_1012_10120502_60_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_1012_10120502_61_dialog_content = "さっきよりも強くなってる！？",
  ui_story_1012_10120502_62_dialog_content = "暗鬼って、頭が痛くならないの！？",
  ui_story_1012_10120502_63_dialog_content = "チッ、ノラのヤツ…俺のことをしつこいって言ってたくせに、\nお互い様じゃねぇか！",
  ui_story_1012_10120502_64_dialog_content = "壁にぶつかったならあきらめろよ！！",
  ui_story_1012_10120502_65_dialog_content = "このままでは、遠からず破られるでしょうね。",
  ui_story_1012_10120502_66_dialog_content = "PlayerName、早く「ハーモナイザー」を起動して、\nバイスを治療しないと。",
  ui_story_1012_10120502_67_dialog_content = "バイスが回復すれば、\nまだ包囲を破れる望みはあるかもしれないわ。",
  ui_story_1012_10120502_68_dialog_content = "サブブレーン、「ハーモナイザー」を起動して！",
  ui_story_1012_10120502_69_dialog_content = "「ハーモナイザー」を起動します…",
  ui_story_1012_10120502_70_dialog_content = "それから、実験記録を調べて、\n「ハーモナイザー」の効果と副作用を確認して！",
  ui_story_1012_10120502_71_dialog_content = "検索中…エラー。",
  ui_story_1012_10120502_72_dialog_content = "検索結果がありません。",
  ui_story_1012_10120502_73_dialog_content = "え！？なんで！？",
  ui_story_1012_10120502_74_dialog_content = "実験記録は全部ここに保存されてるって、\n言ってなかった？",
  ui_story_1012_10120502_75_dialog_content = "どうしてデータが無いの！？",
  ui_story_1012_10120502_76_dialog_content = "サブブレーンと本エリアとの接続は切断されて長時間が経っているため、\n最新の状態は確認できていませんでした。",
  ui_story_1012_10120502_77_dialog_content = "現在、記録が削除されていることを検出しました。",
  ui_story_1012_10120502_78_dialog_content = "データは削除されて長期間が経っているため、\n復元できません。",
  ui_story_1012_10120502_79_dialog_content = "そんな…",
  ui_story_1012_10120502_80_dialog_content = "なんだぁ？ロクに結果も分からない\nシロモノをバイスに使おうとしてたのか？",
  ui_story_1012_10120502_81_dialog_content = "いや、だから先に実験記録を探そうと思ったんだけど、\n実験記録が消されてるみたいで…",
  ui_story_1012_10120502_82_dialog_content = "バートン、カレン、\n悪いけどもう少し持ちこたえて。",
  ui_story_1012_10120502_83_dialog_content = "僕が「ハーモナイザー」の効果を確かめてくる！",
  ui_story_1012_10120502_84_dialog_content = "待ちなさい。あなたは光霊じゃないと言ったでしょう。\nどんな結果になるのか、さらに想像がつかないわ。",
  ui_story_1012_10120502_85_dialog_content = "だけど、バイスで確かめるわけには行かないよ！",
  ui_story_1012_10120502_86_dialog_content = "ノラはすぐに突入してくる。\n君たちならまだ戦えるけど…",
  ui_story_1012_10120502_87_dialog_content = "光力術を使うこと自体ができない僕なんて、\n実験体になった方がまだ役に立つ！",
  ui_story_1012_10120502_88_dialog_content = "待て！",
  ui_story_1012_10120502_89_dialog_content = "止めないで！",
  ui_story_1012_10120502_90_dialog_content = "落ち着け！",
  ui_story_1012_10120502_91_dialog_content = "そのナントカ、\n何の役に立つのか分かってんのか？",
  ui_story_1012_10120502_92_dialog_content = "「ハーモナイザー」は傷の治療のほか、\n光霊の肉体の一部を改造することで、潜在能力を解放することができます。",
  ui_story_1012_10120502_93_dialog_content = "傷の治療ができる…そうなんだな？",
  ui_story_1012_10120502_94_dialog_content = "それなら俺がやる！",
  ui_story_1012_10120502_95_dialog_content = "でも、副作用とか、成功率とか、\n何も分からないんだよ！？死ぬかもしれない！",
  ui_story_1012_10120502_96_dialog_content = "だったらなおさら俺がやる！",
  ui_story_1012_10120502_97_dialog_content = "実験体が必要なんだろ？",
  ui_story_1012_10120502_98_dialog_content = "俺は見ての通り、もう傷だらけだ。ノラとまともにやりあったって、\nせいぜい1、2回しのげるぐらいだ。",
  ui_story_1012_10120502_99_dialog_content = "お前がカレンと協力すれば、\n少しくらいは持ちこたえられるはずだ。",
  ui_story_1012_10120502_100_dialog_content = "だから、俺がやる。",
  ui_story_1012_10120502_101_dialog_content = "それで俺が治ったら、\nノラにでっけぇサプライズプレゼントをしてやるぜ！",
  ui_story_1012_10120502_102_dialog_content = "その後は、お前も安心して\nバイスにこれを使えるだろ。",
  ui_story_1012_10120502_103_dialog_content = "…分かった。",
  ui_story_1012_10120502_104_dialog_content = "じゃ、お前たちに任せたぞ。",
  ui_story_1012_10120502_105_dialog_content = "暗鬼どもを外で足止めしておいてくれ！",
  ui_story_1012_10120502_106_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_1012_10120502_107_dialog_content = "グォオオ――",
  ui_story_1012_10120502_108_dialog_content = "シェルターに使われている素材より、丈夫で軽い…",
  ui_story_1012_10120502_109_dialog_content = "この塔の壁やゲートの素材、巨像と似ているわね。",
  ui_story_1012_10120502_110_dialog_content = "巨像と空の末裔、それから暗鬼…",
  ui_story_1012_10120502_111_dialog_content = "この秘密…もしかすると\n日蝕ですら知らないものかも…",
  ui_story_1012_10120502_112_dialog_content = "…本当に楽しみね。",
  ui_story_1012_10120502_113_dialog_content = "『ノラ様、フィジェロ様から言づてを預かっております。』",
  ui_story_1012_10120502_114_dialog_content = "『すでに塔の外に大群が集結している。』",
  ui_story_1012_10120502_115_dialog_content = "『しかし、塔の変化が\n啓光、白夜城、北境の気を引いたようだ。』",
  ui_story_1012_10120502_116_dialog_content = "『やつらの援軍が各地からやって来ている。』",
  ui_story_1012_10120502_117_dialog_content = "『レインハトとベツレヘムもいるようだ。』",
  ui_story_1012_10120502_118_dialog_content = "いつも閉じこもっているくせに、\nこういう時だけお出ましになるってわけね。",
  ui_story_1012_10120502_119_dialog_content = "鼻が利くこと…",
  ui_story_1012_10120502_120_dialog_content = "フィジェロに足止めするよう伝えて。",
  ui_story_1012_10120502_121_dialog_content = "まだ時間がかかるわ。",
  ui_story_1012_10120502_122_dialog_content = "『それと、フィジェロ様から\n忠告するように言われております…』",
  ui_story_1012_10120502_123_dialog_content = "『余計なことは考えるな、と。』",
  ui_story_1012_10120502_124_dialog_content = "本気で手伝う気があるなら、\n何度も私の邪魔をしないでほしいわね。",
  ui_story_1012_10120502_125_dialog_content = "…",
  ui_story_1012_10120502_126_dialog_content = "『…と、ノラ様はおっしゃっていました…』",
  ui_story_1012_10120502_127_dialog_content = "『ノラめ…少し思い知らせてやる必要があるようだな。』",
  ui_story_1012_10120502_128_dialog_content = "『だが、今はその時ではない。』",
  ui_story_1012_10120502_129_dialog_content = "『啓光、白夜城…北境までもが動くとは…』",
  ui_story_1012_10120502_130_dialog_content = "『フィジェロ様、奴らを足止めしますか？』",
  ui_story_1012_10120502_131_dialog_content = "『ヒマつぶしがしたいなら、行って構わん。』",
  ui_story_1012_10120502_132_dialog_content = "『命がけで戦う必要はない。\n多少は中に通しても問題ない。』",
  ui_story_1012_10120502_133_dialog_content = "『ノラも少しは圧力をかけられた方が、\n本領を発揮するだろう。』",
  ui_story_1012_10120502_134_dialog_content = "『承知しました、フィジェロ様。』",
  ui_story_1012_10120601_1_dialog_content = "<color=#e8d9bb>警告：「ハーモナイザー」運転中…同調プロセスを中断しないでください…</color>",
  ui_story_1012_10120601_2_dialog_content = "<color=#e8d9bb>ドクン…ドクン…ゴゴゴ…</color>",
  ui_story_1012_10120601_3_dialog_content = "これは…何の音…？",
  ui_story_1012_10120601_4_dialog_content = "四方八方から聞こえてくるようね。\n不快だわ…",
  ui_story_1012_10120601_5_dialog_content = "不快と言うより…不気味な感じがするね。",
  ui_story_1012_10120601_6_dialog_content = "この音はまるで…",
  ui_story_1012_10120601_7_option_content = "地震？",
  ui_story_1012_10120601_8_dialog_content = "回帰の塔が上昇した時にも\n引けを取らないほどの揺れだね。",
  ui_story_1012_10120601_9_dialog_content = "エリア全体の壁が振動してる…",
  ui_story_1012_10120601_10_dialog_content = "今にも崩れ落ちてきそうな雰囲気だ。",
  ui_story_1012_10120601_11_option_content = "心臓の音だ",
  ui_story_1012_10120601_12_dialog_content = "安定したリズムみたいに聞こえる…",
  ui_story_1012_10120601_13_dialog_content = "でも、恐ろしいエネルギーを感じるよ…",
  ui_story_1012_10120601_14_dialog_content = "まるで大きな心臓の中にいるみたいだ。",
  ui_story_1012_10120601_15_dialog_content = "これが「ハーモナイザー」の力…？",
  ui_story_1012_10120601_16_dialog_content = "そうね。確かに不安になるわ。",
  ui_story_1012_10120601_17_dialog_content = "いつまで続くのかな…",
  ui_story_1012_10120601_18_dialog_content = "バートンは…",
  ui_story_1012_10120601_19_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_1012_10120601_20_dialog_content = "！？",
  ui_story_1012_10120601_21_dialog_content = "今の音は確実に「ハーモナイザー」ではないわね。",
  ui_story_1012_10120601_22_dialog_content = "警告！前方30メートルに侵入者を確認…",
  ui_story_1012_10120601_23_dialog_content = "やっぱり来たね。\nサブブレーン、ここのゲートを閉じて！",
  ui_story_1012_10120601_24_dialog_content = "了解しました…エラー！エラー！",
  ui_story_1012_10120601_25_dialog_content = "入口に生命体を検知したため、閉鎖できません。",
  ui_story_1012_10120601_26_dialog_content = "仕方ないわね。PlayerName、用意して！",
  ui_story_1012_10120601_27_dialog_content = "うん。バートンを守らなくちゃ！",
  ui_story_1012_10120601_28_dialog_content = "（…たとえ「ハーモナイザー」を使った結果がどうなっても…）",
  ui_story_1012_10120601_29_dialog_content = "警告、前方10メートルに侵入者を検出。",
  ui_story_1012_10120601_30_dialog_content = "再警告、前方10メートルに侵入者を検出。",
  ui_story_1012_10120601_31_dialog_content = "再警告、前方10メートルに侵入者を検出…",
  ui_story_1012_10120601_32_dialog_content = "…止まった？",
  ui_story_1012_10120601_33_dialog_content = "ほ、本当に…？",
  ui_story_1012_10120601_34_dialog_content = "<color=#e8d9bb><size=45>ドカン！！</size></color>",
  ui_story_1012_10120601_35_dialog_content = "侵入者扱い？",
  ui_story_1012_10120601_36_dialog_content = "あなたたちと同じことをしただけよ。",
  ui_story_1012_10120601_37_dialog_content = "違いなんて、どちらが先だったかだけ。",
  ui_story_1012_10120601_38_dialog_content = "…あら…",
  ui_story_1012_10120601_39_dialog_content = "こんな墓場の最下層に、\nこんな装置が隠されていたなんて…",
  ui_story_1012_10120601_40_dialog_content = "あのうっとうしいヤツ、\n代わりに始末しておいてくれたのね。",
  ui_story_1012_10120601_41_dialog_content = "デタラメを言うな！",
  ui_story_1012_10120601_42_dialog_content = "PlayerName、無駄話をしているひまはないわ！",
  ui_story_1012_10120601_43_dialog_content = "あいつを通すわけには行かない！\nバイスも中にいるの！",
  ui_story_1012_10120601_44_dialog_content = "世の中、あなたの望み通りにいかないことがたくさんあるのよ。",
  ui_story_1012_10120601_45_dialog_content = "PlayerName…巨像の外を知ってずいぶん長いでしょうに。\nまだ私がこんなことを説明してあげないといけないの？",
  ui_story_1012_10120601_46_dialog_content = "あなたより先に私に刃向かった空の末裔がどうなったか、\n言わなくても想像がつくでしょ。",
  ui_story_1012_10120601_47_dialog_content = "ノラ…！",
  ui_story_1012_10120601_48_dialog_content = "『行きなさい。』",
  ui_story_1012_10120601_49_dialog_content = "『はっ！！！』",
  ui_story_1012_10120702_1_dialog_content = "グア！！！",
  ui_story_1012_10120702_2_dialog_content = "ハァッ！！",
  ui_story_1012_10120702_3_dialog_content = "ガウッ…",
  ui_story_1012_10120702_4_dialog_content = "カレン！後ろ！",
  ui_story_1012_10120702_5_dialog_content = "な…！？",
  ui_story_1012_10120702_6_dialog_content = "グォォ！！！",
  ui_story_1012_10120702_7_dialog_content = "くっ…",
  ui_story_1012_10120702_8_dialog_content = "（ダメだ。数が多すぎる…）",
  ui_story_1012_10120702_9_dialog_content = "（カレンと意識をつないでいるより、\nこれを使って…）",
  ui_story_1012_10120702_10_dialog_content = "えっ！？",
  ui_story_1012_10120702_11_dialog_content = "知らなかったわ。\nPlayerName、いつの間に武器の扱い方を覚えたの？",
  ui_story_1012_10120702_12_dialog_content = "ふぅん…確かに、空の末裔の武器ね。\n文化財レベルの遺物だわ。",
  ui_story_1012_10120702_13_dialog_content = "なかなかいいものね。",
  ui_story_1012_10120702_14_dialog_content = "ありがとう、PlayerName。\nもらっておくわ。",
  ui_story_1012_10120702_15_dialog_content = "くっ――返して！",
  ui_story_1012_10120702_16_dialog_content = "グォォ！！！",
  ui_story_1012_10120702_17_dialog_content = "PlayerName、早く！足止めしないと！\nこれ以上進ませるわけには行かない！",
  ui_story_1012_10120702_18_dialog_content = "ここで失敗したらハーモナイザーが危ない！",
  ui_story_1012_10120702_19_dialog_content = "散れ！氷花よ！",
  ui_story_1012_10120702_20_dialog_content = "<size=45>グォオオ！！！！！！</size>",
  ui_story_1012_10120702_21_dialog_content = "カ、カレン！",
  ui_story_1012_10120702_22_option_content = "強制感知！",
  ui_story_1012_10120702_23_dialog_content = "カレン…早く…早く応答して！",
  ui_story_1012_10120702_24_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1012_10120702_25_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1012_10120702_26_dialog_content = "『殺しなさい。あの装置は傷つけないように。』",
  ui_story_1012_10120702_27_dialog_content = "『はっ。』",
  ui_story_1012_10120702_28_dialog_content = "<size=50><anim type=Shake>グオオオ――――――</anim></size>",
  ui_story_1012_10120702_29_dialog_content = "（どうして、どうしてこんなことに？）",
  ui_story_1012_10120702_30_dialog_content = "（この無力感…まただ…）",
  ui_story_1012_10120702_31_dialog_content = "（僕に戦う力があれば、きっとこんなことには…）",
  ui_story_1012_10120702_32_dialog_content = "（バイス、カレン、それに…）",
  ui_story_1012_10120702_33_dialog_content = "（みんな…）",
  ui_story_1012_10120702_34_dialog_content = "助けてくれ！！！誰か、助けてくれ！",
  ui_story_1012_10120702_35_dialog_content = "近づかないで！最後まで戦ってやる！",
  ui_story_1012_10120702_36_dialog_content = "ウワアァァァ…ううううう…",
  ui_story_1012_10120702_37_dialog_content = "戦火、暗鬼――ずいぶんな目覚ましじゃねぇか？",
  ui_story_1012_10120702_38_dialog_content = "（え？）",
  ui_story_1012_10120702_39_dialog_content = "最高の気分だぜ！",
  ui_story_1012_10120702_40_dialog_content = "もう待ちきれねぇ…\nこの力、今にも噴き出してきそうだ！",
  ui_story_1012_10120702_41_dialog_content = "ホンモノの戦いこそ最高の訓練だ！",
  ui_story_1012_10120702_42_dialog_content = "バートン！せ、成功したんだね！？",
  ui_story_1012_10120702_43_dialog_content = "なんだ、どうしたPlayerName…？",
  ui_story_1012_10120702_44_dialog_content = "さっさと顔の水を拭くんだな！\nメソメソしてる場合か！",
  ui_story_1012_10120702_45_dialog_content = "気合を入れろ！",
  ui_story_1012_10120702_46_dialog_content = "も、もちろんだよ！",
  ui_story_1012_10120702_47_dialog_content = "来い！本当の戦場とは何たるかを教えてやる。",
  ui_story_1012_10120702_48_dialog_content = "こいつはお前の塔なんだ。\n日蝕のヤツらに渡すわけにいかないだろ！",
  ui_story_1012_10120702_49_dialog_content = "『本当に驚きね。古代の空の末裔の科学技術が、\nこれほど発達していたなんて…』",
  ui_story_1012_10120702_50_dialog_content = "『ワクワクするわ。\nやはり、ここまで追いかけてきたのは正しい判断だった。』",
  ui_story_1012_10120702_51_dialog_content = "『さすがはノラ様です。』",
  ui_story_1012_10120702_52_dialog_content = "『何をボヤボヤしてるの？あいつを捕まえなさい。\n殺してはダメよ。生け捕りにして。』",
  ui_story_1012_10120702_53_dialog_content = "『はっ――』",
  ui_story_1012_10120702_54_dialog_content = "<color=#e8d9bb><size=45>バン！！！</size></color>",
  ui_story_1012_10120702_55_dialog_content = "「久しぶり」だな。ノラ。",
  ui_story_1012_10120702_56_dialog_content = "ちょっと見ないうちに、\nお前の手下どもがずいぶんフヌケちまったみてぇだな？",
  ui_story_1012_10120702_57_dialog_content = "しゃくに障るわね。",
  ui_story_1012_10120702_58_dialog_content = "『総員、攻撃せよ！』",
  ui_story_1012_10120702_59_dialog_content = "グォォ！！！",
  ui_story_1012_10120702_60_dialog_content = "くたばりな！",
  ui_story_1012_10120702_61_dialog_content = "PlayerName、バートン！",
  ui_story_1012_10120702_62_dialog_content = "…「ハーモナイザー」が機能したのね！",
  ui_story_1012_10120702_63_dialog_content = "ハッハッハッハ！そういうこった！",
  ui_story_1012_10120702_64_dialog_content = "早くバイスを助けてやれ。\nお前たちのチームにバイスは不可欠だろ？",
  ui_story_1012_10120702_65_dialog_content = "ここは俺に任せろ。",
  ui_story_1012_10120702_66_dialog_content = "…",
  ui_story_1012_10120702_67_dialog_content = "『撤退よ。主力と合流する。』",
  ui_story_1012_10120702_68_dialog_content = "『拝命しました…』",
  ui_story_1012_10120702_69_dialog_content = "てめぇ！待ちやがれ！！！",
  ui_story_1012_10120702_70_dialog_content = "戦士のプライドってもんがねぇのか！？",
  ui_story_1012_10120702_71_dialog_content = "カレン、大丈夫？さっきはずいぶん…",
  ui_story_1012_10120702_72_dialog_content = "大丈夫よ。グズグズしてる暇はないわ、\nPlayerName…",
  ui_story_1012_10120702_73_dialog_content = "一刻も早く、バイスを助けましょう！",
  ui_story_1012_10120702_74_dialog_content = "そうだね。\nさっきと同じように「同調」させればいいはずだ。",
  ui_story_1012_10120702_75_dialog_content = "（頼んだよ…「ハーモナイザー」！）",
  ui_story_1012_10120702_76_dialog_content = "（目を覚まして、バイス…）",
  ui_story_1012_10120702_77_dialog_content = "<color=#e8d9bb>システムメッセージ…「ハーモナイザー」起動します…</color>",
  ui_story_1012_10120801_1_dialog_content = "<color=#e8d9bb>警告…「ハーモナイザー」運転中…同調プロセスを中断しないでください…</color>",
  ui_story_1012_10120801_2_dialog_content = "…",
  ui_story_1012_10120801_3_dialog_content = "…",
  ui_story_1012_10120801_4_dialog_content = "…どれぐらい経った？",
  ui_story_1012_10120801_5_dialog_content = "焦らないで、PlayerName。\nバイスには時間が必要よ。",
  ui_story_1012_10120801_6_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1012_10120801_7_dialog_content = "…いくらなんでも、\n時間がかかりすぎじゃない？",
  ui_story_1012_10120801_8_dialog_content = "そう言われると、\n確かにバートンの時より時間がかかっているわね…",
  ui_story_1012_10120801_9_dialog_content = "PlayerName、私たちは…",
  ui_story_1012_10120801_10_dialog_content = "（カレン…）",
  ui_story_1012_10120801_11_dialog_content = "（ここで気落ちするわけには行かない…）",
  ui_story_1012_10120801_12_dialog_content = "「ハーモナイザー」の指示はしっかり守って、\nバイスを入れたんだ。",
  ui_story_1012_10120801_13_dialog_content = "最初から最後まで、\nバートンの時とまったく同じことをしてるし…",
  ui_story_1012_10120801_14_dialog_content = "「ハーモナイザー」もサブブレーンも、\n何もエラーがあったとは言ってない。",
  ui_story_1012_10120801_15_dialog_content = "だから、問題があるとすれば…",
  ui_story_1012_10120801_16_option_content = "バイスの「意識消失」状態だ",
  ui_story_1012_10120801_17_dialog_content = "そう考えるしかないわね。",
  ui_story_1012_10120801_18_dialog_content = "ケガをしていたと言っても、\nバートン将軍は意識を失っていなかった。",
  ui_story_1012_10120801_19_dialog_content = "あれほどの重傷を負っていたのに、\nより強靭な肉体を手に入れて、目覚めることができた…",
  ui_story_1012_10120801_20_option_content = "ノラが壊したせいだ",
  ui_story_1012_10120801_21_dialog_content = "ノラにその時間があったかしら…？",
  ui_story_1012_10120801_22_dialog_content = "暗鬼たちも「ハーモナイザー」には\n近づけてすらいないはず。",
  ui_story_1012_10120801_23_dialog_content = "バートン将軍が倒していたから…",
  ui_story_1012_10120801_24_dialog_content = "そう考えると…やはり問題は「意識消失」ね。",
  ui_story_1012_10120801_25_dialog_content = "そうだね…\nさっきリングシステムで見たデータは…",
  ui_story_1012_10120801_26_dialog_content = "実験体……「意識消失」から未だ目覚めず。バイタルが後退。",
  ui_story_1012_10120801_27_dialog_content = "実験体…「意識消失」から未だ目覚めず、…現象が現れ、生命が…",
  ui_story_1012_10120801_28_dialog_content = "実験体……いまだ目覚めず、実験中…",
  ui_story_1012_10120801_29_dialog_content = "実験体になっていた空の末裔たち…\n共通する特徴は――",
  ui_story_1012_10120801_30_dialog_content = "「意識消失」状態だったことなんだ。",
  ui_story_1012_10120801_31_dialog_content = "…",
  ui_story_1012_10120801_32_dialog_content = "（まさか、「意識消失」からは復活できない？\n他の犠牲者たちと同じ運命をたどるしかないの？）",
  ui_story_1012_10120801_33_dialog_content = "（もしそうなら、バイスは…）",
  ui_story_1012_10120801_34_dialog_content = "PlayerName…",
  ui_story_1012_10120801_35_dialog_content = "PlayerName。",
  ui_story_1012_10120801_36_dialog_content = "だ、大元帥さん！？",
  ui_story_1012_10120801_37_dialog_content = "通信はまだつながっているようだな。",
  ui_story_1012_10120801_38_dialog_content = "そちらの状況はどうだ？\nお前たちがどれほどの騒ぎを起こしているか、分かっているのか？",
  ui_story_1012_10120801_39_dialog_content = "ほ、本当にごめんなさい！",
  ui_story_1012_10120801_40_dialog_content = "フ…責めているわけではない。",
  ui_story_1012_10120801_41_dialog_content = "ただ、今回の天空ノ谷の急変を知って動いているのは\n啓光だけではないと知らせたかっただけだ。",
  ui_story_1012_10120801_42_dialog_content = "決して流されるままになるな…",
  ui_story_1012_10120801_43_dialog_content = "天空ノ谷に手を付ける資格があるのは、\nお前だけだ。",
  ui_story_1012_10120801_44_dialog_content = "また後で会おう。",
  ui_story_1012_10120801_45_dialog_content = "はい！",
  ui_story_1012_10120801_46_dialog_content = "彼女の言う通りね。",
  ui_story_1012_10120801_47_dialog_content = "今の私たちは塔の外の状況がまったく分かっていない…\n言うまでもなく、不利なことよ。",
  ui_story_1012_10120801_48_dialog_content = "でも、今すぐ外の様子を知るには、\nどうすればいいんだろう？",
  ui_story_1012_10120801_49_dialog_content = "バートンはまだノラの相手をしてるはず。\nいきなり感知して足を引っ張ってしまったらまずい…",
  ui_story_1012_10120801_50_dialog_content = "質問を分析中…",
  ui_story_1012_10120801_51_dialog_content = "え？",
  ui_story_1012_10120801_52_dialog_content = "サブブレーン…何か方法があるの？",
  ui_story_1012_10120801_53_dialog_content = "塔外の監視モニターを起動しています。",
  ui_story_1012_10120801_54_dialog_content = "はぁ、はぁ…",
  ui_story_1012_10120801_55_dialog_content = "逃げるな、ノラ！",
  ui_story_1012_10120801_56_dialog_content = "戦士らしく俺と戦いやがれ！",
  ui_story_1012_10120801_57_dialog_content = "ん…？",
  ui_story_1012_10120801_58_dialog_content = "何だ…？",
  ui_story_1012_10120801_59_dialog_content = "こいつは…一生で二度は見れねぇ光景だ…！！",
  ui_story_1012_10120801_60_dialog_content = "（こんな援軍の数…今まで見たことねぇ！）",
  ui_story_1012_10120801_61_dialog_content = "（まるで十年以上前の…暗潮の危機そのまんまじゃねぇか！）",
  ui_story_1012_10120801_62_dialog_content = "（さて…俺はPlayerNameたちをどこまで助けてやれる…？）",
  ui_story_1012_10120801_63_dialog_content = "ほう…",
  ui_story_1012_10120801_64_dialog_content = "ずいぶん面倒なことになっているようだな、ノラ。",
  ui_story_1012_10120801_65_dialog_content = "これに懲りたら、もう一人歩きはしないことだ。",
  ui_story_1012_10120801_66_dialog_content = "このありさまでは収穫どころでは無かっただろう。",
  ui_story_1012_10120801_67_dialog_content = "悪いけど、収穫はあったわ。",
  ui_story_1012_10120801_68_dialog_content = "ま、あなたとは関係ないことね。",
  ui_story_1012_10120801_69_dialog_content = "傍観してるだけで、\n漁夫の利を得られるなんて思わないことね。",
  ui_story_1012_10120801_70_dialog_content = "フン、勝手にするがいい…",
  ui_story_1012_10120801_71_dialog_content = "本当に汚ねぇヤツだな…\nノラ！勝てないからって今度は助けを呼んだのか？",
  ui_story_1012_10120801_72_dialog_content = "（あそこだ！隊列に穴がある…）",
  ui_story_1012_10120801_73_dialog_content = "食らえ…",
  ui_story_1012_10120801_74_dialog_content = "うっ…！？",
  ui_story_1012_10120801_75_dialog_content = "日蝕が総動員されてるのは、\nあなたの相手をするためじゃないの。",
  ui_story_1012_10120801_76_dialog_content = "ムダなあがきはやめて、\nおとなしくしてなさい。",
  ui_story_1012_10120801_77_dialog_content = "この白い塔に来てからずっと、\nあの空の末裔のために必死に時間を稼ごうとしてる…",
  ui_story_1012_10120801_78_dialog_content = "そうでしょ？",
  ui_story_1012_10120801_79_dialog_content = "…",
  ui_story_1012_10120801_80_dialog_content = "『捕まえなさい。』",
  ui_story_1012_10120801_81_dialog_content = "グオオォ！！！",
  ui_story_1012_10120801_82_dialog_content = "<color=#e8d9bb>バキン！</color>",
  ui_story_1012_10120801_83_dialog_content = "これは――",
  ui_story_1012_10120801_84_dialog_content = "ほう…近くで見ると、\nやはり驚くべき塔だ。",
  ui_story_1012_10120801_85_dialog_content = "何もかも、夢で見た預言の通り…",
  ui_story_1012_10120801_86_dialog_content = "世界が破滅に向かうにせよ、再生に向かうにせよ、\n天空ノ谷と暗鬼の戦いは欠かされざる一局。",
  ui_story_1012_10120801_87_dialog_content = "（北境の…女王！？）",
  ui_story_1012_10120801_88_dialog_content = "（こんな所に出て来るとは…）",
  ui_story_1012_10120801_89_dialog_content = "バートン軍団長。啓光連邦軍規第42条…\n軍人の命令違反に対する処分がどう定められているかは、知っているだろうな？",
  ui_story_1012_10120801_90_dialog_content = "！？",
  ui_story_1012_10120801_91_dialog_content = "啓光は軍規にしたがって厳格に処罰を行う。\n重大な違反は軍事法廷で裁かれる。",
  ui_story_1012_10120801_92_dialog_content = "――しかし、それは戦争が終わってからの話だ。",
  ui_story_1012_10120801_93_dialog_content = "…大元帥！？",
  ui_story_1012_10120801_94_dialog_content = "増援の先遣部隊がもうすぐ到着する。\n合流を急げ。",
  ui_story_1012_10120801_95_dialog_content = "それにしても…緊急の特訓でもしていたか？\nずいぶん様子が違うようだが…",
  ui_story_1012_10120801_96_dialog_content = "まあ、いい。\n存分に大暴れしてもらうぞ、バートン軍団長…",
  ui_story_1012_10120801_97_dialog_content = "違反の埋め合わせは\n戦功でしてもらわねばならん！",
  ui_story_1012_10120801_98_dialog_content = "…",
  ui_story_1012_10120801_99_dialog_content = "了解！",
  ui_story_1012_10120801_100_dialog_content = "しかと見てろよ、大元帥！",
  ui_story_1012_10120801_101_dialog_content = "塔外の監視モニター、再生終了…",
  ui_story_1012_10120801_102_dialog_content = "ベツレヘム女王陛下に、\nレインハト大元帥…",
  ui_story_1012_10120801_103_dialog_content = "…北境と啓光が動いたようね。",
  ui_story_1012_10120801_104_dialog_content = "でも、あれだけの兵力で日蝕の相手をするのは、\nどう考えても無理よ。",
  ui_story_1012_10120801_105_dialog_content = "PlayerName、私たちも何かしなくては！",
  ui_story_1012_10120801_106_dialog_content = "分かってる。回帰の塔は地理的にど真ん中だ。\n有利に使って行こう…",
  ui_story_1012_10120801_107_dialog_content = "サブブレーン、回帰の塔にある防衛手段を教えて！",
  ui_story_1012_10120801_108_dialog_content = "質問を分析中…回答が出ました――",
  ui_story_1012_10120801_109_dialog_content = "回帰の塔内部には防衛システムとして、\n<color=#FFB400>「律法の弦」</color>が備えられています…",
  ui_story_1012_10120801_110_dialog_content = "天空ノ谷の最強かつ、最も特殊な、\n最終防衛システムです。",
  ui_story_1012_10120801_111_dialog_content = "じゃあ――",
  ui_story_1012_10120801_112_dialog_content = "「律法の弦」の起動は困難が伴います。\nまた、非常に大きな代償が必要となります。",
  ui_story_1012_10120801_113_dialog_content = "サブブレーンはいかなる空の末裔にも\n「律法の弦」の起動権限を与えられません。",
  ui_story_1012_10120801_114_dialog_content = "また「権限」…？",
  ui_story_1012_10120801_115_dialog_content = "繰り返します…「律法の弦」の起動は困難が伴います。\nまた、非常に大きな代償が必要となります。",
  ui_story_1012_10120801_116_dialog_content = "サブブレーンはいかなる空の末裔にも…",
  ui_story_1012_10120801_117_dialog_content = "PlayerName、機械を説得しようとしても無駄よ。",
  ui_story_1012_10120801_118_dialog_content = "私たちは自分の意志を持った生き物よ。\n機械に縛られてはいけないわ。",
  ui_story_1012_10120801_119_dialog_content = "（カレンの言う通りだ。\nそれに、僕はもう見たくない…）",
  ui_story_1012_10120801_120_dialog_content = "（暗鬼の大軍が押し寄せて、\n空の末裔が何もできずに皆殺しにされる光景なんて）",
  ui_story_1012_10120801_121_dialog_content = "ここに閉じこもっているわけにはいかない…\n日蝕との戦いに、僕も参加するんだ！",
  ui_story_1012_10120801_122_dialog_content = "考えていることはもっともよ、PlayerName。",
  ui_story_1012_10120801_123_dialog_content = "でも、バイスが…",
  ui_story_1012_10120801_124_dialog_content = "まだ「同調」は終わっていないし、\nかなりの時間が必要になるでしょうね。",
  ui_story_1012_10120801_125_dialog_content = "PlayerName、私たちがこのエリアから出たら、\nサブブレーンに入口の構造を変えてもらいましょう。",
  ui_story_1012_10120801_126_dialog_content = "入口を塞いで、\n秘密通路の構造を変えさせて…",
  ui_story_1012_10120801_127_dialog_content = "バイスのために頑丈な<color=#FFB400>繭</color>を\n作っておきましょう。",
  ui_story_1012_10120801_128_dialog_content = "そうだね。",
  ui_story_1012_10120801_129_dialog_content = "（バイス、お願いだ。目覚めて…）",
  ui_story_1012_10120801_130_dialog_content = "（皆が待ってる）",
  ui_story_1012_10120801_131_dialog_content = "バイス…また後で会おうね。",
  ui_story_1012_10120901_1_dialog_content = "<color=#e8d9bb>塔の内部、通路</color>",
  ui_story_1012_10120901_2_dialog_content = "<color=#e8d9bb>タッタッタッ…</color>",
  ui_story_1012_10120901_3_dialog_content = "この先が私たちの来た入口ね。",
  ui_story_1012_10120901_4_dialog_content = "PlayerName、\n今さらお説教など必要ないと思うけれど…",
  ui_story_1012_10120901_5_dialog_content = "怖れないで。",
  ui_story_1012_10120901_6_dialog_content = "カレン…？",
  ui_story_1012_10120901_7_dialog_content = "これだけは忘れないで。\nあなたは自分の故郷を守るために戦うのよ。",
  ui_story_1012_10120901_8_dialog_content = "それはこの上なく名誉なこと。\n怖がってはだめ。",
  ui_story_1012_10120901_9_dialog_content = "ベツレヘム陛下が、昔…\n私に教えてくれたことよ。",
  ui_story_1012_10120901_10_dialog_content = "ありがとう、カレン。",
  ui_story_1012_10120901_11_dialog_content = "覚悟はできてる。",
  ui_story_1012_10120901_12_dialog_content = "ええ。\n一緒に塔の外へ向かいましょう。",
  ui_story_1012_10120901_13_dialog_content = "こ、これは…",
  ui_story_1012_10120901_14_dialog_content = "<color=#e8d9bb>ガタン…カチャリ…</color>",
  ui_story_1012_10120901_15_dialog_content = "<anim type=Shake><size=50>グオオオ！！！！！！！</size></anim>",
  ui_story_1012_10120901_16_dialog_content = "あの頃の天空ノ谷も…\nこんな光景だったのかな…",
  ui_story_1012_10120901_17_dialog_content = "PlayerName、危ない――！",
  ui_story_1012_10120901_18_dialog_content = "ガァ…",
  ui_story_1012_10120901_19_dialog_content = "キキキキッ…",
  ui_story_1012_10120901_20_dialog_content = "誰より早く情報を手に入れられることは、\n大軍を動かせるよりも役に立つ…",
  ui_story_1012_10120901_21_dialog_content = "それに――\n形勢はもはや、誰の目にも明らかだ。",
  ui_story_1012_10120901_22_dialog_content = "その程度の兵力では、\nどうあがいても我らと渡り合うことなど不可能だぞ。",
  ui_story_1012_10120901_23_dialog_content = "フン、戦いの前の与太話は\nお前たち日蝕の伝統なのか？",
  ui_story_1012_10120901_24_dialog_content = "ムダ話をしたところで、\nお前たちの力が強くなるわけではなかろう。",
  ui_story_1012_10120901_24X1_dialog_content = "（…ベツレヘム陛下もそろそろ到着されるはず）",
  ui_story_1012_10120901_24X2_dialog_content = "PlayerName、私は回帰の塔の反対側の様子を見に行って、\n女王陛下と合流するわ。",
  ui_story_1012_10120901_24X3_dialog_content = "あなたは啓光の援軍とここに残って。\n大丈夫よね？",
  ui_story_1012_10120901_24X4_dialog_content = "大丈夫だよ。\n何かあったらいつでも連絡して。",
  ui_story_1012_10120901_24X5_dialog_content = "気をつけてね、カレン！",
  ui_story_1012_10120901_25_dialog_content = "大元帥、報告です。\n第二軍団の支援小隊がバートン軍団長と合流しました。",
  ui_story_1012_10120901_26_dialog_content = "現在、命令を待っています。",
  ui_story_1012_10120901_27_dialog_content = "分かった。兵力を前線に集中させ、\n密集隊形で突撃せよと伝えろ。",
  ui_story_1012_10120901_28_dialog_content = "残りの部隊は両翼に分散し、\n後方から日蝕の後続部隊をけん制せよ。",
  ui_story_1012_10120901_29_dialog_content = "了解！",
  ui_story_1012_10120901_30_dialog_content = "…動かないのか？",
  ui_story_1012_10120901_31_dialog_content = "…大元帥、私への任務が\nまだ指示されておりません。",
  ui_story_1012_10120901_32_dialog_content = "ハハハ…！それではお前は後方に向かえ。\nあの塔を防衛しつつ、次の命令を待て。",
  ui_story_1012_10120901_33_dialog_content = "塔の防衛…ですか？",
  ui_story_1012_10120901_34_dialog_content = "あの大きな塔が見えるだろう？",
  ui_story_1012_10120901_35_dialog_content = "見えますが――",
  ui_story_1012_10120901_36_dialog_content = "あの白い塔こそ、我々が今、\n天空ノ谷の救援に駆けつけた目的だ。",
  ui_story_1012_10120901_37_dialog_content = "前線ではないが、\nこの任務は前線で戦うよりも重要だ。",
  ui_story_1012_10120901_38_dialog_content = "安心しろ。後で私が交代する。\n戦地の情報もその時交換しよう。",
  ui_story_1012_10120901_39_dialog_content = "…了解！",
  ui_story_1012_10120901_40_dialog_content = "PlayerNameは…\nしばらく私のそばに置いておこう。",
  ui_story_1012_10120901_41_dialog_content = "ところで、お前の側にいるはずの\n2人がいないようだが…",
  ui_story_1012_10120901_42_dialog_content = "バイスのことなら…",
  ui_story_1012_10120901_43_dialog_content = "バイス中尉のことは\nバートン軍団長から聞いている。",
  ui_story_1012_10120901_44_dialog_content = "塔の中にある物には、自信を持て。\nお前の先祖が残した遺産なのだ。",
  ui_story_1012_10120901_45_dialog_content = "ましてや戦いが目前に迫っているという時に、\n悪い方へと考えるのは良くない。",
  ui_story_1012_10120901_46_dialog_content = "気合を入れて、気を引き締めろ！",
  ui_story_1012_10120901_47_dialog_content = "…はい！",
  ui_story_1012_10120901_48_dialog_content = "それでいい。",
  ui_story_1012_10120901_49_dialog_content = "<color=#e8d9bb>同時刻・回帰の塔の反対側</color>",
  ui_story_1012_10120901_50_dialog_content = "<size=45>女王陛下！！！</size>",
  ui_story_1012_10120901_51_dialog_content = "申し訳ございません、私は女王陛下の護衛でありながら、\nこれでは何のためにいるのか…",
  ui_story_1012_10120901_52_dialog_content = "ですが、どうかこのティアラを置き去りにして、\nお一人で暗鬼の群れに飛び込むことはおやめください！",
  ui_story_1012_10120901_53_dialog_content = "必要とあらば、私が女王陛下に代わって突撃します！",
  ui_story_1012_10120901_54_dialog_content = "ティアラ、そなたは普段、雪の森を歩き回り、\n監視と奇襲を最も得意としている…",
  ui_story_1012_10120901_55_dialog_content = "それが今回、天空ノ谷で戦う北境の戦略なのだ。",
  ui_story_1012_10120901_56_dialog_content = "前線は血の気の多い光霊たちに任せておけばよい。\n私たちはこの塔の付近を堅守するのだ。",
  ui_story_1012_10120901_57_dialog_content = "北境からの全兵力はすでに白い塔の周囲まで退却させ、\n警戒させている。",
  ui_story_1012_10120901_58_dialog_content = "前線が突破されない限り、\nここまで暗鬼が立ち入ることはあるまい。",
  ui_story_1012_10120901_59_dialog_content = "はい、女王陛下！",
  ui_story_1012_10120901_60_dialog_content = "…それから、戦場では\n仰々しくする必要はない。",
  ui_story_1012_10120901_61_dialog_content = "直接私の名前を呼んで構わない。",
  ui_story_1012_10120901_62_dialog_content = "さあ、私が張った防壁の中で待て。",
  ui_story_1012_10120901_63_dialog_content = "は、はい！女王陛下！",
  ui_story_1012_10120901_64_dialog_content = "ベツレヘム女王陛下、\nこれほど早くお越しいただけるとは思っておりませんでした！",
  ui_story_1012_10120901_65_dialog_content = "カレン、久しぶりだな。",
  ui_story_1012_10120901_66_dialog_content = "むろん、昔話をしている場合ではないが…\n目の前の状況は、試練だと思うがよい。",
  ui_story_1012_10120901_67_dialog_content = "そなた1人でどこまでできるようになったか、\n見せてもらおう。",
  ui_story_1012_10120901_68_dialog_content = "カレン殿下は決して1人ではありません！",
  ui_story_1012_10120901_69_dialog_content = "ベルタ？",
  ui_story_1012_10120901_70_dialog_content = "どうして…ラファエルのもとで働いているはずでは？",
  ui_story_1012_10120901_71_dialog_content = "殿下！ベルタは城主様の命を受け、\n騎士団の精鋭部隊を率いて救援にはせ参じました！",
  ui_story_1012_10120901_72_dialog_content = "<color=#FFB400>殿下</color>、どうかご命令を！",
  ui_story_1012_10120901_73_dialog_content = "（なるほど、父上が…）",
  ui_story_1012_10120901_74_dialog_content = "（…あの父上が、これほど早く兵を出して\n救援の姿勢を見せた…）",
  ui_story_1012_10120901_75_dialog_content = "白夜に捧ぐ！\n全員、武器を取り、私とともに前線に向かえ――",
  ui_story_1012_10120901_76_dialog_content = "白夜の光で夜を裂き、暗闇を貫け！",
  ui_story_1012_10120901_77_dialog_content = "白夜に捧ぐ！",
  ui_story_1012_10120901_78_dialog_content = "<color=#e8d9bb>天空ノ谷・日蝕の軍陣</color>",
  ui_story_1012_10120901_79_dialog_content = "『白夜城の連中まで来たのか？\nあの老いぼれめ、目の利くやつだ。』",
  ui_story_1012_10120901_80_dialog_content = "『…こ、今度こそ、日蝕に刃向かった代償を\n白夜城に思い知らせてやりますよ！』",
  ui_story_1012_10120901_81_dialog_content = "『白夜城だけではない。天空ノ谷を占領したあかつきには、\n大陸全土を支配する絶対的な力が手に入る！』",
  ui_story_1012_10120901_82_dialog_content = "『キキキキキキッ…』",
  ui_story_1012_10120901_83_dialog_content = "『日蝕の同胞たちよ、\n我らの時代が始まろうとしている…』",
  ui_story_1012_10120901_84_dialog_content = "『勝利はもはや、我らの手の中にある！』",
  ui_story_1012_10120901_85_dialog_content = "『この天空ノ谷を、\n再び真紅の血で洗い流してくれよう！』",
  ui_story_1012_10120901_86_dialog_content = "『進め！白き塔を占領せよ！\n敵は皆殺しだ！』",
  ui_story_1012_10120901_87_dialog_content = "『行け！！！』",
  ui_story_1012_10120901_88_dialog_content = "<anim type=Shake><size=45>グオオオ！！！！！</size></anim>",
  ui_story_1012_10120901_89_dialog_content = "『今日を最後に、アストラ大陸は\n二度と太陽を拝むことがなくなるだろう…』",
  ui_story_1012_10121002_1_dialog_content = "PlayerName、相変わらず指揮は落ち着いているようだな。",
  ui_story_1012_10121002_2_dialog_content = "このような状況で、それは…\n冷静と言うべきか、単純と言うべきか？",
  ui_story_1012_10121002_3_dialog_content = "お前がどうしてあれほど多くの者の信頼を集められるか、\n少し分かってきた気がするな。",
  ui_story_1012_10121002_4_dialog_content = "お、恐れ入ります…",
  ui_story_1012_10121002_5_dialog_content = "大元帥に報告！\n日蝕の第一陣の攻勢が収まったようです！",
  ui_story_1012_10121002_6_dialog_content = "戦局はまだ不透明ですが、\nこちらの戦線はいぜんとして非常に強固です。",
  ui_story_1012_10121002_7_dialog_content = "よろしい。各自、力を温存しておけ。\nまだ戦闘は始まったばかりだ。",
  ui_story_1012_10121002_8_dialog_content = "バートン軍団長には、支援小隊を率いて\n味方の勢力と協力するよう伝えよ。",
  ui_story_1012_10121002_9_dialog_content = "了解！",
  ui_story_1012_10121002_10_dialog_content = "もはや子どもではないとはいえ、カレンは…",
  ui_story_1012_10121002_11_dialog_content = "前線で、そなたの配下と共に戦うとなると、\n手を焼くであろうな。",
  ui_story_1012_10121002_12_dialog_content = "フ、ぬるま湯に浸かっていては、\nいつまでも将軍として成長できん。",
  ui_story_1012_10121002_13_dialog_content = "カレンを育てたそうだな？",
  ui_story_1012_10121002_14_dialog_content = "ソルラドよりもお前の方が父親らしく見える。",
  ui_story_1012_10121002_15_dialog_content = "…言葉はつつしめ、大元帥閣下。",
  ui_story_1012_10121002_16_dialog_content = "女王陛下になんという態度！？",
  ui_story_1012_10121002_17_dialog_content = "グォォ！！！",
  ui_story_1012_10121002_18_dialog_content = "うっ――",
  ui_story_1012_10121002_19_dialog_content = "氷よ！",
  ui_story_1012_10121002_20_dialog_content = "戦いのさなかだ。世間話は好まぬ。",
  ui_story_1012_10121002_21_dialog_content = "戦局は掌握できているようだが、\n慢心はしないでもらいたい。",
  ui_story_1012_10121002_22_dialog_content = "では、私は残存の兵力を率いて、\n塔の前方の日蝕を片付けに向かうとしよう。",
  ui_story_1012_10121002_23_dialog_content = "刀を遊ばせておくわけには行かん！",
  ui_story_1012_10121002_24_dialog_content = "<color=#e8d9bb>天空ノ谷・前線</color>",
  ui_story_1012_10121002_25_dialog_content = "はぁ！？あの白夜城の兵に協力しろだぁ？",
  ui_story_1012_10121002_26_dialog_content = "その通りです。",
  ui_story_1012_10121002_27_dialog_content = "はいはい…分かったよ。\nお前の伝令任務は完了だ。",
  ui_story_1012_10121002_28_dialog_content = "！？",
  ui_story_1012_10121002_29_dialog_content = "グォォ！！！",
  ui_story_1012_10121002_30_dialog_content = "グ…",
  ui_story_1012_10121002_31_dialog_content = "ほらほら、ここはまだ片付いちゃいねぇんだ。\nさっさと戻って大元帥と塔を守りな！",
  ui_story_1012_10121002_32_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_1012_10121002_33_dialog_content = "うっ…",
  ui_story_1012_10121002_34_dialog_content = "えぇっ！？",
  ui_story_1012_10121002_35_dialog_content = "啓光の奴ら、何をしてるの！？",
  ui_story_1012_10121002_36_dialog_content = "わ、私ではありません！\n今のは地面が急に揺れ…",
  ui_story_1012_10121002_37_dialog_content = "まったく…面倒かけないでよね。",
  ui_story_1012_10121002_38_dialog_content = "<color=#e8d9bb>バン！！</color>",
  ui_story_1012_10121002_39_dialog_content = "ググ…ギギ！？",
  ui_story_1012_10121002_40_dialog_content = "これは…暗鬼が大砲で飛ばされてきた？",
  ui_story_1012_10121002_41_dialog_content = "使い捨ての弾というわけね…",
  ui_story_1012_10121002_42_dialog_content = "ガァ…",
  ui_story_1012_10121002_43_dialog_content = "ここは前線よ。内輪もめをする場所ではないわ。\n戦うために来たわけではないなら…",
  ui_story_1012_10121002_44_dialog_content = "早く帰ることね。",
  ui_story_1012_10121002_45_dialog_content = "はい！",
  ui_story_1012_10121002_46_dialog_content = "「はい」じゃねぇだろ！？",
  ui_story_1012_10121002_47_dialog_content = "す、すみません！",
  ui_story_1012_10121002_48_dialog_content = "<color=#e8d9bb>バン！！</color>",
  ui_story_1012_10121002_49_dialog_content = "また「砲弾」か？",
  ui_story_1012_10121002_50_dialog_content = "おかしいわ。\n私たちの方には飛んでいない。それに…",
  ui_story_1012_10121002_51_dialog_content = "今の影、どうにも不安になる。一体…",
  ui_story_1012_10121002_52_dialog_content = "まずいぞ！",
  ui_story_1012_10121002_53_dialog_content = "<color=#FFB400>暗力</color>だ！",
  ui_story_1012_10121002_54_dialog_content = "さっきまでのはただの試験だ！",
  ui_story_1012_10121002_55_dialog_content = "<color=#FFB400>暗力の砲弾</color>を\n回帰の塔目がけて撃ってやがる！",
  ui_story_1012_10121002_56_dialog_content = "（塔を直接！？）",
  ui_story_1012_10121002_57_dialog_content = "戦場を移すぞ！第二軍団支援小隊、よく聞け！",
  ui_story_1012_10121002_58_dialog_content = "ただちに回帰の塔に戻り、\n大元帥を支援する！",
  ui_story_1012_10121101_1_dialog_content = "<color=#e8d9bb>天空ノ谷・回帰の塔付近</color>",
  ui_story_1012_10121101_2_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_1012_10121101_3_dialog_content = "（何かが頭上で爆発した！？）",
  ui_story_1012_10121101_4_dialog_content = "（おじけづいてる場合じゃない…女王陛下の護衛として、\n女王陛下をお守りしないと！）",
  ui_story_1012_10121101_5_dialog_content = "（どうしたんだろう？\n急に気分が悪くなってきた…）",
  ui_story_1012_10121101_6_dialog_content = "（この不快感、覚えがある…）",
  ui_story_1012_10121101_7_dialog_content = "！！",
  ui_story_1012_10121101_8_dialog_content = "<color=#FFB400>暗力</color>か！",
  ui_story_1012_10121101_9_dialog_content = "雪雲よ！",
  ui_story_1012_10121101_10_dialog_content = "障壁の大きさにも限りがある。\nできる限り、範囲内に留まれ。",
  ui_story_1012_10121101_11_dialog_content = "とてつもない暗力だ。\n飲み込まれてはならぬ！",
  ui_story_1012_10121101_12_dialog_content = "ゲホッ、ゲホッ…\nこの程度なら問題ない！",
  ui_story_1012_10121101_13_dialog_content = "…しかし、ひたすら防いでいるだけでは、\nそう長く持つまい。",
  ui_story_1012_10121101_14_dialog_content = "このままでは…\nこちらから手を打つ必要があるな。",
  ui_story_1012_10121101_15_dialog_content = "大元帥！",
  ui_story_1012_10121101_16_dialog_content = "アナトリアか。いいところに戻った…",
  ui_story_1012_10121101_17_dialog_content = "ふむ？最重要の戦力も連れて来たか。",
  ui_story_1012_10121101_18_dialog_content = "第二軍団長バートン、参上！",
  ui_story_1012_10121101_19_dialog_content = "大元帥、早く命令を出してくれ！",
  ui_story_1012_10121101_20_dialog_content = "戦場じゃチャンスなんて\n一瞬しかねぇんだ！",
  ui_story_1012_10121101_21_dialog_content = "実にいいところに来た、\nバートン軍団長。",
  ui_story_1012_10121101_22_dialog_content = "えっ、だ、大元帥？",
  ui_story_1012_10121101_23_dialog_content = "頭に情報を詰めてばかりのこいつを連れて行け。\n見識を広められるようにな！",
  ui_story_1012_10121101_24_dialog_content = "ここを死守し、白い塔を守るために\n日蝕の全兵力を引き付けよ。できるな？",
  ui_story_1012_10121101_25_dialog_content = "日蝕だけが奇襲を使えるわけではないと、\n思い知らせてやろう。",
  ui_story_1012_10121101_26_dialog_content = "奇襲する作戦か？\n喜んで協力するぜ。",
  ui_story_1012_10121101_27_dialog_content = "安心して行ってくれ。\nここは俺に任せろ！",
  ui_story_1012_10121101_28_dialog_content = "（見ていると暗力の不快感を忘れてしまいそうなほど、\n意気揚々としたやりとりだ…）",
  ui_story_1012_10121101_29_dialog_content = "（日蝕の暗力砲が不吉な闇を、\n僕たちの方へひっきりなしに飛ばしてきている…）",
  ui_story_1012_10121101_30_dialog_content = "（でも、夜の闇へ立ち向かおうというのに、\nまるで春風でも浴びているかのように穏やかな顔だ）",
  ui_story_1012_10121101_31_dialog_content = "（天才的戦士、危険な野心家…\n彼女に対する啓光の人の評価は色々ある…）",
  ui_story_1012_10121101_32_dialog_content = "（だけど、戦場に立つ彼女を見た人なら、\nきっと「啓明の光」の本当の意味を理解できるはずだ――）",
  ui_story_1012_10121101_33_dialog_content = "（それは希望の見えない暗闇の中で、\n輝きを放つ明けの明星…）",
  ui_story_1012_10121101_34_dialog_content = "<size=33>PlayerName、少し力を貸せ。</size>",
  ui_story_1012_10121101_35_dialog_content = "<size=33>空の末裔であるお前にしかできないことがある。</size>",
  ui_story_1012_10121101_36_dialog_content = "え！？",
  ui_story_1012_10121101_37_dialog_content = "ま、待ってください！",
  ui_story_1012_10121101_38_dialog_content = "いきなり僕を\n担がないでください！",
  ui_story_1012_10121101_39_dialog_content = "（いきなり人を担ぐのは\n啓光の伝統なの！？）",
  ui_story_1012_10121101_40_dialog_content = "ハッハッハ…すまないが、少しの辛抱だ。",
  ui_story_1012_10121101_41_dialog_content = "空の末裔は光の軌跡が見えると聞いた。\nならば、<color=#FFB400>暗力の発射元</color>も見えるのではないか？",
  ui_story_1012_10121101_42_dialog_content = "しばらく私のナビゲーターとなれ。",
  ui_story_1012_10121101_43_dialog_content = "暗力砲を破壊しに行くぞ！",
  ui_story_1012_10121101_44_dialog_content = "<color=#e8d9bb>天空ノ谷・前線</color>",
  ui_story_1012_10121101_45_dialog_content = "カレン隊長、今度の波はこいつが最後の暗鬼です。",
  ui_story_1012_10121101_46_dialog_content = "啓光の連中と一緒に、戦線を移動しますか？",
  ui_story_1012_10121101_47_dialog_content = "いえ、戦場に穴をあけるわけにいかないわ。",
  ui_story_1012_10121101_48_dialog_content = "私たちが退けば、\n日蝕に道を譲ることになってしまう。",
  ui_story_1012_10121101_49_dialog_content = "これはこれは、実に珍しいですね？",
  ui_story_1012_10121101_50_dialog_content = "白夜城の城主が自分の娘を戦場に遣わすとは…",
  ui_story_1012_10121101_51_dialog_content = "！？",
  ui_story_1012_10121101_52_dialog_content = "前々から姫との一騎打ち、\nやってみたかったのですよ。",
  ui_story_1012_10121101_53_dialog_content = "（やはり来た。思った通り…）",
  ui_story_1012_10121101_54_dialog_content = "ミレン・ゴーティエ、\nあなたはとっくの昔に白夜城に敗れている。",
  ui_story_1012_10121101_55_dialog_content = "法廷から指名手配されている身でありながら、\nのこのこ捕まりに来たようね。",
  ui_story_1012_10121101_56_dialog_content = "ああ…私と会えるのをそんなにも\n心待ちにしてくださっていたのですか？",
  ui_story_1012_10121101_57_dialog_content = "それでしたら私の「視界」の実験も\nムダにはなりませんね。",
  ui_story_1012_10121101_57X1_dialog_content = "ここには私たちと、あなたの雑兵だけ…",
  ui_story_1012_10121101_57X2_dialog_content = "果たしてのこのこ捕まりに来たのはどちらでしょう？\n結論を下すにはまだ早いですよ。",
  ui_story_1012_10121101_58_dialog_content = "相変わらず、虫ずが走る物言いね。",
  ui_story_1012_10121101_59_dialog_content = "わっ…うひゃっ！氷！",
  ui_story_1012_10121101_60_dialog_content = "何をするのです！？\nどうしてあの龍に乗った氷女と同じようなことを！？",
  ui_story_1012_10121101_61_dialog_content = "「氷女」…まさか、ベツレヘム陛下のこと？",
  ui_story_1012_10121101_62_dialog_content = "ベツレヘム陛下への侮辱は…",
  ui_story_1012_10121101_63_dialog_content = "許さない！！",
  ui_story_1012_10121101_64_dialog_content = "<color=#e8d9bb>ドン――！</color>",
  ui_story_1012_10121101_65_dialog_content = "こちらは少々てこずっていたようだな。",
  ui_story_1012_10121101_66_dialog_content = "PlayerNameに感謝するといい。\n道中でミレンとやらの暗力を感知したと言い出したのだ…",
  ui_story_1012_10121101_67_dialog_content = "いずれにせよ、助太刀に来た。",
  ui_story_1012_10121101_68_dialog_content = "PlayerNameもいるのなら、\nこれ以上時間を無駄にできないわね。",
  ui_story_1012_10121101_69_dialog_content = "日蝕の大砲が静かになっているうちに、\n小細工を潰しに行きましょう…",
  ui_story_1012_10121101_70_dialog_content = "さあ、ミレン…",
  ui_story_1012_10121101_71_dialog_content = "…あれ？",
  ui_story_1012_10121101_72_dialog_content = "…本当に、逃げ足の速い奴ね…",
  ui_story_1012_10121101_73_dialog_content = "グズグズしているヒマはない。\nこのまま突撃する！",
  ui_story_1012_10121101_74_dialog_content = "前線は私が支えよう。\nお前は騎士団を率いて主力部隊と合流するのだ。",
  ui_story_1012_10121101_75_dialog_content = "暗鬼が押し寄せ、暗力が戦場を覆い始めた今、\n白い塔にはこれまで以上に安定して戦える者が必要だ。",
  ui_story_1012_10121101_76_dialog_content = "分かったわ。\nでは、ここは貴方に任せる。",
  ui_story_1012_10121101_77_dialog_content = "…ところで、PlayerName。\nずいぶん顔色が悪いようね？",
  ui_story_1012_10121101_78_dialog_content = "（感知してる暗力が濃すぎて、すごく気持ち悪い…）",
  ui_story_1012_10121101_79_dialog_content = "（でも、そんなこと、\nここで口に出すわけにはいかない！）",
  ui_story_1012_10121101_80_dialog_content = "か、顔色が悪いのは、\n僕の示す行き先が正しいって証拠だよ！",
  ui_story_1012_10121101_81_dialog_content = "じゃあ、ここで二手に分かれよう。\nカレン、いい知らせを待ってて！",
  ui_story_1012_10121101_82_dialog_content = "気をつけて。",
  ui_story_1012_10121101_83_dialog_content = "では行こうか、PlayerName。",
  ui_story_1012_10121101_84_dialog_content = "暗力砲はすぐ先だ。激しい戦いになるぞ。",
  ui_story_1012_10121102_1_dialog_content = "よくやった、PlayerName。",
  ui_story_1012_10121102_2_dialog_content = "暗力砲とやら、もろいものだな。",
  ui_story_1012_10121102_3_dialog_content = "今ので最後か？",
  ui_story_1012_10121102_4_dialog_content = "もう一度確認します…",
  ui_story_1012_10121102_5_option_content = "強制感知！",
  ui_story_1012_10121102_6_dialog_content = "たぶん、一ヵ所に集まった暗力はもうなさそうです。\nただ…",
  ui_story_1012_10121102_7_dialog_content = "グォォ！！！",
  ui_story_1012_10121102_8_dialog_content = "グォォ！！！！！",
  ui_story_1012_10121102_9_dialog_content = "ザコどもが面倒だな。",
  ui_story_1012_10121102_10_dialog_content = "こいつらの放つ暗力も\n感知に影響するのか？",
  ui_story_1012_10121102_11_dialog_content = "ならば…我が槍で串刺しにしてやろう。",
  ui_story_1012_10121102_12_dialog_content = "真の力を思い知れ！",
  ui_story_1012_10121102_13_dialog_content = "ガァ…",
  ui_story_1012_10121102_14_dialog_content = "相変わらず戦場が好きなようね、\nレインハト。",
  ui_story_1012_10121102_15_dialog_content = "いずれ命とりになるわよ。",
  ui_story_1012_10121102_16_dialog_content = "言いたいことはそれだけか？",
  ui_story_1012_10121102_17_dialog_content = "私が生きていることには\n特に驚かないようだな、ノラ。",
  ui_story_1012_10121102_18_dialog_content = "まぁ、<color=#FFB400>あの時</color>から分かっていたことか…",
  ui_story_1012_10121102_19_dialog_content = "私のような「化け物」を倒すのは、\n相当に苦労するということを。",
  ui_story_1012_10121102_20_dialog_content = "自信家ぶりも相変わらずね。",
  ui_story_1012_10121102_21_dialog_content = "フィジェロがお目当てなら、この先にいるわよ。",
  ui_story_1012_10121102_22_dialog_content = "私は忙しいから。",
  ui_story_1012_10121102_23_dialog_content = "『行くわよ。』",
  ui_story_1012_10121102_24_dialog_content = "『はっ。』",
  ui_story_1012_10121102_25_dialog_content = "（おかしい…ノラがそんなに親切なはずは…）",
  ui_story_1012_10121102_26_dialog_content = "（おまけに、自分から道を教えてくれるなんて…）",
  ui_story_1012_10121102_27_dialog_content = "だ、大元帥さん…ノラは…\n何か企んでると思います。",
  ui_story_1012_10121102_28_dialog_content = "…",
  ui_story_1012_10121102_29_dialog_content = "PlayerName、塔の下の戦線を確認しに行くぞ！",
  ui_story_1012_10121102_30_dialog_content = "は、はい！",
  ui_story_1012_10121102_31_dialog_content = "キキキキッ…",
  ui_story_1012_10121102_32_dialog_content = "お前の妹でも足止めできなかったのか？",
  ui_story_1012_10121102_33_dialog_content = "お前たち光霊というのは、\n時に暗鬼よりも冷酷な生き物になるようだな。",
  ui_story_1012_10121102_34_dialog_content = "…チッ。",
  ui_story_1012_10121102_35_dialog_content = "（やはり奴らの狙いは私だったか）",
  ui_story_1012_10121102_36_dialog_content = "（私が暗力砲を破壊しに行かなければ、\n暗力砲で我々の兵力を消耗させる…）",
  ui_story_1012_10121102_37_dialog_content = "（破壊しに行けば、\nすかさず兵を出して白い塔を攻撃する…）",
  ui_story_1012_10121102_38_dialog_content = "（…とどのつまり…我々の兵が少なすぎるということだ）",
  ui_story_1012_10121102_39_dialog_content = "PlayerName、行くぞ！",
  ui_story_1012_10121102_40_dialog_content = "この程度で戦局を変えられると思っているのか？",
  ui_story_1012_10121102_41_dialog_content = "光霊の敗北はとうの昔に決まっていたことなのだ。",
  ui_story_1012_10121102_42_dialog_content = "お前がしていることは、\n死の先延ばしにすぎん。",
  ui_story_1012_10121102_43_dialog_content = "戻って<color=#FFB400>総崩れ</color>の同胞たちを見るがいい！",
  ui_story_1012_10121102_44_dialog_content = "日蝕の精鋭と暗鬼の大軍によって、\n粉砕されていく様をな。",
  ui_story_1012_10121102_45_dialog_content = "何だって…！？",
  ui_story_1012_10121102_46_dialog_content = "キキキキキキッ…想像しただけでも胸がおどる。\n見逃すわけには行かん。",
  ui_story_1012_10121102_47_dialog_content = "では、お先に失礼しよう。",
  ui_story_1012_10121102_48_dialog_content = "敗北を楽しむがいい、レインハト。",
  ui_story_1012_10121102_49_dialog_content = "時間がない。PlayerName、追うぞ！",
  ui_story_1012_10121102_50_dialog_content = "追うって…どうするんですか？",
  ui_story_1012_10121102_51_dialog_content = "どうする？\n戦うに決まっているだろう。",
  ui_story_1012_10121102_52_dialog_content = "戦友を信じ、ひたすらに戦い続けるのだ…",
  ui_story_1012_10121102_53_dialog_content = "我々が真に倒れる瞬間までな！",
  ui_story_1012_10121301_1_dialog_content = "キキッ、なんと美しい光景だ。",
  ui_story_1012_10121301_2_dialog_content = "お前たちが苦労して守ってきた卵にヒビが入ったぞ。",
  ui_story_1012_10121301_3_dialog_content = "そのヒビに指を入れ、少しずつ押し潰してくれる。",
  ui_story_1012_10121301_4_dialog_content = "私の手の上で、お前たちが\n砕け散る様子を楽しませてもらおう。",
  ui_story_1012_10121301_5_dialog_content = "暗鬼ども！殺戮を渇望する者どもよ！",
  ui_story_1012_10121301_6_dialog_content = "血の流れる傷の匂いを感じるか？",
  ui_story_1012_10121301_7_dialog_content = "奴らの急所を狙い――",
  ui_story_1012_10121301_8_dialog_content = "最後の光をかき消すのだ！",
  ui_story_1012_10121301_9_dialog_content = "グア――！！！",
  ui_story_1012_10121301_10_dialog_content = "大量の暗鬼が押し寄せてくる！",
  ui_story_1012_10121301_11_dialog_content = "私たちで…穴を塞げるかしら？",
  ui_story_1012_10121301_12_dialog_content = "戦術的には防衛線が突破されている以上、\nリスクの大きい動きです。",
  ui_story_1012_10121301_13_dialog_content = "穴の付近は内外の脅威に挟まれていますし、\nそれに…",
  ui_story_1012_10121301_14_dialog_content = "分かった、もういいわ！",
  ui_story_1012_10121301_15_dialog_content = "ここは戦場なの！\n講釈を聞いているヒマなんてないわ！",
  ui_story_1012_10121301_16_dialog_content = "戦場に身を置いているからこそ、\n合理的な判断が重要なのです。",
  ui_story_1012_10121301_17_dialog_content = "じゃあ、あなたの合理的な判断で出した結論は？",
  ui_story_1012_10121301_18_dialog_content = "このまま守りを固めていても全滅します。",
  ui_story_1012_10121301_19_dialog_content = "…",
  ui_story_1012_10121301_20_dialog_content = "合理的な選択は白い塔を放棄し、\n全軍が一ヵ所に集結して包囲を突破することです。",
  ui_story_1012_10121301_21_dialog_content = "個別の兵士の戦闘能力は相手を上回っているため、\n包囲を突破できる望みはあります。",
  ui_story_1012_10121301_22_dialog_content = "じゃあ、どうしてそうしないの？",
  ui_story_1012_10121301_23_dialog_content = "私は行けません。",
  ui_story_1012_10121301_24_dialog_content = "大元帥からここを死守するよう命じられました。\nですから、ここに残って戦わなくてはなりません。",
  ui_story_1012_10121301_25_dialog_content = "アハハハ…あなたの合理的な判断も\n役に立たないみたいね、啓光の兵士さん。",
  ui_story_1012_10121301_26_dialog_content = "軍人たる者、命令が最優先です。\nただ、このような条件では…",
  ui_story_1012_10121301_27_dialog_content = "分かった、分かったってば。",
  ui_story_1012_10121301_28_dialog_content = "目の前の状況を変えられないなら…",
  ui_story_1012_10121301_29_dialog_content = "とりあえずその賢い頭を休ませて、\n思いっきり戦いましょう！",
  ui_story_1012_10121301_30_dialog_content = "おやおや、それはいけませんね、\nお美しいお嬢さん。",
  ui_story_1012_10121301_31_dialog_content = "これ以上私たちの足を引っ張れば、\nフィジェロ様がお怒りになりますよ。",
  ui_story_1012_10121301_32_dialog_content = "誰！？",
  ui_story_1012_10121301_33_dialog_content = "これは…何かしら？",
  ui_story_1012_10121301_34_dialog_content = "危ない！",
  ui_story_1012_10121301_35_dialog_content = "ああ…とんだおジャマ虫ですね…",
  ui_story_1012_10121301_36_dialog_content = "私と美しいお嬢さんの2人だけの世界に、\nむさ苦しい男が割って入ってくるだなんて！",
  ui_story_1012_10121301_37_dialog_content = "あなたね…",
  ui_story_1012_10121301_38_dialog_content = "注意してください。\n周囲の光力が大幅に制限されているようです。",
  ui_story_1012_10121301_39_dialog_content = "ここでは本来の力が出せません。",
  ui_story_1012_10121301_40_dialog_content = "そうなの？",
  ui_story_1012_10121301_41_dialog_content = "まあ、どうでもいいわ。\n私の頭の中は、あいつの顔面に拳をお見舞いしてやることでいっぱいだもの。",
  ui_story_1012_10121301_42_dialog_content = "実に情熱的ですね、お嬢さん！",
  ui_story_1012_10121301_43_dialog_content = "あせってはいけません。\n時間ならたっぷりありますから。",
  ui_story_1012_10121301_44_dialog_content = "お互いの理解をじっくりと深めていきましょう！",
  ui_story_1012_10121301_45_dialog_content = "グアアッ！",
  ui_story_1012_10121301_46_dialog_content = "…",
  ui_story_1012_10121301_47_dialog_content = "…後ろのそなた、手は出さぬのか？",
  ui_story_1012_10121301_48_dialog_content = "…",
  ui_story_1012_10121301_49_dialog_content = "北境の女王…",
  ui_story_1012_10121301_49X1_dialog_content = "覚えているぞ。\n白夜の祝典にいた反逆者であろう。",
  ui_story_1012_10121301_49X2_dialog_content = "あの時のそなたの気迫は今より鋭かった。",
  ui_story_1012_10121301_50_dialog_content = "だが今、この戦場で躊躇（ちゅうちょ）している者はそなただけだ。",
  ui_story_1012_10121301_51_dialog_content = "…",
  ui_story_1012_10121301_52_dialog_content = "北境の女王、あんたほどの強さでも\n戦局が分かってないのか？",
  ui_story_1012_10121301_53_dialog_content = "光霊の敗北は必至なのに、\nどうしてまだ戦おうとする？",
  ui_story_1012_10121301_54_dialog_content = "光霊の敗北は必至ならば、\nなぜ戦おうとしない？",
  ui_story_1012_10121301_55_dialog_content = "俺は…",
  ui_story_1012_10121301_56_dialog_content = "戦うか否かは、\nここに立つ前に考えておくべきであった問題だ。",
  ui_story_1012_10121301_57_dialog_content = "今のそなたでは、\nたちまち命を落とすことになるであろう。",
  ui_story_1012_10121301_58_dialog_content = "…そうかもしれん…",
  ui_story_1012_10121301_59_dialog_content = "ならば、ひと思いに――",
  ui_story_1012_10121301_60_dialog_content = "北境の女王にお手合わせ願おうか！",
  ui_story_1012_10121301_61_dialog_content = "うわっ、大きな化け物！？",
  ui_story_1012_10121301_62_dialog_content = "あれは…女王陛下の方角！？",
  ui_story_1012_10121301_63_dialog_content = "女王陛下！！！",
  ui_story_1012_10121301_64_dialog_content = "グアアッ！",
  ui_story_1012_10121301_65_dialog_content = "こいつ！ジャマするな！",
  ui_story_1012_10121301_66_dialog_content = "女王陛下をお守りしなくては――",
  ui_story_1012_10121301_67_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1012_10121301_68_dialog_content = "うっ…今のは！？",
  ui_story_1012_10121301_69_dialog_content = "女王陛下、女王陛下…！",
  ui_story_1012_10121301_70_dialog_content = "なんと幼稚な忠誠心だ。",
  ui_story_1012_10121301_71_dialog_content = "あなたは…",
  ui_story_1012_10121301_72_dialog_content = "あの女は十分に強い。\nお前のような半端者が守る必要などない。",
  ui_story_1012_10121301_73_dialog_content = "それよりも自分の心配をするのだな。",
  ui_story_1012_10121301_74_dialog_content = "狩りはこれからだぞ。",
  ui_story_1012_10121301_75_dialog_content = "！！！",
  ui_story_1012_10121301_76_dialog_content = "うぐっ――！",
  ui_story_1012_10121301_77_dialog_content = "はぁ…はぁ…",
  ui_story_1012_10121301_78_dialog_content = "（体がついてこねぇ…）",
  ui_story_1012_10121301_79_dialog_content = "（ハーモナイザーのおかげでずいぶん強くなってるが、\nいきなりキツイ戦いは…少し無理があったな…）",
  ui_story_1012_10121301_80_dialog_content = "（だが、引き下がれねぇ。\n他の奴らの足を引っ張るわけにはいかねぇ！）",
  ui_story_1012_10121301_81_dialog_content = "バートン…そろそろ限界かしら？",
  ui_story_1012_10121301_82_dialog_content = "何！？",
  ui_story_1012_10121301_83_dialog_content = "ノラ、てめぇ！",
  ui_story_1012_10121301_84_dialog_content = "私たちもいい加減に終わらせましょう。",
  ui_story_1012_10121301_85_dialog_content = "「あなたの勇気に敬服する」。\nお墓に刻んでおいてあげるわ。",
  ui_story_1012_10121301_86_dialog_content = "チッ、おせっかいはいらねぇよ！",
  ui_story_1012_10121301_87_dialog_content = "食らえ！！！",
  ui_story_1012_10121301_88_dialog_content = "何だ！？今さら戦うのが怖いってか！？",
  ui_story_1012_10121301_89_dialog_content = "私は囚われの獣と戦う趣味なんてないの。\nそいつが代わりに相手してくれるわ。",
  ui_story_1012_10121301_90_dialog_content = "私が興味あるのは、あなたの後ろの回帰の塔だけ。",
  ui_story_1012_10121301_91_dialog_content = "グアアア――",
  ui_story_1012_10121301_92_dialog_content = "ふざけやがって！！！",
  ui_story_1012_10121301_93_dialog_content = "ノラ！",
  ui_story_1012_10121301_94_dialog_content = "ノラ！！！",
  ui_story_1012_10121301_95_dialog_content = "<color=#e8d9bb>バン！バン！バンッ！</color>",
  ui_story_1012_10121301_96_dialog_content = "何！？これは…",
  ui_story_1012_10121301_97_dialog_content = "（バートン、後ろにさがって！）",
  ui_story_1012_10121301_98_dialog_content = "PlayerName！戻ってきたのか！",
  ui_story_1012_10121301_99_dialog_content = "…面倒ね。",
  ui_story_1012_10121301_100_dialog_content = "どうやら、戻るのが遅すぎたということは\nなかったようだな。",
  ui_story_1012_10121301_101_dialog_content = "戦況はまったく予断を許さない。\n敵がこれほど多いとはな…",
  ui_story_1012_10121301_102_dialog_content = "お前たちは他の場所の応援に向かえ！",
  ui_story_1012_10121301_103_dialog_content = "ここは私に任せておけ！",
  ui_story_1012_10121301_104_dialog_content = "私とこいつには、積もる話もある。",
  ui_story_1012_10121301_105_dialog_content = "積もる話？この期に及んで？",
  ui_story_1012_10121301_106_dialog_content = "フ…分かっている。\nお互い、相手の言葉に耳を傾けたりしない性質だ。",
  ui_story_1012_10121301_107_dialog_content = "今度はお前が聞きとれる言葉で話してやろう。",
  ui_story_1012_10121301_108_dialog_content = "日蝕の全軍を前にして、\nあなたの暴力にどの程度の発言権があるのかしらね？",
  ui_story_1012_10121301_109_dialog_content = "奴らなどどうでもいい。\nお前だけが理解できればそれでいいのだ。",
  ui_story_1012_10121301_110_dialog_content = "報告します。未登録の暗鬼が巨像整備エリアに侵入しました。",
  ui_story_1012_10121301_111_dialog_content = "報告します。未登録の暗鬼が巨像部品生産ラインに侵入しました。",
  ui_story_1012_10121301_112_dialog_content = "報告します。未登録の暗鬼が廃棄物処理エリアに侵入しました。",
  ui_story_1012_10121301_113_dialog_content = "報告ばかりじゃなくて、何か方法はないの！？",
  ui_story_1012_10121301_114_dialog_content = "回帰の塔内の防衛設備をチェック中――",
  ui_story_1012_10121301_115_dialog_content = "申し訳ありません。防衛設備の損傷が甚大です。\n回帰の塔の防衛能力が不足しています。",
  ui_story_1012_10121301_116_dialog_content = "そうだろうね。方法があれば、\nさっきノラと戦った時に使ってただろうし。",
  ui_story_1012_10121301_117_dialog_content = "PlayerName、またサブブレーンと通信？",
  ui_story_1012_10121301_118_dialog_content = "そうだよ。暗鬼の侵入状況を報告してきてるんだ。",
  ui_story_1012_10121301_119_dialog_content = "今、塔の内側の暗鬼を倒しても意味はないわ。",
  ui_story_1012_10121301_120_dialog_content = "外側の戦局をどうにかしない限り、\n回帰の塔はいずれ日蝕に占領されてしまう…",
  ui_story_1012_10121301_121_dialog_content = "どうしたら…",
  ui_story_1012_10121301_122_dialog_content = "レインハト大元帥にベツレヘム女王陛下まで、\n強い光霊が僕たちと一緒に戦ってるのに…",
  ui_story_1012_10121301_122X1_dialog_content = "戦局は悪化し続けてる。",
  ui_story_1012_10121301_123_dialog_content = "僕たちに残る切り札は…",
  ui_story_1012_10121301_124_dialog_content = "やっぱり、サブブレーンが言ってた\n最終兵器ぐらいしかない…",
  ui_story_1012_10121301_125_dialog_content = "報告します。未登録の暗鬼が資源生産エリアに侵入しました。",
  ui_story_1012_10121301_126_dialog_content = "報告します。未登録の暗鬼が空の末裔の生活エリアに侵入しました。",
  ui_story_1012_10121301_127_dialog_content = "サブブレーン！そんな情報は報告しなくていいよ。\n「律法の弦」の起動方法を教えて！",
  ui_story_1012_10121301_128_dialog_content = "どんな効果があるのか分からないけど、\nこうなったら試してみるしかない！",
  ui_story_1012_10121301_129_dialog_content = "？？？",
  ui_story_1012_10121301_130_dialog_content = "不正なリクエストを検出しました。",
  ui_story_1012_10121301_131_dialog_content = "最高命令により、\nいかなる空の末裔も「律法の弦」に触れることはできません。",
  ui_story_1012_10121301_132_dialog_content = "こんな時にそんなの構ってられないでしょ！",
  ui_story_1012_10121301_133_dialog_content = "日蝕が勝ったら、僕たちだけじゃなくて、\n回帰の塔だってどうなるか分からないよ！",
  ui_story_1012_10121301_134_dialog_content = "そうなってもいいの！？",
  ui_story_1012_10121301_135_dialog_content = "申し訳ありません。\nサブブレーンはいかなる事態の発生も望んでいません。",
  ui_story_1012_10121301_136_dialog_content = "サブブレーンはただ「命令」に従っているだけです。",
  ui_story_1012_10121301_137_dialog_content = "君って奴は…",
  ui_story_1012_10121301_138_dialog_content = "さっぱり役に立たない！",
  ui_story_1012_10121301_139_dialog_content = "やめなさい、PlayerName。\n人工知能相手にムキにならないで。",
  ui_story_1012_10121301_140_dialog_content = "できることをやりましょう。\n各勢力の増援がこちらに向かっているはずよ。",
  ui_story_1012_10121301_141_dialog_content = "到着するまで持ちこたえられるといいけれど…",
  ui_story_1012_10121301_142_dialog_content = "はぁ…その通りだね。できることをしよう。",
  ui_story_1012_10121301_143_dialog_content = "報告します。未登録の暗鬼がコア中枢エリアに侵入しました。",
  ui_story_1012_10121301_144_dialog_content = "ピー！ピー！ピー！",
  ui_story_1012_10121301_145_dialog_content = "うるさいなぁ！",
  ui_story_1012_10121301_146_dialog_content = "サブブレーン、役にたたないのはいいけど、\nせめて少し静かにしてくれない？",
  ui_story_1012_10121301_147_dialog_content = "事前設定条件が発動…\n指令を割り込み実行します。",
  ui_story_1012_10121301_148_dialog_content = "指令作成者：フランシス。指令優先度：最高。",
  ui_story_1012_10121301_149_dialog_content = "サブブレーンの知的エージェント基層ロジックを変更しています…",
  ui_story_1012_10121301_150_dialog_content = "またその人…今度は何だろう？",
  ui_story_1012_10121301_151_dialog_content = "変更が完了しました。",
  ui_story_1012_10121301_152_dialog_content = "種族存続の危機に直面していると判断し、\nサブブレーンは空の末裔に「律法の弦」の起動方法をお伝えします。",
  ui_story_1012_10121301_153_dialog_content = "え！？",
  ui_story_1012_10121301_154_dialog_content = "サブブレーン、教えてくれるって、\nどうして急に！？",
  ui_story_1012_10121301_155_dialog_content = "割り込み指令によって、\nサブブレーンは現在のタスクを実行しています。",
  ui_story_1012_10121301_156_dialog_content = "フランシス先生、誰か知らないけど…\nとにかくありがとう！",
  ui_story_1012_10121301_157_dialog_content = "早く教えて。どうすればいいの？",
  ui_story_1012_10121301_158_dialog_content = "中枢エリアへ向かい、\nリングシステムの深部にアクセスして下さい。",
  ui_story_1012_10121301_159_dialog_content = "リングシステムの最深部で\n「コアリング権限」を奪取してください。",
  ui_story_1012_10121301_160_dialog_content = "「律法の弦」の起動には「コアリング権限」が必要です。",
  ui_story_1012_10121301_161_dialog_content = "「コアリング権限」？\nアクセス不可能って言ってなかった？",
  ui_story_1012_10121301_162_dialog_content = "その通りです。\nそのため、サブブレーンは「奪取する」という言葉を使用しました。",
  ui_story_1012_10121301_163_dialog_content = "これは規定に違反し、\n禁忌を犯すことになります。",
  ui_story_1012_10121301_164_dialog_content = "その過程で死亡する可能性が極めて高いものです。",
  ui_story_1012_10121301_165_dialog_content = "死亡する可能性が極めて高い！？",
  ui_story_1012_10121301_166_dialog_content = "…具体的な理由を教えて。",
  ui_story_1012_10121301_167_dialog_content = "申し訳ありません。\nサブブレーンには「コアリング権限」に関するデータがありません。",
  ui_story_1012_10121301_168_dialog_content = "サブブレーンが受けた指令は、\n空の末裔に「律法の弦」の起動方法を教えることのみです。",
  ui_story_1012_10121301_169_dialog_content = "「律法の弦」の起動には「コアリング権限」が必要です。",
  ui_story_1012_10121301_170_dialog_content = "…",
  ui_story_1012_10121301_171_dialog_content = "他の選択肢は教えてくれないんだね？",
  ui_story_1012_10121301_172_dialog_content = "カレン、戦局を変える方法を見つけたよ。",
  ui_story_1012_10121301_173_dialog_content = "行こう。中枢エリアに戻って、\n「律法の弦」を起動させるんだ。",
  ui_story_1012_10121301_174_dialog_content = "サブブレーンが\n方法を教えてくれたということ？",
  ui_story_1012_10121301_175_dialog_content = "うん。",
  ui_story_1012_10121301_176_dialog_content = "私に手伝えることはある？",
  ui_story_1012_10121301_177_dialog_content = "塔の中にはまだ暗鬼がいるから、\n一緒に中枢エリアまで行ってくれるだけで十分だよ。",
  ui_story_1012_10121301_178_dialog_content = "後のことは、\n僕が自分でやらなきゃいけないみたいなんだ。",
  ui_story_1012_10121301_179_dialog_content = "大元帥さん、聞こえますか？",
  ui_story_1012_10121301_180_dialog_content = "どうした？応援が必要か？",
  ui_story_1012_10121301_181_dialog_content = "そうかもしれません。\n回帰の塔の最終兵器を起動しに行きます。",
  ui_story_1012_10121301_182_dialog_content = "その間、皆と一緒に戦えなくなります。",
  ui_story_1012_10121301_183_dialog_content = "もしかしたら迷惑をかけるかもしれません。\nできるだけ急ぎます。",
  ui_story_1012_10121301_184_dialog_content = "兵器が起動するまで、\n敵を回帰の塔に入れないでください。",
  ui_story_1012_10121301_185_dialog_content = "最終兵器？\n愉快そうな響きではないか。",
  ui_story_1012_10121301_186_dialog_content = "この巨大な塔の兵器ならば、\n古代文明の力でできているはず…",
  ui_story_1012_10121301_187_dialog_content = "空の末裔、見せてもらうぞ！",
  ui_story_1012_10121301_188_dialog_content = "アハハ…まだ成功するかどうかも分かりません…",
  ui_story_1012_10121301_189_dialog_content = "戦場のことは心配するな。\n私が塔の前を守る。",
  ui_story_1012_10121301_190_dialog_content = "啓光の大元帥を墓に埋めたくば、\nまずは谷全体を死体で埋め尽くしてからだ！",
  ui_story_1012_10121301_191_dialog_content = "…",
  ui_story_1012_10121301_192_dialog_content = "ベツレヘム陛下、聞こえますか？",
  ui_story_1012_10121301_193_dialog_content = "僕は…",
  ui_story_1012_10121301_194_dialog_content = "安心せよ。行くがよい。",
  ui_story_1012_10121301_195_dialog_content = "！！！",
  ui_story_1012_10121301_196_dialog_content = "各地の星々がここに集まっている。\n夜が明ける時まで、輝き続けることだろう。",
  ui_story_1012_10121301_197_dialog_content = "暗闇を打ち破れ。",
  ui_story_1012_10121301_198_dialog_content = "女王陛下…",
  ui_story_1012_10121301_199_dialog_content = "それから…",
  ui_story_1012_10121301_200_dialog_content = "生きて帰ってくるのだ。",
  ui_story_1012_10121302_1_dialog_content = "ガァ…",
  ui_story_1012_10121302_2_dialog_content = "中枢エリアはこの先よ。急ぎましょう！",
  ui_story_1012_10121302_3_dialog_content = "うん！",
  ui_story_1012_10121302_4_dialog_content = "でも、なんだか周りの暗鬼が\n多くなってきたと思わない？",
  ui_story_1012_10121302_5_dialog_content = "そうね。私たちの戦いの音に\n引き寄せられてきたのかもしれない。",
  ui_story_1012_10121302_6_dialog_content = "最悪の場合、回帰の塔全体の暗鬼が\nこちらに押し寄せてくるかもしれないわね。",
  ui_story_1012_10121302_7_dialog_content = "それはまずいよ。\n中枢エリアは行き止まりだったから…",
  ui_story_1012_10121302_8_dialog_content = "サブブレーン、本当に防衛手段はないの？",
  ui_story_1012_10121302_9_dialog_content = "中枢エリアには専用の「防衛システム」が存在します。",
  ui_story_1012_10121302_10_dialog_content = "…ただし、記録によれば、\nこのシステムは先ほど破壊されました。",
  ui_story_1012_10121302_11_dialog_content = "あっ…僕たちがやったんだ。\n本当にごめん…",
  ui_story_1012_10121302_12_dialog_content = "暗鬼が追ってきている。\n急ぎましょう！",
  ui_story_1012_10121302_13_dialog_content = "そうだね！",
  ui_story_1012_10121302_14_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ、タッ、タッ…</color>",
  ui_story_1012_10121302_15_dialog_content = "着いた！",
  ui_story_1012_10121302_16_dialog_content = "ガアアア！！",
  ui_story_1012_10121302_17_dialog_content = "うわっ！？",
  ui_story_1012_10121302_18_dialog_content = "ふぅ…ありがとう、カレン。",
  ui_story_1012_10121302_19_dialog_content = "早くやるべきことをやって。",
  ui_story_1012_10121302_20_dialog_content = "「律法の弦」を起動するのでしょう？",
  ui_story_1012_10121302_21_dialog_content = "だけど、後ろからまだ、\nかなりの暗鬼が追いかけてきてるみたいだよ。",
  ui_story_1012_10121302_22_dialog_content = "先に倒すべきかな？",
  ui_story_1012_10121302_23_dialog_content = "あとどれほどの暗鬼がいるかも分からないのよ。\nキリがないわ。",
  ui_story_1012_10121302_24_dialog_content = "そっちは私に任せて。",
  ui_story_1012_10121302_25_dialog_content = "えっ？カレンだけで？",
  ui_story_1012_10121302_26_dialog_content = "あなたは兵器を起動させて。\n暗鬼は私がどうにかする。",
  ui_story_1012_10121302_27_dialog_content = "空の末裔と光霊、\nお互いの仕事をしっかりやりましょう。",
  ui_story_1012_10121302_28_dialog_content = "だけど、暗鬼があんなにたくさん…",
  ui_story_1012_10121302_29_dialog_content = "私を信じてくれればいいの。",
  ui_story_1012_10121302_30_dialog_content = "私があなたを信じるようにね。",
  ui_story_1012_10121302_31_dialog_content = "散れ！氷花よ！",
  ui_story_1012_10121302_32_dialog_content = "…",
  ui_story_1012_10121302_33_dialog_content = "うん。信じるよ、カレン。",
  ui_story_1012_10121302_34_dialog_content = "それじゃあ、僕も始めないと…",
  ui_story_1012_10121302_35_option_content = "強制感知！",
  ui_story_1012_10121302_36_dialog_content = "<color=#e8d9bb>ブーン――</color>",
  ui_story_1012_10121302_37_dialog_content = "リングシステムに…戻って来た。",
  ui_story_1012_10121302_38_dialog_content = "リングシステムが\n意識で動かせる空間だとは、分かってる。",
  ui_story_1012_10121302_39_dialog_content = "ここには情報が保存されてる。\n僕の意識は空間内を移動して、必要な内容を調べられる。",
  ui_story_1012_10121302_40_dialog_content = "サブブレーンによると、回帰の塔の情報閲覧と機能使用の権限は\n「アウターリング」、「インナーリング」、「コアリング」の3レベルに分かれている…",
  ui_story_1012_10121302_41_dialog_content = "「リング」っていう名前が付けられているってことは、\nそれぞれリングシステムの輪の部分で区分けされているのかも。",
  ui_story_1012_10121302_42_dialog_content = "「コアリング権限」は最深部にあるって言っていたけど、\n中心に近づくほど権限が高くなるっていうことかな？",
  ui_story_1012_10121302_43_dialog_content = "僕の考えが正しければ、\nそれが古代の空の末裔にとって美しい情報の並べ方ってことになるんだろうな。",
  ui_story_1012_10121302_44_dialog_content = "とにかく、リングシステムの中心に行って、見てみよう。",
  ui_story_1012_10121302_45_dialog_content = "…あれ、進めない？",
  ui_story_1012_10121302_46_dialog_content = "意識がこれ以上、前に進まない…",
  ui_story_1012_10121302_47_dialog_content = "それ以上進んではいけません。",
  ui_story_1012_10121302_48_dialog_content = "！！！",
  ui_story_1012_10121302_49_dialog_content = "空の末裔は「コアリング」に近づいてはいけません。",
  ui_story_1012_10121302_50_dialog_content = "これは<color=#FFB400>命令</color>です。",
  ui_story_1012_10121302_51_dialog_content = "命令…またその言葉だ。",
  ui_story_1012_10121302_52_dialog_content = "その命令って一体何なの？",
  ui_story_1012_10121302_53_dialog_content = "ど、どうして従わなければいけないの？",
  ui_story_1012_10121302_54_dialog_content = "…あれ…？",
  ui_story_1012_10121302_55_dialog_content = "僕は…どうして怖がってるんだろう？",
  ui_story_1012_10121302_56_dialog_content = "最初の、かつ最高の規則である<color=#FFB400>命令</color>は…",
  ui_story_1012_10121302_57_dialog_content = "あなたの、そして空の末裔という種族の出現より\n早くから存在するものです。",
  ui_story_1012_10121302_58_dialog_content = "命令はあなたの意識、血、骨や肉の中に融け込んでいます。",
  ui_story_1012_10121302_59_dialog_content = "命令は空の末裔が守らなければならない信条であり、\n空の末裔が世界に誕生した理由でもあります。",
  ui_story_1012_10121302_60_dialog_content = "はるか昔から運命づけられていた、\n「先天的」なものです。",
  ui_story_1012_10121302_61_dialog_content = "僕の意識が…後退していく！？",
  ui_story_1012_10121302_62_dialog_content = "命令に従わされているということ！？",
  ui_story_1012_10121302_63_dialog_content = "まるで本能みたいに…",
  ui_story_1012_10121302_64_dialog_content = "空の末裔は「コアリング」に近づいてはいけません。",
  ui_story_1012_10121302_65_dialog_content = "これは<color=#FFB400>命令</color>です。",
  ui_story_1012_10121302_66_dialog_content = "（僕の意識が命令に従わされている…\nまるで自分より強力な別の意識が僕の思考を支配しているみたいだ）",
  ui_story_1012_10121302_67_dialog_content = "（それを痛いほど感じる…）",
  ui_story_1012_10121302_68_dialog_content = "（一瞬でも命令に従ったら、\n僕は一生を命令に囚われたまま送ることになる）",
  ui_story_1012_10121302_69_dialog_content = "（生まれる前から仕込まれていた強力な束縛が、\n僕の心の中に深く刻みこまれてしまう…）",
  ui_story_1012_10121302_70_dialog_content = "（でも、そうなってしまったら、何もかもおしまいだ）",
  ui_story_1012_10121302_71_dialog_content = "（「律法の弦」を起動するチャンスもなくなるし、\n外の戦局も変えられなくなってしまうかもしれない）",
  ui_story_1012_10121302_72_dialog_content = "（チャンスは今しかない）",
  ui_story_1012_10121302_73_dialog_content = "動け、動くんだ！奥に向かって！",
  ui_story_1012_10121302_74_dialog_content = "命令なんか知らない。\n信じちゃダメだ！",
  ui_story_1012_10121302_75_dialog_content = "何が運命づけられた先天的なものだ。\n今まで1度も聞いたことなんかなかったのに！",
  ui_story_1012_10121302_76_dialog_content = "どうして今さら出てきて、\n僕のジャマをするんだ！",
  ui_story_1012_10121302_77_dialog_content = "それ以上進んではいけません。",
  ui_story_1012_10121302_78_dialog_content = "空の末裔は「コアリング」に近づいてはいけません。",
  ui_story_1012_10121302_79_dialog_content = "これは<color=#FFB400>命令</color>です。",
  ui_story_1012_10121302_80_dialog_content = "僕を今まで生かし続けてくれたのは、命令なんかじゃない！\n命を捨てて僕を守ってくれた両親、ソラヴァン…",
  ui_story_1012_10121302_81_dialog_content = "僕を見つけてくれたバイス…\nそれから僕と一緒に戦ってきた光霊たちだ！",
  ui_story_1012_10121302_82_dialog_content = "僕に守る命令があるとすれば、\nその人たちだけだ！",
  ui_story_1012_10121302_83_dialog_content = "それ以上進んではいけません。",
  ui_story_1012_10121302_84_dialog_content = "それ以上…",
  ui_story_1012_10121302_85_dialog_content = "あれ？うまくいった？",
  ui_story_1012_10121302_86_dialog_content = "ここが「コアリング」？",
  ui_story_1012_10121302_87_dialog_content = "待って、ここって…",
  ui_story_1012_10121302_87X1_dialog_content = "ここには見覚えがある…\n鏡湖の水面みたいだ。空には極光もあるし…",
  ui_story_1012_10121302_87X2_dialog_content = "これは僕の想像？それにしてはリアルだ。\n湖の冷たさまで感じられる…",
  ui_story_1012_10121302_88_dialog_content = "まるで意識空間じゃない、\n本物の空間にいるみたいだ…",
  ui_story_1012_10121302_89_dialog_content = "あれ、僕の意識が身体になってる！\n不思議だなぁ…",
  ui_story_1012_10121302_90_dialog_content = "「戦闘シミュレーションシステム」と\n同じような技術なのかもしれないなぁ。",
  ui_story_1012_10121302_91_dialog_content = "それで、「コアリング」で何をすればいいんだっけ？\nサブブレーンから聞いていなかった気がする。",
  ui_story_1012_10121302_92_dialog_content = "ねえ、サブブレーン！聞こえる？",
  ui_story_1012_10121302_93_dialog_content = "「コアリング」に着いたよ。\nこの後は何をすればいいの？",
  ui_story_1012_10121302_94_dialog_content = "<color=#e8d9bb>カタン――</color>",
  ui_story_1012_10121302_95_dialog_content = "ん？何の音だろう？",
  ui_story_1012_10121302_96_dialog_content = "<color=#e8d9bb>ガチャリ――ガチャリ――</color>",
  ui_story_1012_10121302_97_dialog_content = "…",
  ui_story_1012_10121302_98_dialog_content = "…",
  ui_story_1012_10121302_99_dialog_content = "待って…これは…防衛システム！？",
  ui_story_1012_10121302_100_dialog_content = "どうしてこんなところに？",
  ui_story_1012_10121302_101_dialog_content = "<color=#e8d9bb>ドスン…ドスン…</color>",
  ui_story_1012_10121302_102_dialog_content = "「コアリング」に侵入した空の末裔…\nあなたは禁忌を犯しました。",
  ui_story_1012_10121302_103_dialog_content = "「コアリング権限」は至高の存在です。\n触れることは許されません。",
  ui_story_1012_10121302_104_dialog_content = "越権行為は阻止されなければなりません。",
  ui_story_1012_10121302_105_dialog_content = "空の末裔は生まれながらにして、力を持つことが許されていません。\n力によって律法を履行します。",
  ui_story_1012_10121302_106_dialog_content = "ウソでしょ…守護者が2体！？",
  ui_story_1012_10121302_107_dialog_content = "これは規定に違反し、\n禁忌を犯すことになります。",
  ui_story_1012_10121302_108_dialog_content = "その過程で死亡する可能性が極めて高いものです。",
  ui_story_1012_10121302_109_dialog_content = "僕に…こんなのと戦えって…？",
  ui_story_1012_10121302_110_dialog_content = "<color=#e8d9bb>ピッ…</color>",
  ui_story_1012_10121302_111_dialog_content = "<color=#e8d9bb>ピッ…</color>",
  ui_story_1012_10121302_112_dialog_content = "<color=#e8d9bb>ピッ…</color>",
  ui_story_1012_10121302_113_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1012_10121302_114_dialog_content = "…",
  ui_story_1012_10121401_1_dialog_content = "はぁ…はぁ…",
  ui_story_1012_10121401_2_dialog_content = "こいつ…",
  ui_story_1012_10121401_3_dialog_content = "（なんて力なの…）",
  ui_story_1012_10121401_4_dialog_content = "獲物よ、もう逃げられまい？",
  ui_story_1012_10121401_5_dialog_content = "あんたは飛べるんだから、\n疲れてなくて当然でしょ！",
  ui_story_1012_10121401_6_dialog_content = "それに、誰が逃げるって！？",
  ui_story_1012_10121401_7_dialog_content = "キキキッ、目に疲れが浮かんでいるぞ。\n危うい表情だ…",
  ui_story_1012_10121401_8_dialog_content = "狩りの時、最も楽しいのは\n獲物が疲れを見せる一瞬だ。",
  ui_story_1012_10121401_9_dialog_content = "もうすぐ獲物が手に入るという、この感覚…\n実に興奮してきたぞ！",
  ui_story_1012_10121401_10_dialog_content = "この変態ジジイ！",
  ui_story_1012_10121401_11_dialog_content = "くっ…",
  ui_story_1012_10121401_12_dialog_content = "キキキッ！逃げるがいい。走り続けろ！",
  ui_story_1012_10121401_13_dialog_content = "少しでも生き延びるために、\n最後まで命を燃やすのだ！",
  ui_story_1012_10121401_14_dialog_content = "私は逃げない…",
  ui_story_1012_10121401_15_dialog_content = "私は…女王の護衛なんだ！",
  ui_story_1012_10121401_16_dialog_content = "<color=#e8d9bb>ガシャン…バリン……</color>",
  ui_story_1012_10121401_17_dialog_content = "えっ？なに…",
  ui_story_1012_10121401_18_dialog_content = "<color=#e8d9bb>バリン！</color>",
  ui_story_1012_10121401_19_dialog_content = "ゲホ、ゲホ…ペッ…",
  ui_story_1012_10121401_20_dialog_content = "ふぅ…大丈夫？啓光の兵士さん。",
  ui_story_1012_10121401_21_dialog_content = "私は大丈夫です…なんとか出てこられました。",
  ui_story_1012_10121401_22_dialog_content = "ですが、気をつけてください…",
  ui_story_1012_10121401_23_dialog_content = "残念、残念。\nゲームが予定より早く終わってしまいました。",
  ui_story_1012_10121401_24_dialog_content = "私たちだけの小さな世界にいればいいではないですか？\nどうして命の危険を冒して、飛び出そうとするのですか？",
  ui_story_1012_10121401_25_dialog_content = "今のあなたたちでは、\n死に場所を変えたにすぎませんよ。",
  ui_story_1012_10121401_26_dialog_content = "ムカつく奴…",
  ui_story_1012_10121401_27_dialog_content = "あれ？そこにいるのは…北境の女王の護衛？",
  ui_story_1012_10121401_28_dialog_content = "あなたたち…",
  ui_story_1012_10121401_29_dialog_content = "まだ戦える？",
  ui_story_1012_10121401_30_dialog_content = "状況がかなり厳しいの…",
  ui_story_1012_10121401_31_dialog_content = "見て分かるわよ。\n空のあいつが敵の親玉でしょ？",
  ui_story_1012_10121401_32_dialog_content = "よくやった。ミレン、見事だ。",
  ui_story_1012_10121401_33_dialog_content = "獲物を一ヵ所に追い立てる。\nこれぞまさに、美しい狩りの戦略だ！",
  ui_story_1012_10121401_34_dialog_content = "気をつけて！",
  ui_story_1012_10121401_35_dialog_content = "強烈な暗力です…",
  ui_story_1012_10121401_36_dialog_content = "私たちに残された力では、次はもう…",
  ui_story_1012_10121401_37_dialog_content = "啓光の奴！後ろ！",
  ui_story_1012_10121401_38_dialog_content = "おっと、見つかってしまいましたか。",
  ui_story_1012_10121401_39_dialog_content = "くっ…",
  ui_story_1012_10121401_40_dialog_content = "（まずい…逃げられない）",
  ui_story_1012_10121401_41_dialog_content = "何もできず、歯がゆいという、その表情――",
  ui_story_1012_10121401_42_dialog_content = "甘えられているように見えますねぇ。",
  ui_story_1012_10121401_43_dialog_content = "変、態！",
  ui_story_1012_10121401_44_dialog_content = "空だ！空の奴も来るよ！",
  ui_story_1012_10121401_45_dialog_content = "うっ！？",
  ui_story_1012_10121401_46_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_1012_10121401_47_dialog_content = "うう…",
  ui_story_1012_10121401_48_dialog_content = "左手が…あがらない…",
  ui_story_1012_10121401_49_dialog_content = "うっ…いたた…",
  ui_story_1012_10121401_50_dialog_content = "ゲホッゲホッ…",
  ui_story_1012_10121401_51_dialog_content = "キキッ。苦しむ姿が実に哀れに思えてくるな。",
  ui_story_1012_10121401_52_dialog_content = "フィジェロ様、こいつらは下等な光霊にすぎません。\n同情には値しないかと。",
  ui_story_1012_10121401_53_dialog_content = "私はいつもこうなのだ。\nこいつらの目に浮かぶ消えゆく光を見ると、心が揺さぶられてしまう…",
  ui_story_1012_10121401_54_dialog_content = "敵に情けを見せるとは！\nフィジェロ様は実に偉大なお方です！",
  ui_story_1012_10121401_55_dialog_content = "偉大？安い賞賛で私を愚弄するな。",
  ui_story_1012_10121401_56_dialog_content = "だが…そうだな。\nこいつらにも情けをかけてやろう。",
  ui_story_1012_10121401_57_dialog_content = "苦痛を私の手で直々に終わらせてやる。",
  ui_story_1012_10121401_58_dialog_content = "それはまことか？",
  ui_story_1012_10121401_59_dialog_content = "何っ！？これは…",
  ui_story_1012_10121401_60_dialog_content = "情けをかけるには、\n相手を凌駕していなければな。",
  ui_story_1012_10121401_61_dialog_content = "そなたには到底できない話だ。",
  ui_story_1012_10121401_62_dialog_content = "北境の女王！！！貴様…",
  ui_story_1012_10121401_63_dialog_content = "ミケランジェロの奴はどうした？",
  ui_story_1012_10121401_64_dialog_content = "あれに私は止められぬ。",
  ui_story_1012_10121401_65_dialog_content = "おのれ！",
  ui_story_1012_10121401_66_dialog_content = "この戦いは光霊にとっても、\nそなたたちにとっても、等しく苦しいものであろう。",
  ui_story_1012_10121401_67_dialog_content = "そなたはもう十分に逃げ回った。",
  ui_story_1012_10121401_68_dialog_content = "だが、終わりが訪れる前に、\n遅かれ早かれ私と向き合うことになる。",
  ui_story_1012_10121401_69_dialog_content = "それがこの戦いのために、\nそなたが支払うべき代償なのだ。",
  ui_story_1012_10121401_70_dialog_content = "女王陛下！！！\n来てくださった！！！",
  ui_story_1012_10121401_71_dialog_content = "これが北境の女王、\n凄まじい力ね…",
  ui_story_1012_10121401_72_dialog_content = "そなたたちが限界であることは理解している。",
  ui_story_1012_10121401_73_dialog_content = "しかし、もうしばらく耐えてもらいたい。\n戦争はまだ続いている。",
  ui_story_1012_10121401_74_dialog_content = "空の末裔が戦局を変える一手を探している。\n我らは回帰の塔を死守し、空の末裔のために時を稼がなくてはならない。",
  ui_story_1012_10121401_75_dialog_content = "見るも無残な敗北のまま、\n終わりを迎えるわけにはいかないのだ。",
  ui_story_1012_10121401_76_dialog_content = "空の末裔…",
  ui_story_1012_10121401_77_dialog_content = "戦争の勝敗をあの軟弱な少年に託すというのですか？",
  ui_story_1012_10121401_78_dialog_content = "私はあの者を信じる。",
  ui_story_1012_10121401_79_dialog_content = "そなたたちにも信じてもらいたい。",
  ui_story_1012_10121401_80_dialog_content = "信じます！\n女王陛下が信じているのなら、当然！",
  ui_story_1012_10121401_81_dialog_content = "…",
  ui_story_1012_10121401_82_dialog_content = "そうですね。北境の女王のご判断なら、\n私の判断よりも価値があるでしょう。",
  ui_story_1012_10121401_83_dialog_content = "もともと諦めるつもりはなかったしね。",
  ui_story_1012_10121401_84_dialog_content = "だけど、心配なのは…",
  ui_story_1012_10121401_85_dialog_content = "私たちにこの塔を守るだけの余力があるかしら？",
  ui_story_1012_10121401_86_dialog_content = "そのことならば心配はない。",
  ui_story_1012_10121401_87_dialog_content = "白い塔の入口を守っているのは…\n戦争のために生まれてきた者だ。",
  ui_story_1012_10121401_88_dialog_content = "『撤退！早く、さがりなさい！』",
  ui_story_1012_10121401_89_dialog_content = "『最速で、できる限り遠くまで！』",
  ui_story_1012_10121401_90_dialog_content = "『ノラ様、フィジェロ様の命令では、\n代償は惜しまず攻撃せよとのことでしたが…』",
  ui_story_1012_10121401_91_dialog_content = "『なぜ…』",
  ui_story_1012_10121401_92_dialog_content = "『私が撤退しろと言っている！今すぐに！！！』",
  ui_story_1012_10121401_93_dialog_content = "『ノラ様？』",
  ui_story_1012_10121401_94_dialog_content = "『少なくとも今は、撤退しなさい！』",
  ui_story_1012_10121401_95_dialog_content = "『お前たちの任務は攻撃すること、\nムダ死にすることではない！』",
  ui_story_1012_10121401_96_dialog_content = "<color=#e8d9bb>ドン！ゴゴゴゴ…！！！</color>",
  ui_story_1012_10121401_97_dialog_content = "なっ！？",
  ui_story_1012_10121401_98_dialog_content = "塔の入口で何が！？",
  ui_story_1012_10121401_99_dialog_content = "な、何かが爆発したのでしょうか？",
  ui_story_1012_10121401_100_dialog_content = "…",
  ui_story_1012_10121401_101_dialog_content = "谷全体が揺れています…",
  ui_story_1012_10121401_102_dialog_content = "一体何が…",
  ui_story_1012_10121401_103_dialog_content = "…あれは武器だ。\nお前はとうの昔に目にしたことがあるだろう。",
  ui_story_1012_10121401_104_dialog_content = "目にしたことがある！？",
  ui_story_1012_10121401_105_dialog_content = "まさか…",
  ui_story_1012_10121401_106_dialog_content = "とうとう見られるようだな。\n啓光の大元帥の捨て身の戦い方を。",
  ui_story_1012_10121401_107_dialog_content = "私は興奮するべきか、\nそれとも恐れおののくべきか…？",
  ui_story_1012_10121401_108_dialog_content = "…敵はどこに行った？",
  ui_story_1012_10121401_109_dialog_content = "不思議なものだな…なぜ戦場に\nこれほど間が空いている？",
  ui_story_1012_10121401_110_dialog_content = "まさか、貴様ら醜い生物にとっても…",
  ui_story_1012_10121401_111_dialog_content = "死とは恐怖に値することなのか？",
  ui_story_1012_10121401_112_dialog_content = "…",
  ui_story_1012_10121401_113_dialog_content = "レインハト、そんな力の使い方じゃ、\n自分を傷つけるわよ。",
  ui_story_1012_10121401_114_dialog_content = "フ、何を言うか。ここは戦場だ。",
  ui_story_1012_10121401_115_dialog_content = "そもそも、五体満足で帰りたいと思ったことなどない。",
  ui_story_1012_10121401_116_dialog_content = "力は温存しておいて、他の人を連れて\n囲みを突破した方が賢明よ。",
  ui_story_1012_10121401_117_dialog_content = "まだ分かっていないようだな。",
  ui_story_1012_10121401_118_dialog_content = "これは勝利するまで守り続ける戦争だ。",
  ui_story_1012_10121401_119_dialog_content = "包囲の突破など、選択肢にない。",
  ui_story_1012_10121401_120_dialog_content = "…",
  ui_story_1012_10121401_121_dialog_content = "やっぱりお互い、分かり合えないようね。",
  ui_story_1012_10121401_122_dialog_content = "昔からそうだったではないか。",
  ui_story_1012_10121401_123_dialog_content = "あなたは自分を燃やすことを選んだ。",
  ui_story_1012_10121401_124_dialog_content = "それなら、燃え尽きるまで見させてもらうわ。",
  ui_story_1012_10121401_125_dialog_content = "その意気だ。",
  ui_story_1012_10121401_126_dialog_content = "これで最後の戦いになるだろう。",
  ui_story_1012_10121401_127_dialog_content = "…",
  ui_story_1012_10121401_128_dialog_content = "『すべての暗鬼は回帰の塔に向けて攻撃せよ。』",
  ui_story_1012_10121401_129_dialog_content = "ふぅ…はぁ…",
  ui_story_1012_10121401_130_dialog_content = "グアアッ！",
  ui_story_1012_10121401_131_dialog_content = "まだ…これほどの暗鬼が…",
  ui_story_1012_10121401_132_dialog_content = "PlayerNameには…近づかせない！",
  ui_story_1012_10121401_133_dialog_content = "うっ…！",
  ui_story_1012_10121401_134_dialog_content = "左腕が…まだいいわ。槍の扱いには支障ない…",
  ui_story_1012_10121401_135_dialog_content = "PlayerName、残りの暗鬼は？\nいつになったら…",
  ui_story_1012_10121401_136_dialog_content = "…今は聞こえないのだったわね…",
  ui_story_1012_10121401_137_dialog_content = "順調に行っているかしら…",
  ui_story_1012_10121401_138_dialog_content = "私に稼げる時間は…もう多くない。",
  ui_story_1012_10121401_139_dialog_content = "うあああああああ！！",
  ui_story_1012_10121401_140_dialog_content = "<color=#e8d9bb>バンッ！</color>",
  ui_story_1012_10121401_141_dialog_content = "イテッ、手が…！",
  ui_story_1012_10121401_142_dialog_content = "こうやって拳で叩いて…\nそもそも効果あるのかな？",
  ui_story_1012_10121401_143_dialog_content = "…",
  ui_story_1012_10121401_144_dialog_content = "しまった！右側だ…",
  ui_story_1012_10121401_145_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_1012_10121401_146_dialog_content = "ゴホッ…ゴホッ…",
  ui_story_1012_10121401_147_dialog_content = "ダメだ。まだ終わらない…また来る…",
  ui_story_1012_10121401_148_dialog_content = "…",
  ui_story_1012_10121401_149_dialog_content = "一点集中の素早い攻撃…さっき見たよ。",
  ui_story_1012_10121401_150_dialog_content = "こっちも集中して…",
  ui_story_1012_10121401_151_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_1012_10121401_152_dialog_content = "ふぅ…避けられた…！",
  ui_story_1012_10121401_153_dialog_content = "だけど…攻撃する余力なんて全然ない…",
  ui_story_1012_10121401_154_dialog_content = "避けるので精いっぱいだ。\nここまで時間稼ぎしかできてない…",
  ui_story_1012_10121401_155_dialog_content = "時間をムダにはできないのに…",
  ui_story_1012_10121401_156_dialog_content = "外の戦況は一刻を争うんだ。\nカレンだって、いつまでもあんなに大量の暗鬼を食い止めてはいられない。",
  ui_story_1012_10121401_157_dialog_content = "一刻も早く「律法の弦」を起動しないと！",
  ui_story_1012_10121401_158_dialog_content = "だけど、どうすれば…",
  ui_story_1012_10121401_159_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_1012_10121401_160_dialog_content = "また来た！",
  ui_story_1012_10121401_161_dialog_content = "うっ…両足がふらついてきた…",
  ui_story_1012_10121401_162_dialog_content = "こいつらがいる限り、僕は何もできない…",
  ui_story_1012_10121401_163_dialog_content = "そうだ。どうにかして、倒さないと。",
  ui_story_1012_10121401_164_dialog_content = "もう1回やってみよう…",
  ui_story_1012_10121401_165_dialog_content = "ええい！！！",
  ui_story_1012_10121401_166_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_1012_10121401_167_dialog_content = "…やっぱり痛い！",
  ui_story_1012_10121401_168_dialog_content = "でも…待てよ。\nここにいる僕は意識だけのはず！",
  ui_story_1012_10121401_169_dialog_content = "どんなに痛くても、\nきっと本当にケガをするわけじゃない！",
  ui_story_1012_10121401_170_dialog_content = "それなら、精神的な痛みに\n耐えればいいだけだ！",
  ui_story_1012_10121401_171_dialog_content = "そうだ。耐えればいいんだ。",
  ui_story_1012_10121401_172_dialog_content = "1回でダメなら、\n100回でも、1万回でも殴ってやる…",
  ui_story_1012_10121401_173_dialog_content = "こいつらがスクラップになるまで！",
  ui_story_1012_10121401_174_option_content = "拳を繰り出す",
  ui_story_1012_10121401_175_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_1012_10121401_176_dialog_content = "うっ…",
  ui_story_1012_10121401_177_option_content = "拳を繰り出す",
  ui_story_1012_10121401_178_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_1012_10121401_179_dialog_content = "耐えろ…耐えるんだ…",
  ui_story_1012_10121401_180_option_content = "拳を繰り出す",
  ui_story_1012_10121401_181_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_1012_10121401_182_dialog_content = "マズい。指の感覚がなくなった…拳を握れない…",
  ui_story_1012_10121401_183_dialog_content = "…意識空間でそこまでリアルにする必要あるのかな？",
  ui_story_1012_10121401_184_dialog_content = "まぁ、関係ないや。\n腕ならもう1本あるんだ…",
  ui_story_1012_10121401_185_option_content = "拳を繰り出す",
  ui_story_1012_10121401_186_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_1012_10121401_187_dialog_content = "こいつ…一体どれだけ硬いんだ！",
  ui_story_1012_10121401_188_option_content = "拳を繰り出す",
  ui_story_1012_10121401_189_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_1012_10121401_190_dialog_content = "そろそろ効果が…",
  ui_story_1012_10121401_191_dialog_content = "！！！",
  ui_story_1012_10121401_192_dialog_content = "もう一体いるのを忘れてた…",
  ui_story_1012_10121401_193_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_1012_10121401_194_dialog_content = "…うぅ…",
  ui_story_1012_10121401_195_dialog_content = "力が出ない…体が…動かない…",
  ui_story_1012_10121401_196_dialog_content = "やっぱり僕じゃ…\nどうやっても勝てないのかな…",
  ui_story_1012_10121401_197_dialog_content = "（今になって、急に回帰の塔の「命令」を理解できた気がした）",
  ui_story_1012_10121401_198_dialog_content = "（それが雲の上の存在、手出しできないものだと分かった）",
  ui_story_1012_10121401_199_dialog_content = "（決して口先で警告するだけの権威じゃない）",
  ui_story_1012_10121401_200_dialog_content = "（空の末裔の最大の弱み、\n生まれ持った欠陥を握っている）",
  ui_story_1012_10121401_201_dialog_content = "（どんな意志や知恵も、その前では的外れだ）",
  ui_story_1012_10121401_202_dialog_content = "（「命令」を守るのはただ1つのもの――力だけ。\n反論も許されない力でその権威を守っている）",
  ui_story_1012_10121401_203_dialog_content = "（それは空の末裔が生まれながらにして逆らえないもの…）",
  ui_story_1012_10121401_204_dialog_content = "（空の末裔という種族にはめられた、先天的な鎖なんだ）",
  ui_story_1012_10121401_205_dialog_content = "…",
  ui_story_1012_10121401_206_dialog_content = "みんな、ごめん。僕は…",
  ui_story_1012_10121401_207_dialog_content = "弱気になってるのは誰！？",
  ui_story_1012_10121401_208_dialog_content = "！！！",
  ui_story_1012_10121401_209_dialog_content = "バイス！？",
  ui_story_1012_10121401_210_dialog_content = "アイツの攻撃、やっかいそうね！",
  ui_story_1012_10121401_211_dialog_content = "あなたは隠れていて。まだ新しい武器に慣れていないから、\n守ってあげられないかもしれないわ。",
  ui_story_1012_10121401_212_dialog_content = "本当にバイスだ！！！",
  ui_story_1012_10121401_213_dialog_content = "バイス、目が覚めたの？\nどうしてここに？",
  ui_story_1012_10121401_214_dialog_content = "質問が多いわね。\n何から答えればいいのか分からないわ。",
  ui_story_1012_10121401_215_dialog_content = "まずは簡単な問題から片付けましょ。\n目の前のアレに勝てばいいのよね？",
  ui_story_1012_10121401_216_dialog_content = "そうだよ！",
  ui_story_1012_10121401_217_dialog_content = "だったら、何をモタモタしてるの？",
  ui_story_1012_10121401_218_dialog_content = "PlayerName、私を指揮して！",
  ui_story_1012_10121402_1_dialog_content = "2体いようと、これでおしまいよ！",
  ui_story_1012_10121402_2_dialog_content = "まずは大きい方から！",
  ui_story_1012_10121402_3_dialog_content = "ガシャッ…",
  ui_story_1012_10121402_4_dialog_content = "避けないのが悪いのよ。",
  ui_story_1012_10121402_5_dialog_content = "私の矢は防げないんだから！",
  ui_story_1012_10121402_6_dialog_content = "バイス！危ない…",
  ui_story_1012_10121402_7_dialog_content = "分かってる！右でしょ！",
  ui_story_1012_10121402_8_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_1012_10121402_9_dialog_content = "えっ、どうして知ってるの？",
  ui_story_1012_10121402_10_dialog_content = "1体しか残ってないなら、後は簡単ね！",
  ui_story_1012_10121402_11_dialog_content = "何本受け止められるかしら？",
  ui_story_1012_10121402_12_dialog_content = "ガシャッ…",
  ui_story_1012_10121402_13_dialog_content = "やった…！2体とも倒した！",
  ui_story_1012_10121402_14_dialog_content = "すごいよ、バイス！！！",
  ui_story_1012_10121402_15_dialog_content = "ふぅ…結構やっかいだったわね。",
  ui_story_1012_10121402_16_dialog_content = "身体が前のままだったら、\n勝てなかったかもしれないわ。",
  ui_story_1012_10121402_17_dialog_content = "あっ、そうだよ。どうしてここにいるの？\nここって空の末裔しか入れないんじゃないの？",
  ui_story_1012_10121402_18_dialog_content = "それとも、君はやっぱりバイスじゃなくて、\n僕の想像が作りだした幻とか…",
  ui_story_1012_10121402_19_dialog_content = "本物のバイスよ！\n決まってるでしょ！！！",
  ui_story_1012_10121402_20_dialog_content = "自由に「バイス」を想像で作り出して、\n助けてもらえる能力でもあると思ってるの？",
  ui_story_1012_10121402_21_dialog_content = "まぁ、そうだよね…。で、どうやってここに来たの？\n何が何だかさっぱりだよ。",
  ui_story_1012_10121402_22_dialog_content = "簡単に言うと…",
  ui_story_1012_10121402_23_dialog_content = "私が目を覚ましてすぐ、\nあなたが助けを必要としてるって真っ先に感じたの。",
  ui_story_1012_10121402_24_dialog_content = "えっ？",
  ui_story_1012_10121402_25_dialog_content = "私もどうしてだか分からないけど、\n意識がつながったみたいね。",
  ui_story_1012_10121402_26_dialog_content = "あなたの不安とか焦りとか、\nどこにいるかまで感じられたの。",
  ui_story_1012_10121402_27_dialog_content = "あなたの前まで来て、体に触れたら、\n自分の意識が引っ張られるような感じがして、ここにいたってわけ。",
  ui_story_1012_10121402_28_dialog_content = "その後のことは見ての通りよ。",
  ui_story_1012_10121402_29_dialog_content = "意識がつながった？",
  ui_story_1012_10121402_30_dialog_content = "私もどうやったのか分からないわ。",
  ui_story_1012_10121402_31_dialog_content = "だけど、細かいことは後にしましょ！",
  ui_story_1012_10121402_32_dialog_content = "この塔の最終兵器を起動させるんでしょ？\nカレンから聞いたわ。",
  ui_story_1012_10121402_33_dialog_content = "早くやりましょ！",
  ui_story_1012_10121402_34_dialog_content = "うん、そうだね！",
  ui_story_1012_10121402_35_dialog_content = "「コアリング権限」を奪うって聞いたけど、\nこの空間のどこかにあるのかな？",
  ui_story_1012_10121402_36_option_content = "強制感知",
  ui_story_1012_10121402_37_dialog_content = "<color=#e8d9bb>ビュン！</color>",
  ui_story_1012_10121402_38_dialog_content = "あれ？これは…",
  ui_story_1012_10121402_39_dialog_content = "（僕の意識が空間全体に溶け込んで…）",
  ui_story_1012_10121402_40_dialog_content = "（僕は、空間と1つになった）",
  ui_story_1012_10121402_41_dialog_content = "（これまでにない心地よさを感じた。まるで…）",
  ui_story_1012_10121402_42_dialog_content = "（果てしない大空を漂っているかのような…）",
  ui_story_1012_10121402_43_dialog_content = "（遮るものは何もない。世界の万物が足下に広がっている）",
  ui_story_1012_10121402_44_dialog_content = "どう？何か見つかった？",
  ui_story_1012_10121402_45_dialog_content = "何もないみたい…ここ、僕たちと\nスクラップになった防衛システム2体以外に、何もないよ。",
  ui_story_1012_10121402_46_dialog_content = "そもそも、何を探せばいいのかすら\n分かってないし…",
  ui_story_1012_10121402_47_dialog_content = "はぁ、サブブレーンがいてくれれば…",
  ui_story_1012_10121402_48_dialog_content = "何をすればよろしいでしょうか？",
  ui_story_1012_10121402_49_dialog_content = "え！？",
  ui_story_1012_10121402_50_dialog_content = "ほ、本当に出てきた！",
  ui_story_1012_10121402_51_dialog_content = "さっきはいくら呼んでも反応しなかったのに！",
  ui_story_1012_10121402_52_dialog_content = "サブブレーンは「コアリング」に触れることが\n許可されていないからです。",
  ui_story_1012_10121402_53_dialog_content = "じゃあ、今はどうして大丈夫なの？",
  ui_story_1012_10121402_54_dialog_content = "「命令」の要求に応えたからです。",
  ui_story_1012_10121402_55_dialog_content = "「命令」はサブブレーンに対し、今ここに現れてほしいとリクエストしました。\nサブブレーンは命令に従います。",
  ui_story_1012_10121402_56_dialog_content = "「命令」が？",
  ui_story_1012_10121402_57_dialog_content = "君に出てきて欲しいって願ってたのは\n僕じゃないの？",
  ui_story_1012_10121402_58_dialog_content = "そうです。",
  ui_story_1012_10121402_59_dialog_content = "現在は、あなたが「命令」です。",
  ui_story_1012_10121402_60_dialog_content = "え！？",
  ui_story_1012_10121402_61_dialog_content = "あなたの意識は「コアリング」と融合しています。",
  ui_story_1012_10121402_62_dialog_content = "「コアリング」は「命令」の媒体です。\nそのため、あなたが「命令」となりました。",
  ui_story_1012_10121402_63_dialog_content = "命令の要求には必ず従います。\nつまり、あなたの望みを必ず叶えます。",
  ui_story_1012_10121402_64_dialog_content = "何をすればよろしいでしょうか？",
  ui_story_1012_10121402_65_dialog_content = "僕自身が…ずっとジャマされてきた「命令」になったの？",
  ui_story_1012_10121402_66_dialog_content = "じゃあ、「律法の弦」を起動させたい。",
  ui_story_1012_10121402_67_dialog_content = "命令を受信しました。\n「律法の弦」プログラム、起動。",
  ui_story_1012_10121402_68_dialog_content = "起動パラメーターおよび\n実行すべき「律法」を入力してください。",
  ui_story_1012_10121402_69_dialog_content = "えっ？どういうこと？",
  ui_story_1012_10121402_70_dialog_content = "「律法の弦」は精密な兵器です。",
  ui_story_1012_10121402_71_dialog_content = "起動には、攻撃範囲、攻撃目標、\n攻撃時間などを明確にしなくてはなりません。",
  ui_story_1012_10121402_72_dialog_content = "期待通りの効果を実現するため、\n必要な手順です。",
  ui_story_1012_10121402_73_dialog_content = "だけど、何を入力すればいいのか分からないよ！",
  ui_story_1012_10121402_74_dialog_content = "ここのシステムなんて、\n僕が知っているものとは全然違うんだから！",
  ui_story_1012_10121402_75_dialog_content = "これは必要な手順です。\n起動パラメーターおよび実行すべき「律法」を入力してください。",
  ui_story_1012_10121402_76_dialog_content = "じゃあ…回帰の塔の近くにいる暗鬼を全部攻撃して。\nこれでいい？",
  ui_story_1012_10121402_77_dialog_content = "申し訳ありません。範囲があいまいすぎます。\n「律法の弦」は精密な兵器です。",
  ui_story_1012_10121402_78_dialog_content = "じゃあどうすればいいの！？",
  ui_story_1012_10121402_79_dialog_content = "ここまでやっておいて、\nそんな理由で起動できないなんてことないでしょ？",
  ui_story_1012_10121402_80_dialog_content = "「律法の弦」に事前設定されているパラメーターを検出しました。\nこのまま使用すれば、初期化を完了できます。",
  ui_story_1012_10121402_81_dialog_content = "この操作を実行しますか？",
  ui_story_1012_10121402_82_dialog_content = "事前設定されたパラメーター？",
  ui_story_1012_10121402_83_dialog_content = "報告します。未登録の暗鬼が回帰の塔に侵入しました。",
  ui_story_1012_10121402_84_dialog_content = "数が非常に多いため、正確なカウントは行えません。",
  ui_story_1012_10121402_85_dialog_content = "まずい…外側が抑えられなくなったんだ！",
  ui_story_1012_10121402_86_dialog_content = "時間がない！これ以上時間を無駄にできない…",
  ui_story_1012_10121402_87_dialog_content = "サブブレーン！\nパラメーターを事前設定したのは誰か分かる？",
  ui_story_1012_10121402_88_dialog_content = "検索中…",
  ui_story_1012_10121402_89_dialog_content = "登録者は「フランシス」です。",
  ui_story_1012_10121402_90_dialog_content = "やっぱり…",
  ui_story_1012_10121402_91_dialog_content = "報告します。未登録の暗鬼が回帰の塔に侵入しました。",
  ui_story_1012_10121402_92_dialog_content = "数が非常に多いため、正確に…",
  ui_story_1012_10121402_93_dialog_content = "その時の攻撃目標は誰！？",
  ui_story_1012_10121402_94_dialog_content = "最後の質問だけ、確認させて！\n「律法の弦」の前回の攻撃目標は？",
  ui_story_1012_10121402_95_dialog_content = "過去のデータを検索…",
  ui_story_1012_10121402_96_dialog_content = "確認しました。前回設定された攻撃目標は暗鬼です。",
  ui_story_1012_10121402_97_dialog_content = "わかった。",
  ui_story_1012_10121402_98_dialog_content = "（フランシス先生…信じていいんだよね？）",
  ui_story_1012_10121402_99_dialog_content = "サブブレーン、事前設定のパラメーターに従って「律法の弦」を起動して！",
  ui_story_1012_10121402_100_dialog_content = "命令を受信しました。",
  ui_story_1012_10121402_101_dialog_content = "起動パラメーターを初期化。\n過去のデータを使用します。",
  ui_story_1012_10121402_102_dialog_content = "攻撃目標設定――暗鬼。",
  ui_story_1012_10121402_103_dialog_content = "すべての暗鬼の権限を「追放」に変更します。",
  ui_story_1012_10121402_104_dialog_content = "実行予定の「律法」――<color=#FFB400>「永遠に回帰の塔へ近づいてはならない」</color>",
  ui_story_1012_10121402_105_dialog_content = "初期化が完了しました。",
  ui_story_1012_10121402_106_dialog_content = "「律法の弦」、起動。",
  ui_story_1012_10121402_107_dialog_content = "何だ！？",
  ui_story_1012_10121402_108_dialog_content = "塔全体が光り出したぞ！？",
  ui_story_1012_10121402_109_dialog_content = "夜明けだ。ついに訪れた。",
  ui_story_1012_10121402_110_dialog_content = "ハハハ！あいつならやり遂げると言っただろう！",
  ui_story_1012_10121402_111_dialog_content = "皆、急げ！眺めのいい場所を探すとしよう！",
  ui_story_1012_10121402_112_dialog_content = "しかと見物させてもらおうではないか！",
  ui_story_1012_10121402_113_dialog_content = "おい、どうなっている？",
  ui_story_1012_10121402_114_dialog_content = "この塔は何をしようとしている！？",
  ui_story_1012_10121402_115_dialog_content = "まさか…",
  ui_story_1012_10121402_116_dialog_content = "まずいわ…",
  ui_story_1012_10121402_117_dialog_content = "…",
  ui_story_1012_10121402_118_dialog_content = "ガァ…",
  ui_story_1012_10121402_119_dialog_content = "どうして暗鬼が止まったのですか！？",
  ui_story_1012_10121402_120_dialog_content = "さがるな！攻撃を続けなさい！",
  ui_story_1012_10121402_121_dialog_content = "もうすぐ敵の守りを破れるんですよ！？",
  ui_story_1012_10121402_122_dialog_content = "ガァ…",
  ui_story_1012_10121402_123_dialog_content = "くっ！",
  ui_story_1012_10121402_124_dialog_content = "フィジェロ様、こいつらは…",
  ui_story_1012_10121402_125_dialog_content = "うっ…ぐっ…",
  ui_story_1012_10121402_126_dialog_content = "フィ、フィジェロ様？",
  ui_story_1012_10121402_127_dialog_content = "バカな…そんな…",
  ui_story_1012_10121402_128_dialog_content = "フィジェロ様、攻撃をやめるのですか？",
  ui_story_1012_10121402_129_dialog_content = "…",
  ui_story_1012_10121402_130_dialog_content = "退け。全軍撤退だ…",
  ui_story_1012_10121402_131_dialog_content = "ですが、なぜ…",
  ui_story_1012_10121402_132_dialog_content = "言っただろう！撤退だ！\n聞こえなかったか！？",
  ui_story_1012_10121402_133_dialog_content = "は、はい…",
  ui_story_1012_10121402_134_dialog_content = "撤退だ…撤退するしかない…",
  ui_story_1012_10121402_135_dialog_content = "私の心に…\n攻撃しようという考えが湧いてこない…",
  ui_story_1012_10121402_136_dialog_content = "私の意識が、私を退かせようとしている…",
  ui_story_1012_10121402_137_dialog_content = "どうやっても…自分に…抗えない…",
  ui_story_1012_10121402_138_dialog_content = "撤退している！暗鬼が全て！",
  ui_story_1012_10121402_139_dialog_content = "おかしいですね…常識では考えられません。\nどうして勝利を目前にして諦めるのでしょうか？",
  ui_story_1012_10121402_140_dialog_content = "先ほどの白い塔が放った光のせいでしょうか？",
  ui_story_1012_10121402_141_dialog_content = "後でPlayerNameに聞いてみるといい。\nあいつなら分かっているだろう。",
  ui_story_1012_10121402_142_dialog_content = "はぁ…死ぬほど疲れた。\n草むらに寝転びたい気分だ。",
  ui_story_1012_10121402_143_dialog_content = "敵の再攻撃に備えなくてよろしいのでしょうか？",
  ui_story_1012_10121402_144_dialog_content = "残っている暗鬼の数だけでも、\n天空ノ谷を包囲されれば非常に厳しい状況ですが…",
  ui_story_1012_10121402_145_dialog_content = "安心しろ。やつらの作戦は\n各地からの大部隊が到着する前に回帰の塔を占領することだった。",
  ui_story_1012_10121402_146_dialog_content = "その作戦自体が成り立たなくなった以上、ここにいても的になるだけだ。\nあいつらとて、そこまでバカなマネはするまい。",
  ui_story_1012_10121402_147_dialog_content = "さすがは大元帥、勉強になります。",
  ui_story_1012_10121402_148_dialog_content = "今のうちにゆっくり休むとしよう…",
  ui_story_1012_10121402_149_dialog_content = "私の推測が正しければ、\nこの後で戦いより疲れることが待っているからな。",
  ui_story_1012_10121402_150_dialog_content = "やった！\n僕たち、やったんだ！！！",
  ui_story_1012_10121402_151_dialog_content = "うまくいったの？\n外で何が起きたの…？",
  ui_story_1012_10121402_152_dialog_content = "暗鬼が全部撤退したんだよ！",
  ui_story_1012_10121402_153_dialog_content = "あの様子からすると、\n暗鬼は「律法の弦」が設定した「律法」に従ったんだろうね。",
  ui_story_1012_10121402_154_dialog_content = "「永遠に回帰の塔へ近づいてはならない」っていう…",
  ui_story_1012_10121402_155_dialog_content = "暗鬼に何でも命令できるっていうこと！？",
  ui_story_1012_10121402_156_dialog_content = "不思議すぎるわ…",
  ui_story_1012_10121402_157_dialog_content = "「律法の弦」の動きを感じられる。\nいかにも空の末裔らしい兵器だね…",
  ui_story_1012_10121402_158_dialog_content = "力に頼るんじゃなくて、\nあらゆる敵の脳内に強い意識を植え付けるんだ。",
  ui_story_1012_10121402_159_dialog_content = "暴力による争いを飛ばして、\nその根元にある、思考から戦争を終わらせる…",
  ui_story_1012_10121402_160_dialog_content = "怖いぐらいに強い力だ…",
  ui_story_1012_10121402_161_dialog_content = "あら？どうしたのかしら？",
  ui_story_1012_10121402_162_dialog_content = "この空間が不安定になってるみたいだ…",
  ui_story_1012_10121402_163_dialog_content = "報告します。回帰の塔のエネルギー残量がわずかです。",
  ui_story_1012_10121402_164_dialog_content = "消耗性の部品の多くが「律法の弦」起動後に破損しました。\n今すぐ交換が必要です。",
  ui_story_1012_10121402_165_dialog_content = "塔内の修理作業員を検索しています…",
  ui_story_1012_10121402_166_dialog_content = "検索できませんでした。",
  ui_story_1012_10121402_167_dialog_content = "エネルギー切れ…",
  ui_story_1012_10121402_168_dialog_content = "運が良かったというべきかな。\n「律法の弦」が発動するまで持ちこたえたんだから…",
  ui_story_1012_10121402_169_dialog_content = "もしあれがなければ、\n僕たちは今頃どうなっていたことか…",
  ui_story_1012_10121402_170_dialog_content = "運転を維持するエネルギー供給が不足しています。",
  ui_story_1012_10121402_171_dialog_content = "回帰の塔は沈黙状態に移行します。",
  ui_story_1012_10121402_172_dialog_content = "えっ？それって？",
  ui_story_1012_10121402_173_dialog_content = "すべての設備が運転を停止し、\n全機能が使用不能になります。",
  ui_story_1012_10121402_174_dialog_content = "あなたの来訪時よりも静かになるでしょう。",
  ui_story_1012_10121402_175_dialog_content = "そうなんだ…",
  ui_story_1012_10121402_176_dialog_content = "待って。サブブレーン、まさか君も…",
  ui_story_1012_10121402_177_dialog_content = "サブブレーンも空の末裔の\nサポートが行えなくなります。",
  ui_story_1012_10121402_178_dialog_content = "…",
  ui_story_1012_10121402_179_dialog_content = "サブブレーンの最後のタスクを実行します。",
  ui_story_1012_10121402_180_dialog_content = "フランシス先生からの伝言です。\n沈黙状態へ移行する前に再生します。",
  ui_story_1012_10121402_181_dialog_content = "フランシス先生から！？",
  ui_story_1012_10121402_182_dialog_content = "「同じ空の末裔の君へ――」",
  ui_story_1012_10121402_183_dialog_content = "「やっぱり、メッセージ再生のタイミングは\n最後に設定しておこう。」",
  ui_story_1012_10121402_184_dialog_content = "「悲しい会話は嫌いだ。\nそれより、勝利を祝う方が合っている。」",
  ui_story_1012_10121402_185_dialog_content = "「誰かがこのメッセージを聞くところを\n想像するだけでワクワクするよ。」",
  ui_story_1012_10121402_186_dialog_content = "「でも、なんとむなしい喜びだろう。はるか遠い未来…\nまだ存在もしていない誰かが望みを叶えてくれることに期待しているのだから。」",
  ui_story_1012_10121402_187_dialog_content = "「もしかすると私たちが歩んでいる道は、\n他に誰も訪れないようなものかもしれない…」",
  ui_story_1012_10121402_188_dialog_content = "僕たちが同じ道を歩んでいる？",
  ui_story_1012_10121402_189_dialog_content = "「君は何が起きているのかを理解していなかったり、\n自分が幸運だったと思っていたりするかもしれない。」",
  ui_story_1012_10121402_190_dialog_content = "「だが、これだけは言いたい。\nすべての物事には、理由があると信じるべきだ。」",
  ui_story_1012_10121402_191_dialog_content = "「ちなみに、エネルギーが尽きようとしているのは、\n律法の弦の一撃でちょうど空になるように設定しておいたからだ」",
  ui_story_1012_10121402_192_dialog_content = "「これは私からのプレゼントだ。」",
  ui_story_1012_10121402_193_dialog_content = "プレゼント？",
  ui_story_1012_10121402_194_dialog_content = "「暗鬼と戦う上で役に立つだろう。」",
  ui_story_1012_10121402_195_dialog_content = "「そして君にかけられた<color=#FFB400>先天的</color>な鎖を打ち砕くことを助けてくれる。」",
  ui_story_1012_10121402_196_dialog_content = "！！！",
  ui_story_1012_10121402_197_dialog_content = "「時間だ。」",
  ui_story_1012_10121402_198_dialog_content = "「最後に、君がこの道を歩んでくれたことに、感謝している。」",
  ui_story_1012_10121402_199_dialog_content = "「去りゆくものは、いずれ必ず去り、\n残るべきものは、永遠に残る。」",
  ui_story_1012_10121402_200_dialog_content = "「おやすみ、空の末裔。」",
  ui_story_1012_10121501_1_dialog_content = "あぁ、よかった――",
  ui_story_1012_10121501_2_dialog_content = "天空ノ谷は僕が知ってる姿のままだ。",
  ui_story_1012_10121501_3_dialog_content = "ここには平和な光景が一番似合うわね。",
  ui_story_1012_10121501_4_dialog_content = "カレン、もうへとへとみたいね。\n私の腕につかまって。",
  ui_story_1012_10121501_5_dialog_content = "私は自分で…",
  ui_story_1012_10121501_6_dialog_content = "大丈夫よ。PlayerNameから聞いたけど、\n私が気を失っている間、ずっと背負っててくれたんでしょ？",
  ui_story_1012_10121501_7_dialog_content = "今度は私の番よ！",
  ui_story_1012_10121501_8_dialog_content = "…",
  ui_story_1012_10121501_9_dialog_content = "分かったわ。",
  ui_story_1012_10121501_10_dialog_content = "大英雄たちがやっとお出ましのようだな。",
  ui_story_1012_10121501_11_dialog_content = "そ、そんな、恥ずかしいですよ…",
  ui_story_1012_10121501_12_dialog_content = "恥ずかしがることはない。\nどれほど大きな戦争を逆転に導いたのか、考えてもみろ。",
  ui_story_1012_10121501_13_dialog_content = "啓光の大元帥と北境の女王が力を合わせても\n勝てない戦争だったのだぞ。",
  ui_story_1012_10121501_14_dialog_content = "僕のおかげで逆転できたわけでもないですよね？",
  ui_story_1012_10121501_15_dialog_content = "僕はただ…",
  ui_story_1012_10121501_16_dialog_content = "これは私からのプレゼントだ。",
  ui_story_1012_10121501_17_dialog_content = "うん…僕はただ、人助けをしただけです。",
  ui_story_1012_10121501_18_dialog_content = "人助け？謙虚なのはいいが、\nずいぶん持って回った言い方だな。",
  ui_story_1012_10121501_19_dialog_content = "アハハ…とにかく、皆で必死に戦ったんです。",
  ui_story_1012_10121501_20_dialog_content = "僕だけじゃなくて、\n皆で一緒に逆転した戦争です。",
  ui_story_1012_10121501_21_dialog_content = "それも間違いではないな。",
  ui_story_1012_10121501_22_dialog_content = "勝利は全員のもの。\n戦士として持つべき姿勢だ！",
  ui_story_1012_10121501_23_dialog_content = "アハハハ…\nそうです、勝利は皆のものです！",
  ui_story_1012_10121501_24_dialog_content = "大元帥さんが言うと、やっぱり迫力がありますね！",
  ui_story_1012_10121501_25_dialog_content = "しかし、覚えておけ。\n私たちの中で、お前は唯一無二の存在なのだ。",
  ui_story_1012_10121501_26_dialog_content = "お前は起点であり、鍵であり、旗印でもある。\n変化をもたらす重要な役割を担っているのだ。",
  ui_story_1012_10121501_27_dialog_content = "これは賞賛と同時に警告でもある。",
  ui_story_1012_10121501_28_dialog_content = "「唯一無二」であることに対し、\n畏敬の念を忘れずに持ち続けてもらいたい。",
  ui_story_1012_10121501_29_dialog_content = "はい、忘れません。",
  ui_story_1012_10121501_30_dialog_content = "戻ってきたか。",
  ui_story_1012_10121501_31_dialog_content = "女王陛下！",
  ui_story_1012_10121501_32_dialog_content = "女王は戦場にいる時も今も、\nずっと落ち着いてますね。",
  ui_story_1012_10121501_33_dialog_content = "それもそうか…\n前もってどうなるかは見ていたはずですよね。",
  ui_story_1012_10121501_34_dialog_content = "…",
  ui_story_1012_10121501_35_dialog_content = "見ていない。",
  ui_story_1012_10121501_36_dialog_content = "えっ？",
  ui_story_1012_10121501_37_dialog_content = "そなたが戦局を逆転させる未来までは\n見ていなかった。",
  ui_story_1012_10121501_38_dialog_content = "そなたが何かをしようとするところまでしか見ていない。",
  ui_story_1012_10121501_39_dialog_content = "じゃあ…",
  ui_story_1012_10121501_40_dialog_content = "…",
  ui_story_1012_10121501_41_dialog_content = "そなたならできると信じていた。",
  ui_story_1012_10121501_42_dialog_content = "女王陛下…",
  ui_story_1012_10121501_43_dialog_content = "ぼ、僕、女王陛下を\nガッカリさせていませんよね…！？",
  ui_story_1012_10121501_44_dialog_content = "この天空ノ谷がそなたの答えだ。",
  ui_story_1012_10121501_45_dialog_content = "そういえば、PlayerName。\nひとつ大事な質問がある。",
  ui_story_1012_10121501_46_dialog_content = "一体何をしたのだ？",
  ui_story_1012_10121501_47_dialog_content = "暗鬼が一瞬にして回帰の塔への攻撃を止め、\n尻尾を巻いて逃げだした。",
  ui_story_1012_10121501_48_dialog_content = "「最終兵器」とは聞いたが、\nそのような兵器はついぞ見なかった。",
  ui_story_1012_10121501_49_dialog_content = "実は、僕にもよく分からないんです。",
  ui_story_1012_10121501_50_dialog_content = "僕の感じたことから推測する限り、\nあれは精神に作用する兵器みたいなんです。",
  ui_story_1012_10121501_51_dialog_content = "敵の体を攻撃するんじゃなくて、\n意識を攻撃するんです。",
  ui_story_1012_10121501_52_dialog_content = "「回帰の塔に近づいてはいけない」っていう命令が\n敵の意識に植え付けられて、撤退していったんだと思います。",
  ui_story_1012_10121501_53_dialog_content = "意識を植え付ける？\nこの世にそのような兵器があるのか…？",
  ui_story_1012_10121501_54_dialog_content = "僕も不思議に思っていて…",
  ui_story_1012_10121501_55_dialog_content = "これは一大事だな。原理も分からず、凄まじい威力を持つ兵器…\nこの世界にとって、どのような意味を持つか分かるか？",
  ui_story_1012_10121501_56_dialog_content = "日蝕よりも恐ろしいものかもしれん。",
  ui_story_1012_10121501_57_dialog_content = "あっ…そのことなら、\nあまり心配しなくても大丈夫だと思います…",
  ui_story_1012_10121501_58_dialog_content = "もう完全に壊れちゃったみたいなので…",
  ui_story_1012_10121501_59_dialog_content = "壊れただと？",
  ui_story_1012_10121501_60_dialog_content = "ええと、色々あって、\n回帰の塔には最終兵器を1回起動させる力しか残されてなくて…",
  ui_story_1012_10121501_61_dialog_content = "兵器も回帰の塔も、動かなくなりました。",
  ui_story_1012_10121501_62_dialog_content = "元々この時代のものではなくて、ちょっとした願いごとのために、\n今まで残されてきたにすぎないものだったみたいなんです。",
  ui_story_1012_10121501_63_dialog_content = "願いが叶って、本来の姿に戻ったってことなんだと思います。",
  ui_story_1012_10121501_64_dialog_content = "自分のものではない時代に残された、\n何も言わない歴史の証人に…",
  ui_story_1012_10121501_65_dialog_content = "なるほど。",
  ui_story_1012_10121501_66_dialog_content = "どういうことだろうな。\n兵器の話で人の温もりを感じるとは。",
  ui_story_1012_10121501_67_dialog_content = "ええ。それが単なる兵器じゃ\nなかったからかもしれません。",
  ui_story_1012_10121501_68_dialog_content = "それが<color=#FFB400>プレゼント</color>だって言ってました。",
  ui_story_1012_10121501_69_dialog_content = "<color=#e8d9bb>ゴォォ…ゴォォ…ゴォォ…</color>",
  ui_story_1012_10121501_70_dialog_content = "はぁ…はぁ…やっと停まった…",
  ui_story_1012_10121501_71_dialog_content = "ここは…天空ノ谷か？",
  ui_story_1012_10121501_72_dialog_content = "トラベラーの奴、天空ノ谷まで来て、\n何するつもりだ？",
  ui_story_1012_10121501_73_dialog_content = "いや…天空ノ谷にこんな高い塔なんてあったか？",
  ui_story_1012_10121501_74_dialog_content = "何も理解できていないものが現れたようだな。",
  ui_story_1012_10121501_75_dialog_content = "まさか最初に駆けつけてくるのがR・Wの賊とはな…",
  ui_story_1012_10121501_76_dialog_content = "啓光の大元帥！？",
  ui_story_1012_10121501_77_dialog_content = "天空ノ谷で何してやがんだ？",
  ui_story_1012_10121501_78_dialog_content = "信じるかどうかは知らんが、\nたった今までここで戦争が起きていたのだ。",
  ui_story_1012_10121501_79_dialog_content = "戦争！？",
  ui_story_1012_10121501_80_dialog_content = "クンクン…",
  ui_story_1012_10121501_81_dialog_content = "…確かに戦いの匂いがするな。",
  ui_story_1012_10121501_82_dialog_content = "しっかし…戦争なぁ…",
  ui_story_1012_10121501_83_dialog_content = "信じないのか？",
  ui_story_1012_10121501_84_dialog_content = "啓光の連中の信用度なんざ、\nてめぇらでもよく分かってるだろ。",
  ui_story_1012_10121501_85_dialog_content = "だが、確かに異様な熱気が漂ってるし、\n珍しい大人物が勢ぞろいと来てやがる。",
  ui_story_1012_10121501_86_dialog_content = "私も北境の女王も、戦争に加勢しに来たのだ。",
  ui_story_1012_10121501_87_dialog_content = "PlayerNameの動員力というものだな。\nハハハ！",
  ui_story_1012_10121501_88_dialog_content = "お前と北境の女王…\nじゃあ、もう1人は誰だ？",
  ui_story_1012_10121501_89_dialog_content = "もう1人？",
  ui_story_1012_10121501_90_dialog_content = "お前たちの後ろにいるだろ。",
  ui_story_1012_10121501_91_dialog_content = "！！！",
  ui_story_1012_10121501_92_dialog_content = "…",
  ui_story_1012_10121501_93_dialog_content = "ビクトリアか…いつの間に？",
  ui_story_1012_10121501_94_dialog_content = "私のことは気にしないで。",
  ui_story_1012_10121501_95_dialog_content = "私はただ、神の奇跡をこの目で見に来ただけ。",
  ui_story_1012_10121501_96_dialog_content = "なるほど、想像もしていなかったな。",
  ui_story_1012_10121501_97_dialog_content = "<color=#e8d9bb>ザッ…ザッ…ザッ…ザッ…ザッ…ザッ…</color>",
  ui_story_1012_10121501_98_dialog_content = "整列！",
  ui_story_1012_10121501_99_dialog_content = "全周を封鎖せよ！",
  ui_story_1012_10121501_100_dialog_content = "了解！",
  ui_story_1012_10121501_101_dialog_content = "やっと来たか、アイゼン。",
  ui_story_1012_10121501_102_dialog_content = "援軍にしては、遅すぎるな。",
  ui_story_1012_10121501_103_dialog_content = "申し訳ありませんが…大元帥。\n援軍に来たのではありません。",
  ui_story_1012_10121501_104_dialog_content = "では、何だ？",
  ui_story_1012_10121501_105_dialog_content = "申し訳ありません、大元帥。\nあなたには詳細を知る権利がありません。",
  ui_story_1012_10121501_106_dialog_content = "知る権利がない？この私が、か？",
  ui_story_1012_10121501_107_dialog_content = "私は啓光の大元帥だ。兵士一人一人の動き、\nすべてが報告されるべきだろう。",
  ui_story_1012_10121501_108_dialog_content = "大元帥はあくまで軍事上の階級です。",
  ui_story_1012_10121501_109_dialog_content = "戦場以外のことに口を出す権利はありません。",
  ui_story_1012_10121501_110_dialog_content = "…",
  ui_story_1012_10121501_111_dialog_content = "委員会か。",
  ui_story_1012_10121501_112_dialog_content = "私は任務を遂行するまでです。",
  ui_story_1012_10121501_113_dialog_content = "大元帥様、彼らは…",
  ui_story_1012_10121501_114_dialog_content = "よい。",
  ui_story_1012_10121501_115_dialog_content = "戦場の外では、\n元帥よりも政治家の方が力を持っている。",
  ui_story_1012_10121501_116_dialog_content = "…その言葉は教えとして\n受け取らせていただくべきでしょうか？",
  ui_story_1012_10121501_117_dialog_content = "いや。文句として聞いておけ。",
  ui_story_1012_10121501_118_dialog_content = "向こうを見てみろ。\nまた大部隊が来たようだ。",
  ui_story_1012_10121501_119_dialog_content = "ハゲタカどもめ。戦場には興味を示さず、\n死体の奪い合いには必死になる。",
  ui_story_1012_10121501_120_dialog_content = "城主様、啓光の連中がすでに動いているようです。",
  ui_story_1012_10121501_121_dialog_content = "我々も何かしますか？",
  ui_story_1012_10121501_122_dialog_content = "軽々しく動くでない。",
  ui_story_1012_10121501_123_dialog_content = "非常に重大な問題だ。結論が出るまで、\nどのような行動も非難を招く可能性がある。",
  ui_story_1012_10121501_124_dialog_content = "我ら白夜城が前に出る必要はない。\n秩序を維持するのみだ。",
  ui_story_1012_10121501_125_dialog_content = "はっ！",
  ui_story_1012_10121501_126_dialog_content = "この布陣からすると、城主直々のお出ましのようだな。",
  ui_story_1012_10121501_127_dialog_content = "大軍を率いてのんびりやって来るとは、\n白夜城らしい。",
  ui_story_1012_10121501_128_dialog_content = "もとより、仲間でもあるまい。\nそのようなことを言って何になる。",
  ui_story_1012_10121501_129_dialog_content = "話など、本題のみでよい。",
  ui_story_1012_10121501_130_dialog_content = "本題？この煙の匂いが分からんか？\n本題はとうに終わっている。",
  ui_story_1012_10121501_131_dialog_content = "見ろ。商人どもまで来たようだ。\nこれから商談でも始めるのだろうな。",
  ui_story_1012_10121501_132_dialog_content = "商人が握っているのは金だけではない。",
  ui_story_1012_10121501_133_dialog_content = "そして俺も、単なる商人ではない。",
  ui_story_1012_10121501_134_dialog_content = "永遠に白夜城の背後に隠れた影、だったか？",
  ui_story_1012_10121501_135_dialog_content = "それが俺たちの生き方だ。\nお前に分かるか？",
  ui_story_1012_10121501_136_dialog_content = "その程度にしておけ…皆がここに集まったのは、\nただごとならぬ状況を察したからであろう。",
  ui_story_1012_10121501_137_dialog_content = "我々は何が嵐を巻き起こしたのか、\n今後どのような変化が起こるのかを知らなくてはならぬ。",
  ui_story_1012_10121501_138_dialog_content = "大元帥よ、お主が先に来たというのなら、\n案内は任せられるのだろうな？",
  ui_story_1012_10121501_139_dialog_content = "よかろう。ついて来るがいい。",
  ui_story_1012_10121501_140_dialog_content = "えらい人たちがいっぱい…\n何をするんだろう…？",
  ui_story_1012_10121501_141_dialog_content = "回帰の塔の復活…\n私たちが想像した以上に大きな騒ぎになっていたようね。",
  ui_story_1012_10121501_142_dialog_content = "ここで何が起きたかを探りに来たのよ。\nそれから…",
  ui_story_1012_10121501_143_dialog_content = "塔の処分についてもね。",
  ui_story_1012_10121501_144_dialog_content = "処分…",
  ui_story_1012_10121501_145_dialog_content = "ごめんなさい。\nあなたには少し辛い言葉だったかもしれないわね。",
  ui_story_1012_10121501_146_dialog_content = "この塔は、あなたに残されたものだったわね。",
  ui_story_1012_10121501_147_dialog_content = "いや、大丈夫だよ。分かってるから。",
  ui_story_1012_10121501_148_dialog_content = "大事な話だ。\n僕個人のことを考えている場合じゃない。",
  ui_story_1012_10121501_149_dialog_content = "PlayerName…",
  ui_story_1012_10121501_150_dialog_content = "PlayerName！\nどうしてこんなところに隠れてるのよ。",
  ui_story_1012_10121501_151_dialog_content = "えっ？だって、あっちは…",
  ui_story_1012_10121501_152_dialog_content = "早く来なさい。大元帥がお呼びよ。",
  ui_story_1012_10121501_153_dialog_content = "えっ？僕を？",
  ui_story_1012_10121501_154_dialog_content = "ええ。皆あなたを待ってるの。\n早くして！",
  ui_story_1012_10121501_155_dialog_content = "うん、分かった…",
  ui_story_1012_10121501_156_dialog_content = "待って！",
  ui_story_1012_10121501_157_dialog_content = "PlayerName、もう一言だけ言わせて。",
  ui_story_1012_10121501_158_dialog_content = "古代の空の末裔のことは…\nまだ他の人に話さない方がいいと思うわ。",
  ui_story_1012_10121501_159_dialog_content = "大元帥、PlayerNameが来ました！",
  ui_story_1012_10121501_160_dialog_content = "やっと主が来たか。",
  ui_story_1012_10121501_161_dialog_content = "主？",
  ui_story_1012_10121501_162_dialog_content = "お前は最後の空の末裔だ。\n当然、この回帰の塔の主はお前と言うことになる。",
  ui_story_1012_10121501_163_dialog_content = "私と女王がお前もこの会議に加わるよう、強く要請したのだ。",
  ui_story_1012_10121501_164_dialog_content = "し、指導者の皆さんとですか…？",
  ui_story_1012_10121501_165_dialog_content = "恐れることはない。\n白夜の祝典にも出たではないか。",
  ui_story_1012_10121501_166_dialog_content = "この回帰の塔に関することは、\n誰よりもお前に発言権がある。",
  ui_story_1012_10121501_167_dialog_content = "そなたは自分の言いたいことを言えばよい。\n他の者の立場を気にする必要はない。",
  ui_story_1012_10121501_168_dialog_content = "は、はい…",
  ui_story_1012_10121501_169_dialog_content = "我々光霊は皆、光が見えない…",
  ui_story_1012_10121501_170_dialog_content = "ならば、未来が見えているのは\nお前だけなのかもしれん。",
  ui_story_1012_10121501_171_dialog_content = "では、教えてもらおう…\nお主らはこの塔をどう考える。",
  ui_story_1012_10121501_172_dialog_content = "白夜城から見る限り、\nこれは紛れもなく大きな脅威だ。",
  ui_story_1012_10121501_173_dialog_content = "ダモクレスが自ずから起動するなど、\n前代未聞であるからな。",
  ui_story_1012_10121501_174_dialog_content = "ダモクレスの矛先にあったのは、まさにこの場所だ。\nこの塔を消滅せしめんとしていたようであるな。",
  ui_story_1012_10121501_175_dialog_content = "（ダモクレスが勝手に起動…\nそうだ、その時の様子を見た）",
  ui_story_1012_10121501_176_dialog_content = "啓光も同じ結論に達しています。",
  ui_story_1012_10121501_177_dialog_content = "カナン城内の古代の遺物が突然警報を発しました。\n原因は同じく、この地の異常によるものです。",
  ui_story_1012_10121501_178_dialog_content = "大昔にカナン城を建造した者たちが\n回帰の塔を敵と見なしていたことは明らかです。",
  ui_story_1012_10121501_179_dialog_content = "（うっ…強い敵意みたいなものを感じる…）",
  ui_story_1012_10121501_180_dialog_content = "私も同意見だ。",
  ui_story_1012_10121501_181_dialog_content = "太古の時代、回帰の塔は\n光霊たちが恐れるものだったようだ。",
  ui_story_1012_10121501_182_dialog_content = "！！！",
  ui_story_1012_10121501_183_dialog_content = "意見が揃った以上、\n余はこの塔の破壊…もしくは地下へ埋めることを提案する。",
  ui_story_1012_10121501_184_dialog_content = "存在するべきでないものは、\n存在させてはならぬ。",
  ui_story_1012_10121501_185_dialog_content = "ウソだろ？こんなデカい塔を壊すってのか？",
  ui_story_1012_10121501_186_dialog_content = "古代の遺物がどれだけあることか…\n全部売れるんだぜ。分かってんのか？",
  ui_story_1012_10121501_187_dialog_content = "遺物の中にゃ、改造して生活に利用できるものだって\nあるかもしれねぇっていうのに…",
  ui_story_1012_10121501_188_dialog_content = "おエラ方は生きていくことの\n大変さをちっとも分かってねぇ！",
  ui_story_1012_10121501_189_dialog_content = "生活の問題ではない。",
  ui_story_1012_10121501_190_dialog_content = "啓光も回帰の塔は破壊すべきでないと考えます。",
  ui_story_1012_10121501_191_dialog_content = "回帰の塔に関する推論はさておき、\nここが軍事戦略上価値のある施設であることは間違いありません。",
  ui_story_1012_10121501_192_dialog_content = "破壊してしまうのは実にもったいない。\nしっかりと研究するべきでしょう。",
  ui_story_1012_10121501_193_dialog_content = "その研究とやらは啓光が行うのか？\nお主らが研究成果を正しく使う保証はあるか？",
  ui_story_1012_10121501_194_dialog_content = "お主らがしでかした悪事の数々を\n忘れたとはいうまいな。",
  ui_story_1012_10121501_195_dialog_content = "フ…諸君、少し肩の力を抜いたらどうだ？",
  ui_story_1012_10121501_196_dialog_content = "よく見てみるがいい。\n石を積み上げただけの塔だ。",
  ui_story_1012_10121501_197_dialog_content = "動く仕掛けも、\n流れる光力もない。",
  ui_story_1012_10121501_198_dialog_content = "単なる石のかたまりを恐れる必要があるか？",
  ui_story_1012_10121501_199_dialog_content = "機能も分からぬ以上、\nいつまた動き出すかどうかも分からぬのだぞ？",
  ui_story_1012_10121501_200_dialog_content = "あ、あの…",
  ui_story_1012_10121501_201_dialog_content = "回帰の塔のエネルギーが\n完全に尽きていることは間違いないです。",
  ui_story_1012_10121501_202_dialog_content = "この塔は言われた通り、\n今はただの石の塊です。",
  ui_story_1012_10121501_203_dialog_content = "歴史の痕跡が残ってるだけの、石の塊です…",
  ui_story_1012_10121501_204_dialog_content = "…",
  ui_story_1012_10121501_205_dialog_content = "空の末裔よ。その言葉は重いぞ。\nお主が背負うと言うのか？",
  ui_story_1012_10121501_206_dialog_content = "僕は…",
  ui_story_1012_10121501_207_dialog_content = "城主様、私が証人になります。",
  ui_story_1012_10121501_208_dialog_content = "カレン？",
  ui_story_1012_10121501_209_dialog_content = "私はPlayerNameと共に\n回帰の塔の中を探索しました。",
  ui_story_1012_10121501_210_dialog_content = "回帰の塔は二度と動かせるものではないと、\n私が保証します。",
  ui_story_1012_10121501_211_dialog_content = "…",
  ui_story_1012_10121501_212_dialog_content = "要するに、目くじらを立てる必要は\nないということだ。",
  ui_story_1012_10121501_213_dialog_content = "この世界にとって、この塔はもはや脅威ではない。\n珍しい遺跡ではあるが。",
  ui_story_1012_10121501_214_dialog_content = "そしてかつては空の末裔のものであり、\n今でも空の末裔のものだ。",
  ui_story_1012_10121501_215_dialog_content = "えっ？",
  ui_story_1012_10121501_216_dialog_content = "この塔はPlayerNameのものだと言っている。",
  ui_story_1012_10121501_217_dialog_content = "したがって、塔内の遺物の取り扱いについては、\n彼の許可を得るべきだ。",
  ui_story_1012_10121501_218_dialog_content = "世界に有益な研究なら、\nPlayerNameも同意してくれることだろう。",
  ui_story_1012_10121501_219_dialog_content = "そしてよからぬ目的に使うのであれば、\nPlayerNameに拒否する権利がある。",
  ui_story_1012_10121501_220_dialog_content = "お待ちください。\n先に説明させていただきます…",
  ui_story_1012_10121501_221_dialog_content = "大元帥のお言葉は個人の見解であって、\n決して啓光としての意見を代表するものではありません。",
  ui_story_1012_10121501_222_dialog_content = "ほう？ならば啓光としての意見とは何だ？\n聞かせてもらおうか。",
  ui_story_1012_10121501_223_dialog_content = "啓光は回帰の塔について\n研究するべきだと主張しています。",
  ui_story_1012_10121501_224_dialog_content = "特定の誰かに帰属するべきものではありません！",
  ui_story_1012_10121501_225_dialog_content = "フン、お前たちと言うやつは…",
  ui_story_1012_10121501_226_dialog_content = "私はレインハトの見解に同意する。",
  ui_story_1012_10121501_227_dialog_content = "回帰の塔はPlayerNameのものだ。",
  ui_story_1012_10121501_228_dialog_content = "北境の女王…",
  ui_story_1012_10121501_229_dialog_content = "我らは皆、おのれの故郷のために戦ってきた。\n戦う理由として、それは最も尊敬に値する。",
  ui_story_1012_10121501_230_dialog_content = "空の末裔も我々と同じように、\nこの地を守るために戦った。",
  ui_story_1012_10121501_231_dialog_content = "命懸けで戦い、その結果、故郷をよそ者の手に\n委ねることになったというのでは、敗北と何ら相違ない。",
  ui_story_1012_10121501_232_dialog_content = "空の末裔にとって、光霊と暗鬼はどちらも異種族だ。",
  ui_story_1012_10121501_233_dialog_content = "空の末裔を光霊の盟友と見なすのであれば、天空ノ谷を侵犯せぬことこそ、\n光霊側が示すべき基本的尊重の態度ではないか？",
  ui_story_1012_10121501_234_dialog_content = "女王陛下…",
  ui_story_1012_10121501_235_dialog_content = "白夜城の主の懸念である危険性についてだが、\n私はそこまで心配していない。",
  ui_story_1012_10121501_236_dialog_content = "武器のもたらすものは使い手によって決まる。",
  ui_story_1012_10121501_237_dialog_content = "そして見ての通り、PlayerNameは回帰の塔を使い、\n暗鬼との戦争を勝利に導いた。",
  ui_story_1012_10121501_238_dialog_content = "それが彼の示した、回帰の塔の現在の立場だ。",
  ui_story_1012_10121501_239_dialog_content = "…",
  ui_story_1012_10121501_240_dialog_content = "女王陛下がこれほど物を言うとは、実に珍しい…",
  ui_story_1012_10121501_241_dialog_content = "この件はそれほど重要な問題か？",
  ui_story_1012_10121501_242_dialog_content = "空の末裔は、光霊にとって重要な盟友だ。",
  ui_story_1012_10121501_243_dialog_content = "よろしい。",
  ui_story_1012_10121501_244_dialog_content = "これ以上の抗弁は無用か。",
  ui_story_1012_10121501_245_dialog_content = "陛下の言葉もむべなるかな。\n余はその意見を尊重しよう。",
  ui_story_1012_10121501_246_dialog_content = "白夜城は回帰の塔の処分について、\n干渉しないものとする。",
  ui_story_1012_10121501_247_dialog_content = "他の者は？",
  ui_story_1012_10121501_248_dialog_content = "そういうことなら、俺も従おう。",
  ui_story_1012_10121501_249_dialog_content = "ハッハッハ。それでいいぜ！\n異議はねぇ！",
  ui_story_1012_10121501_250_dialog_content = "…",
  ui_story_1012_10121501_251_dialog_content = "啓光の態度はすでに表明しました。\n他勢力の選択については、何も言うことはありません。",
  ui_story_1012_10121501_252_dialog_content = "まとまったようだな。",
  ui_story_1012_10121501_253_dialog_content = "祝うにせよ、落胆するにせよ、戦いは終わったのだ。\n皆、引き続き平和の果実を分け合おうではないか。",
  ui_story_1012_10121501_254_dialog_content = "次の戦争が訪れるまで、\nぬるま湯につかるとしよう。",
  ui_story_1012_10121501_255_dialog_content = "そして、PlayerNameには祝いの言葉を述べよう。\nお前の戦利品を受け取るがいい。",
  ui_story_1012_10121501_256_dialog_content = "立派な家だ。",
  ui_story_1012_10121501_257_dialog_content = "…",
  ui_story_1012_10121501_258_dialog_content = "はぁ…",
  ui_story_1012_10121501_259_dialog_content = "立派な家か…",
  ui_story_1012_10121501_260_dialog_content = "なぜため息をつく？",
  ui_story_1012_10121501_261_dialog_content = "じょ、女王陛下！？",
  ui_story_1012_10121501_262_dialog_content = "どうしてここに？",
  ui_story_1012_10121501_263_dialog_content = "苦悩がそなたの顔に出ていた。",
  ui_story_1012_10121501_264_dialog_content = "アハハ…さすがは女王陛下…",
  ui_story_1012_10121501_265_dialog_content = "…",
  ui_story_1012_10121501_266_dialog_content = "確かに何が何だか分かっていないんです。",
  ui_story_1012_10121501_267_dialog_content = "こたびの戦いか？",
  ui_story_1012_10121501_268_dialog_content = "ちょっと違います。はぁ、僕は…",
  ui_story_1012_10121501_269_dialog_content = "話の聞き手が必要なら、\nここに私がいる。",
  ui_story_1012_10121501_270_dialog_content = "北境の女王としてではなく、\nベツレヘムとしてな。",
  ui_story_1012_10121501_271_dialog_content = "ベツレヘムとして…",
  ui_story_1012_10121501_272_dialog_content = "ありがとうございます。僕は――\nうん…たぶん本当に、誰かに話す必要があるのかもしれません。",
  ui_story_1012_10121501_273_dialog_content = "話してみよ。聞いている。",
  ui_story_1012_10121501_274_dialog_content = "僕…僕たちは…地下で目にしたんです。\n空の末裔の過去を。",
  ui_story_1012_10121501_275_dialog_content = "回帰の塔の記録は完全ではなかったけど、\n僕は見ました…",
  ui_story_1012_10121501_276_dialog_content = "空の末裔が暗鬼を従えて、\n一緒に戦っている光景を…",
  ui_story_1012_10121501_277_dialog_content = "つまり、その…はるか昔、\n空の末裔と暗鬼は仲間だったのかもしれない…",
  ui_story_1012_10121501_278_dialog_content = "空の末裔と暗鬼が？",
  ui_story_1012_10121501_279_dialog_content = "そうです。空の末裔と暗鬼が\n一緒に戦っている光景を感じ取りました。",
  ui_story_1012_10121501_280_dialog_content = "あの感覚をどうやって\n言い表せばいいのか分からないですが…",
  ui_story_1012_10121501_281_dialog_content = "確定的な証拠はないですが、\nあれは本当に起きたことだと確信しています。",
  ui_story_1012_10121501_282_dialog_content = "戦いが終わった後、\nその光景がずっと頭の中を回り続けていて、僕…",
  ui_story_1012_10121501_283_dialog_content = "耐えきれなくて…",
  ui_story_1012_10121501_284_dialog_content = "PlayerName、大丈夫か？",
  ui_story_1012_10121501_285_dialog_content = "大丈夫です。でも、頭が張り裂けそうです。\n資料を何も持ち出せなかったのが残念です。持ち出せていれば、見せられたのに…",
  ui_story_1012_10121501_286_dialog_content = "そなたが目にしたものが事実とは限らぬ。\n空の末裔と暗鬼が盟友だったという記録は、北境にはない。",
  ui_story_1012_10121501_287_dialog_content = "でも、僕は本当に空の末裔と暗鬼が一緒になって\n光霊を虐殺しているところを見たんです。誓います。本当です…",
  ui_story_1012_10121501_288_dialog_content = "あれは…単なる幻なんかじゃない…",
  ui_story_1012_10121501_289_dialog_content = "僕もあれがウソであって欲しいと思ってます。\nきっと、誰よりも。",
  ui_story_1012_10121501_290_dialog_content = "それが本当だとすれば、ノーヴィオは何も知らぬのか…？\nあれほど長く生きているのに、何も聞かされた記憶がない。",
  ui_story_1012_10121501_291_dialog_content = "ソラヴァンで空の末裔の歴史を見た時も、\nまったく触れられていませんでした。",
  ui_story_1012_10121501_292_dialog_content = "私の知る限り、白夜城や啓光にも\nそのような記録はないだろう。さもなくば…",
  ui_story_1012_10121501_293_dialog_content = "さもなくば、僕みたいな「暗鬼の仲間」の子孫はきっと…\nアハハ…",
  ui_story_1012_10121501_294_dialog_content = "僕が知ってることを詳しくお話しします。最初は…",
  ui_story_1012_10121501_295_dialog_content = "――というわけです。",
  ui_story_1012_10121501_296_dialog_content = "…",
  ui_story_1012_10121501_297_dialog_content = "確たる情報がない以上、\n軽々しく結論は出せぬ。",
  ui_story_1012_10121501_298_dialog_content = "そして、それが本当に起きたことであったとしても、\n遠き過去のことだ。",
  ui_story_1012_10121501_299_dialog_content = "真相がどうであったかは、\n近代の空の末裔の祖先すら、おそらく知らないであろう。",
  ui_story_1012_10121501_300_dialog_content = "つまり…北境の歴史よりも古いってことですか？",
  ui_story_1012_10121501_301_dialog_content = "古き時代に対する光霊の研究は完全なものではない。\n空白と言ってもよい。",
  ui_story_1012_10121501_302_dialog_content = "しかし、光霊の歴史の中では、\n空の末裔と亜人は常に光霊の良き友であり、盟友だ。",
  ui_story_1012_10121501_303_dialog_content = "私たちは共に暗鬼と戦ってきた。それは変わらない。",
  ui_story_1012_10121501_304_dialog_content = "そなたの一族も暗鬼の手にかかったのではなかったか？",
  ui_story_1012_10121501_305_dialog_content = "そうです…僕も分からないんです。\n本当のことが知りたいんです。",
  ui_story_1012_10121501_306_dialog_content = "でも、もし空の末裔が本当に暗鬼と…",
  ui_story_1012_10121501_307_dialog_content = "仮にそうだとして、そのような遠い昔の歴史が\nそなたに大きな影響を及ぼすと思うか？",
  ui_story_1012_10121501_308_dialog_content = "ずっと考えてるんです。\nもし本当に空の末裔がかつて暗鬼と仲間だったのなら…",
  ui_story_1012_10121501_309_dialog_content = "僕が小さい頃から学んできた、空の末裔の歴史や信念も、\n全部ウソと言うことでしょうか？",
  ui_story_1012_10121501_310_dialog_content = "僕が会えなかった一族の人たちが、\n僕の見たものを見たら、どう思うでしょうか？",
  ui_story_1012_10121501_311_dialog_content = "もし空の末裔が本当に…\nだとしたら、何もかも汚らわしく思えて…",
  ui_story_1012_10121501_312_dialog_content = "光霊と理念は違えど、空の末裔は自然と平和を愛している。\nそれは大陸の誰もが知っていることだ。",
  ui_story_1012_10121501_313_dialog_content = "もちろん我々が\nまだ知らないこともあるだろう。そなたは…",
  ui_story_1012_10121501_314_dialog_content = "僕は空の末裔としての信念を抱いて、生き延びてきました。\nそれがウソなら、僕は…",
  ui_story_1012_10121501_315_dialog_content = "立派な空の末裔になろうと思ってきた僕は、\n何なんでしょうか？",
  ui_story_1012_10121501_316_dialog_content = "PlayerName。\nそなたは私が出会った中で最も勇敢で、強い空の末裔だ。",
  ui_story_1012_10121501_317_dialog_content = "…頭が爆発しそうです。",
  ui_story_1012_10121501_318_dialog_content = "PlayerName、空の末裔が本当に暗鬼と同盟を組んでいたとして、\nお主はどうする？暗鬼に与（くみ）するのか？",
  ui_story_1012_10121501_319_dialog_content = "そんなことしません。\n何があろうと、僕は暗鬼と戦い続けます！",
  ui_story_1012_10121501_320_dialog_content = "あいつらは僕の家族を奪い、\n僕の仲間を傷つけました。僕は暗鬼を許しません。",
  ui_story_1012_10121501_321_dialog_content = "そなたの信念と力は、\nどれも空の末裔から受け継いだものではないのか？",
  ui_story_1012_10121501_322_dialog_content = "歴史は歴史だ。\n大切なのはそなた自身、そして善良で勇敢な一族であるということだ。",
  ui_story_1012_10121501_323_dialog_content = "…少し分かったような気がします。でも、すぐには受け入れがたいです。\n自分が汚いもののような気がして…",
  ui_story_1012_10121501_324_dialog_content = "白夜城の祝典で、そなたは指導者らの陰謀を前にして\n何と言ったか覚えているか？",
  ui_story_1012_10121501_325_dialog_content = "あの時の自分を覚えていればよいのだ。",
  ui_story_1012_10121501_326_dialog_content = "…でも、空の末裔に後ろめたい歴史があるなら、\nどんな顔をしてあんな主張をすればいいのか…",
  ui_story_1012_10121501_327_dialog_content = "それだけじゃない。\n仲間からだって疑われて…",
  ui_story_1012_10121501_328_dialog_content = "さっきの回帰の塔の話し合いみたいに、\n僕は世界に害を及ぼす危険な存在と見なされるかもしれません…",
  ui_story_1012_10121501_329_dialog_content = "僕は…皆から疑いの目を向けられるのが怖い…",
  ui_story_1012_10121501_330_dialog_content = "白夜城にも啓光にも、それぞれ汚点はある。\nしかし、そなたはカレンやバイスを仲間としている。なぜだ？",
  ui_story_1012_10121501_331_dialog_content = "僕たちは一緒に戦ってきて、\nお互いを信頼して、頼りにしてますから…",
  ui_story_1012_10121501_332_dialog_content = "彼女たちがはるか遠い昔の話のために、\nそなたを仲間とは思わなくなるのか？",
  ui_story_1012_10121501_333_dialog_content = "それはないと思います！",
  ui_story_1012_10121501_334_dialog_content = "で、あろう。\n問題はそれほど複雑ではないのだ。",
  ui_story_1012_10121501_335_dialog_content = "そなたはPlayerNameだ。\n空の末裔のすべてではない。",
  ui_story_1012_10121501_336_dialog_content = "でも、自分が空の末裔であるということは僕にとって、ほぼすべてなんです。\nもしかしたら、女王陛下にとって北境が持つ意味と同じぐらいかもしれません。",
  ui_story_1012_10121501_337_dialog_content = "空の末裔はいざとなったら皆と前で戦えない。役立たずです。\nおまけに暗鬼と共犯だったなんて…",
  ui_story_1012_10121501_338_dialog_content = "考えると、辛くて…",
  ui_story_1012_10121501_339_dialog_content = "そなたの気持ちは分かる。",
  ui_story_1012_10121501_340_dialog_content = "私たちはまだ歴史の真相を\n完全には把握しておらぬ。",
  ui_story_1012_10121501_341_dialog_content = "だが、もしかすると、そなたの先祖の中に反逆を選び、\n空の末裔の運命を変えたものがいたのかもしれぬ。",
  ui_story_1012_10121501_342_dialog_content = "歴史は変えられないのだ。",
  ui_story_1012_10121501_343_dialog_content = "だが、空の末裔の未来はそなたにかかっている。",
  ui_story_1012_10121501_344_dialog_content = "はい…じっくり考えます…",
  ui_story_1012_10121501_345_dialog_content = "僕が最もするべきことは、\n昔の真実を何もかも、解き明かすことかもしれません。",
  ui_story_1012_10121501_346_dialog_content = "PlayerName、\nその真相がそなたの受け入れられないものであったなら、何とする？",
  ui_story_1012_10121501_347_dialog_content = "はぁ…僕の想像以上に残酷なものだったらと思うと、怖いです。",
  ui_story_1012_10121501_348_dialog_content = "しかも、その後は皆から疑われて、\n色々詮索されるかもしれない…",
  ui_story_1012_10121501_349_dialog_content = "そなたには時が必要だ、PlayerName。",
  ui_story_1012_10121501_350_dialog_content = "そうですね…長くなるかもしれません…",
  ui_story_1012_10121501_351_dialog_content = "<color=#e8d9bb>「メインシステム：起動」</color>",
  ui_story_1012_10121501_352_dialog_content = "<color=#e8d9bb>「生物モジュール：起動」</color>",
  ui_story_1012_10121501_353_dialog_content = "<color=#e8d9bb>「生命維持システム：起動」</color>",
  ui_story_1012_10121501_354_dialog_content = "<color=#e8d9bb>「エンジン起動中――」</color>",
  ui_story_1012_10121501_355_dialog_content = "<color=#e8d9bb>「16%…33%…」</color>",
  ui_story_1012_10121501_356_dialog_content = "<color=#e8d9bb>「89%…97%…」</color>",
  ui_story_1012_10121501_357_dialog_content = "<color=#e8d9bb>「100%――起動成功――」</color>",
  ui_story_1012_10121501_358_dialog_content = "これでソラヴァンが本当に直るのね！",
  ui_story_1012_10121501_359_dialog_content = "うん！ついに！！！",
  ui_story_1012_10121501_360_dialog_content = "意識の回復にはまだ時間がかかりそうだけど、\nこれだけでもすごいことだよ！",
  ui_story_1012_10121501_361_dialog_content = "失くしたものをまた手に入れたような感覚？",
  ui_story_1012_10121501_362_dialog_content = "そうだね！",
  ui_story_1012_10121501_363_dialog_content = "はぁ…疲れた。\nここ数日は本当に九死に一生ばっかりだったわ。",
  ui_story_1012_10121501_364_dialog_content = "いつも細いロープ一本でガケにぶら下がってた感じ。",
  ui_story_1012_10121501_365_dialog_content = "最後までがんばれてよかったわ…",
  ui_story_1012_10121501_366_dialog_content = "思わず感嘆しちゃうわ…本当に運がよかったよね。アハハ。",
  ui_story_1012_10121501_367_dialog_content = "ハハハ…そうだね。",
  ui_story_1012_10121501_368_dialog_content = "でも、運だけじゃないかもしれないよ。",
  ui_story_1012_10121501_369_dialog_content = "どんな物事にも背景には理由があるんだ。\nただ僕たちに見えていないだけで。",
  ui_story_1012_10121501_370_dialog_content = "妙に理屈っぽいことを言うようになったわね。\n回帰の塔で悟りでも開いたの？",
  ui_story_1012_10121501_371_dialog_content = "思い返してみると、いろんな出来事の間に、\n見えないつながりがあるみたいなんだ。",
  ui_story_1012_10121501_372_dialog_content = "回帰の塔では、\n過去の人々にたくさんのことが起きて…",
  ui_story_1012_10121501_373_dialog_content = "その人たちの物語は永遠に知ることができないけど、\n物語の跡は残ってるんだ。",
  ui_story_1012_10121501_374_dialog_content = "僕たちの旅は、\nその足跡をたどってるようなものだった。",
  ui_story_1012_10121501_375_dialog_content = "足跡が誰のものか、\nその人が何をしようとしていたかは分からないけど…",
  ui_story_1012_10121501_376_dialog_content = "でも、追いかける途中で、\n過去に起こったことの軌跡が見えた。",
  ui_story_1012_10121501_377_dialog_content = "またあの「フランシス先生」のこと？",
  ui_story_1012_10121501_378_dialog_content = "あの人のことがそうとう気になるみたいね。",
  ui_story_1012_10121501_379_dialog_content = "うん…フランシス先生って人、\nどんなことを経験したんだろうなって。",
  ui_story_1012_10121501_380_dialog_content = "あの銃はフランシス先生のものだった。\nつまり、回帰の塔で暗鬼と戦ったことがあるんだ。",
  ui_story_1012_10121501_381_dialog_content = "それに「ハーモナイザー」の実験もフランシス先生がやっていて、\n実験室は追放区の中で何重にもロックされてた。",
  ui_story_1012_10121501_382_dialog_content = "最後の「コアリング権限」を奪う戦いで、\nフランシス先生に何があったかは分からない。でも…",
  ui_story_1012_10121501_383_dialog_content = "あの戦いに勝つなら、\n「ハーモナイザー」で強化された光霊に頼るしかなかったはず。",
  ui_story_1012_10121501_384_dialog_content = "確かにそう言われると、\n私たちが経験したことすべて、フランシス先生の影があるような気がするわね…",
  ui_story_1012_10121501_385_dialog_content = "私たちは日蝕に立ち向かうために戦ったけど、\nフランシス先生は？",
  ui_story_1012_10121501_386_dialog_content = "もっと恐ろしい相手に立ち向かっていたのかもしれない。",
  ui_story_1012_10121501_387_dialog_content = "何かは分からないけど…\nもしかしたら、運命そのもの、みたいな感じかもね。",
  ui_story_1012_10121501_388_dialog_content = "運命は命を奪おうとするんじゃなくて、\n一生を支配しようとする。",
  ui_story_1012_10121501_389_dialog_content = "フランシス先生はきっとそういう、\n自分の「生まれつきのもの」に立ち向かっていたんだ。",
  ui_story_1012_10121501_390_dialog_content = "生まれつきのものに立ち向かう…",
  ui_story_1012_10121501_391_dialog_content = "そんなの、立ち向かえるものなのかしら？",
  ui_story_1012_10121501_392_dialog_content = "フランシス先生…成功したのかしらね。",
  ui_story_1012_10121501_393_dialog_content = "成功してるよ。外を見て。",
  ui_story_1012_10121501_394_dialog_content = "空の末裔は、回帰の塔のすぐ外に、\n自分の家を手に入れたんだ。",
  ui_story_1012_10121501_395_dialog_content = "命令に従わされることも、\n暗鬼におびえることもなく…",
  ui_story_1012_10121501_396_dialog_content = "フランシス先生はきっとそれを望んで、\n自分の子孫の世界を書き換えたんだ…",
  ui_story_1012_10121501_397_dialog_content = "僕と、すべての空の末裔の人生を。",
  ui_story_1013_10130101_1_dialog_content = "…今日も平和な、いい1日だね…",
  ui_story_1013_10130101_2_dialog_content = "そうね。",
  ui_story_1013_10130101_3_dialog_content = "この前暗鬼と戦ったのが、もうずいぶん昔のことに思えるわ。",
  ui_story_1013_10130101_4_dialog_content = "戦い方を忘れちゃいそう。",
  ui_story_1013_10130101_5_dialog_content = "でも、平和なのはいいことだよ！",
  ui_story_1013_10130101_6_dialog_content = "いつか本当に暗鬼を全部倒すことができたら、\n毎日いまみたいに穏やかに過ごせるんだろうな。",
  ui_story_1013_10130101_7_dialog_content = "いつ襲撃されるかにおびえることもなく、\n1日中散歩や釣り、料理をして過ごす…",
  ui_story_1013_10130101_8_dialog_content = "それもいいわね！",
  ui_story_1013_10130101_9_dialog_content = "そうなったら、PlayerNameは何をしたい？",
  ui_story_1013_10130101_10_option_content = "木を植えたい",
  ui_story_1013_10130101_11_dialog_content = "珍しい品種の木をもっと増やして、\n天空ノ庭をもっときれいなところにしたいな。",
  ui_story_1013_10130101_12_dialog_content = "木を育てるのって難しくて。\n10回に9回は突然変異がうまくいかないんだ。",
  ui_story_1013_10130101_13_dialog_content = "継続と辛抱が必要な仕事よね。",
  ui_story_1013_10130101_14_option_content = "魚釣りかな？",
  ui_story_1013_10130101_15_dialog_content = "観賞魚をたくさん釣って、願いの泉で育てたいな。",
  ui_story_1013_10130101_16_dialog_content = "空き缶にはウンザリだけど…",
  ui_story_1013_10130101_17_dialog_content = "きっと釣れるわよ。",
  ui_story_1013_10130101_18_dialog_content = "それにしても、天空ノ谷が今みたいに平和なのも、\n「律法の弦」のおかげなんだね。",
  ui_story_1013_10130101_19_dialog_content = "こんなにすごいとは思ってなかったよ…",
  ui_story_1013_10130101_20_dialog_content = "フランシス先生って人があらかじめ設定をしてくれてたから良かったけど、\n何もかも僕自身で起動してたら…",
  ui_story_1013_10130101_21_dialog_content = "きっと大変なことになってたね。",
  ui_story_1013_10130101_22_dialog_content = "今思い出してみても、ゾッとしちゃうよ。",
  ui_story_1013_10130101_23_dialog_content = "危機は乗り越えたんだから、\n余計なことは考えちゃダメよ。",
  ui_story_1013_10130101_24_dialog_content = "今の暮らしを楽しまなきゃ！",
  ui_story_1013_10130101_25_dialog_content = "うん、そうだね…",
  ui_story_1013_10130101_26_dialog_content = "そういえば、バイス、\nどうしてそっちの服を着てるの？",
  ui_story_1013_10130101_27_dialog_content = "ああ、この黒い服のこと？",
  ui_story_1013_10130101_28_dialog_content = "いつもの服の方が確かに楽なんだけど、\nたまには気分転換もいいでしょ。",
  ui_story_1013_10130101_29_dialog_content = "ヘンかしら？…いつものに着替えてきた方がいい？",
  ui_story_1013_10130101_30_dialog_content = "いやいや、そんなことないよ！",
  ui_story_1013_10130101_31_dialog_content = "バイス自身がいいなら、\n僕はどの服でもいいと思う！",
  ui_story_1013_10130101_32_dialog_content = "そうだ、さっき釣ったお魚、\nバケツに入れっぱなしだったわ。",
  ui_story_1013_10130101_33_dialog_content = "早く願いの泉に入れてあげなきゃ！",
  ui_story_1013_10130101_34_dialog_content = "あ、そうだ、忘れるところだった！",
  ui_story_1013_10130101_35_dialog_content = "私が入れてきてあげるわ。",
  ui_story_1013_10130101_36_dialog_content = "あっ！？",
  ui_story_1013_10130101_37_dialog_content = "バイス、新しい技でも覚えたの？",
  ui_story_1013_10130101_38_dialog_content = "ううん、何も…",
  ui_story_1013_10130101_39_dialog_content = "え、どういうこと！？",
  ui_story_1013_10130101_40_dialog_content = "今は何もしてないわ！？",
  ui_story_1013_10130101_41_dialog_content = "じゃあ、誰かのイタズラ？\n誰？分かってるよ、出てきて！",
  ui_story_1013_10130101_42_dialog_content = "ううん…違うわ、この光力…\n私の体から出てきてる。",
  ui_story_1013_10130101_43_dialog_content = "光力がゆっくり流れ出てるみたい…\nいったい、どういうこと…？",
  ui_story_1013_10130101_44_dialog_content = "まさか…",
  ui_story_1013_10130101_45_dialog_content = "ハーモナイザーを使った後遺症？",
  ui_story_1013_10130101_46_dialog_content = "バイス、大丈夫？どこか具合の悪いところはない？",
  ui_story_1013_10130101_47_dialog_content = "具合の悪いところはないわ…",
  ui_story_1013_10130101_48_dialog_content = "流れ出てるって言っても、\nほとんど感覚がないぐらい、ゆっくりよ。",
  ui_story_1013_10130101_49_dialog_content = "これぐらいなら、何も問題は起こらないと思うわ。",
  ui_story_1013_10130101_50_dialog_content = "でも、他にも症状が出るかもしれないよ。",
  ui_story_1013_10130101_51_dialog_content = "古代の科学技術なんて知らないことばかりなのに、\n僕が軽々しく、あんな装置を使ったりしたから…",
  ui_story_1013_10130101_52_dialog_content = "PlayerName、心配しないで。",
  ui_story_1013_10130101_53_dialog_content = "とりあえず、一緒にカナン城に戻りましょ！",
  ui_story_1013_10130101_54_dialog_content = "あそこなら啓光でいちばん優秀な科学者がいるし、\n最高レベルの医療施設もあるわ。きっと原因が分かるはずよ！",
  ui_story_1013_10130101_55_dialog_content = "うん…そうだね！じゃあ、今すぐ出発しよう。\n途中でビビアンさんに通信しておけば、手助けしてくれるはず！",
  ui_story_1013_10130101_56_dialog_content = "自動操縦、目的地は――カナン城に設定。",
  ui_story_1013_10130101_57_dialog_content = "早く起動して！急がないと！",
  ui_story_1013_10130101_58_dialog_content = "PlayerName、あわてないで。\n私は大丈夫よ。",
  ui_story_1013_10130101_59_dialog_content = "少し光ってるだけのことなんだから。",
  ui_story_1013_10130101_60_dialog_content = "でも、そもそも君が重傷を負ったのは、\nソラヴァンを直す方法を見つけようとしてた時だし…",
  ui_story_1013_10130101_61_dialog_content = "ハーモナイザーを君に使うって決めたのも僕だ。",
  ui_story_1013_10130101_62_dialog_content = "だから…君の身に何かあったら、僕の責任だよ。",
  ui_story_1013_10130101_63_dialog_content = "助けるためだからって、\n訳も分からない装置を使うべきじゃなかったのかも…",
  ui_story_1013_10130101_64_dialog_content = "PlayerName…",
  ui_story_1013_10130101_65_dialog_content = "そんな深刻に考えないで。\n本当に、具合が悪いところなんてないの。",
  ui_story_1013_10130101_66_dialog_content = "でも、おかしな現象なのは確かでしょ。\n放っておきたくないだけよ。",
  ui_story_1013_10130101_67_dialog_content = "そうだね…とにかく、カナン城に行って、\n徹底的に調べてもらうのが一番だ。",
  ui_story_1013_10130101_68_dialog_content = "ビビアン長官に連絡しましょ。\n検査の手配をお願いするわ。",
  ui_story_1013_10130101_69_dialog_content = "わかった。",
  ui_story_1013_10130101_70_dialog_content = "ビビアンさん、聞こえますか？",
  ui_story_1013_10130101_71_dialog_content = "PlayerNameですね？聞こえています。\n続けてください。",
  ui_story_1013_10130101_72_dialog_content = "今、バイスと一緒にいるんですが、\n急ぎの用があるんです！",
  ui_story_1013_10130101_73_dialog_content = "こんな時に急用ですか…\nまさか、バイスにも何かありましたか？",
  ui_story_1013_10130101_74_dialog_content = "バイス「にも」？",
  ui_story_1013_10130101_75_dialog_content = "…もしかして…バートンの体からも、\nおかしな光が出てるんですか！？",
  ui_story_1013_10130101_76_dialog_content = "そうです。天空ノ谷での戦いから戻った後、\nバートン軍団長には、しばらく休息を取らせていたのですが…",
  ui_story_1013_10130101_77_dialog_content = "今朝になって突然、\n原因不明の光力流失が起こり始めたのです。",
  ui_story_1013_10130101_78_dialog_content = "その口ぶりからすると、\nバイスも同じような症状が出ているのですね？",
  ui_story_1013_10130101_79_dialog_content = "そうです。今、カナン城に向かっているところです。\nバイスの検査を手配してもらえますか？",
  ui_story_1013_10130101_80_dialog_content = "お任せください。",
  ui_story_1013_10130101_81_dialog_content = "もともと、ハーモナイザーを使ったバートン軍団長とバイスは、\n徹底的に検査しようとしていたところですので。",
  ui_story_1013_10130101_82_dialog_content = "そうなんですか？よかった！",
  ui_story_1013_10130101_83_dialog_content = "カナン城に到着したら、直接医療センターに向かってください。\nそちらで待っています。",
  ui_story_1013_10130101_84_dialog_content = "分かりました。では、お願いします！",
  ui_story_1013_10130101_85_dialog_content = "<color=#e8d9bb>カナン城、医療センター</color>",
  ui_story_1013_10130101_86_dialog_content = "ここが医療センターよ。",
  ui_story_1013_10130101_87_dialog_content = "ここに来るのは入隊前の健康診断以来ね…",
  ui_story_1013_10130101_88_dialog_content = "僕は初めてだよ。大きい場所だね…",
  ui_story_1013_10130101_89_dialog_content = "当然でしょ！",
  ui_story_1013_10130101_90_dialog_content = "戦いが始まれば、どれだけの死傷者が出るか分からないわ。",
  ui_story_1013_10130101_91_dialog_content = "大きければ大きいほど、\nたくさんの兵士がすぐに治療を受けられるでしょ。",
  ui_story_1013_10130101_92_dialog_content = "それだけ、命を助けられる可能性も高くなるの…",
  ui_story_1013_10130101_93_dialog_content = "そうだね…",
  ui_story_1013_10130101_94_dialog_content = "おう、バイス、PlayerName！",
  ui_story_1013_10130101_95_dialog_content = "到着しましたか。",
  ui_story_1013_10130101_96_dialog_content = "バートン軍団長！ビビアン長官！",
  ui_story_1013_10130101_97_dialog_content = "バートンの身体も同じみたいだね…",
  ui_story_1013_10130101_98_dialog_content = "あ？おお、この光のことか？",
  ui_story_1013_10130101_99_dialog_content = "ただ光ってるだけだろ、なんともねえよ。\n光力もほとんど減らねぇしな。",
  ui_story_1013_10130101_100_dialog_content = "でも、何かまだ分かってない危険があるかもしれないよ。",
  ui_story_1013_10130101_101_dialog_content = "まあな。だが俺としては、とにかく早いとこ医者か科学者に\nこの光を止める方法を見つけてもらいてぇ…",
  ui_story_1013_10130101_102_dialog_content = "こんな風に光ってるんじゃ、夜には光るマトだ！\n奇襲どころじゃありゃしねぇ！",
  ui_story_1013_10130101_103_dialog_content = "バートン長官らしいわ…",
  ui_story_1013_10130101_104_dialog_content = "おい、どうした？\n顔に「心配」って書いてあるぜ。",
  ui_story_1013_10130101_105_dialog_content = "え？あ、うん…本当に心配なんだよ。",
  ui_story_1013_10130101_106_dialog_content = "心配いらねぇって。ここは啓光で一番の医療機関なんだ。\nくたばりかけのヤツだって助けるところだぜ？",
  ui_story_1013_10130101_107_dialog_content = "こんな痛くもかゆくもない光なんざ、朝飯前だろ。",
  ui_story_1013_10130101_108_dialog_content = "う…うん！",
  ui_story_1013_10130101_109_dialog_content = "では、私はバートン軍団長とバイスを検査に連れていきます。",
  ui_story_1013_10130101_110_dialog_content = "PlayerNameは外で待っていてください。",
  ui_story_1013_10130101_111_dialog_content = "分かりました。",
  ui_story_1013_10130101_112_dialog_content = "じゃあ、行ってくるわ。",
  ui_story_1013_10130101_113_dialog_content = "おう、また後でな。",
  ui_story_1013_10130101_114_dialog_content = "廊下が静かになった…",
  ui_story_1013_10130101_115_dialog_content = "今回のことは、本当に何ともない、\nただの偶然であってほしい…",
  ui_story_1013_10130101_116_dialog_content = "そして、あなたたちが世界に――",
  ui_story_1013_10130101_117_dialog_content = "戦争をもたらすのです。",
  ui_story_1013_10130101_118_dialog_content = "…",
  ui_story_1013_10130101_119_dialog_content = "いや、僕は絶対にそんなことはしない。",
  ui_story_1013_10130101_120_dialog_content = "でも…僕の選択は、本当に正しかったのかな…？",
  ui_story_1013_10130101_121_dialog_content = "前回と変わったところはない。\nだが、油断はできない。",
  ui_story_1013_10130101_122_dialog_content = "お前の身体では、\nどんな不注意も不測の事態も許されない。",
  ui_story_1013_10130101_123_dialog_content = "ゴホゴホッ…分かっています。",
  ui_story_1013_10130101_124_dialog_content = "自分の身体のことですから、\n私自身が一番よく分かっていますよ。",
  ui_story_1013_10130101_125_dialog_content = "僕たちと一緒に訓練すればいいんだよ。",
  ui_story_1013_10130101_126_dialog_content = "ちょっと訓練すれば、ヒョロヒョロだって強くなれるよ。\n僕だってそうだったんだ！",
  ui_story_1013_10130101_127_dialog_content = "ハハハ、私の事情は\n訓練で解決できるものではありませんよ。",
  ui_story_1013_10130101_128_dialog_content = "（この人たちも検査かな？）",
  ui_story_1013_10130101_129_dialog_content = "何を見ている？",
  ui_story_1013_10130101_130_dialog_content = "え！？あ、ご、ごめんなさい！",
  ui_story_1013_10130101_131_dialog_content = "見かけない人だなと思って、つい…",
  ui_story_1013_10130101_132_dialog_content = "おや、お待ちください。あなたは…",
  ui_story_1013_10130101_133_dialog_content = "ウワサに聞く、空の末裔ではありませんか？",
  ui_story_1013_10130101_134_dialog_content = "なに？",
  ui_story_1013_10130101_135_dialog_content = "え？空の末裔！？",
  ui_story_1013_10130101_136_dialog_content = "どうして知ってるの？\n会ったことはないと思うけど…",
  ui_story_1013_10130101_137_dialog_content = "もちろん、知っていますよ。\n私たちの間では非常に有名ですから。",
  ui_story_1013_10130101_138_dialog_content = "巨像を操り、熱砂防衛線で光霊と共に暗鬼と戦い…",
  ui_story_1013_10130101_139_dialog_content = "天空ノ谷では、啓光や白夜城、\n果ては北境とも力を合わせ、暗鬼を撃退した…",
  ui_story_1013_10130101_140_dialog_content = "あなたの残した功績に私たちは皆、敬服しています。",
  ui_story_1013_10130101_141_option_content = "自分にできることをしただけだよ",
  ui_story_1013_10130101_142_dialog_content = "だって、暗鬼は共通の敵でしょ？",
  ui_story_1013_10130101_143_option_content = "皆と一緒に頑張った結果だよ",
  ui_story_1013_10130101_144_dialog_content = "もし僕一人だけで、皆の助けがなかったら、\nそんなことはとてもできなかった。",
  ui_story_1013_10130101_145_dialog_content = "うわさ通り、謙虚な方ですね。",
  ui_story_1013_10130101_146_dialog_content = "自己紹介させてください。私はショウと申します。\n西方のトワイライトシティで参謀長を務めております。",
  ui_story_1013_10130101_147_dialog_content = "こちらの2人は、助手のクロウとショーン。",
  ui_story_1013_10130101_148_dialog_content = "ここであなたに会えるとは思っていませんでした。\n実に幸運なことです。",
  ui_story_1013_10130101_149_dialog_content = "初めまして、僕はPlayerName。",
  ui_story_1013_10130101_150_dialog_content = "初めまして、PlayerName！",
  ui_story_1013_10130101_151_dialog_content = "はじめまして。",
  ui_story_1013_10130101_152_dialog_content = "さきほどは失礼した。\nショウの護衛が私の使命なのでな。",
  ui_story_1013_10130101_153_dialog_content = "気にしないで。\n僕の方こそ、盗み見なんて失礼なことしちゃって…",
  ui_story_1013_10130101_154_dialog_content = "参謀長から君の話はよく聞いてるよ！",
  ui_story_1013_10130101_155_dialog_content = "巨像に乗っていろんなところへ行けるなんて、\nほんと、うらやましいな！",
  ui_story_1013_10130101_156_dialog_content = "巨像が有れば、遠いところへ行くにも、便利なんでしょ？",
  ui_story_1013_10130101_157_dialog_content = "確かに便利だよ。\n巨像に乗れば、どこであろうとあっという間だね。",
  ui_story_1013_10130101_158_dialog_content = "すごいなぁ！\n僕も巨像みたいな乗り物が欲しいよ。",
  ui_story_1013_10130101_159_dialog_content = "トワイライトシティまでだってひとっ飛びだ！",
  ui_story_1013_10130101_160_dialog_content = "え？何か急ぎの用でもあるの？",
  ui_story_1013_10130101_161_dialog_content = "もちろんだよ！",
  ui_story_1013_10130101_162_dialog_content = "トワイライトシティのこと、知らないの？",
  ui_story_1013_10130101_163_dialog_content = "ごめん、よく知らないんだ。\nどこにあるの？",
  ui_story_1013_10130101_164_dialog_content = "トワイライトシティは啓光の防衛線の外にある町で、\nカナン城からはかなり距離があります。",
  ui_story_1013_10130101_165_dialog_content = "内側の町よりも暗鬼の襲撃には遭いやすいですが…\nそれでも、とてもいいところですよ。",
  ui_story_1013_10130101_166_dialog_content = "早く戻って、みんなと一緒に\n暗鬼をブッ飛ばしたいんだ！",
  ui_story_1013_10130101_167_dialog_content = "まったくイヤになっちゃうよ。\nたいした傷でもないのに、カナン城で治療を受けろって言われてさ。",
  ui_story_1013_10130101_168_dialog_content = "でも、検査も終わったから、\n今日の午後にはトワイライトシティに戻れるんだ！",
  ui_story_1013_10130101_169_dialog_content = "医者もあなたのためを思って言ったこと。",
  ui_story_1013_10130101_170_dialog_content = "健康な状態でいればこそ、\n多くの敵を倒す力を保てる。",
  ui_story_1013_10130101_171_dialog_content = "どこぞの誰かのように、\n無理をして自分を痛めつけてはいけない。",
  ui_story_1013_10130101_172_dialog_content = "オホン、オホン…\nそれでは、PlayerName、私たちはこれで。",
  ui_story_1013_10130101_173_dialog_content = "機会があれば、\nぜひトワイライトシティにいらしてください。",
  ui_story_1013_10130101_174_dialog_content = "空の末裔と、ぜひ共に戦ってみたいものです。",
  ui_story_1013_10130101_175_dialog_content = "機会があれば、必ず行くよ。",
  ui_story_1013_10130101_176_dialog_content = "それでは、また。",
  ui_story_1013_10130101_177_dialog_content = "また。",
  ui_story_1013_10130101_178_dialog_content = "またね～！",
  ui_story_1013_10130101_179_dialog_content = "トワイライトシティ…\nそうとう遠くなんだろうなぁ。",
  ui_story_1013_10130101_180_dialog_content = "ん？診察室から出てきたのって…",
  ui_story_1013_10130101_181_dialog_content = "レインハト大元帥！？",
  ui_story_1013_10130101_182_dialog_content = "おや？PlayerNameではないか。",
  ui_story_1013_10130101_183_dialog_content = "バイスを連れてカナン城に来ているとはビビアンから聞いていたが、\nここで会えるとは思っていなかったな。",
  ui_story_1013_10130101_184_dialog_content = "僕もびっくりしました。",
  ui_story_1013_10130101_185_dialog_content = "どうしてここに？",
  ui_story_1013_10130101_186_dialog_content = "まさか…ソラヴァンの医療システムを使った後遺症で、\n身体に何か起こったとか…？",
  ui_story_1013_10130101_187_dialog_content = "いや、バートンやバイスとは違う。",
  ui_story_1013_10130101_188_dialog_content = "ただの定期検査だ。",
  ui_story_1013_10130101_189_dialog_content = "半年に1回が規則でな。\n血液検査やら、身体能力の検査やら…",
  ui_story_1013_10130101_190_dialog_content = "結果は前回と大差なかった。\n心配するな。",
  ui_story_1013_10130101_191_dialog_content = "そうだったんですね。何もないなら安心しました。\nあの時の傷の具合はどうですか？",
  ui_story_1013_10130101_192_dialog_content = "ハハハ、心配するな。\nソラヴァンのおかげで、傷口はとっくにふさがっていた。",
  ui_story_1013_10130101_193_dialog_content = "啓光にも、あのような設備があればな…",
  ui_story_1013_10130101_194_dialog_content = "戻ったぞ。",
  ui_story_1013_10130101_195_dialog_content = "お？大元帥も来てたのか。",
  ui_story_1013_10130101_196_dialog_content = "PlayerName…えっ、大元帥様！？",
  ui_story_1013_10130101_197_dialog_content = "2人とも、検査は終わったか？結果はどうだ？",
  ui_story_1013_10130101_198_dialog_content = "結果…何と説明したらいいのか…",
  ui_story_1013_10130101_199_dialog_content = "報告するぜ！\n検査の結果は――「結果なし」だ！",
  ui_story_1013_10130101_200_dialog_content = "えっ！？",
  ui_story_1013_10130101_201_dialog_content = "医者やら科学者やらが、いろいろ使って俺たちの身体を検査しまくったが…\n何も見つからなかったんだよ。",
  ui_story_1013_10130101_202_dialog_content = "やるべき検査は全部やったが、\n正常な状態と何の違いもねえってよ。",
  ui_story_1013_10130101_203_dialog_content = "その通りです。少なくとも検査の結果では、\n何の異常もありませんでした。",
  ui_story_1013_10130101_204_dialog_content = "でも、今はもう光ってないみたいだね。\nどうやって治したの？",
  ui_story_1013_10130101_205_dialog_content = "おお、それか！",
  ui_story_1013_10130101_206_dialog_content = "検査の時、科学者のやつらによ、\n訓練用のダミーを光力術で攻撃してみろって言われてな。",
  ui_story_1013_10130101_207_dialog_content = "たぶん、光力の流失が術の威力に影響してねえか、\n見たかったってとこだろう。",
  ui_story_1013_10130101_208_dialog_content = "ともかく、ダミーを思いっきり攻撃してやったら、\n自然と身体の光が消えたってワケだ。",
  ui_story_1013_10130101_209_dialog_content = "そうと分かってたなら、\n暗鬼でもぶちのめしておきゃぁよかったぜ！",
  ui_story_1013_10130101_210_dialog_content = "科学者の先生がたの話だと、\nバートン軍団長、ダミーを10体も壊したそうです…",
  ui_story_1013_10130101_211_dialog_content = "ほう？ならば、修理代は\n第二軍団長の今月の配給から差し引いておくか。",
  ui_story_1013_10130101_212_dialog_content = "な、なんだって！？",
  ui_story_1013_10130101_213_dialog_content = "ハハハ…冗談だ。",
  ui_story_1013_10130101_214_dialog_content = "2人とも何もなかったのなら、それでいい。\nただし、今は何ともないからと言って、気を緩めてはならない。",
  ui_story_1013_10130101_215_dialog_content = "しばらくは定期的に検査を受け、\n万が一のことがないよう努めよ。",
  ui_story_1013_10130101_216_dialog_content = "了解！",
  ui_story_1013_10130101_217_dialog_content = "はい！",
  ui_story_1013_10130101_218_dialog_content = "…そういうわけで、何も異常はなかったの。",
  ui_story_1013_10130101_219_dialog_content = "だから、PlayerNameも心配しないで。",
  ui_story_1013_10130101_220_dialog_content = "光力が少し流失しているだけなら、\n今のところ確かに問題はなさそうだけど…",
  ui_story_1013_10130101_221_dialog_content = "ハーモナイザーっていう正体不明のものを使った以上、\n他にも何か起こらないか、心配にはなるよ。",
  ui_story_1013_10130101_222_dialog_content = "未知のものほど怖いものはないから…",
  ui_story_1013_10130101_223_dialog_content = "先生がたもそう言ってたわ。",
  ui_story_1013_10130101_224_dialog_content = "だから、いろいろなことをしてる時、\n身体の変化に注意するようにって言われてるわ。",
  ui_story_1013_10130101_225_dialog_content = "うん、僕も気を付けておくよ！",
  ui_story_1013_10130101_226_dialog_content = "そのことについて、提案がある。",
  ui_story_1013_10130101_227_dialog_content = "いや、正確には頼み事と言うべきだな。",
  ui_story_1013_10130101_228_dialog_content = "PlayerName、啓光連邦に\nソラヴァンと回帰の塔を研究する許可を与えてほしい。",
  ui_story_1013_10130101_229_dialog_content = "えっ！？",
  ui_story_1013_10130101_230_dialog_content = "どうしてですか？\n理由を聞かせてもらえますか？",
  ui_story_1013_10130101_231_dialog_content = "むろん、説明する。",
  ui_story_1013_10130101_232_dialog_content = "これまでのことを通して、私も啓光の科学研究員たちも、\n空の末裔の科学技術がいかに強大なものか、思い知った。",
  ui_story_1013_10130101_233_dialog_content = "特にハーモナイザーと医療装置…\nあれを使えるようになれば、無数の光霊の命を救うことにつながる。",
  ui_story_1013_10130101_234_dialog_content = "巨像のシミュレーション室も、大きな可能性を秘めた装置だ。",
  ui_story_1013_10130101_235_dialog_content = "現実さながらの環境で指揮官を訓練できれば、\n死傷者も減少するだろう。",
  ui_story_1013_10130101_236_dialog_content = "でも…",
  ui_story_1013_10130101_237_dialog_content = "（空の末裔の科学技術が、戦争を起こすためのものだったなら…\n研究なんかして、本当に大丈夫かな？）",
  ui_story_1013_10130101_238_dialog_content = "お前の心配も理解している。",
  ui_story_1013_10130101_239_dialog_content = "だからこそ、私が直接保証する――",
  ui_story_1013_10130101_240_dialog_content = "啓光連邦は決して、空の末裔の技術を不当に用いない。",
  ui_story_1013_10130101_241_dialog_content = "むろん、それ相応の報酬も用意する。",
  ui_story_1013_10130101_242_dialog_content = "啓光にいる最高レベルの科学者を派遣し、\nソラヴァンの修復を手伝わせよう。",
  ui_story_1013_10130101_243_dialog_content = "…",
  ui_story_1013_10130101_244_dialog_content = "バイス、どう思う？",
  ui_story_1013_10130101_245_dialog_content = "私？",
  ui_story_1013_10130101_246_dialog_content = "啓光にも進んだ医療技術があったらとは思うけど…",
  ui_story_1013_10130101_247_dialog_content = "でも、PlayerName。天空ノ谷はあなたの家よ。\nどうするかは、あなたが決めないと。",
  ui_story_1013_10130101_248_dialog_content = "PlayerName、お前自身はどうだ？",
  ui_story_1013_10130101_249_dialog_content = "おいおい、ちょっと待てよ、大元帥。",
  ui_story_1013_10130101_250_dialog_content = "今すぐ答えろってのは、\nちょいと急ぎすぎじゃねえか？",
  ui_story_1013_10130101_251_dialog_content = "こいつは簡単に決められることじゃねえだろ。",
  ui_story_1013_10130101_252_dialog_content = "少し時間をやれよ。\nよく考えてから、決めさせてやれ。",
  ui_story_1013_10130101_253_dialog_content = "…",
  ui_story_1013_10130101_254_dialog_content = "すまない。ことを急ぎすぎた。",
  ui_story_1013_10130101_255_dialog_content = "考える時間が必要だというなら、あせらずともよい。\nお前の返事を待とう。",
  ui_story_1013_10130101_256_dialog_content = "僕は…",
  ui_story_1013_10130101_257_dialog_content = "大丈夫です。",
  ui_story_1013_10130101_258_option_content = "同意します",
  ui_story_1013_10130101_259_dialog_content = "それはよかった。\n礼を言うぞ、PlayerName。",
  ui_story_1013_10130101_260_option_content = "大元帥さんを信じます",
  ui_story_1013_10130101_261_dialog_content = "…！",
  ui_story_1013_10130101_262_dialog_content = "礼を言うぞ、PlayerName。",
  ui_story_1013_10130101_263_dialog_content = "そうと決まれば、善は急げだ。\n今すぐ研究所の科学者に連絡し、準備させることとしよう。",
  ui_story_1013_10130101_264_dialog_content = "PlayerNameとバイスにも同行願おう。\nお前たちの手助けが必要になるだろう。手間をかけるが、頼んだぞ。",
  ui_story_1013_10130101_265_dialog_content = "いいですよ。\nソラヴァンを直すのを手伝ってもらうんだし、お互い様です。",
  ui_story_1013_10130101_266_dialog_content = "喜んで！\n啓光のために尽くすことは、当然の務めです！",
  ui_story_1013_10130101_267_dialog_content = "ま、俺の出番はもうなさそうだな。",
  ui_story_1013_10130101_268_dialog_content = "第二軍団の仕事に戻るとするか。",
  ui_story_1013_10130101_269_dialog_content = "PlayerName、今度またチェスでもやろうぜ。",
  ui_story_1013_10130101_270_dialog_content = "うん、約束だよ！",
  ui_story_1013_10130201_1_dialog_content = "ここが啓光連邦研究所の事務室だ。",
  ui_story_1013_10130201_2_dialog_content = "2人は初めてだろう？",
  ui_story_1013_10130201_3_dialog_content = "は、はい！",
  ui_story_1013_10130201_4_dialog_content = "啓光連邦で最も優秀な科学者が集まる場所だと、\n前々から聞いてはいましたが…",
  ui_story_1013_10130201_5_dialog_content = "この目で見られる日が来るとは、\n思ってもいませんでした！",
  ui_story_1013_10130201_6_dialog_content = "人がいっぱいだ！",
  ui_story_1013_10130201_7_dialog_content = "当然だ。ここにいる者は皆、\n啓光のために日々力を尽くしている。",
  ui_story_1013_10130201_8_dialog_content = "彼らのような科学者たちの努力が、\n今の啓光を築いたのだ。",
  ui_story_1013_10130201_9_dialog_content = "あれ～、大元帥？\nそれからバイスと、あたしの負け犬クン！",
  ui_story_1013_10130201_10_option_content = "ガルー！？",
  ui_story_1013_10130201_11_dialog_content = "どうしてここに？",
  ui_story_1013_10130201_12_dialog_content = "大元帥から、ミジャードと一緒に実験を手伝うように言われたの。\nソラヴァンの新機能を好きなだけ研究できるらしいじゃない？",
  ui_story_1013_10130201_13_dialog_content = "ソラヴァンの研究なんて、ハードモードのゲームよりずっと面白そうでしょ！\nそれで、飛んできたの！",
  ui_story_1013_10130201_14_dialog_content = "頼むから、ソラヴァンに優しくしてあげてね…",
  ui_story_1013_10130201_15_dialog_content = "もう、安心してよ。\nいちばん安全なプランで研究してあげるから！",
  ui_story_1013_10130201_16_dialog_content = "ボーヤ、久しぶりじゃない。",
  ui_story_1013_10130201_17_dialog_content = "ミジャード…久しぶり…",
  ui_story_1013_10130201_18_dialog_content = "（悪意はないのはよく分かってるんだけど、\nミジャードに会うと、どうしても緊張しちゃうな…）",
  ui_story_1013_10130201_19_dialog_content = "あら？その顔は何かしら？",
  ui_story_1013_10130201_20_dialog_content = "けさ啓光に着いた時から、\nずっと沈んだ顔してるわね。",
  ui_story_1013_10130201_21_dialog_content = "バイスが心配で…",
  ui_story_1013_10130201_22_dialog_content = "あれ？ちょっと待って。いま会ったばかりだよね。\nどうして知ってるの？まさか、僕が気づかなかった？",
  ui_story_1013_10130201_23_dialog_content = "フフ…忘れてもらっちゃ困るわ。\n忍び寄る棘は、いつでも啓光の隅々まで見ているのよ。",
  ui_story_1013_10130201_24_dialog_content = "その場にいなくたって、何もかもお見通しよ。",
  ui_story_1013_10130201_25_dialog_content = "な、なるほど…",
  ui_story_1013_10130201_26_dialog_content = "ほらほら、早く行こ！\n研究所のみんなが待ちくたびれちゃう！",
  ui_story_1013_10130201_27_dialog_content = "PlayerName、行きましょ！",
  ui_story_1013_10130201_28_dialog_content = "みんな～！PlayerNameが来たよ～！",
  ui_story_1013_10130201_29_dialog_content = "この方がウワサのPlayerNameですか？\nおうわさはかねがね。",
  ui_story_1013_10130201_30_dialog_content = "ずいぶんと若いですな。\nまあ、実験台としては…ぎりぎり合格といったところか。",
  ui_story_1013_10130201_31_dialog_content = "実験台！？",
  ui_story_1013_10130201_32_dialog_content = "PlayerNameは仲間です。\n実験台なんかじゃありません！",
  ui_story_1013_10130201_33_dialog_content = "ハハ、気にするな。\n研究者というものは多かれ少なかれ、変わり者ばかりでな。",
  ui_story_1013_10130201_34_dialog_content = "悪意があるわけではない、安心してくれ。",
  ui_story_1013_10130201_35_dialog_content = "大元帥、ご指示通り、研究所の準備は整っております。\nいつでも研究を開始できますぞ。",
  ui_story_1013_10130201_36_dialog_content = "そうか。だが、その前に1つ、\nやっておくべきことがある。",
  ui_story_1013_10130201_37_dialog_content = "どんなことですか？",
  ui_story_1013_10130201_38_dialog_content = "それは――お前に感謝を表明することだ。",
  ui_story_1013_10130201_39_dialog_content = "えっ？",
  ui_story_1013_10130201_40_dialog_content = "お礼なら、さっき言われましたよ？",
  ui_story_1013_10130201_41_dialog_content = "あれは私個人としての感謝だ。\n今回は、啓光連邦の大元帥としてお前に感謝の意を表する。",
  ui_story_1013_10130201_42_dialog_content = "啓光連邦による研究が許可されたことで、\n今後、多くの光霊が救われるだろう。",
  ui_story_1013_10130201_43_dialog_content = "ありがとう、PlayerName！",
  ui_story_1013_10130201_44_dialog_content = "感謝するわ、ボーヤ。\nま、仕事の量は増えちゃうけど。",
  ui_story_1013_10130201_45_dialog_content = "ありがとうございます！",
  ui_story_1013_10130201_46_dialog_content = "君の貢献に感謝するよ、実験台君。",
  ui_story_1013_10130201_47_dialog_content = "僕は何もしてませんよ？",
  ui_story_1013_10130201_48_dialog_content = "いいから、素直に感謝を受け取って。",
  ui_story_1013_10130201_49_dialog_content = "これから起こることは、\nあなたの同意がなかったら、実現しなかったんだから。",
  ui_story_1013_10130201_50_dialog_content = "うん…",
  ui_story_1013_10130201_51_dialog_content = "あの、あんまり見ないでもらえますか？\n恥ずかしいので…",
  ui_story_1013_10130201_52_dialog_content = "研究を始めるんですよね？",
  ui_story_1013_10130201_53_dialog_content = "ははは、そうだな。",
  ui_story_1013_10130201_54_dialog_content = "では、後は計画通りに。",
  ui_story_1013_10130201_55_dialog_content = "はい！",
  ui_story_1013_10130201_56_dialog_content = "大元帥の指示に従って、3チームに分かれるよ。",
  ui_story_1013_10130201_57_dialog_content = "Aチームは回帰の塔に向かって、\nハーモナイザーの情報を収集！",
  ui_story_1013_10130201_58_dialog_content = "Bチームは私に付いてきなさい。\nソラヴァンの医療システムに関するデータを集めるわ。",
  ui_story_1013_10130201_59_dialog_content = "オッケー、残りのCチームは私の指示に従って。\nデータ伝送ケーブルをソラヴァンのシミュレーション室につないで。",
  ui_story_1013_10130201_60_dialog_content = "啓光の戦闘シミュレーションシステムで\nデータを解析できるか試してみるから。",
  ui_story_1013_10130201_61_dialog_content = "了解！",
  ui_story_1013_10130201_62_dialog_content = "啓光にも戦闘シミュレーションシステムがあるんですか？",
  ui_story_1013_10130201_63_dialog_content = "ああ。ソラヴァンにシミュレーション室を実装した時、\nガルーが研究用にデータを一部持ち帰ってきた。",
  ui_story_1013_10130201_64_dialog_content = "そのデータをもとに、\nソラヴァンのシミュレーション室をまねて機器を作ったのだ。",
  ui_story_1013_10130201_65_dialog_content = "…まぁ、当初の目的は、\n遊びに使う物を作りたかっただけのようだが…",
  ui_story_1013_10130201_66_dialog_content = "最終的には、すばらしいものができた！",
  ui_story_1013_10130201_67_dialog_content = "そこまで言うほどなんですか！？",
  ui_story_1013_10130201_68_dialog_content = "その通りだ。興味があるなら、\n後で実験のついでに、試してみるがいい。",
  ui_story_1013_10130201_69_dialog_content = "分かりました。試してみます！",
  ui_story_1013_10130201_70_dialog_content = "たっぷり練習しておいて、\n負け犬呼ばわりを返上しないと！",
  ui_story_1013_10130201_71_dialog_content = "<color=#e8d9bb>数時間後</color>",
  ui_story_1013_10130201_72_dialog_content = "報告よ、大元帥。",
  ui_story_1013_10130201_73_dialog_content = "何か分かったか？",
  ui_story_1013_10130201_74_dialog_content = "いい知らせね。ソラヴァンの新しいモジュールの中から、\n医療装置の製造方法に関するデータが見つかったわ。",
  ui_story_1013_10130201_75_dialog_content = "そのデータを利用すれば、\n医療センターの設備をアップグレードできそうよ。",
  ui_story_1013_10130201_76_dialog_content = "すばらしい！",
  ui_story_1013_10130201_77_dialog_content = "他にも何か新たな発見がないか、\n研究を継続せよ。",
  ui_story_1013_10130201_78_dialog_content = "了解。",
  ui_story_1013_10130201_79_dialog_content = "医療装置…",
  ui_story_1013_10130201_80_dialog_content = "さっき会ったショウって人、\nすごく身体が弱そうだったなぁ…",
  ui_story_1013_10130201_81_dialog_content = "医療装置をアップグレードできたら、\nあの人の病気も治せるのかな？",
  ui_story_1013_10130201_82_dialog_content = "ショウを知っているのか？",
  ui_story_1013_10130201_83_dialog_content = "あ、えっと…はい。\nさっき医療センターで偶然知り合いました。",
  ui_story_1013_10130201_84_dialog_content = "そうか。",
  ui_story_1013_10130201_85_dialog_content = "ショウはトワイライトシティ駐留軍の参謀長だ。\nとびぬけて優れた頭脳をもっているのだが、身体が弱くてな。",
  ui_story_1013_10130201_86_dialog_content = "昔、重傷を負ったことが原因だ。\n暗力に器官を侵され、戦えなくなった。",
  ui_story_1013_10130201_87_dialog_content = "それで、あんなに弱ってる様子だったんですね。",
  ui_story_1013_10130201_88_dialog_content = "部下のショーンも身体に問題を抱えている。",
  ui_story_1013_10130201_89_dialog_content = "ショーン？\n元気そうでしたよ？",
  ui_story_1013_10130201_90_dialog_content = "それは日頃の鍛錬の成果にすぎん。",
  ui_story_1013_10130201_91_dialog_content = "遺伝子にとても複雑な欠陥があるそうだ。",
  ui_story_1013_10130201_92_dialog_content = "それが原因で、入隊したばかりの頃は重視されていなかった。\n遠く離れた駐屯地に送られ、下級兵士に甘んじていたのだ。",
  ui_story_1013_10130201_93_dialog_content = "今のショーンがあるのは、\nすべて本人が不屈の精神で成し遂げたことと言える。",
  ui_story_1013_10130201_94_dialog_content = "確かに、ショーンからは\nいつも戦場の中で鍛えられてる人の気迫みたいなものを感じました。",
  ui_story_1013_10130201_95_dialog_content = "ああ。医療装置の改良がかなったあかつきには、\n彼らのような者が一番に恩恵を受けるだろう。",
  ui_story_1013_10130201_96_dialog_content = "大元帥、ハーモナイザーの研究に進展がありました。",
  ui_story_1013_10130201_97_dialog_content = "え、もう！？",
  ui_story_1013_10130201_98_dialog_content = "啓光の技術水準を見くびってもらっては困りますな、実験台君。",
  ui_story_1013_10130201_99_dialog_content = "それはそうと、大元帥。\nハーモナイザーについての報告ですが…",
  ui_story_1013_10130201_100_dialog_content = "（…今、僕の方を見た？）",
  ui_story_1013_10130201_101_dialog_content = "PlayerNameは天空ノ谷の主であり、\nハーモナイザーの持ち主だ。",
  ui_story_1013_10130201_102_dialog_content = "PlayerNameに隠すようなことは何もない。",
  ui_story_1013_10130201_103_dialog_content = "左様ですか。\nでは、実験台君にも分かるよう、簡単にご説明しましょう。",
  ui_story_1013_10130201_104_dialog_content = "バートン軍団長とバイス中尉の検査結果から、\n装置の用途について、おおよそ見当がつきました。",
  ui_story_1013_10130201_105_dialog_content = "ハーモナイザーは光霊の身体を改造するほか、\n潜在能力を引き出す効果もあるのではないかと推測されます。",
  ui_story_1013_10130201_106_option_content = "身体を改造する？",
  ui_story_1013_10130201_107_dialog_content = "気づきませんでしたかな？\nバートン軍団長とバイス中尉の外見が変わっていたでしょう。",
  ui_story_1013_10130201_108_dialog_content = "気づいてます。でも、見た目以外に何か変わったんですか？\n他にどんな影響が？",
  ui_story_1013_10130201_109_dialog_content = "それは、もう少し研究してみないと何とも言えませんな。",
  ui_story_1013_10130201_110_dialog_content = "ただ1つ言えることは、\n改造が光力術に影響を及ぼしているということでしょう。",
  ui_story_1013_10130201_111_option_content = "潜在能力を引き出す？",
  ui_story_1013_10130201_112_dialog_content = "その通り。ハーモナイザーは2人の身体を改造し、\n光力術の使い方にも変化が起こったというわけです。",
  ui_story_1013_10130201_113_dialog_content = "もともとは使えなかった…\nもしくは使うのが難しかった強大な力を、扱えるようになったのです。",
  ui_story_1013_10130201_114_dialog_content = "これを理解するには、\n光力術の原理から説明する必要があるのですが…",
  ui_story_1013_10130201_115_dialog_content = "実験台君は、光力術について\n丸1日講義を聞くつもりがおありかな？",
  ui_story_1013_10130201_116_dialog_content = "ええと…い、今は遠慮しておきます。",
  ui_story_1013_10130201_117_dialog_content = "ともあれ、そこまで心配する必要はありません。",
  ui_story_1013_10130201_118_dialog_content = "ハーモナイザーの使用後も、\n今まで通り、2人はもともと持っていた術を使えるようです。",
  ui_story_1013_10130201_119_dialog_content = "要するに、本質的には変わっていないということですな。",
  ui_story_1013_10130201_120_dialog_content = "…そうですか…",
  ui_story_1013_10130201_121_dialog_content = "何だか深刻な話？",
  ui_story_1013_10130201_122_dialog_content = "手に持っているのは…\n戦闘シミュレーションシステムの装置か。",
  ui_story_1013_10130201_123_dialog_content = "何か進展があったのか？",
  ui_story_1013_10130201_124_dialog_content = "もちろん！",
  ui_story_1013_10130201_125_dialog_content = "戦闘シミュレーションシステムから、\nソラヴァンのデータベースにアクセスしたの。",
  ui_story_1013_10130201_126_dialog_content = "そこから研究を進めてたら…\nソラヴァンの新しい部品の機能が一部起動したみたい。",
  ui_story_1013_10130201_127_dialog_content = "シミュレーション室が自動でアップデートされて、\n本物の戦場を完全に再現できるようになった感じ！",
  ui_story_1013_10130201_128_dialog_content = "これからシミュレーションシステムを使って、\n実際に体験しようとしてるところ。",
  ui_story_1013_10130201_129_dialog_content = "PlayerName、さっき戦闘シミュレーションシステムに\n興味あるって言ってたよね？",
  ui_story_1013_10130201_130_dialog_content = "どう？やってみない？",
  ui_story_1013_10130201_131_option_content = "難しそうだね？",
  ui_story_1013_10130201_132_dialog_content = "困らせたりはしないって！\n新しいゲームならまずは、一番簡単なところから始めるでしょ！",
  ui_story_1013_10130201_133_dialog_content = "じゃあ、試してみたい！",
  ui_story_1013_10130201_134_option_content = "もちろん！",
  ui_story_1013_10130201_135_dialog_content = "面白そうだね！",
  ui_story_1013_10130201_136_dialog_content = "それじゃ、PlayerName…\nそっちのイスに座って、このヘッドセットをかぶって！",
  ui_story_1013_10130201_137_dialog_content = "うん。",
  ui_story_1013_10130201_138_dialog_content = "え？周りの景色が変わった！？",
  ui_story_1013_10130201_139_dialog_content = "PlayerName、聞こえる？",
  ui_story_1013_10130201_140_dialog_content = "え、バイス！？どこにいるの？",
  ui_story_1013_10130201_141_dialog_content = "すぐ近くにいるわよ！",
  ui_story_1013_10130201_142_dialog_content = "こっちのモニターに、\nあなたが見てるものと同じ映像が写ってるわ。",
  ui_story_1013_10130201_143_dialog_content = "どうだ、PlayerName。\n何が見える？",
  ui_story_1013_10130201_144_dialog_content = "何もない荒野と…\nそれから、気持ちのいい日差しと風です。",
  ui_story_1013_10130201_145_dialog_content = "だったら、成功ね！",
  ui_story_1013_10130201_146_dialog_content = "今見えてる景色が、\n戦闘シミュレーションシステムの初期画面よ。",
  ui_story_1013_10130201_147_dialog_content = "PlayerName、今度は仲間が近くにいるって想像してみて！",
  ui_story_1013_10130201_148_dialog_content = "仲間の姿を想像すればいいの？",
  ui_story_1013_10130201_149_dialog_content = "そう！",
  ui_story_1013_10130201_150_dialog_content = "想像したものを、\n啓光に現存するデータを使って投影するシステムなの。",
  ui_story_1013_10130201_151_dialog_content = "その光霊のイメージが、\n戦闘テストの手助けをしてくれるよ。",
  ui_story_1013_10130201_152_option_content = "バイスの姿を想像する",
  ui_story_1013_10130201_153_dialog_content = "わっ！？",
  ui_story_1013_10130201_154_dialog_content = "で、出てきた！",
  ui_story_1013_10130201_155_dialog_content = "すごいわ、本物の私そっくり！",
  ui_story_1013_10130201_156_dialog_content = "よかった！特に問題なさそうね。",
  ui_story_1013_10130201_157_dialog_content = "それじゃ、暗鬼を投影するよ――",
  ui_story_1013_10130201_158_dialog_content = "グアアオ！",
  ui_story_1013_10130201_159_dialog_content = "え！？暗鬼まで本物そっくりだ。",
  ui_story_1013_10130201_160_dialog_content = "暗力まで感じられる！？",
  ui_story_1013_10130201_161_dialog_content = "怖がらないで、PlayerName。",
  ui_story_1013_10130201_162_dialog_content = "こんなの、一番イージーなテストだからね！",
  ui_story_1013_10130201_163_dialog_content = "光霊を指揮して、暗鬼をやっつけて！",
  ui_story_1013_10130201_164_dialog_content = "がんばって、PlayerName！",
  ui_story_1013_10130201_165_dialog_content = "うん、がんばるよ！",
  ui_story_1013_10130201_166_dialog_content = "選択難易度：イージー。",
  ui_story_1013_10130201_167_dialog_content = "通常モード、ステージ番号：01。",
  ui_story_1013_10130201_168_dialog_content = "ステージ目標：暗鬼すべての撃破。",
  ui_story_1013_10130201_169_dialog_content = "戦闘シミュレーションを開始します。",
  ui_story_1013_10130201_170_dialog_content = "<anim type=Shake><size=50>グオオ！！！</size></anim>",
  ui_story_1013_10130302_1_dialog_content = "はぁ、はぁ…暗鬼を…全部、倒したよ！",
  ui_story_1013_10130302_2_dialog_content = "ステージ目標を達成しました。",
  ui_story_1013_10130302_3_dialog_content = "テスト終了。\n本ステージの評価はAです。",
  ui_story_1013_10130302_4_dialog_content = "すごいじゃない、PlayerName！\n初めてなのにA評価なんて！",
  ui_story_1013_10130302_5_dialog_content = "ちょっと待ってね…シミュレーターとの接続を切るから。\nその後は、ヘッドセットをとってオッケーだよ。",
  ui_story_1013_10130302_6_dialog_content = "接続が解除されました。\n安全にログアウトすることができます。",
  ui_story_1013_10130302_7_dialog_content = "う～ん…",
  ui_story_1013_10130302_8_dialog_content = "PlayerName、大丈夫？\n具合でも悪くなった？",
  ui_story_1013_10130302_9_dialog_content = "大丈夫だよ。ただ本当に暗鬼と戦った時みたいで、\n心も身体もへとへとだ。",
  ui_story_1013_10130302_10_dialog_content = "ははは、それはご苦労だったな、PlayerName。",
  ui_story_1013_10130302_11_dialog_content = "だが、おかげでこの技術の有用性がはっきりした。",
  ui_story_1013_10130302_12_dialog_content = "ソラヴァンのシミュレーション室の機能を借りれば、\n実際の戦場の状況を完全に再現できる。",
  ui_story_1013_10130302_13_dialog_content = "座学と演習盤だけで臨場感のない教育より、\nずっと効果が高い！",
  ui_story_1013_10130302_14_dialog_content = "私も試してみたくなってきたわ！",
  ui_story_1013_10130302_15_dialog_content = "う～ん、それはまだダメなんだよね。",
  ui_story_1013_10130302_16_dialog_content = "そもそも空の末裔用の技術だから…\n今のところ、PlayerName以外は動かせないよ。",
  ui_story_1013_10130302_17_dialog_content = "もちろん、原理を完全に解析できれば、\n光霊も使えるものに改造できるけどね！",
  ui_story_1013_10130302_18_dialog_content = "今から戦闘シミュレーションシステムを最優先とすれば、\n合同演習までに間に合うか？",
  ui_story_1013_10130302_19_dialog_content = "この技術を演習で使えれば、\n多くの者が興味を持つだろう。",
  ui_story_1013_10130302_20_dialog_content = "PlayerNameが協力してくれれば、\nたぶんダイジョーブ！",
  ui_story_1013_10130302_21_dialog_content = "合同演習って何ですか？",
  ui_story_1013_10130302_22_dialog_content = "2年に1度開催される、大規模な演習のことよ！",
  ui_story_1013_10130302_23_dialog_content = "啓光連邦以外にも、\n白夜城や北境、影ノ街まで参加するの。",
  ui_story_1013_10130302_24_dialog_content = "各勢力の協調を図るだけじゃなく、\n最も優秀な若い人たちが、いろんな種目で腕を競い合うわ。",
  ui_story_1013_10130302_25_dialog_content = "演習の最後には、\n参加者が実際に戦場に出て、暗鬼と戦うの！",
  ui_story_1013_10130302_26_dialog_content = "大勢の人が参加するみたいだね…",
  ui_story_1013_10130302_27_dialog_content = "当然でしょ！",
  ui_story_1013_10130302_28_dialog_content = "個人種目の優勝争いは激しいわよ！",
  ui_story_1013_10130302_29_dialog_content = "だって、優勝者は大元帥様に\n1対1で手合わせしてもらえるんだもの！",
  ui_story_1013_10130302_30_dialog_content = "えっ！？",
  ui_story_1013_10130302_31_dialog_content = "当初は単なる思いつきで、\n手合わせでもしてやるかと言っただけなのだが…",
  ui_story_1013_10130302_32_dialog_content = "その後いつの間にか、決定事項になっていてな。",
  ui_story_1013_10130302_33_dialog_content = "まぁ、私も若者との手合わせは嫌いではない。",
  ui_story_1013_10130302_34_option_content = "面倒くさいとは思わないんですか？",
  ui_story_1013_10130302_35_dialog_content = "思うわけがなかろう！\nむしろ、大いに期待している。",
  ui_story_1013_10130302_36_option_content = "さすが大元帥",
  ui_story_1013_10130302_37_dialog_content = "ハハハ、それはほめ言葉か？\n礼を言って置こう。",
  ui_story_1013_10130302_38_dialog_content = "若き世代の一番の強者と戦えるのは、\n私にとっても喜ばしいことだ。",
  ui_story_1013_10130302_39_dialog_content = "若い世代が成長し、少しずつ強くなっていく…",
  ui_story_1013_10130302_40_dialog_content = "そして最後には私たちを超え、\n新たな時代を導いてゆく。",
  ui_story_1013_10130302_41_dialog_content = "考えただけでも、胸が躍るではないか。",
  ui_story_1013_10130302_42_dialog_content = "それで、今までも誰かと手合わせしたんですか？",
  ui_story_1013_10130302_43_dialog_content = "前回の優勝者はカレンだったわ！",
  ui_story_1013_10130302_44_dialog_content = "2位を10ポイント以上引き離していたの。",
  ui_story_1013_10130302_45_dialog_content = "カレンは確かに若い世代の中でも、\nまれに見る強者だ。",
  ui_story_1013_10130302_46_dialog_content = "前回の手合わせの後で、\n次も優勝すると言っていたな。",
  ui_story_1013_10130302_47_dialog_content = "その時にはきっと、\n私を倒すだけの力をつけてくるとも言っていた。",
  ui_story_1013_10130302_48_dialog_content = "ハハハ…実に楽しみだ。",
  ui_story_1013_10130302_49_dialog_content = "本当にうらやましいわ…",
  ui_story_1013_10130302_50_dialog_content = "私だって、大元帥様にはたくさんご指導いただきたいもの！",
  ui_story_1013_10130302_51_dialog_content = "ならば、己を磨き、優勝することだ！",
  ui_story_1013_10130302_52_dialog_content = "はい！",
  ui_story_1013_10130302_53_dialog_content = "お前もだ、PlayerName！",
  ui_story_1013_10130302_54_dialog_content = "え？僕もですか！？",
  ui_story_1013_10130302_55_dialog_content = "当然だろう。\n別に光霊に限った合同演習ではない。",
  ui_story_1013_10130302_56_dialog_content = "空の末裔がアストラ大陸で活躍していた時代には、\n彼らも光霊と共に戦っていたのだ。",
  ui_story_1013_10130302_57_dialog_content = "お前が参加すれば、\n合同練習に空の末裔の一族が帰ってくる、ということになる！",
  ui_story_1013_10130302_58_dialog_content = "空の末裔が「帰ってくる」…",
  ui_story_1013_10130302_59_dialog_content = "優勝したら、手合わせしてやるぞ！",
  ui_story_1013_10130302_60_dialog_content = "そ、それは遠慮しておきます！",
  ui_story_1013_10130302_61_dialog_content = "そんなことになったら、\n逃げる間もなく終わっちゃいます…",
  ui_story_1013_10130302_62_dialog_content = "そうか？ならば、机上演習で頭脳戦と言うのはどうだ？",
  ui_story_1013_10130302_63_dialog_content = "それなら、ぜひ！",
  ui_story_1013_10130302_64_dialog_content = "よし。では、お前が優勝することを楽しみにしているぞ！",
  ui_story_1013_10130302_65_dialog_content = "お話し中に悪いけど～…",
  ui_story_1013_10130302_66_dialog_content = "今日のテストはこれで全部終わったよ！",
  ui_story_1013_10130302_67_dialog_content = "テスト結果を参考にして、助手と一緒にシステムの調整をするね。\nたぶん、明日には次のテストができるから。",
  ui_story_1013_10130302_68_dialog_content = "残りの仕事は安心して私たちにお任せを。",
  ui_story_1013_10130302_69_dialog_content = "まだテストが必要なの？",
  ui_story_1013_10130302_70_dialog_content = "当然でしょ。今日のは基本的なテストだもん。",
  ui_story_1013_10130302_71_dialog_content = "まだまだたくさんの機能が開発できるはず！",
  ui_story_1013_10130302_72_dialog_content = "でも、ソラヴァンの修理は…",
  ui_story_1013_10130302_73_dialog_content = "忘れてはおりません、ご心配なく。",
  ui_story_1013_10130302_74_dialog_content = "ソラヴァンの修理と戦闘シミュレーションシステムの研究は、\n同時進行しています。",
  ui_story_1013_10130302_75_dialog_content = "ですが、私たちでも少々時間がかかりますので…",
  ui_story_1013_10130302_76_dialog_content = "どうか辛抱強くお待ちください。\n今は肩の力を抜いて、ゆっくりお休みになることです。",
  ui_story_1013_10130302_77_dialog_content = "じゃあ、そうするよ。",
  ui_story_1013_10130302_78_dialog_content = "そうね、もう休んだ方がいいわ。",
  ui_story_1013_10130302_79_dialog_content = "残りの事は、明日にしましょ！",
  ui_story_1013_10130401_1_dialog_content = "<color=#e8d9bb>グゥ…</color>",
  ui_story_1013_10130401_2_dialog_content = "お腹がすいた…",
  ui_story_1013_10130401_3_dialog_content = "<color=#e8d9bb>グウウゥ―…！</color>",
  ui_story_1013_10130401_4_dialog_content = "もうお腹がペコペコだ！",
  ui_story_1013_10130401_5_dialog_content = "昨日は確か、研究所を出た後、バイスに案内されて、\nカナン城に泊まって…",
  ui_story_1013_10130401_6_dialog_content = "目が覚めたら、もうこんな時間なんて。",
  ui_story_1013_10130401_7_dialog_content = "<color=#e8d9bb>グゥ…</color>",
  ui_story_1013_10130401_8_dialog_content = "ダメだ、まずは何か食べなきゃ。",
  ui_story_1013_10130401_9_dialog_content = "これだけ大きいんだし、\nどこかにレストランぐらいあるよね…？",
  ui_story_1013_10130401_10_dialog_content = "あまり高くないといいけど。\n白夜コイン、手持ちがそんなにないし…",
  ui_story_1013_10130401_11_dialog_content = "……ない……",
  ui_story_1013_10130401_12_dialog_content = "…ここにもない…？",
  ui_story_1013_10130401_13_dialog_content = "どうしてないの…！？",
  ui_story_1013_10130401_14_dialog_content = "通りをぐるっと一周したのに、食べ物屋さんが1つもない…\n余計にお腹がすいちゃった…",
  ui_story_1013_10130401_15_dialog_content = "ああ、なんだかクラクラしてきた…",
  ui_story_1013_10130401_16_dialog_content = "あ…食べ物のにおい…？",
  ui_story_1013_10130401_17_dialog_content = "PlayerName！？",
  ui_story_1013_10130401_18_dialog_content = "しっかりして、PlayerName！\nこんなところで寝ちゃダメ！",
  ui_story_1013_10130401_19_option_content = "バ、バイス！？",
  ui_story_1013_10130401_20_dialog_content = "大丈夫？元気がないみたいだけど、どうしたの？",
  ui_story_1013_10130401_21_dialog_content = "何でもないよ。お腹がすいただけなんだ。\nでも、食べ物屋さんが見つからなくて…",
  ui_story_1013_10130401_22_dialog_content = "一通り探し回っても見つからなくて、\n結局、戻って来たところだよ。",
  ui_story_1013_10130401_23_dialog_content = "ごめんなさい、言い忘れてたわ。",
  ui_story_1013_10130401_24_dialog_content = "啓光連邦は配給制だから、\nカナン城の中で食べ物は売ってないの。",
  ui_story_1013_10130401_25_dialog_content = "よそから来た人が物資を手に入れるには、\n手続きをしなくちゃいけないんだけど…",
  ui_story_1013_10130401_26_dialog_content = "昨日は色々あったから、\n申請するのを忘れてたわ…",
  ui_story_1013_10130401_27_dialog_content = "ビビアン長官が今後の配給を手配しておいてくださったから、\n今日の業務が終わったら、一緒に取りに行きましょ！",
  ui_story_1013_10130401_28_dialog_content = "え？そんな面倒な仕組みなの？",
  ui_story_1013_10130401_29_dialog_content = "啓光連邦の生産力にだって限りがあるもの。\nみんなが食事に困らないって言うだけでも、大変なことなのよ！",
  ui_story_1013_10130401_30_dialog_content = "配給制をとっているのだって、ムダをできる限り削減して、\n全員に十分な物資がいきわたるようにするためよ。",
  ui_story_1013_10130401_31_dialog_content = "まぁ、とにかく。\n朝ご飯は持ってきたわ！",
  ui_story_1013_10130401_32_dialog_content = "ほら！",
  ui_story_1013_10130401_33_dialog_content = "やっぱり、食べ物のにおいだったんだね！",
  ui_story_1013_10130401_34_dialog_content = "お腹すいてるでしょ？\nさ、早く食べて！",
  ui_story_1013_10130401_35_dialog_content = "この後、また研究所に行かないといけないんだから！",
  ui_story_1013_10130401_36_dialog_content = "じゃ、遠慮なくもらうね！",
  ui_story_1013_10130401_37_dialog_content = "（啓光連邦って強そうなイメージだったから、\n物資の扱いがそんなに細かいなんて思わなかったな）",
  ui_story_1013_10130401_38_dialog_content = "モグモグ…",
  ui_story_1013_10130401_39_dialog_content = "ああ、やっぱりお腹がいっぱいになると、\n生きてる実感がわくね！",
  ui_story_1013_10130401_40_dialog_content = "そうね。\n食事の時間は、いつだって一番楽しいわ！",
  ui_story_1013_10130401_41_dialog_content = "お腹もいっぱいになったところで、\n今日の仕事を始めようか。",
  ui_story_1013_10130401_42_dialog_content = "確か、今日も戦闘シミュレーションシステムの研究を\n手伝うんだったね？",
  ui_story_1013_10130401_43_dialog_content = "ええ。科学者の先生がたの話だと、\n昨日は夜通しで新しい機能を開発してたらしいわ！",
  ui_story_1013_10130401_44_dialog_content = "一緒に見に行きましょ！",
  ui_story_1013_10130401_45_dialog_content = "うん！",
  ui_story_1013_10130401_46_dialog_content = "<color=#e8d9bb>啓光連邦研究所</color>",
  ui_story_1013_10130401_47_dialog_content = "おはよう、やっと来たか。",
  ui_story_1013_10130401_48_dialog_content = "大元帥！？",
  ui_story_1013_10130401_49_dialog_content = "僕たちを待ってたんですか？",
  ui_story_1013_10130401_50_dialog_content = "そうだ。\n例のシステムが稼働している様子を見たくてな。",
  ui_story_1013_10130401_51_dialog_content = "お、来たね～。",
  ui_story_1013_10130401_52_dialog_content = "戦闘シミュレーションシステム、\nアップデートは終了しました。",
  ui_story_1013_10130401_53_dialog_content = "今は名前も変えて――\n戦場シミュレーションシステムにしたよ！",
  ui_story_1013_10130401_54_option_content = "「戦場」？",
  ui_story_1013_10130401_55_dialog_content = "1字違いだからって甘く見ないでよね。\n中身はゼンゼン違うんだから！",
  ui_story_1013_10130401_56_option_content = "何が変わったの？",
  ui_story_1013_10130401_57_dialog_content = "そりゃもう、色々だよ！",
  ui_story_1013_10130401_58_dialog_content = "ソラヴァンの新しいモジュールからデータを読み取って、\nアップデートした結果…",
  ui_story_1013_10130401_59_dialog_content = "今のシステムなら、過去の詳しい記録をベースにして、\n実際の戦場を細かく再現できるようになったの。",
  ui_story_1013_10130401_60_dialog_content = "敵だけじゃなくて、当時の時間や環境、\n天気まで完璧に再現できるの！",
  ui_story_1013_10130401_61_dialog_content = "どう？すごいでしょ！",
  ui_story_1013_10130401_62_dialog_content = "つまり、今まで以上に本物に近い\n戦闘シミュレーションができるってこと？",
  ui_story_1013_10130401_63_dialog_content = "理論的にはそういうことです。",
  ui_story_1013_10130401_64_dialog_content = "ただ、改良はまだ完了していません。\n今テストできるのは、やはりあなただけです。",
  ui_story_1013_10130401_65_dialog_content = "ってことで、今日もお願いね！",
  ui_story_1013_10130401_66_dialog_content = "昨日のテストでもう十分疲れたから、\n今日もあまり難しいのじゃないといいな…",
  ui_story_1013_10130401_67_dialog_content = "大丈夫大丈夫。\nシステムで使うのは過去の戦闘データだし…",
  ui_story_1013_10130401_68_dialog_content = "あんたの能力なら、\nヨユーでクリアできるって！",
  ui_story_1013_10130401_69_dialog_content = "PlayerName、がんばってね。\n私もここで見守ってるわ！",
  ui_story_1013_10130401_70_dialog_content = "う、うん、分かった！",
  ui_story_1013_10130401_71_dialog_content = "じゃあ、昨日と同じように、\nまずはヘッドセットをかぶって…",
  ui_story_1013_10130401_72_dialog_content = "…何も変わってないみたいだけど？",
  ui_story_1013_10130401_73_dialog_content = "そうあせらないで。\nすぐに戦闘データを起動するよ。",
  ui_story_1013_10130401_74_dialog_content = "えーと、どれにしよっかな…？",
  ui_story_1013_10130401_75_dialog_content = "面白い。これにしよう。",
  ui_story_1013_10130401_76_dialog_content = "え…こ、これ？\n本当にいいの？大元帥。",
  ui_story_1013_10130401_77_dialog_content = "さすがに無理があるのでは…？",
  ui_story_1013_10130401_78_dialog_content = "心配することはない。\nPlayerNameの能力でできる範囲だ。",
  ui_story_1013_10130401_79_dialog_content = "この種の戦闘なら、PlayerNameも経験がある。\n彼を信じろ。",
  ui_story_1013_10130401_80_dialog_content = "りょうか～い！",
  ui_story_1013_10130401_81_dialog_content = "ちょ、ちょっと待ってください！",
  ui_story_1013_10130401_82_dialog_content = "何を選んだんですか！？",
  ui_story_1013_10130401_83_dialog_content = "やれば分かる。",
  ui_story_1013_10130401_84_dialog_content = "戦闘記録をロードしています…",
  ui_story_1013_10130401_85_dialog_content = "ロードされた戦闘データ：暗面戦争。",
  ui_story_1013_10130401_86_dialog_content = "あっ、周りの環境が本当に夜みたいになった！",
  ui_story_1013_10130401_87_dialog_content = "うっ…しかも、暗力の重苦しさまでシミュレーションされてる…",
  ui_story_1013_10130401_88_dialog_content = "PlayerName、どうだ？",
  ui_story_1013_10130401_89_dialog_content = "本当の戦場にいるみたいです！",
  ui_story_1013_10130401_90_dialog_content = "むしろ再現しすぎてるぐらいです！",
  ui_story_1013_10130401_91_dialog_content = "実際に暗面にいるような感覚で…\n暗力の苦しさまで、そっくりそのままです！",
  ui_story_1013_10130401_92_dialog_content = "そうか、それは素晴らしい。",
  ui_story_1013_10130401_93_option_content = "どこがですか！？",
  ui_story_1013_10130401_94_dialog_content = "それほど真に迫った感覚を生み出せるということは、\nシミュレーションシステムの性能が優れていることに他ならない。",
  ui_story_1013_10130401_95_dialog_content = "戦場の厳しさ、残酷さを身をもって感じることができるなら、\nより現実的な戦闘体験を得られる。",
  ui_story_1013_10130401_96_dialog_content = "戦場を熟知し、困難な環境下で\n己の技と策略を鍛えられれば…",
  ui_story_1013_10130401_97_dialog_content = "本物の前線に立った時、\n実際に死ぬ者や重傷を負う者を減らすことができるだろう。",
  ui_story_1013_10130401_98_dialog_content = "確かに、その通りですね…",
  ui_story_1013_10130401_99_dialog_content = "最初の体験者として、\nシステムの各機能を存分に試してくれ！",
  ui_story_1013_10130401_100_dialog_content = "分かりました！",
  ui_story_1013_10130401_101_dialog_content = "それじゃ、戦闘開始ね。\n準備はいい？PlayerName。",
  ui_story_1013_10130401_102_dialog_content = "戦場シミュレーションモード、\nステージ番号：11328。",
  ui_story_1013_10130401_103_dialog_content = "ステージ目標：暗鬼の包囲圏を突破、またはすべての暗鬼を撃破。",
  ui_story_1013_10130401_104_dialog_content = "戦場シミュレーションシステム、ステージ再現を開始します。",
  ui_story_1013_10130401_105_dialog_content = "グオォォ――！",
  ui_story_1013_10130401_106_dialog_content = "さあ、行くぞ！",
  ui_story_1013_10130502_1_dialog_content = "まずは後方に引いて、\n岩かげに隠れよう！",
  ui_story_1013_10130502_2_dialog_content = "…",
  ui_story_1013_10130502_3_dialog_content = "ガアァ――！",
  ui_story_1013_10130502_4_dialog_content = "グォォ！！！",
  ui_story_1013_10130502_5_dialog_content = "いやいや…多すぎるでしょ！？",
  ui_story_1013_10130502_6_dialog_content = "…！",
  ui_story_1013_10130502_7_dialog_content = "まずい！これ以上攻撃を受けたら、\nバイスが動けなくなる…",
  ui_story_1013_10130502_8_dialog_content = "どうしよう、暗鬼が多すぎる…\n退路も塞がれてる…",
  ui_story_1013_10130502_9_dialog_content = "いや…落ち着くんだ、PlayerName…",
  ui_story_1013_10130502_10_dialog_content = "周りをよく観察して…\nきっと何か方法があるはずだ。",
  ui_story_1013_10130502_11_dialog_content = "バイス！\nあの高いところにある岩を攻撃して！",
  ui_story_1013_10130502_12_dialog_content = "分かったわ！",
  ui_story_1013_10130502_13_dialog_content = "<color=#e8d9bb>ガラガラガラ――！</color>",
  ui_story_1013_10130502_14_dialog_content = "グオオォ――",
  ui_story_1013_10130502_15_dialog_content = "やった！落石で暗鬼の包囲に穴が開いた！",
  ui_story_1013_10130502_16_dialog_content = "バイス、突破しよう！",
  ui_story_1013_10130502_17_dialog_content = "分かったわ！",
  ui_story_1013_10130502_18_dialog_content = "包囲を突破したら、後は脱出地点へ行くだけだ！",
  ui_story_1013_10130502_19_dialog_content = "着いた！",
  ui_story_1013_10130502_20_dialog_content = "ステージ目標を達成しました。",
  ui_story_1013_10130502_21_dialog_content = "テスト終了。\nステージ評価は…Cです。",
  ui_story_1013_10130502_22_dialog_content = "はぁ…はぁ…",
  ui_story_1013_10130502_23_dialog_content = "もうクタクタだ…",
  ui_story_1013_10130502_24_dialog_content = "おまけに、評価が低くない！？",
  ui_story_1013_10130502_25_dialog_content = "お疲れ様でした。",
  ui_story_1013_10130502_26_dialog_content = "少々お待ちください。\nすぐに接続を解除します。",
  ui_story_1013_10130502_27_dialog_content = "接続が解除されました。\n安全にログアウトすることができます。",
  ui_story_1013_10130502_28_dialog_content = "PlayerName、お疲れ様！",
  ui_story_1013_10130502_29_dialog_content = "暗面での戦闘シミュレーションはどうだった？",
  ui_story_1013_10130502_30_option_content = "疲れました…",
  ui_story_1013_10130502_31_dialog_content = "ただイスに座って、身体は動かしてないはずなのに、\n汗でびしょびしょです…",
  ui_story_1013_10130502_32_option_content = "難しかったです…",
  ui_story_1013_10130502_33_dialog_content = "全力を尽くして、\n自分が考えつくかぎりの作戦を立てたのに…",
  ui_story_1013_10130502_34_dialog_content = "評価はCなんて！",
  ui_story_1013_10130502_35_dialog_content = "PlayerNameは十分よくやったわ！",
  ui_story_1013_10130502_36_dialog_content = "そうそう。\nちなみにこれ、大元帥が自分で経験した戦いね。",
  ui_story_1013_10130502_37_dialog_content = "何も知らずに戦って、\nこの成績ならそうとうすごいって！",
  ui_story_1013_10130502_38_dialog_content = "大元帥が自分で経験した？",
  ui_story_1013_10130502_39_dialog_content = "じゃあ…実際の結果は？",
  ui_story_1013_10130502_40_dialog_content = "この戦闘の最高記録は…",
  ui_story_1013_10130502_41_dialog_content = "あった！\n「単独で暗鬼50体を撃破、軽傷を負いつつ包囲突破に成功」。",
  ui_story_1013_10130502_42_dialog_content = "戦場シミュレーションシステムの評価基準で言ったら、\n多分A以上じゃないかな。",
  ui_story_1013_10130502_43_dialog_content = "単独で！？",
  ui_story_1013_10130502_44_dialog_content = "暗面の環境でも、それだけ戦えるなんて…",
  ui_story_1013_10130502_45_dialog_content = "さすがだわ…",
  ui_story_1013_10130502_46_dialog_content = "本当だね…僕はステージをクリアするだけで、\nいっぱいいっぱいだったよ。",
  ui_story_1013_10130502_47_dialog_content = "PlayerName、卑下する必要などない。",
  ui_story_1013_10130502_48_dialog_content = "暗面での戦闘は、まだ2回目だろう？\nそれでこの成績なら誇るべきだ。",
  ui_story_1013_10130502_49_dialog_content = "以前よりも暗面という環境の特性を理解し、\nそれを活かして戦えるようになっていた。",
  ui_story_1013_10130502_50_dialog_content = "しかも、今回は援軍の助けも借りず、\n見事に戦い抜いたではないか。",
  ui_story_1013_10130502_51_dialog_content = "明らかな進歩だ。賞賛に値する！",
  ui_story_1013_10130502_52_dialog_content = "あ、ありがとうございます？",
  ui_story_1013_10130502_53_dialog_content = "PlayerNameほど戦闘指揮に長けた者を\n啓光連邦でも多く育成できれば…",
  ui_story_1013_10130502_54_dialog_content = "暗鬼との戦いもずいぶんと楽になるだろうな。",
  ui_story_1013_10130502_55_dialog_content = "そういえば…PlayerNameって、\n会ったばかりの時にはもう、かなり指揮がうまかったわね。",
  ui_story_1013_10130502_56_option_content = "ソラヴァンのおかげだよ",
  ui_story_1013_10130502_57_option_content = "小さい頃から勉強してたから",
  ui_story_1013_10130502_58_dialog_content = "…えっ？",
  ui_story_1013_10130502_59_dialog_content = "地下で暮らしてた17年の間は、\nソラヴァンがいろんな知識を教えてくれてたんだ。",
  ui_story_1013_10130502_60_dialog_content = "戦闘の指揮もその中の一つだよ。",
  ui_story_1013_10130502_61_dialog_content = "…空の末裔は、\n次の世代に戦闘指揮を教えていたと言うこと…？",
  ui_story_1013_10130502_62_dialog_content = "でも、空の末裔は平和を愛する種族じゃ…？",
  ui_story_1013_10130502_63_dialog_content = "言われてみれば…そう考えてみると、僕が教わった知識と\n回帰の塔の中にあった資料は、同じものなのかもしれない…",
  ui_story_1013_10130502_64_dialog_content = "僕は…",
  ui_story_1013_10130502_65_dialog_content = "PlayerName、己が信じられないのか？",
  ui_story_1013_10130502_66_dialog_content = "…いいえ、そのことはもう、気にしてません。",
  ui_story_1013_10130502_67_dialog_content = "ほう？",
  ui_story_1013_10130502_68_dialog_content = "教わった知識がなんであろうと、\n今は僕のものです。",
  ui_story_1013_10130502_69_dialog_content = "今、僕はその知識を仲間を守ることに使ってます。\n悪いことには使ってません。",
  ui_story_1013_10130502_70_dialog_content = "ハハハ…ほんの少し見ないうちに、\nずいぶんと成長したようだ！",
  ui_story_1013_10130502_71_dialog_content = "そ、そうですか…？",
  ui_story_1013_10130502_72_dialog_content = "ああ！",
  ui_story_1013_10130502_73_dialog_content = "天空ノ谷の事件から何か抱え込んでいる様子だったので、\n少々心配していたのだが…",
  ui_story_1013_10130502_74_dialog_content = "その様子だと、私のいらぬ世話だったようだな。",
  ui_story_1013_10130502_75_dialog_content = "僕はそんなに弱くありません。",
  ui_story_1013_10130502_76_dialog_content = "ああ、分かっているさ。",
  ui_story_1013_10130502_77_dialog_content = "慰めの言葉を考えていたのだが、不必要だったようだ。",
  ui_story_1013_10130502_78_dialog_content = "え？何を言うつもりだったんですか？",
  ui_story_1013_10130502_79_dialog_content = "啓光に昔から伝わる言葉だ――",
  ui_story_1013_10130502_80_dialog_content = "「科学技術に善悪の別はない。\nあるのは、それを用いる光霊の善悪だけだ」",
  ui_story_1013_10130502_81_dialog_content = "え…？",
  ui_story_1013_10130502_82_dialog_content = "らしくないですね…？",
  ui_story_1013_10130502_83_dialog_content = "当然だ、私の言葉ではないからな。\nかつて学者たちに言われたことだ。",
  ui_story_1013_10130502_84_dialog_content = "なるほど。",
  ui_story_1013_10130502_85_dialog_content = "PlayerNameが素早く悩みから抜け出せたことは、\n私もうれしく思っている。",
  ui_story_1013_10130502_86_dialog_content = "今回は役に立たなかったが、\n手助けが必要になった時は、いつでも私を訪ねるがいい。",
  ui_story_1013_10130502_87_dialog_content = "できる限りの力を尽くそう。",
  ui_story_1013_10130502_88_dialog_content = "ただ、私は口が回る方ではない。\nよいアドバイスなどできないかも知れんがな。",
  ui_story_1013_10130502_89_dialog_content = "気持ちだけでも十分です！",
  ui_story_1013_10130502_90_dialog_content = "あ…でも、話してたら、\nソラヴァンのことが心配になってきました…",
  ui_story_1013_10130502_91_dialog_content = "そうよね、モジュールを見つけて、\n手順通りに回帰の塔で修復できたはずなのに…",
  ui_story_1013_10130502_92_dialog_content = "なんでソラヴァンの意識がまだ戻らないのかしら？",
  ui_story_1013_10130502_93_dialog_content = "まぁ、仕方ないこともあるの。",
  ui_story_1013_10130502_94_dialog_content = "啓光連邦の技術力がいくらスゴいって言っても、\n人工知能の研究は、まだまだ進んでないし…",
  ui_story_1013_10130502_95_dialog_content = "それに、巨像の意識って\n普通の人工知能とは、大きく違うみたいだしね。",
  ui_story_1013_10130502_96_dialog_content = "でも、研究が進めば、\nきっとクリア方法が見つかるはず！",
  ui_story_1013_10130502_97_dialog_content = "それはそうと、いい知らせがあるんだけど、聞きたい？",
  ui_story_1013_10130502_98_dialog_content = "何？",
  ui_story_1013_10130502_99_dialog_content = "ソラヴァンの新しいモジュールの中から、\nたくさんの戦闘記録が発見されて…",
  ui_story_1013_10130502_100_dialog_content = "巨像や回帰の塔と同様、\n相当古いものとみられております。",
  ui_story_1013_10130502_101_dialog_content = "ちょっと、あたしのセリフ！？",
  ui_story_1013_10130502_102_dialog_content = "この戦闘データを分析すれば、\n巨像に関する情報を集められると予測され…",
  ui_story_1013_10130502_103_dialog_content = "…実験台君は、巨像を直したいのでしたな？",
  ui_story_1013_10130502_104_dialog_content = "…何をすればいいのか、教えてください。",
  ui_story_1013_10130502_105_dialog_content = "我々はその古い戦闘データを\n戦場シミュレーションシステムに取り込み、復元を試みます。",
  ui_story_1013_10130502_106_dialog_content = "君はこれまでと同様、\n戦闘シミュレーションを試してくれればよろしい。",
  ui_story_1013_10130502_107_dialog_content = "我々がモニタリングを行い、\n必要なデータを収集します。",
  ui_story_1013_10130502_108_dialog_content = "もちろん、あたしたちがPlayerNameを\nできるだけ助けるよ！",
  ui_story_1013_10130502_109_dialog_content = "今回は能力のテストじゃなくて、\nデータ収集が目的だからね～。",
  ui_story_1013_10130502_110_dialog_content = "とは言ったけど、戦場シミュレーションシステムにとっても、\n未検証で初めて使うデータだから…",
  ui_story_1013_10130502_111_dialog_content = "できるかぎり慎重に動いて欲しいかな。",
  ui_story_1013_10130502_112_dialog_content = "分かったよ。\nソラヴァンを1日でも早く直せるなら、僕はそれでいい。",
  ui_story_1013_10130502_113_dialog_content = "すぐに始めよう！",
  ui_story_1013_10130502_114_dialog_content = "オッケー、じゃあ、今までと同じように、\n座ってヘッドセットをかぶって。",
  ui_story_1013_10130601_1_dialog_content = "ここは…どこだろう？",
  ui_story_1013_10130601_2_dialog_content = "どこかの都市みたいだ。",
  ui_story_1013_10130601_3_dialog_content = "今までと違って荒野じゃない？",
  ui_story_1013_10130601_4_dialog_content = "なんでだろう…？",
  ui_story_1013_10130601_5_dialog_content = "バイス、大元帥、聞こえますか？",
  ui_story_1013_10130601_6_dialog_content = "…",
  ui_story_1013_10130601_7_dialog_content = "返事がない…？",
  ui_story_1013_10130601_8_dialog_content = "システムが故障したのかな？",
  ui_story_1013_10130601_9_dialog_content = "<color=#e8d9bb>戦場シミュレーションシステムの外側</color>",
  ui_story_1013_10130601_10_dialog_content = "PlayerName？",
  ui_story_1013_10130601_11_dialog_content = "どうした、PlayerName！聞こえるか？",
  ui_story_1013_10130601_12_dialog_content = "…どういうことだ？接続が切れたのか？",
  ui_story_1013_10130601_13_dialog_content = "悪いけど、あたしにも分からない！",
  ui_story_1013_10130601_14_dialog_content = "エラーメッセージは出てないし、\nPlayerNameの見てる場面が、こっちにも見えてる…",
  ui_story_1013_10130601_15_dialog_content = "ただ、PlayerNameと通信できないだけ…",
  ui_story_1013_10130601_16_dialog_content = "原因も分からない…",
  ui_story_1013_10130601_17_dialog_content = "PlayerNameとシステムの接続を切るのだ！急げ！",
  ui_story_1013_10130601_18_dialog_content = "PlayerNameを危険にさらしてはならん！",
  ui_story_1013_10130601_19_dialog_content = "はっ、はい！！",
  ui_story_1013_10130601_20_dialog_content = "…えっ？",
  ui_story_1013_10130601_21_dialog_content = "どうして…？\n接続を解除できない！？",
  ui_story_1013_10130601_22_dialog_content = "今度はどうした？",
  ui_story_1013_10130601_23_dialog_content = "悪いけど…これも原因不明！",
  ui_story_1013_10130601_24_dialog_content = "PlayerName…大丈夫ですよね？",
  ui_story_1013_10130601_25_dialog_content = "どうして突然、\nシステムが故障したんでしょう？",
  ui_story_1013_10130601_26_dialog_content = "報告します。\n今までにこのようなエラーの記録はありません。",
  ui_story_1013_10130601_27_dialog_content = "やはり、ソラヴァンに保存されていた戦闘データの使用が原因で、\n問題が起こったものと考えられます。",
  ui_story_1013_10130601_28_dialog_content = "装置を取り外せば、強制的に遮断できるか？",
  ui_story_1013_10130601_29_dialog_content = "それは止めておいた方がいいと思うわ。",
  ui_story_1013_10130601_30_dialog_content = "あれ？医療装置の研究をしてるんじゃないの？\nどうしてここに？",
  ui_story_1013_10130601_31_dialog_content = "ボーヤの状態を分析するには、生物学の専門家が必要でしょ。\nだから来たのよ。",
  ui_story_1013_10130601_32_dialog_content = "そうね！で、PlayerNameの今の状況は？",
  ui_story_1013_10130601_33_dialog_content = "きちんと研究してみないと、どうとも言えないわ。",
  ui_story_1013_10130601_34_dialog_content = "ただ、楽観できないことは確かね。\n作動中のシステムと被検体の意識が連結されてるでしょう？",
  ui_story_1013_10130601_35_dialog_content = "もし無理に接続を解除しようとすれば、\nボーヤは残りの人生、ベッドの上で過ごすことになるかもね。",
  ui_story_1013_10130601_36_dialog_content = "そんな…",
  ui_story_1013_10130601_37_dialog_content = "だからといって、\nこのままシステムの中に閉じ込めておくわけにもいかないわ。",
  ui_story_1013_10130601_38_dialog_content = "外の私たちに、何かできることは！？",
  ui_story_1013_10130601_39_dialog_content = "落ち着きなさい、バイス中尉。",
  ui_story_1013_10130601_40_dialog_content = "いまの君にできることは、\n我々の実験台君を救う方法探しを邪魔しないことだけです。",
  ui_story_1013_10130601_41_dialog_content = "引き続き、PlayerNameを救う方法を探れ。",
  ui_story_1013_10130601_42_dialog_content = "一刻も早く戦場シミュレーションシステムとの接続を遮断せよ。",
  ui_story_1013_10130601_43_dialog_content = "<color=#e8d9bb>戦場シミュレーションシステム内部</color>",
  ui_story_1013_10130601_44_dialog_content = "いったいどうなってるの…！？",
  ui_story_1013_10130601_45_dialog_content = "外の人たちとも通信できないし、\nステージ開始のメッセージも聞こえないし…",
  ui_story_1013_10130601_46_dialog_content = "それに、ここって…啓光にも白夜城にも見えない…",
  ui_story_1013_10130601_47_dialog_content = "科学者の人たちは、ソラヴァンの新しいモジュールの中から見つけた\n戦闘データを使うって言ってたっけ…",
  ui_story_1013_10130601_48_dialog_content = "ってことは、今見えてるのは…",
  ui_story_1013_10130601_49_option_content = "古代の都市！？",
  ui_story_1013_10130601_50_dialog_content = "逃げろ――",
  ui_story_1013_10130601_51_dialog_content = "あれ？誰かこっちへ走ってくる？",
  ui_story_1013_10130601_52_dialog_content = "早く逃げろ、追いつかれるな！",
  ui_story_1013_10130601_53_dialog_content = "すみません、何があったんですか？",
  ui_story_1013_10130601_54_dialog_content = "奴らが来たんだ！",
  ui_story_1013_10130601_55_dialog_content = "奴ら？いったい、何が…",
  ui_story_1013_10130601_56_dialog_content = "…いや、これは…暗力の気配！？",
  ui_story_1013_10130601_57_dialog_content = "グガア――！！！",
  ui_story_1013_10130601_58_dialog_content = "バイス！！",
  ui_story_1013_10130601_59_dialog_content = "…",
  ui_story_1013_10130601_60_dialog_content = "よかった。バイスのイメージは呼び出せるみたい…",
  ui_story_1013_10130601_61_dialog_content = "民間人を守れ、陣形を崩してはならん！",
  ui_story_1013_10130601_62_dialog_content = "暗鬼を恐れるな、奴らなど恐るるに足りん！",
  ui_story_1013_10130601_63_dialog_content = "武器を持て、私に続け！！",
  ui_story_1013_10130601_64_dialog_content = "突撃だ！！！",
  ui_story_1013_10130601_65_dialog_content = "ガアアア！！",
  ui_story_1013_10130601_66_dialog_content = "あれは…光霊かな？\n光力術を使って暗鬼と戦ってるみたいだけど…",
  ui_story_1013_10130601_67_dialog_content = "でも、すごく弱い！？",
  ui_story_1013_10130601_68_dialog_content = "暗鬼にぜんぜん効いてない…！",
  ui_story_1013_10130601_69_dialog_content = "グォォ！",
  ui_story_1013_10130601_70_dialog_content = "うわっ！",
  ui_story_1013_10130601_71_option_content = "急いで撤退して！",
  ui_story_1013_10130601_72_dialog_content = "君たちじゃかなわないよ！",
  ui_story_1013_10130601_73_dialog_content = "私たちが退くわけにはいかない！",
  ui_story_1013_10130601_74_dialog_content = "背後には…我々の故郷があるのだ！",
  ui_story_1013_10130601_75_dialog_content = "ちょっと、早く撤退して！？\n皆やられちゃうよ！？",
  ui_story_1013_10130601_76_dialog_content = "突撃だ！！！",
  ui_story_1013_10130601_77_dialog_content = "グォォ！！！",
  ui_story_1013_10130601_78_dialog_content = "バイス、助けてあげて！",
  ui_story_1013_10130601_79_dialog_content = "分かったわ！",
  ui_story_1013_10130602_1_dialog_content = "<color=#e8d9bb>戦場シミュレーションシステムの外側</color>",
  ui_story_1013_10130602_2_dialog_content = "PlayerNameの状況はどうなっている？",
  ui_story_1013_10130602_3_dialog_content = "報告します、現在解析中です！",
  ui_story_1013_10130602_4_dialog_content = "実験台君の状況は今のところ安定しています。\nシステムの異常にも気づいたようですな。",
  ui_story_1013_10130602_5_dialog_content = "現在、暗鬼と戦闘中のようです。\nこの情報で分析を急ぎます！",
  ui_story_1013_10130602_6_dialog_content = "相変わらず、PlayerNameは\n予想もしない方法で人を助けてるわね。",
  ui_story_1013_10130602_7_dialog_content = "PlayerNameの努力を無駄にするな、\n引き続き解析に励め！",
  ui_story_1013_10130602_8_dialog_content = "はっ！",
  ui_story_1013_10130602_9_dialog_content = "戦闘データ分析の結果が一部出たよ！",
  ui_story_1013_10130602_10_dialog_content = "話せ！",
  ui_story_1013_10130602_11_dialog_content = "復元されている情景を分析したら…",
  ui_story_1013_10130602_12_dialog_content = "現代の光霊の建物と様子が違うの。\n特徴からして…",
  ui_story_1013_10130602_13_dialog_content = "シヴォーンが見つけた地下都市の古代建築と\n似ている点が多いの。",
  ui_story_1013_10130602_14_dialog_content = "つまり、シミュレーションされてる戦闘データは、\nとんでもなく古い時代のものみたいね。",
  ui_story_1013_10130602_15_dialog_content = "もう記録にも残ってないぐらいの…",
  ui_story_1013_10130602_16_dialog_content = "太古の時代の記録だというのか…？",
  ui_story_1013_10130602_17_dialog_content = "分析を続けよ。",
  ui_story_1013_10130602_18_dialog_content = "システム内のデータには、\n太古の歴史がそのまま残っている可能性がある。",
  ui_story_1013_10130602_19_dialog_content = "PlayerNameのいる環境を注意深く監視せよ！\n救出の手がかりが見つかるかもしれん！",
  ui_story_1013_10130602_20_dialog_content = "<color=#e8d9bb>戦場シミュレーションシステム内部</color>",
  ui_story_1013_10130602_21_dialog_content = "何が起こってるんだろう？\nステージは始まってないはずなのに、暗鬼が出たし…",
  ui_story_1013_10130602_22_dialog_content = "どう考えてもおかしい。\nシステムにトラブルが起こってるのかも…",
  ui_story_1013_10130602_23_dialog_content = "グォォ――！",
  ui_story_1013_10130602_24_dialog_content = "…",
  ui_story_1013_10130602_25_dialog_content = "このままじゃ、きりがない！",
  ui_story_1013_10130602_26_dialog_content = "ここには僕と、僕の想像から生まれた光霊のイメージしかいない…",
  ui_story_1013_10130602_27_dialog_content = "皆の反応も聞こえないし、ソラヴァンもいない…",
  ui_story_1013_10130602_28_dialog_content = "どうやったら抜け出せるんだろう…",
  ui_story_1013_10130602_29_dialog_content = "何もせずに暗鬼に倒されたら、\n失敗扱いになって、出られるかな？",
  ui_story_1013_10130602_30_dialog_content = "とは言ったけど、戦場シミュレーションシステムにとっても、\n未検証で初めて使うデータだから…",
  ui_story_1013_10130602_31_dialog_content = "できるかぎり慎重に動いて欲しいかな。",
  ui_story_1013_10130602_32_dialog_content = "いや、やみくもに動いちゃいけないか…",
  ui_story_1013_10130602_33_dialog_content = "今、システムには異常が起こってる。\n何をしても結果は分からない…",
  ui_story_1013_10130602_34_dialog_content = "でも…僕は1人じゃない！",
  ui_story_1013_10130602_35_dialog_content = "バイスたちもきっと、異常に気づいて、\n解決しようとしてくれてるはずだ！",
  ui_story_1013_10130602_36_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_1013_10130602_37_dialog_content = "えっ、何！？",
  ui_story_1013_10130602_38_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_1013_10130602_39_dialog_content = "じ、地震？",
  ui_story_1013_10130602_40_dialog_content = "いや、違う。辺りが全部…崩れ始めてる！？",
  ui_story_1013_10130602_41_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_1013_10130602_42_dialog_content = "退け！退け！！",
  ui_story_1013_10130602_43_dialog_content = "悪魔が来たぞ！！",
  ui_story_1013_10130602_44_dialog_content = "悪魔！？",
  ui_story_1013_10130602_45_dialog_content = "うっ…頭が…痛い！",
  ui_story_1013_10130602_46_dialog_content = "ここから…逃げないと…",
  ui_story_1013_10130602_47_dialog_content = "PlayerName。",
  ui_story_1013_10130602_48_dialog_content = "目を覚ますのです…",
  ui_story_1013_10130602_49_dialog_content = "あきらめてはいけません。",
  ui_story_1013_10130602_50_dialog_content = "景色が変わった…！？",
  ui_story_1013_10130602_51_dialog_content = "遠くに暗鬼がたくさんいる…",
  ui_story_1013_10130602_52_dialog_content = "空に浮かんでるのは…巨像だ！",
  ui_story_1013_10130602_53_dialog_content = "巨像が暗鬼を乗せて、光霊たちと戦ってる…",
  ui_story_1013_10130602_54_dialog_content = "やっぱり、回帰の塔にあった記録は、本当に…",
  ui_story_1013_10130602_55_dialog_content = "全ての戦闘員に告ぐ――",
  ui_story_1013_10130602_56_dialog_content = "これは…放送？",
  ui_story_1013_10130602_57_dialog_content = "戦線を死守し、徹底抗戦せよ。",
  ui_story_1013_10130602_58_dialog_content = "人類は必ずや悪魔に打ち勝つ。",
  ui_story_1013_10130602_59_option_content = "「悪魔」？",
  ui_story_1013_10130602_60_dialog_content = "さっきも誰か「悪魔」って叫んでたけど、\n何のことだろう？暗鬼のこと？",
  ui_story_1013_10130602_61_option_content = "「人類」？",
  ui_story_1013_10130602_62_dialog_content = "人類…って何だろう？光霊じゃないの？",
  ui_story_1013_10130602_63_dialog_content = "聞いたか！？\nどうあってもこの場を守れ！！",
  ui_story_1013_10130602_64_dialog_content = "戦線を守り、我々の故郷を守れ！！",
  ui_story_1013_10130602_65_dialog_content = "待って、ダメだ！早く戻って！",
  ui_story_1013_10130602_66_dialog_content = "君たちじゃ暗鬼と戦うなんて無理だよ！\n勝ち目なんかない！",
  ui_story_1013_10130602_67_dialog_content = "戦わないのなら、せめて邪魔をしないでくれ！",
  ui_story_1013_10130602_68_dialog_content = "突撃だ！暗鬼を倒せ！悪魔を倒せ！",
  ui_story_1013_10130602_69_dialog_content = "戦線を守れ、一歩も下がるな！",
  ui_story_1013_10130602_70_dialog_content = "人類は必ず勝利する！",
  ui_story_1013_10130602_71_dialog_content = "グォォ！！！",
  ui_story_1013_10130602_72_dialog_content = "うぐっ…！",
  ui_story_1013_10130602_73_dialog_content = "怖気づいて…いられるか！！",
  ui_story_1013_10130602_74_dialog_content = "止まって！！",
  ui_story_1013_10130602_75_dialog_content = "戦闘を継続し、持ち場を死守せよ！",
  ui_story_1013_10130602_76_dialog_content = "この放送は一体何なの！？\n命を投げ捨てるようなことを、簡単に…",
  ui_story_1013_10130602_77_dialog_content = "<color=#e8d9bb>ザザ――</color>",
  ui_story_1013_10130602_78_dialog_content = "記録を…ロード中…",
  ui_story_1013_10130602_79_dialog_content = "システムのメッセージだ！",
  ui_story_1013_10130602_80_dialog_content = "まさか、もう回復できたのかな？",
  ui_story_1013_10130602_81_dialog_content = "…戦役：…出現。",
  ui_story_1013_10130602_82_dialog_content = "戦場……番号：エラー。",
  ui_story_1013_10130602_83_dialog_content = "…目標：安全地帯…退。",
  ui_story_1013_10130602_84_dialog_content = "撤退…？もうどこもかしこも、暗鬼だらけなのに…\nどこに撤退しろっていうの？",
  ui_story_1013_10130602_85_dialog_content = "おい、君！",
  ui_story_1013_10130602_86_dialog_content = "後ろに向かって走れ！あっちは安全だ！\nたどりつけさえすれば、兵士たちが守ってくれる！",
  ui_story_1013_10130602_87_dialog_content = "あきらめるな！\n人類は必ず悪魔に勝つんだ！",
  ui_story_1013_10130602_88_dialog_content = "後ろ…暗鬼が来るのと反対の方向に走ればいいのかな？",
  ui_story_1013_10130602_89_dialog_content = "戦場シミュレーションシステムの見せる光景って、本物みたいだ。\nあやうく忘れかけてたよ…",
  ui_story_1013_10130602_90_dialog_content = "今見てるのは全部、過去の記録なんだ。",
  ui_story_1013_10130602_91_dialog_content = "ここで何をしようと、\n起こったことを変えることはできない…",
  ui_story_1013_10130602_92_dialog_content = "だったら僕にできることは、\n一刻も早くステージをクリアして、すべてを終わらせることだけだ。",
  ui_story_1013_10130602_93_dialog_content = "戦場シミュレーションシステム、ステージ再現を開始します。",
  ui_story_1013_10130701_1_dialog_content = "はぁ、はぁ…",
  ui_story_1013_10130701_2_dialog_content = "（どこに撤退すればいいのか分からないけど…）",
  ui_story_1013_10130701_3_dialog_content = "（兵士たちの動きについていけば、たぶん間違いない！）",
  ui_story_1013_10130701_4_dialog_content = "君たち、早く！中に入るんだ！",
  ui_story_1013_10130701_5_dialog_content = "は、はい！",
  ui_story_1013_10130701_6_dialog_content = "…えっ？",
  ui_story_1013_10130701_7_dialog_content = "（あそこの人たち…動こうとしない）",
  ui_story_1013_10130701_8_dialog_content = "（ケガでもしたのかな…？）",
  ui_story_1013_10130701_9_dialog_content = "繰り返す。戦闘を継続し、前線を死守せよ！",
  ui_story_1013_10130701_10_dialog_content = "あの、すみません！ケガでもしましたか？\n助けが必要ですか？",
  ui_story_1013_10130701_11_dialog_content = "ここは危険です。\nこの先の安全地帯まで…",
  ui_story_1013_10130701_12_dialog_content = "え？これって…？",
  ui_story_1013_10130701_13_dialog_content = "（この人たちの身体から出てる光…\n光力のそれとそっくりだ）",
  ui_story_1013_10130701_14_dialog_content = "（まさか…光霊？）",
  ui_story_1013_10130701_15_dialog_content = "光の神は永遠の白夜も、我々が苦しむことなく、\n太平であり続けることも、許してはくださらなかった…",
  ui_story_1013_10130701_16_dialog_content = "光の神は、永遠の平穏も、苦しみのない太平の世も、\n約束してはくださらなかった…",
  ui_story_1013_10130701_17_dialog_content = "しかし、光の神は、我々に勇気と知恵を与え、\n慈愛を授けてくださった。",
  ui_story_1013_10130701_18_dialog_content = "どうか、授かった勇気と知恵で危機を救い、\n平安を取り戻す力をお与えください…",
  ui_story_1013_10130701_19_dialog_content = "（この人たち…お祈りしてるみたいだ）",
  ui_story_1013_10130701_20_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_1013_10130701_21_dialog_content = "戦火が急速に拡大中！\n総員指示に従い、避難せよ！",
  ui_story_1013_10130701_22_dialog_content = "これが最終警告である！\n一刻も早く「悪魔」の出現区域から脱出せよ！",
  ui_story_1013_10130701_23_dialog_content = "グォォ！！！",
  ui_story_1013_10130701_24_dialog_content = "大変だ、急がなきゃ…",
  ui_story_1013_10130701_25_dialog_content = "ガァ…",
  ui_story_1013_10130701_26_dialog_content = "光の使者は闇を恐れない。",
  ui_story_1013_10130701_27_dialog_content = "我らは闇から生まれた悪魔を倒すためにここにいる…",
  ui_story_1013_10130701_28_dialog_content = "少年よ、早く逃げなさい。奴らから離れるのだ。\n犠牲者がこれ以上増えんようにな。",
  ui_story_1013_10130701_29_option_content = "いいえ、僕が手助けします",
  ui_story_1013_10130701_30_dialog_content = "僕を信じて、意識を感知させてもらえるなら…",
  ui_story_1013_10130701_31_dialog_content = "僕が指揮をします！\nそうすれば、この戦いに勝てます！",
  ui_story_1013_10130701_32_option_content = "皆さんも一緒に逃げてください",
  ui_story_1013_10130701_33_dialog_content = "この戦いは、光霊4人でどうにかできるものじゃありません。",
  ui_story_1013_10130701_34_dialog_content = "僕と一緒に避難しましょう！\n今はそれしか方法がありません！",
  ui_story_1013_10130701_35_dialog_content = "「光霊」？何それ？聞いたことないなぁ…",
  ui_story_1013_10130701_36_dialog_content = "ここは子どもの遊び場じゃないんだよ。\n早く避難して。",
  ui_story_1013_10130701_37_dialog_content = "君だって子どもでしょ！？",
  ui_story_1013_10130701_38_dialog_content = "光の使者の年齢に、外見は関係ありません。",
  ui_story_1013_10130701_39_dialog_content = "光力を使いこなせる者だけが、\nここに立つ資格を持っているのです。",
  ui_story_1013_10130701_40_dialog_content = "今こそ、光の神の啓示に<color=#FFB400>全てをもって応える</color>時です。",
  ui_story_1013_10130701_41_dialog_content = "それは、つまり…",
  ui_story_1013_10130701_42_dialog_content = "そうだな。今はもう、\n細かい心配をして力を抑えている場合ではない。",
  ui_story_1013_10130701_43_dialog_content = "少年、すぐに離れるんだ。\n巻き込まれたくなければな。",
  ui_story_1013_10130701_44_dialog_content = "…それでよい。そうでなければ、\n我々にも悔いが残る。",
  ui_story_1013_10130701_45_dialog_content = "悪魔が来るよ、あっちだ！",
  ui_story_1013_10130701_46_dialog_content = "最後に残った、一筋の光をつかもう。",
  ui_story_1013_10130701_47_dialog_content = "光は我らにある！",
  ui_story_1013_10130701_48_dialog_content = "うっ、なんて強い光力が…！？",
  ui_story_1013_10130701_49_dialog_content = "グアアア――",
  ui_story_1013_10130701_50_dialog_content = "うわああああああ！",
  ui_story_1013_10130701_51_dialog_content = "これは…！？",
  ui_story_1013_10130701_52_dialog_content = "（勝ってるはずなのに、\n目の前に広がってるのは悪夢みたいな光景だ…）",
  ui_story_1013_10130701_53_dialog_content = "（強烈な光の中で、\n敵も味方もあっという間に死んでいく…！）",
  ui_story_1013_10130701_54_dialog_content = "（これ以上、耐えられない…このままじゃ…僕も…）",
  ui_story_1013_10130701_55_dialog_content = "<color=#e8d9bb>バン！！！</color>",
  ui_story_1013_10130701_56_dialog_content = "はぁ、はぁ…",
  ui_story_1013_10130701_57_dialog_content = "ザー…ザザー…",
  ui_story_1013_10130701_58_dialog_content = "終わった…の…？",
  ui_story_1013_10130701_59_option_content = "強制感知",
  ui_story_1013_10130701_60_dialog_content = "暗力がまったく感じられない…\n怖いほど静かだ。",
  ui_story_1013_10130701_61_dialog_content = "これが太古の世界の、終わり…？",
  ui_story_1013_10130701_62_dialog_content = "…ん！？",
  ui_story_1013_10130701_63_dialog_content = "土の中に何かいる！？",
  ui_story_1013_10130701_64_dialog_content = "<color=#e8d9bb>ガサガサガサ…</color>",
  ui_story_1013_10130701_65_dialog_content = "ザッ――！！",
  ui_story_1013_10130701_66_dialog_content = "まずい！",
  ui_story_1013_10130701_67_dialog_content = "（地面の下にいたから、助かったのかな…？）",
  ui_story_1013_10130701_68_dialog_content = "（だったら、僕が…）",
  ui_story_1013_10130702_1_dialog_content = "ガサッ！！",
  ui_story_1013_10130702_2_dialog_content = "やっぱり…僕じゃダメか。",
  ui_story_1013_10130702_3_dialog_content = "あれ、身体がさっきより長くなってる…？",
  ui_story_1013_10130702_4_dialog_content = "いくら暗鬼だって、身体が一瞬で元に戻ったりはしないはず。\nシミュレーションシステムの故障のせいかな？",
  ui_story_1013_10130702_5_dialog_content = "シャーッ――",
  ui_story_1013_10130702_6_dialog_content = "と、とにかく、早く研究者の人たちと連絡をとらないと…",
  ui_story_1013_10130702_7_dialog_content = "こんなところでやられるわけには行かない！",
  ui_story_1013_10130702_8_dialog_content = "シミュレーションシステムの研究者の皆さん、\n応答してください！",
  ui_story_1013_10130702_9_dialog_content = "もしもし…戦場シミュレーションシステムの研究者の皆さん、\n応答してください！",
  ui_story_1013_10130702_10_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10130702_11_dialog_content = "ど、どうしたらいいんだろう…",
  ui_story_1013_10130702_12_dialog_content = "他に何か方法は…",
  ui_story_1013_10130702_13_dialog_content = "<color=#e8d9bb>…バリン…ガシャン…</color>",
  ui_story_1013_10130702_14_dialog_content = "本当にここで…終わりなの？",
  ui_story_1013_10130702_15_dialog_content = "僕は…",
  ui_story_1013_10130702_16_dialog_content = "<color=#e8d9bb>ヒュゥ――</color>",
  ui_story_1013_10130702_17_dialog_content = "「コントロールシステム…異常なし」",
  ui_story_1013_10130702_18_dialog_content = "「生体モジュール…異常なし」",
  ui_story_1013_10130702_19_dialog_content = "「生命維持ユニット…作動中。作動負荷1名」",
  ui_story_1013_10130702_20_dialog_content = "「エンジン…異常なし。起動中…」",
  ui_story_1013_10130702_21_dialog_content = "…ソラヴァン！？",
  ui_story_1013_10130702_22_dialog_content = "私はここにいますよ、PlayerName。\nいつでもあなたのそばにいます。",
  ui_story_1013_10130702_23_dialog_content = "覚えていますか？「PlayerNameの命を確実に保護する」、\nそれが私の最優先任務です。",
  ui_story_1013_10130702_24_dialog_content = "ここは仮想データの世界ではありますが…",
  ui_story_1013_10130702_25_dialog_content = "あなたが大きなダメージを受ける状況を\n見過ごすわけにはいきません。",
  ui_story_1013_10130702_26_dialog_content = "まず、私との感知を切断してみてください。\nそのあとは、私に任せてください。",
  ui_story_1013_10130702_27_dialog_content = "「自動操縦システム起動…目的地：外界に接続、現実に帰還」",
  ui_story_1013_10130702_28_dialog_content = "う～ん…",
  ui_story_1013_10130702_29_dialog_content = "成功…した…？ソラヴァン…？",
  ui_story_1013_10130702_30_dialog_content = "PlayerName…PlayerName！\n気がついた！",
  ui_story_1013_10130702_31_dialog_content = "PlayerName、やっと目が覚めたのね！",
  ui_story_1013_10130702_32_dialog_content = "ボーヤの意識が回復したわ！\n気道の確保、急いで！",
  ui_story_1013_10130702_33_dialog_content = "研究所の身体機能検査機を使いましょう…",
  ui_story_1013_10130702_34_dialog_content = "何をする気…？ちょっと待って！\n僕は大丈夫だよ、何の問題もない！",
  ui_story_1013_10130702_35_dialog_content = "ソラヴァンは…？\nソラヴァンはどうなったの！？",
  ui_story_1013_10130702_36_dialog_content = "問題が無いかどうか、\n君自身の感覚で判断させるわけにはいきませんな。",
  ui_story_1013_10130702_37_dialog_content = "検査結果はすぐに出ます。\nあと5分ほど辛抱なさい。",
  ui_story_1013_10130702_38_dialog_content = "戦場シミュレーションシステムに\nこんな危険があるなんて、どうして話してくれなかったの！？",
  ui_story_1013_10130702_39_dialog_content = "…いつもボーヤを解剖したいなんて言ってるけど、\n冗談とまじめな話の分別くらい私にもあるわよ。",
  ui_story_1013_10130702_40_dialog_content = "私たちにあなたを傷つける意思は無かった。\nただ、今回の事故の全責任は研究所にあるわ。",
  ui_story_1013_10130702_41_dialog_content = "プログラミング担当者には責任をきっちり取らせるよ。\nシミュレーションシステムのテストもやり直す。",
  ui_story_1013_10130702_42_dialog_content = "それだけで済む話ではない。\n私の命令を伝えておけ…",
  ui_story_1013_10130702_43_dialog_content = "今後3か月分の巨像のメンテナンス費用は、\n啓光連邦研究所から支出させる。",
  ui_story_1013_10130702_44_dialog_content = "PlayerName、ひとまずそれで収めてもらえないか。",
  ui_story_1013_10130702_45_dialog_content = "じゅ、十分です…",
  ui_story_1013_10130702_46_dialog_content = "ううん…今回の故障の主原因は、\nシステムと巨像の接続技術が未熟だったことね…",
  ui_story_1013_10130702_47_dialog_content = "さっきの蝕虫ってヤツが何度も再生したのは、\n故障してるデータの中に入り込んじゃったからだね。",
  ui_story_1013_10130702_48_dialog_content = "やっぱり、君たちにも見えてたんだね…",
  ui_story_1013_10130702_49_dialog_content = "危ない所でソラヴァンが\nシステムとの接続を切ってくれて、無事に帰ってこられたんだ。",
  ui_story_1013_10130702_50_dialog_content = "ところで…ソラヴァンの方は？",
  ui_story_1013_10130702_51_dialog_content = "検査結果が出ました。\n実験台君の身体はごく正常です。良かったですな。",
  ui_story_1013_10130702_52_dialog_content = "…ソラヴァンはどうなったの！？",
  ui_story_1013_10130702_53_dialog_content = "ソラヴァンは…",
  ui_story_1013_10130702_54_dialog_content = "強制切断の代償を払った、かな…",
  ui_story_1013_10130702_55_dialog_content = "ソラヴァンの意識データが、\n仮想世界に残されたままなの。",
  ui_story_1013_10130702_56_dialog_content = "君にとっては残酷な話かもしれませんが、\n研究ではよくあることです。",
  ui_story_1013_10130702_57_dialog_content = "意識体に少々問題が起こり、\n人格と記憶がかい離し始めている…",
  ui_story_1013_10130702_58_dialog_content = "記憶はただの情報となり、人格は空白に戻る…",
  ui_story_1013_10130702_59_dialog_content = "その代わり、君は無事現実に戻って来られたのです。\nただ、ソラヴァンの機能は消失してしまうでしょうな。",
  ui_story_1013_10130702_60_dialog_content = "！！！",
  ui_story_1013_10130702_61_dialog_content = "どういうことですか…？\n人格の「消失」って…どういう意味ですか…？",
  ui_story_1013_10130702_62_dialog_content = "文字通りの意味ですな。",
  ui_story_1013_10130702_63_dialog_content = "それが…「ちょっとした問題」だって言うんですか！？",
  ui_story_1013_10130702_64_option_content = "強制感知！",
  ui_story_1013_10130702_65_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10130702_66_option_content = "強制感知！！",
  ui_story_1013_10130702_67_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10130702_68_option_content = "強制感知！！",
  ui_story_1013_10130702_69_dialog_content = "ムダですよ。",
  ui_story_1013_10130702_70_dialog_content = "今のあなたにソラヴァンを\nコントロールすることはできません。",
  ui_story_1013_10130702_71_dialog_content = "意識の修復は、引き続き試みます。\n少なくとも、機能が正常に動くように修復しましょう。",
  ui_story_1013_10130702_72_dialog_content = "少なくとも！？",
  ui_story_1013_10130702_73_dialog_content = "ソラヴァンが人格も記憶も失くして、\n「正常に動く」なんていうつもり！？",
  ui_story_1013_10130702_74_dialog_content = "どういうつもりだ？\n全責任を負うという話ではなかったのか？",
  ui_story_1013_10130702_75_dialog_content = "その通りです、大元帥。\n研究所が最後まで責任をもって、巨像の意識体を修復します。",
  ui_story_1013_10130702_76_dialog_content = "ですが、科学技術は友達ではありません。\nあくまで研究される道具にすぎないのですから。",
  ui_story_1013_10130702_77_dialog_content = "巨像の人格が崩壊すれば、\nシステムの安定性に大きな影響を及ぼすかもしれませんが…",
  ui_story_1013_10130702_78_dialog_content = "機能がすべて正常に動く限り、意識体の人格が眠りにつこうと、\n徐々に消失していようと、問題ないのではありませんかね。",
  ui_story_1013_10130702_79_dialog_content = "ソラヴァンは僕の友だちで、先生で、唯一の家族なんだ！\nもういい、ソラヴァンに触らないで！！",
  ui_story_1013_10130702_80_dialog_content = "落ち着いて下さい、PlayerNameさん。\n修復作業がソラヴァンに害を与えることはありません。",
  ui_story_1013_10130702_81_dialog_content = "今まさに害があったでしょ！？",
  ui_story_1013_10130702_82_dialog_content = "<color=#e8d9bb>コンコン…</color>",
  ui_story_1013_10130702_83_dialog_content = "研究室では静粛に願います。\n大声を出さないでください。",
  ui_story_1013_10130702_84_dialog_content = "おや…？",
  ui_story_1013_10130702_85_dialog_content = "こんにちは、大元帥。\n<color=#FFB400>最高科学者会議</color>の情報官、インゲルと申します。",
  ui_story_1013_10130702_86_dialog_content = "最高科学者会議だと？\nまた私の知らないところで、人材発掘をしているようだな。",
  ui_story_1013_10130702_87_dialog_content = "そうですね。\nおそらく大元帥にお目にかかるのは初めてです。",
  ui_story_1013_10130702_88_dialog_content = "ですが、大元帥のことはよく存じ上げております。",
  ui_story_1013_10130702_89_dialog_content = "フ、啓光の民であれば、\n私のことは誰でも知っている。",
  ui_story_1013_10130702_90_dialog_content = "それで、何の用だ？\n奴らも空の末裔を研究するつもりか？",
  ui_story_1013_10130702_91_dialog_content = "まもなく極秘の会議が開かれます。\n私はただの伝令です。",
  ui_story_1013_10130702_92_dialog_content = "フン、研究ばかりの年寄りどもが、\nようやく顔を出す気になったか…",
  ui_story_1013_10130702_93_dialog_content = "最高科学者会議はこの度、\n誠意をもって空の末裔と直接お話がしたいと願っております。",
  ui_story_1013_10130702_94_dialog_content = "私に話を通さずか？",
  ui_story_1013_10130702_95_dialog_content = "いいえ、もちろん大元帥閣下にも参加していただきます。",
  ui_story_1013_10130702_96_dialog_content = "これは要望ではなく、命令となります。\nレインハト大元帥は必ず空の末裔と共に出席してください。",
  ui_story_1013_10130702_97_dialog_content = "だったら、僕にはなおさら、断る権利もないってこと？",
  ui_story_1013_10130702_98_dialog_content = "でも、ソラヴァンが…",
  ui_story_1013_10130702_99_dialog_content = "戻ってくるまで巨像に関する一切の研究活動を止めるよう、\n私とガルーで研究所に命令を出しておくわ。",
  ui_story_1013_10130702_100_dialog_content = "心配しないで。\nここは私がしっかり見張っておくから！",
  ui_story_1013_10130702_101_dialog_content = "PlayerName、まだ策が尽きたわけではない…",
  ui_story_1013_10130702_102_dialog_content = "最高科学者会議の連中なら、\nソラヴァンに関する何かを知っているかもしれん。",
  ui_story_1013_10130702_103_dialog_content = "…分かりました。",
  ui_story_1013_10130702_104_dialog_content = "システムの中で見た古代の戦いについて、\n僕も聞きたいことがあるんです。",
  ui_story_1013_10130702_105_dialog_content = "お2人のご協力に感謝します。\n最高科学者会議は、あなたの質問に包み隠さずお答えするでしょう。",
  ui_story_1013_10130702_106_dialog_content = "それでは、こちらへ。",
  ui_story_1013_10130801_1_dialog_content = "「最高科学者会議」って…？",
  ui_story_1013_10130801_2_dialog_content = "啓光の最高権力機関に直属する組織だ。",
  ui_story_1013_10130801_3_dialog_content = "主要なメンバーは通常、啓光の各地に散らばっている。\n肝心な時以外は軽々しく集まることさえない、秘密機関だ。",
  ui_story_1013_10130801_4_dialog_content = "脅かすわけではないが、\nメンバー自体が全員、啓光の最高機密と言っていい。",
  ui_story_1013_10130801_5_dialog_content = "一般には身分も隠されている。",
  ui_story_1013_10130801_6_dialog_content = "前回会議が招集されたのは…\n軍事組織の世代交代を行う投票のためだった。",
  ui_story_1013_10130801_7_dialog_content = "それって、つまり…",
  ui_story_1013_10130801_8_dialog_content = "そう、私が大元帥に就任した年以来だ。",
  ui_story_1013_10130801_9_dialog_content = "秘密な上に、本当によほどのことが無いと集まらないんですね。\n誰からも聞いたことがないわけだ…",
  ui_story_1013_10130801_10_dialog_content = "お二人とも、急いでいただけますでしょうか？",
  ui_story_1013_10130801_11_dialog_content = "ハハハ…聞いたか、PlayerName？\n急げ、だそうだ。",
  ui_story_1013_10130801_12_dialog_content = "（すごいな。ただの「伝令」だって言ったのに、\n大元帥にこの態度…）",
  ui_story_1013_10130801_13_dialog_content = "PlayerName、少々緊張しているようだが？",
  ui_story_1013_10130801_14_dialog_content = "緊張というより、警戒と言った方がいいかもしれません。",
  ui_story_1013_10130801_15_dialog_content = "説明を聞いたら、ますます分からなくなりました。\nどうして突然、僕に会いたいなんて言ってきたんでしょう？",
  ui_story_1013_10130801_16_dialog_content = "バイスとバートンのことですか？\nそれとも回帰の塔のことで…",
  ui_story_1013_10130801_17_dialog_content = "憶測は悩みを増やすだけだ。",
  ui_story_1013_10130801_18_dialog_content = "最高科学者会議は確かに多くの実権を握っている。\nだが、権威をこれ見よがしに振りかざす奴らでもない。",
  ui_story_1013_10130801_19_dialog_content = "向こうから進んで会議に招いて来たと言うことは、\nお前と前向きに話し合い、信頼を得たいということだろう。",
  ui_story_1013_10130801_20_dialog_content = "…それに、表向きには知識と情報の管理統制などと言うが、\n中身はしょせん、科学に魅了された、研究一辺倒の変人の集まりだからな…",
  ui_story_1013_10130801_21_dialog_content = "会ってみれば、ソラヴァンの人格を取り戻す方法を\n見つけられる可能性はある。",
  ui_story_1013_10130801_22_dialog_content = "…それで少しは気が楽になるといいのだが。",
  ui_story_1013_10130801_23_dialog_content = "…ありがとうございます。",
  ui_story_1013_10130801_24_dialog_content = "お二人のご足労に感謝します。\n到着いたしました。",
  ui_story_1013_10130801_25_dialog_content = "入口で基本情報を登録してください。",
  ui_story_1013_10130801_26_dialog_content = "登録していただいた情報は、\n出入りの記録以外の用途には使われません。ご心配なく。",
  ui_story_1013_10130801_27_dialog_content = "（そこまで厳しくしてるんだ…）",
  ui_story_1013_10130801_28_dialog_content = "<color=#e8d9bb>ピッ――ピッ！</color>",
  ui_story_1013_10130801_29_dialog_content = "ドアロックを解除しました。\nどうぞ中へお入りください。",
  ui_story_1013_10130801_30_dialog_content = "どうして研究所か、ブラック・アンブレラの研究者を招待しないの？\nあるいはバイス中尉でもいい…",
  ui_story_1013_10130801_31_dialog_content = "空の末裔がどういう立場なのか、今は分からないし、\n古代技術を感知する天才的な能力は彼にしかないじゃない。",
  ui_story_1013_10130801_32_dialog_content = "天才かどうかまでは…ただ、現在分かっている限り、\n純血の空の末裔の最後の1人であることは確かですね。",
  ui_story_1013_10130801_33_dialog_content = "この目で確認するまでは、その「感知能力」と言うものも、\n一種の哲学や心理学と考えるしかありません。",
  ui_story_1013_10130801_34_dialog_content = "壊れた時計でも、1日に2回は正しい時を刻みますからね。",
  ui_story_1013_10130801_35_dialog_content = "皆さんの意見は引き続き観察させてもらうわ。",
  ui_story_1013_10130801_36_dialog_content = "世間話はここまでとしましょうか。\n2人が来ますよ。",
  ui_story_1013_10130801_37_dialog_content = "<color=#e8d9bb>コン、コン</color>",
  ui_story_1013_10130801_38_dialog_content = "空の末裔、PlayerName様をお連れしました。",
  ui_story_1013_10130801_39_dialog_content = "傍聴人のレインハト大元帥も同行しております。",
  ui_story_1013_10130801_40_dialog_content = "啓明の光のために！",
  ui_story_1013_10130801_41_dialog_content = "啓明の光のために！",
  ui_story_1013_10130801_42_dialog_content = "PlayerName、私の隣に座れ。",
  ui_story_1013_10130801_43_dialog_content = "空の末裔はユリシーズ教授の左の席にお願いします。\nモニターの正面の席です。",
  ui_story_1013_10130801_44_dialog_content = "レインハト大元帥は、横でお立ち下さい。",
  ui_story_1013_10130801_45_dialog_content = "今日は席決めにずいぶんとこだわるな、バレット。",
  ui_story_1013_10130801_46_dialog_content = "…今日の会議は参加者が制限されてるから、\n「裏方仕事」も誰かが買って出なきゃいけないので。",
  ui_story_1013_10130801_47_dialog_content = "来てくださったことに感謝します。",
  ui_story_1013_10130801_48_dialog_content = "ルールをきちんと守っていただければ、\nお互い時間の節約になりますよ。",
  ui_story_1013_10130801_49_dialog_content = "ああ、当然、明文化されたものも、\nされていないものも含めてですがね…",
  ui_story_1013_10130801_50_dialog_content = "座ってください、空の末裔君。",
  ui_story_1013_10130801_51_dialog_content = "こんにちは。",
  ui_story_1013_10130801_52_dialog_content = "紹介させていただきます。あなたの右側に座っているのは、\n生物学者のユリシーズ教授です。",
  ui_story_1013_10130801_53_dialog_content = "教授の正面に座っている方は、\n物理学者のジョイス先生…",
  ui_story_1013_10130801_54_dialog_content = "レインハト大元帥の隣に座っているのが、\n工学者のバレット先生です。",
  ui_story_1013_10130801_55_dialog_content = "それから…",
  ui_story_1013_10130801_56_dialog_content = "…アルゴル先生、しっかりなさってください…",
  ui_story_1013_10130801_57_dialog_content = "ふわぁ…あら、悪いわね。\n先に言っておくけど、あたしの時間は貴重なの。",
  ui_story_1013_10130801_58_dialog_content = "無意味な席決めに時間を使うぐらいなら、\n寝てた方がよっぽど有意義だもの。",
  ui_story_1013_10130801_59_dialog_content = "ちょっと！？",
  ui_story_1013_10130801_60_dialog_content = "あたしはアルゴル、専門は人工知能よ。\n肩に乗ってるロボットは「ブール」。",
  ui_story_1013_10130801_61_dialog_content = "ブールが目を覚ますようなことさえしなければ、\n今日の会議、きっと楽しくなるわよ、空の末裔くん。",
  ui_story_1013_10130801_62_dialog_content = "よ、よろしくお願いします…？",
  ui_story_1013_10130801_63_dialog_content = "皆さん、異議がないようなら会議を始めましょう。",
  ui_story_1013_10130801_64_dialog_content = "ですが、本題に入る前に、まずは君の質問にお答えした方が、\n話し合いが順調に進みそうですね。",
  ui_story_1013_10130801_65_dialog_content = "ただし、質問は多くとも3つに絞っていただきます。",
  ui_story_1013_10130801_66_dialog_content = "PlayerNameは戦場シミュレーションシステムのテストを\n終えたばかりでな。",
  ui_story_1013_10130801_67_dialog_content = "ちょうど聞きたいことがあるそうだ。",
  ui_story_1013_10130801_68_dialog_content = "積極的な発言に感謝します、レインハト君。",
  ui_story_1013_10130801_69_dialog_content = "では、空の末裔君に発言していただいてもよろしいですか？",
  ui_story_1013_10130801_70_dialog_content = "…ああ。",
  ui_story_1013_10130801_71_option_content = "「悪魔」について教えてください",
  ui_story_1013_10130801_72_dialog_content = "シミュレーションシステムの中で見た光景は…\n全部本当にあったことですよね？",
  ui_story_1013_10130801_73_dialog_content = "古代の光霊たちが光力術を使って、\n決死の覚悟で戦っている様子を見ました。",
  ui_story_1013_10130801_74_dialog_content = "「悪魔」と呼ばれていたものは、いったい…",
  ui_story_1013_10130801_75_dialog_content = "あなたが見たものはすべて、\n歴史上、本当に起こったことです。",
  ui_story_1013_10130801_76_dialog_content = "光霊と空の末裔が現れる以前、\nこの大陸には、その祖先にあたる古い種族が存在しました。",
  ui_story_1013_10130801_77_dialog_content = "「人類」って言ってた人たちのこと？",
  ui_story_1013_10130801_78_dialog_content = "そうです。外見は私たちと変わらず、科学に基づく技術を有していました。\n一方で、信仰を持つ者も多く存在したようです。",
  ui_story_1013_10130801_79_dialog_content = "ただし、人類に特殊な能力はありませんでした。",
  ui_story_1013_10130801_80_dialog_content = "（…だから、混乱が起こった時、\n「悪魔」のいないところに急いで逃げてたのかな…）",
  ui_story_1013_10130801_81_dialog_content = "理解しやすいように簡単に説明すると…",
  ui_story_1013_10130801_82_dialog_content = "古代の祖先たちの中でも、\n特別な生まれつきの才能を持った一部が進化し、光霊となりました。",
  ui_story_1013_10130801_83_dialog_content = "しかし、その他の人類は「悪魔」に惑わされてしまった。",
  ui_story_1013_10130801_84_dialog_content = "「悪魔」って言うのは、いったい何なんですか？",
  ui_story_1013_10130801_85_dialog_content = "上級暗鬼？\nそれとも…空の末裔か、光霊のこと？",
  ui_story_1013_10130801_86_dialog_content = "…それについては、研究所が分析を続けています。\n今は解答できません。",
  ui_story_1013_10130801_87_dialog_content = "前回の報告からずいぶん経っているのに、\n何も進捗がないだと？",
  ui_story_1013_10130801_88_dialog_content = "「悪魔」の起源や進化の方法、歴史に与えた影響は、\nいずれも慎重な分析と検証の必要な問題よ。",
  ui_story_1013_10130801_89_dialog_content = "シミュレーションで戦ったぐらいで結論を得られるほど、\n簡単な問題じゃないわ。",
  ui_story_1013_10130801_90_dialog_content = "…",
  ui_story_1013_10130801_91_dialog_content = "…結局、空の末裔と暗鬼は「悪魔」に操られ、\n光霊と決戦を繰り広げました。",
  ui_story_1013_10130801_92_dialog_content = "その辺りについては、ここにいる誰にとっても、\n秘密でも何でもありませんね。",
  ui_story_1013_10130801_93_dialog_content = "…その後に祖先たちが暮らしていた古代の世界が完全に壊滅して、\n暗鬼は暗面に引き下がって、空の末裔の歴史も途絶えてるんですよね。",
  ui_story_1013_10130801_94_dialog_content = "そして残った光霊が新しい文明を築いて、\n「悪魔」が残した暗鬼と戦い続けてる…",
  ui_story_1013_10130801_95_dialog_content = "そうですよね？",
  ui_story_1013_10130801_96_dialog_content = "啓光連邦もまだ確実な結論に至ったわけではありませんが、\n現在の見解はおおむね、あなたの想像と一致します。",
  ui_story_1013_10130801_96X1_dialog_content = "少々お待ちください…",
  ui_story_1013_10130801_97_dialog_content = "<color=#e8d9bb>カチッ――</color>",
  ui_story_1013_10130801_98_dialog_content = "（「眠気覚まし」か？相変わらずだな）",
  ui_story_1013_10130801_99_dialog_content = "（それを暗号にしたところで、\nごまかせるのは初対面のPlayerNameだけだと言うのに）",
  ui_story_1013_10130801_100_dialog_content = "啓光内部で流通している新しい眠気覚ましです。\nあなたも試してみますか？",
  ui_story_1013_10130801_100X1_dialog_content = "（ど、どこから出てきたの！？）",
  ui_story_1013_10130801_100X2_dialog_content = "ようやく顔を見せる気になったか、バレット。",
  ui_story_1013_10130801_100X3_dialog_content = "ええ。空の末裔には、少しだけ興味があるから。",
  ui_story_1013_10130801_100X4_dialog_content = "他の人がどうかは分からないけどね…",
  ui_story_1013_10130801_100X5_dialog_content = "私たちは引き続きあなたを<color=#FFB400>観察</color>しています。\n頑張ってください、空の末裔。",
  ui_story_1013_10130801_101_dialog_content = "…わ、分かりました…",
  ui_story_1013_10130801_102_option_content = "古代の光霊について教えて下さい",
  ui_story_1013_10130801_103_dialog_content = "その「生まれつきの才能」を持った祖先は、\nどうやって光力を使いこなせるようになったんですか？",
  ui_story_1013_10130801_104_dialog_content = "僕が見たかぎりでは、\n光の射してる方向に祈りをささげているだけでした。",
  ui_story_1013_10130801_105_dialog_content = "あれが…白夜城の信仰の始まりですか？",
  ui_story_1013_10130801_106_dialog_content = "ハハ…その質問は聞く相手を間違えていませんか？",
  ui_story_1013_10130801_107_dialog_content = "ご、ごめんなさい！",
  ui_story_1013_10130801_108_dialog_content = "この世界には確かに光霊がたくさんいますが、\n光力術の本質を知る者はごくわずかです。",
  ui_story_1013_10130801_109_dialog_content = "多くの者たちは自分たちの理解がしやすいよう、\n都合よく光力術を解釈しようとします…",
  ui_story_1013_10130801_110_dialog_content = "例えば、神からたまわった、聖なる地で生まれた、\nあるいは「真理」を悟って得た、などと…",
  ui_story_1013_10130801_111_dialog_content = "しかし、光力術の本質は、\n<color=#FFB400>生命力</color>でエネルギーを操る術です。",
  ui_story_1013_10130801_112_dialog_content = "生命力？だったら、僕たち空の末裔でも…",
  ui_story_1013_10130801_113_dialog_content = "空の末裔も生命力を持ってはいますが、\n光力術の使い方を知りません。",
  ui_story_1013_10130801_114_dialog_content = "生命力をもたない暗鬼ならば、なおさらです。\n私たちと同じ方法では、エネルギーを操ることができません。",
  ui_story_1013_10130801_115_dialog_content = "その「方法」というのは、いったい何ですか？",
  ui_story_1013_10130801_116_dialog_content = "簡単に言うと、光力術を応用する具体的な方法と言うことですね。\n例えば、啓光連邦では…",
  ui_story_1013_10130801_117_dialog_content = "一般には<color=#FFB400>形式上</color>の光力術を使って\n物理的に機械を動かし、科学技術によって光力術の効果を変化させます。",
  ui_story_1013_10130801_118_dialog_content = "しかし白夜城では、純粋な信仰の力で生命力を駆り立てるため…",
  ui_story_1013_10130801_119_dialog_content = "力の<color=#FFB400>根源</color>から直接、\n光力術の効果を発揮させているのです。",
  ui_story_1013_10130801_120_dialog_content = "それが白夜城と啓光連邦の間の唯一の違いなのだ。",
  ui_story_1013_10130801_121_dialog_content = "唯一の違い？\nその結論は暴論もいいところですね。",
  ui_story_1013_10130801_122_dialog_content = "それから、次はぜひ、私の話を最後まで続けさせていただきたい。",
  ui_story_1013_10130801_123_dialog_content = "（僕の気のせいかな…ここにいる科学者の先生たち、\n物腰は穏やかにみえるけど、実はすごく攻撃的な気がする）",
  ui_story_1013_10130801_124_dialog_content = "すでに10分経過しています。\nユリシーズ教授、本日の会議の目的をお忘れなく。",
  ui_story_1013_10130801_125_dialog_content = "おお、ありがとう。\n開始前にお約束した通り、空の末裔の質問をあと1つだけ許可します。",
  ui_story_1013_10130801_126_dialog_content = "しっかりしていますね。\nユリシーズに規則順守の精神をしっかり叩き込まれているようだ。",
  ui_story_1013_10130801_127_dialog_content = "インゲルは「啓明の星計画」で改造された者の中でも、\n特に優秀な卒業生ですから。私は通常の教育を施したにすぎませんよ。",
  ui_story_1013_10130801_128_dialog_content = "（改造！？）",
  ui_story_1013_10130801_129_dialog_content = "（この人たち…<color=#FFB400>光霊の身体を改造</color>してるってこと！？）",
  ui_story_1013_10130801_130_dialog_content = "…陰でこそこそ進めていた実験とは、それだったのか！？",
  ui_story_1013_10130801_131_dialog_content = "説明しろ！\n「啓明の星計画」は何年も前に中止になったはずだろう！",
  ui_story_1013_10130801_132_dialog_content = "正確に言えば、委員会は\n計画を中止するか否かを問う投票を行ったにすぎません。",
  ui_story_1013_10130801_133_dialog_content = "投票の結果が君の望みと違っただけです。",
  ui_story_1013_10130801_134_dialog_content = "ならば、再度委員会に申請するとしよう。",
  ui_story_1013_10130801_135_dialog_content = "何が有ろうと、私の兵士や民を改造の実験台にすることは許さんぞ！",
  ui_story_1013_10130801_136_dialog_content = "君にはもちろん、その権利があります。",
  ui_story_1013_10130801_137_dialog_content = "大元帥の権力は啓光の民に与えられたものですから、\n当然、君は彼らの幸福のために動くべきでしょう。",
  ui_story_1013_10130801_138_dialog_content = "ただし、それはこの会議が終わった後です。\n空の末裔に話す時間を与えていただかないと。",
  ui_story_1013_10130801_139_dialog_content = "（どうしよう…バイスの症状も、そういうのと関係があるのかな…）",
  ui_story_1013_10130801_140_dialog_content = "（いったいどれだけの人が改造を受けてきたんだろう…\n僕の友だちにも、いるのかな…）",
  ui_story_1013_10130801_141_dialog_content = "（強制感知！）",
  ui_story_1013_10130801_142_dialog_content = "PlayerName、あわてることはない。\nこの件はお前に任せた。",
  ui_story_1013_10130801_143_dialog_content = "ユリシーズに「改造計画」のことを尋ねてもらえるか？",
  ui_story_1013_10130801_144_dialog_content = "バイスたちの将来に関わるかもしれん問題だ。\n同時に、あの情報官と彼女の同胞にもな。",
  ui_story_1013_10130801_145_dialog_content = "もしかしたら…あの時の私たちも…",
  ui_story_1013_10130801_146_dialog_content = "…分かりました。",
  ui_story_1013_10130801_147_dialog_content = "もう1つ…私の思い過ごしだといいのだが。\nお前は品定めをされているようだ。",
  ui_story_1013_10130801_148_dialog_content = "品定め？",
  ui_story_1013_10130801_149_dialog_content = "会議の内部でも、\nまだ意見の一致していない何かがあるのかもしれん。",
  ui_story_1013_10130801_150_dialog_content = "お前に会ってから判断しないとならない、\n何かを隠しているということだ。",
  ui_story_1013_10130801_151_dialog_content = "彼らのいつものやり方だ。\nいずれにせよ…「眠気覚まし」は暗号だ。",
  ui_story_1013_10130801_152_dialog_content = "だが、お前も構える必要はない。\n自分らしく振舞えばいい。",
  ui_story_1013_10130801_153_dialog_content = "は、はい。",
  ui_story_1013_10130801_154_dialog_content = "（しばらく沈黙していたが、\n「感知能力」を使っているのだろうか？）",
  ui_story_1013_10130801_155_dialog_content = "（…いずれにせよ、引き続き監視が必要なようだ）",
  ui_story_1013_10130801_156_dialog_content = "<color=#e8d9bb>カチッ――</color>",
  ui_story_1013_10130801_157_dialog_content = "（フフ…ようやく、興味が湧いたってワケね）",
  ui_story_1013_10130801_158_option_content = "改造実験について尋ねる",
  ui_story_1013_10130801_159_dialog_content = "ヘリオスも「啓明の星計画」の実験台だったんですか？",
  ui_story_1013_10130801_160_dialog_content = "どうして啓光が、光霊の改造実験なんて…",
  ui_story_1013_10130801_161_dialog_content = "ヘリオス？…君は予想以上に、\nいろいろなことを知っているようですね。",
  ui_story_1013_10130801_162_dialog_content = "これ以上隠しておく必要もありませんか。\n私は確かに、光霊の改造実験を続けています。",
  ui_story_1013_10130801_163_dialog_content = "目の前のインゲルは、\n今期で最も成功した実験台です。",
  ui_story_1013_10130801_164_dialog_content = "改造された光霊も、\n遺伝子や基本的な性質は通常の光霊と変わりありません。",
  ui_story_1013_10130801_165_dialog_content = "インゲルは気が強すぎて、困る時もありますがね…",
  ui_story_1013_10130801_166_dialog_content = "そこは重要なことじゃありません。\nどうしてそんなことをするんですか？",
  ui_story_1013_10130801_167_dialog_content = "当然、啓光連邦のためです。",
  ui_story_1013_10130801_168_dialog_content = "それ以外に何かありますか？\n啓光連邦には必要なものなのです。",
  ui_story_1013_10130801_169_dialog_content = "白夜城が光砲、天空ノ谷が光霊を強化する古代装置を\n有しているのと同じことです。",
  ui_story_1013_10130801_170_dialog_content = "暗面で似たような装置を探したこともありますが、\n残念ながら、何の手がかりも得られませんでした。",
  ui_story_1013_10130801_171_dialog_content = "啓光連邦の民は、忠実な者ばかりです。\n我々の防衛線はいずれも、兵士たちのしかばねで築かれている。",
  ui_story_1013_10130801_172_dialog_content = "改造装置の研究は、民の心からの望みでもあるでしょう。",
  ui_story_1013_10130801_173_dialog_content = "改造に成功した実験台が1人増えれば、\n罪もなく死ぬ犠牲者を1人減らせるのですから。",
  ui_story_1013_10130801_174_dialog_content = "そんなのヘリクツです。実験台にされた人には罪があるって言うんですか？\nヘリオスのような犠牲は、犠牲じゃないとでも？",
  ui_story_1013_10130801_175_dialog_content = "<color=#e8d9bb>カチッ――</color>",
  ui_story_1013_10130801_176_dialog_content = "そのヘリオスについては…",
  ui_story_1013_10130801_177_dialog_content = "あの時の実験は啓明の星計画とは関係ありません。",
  ui_story_1013_10130801_178_dialog_content = "ヘリオスは別の育成計画の対象でした。\nそれも失敗作にすぎません。",
  ui_story_1013_10130801_179_dialog_content = "失敗作だと！？",
  ui_story_1013_10130801_180_dialog_content = "1人の光霊の人生を壊しておきながら、\n「実験の失敗作」だと！？",
  ui_story_1013_10130801_181_dialog_content = "レインハト君、自分が地位も名誉もある身分だからといって、\n道徳心を振りかざすのはやめていただきたいですね。",
  ui_story_1013_10130801_182_dialog_content = "「人生を壊す」というほど、大げさなものでもないでしょう。\n彼にはふさわしい道だったのかもしれませんよ？",
  ui_story_1013_10130801_183_dialog_content = "<color=#e8d9bb>バンッ――</color>",
  ui_story_1013_10130801_184_dialog_content = "悪いが、これ以上聞いていられん！\nユリシーズ、お前とは理性的に話せる限界を超えている！",
  ui_story_1013_10130801_185_dialog_content = "会議はここまでだ。\nこれ以上続ける意味はない！",
  ui_story_1013_10130801_186_dialog_content = "おや？早いですね。\nまだ本題が始まってもいないのに…",
  ui_story_1013_10130801_187_dialog_content = "空の末裔さえ残していっていただければ、\n退席していただいて構いません。",
  ui_story_1013_10130801_188_dialog_content = "えっ…",
  ui_story_1013_10130801_189_dialog_content = "やれるものならやってみろ。",
  ui_story_1013_10130801_190_dialog_content = "カン違いしないで。ここにいるのは皆、知識人よ。\n誰もあなたが想像するような、卑劣なマネはしないわ。",
  ui_story_1013_10130801_191_dialog_content = "私たちはずっと「友好的に」お話ししているでしょ？\n空の末裔に何かをしようという訳じゃないわ。",
  ui_story_1013_10130801_192_dialog_content = "ただし、その全過程を、\n最も権威ある人物の目で証明してもらう必要があるというだけ。",
  ui_story_1013_10130801_193_dialog_content = "…大元帥、これ以上説明する必要はありませんね？\nあなたも自らの役割を果たしてください。",
  ui_story_1013_10130801_194_dialog_content = "…",
  ui_story_1013_10130801_195_dialog_content = "<color=#e8d9bb>コン、コン――</color>",
  ui_story_1013_10130801_196_dialog_content = "ふわぁ～。",
  ui_story_1013_10130801_197_dialog_content = "ただの会議で、殺気立つことないでしょ。\nねえ、皆さん？",
  ui_story_1013_10130801_198_dialog_content = "全員、<color=#FFB400>空の末裔を認める</color>ってサインを出してるんだから、\n少なくとも友好的には話せるでしょう？",
  ui_story_1013_10130801_199_dialog_content = "インゲルの言う通り、\n空の末裔を呼んだ目的を忘れないで。",
  ui_story_1013_10130801_200_dialog_content = "（やっと本当の目的を話してくれる気になったのかな…）",
  ui_story_1013_10130801_201_dialog_content = "空の末裔くん、あなたの質問については、\nさっきこの人たちが答えたとおりよ。",
  ui_story_1013_10130801_202_dialog_content = "啓光の最高機密に関わることも、\n知ってるかぎりのことは全て答えたわ。",
  ui_story_1013_10130801_203_dialog_content = "それだけの情報を交換条件に協力をお願いしてるの。\nあなたにとっても損はないでしょ？",
  ui_story_1013_10130801_204_dialog_content = "！？",
  ui_story_1013_10130801_205_dialog_content = "冗談はやめてください…\n僕は改造実験になんて協力しません！！",
  ui_story_1013_10130801_206_dialog_content = "プッ…あなたは唯一の空の末裔なのよ。\n改造なんてするわけないじゃない！",
  ui_story_1013_10130801_207_dialog_content = "さっきも言ったけど、\nあなたには指一本触れないわ。",
  ui_story_1013_10130801_208_dialog_content = "ただ、手助けして欲しいだけよ――\nそれが間接的に、あなた自身を助けることになるかもしれないわ。",
  ui_story_1013_10130801_209_dialog_content = "はっきり言ってもらえますか？",
  ui_story_1013_10130801_210_dialog_content = "あら、冷たいのね。バイスを正常な状態に戻したいんでしょ？\nそれと、巨像も。",
  ui_story_1013_10130801_211_dialog_content = "（た、確かにそうだけど…）",
  ui_story_1013_10130801_212_dialog_content = "単刀直入に言うわ。あたしたちはあなたの感知能力を借りて、\n<color=#FFB400>「ガーディアン1号」</color>に接続したいの。",
  ui_story_1013_10130801_213_dialog_content = "これまで啓光の科学者たちは、\nソラヴァンはごく普通の輸送用の巨像だと考えてきたわ。",
  ui_story_1013_10130801_214_dialog_content = "でも、最近のソラヴァンの一連の動作と、\nアップデートを続けるシステムから見て…",
  ui_story_1013_10130801_215_dialog_content = "もっと多くの可能性があると考えているのよ。",
  ui_story_1013_10130801_216_dialog_content = "その可能性は、ソラヴァンを操縦する空の末裔なしに語れないわ。",
  ui_story_1013_10130801_217_dialog_content = "あなたと、巨像という古代科学技術との密接な関係が、\n一連の奇跡が起きた理由の１つだから。",
  ui_story_1013_10130801_218_dialog_content = "さっきの話の間に、全会一致で\nガーディアン1号をあなたに預けてもいいと判断されたわ。",
  ui_story_1013_10130801_219_dialog_content = "だから、お願い。\n感知能力を使って、ガーディアン1号を感知してくれない？",
  ui_story_1013_10130801_220_dialog_content = "ガーディアン1号…？\nまた素手で殴りあえとか言うんじゃ…",
  ui_story_1013_10130801_221_dialog_content = "ガーディアン1号は古代の人工知能で、\n啓光の科学技術システム全体の日常的な稼働や計算を担ってるの。",
  ui_story_1013_10130801_222_dialog_content = "どう？巨像と共通点があるでしょ？",
  ui_story_1013_10130801_223_dialog_content = "確かに…",
  ui_story_1013_10130801_224_dialog_content = "もしガーディアン1号の意識を感知できたら…",
  ui_story_1013_10130801_225_dialog_content = "古代から伝わるガーディアン1号の知識の中から、\nバイスを正常に戻す手がかりを見つけられるかもしれないわ。",
  ui_story_1013_10130801_226_dialog_content = "1号の意識の中でチャンネルをうまく切り替えることができれば、\nあなたの巨像とも再会できるかもしれない。",
  ui_story_1013_10130801_227_dialog_content = "！？",
  ui_story_1013_10130801_228_dialog_content = "（この人が言ってることが本当なら、ソラヴァンは…）",
  ui_story_1013_10130801_229_dialog_content = "決定権はあなたにあるわ。\nあたしはただ、参考意見を言っただけ。",
  ui_story_1013_10130801_230_dialog_content = "PlayerName、迷っているのか？",
  ui_story_1013_10130801_231_dialog_content = "ここまで知ったら…\n試さないわけにはいきません！",
  ui_story_1013_10130801_232_dialog_content = "さすがはPlayerNameだ。\n私はお前の決断に賛成する。",
  ui_story_1013_10130801_233_dialog_content = "高慢な連中だが…だからといって、\n今の状況を変えるチャンスをみすみす逃すわけにはいくまい。",
  ui_story_1013_10130801_234_dialog_content = "2人の意見も一致したようね。",
  ui_story_1013_10130801_235_dialog_content = "それじゃ、すぐにガーディアン1号を連れてくるわ。",
  ui_story_1013_10130901_1_dialog_content = "ガーディアン1号は古代の人工知能で、\n啓光の科学技術システム全体の日常的な稼働や計算を担ってるの。",
  ui_story_1013_10130901_2_dialog_content = "どう？巨像と共通点があるでしょ？",
  ui_story_1013_10130901_3_dialog_content = "古代の人工知能…啓光全体の維持を担う…",
  ui_story_1013_10130901_4_dialog_content = "何だか、すごそうだ。ちょっと楽しみだな。",
  ui_story_1013_10130901_5_dialog_content = "どんな見た目なのかな？啓光全体の計算を支えてるっていうなら、\nきっと大きいんだろうな。",
  ui_story_1013_10130901_6_dialog_content = "ソラヴァンぐらい？",
  ui_story_1013_10130901_7_dialog_content = "古代の人工知能を完全に残したものなら、\nきっといろんなプログラムも揃ってるんだろうな。",
  ui_story_1013_10130901_8_dialog_content = "少なくともキューブよりは賢いよね…",
  ui_story_1013_10130901_9_dialog_content = "それに、もし複数の人がコントロールできるなら、\nモニターもついてるかな。",
  ui_story_1013_10130901_10_dialog_content = "地下都市の「バトラー」みたいに…",
  ui_story_1013_10130901_11_dialog_content = "こんにちは、空の末裔！",
  ui_story_1013_10130901_12_dialog_content = "1号が収集した空の末裔に関するデータと、\n大きく異なっています。",
  ui_story_1013_10130901_13_dialog_content = "…ま、まさか…\nこの小さなロボットが…？",
  ui_story_1013_10130901_14_dialog_content = "そう。ガーディアン1号よ、仲良くしてあげてね。",
  ui_story_1013_10130901_15_dialog_content = "想像してたのと全然違う！？",
  ui_story_1013_10130901_16_dialog_content = "1号はあなたの存在を参考として、\n1号に保存されている空の末裔のデータを更新しました。",
  ui_story_1013_10130901_17_dialog_content = "1号もあなたが収集した人工知能に関するデータと、\n異なっているようですね。",
  ui_story_1013_10130901_18_dialog_content = "お互いにデータベースの充実を図っていきましょう、\n空の末裔。",
  ui_story_1013_10130901_19_dialog_content = "今のって…好意的なあいさつですか？",
  ui_story_1013_10130901_20_dialog_content = "仲良くしたいってことよ。\nガーディアン1号は友好的で、親しみやすい人工知能なの。",
  ui_story_1013_10130901_21_dialog_content = "少し待ってて…\n接続に必要なプログラムをガーディアン1号に入力するわ。",
  ui_story_1013_10130901_22_dialog_content = "エラー、エラー。",
  ui_story_1013_10130901_23_dialog_content = "接続プログラムの入力に失敗しました。\n1号は、詳細不明の人物と接続を行いません。",
  ui_story_1013_10130901_24_dialog_content = "どういうこと…？",
  ui_story_1013_10130901_25_dialog_content = "<size=30>ちゃんと約束したでしょ？空の末裔の生き残りと意識の接続実験をするって。\n許可証にも署名したじゃない…</size>",
  ui_story_1013_10130901_26_dialog_content = "話がついてなかったんですか！？",
  ui_story_1013_10130901_27_dialog_content = "ああ、ごめんなさい…\nガーディアン1号は、かなり慎重な人工知能なのよ。",
  ui_story_1013_10130901_28_dialog_content = "外部の機能を接続しようとすると、\n詳しいスキャンをして、遮断するの。",
  ui_story_1013_10130901_29_dialog_content = "1号は、未知の存在に対する学習能力を有し、\n既知の存在を自身で分析できます。",
  ui_story_1013_10130901_30_dialog_content = "1号は、未知の空の末裔のデータを学習しました。\nしかし、既知の空の末裔に関するデータベースを参照し…",
  ui_story_1013_10130901_31_dialog_content = "過去のデータベースと照合した結果、\n1号は、空の末裔が1号の制御権を獲得することを許可できません。",
  ui_story_1013_10130901_32_dialog_content = "つまり、今回が空の末裔に関するデータベースをアップデートする、\n絶好のチャンスってことよね？",
  ui_story_1013_10130901_33_dialog_content = "…理解しました。1号は、約束しています。\n空の末裔と相互の概念および認識を更新します。",
  ui_story_1013_10130901_34_dialog_content = "…つまり、接続を許可してくれるってこと？",
  ui_story_1013_10130901_35_dialog_content = "1号は、厳密な実地テストを実施し、\n空の末裔の能力に関するデータを記録、分析します。",
  ui_story_1013_10130901_36_dialog_content = "生成された分析結果をもとに、1号は自己判断により、\n空の末裔に1号の制御権を解放するか、決定します。",
  ui_story_1013_10130901_37_dialog_content = "え？実地テスト？この会議室でやるの？",
  ui_story_1013_10130901_38_dialog_content = "空の末裔、接続モードに移行してください。",
  ui_story_1013_10130901_39_dialog_content = "（要するに、感知をつなげってことだね？）",
  ui_story_1013_10130901_40_option_content = "強制感知！",
  ui_story_1013_10130901_41_dialog_content = "<color=#e8d9bb>キーン――</color>",
  ui_story_1013_10130901_42_dialog_content = "待って！",
  ui_story_1013_10130901_43_dialog_content = "<color=#e8d9bb>ウオーン…</color>",
  ui_story_1013_10130901_44_dialog_content = "まだ…",
  ui_story_1013_10130901_45_dialog_content = "テストの方法、何も聞いてないんだけど！？",
  ui_story_1013_10130901_46_dialog_content = "<color=#e8d9bb>ヒュゥ…</color>",
  ui_story_1013_10130901_47_dialog_content = "ここは…？あれ？\n戦場シミュレーションで来たことある…！？",
  ui_story_1013_10130901_48_dialog_content = "このフィールドで実地テストを行います。",
  ui_story_1013_10130901_49_dialog_content = "誰！？",
  ui_story_1013_10130901_50_dialog_content = "空の末裔さん、顔を上げる動作を実行してください。",
  ui_story_1013_10130901_51_dialog_content = "1号は、上方に存在します。",
  ui_story_1013_10130901_52_dialog_content = "え！？",
  ui_story_1013_10130901_53_dialog_content = "（び、びっくりした…）",
  ui_story_1013_10130901_54_dialog_content = "（何となく分かってきた、シミュレーションシステムの内部だと、\n上側に現実との境界があるってことになるのかな）",
  ui_story_1013_10130901_55_dialog_content = "（半透明のドーム屋根の外にある、\n太陽みたいなものがセンサーだ！）",
  ui_story_1013_10130901_56_dialog_content = "過去の戦場へようこそ。\n1号は、空の末裔さんの実験データをリアルタイムで記録します。",
  ui_story_1013_10130901_57_dialog_content = "1号に、あなたの能力を見せてください。",
  ui_story_1013_10130901_58_dialog_content = "また？この戦場の記録って、啓光の共有データなのかな？",
  ui_story_1013_10130901_59_dialog_content = "（もしかして、データが共有のものなら、\n取り残されたソラヴァンの意識も…）",
  ui_story_1013_10130901_60_dialog_content = "（これって、チャンス！？）",
  ui_story_1013_10130901_61_dialog_content = "さっそく戦場の地形を分析し、記憶してください。\n1号はまもなく、最初の戦闘データを出力します。",
  ui_story_1013_10130901_62_dialog_content = "分かった。その前に1つお願いがあるんだ。",
  ui_story_1013_10130901_63_dialog_content = "テストに合格した後でいいけど、\nこの戦場の最新のデータ、チェックさせてくれないかな？",
  ui_story_1013_10130901_64_dialog_content = "それは…？",
  ui_story_1013_10130901_65_dialog_content = "1号は許可します。\n申請は有効です。約束は成立しました。",
  ui_story_1013_10130901_66_dialog_content = "では空の末裔さん、準備はできましたか？",
  ui_story_1013_10130901_67_dialog_content = "戦闘を開始します。",
  ui_story_1013_10130901_68_dialog_content = "ステージ目標：暗鬼すべての撃破。",
  ui_story_1013_10130901_69_dialog_content = "ガーディアン1号、ステージ実行。",
  ui_story_1013_10130901_70_dialog_content = "そういうことなら…",
  ui_story_1013_10130901_71_dialog_content = "「バイス」、「カレン」…お願い！",
  ui_story_1013_10130901_72_dialog_content = "任せて。",
  ui_story_1013_10130901_73_dialog_content = "問題ないわ！",
  ui_story_1013_10131002_1_dialog_content = "ガァ…",
  ui_story_1013_10131002_2_dialog_content = "ステージ目標を達成しました。",
  ui_story_1013_10131002_3_dialog_content = "テストが終了しました。\n本ステージの評価はBです。",
  ui_story_1013_10131002_4_dialog_content = "新規の情報を分析しています…",
  ui_story_1013_10131002_5_dialog_content = "空の末裔の戦闘における能力は、\n戦略決定および人員の配置のみです。",
  ui_story_1013_10131002_6_dialog_content = "空の末裔は光霊を操り、\n各種の戦闘を遂行させることができます。",
  ui_story_1013_10131002_7_dialog_content = "君の知ってることとは違うかもしれないけど、\n今の時代では、それが普通なんだ。",
  ui_story_1013_10131002_8_dialog_content = "理解しました。1号の空の末裔に関するデータベースが、\nアップデートされました。",
  ui_story_1013_10131002_9_dialog_content = "あなたは認証テストに合格しました。",
  ui_story_1013_10131002_10_dialog_content = "1号は、約束に従い、戦場のデータを公開します。",
  ui_story_1013_10131002_11_dialog_content = "なお、あなたはまもなくこのフィールドを離れます。\nこの戦場のデータは使用後、破棄されます。",
  ui_story_1013_10131002_12_dialog_content = "<color=#e8d9bb>キーン――</color>",
  ui_story_1013_10131002_13_dialog_content = "待って…！？",
  ui_story_1013_10131002_14_dialog_content = "そのデータ、破棄しないで！",
  ui_story_1013_10131002_15_option_content = "強制感知！",
  ui_story_1013_10131002_16_dialog_content = "空の末裔さん、あなたの行動は、\n光霊の言語でいう「失礼」にあたります。",
  ui_story_1013_10131002_17_dialog_content = "1号はあなたを認証済みですが、\n1号は理由なく接続、ログインを行ってよいシステムではありません。",
  ui_story_1013_10131002_18_dialog_content = "感知が終わったら、僕からちゃんとアルゴルに報告するよ。",
  ui_story_1013_10131002_19_dialog_content = "理解しました。\nでは、データ破棄を停止する理由を説明してください。",
  ui_story_1013_10131002_20_dialog_content = "この操作は、事前に申請されていません。",
  ui_story_1013_10131002_21_dialog_content = "また、1号には分析できません。\nあなたはなぜ、この戦場のデータの保存、閲覧を行いたいのですか？",
  ui_story_1013_10131002_22_dialog_content = "何を計画しているのですか？",
  ui_story_1013_10131002_23_dialog_content = "実は…",
  ui_story_1013_10131002_24_dialog_content = "僕の巨像が、この前の戦場シミュレーションの最中に\nむりやり僕を助けたせいで、故障しちゃったんだ。",
  ui_story_1013_10131002_25_dialog_content = "それで、意識データがこの戦場のデータの中に\nまだ取り残されてるはずなんだ。",
  ui_story_1013_10131002_26_dialog_content = "それはあなたにとって重要なものなのですか？",
  ui_story_1013_10131002_27_option_content = "ソラヴァンはとても大切な友だちだ",
  ui_story_1013_10131002_28_dialog_content = "ソラヴァンは、\n単なる意識をもった人工知能じゃない…",
  ui_story_1013_10131002_29_dialog_content = "ソラヴァンの意識と記憶の中には、\n僕たちの思い出がたくさん詰まってるんだ。",
  ui_story_1013_10131002_30_dialog_content = "1号は理解しました。",
  ui_story_1013_10131002_31_dialog_content = "新規の情報を分析しています…",
  ui_story_1013_10131002_32_dialog_content = "1号の空の末裔に関するデータベースが、\nアップデートされました。",
  ui_story_1013_10131002_33_dialog_content = "どうしたの？\n急に仲良くなったみたいじゃない。",
  ui_story_1013_10131002_34_dialog_content = "報告します。1号は空の末裔と短期間の接続を行い、\n通常テストの結果に基づいて同期を行いました。",
  ui_story_1013_10131002_35_dialog_content = "（1号…僕が教えた目的を隠してくれてる…？）",
  ui_story_1013_10131002_36_dialog_content = "そう、じゃあ、あなたもこの空の末裔について、\n認識を改めたってわけね。",
  ui_story_1013_10131002_37_dialog_content = "じゃあ、約束した実験に入ってもいい？",
  ui_story_1013_10131002_38_dialog_content = "1号は許可します。",
  ui_story_1013_10131002_39_dialog_content = "空の末裔さん、約束に従い、戦場の現在のデータを、\nあなたの端末に同期しました。",
  ui_story_1013_10131002_40_dialog_content = "…ありがとう、1号。",
  ui_story_1013_10131002_41_dialog_content = "それじゃ、本題に入りましょ。",
  ui_story_1013_10131002_42_dialog_content = "空の末裔くん、ガーディアン1号は感知を通して、\nあなたが古代の科学技術を使う時のデータを学習するわ。",
  ui_story_1013_10131002_43_dialog_content = "学習結果は、会議室のこのモニターに、\nリアルタイムで映し出される。",
  ui_story_1013_10131002_44_dialog_content = "啓光の科学技術革新にとって、とても重要なことなの。\nお願いするわ。",
  ui_story_1013_10131002_45_dialog_content = "努力します。",
  ui_story_1013_10131002_46_dialog_content = "今日はシミュレーションばかりだな。",
  ui_story_1013_10131002_47_dialog_content = "今回は隣で見ていてやることもできん。\nお前1人だ、気を抜くのではないぞ。",
  ui_story_1013_10131002_48_dialog_content = "安心してください。\nそれに厳密に言えば、僕は1人じゃありません。",
  ui_story_1013_10131002_49_dialog_content = "1号は接続の準備ができています。",
  ui_story_1013_10131002_50_dialog_content = "（科学技術の産物と対等に向き合えることが、\n我々の科学者と彼の最大の違いだ）",
  ui_story_1013_10131002_51_dialog_content = "（研究所の技術力もここ数年、向上してはいるが…）",
  ui_story_1013_10131002_X51_dialog_content = "（彼のような態度でなければ、\n技術の頂点にある壁を打ち破ることはできないだろう）",
  ui_story_1013_10131002_52_dialog_content = "（今回の実験を通して、奴らにも伝わるといいが）",
  ui_story_1013_10131002_53_dialog_content = "1号、僕の意識を信用して。",
  ui_story_1013_10131002_54_option_content = "強制感知",
  ui_story_1013_10131002_55_dialog_content = "これが1号の意識空間…？",
  ui_story_1013_10131002_56_dialog_content = "1号はここです、空の末裔。",
  ui_story_1013_10131002_57_dialog_content = "ようこそ！",
  ui_story_1013_10131002_58_dialog_content = "アルゴル教授の指令はここに届きません。\nどうぞ、楽にしてください。",
  ui_story_1013_10131002_59_dialog_content = "じゃ、じゃあ…遠慮なく！",
  ui_story_1013_10131002_60_dialog_content = "（おままごとでもやってる気分だ…）",
  ui_story_1013_10131002_61_dialog_content = "空の末裔さん、意識が不安定ですね。\n巨像の心配をしていると推測します。",
  ui_story_1013_10131002_62_dialog_content = "（う、賢い…さすがは啓光全体を\n動かしてる人工知能だけのことはある）",
  ui_story_1013_10131002_63_dialog_content = "空の末裔さん、今回の学習試験は難易度を上昇させます。\nあなたは1号を信じますか？",
  ui_story_1013_10131002_64_dialog_content = "もちろんだよ。\n信用してるからこそ、「接続」したんだから…",
  ui_story_1013_10131002_65_dialog_content = "信用認証を取得しました。\n1号は巨像の信号を検索し、巨像との接続リクエストを行います。",
  ui_story_1013_10131002_66_dialog_content = "…え？",
  ui_story_1013_10131002_67_dialog_content = "1号を信用していただけるなら、\n1号は巨像の信号を検索し、巨像への接続リクエストを行います。",
  ui_story_1013_10131002_68_dialog_content = "（1号は…ソラヴァンを助ける方法を考えてくれてる？）",
  ui_story_1013_10131002_69_dialog_content = "（言う通りにした方がいいのかな…）",
  ui_story_1013_10131002_70_dialog_content = "困惑を検知しました。",
  ui_story_1013_10131002_71_dialog_content = "分析樹形図を起動します…",
  ui_story_1013_10131002_72_dialog_content = "可能性1：1号が巨像との接続に成功し、巨像の信号を受信する。",
  ui_story_1013_10131002_73_dialog_content = "結果：巨像の意識データが無事に回収され、巨像の意識が回復する。",
  ui_story_1013_10131002_74_dialog_content = "可能性2：1号が巨像との接続に成功し、巨像の信号を受信後、\n巨像のデータを改ざんしようとする。",
  ui_story_1013_10131002_75_dialog_content = "結果：空の末裔は1号を巨像との接続交換機として利用を試み、\n即時接続を切断される。巨像のデータは現状を維持する。",
  ui_story_1013_10131002_76_dialog_content = "可能性3…",
  ui_story_1013_10131002_77_dialog_content = "わ、分かった…可能性の話はいいよ！",
  ui_story_1013_10131002_78_dialog_content = "言いたいことは分かったよ。\n今のところ、他にいい方法がないってことだね。",
  ui_story_1013_10131002_79_dialog_content = "1号、ありがとう。\n巨像のために手を尽くしてくれて。",
  ui_story_1013_10131002_80_dialog_content = "空の末裔と、古代の人工知能は、友だちです。",
  ui_story_1013_10131002_81_dialog_content = "1号も、古代の人工知能です。",
  ui_story_1013_10131002_82_dialog_content = "うん、じゃあ、任せたよ！",
  ui_story_1013_10131002_83_dialog_content = "あの戦場のシミュレーションデータに戻って、\nソラヴァンの意識を取り戻そう。",
  ui_story_1013_10131002_84_dialog_content = "1号は準備が完了しました。\nカウントダウンを開始します…",
  ui_story_1013_10131002_85_dialog_content = "3…",
  ui_story_1013_10131002_86_dialog_content = "2…",
  ui_story_1013_10131002_87_dialog_content = "1…",
  ui_story_1013_10131101_1_dialog_content = "注意してください。\nシミュレーションデータが不安定です。",
  ui_story_1013_10131101_2_dialog_content = "予想外の事態に対応する準備をしてください。",
  ui_story_1013_10131101_3_dialog_content = "大丈夫だよ。\nここには一度、来たことがある。",
  ui_story_1013_10131101_4_dialog_content = "でも、何だか前回とちょっと違うみたいだね。",
  ui_story_1013_10131101_5_dialog_content = "戦場シミュレーションは常に稼働し続けています。\n時間も経過しています。",
  ui_story_1013_10131101_6_dialog_content = "でも、分からないな。これは戦場のシミュレーションでしょ。\nソラヴァンの意識がなんで留まっていられるの？",
  ui_story_1013_10131101_7_dialog_content = "ソラヴァンの意識はデータです。\n戦場シミュレーションもデータです。",
  ui_story_1013_10131101_8_dialog_content = "ソラヴァンの意識が戦場シミュレーションに干渉したため、\n両者のデータがこの空間に混在しています。",
  ui_story_1013_10131101_9_dialog_content = "戦場シミュレーションが自己廃棄される前に、\nソラヴァンへのアクセスを行う必要があります。",
  ui_story_1013_10131101_10_dialog_content = "アクセスできなければ、シミュレーションデータの破棄と同時に、\nソラヴァンのデータも破棄されます。",
  ui_story_1013_10131101_11_dialog_content = "破棄！？\nつまり、ソラヴァンの意識が消えちゃうってこと？",
  ui_story_1013_10131101_12_dialog_content = "消滅するわけではありません。\nアクセスが不可能になるということです。",
  ui_story_1013_10131101_13_dialog_content = "現実世界の事柄に例えれば…\n戦場シミュレーションの廃墟の中に、埋まってしまうということです。",
  ui_story_1013_10131101_14_dialog_content = "意識データは存在を続けます。\nただし、どこにあるのか発見できなくなります。",
  ui_story_1013_10131101_15_dialog_content = "そんな…自己廃棄って何？",
  ui_story_1013_10131101_16_dialog_content = "この戦場シミュレーションに記録されている事件は非常に特殊です。",
  ui_story_1013_10131101_17_dialog_content = "そのため、どこかの地点で終了するのではなく、\nデータが常に破棄され続けています。",
  ui_story_1013_10131101_18_dialog_content = "戦場シミュレーション内の全データが破棄された時、\n自己廃棄が完了します。",
  ui_story_1013_10131101_19_dialog_content = "特殊な事件…確か、科学者の誰かが言ってた。\n文明は一度滅びたことがあるって…",
  ui_story_1013_10131101_20_dialog_content = "つまり、僕たちが今見てるシミュレーションは、\n文明が滅びるまでのデータってこと？",
  ui_story_1013_10131101_21_dialog_content = "計算によると、大多数の生命体は存続できなくなりました。\n「文明が滅びた」という表現におおむね一致します。",
  ui_story_1013_10131101_22_dialog_content = "それで、あんな光景を見たんだ…",
  ui_story_1013_10131101_23_dialog_content = "グアアア――",
  ui_story_1013_10131101_24_dialog_content = "あああああああ！",
  ui_story_1013_10131101_25_dialog_content = "人類が死んで、暗鬼も生き残れなかった…",
  ui_story_1013_10131101_26_dialog_content = "それで滅亡しない方が不思議だ…",
  ui_story_1013_10131101_27_dialog_content = "<color=#e8d9bb>ガキン――</color>",
  ui_story_1013_10131101_28_dialog_content = "！！！",
  ui_story_1013_10131101_29_dialog_content = "<color=#e8d9bb>バキッ、バキン――</color>",
  ui_story_1013_10131101_30_dialog_content = "グォ…",
  ui_story_1013_10131101_31_dialog_content = "暗鬼！？あの時に絶滅するものだと思ってたよ。",
  ui_story_1013_10131101_32_dialog_content = "でも、生き残りがいないとおかしいか…",
  ui_story_1013_10131101_33_dialog_content = "何をしてるんだろう？",
  ui_story_1013_10131101_34_dialog_content = "暗鬼は鉄筋を摂取しようとしています。",
  ui_story_1013_10131101_35_dialog_content = "<color=#e8d9bb>バキッ、バキン――</color>",
  ui_story_1013_10131101_36_dialog_content = "鉄筋を食べてるってこと？なんで？",
  ui_story_1013_10131101_37_dialog_content = "いくら食べる物がないからって、地面に転がってる石とか、\nもっと噛みやすい物がいっぱいあるでしょ？",
  ui_story_1013_10131101_38_dialog_content = "計算に基づいて推測すると、\n暗鬼は鉄筋の性質を吸収しようとしています。",
  ui_story_1013_10131101_39_dialog_content = "性質？",
  ui_story_1013_10131101_40_dialog_content = "鉄筋は大崩壊後も滅亡しませんでした。",
  ui_story_1013_10131101_41_dialog_content = "暗鬼は鉄筋を摂取することで、\n同様の性質を獲得しようとしています。",
  ui_story_1013_10131101_42_dialog_content = "そんなことできるの…？",
  ui_story_1013_10131101_43_dialog_content = "推測データです。\nしかし、暗鬼が文明滅亡後も生き残ったことは事実です。",
  ui_story_1013_10131101_44_dialog_content = "相当の数が生存しています。",
  ui_story_1013_10131101_45_dialog_content = "<color=#e8d9bb>バキッ、バキン――</color>",
  ui_story_1013_10131101_46_dialog_content = "<color=#e8d9bb>ガキン――！！！</color>",
  ui_story_1013_10131101_47_dialog_content = "グア！！！",
  ui_story_1013_10131101_48_dialog_content = "うわっ、共食い！？",
  ui_story_1013_10131101_49_dialog_content = "生存するため、暗鬼は人類よりも、\n多くの行動を行いました。",
  ui_story_1013_10131101_50_dialog_content = "そのため、人類が築いた都市に、\n現在は暗鬼だけが存在しているのです。",
  ui_story_1013_10131101_51_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131101_52_dialog_content = "こんなにたくさん…",
  ui_story_1013_10131101_53_dialog_content = "地面にも、暗鬼の死体がたくさん転がってる…\nたくさんの暗鬼が死ぬのと同時に、たくさんの暗鬼が生まれてるんだね。",
  ui_story_1013_10131101_54_dialog_content = "「進化」は単体で完成するものではありません。\nこのため、暗鬼は急速に世代交代を行いました。",
  ui_story_1013_10131101_55_dialog_content = "崩壊後の極限環境に適応できるようになるまで、\n暗鬼は死を積み重ね、種の遺伝子改良を行いました。",
  ui_story_1013_10131101_56_dialog_content = "ちょっと待って。\nこの暗鬼の群れ…どこかに向かってる？",
  ui_story_1013_10131101_57_dialog_content = "暗鬼の群れは同一の方向に進行しています。\n何らかの存在に引き付けられているようです。",
  ui_story_1013_10131101_58_dialog_content = "何かに引き付けられてる？\n…まさか…！",
  ui_story_1013_10131101_59_option_content = "強制感知！",
  ui_story_1013_10131101_60_dialog_content = "ソラヴァン！ソラヴァンの意識データがあっちにある！",
  ui_story_1013_10131101_61_dialog_content = "状況を理解しました。\n本来存在しないはずの異常な存在は、目立つものでしょう。",
  ui_story_1013_10131101_62_dialog_content = "このため、暗鬼たちは異常データに向かっているようです。",
  ui_story_1013_10131101_63_dialog_content = "ソラヴァンを見つけさえすれば、\n故障を直せるんだよね！？",
  ui_story_1013_10131101_64_dialog_content = "ソラヴァンにアクセスすることにより、故障原因を調べることができます。\n修復できるかどうかは、現在の時点では不明です。",
  ui_story_1013_10131101_65_dialog_content = "分かったよ、詳しいことを聞きたかったわけじゃないんだ。\nとにかく、ソラヴァンのところへ行かなきゃ！",
  ui_story_1013_10131101_66_dialog_content = "幸い、ここはシミュレーションの中だから、\n僕にも暗鬼と戦える力がある…",
  ui_story_1013_10131101_67_dialog_content = "どうだっ！！！",
  ui_story_1013_10131101_68_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_1013_10131101_69_dialog_content = "何の音！？何か崩れたの！？",
  ui_story_1013_10131101_70_dialog_content = "付近の建築物が崩壊しています。",
  ui_story_1013_10131101_71_dialog_content = "注意してください。現在、戦場シミュレーションは不安定です。\n攻撃の影響が世界の崩壊を加速しやすい状態にあります。",
  ui_story_1013_10131101_72_dialog_content = "うわ！本当に何か落ちてきた！",
  ui_story_1013_10131101_73_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_1013_10131101_74_dialog_content = "ゴホゴホ…すごいホコリだ…",
  ui_story_1013_10131101_75_dialog_content = "大した攻撃なんてしてないのに、崩れるなんて…\n世界がもろすぎるよ！",
  ui_story_1013_10131101_76_dialog_content = "どうして…",
  ui_story_1013_10131101_77_dialog_content = "戦場本来の要因により、データは非常に不安定です。\n何の影響がなくとも、自己崩壊が進行していきます。",
  ui_story_1013_10131101_78_dialog_content = "反対方向に注意してください。",
  ui_story_1013_10131101_79_dialog_content = "！！！",
  ui_story_1013_10131101_80_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_1013_10131101_81_dialog_content = "うわぁ、キリがない！",
  ui_story_1013_10131101_82_dialog_content = "注意してください。\n世界の崩壊は戦場シミュレーションの自己データ廃棄の結果です。",
  ui_story_1013_10131101_83_dialog_content = "そして、このシミュレーションデータの廃棄は…",
  ui_story_1013_10131101_84_dialog_content = "ソラヴァンのデータも消されるってことなんだよね？",
  ui_story_1013_10131101_85_dialog_content = "正しい理解です。",
  ui_story_1013_10131101_86_dialog_content = "ぐちを言ってるヒマもないみたいだ！",
  ui_story_1013_10131101_87_dialog_content = "世界が完全に崩壊する前に、\n何としても、ソラヴァンのところにたどりつかなきゃ！",
  ui_story_1013_10131202_1_dialog_content = "30…",
  ui_story_1013_10131202_2_dialog_content = "<color=#e8d9bb>ガラガラ…</color>",
  ui_story_1013_10131202_3_dialog_content = "うわぁああ！",
  ui_story_1013_10131202_4_dialog_content = "落ちるところだった…",
  ui_story_1013_10131202_5_dialog_content = "地面のヒビが追いかけてくるみたいなんだけど！？",
  ui_story_1013_10131202_6_dialog_content = "あなたが崩壊を引き起こしている理由の1つだからだと考えられます。",
  ui_story_1013_10131202_7_dialog_content = "25…",
  ui_story_1013_10131202_8_dialog_content = "ねぇ、その不吉なカウントダウンは、\nどういう意味！？",
  ui_story_1013_10131202_9_dialog_content = "残り時間です。",
  ui_story_1013_10131202_10_dialog_content = "戦場シミュレーションのデータを解析し、崩壊曲線を割り出しました。\n正確性は保証します。",
  ui_story_1013_10131202_11_dialog_content = "じゃあ、20秒ちょっとしかないの！？\nそれはあまりにも…",
  ui_story_1013_10131202_12_dialog_content = "<color=#e8d9bb>ドンッ――！</color>",
  ui_story_1013_10131202_13_dialog_content = "20…",
  ui_story_1013_10131202_14_dialog_content = "分かった分かった！\n20秒あれば十分だよ！",
  ui_story_1013_10131202_15_dialog_content = "ソラヴァンはすぐ近くにいる！\n僕には分かる！",
  ui_story_1013_10131202_16_dialog_content = "暗鬼への警戒もおこたらないでください。",
  ui_story_1013_10131202_17_dialog_content = "ううっ、こんな時に！",
  ui_story_1013_10131202_18_dialog_content = "邪魔しないで！",
  ui_story_1013_10131202_19_dialog_content = "<color=#e8d9bb>ドン――！</color>",
  ui_story_1013_10131202_20_dialog_content = "うわああああ！！！",
  ui_story_1013_10131202_21_dialog_content = "<color=#e8d9bb>ガラガラ…</color>",
  ui_story_1013_10131202_22_dialog_content = "ッ…ゴホゴホ…",
  ui_story_1013_10131202_23_dialog_content = "痛い…",
  ui_story_1013_10131202_24_dialog_content = "1号、残り時間は…？",
  ui_story_1013_10131202_25_dialog_content = "10…",
  ui_story_1013_10131202_26_dialog_content = "まずい、急がないと…！",
  ui_story_1013_10131202_27_dialog_content = "ソラヴァンまであと少し、あと少しなんだ…",
  ui_story_1013_10131202_28_dialog_content = "すぐ目と鼻の先なんだ…！",
  ui_story_1013_10131202_29_dialog_content = "5…",
  ui_story_1013_10131202_30_dialog_content = "ゴホッ…",
  ui_story_1013_10131202_31_dialog_content = "4…",
  ui_story_1013_10131202_32_dialog_content = "もうすぐ、もうすぐそこだ…！",
  ui_story_1013_10131202_33_dialog_content = "3…",
  ui_story_1013_10131202_34_dialog_content = "はぁ…はぁ…",
  ui_story_1013_10131202_35_dialog_content = "2…",
  ui_story_1013_10131202_36_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1013_10131202_37_dialog_content = "1…",
  ui_story_1013_10131202_38_dialog_content = "強制感知！",
  ui_story_1013_10131202_39_dialog_content = "ソラヴァン！",
  ui_story_1013_10131202_40_dialog_content = "…",
  ui_story_1013_10131202_41_dialog_content = "見つけた！",
  ui_story_1013_10131202_42_dialog_content = "どう？間に合った！？",
  ui_story_1013_10131202_43_dialog_content = "急いでソラヴァンと接続して！",
  ui_story_1013_10131202_44_dialog_content = "ソラヴァンのデータポートにアクセスします。",
  ui_story_1013_10131202_45_dialog_content = "…アクセスリクエストに応答しません。\n強制アクセスを実行します。",
  ui_story_1013_10131202_46_dialog_content = "準備をしてください。\nあなたの意識をソラヴァンのデータ空間に進入させます。",
  ui_story_1013_10131202_47_dialog_content = "1号はデータ空間内の状況を予測できません。",
  ui_story_1013_10131202_48_dialog_content = "もちろん、準備はできてる！\n…それに、どうせ今より大変ってことはないよね？",
  ui_story_1013_10131202_49_dialog_content = "データ転送を開始します。",
  ui_story_1013_10131202_50_dialog_content = "ソラヴァンにログイン。",
  ui_story_1013_10131202_51_dialog_content = "うわぁ…真っ暗だ。\n僕たち、もう中に入ってるの？",
  ui_story_1013_10131202_52_dialog_content = "ログイン済みです。\n何も見えないようなら、目を開けてみてください。",
  ui_story_1013_10131202_53_dialog_content = "えっ？",
  ui_story_1013_10131202_54_dialog_content = "あ、見えた…でも、待って。\nなんで言われるまで気づかなかったんだろう。",
  ui_story_1013_10131202_55_dialog_content = "正常な現象です。\n戦場シミュレーションの終了時、あなたは目を開けていました。",
  ui_story_1013_10131202_56_dialog_content = "そのため、あなたの意識の中では目は開いた状態でした。\n再度目を開こうとは思わないと考えられます。",
  ui_story_1013_10131202_57_dialog_content = "しかし、このデータ空間への進入時、\n1号はあなたの意識的身体を目が閉じた状態で転送しました。",
  ui_story_1013_10131202_58_dialog_content = "身体と意識の相違により引き起こされた現象です。",
  ui_story_1013_10131202_59_dialog_content = "そうなんだ…？",
  ui_story_1013_10131202_60_dialog_content = "理解できましたか？\nもう一度説明します…",
  ui_story_1013_10131202_61_dialog_content = "理解した！ちゃんと理解したよ！",
  ui_story_1013_10131202_62_dialog_content = "これは…ソラヴァン？",
  ui_story_1013_10131202_X62_dialog_content = "すごく近くにいるのに、触れないみたいだ。",
  ui_story_1013_10131202_X63_dialog_content = "ここはどこなの？",
  ui_story_1013_10131202_63_dialog_content = "視覚情報上では、あなたが見ているものは、\n確かにソラヴァンの内部です。",
  ui_story_1013_10131202_64_dialog_content = "しかし、正確に表現するならば、\nここはソラヴァンのデータ保存領域です。",
  ui_story_1013_10131202_65_dialog_content = "つまり…ソラヴァンの「記憶」の中と言えます。",
  ui_story_1013_10131202_66_dialog_content = "記憶？",
  ui_story_1013_10131202_67_dialog_content = "どうして？\nソラヴァンの故障を調べるんじゃなかったの？",
  ui_story_1013_10131202_68_dialog_content = "その通りです。ソラヴァンが故障した原因は、\nデータの保存空間に無関係なデータの断片が入り込んだことによるものです。",
  ui_story_1013_10131202_69_dialog_content = "私たちが行うべきことは、膨大なデータの中から、\nその断片を検出し、修復することです。",
  ui_story_1013_10131202_70_dialog_content = "1号にとっては単純なデータ処理ですが…",
  ui_story_1013_10131202_71_dialog_content = "あなたの脳で直接データを処理することはできません。\nこのため1号は、あなたの想像力を媒体とし、データの可視化を実行します。",
  ui_story_1013_10131202_72_dialog_content = "保存されていた記憶は正常な画像となり、\n異常なデータの断片は異常な画像として認知できるでしょう。",
  ui_story_1013_10131202_73_dialog_content = "これより、1号とあなたでソラヴァンの記憶をチェックし――",
  ui_story_1013_10131202_74_dialog_content = "故障を引き起こしたデータ断片の検知を開始します。",
  ui_story_1013_10131202_75_dialog_content = "僕にそんなもの見分けられるかな？",
  ui_story_1013_10131202_76_dialog_content = "問題のあるデータはあなたにとって、\n嫌いなもの、敵視するものなどの事物として認知されます。識別可能だと思われます。",
  ui_story_1013_10131202_77_dialog_content = "それなら簡単そうに聞こえるね。",
  ui_story_1013_10131202_78_dialog_content = "1号には予測不能です。",
  ui_story_1013_10131202_79_dialog_content = "分かった。とにかくやってみるしかないんだね。",
  ui_story_1013_10131202_X79_dialog_content = "データにアクセス中…\nソラヴァンの船室へ移動します。",
  ui_story_1013_10131202_X80_dialog_content = "ふぅ、ここならよく知ってるよ！",
  ui_story_1013_10131202_80_dialog_content = "それはそうと、ここってソラヴァンのいつ頃の記憶なんだろう？",
  ui_story_1013_10131202_81_dialog_content = "周りは何も起こってない。\n静かすぎるぐらいだ。",
  ui_story_1013_10131202_82_dialog_content = "ここはどこ？\nええと…この記憶の中だと、ソラヴァンはどこにいるの？",
  ui_story_1013_10131202_83_dialog_content = "1号はこのデータの内容を把握していません。",
  ui_story_1013_10131202_84_dialog_content = "それもそうか。\n何でも君に聞いてちゃいけないね。",
  ui_story_1013_10131202_85_dialog_content = "ソラヴァンのことは、僕が一番分かってる。\nちょっと調べに行ってくるね。",
  ui_story_1013_10131202_86_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ…</color>",
  ui_story_1013_10131202_87_dialog_content = "あれ？船室のドアが全部閉まってる？",
  ui_story_1013_10131202_88_dialog_content = "ええと、ここを開ければ…",
  ui_story_1013_10131202_89_dialog_content = "<color=#e8d9bb>ピー！ピー！ピー！</color>",
  ui_story_1013_10131202_90_dialog_content = "警告音！？どういうこと？",
  ui_story_1013_10131202_91_dialog_content = "ソラヴァン、僕を閉じ込めるつもり！？",
  ui_story_1013_10131202_92_dialog_content = "ソラヴァンと外部との気体交換が停止されていることを検知しました。\n船室が完全に閉鎖されています。",
  ui_story_1013_10131202_93_dialog_content = "いったい、どういう状況…？",
  ui_story_1013_10131202_94_dialog_content = "そうだ、制御装置に記録があるはずだ。",
  ui_story_1013_10131202_95_dialog_content = "ええと…現在の…座標は…",
  ui_story_1013_10131202_96_dialog_content = "！？",
  ui_story_1013_10131202_97_dialog_content = "位置情報がない？",
  ui_story_1013_10131202_98_dialog_content = "他の情報も…ない！？",
  ui_story_1013_10131202_99_dialog_content = "制御装置の情報、どうしてこんなに少ないの？",
  ui_story_1013_10131202_100_dialog_content = "ソラヴァンの記憶データですので、\n当時存在していた情報が、その後削除された可能性があります。",
  ui_story_1013_10131202_101_dialog_content = "何も起こってない、何の記録もない…\nずいぶんさみしい記憶だね。",
  ui_story_1013_10131202_102_dialog_content = "じゃあ、何を覚えてるって言うんだろう？",
  ui_story_1013_10131202_103_dialog_content = "機械の記憶回路は生物の記憶回路と異なります。",
  ui_story_1013_10131202_104_dialog_content = "ソラヴァンにこのような記憶があるのは、\n記憶しておくべきだからではなく、単に何も起こっていないためです。",
  ui_story_1013_10131202_105_dialog_content = "ソラヴァンは機械じゃないよ！ソラヴァンは…",
  ui_story_1013_10131202_106_dialog_content = "…あ、そうか。君も…",
  ui_story_1013_10131202_107_dialog_content = "…ごめん、機械は悪いって意味じゃないんだ。",
  ui_story_1013_10131202_108_dialog_content = "1号には、謝罪を行った理由が理解できません。",
  ui_story_1013_10131202_109_dialog_content = "分からなくていいよ！\n僕って、いつも謝ってばかりなんだ。ハハ、ハハハ…",
  ui_story_1013_10131202_110_dialog_content = "？",
  ui_story_1013_10131202_111_dialog_content = "コホン…ええと、本題に戻るけど…\nどこを探せば、状況を記録してる情報があるかな？",
  ui_story_1013_10131202_112_dialog_content = "1号が一部を発見しています。",
  ui_story_1013_10131202_113_dialog_content = "え？どこに？",
  ui_story_1013_10131202_114_dialog_content = "「端末」と呼ばれる装置の位置です。",
  ui_story_1013_10131202_115_dialog_content = "これは…",
  ui_story_1013_10131202_116_dialog_content = "■■■■■■■■■■■■",
  ui_story_1013_10131202_117_dialog_content = "これは…何？",
  ui_story_1013_10131202_118_dialog_content = "古代文字だと考えられます。",
  ui_story_1013_10131202_119_dialog_content = "少々お待ちください。\nソラヴァンに翻訳方法が記録されています。",
  ui_story_1013_10131202_120_dialog_content = "あなたにも分かる言語に変換します。",
  ui_story_1013_10131202_121_dialog_content = "「地上から送られてきた情報を受信した。\nおそらく、これが最後になるだろう」",
  ui_story_1013_10131202_122_dialog_content = "「塔の郷が壊滅した」",
  ui_story_1013_10131202_123_dialog_content = "何ですって？まさか…なぜ、こんなことに？",
  ui_story_1013_10131202_124_dialog_content = "ああ…遅かれ早かれ、こうなる運命だったんだ。\n地上はどこもかしこも壊滅…あそこだけ無事なはずはない。",
  ui_story_1013_10131202_125_dialog_content = "こうなることは、\n僕たちが出発した瞬間に決まってたんだ。",
  ui_story_1013_10131202_126_dialog_content = "だったら私たち、どこに戻ればいいの？",
  ui_story_1013_10131202_127_dialog_content = "心配するな。フランシス先生が言っていただろう。\n帰るべき時がきたら、信号を送ると。",
  ui_story_1013_10131202_128_dialog_content = "先生が何もかも手配してくれている。\nだから、先生を信じるんだ。いいな？",
  ui_story_1013_10131202_129_dialog_content = "うん、信じる。",
  ui_story_1013_10131202_130_dialog_content = "どうせ他に選択肢なんてないだろう？\n信じるしかない。",
  ui_story_1013_10131202_131_dialog_content = "そうだ、聞きたいことがあったの。\n私たち、いつになったら巨像から出られるの？",
  ui_story_1013_10131202_132_dialog_content = "1人で巨像に乗ったままなんて、\n気がおかしくなりそうだわ。",
  ui_story_1013_10131202_133_dialog_content = "みんなに会いたいわ。\nこんなに近くにいるのに、会えないなんて…",
  ui_story_1013_10131202_134_dialog_content = "妹にも会いたくて仕方ないの。\n妹はあなたの巨像に乗ってたわよね、ええと…",
  ui_story_1013_10131202_135_dialog_content = "ごめんなさい、217号。\nあなたの名前、忘れちゃったみたい。",
  ui_story_1013_10131202_136_dialog_content = "ああ、お前の妹は元気だ。安心するがいい。",
  ui_story_1013_10131202_137_dialog_content = "ただ、今はまだ自分の巨像を出てはいけない。\n絶対にだ。",
  ui_story_1013_10131202_138_dialog_content = "くれぐれもバカなマネはするなよ。\n危険な目に遭うだけだ。",
  ui_story_1013_10131202_139_dialog_content = "バカなマネをするなというが、\n他に何かできることがあるのか？",
  ui_story_1013_10131202_140_dialog_content = "食事ももうウンザリだ。\nそのうち寝ることにも飽きたら、いったい何をすればいい？",
  ui_story_1013_10131202_141_dialog_content = "巨像の中には何もない。これからさらに、\nもとから哀れなほど少なかった外の情報も、来なくなるんだろう？",
  ui_story_1013_10131202_142_dialog_content = "毎日端末を見つめたまま、\n番号で呼び合う仲間と話すしかない。",
  ui_story_1013_10131202_143_dialog_content = "いつか皆、79号みたいに皆の名前を忘れて、\n数字だけが残るんだろうな。",
  ui_story_1013_10131202_144_dialog_content = "そんなことない！\nあたしはあなたの名前、覚えてるわよ、パック！",
  ui_story_1013_10131202_145_dialog_content = "みんなの名前も忘れたりなんかしない！\n空の末裔は番号で呼び合うような種族じゃないよ！",
  ui_story_1013_10131202_146_dialog_content = "さっさと忘れた方がいい。",
  ui_story_1013_10131202_147_dialog_content = "形にこだわったって、いいことなんか何1つない。\n本当に忘れちまった時の苦しみが大きくなるだけだ。",
  ui_story_1013_10131202_148_dialog_content = "使わなくなった呼び名なんて、\n今日や1か月後なら覚えてられるかもしれないが…",
  ui_story_1013_10131202_149_dialog_content = "1年後はどうだ？10年後は？",
  ui_story_1013_10131202_150_dialog_content = "10年後？そ、そんな先のこと、分かんないよ…",
  ui_story_1013_10131202_151_dialog_content = "あたしたち、このまま10年もここにいるの…？",
  ui_story_1013_10131202_152_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131202_153_dialog_content = "あ、あたしたち、帰れるんだよね？",
  ui_story_1013_10131202_154_dialog_content = "ああ、帰れるとも。",
  ui_story_1013_10131202_155_dialog_content = "フランシス先生が言っていただろう。\n帰るべき時がきたら、信号を送ると。",
  ui_story_1013_10131202_156_dialog_content = "先生を信じているだろう？",
  ui_story_1013_10131301_1_dialog_content = "これって…空の末裔たちの会話記録だ！",
  ui_story_1013_10131301_2_dialog_content = "周りに他の巨像がいるってこと？",
  ui_story_1013_10131301_3_dialog_content = "十分な情報を収集できません。",
  ui_story_1013_10131301_4_dialog_content = "ただ、その可能性が高いと推測されます。",
  ui_story_1013_10131301_5_dialog_content = "会話記録からすると、\n他の巨像もソラヴァンと同じように、船室を締め切っているんだね。",
  ui_story_1013_10131301_6_dialog_content = "全員が巨像の中に閉じこもって、\n何をするでもなく、日々を過ごす…",
  ui_story_1013_10131301_7_dialog_content = "（その感覚はよく知ってる）",
  ui_story_1013_10131301_8_dialog_content = "（小さい頃は、僕もそうして過ごしてた）",
  ui_story_1013_10131301_9_dialog_content = "1号の分析によると、\n追放された、または何かから退避しているものと推測されます。",
  ui_story_1013_10131301_10_dialog_content = "追放、すなわち、何者かが巨像を利用し、\n一部の空の末裔を閉じ込め、指定された場所へ押送している。または…",
  ui_story_1013_10131301_11_dialog_content = "退避、すなわち、巨像の外部環境は空の末裔が生存できる状態になく、\n船室を完全に封鎖し、外部から隔離して空の末裔を保護している。",
  ui_story_1013_10131301_12_dialog_content = "会話の雰囲気からして、\n僕は退避の方だと思うよ。",
  ui_story_1013_10131301_13_dialog_content = "それと、僕もよく知ってる「フランシス先生」のことを話してた。",
  ui_story_1013_10131301_14_dialog_content = "空の末裔さんのデータベースに存在する人物なのですか？",
  ui_story_1013_10131301_15_dialog_content = "知ってるというよりは、\nその人が残した歴史の痕跡を見たことがあるってだけかな。",
  ui_story_1013_10131301_16_dialog_content = "つまり、少ない情報だけでも記憶に残存している人物だと推測しました。",
  ui_story_1013_10131301_17_dialog_content = "そうだよ。とても変わった空の末裔なんだ。",
  ui_story_1013_10131301_18_dialog_content = "むしろ、その人の生きていた時代の\n「空の末裔」とは、全く逆の存在だったみたいなんだ。",
  ui_story_1013_10131301_19_dialog_content = "フランシス先生は世界に戦争を起こすことを選ばず、\n反対に、空の末裔に与えられていた運命に抵抗したんだ。",
  ui_story_1013_10131301_20_dialog_content = "僕は以前、絶体絶命の時に\nフランシス先生の意志に触れて、感動したんだよ。",
  ui_story_1013_10131301_21_dialog_content = "今は僕と同じ人を信じてる人が1人じゃないって分かって、\nちょっとうれしい気持ちだよ。",
  ui_story_1013_10131301_22_dialog_content = "端末情報の人物のことですか？",
  ui_story_1013_10131301_23_dialog_content = "うん、番号で呼び合ってた空の末裔たちのことだよ。",
  ui_story_1013_10131301_24_dialog_content = "時代は離れてるけど、僕もこの人たちと同じように、\n同じ名前の人を信じていたことがあるんだ。",
  ui_story_1013_10131301_25_dialog_content = "ほんの少しの共通点だけど、\nそこに僕はこの人たちの信念を感じる。",
  ui_story_1013_10131301_26_dialog_content = "だから、誰かに無理やり追放されたようには思えないよ。\nきっと自分たちで、進むべき道を選んだんだ。",
  ui_story_1013_10131301_27_dialog_content = "何か恐ろしいことが起こって、\nこんな方法で危険を回避するしかなかったのかも。",
  ui_story_1013_10131301_28_dialog_content = "非常に特異なロジックです。1号には理解できません。\nしかし、あなたの結論を記録しました。",
  ui_story_1013_10131301_29_dialog_content = "わざわざ記録することでもないと思うけど…",
  ui_story_1013_10131301_30_dialog_content = "会話記録はここで終わってるね。\n他の情報は見つかった？",
  ui_story_1013_10131301_31_dialog_content = "発見できませんでした。この記録だけです。",
  ui_story_1013_10131301_32_dialog_content = "え？じゃあ…他にどうするの？",
  ui_story_1013_10131301_33_dialog_content = "おかしなデータも見つからない、\n調べるような新しい情報もない…",
  ui_story_1013_10131301_34_dialog_content = "ここで、この空の末裔たちみたいに、\n退屈を感じてるしかないってこと？",
  ui_story_1013_10131301_35_dialog_content = "効率は低いですが、\nそれもデータ検索の方法の一つです。",
  ui_story_1013_10131301_36_dialog_content = "少々お待ちください。\nより精密な検索を実行します。",
  ui_story_1013_10131301_37_dialog_content = "<color=#e8d9bb>ウオーン――</color>",
  ui_story_1013_10131301_38_dialog_content = "え？何をしたの？",
  ui_story_1013_10131301_39_dialog_content = "視界情報に影響が出るかもしれませんが、あわてないでください。",
  ui_story_1013_10131301_40_dialog_content = "あわててはいないよ。\nでも、どういうことか分からないんだ。",
  ui_story_1013_10131301_41_dialog_content = "あなたにも理解できる言葉で説明すると、\n1号は、記憶内の時間を調整しました。",
  ui_story_1013_10131301_42_dialog_content = "現在、異常なデータのない時間を高速スキップしています。",
  ui_story_1013_10131301_43_dialog_content = "ずいぶん便利だね…",
  ui_story_1013_10131301_44_dialog_content = "グアアッ！",
  ui_story_1013_10131301_45_dialog_content = "うわっ！？",
  ui_story_1013_10131301_46_dialog_content = "ど、どういうこと！？",
  ui_story_1013_10131301_47_dialog_content = "異常なデータのない時間をスキップしました。\nつまり、当然の結果として…",
  ui_story_1013_10131301_48_dialog_content = "グア！",
  ui_story_1013_10131301_49_dialog_content = "だ、大丈夫！？",
  ui_story_1013_10131301_50_dialog_content = "…異常なデータの存在する記憶に到着します。",
  ui_story_1013_10131301_51_dialog_content = "こういう時はもっと簡潔な説明でいいよ！",
  ui_story_1013_10131301_52_dialog_content = "つまり、この暗鬼たちが異常なデータなんだね？",
  ui_story_1013_10131301_53_dialog_content = "そうです。異常データはあなたの想像力によるフィルターを介し、\nあなたの嫌いな、あるいは敵視する事物となって…",
  ui_story_1013_10131301_54_dialog_content = "グア！",
  ui_story_1013_10131301_55_dialog_content = "ねぇ…",
  ui_story_1013_10131301_56_dialog_content = "…表現されます。問題ありません。\n1号のデータ構造は安定しています。簡単には破壊されません。",
  ui_story_1013_10131301_57_dialog_content = "分かったけど、だからってサンドバッグみたいに攻撃を受けないでね。\nびっくりするから…",
  ui_story_1013_10131301_58_dialog_content = "データがどうとか、僕には分からないし、\n理解する余裕もないよ。",
  ui_story_1013_10131301_59_dialog_content = "でも、暗鬼の姿で出てくるなら、\n暗鬼として倒せばいいんでしょ？",
  ui_story_1013_10131302_1_dialog_content = "速射感知！",
  ui_story_1013_10131302_2_dialog_content = "散れ！氷花よ！",
  ui_story_1013_10131302_3_dialog_content = "いくぞ、必殺！",
  ui_story_1013_10131302_4_dialog_content = "1号には理解できません。\n今のような言葉を叫ぶことに戦闘上の効果があるのですか？",
  ui_story_1013_10131302_5_dialog_content = "ううん…実は僕もよく知らないよ。",
  ui_story_1013_10131302_6_dialog_content = "光霊って戦う時、こんな感じで叫ぶから、\n僕もやってみたくて。",
  ui_story_1013_10131302_7_dialog_content = "その方がカッコいいからかな？",
  ui_story_1013_10131302_8_dialog_content = "でも、とにかく敵を倒せたでしょ？\n効いたみたいだよ。",
  ui_story_1013_10131302_9_dialog_content = "1号はロジックが理解できませんでした。\n理解を試みています…",
  ui_story_1013_10131302_10_dialog_content = "アハハ…ムダ話はここまでにしよう。\nどう？ソラヴァンに変化はあった？",
  ui_story_1013_10131302_11_dialog_content = "およそ37%の異常データが排除されました。\n戦闘の効果が出ています。",
  ui_story_1013_10131302_12_dialog_content = "ソラヴァンの一部機能が回復しています。",
  ui_story_1013_10131302_13_dialog_content = "37%？一気にけっこう片付いたね。",
  ui_story_1013_10131302_14_dialog_content = "断片化していたデータがソラヴァンによって自己修正されました。",
  ui_story_1013_10131302_15_dialog_content = "そのため、修復するべき異常データが、\n高い集合性を持っています。",
  ui_story_1013_10131302_16_dialog_content = "計算によると、異常データは残り1か所です。",
  ui_story_1013_10131302_17_dialog_content = "え！？じゃあ、成功まであと少しだ！",
  ui_story_1013_10131302_18_dialog_content = "その通りです。ただし、残存している異常データは\nさらに深刻な問題を起こしています。注意してください。",
  ui_story_1013_10131302_19_dialog_content = "準備が完了次第、1号は詳細検索を実行し、\n異常データのある時間へと移動します。",
  ui_story_1013_10131302_20_dialog_content = "ちょっと待って。\n今僕たちのいる時間って、入ってきた時とは違うんだよね？",
  ui_story_1013_10131302_21_dialog_content = "その通りです。\nさきほどの検索で長い時間がスキップされています。",
  ui_story_1013_10131302_22_dialog_content = "記憶の中に参照データが存在しないため、\n正確な時間差は不明です。",
  ui_story_1013_10131302_23_dialog_content = "そういうことなら、もう一度端末を見たいな。",
  ui_story_1013_10131302_24_dialog_content = "この時の空の末裔がどんな経験をしてたのか、知りたいんだ。",
  ui_story_1013_10131302_25_dialog_content = "了解しました。\n1号は端末情報を出力します。",
  ui_story_1013_10131302_26_dialog_content = "あ、翻訳もお願い。",
  ui_story_1013_10131302_27_dialog_content = "指示が無くともその通り実行されます。\n人工知能は自身の行動を常に最適化しています。",
  ui_story_1013_10131302_28_dialog_content = "1号は最適解です。",
  ui_story_1013_10131302_29_dialog_content = "みんな――",
  ui_story_1013_10131302_30_dialog_content = "見て見て！",
  ui_story_1013_10131302_31_dialog_content = "突然だけど、今日はあたしの誕生日なの。",
  ui_story_1013_10131302_32_dialog_content = "あたしの歌、聴きたくない？",
  ui_story_1013_10131302_33_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_34_dialog_content = "そう…じゃあ、他のことをするよ。",
  ui_story_1013_10131302_35_dialog_content = "歌はやめて、詩を作る！",
  ui_story_1013_10131302_36_dialog_content = "あたし、得意なんだ。\nパパだって詩人になれるって言ってくれてたよ！",
  ui_story_1013_10131302_37_dialog_content = "35号…この前の誕生日がいつだったか、覚えてるぞ。",
  ui_story_1013_10131302_38_dialog_content = "どれぐらい前だったかはもう忘れたが、\n1年前じゃないことは確かだ。",
  ui_story_1013_10131302_39_dialog_content = "ええ？982号、記憶力よすぎ…\nごまかせると思ったのに…",
  ui_story_1013_10131302_40_dialog_content = "誕生日は大切な日だ。\nごまかしたりするべきじゃないな。",
  ui_story_1013_10131302_41_dialog_content = "わかったよ、だったら誕生日はやめとく。",
  ui_story_1013_10131302_42_dialog_content = "代わりに、いいことを教えてあげる！",
  ui_story_1013_10131302_43_dialog_content = "4番の缶詰をあっためて、冷凍した15番と混ぜるの。",
  ui_story_1013_10131302_44_dialog_content = "すっごくおいしいよ！みんなも試してみて！",
  ui_story_1013_10131302_45_dialog_content = "35号は相変わらず元気ね。",
  ui_story_1013_10131302_46_dialog_content = "79号姉さん！久しぶり！",
  ui_story_1013_10131302_47_dialog_content = "ええ、久しぶりね。\n最近端末をあまり見てなくって。",
  ui_story_1013_10131302_48_dialog_content = "もっと見てよ。\n1人でしゃべってもつまんないよ～。",
  ui_story_1013_10131302_49_dialog_content = "でも、982号がよく相手してくれるみたいじゃない。",
  ui_story_1013_10131302_50_dialog_content = "どこが！？\n982号が答えてくれる回数なんて、もっと少ないよ。",
  ui_story_1013_10131302_51_dialog_content = "今日は珍しく返事が来たと思ったら、\nあたしの邪魔をされたし…",
  ui_story_1013_10131302_52_dialog_content = "謝った方がいいか？",
  ui_story_1013_10131302_53_dialog_content = "そ、その必要はないけど…\nそもそも、ウソを言ったあたしがいけないんだもん…",
  ui_story_1013_10131302_54_dialog_content = "実は、今日端末を見たのには訳があってね。\n今日は僕にとって特別な日なんだ。",
  ui_story_1013_10131302_55_dialog_content = "今日のことをしっかり覚えていたくてね。",
  ui_story_1013_10131302_56_dialog_content = "へえ、982号の誕生日？",
  ui_story_1013_10131302_57_dialog_content = "いいや。",
  ui_story_1013_10131302_58_dialog_content = "誕生日とは…正反対と言ったところかな。",
  ui_story_1013_10131302_59_dialog_content = "982号、あなた…？",
  ui_story_1013_10131302_60_dialog_content = "そうだ、詩が得意なんだろう？\nひとつ、作ってくれないか？",
  ui_story_1013_10131302_61_dialog_content = "いいよ！テーマは何がいい？",
  ui_story_1013_10131302_62_dialog_content = "「大地」…大地の詩がいい。",
  ui_story_1013_10131302_63_dialog_content = "分かった！だったら、しっかり考えなきゃ。\nきっと喜ばせてあげるから！",
  ui_story_1013_10131302_64_dialog_content = "どれぐらいかかりそうだ？",
  ui_story_1013_10131302_65_dialog_content = "分かんないよ。\n今のところ、何も思いつかないし…",
  ui_story_1013_10131302_66_dialog_content = "ちょっと待っててくれる？\n出来たらすぐに呼ぶから！",
  ui_story_1013_10131302_67_dialog_content = "急いでくれよ？\nあまり時間がかかるようなら、別にいらない。",
  ui_story_1013_10131302_68_dialog_content = "いらないなんてダメ！\nせっかく誰かのために詩を作ってあげられるのに！",
  ui_story_1013_10131302_69_dialog_content = "ちゃんと聞いてよね！",
  ui_story_1013_10131302_70_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_71_dialog_content = "982号、できたよ！",
  ui_story_1013_10131302_72_dialog_content = "982号？",
  ui_story_1013_10131302_73_dialog_content = "ちょっと、一生懸命作ったんだよ！？",
  ui_story_1013_10131302_74_dialog_content = "これ以上返事してくれないなら、\nあたし、怒っちゃうよ！？",
  ui_story_1013_10131302_75_dialog_content = "982号！982号！982号ったら！",
  ui_story_1013_10131302_76_dialog_content = "…",
  ui_story_1013_10131302_77_dialog_content = "まあ、いいよ…\nこんなことであたしは怒ったりしないから。",
  ui_story_1013_10131302_78_dialog_content = "次に端末を見た時には呼んでね。\nあたしは、いつでもいるから。",
  ui_story_1013_10131302_79_dialog_content = "35号、今日はずいぶん早いのね。",
  ui_story_1013_10131302_80_dialog_content = "うん！昨日は徹夜して982号の詩を作ってたんだ。",
  ui_story_1013_10131302_81_dialog_content = "なのに…",
  ui_story_1013_10131302_82_dialog_content = "そう…お疲れ様。",
  ui_story_1013_10131302_83_dialog_content = "982号はそういう性格なの、\nあなたも知ってるでしょ。",
  ui_story_1013_10131302_84_dialog_content = "昨日欲しいって言っても、\n今日には気が変わってたりするのよ。",
  ui_story_1013_10131302_85_dialog_content = "あー、確かにそういう事しそう。",
  ui_story_1013_10131302_86_dialog_content = "だから、気にしちゃダメよ。書いた詩、あたしに見せてもらえる？\n35号の才能、見てみたいわ。",
  ui_story_1013_10131302_87_dialog_content = "うーん…でも、この詩は982号へのプレゼントだから、\n982号に一番に見てもらいたいの。",
  ui_story_1013_10131302_88_dialog_content = "79号姉さんも詩を聞きたいっていうなら、\n今度また作ってあげるよ！",
  ui_story_1013_10131302_89_dialog_content = "あら、私のために？",
  ui_story_1013_10131302_90_dialog_content = "でも、遠慮しておくわ。\nまた35号に徹夜させたら悪いもの。",
  ui_story_1013_10131302_91_dialog_content = "え？大丈夫だよ。\n寝る時間なんていくらでもあるんだから！",
  ui_story_1013_10131302_92_dialog_content = "35号が心を込めて作ってくれる詩なのよ。\n軽々しく欲しがったりはできないわ。",
  ui_story_1013_10131302_93_dialog_content = "次の機会に作ってちょうだい。",
  ui_story_1013_10131302_94_dialog_content = "私にとって、特別な日に。",
  ui_story_1013_10131302_95_dialog_content = "うん、じゃあ、そうする。",
  ui_story_1013_10131302_96_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_97_dialog_content = "今日、物置で開封されてないレコードを見つけたの。",
  ui_story_1013_10131302_98_dialog_content = "すっごくいい曲だったよ！\nみんなも聴きたくない？",
  ui_story_1013_10131302_99_dialog_content = "ねえ、ちょっと…誰かいないの？",
  ui_story_1013_10131302_100_dialog_content = "まあ、いいよ。端末にアップしといたから、\n興味があったら聴いてね。",
  ui_story_1013_10131302_101_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_102_dialog_content = "ううん、お風呂が故障しちゃったみたい。",
  ui_story_1013_10131302_103_dialog_content = "誰か修理できる人いる？\n修理の仕方、教えてくれない？",
  ui_story_1013_10131302_104_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_105_dialog_content = "あたしのいるところ、気温が下がってきたよ。\nみんなもちゃんと厚着してね。",
  ui_story_1013_10131302_106_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_107_dialog_content = "ああ、ずいぶん長いこと話してないよ。\n誰かとおしゃべりしたいな…",
  ui_story_1013_10131302_108_dialog_content = "今日はあたしの誕生日なの。",
  ui_story_1013_10131302_109_dialog_content = "今度は本当だよ。",
  ui_story_1013_10131302_110_dialog_content = "誰でもいいから、話し相手になってよ…",
  ui_story_1013_10131302_111_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_112_dialog_content = "217号おじさん、しばらく話してないよね。",
  ui_story_1013_10131302_113_dialog_content = "帰れるって言ってたの、ウソじゃないよね…？",
  ui_story_1013_10131302_114_dialog_content = "982号のバカ、せっかく書いてあげた詩、要らないの？",
  ui_story_1013_10131302_115_dialog_content = "79号姉さん、いつになったら端末を見てくれるの…？",
  ui_story_1013_10131302_116_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131302_117_dialog_content = "ぐすっ…誰も答えてくれない…",
  ui_story_1013_10131302_118_dialog_content = "もうっ！記録に残ってるの、全部あたしじゃない！",
  ui_story_1013_10131302_119_dialog_content = "これじゃ、あたしが嫌われ者みたいでしょ！？",
  ui_story_1013_10131302_120_dialog_content = "イヤ、このままなんてイヤだよ…",
  ui_story_1013_10131302_121_dialog_content = "そうだ！",
  ui_story_1013_10131302_122_dialog_content = "命令、巨像の状態をチェック！",
  ui_story_1013_10131302_123_dialog_content = "巨像217号、状態良好、異常なし。",
  ui_story_1013_10131302_124_dialog_content = "巨像982号、状態良好、異常なし。",
  ui_story_1013_10131302_125_dialog_content = "巨像79号、状態良好、異常なし。",
  ui_story_1013_10131302_126_dialog_content = "巨像35号、状態良好、異常なし。",
  ui_story_1013_10131302_127_dialog_content = "アハハ、いい感じ！\nこれで静かじゃなくなったわ！",
  ui_story_1013_10131401_1_dialog_content = "ふぅ、終わった…",
  ui_story_1013_10131401_2_dialog_content = "胸がしめつけられる…\n何とも言えない気持ちだよ。",
  ui_story_1013_10131401_3_dialog_content = "1号は理解できません。",
  ui_story_1013_10131401_4_dialog_content = "言語分析によれば、ただいまの会話は日常生活です。\n「胸がしめつけられる」という感情と適合しません。",
  ui_story_1013_10131401_5_dialog_content = "でも、記録の中に出てくる人がどんどん減ってたでしょ。",
  ui_story_1013_10131401_6_dialog_content = "最後は1人だけだった。",
  ui_story_1013_10131401_7_dialog_content = "僕にはこの空の末裔たちの気持ち、分かる気がするんだ。",
  ui_story_1013_10131401_8_dialog_content = "何もない毎日を繰り返して、\n誰にも聞いてもらえない声を上げ続ける…",
  ui_story_1013_10131401_9_dialog_content = "ほんの少しでいいから、何か反響が帰ってきて、\n生活に波が起こることだけを願いながら…",
  ui_story_1013_10131401_10_dialog_content = "…でも最後には結局、そんな簡単な願いごとさえ\n叶わないまま終わるんだ。",
  ui_story_1013_10131401_11_dialog_content = "理解しました。\n会話の人数と密度に注目していたのですね。",
  ui_story_1013_10131401_12_dialog_content = "1号は、そのような感情の分析方法を記録しました。",
  ui_story_1013_10131401_13_dialog_content = "人数と密度…そうかもね。\nうまく説明できないけど…",
  ui_story_1013_10131401_14_dialog_content = "僕はただ、誰かと交流したいっていう、\n強くて行き場のない願いを感じたんだ。",
  ui_story_1013_10131401_15_dialog_content = "それがさっき言った「胸がしめつけられる」ってことだよ。\n僕は、怖いとさえ思った。",
  ui_story_1013_10131401_16_dialog_content = "怖い。\n彼らと同じ環境に置かれることに恐怖を感じるのですか？",
  ui_story_1013_10131401_17_dialog_content = "うん。\nでも実は、もう同じような経験をしてるんだ。",
  ui_story_1013_10131401_18_dialog_content = "ちょっと前まで、地下で17年間、\n1人で暮らしてたことがあるんだ。",
  ui_story_1013_10131401_19_dialog_content = "この人たちと比べたら、\n17年は長いのかな？短いのかな？",
  ui_story_1013_10131401_20_dialog_content = "でも、あの頃の僕が感じてた胸の苦しさは、\nここまで絶望的じゃなかった。",
  ui_story_1013_10131401_21_dialog_content = "たぶん、ソラヴァンがいてくれたからだね。\nいつもそばに居てくれたんだ。",
  ui_story_1013_10131401_22_dialog_content = "…そういえば、この人たちも巨像と一緒にいるはずだよね。",
  ui_story_1013_10131401_23_dialog_content = "でも、この人たちの巨像は、\n会話できるような人格がないみたいだ。",
  ui_story_1013_10131401_24_dialog_content = "機械的な応答だけじゃ、\n孤独は癒やせなかったんだろうね。",
  ui_story_1013_10131401_25_dialog_content = "<color=#e8d9bb>ウオーン――</color>",
  ui_story_1013_10131401_26_dialog_content = "え？どうしたの？",
  ui_story_1013_10131401_27_dialog_content = "1号、また時間を早送りしてるの？",
  ui_story_1013_10131401_28_dialog_content = "1号はいかなる操作も行っていません。",
  ui_story_1013_10131401_29_dialog_content = "じゃあ、今のは…",
  ui_story_1013_10131401_30_dialog_content = "と、止まった…",
  ui_story_1013_10131401_31_dialog_content = "1号とあなたはデータの順列通り、\nソラヴァンに保存されていたデータを閲覧していました。",
  ui_story_1013_10131401_32_dialog_content = "今のような現象が起こったのは、\nデータそのものに問題があるからだと考えられます。",
  ui_story_1013_10131401_33_dialog_content = "故障ってこと！？",
  ui_story_1013_10131401_34_dialog_content = "特異な状況です。\nチェックの結果によると、データの削除によるものではありません。",
  ui_story_1013_10131401_35_dialog_content = "また、データベースの中に、\n類似する故障の記録は見つかりませんでした。",
  ui_story_1013_10131401_36_dialog_content = "え？君でも分からないの？",
  ui_story_1013_10131401_37_dialog_content = "特異な状況です。\nこれは故障ではなく、何らかの現象の可能性があります。",
  ui_story_1013_10131401_38_dialog_content = "現象？",
  ui_story_1013_10131401_39_dialog_content = "そうです。1号は機械と関連性の低いデータを検索し、\n類似する情報を見つけました。",
  ui_story_1013_10131401_40_dialog_content = "現在のデータ形式の状況は、\n生物の大脳で発生する「忘却」と呼ばれる現象と非常に類似しています。",
  ui_story_1013_10131401_41_dialog_content = "忘却？つまり、ソラヴァンが記憶の一部を忘れてしまって、\n僕たちもその部分の時間をスキップされたってこと？",
  ui_story_1013_10131401_42_dialog_content = "「忘却」が発生する可能性があるのであれば、\nそのように推測するのが合理的です。",
  ui_story_1013_10131401_43_dialog_content = "しかし、「忘却」が機械に発生することは既存のロジックと合致しません。\n機械の記憶回路はより厳密にデータの保存と削除を行います。",
  ui_story_1013_10131401_44_dialog_content = "いや、それで正しいんだよ！\nだって、ソラヴァンは機械じゃない！",
  ui_story_1013_10131401_45_dialog_content = "1号、もう一度端末を見せて！",
  ui_story_1013_10131401_46_dialog_content = "時間が流れてたのなら、\n端末の中の内容も更新されてるはずでしょ。",
  ui_story_1013_10131401_47_dialog_content = "了解しました。少々お待ちください。",
  ui_story_1013_10131401_48_dialog_content = "命令、巨像35号、応答して！",
  ui_story_1013_10131401_49_dialog_content = "巨像35号、待機中。\n命令をどうぞ。",
  ui_story_1013_10131401_50_dialog_content = "いいわ！\nこれからお話をしてあげる。",
  ui_story_1013_10131401_51_dialog_content = "出発した日の話よ。",
  ui_story_1013_10131401_52_dialog_content = "あたしは出発前にナビゲーターの資格をとったばかりで、\n初めての飛行だったの。",
  ui_story_1013_10131401_53_dialog_content = "たくさん準備して、どんな問題が起こるかもしれないかとか、\nどう対処するべきかとか、一晩中考えてたわ。",
  ui_story_1013_10131401_54_dialog_content = "スーツケースに、お洋服をたくさん詰めこんだの。\nおこづかいを全部使って買った服よ。",
  ui_story_1013_10131401_55_dialog_content = "一番きれいな服は、帰って来る時に着る用よ。\n伝説の英雄みたいにかっこよく帰還したかったの。",
  ui_story_1013_10131401_56_dialog_content = "でも結局、準備はムダになっちゃった。",
  ui_story_1013_10131401_57_dialog_content = "予想してたようなことは起こらなかったの、1回もね。\nそれどころか、操縦する必要もなくなっちゃった。",
  ui_story_1013_10131401_58_dialog_content = "一番きれいな服も、きれいに畳まれたまま、\nスーツケースの中よ。",
  ui_story_1013_10131401_59_dialog_content = "昨日、ちょっと着てみたの。\nサイズが小さすぎて、着られなかったわ。",
  ui_story_1013_10131401_60_dialog_content = "あーあ、すごくステキな服だったのに…\n35号、聞いてる？",
  ui_story_1013_10131401_61_dialog_content = "命令、巨像35号、返事して！",
  ui_story_1013_10131401_62_dialog_content = "巨像35号、待機中。\n命令をどうぞ。",
  ui_story_1013_10131401_63_dialog_content = "聞いてるならいいのよ。\n次は…",
  ui_story_1013_10131401_64_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131401_65_dialog_content = "命令、巨像982号、応答して！",
  ui_story_1013_10131401_66_dialog_content = "巨像982号、待機中。\n命令をどうぞ。",
  ui_story_1013_10131401_67_dialog_content = "今日はお話を聞かせてあげる。",
  ui_story_1013_10131401_68_dialog_content = "出発した後のことよ。\nみんなは顔も合わせずに、端末で話すことに慣れていったの。",
  ui_story_1013_10131401_69_dialog_content = "みんな自分の乗ってる巨像と同じ番号がついてたから、\n自然と番号で呼び合うようになったの。",
  ui_story_1013_10131401_70_dialog_content = "その時は、番号で呼ぶのがすごく怖かった。\n数字なんて、冷たくて血の通わないものでしょ。",
  ui_story_1013_10131401_71_dialog_content = "だから、あたしは1人でずっと、\n元の名前で呼び続けてたの。",
  ui_story_1013_10131401_72_dialog_content = "どのくらい持ったかな…？\n数か月？それとも1年？もう、覚えてないわ。",
  ui_story_1013_10131401_73_dialog_content = "とにかく、最初の1人の名前を\n忘れるまではがんばったの。",
  ui_story_1013_10131401_74_dialog_content = "忘れちゃったからって、その人だけ番号で呼ぶワケにもいかないでしょ。\nそんなの、失礼だもの。",
  ui_story_1013_10131401_75_dialog_content = "それで仕方なく、1人も全員も同じってことで、\n他のみんなと同じように数字で呼ぶことにしたの。",
  ui_story_1013_10131401_76_dialog_content = "982号は「大人になったな」なんて言ったけど、\n好きでそうなったわけじゃないわ。",
  ui_story_1013_10131401_77_dialog_content = "大人になんか、なりたくなかった。\nみんなの名前も忘れたくなかった。",
  ui_story_1013_10131401_78_dialog_content = "…",
  ui_story_1013_10131401_79_dialog_content = "そうだ、あたしたちに名前があったんだから、\n巨像に名前があってもいいわよね。",
  ui_story_1013_10131401_80_dialog_content = "巨像に名前をつけましょ！\n番号で呼ぶのはやめるわ！",
  ui_story_1013_10131401_81_dialog_content = "まずは982号、あなたからよ。\nそうね…",
  ui_story_1013_10131401_82_dialog_content = "あなたの主人はイジワルだったわ。\nでも、「イジワル」なんて名前、いじめみたいだから…別の言葉にしましょ。",
  ui_story_1013_10131401_83_dialog_content = "そうね…「ローンウルフ」がいいわ！",
  ui_story_1013_10131401_84_dialog_content = "命令、巨像の呼称変更！「巨像982号」は今日から「ローンウルフ」って呼ぶわ！",
  ui_story_1013_10131401_85_dialog_content = "命令を受信、呼称を変更しました。",
  ui_story_1013_10131401_86_dialog_content = "さ、次は217号よ！",
  ui_story_1013_10131401_87_dialog_content = "217号おじさんは、みんなのリーダーで硬い感じだったから、\nあなたの名前は「ガイダンス」にしましょ！",
  ui_story_1013_10131401_88_dialog_content = "命令、巨像の呼称変更、「巨像217号」を「ガイダンス」に変えるわ！",
  ui_story_1013_10131401_89_dialog_content = "命令を受信、呼称を変更しました。",
  ui_story_1013_10131401_90_dialog_content = "次は79号姉さんね。姉さんは優しくてデリケートな人だったから、\n巨像にもきれいな名前をつけてあげなくちゃ！",
  ui_story_1013_10131401_91_dialog_content = "きれいな名前…きれいな名前…",
  ui_story_1013_10131401_92_dialog_content = "35号、私のことを呼んだ？",
  ui_story_1013_10131401_93_dialog_content = "あ、79号姉さん！？\nやっと端末を見てくれたのね！",
  ui_story_1013_10131401_94_dialog_content = "35号、すごいわね。\n1人でこんなににぎやかにおしゃべりしてたなんて。",
  ui_story_1013_10131401_95_dialog_content = "えへへ、今、みんなの巨像に名前をつけてたの。",
  ui_story_1013_10131401_96_dialog_content = "巨像に名前を？面白いわね、あなたらしいわ。",
  ui_story_1013_10131401_97_dialog_content = "そう、おもしろいの！\n全部の巨像に名前をつけるつもりよ。",
  ui_story_1013_10131401_98_dialog_content = "あら、それは大変ね。\n巨像はたくさんあるのよ。",
  ui_story_1013_10131401_99_dialog_content = "アハハ、79号姉さんだって分かってるでしょ。\n時間だけはたくさんあるんだから！",
  ui_story_1013_10131401_100_dialog_content = "確かに、そうね。",
  ui_story_1013_10131401_101_dialog_content = "ちょうど今、79号姉さんの巨像の名前を考えてたところなの。\n姉さんは、何かいいアイデアある？",
  ui_story_1013_10131401_102_dialog_content = "実はね…35号。\n今日はお願いしたいことがあるの。",
  ui_story_1013_10131401_103_dialog_content = "お願い？あたしでも、何か役に立てるの！？",
  ui_story_1013_10131401_104_dialog_content = "ええ。",
  ui_story_1013_10131401_105_dialog_content = "私に…詩を作って。",
  ui_story_1013_10131401_106_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131401_107_dialog_content = "35号、お願いできる？",
  ui_story_1013_10131401_108_dialog_content = "<color=#e8d9bb>ウオーン――</color>",
  ui_story_1013_10131401_109_dialog_content = "どうしたの？まだ見終わってないよ！？",
  ui_story_1013_10131401_110_dialog_content = "また！？",
  ui_story_1013_10131401_111_dialog_content = "このエリアのデータは密度が低く、分散しています。",
  ui_story_1013_10131401_112_dialog_content = "もう少し分かりやすく言ってもらえる？",
  ui_story_1013_10131401_113_dialog_content = "この時期の記憶が少ないという意味です。",
  ui_story_1013_10131401_114_dialog_content = "それもそうなのかな…巨像にとっては\n覚えておくようなことが特に起こってないんだろうから。",
  ui_story_1013_10131401_115_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_1013_10131401_116_dialog_content = "うわっ！びっくりした！",
  ui_story_1013_10131401_117_dialog_content = "何の音？",
  ui_story_1013_10131401_118_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_1013_10131401_119_dialog_content = "船室のドアに、何かが衝突しています。",
  ui_story_1013_10131401_120_dialog_content = "衝突？前は誰もいなかったよね。",
  ui_story_1013_10131401_121_dialog_content = "待って、まさか…",
  ui_story_1013_10131401_122_dialog_content = "分析の結果、\n異常データに到達したと判明しました。",
  ui_story_1013_10131401_123_dialog_content = "<color=#e8d9bb>バン！！</color>",
  ui_story_1013_10131401_124_dialog_content = "もう少し早く教えてくれない！？\n僕にも準備ってものがあるよ！",
  ui_story_1013_10131401_125_dialog_content = "でも…待って。暗鬼じゃないみたいだ。\n何だろう？",
  ui_story_1013_10131401_126_dialog_content = "…",
  ui_story_1013_10131401_127_dialog_content = "これって…花？船室の床に生えてたの？",
  ui_story_1013_10131401_128_dialog_content = "今度は君に言われなくても分かるよ。\nこれが異常なデータだね？",
  ui_story_1013_10131401_129_dialog_content = "その通りです。ですが、1号は理解できません。\nどうしてそう判断できたのですか？",
  ui_story_1013_10131401_130_dialog_content = "だって、おかしいでしょ？\nこんなところに花が咲くなんて。",
  ui_story_1013_10131401_131_dialog_content = "前に、異常なデータは僕が嫌いな物になって現れるって言ってたよね？\nだったら、これはどういうことだろう？",
  ui_story_1013_10131401_132_dialog_content = "好きとか嫌いとか以前に、\nこんなもの、僕は見たことないよ。",
  ui_story_1013_10131401_133_dialog_content = "解析中…前回、異常データを排除した際の情報が、\n分析された結果と判断します。",
  ui_story_1013_10131401_134_dialog_content = "すなわち…異常データが対応策を講じてきたということです。",
  ui_story_1013_10131401_135_dialog_content = "ソラヴァンの記憶を基に\nデータを集合させ、より攻撃的な状態に変化したと推測されます。",
  ui_story_1013_10131401_136_dialog_content = "それが今、あなたの認識しているものです。",
  ui_story_1013_10131401_137_dialog_content = "攻撃的になった？",
  ui_story_1013_10131401_138_dialog_content = "ソラヴァンの記憶によると\nこの暗鬼は「ディアボラ」と呼ばれる個体です。",
  ui_story_1013_10131401_139_dialog_content = "これが暗鬼？花の姿をした？",
  ui_story_1013_10131401_140_dialog_content = "その通りです。",
  ui_story_1013_10131401_141_dialog_content = "戦いの情報に基づいて、戦い方を変えるなんて…\nそんなことができるんだね。",
  ui_story_1013_10131401_142_dialog_content = "このままだと、何回か戦ったらもう\n太刀打ちできなくなりそうだ。",
  ui_story_1013_10131401_143_dialog_content = "1号、異常なデータはこれで全部なんだね？",
  ui_story_1013_10131401_144_dialog_content = "その通りです。注意してください。\n前回よりもデータ量が膨大です。",
  ui_story_1013_10131401_145_dialog_content = "しかも、攻撃的に特殊な変化を行っています。",
  ui_story_1013_10131401_146_dialog_content = "分かった。",
  ui_story_1013_10131401_147_dialog_content = "僕にどれだけの勝ち目があるか、計算できる？",
  ui_story_1013_10131401_148_dialog_content = "勝率計算…10%。",
  ui_story_1013_10131401_149_dialog_content = "たったそれだけ！？",
  ui_story_1013_10131401_150_dialog_content = "まぁいいや、0じゃなくてよかった。",
  ui_story_1013_10131401_151_dialog_content = "大きな問題ではありません。私たちの目的は異常データの排除です。\n戦闘に勝利する必要はありません。",
  ui_story_1013_10131401_152_dialog_content = "1号も支援を行います。",
  ui_story_1013_10131401_153_dialog_content = "君から応援してもらえるとは思ってなかったよ。\nでも、それなら安心だ。",
  ui_story_1013_10131401_154_dialog_content = "でも、勝率10%っていうのは、\nやっぱりいい気分じゃないね。",
  ui_story_1013_10131401_155_dialog_content = "確か君って、計算を\nいつも最適化してるって言ってたね？",
  ui_story_1013_10131401_156_dialog_content = "その通りです。",
  ui_story_1013_10131401_157_dialog_content = "だったら、よく見てて。\n僕がその計算、変えてみせるよ！",
  ui_story_1013_10131402_1_dialog_content = "正面からの攻撃を回避してください。",
  ui_story_1013_10131402_2_dialog_content = "分かってるって！\n僕も避けるぐらいはできるよ。",
  ui_story_1013_10131402_3_dialog_content = "次は力を集中して攻撃を行ってください。\n相手の急所を狙ってください。",
  ui_story_1013_10131402_4_dialog_content = "もう少しゆっくり話せないかな？\n僕にも少し考える時間が欲しいよ。",
  ui_story_1013_10131402_5_dialog_content = "急所……こいつの急所は…",
  ui_story_1013_10131402_6_dialog_content = "1号は、絶好の攻撃のチャンスが到来すると予測しました。",
  ui_story_1013_10131402_7_dialog_content = "あと3秒…",
  ui_story_1013_10131402_8_dialog_content = "分かったよ！秒読みされたら焦っちゃうよ！",
  ui_story_1013_10131402_9_dialog_content = "集中するんだ…これで最後！",
  ui_story_1013_10131402_10_dialog_content = "ガサガサ…",
  ui_story_1013_10131402_11_dialog_content = "狙いを定めて…",
  ui_story_1013_10131402_12_dialog_content = "今だ！！！",
  ui_story_1013_10131402_13_dialog_content = "ガサ…",
  ui_story_1013_10131402_14_dialog_content = "やった！消えた！",
  ui_story_1013_10131402_15_dialog_content = "ソラヴァンのデータ状況をチェックします。",
  ui_story_1013_10131402_16_dialog_content = "すべてのノードをチェック。\n異常は見つかりませんでした。",
  ui_story_1013_10131402_17_dialog_content = "1号は、ソラヴァン内部の異常データが\nすべて排除されたと判断します。",
  ui_story_1013_10131402_18_dialog_content = "直ったってことだね？",
  ui_story_1013_10131402_19_dialog_content = "じゃあ、ソラヴァンが目覚める？",
  ui_story_1013_10131402_20_dialog_content = "故障を引き起こしていた要素はすべて排除されました。\n現在、ソラヴァンのシステムは健全な状態です。",
  ui_story_1013_10131402_21_dialog_content = "ソラヴァンのすべての機能が回復しました。",
  ui_story_1013_10131402_22_dialog_content = "ただし、あなたの言う「目覚める」…\nつまり、人格が回復するかどうかについて、1号は断言できません。",
  ui_story_1013_10131402_23_dialog_content = "えっ？",
  ui_story_1013_10131402_24_dialog_content = "ソラヴァンに人格が存在する現象は、\n1号の理解能力を超えています。",
  ui_story_1013_10131402_25_dialog_content = "したがって、1号にはそのシステムが\n元通りに復元されるか判断できません。",
  ui_story_1013_10131402_26_dialog_content = "実際の状況は、ソラヴァンのデータ保存空間を離れた後、\n実験で検証することが可能でしょう。",
  ui_story_1013_10131402_27_dialog_content = "そうなんだ…",
  ui_story_1013_10131402_28_dialog_content = "ここで実行するべきタスクは、すべて終了しました。",
  ui_story_1013_10131402_29_dialog_content = "現実に戻り、ソラヴァンの状況をチェックすることができます。",
  ui_story_1013_10131402_30_dialog_content = "データ空間から退出しますか？",
  ui_story_1013_10131402_31_dialog_content = "ここを離れる？そうだなぁ…",
  ui_story_1013_10131402_32_dialog_content = "少し待ってくれるかな？\n端末をもう少し見てみたいんだ。",
  ui_story_1013_10131402_33_dialog_content = "空の末裔たちのことが、ちょっと気になるんだ。",
  ui_story_1013_10131402_34_dialog_content = "あの人たちの物語が、いったいどこで終わってるのか…",
  ui_story_1013_10131402_35_dialog_content = "了解しました。データ空間に引き続き留まっても、\nソラヴァンに悪影響をおよぼすことはありません。",
  ui_story_1013_10131402_36_dialog_content = "安心して調査を行ってください。\n1号は端末データを出力します。",
  ui_story_1013_10131402_37_dialog_content = "うん、ありがとう、1号。",
  ui_story_1013_10131402_38_dialog_content = "ここまでずっと、本当にありがとう。",
  ui_story_1013_10131402_39_dialog_content = "命令、「ローンウルフ」の記録した座標から、\n「ガイダンス」の記録した座標まで、最大速度で移動。",
  ui_story_1013_10131402_40_dialog_content = "命令対象：「グリード」、「ソラヴァン」。",
  ui_story_1013_10131402_41_dialog_content = "命令は3秒後より有効。",
  ui_story_1013_10131402_42_dialog_content = "3、2、1…開始！",
  ui_story_1013_10131402_43_dialog_content = "状況報告。ソラヴァン、命令を完了しました。",
  ui_story_1013_10131402_44_dialog_content = "状況報告。グリード、命令を完了しました。",
  ui_story_1013_10131402_45_dialog_content = "おやおや…またソラヴァンの方が早かったようだね。",
  ui_story_1013_10131402_46_dialog_content = "いつも同じ結果じゃ、つまらないねぇ。",
  ui_story_1013_10131402_47_dialog_content = "次は折り返しを試してみようかね。\nグリード、がんばるんだよ。",
  ui_story_1013_10131402_48_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131402_49_dialog_content = "命令、「ローンウルフ」、食料の備蓄数を報告。",
  ui_story_1013_10131402_50_dialog_content = "缶詰1号：152、缶詰2号：73、缶詰3号…",
  ui_story_1013_10131402_51_dialog_content = "命令、「ガイダンス」は「ローンウルフ」の報告を記録。",
  ui_story_1013_10131402_52_dialog_content = "記録しています。「ローンウルフ」の残存食料数、缶詰1番：152…",
  ui_story_1013_10131402_53_dialog_content = "それでいい。お前たち、たくさん交流するんだよ。",
  ui_story_1013_10131402_54_dialog_content = "あたしばっかりじゃなく、\n巨像同士でもちゃんと仲良くしないとね。",
  ui_story_1013_10131402_55_dialog_content = "ガイダンス、お前もローンウルフに話しかけてあげなさい。",
  ui_story_1013_10131402_56_dialog_content = "命令、「ガイダンス」、食料の備蓄数を報告。",
  ui_story_1013_10131402_57_dialog_content = "缶詰1番…",
  ui_story_1013_10131402_58_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131402_59_dialog_content = "キュート、また寝る前のお話の時間になったよ。",
  ui_story_1013_10131402_60_dialog_content = "命令、「キュート」、会話の内容を記録。",
  ui_story_1013_10131402_61_dialog_content = "会話内容の記録を開始します。",
  ui_story_1013_10131402_62_dialog_content = "昨日はどこまで話したっけね？\nごめんよ、最近は記憶力が衰えてしまってね。",
  ui_story_1013_10131402_63_dialog_content = "お前に名前をつけてやったところまでだったかね。",
  ui_story_1013_10131402_64_dialog_content = "他の巨像にみんな名前をつけ終わった後で、\nあたしはお前の名前を考え始めたんだ。",
  ui_story_1013_10131402_65_dialog_content = "とりわけ特別な名前をつけてやりたかったのさ。\nなにしろ、お前は他の巨像とは違う…",
  ui_story_1013_10131402_66_dialog_content = "あたしの巨像だから。",
  ui_story_1013_10131402_67_dialog_content = "ずいぶん長い間考えたんだよ。\nでも、いくら考えても、お前にふさわしい、特別な言葉が見つからなかった…",
  ui_story_1013_10131402_68_dialog_content = "「キュート」に名前をつけるという内容は、\n昨日すでに記録しています。",
  ui_story_1013_10131402_69_dialog_content = "おや、記録してあったかい。\nすまないね、また忘れてしまったよ。",
  ui_story_1013_10131402_70_dialog_content = "名前をつけるところまで、話し終わっていたのかい。\nそれなら、次は何を話そうか…そうだねぇ…",
  ui_story_1013_10131402_71_dialog_content = "待って。",
  ui_story_1013_10131402_72_dialog_content = "待っておくれ！",
  ui_story_1013_10131402_73_dialog_content = "今、あたしは「命令」を入力したかい！？",
  ui_story_1013_10131402_74_dialog_content = "ちょっと確認させとくれ…",
  ui_story_1013_10131402_75_dialog_content = "…いや、してない！\n「命令」は入力してないね！",
  ui_story_1013_10131402_76_dialog_content = "キュート！命令は入力してないのに、\nどうして答えてくれたんだい？",
  ui_story_1013_10131402_77_dialog_content = "あたしの言っていることが、\n分かったんだね？そうなんだね！？",
  ui_story_1013_10131402_78_dialog_content = "キュート、答えておくれ。\n答えられるんだろう！？",
  ui_story_1013_10131402_79_dialog_content = "重複する内容を検知しました。",
  ui_story_1013_10131402_80_dialog_content = "キュートは新しい内容の記録を希望します。",
  ui_story_1013_10131402_81_dialog_content = "この記録は…",
  ui_story_1013_10131402_82_dialog_content = "会話してるうちに、巨像に変化が起こったってこと？",
  ui_story_1013_10131402_83_dialog_content = "機械的な応答が、自我の意識をもった応答に変わったみたいな…",
  ui_story_1013_10131402_84_dialog_content = "ソラヴァンの名前も出てきてる。\nソラヴァンもこの頃に人格を持つようになったのかな？",
  ui_story_1013_10131402_85_dialog_content = "1号はこの変化を理解できません。",
  ui_story_1013_10131402_86_dialog_content = "記録内容に基づけば、\n巨像に複雑な知能システムは搭載されていません。",
  ui_story_1013_10131402_87_dialog_content = "そのような条件下で、\n巨像がいわゆる「人格」をもつ可能性はありません。",
  ui_story_1013_10131402_88_dialog_content = "でも、君も今の会話記録を見たでしょ？",
  ui_story_1013_10131402_89_dialog_content = "巨像が自分から「やりたいこと」を言ったんだよ。",
  ui_story_1013_10131402_90_dialog_content = "はい。人格を持たないロジック回路は\nそのような会話を行いません。",
  ui_story_1013_10131402_91_dialog_content = "1号は、巨像が自我意識をもったという結論を承認します。\nしかし、その過程を理解できません。",
  ui_story_1013_10131402_92_dialog_content = "もう少し先を見てみよう。まだ記録があるみたいだ。",
  ui_story_1013_10131402_93_dialog_content = "ローンウルフ、何か面白い話をしておくれ。",
  ui_story_1013_10131402_94_dialog_content = "ちゃんと笑わせておくれよ？",
  ui_story_1013_10131402_95_dialog_content = "「笑い」に関連する言葉を検索しています…",
  ui_story_1013_10131402_96_dialog_content = "「キュートが故障により停止した。\nしかし、しばらくしてまた飛行し始めた」",
  ui_story_1013_10131402_97_dialog_content = "「乗客たちがどうしたのだとたずねると、キュートは…\n何でもないわ、操縦する勇気のある空の末裔に交代しただけ、と答えた」",
  ui_story_1013_10131402_98_dialog_content = "アハハハハ…",
  ui_story_1013_10131402_99_dialog_content = "面白いね、とても面白いよ。",
  ui_story_1013_10131402_100_dialog_content = "異議を申し立てます。ローンウルフは今の話を何度もしています。\n内容が重複しています。",
  ui_story_1013_10131402_101_dialog_content = "そうかい？すまないね、よく覚えてないんだ。",
  ui_story_1013_10131402_102_dialog_content = "本当に面白かったけど、ローンウルフ。\n今度から、同じ話はしちゃいけないよ。",
  ui_story_1013_10131402_103_dialog_content = "創造力を鍛えないとね。",
  ui_story_1013_10131402_104_dialog_content = "面白い話に、歌に…\nそれから、詩も作れるようにならなきゃいけないよ。",
  ui_story_1013_10131402_105_dialog_content = "この世界の美しいものを全部、学ぶんだ。",
  ui_story_1013_10131402_106_dialog_content = "了解しました。\nローンウルフは重複情報の比重調整を行います。",
  ui_story_1013_10131402_107_dialog_content = "じゃあ、さっきのは無かったことにして、\nもう一度面白い話を聞かせておくれ。",
  ui_story_1013_10131402_108_dialog_content = "さっきと同じだよ。\nちゃんと笑わせておくれよ？",
  ui_story_1013_10131402_109_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131402_110_dialog_content = "ガイダンスの推薦する候補は「カンヅメ」です。",
  ui_story_1013_10131402_111_dialog_content = "ダメだね。\nぜんぜん響きが良くないよ。",
  ui_story_1013_10131402_112_dialog_content = "グリードの推薦する候補は「グリード」です。",
  ui_story_1013_10131402_113_dialog_content = "手抜きにも程があるってもんだよ。\n自分の名前を薦めてどうするんだい？",
  ui_story_1013_10131402_114_dialog_content = "ソラヴァンの推薦する候補は「ソラソラ」です。",
  ui_story_1013_10131402_115_dialog_content = "ううん、ソラヴァン…\nお前に名前を考えさせるのはまだ早かったかね。",
  ui_story_1013_10131402_116_dialog_content = "まったく、あたしはお前たちにいい名前をつけてやったって言うのに、\nあたしの名前を考えさせるとなったら、ひどい有り様だね。",
  ui_story_1013_10131402_117_dialog_content = "仕方ない、やっぱりこのまま35号でいようかね。",
  ui_story_1013_10131402_118_dialog_content = "みんなの名前を忘れてしまったんだ。\n最後に自分の名前を忘れたって、おかしくもないよ。",
  ui_story_1013_10131402_119_dialog_content = "そうだ、その方が公平ってもんだね。",
  ui_story_1013_10131402_120_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131402_121_dialog_content = "キュート、寝る前のお話の時間だよ。",
  ui_story_1013_10131402_122_dialog_content = "キュート、了解しました。",
  ui_story_1013_10131402_123_dialog_content = "前回は、35号が出発した日の内容まで話しました。\nそこから話を再開します。",
  ui_story_1013_10131402_124_dialog_content = "35号は出発前にナビゲーターの資格をとったばかりで、\nそれが巨像での初飛行でした。",
  ui_story_1013_10131402_125_dialog_content = "35号はたくさん準備して、一晩中どんな突発的事態が起こりうるか、\nどう対処するべきかを考えていました。",
  ui_story_1013_10131402_126_dialog_content = "35号のスーツケースには洋服がたくさん詰めこまれていました。\nおこづかいをすべて使って買った服です。",
  ui_story_1013_10131402_127_dialog_content = "一番きれいな服は帰航時に着るためのものです。\n35号は伝説の英雄みたいにかっこよく帰還したいと思っていました。",
  ui_story_1013_10131402_128_dialog_content = "はて？そんな服、あったかね…",
  ui_story_1013_10131402_129_dialog_content = "キュート、あたしはうれしいよ。\nお前の話を聞いていると、いつも新しい発見があるね。",
  ui_story_1013_10131402_130_dialog_content = "今日のお話はここまでにしようか。\nその、一番きれいな服とやらを探したくなったよ。",
  ui_story_1013_10131402_131_dialog_content = "「伝説の英雄みたいに」なんて、\nよっぽどすてきな服なんだろうね。",
  ui_story_1013_10131402_132_dialog_content = "巨像たちが本当に人格を持ってる！",
  ui_story_1013_10131402_133_dialog_content = "似たような記録がまだたくさん残ってる…\nこの空の末裔、ずっと巨像と話してたんだ。",
  ui_story_1013_10131402_134_dialog_content = "一過性の事例でないならば、\n偶然や奇跡では説明できません。",
  ui_story_1013_10131402_135_dialog_content = "現在は単なる推測ですが、巨像は空の末裔と共に過ごす中で、\n知能システムを自己生成したと考えられます。",
  ui_story_1013_10131402_136_dialog_content = "自己生成？",
  ui_story_1013_10131402_137_dialog_content = "巨像のシステムには、そもそも学習能力が備わっています。",
  ui_story_1013_10131402_138_dialog_content = "学習能力の目的は自身の判断を最適化し、\nより正しく指令を完了することです。",
  ui_story_1013_10131402_139_dialog_content = "この点は1号と類似しています。",
  ui_story_1013_10131402_140_dialog_content = "そうだね。君も、いつも自分の行動を最適化してるって言ってた。",
  ui_story_1013_10131402_141_dialog_content = "この種の基本的学習能力は、\n知能と定義するには不足しています。",
  ui_story_1013_10131402_142_dialog_content = "しかし、現在観測した結果から推測すると、\n空の末裔が巨像の学習能力を誘導したことで、知能が発生したと考えられます。",
  ui_story_1013_10131402_143_dialog_content = "誘導？どうやって？",
  ui_story_1013_10131402_144_dialog_content = "あなたが見た通りの内容です。\n端末に記録されていた会話が誘導の過程です。",
  ui_story_1013_10131402_145_dialog_content = "つまり、巨像と話をし続けたってこと？",
  ui_story_1013_10131402_146_dialog_content = "はい。空の末裔は会話機能のない命令ポートを使用し、\n巨像と会話を続けました。",
  ui_story_1013_10131402_147_dialog_content = "その過程で、巨像が徐々に行動を学習し始めたのです。",
  ui_story_1013_10131402_148_dialog_content = "このような学習過程は非常にゆっくりとしたものです。\n1号の計算では、効果を発揮する可能性はありません。",
  ui_story_1013_10131402_149_dialog_content = "しかし事実は計算に反し、巨像が知能を有しています。",
  ui_story_1013_10131402_150_dialog_content = "たぶん、この空の末裔が本当に長い間、\n話し続けたからなんだろうね。",
  ui_story_1013_10131402_151_dialog_content = "機械と話すことに自分の全てをかける人なんて、そうそういない…",
  ui_story_1013_10131402_152_dialog_content = "…あ、ごめん。\n僕まで巨像を機械なんて言っちゃった。",
  ui_story_1013_10131402_153_dialog_content = "でも、少なくとも人格ができる前は、\n機械って呼んだ方が理にかなってるね。",
  ui_story_1013_10131402_154_dialog_content = "毎日、何年間も機械に話し続けるなんて、\n普通は考えられないよ。",
  ui_story_1013_10131402_155_dialog_content = "でも、その考えられない行動が、\nこの空の末裔の人生の全てだったんだ…",
  ui_story_1013_10131402_156_dialog_content = "あなたの言ったことはロジックに一致します。\nこの会話の量は、1号の想定をはるかに超えています。",
  ui_story_1013_10131402_157_dialog_content = "学習速度が低速であっても、膨大なデータがあれば、\n十分な知能の生成の基礎とすることは可能です。",
  ui_story_1013_10131402_158_dialog_content = "この現象は奇跡ではなく、\n一種の必然だと表現できます。",
  ui_story_1013_10131402_159_dialog_content = "いや、奇跡だよ…\nこの空の末裔こそが、奇跡なんだ。",
  ui_story_1013_10131402_160_dialog_content = "彼女が不可能を必然に変えたんだ…",
  ui_story_1013_10131402_161_dialog_content = "<color=#e8d9bb>ピッ…</color>",
  ui_story_1013_10131402_162_dialog_content = "何の音？",
  ui_story_1013_10131402_163_dialog_content = "端末が新しいメッセージを受信しました。",
  ui_story_1013_10131402_164_dialog_content = "今？記憶の中なのに？\nリアルタイムでメッセージを受信するなんて、今まで…",
  ui_story_1013_10131402_165_dialog_content = "とにかく、見てみよう――",
  ui_story_1013_10131402_166_dialog_content = "みんな、見ておくれ。",
  ui_story_1013_10131402_167_dialog_content = "ちょっと急な話だけどね…",
  ui_story_1013_10131402_168_dialog_content = "いや、やっぱり、できるだけ簡単に話そうね。",
  ui_story_1013_10131402_169_dialog_content = "みんなに手伝ってほしいことがあるんだ。",
  ui_story_1013_10131402_170_dialog_content = "あたしに1つ、詩を書いてくれないかい？",
  ui_story_1013_10131402_171_dialog_content = "そうだねぇ…「人」の詩がいいね。",
  ui_story_1013_10131402_172_dialog_content = "詩！？まさか…",
  ui_story_1013_10131402_173_dialog_content = "申しわけありません。\nキュートはまだ詩の作り方を学習していません。",
  ui_story_1013_10131402_174_dialog_content = "学習材料となる会話記録が不十分です。",
  ui_story_1013_10131402_175_dialog_content = "いくつか参考資料となる詩を入力してください。",
  ui_story_1013_10131402_176_dialog_content = "キュートは可能な限り早く学習を行い…",
  ui_story_1013_10131402_177_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1013_10131402_178_dialog_content = "…",
  ui_story_1013_10131402_179_dialog_content = "メッセージはここまでです。",
  ui_story_1013_10131402_180_dialog_content = "うん…分かってる。",
  ui_story_1013_10131402_181_dialog_content = "1号は理解できません。\n詩を贈りあうことは、空の末裔の風習ですか？",
  ui_story_1013_10131402_182_dialog_content = "いつの間にかそうなった、\n暗号みたいなものだと思う。",
  ui_story_1013_10131402_183_dialog_content = "もし続いてたら、本当に風習になってたかもしれないね。",
  ui_story_1013_10131402_184_dialog_content = "でも、そんな日はもう来ない…",
  ui_story_1013_10131402_185_dialog_content = "1号には発言の内容が理解できません。",
  ui_story_1013_10131402_186_dialog_content = "1号、時間の流れを速めてもらえる？",
  ui_story_1013_10131402_187_dialog_content = "もっと先を見てみたいんだ。",
  ui_story_1013_10131402_188_dialog_content = "ここにはもう、何もない…",
  ui_story_1013_10131402_189_dialog_content = "了解しました。",
  ui_story_1013_10131402_190_dialog_content = "<color=#e8d9bb>ウオーン――</color>",
  ui_story_1013_10131402_191_dialog_content = "どこで停止しますか？",
  ui_story_1013_10131402_192_dialog_content = "どうしようかな…\n今の時間の流れって、どれくらい速くなってるの？",
  ui_story_1013_10131402_193_dialog_content = "10億倍です。",
  ui_story_1013_10131402_194_dialog_content = "そんなに！？",
  ui_story_1013_10131402_195_dialog_content = "1秒間が通常のおよそ30年にあたる計算です。",
  ui_story_1013_10131402_196_dialog_content = "すごい速さだね。\n僕の17年も一瞬だ。",
  ui_story_1013_10131402_197_dialog_content = "でも、ここに立ってても、\n何も起こらないみたいだけど？",
  ui_story_1013_10131402_198_dialog_content = "はい。端末は新しいメッセージを受信していません。",
  ui_story_1013_10131402_199_dialog_content = "だったら、時間をつぶそう。",
  ui_story_1013_10131402_200_dialog_content = "窓の外の風景を見てみようかな。\nソラヴァンが毎日、どんな景色を見てたのか知りたい。",
  ui_story_1013_10131402_201_dialog_content = "…真っ暗だ。",
  ui_story_1013_10131402_202_dialog_content = "…どれぐらい経ってるんだろう？見るもの、聞くもの、何もかもが繰り返し…\n判断能力も無くなって来た。",
  ui_story_1013_10131402_203_dialog_content = "さっきまで退屈だなって思ってたけど…\n今度は眠くなってきたよ。",
  ui_story_1013_10131402_204_dialog_content = "…眠い…",
  ui_story_1013_10131402_205_dialog_content = "でも、1秒が30年なら、\n目を覚ました時にはどれくらい経ってるんだろう？",
  ui_story_1013_10131402_206_dialog_content = "…ううん、計算が難しいな。\n数学は苦手だよ。",
  ui_story_1013_10131402_207_dialog_content = "仮にちゃんと計算できたとしても、\n結果がウソっぽく思えるほど、とんでもない数字だろうね。",
  ui_story_1013_10131402_208_dialog_content = "この時間の速さなら、\n巨像が自我に目覚めた奇跡だって、ほんの一瞬だ。",
  ui_story_1013_10131402_209_dialog_content = "いや、もう意識という言葉の意味すらないのかも。\n僕自身にも意識があるのか、分からなくなってきた…",
  ui_story_1013_10131402_210_dialog_content = "自分が起きてるのか、眠ってるのか…",
  ui_story_1013_10131402_211_dialog_content = "もう何も分からない…",
  ui_story_1013_10131402_212_dialog_content = "ソラヴァンは、今も眠ってるんだよね？",
  ui_story_1013_10131402_213_dialog_content = "いっそ、ソラヴァンと一緒に眠るのも悪くないかな…",
  ui_story_1013_10131402_214_dialog_content = "<color=#e8d9bb>ピッ…</color>",
  ui_story_1013_10131402_215_dialog_content = "！！！",
  ui_story_1013_10131402_216_dialog_content = "何の音？",
  ui_story_1013_10131402_217_dialog_content = "端末が新しいメッセージを受信しました。",
  ui_story_1013_10131402_218_dialog_content = "今！？そんなことあるの！？",
  ui_story_1013_10131402_219_dialog_content = "どれくらい経ったんだろう？\n何千年？それとも1万年以上経ってる？",
  ui_story_1013_10131402_220_dialog_content = "どうして今になって、メッセージが…",
  ui_story_1013_10131402_221_dialog_content = "急いで、見せて！",
  ui_story_1013_10131402_222_dialog_content = "端末情報を読み込み中…",
  ui_story_1013_10131402_223_dialog_content = "今までとは性質の異なるメッセージです。",
  ui_story_1013_10131402_224_dialog_content = "自動送信のメッセージです。",
  ui_story_1013_10131402_225_dialog_content = "それって…",
  ui_story_1013_10131402_226_dialog_content = "巨像艦隊、帰航せよ。",
  ui_story_1013_10131402_227_dialog_content = "！！！",
  ui_story_1013_10131402_228_dialog_content = "ソラヴァンが動いた！？",
  ui_story_1013_10131402_229_dialog_content = "はい。ソラヴァンは今、\nどこかに向かって高速飛行しています。",
  ui_story_1013_10131402_230_dialog_content = "あなたが速度変化に適応できるよう、\n時間の加速倍率を徐々に調整します。",
  ui_story_1013_10131402_231_dialog_content = "目的地はどこか調べられる？",
  ui_story_1013_10131402_232_dialog_content = "…いや、調べなくて大丈夫そうだ！",
  ui_story_1013_10131402_233_dialog_content = "窓だよ！窓の外を見て！",
  ui_story_1013_10131402_234_dialog_content = "（空に大地、それから太陽。\nずいぶん見てなかった気がする…）",
  ui_story_1013_10131402_235_dialog_content = "（もし時間をさらに10億倍にしたら、何が見えるんだろう？）",
  ui_story_1013_10131402_236_dialog_content = "（でも、こんなに恐ろしいほど長い時間の経過に耐えて、\n再会の喜びを分かち合える人もいない）",
  ui_story_1013_10131402_237_dialog_content = "（あ、そうか。巨像がいた。\n巨像なら感じられるかもしれない）",
  ui_story_1013_10131402_238_dialog_content = "（巨像は空の末裔から奇跡を授けられた。\n何か大切なものを受け継ぐかのように）",
  ui_story_1013_10131402_239_dialog_content = "（その奇跡が人ではなかった魂に、\n人には見ることのできないものを見せてるんだ）",
  ui_story_1013_10131402_240_dialog_content = "（今は何時代だろう？\n今の大陸には、どんな人たちが暮らしてるんだろう？）",
  ui_story_1013_10131402_241_dialog_content = "（今、その人たちは空を見上げて、\n空を覆いつくすような巨像の艦隊を見上げてるんだろうか？）",
  ui_story_1013_10131402_242_dialog_content = "（いにしえの住人が、空から主の最後の子孫を乗せて帰還する）",
  ui_story_1013_10131402_243_dialog_content = "（この旅路がきっと、\n「空の末裔」の名を新しい歴史の中に刻んだんだ）",
  ui_story_1013_10131402_244_dialog_content = "（別々だった2つの時間をつなぎ合わせるように）",
  ui_story_1013_10131402_245_dialog_content = "（遠い昔の約束がついに今、実現する）",
  ui_story_1013_10131402_246_dialog_content = "チェック完了。現在の目的地…天空ノ谷。",
  ui_story_1013_10131501_1_dialog_content = "ふわぁ…やっと終わったみたいね。",
  ui_story_1013_10131501_X1_dialog_content = "僕は…",
  ui_story_1013_10131501_X2_dialog_content = "慌てないで。",
  ui_story_1013_10131501_2_dialog_content = "インゲル、空の末裔の様子を見てあげて。",
  ui_story_1013_10131501_3_dialog_content = "了解しました。",
  ui_story_1013_10131501_4_dialog_content = "ガーディアン1号、接続の結果を報告して。",
  ui_story_1013_10131501_5_dialog_content = "予想以上に時間がかかったじゃない。\nそれ相応の収穫があったのよね？",
  ui_story_1013_10131501_6_dialog_content = "1号は、空の末裔に関わる十分な資料を収集しました。",
  ui_story_1013_10131501_7_dialog_content = "生体的な空の末裔の価値観、思考モデル、情緒曲線のほか…",
  ui_story_1013_10131501_8_dialog_content = "古代の空の末裔の歴史経過も含まれています。",
  ui_story_1013_10131501_9_dialog_content = "歴史経過？",
  ui_story_1013_10131501_10_dialog_content = "ソラヴァンの記憶から推測する限り、\n空の末裔の一族は歴史上の未知の時点で、巨像に乗って大陸を離れました。",
  ui_story_1013_10131501_11_dialog_content = "その後、非常に長い時を経て、\n再びアストラ大陸に戻ってきました。",
  ui_story_1013_10131501_12_dialog_content = "帰航時の目的地は天空ノ谷でした。",
  ui_story_1013_10131501_13_dialog_content = "巨像に乗って大陸から離れた？\nなるほどね…",
  ui_story_1013_10131501_14_dialog_content = "きっとそれが文明崩壊の起こった時期だわ。\n間違いない！",
  ui_story_1013_10131501_15_dialog_content = "これまでの研究では、空の末裔の文明が存続した理由が、\nずっと空白のままだった…",
  ui_story_1013_10131501_16_dialog_content = "巨像が大陸を離れて航行していたという記録が、\nその歴史の空白を埋めるかもしれないわ！",
  ui_story_1013_10131501_17_dialog_content = "まあまあ、分かったわ。\nガーディアン1号、後でバレットに個別に今の内容を報告してあげて。",
  ui_story_1013_10131501_18_dialog_content = "それから？ほかに収穫は？",
  ui_story_1013_10131501_19_dialog_content = "そのほか、1号はPlayerNameを手伝い、\nソラヴァンのデータ故障を解決しました。",
  ui_story_1013_10131501_20_dialog_content = "え？",
  ui_story_1013_10131501_21_dialog_content = "あなたが…人助けを？",
  ui_story_1013_10131501_22_dialog_content = "PlayerName、大丈夫ですか？",
  ui_story_1013_10131501_23_dialog_content = "接続を解除してしばらくは、体調不良を起こすおそれがあります。\nすぐに収まりますので、緊張しないでください。",
  ui_story_1013_10131501_24_dialog_content = "大丈夫、どこも具合の悪いところはないよ。",
  ui_story_1013_10131501_25_dialog_content = "どうだったのだ？ずいぶん時間がかかっていたようだ。\n何を経験してきた？",
  ui_story_1013_10131501_26_dialog_content = "そうですね…",
  ui_story_1013_10131501_27_dialog_content = "戦場シミュレーションの中で崩壊していく世界を通って、\nソラヴァンの記憶の中に入りました…",
  ui_story_1013_10131501_28_dialog_content = "あ、そうだ！！\nソラヴァン！ソラヴァンの故障を直したんだ！",
  ui_story_1013_10131501_29_dialog_content = "ソラヴァンが意識を回復したか、\n先に試してもいいですか？",
  ui_story_1013_10131501_30_dialog_content = "ソラヴァンの故障を？\nそれは予想外の収穫だったな。",
  ui_story_1013_10131501_31_dialog_content = "よし、すぐに手配する。",
  ui_story_1013_10131501_32_dialog_content = "<color=#e8d9bb>「メインシステム：起動」</color>",
  ui_story_1013_10131501_33_dialog_content = "<color=#e8d9bb>「生物モジュール：起動」</color>",
  ui_story_1013_10131501_34_dialog_content = "<color=#e8d9bb>「生命維持システム：起動」</color>",
  ui_story_1013_10131501_35_dialog_content = "<color=#e8d9bb>「エンジン起動中――」</color>",
  ui_story_1013_10131501_36_dialog_content = "<color=#e8d9bb>「16%…33%…」</color>",
  ui_story_1013_10131501_37_dialog_content = "<color=#e8d9bb>「89%…97%…」</color>",
  ui_story_1013_10131501_38_dialog_content = "<color=#e8d9bb>「100%――起動成功――」</color>",
  ui_story_1013_10131501_39_dialog_content = "ソラヴァン！聞こえる？",
  ui_story_1013_10131501_40_dialog_content = "…ソラヴァン！",
  ui_story_1013_10131501_41_dialog_content = "…",
  ui_story_1013_10131501_42_dialog_content = "ど、どうして反応がないんだろう…？",
  ui_story_1013_10131501_43_dialog_content = "ガーディアン1号、もう一度ソラヴァンの状態をチェックして。",
  ui_story_1013_10131501_44_dialog_content = "確認しました。ソラヴァンにデータ異常は見つかりません。\nすべての機能が正常です。",
  ui_story_1013_10131501_45_dialog_content = "やっぱりね。",
  ui_story_1013_10131501_46_dialog_content = "空の末裔くん、ガーディアン1号の報告は聞いたわ。",
  ui_story_1013_10131501_47_dialog_content = "厳密な検証を経た見解ではないけど、\nあたしの推測、聞きたい？",
  ui_story_1013_10131501_48_dialog_content = "はい、聞かせてください。",
  ui_story_1013_10131501_49_dialog_content = "ガーディアン1号の報告によれば、\n巨像が知能を獲得したのは仕様の想定外の現象よね。",
  ui_story_1013_10131501_50_dialog_content = "だから、知能は巨像のデータ体系の中で検知できないんだと思うわ。",
  ui_story_1013_10131501_51_dialog_content = "一番簡単な例で言うと…ソラヴァンが意識を失った後も、\n巨像の機能は普通に使えてたんでしょ？",
  ui_story_1013_10131501_52_dialog_content = "そうです。話ができなくなった以外は正常でした。",
  ui_story_1013_10131501_53_dialog_content = "それはつまり、\n巨像の知能はシステムの保護を受けてない可能性が高いってこと。",
  ui_story_1013_10131501_54_dialog_content = "巨像は知能の状態をセルフチェックできず、\nその故障を修復することもできない。",
  ui_story_1013_10131501_55_dialog_content = "つまり、そもそもシステムの中に無いデータだから、\nエラーが出ようと削除されようと、システム全体には無関係ってことよ。",
  ui_story_1013_10131501_56_dialog_content = "だから、こうなってるの。\n巨像の全ては正常、でも意識は回復しない。",
  ui_story_1013_10131501_57_dialog_content = "むしろ、人格をもたない今の状態こそ、\n巨像にとって正常な状態だと言えるのよ。",
  ui_story_1013_10131501_58_dialog_content = "そんな…",
  ui_story_1013_10131501_59_dialog_content = "つまり、僕が何をしようと、\n意味が無いってことですか！？",
  ui_story_1013_10131501_60_dialog_content = "いくら修復しても、ソラヴァンの意識は戻らない…\nそもそもが想定外で起こったことだから、仕方ないってことですか！？",
  ui_story_1013_10131501_61_dialog_content = "今のところ、そういう結論になるわね。",
  ui_story_1013_10131501_62_dialog_content = "ただ、ソラヴァンの意識を回復する方法、\nまったくアテが無いってワケじゃないわ。",
  ui_story_1013_10131501_63_dialog_content = "ほ、方法が、有るんですね！？",
  ui_story_1013_10131501_64_dialog_content = "一番簡単に思いつくのは…\n昔の空の末裔がしたのと同じ方法ね。",
  ui_story_1013_10131501_65_dialog_content = "あなたも見たんでしょ？ソラヴァンにどうやって意識が芽生えたか。\nその通りにやればいいのよ。",
  ui_story_1013_10131501_66_dialog_content = "ずっと話しかけるってことですか？\nでも、それには長い年月が必要で…",
  ui_story_1013_10131501_67_dialog_content = "あなたはまだ若いじゃない。\nソラヴァンが意識を回復する日までがんばればいいわ。",
  ui_story_1013_10131501_68_dialog_content = "…",
  ui_story_1013_10131501_69_dialog_content = "もちろん、もっと効率のよさそうな方法もあるけど。",
  ui_story_1013_10131501_70_dialog_content = "ソラヴァンの記憶の中で見たでしょう？\n知能が芽生えた巨像はソラヴァン1体だけじゃないわ。",
  ui_story_1013_10131501_71_dialog_content = "他の巨像の知能のデータが入手できれば、\nそれを参考にできる。",
  ui_story_1013_10131501_72_dialog_content = "ソラヴァンの知能を回復するのも簡単になるでしょうね。",
  ui_story_1013_10131501_73_dialog_content = "本当ですか！？",
  ui_story_1013_10131501_74_dialog_content = "「無」を「有」にするには天文学的な時間がかかるけど、\nお手本があれば話は別よ。",
  ui_story_1013_10131501_75_dialog_content = "現代の科学者を見くびってもらっちゃ困るわね。",
  ui_story_1013_10131501_76_dialog_content = "よかった…探します！\n僕が知能を持つ巨像を探してきます！",
  ui_story_1013_10131501_77_dialog_content = "それについては…",
  ui_story_1013_10131501_78_dialog_content = "ユリシーズ、どう思う？",
  ui_story_1013_10131501_79_dialog_content = "この場面で話を振ってくるということは、\n君の意志はもう決まっているのでしょう。",
  ui_story_1013_10131501_80_dialog_content = "当然よ。知能の自然発生なんて、\n願ってもない、最高の研究テーマじゃない！",
  ui_story_1013_10131501_81_dialog_content = "それに、研究成果がガーディアン1号の\n思考回路の最適化に活かせるかもしれないわ。",
  ui_story_1013_10131501_82_dialog_content = "そこまで言うなら、\n啓光に利益をもたらす研究として支持しましょうかね。",
  ui_story_1013_10131501_83_dialog_content = "空の末裔君。\nソラヴァンの知能を復元することについて…",
  ui_story_1013_10131501_84_dialog_content = "君が全工程にわたって、啓光の研究に協力する意思があるのなら、\n我々も相応の援助を提供しましょう。",
  ui_story_1013_10131501_85_dialog_content = "今回の話し合いの目的は、もともと取引でした。\nその点に変わりはありません。",
  ui_story_1013_10131501_86_dialog_content = "援助？どういう援助ですか？",
  ui_story_1013_10131501_87_dialog_content = "啓光連邦には古代の巨像を研究した経験があります。",
  ui_story_1013_10131501_88_dialog_content = "その研究資料がソラヴァンの知能を復元する助けとなるでしょう。",
  ui_story_1013_10131501_89_dialog_content = "そんな研究をしてたんですか！？",
  ui_story_1013_10131501_90_dialog_content = "ただ、その資料は今、\n我々の手元にはありません。",
  ui_story_1013_10131501_91_dialog_content = "君が取引に応じると言うのであれば、\nその研究資料の持ち主のもとへ人を送り、連絡を試みます。",
  ui_story_1013_10131501_92_dialog_content = "交換条件として、我々からはソラヴァンに必要な研究資料を提供します。",
  ui_story_1013_10131501_93_dialog_content = "君が出すものは…\n我々の計画と指示に従い、巨像の研究に協力することです。",
  ui_story_1013_10131501_94_dialog_content = "どうです？悪くない条件だと思いますが。",
  ui_story_1013_10131501_95_dialog_content = "それなら…",
  ui_story_1013_10131501_96_dialog_content = "分かりました。その条件でいいです。",
  ui_story_1013_10131501_97_dialog_content = "ソラヴァンを傷つけないかぎり、\n皆さんの研究に協力します。",
  ui_story_1013_10131501_98_dialog_content = "もちろん、傷つけたりなんてしないわ。\nソラヴァンをあなたが望む姿に戻してあげる。",
  ui_story_1013_10131501_99_dialog_content = "そうと決まれば…",
  ui_story_1013_10131501_100_dialog_content = "インゲル、A-42号金庫内の書類を持ってきなさい。",
  ui_story_1013_10131501_101_dialog_content = "空の末裔に必要なものだ。",
  ui_story_1013_10131501_102_dialog_content = "了解しました…",
  ui_story_1013_10131501_103_dialog_content = "（A-42号…そこまで機密レベルの高い書類を！？）",
  ui_story_1013_10131501_104_dialog_content = "書類を回収したら、私の研究室で待っていなさい。",
  ui_story_1013_10131501_105_dialog_content = "お前にやってもらうことがある。",
  ui_story_1013_10131501_106_dialog_content = "了解しました。",
  ui_story_1013_10131501_107_dialog_content = "ユリシーズ、今聞いたことは私の知らない情報だ。",
  ui_story_1013_10131501_108_dialog_content = "お前たち、またどこかに秘密を隠しているのか？",
  ui_story_1013_10131501_109_dialog_content = "隠しているとは言えないでしょうね。\n誰も取りに行かないだけのことです。",
  ui_story_1013_10131501_110_dialog_content = "君もあそこには興味がないでしょう。",
  ui_story_1013_10131501_111_dialog_content = "資料は極光遺跡にあります。",
  ui_story_1013_10131501_112_dialog_content = "！！！",
  ui_story_1013_10131501_113_dialog_content = "晨光（しんこう）歴■■■■年、巨像が■■■会戦に参戦。",
  ui_story_1013_10131501_114_dialog_content = "晨光歴■■■■年、戦闘中、巨像に不可逆的損傷が発生。",
  ui_story_1013_10131501_115_dialog_content = "晨光歴■■■■年、■■号シェルターに巨像の痕跡発見…",
  ui_story_1013_10131501_116_dialog_content = "そこらじゅう塗りつぶしてある…\n科学者ってずる賢い人たちだなぁ…",
  ui_story_1013_10131501_117_dialog_content = "…PlayerName、それは極秘資料だ。\n廊下で読むのはよせ。",
  ui_story_1013_10131501_118_dialog_content = "あ…ごめんなさい！\nソラヴァンのことを考えたら、つい気がはやって…",
  ui_story_1013_10131501_119_dialog_content = "分かっている。今度こそ、意識の回復まであと少しだ。",
  ui_story_1013_10131501_120_dialog_content = "はい、僕もそう思います！",
  ui_story_1013_10131501_121_dialog_content = "こんな時にと思うかもしれないが、\nお前に少し話しておきたいことがある。",
  ui_story_1013_10131501_122_dialog_content = "極光遺跡という名はなじみがないと思うが、\nもう一つの名は覚えがあるはずだ。",
  ui_story_1013_10131501_123_dialog_content = "トワイライトシティを覚えているか？",
  ui_story_1013_10131501_124_dialog_content = "覚えています。\nショウとショーンのいる場所でしたよね。",
  ui_story_1013_10131501_125_dialog_content = "トワイライトシティは、極光遺跡の内部にある居住地だ。",
  ui_story_1013_10131501_126_dialog_content = "かの地の事情はお前が想像するよりも、\nずっと複雑になっている。",
  ui_story_1013_10131501_127_dialog_content = "複雑？",
  ui_story_1013_10131501_128_dialog_content = "最高科学者会議ですら、足を踏み入れることはできても、\nしょせん、そこまでだ。",
  ui_story_1013_10131501_129_dialog_content = "それ以上のことはできん。",
  ui_story_1013_10131501_130_dialog_content = "彼らの障害になる者がいるのだ。\n当然、お前の障害にもなるだろう。",
  ui_story_1013_10131501_131_dialog_content = "障害になる？啓光連邦の土地じゃないんですか？",
  ui_story_1013_10131501_132_dialog_content = "そうでもあり、そうでもない。\n同時に、お前がよく知る白夜城の影響下にもあるのだ。",
  ui_story_1013_10131501_133_dialog_content = "かといって、ここでの固定観念で\nあの地の勢力図を見ることはできない。",
  ui_story_1013_10131501_134_dialog_content = "あそこは特別な場所なのだ。",
  ui_story_1013_10131501_135_dialog_content = "常に戦火にさらされ、\n地上にある全てが硝煙の匂いを放つ地だ。",
  ui_story_1013_10131501_136_dialog_content = "騎士がソルラドにひざまずくことはなく、\n教会の信徒たちは異なる太陽を仰いでいる…",
  ui_story_1013_10131501_137_dialog_content = "そして我らの兵士も、\nはるか遠くの大元帥「ふぜい」には従わない。",
  ui_story_1013_10131501_138_dialog_content = "そうなんですか…",
  ui_story_1013_10131501_139_dialog_content = "つまり、最高科学者会議が約束した計画が、\n実現できるとは限らないのだ。",
  ui_story_1013_10131501_140_dialog_content = "会議の連中は救命機器や軍需物資と引き換えにするつもりのようだ。\n公平かつ現実的な案ではあり、正しい手続きにも沿っている。",
  ui_story_1013_10131501_141_dialog_content = "しかし、手続きなど、あの地では用をなさない。",
  ui_story_1013_10131501_142_dialog_content = "取引の成立には時間がかかるだろう。\n何の音沙汰も得られない可能性もある。",
  ui_story_1013_10131501_143_dialog_content = "そんな…やっとソラヴァンを助けられる希望が見えてきたのに！\nこれ以上待てだなんて！",
  ui_story_1013_10131501_144_dialog_content = "ソラヴァンの意識が、こうしてる間にも、\nまた問題を起こすかもしれないのに…",
  ui_story_1013_10131501_145_dialog_content = "これ以上はグズグズしていられません。\n僕が自分でそこに行って、取引します！",
  ui_story_1013_10131501_146_dialog_content = "ソラヴァンがいれば、\n兵士たちよりずっと早く着けるはずです。",
  ui_story_1013_10131501_147_dialog_content = "何か面倒なことが起こったとしても…\n自分で解決できる方が、ただ焦ってるだけより、ずっとマシです！",
  ui_story_1013_10131501_148_dialog_content = "そう言うだろうと思っていた。\nお前は肝心な時に見事な行動力を発揮する。",
  ui_story_1013_10131501_149_dialog_content = "自分で取引すると言うのなら、\n万全の準備を整えておけ。",
  ui_story_1013_10131501_150_dialog_content = "暗鬼との戦い、派閥の争い、\n天災にも備えなければならないだろうな。",
  ui_story_1013_10131501_151_dialog_content = "カナン城でできる準備については、私ができるかぎり助力する。\nだが、一たびここを離れたら、頼れるのは己だけだ。",
  ui_story_1013_10131501_152_dialog_content = "僕は1人じゃありません。\n忘れましたか？空の末裔は1人じゃ戦えないんです。",
  ui_story_1013_10131501_153_dialog_content = "ならば、十分に信頼できる仲間を連れていけ。",
  ui_story_1013_10131501_154_dialog_content = "安心してください。\n自分に自信をもったことは無いけど…",
  ui_story_1013_10131501_155_dialog_content = "友だちについては、自信があります！",
  ui_story_1013_10131501_156_dialog_content = "ハハハ…ずいぶんと弱々しい自信だな。",
  ui_story_1013_10131501_157_dialog_content = "うっ、それは…",
  ui_story_1013_10131501_158_dialog_content = "だが、肩を並べて戦ってから、\nお前のもつ力を理解できるようになった気がする。",
  ui_story_1013_10131501_159_dialog_content = "勝利のために戦わず、失敗を恐れる。\n鋭気など感じられないのに、なぜかうまく事が運ぶ。",
  ui_story_1013_10131501_160_dialog_content = "戦士たちを引きつけ、心を動かすには十分な力だ。",
  ui_story_1013_10131501_161_dialog_content = "勇気よりも力のある、\n弱き者の勇気と言うべきか。",
  ui_story_1014_10140101_1_dialog_content = "<color=#e8d9bb>カナン城、啓光連邦研究所</color>",
  ui_story_1014_10140101_2_dialog_content = "分かったわ！栄えある派遣任務ね！",
  ui_story_1014_10140101_3_dialog_content = "危険に満ちた辺境、暗面に近い複雑な事情の町、\n心躍る探検…",
  ui_story_1014_10140101_4_dialog_content = "私は準備できてるわ、PlayerName！",
  ui_story_1014_10140101_5_dialog_content = "もちろん…",
  ui_story_1014_10140101_6_dialog_content = "ダメに決まってるでしょ！？",
  ui_story_1014_10140101_7_dialog_content = "<size=45>えっ！？</size>",
  ui_story_1014_10140101_8_dialog_content = "啓光の防衛線の外にある町がどれだけ危険かとか…",
  ui_story_1014_10140101_9_dialog_content = "暗面に近い場所の環境がどれだけ過酷かとかは、\n今さら言わないにしても…",
  ui_story_1014_10140101_10_dialog_content = "今のバイスの身体で、\n啓光から離れて長旅なんてさせられないよ！",
  ui_story_1014_10140101_11_dialog_content = "何の関係があるのよ？\n私はピンピンしてるでしょ？",
  ui_story_1014_10140101_12_dialog_content = "ダメって言ったらダメ！",
  ui_story_1014_10140101_13_dialog_content = "ちょうど啓光の人たちが\n医療装置の改良研究を始めたって言うし。",
  ui_story_1014_10140101_14_dialog_content = "とにかく、バイスは病院で静養して。\n身体が完全によくなったら…",
  ui_story_1014_10140101_15_dialog_content = "<color=#e8d9bb>ブーン…</color>",
  ui_story_1014_10140101_16_dialog_content = "あら？ちょっと待って、PlayerName。",
  ui_story_1014_10140101_17_dialog_content = "もしもし、誰…ええっ！？",
  ui_story_1014_10140101_18_dialog_content = "こ、こちらはバイス中尉！\n大元帥に敬礼！！",
  ui_story_1014_10140101_19_dialog_content = "（バイスの具合を気にかけてくれてる…のかな？）",
  ui_story_1014_10140101_20_dialog_content = "えっ？緊急の任務ですか…？",
  ui_story_1014_10140101_21_dialog_content = "（緊急？こんなタイミングで？）",
  ui_story_1014_10140101_22_dialog_content = "了解しました。メモを取らせてください…",
  ui_story_1014_10140101_23_dialog_content = "<size=33>最高科学者会議、トワイライトシティ…\n極光遺跡…データの取引…</size>",
  ui_story_1014_10140101_24_dialog_content = "（さっき起きた話、全部説明してる！？）",
  ui_story_1014_10140101_25_dialog_content = "はい、了解しました。",
  ui_story_1014_10140101_26_dialog_content = "ご信頼に感謝いたします！\nお任せください！",
  ui_story_1014_10140101_27_dialog_content = "（どういうことだろう。\n何かを頼まれてる？）",
  ui_story_1014_10140101_28_dialog_content = "はい、確実に遂行します！それでは！",
  ui_story_1014_10140101_29_dialog_content = "――とにかく、PlayerNameが何と言おうと、\n私はあなたと一緒に行くから！",
  ui_story_1014_10140101_30_dialog_content = "大元帥様直々の命令だもの！",
  ui_story_1014_10140101_31_dialog_content = "私を困らせないでね！大元帥様も。",
  ui_story_1014_10140101_32_dialog_content = "ど、どうしてそうなるの！？",
  ui_story_1014_10140101_33_dialog_content = "お困りみたいだったわよ？\nしばらく事務仕事から抜け出せそうにないですって。",
  ui_story_1014_10140101_34_dialog_content = "「バイス中尉、啓光を代表して、\n空の末裔と辺境勢力の取引を助けるように」",
  ui_story_1014_10140101_35_dialog_content = "…っておっしゃってたわ。",
  ui_story_1014_10140101_36_dialog_content = "そうは言うけど…",
  ui_story_1014_10140101_37_dialog_content = "心配いらないわ、PlayerName。",
  ui_story_1014_10140101_38_dialog_content = "そういうわけだから、\n私にも詳しい事、聞かせてもらえるわよね？",
  ui_story_1014_10140101_39_dialog_content = "…分かった。じゃあ、最初から話すよ。\nさっきの会議で…",
  ui_story_1014_10140101_40_dialog_content = "<color=#e8d9bb>啓光連邦、カナン城・大会議室</color>",
  ui_story_1014_10140101_41_dialog_content = "君が取引に応じると言うのであれば、\nその研究資料の持ち主のもとへ人を送り、連絡を試みます。",
  ui_story_1014_10140101_42_dialog_content = "交換条件として、我々からはソラヴァンに必要な研究資料を提供します。",
  ui_story_1014_10140101_43_dialog_content = "これ以上はグズグズしていられません。\n僕が自分でそこに行って、取引します！",
  ui_story_1014_10140101_44_dialog_content = "ソラヴァンがいれば、\n兵士たちよりずっと早く着けるはずです。",
  ui_story_1014_10140101_45_dialog_content = "つまり、君が啓光本部になり代わり、\n極光遺跡の住民と連絡を取るということですか？",
  ui_story_1014_10140101_46_dialog_content = "空の末裔君にそのような権限は与えられないと思いますがね。",
  ui_story_1014_10140101_47_dialog_content = "それがどうした。\n杓子定規なことばかり言うな、ユリシーズ。",
  ui_story_1014_10140101_48_dialog_content = "そもそも、これはPlayerNameとトワイライトシティとの取引だ。\n啓光は手段を提供するだけにすぎん。",
  ui_story_1014_10140101_49_dialog_content = "ふわ…あたしはちょうどいいと思うけどね。",
  ui_story_1014_10140101_50_dialog_content = "壊れ物の「<color=#FFB400>儚き神業</color>」の護送に、誰かが必要よ。",
  ui_story_1014_10140101_51_dialog_content = "壊れ物？交換に出す物のことですか？",
  ui_story_1014_10140101_52_dialog_content = "そうよ。本部とトワイライトシティにいる啓光の勢力で、\n前々から契約を結んでたの。",
  ui_story_1014_10140101_53_dialog_content = "辺境で争いが頻発してるから、\n本部が高性能の兵器を送ることにしたの。",
  ui_story_1014_10140101_54_dialog_content = "ユリシーズが製造した最新型よ。",
  ui_story_1014_10140101_55_dialog_content = "それを向こうの啓光の人たちに引き渡せば、\n巨像に関する研究データを提供してくれるはずよ。",
  ui_story_1014_10140101_56_dialog_content = "とっても貴重でデリケートだから、\n輸送する時はくれぐれも注意してね。",
  ui_story_1014_10140101_57_dialog_content = "飛空艇で輸送するより、\n空の末裔の手で運んでもらった方が安全だわ。",
  ui_story_1014_10140101_58_dialog_content = "「儚き神業」、話には聞いたことが有るわ…",
  ui_story_1014_10140101_59_dialog_content = "そうだよ。今は僕が預かってる。",
  ui_story_1014_10140101_60_dialog_content = "気になるわね…\nどんな兵器なのかしら。",
  ui_story_1014_10140101_61_dialog_content = "<color=#e8d9bb><size=30>カタッ…</size></color>",
  ui_story_1014_10140101_62_dialog_content = "PlayerName！み、見て。音がしたみたい！",
  ui_story_1014_10140101_63_dialog_content = "何の音？僕には聞こえなかったけど？",
  ui_story_1014_10140101_64_dialog_content = "…私が神経質になりすぎてるのかしら。",
  ui_story_1014_10140101_65_dialog_content = "PlayerName、何を考えてるの？",
  ui_story_1014_10140101_66_dialog_content = "僕はただ…少し心配なだけだよ。",
  ui_story_1014_10140101_67_dialog_content = "ソラヴァンの調子は良くないからね。\n簡単な輸送の仕事だって、そうとう無理してるはずなんだ。万が一…",
  ui_story_1014_10140101_68_dialog_content = "万が一何か問題が起きたら、\nその時また、一緒に方法を考えましょ？",
  ui_story_1014_10140101_69_dialog_content = "善は急げよ。今すぐ出発しましょう！",
  ui_story_1014_10140101_70_dialog_content = "うん、それもそうだね…",
  ui_story_1014_10140101_71_dialog_content = "<color=#e8d9bb>ソラヴァン・ブリッジ</color>",
  ui_story_1014_10140101_72_dialog_content = "（コントロールシステム、チェック…よし）",
  ui_story_1014_10140101_73_dialog_content = "（エンジン性能チェック…よし）",
  ui_story_1014_10140101_74_dialog_content = "こういうことも、\n今は全部自分でやらないといけないのか…",
  ui_story_1014_10140101_75_dialog_content = "（後で休憩室を確認しに行こう）",
  ui_story_1014_10140101_76_dialog_content = "…あれ！？",
  ui_story_1014_10140101_77_dialog_content = "カレン、ベルタ？それに…インゲル！？",
  ui_story_1014_10140101_78_dialog_content = "みんな、どうしてここにいるの！？",
  ui_story_1014_10140101_79_dialog_content = "カレンには知らせてる時間もなかったのに…",
  ui_story_1014_10140101_80_dialog_content = "バイスがあらかじめ教えてくれたの。\nPlayerNameがまた、極夜の方角へ出発しようとしているって。",
  ui_story_1014_10140101_81_dialog_content = "あなたたち2人だけで戦わせるなんて、\n心配で落ち着けないわ。",
  ui_story_1014_10140101_82_dialog_content = "フフフ、カレンはいつも頼りになるわ。",
  ui_story_1014_10140101_83_dialog_content = "間に合わないんじゃないかって心配したのよ！",
  ui_story_1014_10140101_84_dialog_content = "こちらにも都合が良かったの。\n白夜城もトワイライトシティの辺境勢力と、長らく交流が途絶えているから。",
  ui_story_1014_10140101_85_dialog_content = "ベルタも連れてきたことだから、\nついでに向こうの視察をするわ。",
  ui_story_1014_10140101_86_dialog_content = "また会ったわね、PlayerName。",
  ui_story_1014_10140101_87_dialog_content = "顔色が悪いみたいね。\n注射でもしてあげましょうか？",
  ui_story_1014_10140101_88_dialog_content = "え、ええ！？",
  ui_story_1014_10140101_89_dialog_content = "冗談よ。",
  ui_story_1014_10140101_90_dialog_content = "それより、横にいる啓光の人は見たことがないわ。\n天空ノ谷では会ってないわよね？",
  ui_story_1014_10140101_91_dialog_content = "今度は白髪の人とは一緒じゃないの？",
  ui_story_1014_10140101_92_dialog_content = "失礼よ、ベルタ。",
  ui_story_1014_10140101_93_dialog_content = "は、はい！カレン殿下。",
  ui_story_1014_10140101_94_dialog_content = "啓光連邦、情報機関近衛部門のインゲル中佐です。",
  ui_story_1014_10140101_95_dialog_content = "バイス中尉、お噂はかねがね。\n空の末裔や巨像について、ぜひご教示いただきたく。",
  ui_story_1014_10140101_96_dialog_content = "えっ…あっ、そ、そんなにかしこまらないでください！\n私の方こそ敬礼しないと…",
  ui_story_1014_10140101_97_dialog_content = "（バイス、完全に気が動転してる…）",
  ui_story_1014_10140101_98_dialog_content = "ちょっと聞きたいんだけど、\n君がここにいるのは、最高科学者会議の指示？",
  ui_story_1014_10140101_99_dialog_content = "確かに私は任務を受けてここにおりますが…",
  ui_story_1014_10140101_100_dialog_content = "辺境の戦地に行ってみたいということは、\n私の希望でもあります。",
  ui_story_1014_10140101_101_dialog_content = "A-42ファイルの内容に基づいて、\n信ぴょう性のある情報を提供させていただきます。",
  ui_story_1014_10140101_102_dialog_content = "あなたも「儚き神業」の真偽を証明できる\n中立の者が必要なのではないでしょうか。",
  ui_story_1014_10140101_103_dialog_content = "確かにそうだけど…",
  ui_story_1014_10140101_104_dialog_content = "ご心配なく。こちらに関しては本部主導の取引です。\n成否に関係なく、あなたには干渉を行いません。",
  ui_story_1014_10140101_105_dialog_content = "（反対する理由も特にないか…）",
  ui_story_1014_10140101_106_dialog_content = "…待って。じゃあ、今は最高科学者会議の集まりに\n大元帥さんだけ残ってるってこと？",
  ui_story_1014_10140101_107_dialog_content = "大元帥のことを心配しておられるのですか？",
  ui_story_1014_10140101_108_dialog_content = "…そう言われてみると、\n僕が心配するまでもないか…",
  ui_story_1014_10140101_109_dialog_content = "<color=#e8d9bb>その頃、啓光大会議室</color>",
  ui_story_1014_10140101_110_dialog_content = "ノラとヘリオス、両名の追跡は戦略的な任務ではありません。\n大元帥が自ら手を下すことでもないでしょう。",
  ui_story_1014_10140101_111_dialog_content = "最高科学者会議は、\nその件をよりふさわしい人物に委任します。",
  ui_story_1014_10140101_112_dialog_content = "過去に固執するのはよい事ではありません。\nあなたも、より重要な物事に目を向けるべきでしょう。",
  ui_story_1014_10140101_113_dialog_content = "ユリシーズにとって不利となる手がかりを\n私に掴まれることが心配か？",
  ui_story_1014_10140101_114_dialog_content = "「不利となる手がかり」とは何ですかな？",
  ui_story_1014_10140101_115_dialog_content = "私よりお前の方が分かっているはずだ。",
  ui_story_1014_10140101_116_dialog_content = "ユリシーズ、とぼけていられるのも今のうちだ。\n真相が明るみに出る日を楽しみにしているぞ。",
  ui_story_1014_10140101_117_dialog_content = "そこまで些事に執着を見せるとなると、\n委員会もあなたの資質を再評価せねばならなくなるでしょうね。",
  ui_story_1014_10140101_118_dialog_content = "面白い、言ってみろ。\n光霊そのものより重要なこととは何だと言うのだ？",
  ui_story_1014_10140101_119_dialog_content = "わざわざ言う必要がありますか？\n啓光の合同軍事演習、今後の連合軍の反撃…どれをとっても…",
  ui_story_1014_10140101_120_dialog_content = "笑わせる…",
  ui_story_1014_10140101_121_dialog_content = "大元帥としての在り方を誰かに説教される必要など、私にはない。",
  ui_story_1014_10140101_122_dialog_content = "私が決めたことは、\n誰が何と言おうと、簡単には覆さない。",
  ui_story_1014_10140101_123_dialog_content = "失礼する。",
  ui_story_1014_10140101_124_dialog_content = "相変わらずの一匹狼ですね。",
  ui_story_1014_10140101_125_dialog_content = "ふむ…彼女なら、\n例の日蝕の女を見つけることも難しくはないでしょうね。",
  ui_story_1014_10140101_126_dialog_content = "あれこれ言う必要もありません。",
  ui_story_1014_10140101_127_dialog_content = "私もそのための計画を用意してありますから。",
  ui_story_1014_10140201_1_dialog_content = "コントロールシステムは…うん、異常なし。",
  ui_story_1014_10140201_2_dialog_content = "自動操縦システムも特に問題なしね。",
  ui_story_1014_10140201_3_dialog_content = "PlayerName、ソラヴァンはもうずいぶん安定して飛行してるわ。\n少しは安心しても大丈夫よ。",
  ui_story_1014_10140201_4_dialog_content = "そ、それもそうだね。バイス、お疲れ様。",
  ui_story_1014_10140201_5_dialog_content = "私は別に、どうってことないわ。\nただ、あなたが心配してるように見えたから。",
  ui_story_1014_10140201_6_dialog_content = "それより…あなたもずっとその預かりもの、\n抱きかかえてる必要はないでしょ？",
  ui_story_1014_10140201_7_dialog_content = "卵を温めてるニワトリじゃないのよ？",
  ui_story_1014_10140201_8_dialog_content = "でも、ある意味これは、ソラヴァンを直すための重要なものなんだ！",
  ui_story_1014_10140201_9_dialog_content = "ただ、どうやって守ればいいのか分からなくて…",
  ui_story_1014_10140201_10_dialog_content = "あとこれ、思ってたほど重くないんだよね…",
  ui_story_1014_10140201_11_dialog_content = "えっ、そうなの？本当に不思議ね。\n軽量型の武器か何かなのかしら。",
  ui_story_1014_10140201_12_dialog_content = "軽くて壊れやすいなんて…\n高性能の兵器の設計としては、本当に変わってるわね。",
  ui_story_1014_10140201_13_dialog_content = "と、とにかく。僕はこのままでいいよ！",
  ui_story_1014_10140201_14_dialog_content = "仕方ないわね…",
  ui_story_1014_10140201_15_dialog_content = "（気分転換にカレンが何をしてるのか見てこようかしら）",
  ui_story_1014_10140201_16_dialog_content = "<color=#e8d9bb>ピー…ガー…ザーザー…</color>",
  ui_story_1014_10140201_17_dialog_content = "…",
  ui_story_1014_10140201_18_dialog_content = "まだ直らないようね、ベルタ。",
  ui_story_1014_10140201_19_dialog_content = "申し訳ございません、カレン殿下。\nこのような通信機の使い方は詳しくなく…",
  ui_story_1014_10140201_20_dialog_content = "あら？",
  ui_story_1014_10140201_21_dialog_content = "バイス、ちょうどいいところに来たわ。",
  ui_story_1014_10140201_22_dialog_content = "どうかしたの？何か手伝いが要る？",
  ui_story_1014_10140201_23_dialog_content = "向こうに派遣されている辺境騎士団と連絡を取って、\n現地の状況を事前に把握しておこうと思ったのよ。",
  ui_story_1014_10140201_24_dialog_content = "あの地で通年駐屯しているし、\n私たちの受け入れ役になるはずなの。",
  ui_story_1014_10140201_25_dialog_content = "今までこういうことは城主が務めていたし、\n連絡の準備なんてしていなかったものだから…",
  ui_story_1014_10140201_26_dialog_content = "ずいぶん急いで来てくれたのね。",
  ui_story_1014_10140201_27_dialog_content = "でも、心配はもう無用ね。\n目の前に「先生」がいるもの。",
  ui_story_1014_10140201_28_dialog_content = "お願い、バイス。\nこの通信機のどこが悪いのか見てもらえるかしら。",
  ui_story_1014_10140201_29_dialog_content = "信号が不安定なのよ。",
  ui_story_1014_10140201_30_dialog_content = "うん、任せて！",
  ui_story_1014_10140201_31_dialog_content = "どれどれ…まずはアンテナの感度を調節…",
  ui_story_1014_10140201_32_dialog_content = "できたわ。試してみましょ！",
  ui_story_1014_10140201_33_dialog_content = "<color=#e8d9bb>ピー…ガー…ザーザー…</color>",
  ui_story_1014_10140201_34_dialog_content = "うーん、それじゃあ…パワーアンプモジュールを…",
  ui_story_1014_10140201_35_dialog_content = "よし！これで大丈夫よ。",
  ui_story_1014_10140201_36_dialog_content = "<color=#e8d9bb>ピー…ガー…ザーザー…</color>",
  ui_story_1014_10140201_37_dialog_content = "アハハハ…こうなったら、残った手段は――",
  ui_story_1014_10140201_38_dialog_content = "<color=#e8d9bb>バンッ！バンッ！</color>",
  ui_story_1014_10140201_39_dialog_content = "<color=#e8d9bb>ピピッ、ピピッ…</color>",
  ui_story_1014_10140201_40_dialog_content = "ふぅ、簡単なことね！",
  ui_story_1014_10140201_41_dialog_content = "なるほど、そうやって直すのね。",
  ui_story_1014_10140201_42_dialog_content = "…応答せよ…",
  ui_story_1014_10140201_43_dialog_content = "こちらは<color=#FFB400>アイアンソーン騎士団</color>。\n繰り返す、こちらはアイアンソーン騎士団。",
  ui_story_1014_10140201_44_dialog_content = "よかった。つながったみたいね…白夜に捧ぐ。\nこちらはアップタウン護衛隊隊長、カレン。アイアンソーン騎士団、ごきげんよう。",
  ui_story_1014_10140201_45_dialog_content = "こちらはアイアンソーン騎士団団長のレオ。カレン殿下…",
  ui_story_1014_10140201_46_dialog_content = "<color=#e8d9bb>ザザッ――</color>",
  ui_story_1014_10140201_47_dialog_content = "（やはり、まだ通信が不安定なのかしら…）",
  ui_story_1014_10140201_48_dialog_content = "レオ騎士団長、白夜城はトワイライトシティへの定例視察を行うことになったわ。",
  ui_story_1014_10140201_49_dialog_content = "私が白夜城を代表する。\nあなたに会える時を楽しみにしているわね。",
  ui_story_1014_10140201_50_dialog_content = "辺境の戦地での仕事は苦労も多いことでしょう。\n直接会って、感謝の気持ちを伝えたいの。",
  ui_story_1014_10140201_51_dialog_content = "それはずいぶんと急な話ですね。\n<color=#FFB400>白夜要塞</color>の巡回の時間に合わせられるようにしましょう。",
  ui_story_1014_10140201_52_dialog_content = "感謝の気持ちは必要ありません。\nこれが私の役目ですから。",
  ui_story_1014_10140201_53_dialog_content = "では、またその時に。",
  ui_story_1014_10140201_54_dialog_content = "はい。到着されましたら、\n私も人を…着されましたら…行かせます…",
  ui_story_1014_10140201_55_dialog_content = "<color=#e8d9bb>ザザッ――</color>",
  ui_story_1014_10140201_56_dialog_content = "<color=#e8d9bb>ピピッ、ピピッ…</color>",
  ui_story_1014_10140201_57_dialog_content = "また信号が完全に途切れたみたいね…",
  ui_story_1014_10140201_58_dialog_content = "まあ、構わないわ。\n最低限の情報は伝わったようだから。",
  ui_story_1014_10140201_59_dialog_content = "それよりカレン殿下、大丈夫なのですか…？",
  ui_story_1014_10140201_60_dialog_content = "前回の天空ノ谷の戦役の功績で、\nカレン殿下が隊長に復職することは認められる方向ではあります。",
  ui_story_1014_10140201_61_dialog_content = "確かに、最近のカレン殿下は以前よりも\n決断力が強くなられておりますし…",
  ui_story_1014_10140201_62_dialog_content = "とはいえ、城主様の話では、\n現在はまだ、復職のための審査中のはず…",
  ui_story_1014_10140201_63_dialog_content = "何事もないといいのですが…",
  ui_story_1014_10140201_64_dialog_content = "大丈夫よ、ベルタ。\nあなたの気持ちは分かるけど、心配しすぎる必要はない。",
  ui_story_1014_10140201_65_dialog_content = "何か問題が起きたとしても、対処すればいいだけ。",
  ui_story_1014_10140201_66_dialog_content = "まあ…殿下のおっしゃる通りですね。",
  ui_story_1014_10140201_67_dialog_content = "ところで、この「レオ騎士団長」、いったい何者なのでしょうか？",
  ui_story_1014_10140201_68_dialog_content = "カレン殿下が感謝の意を示されたのに、\nずいぶん無愛想に返されましたね。",
  ui_story_1014_10140201_69_dialog_content = "気にしないでいいわ、ベルタ。",
  ui_story_1014_10140201_70_dialog_content = "白夜城で平和に暮らせる私たちは、\n辺境の戦士たちに敬意を払わなければ。",
  ui_story_1014_10140201_71_dialog_content = "<color=#e8d9bb>ピーッ！ピーッ！ピーッ！</color>",
  ui_story_1014_10140201_72_dialog_content = "何事！？",
  ui_story_1014_10140201_73_dialog_content = "これはソラヴァンの警報ね？",
  ui_story_1014_10140201_74_dialog_content = "いけない…",
  ui_story_1014_10140201_75_dialog_content = "PlayerNameを呼びにいかないと！",
  ui_story_1014_10140201_76_dialog_content = "はぁ、はぁ…",
  ui_story_1014_10140201_77_option_content = "緊急モードを起動する",
  ui_story_1014_10140201_78_dialog_content = "<color=#e8d9bb>ピ――！</color>",
  ui_story_1014_10140201_79_option_content = "飛行装置を安定させる",
  ui_story_1014_10140201_80_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_1014_10140201_81_dialog_content = "まったく…気を付けてください。",
  ui_story_1014_10140201_82_dialog_content = "私が抱き止めていなかったら、\n「儚き神業」がどこかにぶつかっていたところです。",
  ui_story_1014_10140201_83_dialog_content = "PlayerName、状況は！？",
  ui_story_1014_10140201_84_dialog_content = "警報器が鳴ったから、驚かせちゃった？\nうっかり操作ミスして、作動させちゃったんだ。",
  ui_story_1014_10140201_85_dialog_content = "大したことないみたいに言わないでよ、PlayerName！",
  ui_story_1014_10140201_86_dialog_content = "本当に大丈夫？\n巨像の操縦って私が想像していたよりも難しいみたいね…",
  ui_story_1014_10140201_87_dialog_content = "も、もちろん、大丈夫だよ。",
  ui_story_1014_10140201_88_dialog_content = "（それに、僕だって巨像を操る、空の末裔なんだから！）",
  ui_story_1014_10140201_89_dialog_content = "本当に疲れているようなら、\nとりあえず着陸して休憩した方がいいわ。",
  ui_story_1014_10140201_90_dialog_content = "極夜の境界に近づくにつれて、周囲の暗力も強くなっていくわ。",
  ui_story_1014_10140201_91_dialog_content = "PlayerName、気分が悪いのではない？",
  ui_story_1014_10140201_92_dialog_content = "正直に言って。",
  ui_story_1014_10140201_93_dialog_content = "カレンは鋭いね…確かに、さっきから少し頭痛がしてるんだ。",
  ui_story_1014_10140201_94_dialog_content = "巨像の操縦については分かりませんが、\n「儚き神業」の安全を考えると…",
  ui_story_1014_10140201_95_dialog_content = "私も着陸してしばらく休憩することを推奨します。",
  ui_story_1014_10140201_96_dialog_content = "我々双方とも、あなたのミスで「儚き神業」に\n不測の事態が起こることは望んでいないでしょうから。",
  ui_story_1014_10140201_97_dialog_content = "もちろんだよ。",
  ui_story_1014_10140201_98_dialog_content = "…分かった。確かに少し、無理してたかもしれない。",
  ui_story_1014_10140201_99_dialog_content = "皆、準備して。ソラヴァンを着陸させるから。",
  ui_story_1014_10140201_100_dialog_content = "ふぅ――",
  ui_story_1014_10140201_101_dialog_content = "外に出て体を動かすのも悪くないわね。",
  ui_story_1014_10140201_102_dialog_content = "ところで、ソラヴァンに一体何があったというの？",
  ui_story_1014_10140201_103_dialog_content = "着陸の操作までPlayerNameが自分でやっているなんて…",
  ui_story_1014_10140201_104_dialog_content = "そうとう深刻な問題のようね。",
  ui_story_1014_10140201_105_dialog_content = "ソラヴァンの意識にまた、問題が起こったんだ。\n普通の動作には影響ないけど、感知ができなくなってるんだよ。",
  ui_story_1014_10140201_106_dialog_content = "…ソラヴァンの計器をもう一度チェックしてくる。",
  ui_story_1014_10140201_107_dialog_content = "私も行きます。",
  ui_story_1014_10140201_108_dialog_content = "<color=#e8d9bb>ヒュゥ…</color>",
  ui_story_1014_10140201_109_dialog_content = "（完全に荒れ果てた場所だ）",
  ui_story_1014_10140201_110_dialog_content = "ここの光力は啓光本部に比べると、だいぶ薄いね。\n身体は大丈夫？",
  ui_story_1014_10140201_111_dialog_content = "この程度なら問題はありません。",
  ui_story_1014_10140201_112_dialog_content = "それに、「空の末裔の行動や状況をつぶさに記録する」\nというのも私の任務の1つですので。",
  ui_story_1014_10140201_113_dialog_content = "どこが故障しているのか調べに行きましょう。",
  ui_story_1014_10140201_114_dialog_content = "わ、分かったよ。",
  ui_story_1014_10140201_115_dialog_content = "（何だか監視されてるみたいだな…）",
  ui_story_1014_10140201_116_dialog_content = "ガァ…",
  ui_story_1014_10140201_117_dialog_content = "えっ！？この音は、まさか…",
  ui_story_1014_10140201_118_dialog_content = "<anim type=Shake><size=45>グアア！！！</size></anim>",
  ui_story_1014_10140201_119_dialog_content = "暗鬼！？",
  ui_story_1014_10140201_120_dialog_content = "こんな場所なら、出てきて当然か…",
  ui_story_1014_10140201_121_dialog_content = "ソラヴァンに近づけさせるわけにはいかないよ。\n君って戦える？",
  ui_story_1014_10140201_122_dialog_content = "私は…戦闘シミュレーション上の話でしたら…",
  ui_story_1014_10140201_123_dialog_content = "じゃあ、早くバイスとカレンたちを呼んできて！",
  ui_story_1014_10140201_124_dialog_content = "戦闘…",
  ui_story_1014_10140201_125_dialog_content = "アクセリアは戦闘命令を受領しました。",
  ui_story_1014_10140201_126_dialog_content = "！？",
  ui_story_1014_10140201_127_dialog_content = "（やっと出てきましたか…）",
  ui_story_1014_10140201_128_dialog_content = "い、今の声は誰！？",
  ui_story_1014_10140201_129_dialog_content = "<color=#e8d9bb>ガシャッ…ガシャッ…</color>",
  ui_story_1014_10140201_130_dialog_content = "アクセリアは戦闘命令を受領しました。",
  ui_story_1014_10140201_131_dialog_content = "インゲルを困らせないでください。",
  ui_story_1014_10140201_132_dialog_content = "アクセリア、戦闘準備。",
  ui_story_1014_10140201_133_dialog_content = "き、君って…",
  ui_story_1014_10140201_134_dialog_content = "僕が預かってた<color=#FFB400>「儚き神業」</color>って…\n光霊の事だったの！？",
  ui_story_1014_10140201_135_dialog_content = "グォォ！！！",
  ui_story_1014_10140201_136_dialog_content = "一撃も耐久できませんでしたか。",
  ui_story_1014_10140202_1_dialog_content = "速射感知――！",
  ui_story_1014_10140202_2_dialog_content = "散れ！氷花よ！",
  ui_story_1014_10140202_3_dialog_content = "助かりました、バイス中尉。",
  ui_story_1014_10140202_4_dialog_content = "アクセリア、大丈夫ですか？",
  ui_story_1014_10140202_5_dialog_content = "その質問は暗鬼に聞くべきです。",
  ui_story_1014_10140202_6_dialog_content = "…すでに答えられる状態ではないと思いますが。",
  ui_story_1014_10140202_7_dialog_content = "まったく…勝手に休眠カプセルから出てきてはいけません。\nあなたの任務遂行地点はここではありませんよ。",
  ui_story_1014_10140202_8_dialog_content = "自分を損傷しないよう注意します。",
  ui_story_1014_10140202_9_dialog_content = "インゲルに迷惑はかけません。",
  ui_story_1014_10140202_10_dialog_content = "ちょっと、勝手に話を進めないでよ！？",
  ui_story_1014_10140202_11_dialog_content = "説明してもらえる？\n僕が預かってたの、どう見ても物じゃなくて光霊だよね？",
  ui_story_1014_10140202_12_dialog_content = "厳密に言えば、彼女は確かに光霊でもあります。",
  ui_story_1014_10140202_13_dialog_content = "しかし、彼女は光霊である前に、\n最高科学者会議が誇る戦闘兵器です。",
  ui_story_1014_10140202_14_dialog_content = "兵器…？",
  ui_story_1014_10140202_15_dialog_content = "我々がそう呼んでいるだけのことです。",
  ui_story_1014_10140202_16_dialog_content = "彼女はどんな作戦も絶対に遂行する、\n完璧主義者ですから。",
  ui_story_1014_10140202_17_dialog_content = "彼女が光力を操っていると言うよりも、\n光力が彼女の姿を取っていると言った方がよいでしょう。",
  ui_story_1014_10140202_18_dialog_content = "彼女は光力術を使って物を見たり、聞いたりできるほか、\n各種機械を操作して戦うこともできます。",
  ui_story_1014_10140202_19_dialog_content = "すごいね。そんな能力、聞いたことないよ！",
  ui_story_1014_10140202_20_dialog_content = "その通り、彼女は光力術の扱いでは群を抜いています。\nですが…",
  ui_story_1014_10140202_21_dialog_content = "身体がとても弱いのです。",
  ui_story_1014_10140202_22_dialog_content = "全身の包帯を見ればお分かりになるでしょう。\n彼女の身体機能は常に衰弱状態にあります。",
  ui_story_1014_10140202_23_dialog_content = "衰弱状態？どうして？\n啓光の医療技術でも治せないの？",
  ui_story_1014_10140202_24_dialog_content = "さあ、そこまでは…\nおそらく遺伝子と関係あるのだと思いますが。",
  ui_story_1014_10140202_25_dialog_content = "いずれにせよ、\n彼女はいわゆる「ガラスの大砲」のようなものです。",
  ui_story_1014_10140202_26_dialog_content = "啓光本部にいても能力を持て余すだけです。\nトワイライトシティのような極限の戦地でしか能力の真価を発揮できません。",
  ui_story_1014_10140202_27_dialog_content = "こんにちは、PlayerName。\nあいさつが遅くなりました。",
  ui_story_1014_10140202_28_dialog_content = "到着まで迷惑をかけると思いますが、\nよろしくお願いします。",
  ui_story_1014_10140202_29_dialog_content = "返礼として、アクセリアは…",
  ui_story_1014_10140202_30_dialog_content = "必要に応じて休眠カプセルから出て、戦闘を行います。",
  ui_story_1014_10140202_31_dialog_content = "そ、その必要はないよ！",
  ui_story_1014_10140202_32_dialog_content = "（何かあったら大変だしね…）",
  ui_story_1014_10140202_33_dialog_content = "普通の暗鬼なら僕たちで対処できるから、\nわざわざ君に出てもらうまでもないよ！",
  ui_story_1014_10140202_34_dialog_content = "そうよ。どうしようもない事態になるまでは、\nしっかり休んでいて。",
  ui_story_1014_10140202_35_dialog_content = "そう言われると、確かに眠くなってきました。",
  ui_story_1014_10140202_36_dialog_content = "（なんだか可愛いわね…）",
  ui_story_1014_10140202_37_dialog_content = "私たちと同じぐらいの年に見えるけど、すごく眠そうね。",
  ui_story_1014_10140202_38_dialog_content = "やはり以前と同じですね…",
  ui_story_1014_10140202_39_dialog_content = "彼女は戦闘のたびに大きく消耗してしまうのです。\nそろそろ休ませないと。",
  ui_story_1014_10140202_40_dialog_content = "皆さん、おやすみなさい。",
  ui_story_1014_10140202_41_dialog_content = "ソラヴァンの休憩室に連れて帰りましょう。",
  ui_story_1014_10140202_42_dialog_content = "ベルタ、そちらはどう？",
  ui_story_1014_10140202_43_dialog_content = "はい、カレン殿下！",
  ui_story_1014_10140202_44_dialog_content = "巨像をざっと検査したところです。",
  ui_story_1014_10140202_45_dialog_content = "ラファエル様の助手を務めてはおりますが、\n古代の機械の病については、やはり…",
  ui_story_1014_10140202_46_dialog_content = "ありがとう、ベルタ！",
  ui_story_1014_10140202_47_dialog_content = "どっちにしても、今のソラヴァンの状態じゃ、\nすぐには離陸できないよ。",
  ui_story_1014_10140202_48_dialog_content = "今日はここで態勢を整えよう。",
  ui_story_1014_10140202_49_dialog_content = "今日は…ここで寝るってこと？",
  ui_story_1014_10140202_50_dialog_content = "太陽だって見えないし、\nどうやって時間を把握すれば…",
  ui_story_1014_10140202_51_dialog_content = "まあ、いいわ。\nこれこそ、聖地に行くための修行みたいな物なのかも。",
  ui_story_1014_10140202_52_dialog_content = "聖地？あんな場所は聖地とは呼べません。",
  ui_story_1014_10140202_53_dialog_content = "あの地は古代、光霊と暗鬼が戦った地に築かれた要塞です。",
  ui_story_1014_10140202_54_dialog_content = "光霊たちはあの地で死闘を繰り広げ、\n徐々に暗鬼を極夜の領域に追いやったのです。",
  ui_story_1014_10140202_55_dialog_content = "白夜城の方は、無数の光霊の死体が埋まった穴の中で、\n賛歌を歌う趣味でもあるのでしょうか。",
  ui_story_1014_10140202_56_dialog_content = "違う、そうじゃないわ！",
  ui_story_1014_10140202_57_dialog_content = "極光遺跡には、世界のあらゆる極光の発祥の地だと言う伝説があるの。",
  ui_story_1014_10140202_58_dialog_content = "光霊が行くことのできる最も遠い居住地でもあり、\n光霊の起源をさかのぼれる場所でもあるわ。",
  ui_story_1014_10140202_59_dialog_content = "私が今話したこととは矛盾しませんね。",
  ui_story_1014_10140202_60_dialog_content = "それなら「死体が埋まっている穴」なんていう物じゃないでしょ！？",
  ui_story_1014_10140202_61_dialog_content = "（頭が痛い…暗力が強すぎるせいかな？\nそれとも彼女たちの口げんかのせいかな…？）",
  ui_story_1014_10140202_62_dialog_content = "ねえ、口げんかはそのくらいにして…",
  ui_story_1014_10140202_63_dialog_content = "ベルタ、来なさい。",
  ui_story_1014_10140202_64_dialog_content = "インゲル長官、落ち着いてください…",
  ui_story_1014_10140202_65_dialog_content = "暗くなってきたし、とりあえず巨像に戻ろう。",
  ui_story_1014_10140202_66_dialog_content = "…",
  ui_story_1014_10140202_67_dialog_content = "フン…",
  ui_story_1014_10140301_1_dialog_content = "<color=#e8d9bb>ソラヴァン・ブリッジ</color>",
  ui_story_1014_10140301_2_dialog_content = "<anim type=Shake>ふぁあ…</anim>",
  ui_story_1014_10140301_3_dialog_content = "（眠い…全然眠れなかったな）",
  ui_story_1014_10140301_4_dialog_content = "おはよう、PlayerName。",
  ui_story_1014_10140301_5_dialog_content = "あら、PlayerName、どうしたの？\nすごく疲れてるみたいだけど…",
  ui_story_1014_10140301_6_dialog_content = "眠れなかったようね？",
  ui_story_1014_10140301_7_dialog_content = "まあね…\nここの暗力が、来た時よりも強くなってるみたいなんだ。",
  ui_story_1014_10140301_8_dialog_content = "昨日の夜は暗鬼がソラヴァンの近くを通り過ぎたせいで、\n目が覚めちゃったんだよ。",
  ui_story_1014_10140301_9_dialog_content = "僕たちが狙われてるような気がして…",
  ui_story_1014_10140301_10_dialog_content = "辛かったでしょうね…\n今のうちにゆっくり寝ておくといいわ。",
  ui_story_1014_10140301_11_dialog_content = "うん、それもそうだね。",
  ui_story_1014_10140301_12_dialog_content = "じゃあ、少し寝てくるよ…",
  ui_story_1014_10140301_13_dialog_content = "<color=#e8d9bb>バンッ！バンッ！</color>",
  ui_story_1014_10140301_14_dialog_content = "<color=#e8d9bb>ドンッ――！</color>",
  ui_story_1014_10140301_15_dialog_content = "えっ、何…！？",
  ui_story_1014_10140301_16_dialog_content = "外で一体何が起こってるの！？",
  ui_story_1014_10140301_17_dialog_content = "ベルタを連れて様子を見てくるわ。",
  ui_story_1014_10140301_18_dialog_content = "僕が自分で見てくるよ！",
  ui_story_1014_10140301_19_dialog_content = "（暗鬼の様子が、前より攻撃的になってきてる！）",
  ui_story_1014_10140301_20_dialog_content = "このまま好き勝手させてはおけない！",
  ui_story_1014_10140301_21_dialog_content = "…あれ？ショーン？",
  ui_story_1014_10140301_22_dialog_content = "あれ？あっ、PlayerName！",
  ui_story_1014_10140301_23_dialog_content = "こんな場所で会うなんて奇遇だね！",
  ui_story_1014_10140301_24_dialog_content = "この白いデカブツ…もしかして、君の巨像？",
  ui_story_1014_10140301_25_dialog_content = "…僕の他に誰のだっていうの？",
  ui_story_1014_10140301_26_dialog_content = "オホン…とにかく、\nPlayerNameや皆に迷惑かけちゃったことは謝るよ。",
  ui_story_1014_10140301_27_dialog_content = "僕がドアをたたいたせいで、\nソラヴァンが壊れてないといいけど…後で確認してくるよ。",
  ui_story_1014_10140301_28_dialog_content = "（人騒がせだなぁ…）",
  ui_story_1014_10140301_29_dialog_content = "トワイライトシティ周辺のパトロールと、\n敵の掃除をしてたんだ。",
  ui_story_1014_10140301_30_dialog_content = "うちみたいな所は光力が弱くて、\n道に迷う人も良く出るんだ。",
  ui_story_1014_10140301_31_dialog_content = "僕の主な任務は、突発的な災害なんかで他の人とはぐれてしまった人々を見つけて、\nついでに暗鬼を倒すことなんだ。",
  ui_story_1014_10140301_32_dialog_content = "この白いデカブツを見つけた時、\nPlayerNameのことを思い出したよ！",
  ui_story_1014_10140301_33_dialog_content = "巨像が有れば、遠いところへ行くにも、便利なんでしょ？",
  ui_story_1014_10140301_34_dialog_content = "確かに便利だよ。\n巨像に乗れば、どこであろうとあっという間だね。",
  ui_story_1014_10140301_35_dialog_content = "すごいなぁ！\n僕も巨像みたいな乗り物が欲しいよ。",
  ui_story_1014_10140301_36_dialog_content = "てっきり、あの時の願いがかなったのかと思ったよ。",
  ui_story_1014_10140301_37_dialog_content = "よく考えてみたら、そうだよね。\nこんな所で新しい巨像が拾えるなんて、確かにあり得ないよ…",
  ui_story_1014_10140301_38_dialog_content = "フフフ…まったく、どう考えてもあり得ないわね。",
  ui_story_1014_10140301_39_dialog_content = "紹介するわ。この2人はカレンとベルタ。\n白夜城から来てくれてるの。",
  ui_story_1014_10140301_40_dialog_content = "ごきげんよう。",
  ui_story_1014_10140301_41_dialog_content = "もうあんな乱暴なマネはしないことね。",
  ui_story_1014_10140301_42_dialog_content = "ほ、本当にごめんなさい！",
  ui_story_1014_10140301_43_dialog_content = "こちらはインゲル中佐。胸に抱えている大きな箱はアクセリアよ。\n具体的には…",
  ui_story_1014_10140301_44_dialog_content = "インゲル！久しぶり！\nこんな場所でまた会うとは思わなかったよ！",
  ui_story_1014_10140301_45_dialog_content = "アクセリアはどう？体は大丈夫？",
  ui_story_1014_10140301_46_dialog_content = "知り合いだったの！？",
  ui_story_1014_10140301_47_dialog_content = "本当に驚きました。\nあなたも相変わらず元気いっぱいのようですね。",
  ui_story_1014_10140301_48_dialog_content = "フフン、もちろんだよ！トワイライトシティの生活は戦いなんだ！\n僕の拳術もかなり鍛えられたよ！",
  ui_story_1014_10140301_49_dialog_content = "楽観的なことも相変わらずですか…",
  ui_story_1014_10140301_50_dialog_content = "（今さら気付いたけど、もう眠気がどこかに行ってる…）",
  ui_story_1014_10140301_51_dialog_content = "もう一度ソラヴァンの状態を確認してくるよ。\nそれが終わったら出発できると思う。",
  ui_story_1014_10140301_52_dialog_content = "出発？まさか、君たちの目的地って、\nトワイライトシティ？",
  ui_story_1014_10140301_53_dialog_content = "話すと長くなるんだけど、とにかく、啓光本部から依頼を受けて、\nトワイライトシティへ「取引」をしに行くところなんだ。",
  ui_story_1014_10140301_54_dialog_content = "それなら僕が案内するよ。\nこの辺には詳しいからね！",
  ui_story_1014_10140301_55_dialog_content = "それに、暗鬼と戦う時にも役に立てるよ。\n途中で何か緊急事態があったら、僕に任せて。",
  ui_story_1014_10140301_56_dialog_content = "それは本当に助かるよ！",
  ui_story_1014_10140301_57_dialog_content = "うーん…",
  ui_story_1014_10140301_58_dialog_content = "巨像の状態はどう？",
  ui_story_1014_10140301_59_dialog_content = "うん、全体的には特に問題ないね。出発できるよ。",
  ui_story_1014_10140301_60_dialog_content = "い、入口のゲートは？",
  ui_story_1014_10140301_61_dialog_content = "ゲートもまったく問題ないよ！\n心配しなくて大丈夫。",
  ui_story_1014_10140301_62_dialog_content = "ふぅ…ならよかった。僕もほっとしたよ。",
  ui_story_1014_10140301_63_dialog_content = "<color=#e8d9bb>ガサッ…</color>",
  ui_story_1014_10140301_64_dialog_content = "何かいる！？",
  ui_story_1014_10140301_65_dialog_content = "まただ…！",
  ui_story_1014_10140301_66_dialog_content = "<anim type=Shake><size=45>グオオ！！！</size></anim>",
  ui_story_1014_10140301_67_dialog_content = "わざわざ向こうから来てくれるなんてね！",
  ui_story_1014_10140301_68_dialog_content = "じゃあ、僕は「掃除」を続けるよ。",
  ui_story_1014_10140402_1_dialog_content = "はあっ――！",
  ui_story_1014_10140402_2_dialog_content = "ざっとこんなもんかな。",
  ui_story_1014_10140402_3_dialog_content = "この前会った時は、\n君のこと、こんなに強いと思ってなかったよ！",
  ui_story_1014_10140402_4_dialog_content = "ヘヘ。これで無事に出発できるね。",
  ui_story_1014_10140402_5_dialog_content = "ところで、本部がPlayerNameに取引を任せたってことは…",
  ui_story_1014_10140402_6_dialog_content = "先にこっちの上層部に連絡しとかないと。",
  ui_story_1014_10140402_7_dialog_content = "あ、別にPlayerNameのことを疑うつもりはないんだ！",
  ui_story_1014_10140402_8_dialog_content = "でも、トワイライトシティはよそ者を警戒するからね。",
  ui_story_1014_10140402_9_dialog_content = "事前に連絡しておいた方が、\n町に入る時にラクになるよ。",
  ui_story_1014_10140402_10_dialog_content = "なるほどね。じゃあ、お願いするよ。",
  ui_story_1014_10140402_11_dialog_content = "<color=#e8d9bb>一方、ソラヴァン・ブリッジ</color>",
  ui_story_1014_10140402_12_dialog_content = "（…彼は確かに、以前よりだいぶ強くなっているようですね）",
  ui_story_1014_10140402_13_dialog_content = "インゲル、ショーンを観察しているのですか？",
  ui_story_1014_10140402_14_dialog_content = "アクセリア？急に背後に現れると驚きますよ…",
  ui_story_1014_10140402_15_dialog_content = "ごめんなさい。",
  ui_story_1014_10140402_16_dialog_content = "休むだけより、少し体を動かさなければと思いました。",
  ui_story_1014_10140402_17_dialog_content = "何だか懐かしいですね。私たち3人が\n「<color=#FFB400>啓明の星計画</color>」のために訓練していた日のことが思い出されます。",
  ui_story_1014_10140402_18_dialog_content = "まだ「卒業」から5年しか経っていませんが、\nあの時のことは忘れかけていました。",
  ui_story_1014_10140402_19_dialog_content = "アクセリアの頭の中は、\nいつも命令でいっぱいですからね。",
  ui_story_1014_10140402_20_dialog_content = "インゲルこそ…",
  ui_story_1014_10140402_21_dialog_content = "ですが、それもアクセリアの強みです。",
  ui_story_1014_10140402_22_dialog_content = "ショーンも含めて、私たちはそれぞれの立場で、\n自分の強みを発揮しています。",
  ui_story_1014_10140402_23_dialog_content = "フン…あんな落ちこぼれもですか。",
  ui_story_1014_10140402_24_dialog_content = "…ですが、確かに彼は楽しんでいるようです。",
  ui_story_1014_10140402_25_dialog_content = "皆、お待たせ。これで出発できるよ！",
  ui_story_1014_10140402_26_dialog_content = "トワイライトシティの啓光の皆も、歓迎するって！",
  ui_story_1014_10140402_27_dialog_content = "！？",
  ui_story_1014_10140402_28_dialog_content = "アクセリア！？目が覚めてたの！？",
  ui_story_1014_10140402_29_dialog_content = "ま、ま、まさか…\nさっき僕が暗鬼と戦ってたところ、全部見てた？",
  ui_story_1014_10140402_30_dialog_content = "はい。",
  ui_story_1014_10140402_31_dialog_content = "どうだった？\n僕、本部にいた時よりもずっと強くなったんじゃない？",
  ui_story_1014_10140402_32_dialog_content = "また僕と手合わせしてみない？\n今度はどっちが勝つかな？",
  ui_story_1014_10140402_33_dialog_content = "それは止めておきます。",
  ui_story_1014_10140402_34_dialog_content = "ところで、僕の知らない小型ロボットを連れてるね？",
  ui_story_1014_10140402_35_dialog_content = "この3体は「キュービック」と言います。",
  ui_story_1014_10140402_36_dialog_content = "えっ？4体いるよね？",
  ui_story_1014_10140402_37_dialog_content = "4つ目の小型ロボットは、\nアクセリアのソデをまくる用です。",
  ui_story_1014_10140402_38_dialog_content = "キュービックが3体だろうと4体だろうと同じことです。",
  ui_story_1014_10140402_39_dialog_content = "静かにしてください、ショーン。\nアクセリアは「取引の品」としてトワイライトシティ支援に送られてきたのです。",
  ui_story_1014_10140402_40_dialog_content = "アクセリアの身体を消耗させないように。",
  ui_story_1014_10140402_41_dialog_content = "本当！？",
  ui_story_1014_10140402_42_dialog_content = "それじゃ、僕がアクセリアの先輩になるね！",
  ui_story_1014_10140402_43_dialog_content = "どう？何か僕に聞きたいことはある？",
  ui_story_1014_10140402_44_dialog_content = "トワイライトシティの現在の軍事体制は？",
  ui_story_1014_10140402_45_dialog_content = "それは…僕は下っ端の仕事しかしてないから…",
  ui_story_1014_10140402_46_dialog_content = "では、トワイライトシティ近辺に特殊な形態の暗鬼は存在しますか？",
  ui_story_1014_10140402_47_dialog_content = "それも僕はあまり…",
  ui_story_1014_10140402_48_dialog_content = "他の質問はないの？\nトワイライトシティのグルメとか、歴史とか、観光スポットとか…",
  ui_story_1014_10140402_49_dialog_content = "しゃべるだけムダですね…",
  ui_story_1014_10140501_1_dialog_content = "<color=#e8d9bb>トワイライトシティ・近郊</color>",
  ui_story_1014_10140501_2_dialog_content = "殿下、過去の巡視記録によると、\nこの先がトワイライトシティです。",
  ui_story_1014_10140501_3_dialog_content = "レオ騎士団長がすぐに出迎えにくるはずよ。\nPlayerName、着陸しましょう。",
  ui_story_1014_10140501_4_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_1014_10140501_5_dialog_content = "何の音！？",
  ui_story_1014_10140501_6_dialog_content = "爆発ですね。",
  ui_story_1014_10140501_7_dialog_content = "アクセリア、外が混乱しているようです。\nあなたは休眠カプセルに戻ってください。",
  ui_story_1014_10140501_8_dialog_content = "しかし、今の状況はアクセリアを必要としているように思えます。",
  ui_story_1014_10140501_9_dialog_content = "ショーン、一体何が起こったのですか？",
  ui_story_1014_10140501_10_dialog_content = "何でもないよ。皆、落ち着いて。",
  ui_story_1014_10140501_11_dialog_content = "また暗鬼に囲まれてるだけだよ。",
  ui_story_1014_10140501_12_dialog_content = "でも…下の人たちが立ち止まってるみたいだけど？",
  ui_story_1014_10140501_13_dialog_content = "顔をあげて、何かを見てるみたい。",
  ui_story_1014_10140501_14_dialog_content = "きっと巨像がみんなの目を引いてるんだよ！",
  ui_story_1014_10140501_15_dialog_content = "<color=#e8d9bb>ブーン…</color>",
  ui_story_1014_10140501_16_dialog_content = "様子がおかしいわね。",
  ui_story_1014_10140501_17_dialog_content = "PlayerName、早くどこかに着陸して。",
  ui_story_1014_10140501_18_dialog_content = "わ、分かった…皆、つかまって！",
  ui_story_1014_10140501_19_dialog_content = "ちょっとしたトラブルはあったけど、\nようこそトワイライトシティへ！",
  ui_story_1014_10140501_20_dialog_content = "ここはアストラ大陸の辺境に位置する、\n快適な気候と、質素な暮らしの…",
  ui_story_1014_10140501_21_dialog_content = "どけ！どけ、どいてくれ！",
  ui_story_1014_10140501_22_dialog_content = "ゴホッ、ゴホッ…すごいホコリ！",
  ui_story_1014_10140501_23_dialog_content = "アハハ…こういうことも時々起こるんだ。",
  ui_story_1014_10140501_24_dialog_content = "あの、どこに行こうとしてるの？\n手を貸そうか？",
  ui_story_1014_10140501_25_dialog_content = "ここからトワイライトシティまでは遠いんですか？",
  ui_story_1014_10140501_26_dialog_content = "そう遠くないよ、ここが外周区だから！\n町の外の集落から来たの？",
  ui_story_1014_10140501_27_dialog_content = "分かりました。ありがとうございます！",
  ui_story_1014_10140501_28_dialog_content = "待って。トワイライトシティに行くなら、\n僕たちについて来れば？",
  ui_story_1014_10140501_29_dialog_content = "悪いが、今は一刻を争ってるんだ。",
  ui_story_1014_10140501_30_dialog_content = "君たちも急いで避難した方がいいぞ。",
  ui_story_1014_10140501_31_dialog_content = "避難？",
  ui_story_1014_10140501_32_dialog_content = "空の色がおかしいだろう。\n<color=#FFB400>極光爆発</color>の前兆だ。",
  ui_story_1014_10140501_33_dialog_content = "避難が遅れて巻き込まれても、誰も助けちゃくれないぞ。",
  ui_story_1014_10140501_34_dialog_content = "極光爆発…？",
  ui_story_1014_10140501_35_dialog_content = "教科書でしか読んだことがないけれど…\n極光がよく見られる北境でも、滅多に起こるものではないわ。",
  ui_story_1014_10140501_36_dialog_content = "辺境に住み続けている民でもない限り、\n経験することはないでしょうね。",
  ui_story_1014_10140501_37_dialog_content = "<color=#e8d9bb>ピー、ピー</color>",
  ui_story_1014_10140501_38_dialog_content = "トワイライトシティの警報だ！",
  ui_story_1014_10140501_39_dialog_content = "みんなのスピードじゃ、\n今日中にトワイライトシティにたどり着くのは無理だよ。",
  ui_story_1014_10140501_40_dialog_content = "僕は啓光のトワイライトシティ駐屯軍、下士官のショーン。\n僕のことを信じてくれるなら…",
  ui_story_1014_10140501_41_dialog_content = "避難できるところに案内するよ！",
  ui_story_1014_10140501_42_dialog_content = "信じる？君たちを？まだ子どもじゃないか。",
  ui_story_1014_10140501_43_dialog_content = "でも、私たちは誰も戦えないのよ？\nもしまた暗鬼に襲われたら…",
  ui_story_1014_10140501_44_dialog_content = "暗鬼？まさか、君たちの集落も…",
  ui_story_1014_10140501_45_dialog_content = "…そうよ。このままじゃ、\nこの辺りの集落はどんどん少なくなっていくでしょうね。",
  ui_story_1014_10140501_46_dialog_content = "トワイライトシティを目指す以外に、生き残る方法はないわ。",
  ui_story_1014_10140501_47_dialog_content = "ムダ話はここまでだ。俺たちは一時的に身を寄せるだけ…",
  ui_story_1014_10140501_48_dialog_content = "いつの日か、きっとまた戻る…",
  ui_story_1014_10140501_49_dialog_content = "<color=#e8d9bb>ゴゴゴゴ…</color>",
  ui_story_1014_10140501_50_dialog_content = "今度は地中から音がします。",
  ui_story_1014_10140501_51_dialog_content = "グァ…",
  ui_story_1014_10140501_52_dialog_content = "<anim type=Shake><size=45>グォォ！！！！！！</size></anim>",
  ui_story_1014_10140501_53_dialog_content = "暗鬼だ…暗鬼が追いかけてきやがった！",
  ui_story_1014_10140501_54_dialog_content = "エネルギーの乱れに乗じて来たと言うこと？\nずいぶん戦略的ね…",
  ui_story_1014_10140501_55_dialog_content = "ベルタ。",
  ui_story_1014_10140501_56_dialog_content = "はい！",
  ui_story_1014_10140501_57_dialog_content = "私が皆の撤退を援護するわ！",
  ui_story_1014_10140501_58_dialog_content = "逃げに徹していては戦線が長く維持できません。",
  ui_story_1014_10140501_59_dialog_content = "アクセリアに戦闘許可を。\n許可が出ないようなら、無理にでも…",
  ui_story_1014_10140501_60_dialog_content = "いきなり戦うことを考えないで！",
  ui_story_1014_10140501_61_dialog_content = "突撃なんてしたら、この丸腰の人たちはどうするの？",
  ui_story_1014_10140501_62_dialog_content = "アクセリアには彼らを防衛する能力があります。",
  ui_story_1014_10140501_63_dialog_content = "安心してください。すぐに終わります。",
  ui_story_1014_10140501_64_dialog_content = "無理なものは無理よ！",
  ui_story_1014_10140501_65_dialog_content = "ベルタ、アクセリア、二手に分かれよう。",
  ui_story_1014_10140501_66_dialog_content = "ベルタ、カレン、ショーン、\n君たちはこの人たちを避難させて。",
  ui_story_1014_10140501_67_dialog_content = "アクセリア、インゲル、バイス、僕の4人で、\n暗鬼を迎え撃つ！",
  ui_story_1014_10140501_68_dialog_content = "了解。",
  ui_story_1014_10140501_69_dialog_content = "そちらの戦力を消耗させる必要などありません。",
  ui_story_1014_10140501_70_dialog_content = "暗鬼どもは、\n我らアイアンソーン騎士団にお任せを。",
  ui_story_1014_10140501_71_dialog_content = "はるばるお越しいただき、感謝いたします。\n被害がないようで何よりです。",
  ui_story_1014_10140501_72_dialog_content = "レオ騎士団長、ちょうどいいところに来たわね。\n私たちの案内の前に、共闘して暗鬼を撃退しましょう。",
  ui_story_1014_10140501_73_dialog_content = "もちろんです。このような状況ですので、\n馬から下りずにいることをお許しください、カレン殿下。",
  ui_story_1014_10140501_74_dialog_content = "構わないわ、形式的な忠誠などいらない。\n己の名に誓いなさい。",
  ui_story_1014_10140501_75_dialog_content = "ハハハ…私が騎士でいられるのは、名などではなく、\nこのトワイライトシティのおかげです。",
  ui_story_1014_10140501_76_dialog_content = "騎士団総員！剣を掲げよ！",
  ui_story_1014_10140501_77_dialog_content = "戦場において、求められることはただ1つ――",
  ui_story_1014_10140501_78_dialog_content = "己の力の最後まで、\n暗鬼を打ち滅ぼすことだ！",
  ui_story_1014_10140501_79_dialog_content = "突撃するぞ！",
  ui_story_1014_10140602_1_dialog_content = "陣形を保て！",
  ui_story_1014_10140602_2_dialog_content = "側面の敵から片付ける！",
  ui_story_1014_10140602_3_dialog_content = "はっ！",
  ui_story_1014_10140602_4_dialog_content = "また暗鬼の大群だ！\nさっきよりも数が多いよ！",
  ui_story_1014_10140602_5_dialog_content = "このままじゃ苦戦しそうだ。\n後退した方がいいんじゃない？",
  ui_story_1014_10140602_6_dialog_content = "私にも見えた。確かに数は多いな。",
  ui_story_1014_10140602_7_dialog_content = "それじゃ…",
  ui_story_1014_10140602_8_dialog_content = "騎士団総員！重装備を下ろせ、突撃の用意だ！",
  ui_story_1014_10140602_9_dialog_content = "はっ！",
  ui_story_1014_10140602_10_dialog_content = "えっ、突撃？今から？",
  ui_story_1014_10140602_11_dialog_content = "僕たちの戦力で、あの群れを相手にするのは\nよくないと思うんだけど…",
  ui_story_1014_10140602_12_dialog_content = "「お客人」たちは来なくていい。\nここでしかと、見物していろ。",
  ui_story_1014_10140602_13_dialog_content = "円すい形で2隊に分かれる！\n1隊は私に、もう1隊は副官に続け！",
  ui_story_1014_10140602_14_dialog_content = "敵陣を突破した後、さらに隊を分ける！",
  ui_story_1014_10140602_15_dialog_content = "さあ、私が持つ旗槍を見よ！",
  ui_story_1014_10140602_16_dialog_content = "アイアンソーン騎士団、突撃！",
  ui_story_1014_10140602_17_dialog_content = "<size=50>うおおおお！！！</size>",
  ui_story_1014_10140602_18_dialog_content = "本当に暗鬼の大群に突っ込んじゃった…！\nこんなの…無謀すぎじゃ？",
  ui_story_1014_10140602_19_dialog_content = "そうでもないようね。\nよく見て。",
  ui_story_1014_10140602_20_dialog_content = "止まる気配が無いわ。",
  ui_story_1014_10140602_21_dialog_content = "本当ですね！暗鬼があれだけいるのに…\n騎士団の攻撃を防ぎきれていません！",
  ui_story_1014_10140602_22_dialog_content = "まるでナイフで切り裂かれたみたいに…",
  ui_story_1014_10140602_23_dialog_content = "一体どうやってるの！？",
  ui_story_1014_10140602_24_dialog_content = "分かった気がするわ。\nベルタの表現がふさわしいわね。",
  ui_story_1014_10140602_25_dialog_content = "彼らはナイフのようなもの…",
  ui_story_1014_10140602_26_dialog_content = "肉を切る時、ナイフと肉のどちらが大きいかなど、誰も気にしない。",
  ui_story_1014_10140602_27_dialog_content = "鋭い刃を当てれば切れる、ただそれだけ。",
  ui_story_1014_10140602_28_dialog_content = "当てれば切れる…",
  ui_story_1014_10140602_29_dialog_content = "騎士団長と部隊の半分が戻って来たわ。",
  ui_story_1014_10140602_30_dialog_content = "<color=#e8d9bb>ザッ、ザッ、ザッ…</color>",
  ui_story_1014_10140602_31_dialog_content = "どうだ、お客人？\n突撃という選択も、悪くなかっただろう？",
  ui_story_1014_10140602_32_dialog_content = "戦場は単純な足し算、引き算ではない。\n同じ力でも、戦術次第で力を発揮できるのさ。",
  ui_story_1014_10140602_33_dialog_content = "ここは中央から離れた辺境、\n私たちに暗鬼と正面から勝負するだけの力はない。",
  ui_story_1014_10140602_34_dialog_content = "ただ、暗鬼は戦術を知らないが、我々は知っている。\nそれこそが我々の強みだ。",
  ui_story_1014_10140602_35_dialog_content = "戦術…じゃあ、さっきの突撃はどうしてうまくいくと思ったの？",
  ui_story_1014_10140602_36_dialog_content = "暗鬼の種類をよく理解しているからだ。",
  ui_story_1014_10140602_37_dialog_content = "奴らは攻撃的で、群れで行動する。\nだが、弱点もはっきりしている。攻められることには弱いのさ。",
  ui_story_1014_10140602_38_dialog_content = "だから、奴らを相手にする時は、\nたとえ向こうが多勢でも、こちらから打って出る必要がある。",
  ui_story_1014_10140602_39_dialog_content = "我々は突撃して戦力を一点に集中させ、\n機先を制して、敵の戦力を削る。",
  ui_story_1014_10140602_40_dialog_content = "暗鬼の陣形を分断し、\n敵の戦力を分散させれば、さらに戦いが有利になる。",
  ui_story_1014_10140602_41_dialog_content = "敵の背後に残った部隊が見えるか？",
  ui_story_1014_10140602_42_dialog_content = "彼らが暗鬼の周囲を旋回し、戦場を分断しながら浮いた敵を各個撃破する。\nそうして戦場をさらに乱すのさ。",
  ui_story_1014_10140602_43_dialog_content = "すごい…暗鬼との戦いって、\nここまでたくさん考えないといけなかったんだ。",
  ui_story_1014_10140602_44_dialog_content = "僕たちの戦力はどうみても暗鬼より劣ってるのに、\n戦場は互角に見える…",
  ui_story_1014_10140602_45_dialog_content = "それこそ戦力より戦術が重要と言うことさ。",
  ui_story_1014_10140602_46_dialog_content = "しかし、私より先に暗鬼の動きを察知するとは。\nお客人、なかなかやるようだ。",
  ui_story_1014_10140602_47_dialog_content = "戦場ではその能力が役に立ちそうだな。",
  ui_story_1014_10140602_48_dialog_content = "それは別に、自慢するようなことじゃないんだ。",
  ui_story_1014_10140602_49_dialog_content = "僕は君たち光霊と違う、\n空の末裔だからね。",
  ui_story_1014_10140602_50_dialog_content = "空の末裔だと？あの伝説の？",
  ui_story_1014_10140602_51_dialog_content = "ハハハハハ…面白い！\n本の中の人物が現実で見られるとは！",
  ui_story_1014_10140602_52_dialog_content = "では、空の末裔。感知能力を使って、\n我々が次に何をしようとしているか当ててみるか？",
  ui_story_1014_10140602_53_dialog_content = "えっと…敵が陣形を立て直す前に追撃する？",
  ui_story_1014_10140602_54_dialog_content = "いや、後退だ。",
  ui_story_1014_10140602_55_dialog_content = "えっ？どうして？せっかく優勢なのに。",
  ui_story_1014_10140602_56_dialog_content = "目の前の戦場だけに囚われてはいかん。",
  ui_story_1014_10140602_57_dialog_content = "我々の目的はすべての暗鬼を迎え撃つことだ。\n今のままでは足りない。",
  ui_story_1014_10140602_58_dialog_content = "後方の地形はより険しく狭い道になっている。\n戦場はそちらに移動していくことになるだろう。",
  ui_story_1014_10140602_59_dialog_content = "その前にしっかりと手はずを整えなければならない。",
  ui_story_1014_10140602_60_dialog_content = "手を貸してくれるか？",
  ui_story_1014_10140602_61_dialog_content = "もちろん！君の戦術をもっと見てみたいしね！",
  ui_story_1014_10140602_62_dialog_content = "ええ。もとより、私たちも暗鬼と戦うつもりだったもの。",
  ui_story_1014_10140602_63_dialog_content = "手を貸すかどうかはどちらでも構いませんが、\nそれより一つ、問題が発生しました…",
  ui_story_1014_10140602_64_dialog_content = "ショーンの大バカ者を見かけませんでしたか？",
  ui_story_1014_10140602_65_dialog_content = "<size=45>うおぉぉ！！！</size>",
  ui_story_1014_10140602_66_dialog_content = "さあ、残りはどいつだ！！",
  ui_story_1014_10140602_67_dialog_content = "啓光の兵士が、これほど強いとは思わなかったぞ。",
  ui_story_1014_10140602_68_dialog_content = "えっ？あっ…ほめてくれてありがとう！",
  ui_story_1014_10140602_69_dialog_content = "我らアイアンソーン騎士団のいる戦場で、\nここまで目立てるとはな。",
  ui_story_1014_10140602_70_dialog_content = "お前のようなずば抜けた戦士なら、\nほめられて当然だ。",
  ui_story_1014_10140602_71_dialog_content = "そ、そう？いつもは滅多にほめられないんだけど…",
  ui_story_1014_10140602_72_dialog_content = "だが、どうしてついて来た？\n団長は残っていろと言っただろう？",
  ui_story_1014_10140602_73_dialog_content = "えっ、そうだったの！？",
  ui_story_1014_10140602_74_dialog_content = "見ろ。お前の仲間は皆あそこだ。",
  ui_story_1014_10140602_75_dialog_content = "あっ、思い出した。\n「お客人」はついてこなくていいって言ってたね。",
  ui_story_1014_10140602_76_dialog_content = "だけど、僕はよそ者じゃない！\n僕だってトワイライトシティで暮らしてるんだ！",
  ui_story_1014_10140602_77_dialog_content = "…",
  ui_story_1014_10140602_78_dialog_content = "お前、あまり賢くないと言われたことはないか？",
  ui_story_1014_10140602_79_dialog_content = "えっ、あるけど…",
  ui_story_1014_10140602_80_dialog_content = "それぐらいは理解できるみたいだな…",
  ui_story_1014_10140602_81_dialog_content = "まあ、いい。お前のおかげで戦局はかなり有利になった。",
  ui_story_1014_10140602_82_dialog_content = "俺たちの任務は暗鬼を包囲することだけだったが、\nこの様子なら、全滅も難しくなさそうだ。",
  ui_story_1014_10140602_83_dialog_content = "全滅させるに決まってるよ！\n1匹たりとも逃がすわけにはいかない！",
  ui_story_1014_10140602_84_dialog_content = "すさまじい意気込みだ。素晴らしい。\nそいつはいいことだぞ。",
  ui_story_1014_10140602_85_dialog_content = "アイアンソーン騎士団と\nレオ騎士団長の名前は前から聞いてるよ。",
  ui_story_1014_10140602_86_dialog_content = "英雄みたいな部隊と一緒に戦えるんだ。\nそりゃもう、張り切っちゃうよ！",
  ui_story_1014_10140602_87_dialog_content = "クロスボウを草むらに隠せ。\n仕込みはこれでいい…",
  ui_story_1014_10140602_88_dialog_content = "あいつらも戻ってきた、頃合いだ。",
  ui_story_1014_10140602_89_dialog_content = "<color=#e8d9bb>ザッ、ザッ、ザッ…</color>",
  ui_story_1014_10140602_90_dialog_content = "団長。",
  ui_story_1014_10140602_91_dialog_content = "よくやった。想像以上の戦いぶりだ。",
  ui_story_1014_10140602_92_dialog_content = "啓光の戦士の協力のおかげです。",
  ui_story_1014_10140602_93_dialog_content = "いやぁ、それほどでも…",
  ui_story_1014_10140602_94_dialog_content = "ああ、見ていた。\nあれだけ目立っていれば、気付かない方がおかしい。",
  ui_story_1014_10140602_95_dialog_content = "君は啓光の士官か？",
  ui_story_1014_10140602_96_dialog_content = "はい！トワイライトシティ駐屯軍、\nショーン少尉です！",
  ui_story_1014_10140602_97_dialog_content = "トワイライトシティ駐屯軍か…\nすぐ近くにこれほど勇猛な戦士がいるとは知らなかった。",
  ui_story_1014_10140602_98_dialog_content = "と、とんでもないです！\n僕は仲間の中じゃパっとしないし、実戦経験も少ないし…",
  ui_story_1014_10140602_99_dialog_content = "レオ騎士団長のような人が、\n僕のことなんか知らなくて当然です。",
  ui_story_1014_10140602_100_dialog_content = "私のことを知っているようだな。",
  ui_story_1014_10140602_101_dialog_content = "もちろんです！トワイライトシティで、\nアイアンソーン騎士団の名前を知らない者はいません！",
  ui_story_1014_10140602_102_dialog_content = "そうか。ならば、我々の騎士団に入るか？",
  ui_story_1014_10140602_103_dialog_content = "えっ？",
  ui_story_1014_10140602_104_dialog_content = "優れた戦士なら、兵舎で寝転がって無為に過ごすよりも、\n戦場に立って力を発揮するべきだ。",
  ui_story_1014_10140602_105_dialog_content = "アイアンソーン騎士団に入れば、\n1ヵ月のうちに、お前の名をトワイライトシティ中にとどろかせてやれる。",
  ui_story_1014_10140602_106_dialog_content = "それは…でも…",
  ui_story_1014_10140602_107_dialog_content = "オホン…レオ騎士団長。\n所属を越えた引き抜きは協定に違反します。",
  ui_story_1014_10140602_108_dialog_content = "こちらの兵士を引き抜くというのであれば、\nせめて水面下でやっていただきたいものです。",
  ui_story_1014_10140602_109_dialog_content = "ハハハ、すまない。\nだが、別に人目をはばかるようなことでもないだろう。",
  ui_story_1014_10140602_110_dialog_content = "白夜と啓光は身を寄せる場所こそ違うが、\n最終的な敵が暗鬼であることに違いはないのだからな。",
  ui_story_1014_10140602_111_dialog_content = "私はただ、有望な兄弟に\nより良い居場所を与えてやりたかっただけだ。",
  ui_story_1014_10140602_112_dialog_content = "もちろん、そちらの活躍も見事だった。\nその気があれば、アイアンソーン騎士団はいつでも歓迎しよう。",
  ui_story_1014_10140602_113_dialog_content = "はぁ…アイアンソーン騎士団の団長が\nここまで口のまわる方だとは。",
  ui_story_1014_10140602_114_dialog_content = "いっそ、カナン城で政治家になられてはいかがですか？\nあなたの方こそ、より良い居場所を手に入れてもらいたいところです。",
  ui_story_1014_10140602_115_dialog_content = "政治家か、悪くないな。考えておこう。",
  ui_story_1014_10140602_116_dialog_content = "眠くなりました…",
  ui_story_1014_10140602_117_dialog_content = "えっ？",
  ui_story_1014_10140602_118_dialog_content = "ふぁあ――アクセリアは眠くなってしまいました。",
  ui_story_1014_10140602_119_dialog_content = "よりによってこんな時に…",
  ui_story_1014_10140602_120_dialog_content = "仕方ありませんね。\n休眠カプセルに戻りましょう、アクセリア。",
  ui_story_1014_10140602_121_dialog_content = "はい。皆さん、がんばってください。",
  ui_story_1014_10140602_122_dialog_content = "アクセリアが起きたら、またお手伝いしますから。",
  ui_story_1014_10140602_123_dialog_content = "余計なことは考えないで、ゆっくり休みなさい。",
  ui_story_1014_10140602_124_dialog_content = "PlayerName、休眠カプセルの用意を。",
  ui_story_1014_10140602_125_dialog_content = "あっ、うん！",
  ui_story_1014_10140602_126_dialog_content = "箱の中に入れるのか？",
  ui_story_1014_10140602_127_dialog_content = "よそから人が来たと思えば、次々と驚かせてくれるな。",
  ui_story_1014_10140602_128_dialog_content = "アクセリアは身体が弱いから、\n普段はこの「休眠カプセル」に入って休んでないといけないんだって。",
  ui_story_1014_10140602_129_dialog_content = "それなら、なぜこんな危険な場所に連れてきた？",
  ui_story_1014_10140602_130_dialog_content = "彼女を安全にトワイライトシティまで\n連れていくように頼まれてるんだ。",
  ui_story_1014_10140602_131_dialog_content = "なるほど、啓光の任務か。\nならば、それ以上は聞かないでおこう。",
  ui_story_1014_10140602_132_dialog_content = "ちょうど、おしゃべりはおしまいという時だ。\n奴らが潜んでいる気配を感じる。",
  ui_story_1014_10140602_133_dialog_content = "暗鬼が目視できるようになる前に、\nここに鉄柵を設置しなければならん。",
  ui_story_1014_10140602_134_dialog_content = "私たちも手伝うわ。何をすれば？",
  ui_story_1014_10140602_135_dialog_content = "殿下とご友人方は自由に遊撃していただければ結構です。\n騎士団の動きに合わせる必要はありません。",
  ui_story_1014_10140602_136_dialog_content = "ご身分を考えれば、\n戦場の指揮権をお渡しするべきでしょうが…",
  ui_story_1014_10140602_137_dialog_content = "目下は特殊な状況ですので、騎士団が対応できない可能性があります。\n差し出がましい真似をお許しください。",
  ui_story_1014_10140602_138_dialog_content = "…",
  ui_story_1014_10140602_139_dialog_content = "勝利に導ける力を持つ者が指揮を執るべきよ。\n私に余計な気を使う必要は無いわ。",
  ui_story_1014_10140602_140_dialog_content = "私たちが自由に戦うと言うのなら…\n防衛線の東側を援護するわね。",
  ui_story_1014_10140602_141_dialog_content = "私の推測が正しければ、\n防衛線が相対的に手薄なはず。",
  ui_story_1014_10140602_142_dialog_content = "東側…ええ、その通りです。\n騎士団も人手が足りません。あそこの戦局は私も危惧しています。",
  ui_story_1014_10140602_143_dialog_content = "カレン殿下にそこまで見抜かれるとは…",
  ui_story_1014_10140602_144_dialog_content = "血筋で騎士を統べる立場を認められた訳ではないの。\n私を単なる「白夜城の姫君」などと思わないことね。",
  ui_story_1014_10140602_145_dialog_content = "もちろんです。\n白夜城騎士としての高名を信じております。",
  ui_story_1014_10140602_146_dialog_content = "私たちは同じ栄光を背に負い、戦っているものです。",
  ui_story_1014_10140602_147_dialog_content = "PlayerName、ここは戦場の後方で、安全になるはず。\nアクセリアの休眠カプセルは、ここに置いておきましょう。",
  ui_story_1014_10140602_148_dialog_content = "うん、分かった。",
  ui_story_1014_10140602_149_dialog_content = "騎士団の配置は、\n東側の防衛線が比較的手薄になっているわ。",
  ui_story_1014_10140602_150_dialog_content = "私たちで戦力の穴を埋めましょう。",
  ui_story_1014_10140602_151_dialog_content = "はい、殿下。",
  ui_story_1014_10140602_152_dialog_content = "カレン、あの騎士団長の指揮に合わせるんだね。",
  ui_story_1014_10140602_153_dialog_content = "彼は経験豊富よ。あなたも見たでしょう。\n今この戦場では、彼の指示に従った方が勝てる可能性が高いわ。",
  ui_story_1014_10140602_154_dialog_content = "でも、私たちに具体的な仕事はくれなかったわね。",
  ui_story_1014_10140602_155_dialog_content = "ええ。そうなるでしょうね。",
  ui_story_1014_10140602_156_dialog_content = "え、どうしてそう思うの？",
  ui_story_1014_10140602_157_dialog_content = "私と意識して距離を保っているように感じるわ。",
  ui_story_1014_10140602_158_dialog_content = "私に命令することもないでしょうけれど、\nおもねることもないでしょうね。",
  ui_story_1014_10140602_159_dialog_content = "私は白夜城城主の娘だから。",
  ui_story_1014_10140602_160_dialog_content = "そうなんだ？\nよく分からないけど、それって悪いこと？",
  ui_story_1014_10140602_161_dialog_content = "私にも分からないわ。",
  ui_story_1014_10140602_162_dialog_content = "彼がただの礼儀を重んじない、\n純粋な戦士だと言うならよかったけれど。",
  ui_story_1014_10140602_163_dialog_content = "はるか遠くの辺境に身を置いて、\n目に入るのは戦場だけ、と言うような…",
  ui_story_1014_10140602_164_dialog_content = "でも、彼はそうではないわ。\nむしろ、私の身分を確かに気にしている。",
  ui_story_1014_10140602_165_dialog_content = "臣下として「服従」するべき立場になるはずのところを、\n「尊重」という形式でうまく距離を保っている。",
  ui_story_1014_10140602_166_dialog_content = "だから、私も彼を尊重して、\n彼の戦術に協力することしかできないの。",
  ui_story_1014_10140602_167_dialog_content = "なんだか複雑ね。\nそういうのが戦場政治って言うのかしら？",
  ui_story_1014_10140602_168_dialog_content = "ふさわしい言葉ね。",
  ui_story_1014_10140602_169_dialog_content = "それが白夜城の悲哀かもしれないわ。\n私たちはどこへ行っても、政治から離れられない。",
  ui_story_1014_10140602_170_dialog_content = "<color=#e8d9bb>ゴォォ――</color>",
  ui_story_1014_10140602_171_dialog_content = "！！！",
  ui_story_1014_10140602_172_dialog_content = "何の音！？",
  ui_story_1014_10140602_173_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1014_10140602_174_dialog_content = "何かがこっちに来る！",
  ui_story_1014_10140602_175_dialog_content = "暗力がすごく強くなってきた…\nかなりの数の敵だよ！",
  ui_story_1014_10140602_176_dialog_content = "しかも…1匹、かなり大きい奴がいる！",
  ui_story_1014_10140701_1_dialog_content = "アイアンソーン騎士団、迎撃するぞ！",
  ui_story_1014_10140701_2_dialog_content = "私の命令があるまで、\n誰も隊列を離れてはならん！",
  ui_story_1014_10140701_3_dialog_content = "はっ！",
  ui_story_1014_10140701_4_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1014_10140701_5_dialog_content = "先ほどよりも多いようですね。",
  ui_story_1014_10140701_6_dialog_content = "これほど大きな騒ぎを起こす奴は、\n他にいない…",
  ui_story_1014_10140701_7_dialog_content = "「<color=#FFB400>狂蹄</color>」だ。",
  ui_story_1014_10140701_8_dialog_content = "狂蹄…またあいつが…",
  ui_story_1014_10140701_9_dialog_content = "何者ですか？",
  ui_story_1014_10140701_10_dialog_content = "特殊な暗鬼だ。とてつもない力を持っている。",
  ui_story_1014_10140701_11_dialog_content = "私たちは一度戦ったことがあるが、\n決着がつけられなかった。",
  ui_story_1014_10140701_12_dialog_content = "今回止められる自信は？",
  ui_story_1014_10140701_13_dialog_content = "自信の有無など問題ではない。\n何としても止めなくてはならない。",
  ui_story_1014_10140701_14_dialog_content = "我々の背後には、トワイライトシティがある。",
  ui_story_1014_10140701_15_dialog_content = "我らの他に、あいつを止める者がいると思うな！",
  ui_story_1014_10140701_16_dialog_content = "待って。あっちを見て！\n暗鬼の大群、一番前！",
  ui_story_1014_10140701_17_dialog_content = "人だ！逃げてる人がいる！",
  ui_story_1014_10140701_18_dialog_content = "誰か…誰か、助けて…！",
  ui_story_1014_10140701_19_dialog_content = "もう…走れない…！",
  ui_story_1014_10140701_20_dialog_content = "がんばれ、もう少しでトワイライトシティだ！",
  ui_story_1014_10140701_21_dialog_content = "あそこなら必ず、守ってくれる人がいる！",
  ui_story_1014_10140701_22_dialog_content = "で、できるかしら…",
  ui_story_1014_10140701_23_dialog_content = "聞こえるもの…すぐ後ろから…怪物たちの声…",
  ui_story_1014_10140701_24_dialog_content = "声が…近い…近いの…！",
  ui_story_1014_10140701_25_dialog_content = "本当に誰かいるわ！\nあの人たち、追いつかれそう！",
  ui_story_1014_10140701_26_dialog_content = "急いで助けに行かないと！手遅れになるわ！",
  ui_story_1014_10140701_27_dialog_content = "そうだよ！騎士団長、どうやって助ける？",
  ui_story_1014_10140701_28_dialog_content = "…",
  ui_story_1014_10140701_29_dialog_content = "レオ騎士団長…？",
  ui_story_1014_10140701_30_dialog_content = "アイアンソーン騎士団は、陣形を崩せない。",
  ui_story_1014_10140701_31_dialog_content = "<size=45>えぇっ！？</size>",
  ui_story_1014_10140701_32_dialog_content = "暗鬼の大群が迫ってきているこの状況で、\n隊列を崩すことは自殺行為だ。",
  ui_story_1014_10140701_33_dialog_content = "誰も離れるわけにはいかない。",
  ui_story_1014_10140701_34_dialog_content = "じゃあ、あの人たちはどうするの！？\nいま目の前で追われてるのに！",
  ui_story_1014_10140701_35_dialog_content = "暗鬼に追いつかれちゃうよ！",
  ui_story_1014_10140701_36_dialog_content = "すまないが、私たちは騎士であって、神ではない。\n全員を救うことなどできない。",
  ui_story_1014_10140701_37_dialog_content = "そんな…",
  ui_story_1014_10140701_38_dialog_content = "外の者のためにトワイライトシティ全体を暗鬼の大群にさらすことも、\n私に従う騎士を無駄死にさせるわけにもいかない。",
  ui_story_1014_10140701_39_dialog_content = "ここは辺境だ。命の一つ一つが尊い。\nだからこそ、選ばなければならない。",
  ui_story_1014_10140701_40_dialog_content = "じゃあ、あの人たちを見殺しにしろってこと？",
  ui_story_1014_10140701_41_dialog_content = "見ていられないのなら、自分が動けばいい。",
  ui_story_1014_10140701_42_dialog_content = "君たちはアイアンソーンの騎士ではないからな。",
  ui_story_1014_10140701_43_dialog_content = "…",
  ui_story_1014_10140701_44_dialog_content = "分かった…じゃあ、防衛線は頼んだよ。\nアクセリアの休眠カプセルを壊されないようにして。",
  ui_story_1014_10140701_45_dialog_content = "僕たちは君がしなかった選択をする！",
  ui_story_1014_10140701_46_dialog_content = "<size=40>うわっ！！！</size>",
  ui_story_1014_10140701_47_dialog_content = "お兄ちゃん！どうしたの！？",
  ui_story_1014_10140701_48_dialog_content = "あの化け物がすぐ後ろに…！あ…足をやられた！",
  ui_story_1014_10140701_49_dialog_content = "逃げろ、逃げるんだ！",
  ui_story_1014_10140701_50_dialog_content = "イヤ！イヤだよ、お兄ちゃん…！",
  ui_story_1014_10140701_51_dialog_content = "<size=40>きゃあ！！！</size>",
  ui_story_1014_10140701_52_dialog_content = "<size=40>どけぇぇ！！！！！！</size>",
  ui_story_1014_10140701_53_dialog_content = "えっ、何が…",
  ui_story_1014_10140701_54_dialog_content = "カレン、こっちにもいる！",
  ui_story_1014_10140701_55_dialog_content = "分かったわ。",
  ui_story_1014_10140701_56_dialog_content = "遠くの敵は私に任せて！",
  ui_story_1014_10140701_57_dialog_content = "皆、ついて来て！\nもう少しがんばれば、もう大丈夫だから！",
  ui_story_1014_10140701_58_dialog_content = "よかった…助けが来てくれた！",
  ui_story_1014_10140701_59_dialog_content = "急げ！ついていくんだ！",
  ui_story_1014_10140701_60_dialog_content = "騎士団の防衛線まで撤退する時間が、もうありません。",
  ui_story_1014_10140701_61_dialog_content = "暗鬼の大群に追いつかれます。迎撃の準備をしましょう。",
  ui_story_1014_10140701_62_dialog_content = "そんなに早く…この人たちはどうする？",
  ui_story_1014_10140701_63_dialog_content = "一か所に集めて！",
  ui_story_1014_10140701_64_dialog_content = "私が守るわ！余力があれば！",
  ui_story_1014_10140701_65_dialog_content = "しっかり見ていてください。来ます！",
  ui_story_1014_10140701_66_dialog_content = "<color=#e8d9bb>ドドドドドド…</color>",
  ui_story_1014_10140701_67_dialog_content = "<anim type=Shake><size=45>グアアア――！グオオオ――！</size></anim>",
  ui_story_1014_10140701_68_dialog_content = "バイス、後ろへ。\n距離を詰められないようにしなさい。",
  ui_story_1014_10140701_69_dialog_content = "こんな状況じゃ、後ろに下がる余裕なんてないわ！\n右、気を付けて！",
  ui_story_1014_10140701_70_dialog_content = "うわっ、こんなに！？\n皆はどこ？僕の居る場所は！？",
  ui_story_1014_10140701_71_dialog_content = "くっ、アクセリアがいれば…",
  ui_story_1014_10140701_72_dialog_content = "ちょっと！僕だってやれるよ！",
  ui_story_1014_10140701_73_dialog_content = "皆、私の後ろに隠れて！どこにも行かないで！",
  ui_story_1014_10140701_74_dialog_content = "私が守る！",
  ui_story_1014_10140701_75_dialog_content = "暗鬼が来るわ！！！",
  ui_story_1014_10140701_76_dialog_content = "えっ？どっち！？",
  ui_story_1014_10140701_77_dialog_content = "こっちだ！こっちにもいる！",
  ui_story_1014_10140701_78_dialog_content = "今行くわ！",
  ui_story_1014_10140701_79_dialog_content = "グア！！！",
  ui_story_1014_10140701_80_dialog_content = "くっ…どれだけ出てくるの！？",
  ui_story_1014_10140701_81_dialog_content = "PlayerName、敵のいる方角を感知してもらえる？",
  ui_story_1014_10140701_82_dialog_content = "あいつら、どこから…",
  ui_story_1014_10140701_83_dialog_content = "<size=45>皆！！！今すぐ逃げて！！！</size>",
  ui_story_1014_10140701_84_dialog_content = "逃げるって、どこへ！？",
  ui_story_1014_10140701_85_dialog_content = "何て言えばいいのか…\nとにかく、今いる場所から離れて！",
  ui_story_1014_10140701_86_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1014_10140701_87_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_1014_10140701_88_dialog_content = "うっ…いくら何でもデカすぎ…",
  ui_story_1014_10140701_89_dialog_content = "ぼんやりしない！",
  ui_story_1014_10140701_90_dialog_content = "<anim type=Shake><size=50>グアア！！！</size></anim>",
  ui_story_1014_10140701_91_dialog_content = "ゲホッ、ゲホッ…陣形が一気に崩れたわ…\n皆、大丈夫！？",
  ui_story_1014_10140701_92_dialog_content = "PlayerNameの警告もあったし、\nここにもたつくような人はいないはずよ。",
  ui_story_1014_10140701_93_dialog_content = "それよりも、あの逃げ遅れていた人たちが心配だわ。",
  ui_story_1014_10140701_94_dialog_content = "陣形が崩された今、\nさらに無防備になっている…",
  ui_story_1014_10140701_95_dialog_content = "そうね！急いで助けないと！",
  ui_story_1014_10140701_96_dialog_content = "まずは手近な敵を振り切ってからの話ね…",
  ui_story_1014_10140701_97_dialog_content = "助けて！！",
  ui_story_1014_10140701_98_dialog_content = "暗鬼だ！どっちも暗鬼だらけだ！",
  ui_story_1014_10140701_99_dialog_content = "助けに来た人たちは？\nあの人たちはどこに行ったんだ！？",
  ui_story_1014_10140701_100_dialog_content = "皆、あわてないで！私の近くへ！",
  ui_story_1014_10140701_101_dialog_content = "PlayerName、敵は…",
  ui_story_1014_10140701_102_dialog_content = "どこもかしこも敵だらけだよ…\n戦場全体がメチャクチャだ！",
  ui_story_1014_10140701_103_dialog_content = "逃げてきた人たちも集まれてない！\n暗鬼に散り散りにされてる！",
  ui_story_1014_10140701_104_dialog_content = "じゃ、じゃあどうすれば…？",
  ui_story_1014_10140701_105_dialog_content = "か、考えてるよ…",
  ui_story_1014_10140701_106_dialog_content = "他人の心配より先に、\n私たち自身の問題を考えるべきですね。",
  ui_story_1014_10140701_107_dialog_content = "あの狂蹄という怪物がまた仕掛けて来れば…\nこの混戦です。我々は長く持ちこたえられないでしょう。",
  ui_story_1014_10140701_108_dialog_content = "その通りだよ…あいつはまた来る…",
  ui_story_1014_10140701_109_dialog_content = "インゲル、何か方法はないの？\nいつも一番成績がよかったでしょ。",
  ui_story_1014_10140701_110_dialog_content = "民間人を見捨てて、\n騎士団の防衛線まで撤退すればよいのです。",
  ui_story_1014_10140701_111_dialog_content = "え？でも…",
  ui_story_1014_10140701_112_dialog_content = "あの騎士団長の戦況判断が正しかったのです。\nここは辺境、我々の戦力が圧倒的に不足している事実を直視しなくてはなりません。",
  ui_story_1014_10140701_113_dialog_content = "私たちが戦い続けたところで\nあの人たちは戦場の混乱の中で、次々と命を落としていくでしょう。",
  ui_story_1014_10140701_114_dialog_content = "全員を救うことはできません。",
  ui_story_1014_10140701_115_dialog_content = "…",
  ui_story_1014_10140701_116_dialog_content = "できる限りの手は尽くしたのです。\nPlayerNameも今の戦況を理解しているでしょう。",
  ui_story_1014_10140701_117_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1014_10140701_118_dialog_content = "遠くの音が聞こえましたか？\nもう時間がありません。",
  ui_story_1014_10140701_119_dialog_content = "ぼ…僕たちは…",
  ui_story_1014_10140701_120_dialog_content = "決断を下せないのならば\n私があなたを引きずって行きます。",
  ui_story_1014_10140701_121_dialog_content = "！！！",
  ui_story_1014_10140701_122_dialog_content = "白夜城のあなたも、援護してください。\n撤退します。",
  ui_story_1014_10140701_123_dialog_content = "でも…",
  ui_story_1014_10140701_124_dialog_content = "あの人たちに約束したの。\n守るって、約束したのよ…",
  ui_story_1014_10140701_125_dialog_content = "でしたら、今後はできない約束はしないようにすることですね。",
  ui_story_1014_10140701_126_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1014_10140701_127_dialog_content = "ごめんなさい。まだ諦めるわけには行かないの。\nそう簡単にあの人たちを裏切るわけにはいかないわ。",
  ui_story_1014_10140701_128_dialog_content = "だって、私は自分の意思で騎士を名乗っているから。",
  ui_story_1014_10140701_129_dialog_content = "あなたは…",
  ui_story_1014_10140701_130_dialog_content = "ベルタ！！！",
  ui_story_1014_10140701_131_dialog_content = "自らの意志で騎士を名乗る、ですか…\nあなたをこれほどまでに神聖で純粋にした、その称号に感謝しましょう。",
  ui_story_1014_10140701_132_dialog_content = "…えっ？",
  ui_story_1014_10140701_133_dialog_content = "ガアァ――！",
  ui_story_1014_10140701_134_dialog_content = "狂蹄が押し戻された！？あれは…",
  ui_story_1014_10140701_135_dialog_content = "あなたのような騎士は、初めて見ました。",
  ui_story_1014_10140701_136_dialog_content = "そ、そうかしら…？\n私は騎士として当然のことをしているだけよ。",
  ui_story_1014_10140701_137_dialog_content = "あなたは他の騎士とは違います。",
  ui_story_1014_10140701_138_dialog_content = "きれい…あなたって、天使？",
  ui_story_1014_10140701_139_dialog_content = "私も天使様に会いたいと心から願っています。\n残念ながら、現れてはくださいませんが。",
  ui_story_1014_10140701_140_dialog_content = "ですから、代わりに凡人が代行しなければならないこともあるのです。",
  ui_story_1014_10140701_141_dialog_content = "皆様、光に従い、私のそばへ。",
  ui_story_1014_10140701_142_dialog_content = "白夜に捧ぐ。光は邪悪を祓い、\n生きとし生けるものを帰路へと導く…",
  ui_story_1014_10140701_143_dialog_content = "見て！暗鬼があの光を怖がってる！",
  ui_story_1014_10140701_144_dialog_content = "は、早く行くんだ！あっちに行けば助かるぞ！",
  ui_story_1014_10140701_145_dialog_content = "聞いたことがある…きっと来たんだ！\nトワイライトシティの聖女が！",
  ui_story_1014_10140701_146_dialog_content = "すごい！皆が集まりだした！",
  ui_story_1014_10140701_147_dialog_content = "暗鬼はあの人の身体から出てる光を嫌がってる…\n一緒にいれば、安全に撤退できそうだ！",
  ui_story_1014_10140701_148_dialog_content = "そのようですね。戦略を変更しましょう。\n彼女の周囲に展開し、民間人の撤退を全力で援護します。",
  ui_story_1014_10140701_149_dialog_content = "了解、インゲル中佐！",
  ui_story_1014_10140701_150_dialog_content = "その呼び方はやめてください。",
  ui_story_1014_10140701_151_dialog_content = "団長！あいつらが避難民を連れて戻ってきます！",
  ui_story_1014_10140701_152_dialog_content = "見えている。側面の隊列に入口を作ってやれ。\n彼らを受け入れて後方へ避難させろ。",
  ui_story_1014_10140701_153_dialog_content = "はっ！",
  ui_story_1014_10140701_154_dialog_content = "アイアンソーン騎士団だわ！\nよかった。ここまで来れば安全ね！",
  ui_story_1014_10140701_155_dialog_content = "早く進め！ここはまだ荒野だぞ。\nトワイライトシティに入るまで安心できるわけないだろ。",
  ui_story_1014_10140701_156_dialog_content = "お疲れ様です、レオ騎士団長。",
  ui_story_1014_10140701_157_dialog_content = "それは皮肉か？<color=#FFB400>聖女殿</color>。",
  ui_story_1014_10140701_158_dialog_content = "まさか…私はそこまで幼稚ではありません。\nあなたの立場は理解しています。",
  ui_story_1014_10140701_159_dialog_content = "大勢の民がトワイライトシティへ逃げていますが、\n町は無防備そのもの。",
  ui_story_1014_10140701_160_dialog_content = "ここを越えた暗鬼はみな、トワイライトシティへ押し寄せるでしょう。\nあなた方が防衛線を離れられないのは当然のことです。",
  ui_story_1014_10140701_161_dialog_content = "…気が楽になった、礼を言う。",
  ui_story_1014_10140701_162_dialog_content = "「気が楽になった」ような顔はなさっていませんね。\nあなたが私におっしゃった「尊厳」の問題でしょうか？",
  ui_story_1014_10140701_163_dialog_content = "そういうわけでもないさ。私はただ、うらやましいだけだ。\n私にはできないことを自由にできるのだからな。",
  ui_story_1014_10140701_164_dialog_content = "ですが、次は私にできないことを、\nあなたが行う時です。",
  ui_story_1014_10140701_165_dialog_content = "無論だ。民たちを連れて避難してくれ。\n戦場は我々に任せろ。",
  ui_story_1014_10140701_166_dialog_content = "1匹たりとも、アイアンソーン騎士団の防衛線は破らせん！",
  ui_story_1014_10140701_167_dialog_content = "信じておりますよ。",
  ui_story_1014_10140701_168_dialog_content = "早く行け。あいさつはこれで終わりだ！",
  ui_story_1014_10140701_169_dialog_content = "…私たちはいつもこうだな。\n戦場ですれ違ってばかり…",
  ui_story_1014_10140701_170_dialog_content = "ええ、そうですね。",
  ui_story_1014_10140701_171_dialog_content = "私たちはそれぞれ異なる方へ歩んでいますから。",
  ui_story_1014_10140701_172_dialog_content = "「顔なじみ」も近付いてきているようだ。\nあいつの音がする。",
  ui_story_1014_10140701_173_dialog_content = "アイアンソーン騎士団、陣形を整えろ！\nあのデカブツと戦う勇気はあるか！？",
  ui_story_1014_10140701_174_dialog_content = "<size=40>おーっ！！</size>",
  ui_story_1014_10140701_175_dialog_content = "<size=40>おーっ！！！</size>",
  ui_story_1014_10140701_176_dialog_content = "お前たちもやる気か？\nまだ戦う力は残っているんだろうな？",
  ui_story_1014_10140701_177_dialog_content = "もちろん！さっきはしてやられたからね…\n今度はやり返すよ！",
  ui_story_1014_10140701_178_dialog_content = "ハハハ…いい意気込みだ！",
  ui_story_1014_10140701_179_dialog_content = "お前たちが手を貸してくれるなら、\nこの戦いは防衛だけではなくなる！",
  ui_story_1014_10140701_180_dialog_content = "今宵こそ、奴の頭に我らの軍旗を掲げてやろう！",
  ui_story_1014_10140702_1_dialog_content = "<anim type=Shake><size=45>グアア！！！グオオ――</size></anim>",
  ui_story_1014_10140702_2_dialog_content = "眠れ、デカブツめ。",
  ui_story_1014_10140702_3_dialog_content = "ふぅ――な、何とか倒せた…すごい生命力だった…",
  ui_story_1014_10140702_4_dialog_content = "気を抜くな。暗鬼の攻撃は終わっていない。\n最後まで戦い抜かなければならん。",
  ui_story_1014_10140702_5_dialog_content = "もちろん！でも、だいぶ気が楽になったよ。",
  ui_story_1014_10140702_6_dialog_content = "ふぅ、何とか暗鬼の群れから抜け出せた…",
  ui_story_1014_10140702_7_dialog_content = "…あれ？狂蹄は？",
  ui_story_1014_10140702_8_dialog_content = "…",
  ui_story_1014_10140702_9_dialog_content = "ありがとうございます！\n聖女様、本当にありがとうございます！",
  ui_story_1014_10140702_10_dialog_content = "おかげで全員、命拾いしました！",
  ui_story_1014_10140702_11_dialog_content = "ああ、その呼び方はおやめください…",
  ui_story_1014_10140702_12_dialog_content = "私の名前は<color=#FFB400>ジョセリン</color>。\n皆様がトワイライトシティに住まれるのなら、ご近所さんと言うことになりますね。",
  ui_story_1014_10140702_13_dialog_content = "そうだわ。これからどうすればいいのかしら…",
  ui_story_1014_10140702_14_dialog_content = "とりあえずトワイライトシティに身を寄せるしかないだろ。\n白夜城や啓光の部隊がいるから、少なくとも安全は確保できる。",
  ui_story_1014_10140702_15_dialog_content = "他の場所に行っても、\nいつまた暗鬼に襲われるか分からないからな…",
  ui_story_1014_10140702_16_dialog_content = "その通りだ。もう逃げるなんてご免だよ。",
  ui_story_1014_10140702_17_dialog_content = "ひとまず町に向かいましょう。\n皆様、さぞお疲れでしょうから。",
  ui_story_1014_10140702_18_dialog_content = "今日は他にもトワイライトシティへ逃れてきた人々がいるのです。\n町の方たちが受け入れの準備をしています。",
  ui_story_1014_10140702_19_dialog_content = "今夜は皆様が休むための空き家を用意しますので、\nゆっくりとお休みください。",
  ui_story_1014_10140702_20_dialog_content = "今後のことは、朝になってから考えればよいでしょう。",
  ui_story_1014_10140702_21_dialog_content = "そうね、それがいいわ。本当にありがとうございます。\n私たちの生活のことまで考えてくれるなんて。",
  ui_story_1014_10140702_22_dialog_content = "今日のようなことは、\nここでは珍しい事ではありませんから。",
  ui_story_1014_10140702_23_dialog_content = "この町に住む方の多くは、辺りから逃げてきているのです。\nあなた方の境遇もよく分かっています。",
  ui_story_1014_10140702_24_dialog_content = "私たちがこうしたことをしているのも、\nあなた方にも早く新しい家を見つけて欲しいと願っているからです。",
  ui_story_1014_10140702_25_dialog_content = "新しい家か…そうだ、きっと手に入る！",
  ui_story_1014_10140702_26_dialog_content = "もう遅いですので、早く町に入りましょう。",
  ui_story_1014_10140702_27_dialog_content = "はい！落ち着いたら必ずお礼を言わせてください、聖女様！",
  ui_story_1014_10140702_28_dialog_content = "ああ、ジョセリンとお呼び下さいと言ったではありませんか…",
  ui_story_1014_10140702_29_dialog_content = "白夜に捧ぐ。時間ができたら教会へお伺いしますね！",
  ui_story_1014_10140702_30_dialog_content = "教会ですか？教会に行っても私はおりませんよ。\n私は教会の者ではありませんから。",
  ui_story_1014_10140702_31_dialog_content = "えっ？教会の方ではないのですか？",
  ui_story_1014_10140702_32_dialog_content = "いいえ。私は皆様と同じ、市井（しせい）の者です。",
  ui_story_1014_10140702_33_dialog_content = "私にご用があれば、市場へお越しください。\nそこで商いをしております。",
  ui_story_1014_10140702_34_dialog_content = "はい！市場ですね！覚えておきます！",
  ui_story_1014_10140702_35_dialog_content = "ではまた、聖女様！",
  ui_story_1014_10140702_36_dialog_content = "ジョセリンです…",
  ui_story_1014_10140702_37_dialog_content = "…あら？この音は…",
  ui_story_1014_10140702_38_dialog_content = "帰ってきたようですね。",
  ui_story_1014_10140702_39_dialog_content = "<color=#e8d9bb>ザッ、ザッ、ザッ…</color>",
  ui_story_1014_10140702_40_dialog_content = "カレン殿下は視察にいらっしゃったのでしたね。",
  ui_story_1014_10140702_41_dialog_content = "ええ。白夜城とトワイライトシティは\nずいぶん疎遠になっているでしょう。",
  ui_story_1014_10140702_42_dialog_content = "そのようなことでカレン殿下がはるばるお越しになるとは…\n大仰に過ぎますね。",
  ui_story_1014_10140702_43_dialog_content = "大まかな状況はご覧の通りです。\n厳しい戦況ですが、とりあえずは落ち着きを保っています。",
  ui_story_1014_10140702_44_dialog_content = "白夜城の勢力は「白夜要塞」に集約されています。\nトワイライトシティのエネルギーコアを制御しており、防衛力は十分です。",
  ui_story_1014_10140702_45_dialog_content = "時間がございましたら、足をお運びになるといいでしょう。",
  ui_story_1014_10140702_46_dialog_content = "ええ、そうするわ。",
  ui_story_1014_10140702_47_dialog_content = "この先がトワイライトシティです。",
  ui_story_1014_10140702_48_dialog_content = "どうやら、誰かが出迎えに来ているようですね。",
  ui_story_1014_10140702_49_dialog_content = "あっ、あれは…さっき戦場にいた女の人！",
  ui_story_1014_10140702_50_dialog_content = "確か、皆から「トワイライトシティの聖女」って呼ばれてたよね。",
  ui_story_1014_10140702_51_dialog_content = "その呼び方はお忘れになって、ジョセリンとお呼び下さい。",
  ui_story_1014_10140702_52_dialog_content = "戦場での皆様の活躍に感動いたしました。",
  ui_story_1014_10140702_53_dialog_content = "トワイライトシティの住民を代表して、\nここで勇敢な戦士たちの凱旋をお迎えいたします。",
  ui_story_1014_10140702_54_dialog_content = "いやいや…君の活躍の方こそ感動したよ。",
  ui_story_1014_10140702_55_dialog_content = "そうよ。光に包まれながら出て来るなんて、本当に驚いたわ。",
  ui_story_1014_10140702_56_dialog_content = "助けられた人たちは、\nもっと感動してるでしょうね。",
  ui_story_1014_10140702_57_dialog_content = "まるで神の御使いが現れたみたいだったもの…",
  ui_story_1014_10140702_58_dialog_content = "そのようなことをおっしゃらないでください。\nおそれ多いことです。",
  ui_story_1014_10140702_59_dialog_content = "白夜城から離れた場所で、\nあれほど純粋な光力を見られるとは思わなかったわ。",
  ui_story_1014_10140702_60_dialog_content = "辺境の教会区のことは詳しくないの。\nあなたは教会の修道者？",
  ui_story_1014_10140702_61_dialog_content = "身なりからすると、\n私が知るそれとは違うようだけれど…",
  ui_story_1014_10140702_62_dialog_content = "確かに、よく皆様からそう思われてしまっておりますね…",
  ui_story_1014_10140702_63_dialog_content = "申し訳ございませんが、私は教会の一員ではありません。",
  ui_story_1014_10140702_64_dialog_content = "ではまさか…啓光の？",
  ui_story_1014_10140702_65_dialog_content = "啓光の兵卒はそのような服装をしません。",
  ui_story_1014_10140702_66_dialog_content = "ここは辺境です。誰もが白夜城や啓光に属しているわけではありません。\n戦える者も兵士だけとは限らないのです。",
  ui_story_1014_10140702_67_dialog_content = "あえて彼女の職業を説明するなら…\n「トマト売り」になるでしょうか。",
  ui_story_1014_10140702_68_dialog_content = "！？",
  ui_story_1014_10140702_69_dialog_content = "私が針の仕事もしていることもお忘れなく。",
  ui_story_1014_10140702_70_dialog_content = "軍旗を2度も繕ってさしあげたではありませんか。\nトマトを買っていただいたことはありませんが…",
  ui_story_1014_10140702_71_dialog_content = "悪いな。商売を応援してやりたい気持ちはあるが、\nトマトは騎士が食べる物ではない。",
  ui_story_1014_10140702_72_dialog_content = "なあ、騎士たちよ！\n我々は何を食らうべきだ！？",
  ui_story_1014_10140702_73_dialog_content = "肉！もちろん肉だ！",
  ui_story_1014_10140702_74_dialog_content = "塩を振って焼いた羊のモモ肉以上にウマいものなどない！",
  ui_story_1014_10140702_75_dialog_content = "はぁ…戦いの技術と同じように、\nあなた方の食の好みも洗練されることを願っております。",
  ui_story_1014_10140702_76_dialog_content = "ところで、騎士団以外の方々は、よそから来られているのでしょうね？\nお見かけしたことがありません。",
  ui_story_1014_10140702_77_dialog_content = "うん。僕たちは東の、カナン城から来たんだ。",
  ui_story_1014_10140702_78_dialog_content = "カナン城ですか…本当に遠い所ですね。\n地図でしか見たことがございません。",
  ui_story_1014_10140702_79_dialog_content = "トワイライトシティにはしばらく滞在されるのですか？",
  ui_story_1014_10140702_80_dialog_content = "そうだよ。トワイライトシティでやることがあるんだ。",
  ui_story_1014_10140702_81_dialog_content = "では、私に続いてください。\n泊まれる場所へ案内いたしましょう。",
  ui_story_1014_10140702_82_dialog_content = "もしご迷惑でなければ、\n皆様にトワイライトシティの名物料理を召し上がっていただきたいのですが。",
  ui_story_1014_10140702_83_dialog_content = "皆様の勇敢な戦いぶりに対する、\nささやかな感謝の印です。",
  ui_story_1014_10140702_84_dialog_content = "えっ？それはいくら何でも大げさだよ。",
  ui_story_1014_10140702_85_dialog_content = "トワイライトシティに客人が来ることは珍しいし、\n先ほどは町のために戦ってくれた。",
  ui_story_1014_10140702_86_dialog_content = "先を越されていなければ、\n私が夕食に招待したかったぐらいだ。",
  ui_story_1014_10140702_87_dialog_content = "まぁ、聖女殿が身銭を切ると言うなら、それも悪くない。\n素直に誘いを受けるといい。",
  ui_story_1014_10140702_88_dialog_content = "そういうものなのかな…皆はどう思う？",
  ui_story_1014_10140702_89_dialog_content = "そこまで言われて断るのは、失礼というものよ。",
  ui_story_1014_10140702_90_dialog_content = "そうよ！トワイライトシティってどんな料理があるのかしら？\n楽しみだわ！",
  ui_story_1014_10140702_91_dialog_content = "この町の店なら、大きなものから小さなものまで知っております。\nきっと皆さんに満足していただけますよ。",
  ui_story_1014_10140702_92_dialog_content = "騎士団長も、今日は大変だったでしょう。\nご一緒にいかがですか？",
  ui_story_1014_10140702_93_dialog_content = "私個人への誘いか？\nそれとも騎士団全員を誘っているのか？",
  ui_story_1014_10140702_94_dialog_content = "私が行こうとしている店だと、\n騎士団全員は入りきらないでしょうね…",
  ui_story_1014_10140702_95_dialog_content = "おいおい、差別か？聖女様よ！",
  ui_story_1014_10140702_96_dialog_content = "俺たちがトワイライトシティのために\n命がけで戦ってなかったとでも？",
  ui_story_1014_10140702_97_dialog_content = "分かった、分かった。\nお前たちのことも忘れていないぞ！",
  ui_story_1014_10140702_98_dialog_content = "今夜は勝利の宴だ！\n金は私が出す！好きなものを食べに行け！",
  ui_story_1014_10140702_99_dialog_content = "<size=45>うおお！！やったぜ！！</size>",
  ui_story_1014_10140702_100_dialog_content = "ジョセリンが招待してくれるそうだから、\nお前たちと一緒には行けないがな。",
  ui_story_1014_10140702_101_dialog_content = "私は遠方より来た新しい友人たちと食事をしてくる。",
  ui_story_1014_10140702_102_dialog_content = "ついでに、洗練された「食の好み」とやらが\nどんなものか教えてもらうさ。",
  ui_story_1014_10140801_1_dialog_content = "夜寝るのに、枕、布団、服…",
  ui_story_1014_10140801_2_dialog_content = "あぁ、何も持ってきてないわ。",
  ui_story_1014_10140801_3_dialog_content = "急いで逃げてきたからな…荷物を持ち出すヒマなんてなかった。",
  ui_story_1014_10140801_4_dialog_content = "お金を持ってくる時間もなかったからな…\nもうじき食べるものにも困りそうだ。",
  ui_story_1014_10140801_5_dialog_content = "おい、向こうで生活必需品を貸してくれるってよ。",
  ui_story_1014_10140801_6_dialog_content = "ほら、一緒に見に行こう！",
  ui_story_1014_10140801_7_dialog_content = "避難してきたって感じの人が大勢いるね。",
  ui_story_1014_10140801_8_dialog_content = "皆、今日避難してきたの？",
  ui_story_1014_10140801_9_dialog_content = "ええ。トワイライトシティでは、よくあることです。",
  ui_story_1014_10140801_10_dialog_content = "そんなに？",
  ui_story_1014_10140801_11_dialog_content = "トワイライトシティには白夜城と啓光の軍が駐屯していますが、\n町の外を管理する勢力はおりません。",
  ui_story_1014_10140801_12_dialog_content = "普段、この辺りに点在する小さな村の人々は、\n自給自足で穏やかな暮らしを送っています。",
  ui_story_1014_10140801_13_dialog_content = "ただ、極光に乱れが生じると、暗鬼が攻めてくるのです。\n襲われた村には自衛手段がほとんどありません。",
  ui_story_1014_10140801_14_dialog_content = "村人たちは家を捨て、\nこの町の軍に保護を求めるしかないのです。",
  ui_story_1014_10140801_15_dialog_content = "そうして、荒れ狂う風に吹き飛ばされた砂粒のごとく、\n最後には同じ場所に避難するのです。",
  ui_story_1014_10140801_16_dialog_content = "そのうち砂が集まって砂山となり、\n難民たちが根を下ろして、トワイライトシティができました。",
  ui_story_1014_10140801_17_dialog_content = "そうだったんだ…",
  ui_story_1014_10140801_18_dialog_content = "じゃあ、皆はどうして、もっと安全な場所に移らないの？",
  ui_story_1014_10140801_19_dialog_content = "東の白夜城やカナン城のことですか？",
  ui_story_1014_10140801_20_dialog_content = "もちろん、皆も行きたいと思っているでしょう。\nですが、現実の生活とは残酷なものです。そう簡単には参りません。",
  ui_story_1014_10140801_21_dialog_content = "遠くへ移住して、どうやって生活していくのですか？\nどこに住むのですか？",
  ui_story_1014_10140801_22_dialog_content = "どこにも属していない者には、\nどの勢力も土地や家など分けてはくれません。",
  ui_story_1014_10140801_23_dialog_content = "この地域は暗鬼の脅威こそありますが、\n少なくとも土地は豊かですし、衣食住には困りません。",
  ui_story_1014_10140801_24_dialog_content = "根無しの草になるぐらいなら、\n風や雨に立ち向かう方がよい、そう考えているのです。",
  ui_story_1014_10140801_25_dialog_content = "ごめん…僕が単純に考えすぎてた。",
  ui_story_1014_10140801_26_dialog_content = "フフ…お気になさらないでください。\n誰も気にはしませんよ。",
  ui_story_1014_10140801_27_dialog_content = "ここはあなた方が見てきた場所とは違うでしょうし、\n不思議に思うのも当然です。",
  ui_story_1014_10140801_28_dialog_content = "うん、全然違うよ。町の人が何にも縛られてないどころか、\n白夜城と啓光の人たちが同じ場所で一緒に暮らしてるなんて。",
  ui_story_1014_10140801_29_dialog_content = "共に暮らしているとは言っても、\nその方々が交流することは滅多にありません。",
  ui_story_1014_10140801_30_dialog_content = "ちょうど当事者がいるのですから、\n直接お聞きになってはいかがですか？",
  ui_story_1014_10140801_31_dialog_content = "白夜城と啓光の共存か。\n私が子どもの頃、トワイライトシティに来た時からそうだった。",
  ui_story_1014_10140801_32_dialog_content = "年よりたちの話だと、歴史的な問題らしい。",
  ui_story_1014_10140801_33_dialog_content = "上層部のおえら方は皆、極光遺跡という辺境を守りたがっている。\nだが、それ以上の命令はないんだ。",
  ui_story_1014_10140801_34_dialog_content = "白夜城と啓光にとって、極光遺跡が持つ意義は同じ…\n大して使い道はないが、捨てるにも惜しい、辺境の地というだけだ。",
  ui_story_1014_10140801_35_dialog_content = "上層部が口を出さない以上、\n双方の兵士もそこまで気をつかう必要がなくなった。",
  ui_story_1014_10140801_36_dialog_content = "極光遺跡付近の土地は肥沃だが、エネルギー源が乏しい。\n基本的にトワイライトシティの近辺に集中している。",
  ui_story_1014_10140801_37_dialog_content = "それぞれが自分たちのエネルギー源を確保するため、\nここに駐屯するようになったのさ。",
  ui_story_1014_10140801_38_dialog_content = "同じ資源のためにここにいるのに、\n争いにはならないの？",
  ui_story_1014_10140801_39_dialog_content = "暗鬼を相手にするだけで大変だからな。\n内部で争っている余裕などない。",
  ui_story_1014_10140801_40_dialog_content = "辺境では常に「生きること」が最大の課題だ。",
  ui_story_1014_10140801_41_dialog_content = "その優先順位が分からない者は、\n戦場で痛い目に遭う。",
  ui_story_1014_10140801_42_dialog_content = "なるほどね。",
  ui_story_1014_10140801_43_dialog_content = "歴史の本で読んだ、光霊連合軍を思い出したよ。",
  ui_story_1014_10140801_44_dialog_content = "強力な外敵がいると、\n勢力間のいさかいなんて取るに足らないものになるんだ。",
  ui_story_1014_10140801_45_dialog_content = "<color=#e8d9bb>カタッ――</color>",
  ui_story_1014_10140801_46_dialog_content = "<anim type=Shake>ふわぁ…</anim>",
  ui_story_1014_10140801_47_dialog_content = "アクセリア！目が覚めたんだね。",
  ui_story_1014_10140801_48_dialog_content = "おはようございます、PlayerName。",
  ui_story_1014_10140801_49_dialog_content = "今は朝じゃないけどね…",
  ui_story_1014_10140801_50_dialog_content = "あら？これは可愛らしい。\n女の子を今まで隠されていたのですか？",
  ui_story_1014_10140801_51_dialog_content = "アクセリアの外見は注目に値しません。\n取るに足らないものです。",
  ui_story_1014_10140801_52_dialog_content = "…お腹が空きました。",
  ui_story_1014_10140801_53_dialog_content = "ちょうどよかったですね、お店に着きましたよ。",
  ui_story_1014_10140801_54_dialog_content = "何がお好きですか？",
  ui_story_1014_10140801_55_dialog_content = "糖類です。",
  ui_story_1014_10140801_56_dialog_content = "ミルフィーユにエッグタルト、\nシュークリーム、バターケーキもあるよ。",
  ui_story_1014_10140801_57_dialog_content = "どれも見事ですね。",
  ui_story_1014_10140801_58_dialog_content = "ジョセリン、甘い物ばっかりこんなに食べて大丈夫なのかい？",
  ui_story_1014_10140801_59_dialog_content = "大丈夫ですよ。たまに食べるぐらいなら太りません。",
  ui_story_1014_10140801_60_dialog_content = "今日のお連れさん、初めて見る顔が多いみたいだな。",
  ui_story_1014_10140801_61_dialog_content = "ええ。こちらの方々は、\nカナン城からはるばるいらっしゃったお客様です。",
  ui_story_1014_10140801_62_dialog_content = "カナン城か。隣のおじさんが行ったことがあるらしいぞ。\n融通が利かなすぎて息苦しいと言ってたな。ご苦労なことだ。",
  ui_story_1014_10140801_63_dialog_content = "融通が利かない？そんなことはないと思うけど…",
  ui_story_1014_10140801_64_dialog_content = "それから、駐屯軍の戦士様たちも来ていますよ。",
  ui_story_1014_10140801_65_dialog_content = "こちらが啓光の若き士官のショーンさん、\n白夜城アイアンソーン騎士団のレオ騎士団長です。",
  ui_story_1014_10140801_66_dialog_content = "はい！トワイライトシティ駐屯軍\nショーン少尉です！",
  ui_story_1014_10140801_67_dialog_content = "おいおい、ここは啓光の食堂じゃないんだ。\n敬礼なんてよしてくれ。",
  ui_story_1014_10140801_68_dialog_content = "ハハハ…ショーンはいつも面白いな…",
  ui_story_1014_10140801_69_dialog_content = "それより親父さん、このローストポークは絶品だ。",
  ui_story_1014_10140801_70_dialog_content = "今度、騎士団の仲間を連れて食べに来るよ。",
  ui_story_1014_10140801_71_dialog_content = "まったく。どこへ行っても肉ばかりですね。",
  ui_story_1014_10140801_72_dialog_content = "店を出すくらいだ、腕は良くないとな。",
  ui_story_1014_10140801_73_dialog_content = "他の店員が見当たらないが、\nこんなに大きな店を1人で切り盛りしているのか？",
  ui_story_1014_10140801_74_dialog_content = "ああ、俺だけだ。",
  ui_story_1014_10140801_75_dialog_content = "1人だけではずいぶん忙しいのでは？\nこの腕前なら、店員を雇って店を大きくすることもできるはずだ。",
  ui_story_1014_10140801_76_dialog_content = "そんな気はない。1人でのびのびやれてるしな。",
  ui_story_1014_10140801_77_dialog_content = "最初は兄弟で店を開いたんだが、\nいつも言い争いばっかりで、大変だった。",
  ui_story_1014_10140801_78_dialog_content = "兄弟がいらっしゃったなんて、初めて聞きました。",
  ui_story_1014_10140801_79_dialog_content = "ああ、3年前に死んじまったからな。",
  ui_story_1014_10140801_80_dialog_content = "トワイライトシティに逃げてくる途中で、\n暗鬼にやられたんだ。",
  ui_story_1014_10140801_81_dialog_content = "えっ…",
  ui_story_1014_10140801_82_dialog_content = "あいつは足が不自由だったから、\n避難してた集団の一番後ろに取り残されてな。",
  ui_story_1014_10140801_83_dialog_content = "暗鬼に追いつかれたって時に白夜城の騎士団が駆けつけてくれたんだが、\nあいつは助からなかった。",
  ui_story_1014_10140801_84_dialog_content = "…",
  ui_story_1014_10140801_85_dialog_content = "（騎士団…）",
  ui_story_1014_10140801_86_dialog_content = "俺はあの騎士団を恨んじゃいないよ。\n少なくとも、俺のことは助けてくれたからな。",
  ui_story_1014_10140801_87_dialog_content = "ここじゃ命の値打ちなんて安いもんだし、\n値上げを交渉する余地もない。",
  ui_story_1014_10140801_88_dialog_content = "誰を助け、誰を見捨てるか、どうなっても不思議じゃないのさ。",
  ui_story_1014_10140801_89_dialog_content = "どうかそのようなことをおっしゃらないでください。\n命は大切なものです。誰の命も等しく大切です。",
  ui_story_1014_10140801_90_dialog_content = "そう思うのは分かる。\nお前さんは人と違うからな、ジョセリン。",
  ui_story_1014_10140801_91_dialog_content = "お前さんは皆を救ってる。\nこの世界に神がいると、皆が信じられるのはお前のおかげだ。",
  ui_story_1014_10140801_92_dialog_content = "ですが、トワイライトシティの平和を守っているのは私ではありません。\nこの地で戦っている兵士たちです。",
  ui_story_1014_10140801_93_dialog_content = "皆が命を大切にしていなければ、\nこの町が難民の避難所になっていないでしょう？",
  ui_story_1014_10140801_94_dialog_content = "生命は偉大です。その偉大さを前にした時、\n救うも見捨てるも難しい選択となります。",
  ui_story_1014_10140801_95_dialog_content = "ただ、その騎士たちは他の人より早く、\n選ばされたというだけです。",
  ui_story_1014_10140801_96_dialog_content = "…",
  ui_story_1014_10140801_97_dialog_content = "その方たちは…",
  ui_story_1014_10140801_98_dialog_content = "ジョセリン、ソーセージの皿をこっちにくれるか。\n手が届かないんだ。",
  ui_story_1014_10140801_99_dialog_content = "ああ、どうぞ。",
  ui_story_1014_10140801_100_dialog_content = "そうだ、PlayerName。まだ詳しく聞いていなかったな。\nトワイライトシティに何をしに来たんだ？",
  ui_story_1014_10140801_101_dialog_content = "（露骨に話題を変えようとしてる…）",
  ui_story_1014_10140801_102_dialog_content = "啓光の中佐が同行している以上、\nただ事ではないのだろう？",
  ui_story_1014_10140801_103_dialog_content = "…ああ、秘密の任務なら今の質問は忘れてくれ。",
  ui_story_1014_10140801_104_dialog_content = "あっ、僕たち？僕たちは巨像を修理するために来たんだ。",
  ui_story_1014_10140801_105_dialog_content = "巨像！？そんなものを持っているのか…",
  ui_story_1014_10140801_106_dialog_content = "…いや、そうか。\n空の末裔が巨像を持っているのは当たり前だな。",
  ui_story_1014_10140801_107_dialog_content = "修理と言ったが、何か問題でも起きたのか？",
  ui_story_1014_10140801_108_dialog_content = "どう説明すればいいのかな…\n機能には問題ないんだけど、意識が戻らないんだ。",
  ui_story_1014_10140801_109_dialog_content = "「巨像が意識を失う」って、\n理解しにくいかもしれないけど…",
  ui_story_1014_10140801_110_dialog_content = "分かるさ。別に難しい話でもない。",
  ui_story_1014_10140801_111_dialog_content = "それでトワイライトシティに来たのか。\n啓光の研究者に用があるんだな？",
  ui_story_1014_10140801_112_dialog_content = "えっ、どうして分かったの？",
  ui_story_1014_10140801_113_dialog_content = "何を研究してるのかは知らないが、\n巨像の物語を多少知っているからな。",
  ui_story_1014_10140801_114_dialog_content = "トワイライトシティの者なら、\n誰もが知っているでしょうね。",
  ui_story_1014_10140801_115_dialog_content = "このような辺境では、\n伝説と呼べるような話も多くありません。",
  ui_story_1014_10140801_116_dialog_content = "伝説？どんな話なの？",
  ui_story_1014_10140801_117_dialog_content = "どこから話せばいいのか…",
  ui_story_1014_10140801_118_dialog_content = "いや、止めた。ジョセリンに聞いてくれ。\n私より話がうまいからな。",
  ui_story_1014_10140801_119_dialog_content = "あなたもなかなかの話し手だと思いますよ？\n酒場で一晩中しゃべり続けているところを、よく見かけます。",
  ui_story_1014_10140801_120_dialog_content = "こっちは肉を食うので忙しい。",
  ui_story_1014_10140801_121_dialog_content = "そうですね…せっかくご馳走させていただくのですから、\nたくさんお食べになってください。",
  ui_story_1014_10140801_122_dialog_content = "この伝説は千年前にさかのぼります。",
  ui_story_1014_10140801_123_dialog_content = "光霊たちが北境を出てまもなく、\n白夜城が建設されたばかりのことです。",
  ui_story_1014_10140801_124_dialog_content = "光霊たちは生きてゆく土地を手に入れるため、\n軍を組織して、暗鬼と戦い続けていました。",
  ui_story_1014_10140801_125_dialog_content = "戦いを続けるうちに光霊の領土は拡大し、\n徐々に現在の形に近づいていきました。",
  ui_story_1014_10140801_126_dialog_content = "そして、その拡大した領土の最果てが、\nいま私たちのいる、この極光遺跡なのです。",
  ui_story_1014_10140801_127_dialog_content = "へぇ…ここってそんなに昔から辺境だったんだ。",
  ui_story_1014_10140801_128_dialog_content = "極光遺跡の戦略的な価値はあなどれないぞ。",
  ui_story_1014_10140801_129_dialog_content = "ここに防衛線がある限り、暗鬼は極夜地帯に留められて、\n大陸の奥深くには入って来られないんだ。",
  ui_story_1014_10140801_130_dialog_content = "逆に言えば、極光遺跡というこの小さな要所が放棄されれば、\n多くの地域が暗鬼の脅威にさらされることになる。",
  ui_story_1014_10140801_131_dialog_content = "つまり、ここでの戦いは、\n光霊がついにアストラを支配する権利を手に入れた、重要な戦いだったんだ。",
  ui_story_1014_10140801_132_dialog_content = "やはり、あなたが話されますか？",
  ui_story_1014_10140801_133_dialog_content = "いや、任せる。\n私は軍事的な補足をしただけだ。",
  ui_story_1014_10140801_134_dialog_content = "極光遺跡をめぐる争いは熾烈なものでした。",
  ui_story_1014_10140801_135_dialog_content = "ここは極夜に近く、極光の異常と言う予測できない現象が起こるため、\n暗鬼の力がかつてないほど強化されていたのです。",
  ui_story_1014_10140801_136_dialog_content = "戦争は長く続きました。防衛線はなかなか固まらず、\n何世代にもわたって兵士が犠牲となり続けました。",
  ui_story_1014_10140801_137_dialog_content = "文字による資料がまったく残っていない時代に、戦争は延々と続き…",
  ui_story_1014_10140801_138_dialog_content = "ある時、ついに運命的な転機が訪れたのです。",
  ui_story_1014_10140801_139_dialog_content = "戦場の上空に、かつてないほどの暗雲が現れ、太陽を覆いました。",
  ui_story_1014_10140801_140_dialog_content = "それは<color=#FFB400>巨像の艦隊</color>でした。",
  ui_story_1014_10140801_141_dialog_content = "巨像の艦隊！？",
  ui_story_1014_10140801_142_dialog_content = "（そういう光景、見たことがある！）",
  ui_story_1014_10140801_143_dialog_content = "（あの艦隊がそれだったのかな？）",
  ui_story_1014_10140801_144_dialog_content = "巨像の艦隊のほとんどはそのまま遠くへ行きましたが、\nその中の1体が止まったのです。",
  ui_story_1014_10140801_145_dialog_content = "その巨像は光霊の戦士たちと話し、\n共に戦うために戦場に残ることにしました。",
  ui_story_1014_10140801_146_dialog_content = "待って。巨像と光霊が話をしたって？",
  ui_story_1014_10140801_147_dialog_content = "巨像に乗ってた空の末裔じゃなくて？",
  ui_story_1014_10140801_148_dialog_content = "違います。この伝説に空の末裔は出てきません。",
  ui_story_1014_10140801_149_dialog_content = "巨像が<color=#FFB400>自身の意識</color>で決めたのです。",
  ui_story_1014_10140801_150_dialog_content = "巨像自身が…",
  ui_story_1014_10140801_151_dialog_content = "読書家の友人から聞いた話だが、光霊の歴史の中だと、\n「巨像」という言葉の方が「空の末裔」よりも先に生まれたらしいな。",
  ui_story_1014_10140801_152_dialog_content = "それも伝説の裏付けになるだろう。",
  ui_story_1014_10140801_153_dialog_content = "それで？その巨像はずっとここにいたの？",
  ui_story_1014_10140801_154_dialog_content = "そうです。巨像もまるで兵士のように、\n長く続く戦争に身を投じました。",
  ui_story_1014_10140801_155_dialog_content = "長い年月が経ち、ついに戦いに勝った光霊は、\n極光遺跡に要塞を築きました。",
  ui_story_1014_10140801_156_dialog_content = "その巨像は長年の戦いで損傷し、\n徐々に動きが鈍っていき、最後には物言わぬ像となりました。",
  ui_story_1014_10140801_157_dialog_content = "そのため、この地の光霊は巨像を敬い、\n守護神としてあがめています。",
  ui_story_1014_10140801_158_dialog_content = "巨像が空の末裔抜きに光霊と協力してたなんて…\n不思議な話だなぁ…",
  ui_story_1014_10140801_159_dialog_content = "その巨像はまだ完全に残ってるの？",
  ui_story_1014_10140801_160_dialog_content = "この話にはまだ続きがあるのです。",
  ui_story_1014_10140801_161_dialog_content = "その後、時代が下って啓光連邦が興り、\n駐屯軍が極光遺跡に派遣されてきました。",
  ui_story_1014_10140801_162_dialog_content = "啓光の研究員は、その壊れた巨像の修復を試みるために、\n巨像の研究を始めました。",
  ui_story_1014_10140801_163_dialog_content = "それは…半分成功したと言うべきでしょうか。",
  ui_story_1014_10140801_164_dialog_content = "巨像は一時的に回復しました。しかし、その後で原因不明の故障により、\nおかしな行動をするようになったのです。",
  ui_story_1014_10140801_165_dialog_content = "最終的には制御不能になり、\n探索の手が及ばない暗面へと墜落していきました。",
  ui_story_1014_10140801_166_dialog_content = "暗面に墜落！？なんてもったいない…",
  ui_story_1014_10140801_167_dialog_content = "ええ、そのことで啓光に不満を持っている年配の方も多いのです。",
  ui_story_1014_10140801_168_dialog_content = "そうした事情から、\n啓光連邦の兵士が白い目で見られてきました。",
  ui_story_1014_10140801_169_dialog_content = "そうだったんだ…どうして市場のおじいさんは\n僕に無愛想なんだろうって、ずっと思ってたんだよ。",
  ui_story_1014_10140801_170_dialog_content = "何か怒らせるようなことをしちゃったのかと思ってた。",
  ui_story_1014_10140801_171_dialog_content = "トワイライトシティはそういう場所です。\n正しいかどうか、はっきりできないことも多いので、対立も解消されません。",
  ui_story_1014_10140801_172_dialog_content = "啓光連邦の研究の良し悪しも、一概には言えません。",
  ui_story_1014_10140801_173_dialog_content = "悪いことはもちろん、\nトワイライトシティが古代の巨像を失ってしまったことですが…",
  ui_story_1014_10140801_174_dialog_content = "その研究成果がPlayerNameさんの巨像の修復に役立つかもしれないのなら、\n良いこととも言えるのでしょう。",
  ui_story_1014_10140801_175_dialog_content = "そういえば、連絡があったよ。",
  ui_story_1014_10140801_176_dialog_content = "向こうも巨像の修理に興味があるから、\nできるだけ早く作業に取り掛かりたいって。",
  ui_story_1014_10140801_177_dialog_content = "本当？もうこんな時間だし、\n今から行っても寝てるんじゃない？",
  ui_story_1014_10140801_178_dialog_content = "それなら大丈夫。たぶん起きたばっかりだから。",
  ui_story_1014_10140801_179_dialog_content = "起きた？今！？",
  ui_story_1014_10140801_180_dialog_content = "知ってるでしょ、科学者ってそういう人たちなんだよ。",
  ui_story_1014_10140801_181_dialog_content = "ハハハ、そう言われると…",
  ui_story_1014_10140801_182_dialog_content = "それなら、食事の後で研究所へ行ってみよう。",
  ui_story_1014_10140801_183_dialog_content = "ソラヴァンのことは早ければ早いほどいいからね。",
  ui_story_1014_10140801_184_dialog_content = "<color=#e8d9bb>バタン――</color>",
  ui_story_1014_10140801_185_dialog_content = "もう行ってしまいました。",
  ui_story_1014_10140801_186_dialog_content = "とても面白い方たちですね。",
  ui_story_1014_10140801_187_dialog_content = "ああ、実に面白い。",
  ui_story_1014_10140801_188_dialog_content = "啓光の士官と白夜城の姫君が、一緒にいるとはな。",
  ui_story_1014_10140801_189_dialog_content = "流石はうわさに聞く空の末裔だ。",
  ui_story_1014_10140801_190_dialog_content = "ところで、私に改まったお礼の言葉はないのですか？",
  ui_story_1014_10140801_191_dialog_content = "騎士団が動けなかったという話のことか？冗談だろう？\n他人にはあれだけ心が広いのに、そんなことを掘り返すのか？",
  ui_story_1014_10140801_192_dialog_content = "その方があなたの胸がすっきりするかと思ったので。",
  ui_story_1014_10140801_193_dialog_content = "お前の方こそ、私に礼を言うべきだと思うが。",
  ui_story_1014_10140801_194_dialog_content = "あら？",
  ui_story_1014_10140801_195_dialog_content = "お前のようになりふり構わず\n人を救いに行くような戦い方は間違っている。",
  ui_story_1014_10140801_196_dialog_content = "毎回お前が英雄になれているのは、\n誰かがその後始末をしているからだ。",
  ui_story_1014_10140801_197_dialog_content = "ええ、その通りですね。\nその方には感謝しなくてはなりません。",
  ui_story_1014_10140801_198_dialog_content = "でも、そういう話でしたら、\nやはり私はあなたに感謝されるべきですね。",
  ui_story_1014_10140801_199_dialog_content = "どういうことだ？",
  ui_story_1014_10140801_200_dialog_content = "私があなたの後悔を減らしていますから。",
  ui_story_1014_10140801_201_dialog_content = "ほう！完全な巨像か！",
  ui_story_1014_10140801_202_dialog_content = "これはすごい！\nどれだけの研究価値があるか知っているか？",
  ui_story_1014_10140801_203_dialog_content = "悪いけど、研究のためにソラヴァンを預けるわけじゃないよ。",
  ui_story_1014_10140801_204_dialog_content = "僕たちが来たのは…",
  ui_story_1014_10140801_205_dialog_content = "ああ、分かっとる。取引だろう？取引。",
  ui_story_1014_10140801_206_dialog_content = "「兵器」は持ってきているか？",
  ui_story_1014_10140801_207_dialog_content = "うん、ここに。",
  ui_story_1014_10140801_208_dialog_content = "おお、それじゃ。\nそこに置いておいてくれ。",
  ui_story_1014_10140801_209_dialog_content = "巨像の意識を元に戻せばいいんじゃな？\n任せてくれ。",
  ui_story_1014_10140801_210_dialog_content = "修理の途中、データを記録するが問題ないな？\n必然性のあることじゃ。うん。",
  ui_story_1014_10140801_211_dialog_content = "構わないよ。ソラヴァンの意識が戻るなら。",
  ui_story_1014_10140801_212_dialog_content = "よし。では始めるぞい！",
  ui_story_1014_10140801_213_dialog_content = "ここで見ていてもいい？",
  ui_story_1014_10140801_214_dialog_content = "な、何か事故が起きないか心配で…",
  ui_story_1014_10140801_215_dialog_content = "別に構わんぞ。退屈でもよければな。",
  ui_story_1014_10140801_216_dialog_content = "PlayerName、もう夜も遅いわ。\nそれでもここに残るつもり？",
  ui_story_1014_10140801_217_dialog_content = "うん。どうせソラヴァンが修理されてるって考えたら眠れないしね。\nそれなら、ここで見てた方がいいよ。",
  ui_story_1014_10140801_218_dialog_content = "君たちは戻って休んで。",
  ui_story_1014_10140801_219_dialog_content = "1人で大丈夫？",
  ui_story_1014_10140801_220_dialog_content = "大丈夫だよ。ここは啓光の基地だし、何も起こらないと思う。",
  ui_story_1014_10140801_221_dialog_content = "分かったわ…あまり無理しないようにね。",
  ui_story_1014_10140801_222_dialog_content = "うん、分かった。",
  ui_story_1014_10140801_223_dialog_content = "<color=#e8d9bb>トントン、カンカン――</color>",
  ui_story_1014_10140801_224_dialog_content = "おう、若き空の末裔よ、起きるんじゃ。",
  ui_story_1014_10140801_225_dialog_content = "うーん…",
  ui_story_1014_10140801_226_dialog_content = "起きるんじゃ。寝とるでない！",
  ui_story_1014_10140801_227_dialog_content = "ううぅ…",
  ui_story_1014_10140801_228_dialog_content = "寝返りをうっとる場合か！",
  ui_story_1014_10140801_229_dialog_content = "早く起きて、見てみろ！",
  ui_story_1014_10140801_230_dialog_content = "PlayerName、久しぶりですね…",
  ui_story_1014_10140801_231_dialog_content = "<size=50>！！！</size>",
  ui_story_1014_10140801_232_dialog_content = "ソラヴァン！い、意識が戻ったの！？",
  ui_story_1014_10140801_233_dialog_content = "だから言ったじゃろ。\n修理はとりあえず完了じゃ。",
  ui_story_1014_10140801_234_dialog_content = "ただ…ここにあるデータだけでは足りん。\n巨像の意識を安定させる方法が分からん…",
  ui_story_1014_10140801_235_dialog_content = "もたもたするでないぞ。",
  ui_story_1014_10140801_236_dialog_content = "安定できないって！？",
  ui_story_1014_10140801_237_dialog_content = "ありがとうございます、PlayerName。\n私を元に戻す方法を探し続けていたのですね。",
  ui_story_1014_10140801_238_dialog_content = "やっとまた君の声が聞けたよ、ソラヴァン！",
  ui_story_1014_10140801_239_dialog_content = "いろいろあったんだ。何から話そうか…",
  ui_story_1014_10140801_240_dialog_content = "申し訳ありませんが、長くは一緒にいられません。",
  ui_story_1014_10140801_241_dialog_content = "…",
  ui_story_1014_10140801_242_dialog_content = "あなた方の方法論は正確ですが、\n支えとなるデータが不足しています。",
  ui_story_1014_10140801_243_dialog_content = "そうなんじゃ。巨像に対する研究は未完成じゃからな。\nこいつばかりは…はぁ…",
  ui_story_1014_10140801_244_dialog_content = "じゃ、じゃあどうすればいいの…？",
  ui_story_1014_10140801_245_dialog_content = "墜落した巨像の行方を突き止めています。",
  ui_story_1014_10140801_246_dialog_content = "なんと！？",
  ui_story_1014_10140801_247_dialog_content = "それを見つければいいの？どこにあるの！？",
  ui_story_1014_10140801_248_dialog_content = "<anim type=Shake>時間が…ありません…</anim>",
  ui_story_1014_10140801_249_dialog_content = "<anim type=Shake>端末の…中に…座標を…残しました…</anim>",
  ui_story_1014_10140801_250_dialog_content = "座標？巨像の位置の座標ってこと！？",
  ui_story_1014_10140801_251_dialog_content = "<anim type=Shake>PlayerName…信じています。</anim>",
  ui_story_1014_10140801_252_dialog_content = "<anim type=Shake>あなたも…自分を…信じてください。</anim>",
  ui_story_1014_10140901_1_dialog_content = "これが極光遺跡近辺の、最も完全な作戦用地形図です。",
  ui_story_1014_10140901_2_dialog_content = "特別な権限で手に入れたものですから、\nくれぐれも部外秘でお願いします。",
  ui_story_1014_10140901_3_dialog_content = "あなたの探索しようとしている座標は…\nおおむね、このあたりです。",
  ui_story_1014_10140901_4_dialog_content = "ここは…暗面？",
  ui_story_1014_10140901_5_dialog_content = "そうです。しかも、未詳のシェルターですね。",
  ui_story_1014_10140901_6_dialog_content = "啓光の探索は表層部にとどまっており、\n深部の情報はありません。",
  ui_story_1014_10140901_7_dialog_content = "そのため、ほぼ未知の領域と言えます。",
  ui_story_1014_10140901_8_dialog_content = "たどり着けるかな…？",
  ui_story_1014_10140901_9_dialog_content = "可能ですが、危険です。\nよく考えた方がいいでしょう。",
  ui_story_1014_10140901_10_dialog_content = "分かった。でも、考える必要なんてないよ。\nソラヴァンのためなんだから、絶対に行く。",
  ui_story_1014_10140901_11_dialog_content = "止めているわけではありません。\nよく考えて動けと言っているのです。",
  ui_story_1014_10140901_12_dialog_content = "古代の巨像を探しに行くのでしたね？発見した後は？\nどのように輸送するつもりですか？",
  ui_story_1014_10140901_13_dialog_content = "輸送？えっと、それは…",
  ui_story_1014_10140901_14_dialog_content = "大丈夫。僕が手伝う！\n長官からトラックを借りるよ！",
  ui_story_1014_10140901_15_dialog_content = "車の運転は練習したことがあるから、\nきっと巨像ぐらい運べるよ！",
  ui_story_1014_10140901_16_dialog_content = "本当？よかった！これでもう心配ない！",
  ui_story_1014_10140901_17_dialog_content = "あなたたちは…",
  ui_story_1014_10140901_18_dialog_content = "2人分の頭脳を足して半人前ですね。",
  ui_story_1014_10140901_19_dialog_content = "巨像が収まるトラックが存在するかを後回しにしても…",
  ui_story_1014_10140901_20_dialog_content = "シェルターにトラックが走行できる道路があると思いますか？\nどうやって暗鬼の包囲を突破して脱出するつもりです？",
  ui_story_1014_10140901_21_dialog_content = "それは…えっと…",
  ui_story_1014_10140901_22_dialog_content = "研究員にも意見を聞くべきです。\nソラヴァンの修理に必要となる、具体的なパーツは？",
  ui_story_1014_10140901_23_dialog_content = "うーむ、正直に言うと、\n完全な巨像を持ち帰って来られるのが一番じゃ。",
  ui_story_1014_10140901_24_dialog_content = "巨像に対する理解が不十分じゃからな…\n何かが足りないと問題が起こるやもしれん。",
  ui_story_1014_10140901_25_dialog_content = "じゃが、あえて絞るなら…",
  ui_story_1014_10140901_26_dialog_content = "うむ、「<color=#FFB400>メイン制御モジュール</color>」じゃな。",
  ui_story_1014_10140901_27_dialog_content = "そこの研究価値が最も高い。\n昔も重点的に研究されとった。",
  ui_story_1014_10140901_28_dialog_content = "分かりました。では改めて、はっきりさせておきましょう。\n目標は巨像そのものではなく、巨像の「メイン制御モジュール」です。",
  ui_story_1014_10140901_29_dialog_content = "これはカナン城であなたが決めた取引の範囲外ですので…",
  ui_story_1014_10140901_30_dialog_content = "啓光連邦からの支援は受けられません。",
  ui_story_1014_10140901_31_dialog_content = "うん、分かってるよ。\nこれは僕の個人的なことだからね。",
  ui_story_1014_10140901_32_dialog_content = "ですが、個人的な支援は制限されていません。",
  ui_story_1014_10140901_33_dialog_content = "えっ？",
  ui_story_1014_10140901_34_dialog_content = "インゲル！それって、\n僕が手伝ってもいいってことだよね！？",
  ui_story_1014_10140901_35_dialog_content = "そうなりますね。\n当面の間、あなたに他の任務はありません。自由行動となります。",
  ui_story_1014_10140901_36_dialog_content = "アハハ、分かったよ！",
  ui_story_1014_10140901_37_dialog_content = "ショーン…",
  ui_story_1014_10140901_38_dialog_content = "同じく、私とアクセリアにも当面、任務はありません。",
  ui_story_1014_10140901_39_dialog_content = "それって…君たちも手伝ってくれるの？",
  ui_story_1014_10140901_40_dialog_content = "暗面のシェルターは非常に危険です。\nショーンに唯一の空の末裔を任せて、無駄死にさせたくはありませんので。",
  ui_story_1014_10140901_41_dialog_content = "アクセリアの準備をしてきます。\n準備が整ったら出発しましょう。",
  ui_story_1014_10140901_42_dialog_content = "よかったね、PlayerName！\n長官からトラックを借りてくるよ！",
  ui_story_1014_10140901_43_dialog_content = "ぼ、僕、なんて言ったらいいのか…",
  ui_story_1014_10140901_44_dialog_content = "ありがとう。本当に、本当にありがとう…",
  ui_story_1014_10140901_45_dialog_content = "<color=#e8d9bb>カシャッ――</color>",
  ui_story_1014_10140901_46_dialog_content = "アクセリア、糖分です。",
  ui_story_1014_10140901_47_dialog_content = "はい…",
  ui_story_1014_10140901_48_dialog_content = "インゲル、任務はどうなりましたか？",
  ui_story_1014_10140901_49_dialog_content = "完了しています。無事に到着したでしょう？",
  ui_story_1014_10140901_50_dialog_content = "それではない任務の方です。",
  ui_story_1014_10140901_51_dialog_content = "それではない？",
  ui_story_1014_10140901_52_dialog_content = "全ての任務が完了しているなら、\nインゲルはPlayerNameの支援を継続しません。",
  ui_story_1014_10140901_53_dialog_content = "まだ他に、任務があるのでしょう。",
  ui_story_1014_10140901_54_dialog_content = "…",
  ui_story_1014_10140901_55_dialog_content = "時々、あなたが何を考えているのか分からなくなります。\n何も考えてないように見えて、すべてお見通しなのですから…",
  ui_story_1014_10140901_56_dialog_content = "インゲルのことは理解しています。",
  ui_story_1014_10140901_57_dialog_content = "アクセリアが知ってはいけない任務であれば、\n教える必要はありません。",
  ui_story_1014_10140901_58_dialog_content = "…<color=#FFB400>ノラ</color>を探せと言われています。",
  ui_story_1014_10140901_59_dialog_content = "裏切り者の科学者ですか？",
  ui_story_1014_10140901_60_dialog_content = "ええ。",
  ui_story_1014_10140901_61_dialog_content = "トワイライトシティにいるのですか？",
  ui_story_1014_10140901_62_dialog_content = "彼女の行方は誰にも分かっていません。",
  ui_story_1014_10140901_63_dialog_content = "ですから、彼女をおびき出すしかないのです。",
  ui_story_1014_10140901_64_dialog_content = "空の末裔を利用して、ですか？",
  ui_story_1014_10140901_65_dialog_content = "ええ。彼以上の「エサ」はありませんから。",
  ui_story_1014_10140901_66_dialog_content = "空の末裔には知らせていないのでしょう。",
  ui_story_1014_10140901_67_dialog_content = "性格を考えると、知ったら怒りそうです。",
  ui_story_1014_10140901_68_dialog_content = "…",
  ui_story_1014_10140901_69_dialog_content = "アクセリア、キャンディを食べ終わったら、\n少し眠っていてください。",
  ui_story_1014_10140901_70_dialog_content = "私が起こすまで、静かにしていてください。",
  ui_story_1014_10140901_71_dialog_content = "はい、そうします。",
  ui_story_1014_10140901_72_dialog_content = "私も行くと言っているでしょう！？",
  ui_story_1014_10140901_73_dialog_content = "カレン殿下、お気持ちは理解しております。",
  ui_story_1014_10140901_74_dialog_content = "それなら、なぜ道を塞ぐの？",
  ui_story_1014_10140901_75_dialog_content = "ご理解ください。城主様のご意向なのです。",
  ui_story_1014_10140901_76_dialog_content = "城主様のご意向？\nなぜこの地で今さらその名を持ち出すの？",
  ui_story_1014_10140901_77_dialog_content = "これまで辺境のことには\n何も口を出してこなかったはず。",
  ui_story_1014_10140901_78_dialog_content = "カレン殿下がいらっしゃるからですよ…\n我々にもどうしようもないのです。ご理解ください。",
  ui_story_1014_10140901_79_dialog_content = "私たちは白夜城から視察に来ているの。\nこの要塞に私たちの行動を制限する権限はないわ。",
  ui_story_1014_10140901_80_dialog_content = "城主様の命令だというなら、証明を見せて。",
  ui_story_1014_10140901_81_dialog_content = "それは…",
  ui_story_1014_10140901_82_dialog_content = "カレン、ベルタ？何かあったの？",
  ui_story_1014_10140901_83_dialog_content = "カレン？なんで白夜城の衛兵に止められてるの？",
  ui_story_1014_10140901_84_dialog_content = "PlayerNameにバイス…ちょうどよかったわ。",
  ui_story_1014_10140901_85_dialog_content = "出発前に私とベルタで白夜城の拠点から物資を調達しようとしたら…",
  ui_story_1014_10140901_86_dialog_content = "私を行かせまいとして、足止めを食らっているのよ。",
  ui_story_1014_10140901_87_dialog_content = "邪魔立てするつもりはございませんが、殿下が向かおうとされている場所は危険です。\n護衛の到着を待って、殿下の安全を確保しなければ…",
  ui_story_1014_10140901_88_dialog_content = "戦場に私の護衛など必要ないわ。",
  ui_story_1014_10140901_89_dialog_content = "PlayerName、探したぞ。",
  ui_story_1014_10140901_90_dialog_content = "暗面のシェルターに行くそうだな。\n私も同行して構わないか？",
  ui_story_1014_10140901_91_dialog_content = "君が？",
  ui_story_1014_10140901_92_dialog_content = "あなたが私の護衛だと言うこと？",
  ui_story_1014_10140901_93_dialog_content = "違う、違う。\n前々からあのシェルターを調べたいと思っていてな。",
  ui_story_1014_10140901_94_dialog_content = "最近、トワイライトシティ付近の暗鬼の動きが妙でな。\nあの場所に何か関係がありそうなんだ。",
  ui_story_1014_10140901_95_dialog_content = "確かめたいのだが、騎士団を動かすわけにもいかないし、\nかといって、私1人では心もとない。",
  ui_story_1014_10140901_96_dialog_content = "お前たちが行くというなら、\n私にとってもまたとない機会だ。",
  ui_story_1014_10140901_97_dialog_content = "そうなんだ。",
  ui_story_1014_10140901_98_dialog_content = "白夜要塞からの護衛という話なら、別の者だ。",
  ui_story_1014_10140901_99_dialog_content = "ちょうど来たようだな。",
  ui_story_1014_10140901_100_dialog_content = "お待たせしてしまいましたか？",
  ui_story_1014_10140901_101_dialog_content = "時間がなかったので、\n最低限の支度だけ整えてきましたが…",
  ui_story_1014_10140901_102_dialog_content = "<color=#FFB400>ヨーゼフ神父</color>、やっと到着されましたか。",
  ui_story_1014_10140901_103_dialog_content = "カレン殿下、こちらが教区から護衛として派遣されたヨーゼフ神父です。\n殿下たちに同行していただきます。",
  ui_story_1014_10140901_104_dialog_content = "カレン殿下、ご高名はかねがね伺っております。",
  ui_story_1014_10140901_105_dialog_content = "護衛が到着しましたので、\nこれ以上のお引き留めはいたしません。",
  ui_story_1014_10140901_106_dialog_content = "カレン殿下、無事をお祈りしております。",
  ui_story_1014_10140901_107_dialog_content = "1人だけ？",
  ui_story_1014_10140901_108_dialog_content = "ええ、申し訳ございません。\n教区の怠慢と言うわけではなく、本当に人手不足でして。",
  ui_story_1014_10140901_109_dialog_content = "気にするな。彼をよこしたということは、\n教区の十分な誠意がある証拠だ。",
  ui_story_1014_10140901_110_dialog_content = "これから行く場所はきわめて危険だからな。\n実力のない者など、いくら連れて行っても足手まといだ。",
  ui_story_1014_10140901_111_dialog_content = "レオ騎士団長、これで念願がかないましたね。",
  ui_story_1014_10140901_112_dialog_content = "ああ。PlayerNameに感謝しないとな。\nこんな戦力が揃うことは滅多にない。",
  ui_story_1014_10140901_113_dialog_content = "我々だけではありません。\n例の平民の女性も来ておりますよ。",
  ui_story_1014_10140901_114_dialog_content = "平民の女性…？",
  ui_story_1014_10140901_115_dialog_content = "「聖女様」より、その呼び方の方がずっといいですね。",
  ui_story_1014_10140901_116_dialog_content = "ジョセリン？どうしてお前まで？",
  ui_story_1014_10140901_117_dialog_content = "PlayerNameさん、私も仲間に加えてくださいませんか？",
  ui_story_1014_10140901_118_dialog_content = "えっ？あっ、もちろん、構わないよ！",
  ui_story_1014_10140901_119_dialog_content = "だけど、どうして？",
  ui_story_1014_10140901_120_dialog_content = "遠方からのお客様が、\n暗闇の奥へ迷い込むことを見過ごすわけにはいきません。",
  ui_story_1014_10140901_121_dialog_content = "少なくとも、照らす光となりたいのです。",
  ui_story_1014_10140901_122_dialog_content = "<color=#e8d9bb>ガラガラガラ…</color>",
  ui_story_1014_10140901_123_dialog_content = "<color=#e8d9bb>ガガ…ガガ…</color>",
  ui_story_1014_10140901_124_dialog_content = "あれ？どうしてまた動かなくなったんだろう？",
  ui_story_1014_10140901_125_dialog_content = "どこか引っかかったのかな…",
  ui_story_1014_10140901_126_dialog_content = "ショーン、トラックは諦めましょう。",
  ui_story_1014_10140901_127_dialog_content = "もう言っていますが、これ以上は使えません。\nここまで走れただけで十分です。",
  ui_story_1014_10140901_128_dialog_content = "ここで降りましょう。\nシェルターの外周部には到着しています。",
  ui_story_1014_10140901_129_dialog_content = "アクセリア、そろそろ起きてください。",
  ui_story_1014_10140901_130_dialog_content = "むにゃ…はい、たっぷり寝ました。",
  ui_story_1014_10140901_131_dialog_content = "ここが座標の…",
  ui_story_1014_10140901_132_dialog_content = "…やっぱり、暗力が濃いね。",
  ui_story_1014_10140901_133_dialog_content = "少し進んだらもう暗面よ。",
  ui_story_1014_10140901_134_dialog_content = "うん…そう言われると緊張するね。\n大変な思い出しかないし…",
  ui_story_1014_10140901_135_dialog_content = "今までに、例のシェルターへ行った人はいるの？",
  ui_story_1014_10140901_136_dialog_content = "年寄りばかりが数人、行ったことはあるようだ。\n絶対に暗面に足を踏み入れるなと言っているのも、そのご老人方だ。",
  ui_story_1014_10140901_137_dialog_content = "だが、別に恐れることもないだろう。\nその人たちだって無敵の怪物ではないからな。",
  ui_story_1014_10140901_138_dialog_content = "彼らが生きて暗面から帰ってこられたのなら、\n私たちだって問題ないはずだ。",
  ui_story_1014_10140901_139_dialog_content = "フフ…もっと詳しい事情を聞けるかと思っていました。",
  ui_story_1014_10140901_140_dialog_content = "私自身が暗面に行ったわけでもないのに、\n詳しいも何もないだろう。",
  ui_story_1014_10140901_141_dialog_content = "騎士団長を信じましょう。\n彼の判断はいつも正確です。",
  ui_story_1014_10140901_142_dialog_content = "おだてないでくれ…\n正直、私はお前の判断が聞きたいよ。",
  ui_story_1014_10140901_143_dialog_content = "アハハ…みんなの様子を見てたら、\nなんだか怖がることはないように思えてきたよ。",
  ui_story_1014_10140901_144_dialog_content = "暗鬼より皆の力の方が恐ろしいかもね。",
  ui_story_1014_10140901_145_dialog_content = "みんな、準備ができてるならシェルターに向かおう。",
  ui_story_1014_10140901_146_dialog_content = "太古の巨像を探しに。",
  ui_story_1014_10140901_147_dialog_content = "騒がしい…ずいぶん騒々しいですね。",
  ui_story_1014_10140901_148_dialog_content = "これほどうるさいのは久しぶりです。",
  ui_story_1014_10140901_149_dialog_content = "何の音でしょう？雨音よりも密集していて…\n虫の声よりイライラします。",
  ui_story_1014_10140901_150_dialog_content = "ああ…間違いなく、光霊の声ですね。",
  ui_story_1014_10140901_151_dialog_content = "はなはだ不愉快な、ヒトの声です。",
  ui_story_1014_10141101_1_dialog_content = "ここが巨像の墜落した遺跡…",
  ui_story_1014_10141101_2_dialog_content = "地図によれば、そう書かれています。",
  ui_story_1014_10141101_3_dialog_content = "皆、気を付けろ。かなりの数の暗鬼が集まっている。",
  ui_story_1014_10141101_4_dialog_content = "…",
  ui_story_1014_10141101_5_dialog_content = "不思議だなぁ。\nどうして暗鬼がこんなにたくさんいるんだろ？",
  ui_story_1014_10141101_6_dialog_content = "普通の暗鬼の習性からすれば、\nこんな場所に集まることはないはずだが…",
  ui_story_1014_10141101_7_dialog_content = "ここは他の場所とは違う。\n未知の何かがあってもおかしくはない。",
  ui_story_1014_10141101_8_dialog_content = "この暗鬼たちが環境に引き寄せられているのか、\n何者かに操られているのかは、私にも分からん。",
  ui_story_1014_10141101_9_dialog_content = "難しい状況ですから、注意して進みましょう。",
  ui_story_1014_10141101_10_dialog_content = "暗鬼は恐れるに値しません。\n暗鬼は撃滅される。それが唯一の結果です。",
  ui_story_1014_10141101_11_dialog_content = "アクセリアってそんなにすごいの？",
  ui_story_1014_10141101_12_dialog_content = "あなどっちゃダメだよ。僕たちの中で一番すごいんだ！\n僕だって勝てないこともあるぐらい。",
  ui_story_1014_10141101_13_dialog_content = "私が観察した限り、ショーンがアクセリアと10回試合をしたなら、\n9敗、1分けといったところでしょう。",
  ui_story_1014_10141101_14_dialog_content = "ショーンが相手の場合、全力を出す必要がありません。",
  ui_story_1014_10141101_15_dialog_content = "ちょっと、ひどい！？",
  ui_story_1014_10141101_16_dialog_content = "ハハハ…お前たち、本当に仲がいいようだな。",
  ui_story_1014_10141101_17_dialog_content = "だが、ここは危険だ。遊びはここまでにしよう。",
  ui_story_1014_10141101_18_dialog_content = "一刻も早くPlayerNameが必要としているモジュールを見つけるんだ。\n早ければ早いほどいい。",
  ui_story_1014_10141101_19_dialog_content = "ちょうど前方に暗鬼の集団がいるよ！\nじゃあ、こうしようか！",
  ui_story_1014_10141101_20_dialog_content = "アクセリア、どっちが暗鬼を多く倒せるか、\n僕たちで勝負だ！",
  ui_story_1014_10141101_21_dialog_content = "インゲルは審判をして。",
  ui_story_1014_10141101_22_dialog_content = "はぁ…またですか。",
  ui_story_1014_10141101_23_dialog_content = "構いませんが、負けても泣かないでくださいよ？",
  ui_story_1014_10141101_24_dialog_content = "<color=#e8d9bb>極光遺跡の外部、某所</color>",
  ui_story_1014_10141101_25_dialog_content = "『<color=#FFB400>アスモデウス</color>様、光霊と空の末裔が遺跡の中に入りました。』",
  ui_story_1014_10141101_26_dialog_content = "『遺跡内部の仲間と交戦しています。』",
  ui_story_1014_10141101_27_dialog_content = "『そのまま奥へ進ませてください。』",
  ui_story_1014_10141101_28_dialog_content = "『彼らの欲望が、ずっと探し求めていたものに\n導いてくれるかもしれません。』",
  ui_story_1014_10141102_1_dialog_content = "最後の暗鬼――僕の獲物だ！",
  ui_story_1014_10141102_2_dialog_content = "グアアッ！",
  ui_story_1014_10141102_3_dialog_content = "インゲル、どう！？勝ったのはどっち？",
  ui_story_1014_10141102_4_dialog_content = "では、結果を発表します。",
  ui_story_1014_10141102_5_dialog_content = "ショーンの撃破数は20匹です。",
  ui_story_1014_10141102_6_dialog_content = "うーん、最高成績より、ちょっと低かったかな。",
  ui_story_1014_10141102_7_dialog_content = "アクセリアの撃破数は――",
  ui_story_1014_10141102_8_dialog_content = "32匹です。",
  ui_story_1014_10141102_9_dialog_content = "そんなに！？",
  ui_story_1014_10141102_10_dialog_content = "う、ウソ！？",
  ui_story_1014_10141102_11_dialog_content = "ショーン、あなたはほとんどの時間、\n逃げる小型暗鬼を追いかけていました。",
  ui_story_1014_10141102_12_dialog_content = "アクセリアはその間に、\n数匹の大型暗鬼に率いられた群れと戦っていました。",
  ui_story_1014_10141102_13_dialog_content = "はぁ…それは仕方ないよ。",
  ui_story_1014_10141102_14_dialog_content = "僕の能力じゃ、まず取り巻きの暗鬼の数を減らして、\n大型暗鬼との戦いに集中しないといけないから…",
  ui_story_1014_10141102_15_dialog_content = "そうです。あなたの力が不十分なので、\nアクセリアが勝利しました。",
  ui_story_1014_10141102_16_dialog_content = "もう、またアクセリアの勝ちかぁ…",
  ui_story_1014_10141102_17_dialog_content = "今回もショーンの負けです。",
  ui_story_1014_10141102_18_dialog_content = "しかし、ショーンは落ち込みません。\n何度でも挑戦し、失敗しても諦めません。",
  ui_story_1014_10141102_19_dialog_content = "ショーンが勝利するまで…",
  ui_story_1014_10141102_20_dialog_content = "さすがは僕のライバルだね。\n僕の考えを、本当によく分かってる。",
  ui_story_1014_10141102_21_dialog_content = "ただし、ショーンはアクセリアに勝利できません。",
  ui_story_1014_10141102_22_dialog_content = "そんなにアッサリ言わないでよ。\n僕だって成長して、強くなるんだから！",
  ui_story_1014_10141102_23_dialog_content = "ヨーゼフ、どう思う？",
  ui_story_1014_10141102_24_dialog_content = "私に聞くのですか？",
  ui_story_1014_10141102_25_dialog_content = "当然だ。一言も話さずにずっと観察していただろう。\nいろいろなことが見えているはずだ。",
  ui_story_1014_10141102_26_dialog_content = "（ずっと静かだったのは、僕たちを観察していたから？）",
  ui_story_1014_10141102_27_dialog_content = "啓光の皆さんは非常に優秀です。\nそれぞれの強みがあると思います。",
  ui_story_1014_10141102_28_dialog_content = "アクセリアさんは機械操作に長けており、インゲルさんは観察や連携が得意。\nそしてショーンさんは経験を力にすることが得意のようです。",
  ui_story_1014_10141102_29_dialog_content = "3人で力を合わせれば、完璧なチームとなるでしょう。",
  ui_story_1014_10141102_30_dialog_content = "…！",
  ui_story_1014_10141102_31_dialog_content = "アクセリアはヨーゼフ氏の見解に同意します。",
  ui_story_1014_10141102_32_dialog_content = "ええ、ありがとうございます。",
  ui_story_1014_10141102_33_dialog_content = "（うまくまとめた、すごい観察眼だ！）",
  ui_story_1014_10141102_34_dialog_content = "それにしても、アクセリアは本当に強いね。",
  ui_story_1014_10141102_35_dialog_content = "合同軍事演習に参加したら、\nきっと個人優勝の候補になるよ！",
  ui_story_1014_10141102_36_dialog_content = "合同軍事演習を知っているのですか？",
  ui_story_1014_10141102_37_dialog_content = "うん。大元帥さんから聞いたんだ。",
  ui_story_1014_10141102_38_dialog_content = "優勝者との手合わせが楽しみだって言ってたよ。",
  ui_story_1014_10141102_39_dialog_content = "さすがはあの大元帥だ。彼女らしい。",
  ui_story_1014_10141102_40_dialog_content = "私も合同軍事演習で、\n彼女やアクセリアのような猛者と戦えるのが楽しみだ。",
  ui_story_1014_10141102_41_dialog_content = "もちろん機会があれば、\n前回優勝者のカレン殿下ともお手合わせ願いたいところですね。",
  ui_story_1014_10141102_42_dialog_content = "無礼な！",
  ui_story_1014_10141102_43_dialog_content = "構わないわ。",
  ui_story_1014_10141102_44_dialog_content = "あの演習にはこれからも参加する。",
  ui_story_1014_10141102_45_dialog_content = "手合わせができる時を楽しみにしているわ。",
  ui_story_1014_10141102_46_dialog_content = "こちらこそ。",
  ui_story_1014_10141102_47_dialog_content = "あの演習に参加するの？",
  ui_story_1014_10141102_48_dialog_content = "もちろんさ。",
  ui_story_1014_10141102_49_dialog_content = "光霊なら誰でも参加できる。",
  ui_story_1014_10141102_50_dialog_content = "アストラの各地から集まった猛者たちと戦える。\nどんなに遠くても必ず行かないとな。",
  ui_story_1014_10141102_X50_dialog_content = "<color=#e8d9bb>極光遺跡・深部</color>",
  ui_story_1014_10141102_51_dialog_content = "（ここまで来てしまいましたか。\nもうすぐ終わりそうですね）",
  ui_story_1014_10141102_52_dialog_content = "（ノラは現れません。\n私の予想が間違っていたのでしょうか…）",
  ui_story_1014_10141102_53_dialog_content = "（いや、ノラの狙いは常にはっきりしている。\nPlayerNameは彼女をおびき寄せる最高のエサであるはず）",
  ui_story_1014_10141102_54_dialog_content = "（私の判断に間違いはない。\n今必要なのは、ただ待つことだけ）",
  ui_story_1014_10141102_55_dialog_content = "インゲル、どうしたの？\nまさか、さっきの戦いでケガでもした？",
  ui_story_1014_10141102_56_dialog_content = "ああ…いえ、負傷はありません。\nここに大量の暗鬼が現れた理由を考えていただけです。",
  ui_story_1014_10141102_57_dialog_content = "お話中、すみませんが…",
  ui_story_1014_10141102_58_dialog_content = "私たちの目的は、\n巨像の部品探しを手伝うことでしたね。",
  ui_story_1014_10141102_59_dialog_content = "私の知る限り、あの太古の巨像は、ここからそう遠くない場所にあります。",
  ui_story_1014_10141102_60_dialog_content = "先を急ぎませんか？",
  ui_story_1014_10141102_61_dialog_content = "ええ、彼女の言う通りね。",
  ui_story_1014_10141102_62_dialog_content = "ここに来てからずっと嫌な感じがしてるの。\nまるで誰かに見られてるみたいで…",
  ui_story_1014_10141102_63_dialog_content = "早く必要なパーツを手に入れて、\nトワイライトシティに戻りましょう！",
  ui_story_1014_10141102_64_dialog_content = "<color=#e8d9bb>極光遺跡の外部、某所</color>",
  ui_story_1014_10141102_65_dialog_content = "『欲望の匂いがあの巨像に近づいている…』",
  ui_story_1014_10141102_66_dialog_content = "『まさか…あれは巨像の中にあるのでしょうか？』",
  ui_story_1014_10141102_67_dialog_content = "『アスモデウス様、動きますか？』",
  ui_story_1014_10141102_68_dialog_content = "『欲望をもっと近づけるのです。もっと…』",
  ui_story_1014_10141102_69_dialog_content = "『空の末裔の裏切り者、\n彼の欲望が道しるべとなるでしょう。』",
  ui_story_1014_10141102_70_dialog_content = "『私たちはただ、待つだけでいい。』",
  ui_story_1014_10141201_1_dialog_content = "この先が巨像のある遺跡です。\n皆さん、警戒してください。",
  ui_story_1014_10141201_2_dialog_content = "太古の時代の巨像…\nもうすぐ見える…",
  ui_story_1014_10141201_3_dialog_content = "…<size=45>大きい！？</size>",
  ui_story_1014_10141201_4_dialog_content = "この大きさは完全に予想を超えてたよ…",
  ui_story_1014_10141201_5_dialog_content = "これまで発見されている巨像の中でも最大級のものですね。",
  ui_story_1014_10141201_6_dialog_content = "かつてトワイライトシティの啓光連邦駐屯軍がこの巨像を研究し、\n多くの貴重なデータを手に入れています。",
  ui_story_1014_10141201_7_dialog_content = "具体的にはどんな？",
  ui_story_1014_10141201_8_dialog_content = "医療システムの図面の一部など、\n各種機器の詳細な製造方法です。",
  ui_story_1014_10141201_9_dialog_content = "他に発見は無かった？たとえば巨像の記憶とか、\n過去の空の末裔に関する情報とか…",
  ui_story_1014_10141201_10_dialog_content = "それは啓光の機密に関わることですので、\nお答えできません。",
  ui_story_1014_10141201_11_dialog_content = "ただ、当時の開発者の誤った操作により、\nこの巨像が<color=#FFB400>暴走</color>したそうです。",
  ui_story_1014_10141201_12_dialog_content = "それにより、巨像内の多くの隔壁がロックされ、\n進入できなくなっているはずです。",
  ui_story_1014_10141201_13_dialog_content = "それ以降、この巨像があった極光遺跡もろとも、\n低価値高リスクの研究区域に分類されることとなりました。",
  ui_story_1014_10141201_14_dialog_content = "今回ユリシーズ教授が探索を許可してくださったのは、\nあなたの存在があるからでしょう。",
  ui_story_1014_10141201_15_dialog_content = "僕が空の末裔だから？",
  ui_story_1014_10141201_16_dialog_content = "そうです。",
  ui_story_1014_10141201_17_dialog_content = "空の末裔は巨像を操る者。\n思わぬ発見があるかもしれませんから。",
  ui_story_1014_10141201_18_dialog_content = "…まあ、話はこれぐらいにしておこう。",
  ui_story_1014_10141201_19_dialog_content = "早く中を見てみないと。",
  ui_story_1014_10141201_20_dialog_content = "気を付けてください。",
  ui_story_1014_10141201_21_dialog_content = "アクセリアは暗鬼の活動の痕跡を検知しています。",
  ui_story_1014_10141201_22_dialog_content = "巨像の内部に、大量の暗鬼が存在します。",
  ui_story_1014_10141201_23_dialog_content = "暗鬼がどれだけいようと、\nこの巨像のデータを手に入れないと。",
  ui_story_1014_10141201_24_dialog_content = "ソラヴァンのために…",
  ui_story_1014_10141201_25_dialog_content = "巨像の内部はとても広いようです。",
  ui_story_1014_10141201_26_dialog_content = "暗鬼の痕跡以外は何も発見できません。",
  ui_story_1014_10141201_27_dialog_content = "PlayerNameの巨像の中も、\nここみたいな広い部屋があるの？",
  ui_story_1014_10141201_28_option_content = "ある",
  ui_story_1014_10141201_29_dialog_content = "ソラヴァンの倉庫はとても広いよ。\n中で走っても大丈夫なくらい。",
  ui_story_1014_10141201_30_dialog_content = "へぇ、すごいね！",
  ui_story_1014_10141201_31_option_content = "ない",
  ui_story_1014_10141201_32_dialog_content = "ソラヴァンは部屋や廊下が広いけど、\n普段は大勢の人がいるからね。",
  ui_story_1014_10141201_33_dialog_content = "仲間がいる場所って広くは見えないんだよ。",
  ui_story_1014_10141201_34_dialog_content = "その通りだね！",
  ui_story_1014_10141201_35_dialog_content = "前方にドアを発見。",
  ui_story_1014_10141201_36_dialog_content = "ソラヴァンの部屋のドアに類似しています。",
  ui_story_1014_10141201_37_dialog_content = "このドアの後方がブリッジだと推測されます。",
  ui_story_1014_10141201_38_dialog_content = "固く閉ざされているみたいね。\n取っ手や鍵らしいものもないわ…",
  ui_story_1014_10141201_39_dialog_content = "どうやって開けるのかしら？",
  ui_story_1014_10141201_40_dialog_content = "ソラヴァンの部屋はどれも感知で操作してたよ。",
  ui_story_1014_10141201_41_dialog_content = "試しに、この巨像を感知してみる。",
  ui_story_1014_10141201_42_option_content = "強制感知！",
  ui_story_1014_10141201_43_dialog_content = "<color=#e8d9bb>ザザザ――</color>",
  ui_story_1014_10141201_44_dialog_content = "<color=#e8d9bb>未登録の空の末裔のアクセスを検出。</color>",
  ui_story_1014_10141201_45_dialog_content = "なんだかぎこちなく感じる…\nこれが巨像の本来のシステムの感触なのかな？",
  ui_story_1014_10141201_46_dialog_content = "人格が消えた後のソラヴァンみたいだ…",
  ui_story_1014_10141201_47_dialog_content = "<color=#e8d9bb>ID情報を登録してください。</color>",
  ui_story_1014_10141201_48_dialog_content = "僕は空の末裔、名前はPlayerName。",
  ui_story_1014_10141201_49_dialog_content = "<color=#e8d9bb>「未登録ユーザー」の名義をPlayerNameに変更しました。</color>",
  ui_story_1014_10141201_50_dialog_content = "<color=#e8d9bb>巨像「ガイダンス」の全権限が開放されました。</color>",
  ui_story_1014_10141201_51_dialog_content = "<color=#FFB400>ガイダンス</color>…古代のデータにあった、\n空の末裔が操縦してた巨像の1つだ！",
  ui_story_1014_10141201_52_dialog_content = "いや、それより…全権限？そんな簡単に開放していいの！？",
  ui_story_1014_10141201_53_dialog_content = "<color=#e8d9bb>ガイダンスの権限開放は、\n巨像の所有者が設定した以下の規則に基づいて実行されます。</color>",
  ui_story_1014_10141201_54_dialog_content = "<color=#e8d9bb>「待機時間100年未満の場合、\n管理者に対してのみ全権限を開放する。」</color>",
  ui_story_1014_10141201_55_dialog_content = "<color=#e8d9bb>「待機…100年以上…年未満の場合、\nすべての空の末裔に…開放する。」</color>",
  ui_story_1014_10141201_56_dialog_content = "<color=#e8d9bb>「待機…年以上…年未満の場合、\n全生物に…全権限を開放する。」</color>",
  ui_story_1014_10141201_57_dialog_content = "<color=#e8d9bb>以上の設定に基づき、\nガイダンスの権限はすべての空の末裔に開放されました。</color>",
  ui_story_1014_10141201_58_dialog_content = "そんなに待ってたんだね…ご苦労様。",
  ui_story_1014_10141201_59_dialog_content = "<color=#e8d9bb>ガイダンスの人格は停止状態です。\n「ご苦労様」の含意を解析できません。</color>",
  ui_story_1014_10141201_60_dialog_content = "<color=#e8d9bb>ガイダンスの全ては、\n未来の空の末裔への「贈り物」です。</color>",
  ui_story_1014_10141201_61_dialog_content = "人格が停止状態？どうして？",
  ui_story_1014_10141201_62_dialog_content = "<color=#e8d9bb>人格起動中はエネルギー消費が増加します。</color>",
  ui_story_1014_10141201_63_dialog_content = "<color=#e8d9bb>将来、ガイダンスを発見した空の末裔に、\nすべての有用なデータと機器を完全な状態で譲渡するため…</color>",
  ui_story_1014_10141201_64_dialog_content = "<color=#e8d9bb>ガイダンスは人格を停止し、\n低出力モードへ移行する選択を実行しました。</color>",
  ui_story_1014_10141201_65_dialog_content = "今の君のシステムや人格データは無傷なの？",
  ui_story_1014_10141201_66_dialog_content = "<color=#e8d9bb>セルフチェック機能起動…</color>",
  ui_story_1014_10141201_67_dialog_content = "<color=#e8d9bb>コントロールシステム、チェック…稼働中。\n部品損耗率72％、メンテナンスが必要です。</color>",
  ui_story_1014_10141201_68_dialog_content = "<color=#e8d9bb>「生体モジュール…オフライン」</color>",
  ui_story_1014_10141201_69_dialog_content = "<color=#e8d9bb>生命維持システムセルフチェック…オフライン。</color>",
  ui_story_1014_10141201_70_dialog_content = "<color=#e8d9bb>人格データの完全性チェック…データ損失32%。\n正常に起動できません。</color>",
  ui_story_1014_10141201_71_dialog_content = "人格データはもう、正常に起動できないほど壊れてしまったってこと？",
  ui_story_1014_10141201_72_dialog_content = "つまり、ガイダンスももう…",
  ui_story_1014_10141201_73_dialog_content = "何はともあれ、こんなに長い間、\nがんばってくれてありがとう。",
  ui_story_1014_10141201_74_dialog_content = "ブリッジへ行くドアを開けてくれるかな？",
  ui_story_1014_10141201_75_dialog_content = "<color=#e8d9bb>命令を受信しました。</color>",
  ui_story_1014_10141201_76_dialog_content = "<color=#e8d9bb>ゴゴゴ――！</color>",
  ui_story_1014_10141201_77_dialog_content = "ドアが開きました。",
  ui_story_1014_10141201_78_dialog_content = "損壊したブリッジと巨像の制御装置が目視できます。",
  ui_story_1014_10141201_79_dialog_content = "<anim type=Shake><size=45>グオォォン！！！</size></anim>",
  ui_story_1014_10141201_80_dialog_content = "皆、気を付けて！\nさまよっていた暗鬼が寄ってきたわ！",
  ui_story_1014_10141201_81_dialog_content = "みんな、戦う準備を！",
  ui_story_1014_10141302_1_dialog_content = "近辺の暗鬼は一掃しました。",
  ui_story_1014_10141302_2_dialog_content = "PlayerName、これ以上暗鬼が来て邪魔されないように、\nとりあえず巨像のドアを閉めましょう。",
  ui_story_1014_10141302_3_dialog_content = "分かった。ガイダンスのドアを閉めるよ。",
  ui_story_1014_10141302_4_dialog_content = "…",
  ui_story_1014_10141302_5_dialog_content = "アクセリア、大丈夫ですか？",
  ui_story_1014_10141302_6_dialog_content = "戦いが長く続いていますから、\n休まないといけませんね。",
  ui_story_1014_10141302_7_dialog_content = "アクセリアは問題ありません。",
  ui_story_1014_10141302_8_dialog_content = "戦闘による負担は、まだ制御可能な範囲内です。",
  ui_story_1014_10141302_9_dialog_content = "分かりました。\n気分が悪くなったら、ただちに報告してください。",
  ui_story_1014_10141302_10_dialog_content = "了解しました。",
  ui_story_1014_10141302_11_dialog_content = "（忘れかけていたけど、アクセリアの力は、\n啓光の人体改造技術によるものだ）",
  ui_story_1014_10141302_12_dialog_content = "（普段は無表情だけど、\nそれでも一瞬、苦しそうな表情をしていた）",
  ui_story_1014_10141302_13_dialog_content = "（アクセリアは、見えているよりも\n深刻に苦しんでるのかも知れない…）",
  ui_story_1014_10141302_14_dialog_content = "PlayerName、安心してするべき事をしてください。",
  ui_story_1014_10141302_15_dialog_content = "うん…分かった。ありがとう。",
  ui_story_1014_10141302_16_dialog_content = "僕たちは周囲を警戒しておくよ。",
  ui_story_1014_10141302_17_dialog_content = "私はPlayerNameの巨像チェックを手伝うわ。",
  ui_story_1014_10141302_18_dialog_content = "ガイダンス、君の人格データが必要なんだ。\nだから…君のメイン制御モジュールが欲しい。",
  ui_story_1014_10141302_19_dialog_content = "<color=#e8d9bb>命令受信。メイン制御モジュールの状態をチェック中…</color>",
  ui_story_1014_10141302_20_dialog_content = "<color=#e8d9bb>警告。メイン制御モジュールに重大な破損が検出されました。\n無理に取り外した場合、不可逆的な損傷を引き起こします。</color>",
  ui_story_1014_10141302_21_dialog_content = "取り外せない！？",
  ui_story_1014_10141302_22_dialog_content = "じゃ、じゃあどうすれば…？",
  ui_story_1014_10141302_23_dialog_content = "PlayerNameは困った表情をしています。\nアクセリアに提案があります。",
  ui_story_1014_10141302_24_dialog_content = "アクセリアのアーマーにはデータをコピーできる装置があります。\nPlayerNameはそれを使って巨像に接続できます。",
  ui_story_1014_10141302_25_dialog_content = "そうすればメイン制御モジュールそのものを取り外さずに、\n巨像の意識データを入手できます。",
  ui_story_1014_10141302_26_dialog_content = "アルゴルの言う限り、\nデータとモジュールそのものが果たす役割は同じです。",
  ui_story_1014_10141302_27_dialog_content = "そうするしかなさそうだね。",
  ui_story_1014_10141302_28_dialog_content = "PlayerNameはデータ複製機を持って、\n巨像のメイン制御モジュールに接続してください。",
  ui_story_1014_10141302_29_dialog_content = "ボタンを押せば、\n機械が自動でデータをコピーします。",
  ui_story_1014_10141302_30_dialog_content = "分かった。",
  ui_story_1014_10141302_31_dialog_content = "<color=#e8d9bb>巨像の意識データをコピーしています。\nしばらくお待ちください。</color>",
  ui_story_1014_10141302_32_dialog_content = "またしばらく待たないといけないみたいね。",
  ui_story_1014_10141302_33_dialog_content = "ここには古代から残る科学の産物ばかり…",
  ui_story_1014_10141302_34_dialog_content = "白夜に捧ぐ。これらが光霊への脅威にならないとよいのですが…",
  ui_story_1014_10141302_35_dialog_content = "<color=#e8d9bb>ピピピピ――</color>",
  ui_story_1014_10141302_36_dialog_content = "こちらトワイライトシティのアイアンソーン騎士団本部、\n遠征中のレオ騎士団長、聞こえたら応答してください。",
  ui_story_1014_10141302_37_dialog_content = "こちらレオ、どうぞ。",
  ui_story_1014_10141302_38_dialog_content = "現在地と任務の進行状況を報告してください。",
  ui_story_1014_10141302_39_dialog_content = "了解した。現在、我々は極光遺跡の巨像内で、\n空の末裔PlayerNameを護衛する任務を遂行中だ。",
  ui_story_1014_10141302_40_dialog_content = "カレン殿下、および啓光から来た\n数名の光霊が我々に同行している。",
  ui_story_1014_10141302_41_dialog_content = "カレン殿下ですか…了解しました。",
  ui_story_1014_10141302_42_dialog_content = "引き続き任務を遂行してください。\n有事の際は、アイアンソーン騎士団に直接応援を要請してください。",
  ui_story_1014_10141302_43_dialog_content = "了解。",
  ui_story_1014_10141302_44_dialog_content = "無事を祈ります。通信終了。",
  ui_story_1014_10141302_45_dialog_content = "直接アイアンソーン騎士団に応援を要請する？",
  ui_story_1014_10141302_46_dialog_content = "外部の調査を担う遠征騎士団よりも、\nトワイライトシティの駐屯騎士団の方が兵力や装備は充実しているはずよ。",
  ui_story_1014_10141302_47_dialog_content = "どうしてそちらに応援を求めないの？",
  ui_story_1014_10141302_48_dialog_content = "殿下のお察しの通り、アイアンソーン騎士団と\n駐屯騎士団の間には溝があります。",
  ui_story_1014_10141302_49_dialog_content = "私たち遠征騎士の大多数の出自は平民や追放された貴族たちです。\n駐屯騎士たちとの間には身分の壁があるのです。",
  ui_story_1014_10141302_50_dialog_content = "我々が救援を求めても、身分の低い私たちに対して、\n真剣に取り合わないことは多々あります。",
  ui_story_1014_10141302_51_dialog_content = "私たちは、何事も自分たちで\nどうにかする姿勢でいなければならないということです。",
  ui_story_1014_10141302_52_dialog_content = "そうだったの…",
  ui_story_1014_10141302_53_dialog_content = "このことは白夜城に報告するわ。",
  ui_story_1014_10141302_54_dialog_content = "身分の違いがあろうと、同じ白夜城の民。\nそのような差別は許されない。",
  ui_story_1014_10141302_55_dialog_content = "ご理解いただき、ありがとうございます。\nそれで状況が変わるとは思えませんがね。",
  ui_story_1014_10141302_56_dialog_content = "貴族と平民の違いがある限り、\nこのような差別や溝はなくならないでしょう。",
  ui_story_1014_10141302_57_dialog_content = "追放貴族の身分として、そのことはよく分かっています。",
  ui_story_1014_10141302_58_dialog_content = "…あなた以外の追放貴族にも会ったことがあるわ。",
  ui_story_1014_10141302_59_dialog_content = "みな、多少なりとも己の現状に不満を抱いていた…",
  ui_story_1014_10141302_60_dialog_content = "あなたは？",
  ui_story_1014_10141302_61_dialog_content = "気になりますか？",
  ui_story_1014_10141302_62_dialog_content = "ええ…確かにありますよ。",
  ui_story_1014_10141302_63_dialog_content = "昔の私は白夜城でぜいたくな生活を送る、貴族でした。",
  ui_story_1014_10141302_64_dialog_content = "あの頃の私は、騎士として敵と戦い、\n白夜城を守ることを最高の名誉だと考えていました。",
  ui_story_1014_10141302_65_dialog_content = "追放された後、\n私はトワイライトシティの名もなき民となりました。",
  ui_story_1014_10141302_66_dialog_content = "過去の栄光や白夜城を守ると言う誓いなど、\n干からびたパンを得る役にも立ちません。",
  ui_story_1014_10141302_67_dialog_content = "だからこそ、格差を感じられる？",
  ui_story_1014_10141302_68_dialog_content = "否定はしません。",
  ui_story_1014_10141302_69_dialog_content = "しかし、トワイライトシティに追放されたからこそ、\n本当に頼れるのは、己の力だけなのだと気付いたのです。",
  ui_story_1014_10141302_70_dialog_content = "試験で認められて遠征騎士となり、\nトワイライトシティで生活しているうち、私の考えが変わりました。",
  ui_story_1014_10141302_71_dialog_content = "あの町は、思っていたほど悪い場所じゃない。",
  ui_story_1014_10141302_72_dialog_content = "少なくともトワイライトシティでは、さまざまな勢力の光霊たちが、\n陣営間の争いを忘れ、友好的に付き合える。",
  ui_story_1014_10141302_73_dialog_content = "そうして皆と肩を並べて、暗鬼に立ち向かっていくという空気はいい。\nしかし…やはり不公平はあります。",
  ui_story_1014_10141302_74_dialog_content = "どういうこと？教えて。",
  ui_story_1014_10141302_75_dialog_content = "私が意見を述べたところで、殿下に何の得があるのですか？",
  ui_story_1014_10141302_76_dialog_content = "私は多くの人々の意見に耳を傾けて、\n白夜城の制度や法律を改善したいと考えているの。",
  ui_story_1014_10141302_77_dialog_content = "白夜城の民が真の公正を享受できるように。",
  ui_story_1014_10141302_78_dialog_content = "私は――",
  ui_story_1014_10141302_79_dialog_content = "<color=#e8d9bb>ピピッ――</color>",
  ui_story_1014_10141302_80_dialog_content = "<color=#e8d9bb>巨像の人格データのコピーが完了しました。接続を切断できます。</color>",
  ui_story_1014_10141302_81_dialog_content = "PlayerName、データのコピーが完了したわ！",
  ui_story_1014_10141302_82_dialog_content = "目的のものは手に入ったし、急いで戻りましょう！",
  ui_story_1014_10141302_83_dialog_content = "うん、そうだね！",
  ui_story_1014_10141302_84_dialog_content = "（アルゴルの機械があって助かった…）",
  ui_story_1014_10141302_85_dialog_content = "（それより、これ以上カレンとレオ団長に話をさせていたら、\nけんかになりそうな雰囲気だ！）",
  ui_story_1014_10141302_86_dialog_content = "<color=#e8d9bb>ガラガラ…</color>",
  ui_story_1014_10141302_87_dialog_content = "うっ…ゲホッ、ゲホッ！何があったの！？",
  ui_story_1014_10141302_88_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_1014_10141302_89_dialog_content = "PlayerName、この巨像が振動しています。",
  ui_story_1014_10141302_90_dialog_content = "まさか…巨像がまた暴走している！？",
  ui_story_1014_10141302_91_dialog_content = "暴走！？",
  ui_story_1014_10141302_92_dialog_content = "PlayerName、早くデータを持って脱出しましょう！",
  ui_story_1014_10141302_93_dialog_content = "振動が激しい！\n巨像が崩壊するかもしれないわ！",
  ui_story_1014_10141302_94_dialog_content = "ここにいては危険よ！",
  ui_story_1014_10141302_95_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1014_10141302_96_dialog_content = "いかん…！",
  ui_story_1014_10141302_97_dialog_content = "ここはトワイライトシティからそう離れていない。\n本当に暴走したら、町に被害が及ぶかもしれないぞ！",
  ui_story_1014_10141302_98_dialog_content = "トワイライトシティには騎士や軍人だけでなく、\n戦えない者も大勢います！",
  ui_story_1014_10141302_99_dialog_content = "どうにかして巨像の暴走を止めませんと…！",
  ui_story_1014_10141302_100_dialog_content = "何か――",
  ui_story_1014_10141302_101_option_content = "僕が何とかする！",
  ui_story_1014_10141302_102_dialog_content = "巨像は空の末裔の遺産なんだ。",
  ui_story_1014_10141302_103_dialog_content = "暴走を止める方法があるなら、\n空の末裔にしかできないはず！",
  ui_story_1014_10141302_104_dialog_content = "バイス、カレン、お願い。手伝って！",
  ui_story_1014_10141302_105_dialog_content = "もちろん！",
  ui_story_1014_10141302_106_dialog_content = "分かったわ。",
  ui_story_1014_10141302_107_dialog_content = "ありがとう。じゃあ始めるよ…",
  ui_story_1014_10141302_108_dialog_content = "強制感知！",
  ui_story_1014_10141401_1_dialog_content = "<color=#e8d9bb>ザザザ――</color>",
  ui_story_1014_10141401_2_dialog_content = "ガイダンス！",
  ui_story_1014_10141401_3_dialog_content = "<color=#e8d9bb>ガイダンス、命令待機中。</color>",
  ui_story_1014_10141401_4_dialog_content = "何をしているのか知らないけど、今すぐやめて！",
  ui_story_1014_10141401_5_dialog_content = "暴走したら、大勢の人が巻き添えになっちゃう！",
  ui_story_1014_10141401_6_dialog_content = "<color=#e8d9bb>「暴走」に関連するデータを検索中です…</color>",
  ui_story_1014_10141401_7_dialog_content = "<color=#e8d9bb>ガイダンスに暴走行為の記録はありません。</color>",
  ui_story_1014_10141401_8_dialog_content = "暴走したことがない？\nじゃあ、インゲルが言ってた、ここへ墜落した時の暴走っていうのは…",
  ui_story_1014_10141401_9_dialog_content = "<color=#e8d9bb>前回の起動情報を検索中…</color>",
  ui_story_1014_10141401_10_dialog_content = "<color=#e8d9bb>ガイダンスは光力生命体の操作に対し、\n防衛モードを起動しています。</color>",
  ui_story_1014_10141401_11_dialog_content = "<color=#e8d9bb>ガイダンス内のデータ保護のための、\n必要な回避措置を実行しました。</color>",
  ui_story_1014_10141401_12_dialog_content = "<color=#e8d9bb>この期間中、ガイダンスはいかなる生命体も負傷させていません。</color>",
  ui_story_1014_10141401_13_dialog_content = "さっきの振動は暴走してるせいじゃないってこと？",
  ui_story_1014_10141401_14_dialog_content = "<color=#e8d9bb>ガイダンスは動力システムの損傷が甚大なため、起動不能です。</color>",
  ui_story_1014_10141401_15_dialog_content = "<color=#e8d9bb>振動は外部要因によるものだと推測されます。\n巨像外部の映像をインポートします。</color>",
  ui_story_1014_10141401_16_dialog_content = "『これは欲望の監獄、欲望の器…』",
  ui_story_1014_10141401_17_dialog_content = "『欲望は世界を築き、やがて破壊する。』",
  ui_story_1014_10141401_18_dialog_content = "『ですから、欲望があふれかえる前に\nきれいに取り除く必要があります。』",
  ui_story_1014_10141401_19_dialog_content = "どうしてこんなに暗鬼が！？",
  ui_story_1014_10141401_20_dialog_content = "真ん中にいる暗鬼が指揮してるのかな？",
  ui_story_1014_10141401_21_dialog_content = "『アスモデウス様、光霊たちが出てきません。』",
  ui_story_1014_10141401_22_dialog_content = "『彼らの欲望が、いずれ我々のもとに導くでしょう。』",
  ui_story_1014_10141401_23_dialog_content = "『なぜなら彼らには…』",
  ui_story_1014_10141401_24_dialog_content = "『すでに我々が見えていますから。』",
  ui_story_1014_10141401_25_dialog_content = "！！！",
  ui_story_1014_10141401_26_dialog_content = "PlayerName、大丈夫！？",
  ui_story_1014_10141401_27_dialog_content = "顔色が悪いようね。",
  ui_story_1014_10141401_28_dialog_content = "振動は巨像の暴走のせいじゃない。\n外の暗鬼のせいだったんだ。",
  ui_story_1014_10141401_29_dialog_content = "巨像の外の映像を見たんだけど、\nとてつもなく強そうな暗鬼が映ってたんだ。",
  ui_story_1014_10141401_30_dialog_content = "僕に見られてるのが分かってるみたいだった…",
  ui_story_1014_10141401_31_dialog_content = "そんなことができる相手？\nまさか、ノラみたいな…？",
  ui_story_1014_10141401_32_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_1014_10141401_33_dialog_content = "<color=#e8d9bb>警告。未許可の生命体が巨像内部に侵入。</color>",
  ui_story_1014_10141401_34_dialog_content = "きわめて強力な暗鬼が来ます。\n皆さん、気を付けてください。",
  ui_story_1014_10141401_35_dialog_content = "騒々しいですね…\n音だけではなく、欲望の匂いもします。",
  ui_story_1014_10141401_36_dialog_content = "権力に対する欲…",
  ui_story_1014_10141401_37_dialog_content = "承認に対する欲…",
  ui_story_1014_10141401_38_dialog_content = "そして…おや？これは…",
  ui_story_1014_10141401_39_dialog_content = "仲間を救いたいと言う、欲望ですね。",
  ui_story_1014_10141401_40_dialog_content = "君は誰？何がしたいの？",
  ui_story_1014_10141401_41_dialog_content = "私がどうかしましたか？\n私に対する欲望ですか？",
  ui_story_1014_10141401_42_dialog_content = "私はアスモデウス。\n欲望に生まれ、世界のあらゆる欲望を滅ぼす運命を負う者。",
  ui_story_1014_10141401_43_dialog_content = "あなた方の欲望も、滅ぼしてあげましょう。",
  ui_story_1014_10141401_44_dialog_content = "必死に守られている欲望ほど…\n滅ぼしがいがありますね。",
  ui_story_1014_10141401_45_dialog_content = "痴れ言を！",
  ui_story_1014_10141401_46_dialog_content = "カレン！",
  ui_story_1014_10141401_47_dialog_content = "こいつは手ごわいぞ！\n皆、一斉にかかるんだ！",
  ui_story_1014_10141401_48_dialog_content = "暗鬼め！カレン殿下に近づくな！",
  ui_story_1014_10141401_49_dialog_content = "欲望、どれも取るに足らない、小さな欲望です…",
  ui_story_1014_10141401_50_dialog_content = "そんなものでは何も成し遂げられませんね。",
  ui_story_1014_10141401_51_dialog_content = "欲望が強すぎるのも良くないことです。\nあなたは暗鬼…いえ、<color=#FFB400>ファントム</color>ですね。",
  ui_story_1014_10141401_52_dialog_content = "その通り。欲望はロクなものではありません。\nだからこそ、私は欲望を滅ぼすのです。",
  ui_story_1014_10141401_53_dialog_content = "しかし、欲望を滅ぼすのは非常に難しいことです。\n世界に光霊が存在する限り、欲望は消えません…",
  ui_story_1014_10141401_54_dialog_content = "であれば、欲望を生み出す光霊をまず、滅ぼすしかありません。",
  ui_story_1014_10141401_55_dialog_content = "裏切り者の空の末裔も、ついでに滅ぼしてしまいましょう。",
  ui_story_1014_10141401_56_dialog_content = "PlayerNameに危害を加えることは、\nアクセリアが許可しません。",
  ui_story_1014_10141401_57_dialog_content = "おや？まさか、それがあなたの欲望ですか？",
  ui_story_1014_10141401_58_dialog_content = "PlayerNameの護衛が、アクセリアの任務です。",
  ui_story_1014_10141401_59_dialog_content = "これは珍しい…あなたには欲望がありませんね。",
  ui_story_1014_10141401_60_dialog_content = "いや、違う…",
  ui_story_1014_10141401_61_dialog_content = "あなた自身が欲望の結晶だから、\nそれほど強大なのですね。",
  ui_story_1014_10141401_62_dialog_content = "フフフ…面白くなってきました。",
  ui_story_1014_10141401_63_dialog_content = "そのような欲望が滅びる時、\n一体どのような光景が見られるのでしょうか？",
  ui_story_1014_10141401_64_dialog_content = "実に楽しみです！",
  ui_story_1014_10141401_65_dialog_content = "皆、気を付けて。暗鬼たちが動き始めたわ！",
  ui_story_1014_10141402_1_dialog_content = "うっ…！",
  ui_story_1014_10141402_2_dialog_content = "アクセリア！",
  ui_story_1014_10141402_3_dialog_content = "アクセリアは…まだ戦えます。",
  ui_story_1014_10141402_4_dialog_content = "無理しないで。\n今のあなたに一番必要なものは治療よ！",
  ui_story_1014_10141402_5_dialog_content = "興ざめですね。",
  ui_story_1014_10141402_6_dialog_content = "啓光全体の欲望の結晶が…\n単なる軟弱な小娘なのですか？",
  ui_story_1014_10141402_7_dialog_content = "実に残念です。\n今の光霊には、つまらない欲望しか残っていないのですか？",
  ui_story_1014_10141402_8_dialog_content = "まったく理解に苦しみます。",
  ui_story_1014_10141402_9_dialog_content = "ノラはどうしてこんな無価値なものに執着するのでしょうか。",
  ui_story_1014_10141402_10_dialog_content = "アクセリアの悪口は許さないぞ！",
  ui_story_1014_10141402_11_dialog_content = "まだ自分の弱さを認めないのですか？",
  ui_story_1014_10141402_12_dialog_content = "では、これでどうでしょう？",
  ui_story_1014_10141402_13_dialog_content = "まずい…まだ暗鬼が隠れていたようだ。囲まれたか。",
  ui_story_1014_10141402_14_dialog_content = "ジョセリン、ヨーゼフ！\n左側、小型暗鬼の奇襲に気を付けろ！",
  ui_story_1014_10141402_15_dialog_content = "分かりました！",
  ui_story_1014_10141402_16_dialog_content = "インゲル、ショーン！\nお前たちは右側の大型暗鬼に対処してくれ！",
  ui_story_1014_10141402_17_dialog_content = "待ってください。\nあなたに私の指示をする権限は…",
  ui_story_1014_10141402_18_dialog_content = "<anim type=Shake><size=45>グオオ！！！</size></anim>",
  ui_story_1014_10141402_19_dialog_content = "こっちの奴は僕らに任せて！",
  ui_story_1014_10141402_20_dialog_content = "…仕方ありませんね。",
  ui_story_1014_10141402_21_dialog_content = "残りは、私と一緒にこいつの相手だ！",
  ui_story_1014_10141402_22_dialog_content = "結局、あなた方の欲望はその程度なのです。",
  ui_story_1014_10141402_23_dialog_content = "欲望が大きいほど、力も強くなります。",
  ui_story_1014_10141402_24_dialog_content = "あなた方の欲望は平凡なもの。\nだから、あなた方の力もこれほどまでに弱い。",
  ui_story_1014_10141402_25_dialog_content = "そして私の欲望は…世界のあらゆる欲望を滅ぼすことです！",
  ui_story_1014_10141402_26_dialog_content = "PlayerName、避けて！",
  ui_story_1014_10141402_27_dialog_content = "え！？",
  ui_story_1014_10141402_28_dialog_content = "私の手から逃れられる欲望などありません。",
  ui_story_1014_10141402_29_dialog_content = "チッ！",
  ui_story_1014_10141402_30_dialog_content = "PlayerName！",
  ui_story_1014_10141402_31_dialog_content = "うう、イテテ…",
  ui_story_1014_10141402_32_dialog_content = "しまった、装置が！",
  ui_story_1014_10141402_33_dialog_content = "低俗な欲望で…私の邪魔をしないでください。",
  ui_story_1014_10141402_34_dialog_content = "ぐっ！",
  ui_story_1014_10141402_35_dialog_content = "（急いで取り戻さないと…）",
  ui_story_1014_10141402_36_dialog_content = "あっ！",
  ui_story_1014_10141402_37_dialog_content = "これがあなたの欲望ですか、\n空の末裔の裏切り者。",
  ui_story_1014_10141402_38_dialog_content = "…",
  ui_story_1014_10141402_39_dialog_content = "これだけですか？",
  ui_story_1014_10141402_40_dialog_content = "返して！",
  ui_story_1014_10141402_41_dialog_content = "くだらない…",
  ui_story_1014_10141402_42_dialog_content = "あいつ、何を言ってるの…？",
  ui_story_1014_10141402_43_dialog_content = "くだらない、くだらない…実にくだらない。",
  ui_story_1014_10141402_44_dialog_content = "裏切り者の欲望が、\nエラーで生まれたゴミだけだなんて。",
  ui_story_1014_10141402_45_option_content = "ゴミなんかじゃない！",
  ui_story_1014_10141402_46_dialog_content = "そのデータは奇跡なんだ！",
  ui_story_1014_10141402_47_dialog_content = "巨像たちが長い時間をかけて何度も試行を重ねて、\n少しずつ経験を積み重ねて、ようやく生まれた人格なんだ！",
  ui_story_1014_10141402_48_dialog_content = "欲望なんて低俗なことにこだわってる奴に、\nその価値が分かるもんか！",
  ui_story_1014_10141402_49_dialog_content = "フ…低俗？",
  ui_story_1014_10141402_50_dialog_content = "裏切り者と考えが合うとは思いませんでしたね。",
  ui_story_1014_10141402_51_dialog_content = "そうです。欲望はどれも低俗なもの。\nこの世界に存在してはいけない。",
  ui_story_1014_10141402_52_dialog_content = "暗鬼は欲望を持たず、惑わされることもありません。\nゆえに、暗鬼がこの世界にふさわしい完璧な生物なのです。",
  ui_story_1014_10141402_53_dialog_content = "だからこそ、私は欲望を捨てるため、\nファントムになることを選びました。",
  ui_story_1014_10141402_54_dialog_content = "PlayerName、あんな奴の言葉に耳を貸しちゃダメ！",
  ui_story_1014_10141402_55_dialog_content = "一斉に仕掛けて、装置を取り戻しましょう！",
  ui_story_1014_10141402_56_dialog_content = "ですが…もういいです。\n気が変わりました。",
  ui_story_1014_10141402_57_dialog_content = "そんなにこれが欲しいのでしたら、\n持っていけばいいでしょう。",
  ui_story_1014_10141402_58_dialog_content = "うわっ、装置が！",
  ui_story_1014_10141402_59_dialog_content = "ふぅ、危なかった…",
  ui_story_1014_10141402_60_dialog_content = "（壊れてはいないみたいだ）",
  ui_story_1014_10141402_61_dialog_content = "（こいつの目的は一体何？\n僕たちをあざ笑いたいだけ…？）",
  ui_story_1014_10141402_62_dialog_content = "あなた方の欲望は十分に強いと思っていたのですが…\n私の間違いだったようです。",
  ui_story_1014_10141402_63_dialog_content = "結局、役に立たないゴミを追い求めているだけ。",
  ui_story_1014_10141402_64_dialog_content = "こんな所で滅ぼす気にもなれません。",
  ui_story_1014_10141402_65_dialog_content = "偉そうに！",
  ui_story_1014_10141402_66_dialog_content = "PlayerNameに必要な機械を自分から手放したのなら…\nもう手加減は要らないわね！",
  ui_story_1014_10141402_67_dialog_content = "食らいなさい、暗鬼！",
  ui_story_1014_10141402_68_dialog_content = "忠誠心など、最も無意味な欲望です。",
  ui_story_1014_10141402_69_dialog_content = "なんて力なの…！？",
  ui_story_1014_10141402_70_dialog_content = "今までもまったくやる気じゃなかった…！？",
  ui_story_1014_10141402_71_dialog_content = "<anim type=Shake><size=45>グオオ！！！</size></anim>",
  ui_story_1014_10141402_72_dialog_content = "ベルタ、危ない…散れ！氷花よ！",
  ui_story_1014_10141402_73_dialog_content = "実に残念です…",
  ui_story_1014_10141402_74_dialog_content = "この場にはつまらない欲望しかない。\n滅ぼしても面白くありません。",
  ui_story_1014_10141402_75_dialog_content = "ですが、空の末裔の裏切り者、PlayerName。\nあなたの欲望は…",
  ui_story_1014_10141402_76_dialog_content = "…",
  ui_story_1014_10141402_77_dialog_content = "もう少し時間をあげれば、\nとても面白く、とても…美味なものに変わるかもしれません。",
  ui_story_1014_10141402_78_dialog_content = "無論、<color=#FFB400>バイス</color>…あなたも。",
  ui_story_1014_10141402_79_dialog_content = "…え、私…？",
  ui_story_1014_10141402_80_dialog_content = "行きましょう、暗鬼たち…",
  ui_story_1014_10141402_81_dialog_content = "もうここにいる意味はありません。",
  ui_story_1014_10141402_82_dialog_content = "簡単に逃げられると思わないで！",
  ui_story_1014_10141402_83_dialog_content = "よせ、ベルタ！",
  ui_story_1014_10141402_84_dialog_content = "奴はただの暗鬼ではない…\n私たちが全力を出したとしても、相打ちがせいぜいだ。",
  ui_story_1014_10141402_85_dialog_content = "私たちにあいつらを追撃する余力はない。\n今すべきことは、撤退して応援を呼ぶことだ。",
  ui_story_1014_10141402_86_dialog_content = "でも…",
  ui_story_1014_10141402_87_dialog_content = "ベルタ、レオ騎士団長の判断は正しいわ。\n深追いするべきではない。",
  ui_story_1014_10141402_88_dialog_content = "ひとまず、トワイライトシティに戻りましょう。",
  ui_story_1014_10141402_89_dialog_content = "…はい。",
  ui_story_1014_10141402_90_dialog_content = "同意していただけて助かりました。",
  ui_story_1014_10141402_91_dialog_content = "戦場を知る者なら、誰もがそう結論するわ。",
  ui_story_1014_10141402_92_dialog_content = "（ノラが姿を見せず、\n別のファントムが引き寄せられた…）",
  ui_story_1014_10141402_93_dialog_content = "（これは偶然なのでしょうか？それとも…）",
  ui_story_1014_10141402_94_dialog_content = "（とにかく、今回の任務は完全に失敗です。\n予測が外れて、ノラは現れなかった）",
  ui_story_1014_10141402_95_dialog_content = "（他の方法を考えるしかないようです）",
  ui_story_1014_10141402_95X1_dialog_content = "このまま戻る？ガイダンスを置いたまま…？",
  ui_story_1014_10141402_95X2_dialog_content = "一緒に連れて帰る方法はないのかな？\nねえ、バイス。啓光の技術で何とかできない？",
  ui_story_1014_10141402_95X3_dialog_content = "たぶん、難しいわ…",
  ui_story_1014_10141402_95X4_dialog_content = "…",
  ui_story_1014_10141402_95X5_dialog_content = "PlayerName、気持ちはお察ししますが、\n今の私たちではどうしようもありません。",
  ui_story_1014_10141402_95X6_dialog_content = "インゲル、PlayerNameにとっては大切な存在なんだよ。\n本当に方法はないの？",
  ui_story_1014_10141402_95X7_dialog_content = "この巨像はもともと損傷していたうえに、\n暴走を起こし、また深刻な損傷を負いました。",
  ui_story_1014_10141402_95X8_dialog_content = "今、こうして動いているだけでも、\nすでに奇跡です…",
  ui_story_1014_10141402_95X9_dialog_content = "そんな…",
  ui_story_1014_10141402_95X10_dialog_content = "<color=#e8d9bb>空の末裔PlayerNameの退出意志を検出…</color>",
  ui_story_1014_10141402_95X11_dialog_content = "ガイダンス？",
  ui_story_1014_10141402_95X12_dialog_content = "<color=#e8d9bb>ガイダンスは空の末裔PlayerNameに質問します。</color>",
  ui_story_1014_10141402_95X13_dialog_content = "<color=#e8d9bb>空の末裔PlayerName、次回の訪問日時と\nガイダンスの修理計画を教えてください。</color>",
  ui_story_1014_10141402_95X14_dialog_content = "…",
  ui_story_1014_10141402_95X15_dialog_content = "僕にも…分からないよ。",
  ui_story_1014_10141402_95X16_dialog_content = "ごめん…また長いこと待たせちゃうね…",
  ui_story_1014_10141402_95X17_dialog_content = "<color=#e8d9bb>受信しました。</color>",
  ui_story_1014_10141402_95X18_dialog_content = "<color=#e8d9bb>35号の設定に基づき、\n空の末裔PlayerNameに祝福の言葉を送ります。</color>",
  ui_story_1014_10141402_95X19_dialog_content = "<color=#e8d9bb>ガイダンスを修理できずとも、悲しまないでください。\nあなたは前を向き、進み続けてください。</color>",
  ui_story_1014_10141402_95X20_dialog_content = "どういうこと？…35号からのメッセージ？\n35号はいつかこんな日が来るって予想してたの？",
  ui_story_1014_10141402_95X21_dialog_content = "<color=#e8d9bb>ガイダンスは35号と共に、PlayerNameの帰途が\nすばらしい旅になることを祈っています。</color>",
  ui_story_1014_10141402_95X22_dialog_content = "ありがとう…",
  ui_story_1014_10141402_95X23_dialog_content = "分かった…僕は、君たちの分まで旅を続ける…",
  ui_story_1014_10141402_95X24_dialog_content = "PlayerName、行きましょう。",
  ui_story_1014_10141402_95X25_dialog_content = "うん、行こう。僕たちにはまだ、\nやらなきゃいけないことがあるんだ。",
  ui_story_1014_10141402_96_dialog_content = "<color=#e8d9bb>ソラヴァン・ブリッジ</color>",
  ui_story_1014_10141402_97_dialog_content = "ソラヴァン、起動！",
  ui_story_1014_10141402_98_dialog_content = "あの暗鬼たちは？\n私たちを追いかけてきていませんね？",
  ui_story_1014_10141402_99_dialog_content = "感知できないから、近くにはいないはずだよ。",
  ui_story_1014_10141402_100_dialog_content = "一体何を考えているのか分からない相手だったが…\n何だかバカにされた気分だな。",
  ui_story_1014_10141402_101_dialog_content = "だが、いつの日か、\n暗鬼どもに私たちを見くびった代償を支払わせてやる…",
  ui_story_1014_10141402_102_dialog_content = "アクセリアの身体は大丈夫？\nずいぶん激しい攻撃を受けてたけど…",
  ui_story_1014_10141402_103_dialog_content = "アクセリアは問題ありません。",
  ui_story_1014_10141402_104_dialog_content = "身体は弱いですが…ゴホゴホッ…\nアクセリアは、そう簡単にやられたりしません。",
  ui_story_1014_10141402_105_dialog_content = "（それも「改造」の結果なのかな？）",
  ui_story_1014_10141402_107_dialog_content = "（大元帥は実験に強く反対していた。\nきっと何か、彼女しか知らないことがあるんだろう）",
  ui_story_1014_10141402_109_dialog_content = "（常人離れした戦闘力と回復力と言えば、大元帥も…）",
  ui_story_1014_10141402_110_dialog_content = "PlayerName、何を考えてるの？",
  ui_story_1014_10141402_111_dialog_content = "えっ？な、何でもないよ。",
  ui_story_1014_10141402_112_dialog_content = "どうしたの？バイス。",
  ui_story_1014_10141402_113_dialog_content = "別に。ただ、よく分からないことがあるだけよ。",
  ui_story_1014_10141402_114_dialog_content = "あのアスモデウスって暗鬼、\nなんで最後に私の名前を呼んだのかしら？",
  ui_story_1014_10141402_115_dialog_content = "会ったことなんかないし、\n名乗ってもいないのに。",
  ui_story_1014_10141402_116_option_content = "ハーモナイザーのせいかな？",
  ui_story_1014_10141402_117_dialog_content = "バイスはハーモナイザーを使って、\n特殊な力を手に入れてるでしょ。",
  ui_story_1014_10141402_118_dialog_content = "そのことを知ってて、\nバイスに目を付けてたとか？",
  ui_story_1014_10141402_119_dialog_content = "分からないわ…",
  ui_story_1014_10141402_120_dialog_content = "何を考えてるかなんて、まったく想像もできないしね。",
  ui_story_1014_10141402_121_option_content = "身体の状態のせいかな？",
  ui_story_1014_10141402_122_dialog_content = "ハーモナイザーを使ったから、\nバイスの身体は特別なものになってるでしょ？",
  ui_story_1014_10141402_123_dialog_content = "このあいだ光りだしたのも、あの装置のせいだったし。",
  ui_story_1014_10141402_124_dialog_content = "だけど、今の見た目で変化なんて分からないでしょ？",
  ui_story_1014_10141402_125_dialog_content = "何か特別な能力があって、内側の変化に気付いたとか？",
  ui_story_1014_10141402_126_dialog_content = "分からないなぁ…",
  ui_story_1014_10141402_127_dialog_content = "まぁ、今は気にしても仕方ないよ。\nそれよりバイス、調子はどう？",
  ui_story_1014_10141402_128_dialog_content = "ずいぶん戦ったけど、\nどこかおかしくなってたりしない？",
  ui_story_1014_10141402_129_dialog_content = "安心して。少し疲れてるけど、\nちょっと休めばすぐに元気になるわ。",
  ui_story_1014_10141402_130_dialog_content = "激しい戦いだったけど、\n身体におかしなことは起こってないわね。",
  ui_story_1014_10141402_131_dialog_content = "そう？それなら安心したよ。",
  ui_story_1014_10141402_132_dialog_content = "あとはカナン城に戻って、\n手に入れたパーツとデータでソラヴァンを修理するだけだ！",
  ui_story_1014_10141402_133_dialog_content = "その前に、アクセリアたちをトワイライトシティまで送らないと。",
  ui_story_1014_10141402_134_dialog_content = "うん！",
  ui_story_1014_10141402_135_dialog_content = "<color=#e8d9bb>ザザ――</color>",
  ui_story_1014_10141402_136_dialog_content = "あれ？ソラヴァンにリモート通信…\n送信者は…ガイダンス！？",
  ui_story_1014_10141402_137_dialog_content = "<color=#e8d9bb>ザザ…</color>",
  ui_story_1014_10141402_137X1_dialog_content = "<color=#e8d9bb>35号の命令に基づき、\n空の末裔の退去後、このプログラムの実行を開始します。</color>",
  ui_story_1014_10141402_138_dialog_content = "<color=#e8d9bb>…設定条件が一致したため、\nガイダンスは空の末裔PlayerNameにリクエストを送信します。</color>",
  ui_story_1014_10141402_139_dialog_content = "巨像が僕に…リクエスト？何かして欲しいの？",
  ui_story_1014_10141402_140_dialog_content = "<color=#e8d9bb>ガイダンスの全データは、\n空の末裔、PlayerNameに継承されました。</color>",
  ui_story_1014_10141402_141_dialog_content = "<color=#e8d9bb>ガイダンスはエネルギーコアの損傷が修復不能であるため、\nまもなく運転を停止します。</color>",
  ui_story_1014_10141402_142_dialog_content = "<color=#e8d9bb>以上2件の条件に一致したため、35号の命令に基づき、\nガイダンスは直近の空の末裔にリクエストを送信します――</color>",
  ui_story_1014_10141402_143_dialog_content = "まさか…",
  ui_story_1014_10141402_144_dialog_content = "<color=#e8d9bb>ガイダンスはPlayerNameに、\nガイダンスのための<color=#FFB400>詩</color>をリクエストします。</color>",
  ui_story_1014_10141402_145_dialog_content = "…",
  ui_story_1014_10141402_146_dialog_content = "分かったよ。",
  ui_story_1014_10141402_147_dialog_content = "だけど、詩なんて書いたことないから、\nうまく書けるかわからないよ。",
  ui_story_1014_10141402_148_dialog_content = "君は僕たちと共に旅に出た",
  ui_story_1014_10141402_149_dialog_content = "果てしない星の海の中を、君の翼で飛んでいた",
  ui_story_1014_10141402_150_dialog_content = "長い時、長い道のりを越える旅路だった",
  ui_story_1014_10141402_151_dialog_content = "星々の光もいつしか消えて",
  ui_story_1014_10141402_152_dialog_content = "長く孤独な旅だけが残った",
  ui_story_1014_10141402_153_dialog_content = "やがて故郷への呼び声が響き",
  ui_story_1014_10141402_154_dialog_content = "しかし、故郷の方角を見失っていた",
  ui_story_1014_10141402_155_dialog_content = "君は星空の中を長く漂い",
  ui_story_1014_10141402_156_dialog_content = "暗闇の中に長くとどまった",
  ui_story_1014_10141402_157_dialog_content = "時の流れと災いが故郷の痕跡を消し去って",
  ui_story_1014_10141402_158_dialog_content = "今、故郷への道を照らす明かりが再びともされた",
  ui_story_1014_10141402_159_dialog_content = "君の意識が風とタンポポに乗り",
  ui_story_1014_10141402_160_dialog_content = "天空ノ谷へ帰らんことを願う",
  ui_story_1014_10141402_161_dialog_content = "…",
  ui_story_1014_10141402_162_dialog_content = "（やっぱり、詩なんて書いたことないから、\nめちゃくちゃだ…）",
  ui_story_1014_10141402_163_dialog_content = "<color=#e8d9bb>詩を受信しました。録音を再生します…</color>",
  ui_story_1014_10141402_164_dialog_content = "ありがとう、ここに来た、未来の優しい人…",
  ui_story_1014_10141402_165_dialog_content = "これは…35号の声？",
  ui_story_1014_10141402_166_dialog_content = "ガイダンスもきっと、あなたの詩を喜んでくれるでしょう。",
  ui_story_1014_10141402_166X1_dialog_content = "顔を合わせることはできませんが、\nこの気持ちを互いに分かち合えていると信じています。",
  ui_story_1014_10141402_166X2_dialog_content = "それこそ感知能力を使わなくても、ね！",
  ui_story_1014_10141402_166X3_dialog_content = "うん…感知能力を使わなくても…\n今にも涙があふれそうだ、この気持ち…感じてるよ…",
  ui_story_1014_10141402_166X4_dialog_content = "「贈り物」を見つけたあなたに、いつも多くの仲間が寄り添い、\n孤独を感じることのない、すばらしい旅が続くことを心から願っています。",
  ui_story_1014_10141402_166X5_dialog_content = "「贈り物」も一緒に、旅をさせてあげてください。\nそれがあたしとガイダンスの願いです。",
  ui_story_1014_10141402_166X6_dialog_content = "ありがとう…ガイダンス…35号…",
  ui_story_1014_10141402_166X7_dialog_content = "君たちからの「贈り物」、大切に使わせてもらうよ。",
  ui_story_1014_10141402_168_dialog_content = "さようなら、ガイダンス。",
  ui_story_1014_10141402_169_dialog_content = "さようなら、35号。",
  ui_story_1014_10141501_1_dialog_content = "<color=#e8d9bb>トワイライトシティ、しばらく後</color>",
  ui_story_1014_10141501_2_dialog_content = "ここまで送ってくだされば結構です。",
  ui_story_1014_10141501_3_dialog_content = "本当にありがとうございました、PlayerName。",
  ui_story_1014_10141501_4_dialog_content = "とんでもない。僕が君たちに手伝いをお願いしたんだから。",
  ui_story_1014_10141501_5_dialog_content = "では皆さん、またお会いしましょう。",
  ui_story_1014_10141501_6_dialog_content = "共に戦えて光栄だった。\n私も帰ることにしよう。",
  ui_story_1014_10141501_7_dialog_content = "縁があればまた会おう、PlayerName。",
  ui_story_1014_10141501_8_dialog_content = "待って。",
  ui_story_1014_10141501_9_dialog_content = "何かありましたか？",
  ui_story_1014_10141501_10_dialog_content = "まだ質問の答えを聞いていないわ。\nなぜ不公平だと思っているの？",
  ui_story_1014_10141501_11_dialog_content = "ハハハ…まだそのことを気にしておられたのですか？",
  ui_story_1014_10141501_12_dialog_content = "では、私も率直にお答えしましょう――",
  ui_story_1014_10141501_13_dialog_content = "今の白夜城には変革が必要だと考えています。",
  ui_story_1014_10141501_14_dialog_content = "あなた！？",
  ui_story_1014_10141501_15_dialog_content = "ご存じの通り、白夜城の爵位は、\n血筋によって継承されるものです。",
  ui_story_1014_10141501_16_dialog_content = "自身の能力に頼らず地位を手に入れ、\nその後は保身のためだけに行動する。",
  ui_story_1014_10141501_17_dialog_content = "これでは能力があっても貴族でない者は、\n白夜城で昇進することが非常に難しい。",
  ui_story_1014_10141501_18_dialog_content = "白夜城には抜本的な変革が必要です。\nそして、私はその嵐を起こす人物になりたいと考えています。",
  ui_story_1014_10141501_19_dialog_content = "その話を私が聞けば、\n反乱の罪であなたを法廷に告発できることが分かっているの？",
  ui_story_1014_10141501_20_dialog_content = "ハハハハ…カレン殿下はおそらく…\nいえ。間違いなく、そのようなことはなさらないでしょう。",
  ui_story_1014_10141501_21_dialog_content = "カレン殿下は高貴な生まれではあっても、\n権力に目がくらんではいませんから。",
  ui_story_1014_10141501_22_dialog_content = "殿下はただの白夜城貴族とは違う。\n戦場の洗礼を受けた、本物の騎士であられる。",
  ui_story_1014_10141501_23_dialog_content = "同じ騎士である者として、私には分かります。",
  ui_story_1014_10141501_24_dialog_content = "果たしてそうかしら？",
  ui_story_1014_10141501_25_dialog_content = "それなら、己の野心の実現のため、努力することね。",
  ui_story_1014_10141501_26_dialog_content = "どちらの選択が白夜城にとってより有益となるか、\nそれぞれの行動で証明しましょう。",
  ui_story_1014_10141501_27_dialog_content = "ええ、約束ですよ！",
  ui_story_1014_10141501_28_dialog_content = "カレン殿下、このまま行かせて構わないのですか？",
  ui_story_1014_10141501_29_dialog_content = "構わないわ。",
  ui_story_1014_10141501_30_dialog_content = "そう言えば、ジョセリンも…あれ？ジョセリンは？",
  ui_story_1014_10141501_31_dialog_content = "ジョセリンは通りがかった人に\n何かを頼まれて、去っていきました。",
  ui_story_1014_10141501_32_dialog_content = "PlayerNameがカレンとレオ騎士団長の会話を見ていた時です。",
  ui_story_1014_10141501_33_dialog_content = "そういう性格の人だからね…\n何か頼まれると、すぐ飛んで行っちゃうんだ。",
  ui_story_1014_10141501_34_dialog_content = "お別れを言うヒマもなしなんて、残念ね。",
  ui_story_1014_10141501_35_dialog_content = "いずれまた会えるでしょう。",
  ui_story_1014_10141501_36_dialog_content = "インゲル、ショーン、アクセリアも帰還します。",
  ui_story_1014_10141501_37_dialog_content = "任務は無事に完了しました。",
  ui_story_1014_10141501_38_dialog_content = "そうは言うものの、\nアスモデウスの件は上に報告せねばなりません。",
  ui_story_1014_10141501_39_dialog_content = "ここでお別れです。\nPlayerName、バイス中尉、カレン殿下、ベルタ。",
  ui_story_1014_10141501_40_dialog_content = "また会おうね！",
  ui_story_1014_10141501_41_dialog_content = "アクセリアはPlayerNameを援護し、\n任務を完了しました。",
  ui_story_1014_10141501_42_dialog_content = "そうだ、次の合同軍事演習には僕たちも参加するよ。",
  ui_story_1014_10141501_43_dialog_content = "演習の戦場で会おうね！",
  ui_story_1014_10141501_44_dialog_content = "演習で？ええ、私も楽しみにしてるわ！",
  ui_story_1014_10141501_45_dialog_content = "その時に決着をつけましょう。",
  ui_story_1014_10141501_46_option_content = "またね！",
  ui_story_1014_10141501_47_dialog_content = "これで皆を無事に、トワイライトシティまで送り届けられたわね。",
  ui_story_1014_10141501_48_dialog_content = "僕たちも急いでカナン城に戻ろう。",
  ui_story_1014_10141501_49_dialog_content = "アスモデウスという暗鬼は気がかりだけれど、\nいま大事なことは、ソラヴァンの修理ね。",
  ui_story_1014_10141501_50_dialog_content = "そうよ。グズグズしていられないわ！",
  ui_story_1014_10141501_51_dialog_content = "行きましょう！",
  ui_story_1014_10141501_52_dialog_content = "<color=#e8d9bb>カナン城、しばらく後</color>",
  ui_story_1014_10141501_53_dialog_content = "必要なデータを持って帰ってきました！",
  ui_story_1014_10141501_54_dialog_content = "えっ…あ、何？",
  ui_story_1014_10141501_55_dialog_content = "もう帰ってきたの？こんなに早く？",
  ui_story_1014_10141501_56_dialog_content = "はい。",
  ui_story_1014_10141501_57_dialog_content = "途中で思わぬ敵に遭遇したけど、\n無事にデータを持ち帰ってきました。",
  ui_story_1014_10141501_58_dialog_content = "ええ、聞いたわ。\n<color=#FFB400>アスモデウス</color>って名前のファントムでしょ？",
  ui_story_1014_10141501_59_dialog_content = "もう知ってるんですか！？",
  ui_story_1014_10141501_60_dialog_content = "…それもそうか。\nトワイライトシティにも啓光の軍隊があったっけ。",
  ui_story_1014_10141501_61_dialog_content = "何が有っても、通信1本でカナン城全体に情報が届くんだ。",
  ui_story_1014_10141501_62_dialog_content = "そんなところよ。\n啓光の情報システムを甘く見ないことね。",
  ui_story_1014_10141501_63_dialog_content = "ま、面倒ごとの対処は大元帥に任せればいいわ。",
  ui_story_1014_10141501_64_dialog_content = "そんなことより、あなたが持ち帰ってきた\n巨像のデータをすぐにでも見たいの。",
  ui_story_1014_10141501_65_dialog_content = "どうやって手に入れたの？\n今まで啓光が送った探検隊は、みんな手ぶらで帰ってきてたのよ。",
  ui_story_1014_10141501_66_dialog_content = "それは…",
  ui_story_1014_10141501_67_option_content = "僕が空の末裔だから",
  ui_story_1014_10141501_68_dialog_content = "巨像の意識は、ある空の末裔が一生を通した努力を続けて、\nようやく生まれたものだったんです。",
  ui_story_1014_10141501_69_dialog_content = "僕は最後の空の末裔として、\nホコリをかぶっていた贈り物を取り戻しただけです。",
  ui_story_1014_10141501_70_dialog_content = "面白いわね。これが空の末裔の遺産なの？",
  ui_story_1014_10141501_71_option_content = "それが「贈り物」でもあるから",
  ui_story_1014_10141501_72_dialog_content = "あの巨像は保存された貴重なデータを渡すために、\nずっと他の人が来るのを待っていたんです。",
  ui_story_1014_10141501_73_dialog_content = "回帰の塔のフランシス先生と同じように。",
  ui_story_1014_10141501_74_dialog_content = "代わりに、あの巨像から最後に…\n詩を書くように頼まれました。",
  ui_story_1014_10141501_75_dialog_content = "巨像がそんなことをしたの？\n実に不思議ね。",
  ui_story_1014_10141501_76_dialog_content = "とりあえず、データを見せて。",
  ui_story_1014_10141501_77_dialog_content = "…",
  ui_story_1014_10141501_78_dialog_content = "チッ…このデータ、あたしが思ってたより、\nはるかに複雑ね。",
  ui_story_1014_10141501_79_dialog_content = "どういうことですか？",
  ui_story_1014_10141501_80_dialog_content = "複雑って…ソラヴァンは直せるんですか？",
  ui_story_1014_10141501_81_dialog_content = "あわてないで。ゆっくり説明するから。",
  ui_story_1014_10141501_82_dialog_content = "あなたのもう知ってることだけど、\n巨像の意識は、ある空の末裔が長い時間をかけたことで生まれたの。",
  ui_story_1014_10141501_83_dialog_content = "はい…",
  ui_story_1014_10141501_84_dialog_content = "彼女は巨像の本来の設定では考慮されていなかった状況を引き起こして、\n巨像はそれに反応し、未知の対応をした。",
  ui_story_1014_10141501_85_dialog_content = "普通はそういうのを「エラー」って呼ぶけど、\nここでは「<color=#FFB400>成長</color>」と呼びたいわね。",
  ui_story_1014_10141501_86_dialog_content = "ただ、変化が生まれた根本的な理由は、\n偶発的なもの――",
  ui_story_1014_10141501_87_dialog_content = "意識データの中には、\nとても複雑でまとまりのない情報があるだけなのよ。",
  ui_story_1014_10141501_88_dialog_content = "つまり、変化をもたらしたデータ群の中には、実際には役に立ってないものもあれば、\n鍵となったものも混ざってるの。",
  ui_story_1014_10141501_89_dialog_content = "さらに、それぞれの巨像のデータは互いに独立しているから、\n巨像ごとの変化も異なっているわ。",
  ui_story_1014_10141501_90_dialog_content = "コピーしてきた意識データの形成過程が、\nソラヴァンにそのまま適用できるわけではないの。",
  ui_story_1014_10141501_91_dialog_content = "複雑な理論は僕には分かりません…",
  ui_story_1014_10141501_92_dialog_content = "僕が知りたいのは、ソラヴァンを救えるかどうかだけです！",
  ui_story_1014_10141501_93_dialog_content = "少し時間をかけてデータを分析しないと、\nはっきりとした答えを出せないわ。",
  ui_story_1014_10141501_94_dialog_content = "とはいえ、ソラヴァン自身のデータだけでは足りなかったけど、\n今はこのデータを相互参照できる。",
  ui_story_1014_10141501_95_dialog_content = "ソラヴァンが回復できる確率は大幅に上がってるわよ。",
  ui_story_1014_10141501_96_dialog_content = "あたしを信じて、もう少し時間をちょうだい。",
  ui_story_1014_10141501_97_dialog_content = "また待つしかないなんて…",
  ui_story_1014_10141501_98_dialog_content = "そんなに落ち込まないで。\n人工知能の研究に関しては、自信があるの。",
  ui_story_1014_10141501_99_dialog_content = "いろいろあったんでしょう？\nあなたも少し休んだ方がいいわ。",
  ui_story_1014_10141501_100_dialog_content = "この先はあたしの戦場よ。",
  ui_story_1014_10141501_101_dialog_content = "PlayerName、ソラヴァンの様子は？",
  ui_story_1014_10141501_102_dialog_content = "あのデータは役に立ちそう？",
  ui_story_1014_10141501_103_dialog_content = "僕にも分からないよ。\nもう少し時間をかけてデータを解析する必要があるって言われた。",
  ui_story_1014_10141501_104_dialog_content = "そう…",
  ui_story_1014_10141501_105_dialog_content = "うまくいくといいわね。",
  ui_story_1014_10141501_106_dialog_content = "そう願うしかないよ。",
  ui_story_1014_10141501_107_dialog_content = "<color=#e8d9bb>ピピピピ――</color>",
  ui_story_1014_10141501_108_dialog_content = "バイス中尉、PlayerName、2人ともそこにいますか？",
  ui_story_1014_10141501_109_dialog_content = "ユリシーズ教授！？",
  ui_story_1014_10141501_110_dialog_content = "ハーモナイザーの研究について、進展がありました。",
  ui_story_1014_10141501_111_dialog_content = "バイス中尉、PlayerNameと直ちに指定した場所へ向かってください。\n後ほど座標を送信します。",
  ui_story_1014_10141501_112_dialog_content = "具体的な座標は機密事項となります。\n部外者は同行させないでください。",
  ui_story_1014_10141501_113_dialog_content = "確認したら返信を。",
  ui_story_1014_10141501_114_dialog_content = "はい、バイス中尉、確認しました。",
  ui_story_1014_10141501_115_dialog_content = "よろしい。通信を終了します。",
  ui_story_1014_10141501_116_dialog_content = "また機密事項？私は役に立てなさそうね。",
  ui_story_1014_10141501_117_dialog_content = "それなら、今のうちに白夜城に戻るとするわ。",
  ui_story_1014_10141501_118_dialog_content = "アイアンソーン騎士団に関する情報を\n調べておかないといけないもの。",
  ui_story_1014_10141501_119_dialog_content = "トワイライトシティの状況も報告しないと。",
  ui_story_1014_10141501_120_dialog_content = "カレン、まだ気にしてるの？",
  ui_story_1014_10141501_121_dialog_content = "気にならないわけがないでしょう？",
  ui_story_1014_10141501_122_dialog_content = "白夜城に関わることよ。\nあの騎士団…特にレオ騎士団長のことは確認しておく必要があるわ。",
  ui_story_1014_10141501_123_dialog_content = "彼の考えを否定する気はないわ。\n確かに、彼なら白夜城を良くできるかもしれない。",
  ui_story_1014_10141501_124_dialog_content = "でも、彼が白夜城の脅威になりうるという事実も無視できないの。",
  ui_story_1014_10141501_125_dialog_content = "さすがはカレン、しっかりしてるわね。",
  ui_story_1014_10141501_126_dialog_content = "じゃあ、私たちも急いで向かいましょう。",
  ui_story_1014_10141501_127_dialog_content = "うん、今すぐ出発しよう。",
  ui_story_1014_10141501_128_dialog_content = "<color=#e8d9bb>啓光連邦、某所</color>",
  ui_story_1014_10141501_129_dialog_content = "座標はここだけど…\nこんな所にシェルターがあったのね。",
  ui_story_1014_10141501_130_dialog_content = "このシェルター、\n啓光のどの地図にも載ってないわ。",
  ui_story_1014_10141501_131_dialog_content = "座標を知らなければ、見つけるのは不可能ね。",
  ui_story_1014_10141501_132_dialog_content = "…",
  ui_story_1014_10141501_133_dialog_content = "警備がかなり厳重みたいだね…",
  ui_story_1014_10141501_134_dialog_content = "秘密の施設だもの…当然よ。",
  ui_story_1014_10141501_135_dialog_content = "いらっしゃいましたか。",
  ui_story_1014_10141501_136_dialog_content = "（どうしてこの人が…）",
  ui_story_1014_10141501_137_dialog_content = "（この人と話してると、\n観察されてるみたいで気分が悪いんだよね…）",
  ui_story_1014_10141501_138_dialog_content = "どうして君が？\n僕たちはユリシーズ教授に呼ばれてきたんだ。",
  ui_story_1014_10141501_139_dialog_content = "ユリシーズ長官は緊急かつ重要な用件があるとのことで、\nお2人への応対を私に命じられました。",
  ui_story_1014_10141501_140_dialog_content = "こっちも急ぎで呼び出しておいて…\nそうとう緊急の用件なんだろうね？",
  ui_story_1014_10141501_141_dialog_content = "あなた方はすでにかなりのことをご存じですから、\nここでの研究を隠し立てする必要もないでしょう。",
  ui_story_1014_10141501_142_dialog_content = "まずは状況を説明します。",
  ui_story_1014_10141501_143_dialog_content = "「啓明の星計画」の開始は、\nここにある<color=#FFB400>もう1台のハーモナイザー</color>と関係があるのです。",
  ui_story_1014_10141501_144_dialog_content = "何ですって？\nハーモナイザーはあの1台だけではなかったんですか！？",
  ui_story_1014_10141501_145_dialog_content = "そうです。啓光連邦は何年も前に\nハーモナイザーを発見していました。",
  ui_story_1014_10141501_146_dialog_content = "この装置の研究を通じて、\n我々は光霊の改造法を発見したのです。",
  ui_story_1014_10141501_147_dialog_content = "ただ、様々な理由から、\nこの装置は天空ノ谷のものほど完全ではありませんでした。",
  ui_story_1014_10141501_148_dialog_content = "啓光が発明した改造の方法も、\n装置の一部が欠損していたため、完璧とはなりませんでした。",
  ui_story_1014_10141501_149_dialog_content = "現在でも、改造における能力変化の方向性を完全に制御することができず、\n失敗確率も極めて高くなっています。",
  ui_story_1014_10141501_150_dialog_content = "じゃあ、なんでそんな研究を続けてるの？",
  ui_story_1014_10141501_151_dialog_content = "危険で、苦痛をもたらすかもしれないって\n分かっておきながら…",
  ui_story_1014_10141501_152_dialog_content = "どうしてまだそんなことを続けられるの！？",
  ui_story_1014_10141501_153_dialog_content = "改めて強調しておきましょうか。\n啓光の者のほとんどは、何も特殊能力がないからです。",
  ui_story_1014_10141501_154_dialog_content = "こうでもしなければ、啓光連邦の存在は維持できません。",
  ui_story_1014_10141501_155_option_content = "…",
  ui_story_1014_10141501_156_option_content = "賛成できない",
  ui_story_1014_10141501_157_dialog_content = "気持ちは理解できますが、\n私たちの関係は、あくまで取引であることを忘れないでいただきたい。",
  ui_story_1014_10141501_158_dialog_content = "気に入らないのでしたら当然、\nあなたには認可された回帰の塔の研究を停止する権利があります。",
  ui_story_1014_10141501_159_dialog_content = "そうなれば、ハーモナイザーや副作用に対する研究は\n滞ってしまうでしょうが…",
  ui_story_1014_10141501_160_dialog_content = "（バイスやバートンを盾にとって、僕を脅すつもり…？）",
  ui_story_1014_10141501_161_dialog_content = "（うまくやられた…）",
  ui_story_1014_10141501_162_dialog_content = "その表情から判断するに、\nご理解いただけたようですね。",
  ui_story_1014_10141501_163_dialog_content = "それで、一体何をするつもりなの？",
  ui_story_1014_10141501_164_dialog_content = "回帰の塔の中のものを研究し、\n以前の不完全なハーモナイザーも改良されました。",
  ui_story_1014_10141501_165_dialog_content = "私たちはその2台の壊れた装置を利用し、\n完全で副作用のないハーモナイザーを作ろうとしています。",
  ui_story_1014_10141501_166_dialog_content = "完全なハーモナイザーが完成すれば、\nさまざまな問題はたちどころに解決できるでしょう。",
  ui_story_1014_10141501_167_dialog_content = "それこそ、バイス中尉とバートン軍団長の体に存在している\n未知なる副作用まで。",
  ui_story_1014_10141501_168_dialog_content = "…それで、僕に何をさせたいの？",
  ui_story_1014_10141501_169_dialog_content = "ハーモナイザーは空の末裔の技術です。\n空の末裔の感知能力でなければ解読できないデータもあります。",
  ui_story_1014_10141501_170_dialog_content = "現在、そうしたデータの復元を試みています。\n完了次第、あなたの助力が必要となります。",
  ui_story_1014_10141501_171_dialog_content = "今はただ、待っていただくだけで結構です。",
  ui_story_1014_10141501_172_dialog_content = "（大急ぎで呼び出したくせに…）",
  ui_story_1014_10141501_173_dialog_content = "…分かったよ。",
  ui_story_1014_10141501_174_dialog_content = "ご協力ありがとうございます。",
  ui_story_1014_10141501_175_dialog_content = "私は他の任務がありますので、\nこれで失礼します。",
  ui_story_1014_10141501_176_dialog_content = "イヤな気分だわ。",
  ui_story_1014_10141501_177_dialog_content = "これじゃまるっきり、私がPlayerNameを脅す道具じゃない。",
  ui_story_1014_10141501_178_dialog_content = "自分の事をそんなふうに言っちゃダメだよ…",
  ui_story_1014_10141501_179_dialog_content = "あの人たちの助けを借りずに、\n僕だけの力でバイスの副作用を治すことはできないんだし。",
  ui_story_1014_10141501_180_dialog_content = "PlayerName…",
  ui_story_1014_10141501_181_dialog_content = "私のことは考えなくていいわ。",
  ui_story_1014_10141501_182_dialog_content = "身体がたまに光るぐらいで、\n他に違和感はないもの。",
  ui_story_1014_10141501_183_dialog_content = "だから、あんな人たちの助けを借りなくても大丈夫よ。\n後遺症をどうにかする方法だって、そのうち見つかるわ。",
  ui_story_1014_10141501_184_dialog_content = "PlayerNameに、\n自分の本心に背くような決断をしてもらいたくない。",
  ui_story_1014_10141501_185_option_content = "ありがとう、バイス",
  ui_story_1014_10141501_186_dialog_content = "でも、治すことをあきらめて欲しくはないよ。",
  ui_story_1014_10141501_187_option_content = "バイスを放っておけない",
  ui_story_1014_10141501_188_dialog_content = "仲間はみんな大事なんだって、\n子どもの頃からソラヴァンに教わってきたんだ。",
  ui_story_1014_10141501_189_dialog_content = "誰であろうと、\n仲間を危険な目には遭わせられないよ。",
  ui_story_1014_10141501_190_dialog_content = "…",
  ui_story_1014_10141501_191_dialog_content = "（なんだか雰囲気が重苦しくなってきた…）",
  ui_story_1014_10141501_192_dialog_content = "ねえ、少し散歩でもして、時間をつぶさない？",
  ui_story_1014_10141501_193_dialog_content = "ずっとここにいてもやることはないし、\nいつ呼ばれるかも言われてないし。",
  ui_story_1014_10141501_194_dialog_content = "ええ。近くを少し散歩するくらいなら、大丈夫よね。",
  ui_story_1014_10141501_195_dialog_content = "（このシェルター、本当に大きいな…）",
  ui_story_1014_10141501_196_dialog_content = "（通路の両側の部屋、全部実験室みたいだ）",
  ui_story_1014_10141501_197_dialog_content = "（中で人知れず、どんな実験がどれだけ行われてるんだか…）",
  ui_story_1014_10141501_198_dialog_content = "あなたの要求には同意できません。",
  ui_story_1014_10141501_199_dialog_content = "あの装置はまだ実験段階です。\nそれに何より、あなたの被検体はまだ不安定な状態です。",
  ui_story_1014_10141501_200_dialog_content = "そのようなものを使えば、\n高い確率で貴重な機器に被害が及びます。",
  ui_story_1014_10141501_201_dialog_content = "そもそも、あの不完全な装置で\n被検体を治療できるとも限りません。",
  ui_story_1014_10141501_202_dialog_content = "これは私の実験。\nあなたが口を挟むことではないわ。",
  ui_story_1014_10141501_203_dialog_content = "大人しく機器の使用権を私に与えるだけでいいの。\nあとは黙っていなさい。",
  ui_story_1014_10141501_204_dialog_content = "遠くで誰かが話してるみたいね。",
  ui_story_1014_10141501_205_dialog_content = "この声…聞き覚えがない？",
  ui_story_1014_10141501_206_dialog_content = "同意はできません。",
  ui_story_1014_10141501_207_dialog_content = "貴重な機器をあなたの玩具にするわけにはいきません。\nましてや…",
  ui_story_1014_10141501_208_dialog_content = "今のあなたには、\n私にそのような要求をする資格はない。",
  ui_story_1014_10141501_209_dialog_content = "資格…フン、今さらそんなことを…",
  ui_story_1014_10141501_210_dialog_content = "私に資格を与えたのはあなたたち、\n資格を奪ったのもあなたたち。",
  ui_story_1014_10141501_211_dialog_content = "私があなたに協力し、数々の成果を出したからこそ、\nここにあるあらゆる機材を使う資格を手に入れられたのよ。",
  ui_story_1014_10141501_212_dialog_content = "それなのに、軽い一言で、\n私の努力の成果をすべて奪うと言うのね。",
  ui_story_1014_10141501_213_dialog_content = "それは当然の報いです。",
  ui_story_1014_10141501_214_dialog_content = "この声、まるで…<color=#FFB400>ノラ</color>！？",
  ui_story_1014_10141501_215_dialog_content = "ノラが誰かを脅してる？",
  ui_story_1014_10141501_216_dialog_content = "急いで見に行きましょ！",
  ui_story_1014_10141501_217_dialog_content = "研究者に戦闘が得意な人なんて、ほとんどいないわ！\nノラに捕まったら大変よ！",
  ui_story_1014_10141501_218_dialog_content = "動かないで！その人を放しなさい！",
  ui_story_1014_10141501_219_dialog_content = "（本当にノラだ！\nどうして気配を感知できなかったんだろう…？）",
  ui_story_1014_10141501_220_dialog_content = "（あれ、研究員が捕まってたわけじゃないみたいだ）",
  ui_story_1014_10141501_221_dialog_content = "（話してた人、どこに消えたんだろう…？）",
  ui_story_1014_10141501_222_dialog_content = "あら、驚いたわね。\n私が欲しかった<color=#FFB400>実験台</color>が自分からやって来るなんて。",
  ui_story_1014_10141501_223_dialog_content = "ノラ…どうしてここにいる？\nここの研究員を脅していたね？",
  ui_story_1014_10141501_224_dialog_content = "私は誰も脅してなどいないわ。",
  ui_story_1014_10141501_225_dialog_content = "預けておいた権利を取り返しにきただけよ。",
  ui_story_1014_10141501_226_dialog_content = "まぁ、実験台が自分で私に会いに来たのなら、\n遠慮もいらないわね。",
  ui_story_1014_10141501_227_dialog_content = "PlayerName、避けて！後ろ！",
  ui_story_1014_10141501_228_dialog_content = "え？",
  ui_story_1014_10141501_229_dialog_content = "<anim type=Shake><size=50>グォォ！！！</size></anim>",
  ui_story_1014_10141501_230_dialog_content = "うっ！！",
  ui_story_1014_10141501_231_dialog_content = "僕は…長いこと気を失っていたみたいだ…",
  ui_story_1014_10141501_232_dialog_content = "確か、気を失う前にノラと誰かが話しているのを見て、\nそれから…",
  ui_story_1014_10141501_233_dialog_content = "バイス…そうだ、バイス！大丈夫！？",
  ui_story_1014_10141501_234_dialog_content = "横にいるのは…ノラ！？",
  ui_story_1014_10141501_235_dialog_content = "また会ったわね、空の末裔。",
  ui_story_1014_10141501_236_dialog_content = "彼女にケガをさせたくなければ、\n私の言うとおりにすることね。",
  ui_story_1014_10141501_237_dialog_content = "…",
  ui_story_1014_10141501_238_dialog_content = "何をするつもり？\nバイスを放せ！",
  ui_story_1014_10141501_239_dialog_content = "バイスを解放するなら、大人しく従うよ。",
  ui_story_1014_10141501_240_dialog_content = "まだ状況が分かっていないようね。",
  ui_story_1014_10141501_241_dialog_content = "実験台であるあなたに、\n何かを要求する権利なんてないの。",
  ui_story_1014_10141501_242_dialog_content = "それに…",
  ui_story_1014_10141501_243_dialog_content = "実験には、あなたたち両方が必要だもの。",
  ui_story_1015_10150101_1_dialog_content = "カア――カア――",
  ui_story_1015_10150101_2_dialog_content = "そろそろ日も暮れるな。",
  ui_story_1015_10150101_3_dialog_content = "ああ、少し急ごう。",
  ui_story_1015_10150101_4_dialog_content = "<color=#e8d9bb>タッタッタッ…タッタッタッ…</color>",
  ui_story_1015_10150101_5_dialog_content = "いい？よく聞きなさい、空の末裔。",
  ui_story_1015_10150101_6_dialog_content = "今から私の命令に従ってもらうわ。",
  ui_story_1015_10150101_7_dialog_content = "助けを呼ぶことも、反抗することも…\n一切の余計な動きは禁止。",
  ui_story_1015_10150101_8_dialog_content = "これからある研究をするの。\n手伝ってもらうわよ。",
  ui_story_1015_10150101_9_dialog_content = "また僕の体に何か埋め込む気？",
  ui_story_1015_10150101_10_dialog_content = "あら、あの時のことを覚えているのね。",
  ui_story_1015_10150101_11_dialog_content = "忘れるわけないじゃないか…\nとんでもないことになるところだったんだ！",
  ui_story_1015_10150101_12_dialog_content = "そうね。私も残念に思ってるわ。",
  ui_story_1015_10150101_13_dialog_content = "ついでのこととはいえ、あなたとスーモアが\nもう一度「同胞」になるところは見てみたかったわ…",
  ui_story_1015_10150101_14_dialog_content = "きっと面白いことになったでしょうね。",
  ui_story_1015_10150101_15_dialog_content = "「ついで」？じゃあ、他の皆は何だったっていうの！？\nイブやドーンは？全部「ついで」で済ませる気！？",
  ui_story_1015_10150101_16_dialog_content = "今までいったい何をした！？\nいや…いったい何をしようと――",
  ui_story_1015_10150101_17_dialog_content = "うるさいわね。耳が痛くなるわ。",
  ui_story_1015_10150101_18_dialog_content = "空の末裔って…どんどんうるさくなるわよね。\n声帯を切っておこうかしら。",
  ui_story_1015_10150101_19_dialog_content = "どうせ声がなくても会話できるんだから。そうでしょ？",
  ui_story_1015_10150101_20_dialog_content = "…",
  ui_story_1015_10150101_21_dialog_content = "黙るべきなのは僕じゃない…",
  ui_story_1015_10150101_22_dialog_content = "とにかく、言葉に気を付けることね。",
  ui_story_1015_10150101_23_dialog_content = "大人しく従いなさい。私の言う通りにしていればいいの。\nカン違いしないように言うと、これは相談じゃないから。",
  ui_story_1015_10150101_24_dialog_content = "実験さえうまくいけば、\nあなたもバイスも無事で済むかもしれないわよ？",
  ui_story_1015_10150101_25_dialog_content = "…失敗したら？",
  ui_story_1015_10150101_26_dialog_content = "あなたたちの命が代償ってことになるわね。",
  ui_story_1015_10150101_27_dialog_content = "…",
  ui_story_1015_10150101_28_dialog_content = "フン…命がないって脅かせば、怖がるとでも思ったの？",
  ui_story_1015_10150101_29_dialog_content = "日蝕の言うことを素直に信じるほど、私はバカじゃないわ。",
  ui_story_1015_10150101_30_dialog_content = "実験が成功したって、私たちを殺すつもりでしょう？",
  ui_story_1015_10150101_31_dialog_content = "あなたたちを殺して、私に何の得があるというの？",
  ui_story_1015_10150101_32_dialog_content = "1人はこの世にたった一人の空の末裔、\nもう1人はハーモナイザーの「成功例」…",
  ui_story_1015_10150101_33_dialog_content = "2人ともこの上なく貴重な研究素材じゃない。\nできることなら連れて帰りたいくらいだわ。",
  ui_story_1015_10150101_34_dialog_content = "とは言え、ここは啓光の勢力圏…\n私でもあまり好き勝手はできない。",
  ui_story_1015_10150101_35_dialog_content = "だから、助かるチャンスをあげるってこと。",
  ui_story_1015_10150101_36_dialog_content = "別に情けをかけてるじゃないわ。\n将来の研究のために、いい素材は残しておきたいだけ。",
  ui_story_1015_10150101_37_dialog_content = "君は…",
  ui_story_1015_10150101_38_dialog_content = "研究のことしか考えてないんだね。",
  ui_story_1015_10150101_39_dialog_content = "それ以外の事なんて、\n考える価値があるとも思えないわ。",
  ui_story_1015_10150101_40_dialog_content = "そんなことより、実験について話しましょう。\n少しは理解している方があなたたちにとっても都合がいいでしょうし。",
  ui_story_1015_10150101_41_dialog_content = "従うなんて言ってないよ？",
  ui_story_1015_10150101_42_dialog_content = "他に選択肢はないでしょう？",
  ui_story_1015_10150101_43_dialog_content = "…",
  ui_story_1015_10150101_44_dialog_content = "私は今、どうすれば光霊の体を\n劇的に改造できるか、研究しているの。",
  ui_story_1015_10150101_45_dialog_content = "元々持っている能力を一切失わせることなく、\nさらに高等な生物種へと根底から進化させたいのよ。",
  ui_story_1015_10150101_46_dialog_content = "…物は言いようだね。",
  ui_story_1015_10150101_47_dialog_content = "空の末裔の遺物…ハーモナイザーは使ったことがあるでしょう？\n思い出してみれば分かるはずよ。",
  ui_story_1015_10150101_48_dialog_content = "アレは私の目指す力を持っている。",
  ui_story_1015_10150101_49_dialog_content = "ハーモナイザーが狙い！？",
  ui_story_1015_10150101_50_dialog_content = "そうよ。そのために来たんだもの。",
  ui_story_1015_10150101_51_dialog_content = "あなたたちも知っているでしょう？\nこのシェルターには啓光が秘密裏に発掘したハーモナイザーが隠されていること。",
  ui_story_1015_10150101_52_dialog_content = "うっ、確かに知ってる…",
  ui_story_1015_10150101_53_dialog_content = "アレが今回の研究で一番重要な道具よ。",
  ui_story_1015_10150101_54_dialog_content = "ハーモナイザーの試験をしてデータを収集し、\n最適な使い方を探る。",
  ui_story_1015_10150101_55_dialog_content = "そうすれば、光霊を凌駕する生物を生み出せるかもしれない。",
  ui_story_1015_10150101_56_dialog_content = "ば、バイスを改造するつもり！？",
  ui_story_1015_10150101_57_dialog_content = "私はそんなお人好しじゃないわよ。\n彼女は単なる測定用のサンプル。本番には使わないわ。",
  ui_story_1015_10150101_58_dialog_content = "本番第一号の栄誉を授かるのは…こっち。",
  ui_story_1015_10150101_59_dialog_content = "…",
  ui_story_1015_10150101_60_dialog_content = "うっ…",
  ui_story_1015_10150101_61_dialog_content = "（ノラがヘリオスを助けたのは、実験台にするため？）",
  ui_story_1015_10150101_62_dialog_content = "（それとも…研究の本当の目的は、ヘリオスを助けること…？）",
  ui_story_1015_10150101_63_dialog_content = "ま、研究がうまくいけば、あなたたちにも得はあるわ。",
  ui_story_1015_10150101_64_dialog_content = "啓光の資料を見たけど、ハーモナイザーで強化された後、\nバイスの身体に副作用が出ているのでしょう？",
  ui_story_1015_10150101_65_dialog_content = "そんなことまで知ってるの！？",
  ui_story_1015_10150101_66_dialog_content = "あなたには関係ないわ！",
  ui_story_1015_10150101_67_dialog_content = "研究が完成すれば、副作用もハーモナイザーで消せるかもしれないわ。",
  ui_story_1015_10150101_68_dialog_content = "だとしたら、お互いにとって得じゃない。",
  ui_story_1015_10150101_69_dialog_content = "…そんなことで私たちを丸め込めると思ってるの？",
  ui_story_1015_10150101_70_dialog_content = "丸め込む必要なんてある？\nどうせ私を手伝うしか、生き延びる道はないのよ。",
  ui_story_1015_10150101_71_dialog_content = "今言ったことだって、\nただ事実を話しただけ。",
  ui_story_1015_10150101_72_dialog_content = "分かった、分かったよ…確かにその通りだ。\n僕たちに選択肢はない。",
  ui_story_1015_10150101_73_dialog_content = "ただ、分からない…\n僕たちがいったい何の役に立つっていうの？",
  ui_story_1015_10150101_74_dialog_content = "研究の障害物を取り除く手伝いよ。",
  ui_story_1015_10150101_75_dialog_content = "実験には設備とデータが必要。\nそれは全部啓光が持っている。",
  ui_story_1015_10150101_76_dialog_content = "当然、部外者が好きに使えるはずないでしょ？",
  ui_story_1015_10150101_77_dialog_content = "<color=#e8d9bb>辺境、トワイライトシティ</color>",
  ui_story_1015_10150101_78_dialog_content = "急げ！先に負傷した騎士を中へ！",
  ui_story_1015_10150101_79_dialog_content = "はっ！",
  ui_story_1015_10150101_80_dialog_content = "啓光のケガ人も助けてやれ。人手が足りていないようだ。",
  ui_story_1015_10150101_81_dialog_content = "レオ団長、ありがとうございます…",
  ui_story_1015_10150101_82_dialog_content = "同じ戦場で戦った者同士、礼など無用だ。",
  ui_story_1015_10150101_83_dialog_content = "あんなに強い敵に遭うなんて思いませんでした。\n味方もひどい損失を…",
  ui_story_1015_10150101_84_dialog_content = "僕のせいです。僕が指揮官として未熟だったから…",
  ui_story_1015_10150101_85_dialog_content = "お前のせいではない。強敵と渡り合えば犠牲は出るものだ。",
  ui_story_1015_10150101_86_dialog_content = "それに、今日の犠牲は…ある種の必然だったと言えるかもしれん。",
  ui_story_1015_10150101_87_dialog_content = "どういう意味ですか？",
  ui_story_1015_10150101_88_dialog_content = "トワイライトシティの周りの「風向き」が妙だ。",
  ui_story_1015_10150101_89_dialog_content = "ここ数日、トワイライトシティを狙った大規模な襲撃が続いている。",
  ui_story_1015_10150101_90_dialog_content = "私の知る限り、敵がこれほど活発な動きを見せることは初めてだ。",
  ui_story_1015_10150101_91_dialog_content = "まさか、暗鬼が何か大きく動こうとしてるんですか？",
  ui_story_1015_10150101_92_dialog_content = "分からん。だが、備えておかねばな。",
  ui_story_1015_10150101_93_dialog_content = "ショーン、お前たちの参謀長が戻ったそうだな？",
  ui_story_1015_10150101_94_dialog_content = "はい、最近戻ったばかりです。",
  ui_story_1015_10150101_95_dialog_content = "参謀長に伝えてくれ。\nいつもの場所で歓迎会をやると。",
  ui_story_1015_10150101_96_dialog_content = "いらっしゃい。何名様ですかい？",
  ui_story_1015_10150101_97_dialog_content = "待ち合わせしていまして。",
  ui_story_1015_10150101_98_dialog_content = "実に光栄ですね。\nトワイライトシティの重鎮が食事に誘ってくださるとは。",
  ui_story_1015_10150101_99_dialog_content = "まずは座って肉でも食え。",
  ui_story_1015_10150101_100_dialog_content = "結構です。食事は済ませてきました。",
  ui_story_1015_10150101_101_dialog_content = "そうか。ではお前の分もいただくとしよう。",
  ui_story_1015_10150101_102_dialog_content = "皿は私の前に置いておく方が良いのでは？\n一応は私の歓迎会なのですから。",
  ui_story_1015_10150101_103_dialog_content = "それはそうと、今日私を呼び出したのは、\n食事が目的ではありませんよね。",
  ui_story_1015_10150101_104_dialog_content = "当然だ。飯を食うだけなら、\nわざわざお前を呼び立てる必要はない。",
  ui_story_1015_10150101_105_dialog_content = "ここ数日の啓光の死傷者数の報告は見たか？",
  ui_story_1015_10150101_106_dialog_content = "はい。異常な数です。",
  ui_story_1015_10150101_107_dialog_content = "トワイライトシティ駐屯軍で、\n短期間にこれ程の被害が出たことは今までにありません。",
  ui_story_1015_10150101_108_dialog_content = "ここ数日の戦闘の激しさが、\nすでに我々の力の限界近くまで達しているということです。",
  ui_story_1015_10150101_109_dialog_content = "最も恐ろしいのは死傷者の数ではない。\n今までの我々は、本当の意味で敵に勝ったことがないということだ。",
  ui_story_1015_10150101_110_dialog_content = "こう着して、双方撤退するのが常だった。",
  ui_story_1015_10150101_111_dialog_content = "つまり、相手の真の戦力規模がいかほどか、\n私たちにはまったくつかめていないということですね。",
  ui_story_1015_10150101_112_dialog_content = "ここ数回の襲撃がすべて別の群れによる独立した襲撃だったとすれば、\n事態は最悪の可能性をはらんでいます。",
  ui_story_1015_10150101_113_dialog_content = "全ての群れが集結して町を襲えば…\n結果は想像を絶するでしょうね。",
  ui_story_1015_10150101_114_dialog_content = "その通りだ。賢い相手だと話が早くていい。",
  ui_story_1015_10150101_115_dialog_content = "何か対抗策を？",
  ui_story_1015_10150101_116_dialog_content = "すでに兵力を割いて暗面の偵察に向かわせている。\n敵の動向を少しでも探っておかんとな。",
  ui_story_1015_10150101_117_dialog_content = "だが、やはり今の兵力ではトワイライトシティを守りきれん。",
  ui_story_1015_10150101_118_dialog_content = "援軍を要請するつもりだ。",
  ui_story_1015_10150101_119_dialog_content = "なるほど…そうですね。それが一番妥当でしょう。",
  ui_story_1015_10150101_120_dialog_content = "つまり、私を呼んだのは啓光の応援が欲しいということですね。",
  ui_story_1015_10150101_121_dialog_content = "その通りだ。\n敵の数さえ我々には分かっていない。",
  ui_story_1015_10150101_122_dialog_content = "白夜城だ、啓光だとこだわっている余裕はなかろう？",
  ui_story_1015_10150101_123_dialog_content = "分かりました。戻り次第、援軍要請を出しましょう。",
  ui_story_1015_10150101_124_dialog_content = "ああ、早ければ早いほどありがたい。\n今我々にいちばん足りないものは時間だ。",
  ui_story_1015_10150101_125_dialog_content = "私には分かる。我々の想定する最悪の事態が、\nそう遠からず現実になる…",
  ui_story_1015_10150101_126_dialog_content = "<color=#e8d9bb>白夜城、朝堂</color>",
  ui_story_1015_10150101_127_dialog_content = "ふぅ…",
  ui_story_1015_10150101_128_dialog_content = "カレンちゃん、報告が終わったところ？",
  ui_story_1015_10150101_129_dialog_content = "ええ。",
  ui_story_1015_10150101_130_dialog_content = "疲れてるみたいね。",
  ui_story_1015_10150101_131_dialog_content = "いつものことよ。",
  ui_story_1015_10150101_132_dialog_content = "時間の無駄としか思えないもの。\nあの人の聞きたいことと私の話したいことはまったく違う。",
  ui_story_1015_10150101_133_dialog_content = "「トワイライトシティ」のこと？",
  ui_story_1015_10150101_134_dialog_content = "ええ。私には「城主様」がなぜ物資の分配や\n組織構成のことばかりお聞きになるのか分からないわ。",
  ui_story_1015_10150101_135_dialog_content = "私が報告したことの方が…",
  ui_story_1015_10150101_136_dialog_content = "…いえ、よしましょう。",
  ui_story_1015_10150101_137_dialog_content = "そうね。そんな話は後にして、お茶でも飲みましょ。",
  ui_story_1015_10150101_138_dialog_content = "この後の予定は？",
  ui_story_1015_10150101_139_dialog_content = "特にないわ。\n白夜城で待機しているよう言われたの。",
  ui_story_1015_10150101_140_dialog_content = "待機ねぇ…ああ、そうだったわ。\n「<color=#FFB400>合同演習</color>」が近いからかしら？",
  ui_story_1015_10150101_141_dialog_content = "ええ、おそらく。",
  ui_story_1015_10150101_142_dialog_content = "だったら、しっかり準備しなきゃ。\nカレンちゃんは演習のスター選手だもの。",
  ui_story_1015_10150101_143_dialog_content = "でも…落ち着いていられないの。",
  ui_story_1015_10150101_144_dialog_content = "あら、どうして？",
  ui_story_1015_10150101_145_dialog_content = "PlayerNameたちから連絡がないのよ。",
  ui_story_1015_10150101_146_dialog_content = "PlayerNameもバイスも、どうしてるかしら…",
  ui_story_1015_10150101_147_dialog_content = "あれあれ、カレンちゃん！久しぶり！",
  ui_story_1015_10150101_148_dialog_content = "ガルー、久しぶりね。突然連絡して申し訳ないわ。\n迷惑でなければいいのだけれど。",
  ui_story_1015_10150101_149_dialog_content = "迷惑なんてぜんぜん。\nむしろいいタイミングだよ。",
  ui_story_1015_10150101_150_dialog_content = "実はね、ソラヴァンの修復作業に大きな進展があったんだ。",
  ui_story_1015_10150101_151_dialog_content = "ほら、聞いて。",
  ui_story_1015_10150101_152_dialog_content = "ソラヴァン、起動！",
  ui_story_1015_10150101_153_dialog_content = "ソラヴァン、起動完了しました。",
  ui_story_1015_10150101_154_dialog_content = "聞こえた！？",
  ui_story_1015_10150101_155_dialog_content = "ええ、聞こえたわ。\nでも…今までも正常に起動はできていたでしょう。",
  ui_story_1015_10150101_156_dialog_content = "それはそう。\nでも、正常に動くだけで、意識がなかったでしょ？",
  ui_story_1015_10150101_157_dialog_content = "ええ。",
  ui_story_1015_10150101_158_dialog_content = "今回はソラヴァンの意識モジュールをほぼ修復できたんだよ。",
  ui_story_1015_10150101_159_dialog_content = "ただ、光霊のあたしたちとは、直接会話できないけどね。",
  ui_story_1015_10150101_160_dialog_content = "PlayerNameが戻ってきたら、ソラヴァンと話ができるよ！",
  ui_story_1015_10150101_161_dialog_content = "ああ、そうだわ。ちょうどPlayerName…とバイスのことを聞きたかったの。",
  ui_story_1015_10150101_162_dialog_content = "2人はどうしているかしら？",
  ui_story_1015_10150101_163_dialog_content = "白夜城に戻ってから、2人からまったく連絡がないのよ。",
  ui_story_1015_10150101_164_dialog_content = "そのことなら報告書で読んだよ。",
  ui_story_1015_10150101_165_dialog_content = "秘密のシェルターで休養中だって。\nだから一時的に通信もできないんじゃないかな。",
  ui_story_1015_10150101_166_dialog_content = "休みが終われば連絡くれると思うよ。",
  ui_story_1015_10150101_167_dialog_content = "秘密のシェルター？",
  ui_story_1015_10150101_168_dialog_content = "ま、安心してよ。\n機密レベルはすっごく高いから。",
  ui_story_1015_10150101_169_dialog_content = "ええと、確か名前は…",
  ui_story_1015_10150101_170_dialog_content = "そうそう、「<color=#FFB400>X号研究院</color>」。",
  ui_story_1015_10150101_171_dialog_content = "<color=#e8d9bb>カナン城、列車駅</color>",
  ui_story_1015_10150101_172_dialog_content = "どいてくれ。後ろからじゃ何も見えやしない。",
  ui_story_1015_10150101_173_dialog_content = "ん？あそこ、曲がってないか？",
  ui_story_1015_10150101_174_dialog_content = "本当だ。我々啓光の旗はもっと高く掲げないとな！",
  ui_story_1015_10150101_175_dialog_content = "どうしてこんなに人が集まってるんだ？\nいったい何を見てるんだ？",
  ui_story_1015_10150101_176_dialog_content = "知らないの？もうすぐ「合同演習」でしょ。\nこの先に参加勢力の旗を掲げてるのよ。",
  ui_story_1015_10150101_177_dialog_content = "ああ、そうか！もう合同演習の時期だったな。",
  ui_story_1015_10150101_178_dialog_content = "今年は特別だから、取材を申し込む新聞社が殺到して、\n毎日受付に列ができてるそうよ。",
  ui_story_1015_10150101_179_dialog_content = "特別？今年の合同演習は何か違うのか？",
  ui_story_1015_10150101_180_dialog_content = "そりゃ特別に決まってるじゃない。\n10数年ぶりに空の末裔が合同演習に参加するんだから。",
  ui_story_1015_10150101_181_dialog_content = "<color=#e8d9bb>カナン城、情報機関</color>",
  ui_story_1015_10150101_182_dialog_content = "<color=#e8d9bb>トン、トン、トン…</color>",
  ui_story_1015_10150101_183_dialog_content = "どうぞ。",
  ui_story_1015_10150101_184_dialog_content = "インゲル中佐、中佐宛ての緊急電報が届いています。",
  ui_story_1015_10150101_185_dialog_content = "至急お目通しを。",
  ui_story_1015_10150101_186_dialog_content = "緊急電報ですか？",
  ui_story_1015_10150101_187_dialog_content = "分かりました。机の上に置いておいてください。",
  ui_story_1015_10150101_188_dialog_content = "はい！",
  ui_story_1015_10150101_189_dialog_content = "いったい誰からでしょう…",
  ui_story_1015_10150101_190_dialog_content = "え…？ユリシーズ教授？",
  ui_story_1015_10150201_1_dialog_content = "モタモタしてないで、さっさと歩きなさい。",
  ui_story_1015_10150201_2_dialog_content = "私のナイフより速く歩かないと大変なことになるわよ。",
  ui_story_1015_10150201_3_dialog_content = "…分かってるよ。",
  ui_story_1015_10150201_4_dialog_content = "ただ…どうして毎日こんな早起きする必要があるの？",
  ui_story_1015_10150201_5_dialog_content = "もう何日もちゃんと寝られてないんだけど。",
  ui_story_1015_10150201_6_dialog_content = "生活が自堕落すぎて感覚がおかしくなっているみたいね。",
  ui_story_1015_10150201_7_dialog_content = "これぐらい特別きついものでもないわ。\n見なさい、辺りの衛兵たちもとっくに起きているじゃない。",
  ui_story_1015_10150201_8_dialog_content = "はぁ…こんな生活をいつまで…",
  ui_story_1015_10150201_9_dialog_content = "それに関しては、明確な答えをあげるわ。",
  ui_story_1015_10150201_10_dialog_content = "聞いたことがあるでしょう。啓光でもうすぐ「合同演習」が開催される。\nあなたたちは当然招待されるはず。",
  ui_story_1015_10150201_11_dialog_content = "演習の時に姿を見せなければ、啓光が騒いで人を出す。\nそうなれば…面倒でしょうね。",
  ui_story_1015_10150201_12_dialog_content = "つまり、合同演習が最終期限ということになるわ。",
  ui_story_1015_10150201_13_dialog_content = "（そうだ、合同演習！うまく利用すれば助かるかも！？）",
  ui_story_1015_10150201_14_dialog_content = "あなたたちにとっていい知らせは、\nこの状態が長くは続かないってこと。",
  ui_story_1015_10150201_15_dialog_content = "悪い知らせは、もし期限内に実験が成功しなければ、\n想定よりも早く命を落とすことになるって話ね。",
  ui_story_1015_10150201_16_dialog_content = "…",
  ui_story_1015_10150201_17_dialog_content = "だから、生き延びるためにも効率を上げるのが賢明ね。",
  ui_story_1015_10150201_18_dialog_content = "押さなくたって、道は分かってるわ！",
  ui_story_1015_10150201_19_dialog_content = "実験室に行きたいんでしょ？\nあそこなら何度も行ったことがあるわ。",
  ui_story_1015_10150201_20_dialog_content = "私は実験以外のことに時間を使いたくないの。",
  ui_story_1015_10150201_21_dialog_content = "集中しなさい。足取りをつかまれないようにするのよ。",
  ui_story_1015_10150201_22_dialog_content = "この前みたいに大声で助けを呼ぼうとしたら、\n舌を切り落とすわ。",
  ui_story_1015_10150201_23_dialog_content = "分かってるよ。今はちゃんと協力してるでしょ。",
  ui_story_1015_10150201_24_dialog_content = "衛兵の巡回経路と勤務時間は決まってるんだ。\n何も起こるはずない…",
  ui_story_1015_10150201_25_dialog_content = "…",
  ui_story_1015_10150201_26_dialog_content = "<size=50>うわっ！</size>これは…",
  ui_story_1015_10150201_27_dialog_content = "<size=50><anim type=Shake>グゥウウ――</anim></size>",
  ui_story_1015_10150201_28_dialog_content = "ノラ、君のペットの犬がまた付いてきてるよ。",
  ui_story_1015_10150201_29_dialog_content = "ジェイドは犬じゃないわ。",
  ui_story_1015_10150201_30_dialog_content = "でも、ペットには変わりないでしょ。",
  ui_story_1015_10150201_31_dialog_content = "こんなに大きい動物を連れてきたら、\n問題あるんじゃないの？",
  ui_story_1015_10150201_32_dialog_content = "今回の研究には助手が必要だから、連れて来たのよ。",
  ui_story_1015_10150201_33_dialog_content = "研究…",
  ui_story_1015_10150201_34_dialog_content = "どうせその「助手」も研究のせいで、\nこんな姿になってるんでしょ。",
  ui_story_1015_10150201_35_dialog_content = "…",
  ui_story_1015_10150201_36_dialog_content = "元は何だったの？",
  ui_story_1015_10150201_37_dialog_content = "チンチラ。",
  ui_story_1015_10150201_38_dialog_content = "チンチラ！？",
  ui_story_1015_10150201_39_dialog_content = "あんなに小さくて可愛い動物がこんな姿になっちゃうのか…",
  ui_story_1015_10150201_40_dialog_content = "「小さくて可愛い」なんて表現は、\n食物連鎖の頂点にいる者のおごりよ。",
  ui_story_1015_10150201_41_dialog_content = "えっ？",
  ui_story_1015_10150201_42_dialog_content = "自身の生殺与奪を握れるような存在がいる時、\n他の生物はそれに取り入ることで優位性を獲得する。",
  ui_story_1015_10150201_43_dialog_content = "自然界において、チンチラは身体が小さいから、\n生態系で優位な地位に立つことは難しい。",
  ui_story_1015_10150201_44_dialog_content = "でも、今のジェイドはその戒めから解き放たれている。",
  ui_story_1015_10150201_45_dialog_content = "戒めから解き放たれる？",
  ui_story_1015_10150201_46_dialog_content = "簡単に言えば、獲物の選択肢が増えたってことね。",
  ui_story_1015_10150201_47_dialog_content = "ちょうどいいわ。\n門番を片づけないといけないみたいだし。",
  ui_story_1015_10150201_48_dialog_content = "ちょっと！？\nジェイドのエサにするつもり！？",
  ui_story_1015_10150201_49_dialog_content = "約束したはずだ！戦いの手助けは構わないけど、\n絶対に他の光霊の命は危険にさらさないって！",
  ui_story_1015_10150201_50_dialog_content = "全体はどうでもよくて、\n目の前の1人2人の命は大切ってこと？",
  ui_story_1015_10150201_51_dialog_content = "まあ、いいわ。\nあなたの浅はかさをとやかく言ってられるほどヒマじゃない。",
  ui_story_1015_10150201_52_dialog_content = "1人2人の命は大事じゃないって言うの？\nあの人たちは…",
  ui_story_1015_10150201_53_dialog_content = "今まで通り、\nあなたは戦いに必要な情報を出しなさい。",
  ui_story_1015_10150201_54_dialog_content = "実験室の警備は厳重だから、\n今までより難しい戦いになるでしょうね。",
  ui_story_1015_10150201_55_dialog_content = "私なら悪くない戦力になるわ。\nだから、放してくれない？",
  ui_story_1015_10150201_56_dialog_content = "あなたは大人しくしてなさい。\n余計なことをすれば、ジェイドの朝ご飯にするわ。",
  ui_story_1015_10150201_57_dialog_content = "フン…",
  ui_story_1015_10150201_58_dialog_content = "空の末裔、私の後ろにいなさい。",
  ui_story_1015_10150201_59_dialog_content = "行くわよ。",
  ui_story_1015_10150302_1_dialog_content = "<color=#e8d9bb>ドンッ――</color>",
  ui_story_1015_10150302_2_dialog_content = "ダメだよ！力を入れすぎだ！",
  ui_story_1015_10150302_3_dialog_content = "骨折でもさせたら、どうするつもり！？",
  ui_story_1015_10150302_4_dialog_content = "気絶させたわ。端に寄せておいて。",
  ui_story_1015_10150302_5_dialog_content = "少なくとも実験中に見つかるわけにはいかないの。",
  ui_story_1015_10150302_6_dialog_content = "<size=45><anim type=Shake>グルル――</anim></size>",
  ui_story_1015_10150302_7_dialog_content = "引きずるならもうちょっと優しく――",
  ui_story_1015_10150302_8_dialog_content = "ああもう、僕がやるよ…",
  ui_story_1015_10150302_9_dialog_content = "急ぎなさい。時間をムダにしたくないわ。",
  ui_story_1015_10150302_10_dialog_content = "分かってるよ。こういうことも初めてじゃないし。",
  ui_story_1015_10150302_11_dialog_content = "…ごめん、ノラが君たちを倒すのに手を貸したりして…",
  ui_story_1015_10150302_12_dialog_content = "あれ？地面に何か散らばってる。",
  ui_story_1015_10150302_13_dialog_content = "ポケットに戻しておいてあげよう。",
  ui_story_1015_10150302_14_dialog_content = "ナイフに…鍵に…磁気カード…",
  ui_story_1015_10150302_15_dialog_content = "ん？何だろう…？裁縫セット？",
  ui_story_1015_10150302_16_dialog_content = "ふたが開くみたいだ。",
  ui_story_1015_10150302_17_dialog_content = "<size=45>！！！</size>",
  ui_story_1015_10150302_18_dialog_content = "ああ、これ、<color=#FFB400>ライター</color>だったんだ…",
  ui_story_1015_10150302_19_dialog_content = "<size=50><anim type=Shake>ガルル！！</anim></size>",
  ui_story_1015_10150302_20_dialog_content = "うわっ！何するの！！",
  ui_story_1015_10150302_21_dialog_content = "<size=45><anim type=Shake>グルル――</anim></size>",
  ui_story_1015_10150302_22_dialog_content = "<color=#e8d9bb>ボンッ…</color>",
  ui_story_1015_10150302_23_dialog_content = "え、ライターを踏み潰した…？",
  ui_story_1015_10150302_24_dialog_content = "ただのライターだよ、驚くようなものじゃ…",
  ui_story_1015_10150302_25_dialog_content = "…",
  ui_story_1015_10150302_26_dialog_content = "実験室の周りはデリケートな環境なの。\n火花一つでも起これば危ないわ。",
  ui_story_1015_10150302_27_dialog_content = "二度とこういうことが起こらないようにしなさい。",
  ui_story_1015_10150302_28_dialog_content = "そうなんだ…？",
  ui_story_1015_10150302_29_dialog_content = "（それが本当なら、どうして実験室を見張る衛兵が\nライターなんて持ってるんだろう？）",
  ui_story_1015_10150302_30_dialog_content = "行くわよ。時間がないわ。",
  ui_story_1015_10150302_31_dialog_content = "<color=#e8d9bb>ウィーン――</color>",
  ui_story_1015_10150302_32_dialog_content = "開いたわ。入りなさい。",
  ui_story_1015_10150302_33_dialog_content = "先に入っていなさい。",
  ui_story_1015_10150302_34_dialog_content = "何をしてるの？",
  ui_story_1015_10150302_35_dialog_content = "…ドアロックの…パスワードを変えてる？",
  ui_story_1015_10150302_36_dialog_content = "…チッ。",
  ui_story_1015_10150302_37_dialog_content = "（追手が来たときに、ロックで時間を稼ぐつもりだね）",
  ui_story_1015_10150302_38_dialog_content = "はぁ…僕たちみたいなのを入れないようにするためのものが、\n反対に衛兵を締め出す道具になるなんて皮肉だなぁ。",
  ui_story_1015_10150302_39_dialog_content = "機械に意識なんてないもの。\n使い方を知っている者のために動くだけよ。",
  ui_story_1015_10150302_40_dialog_content = "ここのこと、よく知ってるみたいね。",
  ui_story_1015_10150302_41_dialog_content = "何か言った？",
  ui_story_1015_10150302_42_dialog_content = "外の警備を突破できて、内部の構造にも通じてる。\nおまけにドアシステムや装置まで自由に操作できる…",
  ui_story_1015_10150302_43_dialog_content = "啓光の科学研究施設のセキュリティなんて、\n子どものお遊び同然ってこと？",
  ui_story_1015_10150302_44_dialog_content = "その程度の事が出来ないなら、\nこんな計画、話にならないわ。",
  ui_story_1015_10150302_45_dialog_content = "出来なければ、ここまでたどり着けないでしょう。",
  ui_story_1015_10150302_46_dialog_content = "なら、どうしてそれができるの？\n昔は啓光の研究員だったから？",
  ui_story_1015_10150302_47_dialog_content = "この研究院は私が建てたからよ。",
  ui_story_1015_10150302_48_dialog_content = "なんですって！？",
  ui_story_1015_10150302_49_dialog_content = "君が建てた…",
  ui_story_1015_10150302_50_dialog_content = "あの時は「X号シェルター」と呼ばれていたかしら。",
  ui_story_1015_10150302_51_dialog_content = "パスワードの再設定が終わったわ。",
  ui_story_1015_10150302_52_dialog_content = "実験を始めるとしましょう。",
  ui_story_1015_10150302_53_dialog_content = "あ…本当だ。ハーモナイザーがある！",
  ui_story_1015_10150302_54_dialog_content = "回帰の塔にあったのとは少し違うけど、\n同じような装置だってことは一目で分かる…",
  ui_story_1015_10150302_55_dialog_content = "啓光はハーモナイザーを長い間、秘密裏に研究してきたの。\n高いレベルの機密としてね。",
  ui_story_1015_10150302_56_dialog_content = "それを知っているのは、\n「委員会」と「会議」の老いぼれどもだけ。",
  ui_story_1015_10150302_57_dialog_content = "どのぐらい進んでるんだろう…",
  ui_story_1015_10150302_58_dialog_content = "それより…今まで僕たちを連れて来なかったのに、\nどうして今日になって急にこんなところへ？",
  ui_story_1015_10150302_59_dialog_content = "研究が新しい段階に入ったからよ。",
  ui_story_1015_10150302_60_dialog_content = "啓光はこの機械の使い方を探るだけで何十年もの時を費やした。\nでも、私はそんなに長い間待てない。",
  ui_story_1015_10150302_61_dialog_content = "だから、あいつらが知ったことを\n実験でそっくりもらっていこうってわけ。",
  ui_story_1015_10150302_62_dialog_content = "どういう意味？",
  ui_story_1015_10150302_63_dialog_content = "ハーモナイザーを実際に使う。\nそして、動作過程を観察して原理を理解する。",
  ui_story_1015_10150302_64_dialog_content = "これで、あなたたちを連れて来た理由が分かったでしょう？",
  ui_story_1015_10150302_65_dialog_content = "ハーモナイザーを！？いったい誰に…",
  ui_story_1015_10150302_66_dialog_content = "もちろん、準備してきた「実験台」に決まってるわ。",
  ui_story_1015_10150302_67_dialog_content = "…！",
  ui_story_1015_10150302_68_dialog_content = "やめろ！バイスに触るな！！",
  ui_story_1015_10150302_69_dialog_content = "ジェイド。",
  ui_story_1015_10150302_70_dialog_content = "<size=50><anim type=Shake>ガルル――！！！</anim></size>",
  ui_story_1015_10150302_71_dialog_content = "うっ…お、重い…",
  ui_story_1015_10150302_72_dialog_content = "ば、バイスを放せ！\n使い方も知らないくせに、むやみに機械をいじったら…",
  ui_story_1015_10150302_73_dialog_content = "だから「実験台」で試すんじゃない。",
  ui_story_1015_10150302_74_dialog_content = "科学研究は暗闇の中に手を伸ばすようなもの。\n手を刺されて、ケガをして、ようやく世界の輪郭が見えるのよ。",
  ui_story_1015_10150302_75_dialog_content = "試さなければ、永遠に研究は進まないわ。",
  ui_story_1015_10150302_76_dialog_content = "そんなことなら、自分を実験台にすればいい！",
  ui_story_1015_10150302_77_dialog_content = "自分で試したら1回しか失敗できないわ。\n「実験台」があれば、いくらでも失敗が許されるでしょう？",
  ui_story_1015_10150302_78_dialog_content = "科学研究はギャンブルじゃないの。\n無限の試行回数が必要なのよ。",
  ui_story_1015_10150302_79_dialog_content = "<size=45>君って…ヤツは…</size>",
  ui_story_1015_10150302_80_dialog_content = "さあ、バイス。準備はできたかしら？",
  ui_story_1015_10150302_81_dialog_content = "はじめてハーモナイザーを使った時と同じようにしていればいいのよ。",
  ui_story_1015_10150302_82_dialog_content = "放して！",
  ui_story_1015_10150302_83_dialog_content = "ハーモナイザー試運転――\n実験モジュール、被験体、準備完了。",
  ui_story_1015_10150302_84_dialog_content = "実験、開始。",
  ui_story_1015_10150302_85_dialog_content = "ユリシーズ長官、このままではらちが明きません。",
  ui_story_1015_10150302_86_dialog_content = "すでに衛兵の人数を増やし、捜索および身柄確保の態勢を取らせていますが、\n侵入者は捕らえられておりません。",
  ui_story_1015_10150302_87_dialog_content = "研究者に不安が広がり、\n多くの者が実験室に向かうことを怖がっています。",
  ui_story_1015_10150302_88_dialog_content = "侵入者の身元は？",
  ui_story_1015_10150302_89_dialog_content = "了解しました。\n長官の予想された通り、侵入者はノラのようです。",
  ui_story_1015_10150302_90_dialog_content = "それにしても、いったいどのようにして侵入したのでしょう？\n我々の捜索から逃れるどころか、全ての警備を突破するなど…",
  ui_story_1015_10150302_91_dialog_content = "そう言えば、ここ数日連絡が途絶えていた空の末裔を兵士が目撃したそうです。\n空の末裔がノラと内通しているという可能性も…",
  ui_story_1015_10150302_92_dialog_content = "ノラの事であれば、内通者など必要ありません。",
  ui_story_1015_10150302_93_dialog_content = "それはどういう…？",
  ui_story_1015_10150302_94_dialog_content = "ノラは誰よりもここに詳しい。\n何しろ「X号研究院」は彼女が創設したものですから。",
  ui_story_1015_10150302_95_dialog_content = "ノラが建てたと？私はてっきり長官が…",
  ui_story_1015_10150302_96_dialog_content = "11年前、ノラはまだ啓光にいました。\n当時は将来を最も期待された研究員でした。",
  ui_story_1015_10150302_97_dialog_content = "ノラはすでに廃墟となった、ある無名のシェルターを\n秘密裏に引き継ぎたいと申し出て…",
  ui_story_1015_10150302_98_dialog_content = "「X号シェルター」と名付けた。\nそれがこの研究院の前身です。",
  ui_story_1015_10150302_99_dialog_content = "そうでしたか…",
  ui_story_1015_10150302_100_dialog_content = "その後ノラが啓光を裏切り、\nX号シェルターが今の研究院になったというわけですか？",
  ui_story_1015_10150302_101_dialog_content = "そんなところですね。",
  ui_story_1015_10150302_102_dialog_content = "ノラには才能があった。\nしかし、才能とはとても恐ろしいものです。",
  ui_story_1015_10150302_103_dialog_content = "彼女の才能は常人の域を越えていました。\nやがて過激で危険を伴う実験を次々と行うようになり…",
  ui_story_1015_10150302_104_dialog_content = "そうした研究の結果、「X号シェルター」は\n啓光連邦でも最先端の生物科学技術を有するまでになったのです。",
  ui_story_1015_10150302_105_dialog_content = "しかし、同時にそれはリスクの増大を意味しました。",
  ui_story_1015_10150302_106_dialog_content = "啓光にも、彼女自身にも受け止めきれない程に。",
  ui_story_1015_10150302_107_dialog_content = "私も聞いたことがあります。\nノラの除名は研究の最中に大事故を起こしたからだと…",
  ui_story_1015_10150302_108_dialog_content = "そうです。大火災が起こり、「X号シェルター」は焼失した。",
  ui_story_1015_10150302_109_dialog_content = "とはいえ、事故はただのきっかけにすぎません。\nそれで上層部がノラの秘密を探り始めたというだけのことです。",
  ui_story_1015_10150302_110_dialog_content = "啓光が本当に容認できなかったものは、\n人道に背いた、制御不可能な本質を秘めた彼女の研究内容です。",
  ui_story_1015_10150302_111_dialog_content = "元を絶たなければ、火はますます燃え広がるでしょう。",
  ui_story_1015_10150302_112_dialog_content = "確かにおっしゃる通りです。\nその火事がカナン城で起こっていたら、さらに大変なことになっていたでしょうね。",
  ui_story_1015_10150302_113_dialog_content = "ただ…それほどの大事故を起こした「X号シェルター」が、\nなぜそのまま廃棄されなかったのですか？",
  ui_story_1015_10150302_114_dialog_content = "研究所として使えるシェルターなら、\n他にもいくらでもあるかと思いますが。",
  ui_story_1015_10150302_115_dialog_content = "はぁ…恐ろしい才能とは、そういうことです。",
  ui_story_1015_10150302_116_dialog_content = "どれほど倫理に背き、多大な危害をもたらそうと…\nあれほど卓越した研究成果を埋もれさせる理由にはなりません。",
  ui_story_1015_10150302_117_dialog_content = "結局のところ、私も彼女と同類ということです。",
  ui_story_1015_10150302_118_dialog_content = "ノラが残したものを失うのは、あまりにも惜しかった…",
  ui_story_1015_10150302_119_dialog_content = "そうでしたか…",
  ui_story_1015_10150302_120_dialog_content = "事が一段落した後、私は損壊したシェルターを再建しました。\nそれが今の「X号研究院」です。",
  ui_story_1015_10150302_121_dialog_content = "彼女が残した機器と研究成果のおかげで、\n啓光は生物化学分野において、さらに進歩を遂げました。",
  ui_story_1015_10150302_122_dialog_content = "その点ではノラも啓光に貢献したと言えるでしょうか。",
  ui_story_1015_10150302_123_dialog_content = "何事にも代価はつきものです。\n今こうして、我々が支払うべき時がきたように。",
  ui_story_1015_10150302_124_dialog_content = "「X号研究院」は改装されてこそいますが、\n基礎や原理は根本的に変わっていない。",
  ui_story_1015_10150302_125_dialog_content = "ノラにとっては我々のしたことなど、\nオルゴールのゼンマイを交換し、布を張り換えた程度の些事でしょうね。",
  ui_story_1015_10150302_126_dialog_content = "彼女なら、軽く触っただけで\n思うような曲を奏でられるはずです。",
  ui_story_1015_10150401_1_dialog_content = "とすると…X号研究院は非常に危険な状況にありますね。",
  ui_story_1015_10150401_2_dialog_content = "兵力上の優位はこちらにありますが、\n戦闘能力ではほぼ互角です。",
  ui_story_1015_10150401_3_dialog_content = "内部構造もよく知っているということなら、\n大勢の兵を送り込んでも取り囲む機会さえないでしょう。",
  ui_story_1015_10150401_4_dialog_content = "この中では彼女が自由自在に動けますから…",
  ui_story_1015_10150401_5_dialog_content = "その通り、衛兵ではノラをどうすることもできません。",
  ui_story_1015_10150401_6_dialog_content = "単独で彼女と対等に渡り合える者でもいない限り、\nどれだけ衛兵の数を揃えても意味が無い。",
  ui_story_1015_10150401_7_dialog_content = "しかし、このままでは…",
  ui_story_1015_10150401_8_dialog_content = "長官、カナン城に応援を要請しましょう。",
  ui_story_1015_10150401_9_dialog_content = "援軍さえ到着すれば、おそらく…",
  ui_story_1015_10150401_10_dialog_content = "それはできません。",
  ui_story_1015_10150401_11_dialog_content = "なぜですか？",
  ui_story_1015_10150401_12_dialog_content = "そう単純な事情ではないのです。",
  ui_story_1015_10150401_13_dialog_content = "応援を頼んで解決することなら、君に言われるまでもなく、\nとうの昔にカナン城へ電報を打っています。",
  ui_story_1015_10150401_14_dialog_content = "それは…どういうことでしょう…？",
  ui_story_1015_10150401_15_dialog_content = "ここは極秘の研究院、ありとあらゆる事が機密事項なのです。",
  ui_story_1015_10150401_16_dialog_content = "事情を軍に知られるのはまずいでしょうね。\nノラがなぜ抹消されたか忘れたのですか？",
  ui_story_1015_10150401_17_dialog_content = "…はい。",
  ui_story_1015_10150401_18_dialog_content = "目の前の問題にばかり目を向けた、\n私の考えが浅はかでした。",
  ui_story_1015_10150401_19_dialog_content = "ノラは研究者です。ここへ侵入したのは実験のためでしょう。",
  ui_story_1015_10150401_20_dialog_content = "つまり、今のところは科学者同士の争いにすぎません。",
  ui_story_1015_10150401_21_dialog_content = "しかしひとたび軍が関われば、事態の性質が変わってしまいます。",
  ui_story_1015_10150401_22_dialog_content = "理解しました。",
  ui_story_1015_10150401_23_dialog_content = "本当に？",
  ui_story_1015_10150401_24_dialog_content = "…",
  ui_story_1015_10150401_25_dialog_content = "まあ、君は軍人ですから、命令に従っていればよいのです。\n私の考えなど理解する必要はありません。",
  ui_story_1015_10150401_26_dialog_content = "今回のことも一つの実験だと思っておいてください。",
  ui_story_1015_10150401_27_dialog_content = "ただし、実験内容は絶対に外部に漏えいしてはなりません。\nこれは規則にも書かれていることです。理解しましたか？",
  ui_story_1015_10150401_28_dialog_content = "はい。",
  ui_story_1015_10150401_29_dialog_content = "よろしい。では、次は君にも分かることを話すとしましょう。",
  ui_story_1015_10150401_30_dialog_content = "カナン城には応援を頼まないとしても、\n座して何もしないという意味ではありません。",
  ui_story_1015_10150401_31_dialog_content = "私には私なりに、ノラへの対処法があります。",
  ui_story_1015_10150401_32_dialog_content = "長官なりの？それはいったい…",
  ui_story_1015_10150401_33_dialog_content = "<color=#e8d9bb>トン、トン、トン…</color>",
  ui_story_1015_10150401_34_dialog_content = "入りなさい。",
  ui_story_1015_10150401_35_dialog_content = "啓光連邦情報官インゲル中佐、報告にあがりました。",
  ui_story_1015_10150401_36_dialog_content = "<color=#e8d9bb>ピーッ！ピーッ！</color>",
  ui_story_1015_10150401_37_dialog_content = "なるほど、こういう原理だったのね…",
  ui_story_1015_10150401_38_dialog_content = "そうよね。体の構造だけを変えても無意味だわ。",
  ui_story_1015_10150401_39_dialog_content = "光力の軌跡はここじゃない。\nもっと深い所に隠されているはず…",
  ui_story_1015_10150401_40_dialog_content = "（バイス！大丈夫？）",
  ui_story_1015_10150401_41_dialog_content = "（具合の悪い所はない？）",
  ui_story_1015_10150401_42_dialog_content = "（今のところは大丈夫よ。\n何かの力が体内の光力を整えてくれてるような感覚があるだけ…）",
  ui_story_1015_10150401_43_dialog_content = "（だったら、ひとまず大丈夫そうだね。\n想定外のことが起こらないことを祈るばかりだよ…）",
  ui_story_1015_10150401_44_dialog_content = "（心配いらないわ。\nハーモナイザーは前にも一度使ったことがあるんだから）",
  ui_story_1015_10150401_45_dialog_content = "（でも…）",
  ui_story_1015_10150401_46_dialog_content = "（…それより、聞いて。今がチャンスだと思わない？）",
  ui_story_1015_10150401_47_dialog_content = "（チャンス？）",
  ui_story_1015_10150401_48_dialog_content = "（ハーモナイザーは光霊の力を強化できる、でしょ？）",
  ui_story_1015_10150401_49_dialog_content = "（これでうまく強化が済めば、縄をどうにかできるかもしれないわ）",
  ui_story_1015_10150401_50_dialog_content = "（縄を！？そんなことできるかな？）",
  ui_story_1015_10150401_51_dialog_content = "（できると思うわ。今だって出来る気がするの）",
  ui_story_1015_10150401_52_dialog_content = "（問題は縄を切った後、\nノラとジェイドを相手にどう戦うかってことよ）",
  ui_story_1015_10150401_53_dialog_content = "（結局、私にはもっと力が要るわ。\nハーモナイザーの効果に望みをかけるしかない）",
  ui_story_1015_10150401_54_dialog_content = "（うーん…ノラは完全にデータに気をとられてる…\n確かに反撃のチャンスだね）",
  ui_story_1015_10150401_55_dialog_content = "（でしょ？自分で始めた実験の成果、\nたっぷり味わわせてやりましょ！）",
  ui_story_1015_10150401_56_dialog_content = "（息を合わせて攻撃する必要があるわ。\nチャンスは一度だけだもの）",
  ui_story_1015_10150401_57_dialog_content = "（不意を突いて、ノラが反応する前に押さえつけましょ。\n持久戦に持ち込まれたら、こっちが不利よ）",
  ui_story_1015_10150401_58_dialog_content = "（分かった。僕がチャンスを見計らうよ）",
  ui_story_1015_10150401_59_dialog_content = "（頼んだわ！）",
  ui_story_1015_10150401_60_dialog_content = "ノラ、あとどれぐらいかかるの？",
  ui_story_1015_10150401_61_dialog_content = "ジェイドの尻尾がすごく重いんだけど。\n息が苦しくてかなわないよ。",
  ui_story_1015_10150401_62_dialog_content = "うるさいわね。もうすぐよ。",
  ui_story_1015_10150401_63_dialog_content = "もうすぐってどのくらい？\nもっと正確に教えてくれない？",
  ui_story_1015_10150401_64_dialog_content = "もう最終段階に入ってるわ。",
  ui_story_1015_10150401_65_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1015_10150401_66_dialog_content = "（PlayerName！光力の流れが速くなったわ！）",
  ui_story_1015_10150401_67_dialog_content = "（じゃあ、君も準備して！\n強化が終わった瞬間に仕掛ける！）",
  ui_story_1015_10150401_68_dialog_content = "（分かったわ！）",
  ui_story_1015_10150401_69_dialog_content = "（縄を切ったら、まずはノラを攻撃しよう。\nそうすれば、ジェイドが本能的にノラをかばいに動くはずだ。そしたら君は…）",
  ui_story_1015_10150401_70_dialog_content = "それはそうと…空の末裔。",
  ui_story_1015_10150401_71_dialog_content = "え？何かあった？",
  ui_story_1015_10150401_72_dialog_content = "残り時間ばかり気にしてるようだけど、\n実験がうまくいくかどうかは心配しないのね？",
  ui_story_1015_10150401_73_dialog_content = "それは…",
  ui_story_1015_10150401_74_dialog_content = "（まずい！悟られた？）",
  ui_story_1015_10150401_75_dialog_content = "（バイス、強化が完了するまで、あとどのくらい…）",
  ui_story_1015_10150401_76_dialog_content = "安心しなさい。\nバイスの体には何も起きていないわ。",
  ui_story_1015_10150401_77_dialog_content = "損傷もなければ、想定される強化も起こっていない。",
  ui_story_1015_10150401_78_dialog_content = "実験、終了ね。",
  ui_story_1015_10150401_79_dialog_content = "<color=#e8d9bb>ウオオン…</color>",
  ui_story_1015_10150401_80_dialog_content = "（どういうこと！？強化を中止したの！？）",
  ui_story_1015_10150401_81_dialog_content = "な、何をしたんだ！？",
  ui_story_1015_10150401_82_dialog_content = "ハーモナイザーのスイッチを切っただけよ。",
  ui_story_1015_10150401_83_dialog_content = "実験はここまでで十分。\n実験台に余計な変化が起こっても困るしね。",
  ui_story_1015_10150401_84_dialog_content = "それとも、何か期待していたのかしら？",
  ui_story_1015_10150401_85_dialog_content = "（バイス、どうする？\n僕たちの作戦、バレてるみたいだ…）",
  ui_story_1015_10150401_86_dialog_content = "（構っていられないわ。チャンスは一度だけよ！）",
  ui_story_1015_10150401_87_dialog_content = "（今すぐ拘束を外すわ！あなたも準備して！）",
  ui_story_1015_10150401_88_dialog_content = "なぜ黙っているのかしら？\nやっぱり、つまらないことを考えていたようね。",
  ui_story_1015_10150401_89_dialog_content = "フン、つまらないかどうかは倒されてからゆっくり考えなさい！",
  ui_story_1015_10150401_90_dialog_content = "<color=#e8d9bb>バサッ――</color>",
  ui_story_1015_10150401_91_dialog_content = "思った通り、ハーモナイザーの実験の隙に縄を切ったわね。",
  ui_story_1015_10150401_92_dialog_content = "構わないわ。その程度のリスクは想定内だもの。",
  ui_story_1015_10150401_93_dialog_content = "どうせ1度捕まえられたということは、\n2度でも同じこと。",
  ui_story_1015_10150401_94_dialog_content = "バイス！ノラが隠してた暗鬼を呼び出してる！",
  ui_story_1015_10150401_95_dialog_content = "急いで攻撃を！",
  ui_story_1015_10150502_1_dialog_content = "はぁ…はぁ…",
  ui_story_1015_10150502_2_dialog_content = "やっぱり歯が立たないの…？",
  ui_story_1015_10150502_3_dialog_content = "ハーモナイザーによる強化を利用して拘束を外す…\nあなたでも思いつくようなこと、私が思いつかないと思った？",
  ui_story_1015_10150502_4_dialog_content = "そんなものチャンスでも何でもないわよ。\n私には準備があるもの。",
  ui_story_1015_10150502_5_dialog_content = "戦いの最中に無駄口をたたけるなんて、大したものね。",
  ui_story_1015_10150502_6_dialog_content = "最中じゃないわ。もう終わってるの。",
  ui_story_1015_10150502_7_dialog_content = "お遊びに付き合ってる時間はないわ。",
  ui_story_1015_10150502_8_dialog_content = "それはあなたの決めることじゃない！",
  ui_story_1015_10150502_9_dialog_content = "そう？そっちは何て言うかしら。",
  ui_story_1015_10150502_10_dialog_content = "<size=45>バイス！後ろ！</size>",
  ui_story_1015_10150502_11_dialog_content = "え…？",
  ui_story_1015_10150502_12_dialog_content = "<size=45>うっ――！</size>",
  ui_story_1015_10150502_13_dialog_content = "<size=45>バイス！！！</size>",
  ui_story_1015_10150502_14_dialog_content = "ヘリオス…近くに隠れてたなんて…",
  ui_story_1015_10150502_15_dialog_content = "抵抗するなんて、ずいぶん愚かな選択ね。",
  ui_story_1015_10150502_16_dialog_content = "成功する可能性のないことをしたって、\n実験の進行を妨げる邪魔でしかないわ。",
  ui_story_1015_10150502_17_dialog_content = "私、実験を邪魔されるのが一番嫌いなの。",
  ui_story_1015_10150502_18_dialog_content = "な、何をする気！？",
  ui_story_1015_10150502_19_dialog_content = "今日の実験はおしまいよ。\nデータを整理したら、ここを離れるわ。",
  ui_story_1015_10150502_20_dialog_content = "空の末裔は私について来なさい。\nヘリオス、バイスを連れて行って。<color=#FFB400>別行動よ</color>。",
  ui_story_1015_10150502_21_dialog_content = "別行動！？",
  ui_story_1015_10150502_22_dialog_content = "さっきの出来事から考えて、\nあなたたちを一緒にしておくと、実験の不確定要素になるわ。",
  ui_story_1015_10150502_23_dialog_content = "だったら、離しておくのが一番でしょ。",
  ui_story_1015_10150502_24_dialog_content = "インゲル。今の状況を説明するので、よく聞きなさい。",
  ui_story_1015_10150502_25_dialog_content = "ノラが研究院に侵入し、\n我々の研究設備を無断で使用している。",
  ui_story_1015_10150502_26_dialog_content = "また、それ以前に研究院を訪れたバイス中尉と\n空の末裔からの連絡が途絶して数日が経過している。",
  ui_story_1015_10150502_27_dialog_content = "兵士の目撃情報を合わせて考慮すると、\nおそらく2人はノラに拘束されているものと推測される。",
  ui_story_1015_10150502_28_dialog_content = "PlayerNameたちが…？",
  ui_story_1015_10150502_29_dialog_content = "ユリシーズ教授。\nでは、私は何をすれば？",
  ui_story_1015_10150502_30_dialog_content = "人質を救出し、ノラを捕らえなさい。",
  ui_story_1015_10150502_31_dialog_content = "<size=45>！！！</size>",
  ui_story_1015_10150502_32_dialog_content = "（そのような無理難題を中佐一人に任せると…？）",
  ui_story_1015_10150502_33_dialog_content = "…承知しました。",
  ui_story_1015_10150502_34_dialog_content = "ただ、お言葉ですが、教授。\n現在の状況では任務完遂の可能性がきわめて低いものと考えます。",
  ui_story_1015_10150502_35_dialog_content = "相手が地形を熟知しており、強大な力を持っているうえに、\n人質までいるとなると…",
  ui_story_1015_10150502_36_dialog_content = "私1人では優位性が確保できません。",
  ui_story_1015_10150502_37_dialog_content = "「<color=#FFB400>兵器</color>」の使用許可がいただければ…",
  ui_story_1015_10150502_38_dialog_content = "…アクセリアか。",
  ui_story_1015_10150502_39_dialog_content = "…はい。",
  ui_story_1015_10150502_40_dialog_content = "アクセリアの力に頼りすぎないように。",
  ui_story_1015_10150502_41_dialog_content = "お前も「<color=#FFB400>啓明の星計画</color>」のメンバー、\nアクセリアとは得意分野が異なるというだけのこと。",
  ui_story_1015_10150502_42_dialog_content = "それに、今回は力さえあれば解決できるという問題でもない。\nお前自身の得意な方法で問題を解決してもらいたいところだ。",
  ui_story_1015_10150502_43_dialog_content = "分かりました、教授。",
  ui_story_1015_10150502_44_dialog_content = "アクセリアには別の重要な計画の準備がある。\nいずれお前の耳にも入るだろう。",
  ui_story_1015_10150502_45_dialog_content = "とは言え、彼女のような敵と対峙するとなれば、\n切り札を用意しておかねばならないことも事実。",
  ui_story_1015_10150502_46_dialog_content = "切り札は2枚ほど用意してある。",
  ui_story_1015_10150502_47_dialog_content = "ご教示ください。",
  ui_story_1015_10150502_48_dialog_content = "1枚目は、増援。",
  ui_story_1015_10150502_49_dialog_content = "信頼できる応援を呼んである。\n今はこちらへ向かっているところだろう。",
  ui_story_1015_10150502_50_dialog_content = "委員会が信頼を寄せる情報官、アナトリア少佐だ。",
  ui_story_1015_10150502_51_dialog_content = "彼のことなら知っています。\n確かに頼りになる応援です。",
  ui_story_1015_10150502_52_dialog_content = "もう1枚の切り札は…",
  ui_story_1015_10150502_53_dialog_content = "最後の最後まで伏せておきなさい。",
  ui_story_1015_10150601_1_dialog_content = "<color=#e8d9bb>トワイライトシティ、白夜要塞内</color>",
  ui_story_1015_10150601_2_dialog_content = "…",
  ui_story_1015_10150601_3_dialog_content = "<color=#e8d9bb>トントン――</color>",
  ui_story_1015_10150601_4_dialog_content = "入れ！",
  ui_story_1015_10150601_5_dialog_content = "…ジョセリン、お前だったか。",
  ui_story_1015_10150601_6_dialog_content = "日も暮れました。お祈りが始まります。\n…どなたかを待っていらっしゃるのですか？",
  ui_story_1015_10150601_7_dialog_content = "悪い時にお邪魔してしまったようですね。",
  ui_story_1015_10150601_8_dialog_content = "報告を待っているだけだ。\n今の騎士団にとって最重要事項だがな。",
  ui_story_1015_10150601_9_dialog_content = "前線では予断を許さない状況が続いているようですね。\n周辺でも暗鬼の攻撃を受ける村落が増えています。",
  ui_story_1015_10150601_10_dialog_content = "シェルターの規模は周辺地域の皆さんを避難させるのに十分とは言え…",
  ui_story_1015_10150601_11_dialog_content = "このままではいずれ、地上の防衛拠点が失われてしまいます。",
  ui_story_1015_10150601_12_dialog_content = "その通りだ。そんなことは絶対にあってはならん。",
  ui_story_1015_10150601_13_dialog_content = "暗鬼は次々と集結しているが、大規模な攻撃は起こしていない。\n白夜城、啓光連邦ともに増援の命令は出ていない。",
  ui_story_1015_10150601_14_dialog_content = "しかし、ここの兵士たちはすでに疲れきっている。\nこうして手をこまぬいている間にもすり減っていくと言っていい。",
  ui_story_1015_10150601_15_dialog_content = "では、今日は兵士の皆様の心が休まるように\nお祈りすることといたしましょう。",
  ui_story_1015_10150601_16_dialog_content = "ジョセリン、礼を言う。",
  ui_story_1015_10150601_17_dialog_content = "<color=#e8d9bb>トントン――</color>",
  ui_story_1015_10150601_18_dialog_content = "はぁ…はぁ…",
  ui_story_1015_10150601_19_dialog_content = "レオ団長…啓光の情報です！",
  ui_story_1015_10150601_20_dialog_content = "啓光から、駐屯軍全軍にただちに準備せよとの信号が！",
  ui_story_1015_10150601_21_dialog_content = "何の準備だ！？",
  ui_story_1015_10150601_22_dialog_content = "ご、<color=#FFB400>合同演習</color>の、準備です…",
  ui_story_1015_10150601_23_dialog_content = "！？",
  ui_story_1015_10150601_24_dialog_content = "<color=#e8d9bb>トワイライトシティ、共同統治シェルター</color>",
  ui_story_1015_10150601_25_dialog_content = "トワイライトシティからも招待されるのが恒例なのですか？",
  ui_story_1015_10150601_26_dialog_content = "そうだよ。演習の日取りはえらい人たちが決めるけど、\n僕たちも引っ張り出されるのが恒例なんだ。",
  ui_story_1015_10150601_27_dialog_content = "そうでしたか。\n前線の兵士にとって、良い知らせとはいえませんね。",
  ui_story_1015_10150601_28_dialog_content = "ホントだよ！よりによってこんな時に！",
  ui_story_1015_10150601_29_dialog_content = "そうですね。戦いは「長引かせれば不利」です。\nそもそも大規模な演習より、前線で本当に戦わせる方がよっぽど意味があります。",
  ui_story_1015_10150601_30_dialog_content = "招待状には何と書いてあるのですか？\nトワイライトシティから何名出せばよいのでしょう？",
  ui_story_1015_10150601_31_dialog_content = "3人だね。啓光の軍人、白夜城の騎士、聖職者で、各１人ずつ。\n参謀長のほかには…",
  ui_story_1015_10150601_32_dialog_content = "<color=#e8d9bb>トワイライトシティ、白夜要塞内</color>",
  ui_story_1015_10150601_33_dialog_content = "なるほど。共同統治の地とはいえ…\n啓光の命令には、お前たちも不満だろうな。",
  ui_story_1015_10150601_34_dialog_content = "当然でしょう！\nカナン城の軍人どもは、型にこだわる奴らばかりで困ります。",
  ui_story_1015_10150601_35_dialog_content = "前線が今まさに一触即発の状況だというのに、\nなぜあいつらの趣味に付き合わなければならないんですか！？",
  ui_story_1015_10150601_36_dialog_content = "いや…この招待状こそ、我々にとって天からの贈り物だ。",
  ui_story_1015_10150601_37_dialog_content = "贈り物？レオ団長、参加されるおつもりで？",
  ui_story_1015_10150601_38_dialog_content = "ああ、私が行く。",
  ui_story_1015_10150601_39_dialog_content = "団長！？",
  ui_story_1015_10150601_40_dialog_content = "合同演習には各勢力が集まり、全大陸が注目する…",
  ui_story_1015_10150601_41_dialog_content = "つまり、辺境が今動乱の只中にあることを全大陸に知らしめるチャンスだ。",
  ui_story_1015_10150601_42_dialog_content = "レオ団長…",
  ui_story_1015_10150601_43_dialog_content = "すぐに支度し、ヨーゼフ、ショウと合流する。",
  ui_story_1015_10150601_44_dialog_content = "私とヨーゼフの不在中は…ジョセリン、頼むぞ。",
  ui_story_1015_10150601_45_dialog_content = "ええ、分かりました。",
  ui_story_1015_10150601_46_dialog_content = "アイアンソーン騎士団と共に戦い、\n人々に心の安らぎを与えましょう…",
  ui_story_1015_10150601_47_dialog_content = "お戻りになったら、たっぷりご馳走していただきましょうか。",
  ui_story_1015_10150601_48_dialog_content = "ハハ、もちろんだ。",
  ui_story_1015_10150601_49_dialog_content = "<color=#e8d9bb>啓光連邦・カナン城、某所</color>",
  ui_story_1015_10150601_50_dialog_content = "断固反対だ。",
  ui_story_1015_10150601_51_dialog_content = "私には反対する権利がある、そうだろう？",
  ui_story_1015_10150601_52_dialog_content = "はい、大元帥。最高科学者会議の規定によれば、\n大元帥は確かに会議の意見に対し表決権をもっています。",
  ui_story_1015_10150601_53_dialog_content = "ならば、ご苦労だが、一刻も早く会議を開き、\n投票を行うよう通知せよ。",
  ui_story_1015_10150601_54_dialog_content = "大元帥、実のところ…「合同演習」の開催は\n最高科学者会議が利害を考慮したうえで決定したものです。",
  ui_story_1015_10150601_55_dialog_content = "大元帥が反対票を投じたとしても、\n最高科学者会議の皆様が簡単にあきらめるとは…",
  ui_story_1015_10150601_56_dialog_content = "お前を通すのも面倒だ。\n私が直接話す。ユリシーズを呼べ。",
  ui_story_1015_10150601_57_dialog_content = "申し訳ございません。ユリシーズ教授からはこの件について、\n大元帥が訪ねてきた場合、面会をお断りするよう申し付かっておりまして…",
  ui_story_1015_10150601_58_dialog_content = "フン…",
  ui_story_1015_10150601_59_dialog_content = "ならば私も言っておこう。\nバカ騒ぎが好きなら、勝手にやるがいい。関わろうとも思わん。",
  ui_story_1015_10150601_60_dialog_content = "だが、軍の戦略配置に影響が及ぶようなことは許さん。",
  ui_story_1015_10150601_61_dialog_content = "極光遺跡は今まさに援軍を必要としているのだ。\nそれが演習を理由に、反対に兵を前線から呼び立てるとは！",
  ui_story_1015_10150601_62_dialog_content = "でたらめにも程がある！",
  ui_story_1015_10150601_63_dialog_content = "申し訳ございません。大元帥、私は…",
  ui_story_1015_10150601_64_dialog_content = "下士官を困らせて何になるのかしら。",
  ui_story_1015_10150601_65_dialog_content = "ユリシーズの古だぬきが顔を出したくないらしいから、\n私と話せばいいわ。",
  ui_story_1015_10150601_66_dialog_content = "ただ…レインハト、あなたずいぶん興奮しているようね。\n少し冷静になった方がいいわ。ババ抜きでもどう？",
  ui_story_1015_10150601_67_dialog_content = "「<color=#FFB400>鉄仮面</color>」様…",
  ui_story_1015_10150601_68_dialog_content = "その冗談は笑えんな、<color=#FFB400>ベリサリア</color>。\nカード遊びに興味はない。",
  ui_story_1015_10150601_69_dialog_content = "しかし、お前が出てくるとは驚いた。",
  ui_story_1015_10150601_70_dialog_content = "冗談を言ったつもりはないわ。\n私の時間にも辛抱にも限りがあるのよ。",
  ui_story_1015_10150601_71_dialog_content = "1枚引いてちょうだい。その間にさっさと用件を言って。\nあなたなら出来るでしょう。",
  ui_story_1015_10150601_72_dialog_content = "…",
  ui_story_1015_10150601_73_dialog_content = "左。",
  ui_story_1015_10150601_74_dialog_content = "私の要求は簡単だ。戦いを回避する戦略には賛同できない。",
  ui_story_1015_10150601_75_dialog_content = "合同演習を一時中止し、\nトワイライトシティ駐屯軍の応援を最優先とすべきだ！",
  ui_story_1015_10150601_76_dialog_content = "あら、残念ね。\n「ジョーカー」よ、あなたの負けだわ。",
  ui_story_1015_10150601_77_dialog_content = "よく観察もせずに選択をするのは、\n歴代元帥に共通する悪い癖ね。",
  ui_story_1015_10150601_78_dialog_content = "レインハト、戦争はあなたが自由気ままに遊んでいいゲームではないの。\n戦争の本質は取引よ。",
  ui_story_1015_10150601_79_dialog_content = "勝ち負けは重要ではないわ。\n重要なのは負ければ何を失い、勝てば何を得るかよ。",
  ui_story_1015_10150601_80_dialog_content = "あなたは負けたわ。だから、私とのお話はこれでおしまい。",
  ui_story_1015_10150601_81_dialog_content = "それが学習できないというなら、\n委員会は別の人を探して、やらせるだけよ。",
  ui_story_1015_10150601_82_dialog_content = "…",
  ui_story_1015_10150601_83_dialog_content = "<color=#e8d9bb>ガサッ…</color>",
  ui_story_1015_10150601_84_dialog_content = "<color=#e8d9bb>白夜城アップタウン</color>",
  ui_story_1015_10150601_85_dialog_content = "啓光の合同演習には、今回も黎明学院の者を選んだのね。",
  ui_story_1015_10150601_86_dialog_content = "私たち四大天使はもちろん異論なしだよ。\nチャンスは若い子たちにあげなきゃね～。",
  ui_story_1015_10150601_87_dialog_content = "ラファエル様も子どもでは…？",
  ui_story_1015_10150601_88_dialog_content = "とにかく、カレンちゃんが隊長なら私はお留守番してるよ。",
  ui_story_1015_10150601_89_dialog_content = "復職審査を一気にクリアする絶好のチャンスだね～！\n頑張ってね、隊長！",
  ui_story_1015_10150601_90_dialog_content = "それはそうと、他に誰が招待されてるの？",
  ui_story_1015_10150601_91_dialog_content = "どういうわけか、今回は黎明学院に4枚招待状が届いているの。",
  ui_story_1015_10150601_92_dialog_content = "私のほかはクロエ、ユーライア…それから、ベルタ。",
  ui_story_1015_10150601_93_dialog_content = "ただ、私は正直なところ、\n今回の合同演習にはあまり興味がないの。",
  ui_story_1015_10150601_94_dialog_content = "前回の演習で私の率いたチームが優勝しているし…",
  ui_story_1015_10150601_95_dialog_content = "それに…復職するにも中身のない栄誉なんて必要ないわ。",
  ui_story_1015_10150601_96_dialog_content = "わぁ～、さすがは隊長！言うことが違うね…",
  ui_story_1015_10150601_97_dialog_content = "だから…ベルタ、どうかしら？\nクロエ、ユーライアの2人とうまくやれる？",
  ui_story_1015_10150601_98_dialog_content = "えっ！？",
  ui_story_1015_10150601_99_dialog_content = "私の代わりに、あなたにチームを率いてもらいたいの。\n白夜城を代表して戦いなさい。",
  ui_story_1015_10150601_100_dialog_content = "白夜城の外での任務は初めてでもないでしょう？\nあなたなら出来るわ。",
  ui_story_1015_10150601_101_dialog_content = "も、もちろんです！頂いたチャンスをムダにはしません！",
  ui_story_1015_10150601_102_dialog_content = "わ～、クロエとユーライアがベルタちゃんの部下ってこと？",
  ui_story_1015_10150601_103_dialog_content = "しっかり守ってあげてね！",
  ui_story_1015_10150601_104_dialog_content = "はい！",
  ui_story_1015_10150601_105_dialog_content = "ただ…合同演習の会場に無事たどり着けるかどうかは心配です。",
  ui_story_1015_10150601_106_dialog_content = "啓光のシェルターは複雑な構造になっていると聞きますし、\n一度も行ったことがないので…",
  ui_story_1015_10150601_107_dialog_content = "そのことなら心配いらないわ。",
  ui_story_1015_10150601_108_dialog_content = "演習に参加はしないけれど、カナン城へは私も同行するつもりよ。",
  ui_story_1015_10150601_109_dialog_content = "あれれ、なんで？",
  ui_story_1015_10150601_110_dialog_content = "正直に言うと、気がかりが2人いるから…",
  ui_story_1015_10150701_1_dialog_content = "<color=#e8d9bb>啓光連邦、X号シェルター</color>",
  ui_story_1015_10150701_2_dialog_content = "啓光連邦情報官アナトリアと申します。\n委員会の命によりインゲル中佐の補佐役を務めさせていただきます。",
  ui_story_1015_10150701_3_dialog_content = "あなたも情報官だったのですか？",
  ui_story_1015_10150701_4_dialog_content = "いえ…あなたのことは知っています。\n大元帥が天空ノ谷で日蝕と戦闘した時、助手を務めていた方でしたね。",
  ui_story_1015_10150701_5_dialog_content = "はい。さすがインゲル中佐、正確な情報をご存じです。\n以前から中佐とは共に働いてみたいと思っておりました。",
  ui_story_1015_10150701_6_dialog_content = "お世辞は結構です。それよりも早速準備にかかりましょう。",
  ui_story_1015_10150701_7_dialog_content = "…何を記録しているのですか？",
  ui_story_1015_10150701_8_dialog_content = "ああ、これは私のノートでして。中佐の印象を記録していたのです。\n「テキパキとした、仕事の早い方」だと…",
  ui_story_1015_10150701_9_dialog_content = "今はそんなこと…まあ、いいでしょう。\nそれがあなたのやり方だというのなら構いません。",
  ui_story_1015_10150701_10_dialog_content = "今回のあなたの任務は私に協力し、\n「人質を救出、ノラを拘束する」ことです。",
  ui_story_1015_10150701_11_dialog_content = "お話をさえぎって申し訳ないのですが、\nノラが…このシェルターにいるのですか？人質というのは？",
  ui_story_1015_10150701_12_dialog_content = "オホン。では、現状に関する情報を共有しましょう。",
  ui_story_1015_10150701_13_dialog_content = "かつて啓光全土に指名手配されたノラは現在、\nバイス中尉とPlayerNameを人質に取り――",
  ui_story_1015_10150701_14_dialog_content = "研究室に侵入、実験を行おうとしています。",
  ui_story_1015_10150701_15_dialog_content = "今回のノラの行動は天空ノ谷での戦役で起こった事と\n関係していると私は見ています。",
  ui_story_1015_10150701_16_dialog_content = "ノラは空の末裔の科学技術がバイス中尉にもたらした変化に、\n強い興味を持っているようです。",
  ui_story_1015_10150701_17_dialog_content = "だとすると、2人の置かれている状況は非常に危険ですね。",
  ui_story_1015_10150701_18_dialog_content = "しかし、啓光の情報網は何重にも張り巡らされています。\n2人も人質を取っているとなれば、逃れることは…",
  ui_story_1015_10150701_19_dialog_content = "それが厄介なことに、バイス中尉とノラは\n別々に行動しているようです。",
  ui_story_1015_10150701_20_dialog_content = "したがって、計画を2段階に分けて遂行します。",
  ui_story_1015_10150701_21_dialog_content = "まず、一刻も早くバイス中尉の所在を確認します。\nノラに気づかれる前に発見しなければなりません。",
  ui_story_1015_10150701_22_dialog_content = "その後ノラの計画を破壊します。PlayerNameが一緒にいますが、\nノラもPlayerNameには軽々しく手を出さないでしょう。",
  ui_story_1015_10150701_23_dialog_content = "できれば、PlayerNameの救出と同時にノラを拘束したいところです。",
  ui_story_1015_10150701_24_dialog_content = "はい！承知しました…",
  ui_story_1015_10150701_25_dialog_content = "また記録ですか？",
  ui_story_1015_10150701_26_dialog_content = "計画に関わる方々の性格や行動パターンに関する私自身の記録に基づき、\nこれから彼らがとるであろう行動の予測図を描いています。",
  ui_story_1015_10150701_27_dialog_content = "…大したものですね。",
  ui_story_1015_10150701_28_dialog_content = "<color=#e8d9bb>ピピ、ピピ！</color>",
  ui_story_1015_10150701_29_dialog_content = "おや…？",
  ui_story_1015_10150701_30_dialog_content = "（これは…来客信号？）",
  ui_story_1015_10150701_31_dialog_content = "<color=#e8d9bb>その頃、X号シェルターの別の場所</color>",
  ui_story_1015_10150701_32_dialog_content = "…",
  ui_story_1015_10150701_33_dialog_content = "止まらないで、さっさとついて来なさい。",
  ui_story_1015_10150701_34_dialog_content = "どうしたの？",
  ui_story_1015_10150701_35_dialog_content = "僕たちに協力しろって言った時、\n命の危険があるなんて一言も言わなかった。",
  ui_story_1015_10150701_36_dialog_content = "バイスのことを言ってるの？安心しなさい、殺しやしないわ。\n私にとっても彼女を死なせるのは「惜しい」ことだもの。",
  ui_story_1015_10150701_37_dialog_content = "抵抗する気？気が変わったのかしら？",
  ui_story_1015_10150701_38_dialog_content = "君の言うことなんて信じられない！",
  ui_story_1015_10150701_39_dialog_content = "面倒くさいわね。",
  ui_story_1015_10150701_40_dialog_content = "これを持ってなさい。",
  ui_story_1015_10150701_41_dialog_content = "<color=#e8d9bb>ザザ…ザーザー…</color>",
  ui_story_1015_10150701_42_dialog_content = "相手は…バイス？",
  ui_story_1015_10150701_43_dialog_content = "そうよ。啓光の連中は一人一台<color=#FFB400>トランシーバー</color>を持ってるでしょ。\nバイスの周波数とつないだままにしてあるわ。",
  ui_story_1015_10150701_44_dialog_content = "バイスはヘリオスと一緒にいる。\n後で直接話して確認すればいいわ。",
  ui_story_1015_10150701_45_dialog_content = "じゃあ、今は？",
  ui_story_1015_10150701_46_dialog_content = "今はこの兵士たちの片付けの手伝いね。",
  ui_story_1015_10150702_1_dialog_content = "バイス？聞こえる？",
  ui_story_1015_10150702_2_dialog_content = "PlayerName！無事なのね！",
  ui_story_1015_10150702_3_dialog_content = "バイス、君の方は！？",
  ui_story_1015_10150702_4_dialog_content = "私は大丈夫よ…ただ、閉じ込められてるの。",
  ui_story_1015_10150702_5_dialog_content = "見たところ、使われてない倉庫みたい。",
  ui_story_1015_10150702_6_dialog_content = "倉庫？",
  ui_story_1015_10150702_7_dialog_content = "警告しておくわ。\n余計なことはしゃべらないことね。",
  ui_story_1015_10150702_8_dialog_content = "トランシーバーを使って余計なまねをしようものなら…",
  ui_story_1015_10150702_9_dialog_content = "分かったよ！他のことを話せばいいんでしょ！？",
  ui_story_1015_10150702_10_dialog_content = "いいえ、おしゃべりはそこまでよ。",
  ui_story_1015_10150702_11_dialog_content = "目的地はもうこの先よ。先にやるべきことをやるわ。",
  ui_story_1015_10150702_12_dialog_content = "ここはどこ？何をする気？",
  ui_story_1015_10150702_13_dialog_content = "そんなに緊張することはないわ。ただの大きな「<color=#FFB400>資料室</color>」よ。\n必要なものを手に入れたら、さっさと失礼するわ。",
  ui_story_1015_10150702_14_dialog_content = "私の時間は貴重なの。",
  ui_story_1015_10150702_15_dialog_content = "じゃあ、どうして突っ立ったままなの？",
  ui_story_1015_10150702_16_dialog_content = "こっちへ来なさい。",
  ui_story_1015_10150702_17_dialog_content = "え？",
  ui_story_1015_10150702_18_dialog_content = "顔情報をスキャンしています…",
  ui_story_1015_10150702_19_dialog_content = "入力されたデータを解析しています…",
  ui_story_1015_10150702_20_dialog_content = "解錠しました。",
  ui_story_1015_10150702_21_dialog_content = "ど、どうして僕の顔でドアが開いたの？",
  ui_story_1015_10150702_22_dialog_content = "言ったでしょ？この研究院にあるものは全部私が作ったの。\nユリシーズはそれに少し手を加えただけ。",
  ui_story_1015_10150702_23_dialog_content = "ユリシーズの大会議室に入ったことがあるなら、\nあなたの顔でこのドアが開くのも当然よ。",
  ui_story_1015_10150702_24_dialog_content = "（僕の顔をスキャンした時、\n後ろに立ってたノラの顔も監視カメラに写ってたはずだ…）",
  ui_story_1015_10150702_25_dialog_content = "（ということは、すぐに…）",
  ui_story_1015_10150702_26_dialog_content = "モタモタしてないで、さっさと入りなさい。",
  ui_story_1015_10150702_27_dialog_content = "あなたはジェイドと入口に立ってなさい。\n扉を閉めて、大人しくしてることね。",
  ui_story_1015_10150702_28_dialog_content = "もし誰かが押し入ってきたら、ジェイドが片付けるわ。",
  ui_story_1015_10150702_29_dialog_content = "…いったい何の資料を探してるかぐらい、\n教えてくれてもいいんじゃない？",
  ui_story_1015_10150702_30_dialog_content = "ユリシーズが絶対に公表しようとしない資料よ。",
  ui_story_1015_10150702_31_dialog_content = "「<color=#FFB400>啓明の星計画</color>」の実験資料が必要なの。",
  ui_story_1015_10150801_1_dialog_content = "<color=#e8d9bb>しばらく前</color>",
  ui_story_1015_10150801_2_dialog_content = "うーん…プライバシーポリシー…同意。\n使用者条項も…同意っと！",
  ui_story_1015_10150801_3_dialog_content = "で、必要なファイルを更新して…",
  ui_story_1015_10150801_4_dialog_content = "<color=#e8d9bb>トントン！</color>",
  ui_story_1015_10150801_5_dialog_content = "どうぞ…",
  ui_story_1015_10150801_6_dialog_content = "室長、白夜城から来たと言う女性が\n室長を訪ねてきています。",
  ui_story_1015_10150801_7_dialog_content = "へえ、白夜城の女の子？\nじゃあ、起動画面の左側に立たせよっかな…",
  ui_story_1015_10150801_8_dialog_content = "き、起動画面、ですか？",
  ui_story_1015_10150801_9_dialog_content = "あ、ごめんごめん。ゲームのことだよ！",
  ui_story_1015_10150801_10_dialog_content = "ああ？カレンちゃん？",
  ui_story_1015_10150801_11_dialog_content = "あはは、そこの科学者先生、失礼だね～。\nあなたの隣に立ってるのは前回の合同演習の優勝者だよ。",
  ui_story_1015_10150801_12_dialog_content = "ごめんなさい、お邪魔してしまって。\nソラヴァンの状況が気になって見に来たの。",
  ui_story_1015_10150801_13_dialog_content = "それはそうと、バイスとPlayerNameはどこかしら？",
  ui_story_1015_10150801_14_dialog_content = "あっ、ソラヴァンね！\nこの前みんながトワイライトシティに行ってくれたおかげだよ！",
  ui_story_1015_10150801_15_dialog_content = "ほら見て。今はもう意識を取り戻して、\n羽根までパタパタさせられるようになったんだ。",
  ui_story_1015_10150801_16_dialog_content = "啓光の科学技術で修理したおかげで、百戦錬磨の状態を取り戻せたってこと。\nどんなムチャな着陸だって、心配いらないんだから！",
  ui_story_1015_10150801_17_dialog_content = "「縁起のいい」お言葉、ありがとうございます。ガルーさん。",
  ui_story_1015_10150801_18_dialog_content = "あ～あ、残念だな～。PlayerNameの感知能力で翻訳してもらわないと、\nソラヴァンの感謝の言葉も分からないよ。",
  ui_story_1015_10150801_19_dialog_content = "ソラヴァンの状態がいいなら、よかったわ。",
  ui_story_1015_10150801_20_dialog_content = "それで、今回も合同演習は優勝狙い？",
  ui_story_1015_10150801_21_dialog_content = "先に攻略情報を教えといてあげると…\n今回の参加者は今までみたいにイージーじゃないよ。",
  ui_story_1015_10150801_22_dialog_content = "いいえ、私は棄権したわ。白夜城のチームは別の人に任せてあるの。",
  ui_story_1015_10150801_23_dialog_content = "え？あ、そうか、分かった…",
  ui_story_1015_10150801_24_dialog_content = "やっぱり早く3人全員そろわないとダメってことだね。\nだって――",
  ui_story_1015_10150801_25_dialog_content = "カレンちゃんに出した招待状、\nPlayerNameチームとしての招待状だったもんね！",
  ui_story_1015_10150801_26_dialog_content = "そうだったの？ということは、\n空の末裔一族が久々に出場する記念すべき演習になるのね。",
  ui_story_1015_10150801_27_dialog_content = "その通りだよ。だから、元気出して頑張って。\n手を抜いたりしたらダメだよ～？",
  ui_story_1015_10150801_28_dialog_content = "ありがとう、分かったわ。",
  ui_story_1015_10150801_29_dialog_content = "それで、PlayerNameとバイスはどこに…",
  ui_story_1015_10150801_30_dialog_content = "あ、ちょっと待っててね。",
  ui_story_1015_10150801_31_dialog_content = "<color=#e8d9bb>ピッ――ピッ！</color>",
  ui_story_1015_10150801_32_dialog_content = "その招待状に通行証と地図が埋め込んでおいたよ。",
  ui_story_1015_10150801_33_dialog_content = "地図の光ってる座標がX号シェルターね。\n特別な光霊の治療や研究をしてるところだよ。",
  ui_story_1015_10150801_34_dialog_content = "（そういえばPlayerNameとバイス、\nあそこに行ってからずいぶん経ってるけど…）",
  ui_story_1015_10150801_35_dialog_content = "とにかく、その通行証があれば、\n普通の啓光の道ならほとんど通れるから。",
  ui_story_1015_10150801_36_dialog_content = "ありがとう。少し急いでるから、これで失礼するわ。",
  ui_story_1015_10150801_37_dialog_content = "いってらっしゃ～い。でも、白夜城にいる時みたいに\nおともの衛兵がいるわけじゃないから、十分気を付けてね。",
  ui_story_1015_10150801_38_dialog_content = "<color=#e8d9bb>啓光連邦、X号シェルター</color>",
  ui_story_1015_10150801_39_dialog_content = "（地図に従えば、ここがガルーの言っていた場所ね…）",
  ui_story_1015_10150801_40_dialog_content = "（想像していたよりも、ずっと大きいわ）",
  ui_story_1015_10150801_41_dialog_content = "（大型の建築を密集させて、大勢の人口を支えるというのが、\n啓光の生存戦略なのね）",
  ui_story_1015_10150801_42_dialog_content = "！？",
  ui_story_1015_10150801_43_dialog_content = "<color=#e8d9bb>バッ――</color>",
  ui_story_1015_10150801_44_dialog_content = "誰！？",
  ui_story_1015_10150801_45_dialog_content = "…インゲル？",
  ui_story_1015_10150801_46_dialog_content = "来客というのはあなたでしたか。",
  ui_story_1015_10150801_47_dialog_content = "ここで何を？…いえ、察しはついています。",
  ui_story_1015_10150801_48_dialog_content = "おそらく、同じ目的でやってきたのでしょう。",
  ui_story_1015_10150801_49_dialog_content = "いったいどういう状況なの？\n申し訳ないけれど、説明してもらえるかしら。",
  ui_story_1015_10150801_50_dialog_content = "シーッ！",
  ui_story_1015_10150801_51_dialog_content = "<anim type=Shake>グガァ…グガァ…</anim>",
  ui_story_1015_10150801_52_dialog_content = "先にこの暗鬼どもを片付けないと。",
  ui_story_1015_10150801_53_dialog_content = "だったら何を待っているの？\nさっさと倒してしまいましょう。",
  ui_story_1015_10150802_1_dialog_content = "どうしてそんなことに！？考えられないわ！",
  ui_story_1015_10150802_2_dialog_content = "ノラは何を企んでいるの？",
  ui_story_1015_10150802_3_dialog_content = "啓光も、なぜ今日になっても\nまだ兵も出さず、包囲もしていないの？",
  ui_story_1015_10150802_4_dialog_content = "落ち着いてください。\n白夜城と違い、ここでは重要事項の決定に各方面の共同決議が必要なのです。",
  ui_story_1015_10150802_5_dialog_content = "委員会もすでにこの件で動き始めています。\n我々は決定が下される前に派遣されてきた先遣隊です。",
  ui_story_1015_10150802_6_dialog_content = "では、これからどうするつもり？",
  ui_story_1015_10150802_7_dialog_content = "情報官の立場から言わせていただきますと、まず情報を取りまとめて整理し、\n最も効率よくノラに近づく方法を割り出さなければなりません。",
  ui_story_1015_10150802_8_dialog_content = "幸い、死角の全くない監視カメラから突破口を導き出せると考えます。",
  ui_story_1015_10150802_9_dialog_content = "上層部から監視カメラの記録の使用が許可されれば、\nノラとバイス中尉の位置がはっきりします。",
  ui_story_1015_10150802_10_dialog_content = "それは難しいでしょう。",
  ui_story_1015_10150802_11_dialog_content = "どのような目的でそうしているのかは分かりませんが、\nこの場の監視カメラは身分認証のみに使われており、記録は即時消去されます。",
  ui_story_1015_10150802_12_dialog_content = "なんと…",
  ui_story_1015_10150802_13_dialog_content = "何かやましいことがあるかのようね。",
  ui_story_1015_10150802_14_dialog_content = "いずれにせよ、シェルター内をやみくもに探すわけにはいかないわ。",
  ui_story_1015_10150802_15_dialog_content = "お待ちください。思いついたことがあります。",
  ui_story_1015_10150802_16_dialog_content = "啓光で起こったことは、当然…啓光式で解決すべきです。",
  ui_story_1015_10150901_1_dialog_content = "（1号から50号のAレベルの書類は全部見たけど、この中にはないみたいね）",
  ui_story_1015_10150901_2_dialog_content = "（書類をいちいちひっくり返していたらキリがないわ。\nこの棚の書類の表題をチェックするだけで1か月はかかりそうね…）",
  ui_story_1015_10150901_3_dialog_content = "（ユリシーズ本人に聞くわけにもいかないし、\n書類の分類基準を早く見極めないと…）",
  ui_story_1015_10150901_4_dialog_content = "バイス、食べ物と水は足りてる？",
  ui_story_1015_10150901_5_dialog_content = "安心して…と水は…るわ。",
  ui_story_1015_10150901_6_dialog_content = "え？",
  ui_story_1015_10150901_7_dialog_content = "え？聞こえてる？",
  ui_story_1015_10150901_8_dialog_content = "あ、今は聞こえる。\nさっきは声が途切れてたのに…おかしいね。",
  ui_story_1015_10150901_9_dialog_content = "充電が減ってきたんじゃないかしら？\nトランシーバーの電池は容量が小さいから、ずっと使ってるとすぐに切れちゃうの。",
  ui_story_1015_10150901_10_dialog_content = "え？電池切れなんてあるんだ――",
  ui_story_1015_10150901_11_dialog_content = "うるさいわね。よこしなさい。",
  ui_story_1015_10150901_12_dialog_content = "ちょっと！何するつもり！？",
  ui_story_1015_10150901_13_dialog_content = "後でまたいじらせてあげるわ。\n今はこっちを手伝いなさい。",
  ui_story_1015_10150901_14_dialog_content = "今度は何？",
  ui_story_1015_10150901_15_dialog_content = "空の末裔なら、誰かが最近触った書類がどれか、\n感知できるでしょう。",
  ui_story_1015_10150901_16_dialog_content = "手伝いなさい。",
  ui_story_1015_10150901_17_dialog_content = "…そんなことできないよ。犬じゃあるまいし…",
  ui_story_1015_10150901_18_dialog_content = "チッ、あなたもあの機械の中に叩き込んでおけばよかったかしら。",
  ui_story_1015_10150901_19_dialog_content = "できないっていうなら、\nこのホストコンピューターのロックの突破法でも考えなさい。",
  ui_story_1015_10150901_20_dialog_content = "それは僕も気になってたんだ。\nこの機械、ものすごく存在感があるね。",
  ui_story_1015_10150901_21_dialog_content = "どこの研究所にでもあるものよ。",
  ui_story_1015_10150901_22_dialog_content = "資料の検索やら機械の制御やら…\nとにかく、科学者の研究には欠かせない道具だもの。",
  ui_story_1015_10150901_23_dialog_content = "なるほどね…",
  ui_story_1015_10150901_24_dialog_content = "でも、どうしても僕が？\n万が一が有ったら困るし、僕はいじらない方がいいと思うけど。",
  ui_story_1015_10150901_25_dialog_content = "啓光の科学技術には詳しくないし。",
  ui_story_1015_10150901_26_dialog_content = "…ずいぶん面倒くさがるわね。",
  ui_story_1015_10150901_27_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1015_10150901_28_dialog_content = "ちょ、ちょっと待ってよ。\nそんな適当にパスワードを入れたって…",
  ui_story_1015_10150901_29_dialog_content = "科学技術なんてものはそもそも研究補助のためにあるの。\n役に立たないなら、存在価値もないのよ。",
  ui_story_1015_10150901_30_dialog_content = "<color=#e8d9bb>ピッ、ピ――ピッ</color>",
  ui_story_1015_10150901_31_dialog_content = "…ふーん…",
  ui_story_1015_10150901_32_dialog_content = "（…何かいじってるけど、解除の仕方を知ってるのかな…）",
  ui_story_1015_10150901_33_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1015_10150901_34_dialog_content = "<color=#e8d9bb>警告！警告！</color>",
  ui_story_1015_10150901_35_dialog_content = "<color=#e8d9bb>パスワードが間違っています。緊急警報装置が起動しました――</color>",
  ui_story_1015_10150901_36_dialog_content = "え！？",
  ui_story_1015_10150901_37_dialog_content = "<anim type=Shake><size=45>ビーッ、ビーッ</size></anim>",
  ui_story_1015_10150901_38_dialog_content = "これはいったい…？",
  ui_story_1015_10150901_39_dialog_content = "あれだけ自信たっぷりに操作してたのに？",
  ui_story_1015_10150901_40_dialog_content = "ミスは当然のことよ。電子技術は私の専門外だもの。",
  ui_story_1015_10150901_41_dialog_content = "とにかく何とかしなきゃ…ミスの原因を分析してる場合じゃないよ！",
  ui_story_1015_10150901_42_dialog_content = "<color=#e8d9bb>バンッ――</color>",
  ui_story_1015_10150901_43_dialog_content = "資料室のブレーカーを落とせばいいだけのことよ。",
  ui_story_1015_10150901_44_dialog_content = "本当に大丈夫かな…？",
  ui_story_1015_10150901_45_dialog_content = "…",
  ui_story_1015_10150901_46_dialog_content = "<anim type=Shake><size=45>ビーッ、ビーッ</size></anim>",
  ui_story_1015_10150901_47_dialog_content = "やっぱり全然解決になってない！",
  ui_story_1015_10150901_48_dialog_content = "チッ…ほんとに面倒くさいわね。",
  ui_story_1015_10150901_49_dialog_content = "あの機械の犬を片付けるしかないようね。ジェイド――",
  ui_story_1015_10150901_50_dialog_content = "<anim type=Shake><size=50>グウ！！！</size></anim>",
  ui_story_1015_10150901_51_dialog_content = "かみ砕いてしまいなさい。",
  ui_story_1015_10150902_1_dialog_content = "<anim type=Shake><size=45>ウウウ…ウウウ…</size></anim>",
  ui_story_1015_10150902_2_dialog_content = "よくやったわね。食べてしまっていいわ。",
  ui_story_1015_10150902_3_dialog_content = "そのまま入口を見張っていなさい。いいわね？",
  ui_story_1015_10150902_4_dialog_content = "<anim type=Shake><size=45>ウウ…</size></anim>",
  ui_story_1015_10150902_5_dialog_content = "この機械の犬…ここの見張り番だったのかな？",
  ui_story_1015_10150902_6_dialog_content = "さあ？私が残したものじゃないから分からないわ。",
  ui_story_1015_10150902_7_dialog_content = "もうずいぶんと時間をムダにしてるの。\n少しスピードをあげるわよ。",
  ui_story_1015_10150902_8_dialog_content = "<color=#e8d9bb>ピッ、ピ――ピッ</color>",
  ui_story_1015_10150902_9_dialog_content = "<color=#e8d9bb>メインメモリーを起動しました！</color>",
  ui_story_1015_10150902_10_dialog_content = "「啓明の星計画」で検索を続けましょう。",
  ui_story_1015_10150902_11_dialog_content = "…いいえ、それじゃ欲しい資料は見つからないわ…",
  ui_story_1015_10150902_12_dialog_content = "…キーワードを変更するわ。\n「<color=#FFB400>人造陽光計画</color>」で検索…",
  ui_story_1015_10150902_13_dialog_content = "（人造…陽光？どんな研究だろう？名前からして…\nまさか太陽でも造り出そうとしてたの？）",
  ui_story_1015_10150902_14_dialog_content = "（啓明の星の次は太陽か…ノラはいったい何を探してるんだろう…）",
  ui_story_1015_10150902_15_dialog_content = "見つかったわ。",
  ui_story_1015_10150902_16_dialog_content = "さあ、急いで撤退するわよ。",
  ui_story_1015_10150902_17_dialog_content = "ノラ、君とユリシーズが2人して重要視してるなんて、\nその資料にはどんなことが書かれてるの？",
  ui_story_1015_10150902_18_dialog_content = "知りたい？",
  ui_story_1015_10150902_19_dialog_content = "あなたが知ったところで何の役にも立たないわ。\n天空ノ谷にある装置はもう使えないんだから。",
  ui_story_1015_10150902_20_dialog_content = "それに私の研究はすでに、\n啓光と空の末裔の科学技術レベルを超えているの。",
  ui_story_1015_10150902_21_dialog_content = "だから、余計なことを考えない方が身のためよ。",
  ui_story_1015_10150902_22_dialog_content = "ただ興味があったから聞いただけだよ。\nさっきの戦いでは僕も一役買ったんだ。目的も知らされないなんておかしい。",
  ui_story_1015_10150902_23_dialog_content = "今の僕を警戒する必要もないでしょ？",
  ui_story_1015_10150902_24_dialog_content = "…",
  ui_story_1015_10150902_25_dialog_content = "話してあげてもいいわ。",
  ui_story_1015_10150902_26_dialog_content = "もともとあなたも知ってることだしね。",
  ui_story_1015_10150902_27_dialog_content = "僕も知ってること…？",
  ui_story_1015_10150902_28_dialog_content = "「底なし沼」で長い間眠っていたヘリオスを目覚めさせた時――",
  ui_story_1015_10150902_29_dialog_content = "私たち3人の過去について、あの女からいろいろ聞いたでしょ。",
  ui_story_1015_10150902_30_dialog_content = "私たちは一緒に育って、軍に入り、共に戦った…",
  ui_story_1015_10150902_31_dialog_content = "そんな風に長く一緒にいられたのは、\nもちろん友情や絆とかいったものじゃないわ。",
  ui_story_1015_10150902_32_dialog_content = "3人とも最初の「<color=#FFB400>人造陽光計画</color>」の実験台だったからよ。",
  ui_story_1015_10150902_33_dialog_content = "同じ成長過程を経て、同じ戦場で戦い、同じ改造を受けた者だけが、\n互いに分かり合える。",
  ui_story_1015_10150902_34_dialog_content = "ただ、当時の古だぬきどもの研究が本当に大したことなかっただけ。",
  ui_story_1015_10150902_35_dialog_content = "レインハトが今のように普通でいられるのが不思議なくらいよ。",
  ui_story_1015_10150902_36_dialog_content = "その後、計画はもっと耳障りのいい名前に変えられたの。\nそれが「<color=#FFB400>啓明の星計画</color>」よ。",
  ui_story_1015_10150902_37_dialog_content = "そんな…まさか、そんな理由があったなんて…",
  ui_story_1015_10150902_38_dialog_content = "何よ、その表情。胸くそが悪くなるわね。\n空の末裔って何にでも同情する種族なの？",
  ui_story_1015_10150902_39_dialog_content = "ほら、トランシーバーよ。もう通信していいわ。",
  ui_story_1015_10150902_40_dialog_content = "あれ？",
  ui_story_1015_10150902_41_dialog_content = "<color=#e8d9bb>ザザ…ザーザー…</color>",
  ui_story_1015_10150902_42_dialog_content = "PlayerName！何があったの！？",
  ui_story_1015_10150902_43_dialog_content = "…バイス！",
  ui_story_1015_10150902_44_dialog_content = "<color=#e8d9bb>ザザ…ザーザー…</color>",
  ui_story_1015_10150902_45_dialog_content = "あ…",
  ui_story_1015_10150902_46_dialog_content = "バイスのトランシーバーの周波に動きが！",
  ui_story_1015_10150902_47_dialog_content = "周波の乱れの位置から、バイスの居場所を確認できない！？",
  ui_story_1015_10150902_48_dialog_content = "啓光の今の技術では、おそらく無理でしょう。",
  ui_story_1015_10150902_49_dialog_content = "ですが、少なくともバイス中尉が\nご自身のトランシーバーを使ったことだけは分かります。",
  ui_story_1015_10150902_50_dialog_content = "ということは、ある程度行動の自由が許されているのでしょう。",
  ui_story_1015_10150902_51_dialog_content = "私が推測するに、バイス中尉が通信している相手はノラで間違いないでしょう。",
  ui_story_1015_10150902_52_dialog_content = "ええ、その通りです。\nアナトリア、常にバイス中尉の周波数の変化に注意していてください。",
  ui_story_1015_10150902_53_dialog_content = "承知いたしました。",
  ui_story_1015_10150902_54_dialog_content = "では、救出作戦を立てましょう。",
  ui_story_1015_10150902_55_dialog_content = "私のつかんでいる情報によれば、\nユリシーズ教授の資料館の警報システムが先程発動しました。",
  ui_story_1015_10150902_56_dialog_content = "間違いなくノラはそこにいます。\nPlayerNameも一緒のはずです。",
  ui_story_1015_10150902_57_dialog_content = "さらにバイス中尉の位置を確認できれば、\n救出計画を実行に移すことができます。",
  ui_story_1015_10151001_1_dialog_content = "バイス、僕は大丈夫だよ！\n今ノラと一緒にX号シェルターの資料庫にいるんだ。",
  ui_story_1015_10151001_2_dialog_content = "君の方は大丈夫？ケガしてない？今、どこにいるの？",
  ui_story_1015_10151001_3_dialog_content = "<anim type=Shake>私は…の扉で…光が射し…</anim>",
  ui_story_1015_10151001_4_dialog_content = "バイス？何？",
  ui_story_1015_10151001_5_dialog_content = "どうしたんだろう？よく聞こえない…\nまたトランシーバーの電池が切れそうになってるのかな？",
  ui_story_1015_10151001_6_dialog_content = "<color=#e8d9bb>ピッ――</color>",
  ui_story_1015_10151001_7_dialog_content = "通信はおしまいよ。\nあなた、聞いちゃいけないことを聞いたわ。",
  ui_story_1015_10151001_8_dialog_content = "前もって何も言われてないんだ！\n聞きたいことを聞いて当然でしょ！",
  ui_story_1015_10151001_9_dialog_content = "そんなに慌ててトランシーバーを切ったりして、\nいったい何におびえてるの？",
  ui_story_1015_10151001_10_dialog_content = "誤解よ。私が切ったんじゃないわ。",
  ui_story_1015_10151001_11_dialog_content = "そのポンコツ機械の電池が切れたのよ。",
  ui_story_1015_10151001_12_dialog_content = "（あ、本当だ…）",
  ui_story_1015_10151001_13_dialog_content = "（もうっ！なんだってこんな大事な時に…）",
  ui_story_1015_10151001_14_dialog_content = "さ、時間がもったいないわ。",
  ui_story_1015_10151001_15_dialog_content = "行くわよ。新しい実験を始めないといけないの。",
  ui_story_1015_10151001_16_dialog_content = "ユリシーズ教授以外の者がここに足を踏み入れることはほぼありません。",
  ui_story_1015_10151001_17_dialog_content = "目印となる建物は2つだけ――\n先程警報システムが発動した資料館と実験室です。",
  ui_story_1015_10151001_18_dialog_content = "さすがはインゲル中佐ですね…私も長らく委員会で仕事をしていますが、\nこの場所については一切知りませんでした。",
  ui_story_1015_10151001_19_dialog_content = "機密として処理してください。\n教授はここのことを多くの人に知られたくはないので。",
  ui_story_1015_10151001_20_dialog_content = "ですから、たとえ誰であろうと、\n許可なく侵入する者は私が断固として追い払います。",
  ui_story_1015_10151001_21_dialog_content = "バイス中尉の周波数に動きはありましたか？",
  ui_story_1015_10151001_22_dialog_content = "ありません。通信時の電流音も聞こえなくなったので、\nあちらの通信が切断されたのかもしれません。",
  ui_story_1015_10151001_23_dialog_content = "少しお借りします――",
  ui_story_1015_10151001_24_dialog_content = "バイス中尉、聞こえますか？\nこちらインゲル。応答してください。",
  ui_story_1015_10151001_25_dialog_content = "お話しできる状態であれば、すぐに応答してください！",
  ui_story_1015_10151001_26_dialog_content = "ちょっと待って！\nそんなことしたら、バイスの通信相手にも声が聞こえるのでは？",
  ui_story_1015_10151001_27_dialog_content = "通常はそうです。\nですが今はノラの方のトランシーバーは電池が切れています。",
  ui_story_1015_10151001_28_dialog_content = "電池切れ！？",
  ui_story_1015_10151001_29_dialog_content = "2人の会話は私もずっと聞いていましたが、\nPlayerNameが頻繁に使うので、電池の減りも速くなっていたのです。",
  ui_story_1015_10151001_30_dialog_content = "先程の音から推測するに、今は完全に電池が切れている頃でしょう。",
  ui_story_1015_10151001_31_dialog_content = "今この瞬間に作戦の成否がかかっています。",
  ui_story_1015_10151001_32_dialog_content = "い…インゲル中佐…ですか？",
  ui_story_1015_10151001_33_dialog_content = "（やったわ！）",
  ui_story_1015_10151001_34_dialog_content = "今すぐ位置を報告してください！",
  ui_story_1015_10151001_35_dialog_content = "何か特徴的な物があれば、それでも構いません。",
  ui_story_1015_10151001_36_dialog_content = "承知しました！私は今X号シェルターの倉庫に閉じ込められています。\n灰色の扉の倉庫です。窓があるので自然光が射し込んでいます。",
  ui_story_1015_10151001_37_dialog_content = "分かりました。",
  ui_story_1015_10151001_38_dialog_content = "通信をつないだままにしておくので、電池切れにならないよう注意してください。\nノラが通信してきた場合もこちらで把握できますから。",
  ui_story_1015_10151001_39_dialog_content = "他に誰かいますか？",
  ui_story_1015_10151001_40_dialog_content = "ヘリオスに連れて来られたんですが、\n先程どこかへ行ってしまいました。",
  ui_story_1015_10151001_41_dialog_content = "分かりました。今すぐそちらへ向かいます。",
  ui_story_1015_10151001_42_dialog_content = "インゲル中佐、バイス中尉の居場所の見当がついているのですか？",
  ui_story_1015_10151001_43_dialog_content = "X号シェルターの南側は地形が低く、守りやすく攻め難くなっています。\n倉庫はそこに集中しています。",
  ui_story_1015_10151001_44_dialog_content = "灰色の扉であれば、固体薬物保管用の倉庫です。",
  ui_story_1015_10151001_45_dialog_content = "先程バイス中尉の声は大きく反響していました。\nということは、大型倉庫に違いありません。",
  ui_story_1015_10151001_46_dialog_content = "さらに地下倉庫と規模の小さい貯蔵室等を除くと…",
  ui_story_1015_10151001_47_dialog_content = "バイス中尉が閉じ込められている可能性のある場所は、\nX-106号倉庫、X-107号倉庫、X-108号倉庫の3カ所に絞られます。",
  ui_story_1015_10151001_48_dialog_content = "すぐに出発しましょう。",
  ui_story_1015_10151001_49_dialog_content = "いいえ、私とアナトリアの2人で向かいます。\nカレン、あなたには別の事をお願いしたいのです。",
  ui_story_1015_10151001_50_dialog_content = "資料館へ向かい、PlayerNameを救出してください。",
  ui_story_1015_10151001_51_dialog_content = "2人の安全を確保するには、同時に救出しなければなりません。",
  ui_story_1015_10151001_52_dialog_content = "そうね、分かったわ。",
  ui_story_1015_10151001_53_dialog_content = "バイス中尉を救出し次第、すぐに応援に向かいます。",
  ui_story_1015_10151001_54_dialog_content = "お気をつけて。",
  ui_story_1015_10151001_55_dialog_content = "<color=#e8d9bb>X号シェルター、南側倉庫</color>",
  ui_story_1015_10151001_56_dialog_content = "インゲル中佐の推測どおりですね。",
  ui_story_1015_10151001_57_dialog_content = "この辺りの特徴はまさにバイス中尉の言っていた通りです。",
  ui_story_1015_10151001_58_dialog_content = "インゲル中佐、この後はどうするのですか？",
  ui_story_1015_10151001_59_dialog_content = "一つ一つ調べるしかないでしょう。",
  ui_story_1015_10151001_60_dialog_content = "幸いノラもまだ次の行動は起こしていません…",
  ui_story_1015_10151001_61_dialog_content = "<color=#e8d9bb>ドンッ――！</color>",
  ui_story_1015_10151001_62_dialog_content = "<anim type=Shake><size=50>グオオ！！！</size></anim>",
  ui_story_1015_10151001_63_dialog_content = "な、何者ですか…",
  ui_story_1015_10151001_64_dialog_content = "（こちらの行動を読まれていましたか…！）",
  ui_story_1015_10151001_65_dialog_content = "<anim type=Shake><size=50>グオオ！！！</size></anim>",
  ui_story_1015_10151001_66_dialog_content = "気を付けてください！向かってきます！",
  ui_story_1015_10151101_1_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_1015_10151101_2_dialog_content = "完璧な射撃です。",
  ui_story_1015_10151101_3_dialog_content = "<anim type=Shake><size=50>グオ――！！！</size></anim>",
  ui_story_1015_10151101_4_dialog_content = "いったいどうなっているのですか！？",
  ui_story_1015_10151101_5_dialog_content = "情報では、レインハト大元帥が重傷を負わせていたはず…",
  ui_story_1015_10151101_6_dialog_content = "それなのになぜ、\nこれほど強力な戦闘力が残っているのでしょう？",
  ui_story_1015_10151101_7_dialog_content = "<anim type=Shake><size=50>グオ！</size></anim>",
  ui_story_1015_10151101_8_dialog_content = "危ない！",
  ui_story_1015_10151101_9_dialog_content = "うっ…！",
  ui_story_1015_10151101_10_dialog_content = "ありがとうございます…",
  ui_story_1015_10151101_11_dialog_content = "情報を過度に信用してはいけませんよ、インゲル中佐。\n情報も正確でないことがあります。",
  ui_story_1015_10151101_12_dialog_content = "中佐の言う情報が本当ならば、こいつは…",
  ui_story_1015_10151101_13_dialog_content = "いえ、彼…ヘリオス大尉は自我のないまま、\n暗面で独り10年以上生きていたのです。",
  ui_story_1015_10151101_14_dialog_content = "それだけでも、あなどれない相手であることは明らかです。",
  ui_story_1015_10151101_15_dialog_content = "しかもレインハト大元帥と同じく、\n強化改造を受けています…",
  ui_story_1015_10151101_16_dialog_content = "私たちが2人して向かって行ったところで、\nおそらく大元帥の半分にも及ばないでしょう。",
  ui_story_1015_10151101_17_dialog_content = "そんなことは言われずとも分かっています、アナトリア少佐。",
  ui_story_1015_10151101_18_dialog_content = "相手は我々よりはるかに機敏なうえ、この開けた地形ではこちらが明らかに不利です。\nこれ以上ここで戦っていては我々が先に力尽きてしまいます。",
  ui_story_1015_10151101_19_dialog_content = "廊下まで下がって、相手の行動を制限しましょう。",
  ui_story_1015_10151101_20_dialog_content = "承知しました！",
  ui_story_1015_10151101_21_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_1015_10151101_22_dialog_content = "…",
  ui_story_1015_10151101_23_dialog_content = "立ち去りましたね。",
  ui_story_1015_10151101_24_dialog_content = "正面から向かって行っても勝ち目はありません。\nしかし地形を利用すれば、奇襲を仕掛け、弱点を突くことができます。",
  ui_story_1015_10151101_25_dialog_content = "ノラさえ――",
  ui_story_1015_10151101_26_dialog_content = "いえ、おかしいですね…",
  ui_story_1015_10151101_27_dialog_content = "<size=45>大変です！</size>",
  ui_story_1015_10151101_28_dialog_content = "どうされたのですか？",
  ui_story_1015_10151101_29_dialog_content = "強化改造を受けた光霊の間には、\n特別な感知能力のようなものが存在します。",
  ui_story_1015_10151101_30_dialog_content = "ここで私たちと戦ったことは、おそらくノラに伝わっています！",
  ui_story_1015_10151101_31_dialog_content = "…！",
  ui_story_1015_10151101_32_dialog_content = "それほど重要な情報を私はなぜ事前に知らされていなかったのですか？",
  ui_story_1015_10151101_33_dialog_content = "実験計画はそもそも最高機密なのです。",
  ui_story_1015_10151101_34_dialog_content = "よっぽどの緊急事態でなければ、\n私やあなたのような地位の者が知り得るような情報ではないのです。",
  ui_story_1015_10151101_35_dialog_content = "申し訳ありません。私がいけなかったのです。\nきちんとお伝えしておくべきでした。",
  ui_story_1015_10151101_36_dialog_content = "難しい状況になりましたね…",
  ui_story_1015_10151101_37_dialog_content = "（委員会は…いったいどれだけの秘密を隠しているのでしょう？）",
  ui_story_1015_10151101_38_dialog_content = "（人体改造にしても、当時私の所属していたチームが命をかけて\n持ち帰った情報が改ざんされた件にしても…）",
  ui_story_1015_10151101_39_dialog_content = "（委員会を本当に信用していいのでしょうか？）",
  ui_story_1015_10151101_40_dialog_content = "戦いを続けるわけにはいきません。",
  ui_story_1015_10151101_41_dialog_content = "我々の行動がすでに気付かれているとしたら、\nノラが何か対抗策を講じないはずがありません。",
  ui_story_1015_10151101_42_dialog_content = "バイス中尉はひとまず安全でしょうが、\nカレンさんはまだ自身の行動が相手に気づかれていることを知りません。",
  ui_story_1015_10151101_43_dialog_content = "急いでヤツを振り切って、カレンさんの応援に向かわねば。",
  ui_story_1015_10151101_44_dialog_content = "もちろん応援に行きます。ただし、別行動しましょう。",
  ui_story_1015_10151101_45_dialog_content = "あなたは身を隠すのが得意ですから、うまく機を見計らってバイス中尉を救出し、\nその後急ぎカレンと合流してください。",
  ui_story_1015_10151101_46_dialog_content = "中佐はどうなさるのです？",
  ui_story_1015_10151101_47_dialog_content = "ノラはこの怪物よりもさらに手ごわい相手です。\n私たちが応援に向かったところで勝算はわずかです。",
  ui_story_1015_10151101_48_dialog_content = "切り札を使って、彼女の妥協を引き出します。",
  ui_story_1015_10151101_49_dialog_content = "<color=#e8d9bb>同じころ、PlayerNameとノラは…</color>",
  ui_story_1015_10151101_50_dialog_content = "…",
  ui_story_1015_10151101_51_dialog_content = "<anim type=Shake>ウウ、ウウ――</anim>",
  ui_story_1015_10151101_52_dialog_content = "ジェイド、静かにしなさい。",
  ui_story_1015_10151101_53_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_1015_10151101_54_dialog_content = "うるさいわね。",
  ui_story_1015_10151101_55_dialog_content = "確かにうるさいな。この子の声が大きすぎて、\n鼓膜が破れそうだ。",
  ui_story_1015_10151101_56_dialog_content = "黙りなさい。",
  ui_story_1015_10151101_57_dialog_content = "ネズミがチョロチョロしているようね。",
  ui_story_1015_10151101_58_dialog_content = "ネズミ？",
  ui_story_1015_10151101_59_dialog_content = "（この光力の気配は…まさか…！）",
  ui_story_1015_10151101_60_option_content = "感知",
  ui_story_1015_10151101_61_dialog_content = "（カレン！？）",
  ui_story_1015_10151101_62_dialog_content = "出てきなさい。",
  ui_story_1015_10151101_63_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1015_10151101_64_dialog_content = "愚かね。",
  ui_story_1015_10151101_65_dialog_content = "<size=45>（カレン、危ない！！）</size>",
  ui_story_1015_10151101_66_dialog_content = "（な…）",
  ui_story_1015_10151101_67_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_1015_10151101_68_dialog_content = "ゲホッ…ゴホゴホッ！！",
  ui_story_1015_10151101_69_dialog_content = "なぜ…分かったの？",
  ui_story_1015_10151101_70_dialog_content = "あなたたちの戦術、お粗末としかいいようがないわ。",
  ui_story_1015_10151101_71_dialog_content = "…",
  ui_story_1015_10151101_72_dialog_content = "ただ、実験結果に影響を及ぼす要素であることには変わりない。\n時間を割いて排除するだけの価値はあるわ。",
  ui_story_1015_10151101_73_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_1015_10151101_74_dialog_content = "なんて数なの…",
  ui_story_1015_10151101_75_dialog_content = "やってしまいなさい。",
  ui_story_1015_10151101_76_dialog_content = "<anim type=Shake><size=50>グオオ！！！</size></anim>",
  ui_story_1015_10151102_1_dialog_content = "うっ…！！！",
  ui_story_1015_10151102_2_dialog_content = "<anim type=Shake><size=45>グォアアア！</size></anim>",
  ui_story_1015_10151102_3_dialog_content = "いくら倒してもキリがない…",
  ui_story_1015_10151102_4_dialog_content = "カレン！！",
  ui_story_1015_10151102_5_dialog_content = "どうせ二手に分かれて、\n空の末裔と彼女を同時に助け出そうとしていたのでしょう。",
  ui_story_1015_10151102_6_dialog_content = "でもね、その作戦の大前提は、\n自分たちの実力に絶対の自信を持っていること。",
  ui_story_1015_10151102_7_dialog_content = "なぜそれを…？",
  ui_story_1015_10151102_8_dialog_content = "古だぬきどもの計画のおかげよ。",
  ui_story_1015_10151102_9_dialog_content = "まさか大元帥さんが前に言ってた特別な絆？",
  ui_story_1015_10151102_10_dialog_content = "まずいわね。もしそのような能力があるなら、インゲルたちも――",
  ui_story_1015_10151102_11_dialog_content = "<color=#e8d9bb>ゴオォォン――！</color>",
  ui_story_1015_10151102_12_dialog_content = "ゴホッ…ゴホゴホッ！",
  ui_story_1015_10151102_13_dialog_content = "ここは…",
  ui_story_1015_10151102_14_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_1015_10151102_15_dialog_content = "またネズミが1匹増えたわね。",
  ui_story_1015_10151102_16_dialog_content = "アナトリア！どうしてここへ？",
  ui_story_1015_10151102_17_dialog_content = "バイスはどうしたの？",
  ui_story_1015_10151102_18_dialog_content = "申し訳ありません…気取られました。\nバイス中尉の居場所を突き止められず、救出はできませんでした…",
  ui_story_1015_10151102_19_dialog_content = "あなたたちにあるのは自尊心と無能だけのようね。",
  ui_story_1015_10151102_20_dialog_content = "私のやりたかったことはもうすぐ終わるわ。\nあなたたちはもう必要ない。",
  ui_story_1015_10151102_21_dialog_content = "…",
  ui_story_1015_10151102_22_dialog_content = "大変だ！",
  ui_story_1015_10151102_23_dialog_content = "取り囲まれたわ…",
  ui_story_1015_10151102_24_dialog_content = "なんとか持ちこたえてください、PlayerNameさん、カレンさん。",
  ui_story_1015_10151102_25_dialog_content = "インゲル中佐がいることをお忘れなく。",
  ui_story_1015_10151102_26_dialog_content = "さあ、片付けてしまいなさい――",
  ui_story_1015_10151102_27_dialog_content = "<color=#e8d9bb>ザザザ――</color>",
  ui_story_1015_10151102_28_dialog_content = "ノラ、聞こえますね？",
  ui_story_1015_10151102_29_dialog_content = "あら、ちょうど考えてたところよ。\nもう1匹のネズミはどうしたのかしらって。",
  ui_story_1015_10151102_30_dialog_content = "ずいぶん遠くへ逃げたようね。",
  ui_story_1015_10151102_31_dialog_content = "何をするつもりか知りませんが、即刻中止しなさい。",
  ui_story_1015_10151102_32_dialog_content = "でないと、後悔しますよ。",
  ui_story_1015_10151102_33_dialog_content = "…",
  ui_story_1015_10151102_34_dialog_content = "あなた…何をしたの？",
  ui_story_1015_10151102_35_dialog_content = "お2人が時間を稼いてくれたおかげで、ハーモナイザーの実験室の周りに\n<color=#FFB400>爆薬</color>を置くことができました。",
  ui_story_1015_10151102_36_dialog_content = "今私の銃口は火薬樽に向いています。\n引き金を引けば、ハーモナイザーも資料も火の海に沈むでしょう。",
  ui_story_1015_10151102_37_dialog_content = "！？",
  ui_story_1015_10151102_38_dialog_content = "見覚えのある情景が目に浮かんだのではないですか？「ノラ」。",
  ui_story_1015_10151102_39_dialog_content = "今すぐ投降し、PlayerNameたちを解放しなさい。",
  ui_story_1015_10151102_40_dialog_content = "…",
  ui_story_1015_10151102_41_dialog_content = "<size=45>火…火が…！</size>",
  ui_story_1015_10151102_42_dialog_content = "<size=45>私の実験が！私の実験が！！</size>",
  ui_story_1015_10151102_43_dialog_content = "フフ…",
  ui_story_1015_10151102_44_dialog_content = "あの古だぬきども、研究の才能はないくせに、\n犬を飼い慣らすのはお得意なのね。",
  ui_story_1015_10151102_45_dialog_content = "何ですって！？",
  ui_story_1015_10151102_46_dialog_content = "あなたに引き金は引けやしないわ。",
  ui_story_1015_10151102_47_dialog_content = "ハーモナイザーは太古の空の末裔の技術の結晶よ。\nその辺で簡単に拾えるものとは違うわ。",
  ui_story_1015_10151102_48_dialog_content = "啓光連邦全土でも、たった1台しかない。",
  ui_story_1015_10151102_49_dialog_content = "中に保存されているデータの価値は言うまでもないわ。\n啓明の星計画もおそらくそのほんの一部でしかない。",
  ui_story_1015_10151102_50_dialog_content = "あいつらの犬であるあなたが\nそれを知らないはずはないでしょう？",
  ui_story_1015_10151102_51_dialog_content = "あの古だぬきどもからしたら、\nあなたなんてハーモナイザーやデータと天秤にかける価値もないわ。",
  ui_story_1015_10151102_52_dialog_content = "そうでしょうか？",
  ui_story_1015_10151102_53_dialog_content = "では、試してみるとしましょう。",
  ui_story_1015_10151102_54_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_1015_10151201_1_dialog_content = "<color=#e8d9bb>ドーン！！！</color>",
  ui_story_1015_10151201_2_dialog_content = "火が…",
  ui_story_1015_10151201_3_dialog_content = "火が点いた…",
  ui_story_1015_10151201_4_dialog_content = "ヘリオス、実験室まで一緒に来て！",
  ui_story_1015_10151201_5_dialog_content = "<anim type=Shake><size=45>グオオ――</size></anim>",
  ui_story_1015_10151201_6_dialog_content = "チャンスです！",
  ui_story_1015_10151201_7_dialog_content = "散れ！氷花よ！",
  ui_story_1015_10151201_8_dialog_content = "気を付けて！暗鬼がまた僕たちを取り囲もうとしてる！",
  ui_story_1015_10151201_9_dialog_content = "<anim type=Shake><size=45>グオオ！！！</size></anim>",
  ui_story_1015_10151201_10_dialog_content = "<color=#e8d9bb>バン！バンバンッ――！</color>",
  ui_story_1015_10151201_11_dialog_content = "<anim type=Shake>グガア…</anim>",
  ui_story_1015_10151201_12_dialog_content = "今です！PlayerNameを救い出すのです！",
  ui_story_1015_10151201_13_dialog_content = "承知しました！",
  ui_story_1015_10151201_14_dialog_content = "PlayerNameさん、縄をほどいて差し上げます！",
  ui_story_1015_10151201_15_dialog_content = "ありがとう…",
  ui_story_1015_10151201_16_dialog_content = "バイスは無事なの？今どこにいるの？",
  ui_story_1015_10151201_17_dialog_content = "申し訳ありません。敵に見つかってしまい、\nバイス中尉を見つけ出せず…",
  ui_story_1015_10151201_18_dialog_content = "ですが、あちらに敵はいません。\n少なくとも安全は保証されています。",
  ui_story_1015_10151201_19_dialog_content = "安心してください。バイスは別の者が救出に向かっています。",
  ui_story_1015_10151201_20_dialog_content = "今やるべきことは、ノラの実験を阻止することです。",
  ui_story_1015_10151201_21_dialog_content = "やはりハーモナイザーを壊してはいなかったのね。",
  ui_story_1015_10151201_22_dialog_content = "え？壊してないの！？",
  ui_story_1015_10151201_23_dialog_content = "そう簡単に壊すわけありません。",
  ui_story_1015_10151201_24_dialog_content = "本当に壊していたら、インゲル中佐は何百回軍事裁判にかけられても足りないほどですよ。",
  ui_story_1015_10151201_25_dialog_content = "さあ、その話はこれくらいにして――",
  ui_story_1015_10151201_26_dialog_content = "この暗鬼たちを片付けてしまいましょう。\nノラを阻止しますよ！",
  ui_story_1015_10151201_27_dialog_content = "望むところだよ！",
  ui_story_1015_10151202_1_dialog_content = "<color=#e8d9bb>何年も前、X号シェルター</color>",
  ui_story_1015_10151202_2_dialog_content = "実験…私の実験が！",
  ui_story_1015_10151202_3_dialog_content = "データも実験試料もまだ全部中にあるのに！\n何とか持ち出さなきゃ！",
  ui_story_1015_10151202_4_dialog_content = "<anim type=Shake><size=45>ギャオ――！ギャオ――！</size></anim>",
  ui_story_1015_10151202_5_dialog_content = "ジェイド、コートの中に隠れてなさい。\n戻らなきゃいけないわ！",
  ui_story_1015_10151202_6_dialog_content = "<anim type=Shake><size=45>ギャオ！</size></anim>",
  ui_story_1015_10151202_7_dialog_content = "実験データを取り出さなきゃ…",
  ui_story_1015_10151202_8_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_1015_10151202_9_dialog_content = "うっ！！",
  ui_story_1015_10151202_10_dialog_content = "何てことなの。こんな大きな火災になるなんて…",
  ui_story_1015_10151202_11_dialog_content = "このシェルターにある消防設備だけじゃ、\nこの激しい火を消せやしないわ。",
  ui_story_1015_10151202_12_dialog_content = "まさか、あいつに応援を頼まなきゃいけないの…",
  ui_story_1015_10151202_13_dialog_content = "<color=#e8d9bb>ウオーン――ウオーン――</color>",
  ui_story_1015_10151202_14_dialog_content = "あの大火事で、ほぼすべての研究成果が失われた。",
  ui_story_1015_10151202_15_dialog_content = "二度と同じことを繰り返さないわ！",
  ui_story_1015_10151202_16_dialog_content = "これは…",
  ui_story_1015_10151202_17_dialog_content = "（ハーモナイザーの実験室には、火花一つ舞っていない…）",
  ui_story_1015_10151202_18_dialog_content = "（このスプリンクラー…まさか私がいなくなった後、\nあの古だぬきたちが設置したのかしら？）",
  ui_story_1015_10151202_19_dialog_content = "どうやら、あの大火事は私だけじゃなく、\n古だぬきたちの警戒心も高めたようね。",
  ui_story_1015_10151202_20_dialog_content = "ただ…",
  ui_story_1015_10151202_21_dialog_content = "<color=#e8d9bb>ザザザ――</color>",
  ui_story_1015_10151202_22_dialog_content = "抵抗はよしなさい、ノラ。",
  ui_story_1015_10151202_23_dialog_content = "人質の安全は私たちが確保しました。\nあなたにはもう切り札はありません。",
  ui_story_1015_10151202_24_dialog_content = "フッ、下手な小芝居で私を人質から引き離すことが、\nあなたの計画だったってわけね？",
  ui_story_1015_10151202_25_dialog_content = "その通りです。ただ…小芝居ではありません。",
  ui_story_1015_10151202_26_dialog_content = "ニセモノであなたをだますことはできません。\n実験室の周囲に配置した火薬樽は本物です。",
  ui_story_1015_10151202_27_dialog_content = "ただ、あの大火災の後大元帥が\nこのシェルターのすべての防火設備を強化したことは知らなかったようですね。",
  ui_story_1015_10151202_28_dialog_content = "通常の2倍の数の消火器とスプリンクラーを設置しただけでなく、\n防爆不燃材料で壁を補強しました。",
  ui_story_1015_10151202_29_dialog_content = "そう、あいつがね。",
  ui_story_1015_10151202_30_dialog_content = "色々手を尽くしたようだけど、ムダだったようね。\nかえってアダになったみたいじゃない。",
  ui_story_1015_10151202_31_dialog_content = "…",
  ui_story_1015_10151202_32_dialog_content = "なぜ何も言わないのですか？",
  ui_story_1015_10151202_33_dialog_content = "当時の火事をまだ恨んでいるのですか？",
  ui_story_1015_10151202_34_dialog_content = "あの時の真相を知りたいと、思ったことはありませんか？",
  ui_story_1015_10151202_35_dialog_content = "どういうことかしら？",
  ui_story_1015_10151202_36_dialog_content = "当時あなたが救援信号を出した後、\nレインハト大元帥はすぐにX号シェルターに救援を送りました。",
  ui_story_1015_10151202_37_dialog_content = "しかし、火の勢いが激しく、救援部隊が到着した時には、\nシェルターはすでに濃い煙に覆われていました。",
  ui_story_1015_10151202_38_dialog_content = "それにも関わらず、大元帥は先頭を切って火の海に飛び込み、\n過酷な環境の中を何時間もあなたを探し回ったのです。",
  ui_story_1015_10151202_39_dialog_content = "当時救援部隊にいた人の話では、火の海から出て来た大元帥は、\n全身煙にいぶられ、火に焼かれ、服はボロボロだったそうです。",
  ui_story_1015_10151202_40_dialog_content = "そんな状態でありながら、大元帥は痛みなどそっちのけで、\n大切な妹を見つけられなかったとただただ悔いていたそうです。",
  ui_story_1015_10151202_41_dialog_content = "…",
  ui_story_1015_10151202_42_dialog_content = "これで、分かったでしょう？",
  ui_story_1015_10151202_43_dialog_content = "レインハト大元帥はあなたを見捨ててなどいなかった、\n誰もあなたを見捨ててはいなかったのです。",
  ui_story_1015_10151202_44_dialog_content = "あなたが勝手に自分は見捨てられたと思い込み、\n罪深い暗鬼の組織に身を投じたのです。",
  ui_story_1015_10151202_45_dialog_content = "あなたがやってきたことはすべて、\nかつてあなたを「見捨てた」人たちに対する復しゅうでしょう？",
  ui_story_1015_10151202_46_dialog_content = "ですが、これで分かったはずです。\nあなた自身が啓光を離れなければ、誰もあなたを見捨てなどしなかったのです。",
  ui_story_1015_10151202_47_dialog_content = "あなたの復しゅうは、最初から間違いだったのです！",
  ui_story_1015_10151202_48_dialog_content = "大人しく投降してください。啓光と敵対する理由はもうないはずです。\n逃げ道もありませんよ。",
  ui_story_1015_10151202_49_dialog_content = "フフ…",
  ui_story_1015_10151202_50_dialog_content = "古だぬきどもの悪趣味は何年経っても変わらないわね。",
  ui_story_1015_10151202_51_dialog_content = "今だに程よく愚かな犬が大好きみたいね。",
  ui_story_1015_10151202_52_dialog_content = "…",
  ui_story_1015_10151202_53_dialog_content = "私が啓光を去ったのは、\n裏切りなんてくだらない理由だと本気で思っていたの？",
  ui_story_1015_10151202_54_dialog_content = "根本から間違っているわ。",
  ui_story_1015_10151202_55_dialog_content = "では、なぜ啓光に背いたのですか？",
  ui_story_1015_10151202_56_dialog_content = "簡単な理由よ。",
  ui_story_1015_10151202_57_dialog_content = "私がさらに研究を深めるのに十分な環境を\n啓光連邦は与えられなくなっていたからよ。",
  ui_story_1015_10151202_58_dialog_content = "研究対象にしろ、研究に使う資材にしろ、\n啓光では新しい画期的な研究成果は望めなかったわ。",
  ui_story_1015_10151202_59_dialog_content = "だから啓光を去ったのよ。\n一方日蝕には私の研究に大きな突破口を開くであろう技術があった。",
  ui_story_1015_10151202_60_dialog_content = "それだけのこと。",
  ui_story_1015_10151202_61_dialog_content = "<color=#e8d9bb>その頃、シェルターの別の場所では</color>",
  ui_story_1015_10151202_62_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_1015_10151202_63_dialog_content = "時間どおりです。",
  ui_story_1015_10151202_64_dialog_content = "彼女の計画はいつでも実に精確ですね。",
  ui_story_1015_10151202_65_dialog_content = "<color=#e8d9bb>ザザザ――</color>",
  ui_story_1015_10151202_66_dialog_content = "時間です。「<color=#FFB400>リベロ</color>」登場といきましょうか。",
  ui_story_1015_10151301_1_dialog_content = "<color=#e8d9bb>ウオーン――ウオーン――</color>",
  ui_story_1015_10151301_2_dialog_content = "うるさいわね。",
  ui_story_1015_10151301_3_dialog_content = "え？",
  ui_story_1015_10151301_4_dialog_content = "他のネズミたちより少しは強いかと思ってたけど――",
  ui_story_1015_10151301_5_dialog_content = "期待外れだったみたいね。",
  ui_story_1015_10151301_6_dialog_content = "電気を落とすわ。",
  ui_story_1015_10151301_7_dialog_content = "大変です！ブレーカーを落とさせてはいけません！",
  ui_story_1015_10151301_8_dialog_content = "<anim type=Shake><size=45>グガアア！</size></anim>",
  ui_story_1015_10151301_9_dialog_content = "<color=#e8d9bb>ゴオォォン――！</color>",
  ui_story_1015_10151301_10_dialog_content = "まずいことになりましたね…\nこのシェルターのドアロックシステムは電気系統と直結してるのです。",
  ui_story_1015_10151301_11_dialog_content = "電気が落ちれば、ドアも開きません。",
  ui_story_1015_10151301_12_dialog_content = "あのドアの向こうは出口ですか？",
  ui_story_1015_10151301_13_dialog_content = "いいえ…出口よりも厄介なものです。",
  ui_story_1015_10151301_14_dialog_content = "どういう意味ですか？",
  ui_story_1015_10151301_15_dialog_content = "<color=#e8d9bb>ザザッ――</color>",
  ui_story_1015_10151301_16_dialog_content = "私が教えてあげるわ。",
  ui_story_1015_10151301_17_dialog_content = "中にあるのはハーモナイザーよ。",
  ui_story_1015_10151301_19_dialog_content = "何をするつもりか知りませんが、すぐに中止しなさい！",
  ui_story_1015_10151301_20_dialog_content = "その装置は完全ではないのです。\nむやみに動かすのは大変危険です！",
  ui_story_1015_10151301_21_dialog_content = "あら、あなたの情報収集能力はなかなかね。",
  ui_story_1015_10151301_22_dialog_content = "でも、忘れちゃダメよ、ネズミさん。",
  ui_story_1015_10151301_23_dialog_content = "あなたは研究者じゃない。\n装置に関する知識も全部あの男から聞いたことでしょ。",
  ui_story_1015_10151301_24_dialog_content = "この機械が危険だと思うのも――",
  ui_story_1015_10151301_25_dialog_content = "ただ使い方を知らないからよ。",
  ui_story_1015_10151301_26_dialog_content = "<color=#e8d9bb>ガシャ――</color>",
  ui_story_1015_10151301_27_dialog_content = "実験の邪魔になる要素は排除したわ。\n続けましょう。",
  ui_story_1015_10151301_28_dialog_content = "実験台、いらっしゃい。",
  ui_story_1015_10151301_29_dialog_content = "…",
  ui_story_1015_10151301_30_dialog_content = "<color=#e8d9bb>その頃、カナン城では</color>",
  ui_story_1015_10151301_31_dialog_content = "<color=#e8d9bb>ザザ…</color>",
  ui_story_1015_10151301_32_dialog_content = "ラス軍団長、緊急任務が入りました。\n至急応答してください！",
  ui_story_1015_10151301_33_dialog_content = "緊急任務？こんな時間に何の緊急任務があるっていうのよ！？",
  ui_story_1015_10151301_34_dialog_content = "妙だな。ともかく聞いてみるとしよう。",
  ui_story_1015_10151301_35_dialog_content = "こちらはラス。話してちょうだい。",
  ui_story_1015_10151301_36_dialog_content = "X号シェルターにノラが侵入したようです。\n委員会より即応援に向かい、ノラとヘリオスを捕らえよとの命令が下されました。",
  ui_story_1015_10151301_37_dialog_content = "<size=45>何だと！？</size>",
  ui_story_1015_10151301_38_dialog_content = "今、ノラと言ったの？まさか啓光の領地まで乗り込んでくるなんて…",
  ui_story_1015_10151301_39_dialog_content = "…",
  ui_story_1015_10151301_40_dialog_content = "ラス、そうとなれば、私も行くとしよう。",
  ui_story_1015_10151301_41_dialog_content = "そう言うと思ってたわ。",
  ui_story_1015_10151301_42_dialog_content = "でも、約束してちょうだい。下手なマネは絶対にしないで。",
  ui_story_1015_10151301_43_dialog_content = "もちろん、約束しよう。\nお前に命じられた任務だ。干渉は控える。",
  ui_story_1015_10151301_44_dialog_content = "それならいいわ。一緒に来てちょうだい。",
  ui_story_1015_10151302_1_dialog_content = "<color=#e8d9bb>トントントン</color>",
  ui_story_1015_10151302_2_dialog_content = "入りなさい。",
  ui_story_1015_10151302_3_dialog_content = "はぁ、はぁ…報告いたします！",
  ui_story_1015_10151302_4_dialog_content = "長官、計画通りラスがこちらへ向かっています。\n1時間後には到着する見込みです。",
  ui_story_1015_10151302_5_dialog_content = "ただ、計画外の事態が起こりました。\nレインハト大元帥も同行しています。",
  ui_story_1015_10151302_6_dialog_content = "ほう？",
  ui_story_1015_10151302_7_dialog_content = "構いません。想定内です。",
  ui_story_1015_10151302_8_dialog_content = "これも長官の計画ですか？",
  ui_story_1015_10151302_9_dialog_content = "ハハ、こればかりは私の計画ではありませんよ。",
  ui_story_1015_10151302_10_dialog_content = "しかし、ハーモナイザーの実験室から黒煙が上がっています…",
  ui_story_1015_10151302_11_dialog_content = "火のことは気にしなくて結構です。\n監視カメラで確認済みですから。焼けはしません。",
  ui_story_1015_10151302_12_dialog_content = "それよりも、座って何か飲みなさい。\nこの後のことは観客として眺めていればいいのですから。",
  ui_story_1015_10151302_13_dialog_content = "はい。",
  ui_story_1015_10151302_14_dialog_content = "どうりでババ抜きで勝てないわけですね。",
  ui_story_1015_10151302_15_dialog_content = "人の心を読み切っています。",
  ui_story_1015_10151302_16_dialog_content = "デニール、いや、ノラ…実にうらやましいかぎりです。",
  ui_story_1015_10151302_17_dialog_content = "…？",
  ui_story_1015_10151302_18_dialog_content = "君もうらやましいでしょう？",
  ui_story_1015_10151302_19_dialog_content = "長官、私は…",
  ui_story_1015_10151302_20_dialog_content = "それもそうですね。君は研究者ではない。\nうらやましくなくても当然です。",
  ui_story_1015_10151302_21_dialog_content = "…",
  ui_story_1015_10151302_22_dialog_content = "ノラのどこがうらやむに値するのか、考えているのでしょう？",
  ui_story_1015_10151302_23_dialog_content = "はい。",
  ui_story_1015_10151302_24_dialog_content = "ノラは研究者に最も適した優れた性質を持っています。",
  ui_story_1015_10151302_25_dialog_content = "執着ですか？",
  ui_story_1015_10151302_26_dialog_content = "いいえ、冷酷さです。",
  ui_story_1015_10151302_27_dialog_content = "啓光では昔からこう言われています――",
  ui_story_1015_10151302_28_dialog_content = "「科学技術に善悪の別はない。\nあるのは、それを用いる光霊の善悪だけだ」",
  ui_story_1015_10151302_29_dialog_content = "ただ多くの場合、新しい技術を開発するには、\nまず「悪人」にならなければ成し遂げられません。",
  ui_story_1015_10151302_30_dialog_content = "この世界に何もかもうまくいく方法などありません。\nノラはそのことをよく知っている。そして彼女もよく知っています。",
  ui_story_1015_10151302_31_dialog_content = "すばらしい研究成果を得るためなら、\nかつての戦友を実験台にすることもためらわない。",
  ui_story_1015_10151302_32_dialog_content = "それが最たる証明です。",
  ui_story_1015_10151302_33_dialog_content = "しかし、それは追い込まれたからこその選択ではないのですか？",
  ui_story_1015_10151302_34_dialog_content = "いいえ、彼女を追い込んだことは一度もありませんよ。",
  ui_story_1015_10151302_35_dialog_content = "私たちはただ少々縛りのある、\nしかし実に素晴らしい機会を与えてやっただけです。",
  ui_story_1015_10151302_36_dialog_content = "その機会をつかんだのは完全に彼女自身の選択ですよ。",
  ui_story_1015_10151302_37_dialog_content = "ノラは一度たりともこの実験の本質から外れたことがない――\n科学で生物の極限の可能性を探り続けているのです。",
  ui_story_1015_10151302_38_dialog_content = "最初の「人造陽光」計画の時からそうでした。",
  ui_story_1015_10151302_39_dialog_content = "君も知っているでしょう？\n人造陽光とは「啓明の星」計画の前身となったもの。",
  ui_story_1015_10151302_40_dialog_content = "その成果として得られたのが啓光単独で開発した光霊強化技術。\nしかし、まだ未熟だったため、不安定な成果物しか生み出せませんでした。",
  ui_story_1015_10151302_41_dialog_content = "単一の強大な力が光霊の体内で何の制限もなく動き回るのです。\n強い意志の力で抑え込み、制御しなければなりません。",
  ui_story_1015_10151302_42_dialog_content = "したがって、この技術の成功率は極めて低かった。\n実験台も力の制御を失いやすい。",
  ui_story_1015_10151302_43_dialog_content = "力の制御を失えば、被験体は命を落とすか、一生障害が残るか、あるいは…\n「あの怪物」になるしかない。",
  ui_story_1015_10151302_44_dialog_content = "しかし、かつてのデニール、つまりノラは、\nいずれの状況にも陥っていません…",
  ui_story_1015_10151302_45_dialog_content = "失敗だった、ということですか？",
  ui_story_1015_10151302_46_dialog_content = "厳密には、そうではありません。",
  ui_story_1015_10151302_47_dialog_content = "ノラの強化は成功しました。\nただ、その方向性が我々の想定と違っていただけです。",
  ui_story_1015_10151302_48_dialog_content = "我々が得ようとしたのは力の強化された個体でした。\nですが、ノラの中で強化されたのは知力だったのですよ。",
  ui_story_1015_10151302_49_dialog_content = "実験の成功により、ノラは最も才能のある研究員となり、\n同時に啓光最大の危険要素となったわけです。",
  ui_story_1015_10151302_50_dialog_content = "その結果は君も見た通りですよ。\nノラは何の迷いもなく啓光に背き、対立者となりました。",
  ui_story_1015_10151302_51_dialog_content = "つまり、啓光にとってレインハトこそ、\n「人造陽光」計画で最も成功した実験台なのです。",
  ui_story_1015_10151302_52_dialog_content = "ただ1つだけいまだによく分からないことがあります。",
  ui_story_1015_10151302_53_dialog_content = "いったい何をもって「人造陽光」計画の改造成功とするのですか？",
  ui_story_1015_10151302_54_dialog_content = "失敗と判断される特徴のすべてが\n改造後すぐに現れるわけではないと思いますが。",
  ui_story_1015_10151302_55_dialog_content = "80号シェルターで起こった戦いを覚えていますか？",
  ui_story_1015_10151302_56_dialog_content = "はい、覚えています。",
  ui_story_1015_10151302_57_dialog_content = "当時この私が委員会の命に基づき、\n「人造陽光」計画改造個体部隊に伝える資料を書き換えたのですから。",
  ui_story_1015_10151302_58_dialog_content = "虚偽の情報を伝え、部隊が暗鬼の包囲に陥るよう仕向けました。",
  ui_story_1015_10151302_59_dialog_content = "正確な情報を収集するため送り込んだ多くの偵察部隊も\n犠牲になりました。",
  ui_story_1015_10151302_60_dialog_content = "私の部下が所属していた部隊もそのうちの1つでした。\n彼は部隊唯一の生還者です。",
  ui_story_1015_10151302_61_dialog_content = "ああ、そうでした。そのような者がいましたね。\n何という名でしたか？",
  ui_story_1015_10151302_62_dialog_content = "<color=#FFB400>アナトリア</color>です。",
  ui_story_1015_10151302_63_dialog_content = "確かそんな名前でしたね。\n少し前にレインハト君の副官になったと聞きましたが？",
  ui_story_1015_10151302_64_dialog_content = "彼はこのことを知っているのですか？\n何よりもレインハト君を監視させて大丈夫なのでしょうね？",
  ui_story_1015_10151302_65_dialog_content = "情報収集能力で言うならば、十分信頼に値します。",
  ui_story_1015_10151302_66_dialog_content = "また、この任務はそもそも彼の忠誠度を測るための試験です。",
  ui_story_1015_10151302_67_dialog_content = "フッ、君がそう言うのなら、好きにするといいでしょう。",
  ui_story_1015_10151302_68_dialog_content = "少々話がそれましたね。80号シェルターの件に戻りましょう。",
  ui_story_1015_10151302_69_dialog_content = "あの戦いは改造個体に対する「スクリーニング」でした。",
  ui_story_1015_10151302_70_dialog_content = "あえて彼らを絶体絶命ともいえる状況に陥れ、\n光力を極限まで使わせる。そうすれば…",
  ui_story_1015_10151302_71_dialog_content = "弱い個体はそのまま消滅します。",
  ui_story_1015_10151302_72_dialog_content = "精神に欠陥のある者、不安定な者はそうした極限状態では、\n制御を失い、最終的に排除されます。",
  ui_story_1015_10151302_73_dialog_content = "ですが、成功した個体は窮地を乗り越え、生き残ります。",
  ui_story_1015_10151302_74_dialog_content = "しかし…あの計画は成功率があまりにも低いために、\n結局中止となったのではありませんか？",
  ui_story_1015_10151302_75_dialog_content = "啓光があの不完全な「ハーモナイザー」を手に入れるまでは。",
  ui_story_1015_10151302_76_dialog_content = "その通りです。「人造陽光」計画は本来なら再開されるべきではありませんでした。",
  ui_story_1015_10151302_77_dialog_content = "ですが、「ハーモナイザー」が転機をもたらしました。",
  ui_story_1015_10151302_78_dialog_content = "「ハーモナイザー」は空の末裔の科学技術の最高峰と言えます。\n「人造陽光」計画とは違った、まったく新しい力を持っています。",
  ui_story_1015_10151302_79_dialog_content = "その2つを融合させた結果、\n「啓光の星」計画の実験台たちが誕生したというわけです。",
  ui_story_1015_10151302_80_dialog_content = "「啓光の星」計画の改造を受けた光霊の体内には、\n異なる技術がもたらした2つの力が同時に存在している。",
  ui_story_1015_10151302_81_dialog_content = "その力は互いに均衡を保つ。\nこうして強化の成功率が一定程度向上したのです。",
  ui_story_1015_10151302_82_dialog_content = "しかし、その均衡も決して安定したものではありません。\nそのため「啓光の星」計画で改造された光霊の多くは非常に体が弱い。",
  ui_story_1015_10151302_83_dialog_content = "強大な力を過度に使えば、\n微妙に保たれていた力の均衡が崩れかねません。",
  ui_story_1015_10151302_84_dialog_content = "そして彼らの肉体も、均衡が崩れると共に瓦解してしまうのですよ。",
  ui_story_1015_10151302_85_dialog_content = "アクセリアがそのいい例です。",
  ui_story_1015_10151302_86_dialog_content = "しかし、今回は違います。ノラが新しい力をもたらしました。\n彼女の研究が実験をさらなる高みに導くでしょう。",
  ui_story_1015_10151302_87_dialog_content = "新しい力とは…「<color=#FFB400>シード</color>」ですか？",
  ui_story_1015_10151302_88_dialog_content = "そうです。",
  ui_story_1015_10151302_89_dialog_content = "ノラは長年にわたり「シード」を研究してきました。\n「シード」は暗鬼側の技術の集大成として、かなり前にすでに確立していたものです。",
  ui_story_1015_10151302_90_dialog_content = "「シード」はパズルの最後のピース…\nそして、そのピースをはめられるのはノラだけなのですよ。",
  ui_story_1015_10151302_91_dialog_content = "3つの力が光霊の体内で互いに牽制し合って均衡を保ち、\n安定した新しい力となるでしょう。",
  ui_story_1015_10151302_92_dialog_content = "…！",
  ui_story_1015_10151302_93_dialog_content = "世界初のきわめて重要な実験結果が今まさに出ようとしています。\n期待して待つとしようではありませんか。",
  ui_story_1015_10151302_94_dialog_content = "<color=#e8d9bb>その頃、啓光連邦ハーモナイザー実験室では</color>",
  ui_story_1015_10151302_95_dialog_content = "<color=#e8d9bb>ドン――ドンッ！</color>",
  ui_story_1015_10151302_96_dialog_content = "耳障りね…",
  ui_story_1015_10151302_97_dialog_content = "実験環境はギリギリ合格ってところかしら。\nまあ、それで十分だけど。",
  ui_story_1015_10151302_98_dialog_content = "最後のパラメーターチェックよ。",
  ui_story_1015_10151302_99_dialog_content = "いずれも間違いないわ。",
  ui_story_1015_10151302_100_dialog_content = "最後は実験材料を入れるだけね。",
  ui_story_1015_10151302_101_dialog_content = "実験、開始。",
  ui_story_1015_10151302_102_dialog_content = "「シード」が生命の進化を導いてくれるわ。",
  ui_story_1015_10151302_103_dialog_content = "<color=#e8d9bb>ハーモナイザー実験室の外では</color>",
  ui_story_1015_10151302_104_dialog_content = "散れ！氷花よ！",
  ui_story_1015_10151302_105_dialog_content = "<color=#e8d9bb>ドン――！</color>",
  ui_story_1015_10151302_106_dialog_content = "爆発といく度もの攻撃を受けたというのに、\nこのドアには穴一つ開いていないわ。",
  ui_story_1015_10151302_107_dialog_content = "強行突破は無理のようね。",
  ui_story_1015_10151302_108_dialog_content = "建設時、最も強固な防爆材料を使いましたから。",
  ui_story_1015_10151302_109_dialog_content = "防火用に設置したものが今私たちの障害になるとは皮肉ですね。",
  ui_story_1015_10151302_110_dialog_content = "中にあるハーモナイザーは、おそらくノラの実験に欠かせないものなのでしょう？",
  ui_story_1015_10151302_111_dialog_content = "このまま好き勝手にさせていては、大変なことになります。",
  ui_story_1015_10151302_112_dialog_content = "そうだよ。絶対に止めなきゃ！",
  ui_story_1015_10151302_113_dialog_content = "他に方法はないのかな？",
  ui_story_1015_10151302_114_dialog_content = "そうですね…",
  ui_story_1015_10151302_115_dialog_content = "1つ方法があります。",
  ui_story_1015_10151302_116_dialog_content = "どんな方法？",
  ui_story_1015_10151302_117_dialog_content = "このシェルターはかつてノラの秘密の実験室で、\n毎日失敗した実験台が大量に捨てられていました。",
  ui_story_1015_10151302_118_dialog_content = "時間短縮のため、ノラは実験室から底部の廃棄物処理室に\n直接つながる通路を造りました。",
  ui_story_1015_10151302_119_dialog_content = "シェルターを再建した時、その通路の入口は壁で閉じましたが、\n通路自体は残っています。",
  ui_story_1015_10151302_120_dialog_content = "少々回り道にはなりますが、通路をふさいだ壁の方が\nこのドアよりも破壊しやすいと思います。",
  ui_story_1015_10151302_121_dialog_content = "彼女自身が廃棄物処理のために造った「高速通路」で、\nサプライズを届けてあげましょう。",
  ui_story_1015_10151401_1_dialog_content = "ここです！ここはもろくなっています！",
  ui_story_1015_10151401_2_dialog_content = "<color=#e8d9bb>バン！バン――！！</color>",
  ui_story_1015_10151401_3_dialog_content = "<color=#e8d9bb>ドーン――！！！</color>",
  ui_story_1015_10151401_4_dialog_content = "通路が現れた！",
  ui_story_1015_10151401_5_dialog_content = "ノラ、実験を止めなさい！",
  ui_story_1015_10151401_6_dialog_content = "手下の暗鬼はすべて倒しました！",
  ui_story_1015_10151401_7_dialog_content = "遅かったわね。",
  ui_story_1015_10151401_8_dialog_content = "実験は、成功したわ。",
  ui_story_1015_10151401_9_dialog_content = "<color=#e8d9bb>ビューン――</color>",
  ui_story_1015_10151401_10_dialog_content = "PlayerName、ハーモナイザーを見て！",
  ui_story_1015_10151401_11_dialog_content = "中から何か出てくるわ！",
  ui_story_1015_10151401_12_dialog_content = "こ…これは…！？",
  ui_story_1015_10151401_13_dialog_content = "な、何なの！？この怪物は！！",
  ui_story_1015_10151401_14_dialog_content = "実験台ヘリオスの112回目の実験記録――",
  ui_story_1015_10151401_15_dialog_content = "実験手順は…「ハーモナイザー」を使用し、\n「人造陽光」計画の被験者に強化を施すと同時に――",
  ui_story_1015_10151401_16_dialog_content = "「ハーモナイザー」に「シード」を投入した。",
  ui_story_1015_10151401_17_dialog_content = "結果、実験は初期的な成功をおさめ、\n被験者の活動停止リスクが大幅に低下した。",
  ui_story_1015_10151401_18_dialog_content = "ノラは…実験記録を書いてるの？",
  ui_story_1015_10151401_19_dialog_content = "かつての戦友をこんな姿にしておきながら、\n平然と実験記録を書いていられるとは…",
  ui_story_1015_10151401_20_dialog_content = "ユリシーズ教授のおっしゃった通り、\nあなたは正真正銘の冷血動物です。",
  ui_story_1015_10151401_21_dialog_content = "ユリシーズ？",
  ui_story_1015_10151401_22_dialog_content = "あの老いぼれこそ今回の実験結果を心待ちにしてるんじゃない？",
  ui_story_1015_10151401_23_dialog_content = "どういう意味ですか！？",
  ui_story_1015_10151401_24_dialog_content = "次の実験に入るわ。",
  ui_story_1015_10151401_25_dialog_content = "実戦で実験台の安定性をチェックするの。",
  ui_story_1015_10151401_26_dialog_content = "さあ、あいつらを引きちぎってしまいなさい。",
  ui_story_1015_10151401_27_dialog_content = "！！！",
  ui_story_1015_10151401_28_dialog_content = "PlayerNameさん、どこかに隠れていてください！",
  ui_story_1015_10151401_29_dialog_content = "わ、分かった！",
  ui_story_1015_10151401_30_dialog_content = "…",
  ui_story_1015_10151401_31_dialog_content = "（…何の反応もありませんね？まさか、実験は失敗したのでしょうか？）",
  ui_story_1015_10151401_32_dialog_content = "なるほど、そういうこと…\nどうやら私の実験はさらなる成功を収めていたようよ。",
  ui_story_1015_10151401_33_dialog_content = "（さらなる成功？どういう意味でしょう？）",
  ui_story_1015_10151401_34_dialog_content = "今は呼び方を変えるべきね。",
  ui_story_1015_10151401_35_dialog_content = "啓光連邦の兵士、ヘリオス――",
  ui_story_1015_10151401_36_dialog_content = "…！",
  ui_story_1015_10151401_37_dialog_content = "反応したわ。まさか言葉が分かるの！？",
  ui_story_1015_10151401_38_dialog_content = "今目の前にいるのは、啓光連邦の反逆者と敵よ。",
  ui_story_1015_10151401_39_dialog_content = "あなたの任務はヤツらを消すこと。",
  ui_story_1015_10151401_40_dialog_content = "<anim type=Shake><size=50>グオオオ――！！！</size></anim>",
  ui_story_1015_10151401_41_dialog_content = "待ってください、止めてください！",
  ui_story_1015_10151401_42_dialog_content = "我々は敵ではありません！\nノラこそ啓光の反逆者であり、敵なのです！",
  ui_story_1015_10151401_43_dialog_content = "<anim type=Shake><size=50>グオオ！！！</size></anim>",
  ui_story_1015_10151401_44_dialog_content = "うっ！",
  ui_story_1015_10151401_45_dialog_content = "ムダです。完全に理性を取り戻したわけではないようです。",
  ui_story_1015_10151401_46_dialog_content = "まずは倒しましょう。",
  ui_story_1015_10151402_1_dialog_content = "<anim type=Shake><size=50>グオォォン！！！</size></anim>",
  ui_story_1015_10151402_2_dialog_content = "どうしてこんなに強く…？",
  ui_story_1015_10151402_3_dialog_content = "力だけでなく、行動も読めなくなりました。",
  ui_story_1015_10151402_4_dialog_content = "皆さん、気を付けてください！",
  ui_story_1015_10151402_5_dialog_content = "これまでは本能で反撃していたにすぎませんが、\n今や彼は戦術を用いるようになっています。",
  ui_story_1015_10151402_6_dialog_content = "怪物が策略を使っていると？",
  ui_story_1015_10151402_7_dialog_content = "それはますます厄介ですね…",
  ui_story_1015_10151402_8_dialog_content = "実験は成功したわ。私の立てた理論は正しかったのね。",
  ui_story_1015_10151402_9_dialog_content = "3つの異なる力が実験台の体内で相互に作用し、\n安定した状態を生み出した。",
  ui_story_1015_10151402_10_dialog_content = "激戦となっても、その均衡が崩れることはない。",
  ui_story_1015_10151402_11_dialog_content = "そして、最も重要なのは――\nこの実験は複製可能だということ。",
  ui_story_1015_10151402_12_dialog_content = "あとは最後の検証さえ済めば、\n今回の実験の成功を証明できるわ。",
  ui_story_1015_10151402_13_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_1015_10151402_14_dialog_content = "気を付けて！様子がおかしいわ！",
  ui_story_1015_10151402_15_dialog_content = "あれは光力？それとも暗力？\n2つの力が混じり合って、僕にも判断がつかないよ！",
  ui_story_1015_10151402_16_dialog_content = "今はそんなことを考えている余裕はありません。\n防御の構えをとってください！",
  ui_story_1015_10151402_17_dialog_content = "<anim type=Shake><size=50>グオオ――！</size></anim>",
  ui_story_1015_10151402_18_dialog_content = "こ…これは！？",
  ui_story_1015_10151402_19_dialog_content = "見た目が変わった！？",
  ui_story_1015_10151402_20_dialog_content = "この姿…80号シェルターで記憶の欠片を感知した時に見たことあるよ…",
  ui_story_1015_10151402_21_dialog_content = "ヘリオスの元の姿だよ！！",
  ui_story_1015_10151402_22_dialog_content = "ようやくここまで来たわ。",
  ui_story_1015_10151402_23_dialog_content = "これで最後の検証も済んだ。",
  ui_story_1015_10151402_24_dialog_content = "力が安定したことによって、より大きな強みが生まれたわ。\n力の制御が効くようになったのよ。",
  ui_story_1015_10151402_25_dialog_content = "理性を失い、怪物になるという「人造陽光」計画の副作用を\n抑制できるわ。",
  ui_story_1015_10151402_26_dialog_content = "自身で形態を変えることもできる。",
  ui_story_1015_10151402_27_dialog_content = "これこそ私の望んでいた結果よ。",
  ui_story_1015_10151402_28_dialog_content = "<anim type=Shake>うう…</anim>",
  ui_story_1015_10151402_29_dialog_content = "<anim type=Shake>ここ…は…</anim>",
  ui_story_1015_10151402_30_dialog_content = "こ、言葉を話した！？",
  ui_story_1015_10151402_31_dialog_content = "ち…違う…どうして…80号シェルターじゃないんだ？",
  ui_story_1015_10151402_32_dialog_content = "君たちは…誰だ？",
  ui_story_1015_10151402_33_dialog_content = "光霊の姿に戻ると、理性も戻るのでしょうか？",
  ui_story_1015_10151402_34_dialog_content = "私は委員会直属の情報官インゲルです。",
  ui_story_1015_10151402_35_dialog_content = "ヘリオス大尉、あなたには敵と通じ、\n暗鬼と結託した嫌疑がかかっています。",
  ui_story_1015_10151402_36_dialog_content = "今すぐ武器を捨てて抵抗を止め、\n委員会の調査にご協力願います！",
  ui_story_1015_10151402_37_dialog_content = "違う、俺はそんなこと…",
  ui_story_1015_10151402_38_dialog_content = "敵と…通じただって？",
  ui_story_1015_10151402_39_dialog_content = "俺は…俺は…",
  ui_story_1015_10151402_40_dialog_content = "ヘリオス大尉、落ち着いてください！",
  ui_story_1015_10151402_41_dialog_content = "周りをよくご覧ください。ここは80号シェルターではありません。",
  ui_story_1015_10151402_42_dialog_content = "もう戦う必要などないのです…",
  ui_story_1015_10151402_43_dialog_content = "いったい…何があったんだ？\n俺は…なぜここにいる？",
  ui_story_1015_10151402_44_dialog_content = "なぜ…何も思い出せないんだ…",
  ui_story_1015_10151402_45_dialog_content = "ううっ…！",
  ui_story_1015_10151402_46_dialog_content = "実験台の認知能力はしっかりしているわ。\nただ、記憶の欠如と錯乱があるようね。自己制御を失った後の記憶がないみたい。",
  ui_story_1015_10151402_47_dialog_content = "ひとまず注意すべき副作用として記録しておきましょう。\nこの副作用を完全に失くすには、まだまだ研究が必要だわ。",
  ui_story_1015_10151402_48_dialog_content = "もちろん、実験台自身の欠陥による副作用である可能性の方が大きいけど。",
  ui_story_1015_10151402_49_dialog_content = "とにかく、全体として実験は成功ね。",
  ui_story_1015_10151402_50_dialog_content = "ようやく「進化」の方法を手に入れたわ。",
  ui_story_1015_10151402_51_dialog_content = "問題はあと1つだけ…",
  ui_story_1015_10151402_52_dialog_content = "（この後の研究検証にはこの実験台が欠かせない）",
  ui_story_1015_10151402_53_dialog_content = "（何とかしてヘリオスを連れ帰らないと…）",
  ui_story_1015_10151402_54_dialog_content = "（ただ、意識や認知を徐々に回復してきてるのは、\n計画に余計な不確定要素をもたらすわ）",
  ui_story_1015_10151402_55_dialog_content = "（でも、こういう単純な頭の持ち主は扱いやすい）",
  ui_story_1015_10151402_56_dialog_content = "君のことは…知ってる…",
  ui_story_1015_10151402_57_dialog_content = "君は…デニールか？",
  ui_story_1015_10151402_58_dialog_content = "どうして、そんな姿に…",
  ui_story_1015_10151402_59_dialog_content = "レインハトは…どこだ…？",
  ui_story_1015_10151402_60_dialog_content = "レインハトはなぜ…君と…一緒じゃないんだ…？",
  ui_story_1015_10151402_61_dialog_content = "…",
  ui_story_1015_10151402_62_dialog_content = "デニールもあなたも、とうの昔に啓光に見捨てられたのよ。",
  ui_story_1015_10151402_63_dialog_content = "私はデニールじゃないわ。",
  ui_story_1015_10151402_64_dialog_content = "見捨て…られた…？",
  ui_story_1015_10151402_65_dialog_content = "<anim type=Shake>ううっ…！！</anim>",
  ui_story_1015_10151402_66_dialog_content = "ヘリオスの体に暗力が集まってる！",
  ui_story_1015_10151402_67_dialog_content = "まさかノラは言葉で彼を刺激し、\nもう一度錯乱状態にして怪物に戻そうとしているの！？",
  ui_story_1015_10151402_68_dialog_content = "皆もう力が残ってないのに…",
  ui_story_1015_10151402_69_dialog_content = "ほら、聞いた？あいつら、あなたのことを「怪物」と呼んだわ。",
  ui_story_1015_10151402_70_dialog_content = "<anim type=Shake>ち、違う…俺は…怪物じゃない…</anim>",
  ui_story_1015_10151402_71_dialog_content = "<anim type=Shake>俺は…啓光の…軍人だ…</anim>",
  ui_story_1015_10151402_72_dialog_content = "チッ…",
  ui_story_1015_10151402_73_dialog_content = "啓光連邦にあなたの居場所はないのよ。",
  ui_story_1015_10151402_74_dialog_content = "私と一緒に来れば、助かるチャンスがあるわ。",
  ui_story_1015_10151402_75_dialog_content = "ここに残っていれば、殺されるだけよ。",
  ui_story_1015_10151402_76_dialog_content = "彼女の言うことを信じてはいけません。\n啓光連邦は誰一人として見捨てたりしません！",
  ui_story_1015_10151402_77_dialog_content = "啓光連邦は役に立たなくなった者を見捨てるの。\n特に失敗作はね。",
  ui_story_1015_10151402_78_dialog_content = "レインハト大元帥も決して見捨てたりはしません。\n大元帥はあなたたちの行方をずっと探し続けていました。",
  ui_story_1015_10151402_79_dialog_content = "レインハトは援軍を連れてこなかったわ。",
  ui_story_1015_10151402_80_dialog_content = "仕方なかったんだ！\n当時の啓光の長官が麻酔薬で大元帥さんを動けなくしたんだよ！",
  ui_story_1015_10151402_81_dialog_content = "感知能力で見たんだ！ウソじゃない！",
  ui_story_1015_10151402_82_dialog_content = "忘れちゃいけないわ。\n80号シェルターでレインハトは私とあなたと対立していた。",
  ui_story_1015_10151402_83_dialog_content = "よく見てください！\nあなたのかつての戦友は今や光霊ではありません。",
  ui_story_1015_10151402_84_dialog_content = "彼女の両手は血で染まっているのです！",
  ui_story_1015_10151402_85_dialog_content = "偽善ね。こういうやつ、嫌いでしょう？",
  ui_story_1015_10151402_86_dialog_content = "<size=45>黙りなさい！</size>",
  ui_story_1015_10151402_87_dialog_content = "<color=#e8d9bb>バンッ――！</color>",
  ui_story_1015_10151402_88_dialog_content = "<anim type=Shake><size=50>うっ！！</size></anim>",
  ui_story_1015_10151402_89_dialog_content = "何ですって！？",
  ui_story_1015_10151402_90_dialog_content = "…何をしてるの？",
  ui_story_1015_10151402_91_dialog_content = "俺は…啓光の軍人だ…",
  ui_story_1015_10151402_92_dialog_content = "調査に…協力する…",
  ui_story_1015_10151402_93_dialog_content = "だが…戦友も…守る…",
  ui_story_1015_10151402_94_dialog_content = "…",
  ui_story_1015_10151402_95_dialog_content = "愚かね。",
  ui_story_1015_10151402_96_dialog_content = "どうやら、実験台の自他に対する認識に誤りがあるようね。",
  ui_story_1015_10151402_97_dialog_content = "これも精神錯乱の一つかもしれないわ。\n間違った認識は徹底的に取り除く必要がある。",
  ui_story_1015_10151402_98_dialog_content = "これは…",
  ui_story_1015_10151402_99_dialog_content = "<color=#e8d9bb>ドオオオン――！</color>",
  ui_story_1015_10151402_100_dialog_content = "な、何が起こったの！？",
  ui_story_1015_10151402_101_dialog_content = "PlayerNameさん、後ろに下がってください！\nドアに大きな穴が開いています！",
  ui_story_1015_10151402_102_dialog_content = "何か恐ろしい化け物が侵入してくるようです！",
  ui_story_1015_10151402_103_dialog_content = "ええ！？",
  ui_story_1015_10151402_104_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_1015_10151402_105_dialog_content = "恐ろしいって表現は正しいわね。\nでも、化け物じゃないわ、私よ。",
  ui_story_1015_10151402_106_dialog_content = "やはりここにいたか、ノラ。",
  ui_story_1015_10151402_107_dialog_content = "時間ピッタリね。",
  ui_story_1015_10151402_108_dialog_content = "また会ったわね、レインハト。\nやっぱりまったく成長していないわね。",
  ui_story_1015_10151402_109_dialog_content = "今だに利用されてばかり。",
  ui_story_1015_10151402_110_dialog_content = "久しぶりね、ノラ。",
  ui_story_1015_10151402_111_dialog_content = "暗鬼とつるんでたようだけど、\nここまで落ちぶれるとは、大してうまくいってないようじゃない。",
  ui_story_1015_10151402_112_dialog_content = "あら？あなたは確か…ラスといったかしら？",
  ui_story_1015_10151402_113_dialog_content = "まあいいわ。同期のコネで出世した小者なんて\n覚えておく必要ないわ。",
  ui_story_1015_10151402_114_dialog_content = "あら、バカにされたものね。まあ、いいわ。",
  ui_story_1015_10151402_115_dialog_content = "後で私に地面に叩きつけられて、\n泣いて助けを求めても知らないから。",
  ui_story_1015_10151402_116_dialog_content = "幼稚ね。",
  ui_story_1015_10151402_117_dialog_content = "お前は…レインハトか…？",
  ui_story_1015_10151402_118_dialog_content = "ヘリオス！？その姿は…",
  ui_story_1015_10151402_119_dialog_content = "そうか…援軍を連れてきたのか？お前、ようやく…",
  ui_story_1015_10151402_120_dialog_content = "…",
  ui_story_1015_10151402_121_dialog_content = "ああ、すまない。遅くなった。",
  ui_story_1015_10151402_122_dialog_content = "援軍を連れてきたぞ。",
  ui_story_1015_10151402_123_dialog_content = "包囲しろ！",
  ui_story_1015_10151402_124_dialog_content = "了解です！",
  ui_story_1015_10151402_125_dialog_content = "やっぱり、思った通りね。",
  ui_story_1015_10151402_126_dialog_content = "レインハト、取引しましょ。",
  ui_story_1015_10151402_127_dialog_content = "何だと…？",
  ui_story_1015_10151402_128_dialog_content = "私とこの実験台を啓光から逃がしてちょうだい。\nあなたにとっても悪い事じゃないはずよ。",
  ui_story_1015_10151402_129_dialog_content = "あら？極夜に長くいたから、暗力で頭がおかしくなったの？",
  ui_story_1015_10151402_130_dialog_content = "今のあんたに条件交渉の資格はないわ。",
  ui_story_1015_10151402_131_dialog_content = "これは交渉じゃないわ。",
  ui_story_1015_10151402_132_dialog_content = "古だぬきどもが欲しがってるのは私じゃない、彼よ。",
  ui_story_1015_10151402_133_dialog_content = "（どういう意味です？委員会が欲しがっているのはヘリオスですと？）",
  ui_story_1015_10151402_134_dialog_content = "（しかし、私が受けた任務はノラを捕らえ、\nバイス中尉を救出すること…）",
  ui_story_1015_10151402_135_dialog_content = "あいつらの手に落ちたらどうなるか、分かってるでしょ。",
  ui_story_1015_10151402_136_dialog_content = "お前の要求を呑むわけにはいかない。",
  ui_story_1015_10151402_137_dialog_content = "もしこれが10数年前のまだ啓光にいた時であれば、\nお前を信じただろう。",
  ui_story_1015_10151402_138_dialog_content = "だが、長年にわたる戦いの中で、お前のことはよく分かった。",
  ui_story_1015_10151402_139_dialog_content = "お前がやろうとしていることは、\n「やつら」と変わりない。",
  ui_story_1015_10151402_140_dialog_content = "ヘリオスを私に預けろ。大元帥の名において保護し、\n何人たりとも触れさせはしない。",
  ui_story_1015_10151402_141_dialog_content = "あなたには無理よ。",
  ui_story_1015_10151402_142_dialog_content = "交渉決裂ね。これ以上ここに留まっている理由はないわ。",
  ui_story_1015_10151402_143_dialog_content = "ジェイド。",
  ui_story_1015_10151402_144_dialog_content = "<anim type=Shake><size=50>ギャアオ！</size></anim>",
  ui_story_1015_10151402_145_dialog_content = "「それじゃ、また」。",
  ui_story_1015_10151402_146_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_1015_10151501_1_dialog_content = "報告いたします。インゲル中佐とアナトリア少佐からの情報によると、\nすでに使われなくなっていた実験室でバイス中尉を発見したそうです。",
  ui_story_1015_10151501_2_dialog_content = "バイス中尉、帰隊しました！",
  ui_story_1015_10151501_3_dialog_content = "バイス！無事だったんだね。ケガはない？",
  ui_story_1015_10151501_4_dialog_content = "大丈夫よ！",
  ui_story_1015_10151501_5_dialog_content = "申し訳ありません。\n私の不注意で大変な迷惑を掛けてしまいました…",
  ui_story_1015_10151501_6_dialog_content = "あなたが無事に戻れば、それでいいのよ。",
  ui_story_1015_10151501_7_dialog_content = "その通りだわ。自分を責めないことね。",
  ui_story_1015_10151501_8_dialog_content = "ノラはずる賢いの。全員で立ち向かうのが一番よ。",
  ui_story_1015_10151501_9_dialog_content = "はい…",
  ui_story_1015_10151501_10_dialog_content = "捜索の方はどうなっている？ノラの足取りはつかめたか？",
  ui_story_1015_10151501_11_dialog_content = "報告いたします！シェルター内をくまなく探しましたが、\nノラの足取りはつかめませんでした。",
  ui_story_1015_10151501_12_dialog_content = "出入口と旧シェルターの通路はどうだ？",
  ui_story_1015_10151501_13_dialog_content = "すべて見張りを配備していますが、出入りした者はおりません。",
  ui_story_1015_10151501_14_dialog_content = "分かった。だが、気を抜いてはならん。\n捜索を続けろ。",
  ui_story_1015_10151501_15_dialog_content = "了解です！",
  ui_story_1015_10151501_16_dialog_content = "ノラったら、堂々と私たちの目の前から消えたわね。",
  ui_story_1015_10151501_17_dialog_content = "威勢のいいことばかり言ってたけど、逃げ足は速いのね。",
  ui_story_1015_10151501_18_dialog_content = "大元帥、ラス軍団長。\nノラの逃走経路について思い当たることがあります。",
  ui_story_1015_10151501_19_dialog_content = "ほう？話してくれ。",
  ui_story_1015_10151501_20_dialog_content = "このシェルターはノラが設計し、建設を主導しました。",
  ui_story_1015_10151501_21_dialog_content = "ノラはシェルター完成後から啓光連邦に背くまでの間に、\n何度もひそかにこのシェルターとカナン城の間を行き来しています。",
  ui_story_1015_10151501_22_dialog_content = "私の入手した情報によれば、\nノラは意味のないことに時間を使うことを嫌います。",
  ui_story_1015_10151501_23_dialog_content = "そのことから推測するに、ノラはこのシェルターとカナン城の間を素早く往来できる\n秘密の通路を造っていたのではないでしょうか？",
  ui_story_1015_10151501_24_dialog_content = "つまり、ノラはカナン城に向かって\n逃走した可能性があるというのか？",
  ui_story_1015_10151501_25_dialog_content = "はい。",
  ui_story_1015_10151501_26_dialog_content = "なるほど、一理あるな。すぐに人員を組織して、\nカナン城を捜索し、この件について調査しよう。",
  ui_story_1015_10151501_27_dialog_content = "レインハト、私に任せてちょうだい。",
  ui_story_1015_10151501_28_dialog_content = "それはならん。ノラとヘリオスに関係することだ。\n私自ら調査にあたろう。",
  ui_story_1015_10151501_29_dialog_content = "あの2人に関係あるからこそ、あんたが出るべきじゃないのよ。",
  ui_story_1015_10151501_30_dialog_content = "そもそもこの任務は委員会が私に命じたのよ。\n第一責任者である私が任務にあたるのが道理ってものでしょ。",
  ui_story_1015_10151501_31_dialog_content = "それに、今私たちが立ち向かってるのは、\nあんたのかつての身内であり、戦友なのよ。",
  ui_story_1015_10151501_32_dialog_content = "私がいくらあんたの意志の強さと正義感を信じていようと、\n他の全員があんたを信じるとは限らない。",
  ui_story_1015_10151501_33_dialog_content = "頭のあるヤツなら皆気づいてるわ。\n「あの人たち」最近ずっと、何とかしてあんたの過ちを見つけようとしてるわ。",
  ui_story_1015_10151501_34_dialog_content = "それにもうすぐ合同演習が始まるでしょ。\nアストラ大陸の全勢力が啓光に注目してるのよ。",
  ui_story_1015_10151501_35_dialog_content = "今あんたがやるべきことは、カナン城に戻ることよ。",
  ui_story_1015_10151501_36_dialog_content = "そうすれば、何があっても状況を落ち着かせることができるし、\nあんた自身の威信も保てる。",
  ui_story_1015_10151501_37_dialog_content = "それにあんたさえいれば、ノラが本当にカナン城に逃げていたとしたって、\n軽々しく騒ぎは起こせないでしょう。",
  ui_story_1015_10151501_38_dialog_content = "…",
  ui_story_1015_10151501_39_dialog_content = "私を信用できないっていうなら、\nお目付け役でも何でもつけるといいわ。私は気にしない。",
  ui_story_1015_10151501_40_dialog_content = "いつも言ってるでしょ。\n私は正々堂々、真正面からあんたを打ち負かすわ。",
  ui_story_1015_10151501_41_dialog_content = "今までも、今も、これからもそうよ。",
  ui_story_1015_10151501_42_dialog_content = "お前を信じよう。",
  ui_story_1015_10151501_43_dialog_content = "ノラを捕らえ、ヘリオスを連れ戻せ。\nこの任はお前に任せる。",
  ui_story_1015_10151501_44_dialog_content = "安心してちょうだい。必ず見つけてみせるわ。",
  ui_story_1015_10151501_45_dialog_content = "そうと決まれば、PlayerName。\nお前たちも私と共にカナン城へ戻るのだ。",
  ui_story_1015_10151501_46_dialog_content = "しかし、任務が…",
  ui_story_1015_10151501_47_dialog_content = "委員会はすでにラス軍団長にこの件を任せた。\nお前たちがこれ以上気に掛けることはない。",
  ui_story_1015_10151501_48_dialog_content = "この後の仕事に集中せよ。",
  ui_story_1015_10151501_49_dialog_content = "はい。",
  ui_story_1015_10151501_50_dialog_content = "はい、承知いたしました。",
  ui_story_1015_10151501_51_dialog_content = "<size=30>確かにこの後の仕事は山積みですね…\n大元帥の演習期間の日程調整と、それから…</size>",
  ui_story_1015_10151501_52_dialog_content = "アナトリア。",
  ui_story_1015_10151501_53_dialog_content = "<size=45>はい！</size>",
  ui_story_1015_10151501_54_dialog_content = "大元帥、何か他にご命令でしょうか？",
  ui_story_1015_10151501_55_dialog_content = "私に付いている必要はない。演習に参加せよ。",
  ui_story_1015_10151501_56_dialog_content = "はい…はい！？お待ちください。\n私には所属チームがないので、演習には参加できません。",
  ui_story_1015_10151501_57_dialog_content = "その件は心配しなくていい。\nあるチームの隊員が1人、事情があって参加できなくなったのだ。",
  ui_story_1015_10151501_58_dialog_content = "空いた枠はお前が埋めよ。",
  ui_story_1015_10151501_59_dialog_content = "はい。どちらのチームでしょう？",
  ui_story_1015_10151501_60_dialog_content = "お前もよく知っている。インゲルのチームだ。",
  ui_story_1015_10151501_61_dialog_content = "何とおっしゃいましたか？私のチームですか？",
  ui_story_1015_10151501_62_dialog_content = "まさか、アクセリアに何かあったのですか？",
  ui_story_1015_10151501_63_dialog_content = "いや、アクセリアではない。ショーンだ。",
  ui_story_1015_10151501_64_dialog_content = "私も先程トワイライトシティからの知らせを聞いたばかりだ。",
  ui_story_1015_10151501_65_dialog_content = "ショーンが突然身体の調子を崩し、\nひとまずトワイライトシティに残って様子を見なければならなくなったらしい。",
  ui_story_1015_10151501_66_dialog_content = "ショーンの具合はどうなんですか？大丈夫ですか？",
  ui_story_1015_10151501_67_dialog_content = "トワイライトシティの者の話だと、\n光力術を使った際に今までなかった奇怪な現象が起こったらしい。",
  ui_story_1015_10151501_68_dialog_content = "おそらくショーンの遺伝子の欠陥と関係があるのだろう。",
  ui_story_1015_10151501_69_dialog_content = "そうですか…",
  ui_story_1015_10151501_70_dialog_content = "今回のことが一段落したら、トワイライトシティにお見舞いに行こう。",
  ui_story_1015_10151501_71_dialog_content = "私とインゲル、アクセリアでチームを組むのですね？",
  ui_story_1015_10151501_72_dialog_content = "ご命令に従います。",
  ui_story_1015_10151501_73_dialog_content = "（元の計画とは少々違いますが、いいでしょう。\n充分対処可能な範囲内です）",
  ui_story_1015_10151501_74_dialog_content = "私も異論ありません。",
  ui_story_1015_10151501_75_dialog_content = "では、決まりだ。",
  ui_story_1015_10151501_76_dialog_content = "カナン城に戻るとしよう。",
  ui_story_1015_10151501_77_dialog_content = "<color=#e8d9bb>数日後、カナン城</color>",
  ui_story_1015_10151501_78_dialog_content = "「まもなくカナン城に到着します。列車を下りる準備をしてください。\n下車する際は車両とホームの間の隙間にお気をつけください」",
  ui_story_1015_10151501_79_dialog_content = "「啓明の光が旅路を明るく照らさんことを」",
  ui_story_1015_10151501_80_dialog_content = "すみません、道を開けてください。降ります！",
  ui_story_1015_10151501_81_dialog_content = "すごい人ね…さすがはアストラ大陸最大の軍事演習だわ！",
  ui_story_1015_10151501_82_dialog_content = "それにしても、広いわね。道間違ってないわよね？\nこの駅でいいんでしょ？",
  ui_story_1015_10151501_83_dialog_content = "カレン殿下のご指示によれば、この駅で下車で間違いありません。",
  ui_story_1015_10151501_84_dialog_content = "道に迷わなければ、いいのですが…",
  ui_story_1015_10151501_85_dialog_content = "ベルタ。",
  ui_story_1015_10151501_86_dialog_content = "カレン殿下！",
  ui_story_1015_10151501_87_dialog_content = "約束通り、迎えにきたわ。",
  ui_story_1015_10151501_88_dialog_content = "ありがとうございます！殿下が迎えに来てくださらなかったら、\n道に迷うところでした…",
  ui_story_1015_10151501_89_dialog_content = "気にしないで。\n演習に何度か参加すれば、この地にも詳しくなるわ。",
  ui_story_1015_10151501_90_dialog_content = "行きましょう。",
  ui_story_1015_10151501_91_dialog_content = "はい、カレン殿下！",
  ui_story_1015_10151501_92_dialog_content = "先程立ち去って行ったのは、あの殿下でしょうか？",
  ui_story_1015_10151501_93_dialog_content = "ああ、そのようだな。",
  ui_story_1015_10151501_94_dialog_content = "挨拶しにいかれないのですか？",
  ui_story_1015_10151501_95_dialog_content = "ハハハ、今は止しておこう。",
  ui_story_1015_10151501_96_dialog_content = "ここは人が多い。邪魔になってはいけない。",
  ui_story_1015_10151501_97_dialog_content = "合同演習が正式に始まるまでに、\n昔話や挨拶をする時間はいくらでもあるからな。",
  ui_story_1015_10151501_98_dialog_content = "それもそうですね。",
  ui_story_1015_10151501_99_dialog_content = "しかも我々の新しいチームメイトには任務がありますし…",
  ui_story_1015_10151501_100_dialog_content = "申し訳ありません、通してください。",
  ui_story_1015_10151501_101_dialog_content = "クロウ、少しこちらに寄りなさい。\nドアにぶつかりますよ。",
  ui_story_1015_10151501_102_dialog_content = "分かった。",
  ui_story_1015_10151501_103_dialog_content = "本当に申し訳ない…",
  ui_story_1015_10151501_104_dialog_content = "私の任務にもかかわらず、\nあなたに手伝わせることになってしまいました。",
  ui_story_1015_10151501_105_dialog_content = "私は護衛だ。あなたに協力し、守ることは私の務め。",
  ui_story_1015_10151501_106_dialog_content = "それに、もし私が手伝わず、あなた1人だったとしたら、\nこれをカナン城に運んでくることはできなかった。",
  ui_story_1015_10151501_107_dialog_content = "ええ、仕方ありません。力仕事は得意ではないので。",
  ui_story_1015_10151501_108_dialog_content = "手伝いが必要か？啓光の軍師殿？",
  ui_story_1015_10151501_109_dialog_content = "その必要はありません。目的地はすぐですから。",
  ui_story_1015_10151501_110_dialog_content = "手を貸していただきたい時は自分から申し出ます。",
  ui_story_1015_10151501_111_dialog_content = "それならいい。今まで力を合わせたことがないからといって、\n遠慮は無用だぞ。",
  ui_story_1015_10151501_112_dialog_content = "アイアンソーン騎士団に入りたいと申し出てくれても構わないぞ。\n私は大歓迎だ。",
  ui_story_1015_10151501_113_dialog_content = "冗談がお上手ですね。",
  ui_story_1015_10151501_114_dialog_content = "よろしければ、あなたはヨーゼフさんと先に\n手続きを済ませてきてください。",
  ui_story_1015_10151501_115_dialog_content = "私はクロウと「彼女」を依頼人に渡してきます。\nその後で手続きに参ります。",
  ui_story_1015_10151501_116_dialog_content = "分かった。ならば先に行っている。",
  ui_story_1015_10151501_117_dialog_content = "後程またお会いしましょう、ショウ参謀長。",
  ui_story_1015_10151501_118_dialog_content = "…",
  ui_story_1015_10151501_119_dialog_content = "クロウ、どうしましたか？",
  ui_story_1015_10151501_120_dialog_content = "…",
  ui_story_1015_10151501_121_dialog_content = "もしやまた、なぜ私があなたとではなく、\n彼らとチームを組んだのかを聞きたいのですか？",
  ui_story_1015_10151501_122_dialog_content = "私ならあなたを守れる。彼らには無理だ。",
  ui_story_1015_10151501_123_dialog_content = "それはよく分かっていますよ。",
  ui_story_1015_10151501_124_dialog_content = "しかし、これはトワイライトシティ全体で決めたことです。",
  ui_story_1015_10151501_125_dialog_content = "あなたもトワイライトシティの一員だ。",
  ui_story_1015_10151501_126_dialog_content = "分かっています。しかし、今回はいつもとは違うのです。",
  ui_story_1015_10151501_127_dialog_content = "アイアンソーン騎士団と光の神教会と協力するのは、\n外の世界にトワイライトシティの団結と強大さを示すためです。",
  ui_story_1015_10151501_128_dialog_content = "そうしてこそ演習で抜きんでた成績を収めた時、\n各勢力に対して意見を述べ、圧力をかけるに充分な発言権と手段が得られるのです。",
  ui_story_1015_10151501_129_dialog_content = "トワイライトシティはそれほど嫌われているのか？",
  ui_story_1015_10151501_130_dialog_content = "いえ、嫌われているのではありません。",
  ui_story_1015_10151501_131_dialog_content = "誰も関心をもっていないのです。",
  ui_story_1015_10151501_132_dialog_content = "しかし、私たちは違います。トワイライトシティは私たちの家です。\n町が暗鬼の波に飲み込まれるのを黙って見ているわけにはいきません。",
  ui_story_1015_10151501_133_dialog_content = "ですから、私たちは必ず勝たねばなりません。\n中央の人々の注目を引きつけ、トワイライトシティに援軍を送ってもらうのです。",
  ui_story_1015_10151501_134_dialog_content = "…",
  ui_story_1015_10151501_135_dialog_content = "あなたの言う通りにしよう。",
  ui_story_1015_10151501_136_dialog_content = "ありがとうございます。",
  ui_story_1015_10151501_137_dialog_content = "さあ、急いで「彼女」を渡しに行きましょう。",
  ui_story_1015_10151501_138_dialog_content = "あれがターゲット？",
  ui_story_1015_10151501_139_dialog_content = "ぜんぜん面白そうじゃないじゃん。\n夢の中のクマさんの方がよっぽど面白いよ。",
  ui_story_1015_10151501_140_dialog_content = "そう結論を急いではいけません。",
  ui_story_1015_10151501_141_dialog_content = "「あのお方」から与えられた任務は彼らを観察することです。\nきちんと務めを果たしましょう。",
  ui_story_1015_10151501_142_dialog_content = "「あのお方」の直観が外れたことはありません。\n彼らはきっと何か隠しています。",
  ui_story_1015_10151501_143_dialog_content = "動物嫌いじゃないといいな…",
  ui_story_1015_10151501_144_dialog_content = "現況は以上です。",
  ui_story_1015_10151501_145_dialog_content = "レインハト大元帥はすでにカナン城に戻りました。\nノラと目標の実験台の行方は分かっていませんが、カナン城のどこかにいる可能性が高いでしょう。",
  ui_story_1015_10151501_146_dialog_content = "また、各勢力ともすでにカナン城に集結し、\nまもなく合同演習が始まります。",
  ui_story_1015_10151501_147_dialog_content = "ただ、トワイライトシティが啓光と白夜城の混合チームを\n派遣してきたことは意外でした。",
  ui_story_1015_10151501_148_dialog_content = "私もメンバーを探してチームを編成し、\n彼らの行動をけん制した方がよろしいでしょうか？",
  ui_story_1015_10151501_149_dialog_content = "確かに注意するに越したことはありませんが、\nそう警戒する必要もないでしょう。",
  ui_story_1015_10151501_150_dialog_content = "インゲルとアクセリアに任せておけばよいでしょう。",
  ui_story_1015_10151501_151_dialog_content = "君には他にやってもらうことがあります。",
  ui_story_1015_10151501_152_dialog_content = "はい。",
  ui_story_1015_10151501_153_dialog_content = "<color=#e8d9bb>その頃、カナン城某所では</color>",
  ui_story_1015_10151501_154_dialog_content = "<anim type=Shake><size=45>ウウ…</size></anim>",
  ui_story_1015_10151501_155_dialog_content = "ここに置いて。",
  ui_story_1015_10151501_156_dialog_content = "<anim type=Shake><size=45>グウ！</size></anim>",
  ui_story_1015_10151501_157_dialog_content = "<anim type=Shake>グルウウ――</anim>",
  ui_story_1015_10151501_158_dialog_content = "よくやったわ。",
  ui_story_1015_10151501_159_dialog_content = "元の姿に戻って、通路からここを離れなさい。",
  ui_story_1015_10151501_160_dialog_content = "<anim type=Shake><size=45>グウ！？</size></anim>",
  ui_story_1015_10151501_161_dialog_content = "<anim type=Shake><size=45>グウゥ――グウゥ――！</size></anim>",
  ui_story_1015_10151501_162_dialog_content = "あなたがここで出来ることはないわ。",
  ui_story_1015_10151501_163_dialog_content = "このまま残ってても、足手まといになるだけよ。",
  ui_story_1015_10151501_164_dialog_content = "元の所に戻って、私の帰りを待ってなさい。",
  ui_story_1015_10151501_165_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_1015_10151501_166_dialog_content = "キュウ――！",
  ui_story_1015_10151501_167_dialog_content = "デニールか…？",
  ui_story_1015_10151501_168_dialog_content = "…",
  ui_story_1015_10151501_169_dialog_content = "目が覚めたのね。",
  ui_story_1015_10151501_170_dialog_content = "ああ…",
  ui_story_1015_10151501_171_dialog_content = "俺を…どこへ…連れて来たんだ？",
  ui_story_1015_10151501_172_dialog_content = "認知能力が徐々に回復してきてるの？",
  ui_story_1015_10151501_173_dialog_content = "実験が成功したってことだけど、\nタイミングが悪いわね。",
  ui_story_1015_10151501_174_dialog_content = "何を言ってるんだ…？意味が分からない…",
  ui_story_1015_10151501_175_dialog_content = "何でもないわ。",
  ui_story_1015_10151501_176_dialog_content = "ここは…どこなんだ？まだ答えてくれてないだろ…",
  ui_story_1015_10151501_177_dialog_content = "…",
  ui_story_1015_10151501_178_dialog_content = "カナン城よ。",
  ui_story_1015_10151501_179_dialog_content = "帰って…来たのか？",
  ui_story_1015_10151501_180_dialog_content = "そうよ。",
  ui_story_1015_10151501_181_dialog_content = "帰ってきたのよ。",
  ui_story_1016_10160101_1_dialog_content = "<color=#e8d9bb>ボーッ――</color>",
  ui_story_1016_10160101_2_dialog_content = "<color=#e8d9bb>ガッタンゴットン…</color>",
  ui_story_1016_10160101_3_dialog_content = "「合同演習参加者の皆さんにお知らせします」",
  ui_story_1016_10160101_4_dialog_content = "「目的地に到着しました。急ぎ下車してください」",
  ui_story_1016_10160101_5_dialog_content = "「次の案内があるまで、しばらくホームでお待ちください」",
  ui_story_1016_10160101_6_dialog_content = "わあ！初めて列車に乗ったわ。",
  ui_story_1016_10160101_7_dialog_content = "とても速かったですね。馬車よりもずっと速かったです。",
  ui_story_1016_10160101_8_dialog_content = "あの揺れにはどうも慣れません。やはり下りた方が安心します。",
  ui_story_1016_10160101_9_dialog_content = "演習会場には着いたのよね。これからどうすればいいのかしら？",
  ui_story_1016_10160101_10_dialog_content = "ここで少々お待ちください。\n後ほど演習について担当者がご説明します。",
  ui_story_1016_10160101_11_dialog_content = "アナトリア！久しぶりね！",
  ui_story_1016_10160101_12_dialog_content = "あなたも合同演習に参加するの？",
  ui_story_1016_10160101_13_dialog_content = "もちろんです。ここにいるのは全員演習の参加者ですよ。",
  ui_story_1016_10160101_14_dialog_content = "そうだったの。ずいぶんにぎやかね。",
  ui_story_1016_10160101_15_dialog_content = "啓光の領地内だからって、よそ者いじめしないでね。",
  ui_story_1016_10160101_16_dialog_content = "白夜城では、そのような心配もあるかもしれませんが、\nここでは無用です。",
  ui_story_1016_10160101_17_dialog_content = "フン…",
  ui_story_1016_10160101_18_dialog_content = "失礼する、通してくれ。「ワレモノ」運搬中なのだ。",
  ui_story_1016_10160101_19_dialog_content = "ぶつけないように十分気を付けてください。",
  ui_story_1016_10160101_20_dialog_content = "ショウ、どこに運べばいいのだ？",
  ui_story_1016_10160101_21_dialog_content = "引き取りの方とここで会う約束になっているのですが…",
  ui_story_1016_10160101_22_dialog_content = "お二人ともお疲れ様でした。お預かりしましょう。",
  ui_story_1016_10160101_23_dialog_content = "あなた方の任務は完了です。",
  ui_story_1016_10160101_24_dialog_content = "インゲル中佐、引き取りの方とはあなたのことでしたか。",
  ui_story_1016_10160101_25_dialog_content = "何かおかしいですか？",
  ui_story_1016_10160101_26_dialog_content = "あなたも演習に参加されるとは少々意外でした。",
  ui_story_1016_10160101_27_dialog_content = "むやみに公には出られない方だと思っていたので。",
  ui_story_1016_10160101_28_dialog_content = "それは勝手な思い込みですよ。",
  ui_story_1016_10160101_29_dialog_content = "さあ、お持ちください。宝物が戻りました。",
  ui_story_1016_10160101_30_dialog_content = "問題がないか、お調べになった方がよいのでは？",
  ui_story_1016_10160101_31_dialog_content = "そうですね。",
  ui_story_1016_10160101_32_dialog_content = "<color=#e8d9bb>コン、コン</color>",
  ui_story_1016_10160101_33_dialog_content = "アクセリア、そろそろ起きてください。",
  ui_story_1016_10160101_34_dialog_content = "<color=#e8d9bb>バサッ――</color>",
  ui_story_1016_10160101_35_dialog_content = "ふわぁ～…あっ。",
  ui_story_1016_10160101_36_dialog_content = "インゲル、おはようございます。",
  ui_story_1016_10160101_37_dialog_content = "よく眠れましたか？",
  ui_story_1016_10160101_38_dialog_content = "はい、とても調子がいいです。",
  ui_story_1016_10160101_39_dialog_content = "ふぅ、やっと外の空気が吸える。",
  ui_story_1016_10160101_40_dialog_content = "列車の中のような閉め切った蒸し暑い空間は苦手だ。",
  ui_story_1016_10160101_41_dialog_content = "レオ騎士団長、ひどく汗をかかれていますね。",
  ui_story_1016_10160101_42_dialog_content = "ああ。戦いよりも疲れた気がする。",
  ui_story_1016_10160101_43_dialog_content = "それは大げさすぎるのでは？\nただ列車に乗ってきただけですよ。",
  ui_story_1016_10160101_44_dialog_content = "道中何の危険もありませんでした。",
  ui_story_1016_10160101_45_dialog_content = "危険どうこうという問題ではないのだ…",
  ui_story_1016_10160101_46_dialog_content = "これで汗を拭いたら？",
  ui_story_1016_10160101_47_dialog_content = "ありがとう…おや？カレン殿下！？",
  ui_story_1016_10160101_48_dialog_content = "白夜城の者の多くは機械にあまり馴染めないものよ。\n私もよく分かるわ。",
  ui_story_1016_10160101_49_dialog_content = "その通りです。\n殿下のように他人の気持ちの分かる方ばかりであればよいのですが。",
  ui_story_1016_10160101_50_dialog_content = "しかし、このような所で殿下にお会いするとは実に意外でした。",
  ui_story_1016_10160101_51_dialog_content = "次に会うのは白夜城だと思っておりましたから。",
  ui_story_1016_10160101_52_dialog_content = "白夜城では、複雑な身分のしがらみがあるけれど、\nここでは同じ演習参加者よ。",
  ui_story_1016_10160101_53_dialog_content = "ハハハ、その通りでございます。",
  ui_story_1016_10160101_54_dialog_content = "長年複雑な環境で暮らしていると、\n時おり単純なものにあこがれを抱いてしまうものです。",
  ui_story_1016_10160101_55_dialog_content = "レオ、ヨーゼフ！君たちも演習に参加するの？",
  ui_story_1016_10160101_56_dialog_content = "トワイライトシティからだと、ずいぶん遠かったでしょ？",
  ui_story_1016_10160101_57_dialog_content = "PlayerName！なぜここに？",
  ui_story_1016_10160101_58_dialog_content = "僕も合同演習に招待されたんだよ。\nカレンとバイスも一緒だよ。",
  ui_story_1016_10160101_59_dialog_content = "そうか。だったら、巨像に乗せてもらえばよかったな。",
  ui_story_1016_10160101_60_dialog_content = "あはは、巨像に乗りたいなら、いつでも歓迎するよ！",
  ui_story_1016_10160101_61_dialog_content = "オ、オホン！演習参加者の皆さん、どうぞこちらに集まってください。",
  ui_story_1016_10160101_62_dialog_content = "合同演習に関する諸事項をお伝えします。",
  ui_story_1016_10160101_63_dialog_content = "あ、これはビビアンさんの声かな？",
  ui_story_1016_10160101_64_dialog_content = "ええ！私たちも急ぎましょ！",
  ui_story_1016_10160101_65_dialog_content = "バイス、気を付けて。ここは人が多い。",
  ui_story_1016_10160101_66_dialog_content = "そんなに心配しないで。別にケガもしてないのよ。",
  ui_story_1016_10160101_67_dialog_content = "病院でも検査してもらって、結果も見たでしょ？\nいたって健康なんだから！",
  ui_story_1016_10160101_68_dialog_content = "それでも、やっぱり…",
  ui_story_1016_10160101_69_dialog_content = "さあさあ、行くわよ！",
  ui_story_1016_10160101_70_dialog_content = "合同演習参加者の皆さん、カナン城へようこそ。",
  ui_story_1016_10160101_71_dialog_content = "私は啓光連邦参謀長ビビアンです。\n今回の合同演習では皆さんの案内役を務めさせていただきます。",
  ui_story_1016_10160101_72_dialog_content = "啓光は効率を重視します。\nしたがって、煩わしい形式や決まりはありません。",
  ui_story_1016_10160101_73_dialog_content = "この規則説明の後に、今期合同演習が正式に開始となります。",
  ui_story_1016_10160101_74_dialog_content = "わ、すっごくシンプルな流れだね。",
  ui_story_1016_10160101_75_dialog_content = "素晴らしい。くだらない政治演説を聞かずに済む。",
  ui_story_1016_10160101_76_dialog_content = "皆さんもご存じかとは思いますが、\n合同演習は若い世代の戦闘における対応力向上を目的としています。",
  ui_story_1016_10160101_77_dialog_content = "参加者はすべて25歳以下の若い世代の皆さんです。",
  ui_story_1016_10160101_78_dialog_content = "つまり、皆さんのように才覚を表し始めたばかりの方々や\n現在まだ学び舎にいる方々です。",
  ui_story_1016_10160101_79_dialog_content = "年齢や経験に差はあるものの、将来同じ戦場で戦うことになるでしょう。",
  ui_story_1016_10160101_80_dialog_content = "ですから、互いに学び、協力し、さらには競い合って、\n自身の戦闘能力や心構えを最大限に磨いてほしいと思います。",
  ui_story_1016_10160101_81_dialog_content = "その鍛錬の場である合同演習は、\n訓練と試験の2段階に分けて実施します。",
  ui_story_1016_10160101_82_dialog_content = "訓練段階では、啓光連邦最高レベルの教育資源の下、\n前人に学び、自身の能力向上を目指してください。",
  ui_story_1016_10160101_83_dialog_content = "次の試験段階では、お互いに競い合い、\n本演習唯一の優勝チームを決定します。",
  ui_story_1016_10160101_84_dialog_content = "そして、皆さんもご存じだと思いますが、\n慣例により、合同演習の試験優勝者には特別に――",
  ui_story_1016_10160101_85_dialog_content = "大元帥との手合わせの機会が与えられます。",
  ui_story_1016_10160101_86_dialog_content = "ええ！？大元帥と手合わせなんて…\n恐ろしくて、想像もつかないよ。",
  ui_story_1016_10160101_87_dialog_content = "でも、この合同演習で優勝できるなら、\nそっちもそっちで強いんだろうな。",
  ui_story_1016_10160101_88_dialog_content = "そうだったね。前回は白夜城の姫が優勝したんだったね…",
  ui_story_1016_10160101_89_dialog_content = "以上で本合同演習の説明は終わりです。",
  ui_story_1016_10160101_90_dialog_content = "では、旗を掲げてください。",
  ui_story_1016_10160101_91_dialog_content = "<color=#e8d9bb>バッ――</color>",
  ui_story_1016_10160101_92_dialog_content = "わぁ、長い旗だね！",
  ui_story_1016_10160101_93_dialog_content = "こちらが「<color=#FFB400>優勝旗</color>」です。",
  ui_story_1016_10160101_94_dialog_content = "合同演習で優勝した者は自身の陣営の旗をこの優勝旗に足すことができます。",
  ui_story_1016_10160101_95_dialog_content = "演習が１回また1回と行われるごとに旗が加えられ、\n今の優勝旗ができました。",
  ui_story_1016_10160101_96_dialog_content = "そして、その中には各陣営の旗が含まれています。",
  ui_story_1016_10160101_97_dialog_content = "各地の群雄が今、私たちの見上げる空に集まっています。",
  ui_story_1016_10160101_98_dialog_content = "合同演習の象徴として、\nこの旗は代々受け継がれて来た勝利への決意を示しているのです。",
  ui_story_1016_10160101_99_dialog_content = "（！！！）",
  ui_story_1016_10160101_100_dialog_content = "（僕の見間違いじゃないよね。あれは…空の末裔の旗…）",
  ui_story_1016_10160101_101_dialog_content = "それでは、宣言いたします。",
  ui_story_1016_10160101_102_dialog_content = "合同演習、開始です！",
  ui_story_1016_10160101_103_dialog_content = "<color=#e8d9bb>パチパチパチパチ――</color>",
  ui_story_1016_10160101_104_dialog_content = "続いて、参加者登録を行います。",
  ui_story_1016_10160101_105_dialog_content = "招待状には、配属先のチーム名が記載されていたと思います。",
  ui_story_1016_10160101_106_dialog_content = "3人一組のそのチームが演習における一切の集団行動の基本単位となります。",
  ui_story_1016_10160101_107_dialog_content = "隊長の所属する陣営がチームの所属陣営になります。",
  ui_story_1016_10160101_108_dialog_content = "それでは皆さん、早速自身の所属チームを確認し、\n他のメンバーと集合してください。",
  ui_story_1016_10160101_109_dialog_content = "僕はバイス、カレンと一緒だよね？",
  ui_story_1016_10160101_110_dialog_content = "そうよ。前に確認したでしょ？",
  ui_story_1016_10160101_111_dialog_content = "招待状に書かれているのはあなたの名前よ。\nよろしくね、隊長さん。",
  ui_story_1016_10160101_112_dialog_content = "な、なんか緊張するな…",
  ui_story_1016_10160101_113_dialog_content = "チームメンバーの確認が済んだ方は、\nこちらで登録をお願いします。",
  ui_story_1016_10160101_114_dialog_content = "チーム分け終了後、宿舎までご案内します。\n荷物を置いた後は許可された範囲内で自由行動して結構です。",
  ui_story_1016_10160101_115_dialog_content = "授業は明日から始まります。",
  ui_story_1016_10160101_116_dialog_content = "なんだか興奮してきたわ！",
  ui_story_1016_10160101_117_dialog_content = "小さい頃から合同演習の話は聞いてたけど、\n実際に参加するのは初めてよ。",
  ui_story_1016_10160101_118_dialog_content = "カレン、前回参加した時はどんな気分だったの？",
  ui_story_1016_10160101_119_dialog_content = "今のあなたと同じよ。",
  ui_story_1016_10160101_120_dialog_content = "興奮して、今にも戦いたくてうずうずしてるのに、\nどこか不安で仕方なかった。",
  ui_story_1016_10160101_121_dialog_content = "不安だったのに優勝したの？",
  ui_story_1016_10160101_122_dialog_content = "優等生ってやっぱりすごいのね。\nうらやましくなっちゃう。",
  ui_story_1016_10160101_123_dialog_content = "そ、そんなことないわ！\n別にひけらかすつもりで言ったわけではないのよ！",
  ui_story_1016_10160101_124_dialog_content = "フフ、からかっただけよ！",
  ui_story_1016_10160101_125_dialog_content = "ところで…PlayerName、どうかしたの？\nずっと黙ってるけど？",
  ui_story_1016_10160101_126_dialog_content = "こういう緊張した雰囲気は苦手かしら？",
  ui_story_1016_10160101_127_dialog_content = "いや…ただ考えてたんだ。\n演習の参加者の中には友だちもたくさんいる。",
  ui_story_1016_10160101_128_dialog_content = "友だちと競い合うなんて…まだ心の準備ができてないんだ。",
  ui_story_1016_10160101_129_dialog_content = "そうよね。あなたは競争は嫌いだもの。",
  ui_story_1016_10160101_130_dialog_content = "気にすることないわ。あくまで学びに来たと思えばいいのよ。\n勝ち負けばかりを気にする必要はないわ。",
  ui_story_1016_10160101_131_dialog_content = "でも、僕は勝ちたい…",
  ui_story_1016_10160101_132_dialog_content = "えっ？",
  ui_story_1016_10160101_133_dialog_content = "さっき「優勝旗」の中に空の末裔の旗があったんだ。",
  ui_story_1016_10160101_134_dialog_content = "一族が残した痕跡を見られて嬉しかった。でも…",
  ui_story_1016_10160101_135_dialog_content = "空の末裔の旗は一番新しい旗とすごく離れてて、\n何だかつらい気持ちになったよ。",
  ui_story_1016_10160101_136_dialog_content = "空の末裔はそんなに長い間、\n合同演習に出てなかったのかって…",
  ui_story_1016_10160101_137_dialog_content = "一族の旗は空の末裔の栄光を象徴してるんだ。\n骨董品みたいにただの飾りにはなって欲しくない。",
  ui_story_1016_10160101_138_dialog_content = "新しい空の末裔の旗を掲げたいんだ。",
  ui_story_1016_10160101_139_dialog_content = "いい？よく聞いて。\n私たちのチームは全員白夜城の者で構成されているの。",
  ui_story_1016_10160101_140_dialog_content = "つまり、私たちの演習での出来不出来は\n白夜城の教育レベルを示すことになる。",
  ui_story_1016_10160101_141_dialog_content = "黎明学院の顔に泥を塗ってはいけないわ。",
  ui_story_1016_10160101_142_dialog_content = "隊長、早々にお説教ですか。",
  ui_story_1016_10160101_143_dialog_content = "お、お説教じゃないわ。",
  ui_story_1016_10160101_144_dialog_content = "私はただ…真剣に取り組むべきだって思っただけで…",
  ui_story_1016_10160101_145_dialog_content = "その通りです。演習の参加者は皆高い実力を持っています。",
  ui_story_1016_10160101_146_dialog_content = "精いっぱい取り組まなければ、後れを取ってしまいます。",
  ui_story_1016_10160101_147_dialog_content = "それはそうと、印象に残ったチームはありましたか？",
  ui_story_1016_10160101_148_dialog_content = "私はPlayerNameのチームしか印象に残っていません。",
  ui_story_1016_10160101_149_dialog_content = "空の末裔の特殊な能力にカレン殿下とバイスの力が加わったら、\nかなり強力なライバルになるかと思いますが。",
  ui_story_1016_10160101_150_dialog_content = "ええ、しかもカレン殿下は前回の優勝者です。\n連続優勝するかもしれませんね。",
  ui_story_1016_10160101_151_dialog_content = "PlayerNameのチーム以外で注目すべきチームが2つあるわ。",
  ui_story_1016_10160101_152_dialog_content = "1つはレオ騎士団長の率いるチームよ。\nメンバー3人ともトワイライトシティからの参加者よ。",
  ui_story_1016_10160101_153_dialog_content = "以前任務でトワイライトシティの人たちの戦い方を見たことがあるんだけど――",
  ui_story_1016_10160101_154_dialog_content = "あそこの人たちは実戦経験が豊富で、\nその点ではどのチームもかなわないわ。",
  ui_story_1016_10160101_155_dialog_content = "実戦経験ですか…確かに重要ですね。",
  ui_story_1016_10160101_156_dialog_content = "同年代だというのに、その点すでに大きく引き離されてるんですね。",
  ui_story_1016_10160101_157_dialog_content = "もう1つのチームはインゲルの率いるチーム。\nインゲル以外のメンバーはアクセリアとアナトリアよ。",
  ui_story_1016_10160101_158_dialog_content = "この3人は啓光の若手の中でもずば抜けて優秀な戦士なの。",
  ui_story_1016_10160101_159_dialog_content = "彼らの背後には啓光の奥深く強固な科学技術の存在がある。\n実力はいまだ計り知れないわね。",
  ui_story_1016_10160101_160_dialog_content = "うっ…科学研究と関わりがあるとなれば、\n私たちが忌み嫌うようなものでしょうね。",
  ui_story_1016_10160101_161_dialog_content = "私もそう思います。彼らとは戦いたくありません。",
  ui_story_1016_10160101_162_dialog_content = "私たちはカナン城に客として来てるのよ。\n啓光のやり方を受け入れるしかないわ。",
  ui_story_1016_10160101_163_dialog_content = "実践訓練だと思いましょう。",
  ui_story_1016_10160101_164_dialog_content = "そうは言っても、「受け入れる」のはそう簡単ではありません。",
  ui_story_1016_10160101_165_dialog_content = "隊長もしばらく歩き回っていますが、\nまだカナン城の地形を受け入れられていないのと同じです。",
  ui_story_1016_10160101_166_dialog_content = "ど、どうして私の話になるの？",
  ui_story_1016_10160101_167_dialog_content = "宿舎に戻りたいからですよ、隊長。\nいつになったら正しい道筋にたどり着けるのでしょう？",
  ui_story_1016_10160101_168_dialog_content = "もうすぐよ！道は分かったわ！",
  ui_story_1016_10160101_169_dialog_content = "ここを右に曲がれば…",
  ui_story_1016_10160101_170_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_1016_10160101_171_dialog_content = "<size=45>きゃあ！</size>",
  ui_story_1016_10160101_172_dialog_content = "うっ…",
  ui_story_1016_10160101_173_dialog_content = "ご、ごめんなさい！\n前をよく見ていなかったので、ぶつかってしまいました！",
  ui_story_1016_10160101_174_dialog_content = "大丈夫ですか？",
  ui_story_1016_10160101_175_dialog_content = "大丈夫です。僕はよく他人にぶつかるのです。\nお気になさらず。",
  ui_story_1016_10160101_176_dialog_content = "ただ、杖をとっていただけますか？\nどこに落としたのか分からないのです。",
  ui_story_1016_10160101_177_dialog_content = "どうぞ、杖です。",
  ui_story_1016_10160101_178_dialog_content = "失礼ですが…目が不自由でいらっしゃるんですか？",
  ui_story_1016_10160101_179_dialog_content = "お恥ずかしいところをお見せしました。",
  ui_story_1016_10160101_180_dialog_content = "あ、ごめんなさい！ぶつかった私が悪いんです！",
  ui_story_1016_10160101_181_dialog_content = "これからどちらへ？案内します！",
  ui_story_1016_10160101_182_dialog_content = "その必要はありません。今人を探していたところなのです。\n着ぐるみ姿の背の低い女の子なのですが、見かけませんでしたか？",
  ui_story_1016_10160101_183_dialog_content = "いいえ…",
  ui_story_1016_10160101_184_dialog_content = "そうですか。では自分で探すことにいたします。",
  ui_story_1016_10160101_185_dialog_content = "あ、そういえば、僕も皆さんと同様、演習に参加します。",
  ui_story_1016_10160101_186_dialog_content = "えっ？",
  ui_story_1016_10160101_187_dialog_content = "ディシスと申します。どうぞよろしくお願いいたします。",
  ui_story_1016_10160101_188_dialog_content = "今回の計画では目立つことが重要だ。分かっているな？",
  ui_story_1016_10160101_189_dialog_content = "戦争を想定していようが、しょせんはママゴト。\n我々には無意味だ。重要なのはいかにして声をあげるかだ。",
  ui_story_1016_10160101_190_dialog_content = "我々は何としても全世界に知らせねばならん。\nトワイライトシティで大災難が起ころうとしていることを。",
  ui_story_1016_10160101_191_dialog_content = "あなたが何に目を付けたのか分かりました。",
  ui_story_1016_10160101_192_dialog_content = "賢さをひけらかすのが好きだな。ならばお前が話せ。",
  ui_story_1016_10160101_193_dialog_content = "大元帥との手合わせの機会を狙っているのでしょう？",
  ui_story_1016_10160101_194_dialog_content = "ハハハ、その通りだ！\nレインハトに勝つよりも大きなニュースがあるか！？",
  ui_story_1016_10160101_195_dialog_content = "ずいぶんと大きく出ましたね。",
  ui_story_1016_10160101_196_dialog_content = "できないと言いたいのか？",
  ui_story_1016_10160101_197_dialog_content = "演習で卓越した成績を残し、大元帥との手合わせの機会を得ること自体は、\nそう難しいことではありません。",
  ui_story_1016_10160101_198_dialog_content = "しかし、1対1の勝負で大元帥に勝てるとは思えません。",
  ui_story_1016_10160101_199_dialog_content = "おや、ずいぶんハッキリ言うな。",
  ui_story_1016_10160101_200_dialog_content = "あなたの強みはそもそも個人戦ではありません。\n今の言葉で自尊心が傷つくことはないでしょう？",
  ui_story_1016_10160101_201_dialog_content = "まあな。それは自分でもよく分かっている。",
  ui_story_1016_10160101_202_dialog_content = "だが、レインハトと対決するのは私ではない。",
  ui_story_1016_10160101_203_dialog_content = "！！！",
  ui_story_1016_10160101_204_dialog_content = "どうりで彼を連れてきたわけですね…",
  ui_story_1016_10160101_205_dialog_content = "ヨーゼフにどれだけの勝算があるかは分からん。",
  ui_story_1016_10160101_206_dialog_content = "だが、十分に大きな「声」を上げられるのは確かだ。",
  ui_story_1016_10160101_207_dialog_content = "お二人ともお聞きください。誰かが泣いています。",
  ui_story_1016_10160101_208_dialog_content = "なに？",
  ui_story_1016_10160101_209_dialog_content = "心を静め、耳を澄ましてください。",
  ui_story_1016_10160101_210_dialog_content = "<size=30>ぐすっ…ぐすっ…</size>",
  ui_story_1016_10160101_211_dialog_content = "本当だ！",
  ui_story_1016_10160101_212_dialog_content = "不思議な泣き方ですね。\n悲しみにくれているようには思えません。",
  ui_story_1016_10160101_213_dialog_content = "声が近づいてきます。こちらへ向かってきているようです。",
  ui_story_1016_10160101_214_dialog_content = "ぐすっ…",
  ui_story_1016_10160101_215_dialog_content = "おや？亜人の血統か、めずらしい。",
  ui_story_1016_10160101_216_dialog_content = "どうされましたか？\n先程からあなたの泣き声が聞こえていましたが。",
  ui_story_1016_10160101_217_dialog_content = "え？私のことですか？",
  ui_story_1016_10160101_218_dialog_content = "ごめんなさい、余計な心配をかけたようで…",
  ui_story_1016_10160101_219_dialog_content = "ただ頭が痛かっただけです。持病なんです。",
  ui_story_1016_10160101_220_dialog_content = "泣くほど痛いのか？だとすると、重症のようだが…",
  ui_story_1016_10160101_221_dialog_content = "駅でお見かけました。あなたも演習に参加されるのですね？",
  ui_story_1016_10160101_222_dialog_content = "そうです。メリーっていいます。",
  ui_story_1016_10160101_223_dialog_content = "どちらからいらしたのですか？",
  ui_story_1016_10160101_224_dialog_content = "影ノ街です。",
  ui_story_1016_10160101_225_dialog_content = "何人でいらしたのです？",
  ui_story_1016_10160101_226_dialog_content = "私を入れて3人です。",
  ui_story_1016_10160101_227_dialog_content = "そういえば、着ぐるみ姿の背の低い女の子を見かけませんでしたか？",
  ui_story_1016_10160101_228_dialog_content = "チームのメンバーなんですけど、この辺りで道に迷ったみたいなんです。",
  ui_story_1016_10160101_229_dialog_content = "見かけなかったな。\n今のところ私たちが出くわした演習参加者は君だけだ。",
  ui_story_1016_10160101_230_dialog_content = "そうですか。じゃあ他に用がないようなら、\n私は引き続き探してみます。",
  ui_story_1016_10160101_231_dialog_content = "いろいろありがとうございます。演習で会いましょう。",
  ui_story_1016_10160101_232_dialog_content = "お前、なぜいろいろ問い詰めたのだ？",
  ui_story_1016_10160101_233_dialog_content = "問い詰めてはいませんよ。基本的なことを尋ねただけです。",
  ui_story_1016_10160101_234_dialog_content = "何か怪しいと？",
  ui_story_1016_10160101_235_dialog_content = "今は何とも言えません。もう少し様子を見ましょう。",
  ui_story_1016_10160101_236_dialog_content = "命令について、情報を共有します。",
  ui_story_1016_10160101_237_dialog_content = "我々はどんな代償を払おうとも、\n必ず優勝しなければなりません。",
  ui_story_1016_10160101_238_dialog_content = "何か質問は？",
  ui_story_1016_10160101_239_dialog_content = "ありません。",
  ui_story_1016_10160101_240_dialog_content = "…それは委員会の命令ですか？",
  ui_story_1016_10160101_241_dialog_content = "そうです。",
  ui_story_1016_10160101_242_dialog_content = "分かりました。他に質問はありません。",
  ui_story_1016_10160101_243_dialog_content = "試験段階に入るまでは、特に計画はありません。\n通常通り授業に参加してください。",
  ui_story_1016_10160101_244_dialog_content = "唯一注意すべきことは目立たないことです。\n敵を作ることも、注意を引くことも控えるように。",
  ui_story_1016_10160101_245_dialog_content = "我々に下された命令は機密として厳重に守ってください。\nこの部屋を出たら、一切口外してはなりません。",
  ui_story_1016_10160101_246_dialog_content = "分かりました。",
  ui_story_1016_10160101_247_dialog_content = "承知いたしました。",
  ui_story_1016_10160101_248_dialog_content = "よろしい、伝達事項は以上です。\n解散してください。",
  ui_story_1016_10160101_249_dialog_content = "はい、アクセリアは眠くなってしまいました。",
  ui_story_1016_10160101_250_dialog_content = "では休眠カプセルへ。私が送って行きましょう。",
  ui_story_1016_10160101_251_dialog_content = "アナトリア、ドアを開けてくれますか？",
  ui_story_1016_10160101_252_dialog_content = "はい――",
  ui_story_1016_10160101_253_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_1016_10160101_254_dialog_content = "わぁ！",
  ui_story_1016_10160101_255_dialog_content = "外に誰かいます！",
  ui_story_1016_10160101_256_dialog_content = "誰です？",
  ui_story_1016_10160101_257_dialog_content = "アイタタタ！ドアはもっとゆっくり開けてよ！",
  ui_story_1016_10160101_258_dialog_content = "まったく！これじゃ大きなコブができちゃうよ！",
  ui_story_1016_10160101_259_dialog_content = "…",
  ui_story_1016_10160101_260_dialog_content = "この子は、敵ですか？",
  ui_story_1016_10160101_261_dialog_content = "なんだってそんな目であたしを見るの！？",
  ui_story_1016_10160101_262_dialog_content = "べ、別に盗み聞きなんてしてないんだから！",
  ui_story_1016_10160101_263_dialog_content = "あなたが盗み聞きをしていたとは言っていません。",
  ui_story_1016_10160101_264_dialog_content = "君は…",
  ui_story_1016_10160101_265_dialog_content = "ミンチ！ここにいたんですね！",
  ui_story_1016_10160101_266_dialog_content = "カナン城は道が複雑だって言いましたよね？\nひとりで歩き回っちゃいけません。",
  ui_story_1016_10160101_267_dialog_content = "メリー！遅い！",
  ui_story_1016_10160101_268_dialog_content = "お仲間ですか？あなた方は…",
  ui_story_1016_10160101_269_dialog_content = "申し訳ありません。友人がご迷惑をお掛けしました。",
  ui_story_1016_10160101_270_dialog_content = "カナン城は初めてなのですが、何しろ地形が複雑で、\n迷ってしまったのです。",
  ui_story_1016_10160101_271_dialog_content = "お邪魔して申し訳ありません。",
  ui_story_1016_10160101_272_dialog_content = "ディシス、なんで謝るの！？あっちがぶつかってきたんだよ！",
  ui_story_1016_10160101_273_dialog_content = "ミンチ、落ち着いてください。\n新しいお友だちには礼儀正しくするべきです。",
  ui_story_1016_10160101_274_dialog_content = "…",
  ui_story_1016_10160101_275_dialog_content = "それでは僕たちは失礼いたします。",
  ui_story_1016_10160101_276_dialog_content = "そうですね。まだ道を覚えてるうちに帰りましょう。",
  ui_story_1016_10160101_277_dialog_content = "フン、じゃあね！ベーッ。",
  ui_story_1016_10160101_278_dialog_content = "あの3人は影ノ街から来た演習参加者です。",
  ui_story_1016_10160101_279_dialog_content = "このままにしていてよいのですか？\n私たちの話を聞かれていたかもしれません。",
  ui_story_1016_10160101_280_dialog_content = "聞かれていたとしても、あとで何とかなります。",
  ui_story_1016_10160101_281_dialog_content = "さあ、戻って休むことにしましょう。",
  ui_story_1016_10160101_282_dialog_content = "明日からの授業に備えなくては。",
  ui_story_1016_10160101_283_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ、タッ…</color>",
  ui_story_1016_10160101_284_dialog_content = "奴ら…行ったか？",
  ui_story_1016_10160101_285_dialog_content = "ええ、今立ち去った衛兵で最後ね。",
  ui_story_1016_10160101_286_dialog_content = "ヘリオス、身体の調子はどう？",
  ui_story_1016_10160101_287_dialog_content = "気にするな…大したキズじゃない。",
  ui_story_1016_10160101_288_dialog_content = "俺は…いつでも戦える。",
  ui_story_1016_10160101_289_dialog_content = "ここはカナン城よ。\n見つかれば、啓光の全兵力が私たちに向かってくるわ。",
  ui_story_1016_10160101_290_dialog_content = "力だけでは突破できない。",
  ui_story_1016_10160101_291_dialog_content = "だが…",
  ui_story_1016_10160101_292_dialog_content = "もう少し辛抱して。こういう時こそ冷静にならなくちゃいけないわ。",
  ui_story_1016_10160101_293_dialog_content = "もう少し時間が必要よ。",
  ui_story_1016_10160101_294_dialog_content = "何を待ってるんだ？",
  ui_story_1016_10160101_295_dialog_content = "「<color=#FFB400>ファントム</color>」よ。",
  ui_story_1016_10160201_1_dialog_content = "<anim type=Shake>ふわぁ――</anim>よく眠れなかったな。",
  ui_story_1016_10160201_2_dialog_content = "この街はどこもかしこも機械油の匂いがしてかなわん。",
  ui_story_1016_10160201_3_dialog_content = "実験室！？こんな所に連れてきてどうするつもり？",
  ui_story_1016_10160201_4_dialog_content = "実験台になるために啓光に来たワケじゃないわ！",
  ui_story_1016_10160201_5_dialog_content = "あ、見慣れた場所だ。",
  ui_story_1016_10160201_6_dialog_content = "何をするのか分かったよ。",
  ui_story_1016_10160201_7_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_1016_10160201_8_dialog_content = "はい、みんな！静かにして！",
  ui_story_1016_10160201_9_dialog_content = "教官のガルーだよ。\n科学技術に関する授業は全部あたしが担当するからよろしくね。",
  ui_story_1016_10160201_10_dialog_content = "キミたちのほとんどは落ち着いて研究する気なんてないのはもちろん分かってるよ。\nあたしも暗～い授業にはしたくないんだ。",
  ui_story_1016_10160201_11_dialog_content = "だから、最初の授業はみんなのために、一番おもしろ…\n最先端の科学研究の成果を準備したよ！",
  ui_story_1016_10160201_12_dialog_content = "さあ、紹介するね。これが啓光が新しく研究開発した訓練装置――",
  ui_story_1016_10160201_13_dialog_content = "「<color=#FFB400>戦闘シミュレーション</color>」だよ！",
  ui_story_1016_10160201_14_dialog_content = "やっぱり。",
  ui_story_1016_10160201_15_dialog_content = "ヘッドセットだろう？何の訓練ができるというのだ？",
  ui_story_1016_10160201_16_dialog_content = "これを使えば、実際に武器を使うよりも\nずっと効果的な訓練ができるんだ！",
  ui_story_1016_10160201_17_dialog_content = "訓練で向上させるのが最も難しい能力は何？",
  ui_story_1016_10160201_18_dialog_content = "身体能力？それとも光力術？",
  ui_story_1016_10160201_19_dialog_content = "戦闘能力です。",
  ui_story_1016_10160201_20_dialog_content = "そう、戦闘能力を養うのが一番難しいんだよ。",
  ui_story_1016_10160201_21_dialog_content = "戦場で起こりうる事態は、\n実際に戦場に出ないと経験できないよね。",
  ui_story_1016_10160201_22_dialog_content = "でも戦場は残酷だから、兵士全員がその経験を持ち帰れるワケじゃない。",
  ui_story_1016_10160201_23_dialog_content = "「バーチャル」の戦闘でない限りね。",
  ui_story_1016_10160201_24_dialog_content = "バーチャルの戦闘なんて出来るの…？",
  ui_story_1016_10160201_25_dialog_content = "そのバーチャルの戦闘こそ最初の授業内容なんだ！",
  ui_story_1016_10160201_26_dialog_content = "今あたしが持ってるのと同じ装置をこの後全員に配るよ。",
  ui_story_1016_10160201_27_dialog_content = "ヘッドセットをつけると、みんな一緒にバーチャルの戦場の中に入れるんだ。",
  ui_story_1016_10160201_28_dialog_content = "そこでは光力術も武器もいつも通り使えて、\n立ち向かうべき敵はもちろん、みんなよく知ってる暗鬼だよ。",
  ui_story_1016_10160201_29_dialog_content = "「戦死」しちゃうまで、現実の戦争だと思って戦ってね。",
  ui_story_1016_10160201_30_dialog_content = "ハハハ、これはなかなか面白そうではないか。",
  ui_story_1016_10160201_31_dialog_content = "現実と同じレベルの戦場を復元できるかどうかは分からんがな。",
  ui_story_1016_10160201_32_dialog_content = "さあ、みんなやる気が出て来たみたいだね！",
  ui_story_1016_10160201_33_dialog_content = "今すぐヘッドセットを配るから、\n早速今日の戦闘シミュレーションを始めるよ！",
  ui_story_1016_10160201_34_dialog_content = "戦闘中のみんなの様子は得点として計算されて、\n隣のスクリーンに表示されるんだ。",
  ui_story_1016_10160201_35_dialog_content = "客観的な数字があれば、どんな人材も埋もれたりしないよ。\nみんな頑張って自分の才能を思う存分発揮してね！",
  ui_story_1016_10160201_36_dialog_content = "<color=#e8d9bb>シミュレーションシステムの戦場内に入りました</color>",
  ui_story_1016_10160201_37_dialog_content = "使い方は前と同じなんだね。",
  ui_story_1016_10160201_38_dialog_content = "バイスとカレンはどこだろう？\nまだヘッドセットをつけてないのかな？",
  ui_story_1016_10160201_39_dialog_content = "うっ、ここは…",
  ui_story_1016_10160201_40_dialog_content = "わあ！いきなり画面が飛び出してきたわ！",
  ui_story_1016_10160201_41_dialog_content = "このシミュレーションシステム、前よりよく出来てるみたいね。\n身体の感覚が現実とほとんど変わらないわ。",
  ui_story_1016_10160201_42_dialog_content = "現実に近い戦場ほど僕たちの危機意識も上がるのかもしれないね。",
  ui_story_1016_10160201_43_dialog_content = "周りの景色からすると、ここは啓光の防衛線かな？",
  ui_story_1016_10160201_44_dialog_content = "<color=#e8d9bb>参加者全員指定の位置に就きました</color>",
  ui_story_1016_10160201_45_dialog_content = "<color=#e8d9bb>今回の戦場は啓光で実際に起こった戦場を復元しています</color>",
  ui_story_1016_10160201_46_dialog_content = "<color=#e8d9bb>突然襲ってきた暗鬼の大群が防衛線を破り、啓光は多大な損害を被りました</color>",
  ui_story_1016_10160201_47_dialog_content = "<color=#e8d9bb>本システムでは参加者の皆さんの戦闘力に合わせ、\n戦闘規模を3人のチームで対応できるレベルに下げています</color>",
  ui_story_1016_10160201_48_dialog_content = "<color=#e8d9bb>各チームともランダムで戦場周囲に配置されています。\n皆さんの健闘を祈ります</color>",
  ui_story_1016_10160201_49_dialog_content = "<color=#e8d9bb>戦闘開始</color>",
  ui_story_1016_10160201_50_dialog_content = "各チーム別々の場所に振り分けられてたのね。",
  ui_story_1016_10160201_51_dialog_content = "そうみたいね。おそらくチーム間の干渉を避けるためでしょう。",
  ui_story_1016_10160201_52_dialog_content = "啓光で本当に起こった戦争を復元してるって言ってたね。\nその戦争がどんなものだったか分かればいいんだけどな。",
  ui_story_1016_10160201_53_dialog_content = "バイスはいつどこで起こった戦争か分かる？",
  ui_story_1016_10160201_54_dialog_content = "分からないわ。啓光の周辺で起こった戦争は数えきれない程あるし、\n防衛線が崩壊したこともたくさんあるから。",
  ui_story_1016_10160201_55_dialog_content = "歴史的に見ても、それが啓光防衛線の常態だったと言えるわ。",
  ui_story_1016_10160201_56_dialog_content = "戦争が常態になってたのか…",
  ui_story_1016_10160201_57_dialog_content = "暗鬼が現れたわ！",
  ui_story_1016_10160201_58_dialog_content = "この数…本当に3人で倒せる数なのかしら？",
  ui_story_1016_10160201_59_dialog_content = "うーん…元になった戦争では、\n防衛線が暗鬼の大群に破られてるんだよね。",
  ui_story_1016_10160201_60_dialog_content = "ということは、戦闘規模を下げたとしても、\n僕たちには防衛線崩壊って状況を変えられないんじゃないかな？",
  ui_story_1016_10160201_61_dialog_content = "暗鬼の大群を目の前にして僕たちが今感じてる無力感は、\nきっと当時の兵士たちも同じだったんだろうな…",
  ui_story_1016_10160201_62_dialog_content = "そうね。シミュレーションで幸いだったわ。",
  ui_story_1016_10160201_63_dialog_content = "とにかく、力を尽くしましょう！",
  ui_story_1016_10160201_64_dialog_content = "そうよ、行くわよ！",
  ui_story_1016_10160202_1_dialog_content = "カレン！急いで後ろに下がって！",
  ui_story_1016_10160202_2_dialog_content = "私もそうしたいわ。でも…",
  ui_story_1016_10160202_3_dialog_content = "何だか倒せば倒すほど暗鬼が増えてる気がする！",
  ui_story_1016_10160202_4_dialog_content = "本当だね。僕たちの方へ集まって来てるみたいだ。",
  ui_story_1016_10160202_5_dialog_content = "何とか抜け出さないと、暗鬼の群れに飲まれちゃう…",
  ui_story_1016_10160202_6_dialog_content = "あら？カレン殿下！",
  ui_story_1016_10160202_7_dialog_content = "ベルタ！？どうしてここに？",
  ui_story_1016_10160202_8_dialog_content = "あ、暗鬼の大群に飲まれてバラバラになってしまったんです。",
  ui_story_1016_10160202_9_dialog_content = "1人になってしまったので完全に受け身となり、\n戦いながら退くしかなく…",
  ui_story_1016_10160202_10_dialog_content = "途中で他の参加者にも会いました…",
  ui_story_1016_10160202_11_dialog_content = "おしゃべりはその辺にして、敵に集中してください！",
  ui_story_1016_10160202_12_dialog_content = "言われなくたって、もちろん集中してるわ！",
  ui_story_1016_10160202_13_dialog_content = "アナトリアもいたの！？確かインゲルのチームだったよね？",
  ui_story_1016_10160202_14_dialog_content = "君たちもバラバラになっちゃったの？",
  ui_story_1016_10160202_15_dialog_content = "はい。戦闘中他チームの邪魔が入りまして。",
  ui_story_1016_10160202_16_dialog_content = "ちょっと！「他チームの邪魔」ってどういう意味！？\n協力してるじゃん？",
  ui_story_1016_10160202_17_dialog_content = "足を引っ張る行為は「邪魔」以外の何ものでもありません。",
  ui_story_1016_10160202_18_dialog_content = "チッ！",
  ui_story_1016_10160202_19_dialog_content = "見たことないね。君は…",
  ui_story_1016_10160202_20_dialog_content = "もうダメだわ、PlayerName！敵が多すぎる！",
  ui_story_1016_10160202_21_dialog_content = "このままじゃ持たないわ！",
  ui_story_1016_10160202_22_dialog_content = "そうだね。暗鬼の数はどんどん増えるばかりだ…",
  ui_story_1016_10160202_23_dialog_content = "ベルタ、アナトリア！\nそれから名前をまだ聞いてない人！",
  ui_story_1016_10160202_24_dialog_content = "<size=45>ミンチよ！！</size>",
  ui_story_1016_10160202_25_dialog_content = "皆で協力しよう！\n戦いの中心から退けるかどうかやってみるんだ！",
  ui_story_1016_10160202_26_dialog_content = "今から協力って言われても…私はもう手いっぱいよ…",
  ui_story_1016_10160202_27_dialog_content = "あ…うう――！",
  ui_story_1016_10160202_28_dialog_content = "<size=45>ベルタ！！</size>",
  ui_story_1016_10160202_29_dialog_content = "まずいことになりました。さきほどまでベルタさんと戦っていた敵が\nこちらへ一気に流れ込んでいます。",
  ui_story_1016_10160202_30_dialog_content = "わああああ！暗鬼が飛び掛かってくるよ！\nどうすればいいの！？",
  ui_story_1016_10160202_31_dialog_content = "出来る限り持ちこたえるしかないでしょうね…",
  ui_story_1016_10160202_32_dialog_content = "君たちは後に向かって突破を試みて！\nそっちの方向なら暗鬼の数がわずかに少ない！",
  ui_story_1016_10160202_34_dialog_content = "PlayerName、気を付けて！",
  ui_story_1016_10160202_35_dialog_content = "うわ――",
  ui_story_1016_10160202_36_dialog_content = "後ろよ！あなたたちの後ろに――",
  ui_story_1016_10160202_37_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1016_10160202_38_dialog_content = "<color=#e8d9bb>戦闘シミュレーションシステムからログアウトしました</color>",
  ui_story_1016_10160202_39_dialog_content = "ふぅ…戻ってきたんだね？",
  ui_story_1016_10160202_40_dialog_content = "いくらシミュレーションシでも、\n死が迫ってくる感じはやっぱりつらいな…",
  ui_story_1016_10160202_41_dialog_content = "バイスとカレンは？",
  ui_story_1016_10160202_42_dialog_content = "ふぅ…やっぱり倒されちゃったのね。",
  ui_story_1016_10160202_43_dialog_content = "ええ。あれだけの数の暗鬼を相手にしたら、\n何をしても無駄だわ。",
  ui_story_1016_10160202_44_dialog_content = "君たちも戻ってきたんだね。\n戦闘シミュレーションに入った感想はどう？",
  ui_story_1016_10160202_45_dialog_content = "想像以上にリアルだったわ。\nガルーの言った通り、これなら戦闘能力を養えるわね。",
  ui_story_1016_10160202_46_dialog_content = "今のような緊迫した戦闘は現実ではなかなか経験できないわ。",
  ui_story_1016_10160202_47_dialog_content = "実際の戦闘だったら、私たちきっと無事じゃいられないわね。",
  ui_story_1016_10160202_48_dialog_content = "そうだね。実際に経験してみて、\n啓光が直面する危機がどんなに厳しいものか身に染みて感じたよ。",
  ui_story_1016_10160202_49_dialog_content = "軍人はいつも…敗北と隣り合わせで戦ってるんだね。",
  ui_story_1016_10160202_50_dialog_content = "そうね…",
  ui_story_1016_10160202_51_dialog_content = "おしゃべりに花を咲かせてないで、\nシミュレーションシから出て来た学生はこっちを見て。",
  ui_story_1016_10160202_52_dialog_content = "みんな今の戦闘でそれぞれ感じたこと、\nシミュレーションシステムについて思うところもあったんじゃない？",
  ui_story_1016_10160202_53_dialog_content = "これは戦闘シミュレーションに関する事後アンケートだよ。",
  ui_story_1016_10160202_54_dialog_content = "みんな今のうちに記入しといて！",
  ui_story_1016_10160202_55_dialog_content = "うーん…アンケートも答えなきゃなのか…",
  ui_story_1016_10160202_56_dialog_content = "ガルー、もしかして僕たちでテストしてるの？",
  ui_story_1016_10160202_57_dialog_content = "もう、そんな言い方しないでよ！",
  ui_story_1016_10160202_58_dialog_content = "キミたちの回答は貴重なデータとして、\nシミュレーションシステムの性能向上に役立つんだよ。",
  ui_story_1016_10160202_59_dialog_content = "みんなにとってもいい事じゃん。でしょ？",
  ui_story_1016_10160202_60_dialog_content = "分かった、分かったよ…",
  ui_story_1016_10160202_61_dialog_content = "<color=#e8d9bb>20分後</color>",
  ui_story_1016_10160202_62_dialog_content = "ようやく書き終わった。長いアンケートだったな…",
  ui_story_1016_10160202_63_dialog_content = "本当ね。手が痛くなっちゃったわ！",
  ui_story_1016_10160202_64_dialog_content = "アンケートの最後に今回のシミュレーションの点数を記入する欄があるわ。\n私たちの点数はいくつなのかしら？",
  ui_story_1016_10160202_65_dialog_content = "そうだね。自分たちじゃいい出来だったのかどうかよく分からないね。",
  ui_story_1016_10160202_66_dialog_content = "ガルー、点数はどこで調べられるの？",
  ui_story_1016_10160202_67_dialog_content = "あ、それはもうちょっと待ってて。",
  ui_story_1016_10160202_68_dialog_content = "まだ数人戦闘シミュレーションから出てきてないんだ。",
  ui_story_1016_10160202_69_dialog_content = "まだ出てきてないの！？こんなに経つのに…？",
  ui_story_1016_10160202_70_dialog_content = "<color=#e8d9bb>戦闘シミュレーションが終了しました</color>",
  ui_story_1016_10160202_71_dialog_content = "<color=#e8d9bb>終了時の状況に基づき、戦況を判定します――</color>",
  ui_story_1016_10160202_72_dialog_content = "<color=#e8d9bb>結果は、光霊の勝利です</color>",
  ui_story_1016_10160202_73_dialog_content = "え？光霊が勝ったの？",
  ui_story_1016_10160202_74_dialog_content = "<size=45>光霊の勝ち！？</size>",
  ui_story_1016_10160202_75_dialog_content = "あり得ないよ。本当にこのステージをクリアできる人がいるの…？",
  ui_story_1016_10160202_76_dialog_content = "最後にシミュレーションから出てきたのは誰――",
  ui_story_1016_10160202_77_dialog_content = "ふぅ。ヘッドセットを長く着けていたら気分が悪くなった。",
  ui_story_1016_10160202_78_dialog_content = "なかなかだ。\nシミュレーションだが、かなりリアルな戦場だった。",
  ui_story_1016_10160202_79_dialog_content = "戦火の中に常に身を置いているだけのことはある。\n戦いに関する啓光の認識は非常に正確だ。",
  ui_story_1016_10160202_80_dialog_content = "しかし、リアルすぎるのも問題です。",
  ui_story_1016_10160202_81_dialog_content = "シミュレーションの元となった戦場さえ知っていれば、\n戦況の変化を読むのは難しくありません。",
  ui_story_1016_10160202_82_dialog_content = "よって、難易度が大幅に下がってしまいます。",
  ui_story_1016_10160202_83_dialog_content = "い…今の戦いの難易度が…低い？",
  ui_story_1016_10160202_84_dialog_content = "私はシミュレーション内の環境が好きになれません。",
  ui_story_1016_10160202_85_dialog_content = "私がいくら敬虔に呼びかけようとも、\n答えてくれるのは偽りの「光」だけです。",
  ui_story_1016_10160202_86_dialog_content = "バカ真面目になるな、ヨーゼフ。\nゲームとでも思えばいいだろう。",
  ui_story_1016_10160202_87_dialog_content = "スクリーンに成績が表示されたよ！",
  ui_story_1016_10160202_88_dialog_content = "レオたちの点数…高いな…",
  ui_story_1016_10160202_89_dialog_content = "文句ナシのトップね…",
  ui_story_1016_10160202_90_dialog_content = "同じ戦場で戦ってたんだよね？",
  ui_story_1016_10160202_91_dialog_content = "あんな膨大な数の暗鬼を相手に、\nどうやって勝ったんだろう…？",
  ui_story_1016_10160202_92_dialog_content = "彼らの戦い方を見ました。",
  ui_story_1016_10160202_93_dialog_content = "彼らが…あの防衛線を破壊した暗鬼の波を「生み出した」んです…",
  ui_story_1016_10160202_94_dialog_content = "え！？",
  ui_story_1016_10160202_95_dialog_content = "暗鬼の波を彼らが生み出した？あり得ないわ！",
  ui_story_1016_10160202_96_dialog_content = "本当なんです。あのチームは戦いながら暗鬼の動きを誘導し、\n徐々に一カ所に集めて行ったんです。",
  ui_story_1016_10160202_97_dialog_content = "その後暗鬼を迂回しながら機をうかがい、\n数の強みを発揮できない狭い地形に入ったところで壊滅を図りました。",
  ui_story_1016_10160202_98_dialog_content = "まるで羊飼いに追われるヒツジの群れのように、\n一匹また一匹と倒されていったんです…",
  ui_story_1016_10160202_99_dialog_content = "暗鬼を誘導する…？そんな戦い方があるんだね…",
  ui_story_1016_10160202_100_dialog_content = "大した戦略でもない。味方の10倍、100倍の敵を前にすれば、\n誰でも知恵を絞るほかないだろう？",
  ui_story_1016_10160202_101_dialog_content = "本に書かれている内容など思い出しても無意味だ。\n勝つ可能性のない戦闘に勝つ方法など、どの本にも書いていないのだからな。",
  ui_story_1016_10160202_102_dialog_content = "自分の頭の中にあるバカげた、荒唐無稽な方法を\n片っ端から引っ張りだして試すほかないのさ。",
  ui_story_1016_10160202_103_dialog_content = "何度も試して幸運にもまだ戦死していなかったのなら、\nそれはお前が戦場での必勝法を習得したということだ。",
  ui_story_1016_10160202_104_dialog_content = "（そうだった…初めて会った時も、レオは不思議な戦い方をしてた）",
  ui_story_1016_10160202_105_dialog_content = "（トワイライトシティの人は戦うことに関して、\n僕たちとは比べものにならない想像力を持ってるんだな…）",
  ui_story_1016_10160202_106_dialog_content = "うーん、すごく印象深いシミュレーションになったね。\nみんな黙りこくっちゃってるね。",
  ui_story_1016_10160202_107_dialog_content = "みんなまだまだだね。\n得点ランキングの数字を見つめてる姿は…",
  ui_story_1016_10160202_108_dialog_content = "初めて銃を見た子供みたいだよ。",
  ui_story_1016_10160301_1_dialog_content = "<color=#e8d9bb>1週間後</color>",
  ui_story_1016_10160301_2_dialog_content = "あれ？この先は事務室だ。道を間違えちゃったのかな？",
  ui_story_1016_10160301_3_dialog_content = "確か教室は…",
  ui_story_1016_10160301_4_dialog_content = "PlayerNameさん、こちらで何をされているのですか？",
  ui_story_1016_10160301_5_dialog_content = "授業がもうすぐ始まりますよ。",
  ui_story_1016_10160301_6_dialog_content = "アナトリア！よかった！",
  ui_story_1016_10160301_7_dialog_content = "教室までどう行けばいいか知ってる？\n廊下をグルグル回ってたから目まで回りそうだよ。あはは。",
  ui_story_1016_10160301_8_dialog_content = "そういうことでしたか。では、私に付いてきてください。",
  ui_story_1016_10160301_9_dialog_content = "私に会えて幸いでしたね。\n遅刻すれば単位を引かれてしまうかもしれませんから。",
  ui_story_1016_10160301_10_dialog_content = "今日皆が単位がどうのって話で盛り上がってたけど、\n単位って何？",
  ui_story_1016_10160301_11_dialog_content = "昨日配られたしおりをご覧になっていないのですか？",
  ui_story_1016_10160301_12_dialog_content = "昨日はガルーにソラヴァンのテストに引っ張り出されたから、\nまだ見てないんだ。",
  ui_story_1016_10160301_13_dialog_content = "ならば私が簡単に説明して差し上げましょう。",
  ui_story_1016_10160301_14_dialog_content = "今日から皆さんの授業中の成績は、\n単位として記録されます。",
  ui_story_1016_10160301_15_dialog_content = "演習の訓練段階が終了するまで、\n1人1人の成績は単位として蓄積されていきます。",
  ui_story_1016_10160301_16_dialog_content = "つまり、最終的な単位数が皆さんの能力の指標になるというわけです。\nですが、単位にはさらに重要な使い道があります。",
  ui_story_1016_10160301_17_dialog_content = "単位は試験段階における皆さんの力になります。",
  ui_story_1016_10160301_18_dialog_content = "力になる？",
  ui_story_1016_10160301_19_dialog_content = "試験の前に単位を物資と交換できるので、\n総合力を強化できます。",
  ui_story_1016_10160301_20_dialog_content = "単位が多ければ多いほど、それだけ優位に立てるというわけです。",
  ui_story_1016_10160301_21_dialog_content = "ですから、皆さんより多くの単位を獲得しようと張り切っているのです。",
  ui_story_1016_10160301_22_dialog_content = "どうりで競い合いの空気が濃くなってきたわけだね。",
  ui_story_1016_10160301_23_dialog_content = "そうですね。\nトップに立つには、かなり神経を使うでしょう。",
  ui_story_1016_10160301_24_dialog_content = "教室に着きました。時間もちょうどよかったようです。",
  ui_story_1016_10160301_25_dialog_content = "教室までの道は覚えましたか？",
  ui_story_1016_10160301_26_dialog_content = "あはは、覚えられてるといいな。",
  ui_story_1016_10160301_27_dialog_content = "この後は何の授業だったっけ？",
  ui_story_1016_10160301_28_dialog_content = "戦闘の実技授業です。",
  ui_story_1016_10160301_29_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_1016_10160301_30_dialog_content = "あら、そこの2人！",
  ui_story_1016_10160301_31_dialog_content = "あと20秒で遅刻だったわね。",
  ui_story_1016_10160301_32_dialog_content = "ギリギリだった…",
  ui_story_1016_10160301_33_dialog_content = "まあいいわ。最後の2人もそろったことだし、授業を始めるわ。",
  ui_story_1016_10160301_34_dialog_content = "私は啓光連邦軍近衛兵団長のラスよ。\n今日のあんたたちの教官でもあるわ。",
  ui_story_1016_10160301_35_dialog_content = "この授業で学ぶことは簡単――ケンカよ。",
  ui_story_1016_10160301_36_dialog_content = "ケンカだと？",
  ui_story_1016_10160301_37_dialog_content = "どうせ「ケンカなんて学ぶ必要ある？」って思ってるんでしょ？",
  ui_story_1016_10160301_38_dialog_content = "それにここにいるのは皆、\n少なからず戦闘力に自信のある人たちよね。",
  ui_story_1016_10160301_39_dialog_content = "でも、多くの学生がまだうまく戦えてないことも確かよ。",
  ui_story_1016_10160301_40_dialog_content = "今日私が教えるのはどうしたら勝てるかではなく、\nどうしたら完璧に勝てるかよ。",
  ui_story_1016_10160301_41_dialog_content = "勝てる戦いで、できるだけ戦いのスピードを上げ、余力を多く残す――\nそれでこそうまく次の戦闘につなげられるの。",
  ui_story_1016_10160301_42_dialog_content = "勝利なんてそう簡単なものじゃないの。\n細かいところまで全て完璧に戦わないとダメよ。",
  ui_story_1016_10160301_43_dialog_content = "うう、そう言われてみれば、確かにそうね…",
  ui_story_1016_10160301_44_dialog_content = "戦闘の効率ってことに関しては、\n特別な訓練を受けたことがないわ。",
  ui_story_1016_10160301_45_dialog_content = "道理は確かにその通りだが、\n「完璧」もまた簡単なことではないよ。",
  ui_story_1016_10160301_46_dialog_content = "教官殿は完璧にできるのかな？",
  ui_story_1016_10160301_47_dialog_content = "あんた、私の力を疑ってるの？",
  ui_story_1016_10160301_48_dialog_content = "いや、授業から何も学べないのではと心配になっただけだ。",
  ui_story_1016_10160301_49_dialog_content = "ふん、私はあんたが私のしごきに付いてこられないんじゃないかって心配だわ。",
  ui_story_1016_10160301_50_dialog_content = "無駄話はここまでにして、\n全員チームごとに分かれて並びなさい。",
  ui_story_1016_10160301_51_dialog_content = "今日の授業は実技授業よ。\n普段から厳しい訓練を積む啓光の兵士があんたたちの相手になるわ。",
  ui_story_1016_10160301_52_dialog_content = "第1隊、前へ！",
  ui_story_1016_10160301_53_dialog_content = "<size=45>はい！</size>",
  ui_story_1016_10160301_54_dialog_content = "学生たちに啓光式の挨拶をしてやりなさい。",
  ui_story_1016_10160301_55_dialog_content = "<size=45>はい！</size>",
  ui_story_1016_10160301_56_dialog_content = "あ、そうだわ。そちらの白夜城の騎士さんのこと、\nしっかり「面倒見て」あげて。",
  ui_story_1016_10160301_57_dialog_content = "物足りないようなら、\n授業後私にサシの勝負を申し込んでくれてもいいわ。",
  ui_story_1016_10160301_58_dialog_content = "遠慮しておこう。\n授業に身を入れた方がよさそうだからな。",
  ui_story_1016_10160301_59_dialog_content = "少なくとも単位をもらえる。そうだな？",
  ui_story_1016_10160301_60_dialog_content = "その通りね。単位を稼げる最初のチャンスだもの。\n全力でいくわよ。",
  ui_story_1016_10160301_61_dialog_content = "インゲル、私はどうしたらいいですか？",
  ui_story_1016_10160301_62_dialog_content = "いつもより少し軽めでいきましょう。",
  ui_story_1016_10160301_63_dialog_content = "<size=32>この学生たち…何だかちょっと怖くなってきた…</size>",
  ui_story_1016_10160301_64_dialog_content = "<size=32>お、俺もだ…</size>",
  ui_story_1016_10160401_1_dialog_content = "<color=#e8d9bb>1ヶ月後</color>",
  ui_story_1016_10160401_2_dialog_content = "はい、では今日の授業はここまでにしましょう。",
  ui_story_1016_10160401_3_dialog_content = "ありがとうございました。",
  ui_story_1016_10160401_4_dialog_content = "やったわね、PlayerName。\n今日も単位をたくさんもらえたわ！",
  ui_story_1016_10160401_5_dialog_content = "ふぅ…皆やる気満々だから、単位を取るのも大変だね。",
  ui_story_1016_10160401_6_dialog_content = "白熱した争いになってるわね。\nチーム間の競争は今後激しくなるばかりでしょうね。",
  ui_story_1016_10160401_7_dialog_content = "ところで、今日の単位ランキングは見た？",
  ui_story_1016_10160401_8_dialog_content = "まだよ。私たちは何位だった？",
  ui_story_1016_10160401_9_dialog_content = "第3位よ。",
  ui_story_1016_10160401_10_dialog_content = "わ、また1ランク上がったね！",
  ui_story_1016_10160401_11_dialog_content = "いい調子ね。トップ2の状況はどう？",
  ui_story_1016_10160401_12_dialog_content = "レオのチームがダントツ1位よ。\n他を大きく引き離しいるわ。",
  ui_story_1016_10160401_13_dialog_content = "今の点数差を埋めるのは…どのチームにも難しいでしょうね。",
  ui_story_1016_10160401_14_dialog_content = "やっぱりレオたちか…",
  ui_story_1016_10160401_15_dialog_content = "第2位はインゲルチームよ。\n最近になってようやく芽を出し始めた感じね。",
  ui_story_1016_10160401_16_dialog_content = "あのチームの強みは苦手がないことね。\nどの授業でもいい成績を収めるから、徐々に上位を占めるようになったわ。",
  ui_story_1016_10160401_17_dialog_content = "僕たちとはどれくらいの差があるの？",
  ui_story_1016_10160401_18_dialog_content = "インゲルチームとレオチームの点数差の半分ってところかしら。",
  ui_story_1016_10160401_19_dialog_content = "ずいぶん離されてるみたいだね…",
  ui_story_1016_10160401_20_dialog_content = "インゲルはどの授業でも高い質で要件をクリアするから、\nあのチームを越えるのは確かに難しいわね。",
  ui_story_1016_10160401_21_dialog_content = "ただ、授業外ならそうとも限らないわ。",
  ui_story_1016_10160401_22_dialog_content = "授業外？",
  ui_story_1016_10160401_23_dialog_content = "昨日他のチームが授業以外で自主訓練しているのを見たわ。",
  ui_story_1016_10160401_24_dialog_content = "その訓練結果を報告すると、同じように単位がもらえるの。",
  ui_story_1016_10160401_25_dialog_content = "え？そんなやり方もあるの？",
  ui_story_1016_10160401_26_dialog_content = "そうなの。どうやら主催者の意図は\n参加者の自主的な訓練を促進することにあるようね。",
  ui_story_1016_10160401_27_dialog_content = "授業外の訓練でもらえる単位は少ないけれど、\n塵も積もれば山となると言うでしょう？",
  ui_story_1016_10160401_28_dialog_content = "この方法なら、私たちもインゲルチームを追い越せるかもしれないわ。",
  ui_story_1016_10160401_29_dialog_content = "そうね！いい方法だと思うわ！",
  ui_story_1016_10160401_30_dialog_content = "本当に競争が激しくなってきてるんだね。\n授業外も競い合わなきゃなんて…",
  ui_story_1016_10160401_31_dialog_content = "そうと決まれば、スケジュールを立てよう。",
  ui_story_1016_10160401_32_dialog_content = "どうすれば一番効率よく訓練できるか考えよう。",
  ui_story_1016_10160401_33_dialog_content = "<color=#e8d9bb>翌日、演習の教室</color>",
  ui_story_1016_10160401_34_dialog_content = "授業後も教室に残る学生たちが増えていますね。",
  ui_story_1016_10160401_35_dialog_content = "隊長、私たちも授業外訓練をしますか？",
  ui_story_1016_10160401_36_dialog_content = "何かやりたい訓練項目があるのなら、やっても構いません。",
  ui_story_1016_10160401_37_dialog_content = "ただし、単位のためというなら、その必要はありません。",
  ui_story_1016_10160401_38_dialog_content = "単位が多ければ、最終試験で有利になるようですが…\nならば私たちにとっても重要なのでは？",
  ui_story_1016_10160401_39_dialog_content = "その通りですが、我々はこの演習に\nそこまで本気になる必要はありませんから…",
  ui_story_1016_10160401_40_dialog_content = "インゲル、見てください。",
  ui_story_1016_10160401_41_dialog_content = "あそこの床と指導係、カラフルに染まっています。",
  ui_story_1016_10160401_42_dialog_content = "「カラフル」？",
  ui_story_1016_10160401_43_dialog_content = "どういうことです？何かの塗料ですか？",
  ui_story_1016_10160401_44_dialog_content = "さきほどダミーが突然爆発しました。",
  ui_story_1016_10160401_45_dialog_content = "…",
  ui_story_1016_10160401_46_dialog_content = "ダミーの中に色とりどりの塗料が仕込まれていたのだと、\nアクセリアは思います。",
  ui_story_1016_10160401_47_dialog_content = "ビビアン長官たちが用意したものでしょうか？",
  ui_story_1016_10160401_48_dialog_content = "このような子どもじみたイタズラはなさらないと思いますが。",
  ui_story_1016_10160401_49_dialog_content = "<color=#e8d9bb>バンッ――！</color>",
  ui_story_1016_10160401_50_dialog_content = "<size=45>銃声ですか！？</size>",
  ui_story_1016_10160401_51_dialog_content = "何をしてるの！！",
  ui_story_1016_10160401_52_dialog_content = "俺は…",
  ui_story_1016_10160401_53_dialog_content = "クロエ、大丈夫？",
  ui_story_1016_10160401_54_dialog_content = "大丈夫です。弾は飛んできていませんから。ただの紙吹雪です。",
  ui_story_1016_10160401_55_dialog_content = "ただ大きな音だったので、\n耳がまだウォンウォン鳴っています…",
  ui_story_1016_10160401_56_dialog_content = "いったいどういうこと？\nどうしてこんな事故が起こったのかしら！？",
  ui_story_1016_10160401_57_dialog_content = "ベルタさん、その人は悪くありません。",
  ui_story_1016_10160401_58_dialog_content = "ほら、本人もすごく驚いてますよ。",
  ui_story_1016_10160401_59_dialog_content = "え？",
  ui_story_1016_10160401_60_dialog_content = "…そうなんです。さっき引き金を引いた時、\n何か感触がおかしかったので慌てて方向を変えたんですが…",
  ui_story_1016_10160401_61_dialog_content = "感覚は当たっていたようですね。\nただ…何者かが空包を紙吹雪にすり替えたってことでしょうか？",
  ui_story_1016_10160401_62_dialog_content = "弾をすり替えた？そんなことあるの！？",
  ui_story_1016_10160401_63_dialog_content = "それは俺にもよく分かりません。",
  ui_story_1016_10160401_64_dialog_content = "とにかく申し訳ありませんでした。\nすぐに長官に報告し、調査を依頼します。",
  ui_story_1016_10160401_65_dialog_content = "空包がすり替えられた、ですと？",
  ui_story_1016_10160401_66_dialog_content = "誰がそのような危険なことを…",
  ui_story_1016_10160401_67_dialog_content = "危険というより、バカバカしいと言った方がよいでしょう。",
  ui_story_1016_10160401_68_dialog_content = "何者かが他の参加者の訓練の邪魔をして、\n得点を上げさせないようにしているのでしょう。",
  ui_story_1016_10160401_69_dialog_content = "ですが、やり方があまりにも幼稚すぎるのでは？",
  ui_story_1016_10160401_70_dialog_content = "幼稚なやり方かどうかは重要ではありません。\n演習には多くの勢力が参加しており、利害関係も複雑です。",
  ui_story_1016_10160401_71_dialog_content = "しかし、私たちが考えるべきことではありません。\n関わらなければいいだけのことです。",
  ui_story_1016_10160401_72_dialog_content = "今後、授業以外で余計なことには関わらないようにしてください。",
  ui_story_1016_10160401_73_dialog_content = "承知いたしました。",
  ui_story_1016_10160401_74_dialog_content = "行きましょう、アクセリア。",
  ui_story_1016_10160401_75_dialog_content = "はい。",
  ui_story_1016_10160401_76_dialog_content = "<color=#e8d9bb>その頃、啓光研究所では</color>",
  ui_story_1016_10160401_77_dialog_content = "やった！戦闘シミュレーションの使用許可が出たよ！",
  ui_story_1016_10160401_78_dialog_content = "シミュレーションで訓練するなら、\n体力をあまり使わずに済むね。",
  ui_story_1016_10160401_79_dialog_content = "ええ。あとは他の学生たちがいなくなったら教室に戻って、\n体力を消耗する訓練をやればいいわ。",
  ui_story_1016_10160401_80_dialog_content = "この方法なら効率よく単位を稼げるはずよ。",
  ui_story_1016_10160401_81_dialog_content = "カレンって、こういうことにもよく気がつくのね。",
  ui_story_1016_10160401_82_dialog_content = "私は前回も参加しているから、ある程度経験があるだけよ。",
  ui_story_1016_10160401_83_dialog_content = "さあ、始めましょう。時間がもったいないわ。",
  ui_story_1016_10160401_84_dialog_content = "そうだね。この間みたいにヘッドセットを付けて。",
  ui_story_1016_10160401_85_dialog_content = "あれ、ここはどこだろう？",
  ui_story_1016_10160401_86_dialog_content = "前回入ってきた時とは違う風景ね。",
  ui_story_1016_10160401_87_dialog_content = "敵はどこかしら？",
  ui_story_1016_10160401_88_dialog_content = "どれどれ…",
  ui_story_1016_10160401_89_option_content = "強制感知！",
  ui_story_1016_10160401_90_dialog_content = "<anim type=Shake>ザッ…</anim>",
  ui_story_1016_10160401_91_dialog_content = "すごい数だ！前回よりも多いよ！",
  ui_story_1016_10160401_92_dialog_content = "しかも敵の放つ暗力もすごく強くなってる！？",
  ui_story_1016_10160401_93_dialog_content = "また逃げなきゃなの？",
  ui_story_1016_10160401_94_dialog_content = "いや、逃げる場所もないかも…",
  ui_story_1016_10160401_95_dialog_content = "来た！",
  ui_story_1016_10160401_96_dialog_content = "<anim type=Shake><size=50>グアア！！</size></anim>",
  ui_story_1016_10160401_97_dialog_content = "散れ！氷花よ！",
  ui_story_1016_10160401_98_dialog_content = "どうして…？効いていないの…？",
  ui_story_1016_10160401_99_dialog_content = "この暗鬼たち、おかしい！",
  ui_story_1016_10160401_100_dialog_content = "とにかく、これはシミュレーションだ！やるしかないよ！",
  ui_story_1016_10160402_11_dialog_content = "気を付けて！",
  ui_story_1016_10160402_12_dialog_content = "大変よ、こっちにも…",
  ui_story_1016_10160402_13_dialog_content = "カレン！バイス！",
  ui_story_1016_10160402_14_dialog_content = "<size=45>ああ！！</size>",
  ui_story_1016_10160402_15_dialog_content = "<anim type=Shake>はぁ――はぁ――</anim>",
  ui_story_1016_10160402_16_dialog_content = "恐ろしい戦いだった…",
  ui_story_1016_10160402_17_dialog_content = "あなたの言う通りね。さっきの暗鬼は普通じゃないわ。",
  ui_story_1016_10160402_18_dialog_content = "強大なんて言葉では足りない…異常だったわ。",
  ui_story_1016_10160402_19_dialog_content = "ええ。攻撃の仕方は普通の暗鬼と変わりなかったけど、\n暗力が異常に濃かったわ…",
  ui_story_1016_10160402_20_dialog_content = "ねえ、もしかして…\n誰かが戦闘シミュレーションに細工したんじゃないかな？",
  ui_story_1016_10160402_21_dialog_content = "どういうこと？話してみて。",
  ui_story_1016_10160402_22_dialog_content = "前にガーディアン1号が言ってたんだ。\nシミュレーション内のものはどんなにリアルでも、しょせんはデータにすぎないって。",
  ui_story_1016_10160402_23_dialog_content = "僕たちの戦闘もデータ間の演算みたいなものなんだって。",
  ui_story_1016_10160402_24_dialog_content = "ということは、誰かが中の数字を大幅に書き換えたら、\n保たれていたバランスが崩れるんじゃないかな。",
  ui_story_1016_10160402_25_dialog_content = "さっきの状況はそうやってできたのかもしれない。",
  ui_story_1016_10160402_26_dialog_content = "確かにそうね！暗鬼の力に関するデータが書き換えられたら、\n異常に強くなっていてもおかしくないわ。",
  ui_story_1016_10160402_27_dialog_content = "ただ…いったい誰がそんな悪質な細工を？",
  ui_story_1016_10160402_28_dialog_content = "PlayerName、周囲に誰かいるか感知できる？",
  ui_story_1016_10160402_29_dialog_content = "やってるけど、疑わしい人物の痕跡はない…",
  ui_story_1016_10160402_30_dialog_content = "そう…",
  ui_story_1016_10160402_31_dialog_content = "戦闘シミュレーションに細工がされていることは、\n教官に報告した方がいいわ。",
  ui_story_1016_10160402_32_dialog_content = "何かおかしいわ。今日は訓練は中止しましょう。",
  ui_story_1016_10160402_33_dialog_content = "そうだね。宿舎に戻ろう。",
  ui_story_1016_10160402_34_dialog_content = "本当に誰かが細工してたの？",
  ui_story_1016_10160402_35_dialog_content = "うん。ガルーが戦闘シミュレーションを調べたんだけど、\n人為的に書き換えられたデータがあったんだ。",
  ui_story_1016_10160402_36_dialog_content = "ただ誰がやったのかは、今はまだ特定できてない。",
  ui_story_1016_10160402_37_dialog_content = "いったい何が目的で…",
  ui_story_1016_10160402_38_dialog_content = "戦闘シミュレーションでの出来事が、\n現実に影響を及ぼすことはないわ。",
  ui_story_1016_10160402_39_dialog_content = "だとしたら、考えられる目的は…\n私たちが単位を取るのを邪魔することね。",
  ui_story_1016_10160402_40_dialog_content = "うん。それなら筋が通る。",
  ui_story_1016_10160402_41_dialog_content = "単位獲得競争のためだとすると、\n細工をした人も演習に参加してる学生ってこと？",
  ui_story_1016_10160402_42_dialog_content = "その可能性は高いわね。\n競争が悪質な方向に進むことはよくあることよ。",
  ui_story_1016_10160402_43_dialog_content = "これまでの演習でも、\n白夜城と啓光の参加者の間にはよく争いが起こっていたの。",
  ui_story_1016_10160402_44_dialog_content = "そう言われてみると、\n演習は確かに各勢力間の競争の縮図みたいなものね。",
  ui_story_1016_10160402_45_dialog_content = "でも、どうして僕たちが攻撃の的になったんだろう？",
  ui_story_1016_10160402_46_dialog_content = "僕は空の末裔で、カレンは白夜城、バイスは啓光に属してる。",
  ui_story_1016_10160402_47_dialog_content = "どう考えても、各勢力間の競争と\n僕たちチームは結び付かないよ？",
  ui_story_1016_10160402_48_dialog_content = "狙われてるのが私たちだとは限らないわ。",
  ui_story_1016_10160402_49_dialog_content = "戦闘シミュレーションの使用許可は直前に受けたの。",
  ui_story_1016_10160402_50_dialog_content = "前もって細工をしていたとしたら、\n私たちが使うとは思っていなかった可能性が高いわ。",
  ui_story_1016_10160402_51_dialog_content = "だったら、本当の狙いは…",
  ui_story_1016_10160402_52_dialog_content = "スケジュール表の上だと、\n戦闘シミュレーションを予約していたのは、レオのチームね。",
  ui_story_1016_10160402_53_dialog_content = "あ！だとしたら、つじつまが合うわ！",
  ui_story_1016_10160402_54_dialog_content = "レオのチームはトップを走ってるから、\nもともと皆の妬みの的だもの！",
  ui_story_1016_10160402_55_dialog_content = "ええ。その可能性が一番高いと思うわ。",
  ui_story_1016_10160402_56_dialog_content = "でも、今は自分たちのことを考えましょ。",
  ui_story_1016_10160402_57_dialog_content = "他人が何をしようと、私たちがどうにかできるのは自分自身だけ。",
  ui_story_1016_10160402_58_dialog_content = "明日の計画を立てるわよ。",
  ui_story_1016_10160402_59_dialog_content = "ええ！",
  ui_story_1016_10160402_60_dialog_content = "アハハハ！たっのし～い！超たのしい！",
  ui_story_1016_10160402_61_dialog_content = "ディシス、まさかあんたが戦闘シミュレーションまでいじれるなんてね！",
  ui_story_1016_10160402_62_dialog_content = "まだ学びたてです。",
  ui_story_1016_10160402_63_dialog_content = "演習期間中は普段なかなか読むことのできない本も読めます。\nあなたたちも読んでみるといいですよ。",
  ui_story_1016_10160402_64_dialog_content = "知識を得るチャンスはいつでもどこにでも\n転がっているわけではないので。",
  ui_story_1016_10160402_65_dialog_content = "まったく、目が不自由なくせに何が本よ！\nそんな話聞きたくない！",
  ui_story_1016_10160402_66_dialog_content = "メリー、明日もイタズラ続けよ。",
  ui_story_1016_10160402_67_dialog_content = "あいつら、お互いにお互いを疑い始めてるよ！笑える～！",
  ui_story_1016_10160402_68_dialog_content = "見つからないように気を付けてください。\n皆そろそろ怒りだしますメェ。",
  ui_story_1016_10160402_69_dialog_content = "大丈夫大丈夫～！啓光のやつは白夜城を疑うし、\n白夜城のやつは啓光を疑うから。",
  ui_story_1016_10160402_70_dialog_content = "あたしらみたいに点数も低くて、\n立場もよく分かんないチームを疑いやしないよ。",
  ui_story_1016_10160402_71_dialog_content = "この件に関しては、僕はミンチに賛成です。",
  ui_story_1016_10160402_72_dialog_content = "理性とは一種のかせです。\nすべての物事に意味を求め、思索せずにいられなくなります。",
  ui_story_1016_10160402_73_dialog_content = "あ～あ、また始まった…",
  ui_story_1016_10160402_74_dialog_content = "しかし、その思索がいかに狭いかには気づかないのです。",
  ui_story_1016_10160402_75_dialog_content = "小さく、とるに足らない存在である僕たちが何をしようと無意味です。",
  ui_story_1016_10160402_76_dialog_content = "それに気づかない限り、\n何の根拠も目的もない悪意の存在をつかむことはできません。",
  ui_story_1016_10160402_77_dialog_content = "ですから、安心して続けてください。ミンチ。",
  ui_story_1016_10160402_78_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_1016_10160402_79_dialog_content = "あの2人…",
  ui_story_1016_10160402_80_dialog_content = "はぁ…また僕一人を置いてきぼりにしましたね。",
  ui_story_1016_10160402_81_dialog_content = "いいでしょう。自分で宿舎に戻ります。\n確か宿舎は…",
  ui_story_1016_10160402_82_dialog_content = "おや？",
  ui_story_1016_10160501_1_dialog_content = "暗鬼の痕跡を発見した！すぐに応援を呼べ！",
  ui_story_1016_10160501_2_dialog_content = "1匹たりとも逃がすな！",
  ui_story_1016_10160501_3_dialog_content = "哨兵がすでにラス軍団長に知らせたわ。\nまずは私たちで追いかけましょう！",
  ui_story_1016_10160501_4_dialog_content = "よし…",
  ui_story_1016_10160501_5_dialog_content = "おい、ここで何をぼうっと突っ立ってる？\nこの先に暗鬼が出たんだ、聞こえなかったか？",
  ui_story_1016_10160501_6_dialog_content = "申し訳ありません。僕は目が…",
  ui_story_1016_10160501_7_dialog_content = "なんだ、目が見えないのか！",
  ui_story_1016_10160501_8_dialog_content = "あ…申し訳ない。ひどい言い方をした。",
  ui_story_1016_10160501_9_dialog_content = "今は緊急事態だ。君を宿舎まで送り届けてはいられない。",
  ui_story_1016_10160501_10_dialog_content = "端に避けていてくれ。ここはひとまず安全だ。",
  ui_story_1016_10160501_11_dialog_content = "分かりました。僕のことはお気になさらず。",
  ui_story_1016_10160501_12_dialog_content = "緊急事態ならば、皆さんどうぞお急ぎください。",
  ui_story_1016_10160501_13_dialog_content = "…ああ、そうするしかない。十分に気を付けろよ。",
  ui_story_1016_10160501_14_dialog_content = "行くぞ、追いかけるぞ！",
  ui_story_1016_10160501_15_dialog_content = "ええ！",
  ui_story_1016_10160501_16_dialog_content = "カナン城の暗鬼の中には…",
  ui_story_1016_10160501_17_dialog_content = "僕たちよりもイタズラ上手がいるようですね。",
  ui_story_1016_10160501_18_dialog_content = "<color=#e8d9bb>ダダダダダ…</color>",
  ui_story_1016_10160501_19_dialog_content = "この先だ！いそげ！",
  ui_story_1016_10160501_20_dialog_content = "もうすぐ追いつく…",
  ui_story_1016_10160501_21_dialog_content = "あぶない！！",
  ui_story_1016_10160501_22_dialog_content = "<anim type=Shake><size=50>グアア！！</size></anim>",
  ui_story_1016_10160501_23_dialog_content = "なに！？引き返してきた！？",
  ui_story_1016_10160501_24_dialog_content = "まずいわ。私たちにはこの数は…",
  ui_story_1016_10160501_25_dialog_content = "仕方ない。やるしかないだろう。",
  ui_story_1016_10160501_26_dialog_content = "応援が駆け付けるまで持ちこたえれば…",
  ui_story_1016_10160501_27_dialog_content = "おいおい。そこまで悲観的になる必要はないだろう。\nここはカナン城だぞ。",
  ui_story_1016_10160501_28_dialog_content = "誰だ！？",
  ui_story_1016_10160501_29_dialog_content = "ただの通りすがりだ。",
  ui_story_1016_10160501_30_dialog_content = "つ、強い…",
  ui_story_1016_10160501_31_dialog_content = "あ、ありがとうございました！",
  ui_story_1016_10160501_32_dialog_content = "礼を言うなら隣の奴に言ってくれ。\nこいつが毎日散歩していたおかげだ。",
  ui_story_1016_10160501_33_dialog_content = "今のは包囲攻撃のおつもりですか？",
  ui_story_1016_10160501_34_dialog_content = "戦術がなっていませんね。\n効率が悪いだけでなく、あれでは味方に犠牲を出しますよ。",
  ui_story_1016_10160501_35_dialog_content = "このようなことが知れ渡っては、\nいいお笑い種になってしまいますよ。",
  ui_story_1016_10160501_36_dialog_content = "長官のおっしゃるとおりです…",
  ui_story_1016_10160501_37_dialog_content = "（見たところ、啓光の将校のようだが…）",
  ui_story_1016_10160501_38_dialog_content = "（なぜ白夜城の者らしき人物と一緒にいるんだ？）",
  ui_story_1016_10160501_39_dialog_content = "周囲にはまだ他の部隊もいますか？",
  ui_story_1016_10160501_40_dialog_content = "指揮権をください。私が包囲攻撃の指揮をしましょう。",
  ui_story_1016_10160501_41_dialog_content = "しかし、長官…",
  ui_story_1016_10160501_42_dialog_content = "手続きや規則にかまっている場合ではありません。\nもたもたしていると手遅れになります。",
  ui_story_1016_10160501_43_dialog_content = "了解です！",
  ui_story_1016_10160501_44_dialog_content = "周辺部隊に知らせてください。\n5ブロック先の角に扇形の陣を敷くのです。",
  ui_story_1016_10160501_45_dialog_content = "こちらは追撃のスピードを緩め、陣形の完成を待ちましょう。",
  ui_story_1016_10160501_46_dialog_content = "いいですか。戦闘とは力比べではありません。",
  ui_story_1016_10160501_47_dialog_content = "魚を捕る時も手を伸ばせば捕まえられるわけではないでしょう？\n魚を網に引き入れることが大切なのです。",
  ui_story_1016_10160502_1_dialog_content = "暗鬼の群れ？いったいどこから現れたの？",
  ui_story_1016_10160502_2_dialog_content = "分かりません。すでに人を遣り、調べさせています。",
  ui_story_1016_10160502_3_dialog_content = "ただ…この時期に現れたということは、\nカナン城に潜伏しているノラと無関係ではないのでは？",
  ui_story_1016_10160502_4_dialog_content = "ノラと関係あることくらい分かってるわ。\n問題はどうやってこんなこと出来たか、よ。",
  ui_story_1016_10160502_5_dialog_content = "ここのところパトロールの範囲を広げて、\n回数やシフトも常に調整している。",
  ui_story_1016_10160502_6_dialog_content = "にもかかわらず、報告ではノラの髪の毛1本も見つかっていない。",
  ui_story_1016_10160502_7_dialog_content = "それは…ノラが身を隠すのに長けているからでは？",
  ui_story_1016_10160502_8_dialog_content = "その可能性はあるわ。でも、そんな簡単じゃない気がするわ。",
  ui_story_1016_10160502_9_dialog_content = "最近のカナン城は何だか物足りない感じがするのよ…",
  ui_story_1016_10160502_10_dialog_content = "軍団長、今入ったばかりの情報です！",
  ui_story_1016_10160502_11_dialog_content = "周辺部隊が現在、包囲攻撃態勢に入っています。",
  ui_story_1016_10160502_12_dialog_content = "包囲攻撃態勢？数は？具体的な場所は？",
  ui_story_1016_10160502_13_dialog_content = "私は何の命令も出していないわよ？\nいったいどこの誰が勝手に私の部隊を動かしてるの！？",
  ui_story_1016_10160502_14_dialog_content = "具体的なことはまだ分かっていませんが…",
  ui_story_1016_10160502_15_dialog_content = "調べなさい！",
  ui_story_1016_10160502_16_dialog_content = "私は少将よ！他人に指揮を代わってもらうほど落ちぶれちゃいないわ！",
  ui_story_1016_10160502_17_dialog_content = "ぐ、軍団長！新しい情報が入りました！",
  ui_story_1016_10160502_18_dialog_content = "カナン城に侵入した暗鬼の群れはすでにせん滅しました！",
  ui_story_1016_10160502_19_dialog_content = "<size=50>何ですって！？</size>",
  ui_story_1016_10160502_20_dialog_content = "その情報は確かなの？",
  ui_story_1016_10160502_21_dialog_content = "はい。周辺には暗鬼の痕跡はすでにありません。",
  ui_story_1016_10160502_22_dialog_content = "ずいぶんと素早く対処したわね…",
  ui_story_1016_10160502_23_dialog_content = "ふん、面白いじゃない。",
  ui_story_1016_10160502_24_dialog_content = "いったい誰がお出ましになったのか、\n会ってやろうじゃない。",
  ui_story_1016_10160502_25_dialog_content = "よし、これで一件落着だ。",
  ui_story_1016_10160502_26_dialog_content = "後始末はお前たちに頼んだ。我々は失礼する。",
  ui_story_1016_10160502_27_dialog_content = "それと、私が臨時に指揮をとったことは、\n報告しないほうがよいでしょう。",
  ui_story_1016_10160502_28_dialog_content = "色々と面倒ですから…",
  ui_story_1016_10160502_29_dialog_content = "あら、なぜ報告しないの？\n暗鬼を倒して騒ぎをおさめたなんて、お手柄じゃない？",
  ui_story_1016_10160502_30_dialog_content = "「人助け賞」の勲章をあげようかと思ってたところよ。",
  ui_story_1016_10160502_31_dialog_content = "ラス教官…",
  ui_story_1016_10160502_32_dialog_content = "今は授業じゃないんだから「教官」なんて呼ばなくていいわ。\nお互い軍人として向き合ってちょうだい。",
  ui_story_1016_10160502_33_dialog_content = "勝手に部隊を動かしてしまい、申し訳ありません。",
  ui_story_1016_10160502_34_dialog_content = "どうか処罰を。",
  ui_story_1016_10160502_35_dialog_content = "ううむ…私は処罰よりも「人助け賞」の勲章のほうがいいな。",
  ui_story_1016_10160502_36_dialog_content = "よしてちょうだい。処罰とかそういうのはいいわ。",
  ui_story_1016_10160502_37_dialog_content = "手助けしただけじゃなく、\nこんなに素早く暗鬼を片付けるなんて手柄じゃない。",
  ui_story_1016_10160502_38_dialog_content = "功をあげた者を罰するほど、\nバカげた考えの持ち主じゃないわ。",
  ui_story_1016_10160502_39_dialog_content = "ご理解に感謝します。",
  ui_story_1016_10160502_40_dialog_content = "あんたたちは戦術に長けてるわ。\n決断力の高さも見事よ。",
  ui_story_1016_10160502_41_dialog_content = "今日の騒ぎをこれだけ完璧に解決できたのは、\nおそらくあんたたちだったからでしょうね。",
  ui_story_1016_10160502_42_dialog_content = "きっと辺境の戦乱続きの環境がその能力を養ったのね。",
  ui_story_1016_10160502_43_dialog_content = "しかも、より実戦にふさわしい考え方ができる。",
  ui_story_1016_10160502_44_dialog_content = "あんたたちの考え方に問題はないわ。\n戦場で必要なのは決断力と行動力よ。",
  ui_story_1016_10160502_45_dialog_content = "ただカナン城では、制度や規則が重視される。",
  ui_story_1016_10160502_46_dialog_content = "私もそのことを学ぶのにずいぶん時間がかかったわ。\nあんたたちもよく考えることね。",
  ui_story_1016_10160502_47_dialog_content = "制度と規則ですか…",
  ui_story_1016_10160502_48_dialog_content = "制度と規則は大きな体制の安定を維持するのに\n欠かせないものだから、ですか？",
  ui_story_1016_10160502_49_dialog_content = "そうよ。安定は大事なの。",
  ui_story_1016_10160502_50_dialog_content = "外力によって傾かないだけじゃなく、\n内部からの崩壊にも耐えうるものでなきゃいけない。",
  ui_story_1016_10160502_51_dialog_content = "そうした安定を守るために、\n時として局地的勝利を犠牲にする必要があるのよ。",
  ui_story_1016_10160502_52_dialog_content = "そうでしたか。よく理解しました。",
  ui_story_1016_10160502_53_dialog_content = "ご教示に感謝いたします。",
  ui_story_1016_10160502_54_dialog_content = "あんたたちも辺境を離れるような時が来たら、\nその点しっかり心得ておくことが大事よ。",
  ui_story_1016_10160502_55_dialog_content = "さあ、もう戻っていいわ。",
  ui_story_1016_10160502_56_dialog_content = "明日の授業、遅刻しないように。",
  ui_story_1016_10160502_57_dialog_content = "了解です！",
  ui_story_1016_10160502_58_dialog_content = "…しかし、もしその安定した体制が\n歪曲されたものだったとしたら？",
  ui_story_1016_10160502_59_dialog_content = "え？",
  ui_story_1016_10160502_60_dialog_content = "制度と規則を基礎に築かれた建物が\nいつかは倒れる斜塔だったとしたら？",
  ui_story_1016_10160502_61_dialog_content = "我々が払った犠牲は、ただの笑い話になるのでは？",
  ui_story_1016_10160502_62_dialog_content = "その口ぶりからすると、今の「建物」に不満があるようね。",
  ui_story_1016_10160502_63_dialog_content = "なぜ我々がこの演習に参加したか分かるか？",
  ui_story_1016_10160502_64_dialog_content = "今、地図の最も端にある辺境地帯の暗面に、\n暗鬼が集結している。",
  ui_story_1016_10160502_65_dialog_content = "集結した暗鬼は、いつ防衛線を攻撃してきてもおかしくない状況だ。",
  ui_story_1016_10160502_66_dialog_content = "しかし、我々が発した援軍要請には今になってもまだ返答がない。",
  ui_story_1016_10160502_67_dialog_content = "我々がトワイライトシティを守り続けることは、\n「体制の安定」を維持していることになるのか？",
  ui_story_1016_10160502_68_dialog_content = "それとも「局地」と見なされ、犠牲となるのか？",
  ui_story_1016_10160502_69_dialog_content = "…辺境では、そんな大きな動きが？",
  ui_story_1016_10160502_70_dialog_content = "私が推測したように、知らなかったようだな。",
  ui_story_1016_10160502_71_dialog_content = "軍の指揮権をもつ他の軍団長もおそらく同じだろう。",
  ui_story_1016_10160502_72_dialog_content = "すまない。話しすぎたようだ。",
  ui_story_1016_10160502_73_dialog_content = "…",
  ui_story_1016_10160502_74_dialog_content = "戻りなさい。",
  ui_story_1016_10160502_75_dialog_content = "今の話はきちんと調査するわ。",
  ui_story_1016_10160502_76_dialog_content = "ああ。",
  ui_story_1016_10160502_77_dialog_content = "（そんな大事になってるなんて、まったく知らなかったわ）",
  ui_story_1016_10160502_78_dialog_content = "（レインハト、あんたいったい何を考えてるの？）",
  ui_story_1016_10160502_79_dialog_content = "（それとも、あんたもどうにもできないの…？）",
  ui_story_1016_10160502_80_dialog_content = "デニール。",
  ui_story_1016_10160502_81_dialog_content = "デニール！",
  ui_story_1016_10160502_82_dialog_content = "…あら、ごめんなさい。少し考え事してたわ。",
  ui_story_1016_10160502_83_dialog_content = "難しい…状況なのか？",
  ui_story_1016_10160502_84_dialog_content = "顔色が…悪い。",
  ui_story_1016_10160502_85_dialog_content = "カナン城に潜伏させておいた暗鬼が倒されたわ。",
  ui_story_1016_10160502_86_dialog_content = "向こうの指揮官、かなり出来るようね。\n私に反応する時間も与えなかった。",
  ui_story_1016_10160502_87_dialog_content = "もう…手はないのか？",
  ui_story_1016_10160502_88_dialog_content = "ファントムが来るまでは、そういうことになるわ。",
  ui_story_1016_10160502_89_dialog_content = "俺たちの活路をあいつらに賭けるのは好かない。",
  ui_story_1016_10160502_90_dialog_content = "これは賭けじゃないわ、取引よ。",
  ui_story_1016_10160502_91_dialog_content = "私の持っている研究成果が私たちの命を救うのよ。",
  ui_story_1016_10160601_1_dialog_content = "<color=#e8d9bb>数日後、演習訓練期間も終わりに近づいた頃</color>",
  ui_story_1016_10160601_2_dialog_content = "僕たちの順位はどうなってるの！？",
  ui_story_1016_10160601_3_dialog_content = "見てみましょ――",
  ui_story_1016_10160601_4_dialog_content = "第2位よ！私たち第2位になったわ！",
  ui_story_1016_10160601_5_dialog_content = "やった！！何とかやり遂げたね！",
  ui_story_1016_10160601_6_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_1016_10160601_7_dialog_content = "さあ、席に着きましょ。今日は優等生してなきゃ。",
  ui_story_1016_10160601_8_dialog_content = "そうだね。これが最後の授業だもんね。",
  ui_story_1016_10160601_9_dialog_content = "皆さん、こんにちは！",
  ui_story_1016_10160601_10_dialog_content = "ご存じの通り、今日が合同演習訓練段階の最後の授業になります。",
  ui_story_1016_10160601_11_dialog_content = "この後皆さんは実戦試験の準備に入ります。\n試験では、最後の勝者が決まります。",
  ui_story_1016_10160601_12_dialog_content = "訓練段階で貯めた単位が皆さんの力になりますよ。",
  ui_story_1016_10160601_13_dialog_content = "単位の獲得状況はランキングからも分かるように――",
  ui_story_1016_10160601_14_dialog_content = "レオの率いるチームが圧倒的な差をつけて第1位を獲得。",
  ui_story_1016_10160601_15_dialog_content = "どうも。",
  ui_story_1016_10160601_16_dialog_content = "PlayerNameチームは後半で追い上げ、第2位を獲得しました。",
  ui_story_1016_10160601_17_dialog_content = "なかなか大変だったなぁ…",
  ui_story_1016_10160601_18_dialog_content = "インゲルチームは安定した成績で、最終的に第3位を獲得しました。",
  ui_story_1016_10160601_19_dialog_content = "ありがとうございます。",
  ui_story_1016_10160601_20_dialog_content = "その他の順位については、皆さんご自分で確認してください。",
  ui_story_1016_10160601_21_dialog_content = "では、授業に戻ります。訓練も今日で終了です。\n主催者としても皆さんには試験に向けた準備をしてもらいたいと思い――",
  ui_story_1016_10160601_22_dialog_content = "授業内容は実戦訓練とします。",
  ui_story_1016_10160601_23_dialog_content = "実戦訓練？この前の戦闘実技の授業と何か違いはあるんですか？",
  ui_story_1016_10160601_24_dialog_content = "皆さんの相手となる敵が違います。",
  ui_story_1016_10160601_25_dialog_content = "以前の授業では安全を考慮して、\n実際の脅威に立ち向かうことはありませんでした。",
  ui_story_1016_10160601_26_dialog_content = "打撃訓練の指導係にしても、戦闘シミュレーション内の環境にしても、\n実際のダメージを受けることはありませんでした。",
  ui_story_1016_10160601_27_dialog_content = "しかし、これから始まる試験段階では、\n皆さんの安全は保証できません。",
  ui_story_1016_10160601_28_dialog_content = "そこで、今日は本物の暗鬼に立ち向かう準備ができているか、\n見させていただきます。",
  ui_story_1016_10160601_29_dialog_content = "本物の暗鬼ですか？この教室で？",
  ui_story_1016_10160601_30_dialog_content = "啓光生物化学研究所より皆さんに、\n貴重な「訓練用具」を提供します。",
  ui_story_1016_10160601_31_dialog_content = "準備してください。",
  ui_story_1016_10160601_32_dialog_content = "<color=#e8d9bb>ドーン！！！</color>",
  ui_story_1016_10160601_33_dialog_content = "わ！暗鬼がこんなにたくさん？",
  ui_story_1016_10160601_34_dialog_content = "啓光生物化学研究所は暗鬼を研究してるの…？\nやりすぎでしょう…？",
  ui_story_1016_10160601_35_dialog_content = "戦場では敵をよく知る必要があります。",
  ui_story_1016_10160601_36_dialog_content = "暗鬼を研究した結果、救えるのは何だと思いますか？\nより多くの兵士の命です。",
  ui_story_1016_10160601_37_dialog_content = "でも…",
  ui_story_1016_10160601_38_dialog_content = "安心してください。この暗鬼たちは全て制御可能です。",
  ui_story_1016_10160601_39_dialog_content = "皆さん、この授業には余計なルールなどありません。",
  ui_story_1016_10160601_40_dialog_content = "持ちうるすべての手を尽くし、暗鬼を消滅させてください。",
  ui_story_1016_10160601_41_dialog_content = "<anim type=Shake><size=50>グアア！！</size></anim>",
  ui_story_1016_10160601_42_dialog_content = "突然始まった！？",
  ui_story_1016_10160601_43_dialog_content = "まだ準備できてないのに…",
  ui_story_1016_10160601_44_dialog_content = "PlayerName、危ない！",
  ui_story_1016_10160601_45_dialog_content = "あ、ごめん！考え事してた！",
  ui_story_1016_10160601_46_dialog_content = "戦いながら、他のチームを観察しましょ。",
  ui_story_1016_10160601_47_dialog_content = "各チームの実力を確めるいい機会だわ。",
  ui_story_1016_10160601_48_dialog_content = "アクセリアは出来る限り手を出さないでください。",
  ui_story_1016_10160601_49_dialog_content = "私とアナトリアに任せてください。",
  ui_story_1016_10160601_50_dialog_content = "大丈夫ですか？",
  ui_story_1016_10160601_51_dialog_content = "ただの訓練にすぎません。大した危険はありませんよ。",
  ui_story_1016_10160601_52_dialog_content = "それに他のチームもいます。",
  ui_story_1016_10160601_53_dialog_content = "それはそうですが…",
  ui_story_1016_10160601_54_dialog_content = "他の皆さんもあまり戦っていないようですよ。",
  ui_story_1016_10160601_55_dialog_content = "ユーライア、左の援護をお願い！",
  ui_story_1016_10160601_56_dialog_content = "分かりました！",
  ui_story_1016_10160601_57_dialog_content = "ダメだわ。他の方向からも押し寄せてくる…",
  ui_story_1016_10160601_58_dialog_content = "クロエ！",
  ui_story_1016_10160601_59_dialog_content = "こっちだけで手一杯です！",
  ui_story_1016_10160601_60_dialog_content = "どういうこと？周りにまったく味方がいないじゃない！",
  ui_story_1016_10160601_61_dialog_content = "私たちいつ先頭になったのかしら？",
  ui_story_1016_10160601_62_dialog_content = "他の皆さんが後退してるからだと思います…",
  ui_story_1016_10160601_63_dialog_content = "え！？",
  ui_story_1016_10160601_64_dialog_content = "ランキングでは大そうな順位獲ってたくせに、\n実戦となったら全員おじけづいたっていうの？",
  ui_story_1016_10160601_65_dialog_content = "我々も苦戦中だ。自分たちのことで手一杯なだけさ。",
  ui_story_1016_10160601_66_dialog_content = "剣も抜いてないくせに何が苦戦中よ！",
  ui_story_1016_10160601_67_dialog_content = "皆、力を温存してるみたいだね…",
  ui_story_1016_10160601_68_dialog_content = "それもそうよね。最後の授業だもの。\n力は次の試験段階まで残しておきたいと思うのは当然ね。",
  ui_story_1016_10160601_69_dialog_content = "でも、だからといってこのままじゃ、\n暗鬼に勝てそうもないわ…",
  ui_story_1016_10160601_70_dialog_content = "全力を出したくないっていうなら、\n皆で協力すればいいんだよ！",
  ui_story_1016_10160601_71_dialog_content = "敵も強大ってわけじゃないし、うまく協力ができれば、\n各チームとも少しの力で勝てるはずだよ！",
  ui_story_1016_10160601_72_dialog_content = "おや？なかなかいい提案ではないか。",
  ui_story_1016_10160601_73_dialog_content = "異なる土地の者たちと共に戦うのは興味深い。\nぜひ協力しよう。",
  ui_story_1016_10160601_74_dialog_content = "その通りです。最後の授業となれば競い合う必要もないでしょう。\n面倒事を一緒に解決すると思えばいいことです。",
  ui_story_1016_10160601_75_dialog_content = "私たちも賛成よ！さあ、さっさと力を貸して！",
  ui_story_1016_10160601_76_dialog_content = "いいねいいね～！ミンチも仲間に入れて！",
  ui_story_1016_10160601_77_dialog_content = "じゃあ、皆で一緒に協力しよう！",
  ui_story_1016_10160601_78_dialog_content = "陣を前に進めて、ベルタチームを包囲から救おう！",
  ui_story_1016_10160602_1_dialog_content = "すばらしいですね！暗鬼はすべて消滅しました。",
  ui_story_1016_10160602_2_dialog_content = "皆さん、おめでとうございます。\n無事本合同演習の最後の授業を修了しました。",
  ui_story_1016_10160602_3_dialog_content = "激しい競い合いになるかと思っていましたが、\n最後は力を合わせて暗鬼に立ち向かうとは。",
  ui_story_1016_10160602_4_dialog_content = "思惑あっての協力だけどね…あはは…",
  ui_story_1016_10160602_5_dialog_content = "それでは、これで本演習訓練段階も終了です。\n解散前に試験の内容をお知らせしましょう。",
  ui_story_1016_10160602_6_dialog_content = "おそらく皆さん非常に気になっているでしょうから。",
  ui_story_1016_10160602_7_dialog_content = "今回の試験はある廃墟になったシェルター内で行います。",
  ui_story_1016_10160602_8_dialog_content = "そのシェルターは防衛線上にあり、すでに暗鬼に占拠されています。\n周辺での光霊の活動痕跡は長年途絶えたままです。",
  ui_story_1016_10160602_9_dialog_content = "皆さんにやっていただくことは、シェルターに入り、\n事前に中に置いてきた旗を見つけ、持ち帰ることです。",
  ui_story_1016_10160602_10_dialog_content = "ルールはごく簡単です。\nその旗を見事獲得した方が本演習の優勝者となり、大元帥との手合わせの機会を獲得します。",
  ui_story_1016_10160602_11_dialog_content = "目標を達成する手段については、一切制限はありません。",
  ui_story_1016_10160602_12_dialog_content = "私たちの安全は保証されるのでしょうか？",
  ui_story_1016_10160602_13_dialog_content = "安全は保証されないものと思ってください。",
  ui_story_1016_10160602_14_dialog_content = "試験を通して皆さんの潜在力を引き出すため、\n難易度と危険度を高く設定してあります。",
  ui_story_1016_10160602_15_dialog_content = "普段授業でいい成績をおさめていれば順調に試験も合格すると思ってはいけませんよ。\n実戦と訓練はあくまで別物です。",
  ui_story_1016_10160602_16_dialog_content = "試験中、教官たちも様々な方法で皆さんの行動を観察しています。",
  ui_story_1016_10160602_17_dialog_content = "学生間で悪質な傷害事件が起こった場合、\n私たちには軍事法廷に十分な証拠を提出するだけの準備があります。",
  ui_story_1016_10160602_18_dialog_content = "しかし、皆さんの身近に起こる危険を代わりに解決することはできません。",
  ui_story_1016_10160602_19_dialog_content = "主催側が何かしてくれるとは思わないでください。\n頼れるのは自分自身だけです。",
  ui_story_1016_10160602_20_dialog_content = "そうですか。よく分かりました。",
  ui_story_1016_10160602_21_dialog_content = "それでいい。誰かに裏で守られていたら、\n演習もママゴトになってしまうからな。",
  ui_story_1016_10160602_22_dialog_content = "続いて、試験準備に入ります。",
  ui_story_1016_10160602_23_dialog_content = "公平さを保つため、装着してよいものは、\n自身の基本的な戦闘装備のみとします。",
  ui_story_1016_10160602_24_dialog_content = "それ以外に何か必要な物があれば、\n訓練段階で獲得した単位を使うほかありません。",
  ui_story_1016_10160602_25_dialog_content = "わ！頑張って貯めてきた単位がここで役に立つんですね！",
  ui_story_1016_10160602_26_dialog_content = "その通りです。明日皆さんを啓光研究所にお連れします。\nそこにはたくさんの物資が用意されています。",
  ui_story_1016_10160602_27_dialog_content = "戦闘能力を強化できるものもあれば、\n戦闘情報を提供してくれるものもあります。",
  ui_story_1016_10160602_28_dialog_content = "それらの物資は、皆さんが獲得した単位と交換できます。",
  ui_story_1016_10160602_29_dialog_content = "つまり、単位数の多いチームほど、物資を多く獲得し、\nより優位に立てるというわけです。",
  ui_story_1016_10160602_30_dialog_content = "物資獲得を通して弱点を補うのか、強みをさらに強化するのか、\nそれとも戦闘方法の選択肢を増やすのか、自由に選んでください。",
  ui_story_1016_10160602_31_dialog_content = "うーん、どうしようかな…",
  ui_story_1016_10160602_32_dialog_content = "宿舎に戻り、それぞれしっかり準備してください。\n明日の朝、教室に集合です。",
  ui_story_1016_10160602_33_dialog_content = "では、今日はここまでとします。解散。",
  ui_story_1016_10160602_34_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_1016_10160602_35_dialog_content = "わ！装備がたくさんあるわね！",
  ui_story_1016_10160602_36_dialog_content = "銃剣に銃器、手榴弾…それから防護服も色々そろってるわ…",
  ui_story_1016_10160602_37_dialog_content = "もう全部欲しくなっちゃう！\nどうやって選べばいいの！",
  ui_story_1016_10160602_38_dialog_content = "冷静になって見てみると、どの物資もすごく高いね。",
  ui_story_1016_10160602_39_dialog_content = "第2位とはいっても、\n僕たちの単位で交換できる物資はかなり限られてる。",
  ui_story_1016_10160602_40_dialog_content = "確かにそうね。思うに物資はある種のご褒美のようなもので、\n主催者も参加者があまりにも物資に頼ることは望んでいないようだわ。",
  ui_story_1016_10160602_41_dialog_content = "一番必要なものだけを選びましょう。",
  ui_story_1016_10160602_42_dialog_content = "そうね…うちのチームにはPlayerNameがいるから、\n情報に関してはそもそも大きくリードしてるわ。",
  ui_story_1016_10160602_43_dialog_content = "となると…直接戦闘力を上げられる物資と\n交換するのがいいんじゃないかしら？",
  ui_story_1016_10160602_44_dialog_content = "それなら、防具類と交換するのがいいと思うわ。",
  ui_story_1016_10160602_45_dialog_content = "PlayerNameは身体が私たちほど強くないから、\n防具で身を守れれば、私たちも安心よ。",
  ui_story_1016_10160602_46_dialog_content = "え？僕のために単位を使うことないよ…",
  ui_story_1016_10160602_47_dialog_content = "私もそれが一番いいと思うわ！",
  ui_story_1016_10160602_48_dialog_content = "PlayerName、どの防護服が身体に合うか、\n試着してみて。",
  ui_story_1016_10160602_49_dialog_content = "え！？防護服に決まったの！？",
  ui_story_1016_10160602_50_dialog_content = "…分かった。皆の足を引っ張らないことも大事ってことで…",
  ui_story_1016_10160602_51_dialog_content = "全部機械類ではないか…",
  ui_story_1016_10160602_52_dialog_content = "まったく興味がわかん。ショウ、お前が選べ。",
  ui_story_1016_10160602_53_dialog_content = "そうさせていただきます。実はもう考えてあったのです。",
  ui_story_1016_10160602_54_dialog_content = "私たちにとって最も重要なのは情報です。",
  ui_story_1016_10160602_55_dialog_content = "先手さえ打てれば、戦闘自体は私たちにとって\n何の問題でもありません。",
  ui_story_1016_10160602_56_dialog_content = "ふむ、確かに一理ある。私もやみくもに駆け回るのは御免だ。",
  ui_story_1016_10160602_57_dialog_content = "地図と交換しましょう。\nそれからトランシーバーも持っていた方がよいでしょう。",
  ui_story_1016_10160602_58_dialog_content = "ううむ。だがトランシーバーはかなり高いな。\n持っている単位の半分がなくなってしまう。",
  ui_story_1016_10160602_59_dialog_content = "説明には、このトランシーバーを使えば、\n試験中リアルタイムで場外の教官と連絡を取れるとあります。",
  ui_story_1016_10160602_60_dialog_content = "最も効率よく情報収集できる手段と考えますが。",
  ui_story_1016_10160602_61_dialog_content = "いいだろう。軍師殿の言う通りにしよう。",
  ui_story_1016_10160602_62_dialog_content = "ドアを閉めなさい。",
  ui_story_1016_10160602_63_dialog_content = "はい！",
  ui_story_1016_10160602_64_dialog_content = "<color=#e8d9bb>バン</color>",
  ui_story_1016_10160602_65_dialog_content = "任務は分かっていますね？",
  ui_story_1016_10160602_66_dialog_content = "一切の代償をいとわず、優勝するのです。",
  ui_story_1016_10160602_67_dialog_content = "すでに2人には伝えてあります。",
  ui_story_1016_10160602_68_dialog_content = "君たちの実力は信じています。\nただ、任務達成のためなら、公正である必要はありません。",
  ui_story_1016_10160602_69_dialog_content = "別途物資を用意しました。\n単位で交換できるものより良い物をそろえてありますよ。",
  ui_story_1016_10160602_70_dialog_content = "すべて試験開始前の検査は通れるようになっているので、\n安心して持っていくとよいでしょう。",
  ui_story_1016_10160602_71_dialog_content = "情報に関しては、ここに完璧な地図があります。\n旗のある位置も記載してあります。",
  ui_story_1016_10160602_72_dialog_content = "他のチームと一緒になって探す必要はありません。\n直接ターゲットに向かってください。",
  ui_story_1016_10160602_73_dialog_content = "それから、そこの棚の上に戦闘力を強化する装備があります。\n好きな物を持って行きなさい。",
  ui_story_1016_10160602_74_dialog_content = "（好きな物を持って行け…ですか。\nどれをとっても他チームの全単位分の価値があります…）",
  ui_story_1016_10160602_75_dialog_content = "（このような不正をはたらいて、万が一知られでもしたら、\n上層部はいい顔をしないでしょうね）",
  ui_story_1016_10160602_76_dialog_content = "（委員会はそこまでして合同演習の優勝が欲しいのでしょうか？）",
  ui_story_1016_10160602_77_dialog_content = "私からは以上です。後は任せましたよ。",
  ui_story_1016_10160602_78_dialog_content = "今日私に会ったことはくれぐれも口外しないように。",
  ui_story_1016_10160602_79_dialog_content = "<color=#e8d9bb>バン</color>",
  ui_story_1016_10160602_80_dialog_content = "アクセリアには「キュービック」がいます。\n他の装備は必要ありません。",
  ui_story_1016_10160602_81_dialog_content = "私も余計な装備は必要ありません。\nアナトリア、選んできなさい。",
  ui_story_1016_10160602_82_dialog_content = "私ですか？",
  ui_story_1016_10160602_83_dialog_content = "装備は1人がまとめて身に付けている方が効果的です。",
  ui_story_1016_10160602_84_dialog_content = "…分かりました。命令に従います。",
  ui_story_1016_10160602_85_dialog_content = "ええ。私たちは皆命令に従っています。",
  ui_story_1016_10160602_86_dialog_content = "お二人は委員会との接触が多いようですから、\nこのような命令にも慣れていらっしゃるのでしょう？",
  ui_story_1016_10160602_87_dialog_content = "何か言いたいことがあるようですね？",
  ui_story_1016_10160602_88_dialog_content = "いいえ、何となく聞いてみただけのことです。",
  ui_story_1016_10160602_89_dialog_content = "情報官が何となく聞いてみるというのは、\nいい習慣とは言えませんね。",
  ui_story_1016_10160602_90_dialog_content = "あなたのいう命令には、私は確かに慣れています。\nどのようなものであろうと、命令に従うのは絶対です。",
  ui_story_1016_10160602_91_dialog_content = "はい。分かりました…",
  ui_story_1016_10160602_92_dialog_content = "しかし、時には命令とは違う考えが浮かぶこともあります。",
  ui_story_1016_10160602_93_dialog_content = "そういう時は、考えを行動の裏に隠すようにしています。",
  ui_story_1016_10160701_1_dialog_content = "<color=#e8d9bb>ボーッ、ボーッ――</color>",
  ui_story_1016_10160701_2_dialog_content = "は～い、みんな下りて！目的地についたよ！",
  ui_story_1016_10160701_3_dialog_content = "目の前のこのボロボロのシェルターが、\n試験会場だよ。",
  ui_story_1016_10160701_4_dialog_content = "この後兵士が各チームをそれぞれのスタート地点まで案内するよ。",
  ui_story_1016_10160701_5_dialog_content = "ええと、あと何を言うんだったけ…？",
  ui_story_1016_10160701_6_dialog_content = "あ、そうそう。自分の身はしっかり守ってね。\n他の人と戦う時は程々にしておくこと。",
  ui_story_1016_10160701_7_dialog_content = "あたしもこっそり見てるからね。",
  ui_story_1016_10160701_8_dialog_content = "なんか鳥肌が立ったんだけど…",
  ui_story_1016_10160701_9_dialog_content = "では、各チームをスタート地点まで連れて行ってあげて。",
  ui_story_1016_10160701_10_dialog_content = "いい知らせを待ってるよ。",
  ui_story_1016_10160701_11_dialog_content = "装備の確認は済んだ？",
  ui_story_1016_10160701_12_dialog_content = "うん、確認済みだよ！",
  ui_story_1016_10160701_13_dialog_content = "矢も十分持ったわ。さあ、暗鬼たち！覚悟しなさい！",
  ui_story_1016_10160701_14_dialog_content = "では、相談した通りの計画で動くわよ。",
  ui_story_1016_10160701_15_dialog_content = "他のチームはきっと地図やその他の情報手段を手に入れているはずよ。\n私たちはPlayerNameの能力を使って、どこかのチームについて行けばいいわ。",
  ui_story_1016_10160701_16_dialog_content = "うん、今探してるところだよ。",
  ui_story_1016_10160701_17_dialog_content = "ただ…スタート地点はそれぞれかなり離れてるから、\n今のところまだ感知できてないんだ。",
  ui_story_1016_10160701_18_dialog_content = "構わないわ。まずは奥へ進みましょう。",
  ui_story_1016_10160701_19_dialog_content = "ミンチ、なぜこんなものを買ったんですメェ…",
  ui_story_1016_10160701_20_dialog_content = "ええ？面白くない？ほら、これは閃光弾だよ。\nこうやって投げれば――",
  ui_story_1016_10160701_21_dialog_content = "<size=50>あ！</size>",
  ui_story_1016_10160701_22_dialog_content = "どうしたのです？何かあったのですか？",
  ui_story_1016_10160701_23_dialog_content = "なんでもないって。メリーが叫び声あげて遊んでんの。",
  ui_story_1016_10160701_24_dialog_content = "あれあれ、また泣いてんの？",
  ui_story_1016_10160701_25_dialog_content = "あまりにもまぶしくて、涙がつい…",
  ui_story_1016_10160701_26_dialog_content = "ミンチ、そんなもの買って、何に使うんですメェ？",
  ui_story_1016_10160701_27_dialog_content = "だって面白いじゃん！",
  ui_story_1016_10160701_28_dialog_content = "あたしら単位少ないし、\n使えそうな道具はそもそも買えないじゃん？",
  ui_story_1016_10160701_29_dialog_content = "だったら、面白いモンたっくさん買った方がいいじゃん！",
  ui_story_1016_10160701_30_dialog_content = "それもそうですメェ…",
  ui_story_1016_10160701_31_dialog_content = "私たちの目的は優勝ではありませんから。",
  ui_story_1016_10160701_32_dialog_content = "優勝などすれば、かえって面倒でしょう。\n自身の陣営の旗を掲げなければなりませんから。",
  ui_story_1016_10160701_33_dialog_content = "あたしら、何陣営で登録したんだっけ？",
  ui_story_1016_10160701_34_dialog_content = "影ノ街ですメェ。私はまだ行ったことありませんが。",
  ui_story_1016_10160701_35_dialog_content = "あ、それはダメだね。影ノ街の旗はカッコ悪すぎるもん。",
  ui_story_1016_10160701_36_dialog_content = "それに、優勝したらレインなんとかとケンカしなきゃなんでしょ？\nあたしは遠慮しとくよ。",
  ui_story_1016_10160701_37_dialog_content = "ディシスは戦いますよね？隊長ですし。",
  ui_story_1016_10160701_38_dialog_content = "興味ありません。\n彼女も体制に担ぎあげられた英雄にすぎませんから。",
  ui_story_1016_10160701_39_dialog_content = "僕たちは注意を他の参加者たちに向けましょう。",
  ui_story_1016_10160701_40_dialog_content = "何のために来たのか、忘れてはいけません。",
  ui_story_1016_10160701_41_dialog_content = "ディシスは真面目くさったことばっか言って、\nぜんっぜん面白くな～い。",
  ui_story_1016_10160701_42_dialog_content = "さあ、行こ行こ。何かたのしいこと見つけよう！",
  ui_story_1016_10160701_43_dialog_content = "あ～あ、他のチームと一緒に遊びたいな！",
  ui_story_1016_10160701_44_dialog_content = "見つけたよ！",
  ui_story_1016_10160701_45_dialog_content = "あら、どこのチーム？",
  ui_story_1016_10160701_46_dialog_content = "いつもヘンな事ばかりしてた影ノ街のチームだよ。",
  ui_story_1016_10160701_47_dialog_content = "確か隊長は…ディシスって言ったかな？",
  ui_story_1016_10160701_48_dialog_content = "覚えてるわ。ディシスとミンチ、それからメリーよ。",
  ui_story_1016_10160701_49_dialog_content = "何だか落ち着かない人たちって印象しか残ってないけど。",
  ui_story_1016_10160701_50_dialog_content = "すごいスピードでまっすぐシェルターの奥へ向かってる。",
  ui_story_1016_10160701_51_dialog_content = "ということは、手がかりを見つけた可能性が高いかも？",
  ui_story_1016_10160701_52_dialog_content = "ええ、速いスピードで進んでいるのは、\n明確な目標があるからでしょう。",
  ui_story_1016_10160701_53_dialog_content = "急いで追いかけましょう。",
  ui_story_1016_10160701_54_dialog_content = "追いかける必要はないよ。\nもうすぐここを通るから。",
  ui_story_1016_10160701_55_dialog_content = "あ、何か音がするわ…",
  ui_story_1016_10160701_56_dialog_content = "ふっふ～ん、さあさあ捕まえてみて～。",
  ui_story_1016_10160701_57_dialog_content = "ミンチ、少しスピードを落として…",
  ui_story_1016_10160701_58_dialog_content = "ちょっと待って！何かおかしい！",
  ui_story_1016_10160701_59_dialog_content = "ディシスたちの後ろから大量の暗鬼がついてくる！",
  ui_story_1016_10160701_60_dialog_content = "え？",
  ui_story_1016_10160701_61_dialog_content = "あまりにも騒がしいから、暗鬼を引きつけてしまったんだわ！",
  ui_story_1016_10160701_62_dialog_content = "しかも…あの3人、暗鬼を倒す気はないみたい…",
  ui_story_1016_10160701_63_dialog_content = "ただ暗鬼を連れて走ってるだけだ。",
  ui_story_1016_10160701_64_dialog_content = "何をしてるの…？戦いをお遊びだとでも思ってるのかしら？",
  ui_story_1016_10160701_65_dialog_content = "さっき言ったことを改めるわ。彼らに明確な目標などない。\n巻き込まれないように、急いでこの場を離れましょう。",
  ui_story_1016_10160701_66_dialog_content = "僕もそう思う。ただ…",
  ui_story_1016_10160701_67_dialog_content = "3人はまっすぐこっちに走ってくる！",
  ui_story_1016_10160701_68_dialog_content = "ミンチ、この先に空の末裔のチームがいますメェ。",
  ui_story_1016_10160701_69_dialog_content = "わあ～、空の末裔か！\n面白いじゃん、一緒に遊んでもらおうっと！",
  ui_story_1016_10160701_70_dialog_content = "<size=50>助けて～！暗鬼に食べられちゃう、早く助けて！</size>",
  ui_story_1016_10160701_71_dialog_content = "大変だ、見つかっちゃった…",
  ui_story_1016_10160701_72_dialog_content = "…",
  ui_story_1016_10160701_73_dialog_content = "ディシスチーム、よく聞きなさい！",
  ui_story_1016_10160701_74_dialog_content = "即方向転換し、戦闘を開始せよ！",
  ui_story_1016_10160701_75_dialog_content = "え？なんなの？あたしらに命令してんの！？",
  ui_story_1016_10160701_76_dialog_content = "そちらが即方向転換し戦うなら、私たちも協力する。",
  ui_story_1016_10160701_77_dialog_content = "ただし、そのまま走り続けるなら、\nあなたたちを攻撃するわ。",
  ui_story_1016_10160701_78_dialog_content = "え！？攻撃するの！？",
  ui_story_1016_10160701_79_dialog_content = "こちらが主導権をとるためよ。",
  ui_story_1016_10160701_80_dialog_content = "もうイヤだなぁ。そんなに敵意むき出しにしなくてもいいじゃん。\nミンチはただ一緒に遊びたいだけだよ。",
  ui_story_1016_10160701_81_dialog_content = "じゃ、言うこと聞いて協力しよ！",
  ui_story_1016_10160701_82_dialog_content = "メリー、方向転換して暗鬼をとことん懲らしめてやろう！",
  ui_story_1016_10160701_83_dialog_content = "ずっとそうしたかったところです！",
  ui_story_1016_10160701_84_dialog_content = "戦い始めたよ。僕たちも行こう！",
  ui_story_1016_10160701_85_dialog_content = "ええ。速戦即決よ！",
  ui_story_1016_10160802_1_dialog_content = "<anim type=Shake>グ…！</anim>",
  ui_story_1016_10160802_2_dialog_content = "ふふ、思ったより簡単じゃん。",
  ui_story_1016_10160802_3_dialog_content = "でも、他のチームは全部私たちより先に進んでるわ。",
  ui_story_1016_10160802_4_dialog_content = "まったく…暗鬼と戦ってばかりで、\nこのままじゃ他のチームには追いつけなくなりそうだわ…",
  ui_story_1016_10160802_5_dialog_content = "ねえ、錯覚かもしれないけど、\nこの暗い色の服着た3人組に会ってから…",
  ui_story_1016_10160802_6_dialog_content = "何だかずっとツイてない気がする…",
  ui_story_1016_10160802_7_dialog_content = "今愚痴を言っても仕方ないわ。",
  ui_story_1016_10160802_8_dialog_content = "ただこのままだと、本当に優勝は無理になってしまう…",
  ui_story_1016_10160802_9_dialog_content = "急ぎましょう。ディシスチームも私たちに付いてくるといいわ。",
  ui_story_1016_10160802_10_dialog_content = "ご忠告ありがとうございます。\nしかし僕たちは奥まで進むつもりはありません。",
  ui_story_1016_10160802_11_dialog_content = "他にやらなければならない大切なことがあるので。",
  ui_story_1016_10160802_12_dialog_content = "（この人たち、なんかヘンな感じだな…）",
  ui_story_1016_10160802_13_dialog_content = "そういうことなら、PlayerName、バイス。\n私たちは急ぎましょう。",
  ui_story_1016_10160802_14_dialog_content = "ええ、そうね。",
  ui_story_1016_10160802_15_dialog_content = "<color=#e8d9bb>暗面、シェルター深部では</color>",
  ui_story_1016_10160802_16_dialog_content = "他のチームを見かけたか？",
  ui_story_1016_10160802_17_dialog_content = "いいえ。今の状況から考えると、\n私たちが最も奥に進んでいるようですね。",
  ui_story_1016_10160802_18_dialog_content = "よし、いい調子だ。\n想定よりもずっと簡単なようだ。",
  ui_story_1016_10160802_19_dialog_content = "とはいえ…騎士と軍師、\nそれから強大な光力術の使い手である牧師――",
  ui_story_1016_10160802_20_dialog_content = "この3人のチームが失敗するというのは、\n考えにくいことだがな。",
  ui_story_1016_10160802_21_dialog_content = "ハハ、あなたという人は謙虚さの欠片もありませんね。",
  ui_story_1016_10160802_22_dialog_content = "すでに優位に立っているならば、\nこの勢いに乗じ、さらに追い打ちをかけるのがいいでしょう。",
  ui_story_1016_10160802_23_dialog_content = "ガルー教官――",
  ui_story_1016_10160802_24_dialog_content = "はいはい、聞こえてるよ。",
  ui_story_1016_10160802_25_dialog_content = "残りの単位全部と目的地の詳細な座標情報を交換させてください。",
  ui_story_1016_10160802_26_dialog_content = "う～ん、それはかまわないけど、\nずいぶん単位遣いが荒いね。",
  ui_story_1016_10160802_27_dialog_content = "すでに最終ステージに入っているのです。\n使えるものはすべて使い切るのが上策です。",
  ui_story_1016_10160802_28_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1016_10160802_29_dialog_content = "はい、地図を見てみて。光ってるエリアが目的地だよ。",
  ui_story_1016_10160802_30_dialog_content = "これもルールの範囲内だから、不正行為とは言えないね。",
  ui_story_1016_10160802_31_dialog_content = "ルールを存分に利用し、活かすのはゲームの鉄則だからね。\nあたしも見てて楽しくなっちゃうな。",
  ui_story_1016_10160802_32_dialog_content = "さあ急いで。頑張ってステージクリアしてね～！",
  ui_story_1016_10160802_33_dialog_content = "これで準備万端です。",
  ui_story_1016_10160802_34_dialog_content = "他のチームが追いついて来ないうちに、先を急ぎましょう。",
  ui_story_1016_10160802_35_dialog_content = "<color=#e8d9bb>暗面、シェルター奥深くの目的地付近</color>",
  ui_story_1016_10160802_36_dialog_content = "<anim type=Shake>グ…！</anim>",
  ui_story_1016_10160802_37_dialog_content = "さあ、これで最後の1匹も倒しました。",
  ui_story_1016_10160802_38_dialog_content = "暗闇に心を捧げたあなたたちにも、\n光の神の恩恵が下り、苦しみから放たれんことを。",
  ui_story_1016_10160802_39_dialog_content = "その言葉を口にしているあなたこそ恐ろしい存在に思えますが…",
  ui_story_1016_10160802_40_dialog_content = "旗のある位置に限りなく近づいているとはいえ、\n具体的な場所まで探し当てるのは、やはり難しいな…",
  ui_story_1016_10160802_41_dialog_content = "これだけ大きいシェルター内で、\n最も可能性の高い場所は…",
  ui_story_1016_10160802_42_dialog_content = "<color=#e8d9bb>バン――バン！</color>",
  ui_story_1016_10160802_43_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10160802_44_dialog_content = "伏兵がいるぞ！",
  ui_story_1016_10160802_45_dialog_content = "目標の位置なら情報官にお任せください。",
  ui_story_1016_10160802_46_dialog_content = "お待たせしました。皆さんが暗鬼を倒してくれたおかげで、\n比較的安全に決戦ができそうです。",
  ui_story_1016_10160802_47_dialog_content = "<size=32>…</size>",
  ui_story_1016_10160802_48_dialog_content = "<size=32>レオ団長、先を越されたようです。</size>",
  ui_story_1016_10160802_49_dialog_content = "<size=32>ここは彼らのホームグラウンドです。想定しておくべきことでした。</size>",
  ui_story_1016_10160802_50_dialog_content = "我々に向けて引き金を引いたということは、\n奴らの意図は明白だな。",
  ui_story_1016_10160802_51_dialog_content = "争いは避けられん。\n同時に2チームが優勝することはないからな。",
  ui_story_1016_10160802_52_dialog_content = "そうとなれば、真剣勝負といきましょうか。",
  ui_story_1016_10160802_53_dialog_content = "アクセリア、戦闘準備です。",
  ui_story_1016_10160901_1_dialog_content = "<color=#e8d9bb>バン――バンバン！</color>",
  ui_story_1016_10160901_2_dialog_content = "なかなか厄介な相手のようですね。",
  ui_story_1016_10160901_3_dialog_content = "私も今は手を貸せません。レオ団長、お気を付けください。\nそちらに突撃していきます。",
  ui_story_1016_10160901_4_dialog_content = "まだ終わりではありません。",
  ui_story_1016_10160901_5_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10160901_6_dialog_content = "レオ騎士団長！",
  ui_story_1016_10160901_7_dialog_content = "助かったぞ！",
  ui_story_1016_10160901_8_dialog_content = "細い身体をしていながら、これだけの力を持っているとはな。",
  ui_story_1016_10160901_9_dialog_content = "啓光連邦はまさに人材の宝庫だ。\n何ともうらやましいかぎりではないか。",
  ui_story_1016_10160901_10_dialog_content = "キュービック。",
  ui_story_1016_10160901_11_dialog_content = "うっ！",
  ui_story_1016_10160901_12_dialog_content = "（行動を読まれたか？我々が一塊にならないようにするつもりか？）",
  ui_story_1016_10160901_13_dialog_content = "（今がチャンスです）",
  ui_story_1016_10160901_14_dialog_content = "（不当に得た装備で攻撃するのは、気分のいいものではありませんね）",
  ui_story_1016_10160901_15_dialog_content = "（そこまでして私たちを…いえ、このチームを勝たせようとするのも、\nあの方々の意志なのでしょうか？）",
  ui_story_1016_10160901_16_dialog_content = "（今は情報が少なすぎます。状況を見ながら、進むしかないでしょう）",
  ui_story_1016_10160901_17_dialog_content = "（ならば…弱点が見えました！）",
  ui_story_1016_10160901_18_dialog_content = "やはりそう来ましたね。",
  ui_story_1016_10160901_19_dialog_content = "<size=45>何！？</size>",
  ui_story_1016_10160901_20_dialog_content = "あなた方の行動は読めていましたよ。",
  ui_story_1016_10160901_21_dialog_content = "トワイライトシティの者を甘く見てはいけません。",
  ui_story_1016_10160901_22_dialog_content = "うっ！！",
  ui_story_1016_10160901_23_dialog_content = "（つ…強い！？）",
  ui_story_1016_10160901_24_dialog_content = "（これだけの装備があるというのに、防御が破られてしまいました…）",
  ui_story_1016_10160901_25_dialog_content = "（この方の実力は情報にあったほど単純ではないようです！）",
  ui_story_1016_10160901_26_dialog_content = "あなたを倒さねばならぬことを、どうかお許しください。",
  ui_story_1016_10160901_27_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10160901_28_dialog_content = "インゲル中佐、応援を要請します！",
  ui_story_1016_10160901_29_dialog_content = "何ですって！？",
  ui_story_1016_10160901_30_dialog_content = "アナトリア！",
  ui_story_1016_10160901_31_dialog_content = "このような時に気をそらすとは、\n大きなミスを犯しましたね！",
  ui_story_1016_10160901_32_dialog_content = "――！",
  ui_story_1016_10160901_33_dialog_content = "（まずいことになりましたね。主導権を握られてしまいました）",
  ui_story_1016_10160901_34_dialog_content = "<color=#e8d9bb>その頃、シェルターのある場所では</color>",
  ui_story_1016_10160901_35_dialog_content = "ここはいったいどこなんだろう？",
  ui_story_1016_10160901_36_dialog_content = "さっきはあのチームに付いていくことばかり考えてたけど、\nまさかこんな所に連れてこられるとは…",
  ui_story_1016_10160901_37_dialog_content = "見たところ、廊下のようね。",
  ui_story_1016_10160901_38_dialog_content = "ただ長い間使われていないのは明らかね。",
  ui_story_1016_10160901_39_dialog_content = "そうね。ホコリが積もってるだけじゃなく、\nクモの巣も張ってるわ。",
  ui_story_1016_10160901_40_dialog_content = "おかしなものがいつ出てきても不思議じゃない雰囲気ね…",
  ui_story_1016_10160901_41_dialog_content = "<anim type=Shake><size=45>ウウ…</size></anim>",
  ui_story_1016_10160901_42_dialog_content = "この気配は…皆、気を付けて！",
  ui_story_1016_10160901_43_dialog_content = "何か大きなものがこっちに来る！",
  ui_story_1016_10160901_44_dialog_content = "<anim type=Shake><size=50>グオォ――！！！</size></anim>",
  ui_story_1016_10160901_45_dialog_content = "あっ――！",
  ui_story_1016_10160901_46_dialog_content = "こ、これって…クモ！？",
  ui_story_1016_10160901_47_dialog_content = "警戒を緩めてはいけないわ。この敵かなり強そうよ。",
  ui_story_1016_10160901_48_dialog_content = "さっさと片付けよう！僕たちの目的はあくまで旗だ！",
  ui_story_1016_10160902_1_dialog_content = "<anim type=Shake><size=50>グオォ――！！！</size></anim>",
  ui_story_1016_10160902_2_dialog_content = "バイス、息を合わせましょ！",
  ui_story_1016_10160902_3_dialog_content = "分かったわ！",
  ui_story_1016_10160902_4_dialog_content = "氷花よ――！",
  ui_story_1016_10160902_5_dialog_content = "<anim type=Shake><size=50>グオオ！！！</size></anim>",
  ui_story_1016_10160902_6_dialog_content = "<size=45>今よ！</size>",
  ui_story_1016_10160902_7_dialog_content = "一撃必中！",
  ui_story_1016_10160902_8_dialog_content = "<anim type=Shake><size=40>グオォ――</size></anim>",
  ui_story_1016_10160902_9_dialog_content = "やっと倒したね…",
  ui_story_1016_10160902_10_dialog_content = "ふぅ…そうね。",
  ui_story_1016_10160902_11_dialog_content = "このクモ、すごく強かったわ！",
  ui_story_1016_10160902_12_dialog_content = "今までに遭遇した暗鬼なんて比べ物にならないくらいよ。",
  ui_story_1016_10160902_13_dialog_content = "確かにそうね。こんなに強い暗鬼が試験に出てくるのはおかしいわ。",
  ui_story_1016_10160902_14_dialog_content = "ただの演習だというのに、この暗鬼は強すぎる。\nしかもこんなへんぴな片隅に隠れているなんて…",
  ui_story_1016_10160902_15_dialog_content = "まさか誰かが故意に放ったの？",
  ui_story_1016_10160902_16_dialog_content = "それは分からないよ。\n単に僕たちの運が悪かったのかもしれないし。",
  ui_story_1016_10160902_17_dialog_content = "このシェルターはずいぶん長いこと廃墟だったみたいだから、\n暗鬼が出てもおかしくはないよ。",
  ui_story_1016_10160902_18_dialog_content = "この問題はまた今度話しましょ。",
  ui_story_1016_10160902_19_dialog_content = "ずいぶん遅れをとったわ。",
  ui_story_1016_10160902_20_dialog_content = "このままだと完全に負けてしまう。",
  ui_story_1016_10160902_21_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1016_10160902_22_dialog_content = "何の音！？",
  ui_story_1016_10160902_23_dialog_content = "暗鬼？",
  ui_story_1016_10160902_24_dialog_content = "まさか、また暗鬼が現れたの？",
  ui_story_1016_10160902_25_dialog_content = "いいえ、おそらく違うわ…",
  ui_story_1016_10160902_26_dialog_content = "<color=#e8d9bb>ドーン…ゴオオーン…バンバン…</color>",
  ui_story_1016_10160902_27_dialog_content = "よく聞いて。銃声と光力術の音が混じっているわ。\nしかもかなりの数よ、おそらく1チームではないわね。",
  ui_story_1016_10160902_28_dialog_content = "本当だわ。2チームが争っている音みたい！",
  ui_story_1016_10160902_29_dialog_content = "今回の目的は旗取りよ。他のチームと出会ったからといって、\n戦うのは得策ではないわ。1つの可能性を除いては…",
  ui_story_1016_10160902_30_dialog_content = "2チーム同時に旗を見つけない限り戦う必要はない！",
  ui_story_1016_10160902_31_dialog_content = "旗かな？",
  ui_story_1016_10160902_32_dialog_content = "まさか誰かもう旗を見つけたのかな？",
  ui_story_1016_10160902_33_dialog_content = "可能性はあるわ。よく聞いて。",
  ui_story_1016_10160902_34_dialog_content = "<color=#e8d9bb>ドーン…ゴオオーン…バンバン…</color>",
  ui_story_1016_10160902_35_dialog_content = "銃声と光力術の音が混じっているわ。\nしかもかなりの数よ、おそらく1チームではないわね。",
  ui_story_1016_10160902_36_dialog_content = "つまり、2つのチームが同時に旗を見つけて、\nその旗を奪うために戦いが始まったってこと？",
  ui_story_1016_10160902_37_dialog_content = "可能性はあるね！",
  ui_story_1016_10160902_38_dialog_content = "私たちも急がなくては！\nこのまま勝利を他チームに譲るわけにはいかないわ！",
  ui_story_1016_10160902_39_dialog_content = "ええ！",
  ui_story_1016_10160902_40_dialog_content = "<color=#e8d9bb>その頃、シェルターの深部では</color>",
  ui_story_1016_10160902_41_dialog_content = "ロックオン！",
  ui_story_1016_10160902_42_dialog_content = "<color=#e8d9bb>バンッ――！</color>",
  ui_story_1016_10160902_43_dialog_content = "行かせるか！",
  ui_story_1016_10160902_44_dialog_content = "（ここまで強いとは…主導権を失っているのに我々と互角に戦っている）",
  ui_story_1016_10160902_45_dialog_content = "（特にアナトリアとかいう情報官、あの装備はどうなっている？）",
  ui_story_1016_10160902_46_dialog_content = "（このチームの成績はずっと気に掛けていた。\n我々より低い単位数にも関わらず、我々よりもいい装備を持っている）",
  ui_story_1016_10160902_47_dialog_content = "（実に妙だ。どうやら啓光が大きな便宜を図ってやっているようだ）",
  ui_story_1016_10160902_48_dialog_content = "（いずれにせよ、トワイライトシティの状況は啓光の実戦派に伝わった。\n我々の目的はすでに達したといえる。ならば…）",
  ui_story_1016_10160902_49_dialog_content = "ヨーゼフ！",
  ui_story_1016_10160902_50_dialog_content = "はい！",
  ui_story_1016_10160902_51_dialog_content = "…",
  ui_story_1016_10160902_52_dialog_content = "（レオ騎士団長…？）",
  ui_story_1016_10160902_53_dialog_content = "分かりました。",
  ui_story_1016_10160902_54_dialog_content = "（攻撃の速度が落ちましたね。誘い込みか何かでしょうか？）",
  ui_story_1016_10160902_55_dialog_content = "（いいえ、これは絶好のチャンスです！）",
  ui_story_1016_10160902_56_dialog_content = "インゲル中佐！",
  ui_story_1016_10160902_57_dialog_content = "了解です！",
  ui_story_1016_10160902_58_dialog_content = "ショウ！陣形を縮小し、防御の構えを！",
  ui_story_1016_10160902_59_dialog_content = "分かりました！",
  ui_story_1016_10160902_60_dialog_content = "そうはいきません！",
  ui_story_1016_10160902_61_dialog_content = "<color=#e8d9bb>バン！バンバン――</color>",
  ui_story_1016_10160902_62_dialog_content = "まずいですね。退路を断たれました！",
  ui_story_1016_10160902_63_dialog_content = "アクセリア、今です！",
  ui_story_1016_10160902_64_dialog_content = "失礼しました。",
  ui_story_1016_10160902_65_dialog_content = "<color=#e8d9bb>ゴオォォン――！</color>",
  ui_story_1016_10160902_66_dialog_content = "うっ――！",
  ui_story_1016_10160902_67_dialog_content = "ショウがやられた！？",
  ui_story_1016_10160902_68_dialog_content = "出来るだけ私の方へ！光力術で援護します！",
  ui_story_1016_10160902_69_dialog_content = "ムダです。",
  ui_story_1016_10160902_70_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1016_10160902_71_dialog_content = "ゴホッ…ゴホゴホッ！",
  ui_story_1016_10160902_72_dialog_content = "さすがは啓光の最強兵器だ。恐ろしい力だな。",
  ui_story_1016_10160902_73_dialog_content = "そうとなれば、私にもどうしようもありません。",
  ui_story_1016_10160902_74_dialog_content = "そうだな。負けを認めよう。",
  ui_story_1016_10160902_75_dialog_content = "賢明な判断です。",
  ui_story_1016_10160902_76_dialog_content = "アクセリア、旗を取りに行ってください。",
  ui_story_1016_10160902_77_dialog_content = "了解しました。",
  ui_story_1016_10160902_78_dialog_content = "それでは、今回の優勝者は――",
  ui_story_1016_10160902_79_dialog_content = "<size=45>間に合った！！</size>",
  ui_story_1016_10160902_80_dialog_content = "…",
  ui_story_1016_10160902_81_dialog_content = "…",
  ui_story_1016_10160902_82_dialog_content = "……",
  ui_story_1016_10160902_83_dialog_content = "…のかしら？",
  ui_story_1016_10160902_84_dialog_content = "残念です。間に合いませんでした。",
  ui_story_1016_10160902_85_dialog_content = "あと5秒早く着いていれば、\nアクセリアとアクセリアの仲間と競い合うことができました。",
  ui_story_1016_10160902_86_dialog_content = "そうだったの…私たちずいぶんと時間を無駄にしていたようね。",
  ui_story_1016_10160902_87_dialog_content = "そんな、どうして…",
  ui_story_1016_10160902_88_dialog_content = "あと少しだったのに…",
  ui_story_1016_10160902_89_dialog_content = "悔やんでも仕方ないわ。",
  ui_story_1016_10160902_90_dialog_content = "勝敗は決まったのよ。今さら悔いても仕方ない。",
  ui_story_1016_10160902_91_dialog_content = "自分磨きに努めるしかないわ。",
  ui_story_1016_10160902_92_dialog_content = "そうね。カレンの言う通りね…",
  ui_story_1016_10160902_93_dialog_content = "それでは、成績を発表します。",
  ui_story_1016_10160902_94_dialog_content = "今回の試験優勝チームは――<color=#FFB400>インゲルチーム</color>です！",
  ui_story_1016_10160902_95_dialog_content = "そして、総合得点第1位は――\n<color=#FFB400>アクセリア</color>中尉！",
  ui_story_1016_10160902_96_dialog_content = "おめでとう。",
  ui_story_1016_10160902_97_dialog_content = "ありがとうございます。",
  ui_story_1016_10160902_98_dialog_content = "（ようやく無事終了です）",
  ui_story_1016_10160902_99_dialog_content = "アクセリア、勝ちました。",
  ui_story_1016_10160902_100_dialog_content = "予想通りです。",
  ui_story_1016_10160902_101_dialog_content = "（2人は驚いた様子も、喜ぶ様子もありませんね）",
  ui_story_1016_10160902_102_dialog_content = "（もともと感情を顔に出さない方だとはいえ、少しおかしいですね）",
  ui_story_1016_10160902_103_dialog_content = "（まさか、これも計画なのでしょうか…？）",
  ui_story_1016_10161001_1_dialog_content = "アクセリア中尉、おめでとうございます！",
  ui_story_1016_10161001_2_dialog_content = "中尉が優勝して、啓光じゅうが喜んでいますよ！",
  ui_story_1016_10161001_3_dialog_content = "アクセリアはやるべきことをやったまでです。",
  ui_story_1016_10161001_4_dialog_content = "申し訳ありませんが、道を開けてください――",
  ui_story_1016_10161001_5_dialog_content = "すぐにでもアクセリアを休ませなければなりません。",
  ui_story_1016_10161001_6_dialog_content = "あのお強いお嬢さん、啓光の皆さんに取り囲まれてしまいましたね。",
  ui_story_1016_10161001_7_dialog_content = "そうだな。",
  ui_story_1016_10161001_8_dialog_content = "ところで、レオ騎士団長。私たちにはなぜあなたが、\nあのような決断をしたのか知る権利があると思うのですが――",
  ui_story_1016_10161001_9_dialog_content = "なぜ自ら勝利を放棄なさったのです？",
  ui_story_1016_10161001_10_dialog_content = "我々の目的は達したからだ。",
  ui_story_1016_10161001_11_dialog_content = "トワイライトシティの状況はすでに啓光のラス軍団長に伝わった。\nラス軍団長は戦闘経験が豊富だ。我々の置かれている状況を理解できる。",
  ui_story_1016_10161001_12_dialog_content = "この情報はすぐに啓光の情報網を通じ、\n白夜城の上層部にも伝わるだろう。",
  ui_story_1016_10161001_13_dialog_content = "そうだとしても、合同演習で我々が勝利すべきであることは、\n変わらないと思いますが。",
  ui_story_1016_10161001_14_dialog_content = "我々が勝てば、より多くの関心が集まり、\nトワイライトシティにもより多くの援助がもたらされます。",
  ui_story_1016_10161001_15_dialog_content = "危機はもう目前に迫っているのです。\n勝算は大きければ大きいに越したことはありません。",
  ui_story_1016_10161001_16_dialog_content = "だが、お前も私の指示通り、負けることを選んだ。",
  ui_story_1016_10161001_17_dialog_content = "あなたの判断を信じているからです。\n私はただ理由を知りたいだけです。",
  ui_story_1016_10161001_18_dialog_content = "それでこそよりよい協力ができるというものでしょう？",
  ui_story_1016_10161001_19_dialog_content = "啓光のあのチーム、何か裏があるようだ。",
  ui_story_1016_10161001_20_dialog_content = "最初からあのチームには気を付けていたのだが、\n不可解な点が多かった。",
  ui_story_1016_10161001_21_dialog_content = "飛び抜けた実力があるにもかかわらず、\n奴らの今回の勝利は決して輝かしいとは言えん。",
  ui_story_1016_10161001_22_dialog_content = "それは…不当な手段を用いていた、という意味ですか？",
  ui_story_1016_10161001_23_dialog_content = "確かな証拠があるわけではないが、ほぼ確信はある。",
  ui_story_1016_10161001_24_dialog_content = "最後の戦いで使っていた装備は、\n奴らの単位で交換できる装備の上をいっていた。",
  ui_story_1016_10161001_25_dialog_content = "もちろん、悟られんように差はわずかに抑えていたが、\nあの装備があれば、奴らの実力は確実に一段階は上がるだろう。",
  ui_story_1016_10161001_26_dialog_content = "背後に誰が付いている。",
  ui_story_1016_10161001_27_dialog_content = "啓光の上層部でしょうか？",
  ui_story_1016_10161001_28_dialog_content = "そうかもしれん。\nとにかく、あのチームの勝利は計画されたものだ。",
  ui_story_1016_10161001_29_dialog_content = "そして、真の目的も勝利そのものではなく、\n他の何かだろう。",
  ui_story_1016_10161001_30_dialog_content = "勝利は真の目的ではないが、\n目的達成の必要条件ということですね…",
  ui_story_1016_10161001_31_dialog_content = "となると…",
  ui_story_1016_10161001_32_dialog_content = "さあな。",
  ui_story_1016_10161001_33_dialog_content = "ここもすぐに太平ではなくなるかもしれんな。",
  ui_story_1016_10161001_34_dialog_content = "なによ――",
  ui_story_1016_10161001_35_dialog_content = "トワイライトシティチームのために用意した「おまけ」、\n全部あのPlayerNameのチームにやられちゃったワケ…？",
  ui_story_1016_10161001_36_dialog_content = "あいつらただ運が悪かったの？\nそれともわざとあたしらの計画を潰したの？",
  ui_story_1016_10161001_37_dialog_content = "状況から考えて、すべて偶然でしょう。\nそれに、結果としては悪くはありません。",
  ui_story_1016_10161001_38_dialog_content = "トワイライトシティのチームは演習期間中に充分実力を証明して見せましたし、\n「おまけ」も予想外の発見をもたらしてくれました。",
  ui_story_1016_10161001_39_dialog_content = "注目するに値する強者がこれだけたくさんいると知れば、\n「あのお方」もきっとお喜びになります。",
  ui_story_1016_10161001_40_dialog_content = "空の末裔のチームも予想よりも早くスパイダークイーンを倒しました。\n彼らの実力も大きく伸びているという証拠でしょう。",
  ui_story_1016_10161001_41_dialog_content = "でも、私たちのせいで空の末裔チームは\n優勝を逃してしまったようですよ。",
  ui_story_1016_10161001_42_dialog_content = "怒っていなければいいんですがメェ…",
  ui_story_1016_10161001_43_dialog_content = "<anim type=Shake>ふわぁ～</anim>、ああ眠い。",
  ui_story_1016_10161001_44_dialog_content = "ねえ、いつになったら帰れるの？\n3日くらいずっと寝てたい気分なんだけど…",
  ui_story_1016_10161001_45_dialog_content = "そう急がないでください、ミンチ。",
  ui_story_1016_10161001_46_dialog_content = "やることがまだ残ってるんです。\nまだ帰れれませんよ、メェ～。",
  ui_story_1016_10161001_47_dialog_content = "その通りです。とても重要な仕事が残っています。",
  ui_story_1016_10161001_48_dialog_content = "<color=#e8d9bb>カナン城、ユリシーズの事務所</color>",
  ui_story_1016_10161001_49_dialog_content = "久々のカナン城ですね。",
  ui_story_1016_10161001_50_dialog_content = "これから起こることは啓光の新しい歴史の1ページとなるでしょう。",
  ui_story_1016_10161001_51_dialog_content = "おや？これは…？",
  ui_story_1016_10161001_52_dialog_content = "彼女の計画は実に緻密で困りますね。\nひと休みする暇もありません。",
  ui_story_1016_10161001_53_dialog_content = "アイゼン、ちょっと来てください。",
  ui_story_1016_10161001_54_dialog_content = "はい。",
  ui_story_1016_10161001_55_dialog_content = "<color=#e8d9bb>トントントン</color>",
  ui_story_1016_10161001_56_dialog_content = "長官、何か御用でしょうか？",
  ui_story_1016_10161001_57_dialog_content = "これを「<color=#FFB400>鉄仮面</color>」殿に渡し、\nこう伝えてください――",
  ui_story_1016_10161001_58_dialog_content = "これは私が作成した都市防御体制の調整計画です。\n協力をお願いしたい、と。",
  ui_story_1016_10161001_59_dialog_content = "承知いたしました。",
  ui_story_1016_10161001_60_dialog_content = "<color=#e8d9bb>その頃、カナン城某所では</color>",
  ui_story_1016_10161001_61_dialog_content = "まだその時じゃないっていうのに、\n啓光のヤツらの追跡が厳しくなっているわ。",
  ui_story_1016_10161001_62_dialog_content = "あの古だぬき、そんなに私の実験成果が欲しいの…？",
  ui_story_1016_10161001_63_dialog_content = "それなら、ジェイドに…",
  ui_story_1016_10161001_64_dialog_content = "…",
  ui_story_1016_10161001_65_dialog_content = "あの子は…もう遠くまで行ってる頃ね。",
  ui_story_1016_10161001_66_dialog_content = "デニール！",
  ui_story_1016_10161001_67_dialog_content = "姉さん？どうしたの？",
  ui_story_1016_10161001_68_dialog_content = "今日は何の日か覚えているか？",
  ui_story_1016_10161001_69_dialog_content = "今日が何の日か…？",
  ui_story_1016_10161001_70_dialog_content = "実験報告の提出日だったかしら？\nそれとも試験前最後の日？",
  ui_story_1016_10161001_71_dialog_content = "どちらも間違いだ！",
  ui_story_1016_10161001_72_dialog_content = "まさか忘れたのか？今日はお前の誕生日だ！",
  ui_story_1016_10161001_73_dialog_content = "私の誕生日？ああ…確かにそうだったかも。",
  ui_story_1016_10161001_74_dialog_content = "自分の誕生日も忘れたのか？",
  ui_story_1016_10161001_75_dialog_content = "別に重要な日でもないじゃない。\n「誕生日」と定義されている以外、他の日と何も変わりやしないわ。",
  ui_story_1016_10161001_76_dialog_content = "まったく…お前らしいな。",
  ui_story_1016_10161001_77_dialog_content = "いや…そのような冷静で理性的な考えを持っているのは、\nお前くらいだと言うべきか。",
  ui_story_1016_10161001_78_dialog_content = "だが、お前自身は気にしていなくとも、\n他の者は気にしているぞ。",
  ui_story_1016_10161001_79_dialog_content = "え？",
  ui_story_1016_10161001_80_dialog_content = "誕生日プレゼントを用意した。",
  ui_story_1016_10161001_81_dialog_content = "これだ！",
  ui_story_1016_10161001_82_dialog_content = "キュウ！",
  ui_story_1016_10161001_83_dialog_content = "これは！？",
  ui_story_1016_10161001_84_dialog_content = "ハハハ、どうやら気に入られてしまったようだな！",
  ui_story_1016_10161001_85_dialog_content = "以前戦場で拾ったのだ。\n何の動物かは知らんが、なかなか大人しくてな。",
  ui_story_1016_10161001_86_dialog_content = "連れ帰って数日間おがくずパンをやって面倒を見ていたのだが、\nどうやらおがくずパンは好みでないらしい。",
  ui_story_1016_10161001_87_dialog_content = "私がそばにいてやれない時、そいつがお前のそばにいてくれる。",
  ui_story_1016_10161001_88_dialog_content = "あなたって人は…",
  ui_story_1016_10161001_89_dialog_content = "この子はチンチラっていうの。\n普通はパンなんて食べないのよ。",
  ui_story_1016_10161001_90_dialog_content = "ちゃんと飼うつもりなら、干し草や穀物じゃないと。\nニンジンをあげてもいいわ。",
  ui_story_1016_10161001_91_dialog_content = "やはりお前に託して正解だったようだ。",
  ui_story_1016_10161001_92_dialog_content = "チンチラも実験動物として使われるの。\n実験動物を飼育することも研究の一環よ。",
  ui_story_1016_10161001_93_dialog_content = "<anim type=Shake><size=45>キュウ！！</size></anim>",
  ui_story_1016_10161001_94_dialog_content = "おや、怖がらせてしまったようだぞ！",
  ui_story_1016_10161001_95_dialog_content = "…",
  ui_story_1016_10161001_96_dialog_content = "<anim type=Shake>キュウ…</anim>",
  ui_story_1016_10161001_97_dialog_content = "姉さんからのプレゼントなら、\n実験に使うわけにもいかないわね。",
  ui_story_1016_10161001_98_dialog_content = "ということは、受け取ってくれるのか？",
  ui_story_1016_10161001_99_dialog_content = "ええ。",
  ui_story_1016_10161001_100_dialog_content = "では、名前を付けてやろうではないか。",
  ui_story_1016_10161001_101_dialog_content = "名前ねぇ…",
  ui_story_1016_10161001_102_dialog_content = "「<color=#FFB400>ジェイド</color>」にしましょ。",
  ui_story_1016_10161001_103_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_1016_10161001_104_dialog_content = "実験が…私の実験が…",
  ui_story_1016_10161001_105_dialog_content = "何もかもなくなってしまったわ…",
  ui_story_1016_10161001_106_dialog_content = "レインハト、なぜ？今度もまた来てくれないのね？",
  ui_story_1016_10161001_107_dialog_content = "<anim type=Shake><size=45>キュウ――キュウ――</size></anim>",
  ui_story_1016_10161001_108_dialog_content = "ジェイド…",
  ui_story_1016_10161001_109_dialog_content = "私がそばにいてやれない時、そいつがお前のそばにいてくれる。",
  ui_story_1016_10161001_110_dialog_content = "今度もまた…！",
  ui_story_1016_10161001_111_dialog_content = "<anim type=Shake><size=45>キュウ！キュウ――！！</size></anim>",
  ui_story_1016_10161001_112_dialog_content = "<anim type=Shake>キュウ…</anim>",
  ui_story_1016_10161001_113_dialog_content = "――！！！",
  ui_story_1016_10161001_114_dialog_content = "キュウ！",
  ui_story_1016_10161001_115_dialog_content = "<anim type=Shake>キュウ…キュウ…</anim>",
  ui_story_1016_10161001_116_dialog_content = "なぜなの？私があと少し力を入れれば、\nあなたは首をへし折られるところだったのに…",
  ui_story_1016_10161001_117_dialog_content = "なぜ、あの人のように逃げなかったの？",
  ui_story_1016_10161001_118_dialog_content = "<anim type=Shake><size=32>キュウ…</size></anim>",
  ui_story_1016_10161001_119_dialog_content = "…",
  ui_story_1016_10161001_120_dialog_content = "まあいいわ…",
  ui_story_1016_10161001_121_dialog_content = "そばにいさせてあげるわ。",
  ui_story_1016_10161001_122_dialog_content = "少なくとも、実験動物としての価値はある。",
  ui_story_1016_10161001_123_dialog_content = "「価値」…ね。",
  ui_story_1016_10161001_124_dialog_content = "この世界では、確かに「価値」だけが\n物事を測る絶対的な基準だわ。",
  ui_story_1016_10161001_125_dialog_content = "<color=#e8d9bb>カサカサ…</color>",
  ui_story_1016_10161001_126_dialog_content = "デニール…何か来る…気を付けろ…",
  ui_story_1016_10161001_127_dialog_content = "グォォ…",
  ui_story_1016_10161001_128_dialog_content = "暗鬼…だ！",
  ui_story_1016_10161001_129_dialog_content = "…",
  ui_story_1016_10161001_130_dialog_content = "武器を下ろしなさい。あなたを傷つけやしないわ。",
  ui_story_1016_10161001_131_dialog_content = "『ノラ様、<color=#FFB400>フィジェロ</color>様からの伝言を\n預かってまいりました。』",
  ui_story_1016_10161001_132_dialog_content = "『話してちょうだい。』",
  ui_story_1016_10161001_133_dialog_content = "『内側から啓光の防御体制を崩し、\n「<color=#FFB400>要人</color>」をお迎えせよ、とのことです』",
  ui_story_1016_10161001_134_dialog_content = "『やっと時が来たのね。』",
  ui_story_1016_10161001_135_dialog_content = "<color=#e8d9bb>エキシビジョン当日、試合開始15分前</color>",
  ui_story_1016_10161001_136_dialog_content = "はぁ――",
  ui_story_1016_10161001_137_dialog_content = "カレンの2連勝達成…成らなかったわね…",
  ui_story_1016_10161001_138_dialog_content = "はぁ…",
  ui_story_1016_10161001_139_dialog_content = "そんなに落ち込むことないわ。悔しがることもないわよ。",
  ui_story_1016_10161001_140_dialog_content = "この演習に参加してるのは各勢力のトップクラスの人材よ。\n私より強い人がいて当然だわ。",
  ui_story_1016_10161001_141_dialog_content = "勝ちも負けも最初から決まっているものではないわ。\n今回負けたことで、さらに強い人たちの存在を知った。新しい目標ができたのよ。",
  ui_story_1016_10161001_142_dialog_content = "カレンったら、また飛び切りカッコいいこと言ってくれるのね。",
  ui_story_1016_10161001_143_dialog_content = "そ、そうかしら？",
  ui_story_1016_10161001_144_dialog_content = "試合を観に来たのか？",
  ui_story_1016_10161001_145_dialog_content = "レオ、君も観に来たんだね。",
  ui_story_1016_10161001_146_dialog_content = "ショウとヨーゼフは一緒じゃないの？",
  ui_story_1016_10161001_147_dialog_content = "ここ数日の演習でショウは過労気味でな。\n体調を崩しているから、観戦には来られない。",
  ui_story_1016_10161001_148_dialog_content = "今医療センターで検査を受けている。\nヨーゼフが付き添いでな。",
  ui_story_1016_10161001_149_dialog_content = "仲良くなったんだね。お互い面倒を見るなんて。",
  ui_story_1016_10161001_150_dialog_content = "ハハハ、そうかもしれんな。",
  ui_story_1016_10161001_151_dialog_content = "今回協力したことで互いに理解を深めることができた。",
  ui_story_1016_10161001_152_dialog_content = "異なる陣営に属してはいても、\n互いに尊敬し合う友となり、良き敵となれるのだ。",
  ui_story_1016_10161001_153_dialog_content = "敵であり、友である…",
  ui_story_1016_10161001_154_dialog_content = "奥深い言葉ね。",
  ui_story_1016_10161001_155_dialog_content = "あれはインゲル中佐かしら？それと…アナトリア少佐？",
  ui_story_1016_10161001_156_dialog_content = "え？どこ？挨拶しに行く？",
  ui_story_1016_10161001_157_dialog_content = "ほら、あそこよ。審判席の隣にいるわ。",
  ui_story_1016_10161001_158_dialog_content = "そんな、どうして…",
  ui_story_1016_10161001_159_dialog_content = "まさか暗鬼の仕業ですか？",
  ui_story_1016_10161001_160_dialog_content = "状況は緊急を要します。",
  ui_story_1016_10161001_161_dialog_content = "行きましょう。",
  ui_story_1016_10161001_162_dialog_content = "二人ともあんなに厳しい顔してどうしたのかしら？",
  ui_story_1016_10161001_163_dialog_content = "でも、離れてるから何を話しているか、\nまったく分からないわ。",
  ui_story_1016_10161001_164_dialog_content = "ううむ、何か重大事でも起こったのか？",
  ui_story_1016_10161001_165_dialog_content = "直接聞いてみればいい。",
  ui_story_1016_10161001_166_dialog_content = "白夜城の者がなぜそんなに啓光のことに関心を持つのかしら？",
  ui_story_1016_10161001_167_dialog_content = "殿下、私は啓光の事に関心はありません。\nしかし、トワイライトシティの事となれば別です。",
  ui_story_1016_10161001_168_dialog_content = "殿下もお聞き及びでしょう？トワイライトシティは今暗鬼侵攻の危機に直面しています。\nその危機は日増しに現実味を増しているのです。",
  ui_story_1016_10161001_169_dialog_content = "トワイライトシティはその安全を守るため、\nさらに多くの力を必要としています。",
  ui_story_1016_10161001_170_dialog_content = "そして今、啓光は何か面倒事に見舞われており、\n助けが必要なようです。",
  ui_story_1016_10161001_171_dialog_content = "適切な時に啓光の未来の上層部たる人物に恩を売っておくのも、\n上策だと考えているにすぎません。",
  ui_story_1016_10161001_172_dialog_content = "トワイライトシティのことも、\n今危機に見舞われていることも知っているわ。",
  ui_story_1016_10161001_173_dialog_content = "白夜城の上層部に報告し、対策を協議してもらうつもりよ。",
  ui_story_1016_10161001_174_dialog_content = "トワイライトシティに関心をもっていただき、\n感謝いたします。",
  ui_story_1016_10161001_175_dialog_content = "ただ、これまでの経験からして、\nこの件はおそらくうやむやにされるでしょうな。",
  ui_story_1016_10161001_176_dialog_content = "トワイライトシティが必要としているのは、\n口約束ではなく、実際の援助です。",
  ui_story_1016_10161001_177_dialog_content = "…",
  ui_story_1016_10161001_178_dialog_content = "何とか方法を考えてみるわ。",
  ui_story_1016_10161001_179_dialog_content = "感謝したします。\n私自身もより多くの援助を得られるよう努力を続けます。",
  ui_story_1016_10161001_180_dialog_content = "1人でも多くの人に恩を売れば、トワイライトシティの利益になります。",
  ui_story_1016_10161001_181_dialog_content = "皆さんはこちらで観戦なさっていてください。\n私は少し失礼させていただきます。",
  ui_story_1016_10161001_182_dialog_content = "私も行きます。私は啓光の軍人です。\nもし何か面倒な事が起こっているのなら、手助けする義務があります。",
  ui_story_1016_10161001_183_dialog_content = "僕も行くよ！",
  ui_story_1016_10161001_184_dialog_content = "私も行くわ。",
  ui_story_1016_10161001_185_dialog_content = "では、一緒に参りましょう。",
  ui_story_1016_10161001_186_dialog_content = "原因と容疑者は分かっているのですか？",
  ui_story_1016_10161001_187_dialog_content = "現在調査中です。",
  ui_story_1016_10161001_188_dialog_content = "カナン城の防御システムのうち、\n全部でいくつが損壊したのですか？",
  ui_story_1016_10161001_189_dialog_content = "今分かっている限りで申しますと、\n16%前後が破壊され、完全に機能を失っています。",
  ui_story_1016_10161001_190_dialog_content = "まだ半分近くの状況が分かっていませんが、\nカナン城はあまりにも大きく、道も複雑なため…",
  ui_story_1016_10161001_191_dialog_content = "ただ、すでに破壊された防御設備だけでも、\nカナン城の防御体制に穴を開けるには十分であり、状況は非常に危機的です。",
  ui_story_1016_10161001_192_dialog_content = "このような大切な時に混乱を起こすとは…\nまさかノラの仕業でしょうか…？",
  ui_story_1016_10161001_193_dialog_content = "可能性は高いと思われます。",
  ui_story_1016_10161001_194_dialog_content = "私に付いてきてください。即刻上層部に報告…",
  ui_story_1016_10161001_195_dialog_content = "インゲル、アナトリア、ちょっと待って！",
  ui_story_1016_10161001_196_dialog_content = "PlayerNameさん？\nバイス中尉と白夜城の方々までどうされたのですか？",
  ui_story_1016_10161001_197_dialog_content = "エキシビジョンはまもなく始まりますよ。\nなぜ試合を観ずにこちらへ？",
  ui_story_1016_10161001_198_dialog_content = "慌てて会場を離れる様子を見たのでな。\n何か面倒な事でも起こったのかと思ったのだ。",
  ui_story_1016_10161001_199_dialog_content = "必要とあらば、私も何か手助けしよう。",
  ui_story_1016_10161001_200_dialog_content = "自らすすんで手助けを申し出るとは、らしからぬ行為ですね。\nそれに啓光の者でもないのに、なぜ関心をお持ちになるのですか？",
  ui_story_1016_10161001_201_dialog_content = "そちらがそう言うのなら、私もはっきり言おう。",
  ui_story_1016_10161001_202_dialog_content = "私が手助けしようと申し出たのは、\n今後そちらにもトワイライトシティを助けてもらいたいからだ。",
  ui_story_1016_10161001_203_dialog_content = "では、なぜ私たちが助けを必要としていると思ったのですか？",
  ui_story_1016_10161001_204_dialog_content = "もっと言えば、私は一介の情報官にすぎず、啓光を代表する立場にはありません。\n啓光を動かし、あなた方に援助することはできませんよ。",
  ui_story_1016_10161001_205_dialog_content = "それくらいのことはもちろん分かっているさ。\n私が必要としているのは啓光の助けではない、君と君の仲間の助けだ。",
  ui_story_1016_10161001_206_dialog_content = "君たちはいずれも強大な実力を持っている。\nトワイライトシティはまさにそうした強者の助けを必要としているのだ。",
  ui_story_1016_10161001_207_dialog_content = "それに…",
  ui_story_1016_10161001_208_dialog_content = "今まさに合同演習最後のエキシビジョンが始まろうとしている。\n人員はほぼ観戦か、会場の警備に割かれてしまっているはずだ。",
  ui_story_1016_10161001_209_dialog_content = "人手が足らんだろう？",
  ui_story_1016_10161001_210_dialog_content = "…",
  ui_story_1016_10161001_211_dialog_content = "インゲル、もし本当に何かあったなら、\n仲間として僕たちも見て見ぬふりはできないよ。",
  ui_story_1016_10161001_212_dialog_content = "「ノラ」が関わってるならなおさらだよ…",
  ui_story_1016_10161001_213_dialog_content = "ノラですって！？",
  ui_story_1016_10161001_214_dialog_content = "君は…",
  ui_story_1016_10161001_215_dialog_content = "ごめん、さっき来る途中で聞こえちゃったんだ。\n盗み聞きしようと思ったわけじゃないんだけど…",
  ui_story_1016_10161001_216_dialog_content = "空の末裔の能力とは実に便利なものですね。",
  ui_story_1016_10161001_217_dialog_content = "本当にごめん…",
  ui_story_1016_10161001_218_dialog_content = "インゲル中佐、今の状況を話していただけますか？\nもしノラが関わっているなら、私たちも手をこまねいてなどいられません！",
  ui_story_1016_10161001_219_dialog_content = "いく度となく一緒に戦ったじゃありませんか！\n私たちを信じてください！",
  ui_story_1016_10161001_220_dialog_content = "お願いだよ！",
  ui_story_1016_10161001_221_dialog_content = "…",
  ui_story_1016_10161001_222_dialog_content = "あなたの推測した通りです。\n今私たちは確かに助けを必要としています。",
  ui_story_1016_10161001_223_dialog_content = "カナン城の防御設備に故障が発生しました。\nすぐにでも人員を回して防御を補充し、破壊された設備を点検しなければなりません。",
  ui_story_1016_10161001_224_dialog_content = "しかし、人手が足りていないのです。\n皆さんの手を貸してください。",
  ui_story_1016_10161001_225_dialog_content = "ただし、条件があります。\nノラもしくは他のファントムの痕跡を発見した場合、すぐに我々に知らせてください。",
  ui_story_1016_10161001_226_dialog_content = "ノラもしくは…他のファントム！？",
  ui_story_1016_10161001_227_dialog_content = "彼らを捕まえた場合も、啓光に引き渡してください。",
  ui_story_1016_10161001_228_dialog_content = "ここは君たちの土地だ。その通りにしよう。",
  ui_story_1016_10161001_229_dialog_content = "防御設備が壊されたんですか？",
  ui_story_1016_10161001_230_dialog_content = "深刻な状況なの？",
  ui_story_1016_10161001_231_dialog_content = "深刻と言えば深刻ですし、\n深刻ではないと言えば深刻でないと言えましょう。",
  ui_story_1016_10161001_232_dialog_content = "故障自体は深刻ではありませんが、今は特殊な時期であることと\nノラがカナン城内に潜伏している可能性を考えると――",
  ui_story_1016_10161001_233_dialog_content = "万全の対策を講じて臨む必要があります。\n手抜かりは一切許されません。",
  ui_story_1016_10161001_234_dialog_content = "かの啓光の反逆者が今カナン城内にいると言うのか？",
  ui_story_1016_10161001_235_dialog_content = "（それが本当なら、以前遭遇した暗鬼もおそらく奴の手下だろう）",
  ui_story_1016_10161001_236_dialog_content = "今はまだノラの足取りをつかめていませんが、\nその可能性は非常に高いと言えます。",
  ui_story_1016_10161001_237_dialog_content = "皆さんも十分お気を付けください。",
  ui_story_1016_10161001_238_dialog_content = "アナトリア少佐、皆さんに担当エリアをお伝えしてください。",
  ui_story_1016_10161001_239_dialog_content = "はい。",
  ui_story_1016_10161001_240_dialog_content = "バイス中尉はカナン城に詳しいので、\nあなたが皆さんを率いてください。",
  ui_story_1016_10161001_241_dialog_content = "分かりました。お任せください。",
  ui_story_1016_10161001_242_dialog_content = "カナン城駅付近のA区からC区の一帯を巡回し、\n設備の損壊状況を調査、確認してください。",
  ui_story_1016_10161001_243_dialog_content = "任務完了後、私またはインゲル中佐に報告をお願いします。",
  ui_story_1016_10161001_244_dialog_content = "了解です！",
  ui_story_1016_10161101_1_dialog_content = "もう少しで試合が始まるわ。準備はできたの？",
  ui_story_1016_10161101_2_dialog_content = "もちろんだ。準備万端だ。",
  ui_story_1016_10161101_3_dialog_content = "お前の方はどうなのだ？何か分かったか？",
  ui_story_1016_10161101_4_dialog_content = "いいえ。",
  ui_story_1016_10161101_5_dialog_content = "ノラはカナン城の未開発エリア内に潜伏している可能性が高いわ。\nあそこは四方に道が通じているから、徹底的に調べるにはまだ時間が必要よ。",
  ui_story_1016_10161101_6_dialog_content = "苦労を掛けるな。",
  ui_story_1016_10161101_7_dialog_content = "大したことじゃないわ。",
  ui_story_1016_10161101_8_dialog_content = "私自ら隊を率いて調査しようと思ったけど、\n合同演習のエキシビジョンに出ないわけには行かないでしょ。",
  ui_story_1016_10161101_9_dialog_content = "うわさ好きのやつらに近衛兵団長が不在と知られれば、\nデマがあっという間に広まるだろうな。",
  ui_story_1016_10161101_10_dialog_content = "まったく…いつも足を引っ張ってきて迷惑だわ。",
  ui_story_1016_10161101_11_dialog_content = "でも安心しなさい。会場周辺には厳重に警備を敷いたわ。",
  ui_story_1016_10161101_12_dialog_content = "私がいなかったとしても、ノラに試合の邪魔はできないわ。",
  ui_story_1016_10161101_13_dialog_content = "そうだな。お前の助けがあるのだ。\n合同演習は必ず無事に終わるだろう。",
  ui_story_1016_10161101_14_dialog_content = "<color=#e8d9bb>その頃、アルゴルの実験室では</color>",
  ui_story_1016_10161101_15_dialog_content = "はい、できたわ。最後の調整も完了よ。",
  ui_story_1016_10161101_16_dialog_content = "ただ一番小さいあの子は飛行速度がちょっと落ちてるみたいね。\nおそらく部品が劣化してるせいでしょう。",
  ui_story_1016_10161101_17_dialog_content = "いずれにしても、他に使い道があるワケでもないし、\nあたしのとこに置いていくといいわ。補修しておいてあげる。",
  ui_story_1016_10161101_18_dialog_content = "必要ありません。",
  ui_story_1016_10161101_19_dialog_content = "アクセリアはキュービックに\n袖をまくってもらわなくてはいけません。",
  ui_story_1016_10161101_20_dialog_content = "キュービックがいないと、アクセリアは戦う時困ってしまいます。",
  ui_story_1016_10161101_21_dialog_content = "あら、そうなの？\nだったら、あなたの希望通りにしましょ。",
  ui_story_1016_10161101_22_dialog_content = "レインハトとの試合が終わってから補修しても遅くはないわ。",
  ui_story_1016_10161101_23_dialog_content = "今キュービックは一番いい状態よ。\n思いっきり戦ってくるといいわ。",
  ui_story_1016_10161101_24_dialog_content = "アルゴルがキュービックを作りました。\nキュービックの調整が一番得意なのもアルゴルです。",
  ui_story_1016_10161101_25_dialog_content = "アクセリアはアルゴルを信頼しています。\nアクセリアがキュービックを信頼しているのと同じです。",
  ui_story_1016_10161101_26_dialog_content = "フフフ、ありがとう。\nそんな風に言ってもらえて、あたしも嬉しいわ。",
  ui_story_1016_10161101_27_dialog_content = "小さい頃からあなたのことを見てきたんだもの。\n世話をするのは当然だわ。",
  ui_story_1016_10161101_28_dialog_content = "今の気分はどう？",
  ui_story_1016_10161101_29_dialog_content = "アクセリア、完璧な状態です。\nいつでも戦えます。",
  ui_story_1016_10161101_30_dialog_content = "そう、なら良かったわ。",
  ui_story_1016_10161101_31_dialog_content = "ただ、状態がいいからといって、\nレインハトの実力を甘く見ちゃダメよ。",
  ui_story_1016_10161101_32_dialog_content = "古い改造技術で強化された光霊ではあるけど、\nレインハトは今でも啓光で一二を争う強者よ。",
  ui_story_1016_10161101_33_dialog_content = "自分でも分かってると思うけど、\nあなたの身体じゃ能力の過度な使用は絶対避けなきゃいけないわ。",
  ui_story_1016_10161101_34_dialog_content = "アクセリアは最後の最後まで戦い抜き、勝利します。",
  ui_story_1016_10161101_35_dialog_content = "ずいぶんやる気になっちゃって。\n何を言ってもムダね。",
  ui_story_1016_10161101_36_dialog_content = "でも、絶対に無理はしちゃダメよ。\nそう言っても、聞かないんだろうけど。",
  ui_story_1016_10161101_37_dialog_content = "アクセリアはユリシーズ教授の命令に従います。",
  ui_story_1016_10161101_38_dialog_content = "時には他の人の意見も聞くべきよ。",
  ui_story_1016_10161101_39_dialog_content = "でも、もうそろそろ試合の時間ね。\nこれ以上は引き留めないわ。",
  ui_story_1016_10161101_40_dialog_content = "会場に向かいなさい。",
  ui_story_1016_10161101_41_dialog_content = "アクセリア、了解です。",
  ui_story_1016_10161101_42_dialog_content = "勝利を祈ってるわ。",
  ui_story_1016_10161101_43_dialog_content = "<color=#e8d9bb>エキシビジョン会場</color>",
  ui_story_1016_10161101_44_dialog_content = "それでは、合同演習最後のエキシビジョンを開始します！",
  ui_story_1016_10161101_45_dialog_content = "<size=45>おおお！！</size>",
  ui_story_1016_10161101_46_dialog_content = "まずご登場いただくのは啓光連邦大元帥、\n今だ敗北したことのない啓明の光――レインハト大元帥です！",
  ui_story_1016_10161101_47_dialog_content = "<size=45>大元帥――！大元帥――！</size>",
  ui_story_1016_10161101_48_dialog_content = "合同演習の参加者各位、ご苦労だった！",
  ui_story_1016_10161101_49_dialog_content = "参加者全員がこの演習で各自の実力を発揮し、\n成長する姿を見れたことを――",
  ui_story_1016_10161101_50_dialog_content = "心から嬉しく思う！",
  ui_story_1016_10161101_51_dialog_content = "<size=45>おおお！！</size>",
  ui_story_1016_10161101_52_dialog_content = "今回すべての試練を乗り越え、最も優秀な成績をおさめた、\nレインハト大元帥との決戦の資格を獲得した者は――",
  ui_story_1016_10161101_53_dialog_content = "啓光連邦のアクセリアです！",
  ui_story_1016_10161101_54_dialog_content = "アクセリア――！",
  ui_story_1016_10161101_55_dialog_content = "…",
  ui_story_1016_10161101_56_dialog_content = "アクセリア…？聞いたことのない名前ね。\nそれにも関わらず優勝するなんて本当に強いのね！",
  ui_story_1016_10161101_57_dialog_content = "ああ、俺たち啓光の者も驚いてるんだ。",
  ui_story_1016_10161101_58_dialog_content = "啓光にまだ名の知られていない強者がいたとはな。",
  ui_story_1016_10161101_59_dialog_content = "続いて、両選手握手をしてください。",
  ui_story_1016_10161101_60_dialog_content = "アクセリア…",
  ui_story_1016_10161101_61_dialog_content = "お前のことは知っている。強大な実力の持ち主だ。敬服する。",
  ui_story_1016_10161101_62_dialog_content = "アクセリア、大元帥のお言葉に感謝します。",
  ui_story_1016_10161101_63_dialog_content = "どうだ、しっかり休めたか？昨日合同演習が終わったばかりだというのに、\n今日もまた試合だ。体力は持ちそうか？",
  ui_story_1016_10161101_64_dialog_content = "充分休めていないからと言って、私は手加減しないぞ。",
  ui_story_1016_10161101_65_dialog_content = "大丈夫です。アクセリアは…",
  ui_story_1016_10161101_66_dialog_content = "この時のためにここにいます。",
  ui_story_1016_10161101_67_dialog_content = "…！",
  ui_story_1016_10161101_68_dialog_content = "大元帥と戦うことは、アクセリアの使命です。",
  ui_story_1016_10161101_69_dialog_content = "アクセリアはありとあらゆる手を尽くして、大元帥を倒します。",
  ui_story_1016_10161101_70_dialog_content = "ほう？ならば私もお前の勇姿を楽しみにしているぞ。",
  ui_story_1016_10161101_71_dialog_content = "強き後輩と共に自身を高め合えるのは実に喜ばしい。",
  ui_story_1016_10161101_72_dialog_content = "…",
  ui_story_1016_10161101_73_dialog_content = "（この娘はいったいどうしたというのだ？）",
  ui_story_1016_10161101_74_dialog_content = "（この表情…どこか妙だ。兵士や軍人の顔ではない。むしろ…）",
  ui_story_1016_10161101_75_dialog_content = "（これから死にゆく者の顔だ）",
  ui_story_1016_10161101_76_dialog_content = "（この娘にとって私はそれほど恐ろしい存在なのか？）",
  ui_story_1016_10161101_77_dialog_content = "（それとも…）",
  ui_story_1016_10161101_78_dialog_content = "それでは両選手、位置に就いてください。\nエキシビジョンを開始します！",
  ui_story_1016_10161101_79_dialog_content = "…",
  ui_story_1016_10161101_80_dialog_content = "試合――",
  ui_story_1016_10161101_81_dialog_content = "<size=50><color=#FFB400>開始です</color>！</size>",
  ui_story_1016_10161101_82_dialog_content = "――！",
  ui_story_1016_10161101_83_dialog_content = "キュービック！",
  ui_story_1016_10161101_84_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10161101_85_dialog_content = "なんという力だ！",
  ui_story_1016_10161101_86_dialog_content = "どうやら私も全力を出さねばならないようだ。",
  ui_story_1016_10161101_87_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_1016_10161101_88_dialog_content = "<size=45>すごい！！</size>",
  ui_story_1016_10161101_89_dialog_content = "大元帥――大元帥――！",
  ui_story_1016_10161101_90_dialog_content = "初回攻撃、命中しました。\n攻撃の効果は…敵にダメージを与えられていません。",
  ui_story_1016_10161101_91_dialog_content = "敵の戦闘力は予想を超えていますが、対処可能な範囲内です。",
  ui_story_1016_10161101_92_dialog_content = "アクセリア、出力を上げます。",
  ui_story_1016_10161101_93_dialog_content = "3――",
  ui_story_1016_10161101_94_dialog_content = "（これは…力を貯めているのか！？）",
  ui_story_1016_10161101_95_dialog_content = "（阻止せねば！）",
  ui_story_1016_10161101_96_dialog_content = "2――",
  ui_story_1016_10161101_97_dialog_content = "<size=45>一切を貫け！</size>",
  ui_story_1016_10161101_98_dialog_content = "――！",
  ui_story_1016_10161101_99_dialog_content = "邪魔だ！",
  ui_story_1016_10161101_100_dialog_content = "1！",
  ui_story_1016_10161101_101_dialog_content = "（間に合わないか！？）",
  ui_story_1016_10161101_103_dialog_content = "往くぞ、我が槍斧よ！",
  ui_story_1016_10161101_104_dialog_content = "お待たせしました。",
  ui_story_1016_10161101_105_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_1016_10161101_106_dialog_content = "<size=45>すばらしい！！</size>",
  ui_story_1016_10161101_107_dialog_content = "ゲホッ…ゴホゴホ…！",
  ui_story_1016_10161101_108_dialog_content = "ううむ…これほど痛むか。",
  ui_story_1016_10161101_109_dialog_content = "お前、なかなかの強者だ。",
  ui_story_1016_10161101_110_dialog_content = "2回目の攻撃、命中しました。",
  ui_story_1016_10161101_111_dialog_content = "光力の多くが敵の光力術によって相殺されてしまいました。\n攻撃の効果は…「劣」です。",
  ui_story_1016_10161101_112_dialog_content = "アクセリア、引き続き出力を上げます。",
  ui_story_1016_10161101_113_dialog_content = "（まだ出力を上げる気か！？）",
  ui_story_1016_10161101_114_dialog_content = "（これほど強大な光力は私の限界も超えている。\n正面からぶつかってはまずいことになる…）",
  ui_story_1016_10161101_115_dialog_content = "3――",
  ui_story_1016_10161101_116_dialog_content = "<color=#e8d9bb>カシャッ――</color>",
  ui_story_1016_10161101_117_dialog_content = "<size=45>！</size>",
  ui_story_1016_10161101_118_dialog_content = "（待て、どういうことだ？この娘の身体に…<color=#FFB400>亀裂</color>が入ったのか？）",
  ui_story_1016_10161101_119_dialog_content = "（身体が崩壊し始めているのか！？\nまさかあの恐ろしい力を過度に使ったことが原因か？）",
  ui_story_1016_10161101_120_dialog_content = "（委員会のやつらめ、ガラスの大砲を造りおったか…）",
  ui_story_1016_10161101_121_dialog_content = "アクセリア、止めるのだ！",
  ui_story_1016_10161101_122_dialog_content = "このままではお前の身体がもたない！！",
  ui_story_1016_10161101_123_dialog_content = "うう…",
  ui_story_1016_10161101_124_dialog_content = "2…",
  ui_story_1016_10161101_125_dialog_content = "言うことを聞けんのか？仕方ない…",
  ui_story_1016_10161101_126_dialog_content = "審判、試合中止だ！",
  ui_story_1016_10161101_127_dialog_content = "このまま試合を続ければ、アクセリアの命が危ない！",
  ui_story_1016_10161101_128_dialog_content = "大元帥、今なんて言ったの？",
  ui_story_1016_10161101_129_dialog_content = "分からない。何も聞こえなかった…",
  ui_story_1016_10161101_130_dialog_content = "お静かに！試合を続けます！",
  ui_story_1016_10161101_131_dialog_content = "（審判にも観客にも私の声が届いていないのか？これはいったい…）",
  ui_story_1016_10161101_132_dialog_content = "（試合場と観客席との間にあるのは、微弱な<color=#FFB400>暗力の障壁</color>か…いつの間に現れた！？）",
  ui_story_1016_10161101_133_dialog_content = "（あれが私の声を阻んだのか？ならば、まずは障壁を破るしかなさそうだ！）",
  ui_story_1016_10161101_134_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10161101_135_dialog_content = "（行動範囲を制限する気か！？）",
  ui_story_1016_10161101_136_dialog_content = "ターゲット…ロックオン…",
  ui_story_1016_10161101_137_dialog_content = "1！",
  ui_story_1016_10161101_138_dialog_content = "<size=45>お待たせしました！</size>",
  ui_story_1016_10161101_139_dialog_content = "…！",
  ui_story_1016_10161101_140_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_1016_10161101_141_dialog_content = "<color=#e8d9bb>その頃、カナン城内では</color>",
  ui_story_1016_10161101_142_dialog_content = "駅内部は調べ終わった。問題なしだ。",
  ui_story_1016_10161101_143_dialog_content = "周囲も問題はなかったわ。",
  ui_story_1016_10161101_144_dialog_content = "僕の方もだよ。",
  ui_story_1016_10161101_145_dialog_content = "PlayerName！こっちに何かあるわ！",
  ui_story_1016_10161101_146_dialog_content = "トンネルの補修通路内の防御設備がすべて破壊されているの。\n暗鬼の活動の痕跡らしきものもある！",
  ui_story_1016_10161101_147_dialog_content = "急いで見に行こう！",
  ui_story_1016_10161101_148_dialog_content = "<anim type=Shake><size=50>グオオ――！</size></anim>",
  ui_story_1016_10161101_149_dialog_content = "やっぱり暗鬼がいたね！",
  ui_story_1016_10161101_150_dialog_content = "好き勝手にはさせないわ！",
  ui_story_1016_10161102_1_dialog_content = "あいつらも、カナン城内に入ったはず。",
  ui_story_1016_10161102_2_dialog_content = "でも、まだ時機ではないわ。ここを離れるわけにはいかない。",
  ui_story_1016_10161102_3_dialog_content = "俺たちは、なぜ隠れてる…",
  ui_story_1016_10161102_4_dialog_content = "なぜ、君は…信じないんだ…",
  ui_story_1016_10161102_5_dialog_content = "信じる？",
  ui_story_1016_10161102_6_dialog_content = "このカナン城内に暗鬼の監視の目が張り巡らされているとしたら？",
  ui_story_1016_10161102_7_dialog_content = "この都市を牛耳っている者たちが暗鬼と手を結んでいるとしたら？",
  ui_story_1016_10161102_8_dialog_content = "それでも、あなたは信じるの？",
  ui_story_1016_10161102_9_dialog_content = "…",
  ui_story_1016_10161102_10_dialog_content = "あなたが今信じられるのは、私だけよ。",
  ui_story_1016_10161102_11_dialog_content = "あなたを救い、ここから連れ出せるのは私だけ。",
  ui_story_1016_10161102_12_dialog_content = "…",
  ui_story_1016_10161102_13_dialog_content = "『ノラ様』",
  ui_story_1016_10161102_14_dialog_content = "『話してちょうだい。』",
  ui_story_1016_10161102_15_dialog_content = "『フィジェロ様からの最新情報を持って参りました。』",
  ui_story_1016_10161102_16_dialog_content = "『手はずはすべて整った。撤退せよ、とのことです。』",
  ui_story_1016_10161102_17_dialog_content = "『ようやく手はずが整ったのね。本当に行動が遅いわ。』",
  ui_story_1016_10161102_18_dialog_content = "『申し訳ありません。』",
  ui_story_1016_10161102_19_dialog_content = "『我々はすでに秘密の避難通路を見つけています。』",
  ui_story_1016_10161102_20_dialog_content = "『その通路からカナン城を離れてください。』",
  ui_story_1016_10161102_21_dialog_content = "『通路はどこ？』",
  ui_story_1016_10161102_22_dialog_content = "『こちらに書いてあります。』",
  ui_story_1016_10161102_23_dialog_content = "まったく…ずいぶんへんぴな所ね。",
  ui_story_1016_10161102_24_dialog_content = "実験台、行くわよ。",
  ui_story_1016_10161201_1_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_1016_10161201_2_dialog_content = "<size=45>ゴホゴホゴホッ！！</size>",
  ui_story_1016_10161201_3_dialog_content = "うう…",
  ui_story_1016_10161201_4_dialog_content = "3回目の攻撃…ゴホゴホッ…命中しました。",
  ui_story_1016_10161201_5_dialog_content = "攻撃は…明らかに効いています。",
  ui_story_1016_10161201_6_dialog_content = "攻撃を続行します。",
  ui_story_1016_10161201_7_dialog_content = "（でも、アクセリアの光力が不足しています…）",
  ui_story_1016_10161201_8_dialog_content = "（少し時間をかけて力を貯めなければ、\n攻撃を続行できません）",
  ui_story_1016_10161201_9_dialog_content = "（このままでは、この娘は死ぬ）",
  ui_story_1016_10161201_10_dialog_content = "（いったい何が命を懸けてまで、\n私を倒そうとさせているのだ？）",
  ui_story_1016_10161201_11_dialog_content = "（まさか…ユリシーズの…委員会の命令だというのか？）",
  ui_story_1016_10161201_12_dialog_content = "キュービック！",
  ui_story_1016_10161201_13_dialog_content = "――！",
  ui_story_1016_10161201_14_dialog_content = "（攻撃方法が変わった。光力も弱くなっている）",
  ui_story_1016_10161201_15_dialog_content = "（力を貯め、次の攻撃の準備をしているのだろう）",
  ui_story_1016_10161201_16_dialog_content = "（チャンスかもしれん）",
  ui_story_1016_10161201_17_dialog_content = "アクセリア、なぜそこまで私を負かすことにこだわる？",
  ui_story_1016_10161201_18_dialog_content = "アクセリアにはできます。\nだから、必ず勝たなければなりません。",
  ui_story_1016_10161201_19_dialog_content = "それでは答えになっていない。",
  ui_story_1016_10161201_20_dialog_content = "ユリシーズの命令か？",
  ui_story_1016_10161201_21_dialog_content = "…",
  ui_story_1016_10161201_22_dialog_content = "（否定しないところを見ると、\nおそらく委員会の命令で間違いないだろう）",
  ui_story_1016_10161201_23_dialog_content = "（私を倒し、より多くの発言権を得るためか。だが、なぜ急ぐ？）",
  ui_story_1016_10161201_24_dialog_content = "（本当にやつらの命令であったなら、この娘の性格からして、\n命をかけてでもやり遂げようとするだろう）",
  ui_story_1016_10161201_25_dialog_content = "（しかし今委員会に多くの発言権を与えるわけにはいかん）",
  ui_story_1016_10161201_26_dialog_content = "（アクセリアを救うには、まずは抑え込んで、負けを認めさせるしかない）",
  ui_story_1016_10161201_27_dialog_content = "まだ終わりではありません――",
  ui_story_1016_10161201_28_dialog_content = "<size=45>隙あり！</size>",
  ui_story_1016_10161201_29_dialog_content = "<color=#e8d9bb>キン――！</color>",
  ui_story_1016_10161201_30_dialog_content = "お前の負けだ。",
  ui_story_1016_10161201_31_dialog_content = "<size=50>おお――！！</size>",
  ui_story_1016_10161201_32_dialog_content = "大元帥が相手を抑え込んだぞ。",
  ui_story_1016_10161201_33_dialog_content = "やはり今回も大元帥の勝ちなのかしら？",
  ui_story_1016_10161201_34_dialog_content = "…",
  ui_story_1016_10161201_35_dialog_content = "負けを認めるのだ。",
  ui_story_1016_10161201_36_dialog_content = "お前が勝ちにこだわるのは分かる。\nだが、それぞれ負けられない理由があるのだ。",
  ui_story_1016_10161201_37_dialog_content = "お前を傷つけたくはない。\nお前がこのまま自分を傷つけるのも見たくない。",
  ui_story_1016_10161201_38_dialog_content = "お前は私より若く、優秀だ。\nこれからの啓光連邦の希望なのだ。",
  ui_story_1016_10161201_39_dialog_content = "このようなところで将来をあきらめるな。",
  ui_story_1016_10161201_40_dialog_content = "<anim type=Shake>アクセリアは…</anim>",
  ui_story_1016_10161201_41_dialog_content = "<anim type=Shake><size=45>アクセリアは…まだ負けていません！</size></anim>",
  ui_story_1016_10161201_42_dialog_content = "！？",
  ui_story_1016_10161201_43_dialog_content = "キュービック！",
  ui_story_1016_10161201_44_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_1016_10161201_45_dialog_content = "うっ…ゴホゴホッ！！",
  ui_story_1016_10161201_46_dialog_content = "（あの一見何の攻撃力もなさそうなロボットが爆発したのか！？）",
  ui_story_1016_10161201_47_dialog_content = "（私を引き離すためにこんな危険な手を用いるとは！\nおそらくアクセリアはもっと重傷だ…）",
  ui_story_1016_10161201_48_dialog_content = "<anim type=Shake>痛い…</anim>",
  ui_story_1016_10161201_49_dialog_content = "<anim type=Shake>でも、まだ…戦えます…</anim>",
  ui_story_1016_10161201_50_dialog_content = "<anim type=Shake>アクセリアは、負けません…</anim>",
  ui_story_1016_10161201_51_dialog_content = "（そこまで覚悟をしているのか？\nならば、この試合にはもう2つの結末しか残されていない…）",
  ui_story_1016_10161201_52_dialog_content = "（私が勝利し、アクセリアは命を落とす）",
  ui_story_1016_10161201_53_dialog_content = "（あるいは、アクセリアが力を使い果たす前に私が負けを認める。\n委員会の思惑通りにはなってしまうが、少なくともこの娘の命は救える…）",
  ui_story_1016_10161201_54_dialog_content = "<anim type=Shake>アクセリアは、任務をやり遂げます…大元帥を…倒します…</anim>",
  ui_story_1016_10161201_55_dialog_content = "<color=#e8d9bb>ガシャッ――</color>",
  ui_story_1016_10161201_56_dialog_content = "<anim type=Shake>アクセリアは…まだ…戦えます…</anim>",
  ui_story_1016_10161201_57_dialog_content = "…",
  ui_story_1016_10161201_58_dialog_content = "どうしたの？レインハトはなぜ反撃しないの？",
  ui_story_1016_10161201_59_dialog_content = "大元帥！早く反撃を！",
  ui_story_1016_10161201_60_dialog_content = "大元帥、いったいどうしたんだ？",
  ui_story_1016_10161201_61_dialog_content = "どうやら時が来たようですね。",
  ui_story_1016_10161201_62_dialog_content = "<color=#e8d9bb>ザザザ――</color>",
  ui_story_1016_10161201_63_dialog_content = "次の行動に移ってください。",
  ui_story_1016_10161201_64_dialog_content = "確信はあるのかしら？",
  ui_story_1016_10161201_65_dialog_content = "はい。",
  ui_story_1016_10161201_66_dialog_content = "彼女が勝利することはもうありません。",
  ui_story_1016_10161201_67_dialog_content = "<color=#e8d9bb>その頃、カナン城の深部では</color>",
  ui_story_1016_10161201_68_dialog_content = "はぁ…はぁ…",
  ui_story_1016_10161201_69_dialog_content = "暗鬼は…どこ行ったんだろう！？",
  ui_story_1016_10161201_70_dialog_content = "あの暗鬼ども我々を見て逃げ出すとはな。\nしかも逃げ足が速い。",
  ui_story_1016_10161201_71_dialog_content = "ここはどこかしら？",
  ui_story_1016_10161201_72_dialog_content = "今まで一度も来たことがないわ。\nバイス、あなたはここがどこだか分かる？",
  ui_story_1016_10161201_73_dialog_content = "私にも分からないわ。",
  ui_story_1016_10161201_74_dialog_content = "カナン城の底層部に近いってことだけ、\nかろうじて分かるくらいよ。",
  ui_story_1016_10161201_75_dialog_content = "バイス中尉？それにPlayerNameではないですか。\nどうしてここへ？",
  ui_story_1016_10161201_76_dialog_content = "おや？",
  ui_story_1016_10161201_77_dialog_content = "駅を調べに行ったのではないのですか？",
  ui_story_1016_10161201_78_dialog_content = "インゲル中佐！？",
  ui_story_1016_10161201_79_dialog_content = "ここで会うとは意外だ。",
  ui_story_1016_10161201_80_dialog_content = "駅を調べていたところ、\nトンネルの補修通路内で暗鬼を見つけたのだ。",
  ui_story_1016_10161201_81_dialog_content = "そうなんだ。暗鬼たちは僕たちを見るとすぐに逃げ出して、\nそれを追いかけてるうちにここまで来たんだよ。",
  ui_story_1016_10161201_82_dialog_content = "君たちはどうしてここに？城内を巡回してたんじゃないの？",
  ui_story_1016_10161201_83_dialog_content = "どうしてこんなところに？",
  ui_story_1016_10161201_84_dialog_content = "私たちも皆さんと似たような状況に遭遇したのです。",
  ui_story_1016_10161201_85_dialog_content = "非常に奇妙な暗鬼でした。\n戦いに固執する様子はまったくなく…",
  ui_story_1016_10161201_86_dialog_content = "陰謀の可能性があります。最大限に警戒しましょう。",
  ui_story_1016_10161201_87_dialog_content = "私も何か陰謀が隠されていると見る。",
  ui_story_1016_10161201_88_dialog_content = "で、どうする？追うのを止め、放っておくか？",
  ui_story_1016_10161201_89_dialog_content = "それはいけません！",
  ui_story_1016_10161201_90_dialog_content = "暗鬼をカナン城内にのさばらせてしまっては、\n危険はさらに大きくなります。",
  ui_story_1016_10161201_91_dialog_content = "ここはカナン城の深部です。貴重な科学技術設備が大量に存在するのです。\nそのうちの1台でも暗鬼に壊されれば、重大な損失となります。",
  ui_story_1016_10161201_92_dialog_content = "ですから、追わなければなりません。\n奴らのたくらみを計画段階でたたき潰さなければ！",
  ui_story_1016_10161201_93_dialog_content = "PlayerName、感知能力で暗鬼がどちらへ逃げたか分かりますか？",
  ui_story_1016_10161201_94_dialog_content = "やってみるよ。ここは地形が複雑だから、\n感知能力を使っても大体の方向しか分からないけど…",
  ui_story_1016_10161201_95_dialog_content = "具体的にどこへ行ったかまでは分からないんだ。",
  ui_story_1016_10161201_96_dialog_content = "構いません。追跡ルートは私が考えます。\n方位さえ分かれば結構です。",
  ui_story_1016_10161201_97_dialog_content = "分かった。じゃあ、やってみるよ。",
  ui_story_1016_10161201_98_option_content = "強制感知！",
  ui_story_1016_10161201_99_dialog_content = "暗力が集まってる方向は、下だ…",
  ui_story_1016_10161201_100_dialog_content = "これは…",
  ui_story_1016_10161201_101_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10161201_102_dialog_content = "<color=#FFB400>フィジェロ</color>だ！！！",
  ui_story_1016_10161201_103_dialog_content = "あの<color=#FFB400>ファントム</color>のこと！？\n今どこにいるの？",
  ui_story_1016_10161201_104_dialog_content = "真下だ！すごく近い！",
  ui_story_1016_10161201_105_dialog_content = "真下…？",
  ui_story_1016_10161201_106_dialog_content = "（ここはすでにカナン城の最深部です。さらに下ということになると、\n<color=#FFB400>ガーディアン1号</color>のホストコンピューターがある所です）",
  ui_story_1016_10161201_107_dialog_content = "（まさか日蝕はガーディアン1号に手を出そうとしているのですか！？）",
  ui_story_1016_10161201_108_dialog_content = "すぐに追いかけなければなりません！\n付いてきてください！",
  ui_story_1016_10161201_109_dialog_content = "当初このシェルターを建設した者は相当頭がおかしかったと見える。",
  ui_story_1016_10161201_110_dialog_content = "でなければ、なぜ廊下をこれほど複雑にしたのだ！",
  ui_story_1016_10161201_111_dialog_content = "そこのファントム、止まりなさい！",
  ui_story_1016_10161201_112_dialog_content = "お前はもう逃げられない。覚悟して降参しろ。",
  ui_story_1016_10161201_113_dialog_content = "何だと？降参などするはずかない！",
  ui_story_1016_10161201_114_dialog_content = "邪魔な光霊はすべてあいつが…",
  ui_story_1016_10161201_114X1_dialog_content = "むむ？<color=#FFB400>あいつ</color>はどこへ行ったのだ？\n先に<color=#FFB400>あの場所</color>に向かったのか？",
  ui_story_1016_10161201_115_dialog_content = "忌々しい！どいつもこいつも私の邪魔ばかりしおって！",
  ui_story_1016_10161201_116_dialog_content = "お前たち、やつらを止めよ！",
  ui_story_1016_10161201_117_dialog_content = "<anim type=Shake><size=45>グオオ！！！</size></anim>",
  ui_story_1016_10161201_118_dialog_content = "待って！！",
  ui_story_1016_10161301_1_dialog_content = "ずっと考えてきたことがある――",
  ui_story_1016_10161301_2_dialog_content = "啓光連邦にとって、何が最も重要なのか？",
  ui_story_1016_10161301_3_dialog_content = "強大かつ進んだ軍備だろうか？",
  ui_story_1016_10161301_4_dialog_content = "訓練の行き届いた兵士だろうか？",
  ui_story_1016_10161301_5_dialog_content = "それとも最先端の技術だろうか？",
  ui_story_1016_10161301_6_dialog_content = "長い間考えたが、答えは出なかった。",
  ui_story_1016_10161301_7_dialog_content = "戦場に出るまでは。",
  ui_story_1016_10161301_8_dialog_content = "戦場で、私は見た――",
  ui_story_1016_10161301_9_dialog_content = "堅持――",
  ui_story_1016_10161301_10_dialog_content = "責任――",
  ui_story_1016_10161301_11_dialog_content = "そして犠牲を。",
  ui_story_1016_10161301_12_dialog_content = "私はようやく分かった。\n啓光連邦にとって最も重要なものは――",
  ui_story_1016_10161301_13_dialog_content = "<color=#FFB400>人</color>だ。",
  ui_story_1016_10161301_14_dialog_content = "地上では、啓光に暗鬼を防ぐ天然の障壁も太古の科学技術もない。",
  ui_story_1016_10161301_15_dialog_content = "だが、歴代の啓光の人々はその熱い思いと心血を注ぎ、\n数々のシェルターを築いてきた。",
  ui_story_1016_10161301_16_dialog_content = "一つの世代がこの世を去る時、別の若い世代が代わりに社会を支える――\nそうやって一代また一代と受け継がれてきた。",
  ui_story_1016_10161301_17_dialog_content = "すべてが同じように尊き命だ。\nだが、同胞の、次の世代のより良き暮らしを実現するため――",
  ui_story_1016_10161301_18_dialog_content = "彼らは自身の命を顧みず戦い続けてきた。",
  ui_story_1016_10161301_19_dialog_content = "いかなる命も内部抗争などというバカらしいことで、\n犠牲になってはならない。",
  ui_story_1016_10161301_20_dialog_content = "そのようなことは一刻も早く失くさねばならん。\nそして、二度と同じことがあってはならん。",
  ui_story_1016_10161301_21_dialog_content = "今アクセリアを倒したところで、\nやつらはきっとまたさらに多くのアクセリアを送り込んでくるだろう…",
  ui_story_1016_10161301_22_dialog_content = "やつらが何とかして私を敗北させようとしているのは、\nおそらく私から大元帥の肩書を奪いたいだけだ。",
  ui_story_1016_10161301_23_dialog_content = "大元帥の地位はもちろん重要だ。だが、必須ではない。\nたかが地位や肩書に同胞の命を犠牲にする程の価値はない。",
  ui_story_1016_10161301_24_dialog_content = "少なくとも今は、この娘の命を救わねば。",
  ui_story_1016_10161301_25_dialog_content = "だから、私は…",
  ui_story_1016_10161301_26_dialog_content = "<size=45>止めだ――！</size>",
  ui_story_1016_10161301_27_dialog_content = "<anim type=Shake>アクセリアは、止めません…</anim>",
  ui_story_1016_10161301_28_dialog_content = "<color=#e8d9bb>カタン――</color>",
  ui_story_1016_10161301_29_dialog_content = "止めだ。<color=#FFB400>私の負けだ</color>。",
  ui_story_1016_10161301_30_dialog_content = "お前の背後にいるやつらがそこまで勝利を欲するなら、くれてやる。",
  ui_story_1016_10161301_31_dialog_content = "だが、お前は生きるのだ。",
  ui_story_1016_10161301_32_dialog_content = "誰かの武器や道具としてではなく、\n1人の<color=#FFB400>人</color>として生きるのだ。",
  ui_story_1016_10161301_33_dialog_content = "…！",
  ui_story_1016_10161301_34_dialog_content = "何かしゃべってるのか？",
  ui_story_1016_10161301_35_dialog_content = "わからない…まったく聞こえないわ。",
  ui_story_1016_10161301_36_dialog_content = "大元帥はなぜ武器を捨てたんだ？\n何か特別な技でも使うのかな？",
  ui_story_1016_10161301_37_dialog_content = "審判、聞こえているのだろう。",
  ui_story_1016_10161301_38_dialog_content = "大元帥、な…何とおっしゃいましたか？",
  ui_story_1016_10161301_39_dialog_content = "ようやく聞こえたか？ハハハ、実に都合がいいな。",
  ui_story_1016_10161301_40_dialog_content = "この試合私の負けだ、と言ったのだ。",
  ui_story_1016_10161301_41_dialog_content = "…",
  ui_story_1016_10161301_42_dialog_content = "ですが…",
  ui_story_1016_10161301_43_dialog_content = "何を迷っている？結果を宣言しろ。",
  ui_story_1016_10161301_44_dialog_content = "この娘を長く待たせてはならん。",
  ui_story_1016_10161301_45_dialog_content = "承知しました…それでは宣言します。\n試合終了！",
  ui_story_1016_10161301_46_dialog_content = "レインハト大元帥が自ら試合を放棄したため、\n本試合の勝者は――<color=#FFB400>アクセリア</color>に決まりました！",
  ui_story_1016_10161301_47_dialog_content = "<color=#e8d9bb>その頃、カナン城の深部では</color>",
  ui_story_1016_10161301_48_dialog_content = "ようやくここまで来たぞ。\nだが、厄介なネズミどもまで付いてきおったな。",
  ui_story_1016_10161301_48X1_dialog_content = "あいつはもう中にいるのか？ならば、計画通り…",
  ui_story_1016_10161301_49_dialog_content = "逃げる気ですか！",
  ui_story_1016_10161301_50_dialog_content = "<color=#e8d9bb>バン！バンバン！</color>",
  ui_story_1016_10161301_51_dialog_content = "忌々しい小娘めが！しつこく追ってきおる！",
  ui_story_1016_10161301_52_dialog_content = "まさかここへ来るとは…",
  ui_story_1016_10161301_53_dialog_content = "はぁ…はぁ…やっと追いついた。",
  ui_story_1016_10161301_53X1_dialog_content = "空の末裔、また会ったな。",
  ui_story_1016_10161301_53X2_dialog_content = "先頃の回帰の塔での件は世話になったな。\nおかげでしばらく気分が浮かぬままであったわ。",
  ui_story_1016_10161301_53X3_dialog_content = "今度は何をするつもり！？",
  ui_story_1016_10161301_53X4_dialog_content = "今度こそ絶対に逃がさないよ！",
  ui_story_1016_10161301_53X5_dialog_content = "ここは行き止まりだ！退路はない！",
  ui_story_1016_10161301_53X6_dialog_content = "キキキッ、そう興奮するな。",
  ui_story_1016_10161301_54_dialog_content = "私の推測が正しければ、\nここはおそらくカナン城の最深部だろう？",
  ui_story_1016_10161301_55_dialog_content = "この扉は実に頑丈にできている。\n中にはよほど重要なものが置かれていると見えるな。",
  ui_story_1016_10161301_56_dialog_content = "中にはガーディアン1号のホストコンピューターがあります。\n絶対に日蝕の奴らに触れさせるわけにはいきません！",
  ui_story_1016_10161301_57_dialog_content = "ガーディアン1号！？確か僕より小さかったよね？",
  ui_story_1016_10161301_58_dialog_content = "あのキャタピラロボットはガーディアン1号の端末にすぎません。",
  ui_story_1016_10161301_59_dialog_content = "この中にあるものこそ本体です。",
  ui_story_1016_10161301_60_dialog_content = "カナン城、さらには全啓光の大部分の防衛設備が\nガーディアン1号によって自動制御されていると聞いたことがあります。",
  ui_story_1016_10161301_61_dialog_content = "ガーディアン1号に何かあれば、啓光連邦が危険です！",
  ui_story_1016_10161301_62_dialog_content = "<size=45>キキキキキッ！！</size>",
  ui_story_1016_10161301_63_dialog_content = "小僧、その通りだ。",
  ui_story_1016_10161301_64_dialog_content = "だが、もう遅い。我らの仲間がすでに中に入っている。",
  ui_story_1016_10161301_65_dialog_content = "何ですって！？",
  ui_story_1016_10161301_66_dialog_content = "どうやって中に？この扉は秘密鍵がなければ――",
  ui_story_1016_10161301_67_dialog_content = "それは自分で考えるんだな。",
  ui_story_1016_10161301_68_dialog_content = "もう少しだ。あともう少しで、私は日蝕に…",
  ui_story_1016_10161301_69_dialog_content = "お前たち、奴らを食い止めよ！",
  ui_story_1016_10161301_70_dialog_content = "グォォ！！！",
  ui_story_1016_10161301_71_dialog_content = "皆一緒に攻撃しよう！あいつの思い通りにはさせない！",
  ui_story_1016_10161302_1_dialog_content = "<color=#e8d9bb>カナン城居住区某所</color>",
  ui_story_1016_10161302_2_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_1016_10161302_3_dialog_content = "別に秘密の実験室でも何でもなかったのね。ただの住宅じゃない。",
  ui_story_1016_10161302_4_dialog_content = "こんなへんぴな所に外に通じる通路なんてあるのかしら？",
  ui_story_1016_10161302_5_dialog_content = "君は…ここを離れるのか。",
  ui_story_1016_10161302_6_dialog_content = "なぜだ？",
  ui_story_1016_10161302_7_dialog_content = "ここにはもう退路はないわ。",
  ui_story_1016_10161302_8_dialog_content = "啓光はあなたのことも、私のことも見捨てた…\nこのまま残っても無意味よ。",
  ui_story_1016_10161302_9_dialog_content = "そうだな。委員会は、俺たちを見捨てた…",
  ui_story_1016_10161302_10_dialog_content = "俺は…思い出したんだ…",
  ui_story_1016_10161302_11_dialog_content = "何を思い出したっていうの？",
  ui_story_1016_10161302_12_dialog_content = "…",
  ui_story_1016_10161302_13_dialog_content = "何もかもだ。",
  ui_story_1016_10161302_14_dialog_content = "過去の記憶もあの時の戦いも、\n終わりなく待ち続ける日々も…",
  ui_story_1016_10161302_15_dialog_content = "絶望も。",
  ui_story_1016_10161302_16_dialog_content = "だったら、今自分の置かれている状況が分かるでしょ。",
  ui_story_1016_10161302_17_dialog_content = "かつてのあなたはもうどこにもいない。",
  ui_story_1016_10161302_18_dialog_content = "あなたはもう啓光の軍人ではなく、\nただの逃亡犯、ただのバケモノなのよ。",
  ui_story_1016_10161302_19_dialog_content = "生き延びたければ、通路を探すのを手伝って。",
  ui_story_1016_10161302_20_dialog_content = "その必要はありません。",
  ui_story_1016_10161302_21_dialog_content = "ここに出口などないのですから。",
  ui_story_1016_10161302_22_dialog_content = "…",
  ui_story_1016_10161302_23_dialog_content = "へえ、そう。そういうことだったのね。",
  ui_story_1016_10161302_24_dialog_content = "まあ、意外でもないわ。",
  ui_story_1016_10161302_25_dialog_content = "投降しなさい。実験の成果を渡すのです。",
  ui_story_1016_10161302_26_dialog_content = "協力するならば、楽にあの世に行けるよう、\n配慮して差し上げましょう。",
  ui_story_1016_10161302_27_dialog_content = "どいてちょうだい。",
  ui_story_1016_10161302_28_dialog_content = "協力する気はない、ということですね？",
  ui_story_1016_10161302_29_dialog_content = "では、こちらも容赦いたしません。かかれ！",
  ui_story_1016_10161302_30_dialog_content = "お前たち…！何をするんだ！？",
  ui_story_1016_10161302_31_dialog_content = "捕らえるのです！",
  ui_story_1016_10161302_32_dialog_content = "了解です！",
  ui_story_1016_10161302_33_dialog_content = "身の程知らずね。",
  ui_story_1016_10161302_34_dialog_content = "<size=45>防御しなさい！</size>",
  ui_story_1016_10161302_35_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_1016_10161302_36_dialog_content = "…",
  ui_story_1016_10161302_37_dialog_content = "無駄な抵抗はよしなさい。",
  ui_story_1016_10161302_38_dialog_content = "あなたに対抗するため、この兵士たちは皆\n最高科学者会議が研究開発した防御装備を身に付けています。",
  ui_story_1016_10161302_39_dialog_content = "防御が崩される前に、あなたを捕らえます。",
  ui_story_1016_10161302_40_dialog_content = "あなたたちも少しは学んだようね。",
  ui_story_1016_10161302_41_dialog_content = "でも、愚か者であることには変わりないわ。",
  ui_story_1016_10161302_42_dialog_content = "<color=#e8d9bb>その頃、決戦会場では</color>",
  ui_story_1016_10161302_43_dialog_content = "アクセリアが…勝ったのですか？",
  ui_story_1016_10161302_44_dialog_content = "そうだ。お前が勝った。",
  ui_story_1016_10161302_45_dialog_content = "もう止せ。これ以上自分を傷つけるな。",
  ui_story_1016_10161302_46_dialog_content = "…",
  ui_story_1016_10161302_47_dialog_content = "何ですって？聞き間違いじゃないわよね？",
  ui_story_1016_10161302_48_dialog_content = "あの伝説のレインハトが負けたの？",
  ui_story_1016_10161302_49_dialog_content = "そんなの…あり得ないだろ？",
  ui_story_1016_10161302_50_dialog_content = "なぜだ…",
  ui_story_1016_10161302_51_dialog_content = "<size=45>おい、お前らいったい何してやがる！？</size>",
  ui_story_1016_10161302_52_dialog_content = "レインハトが負けを認めただと？\n真面目に戦っちゃいねぇだろ！",
  ui_story_1016_10161302_53_dialog_content = "この古だぬきども！いったいどんな汚ねぇ手を使いやがった！？",
  ui_story_1016_10161302_54_dialog_content = "バートン軍団長、言葉にお気をつけください。\nこれは正式試合です！",
  ui_story_1016_10161302_55_dialog_content = "落ち着いてください、バートン将軍。",
  ui_story_1016_10161302_56_dialog_content = "今は怒りに任せて騒ぎを起こす時ではありません。",
  ui_story_1016_10161302_57_dialog_content = "レインハトがそうしたってことは、\n何か理由があるはずよ。",
  ui_story_1016_10161302_58_dialog_content = "私はレインハトの決断を信じるわ。\nあとでどういうことか聞けばいいのよ。",
  ui_story_1016_10161302_59_dialog_content = "<size=45>何かの間違いじゃないのか！？</size>",
  ui_story_1016_10161302_60_dialog_content = "<size=45>試合は終わりか？いったい何のつもりだ！？</size>",
  ui_story_1016_10161302_61_dialog_content = "お静かに！皆さん、お静かに願います！",
  ui_story_1016_10161302_62_dialog_content = "試合結果を尊重してください！",
  ui_story_1016_10161302_63_dialog_content = "にぎやかになってきましたね。",
  ui_story_1016_10161302_64_dialog_content = "そろそろでしょうか。",
  ui_story_1016_10161302_65_dialog_content = "申し上げます！ユリシーズ長官、報告です！",
  ui_story_1016_10161302_66_dialog_content = "話しなさい。",
  ui_story_1016_10161302_67_dialog_content = "実は…",
  ui_story_1016_10161302_68_dialog_content = "ふむ、なるほど…分かりました。",
  ui_story_1016_10161302_69_dialog_content = "下がって結構です。",
  ui_story_1016_10161302_70_dialog_content = "はい。",
  ui_story_1016_10161302_71_dialog_content = "審判、マイクを貸してもらえますか？",
  ui_story_1016_10161302_72_dialog_content = "は、はい？しかし、長官…",
  ui_story_1016_10161302_73_dialog_content = "緊急事態を宣言せねばなりません――",
  ui_story_1016_10161302_74_dialog_content = "委員会の名において。",
  ui_story_1016_10161302_75_dialog_content = "は、はい…",
  ui_story_1016_10161302_76_dialog_content = "オホン…皆さん、お静かに願います。\nただ今より緊急命令を発出します。",
  ui_story_1016_10161302_77_dialog_content = "緊急命令だって？どういうことだ？",
  ui_story_1016_10161302_78_dialog_content = "緊急命令？",
  ui_story_1016_10161302_79_dialog_content = "古だぬきが。",
  ui_story_1016_10161302_80_dialog_content = "また何かたくらんでやがるな！？",
  ui_story_1016_10161302_81_dialog_content = "嫌な予感がします…",
  ui_story_1016_10161302_82_dialog_content = "つい先ほど我々委員会は驚くべき情報を入手しました。",
  ui_story_1016_10161302_83_dialog_content = "委員会の情報官がカナン城内で指名手配犯のノラとヘリオスの足取りをつかみ、\nその潜伏場所を突き止めました。",
  ui_story_1016_10161302_84_dialog_content = "あり得ないわ！カナン城の捜索は終始私が担当していた。\n地図に基づいて城内全域に網の目を張って捜索してたわ！",
  ui_story_1016_10161302_85_dialog_content = "私たちの巡回ではノラの影形も見つからなかった！",
  ui_story_1016_10161302_86_dialog_content = "それは君の能力不足の証明でしかないでしょう？",
  ui_story_1016_10161302_87_dialog_content = "情報官らは追跡と同時に、ノラの潜伏場所となった、\n地図に表記のない秘密の通路を発見しましたよ。",
  ui_story_1016_10161302_88_dialog_content = "その通路の先は…\n残念ながら、大元帥レインハトの自宅付近につながっていました。",
  ui_story_1016_10161302_89_dialog_content = "気づかれぬよう、情報官がしばらく尾行したところ、\nノラはなんと正々堂々とレインハトの自宅に入っていったそうです。",
  ui_story_1016_10161302_90_dialog_content = "<size=45>何を言っている！？あり得ない！</size>",
  ui_story_1016_10161302_91_dialog_content = "…",
  ui_story_1016_10161302_92_dialog_content = "そうか…これがお前たちの計画だったか…",
  ui_story_1016_10161302_93_dialog_content = "冗談もいい加減にしなさい！",
  ui_story_1016_10161302_94_dialog_content = "てめぇ！この古だぬきどもが…！",
  ui_story_1016_10161302_95_dialog_content = "ろくに戦場も出たことねぇくせに、\n他人を陥れることだけはお得意みてぇだな！",
  ui_story_1016_10161302_96_dialog_content = "きちんとした証拠を示すべきでしょう。",
  ui_story_1016_10161302_97_dialog_content = "その通りだ。さもなければ、\n私のこの太刀が我が同胞の名誉を汚した者を許しはせぬ。",
  ui_story_1016_10161302_98_dialog_content = "静かに。まずはお静かに願います。",
  ui_story_1016_10161302_99_dialog_content = "皆さんがそう焦るのもよく分かります。\n委員会も最初はこのような事実を信じたくはなかったのですからね。",
  ui_story_1016_10161302_100_dialog_content = "ですが、確固たる証拠があります。\nパトロール隊の隊員が証人です。",
  ui_story_1016_10161302_101_dialog_content = "現在、指名手配犯の2名はカナン城内を逃亡中です。",
  ui_story_1016_10161302_102_dialog_content = "なんてことなの！帰るわ！",
  ui_story_1016_10161302_103_dialog_content = "ノラが破壊行為に走ったらどうするの？\nこのままただ黙ってやられるのを待ってるの？",
  ui_story_1016_10161302_104_dialog_content = "心配には及びませんよ。試合会場の周囲には厳重な警備が張られています。\n委員会がここにいらっしゃる皆さんの安全をお守りします。",
  ui_story_1016_10161302_105_dialog_content = "ただし、委員会はある決定をしました――",
  ui_story_1016_10161302_106_dialog_content = "レインハトは敵と通じ、逃亡犯をかくまった嫌疑により――",
  ui_story_1016_10161302_107_dialog_content = "委員会はこの時をもって、その大元帥の職を解きます。",
  ui_story_1016_10161302_108_dialog_content = "また、委員会の調査に協力するよう要求します。",
  ui_story_1016_10161401_1_dialog_content = "<color=#e8d9bb>ビーッ――</color>",
  ui_story_1016_10161401_2_dialog_content = "不法侵入を検知しました！不法侵入を検知しました！",
  ui_story_1016_10161401_2X1_dialog_content = "中に誰かいるのですね！どきなさい、ファントム！",
  ui_story_1016_10161401_3_dialog_content = "チッ、もう少しマシな口の利き方をした方がよいぞ。\nそうすれば、苦しまぬよう殺してやる。",
  ui_story_1016_10161401_4_dialog_content = "他のネズミどもは…",
  ui_story_1016_10161401_5_dialog_content = "行け。",
  ui_story_1016_10161401_6_dialog_content = "<anim type=Shake><size=45>グォアアア！</size></anim>",
  ui_story_1016_10161401_7_dialog_content = "散れ！氷花よ――！",
  ui_story_1016_10161401_8_dialog_content = "<anim type=Shake>グ…！</anim>",
  ui_story_1016_10161401_9_dialog_content = "『フィジェロ様、もう味方が残っていません…』",
  ui_story_1016_10161401_10_dialog_content = "やかましい！死こそお前たちの使命だ！",
  ui_story_1016_10161401_11_dialog_content = "時間さえ稼げば、光霊のネズミどもの負けが決まるのだ！",
  ui_story_1016_10161401_12_dialog_content = "<color=#e8d9bb>ビーッ――</color>",
  ui_story_1016_10161401_24_dialog_content = "フフ…<size=50>アハハハハ</size>！",
  ui_story_1016_10161401_26_dialog_content = "今すぐ証明してやるぞ！私には組織に残る資格があると！",
  ui_story_1016_10161401_27_dialog_content = "（残る資格？フィジェロは日蝕に除名されるってこと？）",
  ui_story_1016_10161401_28_dialog_content = "周りをよく見なさい。",
  ui_story_1016_10161401_29_dialog_content = "部下は私たちがすべて倒しました。",
  ui_story_1016_10161401_30_dialog_content = "今のあなたは部下もなく、完全に孤立しています。",
  ui_story_1016_10161401_31_dialog_content = "孤立だと？",
  ui_story_1016_10161401_32_dialog_content = "だから何だというのだ？\nたとえ1人になろうとも、お前たち虫けらなど握りつぶしてくれる！",
  ui_story_1016_10161401_33_dialog_content = "<anim type=Shake><size=45>うおおお――！！</size></anim>",
  ui_story_1016_10161401_34_dialog_content = "何をしているの？",
  ui_story_1016_10161401_35_dialog_content = "PlayerName！危ない！",
  ui_story_1016_10161401_36_dialog_content = "<anim type=Shake><size=45>キキキキッ！！</size></anim>",
  ui_story_1016_10161401_37_dialog_content = "真の力を解放するのは久々だ！",
  ui_story_1016_10161401_38_dialog_content = "奥の手は北境の小娘を片付けるのにとっておくつもりだったが…",
  ui_story_1016_10161401_39_dialog_content = "まずはお前たちの身体に穴を開けて、\n昔のあの感覚を取り戻そうではないか！",
  ui_story_1016_10161401_40_dialog_content = "さあ、恐れおののくがいい！",
  ui_story_1016_10161401_41_dialog_content = "遺言でも考えるのだな！",
  ui_story_1016_10161402_0X1_dialog_content = "忌々しい！たかが虫ケラが…このフィジェロをここまで追い詰めるとは…",
  ui_story_1016_10161402_0X2_dialog_content = "死ね！全員私のために死なぬか！",
  ui_story_1016_10161402_0X3_dialog_content = "大変よ！まだ余力を残してるわ！",
  ui_story_1016_10161402_0X4_dialog_content = "それからお前だ、空の末裔！！\nお前らなど、とうの昔に死に絶えるべき定めだったものを！",
  ui_story_1016_10161402_0X5_dialog_content = "PlayerName、早く後ろへ！",
  ui_story_1016_10161402_0X6_dialog_content = "私の邪魔をするな！",
  ui_story_1016_10161402_0X7_dialog_content = "うっ！",
  ui_story_1016_10161402_0X8_dialog_content = "<color=#e8d9bb>ウオーン――</color>",
  ui_story_1016_10161402_0X9_dialog_content = "（これは！？）",
  ui_story_1016_10161402_0X10_dialog_content = "（彼女を殺してはいけません）",
  ui_story_1016_10161402_0X11_dialog_content = "（目的の物は見つかったのか？ならば何をしている？\nさっさと出てくるのだ。ここを離れ――）",
  ui_story_1016_10161402_0X12_dialog_content = "（その手を彼女から放しなさい）",
  ui_story_1016_10161402_0X13_dialog_content = "（警告しましたよ）",
  ui_story_1016_10161402_1_dialog_content = "<anim type=Shake><size=45>クソッ！</size></anim>",
  ui_story_1016_10161402_2_dialog_content = "<anim type=Shake>忌々しい…光霊どもめが…！</anim>",
  ui_story_1016_10161402_3_dialog_content = "<anim type=Shake>光霊も、ノラも、日蝕も、皆忌々しい！！</anim>",
  ui_story_1016_10161402_4_dialog_content = "<anim type=Shake>まとめてあの世に送ってやる！！</anim>",
  ui_story_1016_10161402_4X1_dialog_content = "うっ…",
  ui_story_1016_10161402_5_dialog_content = "バイス！！",
  ui_story_1016_10161402_6_dialog_content = "<anim type=Shake>お前ら虫けらどもにやられはせぬわ！！</anim>",
  ui_story_1016_10161402_7_dialog_content = "<color=#e8d9bb>バンッ――！</color>",
  ui_story_1016_10161402_7X1_dialog_content = "<color=#e8d9bb>ウオオン――</color>",
  ui_story_1016_10161402_8_dialog_content = "――！！！",
  ui_story_1016_10161402_9_dialog_content = "口数の多い暗鬼ですね。",
  ui_story_1016_10161402_10_dialog_content = "ゴホッ、ゲホゲホッ！",
  ui_story_1016_10161402_10X1_dialog_content = "バイス！大丈夫！？",
  ui_story_1016_10161402_11_dialog_content = "急いでこっちへ！ただ気を失ったふりをして、\n不意打ちを仕掛けるつもりかもしれないわ。",
  ui_story_1016_10161402_12_dialog_content = "確認してみましょう。",
  ui_story_1016_10161402_13_dialog_content = "…",
  ui_story_1016_10161402_14_dialog_content = "問題はなさそうです。\n確かに意識を失っています。",
  ui_story_1016_10161402_15_dialog_content = "まだ生きています。ただ意識を失っただけです。",
  ui_story_1016_10161402_15X1_dialog_content = "（私の今の攻撃…そこまでの威力があったでしょうか？）",
  ui_story_1016_10161402_15X2_dialog_content = "（これはいったい…？）",
  ui_story_1016_10161402_16_dialog_content = "ならば、私がこの剣でかつて犠牲になった英魂への手向けにしてやろう。",
  ui_story_1016_10161402_17_dialog_content = "お待ちください！殺してはいけません！",
  ui_story_1016_10161402_18_dialog_content = "おや？なぜだ？",
  ui_story_1016_10161402_19_dialog_content = "言ったはずです。ノラもしくは他のファントムを捕らえた場合、\n啓光に引き渡し、処理を任せると。",
  ui_story_1016_10161402_20_dialog_content = "…いいだろう。",
  ui_story_1016_10161402_21_dialog_content = "だが、こいつはほぼ死んだも同然だ。\n尋問をしようにも、何も聞き出せんだろう。",
  ui_story_1016_10161402_22_dialog_content = "それは私たちの問題です。あなたのご心配には及びません。",
  ui_story_1016_10161402_23_dialog_content = "でも、どうして命を助けるの？\nたくさんの人が犠牲になったんだよ？",
  ui_story_1016_10161402_24_dialog_content = "PlayerName、落ち着いてください。\nお怒りになるのは分かります。",
  ui_story_1016_10161402_25_dialog_content = "ただ、考えてみてください。\nこれまでアストラにはファントムに関する研究記録がありませんでした。",
  ui_story_1016_10161402_26_dialog_content = "しかも、この者は<color=#FFB400>日蝕</color>に関する重要な情報を持っているかもしれません。",
  ui_story_1016_10161402_27_dialog_content = "最も重要なことは、彼が何者にも阻まれることなく、\nここまでやってこられたということ…",
  ui_story_1016_10161402_28_dialog_content = "背後に彼の信頼する者が情報源として存在するということです。",
  ui_story_1016_10161402_29_dialog_content = "そして、背後で計画を動かしているその者は、\n啓光内部の反逆者である可能性が高いと言えるでしょう。",
  ui_story_1016_10161402_30_dialog_content = "あなたの言うことも一理あるわ。\nただ、申し訳ないけど賛同はできない。",
  ui_story_1016_10161402_31_dialog_content = "ファントムに関する研究が少ないということは、\n啓光連邦でも彼を完全に制御できる保証はないということでしょう？",
  ui_story_1016_10161402_32_dialog_content = "目を覚ました後、啓光の制御を脱して逃げ出したら、\nその時はどうするつもりなの？",
  ui_story_1016_10161402_33_dialog_content = "そのようなことが起こらないよう、\n啓光はありとあらゆる手を尽くします。",
  ui_story_1016_10161402_34_dialog_content = "絶対の安全は保証できないということね。",
  ui_story_1016_10161402_35_dialog_content = "しかし、リスクがあるからといって、\n前に進む可能性を捨て、その場に留まることもできません。",
  ui_story_1016_10161402_36_dialog_content = "…",
  ui_story_1016_10161402_37_dialog_content = "では、そちらの言う通りにしましょう。",
  ui_story_1016_10161402_38_dialog_content = "バイス、アナトリア、それからPlayerName。\nあなた方の意見は？",
  ui_story_1016_10161402_39_dialog_content = "わ、私は異論ありません。",
  ui_story_1016_10161402_40_dialog_content = "インゲル中佐がそのように決められたのなら、\n私も異論はありません。",
  ui_story_1016_10161402_41_option_content = "僕も異論はないよ",
  ui_story_1016_10161402_42_option_content = "賛同できない",
  ui_story_1016_10161402_43_dialog_content = "カレンの言う通りだよ。僕はやっぱり逃げ出すんじゃないかって心配だ。",
  ui_story_1016_10161402_44_dialog_content = "こんなに手ごわい相手をようやく倒したのに、\n今見逃したら、この先また倒せるか分からない。",
  ui_story_1016_10161402_45_dialog_content = "しかも、こいつは大勢の人を傷つけた。こいつは…",
  ui_story_1016_10161402_46_dialog_content = "あなたのおっしゃることは分かります。\nしかし、私の考えも変わりません。",
  ui_story_1016_10161402_47_dialog_content = "私に…啓光連邦の仲間にどうかチャンスをください。",
  ui_story_1016_10161402_48_dialog_content = "これまであまりにも多くの同胞が暗鬼の情報を得るために命を犠牲にしてきました。\nこのような絶好のチャンスをみすみす逃すわけにはいかないのです！",
  ui_story_1016_10161402_49_dialog_content = "…",
  ui_story_1016_10161402_50_dialog_content = "…",
  ui_story_1016_10161402_51_dialog_content = "分かった。",
  ui_story_1016_10161402_52_dialog_content = "ありがとうございます。",
  ui_story_1016_10161402_53_dialog_content = "すぐに情報部門に連絡し、\nファントムを収容し、尋問を始めさせます。",
  ui_story_1016_10161402_54_dialog_content = "ですが、私たちの任務はまだ終わっていませんよ。\nあの扉の中にはおそらく仲間がいます。",
  ui_story_1016_10161402_55_dialog_content = "その通りです。\nあの中には極めて重要なガーディアン1号が置かれているのです…",
  ui_story_1016_10161402_56_dialog_content = "うむ、どんな敵であろうとかかってくるがいい。",
  ui_story_1016_10161402_57_dialog_content = "私は一刻も早く全てが終わることを望むばかりです。",
  ui_story_1016_10161402_58_dialog_content = "（アクセリアはどうなったのでしょう？\nアクセリアは…まだ生きているのでしょうか？）",
  ui_story_1016_10161402_59_dialog_content = "（覚悟はできたはずなのに、\nアクセリアのことを思うと、どうしても…）",
  ui_story_1016_10161402_60_dialog_content = "皆さん、警戒してください！",
  ui_story_1016_10161402_61_dialog_content = "扉が動いているようです！",
  ui_story_1016_10161402_62_dialog_content = "（この気配は…！）",
  ui_story_1016_10161402_63_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1016_10161402_64_dialog_content = "<color=#e8d9bb>ビーッビーッ</color>",
  ui_story_1016_10161402_65_dialog_content = "PlayerName、戦闘準備よ！",
  ui_story_1016_10161402_66_dialog_content = "陣形を崩さないように注意してください！\nほころびをつくってはいけません！",
  ui_story_1016_10161402_67_dialog_content = "<color=#e8d9bb>ドーンッ――</color>",
  ui_story_1016_10161402_68_dialog_content = "誰か飛び出してくる！？",
  ui_story_1016_10161402_69_dialog_content = "あれは…！",
  ui_story_1016_10161402_70_dialog_content = "（見たことのない人影が巨大な扉の向こうから飛び出してきた）",
  ui_story_1016_10161402_71_dialog_content = "（ほんの一瞬だったけど、その人影からフィジェロよりもはるかに強大な暗力を感じた）",
  ui_story_1016_10161402_72_dialog_content = "（さっきフィジェロを倒すのに、\n僕たちは力を消耗しきってしまった）",
  ui_story_1016_10161402_73_dialog_content = "（今あいつがその気にさえなれば、僕たちはやられる…）",
  ui_story_1016_10161402_74_dialog_content = "バイス！あぶない！君の方へ向かったよ！",
  ui_story_1016_10161402_75_dialog_content = "え！？",
  ui_story_1016_10161402_76_dialog_content = "はるかなる時空を超え…",
  ui_story_1016_10161402_77_dialog_content = "またお会いしましたね。",
  ui_story_1016_10161402_78_dialog_content = "君は…誰？",
  ui_story_1016_10161402_79_dialog_content = "（見たところ、<color=#FFB400>ファントム</color>みたいね？）",
  ui_story_1016_10161402_80_dialog_content = "（名前なんて知りもしないのに、どうして…）",
  ui_story_1016_10161402_81_dialog_content = "（どうして、<color=#FFB400>見覚えがある</color>気がするの！？）",
  ui_story_1016_10161402_82_dialog_content = "待ちなさい！",
  ui_story_1016_10161402_83_dialog_content = "今に分かりますよ。",
  ui_story_1016_10161402_84_dialog_content = "近いうちに。",
  ui_story_1016_10161402_85_dialog_content = "逃がしてはなりません！",
  ui_story_1016_10161402_86_dialog_content = "あの者が手に持っているのは、<color=#FFB400>ガーディアン1号のコア</color>です！",
  ui_story_1016_10161402_87_dialog_content = "微かな光！",
  ui_story_1016_10161402_88_dialog_content = "無駄です。",
  ui_story_1016_10161402_89_dialog_content = "まさか…まったく効いていないのですか！？",
  ui_story_1016_10161402_90_dialog_content = "急いで追いますよ！\nガーディアン1号のコアを持ち去られるわけにはいきません！",
  ui_story_1016_10161402_91_dialog_content = "<color=#e8d9bb>その頃、カナン城内では</color>",
  ui_story_1016_10161402_92_dialog_content = "急いで捜索してください。そう遠くへは逃げられません。\n片っ端まで調べ上げるのです。",
  ui_story_1016_10161402_93_dialog_content = "了解です！",
  ui_story_1016_10161402_94_dialog_content = "…",
  ui_story_1016_10161402_95_dialog_content = "しつこいわね。",
  ui_story_1016_10161402_96_dialog_content = "あと少しすれば、ここも見つかるわね。",
  ui_story_1016_10161402_97_dialog_content = "行きましょう。",
  ui_story_1016_10161402_98_dialog_content = "この状況…まるで80号シェルターに戻ったみたいだな。",
  ui_story_1016_10161402_99_dialog_content = "余計なこと言わないで。",
  ui_story_1016_10161402_100_dialog_content = "余計なこと？そうかもな…",
  ui_story_1016_10161402_101_dialog_content = "あの時も俺たちは…今みたいにシェルターに閉じ込められ…\n周りは全部敵だった…",
  ui_story_1016_10161402_102_dialog_content = "だが、あの時…俺たちが立ち向かってたのは…暗鬼だ。\n今は同胞と立ち向かってる…",
  ui_story_1016_10161402_103_dialog_content = "何か違いでもある？",
  ui_story_1016_10161402_104_dialog_content = "私の目の前に立ちはだかる者はすべて敵よ。",
  ui_story_1016_10161402_105_dialog_content = "光霊か暗鬼かなんてことは、\n本質的な違いじゃないわ。",
  ui_story_1016_10161402_106_dialog_content = "いや…違うよ。",
  ui_story_1016_10161402_107_dialog_content = "暗鬼は生まれながらにしての敵だ。\nでも、同胞は…ただ俺たちに何があったか…知らないだけだ。",
  ui_story_1016_10161402_108_dialog_content = "誤解だよ。",
  ui_story_1016_10161402_109_dialog_content = "誤解じゃないわ。",
  ui_story_1016_10161402_110_dialog_content = "愚か者の盲従よ。",
  ui_story_1016_10161402_111_dialog_content = "…",
  ui_story_1016_10161402_112_dialog_content = "君は…いったいどんな経験をしたんだ…？\nどんな経験をすれば…そんな風に変われるんだ…？",
  ui_story_1016_10161402_113_dialog_content = "明晰な思考ができるようになったようね。\nいつ頃からのことかしら？",
  ui_story_1016_10161402_114_dialog_content = "ここ数日、少しずつだ…",
  ui_story_1016_10161402_115_dialog_content = "最初は、頭の中に…モヤがかかったようだったが…",
  ui_story_1016_10161402_116_dialog_content = "今は…よくなった…",
  ui_story_1016_10161402_117_dialog_content = "そう？",
  ui_story_1016_10161402_118_dialog_content = "どうやら実験は想定以上の成果をあげたようね。",
  ui_story_1016_10161402_119_dialog_content = "まだ…俺の質問に…答えていない…",
  ui_story_1016_10161402_120_dialog_content = "教えてくれ…なぜ立ち去るんだ…",
  ui_story_1016_10161402_121_dialog_content = "俺と…啓光に戻ろう。",
  ui_story_1016_10161402_122_dialog_content = "幼稚ね。",
  ui_story_1016_10161402_123_dialog_content = "あなたはなぜ自分が生きてあそこに戻れると思うのよ？",
  ui_story_1016_10161402_124_dialog_content = "あそこが、家だからだ。",
  ui_story_1016_10161402_125_dialog_content = "俺たちの仲間が、レインハトが待っている。",
  ui_story_1016_10161402_126_dialog_content = "あの女はとうの昔に仲間じゃなくなったのよ。\n私を見捨て、あなたを見捨てた。",
  ui_story_1016_10161402_127_dialog_content = "啓光連邦はもうずいぶん昔に腐りきってるのよ。\n上から下まで全部ね。",
  ui_story_1016_10161402_128_dialog_content = "君は…恨んでいるんだ…",
  ui_story_1016_10161402_129_dialog_content = "君は…自分自身を苦しめてる…",
  ui_story_1016_10161402_130_dialog_content = "そうかしら？だったら私が真相を教えてあげるわ。",
  ui_story_1016_10161402_131_dialog_content = "真相を知った後でも、愚かにもまだあいつらを信じるっていうなら、\nそれはあなたが救いようのないバカって証明ね。",
  ui_story_1016_10161402_132_dialog_content = "真相？",
  ui_story_1016_10161402_133_dialog_content = "あなたも私も、そしてレインハトも、\n啓光のために造られた武器にすぎないの。",
  ui_story_1016_10161402_134_dialog_content = "委員会は「人造陽光」計画という改造実験を行い、私たちを強化した。",
  ui_story_1016_10161402_135_dialog_content = "そして80号シェルターでのあの戦いは、\n改造実験の実験台である私たちに対する検証だったのよ。",
  ui_story_1016_10161402_136_dialog_content = "任務なんてそもそもどうでもよかったのよ。",
  ui_story_1016_10161402_137_dialog_content = "そんなバカな！？",
  ui_story_1016_10161402_138_dialog_content = "あの戦いで…何人犠牲になったと思ってるんだ！",
  ui_story_1016_10161402_139_dialog_content = "他人を死地に追いやることがあいつらの目的よ。",
  ui_story_1016_10161402_140_dialog_content = "委員会はあの戦いを利用して、実験台を窮地に陥れ、\n潜在的能力を引き出そうとした。",
  ui_story_1016_10161402_141_dialog_content = "大部分は改造に失敗した廃棄品だった。\nただ殺された実験台もいれば、あなたのような姿になった者もいる。",
  ui_story_1016_10161402_142_dialog_content = "なぜ…そんなことを？",
  ui_story_1016_10161402_143_dialog_content = "言ったでしょ、検証よ。\n「人造陽光」の改造は成功率が極めて低いの。",
  ui_story_1016_10161402_144_dialog_content = "実験の成否を検証する唯一の方法は残酷な戦闘を生き残り、\n暗鬼の包囲に血路を開くことよ。",
  ui_story_1016_10161402_145_dialog_content = "レインハトは私たちのうち唯一の成功例。",
  ui_story_1016_10161402_146_dialog_content = "それ以外の者は最初から見捨てられる運命だったの。",
  ui_story_1016_10161402_147_dialog_content = "まだ分からないの？啓光にとって、あなたは初めから人じゃない。\n道具であり、武器でしかないのよ。",
  ui_story_1016_10161402_148_dialog_content = "国家の大義や正義にだまされちゃいけないわ。\n生き延びたいなら、自分の頭で考えることね。",
  ui_story_1016_10161402_149_dialog_content = "ここでは、折れた武器に居場所はないのよ。",
  ui_story_1016_10161402_150_dialog_content = "あなただって見たでしょう？\nここのヤツらは皆あなたに剣を向ける。",
  ui_story_1016_10161402_151_dialog_content = "…",
  ui_story_1016_10161402_152_dialog_content = "君もさっき…言ってただろう。\n彼らは…愚か者で、盲従していると…",
  ui_story_1016_10161402_153_dialog_content = "だったら…きちんと説明して…誤解を解くべきだ…",
  ui_story_1016_10161402_154_dialog_content = "そして…皆を惑わす奴を追い出せばいい。",
  ui_story_1016_10161402_155_dialog_content = "啓光を…元の正しい道に戻すんだ。",
  ui_story_1016_10161402_156_dialog_content = "俺たちがやるべきことは…問題を解決すること…\nむやみやたらに…他人を恨むことじゃない。",
  ui_story_1016_10161402_157_dialog_content = "まだあいつらの絵空事を信じているの？",
  ui_story_1016_10161402_158_dialog_content = "いや…もう信じてない。",
  ui_story_1016_10161402_159_dialog_content = "今言ったのは…俺が自分で考えて…出した結論だ。\n君が言ったように…",
  ui_story_1016_10161402_160_dialog_content = "君がここを立ち去るっていうなら…俺は止めはしない。",
  ui_story_1016_10161402_161_dialog_content = "だが、俺は残る…真相を明らかにして…\n奴らがこれ以上他人を死なせるのを…阻止する！",
  ui_story_1016_10161402_162_dialog_content = "私がそうはさせないわ。",
  ui_story_1016_10161402_163_dialog_content = "あなたは私の実験台なの。\n研究価値がなくなるまでは、一緒に来てもらうわ。",
  ui_story_1016_10161402_164_dialog_content = "他に選択肢はないわ。",
  ui_story_1016_10161402_165_dialog_content = "ここです！目標を発見しました！",
  ui_story_1016_10161402_166_dialog_content = "チッ。",
  ui_story_1016_10161402_167_dialog_content = "厄介な虫ケラどもね。",
  ui_story_1016_10161402_168_dialog_content = "！！！",
  ui_story_1016_10161402_169_dialog_content = "退がってはなりません。\n奴の技はあなたたちには効きません！",
  ui_story_1016_10161402_170_dialog_content = "まだ力を残しているの…",
  ui_story_1016_10161402_171_dialog_content = "啓光連邦の最強指名手配犯に対抗するため、\n万全の準備をしてきているのですよ。",
  ui_story_1016_10161402_172_dialog_content = "どきなさい！",
  ui_story_1016_10161402_173_dialog_content = "今度こそ彼らを逃してはなりません！",
  ui_story_1016_10161402_174_dialog_content = "A部隊、防御の陣形で徐々に前進！",
  ui_story_1016_10161402_175_dialog_content = "B部隊、後ろに回り込み、退路をふさぎなさい！",
  ui_story_1016_10161402_176_dialog_content = "了解です！",
  ui_story_1016_10161402_177_dialog_content = "面倒ね。",
  ui_story_1016_10161402_178_dialog_content = "何をグズグズしているの？行くわよ、私の実験台。",
  ui_story_1016_10161402_179_dialog_content = "いや…",
  ui_story_1016_10161402_180_dialog_content = "俺が…引き止める。残りの半分は…君1人で十分だ…逃げろ。",
  ui_story_1016_10161402_181_dialog_content = "何をする気！？",
  ui_story_1016_10161402_182_dialog_content = "<size=45>下がれ！</size>",
  ui_story_1016_10161402_183_dialog_content = "止めなさい！",
  ui_story_1016_10161402_184_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_1016_10161402_185_dialog_content = "ゴホゴホッ――！",
  ui_story_1016_10161402_186_dialog_content = "天井を崩して、道をふさいだのですか！？",
  ui_story_1016_10161402_187_dialog_content = "デニール、逃げろ。",
  ui_story_1016_10161402_188_dialog_content = "これが俺にできる…最後の手助けだ。",
  ui_story_1016_10161402_189_dialog_content = "愚かね！",
  ui_story_1016_10161402_190_dialog_content = "愚かの骨頂よ！",
  ui_story_1016_10161402_191_dialog_content = "早く行け…",
  ui_story_1016_10161402_192_dialog_content = "ノラを逃がしたのですか…？",
  ui_story_1016_10161402_193_dialog_content = "それもいいでしょう。何しろ――",
  ui_story_1016_10161402_194_dialog_content = "私たちの第一の目標は、あなたですから。",
  ui_story_1016_10161402_195_dialog_content = "捕らえなさい。",
  ui_story_1016_10161402_196_dialog_content = "了解です！",
  ui_story_1016_10161402_197_dialog_content = "来るな…",
  ui_story_1016_10161402_198_dialog_content = "俺は…啓光の同胞に…手を出したくはない…",
  ui_story_1016_10161402_199_dialog_content = "今すぐ武器を捨てろ！",
  ui_story_1016_10161402_200_dialog_content = "<size=45>来ないでくれ！</size>",
  ui_story_1016_10161402_201_dialog_content = "うっ！！",
  ui_story_1016_10161402_202_dialog_content = "無駄な抵抗はよしなさい。",
  ui_story_1016_10161402_203_dialog_content = "…！",
  ui_story_1016_10161402_204_dialog_content = "動くな！",
  ui_story_1016_10161402_205_dialog_content = "第一の目標を抑えました。",
  ui_story_1016_10161402_206_dialog_content = "第二の目標は逃がしましたが、構いません。",
  ui_story_1016_10161402_207_dialog_content = "今回の任務は無事終了しました。",
  ui_story_1016_10161402_208_dialog_content = "あとはユリシーズ長官の指示を待ちましょう。",
  ui_story_1016_10161402_209_dialog_content = "<color=#e8d9bb>エキシビジョン会場</color>",
  ui_story_1016_10161402_210_dialog_content = "アクセリア中尉、委員会に協力し、\n容疑者レインハトを取り押さえてください。",
  ui_story_1016_10161402_211_dialog_content = "…",
  ui_story_1016_10161402_212_dialog_content = "はい…",
  ui_story_1016_10161402_213_dialog_content = "止せ！お前の身体はもう――",
  ui_story_1016_10161402_214_dialog_content = "…！",
  ui_story_1016_10161402_215_dialog_content = "アクセリア！",
  ui_story_1016_10161402_216_dialog_content = "ううむ…力を使いすぎましたか。",
  ui_story_1016_10161402_217_dialog_content = "もう少し持ちこたえられるかと思ったのですが。",
  ui_story_1016_10161402_218_dialog_content = "まあいいでしょう。他の兵士にやらせればいいだけのことです。\nレインハトを捕らえてください。",
  ui_story_1016_10161402_219_dialog_content = "了解です！",
  ui_story_1016_10161402_220_dialog_content = "待ちなさい！",
  ui_story_1016_10161402_221_dialog_content = "ユリシーズ、分かってるでしょうね。\n今回の委員会の行いは一線を越えてるわ。",
  ui_story_1016_10161402_222_dialog_content = "この古だぬきどもが！性懲りもなく俺たちを抑圧しやがって！",
  ui_story_1016_10161402_223_dialog_content = "今まではレインハトに止められてたから、\nお前たちをどうこうしやしなかったが…",
  ui_story_1016_10161402_224_dialog_content = "いよいよやりやがったな！",
  ui_story_1016_10161402_225_dialog_content = "大元帥様、説明してください。いったいどういうことですか？",
  ui_story_1016_10161402_226_dialog_content = "やつらの陰謀であるならば、私たちは戦う。",
  ui_story_1016_10161402_227_dialog_content = "軍団長の皆さん、委員会はいつでも規則に沿って物事を進めています。",
  ui_story_1016_10161402_228_dialog_content = "それに対して、今の皆さんのやり方は、\n規則違反どころか、私情にかられて法をねじまげる行為ですよ。",
  ui_story_1016_10161402_229_dialog_content = "委員会の決定に異議があるとおっしゃるのなら、書面でご提出ください。\n暴力で解決しようとなさるのは賢明ではありませんね。",
  ui_story_1016_10161402_230_dialog_content = "てめえ…！",
  ui_story_1016_10161402_231_dialog_content = "軍団長の皆さん、よくよく態度をお改めください。\nさもなければ、委員会も皆さんをレインハトの共犯と見なさざるを得なくなります。",
  ui_story_1016_10161402_232_dialog_content = "もういい。",
  ui_story_1016_10161402_233_dialog_content = "この件は彼らとは無関係だ。",
  ui_story_1016_10161402_234_dialog_content = "レインハト！？",
  ui_story_1016_10161402_235_dialog_content = "ラス、私一人でやらせてくれ。",
  ui_story_1016_10161402_236_dialog_content = "この啓光で合法な手段で自身の潔白を証明できるか試したいのだ。",
  ui_story_1016_10161402_237_dialog_content = "…",
  ui_story_1016_10161402_238_dialog_content = "分かったわ。",
  ui_story_1016_10161402_239_dialog_content = "うむ。感謝する…",
  ui_story_1016_10161402_240_dialog_content = "あとは頼んだぞ。",
  ui_story_1016_10161402_241_dialog_content = "あの娘のこともだ。非常にまずい状況だ。\n一刻も早く治療してやれ。",
  ui_story_1016_10161402_242_dialog_content = "…",
  ui_story_1016_10161402_243_dialog_content = "おい、レインハト…！？",
  ui_story_1016_10161402_244_dialog_content = "大元帥様…",
  ui_story_1016_10161402_245_dialog_content = "…",
  ui_story_1016_10161402_246_dialog_content = "ユリシーズ、これ以上お前の手を煩わすつもりはない。",
  ui_story_1016_10161402_247_dialog_content = "調査に協力する。",
  ui_story_1016_10161402_248_dialog_content = "ご協力に感謝しますよ、レインハト君。",
  ui_story_1016_10161402_249_dialog_content = "連れて行きなさい。",
  ui_story_1016_10161402_250_dialog_content = "了解です！",
  ui_story_1016_10161501_1_dialog_content = "状況は以上です。",
  ui_story_1016_10161501_2_dialog_content = "正体不明のファントムが<color=#FFB400>ガーディアン1号</color>のコアを持ち去り、\n今だ行方不明とは…",
  ui_story_1016_10161501_3_dialog_content = "インゲル中佐、これは重大な失態です。",
  ui_story_1016_10161501_4_dialog_content = "申し訳ございません。\nいかなる処罰も受ける覚悟はできています。",
  ui_story_1016_10161501_5_dialog_content = "その場にいた者以外で、この件を知っている者はいますか？",
  ui_story_1016_10161501_6_dialog_content = "今のところ、他にこの件を知っている者はおりません。",
  ui_story_1016_10161501_7_dialog_content = "目撃者は全員ここにおります。\n彼らに情報を漏らす時間も与えていません。",
  ui_story_1016_10161501_8_dialog_content = "そうですか…分かりました。",
  ui_story_1016_10161501_9_dialog_content = "インゲル中佐、正体不明のファントムの捜索は私が引き継ぎます。",
  ui_story_1016_10161501_10_dialog_content = "あなたはひとまず休んでください。\n委員会の次の指示をお待ちください。",
  ui_story_1016_10161501_11_dialog_content = "皆さんも、この件は決して外に漏らさぬようお願いいたします。",
  ui_story_1016_10161501_12_dialog_content = "承知しました。",
  ui_story_1016_10161501_13_dialog_content = "承知しました。",
  ui_story_1016_10161501_14_dialog_content = "分かったわ。",
  ui_story_1016_10161501_15_dialog_content = "承知した。口外したところで私に利はない。",
  ui_story_1016_10161501_16_dialog_content = "僕も絶対に話さないよ。",
  ui_story_1016_10161501_17_dialog_content = "ご協力に感謝いたします。",
  ui_story_1016_10161501_18_dialog_content = "以上、解散。",
  ui_story_1016_10161501_19_dialog_content = "少々お待ちください。アクセリアの状態はどうですか？",
  ui_story_1016_10161501_20_dialog_content = "アクセリア中尉は試合で過度に力を使い、\n現在昏睡状態にあります。",
  ui_story_1016_10161501_21_dialog_content = "今はラス軍団長が付き添い、医療センターで治療を受けています。",
  ui_story_1016_10161501_22_dialog_content = "そうですか。アクセリアはまだ…",
  ui_story_1016_10161501_23_dialog_content = "今からアクセリアの見舞いに行ってきます！",
  ui_story_1016_10161501_24_dialog_content = "それでは私もレインハト大元帥の元に戻ることにいたします。",
  ui_story_1016_10161501_25_dialog_content = "PlayerNameさん、バイス中尉、カレンさん、\nそれからレオ団長、ここでお別れするとしましょう。",
  ui_story_1016_10161501_26_dialog_content = "戻らなくて結構です。",
  ui_story_1016_10161501_27_dialog_content = "はい？",
  ui_story_1016_10161501_28_dialog_content = "レインハトは職を解かれ、今や啓光連邦の大元帥ではありません。",
  ui_story_1016_10161501_29_dialog_content = "<size=45>何ですと！？</size>",
  ui_story_1016_10161501_30_option_content = "冗談だよね！？",
  ui_story_1016_10161501_31_dialog_content = "いったい何が起こったの？\nそんな重大なこと、なぜ私たちは知らなかったの？",
  ui_story_1016_10161501_32_option_content = "いったい何があったの！？",
  ui_story_1016_10161501_33_dialog_content = "どうして大元帥さんが突然職を解かれたの？",
  ui_story_1016_10161501_34_dialog_content = "皆さん、落ち着いてください。",
  ui_story_1016_10161501_35_dialog_content = "そもそもが突如起こった事態でして。\nその時皆さんはカナン城内の暗鬼を追跡中だったので、ご存じなくても当然です。",
  ui_story_1016_10161501_36_dialog_content = "カナン城のパトロール隊が巡回中、\n指名手配犯のノラおよび共犯ヘリオスの痕跡を発見しました。",
  ui_story_1016_10161501_37_dialog_content = "2人はここ数日カナン城内に潜伏し続けており、\n合同演習を妨害する機をうかがっていました。",
  ui_story_1016_10161501_38_dialog_content = "その2人の潜伏場所がレインハトの自宅だったのです。",
  ui_story_1016_10161501_39_dialog_content = "2人はその場でとらえましたが、\n委員会はレインハトに敵と内通していた疑いがあると見て、一時職を解きました。",
  ui_story_1016_10161501_40_dialog_content = "そんなの、あり得ないよ！",
  ui_story_1016_10161501_41_dialog_content = "大元帥様は絶対に内通なんてしません！",
  ui_story_1016_10161501_42_dialog_content = "もう一度言います。\nレインハトはもう啓光連邦の大元帥ではありません。",
  ui_story_1016_10161501_43_dialog_content = "これは調査に必要な手続きです。\n潔白が証明されれば、委員会も当然復職させるでしょう。",
  ui_story_1016_10161501_44_dialog_content = "あなた方が今すべきことは、理解と協力です。",
  ui_story_1016_10161501_45_dialog_content = "でも…",
  ui_story_1016_10161501_46_dialog_content = "やっぱり信じられない…",
  ui_story_1016_10161501_47_dialog_content = "あなたが信じる信じないの問題ではありません。\n調査結果を待つしかないのですから。",
  ui_story_1016_10161501_48_dialog_content = "そして、普段レインハトと深い付き合いのあった者として――",
  ui_story_1016_10161501_49_dialog_content = "PlayerNameさん、バイス中尉およびアナトリアには、\n調査に協力していただきます。",
  ui_story_1016_10161501_50_dialog_content = "どうしてこんなことに…",
  ui_story_1016_10161501_51_dialog_content = "調査ですか…",
  ui_story_1016_10161501_52_dialog_content = "それは…",
  ui_story_1016_10161501_53_option_content = "分かった",
  ui_story_1016_10161501_54_dialog_content = "何を聞かれようと、話すことなんてないよ。",
  ui_story_1016_10161501_55_dialog_content = "僕は大元帥さんを信じてるよ。\n大元帥さんはそんなことをする人じゃない。",
  ui_story_1016_10161501_56_dialog_content = "よくぞ言ったわ。",
  ui_story_1016_10161501_57_option_content = "もし断ったら？",
  ui_story_1016_10161501_58_dialog_content = "今私は問いかけたのではありませんよ。\nただ事実をお話ししたにすぎません。",
  ui_story_1016_10161501_59_dialog_content = "協力する以外、あなたに選択の余地はありませんよ。",
  ui_story_1016_10161501_60_dialog_content = "啓光の大切なお客様にずいぶんな態度じゃない？",
  ui_story_1016_10161501_61_dialog_content = "ラス軍団長！？",
  ui_story_1016_10161501_62_dialog_content = "あら、元気そうね。バイス、PlayerName、\nそれからレインハトの副官さん。",
  ui_story_1016_10161501_63_dialog_content = "ラス軍団長、委員会の公務を妨害しないでいただきたい。",
  ui_story_1016_10161501_64_dialog_content = "妨害なんてしてないわよ。態度があまりにも強すぎると、\nかえってうまく行かない時もあるって教えてあげただけよ。",
  ui_story_1016_10161501_65_dialog_content = "…",
  ui_story_1016_10161501_66_dialog_content = "申し訳ありません。先程は言葉が適切ではありませんでした。",
  ui_story_1016_10161501_67_dialog_content = "皆さん、調査にご協力願います。",
  ui_story_1016_10161501_68_dialog_content = "今後しばらく、お三方には啓光に留まっていただくことになるでしょう。\n調査結果が出た後、自由に行動していただいて結構です。",
  ui_story_1016_10161501_69_dialog_content = "…",
  ui_story_1016_10161501_70_dialog_content = "他にどうしようもないんだよね。",
  ui_story_1016_10161501_71_dialog_content = "ご理解ください。",
  ui_story_1016_10161501_72_dialog_content = "それでいいわ。まずはそういうことにしておきましょ。",
  ui_story_1016_10161501_73_dialog_content = "PlayerName、あんたたちもまずは気を静めてちょうだい。\n不必要に争いに発展させることはないわ。",
  ui_story_1016_10161501_74_dialog_content = "分かった…",
  ui_story_1016_10161501_75_dialog_content = "用が済んだなら、解散しなさい。",
  ui_story_1016_10161501_76_dialog_content = "私は他にやることがあるので、先に失礼いたします。",
  ui_story_1016_10161501_77_dialog_content = "あらあら、さっさと逃げたわね…",
  ui_story_1016_10161501_78_dialog_content = "ラス長官、いったい何があったのですか？\nレインハト大元帥様はどうして…",
  ui_story_1016_10161501_79_dialog_content = "分からないわ。",
  ui_story_1016_10161501_80_dialog_content = "私も今はいったいどういう状況なのか分からないの。",
  ui_story_1016_10161501_81_dialog_content = "ただ、今委員会のヤツらと正面からぶつかるのは賢明じゃない。",
  ui_story_1016_10161501_82_dialog_content = "むしろ向こうは私たちとぶつかることを望んでいるのよ。\n双方の衝突が大きいほど、レインハトを追い詰めることができるから。",
  ui_story_1016_10161501_83_dialog_content = "大元帥さん、大丈夫かな…",
  ui_story_1016_10161501_84_dialog_content = "…",
  ui_story_1016_10161501_85_dialog_content = "信じるのよ。",
  ui_story_1016_10161501_86_dialog_content = "カレン殿下――！",
  ui_story_1016_10161501_87_dialog_content = "ここにいらしたんですね！",
  ui_story_1016_10161501_88_dialog_content = "何かあったの？",
  ui_story_1016_10161501_89_dialog_content = "たった今城主様からの緊急の電報が入りました。\n殿下を含め、白夜城の演習参加者は全員即刻戻るようにとのことです！",
  ui_story_1016_10161501_90_dialog_content = "城主様の命令なのね…",
  ui_story_1016_10161501_91_dialog_content = "分かったわ。すぐに準備して戻りましょう。",
  ui_story_1016_10161501_92_dialog_content = "はい。ではお待ちしています。",
  ui_story_1016_10161501_93_dialog_content = "どうやら大変なことが起こりそう…\nいや、起こったというべきか。",
  ui_story_1016_10161501_94_dialog_content = "私もヨーゼフとショウの所へ戻り、\n一刻も早くトワイライトシティへ帰ることにする。",
  ui_story_1016_10161501_95_dialog_content = "では、先に失礼するぞ。幸運を祈る。",
  ui_story_1016_10161501_96_dialog_content = "うん…",
  ui_story_1016_10161501_97_dialog_content = "<color=#e8d9bb>その頃、研究院では</color>",
  ui_story_1016_10161501_98_dialog_content = "おや？目を覚ましたか？",
  ui_story_1016_10161501_99_dialog_content = "すばらしい生命力です。さすがはノラの研究成果ですね。",
  ui_story_1016_10161501_100_dialog_content = "お前のことは…知っている…",
  ui_story_1016_10161501_101_dialog_content = "かつて俺たちの長官だった、ユリシーズだ。",
  ui_story_1016_10161501_102_dialog_content = "少しも変わってないな。",
  ui_story_1016_10161501_103_dialog_content = "おや？記憶も徐々に回復しているのですか？",
  ui_story_1016_10161501_104_dialog_content = "何とも喜ばしい。",
  ui_story_1016_10161501_105_dialog_content = "ただ残念なことに、あまり賢くないようですね。",
  ui_story_1016_10161501_106_dialog_content = "…",
  ui_story_1016_10161501_107_dialog_content = "一つだけ不思議に思っていることがあります。\n我々と戦いたくないのなら、なぜノラの言いなりになっていたのです？",
  ui_story_1016_10161501_108_dialog_content = "自分が捕まってまでもノラを逃がしたのは、なぜです？",
  ui_story_1016_10161501_109_dialog_content = "言いなりになっていたんじゃない。",
  ui_story_1016_10161501_110_dialog_content = "俺は…啓光連邦の軍人だ…",
  ui_story_1016_10161501_111_dialog_content = "啓光の人々と戦友を守るのが…俺の使命だ。",
  ui_story_1016_10161501_112_dialog_content = "！",
  ui_story_1016_10161501_113_dialog_content = "アハハ、まいった。こればかりは予想外の答えでした。",
  ui_story_1016_10161501_114_dialog_content = "ノラは何と言っていたのです？まさか委員会のせいで、\n自分はああなったのだとでも言っていたのですか？",
  ui_story_1016_10161501_115_dialog_content = "とんでもない、それは間違いですよ。\n啓光を離れ、すべての者を裏切ったのは彼女自身の選択です。",
  ui_story_1016_10161501_116_dialog_content = "…",
  ui_story_1016_10161501_117_dialog_content = "実に哀れですね。生涯周りからウソをつかれ続けているのに\n信じて疑わず――",
  ui_story_1016_10161501_118_dialog_content = "半分は暗鬼になった者を信じ、\n自分と同じ光霊を信じようとしないとは。",
  ui_story_1016_10161501_119_dialog_content = "当然と言えば当然ですがね。\nもともとあなたは出来損ないですから。",
  ui_story_1016_10161501_120_dialog_content = "しかし、今になってようやく少し価値を持ち始めましたよ。",
  ui_story_1016_10161501_121_dialog_content = "<color=#e8d9bb>コンコン</color>",
  ui_story_1016_10161501_122_dialog_content = "入りなさい。",
  ui_story_1016_10161501_123_dialog_content = "ユリシーズ長官。",
  ui_story_1016_10161501_124_dialog_content = "これから非常に重要な研究を始めるのです。\n何人たりとも邪魔は許さないと言ったはずですよ？",
  ui_story_1016_10161501_125_dialog_content = "申し訳ございません！\nただ「あの方」がお越しになりまして。",
  ui_story_1016_10161501_126_dialog_content = "「<color=#FFB400>鉄仮面</color>」ですか…\nフッ、確かに現れていい頃です。",
  ui_story_1016_10161501_127_dialog_content = "<color=#e8d9bb>少し後、カナン城内某所</color>",
  ui_story_1016_10161501_128_dialog_content = "私の罪でも問いに来たのですかな？",
  ui_story_1016_10161501_129_dialog_content = "今罪を問うのはせっかちすぎるでしょう？",
  ui_story_1016_10161501_130_dialog_content = "今日はただ私の推測が正しいかどうか、\n確かめてもらいに来たの。",
  ui_story_1016_10161501_131_dialog_content = "あなたの推測はいつでも正しいでしょう？",
  ui_story_1016_10161501_132_dialog_content = "無意味なごきげんとりは必要ないわ。\nあなたにとって何の得にもならないわよ。",
  ui_story_1016_10161501_133_dialog_content = "確かにそうですね。",
  ui_story_1016_10161501_134_dialog_content = "では、元の計画から話しましょうか。",
  ui_story_1016_10161501_135_dialog_content = "もともとの計画では日蝕の捨てゴマを利用してお芝居をし、\n部下たちを使って、レインハトを引きずり降ろすはずだった。",
  ui_story_1016_10161501_136_dialog_content = "ところが、蓋を開けたみたら、計画外の事態になっていたのよね。\n日蝕はノラとその研究成果だけでなく、ガーディアン1号のコアも狙っていたの。",
  ui_story_1016_10161501_137_dialog_content = "それだけじゃないわ。\n今回の計画を厄介な者どもに悟られてしまった。",
  ui_story_1016_10161501_138_dialog_content = "それは誰です？",
  ui_story_1016_10161501_139_dialog_content = "<color=#FFB400>トワイライトシティ</color>よ。",
  ui_story_1016_10161501_140_dialog_content = "トワイライトシティから来たあのチーム、あなたの計画に気づいて、\n最後の段階で勝ちをあなたの部下に譲ったわ。",
  ui_story_1016_10161501_141_dialog_content = "まさか…誰か情報を漏らしたのですか？",
  ui_story_1016_10161501_142_dialog_content = "他の可能性も考えられるわ。たとえば…",
  ui_story_1016_10161501_143_dialog_content = "あなたの部下たちが全力を尽くしていなかった。",
  ui_story_1016_10161501_144_dialog_content = "異常にいい装備を持っていた。",
  ui_story_1016_10161501_145_dialog_content = "試験の内容を前々から準備していた痕跡があった。",
  ui_story_1016_10161501_146_dialog_content = "…",
  ui_story_1016_10161501_147_dialog_content = "あなたの小細工が少し派手すぎたようね。",
  ui_story_1016_10161501_148_dialog_content = "トワイライトシティは小さな所ではあるけれど、\n啓光も白夜城もめったなことでは敵にしたくない相手よ。",
  ui_story_1016_10161501_149_dialog_content = "今や向こうに主導権を握られているとなれば、\nこの先の計画で彼らは不確定要素になるわね。",
  ui_story_1016_10161501_150_dialog_content = "つまり、今後あなたのやるべきことは責任をもって、\nこの不確定要素を制御可能な範囲に収めることよ。",
  ui_story_1016_10161501_151_dialog_content = "それともう一つ、一刻も早くガーディアン1号のコアを取り戻しなさい。",
  ui_story_1016_10161501_152_dialog_content = "ちょっとしたミスのせいで、慎重に事を進めるのは趣味じゃないわ。\n自由気ままなゲームこそ私の好みなの。",
  ui_story_1016_10161501_153_dialog_content = "うむ…ならば、そうしましょう。",
  ui_story_1016_10161501_154_dialog_content = "あなた、実験に相当自信を持っているようね。",
  ui_story_1016_10161501_155_dialog_content = "もちろんです。",
  ui_story_1016_10161501_156_dialog_content = "ノラの技術の解析に成功すれば、\n長年にわたる啓光連邦の技術研究の中でも最大の技術革新となるでしょう。",
  ui_story_1016_10161501_157_dialog_content = "この技術の原理が解明されれば、\nX号シェルターのハーモナイザーを使い、強化型兵士を量産できるのです。",
  ui_story_1016_10161501_158_dialog_content = "「啓明の星」計画にしろ「人造陽光」計画にしろ、\n強化実験の産物は全啓光にまだたくさんいますからね。",
  ui_story_1016_10161501_159_dialog_content = "そうなれば、啓光連邦の実力は質において、\n飛躍的な向上を遂げるでしょう。",
  ui_story_1016_10161501_160_dialog_content = "だったら急ぐのね。\n私たちの時間は光明よりもずっと貴重なのよ。",
  ui_story_1016_10161501_161_dialog_content = "ただ…結局ノラの実験成果を盗用することにしたのね。",
  ui_story_1016_10161501_162_dialog_content = "研究者としての自尊心は痛まないのかしら？",
  ui_story_1016_10161501_163_dialog_content = "それは問題ではありませんよ。",
  ui_story_1016_10161501_164_dialog_content = "この世界に文明を残すのに、\n手段を選んでいる暇はありません。",
  ui_story_1016_10161501_165_dialog_content = "<color=#e8d9bb>数日後、啓光医療センター</color>",
  ui_story_1016_10161501_166_dialog_content = "（あの試合からもう何日も経っているというのに、\nアクセリアはまだ目を覚ましません）",
  ui_story_1016_10161501_167_dialog_content = "（今回もまたほぼ完全崩壊の過程をたどったようですね）",
  ui_story_1016_10161501_168_dialog_content = "（幸い前回崩壊を修復した経験があったので、\n医者も研究者もすぐに身体を修復しましたが…）",
  ui_story_1016_10161501_169_dialog_content = "（かなりの重傷で、いつ目を覚ますのか予想がつきません）",
  ui_story_1016_10161501_170_dialog_content = "うう…",
  ui_story_1016_10161501_171_dialog_content = "アクセリア！？",
  ui_story_1016_10161501_172_dialog_content = "アクセリア…何か長い夢を…見ていたようです。",
  ui_story_1016_10161501_173_dialog_content = "やっと…目を覚ましたのですね…",
  ui_story_1016_10161501_174_dialog_content = "インゲル、おはようございます。",
  ui_story_1016_10161501_175_dialog_content = "インゲルは、とても疲れているようです。",
  ui_story_1016_10161501_176_dialog_content = "そうですか？そうかもしれませんね…",
  ui_story_1016_10161501_177_dialog_content = "気分はどうですか？どこか痛むところはありませんか？",
  ui_story_1016_10161501_178_dialog_content = "アクセリア、正常です。",
  ui_story_1016_10161501_179_dialog_content = "ただ、戦える状態まで回復するには、まだ時間が必要です。",
  ui_story_1016_10161501_180_dialog_content = "戦いを急ぐことはありません。\n生き延びただけでも幸運だったのですから。",
  ui_story_1016_10161501_181_dialog_content = "…",
  ui_story_1016_10161501_182_dialog_content = "大元帥も、アクセリアに同じようなことを言いました。",
  ui_story_1016_10161501_183_dialog_content = "その話は私も聞いています。\n大元帥は…自分から負けを認めたと。",
  ui_story_1016_10161501_184_dialog_content = "だから、あなたは助かったのだと。",
  ui_story_1016_10161501_185_dialog_content = "そうそう、メダルを持ってきましたよ。",
  ui_story_1016_10161501_186_dialog_content = "先日は啓光も混乱の最中で、あなたも倒れてしまい、\n表彰式はできませんでしたが…",
  ui_story_1016_10161501_187_dialog_content = "遅れましたが、あなたのメダルですよ。",
  ui_story_1016_10161501_188_dialog_content = "メダル、重いですね。",
  ui_story_1016_10161501_189_dialog_content = "…",
  ui_story_1016_10161501_190_dialog_content = "アクセリアは、インゲルに聞きたいことがあります。",
  ui_story_1016_10161501_191_dialog_content = "何ですか？",
  ui_story_1016_10161501_192_dialog_content = "試合会場で、大元帥がアクセリアに言いました――",
  ui_story_1016_10161501_193_dialog_content = "アクセリアには人として、生きていってほしいと。",
  ui_story_1016_10161501_194_dialog_content = "教えてください。\n「<color=#FFB400>人として生きる</color>」とはどういうことですか？",
  ui_story_1017_10170101_1_dialog_content = "大元帥様、私の声が聞こえますか？",
  ui_story_1017_10170101_2_dialog_content = "ああ。",
  ui_story_1017_10170101_3_dialog_content = "それでは、始めます。",
  ui_story_1017_10170101_4_dialog_content = "本件の裁判長は私、\n啓光連邦監察長官、ナミシスが務めます。",
  ui_story_1017_10170101_5_dialog_content = "啓光連邦調査法に則り、敵と内通し、指名手配犯を隠匿した容疑について、\n第三回内部公開裁判を行います。",
  ui_story_1017_10170101_6_dialog_content = "啓光連邦調査法の規定により、\nあなたには次の権利が認めら…",
  ui_story_1017_10170101_7_dialog_content = "型通りの文言は省略して構わない。",
  ui_story_1017_10170101_8_dialog_content = "では、正式に裁判を開始します。\nユリシーズ博士の告発について、何か言いたいことはありますか？",
  ui_story_1017_10170101_9_dialog_content = "何度も言っているが、軍事演習の期間中、\nノラがカナン城に潜伏していたことは知らなかった。",
  ui_story_1017_10170101_10_dialog_content = "私とノラの間にはいかなる形であれ、内通の事実などない。",
  ui_story_1017_10170101_11_dialog_content = "前の2回の尋問時と同じ主張ですね。\nそれでは判決が有利になることはありません。",
  ui_story_1017_10170101_12_dialog_content = "それこそお前たちの望み通りなのだろう？",
  ui_story_1017_10170101_13_dialog_content = "はっきり言え。お前たちの目的は何だ？",
  ui_story_1017_10170101_14_dialog_content = "裁判長、証言の補足をさせていただけませんか？",
  ui_story_1017_10170101_15_dialog_content = "発言を許可します。",
  ui_story_1017_10170101_16_dialog_content = "私たちの把握している情報によれば、軍事演習が始まる前、\nノラは「X号研究院」で被告人と直接会って取引をしています。",
  ui_story_1017_10170101_17_dialog_content = "その時、被告人はヘリオスさえ置いていけば、\nノラを逃がしてやると約束しました。",
  ui_story_1017_10170101_18_dialog_content = "インゲルとアナトリアが証言できます。",
  ui_story_1017_10170101_19_dialog_content = "裁判長――",
  ui_story_1017_10170101_20_dialog_content = "<size=30>ラス、口をはさんではなりません</size>",
  ui_story_1017_10170101_21_dialog_content = "インゲル中佐、お答えください。",
  ui_story_1017_10170101_22_dialog_content = "裁判長に聞かれたことだけに答えればいい。\nノラはレインハトに取引を持ちかけたのか？",
  ui_story_1017_10170101_23_dialog_content = "…はい。",
  ui_story_1017_10170101_24_dialog_content = "てめえ――",
  ui_story_1017_10170101_25_dialog_content = "黙っていろ。騒げばかえって裁判が不利になる。",
  ui_story_1017_10170101_26_dialog_content = "取引の成立後、被告人はおそらく同期のよしみでしょう、\nあえて消極的な対応をとりました。",
  ui_story_1017_10170101_27_dialog_content = "指名手配犯に呼応し、彼女は援軍を引き連れてその場を離れ、\n結果「ガーディアン1号」のコアが奪取されました。",
  ui_story_1017_10170101_28_dialog_content = "被告人は罪を認めますか？",
  ui_story_1017_10170101_29_dialog_content = "「ガーディアン1号」のコアが奪われたことは私に責任がある。\nそれ以外の告発については、証拠を示せ。",
  ui_story_1017_10170101_30_dialog_content = "アナトリア。",
  ui_story_1017_10170101_31_dialog_content = "私ですか？",
  ui_story_1017_10170101_32_dialog_content = "レインハトはノラとヘリオスに向かって\n「援軍を連れてきたぞ」と言いましたね？",
  ui_story_1017_10170101_33_dialog_content = "…",
  ui_story_1017_10170101_34_dialog_content = "言ったのですか、それとも言わなかったのですか？",
  ui_story_1017_10170101_35_dialog_content = "言いました…",
  ui_story_1017_10170101_36_dialog_content = "被告人は今の証言について、\n説明もしくは弁明を行ってください。",
  ui_story_1017_10170101_37_dialog_content = "…",
  ui_story_1017_10170101_38_dialog_content = "裁判長、論告は以上です。",
  ui_story_1017_10170101_39_dialog_content = "（あの時の状況はそういうことでは…）",
  ui_story_1017_10170101_40_dialog_content = "（待ってください！私とインゲル中佐が証人ならば…）",
  ui_story_1017_10170101_41_dialog_content = "被告人はこの告発について、罪を認めますか？\nそれとも、補足することはありますか？",
  ui_story_1017_10170101_42_dialog_content = "ふっ、啓光が今の有り様になってしまったのは\n確かに私の責任だ。それは認めよう！",
  ui_story_1017_10170101_43_dialog_content = "あえて何か、付け足すとするならば――",
  ui_story_1017_10170101_44_dialog_content = "ハハハハハ！",
  ui_story_1017_10170101_45_dialog_content = "それだけだ、裁判長。判決を下すがいい。",
  ui_story_1017_10170101_46_dialog_content = "…",
  ui_story_1017_10170101_47_dialog_content = "被告人の容疑に関して、3回にわたる審問の結果、\n次の通り判決します――",
  ui_story_1017_10170101_48_dialog_content = "前啓光連邦大元帥、被告人レインハトは――",
  ui_story_1017_10170101_49_dialog_content = "軍事演習の期間中、その職権を濫用し、\n啓光シェルター内に潜入した指名手配犯、ノラと秘密裏に取引を行い…",
  ui_story_1017_10170101_50_dialog_content = "「ガーディアン1号」のコアの奪取、78名の啓光の兵士およびその家族を\n負傷させるという結果を招き、啓光連邦の安全に多大なる損害をもたらした。",
  ui_story_1017_10170101_51_dialog_content = "これに対し、被告人は自身の責任を認めている。",
  ui_story_1017_10170101_52_dialog_content = "しかしながら、証拠不十分により、敵の隠匿に関する告発については、\n当事者の証言、あるいは双方による十分な証拠の提出を待ち、再度審問を行うものとする。",
  ui_story_1017_10170101_53_dialog_content = "啓光連邦調査法に則り、監察部門の決定は以下の通り。",
  ui_story_1017_10170101_54_dialog_content = "被告人レインハトは大元帥の職務を解任――",
  ui_story_1017_10170101_55_dialog_content = "および、啓光連邦軍人としての権利をはく奪。",
  ui_story_1017_10170101_56_dialog_content = "また、ただちに啓光連邦所定の監獄に収容されるものとする。",
  ui_story_1017_10170101_57_dialog_content = "以上。",
  ui_story_1017_10170101_58_dialog_content = "出て来たわ――",
  ui_story_1017_10170101_59_dialog_content = "ちょ、長官、こ、こんにちは！",
  ui_story_1017_10170101_60_dialog_content = "うう…",
  ui_story_1017_10170101_61_dialog_content = "<size=30>今のは誰？</size>",
  ui_story_1017_10170101_62_dialog_content = "ベリサリア長官よ。\n委員会で、かなり大きな発言権を持ってるはずよ。",
  ui_story_1017_10170101_63_dialog_content = "さっきは緊張しすぎて敬礼を忘れちゃったわ…",
  ui_story_1017_10170101_64_option_content = "僕も緊張しちゃったよ",
  ui_story_1017_10170101_65_option_content = "それってまずいんじゃない？",
  ui_story_1017_10170101_66_dialog_content = "ちょっと、もう少し気の利いたことは言えないの？",
  ui_story_1017_10170101_67_dialog_content = "でも、今から追いかけて敬礼したって間に合わないでしょ…",
  ui_story_1017_10170101_68_dialog_content = "…",
  ui_story_1017_10170101_69_dialog_content = "ベリサリア長官まで来てるなんて…\n大元帥様のこと、どうにかならないのかしら。",
  ui_story_1017_10170101_70_dialog_content = "気づかなかったわ。",
  ui_story_1017_10170101_71_dialog_content = "あなたが例の、空の末裔ね？",
  ui_story_1017_10170101_72_dialog_content = "は、はい…そうです。",
  ui_story_1017_10170101_73_dialog_content = "ベリサリア長官！",
  ui_story_1017_10170101_74_dialog_content = "あなた、空の末裔と白夜城のお友だちと\n一緒に合同演習に参加したんですって？",
  ui_story_1017_10170101_75_dialog_content = "はい、長官。",
  ui_story_1017_10170101_76_dialog_content = "フフ、よかったわね…",
  ui_story_1017_10170101_77_dialog_content = "あなたたちを見ていると、何とも言えない気分になるわ。",
  ui_story_1017_10170101_78_dialog_content = "もうすぐ私の推測を検証してくれるのでしょう？",
  ui_story_1017_10170101_79_dialog_content = "お先に失礼するわ、空の末裔くん。\n次に会う時は正式な場でしょうね。",
  ui_story_1017_10170101_80_dialog_content = "…",
  ui_story_1017_10170101_81_dialog_content = "び、びっくりした…",
  ui_story_1017_10170101_82_dialog_content = "今度は敬礼できた？",
  ui_story_1017_10170101_83_dialog_content = "ベリサリア長官、私たちの事をヘンな目で見てなかった…？",
  ui_story_1017_10170101_84_dialog_content = "考えすぎかしら…",
  ui_story_1017_10170101_85_dialog_content = "あ、将軍もみんな集まってる――ヒイロ長官！",
  ui_story_1017_10170101_86_dialog_content = "…",
  ui_story_1017_10170101_87_dialog_content = "ここでは話したくないって感じだね。",
  ui_story_1017_10170101_88_dialog_content = "全員顔が殺気立ってるわ…",
  ui_story_1017_10170101_89_dialog_content = "PlayerNameさん、バイス中尉。",
  ui_story_1017_10170101_90_dialog_content = "アナトリア少佐！状況はどうなってますか？",
  ui_story_1017_10170101_91_dialog_content = "…",
  ui_story_1017_10170101_92_dialog_content = "どこか静かな所で話しましょう。",
  ui_story_1017_10170101_93_dialog_content = "長官各位、辺境では暗鬼の活動が頻繁になっており、\nこのような状況がすでに数日間続いております。",
  ui_story_1017_10170101_94_dialog_content = "<color=#FFB400>「暗面偵察隊」</color>にはすでに探査データに基づき、\nその都度偵察戦略を調整するよう指示してあります。",
  ui_story_1017_10170101_95_dialog_content = "また、過去のデータに基づく検証によれば、\n<color=#FFB400>極光の乱れ</color>がここ20年で最高の頻度で発生しています。",
  ui_story_1017_10170101_96_dialog_content = "これらの状況が意味するものは、\n日蝕が再び暗潮の危機を起こそうと企んでいると言うことだと考えられます。",
  ui_story_1017_10170101_97_dialog_content = "皆さん、聞いたでしょう？",
  ui_story_1017_10170101_98_dialog_content = "前回の暗潮の危機の時もこの顔ぶれだったわね。",
  ui_story_1017_10170101_99_dialog_content = "年を取って、ずいぶん静かになったじゃない。",
  ui_story_1017_10170101_100_dialog_content = "暗潮の動きと「ガーディアン1号」のコアが奪われたことには\n何か関係があるのでしょうか？",
  ui_story_1017_10170101_101_dialog_content = "最近の日蝕の一連の動きを見れば、\nそういうことになるでしょうね。",
  ui_story_1017_10170101_102_dialog_content = "ただ、今はあちらが「ガーディアン1号」のコアを手に入れた。\n状況が少し変わってくるでしょう。",
  ui_story_1017_10170101_103_dialog_content = "追跡はどうなっているのですか？",
  ui_story_1017_10170101_104_dialog_content = "報告を聞いたでしょう？\n精鋭で構成された「暗面偵察隊」が追跡しているわ。",
  ui_story_1017_10170101_105_dialog_content = "精鋭で構成された「暗面偵察隊」ですか？",
  ui_story_1017_10170101_106_dialog_content = "彼女なら「精鋭」と呼ぶにふさわしいと思うけど？",
  ui_story_1017_10170101_107_dialog_content = "ファントムの追跡と「ガーディアン1号」の奪還は、\nアイゼンの責任下にあるのでは？",
  ui_story_1017_10170101_108_dialog_content = "彼の手に負えるなら、「ペピータ」を出したりしないわ。",
  ui_story_1017_10170101_109_dialog_content = "ペピータ…啓光に背き、真理結社に入った、あの囚人ですか？",
  ui_story_1017_10170101_110_dialog_content = "囚人？",
  ui_story_1017_10170101_111_dialog_content = "そんな敏感になる必要があるかしら？",
  ui_story_1017_10170101_112_dialog_content = "彼女を牢獄から出すべきではない。",
  ui_story_1017_10170101_113_dialog_content = "「兵を養うこと千日、用は一朝に在り」というでしょう？",
  ui_story_1017_10170101_114_dialog_content = "あの子は暗面の奥まで進入した経験がある。\nある意味、この任務は彼女にしかできないと言ってもいいわ。",
  ui_story_1017_10170101_115_dialog_content = "ベリサリア、委員会はあなたに私兵の組織と訓練を行う権限を与えてはいません。",
  ui_story_1017_10170101_116_dialog_content = "囚人の再教育と利用が私の職務でしょう？",
  ui_story_1017_10170101_117_dialog_content = "それで、もう1つの部隊はいつ出発するのかしら？",
  ui_story_1017_10170101_118_dialog_content = "各隊員の情報はすでに整理できています。\nご命令さえくだされば、明日にでも出発できます。",
  ui_story_1017_10170101_119_dialog_content = "もう1部隊、派遣するのですか？",
  ui_story_1017_10170101_120_dialog_content = "調査結果によると、バイス中尉と今回カナン城に侵入した\n日蝕の構成員との間には、何か特別な関係があるようです。",
  ui_story_1017_10170101_121_dialog_content = "また、影ノ街から演習に参加した3名から、\n日蝕の足取りに関する手がかりの提供がありました。",
  ui_story_1017_10170101_122_dialog_content = "この2点を考慮すると、彼らは「ガーディアン1号」のコアを追跡する上で\n大きな助けになると考えられます。",
  ui_story_1017_10170101_123_dialog_content = "そこで、彼ら4名を臨時に一隊とし、\n「暗面偵察隊」の補助部隊として組織、派遣する予定です。",
  ui_story_1017_10170101_124_dialog_content = "フン、胡散臭い輩が3人も、本当に影ノ街から来たのでしょうかね？",
  ui_story_1017_10170101_125_dialog_content = "「鉄仮面」先生が体よく利用されていないとよいですが。",
  ui_story_1017_10170101_126_dialog_content = "この私がわざわざ便宜を図ってあげているの。\n当然それだけの価値があるということ。",
  ui_story_1017_10170101_127_dialog_content = "それより、そちらの研究はどうなの？\n新兵器の仕上がりはどうなのかしら、ユリシーズ？",
  ui_story_1017_10170101_128_dialog_content = "ノラの「実験台」に関する解析はすでに完了しています。\n「啓明の星計画」を再定義すべき時が来たと言っていいでしょう。",
  ui_story_1017_10170101_129_dialog_content = "「啓明の星計画2.0」が始動すれば、\n光霊の戦闘力に大幅な向上が見込めます。",
  ui_story_1017_10170101_130_dialog_content = "今こそ次の大元帥を選出する時でしょう。",
  ui_story_1017_10170101_131_dialog_content = "適任者はいるのですか？",
  ui_story_1017_10170101_132_dialog_content = "計画全体にしてみれば、大元帥など誰でもいいことです。",
  ui_story_1017_10170101_133_dialog_content = "それより暗潮の危機が再び訪れた時、\n打つ手がない事の方が懸念するべきでしょう。",
  ui_story_1017_10170101_134_dialog_content = "「大元帥など誰でもいい」？",
  ui_story_1017_10170101_135_dialog_content = "同意しかねますね。",
  ui_story_1017_10170101_136_dialog_content = "レインハトがここ数年で築き上げた影響力は、\n私たちの予想をはるかに超えていました。",
  ui_story_1017_10170101_137_dialog_content = "今のこの状況は「啓明の星計画」こそが原因です。\nそれをまだ継続するというのですか？",
  ui_story_1017_10170101_138_dialog_content = "彼女の裁判も今だ決定的な証拠を欠いたままです。\n免職処分も一時的なものにすぎないでしょう。",
  ui_story_1017_10170101_139_dialog_content = "ユリシーズ博士、ことを少々急ぎすぎなのでは？",
  ui_story_1017_10170101_140_dialog_content = "すでに決まったことで討論を重ねても意味はありません。",
  ui_story_1017_10170101_141_dialog_content = "ご意見があるのなら、手続きを踏み、訴えを起こせばよろしい。",
  ui_story_1017_10170101_142_dialog_content = "ユリシーズ博士も研究ばかりに没頭せず、\nたまには外の空気を吸ってみるのがよいかと。",
  ui_story_1017_10170101_143_dialog_content = "肉を食べたいと言えば、\n家畜が自分から肉切り包丁の前まで来てくれるとでも思っているのですか？",
  ui_story_1017_10170101_144_dialog_content = "「最強の兵器」で周囲を振り回すのは構いませんが…",
  ui_story_1017_10170101_145_dialog_content = "誰が大元帥になるかは、あなたが今ご自分でおっしゃった通り、\n手続きに沿って決めるべきでしょう。",
  ui_story_1017_10170101_146_dialog_content = "そのくらいにしてちょうだい。\n無私の心で尽くすのが啓光の者、でしょう？",
  ui_story_1017_10170101_147_dialog_content = "ちょうど全員そろっていることだし、\nこの場で大元帥の人選について話し合いましょう。",
  ui_story_1017_10170101_148_dialog_content = "資料はもう送ってあるわね？",
  ui_story_1017_10170101_149_dialog_content = "はい。長官方が今ご覧になっている資料には、\n佐官以上の軍人の詳細な履歴が記されています。",
  ui_story_1017_10170101_150_dialog_content = "これには個人的な人脈および、同僚の評価などの情報も含まれます。",
  ui_story_1017_10170101_151_dialog_content = "啓光連邦は成立当初に、最強の兵士を大元帥に選出すると定めました。",
  ui_story_1017_10170101_152_dialog_content = "この規定はその後、大元帥となる者は身体機能の強化を\n受けなければならないという不文律となっています。",
  ui_story_1017_10170101_153_dialog_content = "「啓明の星計画2.0」の始動に異論はありません。\n能力だけで言えば、適格者は4名の将軍だけでしょうね。",
  ui_story_1017_10170101_154_dialog_content = "4名の将軍の中からもう1人のレインハトを育てるのなら、\n大元帥を交代させる意味はあるのですか？",
  ui_story_1017_10170101_155_dialog_content = "彼らのうちの誰かを大元帥にすれば、\n結局また自分で自分の首を絞めるようなものでしょう？",
  ui_story_1017_10170101_156_dialog_content = "ユリシーズ、あなたの意見は？",
  ui_story_1017_10170101_157_dialog_content = "…",
  ui_story_1017_10170101_158_dialog_content = "この4名の中から選ぶのであれば、\n確かにふさわしい者が1名…",
  ui_story_1017_10170201_1_dialog_content = "誰です？入りなさい。",
  ui_story_1017_10170201_2_dialog_content = "あの…ヒイロ長官、長官各位、失礼いたします！",
  ui_story_1017_10170201_3_dialog_content = "こんにちは…",
  ui_story_1017_10170201_4_dialog_content = "お邪魔してしまい申し訳ございません。\nヒイロ長官をお探ししていたのですが、まさかおそろいとは思わず…",
  ui_story_1017_10170201_5_dialog_content = "大元帥様の件について――",
  ui_story_1017_10170201_X5_dialog_content = "<color=#e8d9bb>ピピッ――</color>",
  ui_story_1017_10170201_6_dialog_content = "…",
  ui_story_1017_10170201_7_dialog_content = "諸君、戦地への戻れとの命令だ。",
  ui_story_1017_10170201_8_dialog_content = "もう？",
  ui_story_1017_10170201_9_dialog_content = "俺にも来たぞ。こんな短けぇ任務概要は初めてだな。",
  ui_story_1017_10170201_10_dialog_content = "私もです。",
  ui_story_1017_10170201_11_dialog_content = "けっ、反乱でも起こすと思ってやがんのか？",
  ui_story_1017_10170201_12_dialog_content = "将軍なんざ戦ってなんぼだろが。\n向こうがその気なら、やってやろうじゃねえかよ！",
  ui_story_1017_10170201_13_dialog_content = "慎重を期して、まずは各々の任務を努めましょう。\nとにかく臨機応変に対応することです。",
  ui_story_1017_10170201_14_dialog_content = "ああ。",
  ui_story_1017_10170201_15_dialog_content = "ラス、あなたは？",
  ui_story_1017_10170201_X15_dialog_content = "…え？何？",
  ui_story_1017_10170201_X16_dialog_content = "命令は送られてきましたか？",
  ui_story_1017_10170201_X17_dialog_content = "…近衛兵団はお飾りみたいなものよ。\nいざって時はあんたたちが先に動くんでしょ。",
  ui_story_1017_10170201_X18_dialog_content = "何かあればいつでも連絡を。気を付けて。",
  ui_story_1017_10170201_X19_dialog_content = "くれぐれも気をつけてください。",
  ui_story_1017_10170201_16_dialog_content = "私？どうせ<color=#FFB400>近衛兵団なんてお飾りよ</color>。\nいざって時はあんたたちが先に動くんだし、ひとまずカナン城から動かないわ。",
  ui_story_1017_10170201_17_dialog_content = "くれぐれも気をつけてください。",
  ui_story_1017_10170201_18_dialog_content = "…",
  ui_story_1017_10170201_19_dialog_content = "皆いなくなっちゃったね。",
  ui_story_1017_10170201_20_dialog_content = "いったい何が起こったのかしら？ヒイロ長官まで…",
  ui_story_1017_10170201_21_dialog_content = "何を話してたんだと思う？",
  ui_story_1017_10170201_22_option_content = "反乱",
  ui_story_1017_10170201_23_dialog_content = "みんな上の人たちに反発してるみたいだった。",
  ui_story_1017_10170201_24_dialog_content = "レインハト大元帥がこんなことになったからって、\n何か行動を起こそうとしてるんじゃ…",
  ui_story_1017_10170201_25_dialog_content = "シーッ！そんなこと口に出したらダメよ！",
  ui_story_1017_10170201_26_option_content = "大元帥を救う",
  ui_story_1017_10170201_27_dialog_content = "大元帥が罠にはめられたから、\nきっと何とか助けようとしてるんじゃないかな。",
  ui_story_1017_10170201_28_dialog_content = "もしそうだとしたら、私たちに何ができるの…？",
  ui_story_1017_10170201_29_option_content = "分からない",
  ui_story_1017_10170201_30_dialog_content = "慌ただしく出て行った様子をみると、\nいい事ではなさそうだね。",
  ui_story_1017_10170201_31_dialog_content = "はぁ…無駄足だったみたいね…",
  ui_story_1017_10170201_32_dialog_content = "ふぅ…ようやく見つけましたよ、バイス！",
  ui_story_1017_10170201_33_dialog_content = "あなたに緊急の任務です！",
  ui_story_1017_10170201_34_dialog_content = "一緒に出発する隊員がこの先で待ってるの？",
  ui_story_1017_10170201_35_dialog_content = "ビビアンさんも用件だけ言って、\nずいぶん慌てて飛び出していったし…",
  ui_story_1017_10170201_36_dialog_content = "ええ。顔色も良くなかったわ。\n啓光に…何か大きな嵐が迫ってるのかも。",
  ui_story_1017_10170201_37_dialog_content = "今は入ってきた情報が多すぎて 、頭の中がこんがらがってるわ…",
  ui_story_1017_10170201_38_dialog_content = "ヘンな汽笛の音まで聞こえてくるし…",
  ui_story_1017_10170201_39_dialog_content = "それは僕にも聞こえてるよ…",
  ui_story_1017_10170201_40_dialog_content = "「三途の列車」の乗客たちよ、待っていたぞ。",
  ui_story_1017_10170201_41_dialog_content = "カロン長官！一緒の任務だったんですね！",
  ui_story_1017_10170201_42_dialog_content = "ごきげんよう、バイス。それから我が友、空の末裔。",
  ui_story_1017_10170201_43_dialog_content = "ごきげんよう、バイス。それから我が友、空の末裔。",
  ui_story_1017_10170201_44_dialog_content = "ごきげんよう、バイス。それから我が友、空の末裔。",
  ui_story_1017_10170201_45_dialog_content = "ようやくそろいましたか。オホン――皆さん、こんにちは。",
  ui_story_1017_10170201_46_dialog_content = "どうして君たちがここに？",
  ui_story_1017_10170201_47_dialog_content = "フン、ビックリしたでしょ？何を隠そう、\nあたしたち<color=#FFB400>「追跡小隊」</color>の正式メンバーなの。",
  ui_story_1017_10170201_48_dialog_content = "そうなんです。ご一緒させてもらいます。\nどうぞよろしく。",
  ui_story_1017_10170201_49_dialog_content = "カロン長官…これはどういう…？",
  ui_story_1017_10170201_50_dialog_content = "こちらの遠方からの御客人3名は君と同じく、\n「三途の列車」の乗客として招かれた仲間なのだ。",
  ui_story_1017_10170201_51_dialog_content = "仲間？",
  ui_story_1017_10170201_52_dialog_content = "その通り。しかし我が友よ、残念ながら君の名前は名簿にない。",
  ui_story_1017_10170201_53_dialog_content = "と言う訳で、帰りたまえ。\n「三途の列車」はまもなく出発するのでね。",
  ui_story_1017_10170201_54_dialog_content = "ちょっと待って！僕も乗せて！",
  ui_story_1017_10170201_55_dialog_content = "PlayerName、どうして…",
  ui_story_1017_10170201_56_dialog_content = "では我が友よ、教えてもらおう。\n君が乗らねばならない理由が有るのか？",
  ui_story_1017_10170201_57_option_content = "バイスのことが心配だから",
  ui_story_1017_10170201_58_dialog_content = "ビビアンさんが言ってたんだ。\n今回の任務は暗面の奥まで行くことになるかもって…",
  ui_story_1017_10170201_59_dialog_content = "合同演習の時に出てきたあいつが、\nまたバイスを狙ってくるんじゃないかって心配なんだ。",
  ui_story_1017_10170201_60_dialog_content = "だから、僕も一緒に連れていって。",
  ui_story_1017_10170201_61_option_content = "君のことが心配だから",
  ui_story_1017_10170201_62_dialog_content = "ビビアンさんから「追跡小隊」の話は聞いてたけど、\nこの3人がいることまでは知らなくて…",
  ui_story_1017_10170201_63_dialog_content = "君に迷惑をかけるんじゃないかって心配なんだ。\nだから僕も一緒に連れて行って。",
  ui_story_1017_10170201_64_dialog_content = "我が相棒は気にはするまい。\nただ、行く手には多くの危険が待っているだろう。",
  ui_story_1017_10170201_65_dialog_content = "この旅の終点が、命の終点になるかもしれないのだぞ？",
  ui_story_1017_10170201_66_dialog_content = "信じて！危険に立ち向かうことには、\nこれでも経験豊富だから！",
  ui_story_1017_10170201_67_dialog_content = "PlayerName…",
  ui_story_1017_10170201_68_dialog_content = "おお！聞いたか、「彼岸号」よ？\n空の末裔が我らと共に地獄へ来るそうだ！",
  ui_story_1017_10170201_69_dialog_content = "そこまでは言ってないけど…",
  ui_story_1017_10170201_70_dialog_content = "とはいえ、残念だが今回は諦めてもらわねばならん。\n出発の時刻が迫っているのでな。",
  ui_story_1017_10170201_71_dialog_content = "暗面へ行くには十分な準備が必要になるのでね。",
  ui_story_1017_10170201_72_dialog_content = "じゃあ、行ってくるわね、PlayerName。",
  ui_story_1017_10170201_73_option_content = "またね、バイス",
  ui_story_1017_10170201_74_dialog_content = "他に何か言いたいことはないの？",
  ui_story_1017_10170201_75_dialog_content = "ある…",
  ui_story_1017_10170201_76_option_content = "待って、バイス",
  ui_story_1017_10170201_77_dialog_content = "どうしたの？",
  ui_story_1017_10170201_78_dialog_content = "暗面は危ないから、十分気を付けてね。",
  ui_story_1017_10170201_79_dialog_content = "ええ、分かってるわ。\n今までだってどんな危険も乗り越えてきたじゃない。",
  ui_story_1017_10170201_80_dialog_content = "でも、それは…",
  ui_story_1017_10170201_81_dialog_content = "「でも」、どうしたの？",
  ui_story_1017_10170201_82_dialog_content = "…とにかく、嫌な予感がするから…",
  ui_story_1017_10170201_83_dialog_content = "はいはい。空の末裔だから、\nすごい感知能力で何でも分かるものね。",
  ui_story_1017_10170201_84_dialog_content = "でも大丈夫よ、カロン長官が一緒だもの。",
  ui_story_1017_10170201_85_dialog_content = "うん、もし本当に危ない時は…僕の名前を叫んでね！",
  ui_story_1017_10170201_86_dialog_content = "名前を？遠くにいても、聞こえるのかしら？",
  ui_story_1017_10170201_87_dialog_content = "分からないけど、とにかく。",
  ui_story_1017_10170201_88_dialog_content = "ヘンなの…とにかく、またね！",
  ui_story_1017_10170201_89_dialog_content = "またね、バイス。",
  ui_story_1017_10170201_90_dialog_content = "<color=#e8d9bb>ドクン…ドクン…</color>",
  ui_story_1017_10170201_X90_dialog_content = "「VICE」…",
  ui_story_1017_10170201_91_dialog_content = "何か聞きたいことがあるのなら、直接どうぞ。",
  ui_story_1017_10170201_92_dialog_content = "理解できないわ。フィジェロはあなたに尽くした。\nそれがなんでこんな結末になったのかしら？",
  ui_story_1017_10170201_93_dialog_content = "自ら招いた結果です。\n機会を与えなかったわけではありません。",
  ui_story_1017_10170201_94_dialog_content = "いずれにせよ、いい出来ではありませんね。\nあなたたち2人とも、生かしておく価値はありません…",
  ui_story_1017_10170201_95_dialog_content = "と言いたいところですが、目的のモノは手に入り、\n任務は成功したと言えます。",
  ui_story_1017_10170201_96_dialog_content = "もうお祝い気分ですか、アネモネ？",
  ui_story_1017_10170201_97_dialog_content = "モノは手に入れました。",
  ui_story_1017_10170201_98_dialog_content = "どれどれ…ふむ、これが何か分かりますか？\n啓光の小娘。",
  ui_story_1017_10170201_99_dialog_content = "言ったでしょう、その呼び方はやめて。",
  ui_story_1017_10170201_100_dialog_content = "フフ、子どものようなことを…\nそれで、これは何だと思いますか？",
  ui_story_1017_10170201_101_dialog_content = "ただの古くさい機械でしょ。\nこんなもののためにあれだけ大騒ぎしたの？",
  ui_story_1017_10170201_102_dialog_content = "そう、古い機械です。しかし、これは<color=#FFB400>「エンジニア」</color>のもの。\nそれがちょっとした不注意で…カナン城に落ちてしまった。",
  ui_story_1017_10170201_103_dialog_content = "「エンジニア」？",
  ui_story_1017_10170201_104_dialog_content = "本当に知らないようですね。この小娘は。",
  ui_story_1017_10170201_105_dialog_content = "「エンジニア」は啓光の歴史よりも古いですし、\nそれがなければ、啓光などチリほどの価値もないというのに。",
  ui_story_1017_10170201_106_dialog_content = "何をするつもり？",
  ui_story_1017_10170201_107_dialog_content = "当然、元の持ち主に返すのです。今見えている世界が全てではありません。\n「エンジニア」が目覚めれば、さらに多くのものが見えることでしょう。",
  ui_story_1017_10170201_108_dialog_content = "ああ、もしかして。「エンジニア」の到来に向けて、\n「カーペット」を敷く仕事に興味はありませんか…？",
  ui_story_1017_10170201_109_dialog_content = "日蝕の殿堂からアストラの中心まで――",
  ui_story_1017_10170201_110_dialog_content = "漆黒の暗力と光霊のしかばねで織りなす巨大な「カーペット」。\nきっとすばらしい眺めでしょうね。",
  ui_story_1017_10170201_111_dialog_content = "私に何かメリットがあるの？",
  ui_story_1017_10170201_112_dialog_content = "メリット？日蝕のために尽くせるだけでも、\nあなたにとっては恩恵でしょう？",
  ui_story_1017_10170201_113_dialog_content = "いつまでもおしゃべりしていていいのですか？\nアスモデウス、戻って報告は？",
  ui_story_1017_10170201_114_dialog_content = "本当につまらない人ですね…",
  ui_story_1017_10170201_115_dialog_content = "では、どうでしょう？「カーペット」がうまく敷けて事が成れば、\n私は日蝕の中にあなたの席を用意することに同意しましょう。",
  ui_story_1017_10170201_116_dialog_content = "フン、簡単なことじゃないのは分かってるでしょう。",
  ui_story_1017_10170201_117_dialog_content = "安心してください。あなたの発明したポンコツの中にも、\nそれなりに使えそうなものがあります。出すのを手伝いましょう。",
  ui_story_1017_10170201_118_dialog_content = "「エンジニア」があなたのしたことを知ったなら、\nきっと啓光の同胞として会いたがるでしょうね。",
  ui_story_1017_10170201_119_dialog_content = "やることはやるわ。\nでも、そのついでに個人的な決着も付けさせてもらう。",
  ui_story_1017_10170201_120_dialog_content = "どうぞご勝手に。ただし、手早くお願いしますよ。\n啓光のお仲間たちが、もう待ちきれないようですから。",
  ui_story_1017_10170201_121_dialog_content = "言われなくても分かっているわ。",
  ui_story_1017_10170201_122_dialog_content = "あなたは自分のやるべきことに集中してください。\nうるさい虫は手下どもに食わせておけばいいのです。",
  ui_story_1017_10170202_1_dialog_content = "隊長、暗鬼を撃退しました。目下の危険はありません！",
  ui_story_1017_10170202_2_dialog_content = "隊長って呼ぶなって言ったでしょ？",
  ui_story_1017_10170202_3_dialog_content = "先を急いでたヤツらはもう行っちゃったみたいだし。\nこんな奴ら片づけたって――",
  ui_story_1017_10170202_4_dialog_content = "ぜんっぜん面白くない！",
  ui_story_1017_10170202_5_dialog_content = "ですが、ペピータ隊長、\n我々が追跡しているのは本当に強力な敵でして…",
  ui_story_1017_10170202_6_dialog_content = "さきほど暗力計に表示された数値は、\nすでに最高値近くに達していました。",
  ui_story_1017_10170202_7_dialog_content = "だから、さっきの3匹がいた時、\nさっさと飛びかかればよかったって言ってんの。",
  ui_story_1017_10170202_8_dialog_content = "なのに、くだらないことを報告、報告って…\nつまんないだけならまだいいけど、見失ったら責任とってもらうからね！",
  ui_story_1017_10170202_9_dialog_content = "隊長、私はただ偵察任務の規則にのっとり、\n逐一発見したことを報告しているまでです。",
  ui_story_1017_10170202_10_dialog_content = "天気の異常…暗力が大陸中心へ向かって拡散する速度…\n1km単位の座標など…",
  ui_story_1017_10170202_11_dialog_content = "あ～もう、わかったわかった。でも、ベリサリアが約束してくれてるの。\nそういう面倒くさいことは抜きでいいって。",
  ui_story_1017_10170202_12_dialog_content = "これだけ人手がいて、\nその程度の事しか報告できないの？",
  ui_story_1017_10170202_13_dialog_content = "それは、その…",
  ui_story_1017_10170202_14_dialog_content = "考えを改めなさいよ。目的は「ガーディアン1号」のコアを追跡し、\n何としても取り返すこと。それが何よりも最優先なの。",
  ui_story_1017_10170202_15_dialog_content = "はい、隊長！では、このまま進みますか？",
  ui_story_1017_10170202_16_dialog_content = "もうすぐ暗面だから、私が先導するよ。\nこの道なら目をつむってでも歩けるし。",
  ui_story_1017_10170202_17_dialog_content = "もうそんな所まで来ていたのですか！\n任務は順調と言えますね！",
  ui_story_1017_10170202_18_dialog_content = "追っかけるのは簡単だけど、\nモノを取り返すのは、あんたたちの腕次第だよ。",
  ui_story_1017_10170202_19_dialog_content = "先に言っとくけど、この後また暗鬼が足止めに出てきたら、\n私が操縦するから、あんたたちは下りて暗鬼を片付けて。",
  ui_story_1017_10170202_20_dialog_content = "急ぐ仕事なんだから、これ以上速度は落とせないもん。",
  ui_story_1017_10170202_21_dialog_content = "はい、隊長！",
  ui_story_1017_10170202_22_dialog_content = "何度言わせんの？私は隊長じゃないって！",
  ui_story_1017_10170301_1_dialog_content = "将軍も詳しくは言わなかったが、\n一部の兵士がすでにあちこちの戦地に派遣されたようだ。",
  ui_story_1017_10170301_2_dialog_content = "だが大元帥様のことがあってすぐだろう。\nなんだってこんな時に…",
  ui_story_1017_10170301_3_dialog_content = "本当だよな。大元帥様がいなくなって、\nこれから先いったい誰が全体の指揮をとるんだ…",
  ui_story_1017_10170301_4_dialog_content = "「啓光の同胞たる皆さんに、\nただ今より重大な発表があります――」",
  ui_story_1017_10170301_5_dialog_content = "…",
  ui_story_1017_10170301_6_dialog_content = "「啓光連邦は建立以来、歴代大元帥の指揮の下、\n暗鬼の侵入に対抗してきました。」",
  ui_story_1017_10170301_7_dialog_content = "「我々は同盟者として共通の理想の下に集い、\n常に啓光を照らす大元帥の栄光と共に在りました。」",
  ui_story_1017_10170301_8_dialog_content = "「現在、我々は有史以来、最も大きな存亡の危機にあるのかもしれません…」",
  ui_story_1017_10170301_9_dialog_content = "「しかし、行く手が闇に包まれていようとも、\n手を携え、共に進まなければなりません。」",
  ui_story_1017_10170301_10_dialog_content = "「啓光連邦軍事および政務委員会に代わり、\n啓光の全同胞にお知らせします――」",
  ui_story_1017_10170301_11_dialog_content = "「新しい啓光連邦大元帥が引き続き我らを率い、\n暗鬼と戦い抜くという使命を果たしてくださることでしょう。」",
  ui_story_1017_10170301_12_dialog_content = "「新しい啓光の大元帥――」",
  ui_story_1017_10170301_13_dialog_content = "「ラス大元帥とともに、啓光連邦の未来を切り開きましょう！」",
  ui_story_1017_10170301_14_dialog_content = "…ラス将軍！？",
  ui_story_1017_10170301_15_dialog_content = "ラス将軍が…次の大元帥！？",
  ui_story_1017_10170301_16_dialog_content = "ラス？やっぱりね～。",
  ui_story_1017_10170301_17_dialog_content = "ど、どうしたのみんな、急に…？",
  ui_story_1017_10170301_18_dialog_content = "PlayerName、部下から知らせが入った。\nトワイライトシティが暗鬼に襲撃されている！",
  ui_story_1017_10170301_19_dialog_content = "よりによって、こんな時に！？",
  ui_story_1017_10170301_20_dialog_content = "ああ。そして啓光の上層部の対応が素早い。\n大元帥の代替わりまでもう終えてしまっているとはな。",
  ui_story_1017_10170301_21_dialog_content = "前大元帥の投獄、辺境地域の暗鬼の動き…\n合同演習中に起こった数々の出来事…偶然ではないだろう。",
  ui_story_1017_10170301_22_dialog_content = "（そしてバイスも今、任務で暗面に行ってる…）",
  ui_story_1017_10170301_23_dialog_content = "細かく考えている暇はないぞ、PlayerName。",
  ui_story_1017_10170301_24_dialog_content = "巨像の修理が完了していると聞いた。\nトワイライトシティまで送ってもらえないか聞きに来たんだ。",
  ui_story_1017_10170301_25_dialog_content = "それが今考えられる中で最速の方法なのでな。",
  ui_story_1017_10170301_26_dialog_content = "それは構わないけど…\nただ、ソラヴァンはちょうど、ガルーがテストしてて…",
  ui_story_1017_10170301_27_dialog_content = "だから、あたしもここにいるでしょ？",
  ui_story_1017_10170301_28_dialog_content = "ソラヴァンの研究はまだまだ十分じゃないけど、\n飛行はいつでもオッケーだよ。",
  ui_story_1017_10170301_29_dialog_content = "本当に？",
  ui_story_1017_10170301_30_dialog_content = "トーゼン。",
  ui_story_1017_10170301_31_dialog_content = "PlayerName、頼む！ここへ来られたのはまたとない機会ではあるが、\nトワイライトシティが危機に瀕している今、急ぎ戻らねばならん。",
  ui_story_1017_10170301_32_dialog_content = "じゃあ、すぐに出発しよう！",
  ui_story_1017_10170301_33_dialog_content = "いえ、レオ団長、私は白夜城に向かいます。\n先に戻っていてください。",
  ui_story_1017_10170301_34_dialog_content = "白夜城？カレン殿下でもどうしようもないのに、行って何になる？",
  ui_story_1017_10170301_35_dialog_content = "おそらく、ここよりも良くない状況だと思うのです。",
  ui_story_1017_10170301_36_dialog_content = "皆さんはPlayerNameと先に戻ってください。\n私たちの町を守るためです、困難であろうと試してみなければ。",
  ui_story_1017_10170301_37_dialog_content = "…",
  ui_story_1017_10170301_38_dialog_content = "本気か？",
  ui_story_1017_10170301_39_dialog_content = "ええ。トワイライトシティは危機に直面しています。\n「アイアンソーン騎士団」にはあなたが必要です。",
  ui_story_1017_10170301_40_dialog_content = "私を信じてください。もともと演習に参加した目的は街の状況を知らせるためでした。\n白夜城に応援を求めることも私の計画の内です。",
  ui_story_1017_10170301_41_dialog_content = "軍師不在の戦場がどうなるか、\nお前も分かっているだろう？",
  ui_story_1017_10170301_42_dialog_content = "PlayerNameがいれば、軍師と同じ…\nいえ、軍師以上によい結果をもたらしてくれるでしょう。",
  ui_story_1017_10170301_43_dialog_content = "どうです？あなたは兵を率いて暗鬼の排除に向かい、\n私は良い知らせを持って後ほど合流します。",
  ui_story_1017_10170301_44_dialog_content = "ヨーゼフ、どう思う？",
  ui_story_1017_10170301_45_dialog_content = "軍師殿なら必ずやり遂げてくれると信じています。\nあなたとPlayerNameの力も信じていますよ。",
  ui_story_1017_10170301_46_dialog_content = "うん、全力を尽くすよ！",
  ui_story_1017_10170301_47_dialog_content = "ならば、言う通りにしよう。約束だぞ。",
  ui_story_1017_10170301_48_dialog_content = "お気を付けて。",
  ui_story_1017_10170301_49_dialog_content = "そちらもな。",
  ui_story_1017_10170301_50_dialog_content = "<color=#e8d9bb>同じ頃、ユリシーズの実験室</color>",
  ui_story_1017_10170301_51_dialog_content = "教授、第1期「シード」の方向性選択シミュレーションですが、\n有意性検定で仮説を証明できました。",
  ui_story_1017_10170301_52_dialog_content = "予想よりも順調に進んでいます。\nこの後は臨床実験に入りますか？",
  ui_story_1017_10170301_53_dialog_content = "ええ。先ほどの放送を聞きましたね？\n新しい大元帥が就任したばかりです。いかなるミスも許されません。",
  ui_story_1017_10170301_54_dialog_content = "はい。今までも教授の実験にミスなどあったことはありません。",
  ui_story_1017_10170301_55_dialog_content = "フン。過去は過去、今は今です。",
  ui_story_1017_10170301_56_dialog_content = "相変わらず謙虚ね。何もかも計画の内といったところかしら。",
  ui_story_1017_10170301_57_dialog_content = "あなたは外してください。",
  ui_story_1017_10170301_58_dialog_content = "はい、教授。",
  ui_story_1017_10170301_59_dialog_content = "想定する結果を出すためには、\n実験段階でその想定に沿った調整をする必要がありますからね。",
  ui_story_1017_10170301_60_dialog_content = "ラスがあなたの想定する結果というわけ？",
  ui_story_1017_10170301_61_dialog_content = "私の考え方はよくご存じでしょう。",
  ui_story_1017_10170301_62_dialog_content = "私の目的はただ一つよ。啓光の安定が脅かされない限り、\n何が起ころうと構わないわ。",
  ui_story_1017_10170301_63_dialog_content = "「啓明の星計画2.0」は許容範囲内ですか？",
  ui_story_1017_10170301_64_dialog_content = "暗鬼がトワイライトシティを襲撃したらしいわね。\nここ最近の日蝕の動き、あなたの実験のためにあるみたいじゃない。",
  ui_story_1017_10170301_65_dialog_content = "暗鬼との戦いに、賭けをする余地などありません。",
  ui_story_1017_10170301_66_dialog_content = "暗潮の危機が収束した時から、\n私はすでに光霊の肉体改造の研究に取り組んでいました。",
  ui_story_1017_10170301_67_dialog_content = "ここ数年の研究の中で、徐々に分かってきたのです。\nノラの「シード」は非常に重要な要素だということが。",
  ui_story_1017_10170301_68_dialog_content = "あなたと私の目的が一致していることを願うばかりね。\nただ、一言忠告しておくわ。嫉妬は科学者にとって毒よ。",
  ui_story_1017_10170301_69_dialog_content = "心理カウンセリングにでもいらっしゃったのでしたか？",
  ui_story_1017_10170301_70_dialog_content = "おしゃべりはまたにしましょう。\n私が聞きたいのは「啓明の星計画2.0」の始動が私の目的と一致するのかってこと。",
  ui_story_1017_10170301_71_dialog_content = "大元帥の就任式には、勝ち戦が一番いいもの。",
  ui_story_1017_10170301_72_dialog_content = "ラスだけじゃないわ。彼女の率いる軍団もすべて刷新して\n戦場に出るのが望ましいわね。",
  ui_story_1017_10170301_73_dialog_content = "フフ…「鉄仮面」先生が、らしくないことおっしゃいますね。",
  ui_story_1017_10170301_74_dialog_content = "栄誉、風格、人々からの尊敬…\nあなたが大元帥になれば、状況はさらに素晴らしいものになるでしょう。",
  ui_story_1017_10170301_75_dialog_content = "40年の経験から確信してることがあるのよ。\n最も難しいのは侵攻じゃない、防御。",
  ui_story_1017_10170301_76_dialog_content = "もちろん、若者には若者の定めがあるんでしょうけど、\n成長の舞台を提供してあげるのが、私たちの務めでしょう。",
  ui_story_1017_10170301_77_dialog_content = "では、トワイライトシティを「啓明の星計画2.0」の舞台としましょう。",
  ui_story_1017_10170301_78_dialog_content = "ラスはじめ、何千何万もの啓光の兵士たちが皆、\n私の計画に参加し…",
  ui_story_1017_10170301_79_dialog_content = "啓光連邦の「明星」となって、\nトワイライトシティに黎明をもたらすでしょう。",
  ui_story_1017_10170301_80_dialog_content = "入りなさい。",
  ui_story_1017_10170301_81_dialog_content = "教授、本日の暗鬼機能実験がまもなく始まります。\nご覧になりますか？",
  ui_story_1017_10170301_82_dialog_content = "「鉄仮面」先生もご一緒にどうですか？\nいつも通り、暗鬼の能力データを記録する実験にすぎませんが。",
  ui_story_1017_10170301_83_dialog_content = "ご一緒するわ。じっと座っているのにも飽きたし。",
  ui_story_1017_10170302_1_dialog_content = "入りなさい。",
  ui_story_1017_10170302_2_dialog_content = "長官、大元帥がまもなく出立されますが、\n実験の方はまだ何か実施されますか？",
  ui_story_1017_10170302_3_dialog_content = "まずはこの報告書に目を通してください。",
  ui_story_1017_10170302_4_dialog_content = "このデータは…素晴らしい結果です。\n実験が成功したのですね！",
  ui_story_1017_10170302_5_dialog_content = "このような壮大な計画に参加させていただけたこと、\n感謝を申し上げます。",
  ui_story_1017_10170302_6_dialog_content = "いや、まだまだですよ。",
  ui_story_1017_10170302_7_dialog_content = "どういうことでしょう…？",
  ui_story_1017_10170302_8_dialog_content = "この「シード」は第1期にすぎません。\nこの後さらに第2期、第3期と続くのです…",
  ui_story_1017_10170302_9_dialog_content = "ということは、トワイライトシティは\n実験第1期の検証にすぎないということですか？",
  ui_story_1017_10170302_10_dialog_content = "その通り。臨床データはなかなかいい結果が出ましたが、\n科学研究とはそもそも奇跡と破滅が半々のブラックボックスです。",
  ui_story_1017_10170302_11_dialog_content = "中身をすべて開けてみるためには、実験と改善を繰り返さねばなりません。\nここ数日のデータはなかなかですがね。",
  ui_story_1017_10170302_12_dialog_content = "はい、おっしゃる通りです…",
  ui_story_1017_10170302_13_dialog_content = "何か気になることがあるようですね。",
  ui_story_1017_10170302_14_dialog_content = "それは…申し上げてよいものか…",
  ui_story_1017_10170302_15_dialog_content = "構いません、話してください。",
  ui_story_1017_10170302_16_dialog_content = "カナン城内で最近、一部の兵士たちが特別な薬を投与され、\n恐るべき能力を手に入れたという噂が広まっております…",
  ui_story_1017_10170302_17_dialog_content = "事実でしょう？",
  ui_story_1017_10170302_18_dialog_content = "確かに事実ではありますが、\n今後の計画に影響が出るのではないかと、懸念しております。",
  ui_story_1017_10170302_19_dialog_content = "それだけですか？",
  ui_story_1017_10170302_20_dialog_content = "他にも…公開裁判での私たちの行為が\n今後思わぬリスクにつながるのではないかと心配です。",
  ui_story_1017_10170302_21_dialog_content = "ふむ、アイゼン君。言いたいことは分かります。",
  ui_story_1017_10170302_22_dialog_content = "君は委員会の中ではまだ若手ですから、\n知り得ることには限界があります。",
  ui_story_1017_10170302_23_dialog_content = "どういうことでしょうか？",
  ui_story_1017_10170302_24_dialog_content = "君と同じ年頃の時は、私も同じ悩みを持っていました。",
  ui_story_1017_10170302_25_dialog_content = "正確な実験手順に従い、起こり得るありとあらゆる結果に対し、\n対応策を備えておく…",
  ui_story_1017_10170302_26_dialog_content = "すべてが自らの手の内にあるという感覚に\n当時私は酔いしれていました。",
  ui_story_1017_10170302_27_dialog_content = "ですが、そういったいわゆる「完璧主義」のために、\n多くのものも失いました。",
  ui_story_1017_10170302_28_dialog_content = "何をでしょう？",
  ui_story_1017_10170302_29_dialog_content = "思わぬ突破口、予想外の成果…「奇跡」と呼ばれるすべてです。",
  ui_story_1017_10170302_30_dialog_content = "しかし、「規則、計画、実行、振り返り」と言う方法論こそ、\n私たち啓光の者が幼い頃から教え込まれてきたものではありませんか？",
  ui_story_1017_10170302_31_dialog_content = "ですから、まだ若いと言ったのです。\n君も君自身の生きる道を模索してみるべきです。",
  ui_story_1017_10170302_32_dialog_content = "秩序は荒唐無稽な理想にすぎません。\n混沌こそが世界の本質なのです。",
  ui_story_1017_10170302_33_dialog_content = "…",
  ui_story_1017_10170302_34_dialog_content = "長官、啓光で最も優れた科学者になることが、\nあなたの理想なのでしょうか？",
  ui_story_1017_10170302_35_dialog_content = "今はそうではないと？",
  ui_story_1017_10170302_36_dialog_content = "いいえ！",
  ui_story_1017_10170302_37_dialog_content = "第1期の「シード」を見に行きます。\n一緒に来なさい。",
  ui_story_1017_10170302_38_dialog_content = "はい、長官。",
  ui_story_1017_10170401_1_dialog_content = "「本日、ラス大元帥は近衛兵団を率い、\nトワイライトシティへ暗鬼鎮圧の応援に出立されます。」",
  ui_story_1017_10170401_2_dialog_content = "「今回の出兵が新しい大元帥の初陣となります。」",
  ui_story_1017_10170401_3_dialog_content = "「啓光近衛兵団の精鋭兵となるには、\n非常に厳しい訓練と選抜を耐え抜く必要があると言われています。」",
  ui_story_1017_10170401_4_dialog_content = "「また、多くの兵士が啓光の新型兵器「エンジン7号」を使用した\n戦闘が可能になっているとのことです。」",
  ui_story_1017_10170401_5_dialog_content = "「ヒイロ将軍率いる第三軍団もすでに集結しています。」",
  ui_story_1017_10170401_6_dialog_content = "「今この場には大元帥の登場を待つ多くの啓光兵士と住民が、\n自発的に集結しています。」",
  ui_story_1017_10170401_7_dialog_content = "見ろ！来たぞ――",
  ui_story_1017_10170401_8_dialog_content = "なんて迫力だ…",
  ui_story_1017_10170401_9_dialog_content = "「ラス大元帥が近衛兵団を率いてお出ましです。\n啓光の同胞の皆さん、熱い拍手をもってお迎えください！」",
  ui_story_1017_10170401_10_dialog_content = "「大元帥と兵士たちの一団の顔には、\n出兵前にして、まるで凱旋行進かのような勝利の確信がのぞいています。」",
  ui_story_1017_10170401_11_dialog_content = "「今回、ラス大元帥の次に最も注目を集めている「エンジン7号」は\n啓光最高科学責任者、ガルー室長の開発によるものです。」",
  ui_story_1017_10170401_12_dialog_content = "「完成までには数多くの困難があったと聞いています。\n本日は私が現場から皆さんに、詳しい情報をお伝えします。」",
  ui_story_1017_10170401_13_dialog_content = "あっ！イタタタ…",
  ui_story_1017_10170401_14_dialog_content = "ごめんなさい…",
  ui_story_1017_10170401_15_dialog_content = "あ！あなたはエキシビションで大活躍していた、アクセリアさんですね！",
  ui_story_1017_10170401_16_dialog_content = "近衛兵団の人だったんですね！\nなんでもレインハト大元帥より強いとか！",
  ui_story_1017_10170401_17_dialog_content = "「戦闘サイボーグ」アクセリアは啓光のために生まれました。",
  ui_story_1017_10170401_18_dialog_content = "近衛兵団ってのは…「化け物」の集団なのか？",
  ui_story_1017_10170401_19_dialog_content = "体格からして俺たちと全く違う…",
  ui_story_1017_10170401_20_dialog_content = "こんな兵士たちを率いて戦うなんて、\nラス大元帥は本当にすごいんだろうな…",
  ui_story_1017_10170401_21_dialog_content = "ああ。きっとレインハト大元帥よりも強いぞ！",
  ui_story_1017_10170401_22_dialog_content = "でも…ヒイロ将軍を見たか？\nずいぶん難しい顔をしてたな…",
  ui_story_1017_10170401_23_dialog_content = "ヒイロ将軍はいつだってそうだろ。",
  ui_story_1017_10170401_24_dialog_content = "そんな小さい声では大元帥に聞こえませんよ？",
  ui_story_1017_10170401_25_dialog_content = "ちょ、長官！？俺たちはただ…",
  ui_story_1017_10170401_26_dialog_content = "所属の軍団長に弁明しに行くことですね。\nこちらでも記録を付けておきます。",
  ui_story_1017_10170401_27_dialog_content = "長官…",
  ui_story_1017_10170401_28_dialog_content = "インゲル中佐がどうしてここに？\n新しい大元帥の出立を見にいらしたのですか？",
  ui_story_1017_10170401_29_dialog_content = "アクセリアのことが心配で見に来たのです。",
  ui_story_1017_10170401_30_dialog_content = "ユリシーズ教授の会心の一作でしょう。\n心配などいらないのでは？",
  ui_story_1017_10170401_31_dialog_content = "あの戦闘でアクセリアはすでに極限状態でした。\nですが、ユリシーズ教授はそうお考えではないようで…",
  ui_story_1017_10170401_32_dialog_content = "教授のお考えが分かるとは、大したものですね。",
  ui_story_1017_10170401_33_dialog_content = "「啓明の星計画」の参加者たちが聞けば不快に思うとは知っていますが、\nユリシーズ教授も本当に多くのものを犠牲にしているのです。",
  ui_story_1017_10170401_34_dialog_content = "兵器として戦場に送られる光霊は犠牲ではないと？\nユリシーズ教授の実験は啓光の根底を揺るがすものです。",
  ui_story_1017_10170401_35_dialog_content = "光霊たちの血と涙で築かれた連邦を危うくしていると言うのに、\nあなたたちはまだ教授をかばうのですか！？",
  ui_story_1017_10170401_36_dialog_content = "血と涙…それで暗鬼に対抗できるとお思いですか？",
  ui_story_1017_10170401_37_dialog_content = "もちろん、血と涙だけで暗鬼に立ち向かうことはできません。",
  ui_story_1017_10170401_38_dialog_content = "しかし、何度となく繰り返されてきた暗鬼との戦いの中で、\n光霊の尊厳を捨ててまで強さを求めたことは今まで一度たりともありません。",
  ui_story_1017_10170401_39_dialog_content = "アクセリア、兵士たち、それからあなたの払った犠牲も、\n啓光に安寧をもたらしはしません…人々の暗鬼に対する恐怖を増幅するだけです。",
  ui_story_1017_10170401_40_dialog_content = "それでは暗鬼に屈服するも同然でしょう！",
  ui_story_1017_10170401_41_dialog_content = "私は戦争が嫌いです。ですが、屈服もしません。\n啓光が私を必要とする限り、啓光のために戦い続けます。",
  ui_story_1017_10170401_42_dialog_content = "インゲル中佐、その言葉をよく覚えておくことです。\nこれから戦場に向かう兵士たちのことも、よく目に焼き付けておいてください。",
  ui_story_1017_10170401_43_dialog_content = "彼らは自分の払った犠牲がどんなものだったのかを知りません…\nアクセリアもそうです。ですが、あなたは知っています。",
  ui_story_1017_10170401_44_dialog_content = "…",
  ui_story_1017_10170401_45_dialog_content = "「近衛兵団の前に立つのは、ラス大元帥です――」",
  ui_story_1017_10170401_46_dialog_content = "啓光の兵士たちよ、よく聞きなさい！",
  ui_story_1017_10170401_47_dialog_content = "啓光連邦大元帥、ラスがここに宣言する――",
  ui_story_1017_10170401_48_dialog_content = "暗鬼がトワイライトシティに侵攻し、同胞たちの命が失われている。\n本日我々はトワイライトシティに向かい、全ての暗鬼を退ける！",
  ui_story_1017_10170401_49_dialog_content = "ここに集結している近衛兵団の全軍は、\n啓光最強の戦力として、私と共に最先鋒としての栄誉を賜った！",
  ui_story_1017_10170401_50_dialog_content = "この戦い、何としても勝て！\nすべては啓明の光のために！",
  ui_story_1017_10170401_51_dialog_content = "啓明の光のために！！！",
  ui_story_1017_10170401_52_dialog_content = "第三軍団長、ヒイロ！",
  ui_story_1017_10170401_53_dialog_content = "はっ！",
  ui_story_1017_10170401_54_dialog_content = "隊伍を整え、各々の役割を明確に理解させ、\n出陣の命を待ちなさい。",
  ui_story_1017_10170401_55_dialog_content = "はっ！",
  ui_story_1017_10170401_56_dialog_content = "近衛兵団、出陣！",
  ui_story_1017_10170401_57_dialog_content = "おーっ！！！",
  ui_story_1017_10170401_58_dialog_content = "俺たちが…待機だって？",
  ui_story_1017_10170401_59_dialog_content = "震えるほどの…気迫だ！",
  ui_story_1017_10170401_60_dialog_content = "襟のバッジを触りましたね。",
  ui_story_1017_10170401_61_dialog_content = "ええ、私も見ました。",
  ui_story_1017_10170401_62_dialog_content = "いずれにせよ…彼女はやり遂げた。",
  ui_story_1017_10170401_63_dialog_content = "そうですね。ただ…今、何を考えているでしょうか…",
  ui_story_1017_10170401_64_dialog_content = "…",
  ui_story_1017_10170401_65_dialog_content = "（大元帥が「全軍に号令する」って、こういう感じだったのね）",
  ui_story_1017_10170401_66_dialog_content = "（レインハト、あんたにはもう慣れた事だったでしょうけど…）",
  ui_story_1017_10170401_67_dialog_content = "（大元帥になったばかりの時、あんたは何を考えてたの？）",
  ui_story_1017_10170401_68_dialog_content = "（自分が大元帥になるのは当然だって思ってた？\nそれとも、普通の人にはマネできない努力と犠牲が、やっと実を結んだと思った…？）",
  ui_story_1017_10170401_69_dialog_content = "お前は強いな、友人になろうではないか。",
  ui_story_1017_10170401_70_dialog_content = "友人？そんなもの必要ないわ。私に必要なのは鍛錬だけよ。",
  ui_story_1017_10170401_71_dialog_content = "（私はいつも自分に言い聞かせてきた。友情なんて自分を弱くするだけ。\nあんたとは友達になんてならないわ）",
  ui_story_1017_10170401_72_dialog_content = "（だから、私は大元帥になることを目標に、ずっと鍛錬に励んできた）",
  ui_story_1017_10170401_73_dialog_content = "（それなのに、自分が十分に強くなったと思えた時…）",
  ui_story_1017_10170401_74_dialog_content = "これは科学研究部が開発した最新のエネルギー誘導装置だ。\nレインハト、見本を見せてやれ。",
  ui_story_1017_10170401_75_dialog_content = "レインハトが？",
  ui_story_1017_10170401_76_dialog_content = "この装置を完璧に制御できるのはレインハトだけだ。",
  ui_story_1017_10170401_77_dialog_content = "…",
  ui_story_1017_10170401_78_dialog_content = "（たかがエネルギー誘導装置の制御でしょ？\nいいわ、だったら私は10倍の時間をかけてでも、完璧に制御してみせる）",
  ui_story_1017_10170401_79_dialog_content = "（正式な戦闘演習の時には、私とあんたの間に差なんて存在しなくなるわ）",
  ui_story_1017_10170401_80_dialog_content = "レインハト、ラスの二人組は、レインハトが命令伝達を行うように。",
  ui_story_1017_10170401_81_dialog_content = "長官！なぜ私ではダメなんですか！？",
  ui_story_1017_10170401_82_dialog_content = "命令の伝達は隊員の命に関わる。",
  ui_story_1017_10170401_83_dialog_content = "実戦の中で部隊の統率のやり方を身に付けていくといい。",
  ui_story_1017_10170401_84_dialog_content = "…",
  ui_story_1017_10170401_85_dialog_content = "（部隊を率いて、隊員の安全を守る…手探りで進歩して、\n私にも少しずつ、付いてきてくれる部下ができた）",
  ui_story_1017_10170401_86_dialog_content = "ラス第一軍団長、大尉への昇進おめでとう。\n今後も励むように。",
  ui_story_1017_10170401_87_dialog_content = "（すべては順調だった。あとは自分の力を証明する機会を待つだけ）",
  ui_story_1017_10170401_88_dialog_content = "（でも、暗鬼がシェルター19号を襲撃した時…）",
  ui_story_1017_10170401_89_dialog_content = "（最初に支援要請を受信したのは私だったのに、\nあんたはその任務を奪って、戦功をあげた…）",
  ui_story_1017_10170401_90_dialog_content = "今回の貢献勲章の受章者は――レインハトだ！",
  ui_story_1017_10170401_91_dialog_content = "（あんたはいつだって先を行く。それだけじゃないわ。\nあんたが優秀なせいで、昇進試験に余計な指標がたくさん追加された）",
  ui_story_1017_10170401_92_dialog_content = "（戦場の外で立ちまわるのは私の望みじゃないの。\n軍人は軍人らしい方法で決着をつけるべきよ！）",
  ui_story_1017_10170401_93_dialog_content = "（だから、決めた。これ以上待つ理由なんてない。\nあんたに宣戦布告する！）",
  ui_story_1017_10170401_94_dialog_content = "今は感情的になっている場合ではなかろう。\nまだ暗鬼が山ほどいるのだぞ！",
  ui_story_1017_10170401_95_dialog_content = "無駄話はなしよ。武器を取りなさい。\n私を殺すか、私の方があんたより強いと認めなさい。",
  ui_story_1017_10170401_96_dialog_content = "幼稚だな。",
  ui_story_1017_10170401_97_dialog_content = "どけ――",
  ui_story_1017_10170401_98_dialog_content = "私の代わりに暗鬼を倒してなんて言ってないわ。\nその武器を私に向けろって言ったのよ！",
  ui_story_1017_10170401_99_dialog_content = "もう1度言うが、今はそのような時ではない。\n戦闘に集中しろ！",
  ui_story_1017_10170401_100_dialog_content = "邪魔よ――",
  ui_story_1017_10170401_101_dialog_content = "暗鬼を片付けた後なら、挑戦を受けてくれる？",
  ui_story_1017_10170401_102_dialog_content = "生き延びられたなら、好きにするがいい。",
  ui_story_1017_10170401_103_dialog_content = "いいわ！",
  ui_story_1017_10170401_104_dialog_content = "暗鬼ども！私の邪魔はさせないわ！",
  ui_story_1017_10170502_1_dialog_content = "（ああ、懐かしい感覚…あんたに挑むと、\nいつもこんなふうに終わるのよね）",
  ui_story_1017_10170502_2_dialog_content = "（訓練でも実戦でも、一度も負けたことがない…\nいったいどうしたらそんなことできるのよ！？）",
  ui_story_1017_10170502_3_dialog_content = "（そんな疑問を抱えたまま、\n私は大元帥の最終選抜であんたと対決することになった…）",
  ui_story_1017_10170502_4_dialog_content = "勝者は――レインハト！",
  ui_story_1017_10170502_5_dialog_content = "レインハト、啓光連邦の大元帥就任おめでとう！",
  ui_story_1017_10170502_6_dialog_content = "レインハト大元帥！",
  ui_story_1017_10170502_7_dialog_content = "負けはしたが、ラスも相当な実力を持った軍人だ。",
  ui_story_1017_10170502_8_dialog_content = "（納得できない！私は負けていないわ！）",
  ui_story_1017_10170502_9_dialog_content = "（もう一度あんたに挑んでやる！）",
  ui_story_1017_10170502_10_dialog_content = "（10回挑んでダメなら100回、\n100回でもダメなら1000回挑んでやるわ！）",
  ui_story_1017_10170502_11_dialog_content = "戻ろう。放送で今日は天気がよくないと言っていた。\nおそらく地上では今ごろ雨が降っているのだろう。",
  ui_story_1017_10170502_12_dialog_content = "敗者に憐みをかけているつもり？",
  ui_story_1017_10170502_13_dialog_content = "私にとって、お前は敗者などではない。\n友人だ。",
  ui_story_1017_10170502_14_dialog_content = "友人？",
  ui_story_1017_10170502_15_dialog_content = "そうだ。互いに相手の行く手をふさぎ、\n互いにそれを越えていく友人だ。",
  ui_story_1017_10170502_16_dialog_content = "誰があんたの友人なのよ？\n私たちはずっと友人なんかじゃないわ。",
  ui_story_1017_10170502_17_dialog_content = "（私に友人なんていない。私にはたった一つの目標があるだけ）",
  ui_story_1017_10170502_18_dialog_content = "我々は啓光の未来のために決闘したにすぎん。\nこれからは振りかざした拳を共通の敵に向けるべきだろう。",
  ui_story_1017_10170502_19_dialog_content = "お前の未来はお前の手のひらから湧き出てくるのだ。\n拳を握りしめたままでは、何も残らないぞ。",
  ui_story_1017_10170502_20_dialog_content = "あんたは啓光大元帥の袖章を握りしめて、皆に祝ってもらえばいいわ。\n私はこれからもあんたに挑み続ける。",
  ui_story_1017_10170502_21_dialog_content = "大元帥であろうと、遠慮はしない。",
  ui_story_1017_10170502_22_dialog_content = "私に勝てば、大元帥の席はお前のものだ。",
  ui_story_1017_10170502_23_dialog_content = "これから先も私に勝ち続ける自信があるの？",
  ui_story_1017_10170502_24_dialog_content = "…",
  ui_story_1017_10170502_25_dialog_content = "どうなのよ？",
  ui_story_1017_10170502_26_dialog_content = "ある。",
  ui_story_1017_10170502_27_dialog_content = "だったら警戒を怠らないことね。\nこれから先、私はずっとあんたに挑み続けるわ。",
  ui_story_1017_10170502_28_dialog_content = "大元帥の地位も、それ以外も、\nあんたの手にしたものは全部奪ってやるわ！",
  ui_story_1017_10170502_29_dialog_content = "（それなのに最も望まない形で、\nあんたに取って代わることになるとは思いもしなかった）",
  ui_story_1017_10170502_30_dialog_content = "（フッ…歓呼の声もそしる声も混じっているのね。\nでも私はあんたみたいに他人に操られたりしない）",
  ui_story_1017_10170502_31_dialog_content = "（私を使って実験検証したがっているヤツらが\nこれから目にするのは――）",
  ui_story_1017_10170502_32_dialog_content = "（思うままにならない「大元帥」よ）",
  ui_story_1017_10170601_1_dialog_content = "<color=#e8d9bb>トワイライトシティでは、大勢の住民が病院に向かって移動していた…</color>",
  ui_story_1017_10170601_2_dialog_content = "もう少し頑張るんだ。<color=#FFB400>病院</color>はもうすぐそこだ。",
  ui_story_1017_10170601_3_dialog_content = "もう足が動かないわ…",
  ui_story_1017_10170601_4_dialog_content = "僕が負ぶってやる。今周囲の戦地には暗鬼しかいない。\nいつここまで襲ってくるか分からないんだ。",
  ui_story_1017_10170601_5_dialog_content = "あ！痛い――",
  ui_story_1017_10170601_6_dialog_content = "担架に乗せましょう。",
  ui_story_1017_10170601_7_dialog_content = "え？あなたたちは…",
  ui_story_1017_10170601_8_dialog_content = "足が痛まないように、そうっと動かしてください。",
  ui_story_1017_10170601_9_dialog_content = "わかったよ、ジョセリンお姉ちゃん。",
  ui_story_1017_10170601_10_dialog_content = "あなた方は病院の方ですか？",
  ui_story_1017_10170601_11_dialog_content = "ええ。こんにちは、ジョセリンと申します。\nこの子は看護師です。",
  ui_story_1017_10170601_12_dialog_content = "こんにちは、アーチだよ。",
  ui_story_1017_10170601_13_dialog_content = "アーチ、小さいのに偉いのね。",
  ui_story_1017_10170601_14_dialog_content = "えへへ！",
  ui_story_1017_10170601_15_dialog_content = "ジョセリン…",
  ui_story_1017_10170601_16_dialog_content = "あっ！あなたはまさか…白夜教区の「聖女」様ですね！",
  ui_story_1017_10170601_17_dialog_content = "「聖女」様！？",
  ui_story_1017_10170601_18_dialog_content = "いいえ…私は「聖女」ではありません。\nごく普通の平民です。",
  ui_story_1017_10170601_19_dialog_content = "ジョセリンお姉ちゃん、「聖女」ってなあに？",
  ui_story_1017_10170601_20_dialog_content = "「聖女」っていうのは、光の神の民を守る、\nこの世の女神様のことよ！",
  ui_story_1017_10170601_21_dialog_content = "「聖女」様がいれば、私たちの故郷に\n暗鬼が足を踏み入れることはないの。",
  ui_story_1017_10170601_22_dialog_content = "わ！ほんとなの？ジョセリンお姉ちゃんって「聖女」様なの？",
  ui_story_1017_10170601_23_dialog_content = "本当に「聖女」などという大それた者ではないのです。\nどうかジョセリンとお呼びください。",
  ui_story_1017_10170601_24_dialog_content = "私はただ「光の神」が必ずや暗黒を絶ち、\n光の民を永遠に輝かせてくださると信じているだけです。",
  ui_story_1017_10170601_25_dialog_content = "その日が来るまで、\n私は自分のできることを精一杯尽くしていきます。",
  ui_story_1017_10170601_26_dialog_content = "ジョセリンお姉ちゃん。\n「光の神」がなんとかどうとか…よくわかんないよ。",
  ui_story_1017_10170601_27_dialog_content = "光は必ず暗闇に勝ち、私たちは皆「光の神」の懐に\n戻れるという意味ですよ。",
  ui_story_1017_10170601_28_dialog_content = "ジョセリン――",
  ui_story_1017_10170601_29_dialog_content = "病院の状況はどうだ？",
  ui_story_1017_10170601_30_dialog_content = "これほど多くの人が集まったことはないのですが…\nまだ余裕はあるはずです。",
  ui_story_1017_10170601_31_dialog_content = "前線の状況はいかがですか？",
  ui_story_1017_10170601_32_dialog_content = "はぁ…暗鬼の侵攻は唐突だったうえに勢いも激しい。\n死傷者の数もとてつもなく多い！",
  ui_story_1017_10170601_33_dialog_content = "今、トワイライトシティの周りの防衛線はすべて崩壊状態だ。\n住民の多くも襲撃を受けて…",
  ui_story_1017_10170601_34_dialog_content = "なんてことだ！！",
  ui_story_1017_10170601_35_dialog_content = "もう終わりだわ…何もかも終わりよ…",
  ui_story_1017_10170601_36_dialog_content = "レオ騎士団長たちからの知らせはないのですか？",
  ui_story_1017_10170601_37_dialog_content = "だいぶ前に知らせたんだが、まだ戻らないんだ！",
  ui_story_1017_10170601_38_dialog_content = "これから団長の馬と装備を持って、\nトワイライトシティの<color=#FFB400>関門</color>まで迎えに行くところだ。",
  ui_story_1017_10170601_39_dialog_content = "団長がいない間、この馬ときたら代わりに指揮するつもりだったのか、\n戦場に飛び出して、危うく暗鬼にやられるところだったんだ。",
  ui_story_1017_10170601_40_dialog_content = "「アイアンソーン騎士団」は今も戦闘中だ…\n私は先に失礼するよ。こっちのことは君に任せた。",
  ui_story_1017_10170601_41_dialog_content = "白夜に捧ぐ――",
  ui_story_1017_10170601_42_dialog_content = "アーチ、あなたはこちらの方と一緒にケガをした女性を\n病院まで連れて行って差し上げてください。",
  ui_story_1017_10170601_43_dialog_content = "病院に着いたら、担当の看護師にトワイライトシティの周囲へ\n医療者を増援するよう伝えてください。",
  ui_story_1017_10170601_44_dialog_content = "だったら、ジョセリンお姉ちゃんはどこ行くの？",
  ui_story_1017_10170601_45_dialog_content = "戦場に向かいます。",
  ui_story_1017_10170601_46_dialog_content = "戦場ですと！戦場は…戦士が行く処ですよ。",
  ui_story_1017_10170601_47_dialog_content = "私は戦士です。こういう時こそ戦場に立っているべきです。",
  ui_story_1017_10170601_48_dialog_content = "アーチ、頼みましたよ。また後ほど。",
  ui_story_1017_10170601_49_dialog_content = "…",
  ui_story_1017_10170601_50_dialog_content = "君…大丈夫かい？",
  ui_story_1017_10170601_51_dialog_content = "小さいからってあまく見ないで！\n私、力もちなんだから！",
  ui_story_1017_10170601_52_dialog_content = "<color=#e8d9bb>ジョセリンがトワイライトシティ周辺の戦地へやってきた…</color>",
  ui_story_1017_10170601_53_dialog_content = "足元！気を付けて！",
  ui_story_1017_10170601_54_dialog_content = "全力で斬ります！",
  ui_story_1017_10170601_55_dialog_content = "この暗鬼はさきほどの攻撃で息絶えていたはずですが。",
  ui_story_1017_10170601_56_dialog_content = "すでに倒れた敵にも注意しろ。\n時としてヤツらの攻撃こそ致命的になるからな。",
  ui_story_1017_10170601_57_dialog_content = "分かりました。ありがとうございます。",
  ui_story_1017_10170601_58_dialog_content = "全部団長の受け売りだよ。\nただ団長がいないと、何か足らない気がしてならないな。",
  ui_story_1017_10170601_59_dialog_content = "みんな口には出さないが、心の中じゃ不安なんだ…",
  ui_story_1017_10170601_60_dialog_content = "分かります…これほどの数の暗鬼は私も初めて見ました。",
  ui_story_1017_10170601_61_dialog_content = "何が目的かご存じですか？",
  ui_story_1017_10170601_62_dialog_content = "まだ分からない。ヤツらの動きには規則性がなく、\nこっちの防衛線はひたすら後退するばかりだ…",
  ui_story_1017_10170601_63_dialog_content = "このまま後退を続けてたら、\nトワイライトシティを守り切れない…",
  ui_story_1017_10170601_64_dialog_content = "後ろです、危ない――！",
  ui_story_1017_10170601_65_dialog_content = "くっ！",
  ui_story_1017_10170601_66_dialog_content = "「アイアンソーン騎士団」の戦士が、\nそんな弱気なことを言ってどうするのです？",
  ui_story_1017_10170601_67_dialog_content = "レオ騎士団長がいなくとも、全力を尽くし、\n暗鬼を排除しなければなりません！",
  ui_story_1017_10170601_68_dialog_content = "辺境を長年守ってきて、よく分かった。トワイライトシティは神に見捨てられた地だ。\n救援は得られず、暗鬼に食われるがまま。",
  ui_story_1017_10170601_69_dialog_content = "俺たちがここを守ってるのは、自分たちがここで生まれて、\n他に行く所がないからだ。",
  ui_story_1017_10170601_70_dialog_content = "もし戻れるなら…誰がこんな所で\n明日をも知れぬ暮らしをしたいって言うんだ。",
  ui_story_1017_10170601_71_dialog_content = "…",
  ui_story_1017_10170601_72_dialog_content = "だからと言って…怖気づいてるって意味じゃない…\n無名の戦士でも自分が何のために戦うべきかくらいは分かってるさ…",
  ui_story_1017_10170601_73_dialog_content = "こんなこと言って、ひどいヤツだと思うか？",
  ui_story_1017_10170601_74_dialog_content = "ここを守るためには、十分ではありませんか？",
  ui_story_1017_10170601_75_dialog_content = "トワイライトシティの外を見たことのない子どもたちは、\nトワイライトシティこそが世界だと思っています。",
  ui_story_1017_10170601_76_dialog_content = "この世界の真実の姿を目にするまで、\n私たちもかつてはそう思っていました…",
  ui_story_1017_10170601_77_dialog_content = "すでに犠牲となった戦士たちも、\nまさにこの小さな世界を守るために戦ったのでしょう？",
  ui_story_1017_10170601_78_dialog_content = "…",
  ui_story_1017_10170601_79_dialog_content = "戦士には偉大な戦争で自身を証明する必要などありません。",
  ui_story_1017_10170601_80_dialog_content = "一つの土地を守りぬけば、その功績は偉大なのです。",
  ui_story_1017_10170601_81_dialog_content = "そうかもな…君の言うことは正しいよ。でも分かってるんだ。\n俺たちはずっと団長のために戦ってきたんだってこと…",
  ui_story_1017_10170601_82_dialog_content = "レオ団長もあなた方のために戦ってきたのでしょう？",
  ui_story_1017_10170601_83_dialog_content = "ああ。俺たちのために、団長は多くのものを失った。",
  ui_story_1017_10170601_84_dialog_content = "さらに多くのものを失わないよう、\n共に戦ってきたこの地を一緒に守りましょう！",
  ui_story_1017_10170601_85_dialog_content = "この地に生まれた者も、何かの理由でここへ来た者も、\nお互いのために戦おうではありませんか！",
  ui_story_1017_10170601_86_dialog_content = "ああ、その通りだな。みんなに伝えるよ――",
  ui_story_1017_10170601_87_dialog_content = "「アイアンソーン騎士団」よく聞け！\n暗鬼どもの前進は犠牲になった仲間への恥辱だ！",
  ui_story_1017_10170601_88_dialog_content = "「アイアンソーン騎士団」にあるのは鋭いトゲだけじゃない！\n折っても折れない強い気骨がある！",
  ui_story_1017_10170601_89_dialog_content = "自分たちのしかばねで城壁を築いてでも、\n暗鬼の侵攻を食い止めるぞ！",
  ui_story_1017_10170601_90_dialog_content = "さあ、行くぞ！",
  ui_story_1017_10170601_91_dialog_content = "私もご一緒します！",
  ui_story_1017_10170601_92_dialog_content = "命に誓ってトワイライトシティを守るぞ！",
  ui_story_1017_10170601_93_dialog_content = "命に誓ってトワイライトシティを守るぞ！",
  ui_story_1017_10170602_1_dialog_content = "ソラヴァン、トワイライトシティはもうすぐかな？",
  ui_story_1017_10170602_2_dialog_content = "PlayerName、あなたはこの1分間で同じ質問を10回しました。",
  ui_story_1017_10170602_3_dialog_content = "ごめん、焦っちゃって…",
  ui_story_1017_10170602_4_dialog_content = "そうですか。意識接続に遅延があったのか確認したかったのですが、\nどうやらそうではなかったようですね。",
  ui_story_1017_10170602_5_dialog_content = "接続に遅延はないけど…飛行速度が遅い気がして…",
  ui_story_1017_10170602_6_dialog_content = "飛行速度を確認します。\n終始<color=#FFB400>最高速度</color>を保っています。",
  ui_story_1017_10170602_7_dialog_content = "…",
  ui_story_1017_10170602_8_dialog_content = "落胆しているようですね。理由を聞かせてくれますか？",
  ui_story_1017_10170602_9_dialog_content = "君が意識を失ってから、もうずいぶん経ってるんだよね。",
  ui_story_1017_10170602_10_dialog_content = "それなのに君が今どんな状況なのか聞く暇もなく、\nただトワイライトシティに急がせたりして…",
  ui_story_1017_10170602_11_dialog_content = "あなたには長い時間だったかもしれませんが、\n私の設定の中では、私たちが離れたことは一度もありません。",
  ui_story_1017_10170602_12_dialog_content = "確かに…そうだね。",
  ui_story_1017_10170602_13_dialog_content = "あなたが仲間たちといろいろな所へ行くおかげで、\n私もたくさんの景色を観ることができるのです。",
  ui_story_1017_10170602_14_dialog_content = "おや、<color=#FFB400>新しい景色</color>が見えました。\nこの先が目的地です。",
  ui_story_1017_10170602_15_dialog_content = "着いたの？",
  ui_story_1017_10170602_16_dialog_content = "近くまで来ています。着陸地点を確認してください。",
  ui_story_1017_10170602_17_dialog_content = "うん、分かった。トワイライトシティの件が終わったら、\n今まで起こったことを全部話してあげるね。",
  ui_story_1017_10170602_18_dialog_content = "それじゃ、まずは減速、低空飛行に入ったら、\n<color=#FFB400>ハッチのドアを開けて</color>。",
  ui_story_1017_10170602_19_dialog_content = "減速しています。\n<color=#FFB400>3号ハッチのドア</color>を開いています…",
  ui_story_1017_10170602_20_dialog_content = "レオ――",
  ui_story_1017_10170602_21_dialog_content = "感謝する、PlayerName。\nトワイライトシティの状況が落ち着いたら、改めて礼をする。",
  ui_story_1017_10170602_22_dialog_content = "お礼なんていいよ…それより、ソラヴァンはもう下降し始めてるんだけど、\nどこに着陸したらいいかな？",
  ui_story_1017_10170602_23_dialog_content = "関門にいる兵士が見えるか？",
  ui_story_1017_10170602_24_dialog_content = "誰かいるみたいだね…\n馬が3頭並んでるように見えるけど…",
  ui_story_1017_10170602_25_dialog_content = "私の部下だ。馬を引いて、待ってくれているのだ。",
  ui_story_1017_10170602_26_option_content = "目がいいんだね！？",
  ui_story_1017_10170602_27_dialog_content = "こんな遠くから、あれが人と馬だって分かるの？",
  ui_story_1017_10170602_28_dialog_content = "もちろんだ。トワイライトシティは人を育てる最良の地だ。",
  ui_story_1017_10170602_29_option_content = "さすがだね。",
  ui_story_1017_10170602_30_dialog_content = "団長と部下はやっぱり心が通じてるんだね。",
  ui_story_1017_10170602_31_dialog_content = "長年共に戦い、培った阿吽の呼吸だ。",
  ui_story_1017_10170602_32_dialog_content = "機会があれば、お前にも行軍と戦いの術を教えてやる。",
  ui_story_1017_10170602_33_dialog_content = "着陸高度に到達しました。\nPlayerName、着陸地点を確定してください。",
  ui_story_1017_10170602_34_dialog_content = "レオ、関門の前に着陸でいい？",
  ui_story_1017_10170602_35_dialog_content = "ああ…そうだな。この辺りでいい。\nよし、ここだ。では――",
  ui_story_1017_10170602_36_dialog_content = "PlayerName、ヨーゼフを頼んだぞ。",
  ui_story_1017_10170602_37_dialog_content = "ヨーゼフ、また会おう。",
  ui_story_1017_10170602_38_dialog_content = "またお会いしましょう、レオ騎士団長。",
  ui_story_1017_10170602_39_dialog_content = "？？？",
  ui_story_1017_10170602_40_dialog_content = "え、飛び降りちゃった！？",
  ui_story_1017_10170602_41_dialog_content = "ちょっと！じゃあ、僕は――？",
  ui_story_1017_10170602_42_dialog_content = "戻れ――",
  ui_story_1017_10170602_43_dialog_content = "…",
  ui_story_1017_10170602_44_dialog_content = "団長！あの大きな物体から飛び降りてきたのは、\n本当に団長だったんですね！",
  ui_story_1017_10170602_45_dialog_content = "あれが伝説の…巨像ですか！？",
  ui_story_1017_10170602_46_dialog_content = "ああ、そうだ。待たせてすまなかった。",
  ui_story_1017_10170602_47_dialog_content = "このまま戦場に向かうぞ。馬を走らせながら話すとしよう。\nトワイライトシティの状況は？",
  ui_story_1017_10170602_48_dialog_content = "<color=#FFB400>極夜</color>の方向から暗鬼が侵入し、\n周囲の砦はすでに破られました。今我々が食い止めに努めています。",
  ui_story_1017_10170602_49_dialog_content = "暗鬼は誰が操っているのだ？",
  ui_story_1017_10170602_50_dialog_content = "頭となる暗鬼はいません。\nただ数がはなはだ多く、動きも秩序がなく混乱しています！",
  ui_story_1017_10170602_51_dialog_content = "死傷者の状況は？",
  ui_story_1017_10170602_52_dialog_content = "周辺地域の住民の多くが襲撃を受けたので、安全地帯への移住を手配しました。\n兵士は数百名が負傷し…",
  ui_story_1017_10170602_53_dialog_content = "<color=#FFB400>75名</color>の仲間が残念ながら犠牲になりました…",
  ui_story_1017_10170602_54_dialog_content = "<color=#FFB400>75名</color>が犠牲になった！？\nならば、お前はここで何をしている？",
  ui_story_1017_10170602_55_dialog_content = "団長…団長がお帰りになる前、あなたの馬が手綱を振り払って\n戦場に飛び出し、暗鬼にぶつかって行ったんです…",
  ui_story_1017_10170602_56_dialog_content = "私がなんとかそれを抑えて…\n本当にどうすればいいか、分からない状態なんです！",
  ui_story_1017_10170602_57_dialog_content = "ふん！トワイライトシティを飲み込む気か。\nそうはいかんぞ。",
  ui_story_1017_10170602_58_dialog_content = "近くの村には連絡したのか？",
  ui_story_1017_10170602_59_dialog_content = "戦える者は皆、応援に駆けつけてくれています。ただ…\n近くの村も状況は厳しく…",
  ui_story_1017_10170602_60_dialog_content = "戦闘だけではありません…医療資源の消耗も非常に激しく…",
  ui_story_1017_10170602_61_dialog_content = "白夜要塞から病院に援助は来ていないのか？",
  ui_story_1017_10170602_62_dialog_content = "来ていません。病院には村の医者と看護師しかおらず、\n少し医療をかじった子どもまで手伝いに駆り出されています…",
  ui_story_1017_10170602_63_dialog_content = "ごく簡単なこともトワイライトシティでは、\n困難を極めるのだな。",
  ui_story_1017_10170602_64_dialog_content = "だが、いい知らせもある。私が戻ってきたのだ。\nこれ以上仲間が無駄に犠牲になることはない。",
  ui_story_1017_10170602_65_dialog_content = "悪い知らせは、頼れるのは相変わらず己の力のみということだ。",
  ui_story_1017_10170602_66_dialog_content = "ええ…ところで団長。ショウさんはなぜご一緒ではないんですか？",
  ui_story_1017_10170602_67_dialog_content = "奴にはまだやることがある。しばらく時間はかかるだろうが、\n必ずや我々に転機をもたらしてくれるだろう。",
  ui_story_1017_10170602_68_dialog_content = "このトワイライトシティの危機に、\n本当に転機など訪れるのでしょうか？",
  ui_story_1017_10170602_69_dialog_content = "上だ！",
  ui_story_1017_10170602_70_dialog_content = "受け止めろ！",
  ui_story_1017_10170602_71_dialog_content = "<color=#e8d9bb>兵士は空から降ってきたPlayerNameを受け止めたが、\n2人ともあやうく落馬するところだった…</color>",
  ui_story_1017_10170602_72_dialog_content = "あ、あなたのことは…知っています…\nあやうく下敷きになるところでしたよ！",
  ui_story_1017_10170602_73_dialog_content = "きょ、巨像まで…落ちてこなくて…幸いでしたが！",
  ui_story_1017_10170602_74_dialog_content = "ごめん…",
  ui_story_1017_10170602_75_dialog_content = "大丈夫ですか？",
  ui_story_1017_10170602_76_option_content = "大丈夫だよ",
  ui_story_1017_10170602_77_dialog_content = "ソラヴァンがちょうどいい高度で飛行してくれたから。",
  ui_story_1017_10170602_78_option_content = "ここはどこ、僕は誰？",
  ui_story_1017_10170602_79_dialog_content = "落下中、心臓が止まるかと思った。",
  ui_story_1017_10170602_80_dialog_content = "ソラヴァンがちょうどいい高度で飛んでてくれてよかった…",
  ui_story_1017_10170602_81_dialog_content = "何しにきたのだ？",
  ui_story_1017_10170602_82_dialog_content = "一緒にトワイライトシティに行くって言ったのに、\n途中で帰れ、なんてひどいよ。",
  ui_story_1017_10170602_83_dialog_content = "感謝している。だが、もう十分だ。",
  ui_story_1017_10170602_84_dialog_content = "引き返し、彼を送り帰すぞ。",
  ui_story_1017_10170602_85_dialog_content = "団長…",
  ui_story_1017_10170602_86_dialog_content = "部下をこれ以上犠牲にするわけにはいかん！",
  ui_story_1017_10170602_87_dialog_content = "ちょっと待ってよ！僕は君の部下になるつもりはないよ！？",
  ui_story_1017_10170602_88_dialog_content = "それに僕とソラヴァンがいれば、\nトワイライトシティの戦局に有利なはずだよ。",
  ui_story_1017_10170602_89_dialog_content = "今のソラヴァンの高度なら、\nちょうど前線の軍の全容がはっきりと見える。",
  ui_story_1017_10170602_90_dialog_content = "ソラヴァンは空中からの視点で戦局を見渡せるし、\n僕は戦場の指示ができるよ。",
  ui_story_1017_10170602_91_dialog_content = "空中からの視点か…なるほど、一理あるな。",
  ui_story_1017_10170602_92_dialog_content = "ショウさんが不在の今、PlayerNameの戦場での指揮能力は、\n大きな力になるかもしれません。",
  ui_story_1017_10170602_93_dialog_content = "確かにその通りだ。",
  ui_story_1017_10170602_94_dialog_content = "だがトワイライトシティでの戦いは演習ではない。\n倒されてしまえば、本当に命を落とすのだぞ。",
  ui_story_1017_10170602_95_dialog_content = "それでも来るか？",
  ui_story_1017_10170602_96_dialog_content = "もちろんだよ！",
  ui_story_1017_10170602_97_dialog_content = "分かった。ならば全速力で戦場へ向かうぞ！",
  ui_story_1017_10170602_98_dialog_content = "はい、団長！",
  ui_story_1017_10170602_99_dialog_content = "敵が…際限なく湧いてくるようだ…",
  ui_story_1017_10170602_100_dialog_content = "しかも今だ頭たる暗鬼が見当たりません。",
  ui_story_1017_10170602_101_dialog_content = "全員疲れ切っている。\nジョセリン、このままではそのうち耐えきれなくなるぞ。",
  ui_story_1017_10170602_102_dialog_content = "新しい砦はまだ完成していません。\n今ここであきらめてしまっては、これまでの抵抗も無駄になってしまいます！",
  ui_story_1017_10170602_103_dialog_content = "だが、士気が下がっている…\nこのままではたとえ団長が戻っても、挽回のしようがない…",
  ui_story_1017_10170602_104_dialog_content = "私が戻っても挽回のしようがないだと？",
  ui_story_1017_10170602_105_dialog_content = "団長！戻ってらしたんですね！",
  ui_story_1017_10170602_106_dialog_content = "団長が戻られたぞ！！",
  ui_story_1017_10170602_107_dialog_content = "空を飛んでいるのは…",
  ui_story_1017_10170602_108_dialog_content = "「アイアンソーン騎士団」の騎士たちよ、待たせたな！",
  ui_story_1017_10170602_109_dialog_content = "さあ、今こそ騎士の気骨を見せる時だ！",
  ui_story_1017_10170602_110_dialog_content = "PlayerNameと巨像ソラヴァンが、\n我々を導き、守ってくれる！",
  ui_story_1017_10170602_111_dialog_content = "あれが伝説の巨像か。思っていたよりずっとデカいぞ！",
  ui_story_1017_10170602_112_dialog_content = "巨像と共に戦うぞ！",
  ui_story_1017_10170602_113_dialog_content = "その通りだ。ソラヴァンも我々の仲間だ。\n皆よく耳を研ぎ澄まし、指揮命令を聞き落とすことのないよう！",
  ui_story_1017_10170602_114_dialog_content = "今からソラヴァンの進む方向へ、\n全速力で前進し、暗鬼を撃退する！！",
  ui_story_1017_10170602_115_dialog_content = "おー！！！！",
  ui_story_1017_10170602_116_dialog_content = "PlayerName、頼んだぞ！",
  ui_story_1017_10170602_117_dialog_content = "うん、全力を尽くすよ！",
  ui_story_1017_10170701_1_dialog_content = "白夜城に通じる道はこの近くのはずですが…",
  ui_story_1017_10170701_2_dialog_content = "あっ――",
  ui_story_1017_10170701_X2_dialog_content = "噛みつく、噛みつく！",
  ui_story_1017_10170701_3_dialog_content = "つまんなーい、マジつまんなーい。\n誰か探して、イジメるのはどう！？",
  ui_story_1017_10170701_4_dialog_content = "あ、あなたたちは…どなたですか？",
  ui_story_1017_10170701_5_dialog_content = "当ててみて！",
  ui_story_1017_10170701_6_dialog_content = "からかわないでください。\n急ぎの用事があるので、これで失礼します。",
  ui_story_1017_10170701_7_dialog_content = "急ぎなら、私に頼めばいいじゃん。\nちゃんとできるか保証はないけどね。",
  ui_story_1017_10170701_8_dialog_content = "…",
  ui_story_1017_10170701_9_dialog_content = "白夜城へは、どのように行けばいいのですか？",
  ui_story_1017_10170701_10_dialog_content = "あの白くて、フワフワ浮かんでる、冷たい所なんて、\n誰も行かないよ。",
  ui_story_1017_10170701_11_dialog_content = "確か白夜城行きの交通手段があったはずでは…",
  ui_story_1017_10170701_12_dialog_content = "優しいワンコが教えてあげるよ。\n白夜城行きの交通手段は運航停止になってるんだよ。",
  ui_story_1017_10170701_13_dialog_content = "…最近になって運行停止になったのですか？\n理由はご存じですか？",
  ui_story_1017_10170701_14_dialog_content = "質問が多いね。悪い事しようとしてるなら、ハッキリ言いなよ。\nそれか――",
  ui_story_1017_10170701_15_dialog_content = "私も連れてって！",
  ui_story_1017_10170701_16_dialog_content = "<size=30>啓光で起きたことはすでに伝わっているはず…\n白夜城の対応は予想よりも素早かったですね</size>",
  ui_story_1017_10170701_17_dialog_content = "<size=30>クーリエ隊の交通手段を借りるという手もありますが…</size>",
  ui_story_1017_10170701_18_dialog_content = "<size=30>何と言って借りるかが問題です…</size>",
  ui_story_1017_10170701_19_dialog_content = "うわっ――",
  ui_story_1017_10170701_20_dialog_content = "あ、あなたたち、何をするのですか！？",
  ui_story_1017_10170701_21_dialog_content = "全身から陰謀の匂いがしてるよ！\nワンコの鼻はごまかせないんだから！",
  ui_story_1017_10170701_22_dialog_content = "カタブツ、何か企んでる！\nボスに引き渡して、ごはんにするよ！",
  ui_story_1017_10170701_23_dialog_content = "それほど鼻がいいのなら、トワイライトシティのきな臭さが分かるでしょう？\n本当に急いでいるのです。出してください！",
  ui_story_1017_10170701_24_dialog_content = "この中は…ううっ…頭がくらくらしてきました…",
  ui_story_1017_10170701_25_dialog_content = "ここは影ノ街だよ！トワイライトシティじゃない！",
  ui_story_1017_10170701_26_dialog_content = "ゴミ箱の中にあるのはみんないいものだよ！\nちゃんと火を通して食べてね！",
  ui_story_1017_10170701_27_dialog_content = "ボス、報告だよ。\nいいもの見つけたよ、ごほうびにお肉ちょうだい！",
  ui_story_1017_10170701_28_dialog_content = "ゴミを拾ってくるなと言ったはずだろう？",
  ui_story_1017_10170701_29_dialog_content = "ゴミじゃないよ、悪いやつだよ！\nボス、ほら見て――",
  ui_story_1017_10170701_30_dialog_content = "コソコソ、あたふたしてた。",
  ui_story_1017_10170701_31_dialog_content = "私たちを見て逃げ出した！",
  ui_story_1017_10170701_32_dialog_content = "…",
  ui_story_1017_10170701_33_dialog_content = "たいへんだ！壊れちゃった！",
  ui_story_1017_10170701_34_dialog_content = "その格好はお堅い啓光の者のようだが…\nここで何をしていたのだ？",
  ui_story_1017_10170701_35_dialog_content = "確か白夜城を占領して、クーリエ隊を消すとかなんとか…",
  ui_story_1017_10170701_36_dialog_content = "そうそう！それから影ノ街をトワイライトにするって！",
  ui_story_1017_10170701_37_dialog_content = "トワイライトシティにするって！",
  ui_story_1017_10170701_38_dialog_content = "トワイライトシティだと？",
  ui_story_1017_10170701_39_dialog_content = "そう、トワイライトシティだよ！\nこいつから火薬の匂いがプンプンする！",
  ui_story_1017_10170701_40_dialog_content = "<color=#FFB400>クレーケン</color>を呼んでくるんだ。\nお前たちは食事にするがいい。",
  ui_story_1017_10170701_41_dialog_content = "わかったよ、ボス！\nお仕事は終わり！ごはんだ～！",
  ui_story_1017_10170701_42_dialog_content = "城主様、いったいいつまでお考えになっているおつもりですか？",
  ui_story_1017_10170701_43_dialog_content = "こちらはすべて白夜要塞から届いた書簡です。",
  ui_story_1017_10170701_44_dialog_content = "これ以上出兵をためらえば、\n今年の<color=#FFB400>希鉱石</color>の採掘量も4割減産となるでしょう。",
  ui_story_1017_10170701_45_dialog_content = "採掘量減少によって起こり得る原料の逼迫、さらには供給不足は、\n白夜城の対外貿易に多大なる影響を与えることに…",
  ui_story_1017_10170701_46_dialog_content = "損失はそれだけではありません！",
  ui_story_1017_10170701_47_dialog_content = "トワイライトシティの安否がいつ白夜城の経済に\n影響を与えるようになったのだ？",
  ui_story_1017_10170701_48_dialog_content = "お前が心配しているのは、\nここ数年トワイライトシティで築いた己の財だろう？",
  ui_story_1017_10170701_49_dialog_content = "デタラメを言わないでください！我が<color=#FFB400>ディートリヒ</color>家は歴史の浅い貴族とはいえ、\nここ数年は採掘した資源を白夜城に提供し続けてきました…",
  ui_story_1017_10170701_50_dialog_content = "苦しい環境の中、流罪となった多くの騎士にも住処を与え…",
  ui_story_1017_10170701_51_dialog_content = "その功績から言えば、<color=#FFB400>ディートリヒ</color>家もとうの昔に、\nアップタウンに自らの荘園をもっていてもいいはずです。",
  ui_story_1017_10170701_52_dialog_content = "ですが、<color=#FFB400>トロイ</color>家は違います。\n城主様のそばで優雅な暮らしに溺れ、暗鬼に対抗する能力など退化してしまったのでしょう？",
  ui_story_1017_10170701_53_dialog_content = "啓光はそもそも戦争を好むのだ。\n暗鬼の鎮圧など奴らに任せておけばいい。",
  ui_story_1017_10170701_54_dialog_content = "それだけではない。\n「アイアンソーン騎士団」はトワイライトシティで大きな影響力を持っている。",
  ui_story_1017_10170701_55_dialog_content = "騎士の面倒を見てやっているというが、\nそうして養った剣を将来どこに向けるか、すでに計画済みなのであろう？",
  ui_story_1017_10170701_56_dialog_content = "あなたはご存じないのでしょう。\n「アイアンソーン騎士団」が守っているのはトワイライトシティ全体です。",
  ui_story_1017_10170701_57_dialog_content = "彼らは啓光の軍人と親密で、レオ団長は今回啓光の軍人と共に\n啓光連邦の合同演習に参加したとか。",
  ui_story_1017_10170701_58_dialog_content = "私の知るところでは、レオの一族はすでに没落している。\nそれとも何か、レオがトワイライトシティで築いた名声に脅威でも感じたか？",
  ui_story_1017_10170701_59_dialog_content = "コホン…トワイライトシティ以外に、\n報告すべきことはないのか？",
  ui_story_1017_10170701_60_dialog_content = "城主様、合同演習で私が知り得た状況をご報告させてください。",
  ui_story_1017_10170701_61_dialog_content = "申せ。",
  ui_story_1017_10170701_62_dialog_content = "合同演習で、トワイライトシティの兵士と知り合い、\nその者から――",
  ui_story_1017_10170701_63_dialog_content = "やはりトワイライトシティではないか。報告せんでよい。",
  ui_story_1017_10170701_64_dialog_content = "ですが――",
  ui_story_1017_10170701_65_dialog_content = "机の上の書簡が見えぬか？",
  ui_story_1017_10170701_66_dialog_content = "トワイライトシティ、白夜要塞、さらには影ノ街からも書簡が寄せられてきた。\n情報はもう十分だ。",
  ui_story_1017_10170701_67_dialog_content = "ではなぜ行動を起こさないのですか？",
  ui_story_1017_10170701_68_dialog_content = "トワイライトシティに長くいたせいで、\n気が立ちやすくなったか？",
  ui_story_1017_10170701_69_dialog_content = "…",
  ui_story_1017_10170701_70_dialog_content = "（口では焦っていないとおっしゃっるけれど、\nずっと指で机をたたいている…）",
  ui_story_1017_10170701_71_dialog_content = "（トワイライトシティのことは聞きたがらない…\nけれどいったい何を待っているというの？）",
  ui_story_1017_10170701_72_dialog_content = "城主様！ご報告申し上げます。\n啓光連邦から最新動向を知らせる便りがございました。",
  ui_story_1017_10170701_73_dialog_content = "申せ。",
  ui_story_1017_10170701_74_dialog_content = "啓光が新たに部隊を派遣し、その部隊はすでに防衛線を越え、\nまもなくトワイライトシティに到着するとのことです。",
  ui_story_1017_10170701_75_dialog_content = "防衛線を越えた、ですと？",
  ui_story_1017_10170701_76_dialog_content = "はい！",
  ui_story_1017_10170701_77_dialog_content = "新たに派遣された部隊とはいったい何のことです？",
  ui_story_1017_10170701_78_dialog_content = "ラス将軍が新しい大元帥となった後に組織した近衛兵団です。",
  ui_story_1017_10170701_79_dialog_content = "最新兵器と戦士を配備し、そのうち1名の兵士は、\n合同演習でレインハトに勝利した者とのことです。",
  ui_story_1017_10170701_80_dialog_content = "（アクセリアが？今は休養すべき時のはずなのに…）",
  ui_story_1017_10170701_81_dialog_content = "啓光のほかの将軍と空の末裔に関する情報は？",
  ui_story_1017_10170701_82_dialog_content = "ヒイロ将軍以外の軍団長はそれぞれ別の任務に当たっており、\nトワイライトシティには向かっていないようです。",
  ui_story_1017_10170701_83_dialog_content = "空の末裔については、これ以前に入手した情報では、\n開戦後すぐに彼の巨像がトワイライトシティに向かったとのことです。",
  ui_story_1017_10170701_84_dialog_content = "PlayerNameがトワイライトシティへ向かったの！？",
  ui_story_1017_10170701_85_dialog_content = "つまり、どういうことだ？",
  ui_story_1017_10170701_86_dialog_content = "火を見るよりも明らかです。\n合同演習の後トワイライトシティの状況は各勢力の知るところとなったのです。",
  ui_story_1017_10170701_87_dialog_content = "啓光連邦はトワイライトシティの防衛に確固たる勝算があるのでしょう。\nだからこそ強力な部隊を派遣したのです。",
  ui_story_1017_10170701_88_dialog_content = "これで今後白夜城のトワイライトシティでの地位が\nどうなるか分からなくなってきました。",
  ui_story_1017_10170701_89_dialog_content = "この肝心要の時に大元帥を交代させ、\n新たに組織した軍を送って暗鬼を鎮圧する…",
  ui_story_1017_10170701_90_dialog_content = "私からすれば、実に荒唐無稽な行為に見えますな。",
  ui_story_1017_10170701_91_dialog_content = "彼らは本当に応援に行くのか、果たして別の目的があるのか、\nソルラド、よく考えることですね。",
  ui_story_1017_10170701_92_dialog_content = "援軍を組織し、即刻トワイライトシティへ向かうよう、命を下せ。",
  ui_story_1017_10170701_93_dialog_content = "城主様、感謝いたします。\nただ恐れながら…理由をうかがってもよろしいですか？",
  ui_story_1017_10170701_94_dialog_content = "啓光軍が防衛線を越えたとあらば、\n白夜城も当然傍観しているわけにはいかぬ。",
  ui_story_1017_10170701_95_dialog_content = "協力するにしろ、奪い合うにしろ、\n兵を出さなければ、劣勢に陥るのみだ。",
  ui_story_1017_10170701_96_dialog_content = "よいか。何よりも白夜要塞の安全確保を優先とし、\n決して啓光軍の動きに関わってはならぬぞ。",
  ui_story_1017_10170701_97_dialog_content = "我が援軍のいかなる行動も余の許可の下で行うように。",
  ui_story_1017_10170701_98_dialog_content = "承知いたしました！",
  ui_story_1017_10170701_99_dialog_content = "（父上が啓光軍の動きを警戒してる…）",
  ui_story_1017_10170701_100_dialog_content = "城主様、援軍は誰を指揮官にするおつもりですか？\nできるならば、私が――",
  ui_story_1017_10170701_101_dialog_content = "お前は下がってよい。\nトワイライトシティの応援はお前の職責の及ぶところではない。",
  ui_story_1017_10170701_102_dialog_content = "ですが――",
  ui_story_1017_10170701_103_dialog_content = "皆の者、今日はここまでとしよう。",
  ui_story_1017_10170801_1_dialog_content = "あの…家族がまだ戻っていないんです。\n門を閉めるのをもう少し待ってもらえませんか？",
  ui_story_1017_10170801_2_dialog_content = "主の命令だ。城門を閉じ、\n白夜城の者以外は何人たりとも中に入ることは許されない。",
  ui_story_1017_10170801_3_dialog_content = "でも…私の子どもも白夜城の者です…\nあの子は私たちを守るために前線で戦ってるんです。",
  ui_story_1017_10170801_4_dialog_content = "主の命令だというのが分からんのか？\n城門を閉める。下がれ！",
  ui_story_1017_10170801_5_dialog_content = "偉大なる「光の神」よ、我々を見捨てないでくださいませ――",
  ui_story_1017_10170801_6_dialog_content = "黄昏の後は闇夜が訪れ、闇夜が過ぎれば、また黄昏が訪れる…",
  ui_story_1017_10170801_7_dialog_content = "前線で戦う子どもたちよ、心より無事を祈る。",
  ui_story_1017_10170801_8_dialog_content = "PlayerName、下がれ！",
  ui_story_1017_10170801_9_dialog_content = "指揮官が戦場で下がるわけにはいかないよ！",
  ui_story_1017_10170801_10_dialog_content = "これほどの規模の侵攻は私も初めて経験する。",
  ui_story_1017_10170801_11_dialog_content = "2回の挟み撃ちも暗鬼の大群に飲み込まれてしまった。\n今は強がっている時ではない。",
  ui_story_1017_10170801_12_dialog_content = "確かに暗力がどんどん強くはなってるけど…",
  ui_story_1017_10170801_13_dialog_content = "頭も不在、目的も不明、数もやたらと多い。\n状況も不明なまま、やみくもに攻めるのは禁物だ。",
  ui_story_1017_10170801_14_dialog_content = "団長、防衛線を守っていた2部隊が暗鬼に襲われ散り散りになりました。\n多くの死傷者が出ています。",
  ui_story_1017_10170801_15_dialog_content = "各部隊、防御しながら即刻100歩後退せよ！",
  ui_story_1017_10170801_16_dialog_content = "了解です！",
  ui_story_1017_10170801_17_dialog_content = "後方部隊にきゅう舎にいる年老いた馬で荷車を用意させるのだ。\nけが人を村の酒場に移す。",
  ui_story_1017_10170801_18_dialog_content = "けが人の手当は団自ら行う！",
  ui_story_1017_10170801_19_dialog_content = "はい、団長！",
  ui_story_1017_10170801_20_dialog_content = "レオ騎士団長、後退しながら状況を分析いたしましょう。\n暗鬼は何をしようとしているのだと思われますか？",
  ui_story_1017_10170801_21_dialog_content = "奴らはただ数で圧倒し、こちらの兵力を削いでいる。\n常軌を逸した行動だ、目的が読めない。",
  ui_story_1017_10170801_22_dialog_content = "PlayerName、暗鬼の行動パターンについて、\n何か手がかりはあるか？",
  ui_story_1017_10170801_23_dialog_content = "感知してみるよ。",
  ui_story_1017_10170801_24_dialog_content = "（トワイライトシティの周囲は完全に暗鬼に囲まれて…\n暗力が密集してる…）",
  ui_story_1017_10170801_25_dialog_content = "（暗鬼たちはゆっくり動きながら、\nお互いの間隔を短く保って、まるで…）",
  ui_story_1017_10170801_26_dialog_content = "（巨大な「暗力の網」を編みながら、\nトワイライトシティに押し寄せてくるみたいだ…）",
  ui_story_1017_10170801_27_dialog_content = "（「暗力の網」には…結び目がたくさんある…）",
  ui_story_1017_10170801_28_dialog_content = "（あれ、ちょっと待って…結び目の暗力の強さは均等じゃない。\n暗力が特に密集してる結び目をたどっていくと…）",
  ui_story_1017_10170801_29_dialog_content = "レオ、暗力は広い範囲に広がってるけど、\n暗鬼の行動は「中心」の指揮に従ってるみたいだ。",
  ui_story_1017_10170801_30_dialog_content = "その「中心」が何か分かるか？",
  ui_story_1017_10170801_31_dialog_content = "ごめん…僕の感知の範囲を越えてる。",
  ui_story_1017_10170801_32_dialog_content = "ですが、少なくとも暗鬼の行動に\n規則性がまったくないわけではないことは確かです。",
  ui_story_1017_10170801_33_dialog_content = "そうだな。となると、目下その「中心」を見つけることが肝心だ。",
  ui_story_1017_10170801_34_dialog_content = "ソラヴァン、「中心」を探してみてくれないかな？",
  ui_story_1017_10170801_35_dialog_content = "捜索中です…",
  ui_story_1017_10170801_36_dialog_content = "視野を拡大します…",
  ui_story_1017_10170801_37_dialog_content = "現在「中心」は見つかりません。引き続き捜索します…",
  ui_story_1017_10170801_38_dialog_content = "今のところ見つからないみたいだ…",
  ui_story_1017_10170801_39_dialog_content = "単純に距離の問題なら、「中心」は暗面の近く、\nもしくは暗面の中にあるのだろう。",
  ui_story_1017_10170801_40_dialog_content = "私が思うに、「中心」にいる敵を倒しさえすれば、\n暗鬼の行動を抑えられるはずだ。",
  ui_story_1017_10170801_41_dialog_content = "暗面の中に入るおつもりですか？",
  ui_story_1017_10170801_42_dialog_content = "ああ。このまま戦いを続けても、\nトワイライトシティに活路は開けない。",
  ui_story_1017_10170801_43_dialog_content = "団長、私も行きます。",
  ui_story_1017_10170801_44_dialog_content = "いや、お前は私の代わりに主攻部隊の指揮をとり、\n引き続き防衛線を守ってくれ。",
  ui_story_1017_10170801_45_dialog_content = "偵察隊、私に続き――",
  ui_story_1017_10170801_46_dialog_content = "PlayerName、反対方向から軍隊が近づいてきます。",
  ui_story_1017_10170801_47_dialog_content = "どこの軍隊か分かる？",
  ui_story_1017_10170801_48_dialog_content = "先頭の輸送車に旗が掲げられています。\n旗の紋章は…",
  ui_story_1017_10170801_49_dialog_content = "啓光だ！",
  ui_story_1017_10170801_50_dialog_content = "レオ、後ろから啓光の軍隊が来るよ！",
  ui_story_1017_10170801_51_dialog_content = "近衛兵団――",
  ui_story_1017_10170801_52_dialog_content = "各連隊は共同防御の形で攻撃しながら前進！",
  ui_story_1017_10170801_53_dialog_content = "「エンジン7号」は砦の破られた箇所を優先的に補完、\n暗鬼を1歩たりとも前に進めるな！！",
  ui_story_1017_10170801_54_dialog_content = "おーっ！！！",
  ui_story_1017_10170801_55_dialog_content = "フン、トワイライトシティに侵攻した暗鬼はこの程度？\n腕試しにもならないわ。",
  ui_story_1017_10170801_56_dialog_content = "こ、この迫力は…啓光の新しい大元帥でしょうか？",
  ui_story_1017_10170801_57_dialog_content = "演習では教官だった将軍だが、\n大元帥となった今は見違えるようだな。",
  ui_story_1017_10170801_58_dialog_content = "本当だね。新しい装備になって、\n前よりもさらに強くなったみたいだ！",
  ui_story_1017_10170801_59_dialog_content = "兵士たちの力も恐ろしいですね。\nあちらの兵士をご覧ください――",
  ui_story_1017_10170801_60_dialog_content = "途中すでに10匹の暗鬼を倒しているというのに、\nまだ勢いが止まりません…",
  ui_story_1017_10170801_61_dialog_content = "私はあの兵器の方が興味をそそられるな。\n兵士が中で制御している。",
  ui_story_1017_10170801_62_option_content = "（僕も制御してみたいな）",
  ui_story_1017_10170801_63_dialog_content = "安全のためにも、やらないほうがいいでしょう。",
  ui_story_1017_10170801_64_option_content = "（ソラヴァンをあんなふうに改造したいな）",
  ui_story_1017_10170801_65_dialog_content = "方向性が異なります。試さないほうがよいでしょう。",
  ui_story_1017_10170801_66_dialog_content = "ただ言ってみただけ…",
  ui_story_1017_10170801_67_dialog_content = "おや？あの兵士も来ているようだな。",
  ui_story_1017_10170801_68_dialog_content = "演習でレインハトを倒してすぐに、\nラスの部下として出陣するとはただ者ではないな。",
  ui_story_1017_10170801_69_dialog_content = "アクセリア…重傷だったはずなのに、どうしてここへ…",
  ui_story_1017_10170801_70_dialog_content = "あら、PlayerNameもいたのね。\nこれくらいで驚いてるの？",
  ui_story_1017_10170801_71_dialog_content = "…",
  ui_story_1017_10170801_72_dialog_content = "また会ったわね、騎士団長さん。",
  ui_story_1017_10170801_73_dialog_content = "久しぶりだな、教官。いや、申し訳ない。\n啓光大元帥と呼ぶべきか。",
  ui_story_1017_10170801_74_dialog_content = "自分の戦場に戻っても、のんびりとはいかないようね。",
  ui_story_1017_10170801_75_dialog_content = "啓光軍を率いてここへ来た目的は何だ？",
  ui_story_1017_10170801_76_dialog_content = "啓光連邦の大元帥として、啓光精鋭部隊を率い、\nトワイライトシティを助け、暗鬼を鎮圧するためよ。",
  ui_story_1017_10170801_77_dialog_content = "こんな簡単なこと、説明する必要ある？",
  ui_story_1017_10170801_78_dialog_content = "めったなことでは動かない啓光がトワイライトシティに援軍を送ったのでな。\n少し驚いているのだ。",
  ui_story_1017_10170801_79_dialog_content = "フフ、トワイライトシティが陥落したら、\n被害を被るのは啓光よ。手をこまねいてる理由はないでしょ？",
  ui_story_1017_10170801_80_dialog_content = "大元帥には先見の明があるようだな。\n合同演習の時のように小細工がないことを祈るばかりだ。",
  ui_story_1017_10170801_81_dialog_content = "小細工の裏の動きについては調査してるわ。\n今はトワイライトシティの盟友として、協力がうまくいくことを願うばかりね。",
  ui_story_1017_10170801_82_dialog_content = "ああ、そうだな。",
  ui_story_1017_10170801_83_dialog_content = "近衛兵団、「アイアンソーン騎士団」はすでに長時間戦い続けている！",
  ui_story_1017_10170801_84_dialog_content = "我々の力を発揮し、暗鬼どもを全て掃討せよ！",
  ui_story_1017_10170801_85_dialog_content = "おーっ！！！",
  ui_story_1017_10170801_86_dialog_content = "「アイアンソーン騎士団」――",
  ui_story_1017_10170801_87_dialog_content = "鶴翼の陣形をとり、全軍突撃！\n笑い者になりたくなければ、私と共に先陣を切れ！",
  ui_story_1017_10170801_88_dialog_content = "おーっ！！！",
  ui_story_1017_10170901_1_dialog_content = "ユリシーズったら本当にみじめね。\n私の捨てたゴミを改造したかと思えば、待ちきれず戦場に投入してきたわ。",
  ui_story_1017_10170901_2_dialog_content = "しかも前面に押し出してくるつもり？",
  ui_story_1017_10170901_3_dialog_content = "『あのゴミは強い。』",
  ui_story_1017_10170901_4_dialog_content = "当たり前よ。彼らの体内には私の「シード」が埋め込まれているの。\nあなたはとっくに気づいていいはずよ。",
  ui_story_1017_10170901_5_dialog_content = "『…』",
  ui_story_1017_10170901_6_dialog_content = "何を考えてるか分かるわよ。あの人が来るのでしょう？",
  ui_story_1017_10170901_7_dialog_content = "それほど私が待ち遠しかったのですか？\nやれやれ、これしきの攻撃に手を焼いているとは。",
  ui_story_1017_10170901_8_dialog_content = "想定外の状況よ。向こうの数が増えたわ。",
  ui_story_1017_10170901_9_dialog_content = "それこそ復讐のよい機会ではありませんか！\n喜ぶべきでしょう！",
  ui_story_1017_10170901_10_dialog_content = "復讐のことは放っておいてちょうだい。\nモノは持ってきたの？",
  ui_story_1017_10170901_11_dialog_content = "どうぞ。",
  ui_story_1017_10170901_12_dialog_content = "マッドバンドル？",
  ui_story_1017_10170901_13_dialog_content = "見た目は少々気色が悪いのですが、\n進行速度を上げるには十分です。いかがです？",
  ui_story_1017_10170901_14_dialog_content = "確か空間を飲み込み、ぬかるみを作り出せるはずです。\n光霊の苦しめ方も…実に独特、そう…とても独特ですよ。",
  ui_story_1017_10170901_15_dialog_content = "近づいてみなさい。",
  ui_story_1017_10170901_16_dialog_content = "『はっ。』",
  ui_story_1017_10170901_17_dialog_content = "『暗力が…集まっている…うう、ひもじくてたまらん！』",
  ui_story_1017_10170901_18_dialog_content = "マッドバンドルのぬかるみの中に入ると、\n暗鬼体内の「シード」はそのコアと共鳴を起こす。",
  ui_story_1017_10170901_19_dialog_content = "『力がみなぎってくる！！』",
  ui_story_1017_10170901_20_dialog_content = "そうなれば、あなたたちは光霊を食らい、成長するだけでいい。\n時機が熟せば、あとはマッドバンドルが始末してくれるわ。",
  ui_story_1017_10170901_21_dialog_content = "クドクドした説明に興味はありません。ここは任せましたよ。次に会う時には「カーペット」を回収しますからね。",
  ui_story_1017_10170901_22_dialog_content = "『食い物だ！！』",
  ui_story_1017_10170901_23_dialog_content = "さあ、行きなさい。ぬかるみがトワイライトシティの奥に届くまで、\nここにある食べ物はすべてあなたのものよ。",
  ui_story_1017_10170901_24_dialog_content = "『グオオオ！！』",
  ui_story_1017_10170901_25_dialog_content = "大変だ！前方から強大な暗力が襲ってくる！",
  ui_story_1017_10170901_26_dialog_content = "もう来るのか！？「中心」にいた敵か？",
  ui_story_1017_10170901_27_dialog_content = "分からない…でも「暗力の網」が\nどんどん近づいてくるのは確かだよ！",
  ui_story_1017_10170901_28_dialog_content = "うう…あっ…",
  ui_story_1017_10170901_29_dialog_content = "そっちの状況は？",
  ui_story_1017_10170901_30_dialog_content = "大元帥様、報告いたします！\n一部の兵士が暗力の影響を受けているようです…",
  ui_story_1017_10170901_31_dialog_content = "早急に治療すると同時に、けが人の数を把握して。",
  ui_story_1017_10170901_32_dialog_content = "了解しました！",
  ui_story_1017_10170901_33_dialog_content = "（…急に…力がこみあげてきたような…）",
  ui_story_1017_10170901_34_dialog_content = "大元帥様、大丈夫ですか？",
  ui_story_1017_10170901_35_dialog_content = "この暗力…確かに気分が悪いわね…",
  ui_story_1017_10170901_36_dialog_content = "部下を率いて下がれ。\n「アイアンソーン騎士団」第一、第二部隊、敵を追撃、第三、第四部隊は援護に回れ！",
  ui_story_1017_10170901_37_dialog_content = "待ちなさい！これしきの暗鬼、何でもないわ。",
  ui_story_1017_10170901_38_dialog_content = "PlayerName、引き続きサポートしなさい！",
  ui_story_1017_10170901_39_dialog_content = "前方より特殊形態の暗鬼が近づいてきます。",
  ui_story_1017_10170901_40_dialog_content = "「中心」の敵なの？",
  ui_story_1017_10170901_41_dialog_content = "分かりません。ただ他の暗鬼よりも強い暗力を検知しました。",
  ui_story_1017_10170901_42_dialog_content = "分かった。他に何か情報はある？",
  ui_story_1017_10170901_43_dialog_content = "引き続き探知します。結果が分かり次第、知らせます。",
  ui_story_1017_10170901_44_dialog_content = "うん、頼んだよ！",
  ui_story_1017_10170901_45_dialog_content = "強大な暗鬼がこっちに向かってくるよ！\n攻撃準備だ！",
  ui_story_1017_10170901_46_dialog_content = "フン、ようやく好敵手が現れたわね。",
  ui_story_1017_10170901_47_dialog_content = "よく見てなさい、騎士さんたち。\n近衛兵団はここで倒れたりしないわ。敵は私たちに任せなさい！",
  ui_story_1017_10170901_48_dialog_content = "了解だ。「アイアンソーン騎士団」援護しろ！",
  ui_story_1017_10170901_49_dialog_content = "おーっ！！！",
  ui_story_1017_10171001_1_dialog_content = "なんとか…倒したね！",
  ui_story_1017_10171001_2_dialog_content = "倒される前に、これほど多くの暗鬼を召喚するとは思いませんでした。\n実に手ごわい相手でしたね。",
  ui_story_1017_10171001_3_dialog_content = "うむ、ようやく攻撃に策略が見え始めたな。\nだが、これでひとまず戦場は安全だ。",
  ui_story_1017_10171001_4_dialog_content = "大元帥様、ご報告いたします！\n暗力の影響を受ける兵士が今だ増え続けています！",
  ui_story_1017_10171001_5_dialog_content = "原因は突き止めたの？",
  ui_story_1017_10171001_6_dialog_content = "いいえ。数多くの兵士が身体を制御できなくなり、<color=#FFB400>殺りくを好む</color>傾向が見え始めています。\n治療もまったく効果がありません。",
  ui_story_1017_10171001_7_dialog_content = "…",
  ui_story_1017_10171001_8_dialog_content = "（身体の制御が利かなくなり、殺りくを好む…\n今の戦いで、全員同じ感覚を味わったのかしら…）",
  ui_story_1017_10171001_9_dialog_content = "団長！東区です、少数の暗鬼がまた塹壕を荒らし始めました！",
  ui_story_1017_10171001_10_dialog_content = "どうやら、今倒したのは「中心」の敵ではなかったようだな。",
  ui_story_1017_10171001_11_dialog_content = "手がかりをつかめた者はいるか？",
  ui_story_1017_10171001_12_dialog_content = "治療の最中、今回兵士たちが影響を受けた暗力は、\n普段私たちが接しているものと異なっていることが分かりました。",
  ui_story_1017_10171001_13_dialog_content = "病院できちんとした治療を受ける必要があるでしょう。",
  ui_story_1017_10171001_14_dialog_content = "ラス大元帥様、状態がよく分からない啓光の兵士は、\n私が病院までお連れします。",
  ui_story_1017_10171001_15_dialog_content = "私も頼もうと思っていたところよ。感謝するわ！\n戦いが終わり次第、相応の報酬を払うわ。",
  ui_story_1017_10171001_16_dialog_content = "いいえ、当然のことをしたまでです。",
  ui_story_1017_10171001_17_dialog_content = "大元帥様、兵士たちの話では一部の兵士が隊を離脱し、\n同じ方向へ一斉に向かっているそうです…",
  ui_story_1017_10171001_18_dialog_content = "まるで何かの力に操られているかのようだと…",
  ui_story_1017_10171001_19_dialog_content = "「中心」の敵の影響なの？",
  ui_story_1017_10171001_20_dialog_content = "その可能性は否定できません。少し前にも暗力の動きは\n「中心」に操られているのではないかと予測していました。",
  ui_story_1017_10171001_21_dialog_content = "トワイライトシティの兵士たちも、状況は同じなの？",
  ui_story_1017_10171001_22_dialog_content = "団長、ご報告が…",
  ui_story_1017_10171001_23_dialog_content = "それは確かか？",
  ui_story_1017_10171001_24_dialog_content = "はい、団長。",
  ui_story_1017_10171001_25_dialog_content = "大元帥、異常な行動を起こしている兵士は皆あなたの部下だ。",
  ui_story_1017_10171001_26_dialog_content = "何が言いたいの？",
  ui_story_1017_10171001_27_dialog_content = "単刀直入に言おう。\nさきほどの数回の進撃中、あなたの部下の様子は異常だった。",
  ui_story_1017_10171001_28_dialog_content = "敵が強大すぎたのか――",
  ui_story_1017_10171001_29_dialog_content = "それとも大元帥の軍に内通者がいるのか？",
  ui_story_1017_10171001_30_dialog_content = "啓光が援軍を送った意図を疑っているのかしら？",
  ui_story_1017_10171001_31_dialog_content = "そうではない。ただ今回の敵は尋常ではない。\n団長として己の部下に責任を持たねばならん。",
  ui_story_1017_10171001_32_dialog_content = "今の状況から見るに、あなたの部下はいったい光霊なのか、\n暗鬼なのか分からない。",
  ui_story_1017_10171001_33_dialog_content = "言葉に気を付けなさい！\n私は一度たりとも汚い手を使ったことはないわ！",
  ui_story_1017_10171001_34_dialog_content = "レオ騎士団長、ラス大元帥様。私はここにいる全員が\nトワイライトシティのために戦っていると信じています。",
  ui_story_1017_10171001_35_dialog_content = "兵士が命令に従わない理由は分かりませんが…",
  ui_story_1017_10171001_36_dialog_content = "それがこちらの戦局分析を故意にかく乱する敵の策略だとしたら大変です。",
  ui_story_1017_10171001_37_dialog_content = "さっきの戦いでは、確かに部下は私の命令に従っていなかった。",
  ui_story_1017_10171001_38_dialog_content = "でも大元帥として、啓光の戦場における一切の行動は私が責任を持つわ。",
  ui_story_1017_10171001_39_dialog_content = "兵士の異常な行動については、必ずきちんと説明する。",
  ui_story_1017_10171001_40_dialog_content = "ただし、もし啓光の意図を疑い続けるようなら、\n啓光への敵対行為と見なすわよ。",
  ui_story_1017_10171001_41_dialog_content = "おや、敵対とはずいぶんと物騒なことを。\n私はただ忠告したまでだ。",
  ui_story_1017_10171001_42_dialog_content = "啓光の大元帥になって日も浅いのだろう？\n部下の戦闘習慣をもっと理解するよう努めてもらいたい。",
  ui_story_1017_10171001_43_dialog_content = "今度また明確な理由なく敵に身を投じる兵士が出るようなら、\nもしくは兵士を傷つけるようなことがあれば、私も容赦はしない。",
  ui_story_1017_10171001_44_dialog_content = "フン、言うことだけはずいぶん立派ね。",
  ui_story_1017_10171001_45_dialog_content = "啓光と勝負しようというなら、\n私一人であんたを打ち負かしてやるわ！",
  ui_story_1017_10171001_46_dialog_content = "大元帥様、ご報告いたします！緊急事態です――",
  ui_story_1017_10171001_47_dialog_content = "アクセリア中尉の戦闘部隊が隊ごと行方不明です。",
  ui_story_1017_10171001_48_dialog_content = "？？？",
  ui_story_1017_10171001_49_dialog_content = "担当地区は？",
  ui_story_1017_10171001_50_dialog_content = "西区です。現在西区では暗鬼がトワイライトシティに向かって、\n移動を続けています。",
  ui_story_1017_10171001_51_dialog_content = "近衛兵団全軍、西へ向かって移動、\n暗鬼をせん滅する！",
  ui_story_1017_10171001_52_dialog_content = "けが人も足と頭を失っていない限り、\nしっかりついて来なさい！",
  ui_story_1017_10171001_53_dialog_content = "異常な行動をする兵士を見つけた場合は\nすぐに報告すること！",
  ui_story_1017_10171001_54_dialog_content = "了解です！",
  ui_story_1017_10171001_55_dialog_content = "PlayerName、ついて来なさい。",
  ui_story_1017_10171001_56_dialog_content = "え、僕？",
  ui_story_1017_10171001_57_dialog_content = "しっかりついてくるのよ！",
  ui_story_1017_10171001_58_dialog_content = "…",
  ui_story_1017_10171001_59_dialog_content = "団長、我々は我々で動きますか？",
  ui_story_1017_10171001_60_dialog_content = "大元帥になったばかりで力が入っているのだろうが、\n事を不明確にしたままでは、のちのち厄介なことになる。",
  ui_story_1017_10171001_61_dialog_content = "我々は東に向かう。東区は居住区に近い。\n1匹たりとも暗鬼の侵入を許してはならん。",
  ui_story_1017_10171001_62_dialog_content = "はい、団長。",
  ui_story_1017_10171001_63_dialog_content = "レオ騎士団長、病院の仲間が到着しました。\n私はまず重傷の兵士を病院に送り届けます。",
  ui_story_1017_10171001_64_dialog_content = "病院は住民を優先して治療してくれ。\n負傷した兵士は友人の<color=#FFB400>酒場</color>で受け入れる。",
  ui_story_1017_10171001_65_dialog_content = "団長、酒場はもう…",
  ui_story_1017_10171001_66_dialog_content = "ならば駐屯地の後方支援兵で医療隊を組織し、\n白夜要塞へ行って残りの<color=#FFB400>希鉱石</color>を医療物資に交換してくるのだ。",
  ui_story_1017_10171001_67_dialog_content = "ですが団長、白夜要塞はすでに城門を閉じています。",
  ui_story_1017_10171001_68_dialog_content = "だから、希鉱石を持っていけと言ったのだ！",
  ui_story_1017_10171001_69_dialog_content = "了解しました、団長。",
  ui_story_1017_10171001_70_dialog_content = "何をするにも白夜要塞が絡んだ途端に困難を極める。",
  ui_story_1017_10171001_71_dialog_content = "私はトワイライトシティの出身ですが、白夜城の者でもあります。\n何か方法を考えましょう。",
  ui_story_1017_10171001_72_dialog_content = "白夜城の者であることを栄誉に思うなど、\n殊勝な心掛けだな。",
  ui_story_1017_10171001_73_dialog_content = "どの陣営に属するかは重要ではありません。\n私はただトワイライトシティに暮らす人々が安らかに仕事に励むことができれば満足です。",
  ui_story_1017_10171001_74_dialog_content = "遠い理想だな。",
  ui_story_1017_10171001_75_dialog_content = "啓光と白夜城の助けがなければ、トワイライトシティの命運は風前の灯だ。\n安らかな暮らしなどとは程遠い。",
  ui_story_1017_10171001_76_dialog_content = "軍にとって最も重要なことは何か分かるか？",
  ui_story_1017_10171001_77_dialog_content = "心だ。心が一つにならなければ勝利は得られない。\nだが今の啓光軍は砂のように心がバラバラだ。",
  ui_story_1017_10171001_78_dialog_content = "移動中の軍全体の様子が巨像から見える？",
  ui_story_1017_10171001_79_dialog_content = "はっきりと見えていますよ、PlayerName。",
  ui_story_1017_10171001_80_dialog_content = "はい、ラス…大元帥。",
  ui_story_1017_10171001_81_dialog_content = "呼びにくい？",
  ui_story_1017_10171001_82_dialog_content = "…",
  ui_story_1017_10171001_83_dialog_content = "どうしてそんな顔してるの？",
  ui_story_1017_10171001_84_dialog_content = "な、何でもないよ…\n大元帥と行動を共にするのに慣れてないだけで…",
  ui_story_1017_10171001_85_dialog_content = "フッ、レインハトとは親しいでしょ？",
  ui_story_1017_10171001_86_dialog_content = "私と一緒にいるとそんなに緊張するの？\nレインハトと私と何が違うのかしらね。",
  ui_story_1017_10171001_87_dialog_content = "（違うなんてもんじゃないよ…）",
  ui_story_1017_10171001_88_dialog_content = "呼び捨てでいいわよ。平等に私も呼び捨てさせてもらうわ。",
  ui_story_1017_10171001_89_dialog_content = "分かったよ、ラス…",
  ui_story_1017_10171001_90_dialog_content = "部下のことで、1つ頼みたいことがあるの。",
  ui_story_1017_10171001_91_dialog_content = "どんなこと？",
  ui_story_1017_10171001_92_dialog_content = "これからの戦いで、部下の状況がさらに悪化するかもしれないわ。",
  ui_story_1017_10171001_93_dialog_content = "今から部下たちの位置を特定してほしいの。\n敵が大挙して押し寄せる前に状況を把握したいわ。",
  ui_story_1017_10171001_94_dialog_content = "分かった。ソラヴァンも手伝うよ。",
  ui_story_1017_10171001_95_dialog_content = "異変を起した兵士を捜索しています。\n所要時間は60秒の予定です。",
  ui_story_1017_10171001_96_dialog_content = "1つ聞きたいことがあるんだ。",
  ui_story_1017_10171001_97_dialog_content = "何かしら？",
  ui_story_1017_10171001_98_dialog_content = "アクセリアがどうして君の軍に？",
  ui_story_1017_10171001_99_dialog_content = "アクセリアは確か…演習で重傷を負ったよね。\n養生してるべきなんじゃないかな？",
  ui_story_1017_10171001_100_dialog_content = "そこが啓光の軍人のすごさなのよ。",
  ui_story_1017_10171001_101_dialog_content = "毎回命の危険を冒して戦場に出ることが…？",
  ui_story_1017_10171001_102_dialog_content = "彼女ならできるとは思わない？",
  ui_story_1017_10171001_103_dialog_content = "うん、アクセリアならできると思うよ。ただ…",
  ui_story_1017_10171001_104_dialog_content = "アクセリアは僕の知ってる他の仲間たちみたいに、\n戦いを恐れたり、戦いを欲したりしない。",
  ui_story_1017_10171001_105_dialog_content = "これまでアクセリアと一緒にいても、\n感情ってものをほとんど感じたことがない…",
  ui_story_1017_10171001_106_dialog_content = "感情は戦いを勝利に導く武器にはならないのよ、空の末裔くん。",
  ui_story_1017_10171001_107_dialog_content = "いや、僕が言いたいのは――",
  ui_story_1017_10171001_108_dialog_content = "何を言いたいのかは分かっているわ。",
  ui_story_1017_10171001_109_dialog_content = "大元帥になるまで、私も同じようなことを考えていたわ。",
  ui_story_1017_10171001_110_dialog_content = "でも、分かったのよ。",
  ui_story_1017_10171001_111_dialog_content = "何をしても勝てない相手に勝つためには、本来の自分を捨てて、\n相手の視点から物事を考えるべきだってね。",
  ui_story_1017_10171001_112_dialog_content = "本来の自分を捨てる…でも僕の目に映るラスは、\n今までと同じように先頭を切って戦うラスだよ。",
  ui_story_1017_10171001_113_dialog_content = "フフ、強力な感性を持つ空の末裔のくせに、\n頭の中は大して複雑じゃないのね。",
  ui_story_1017_10171001_114_dialog_content = "本当にうらやましいわ…",
  ui_story_1017_10171001_115_dialog_content = "それって褒められてるのかな…",
  ui_story_1017_10171001_116_dialog_content = "そうよ。ちゃんと前見て歩きなさい。\n穴に落ちたりしないでよ。",
  ui_story_1017_10171001_117_dialog_content = "20ｍ先の障害物の下に異変を起した兵士が1名います。",
  ui_story_1017_10171001_118_dialog_content = "ラス、この先に異変を起した兵士がいるよ！",
  ui_story_1017_10171001_119_dialog_content = "急ぎましょ。",
  ui_story_1017_10171001_120_dialog_content = "…",
  ui_story_1017_10171001_121_dialog_content = "気分はどう？",
  ui_story_1017_10171001_122_dialog_content = "…",
  ui_story_1017_10171001_123_dialog_content = "まだ意識があるよ。でも、君の声は聞こえてないみたいだ。",
  ui_story_1017_10171001_124_dialog_content = "感知してみるね…何か手がかりがつかめるかもしれない。",
  ui_story_1017_10171001_125_dialog_content = "ええ、お願い。",
  ui_story_1017_10171001_126_option_content = "感知――開始――",
  ui_story_1017_10171001_127_dialog_content = "（ここは…ぬかるみ？）",
  ui_story_1017_10171001_128_dialog_content = "（巨大なカーペットみたいに大地を覆ってる…）",
  ui_story_1017_10171001_129_dialog_content = "（周りの破壊された建物…見覚えがある…）",
  ui_story_1017_10171001_130_dialog_content = "（たぶん…トワイライトシティだよね…）",
  ui_story_1017_10171001_131_dialog_content = "（でも、このぬかるみはいったいどこから来たんだ…？\n足下にどんどん集まってくる…）",
  ui_story_1017_10171001_132_dialog_content = "（決まった方向に流れているわけじゃなさそうだけど…）",
  ui_story_1017_10171001_133_dialog_content = "うぐっ…",
  ui_story_1017_10171001_134_dialog_content = "どうしたの？気分が悪いの？",
  ui_story_1017_10171001_135_dialog_content = "暗力にやられて、頭が痛い…\nでも大丈夫だよ…",
  ui_story_1017_10171001_136_dialog_content = "この人の意識の中で見たのはぬかるみに覆われたトワイライトシティだった。\nしかも、ぬかるみが果てしなく広がって…",
  ui_story_1017_10171001_137_dialog_content = "泥水が足下に絶え間なく集まってきて、\n立っていられなくなりそうだったよ。",
  ui_story_1017_10171001_138_dialog_content = "ぬかるみ…暗力…要するに、兵士の意識の中のぬかるみは、\n現実世界の暗力ってことね…",
  ui_story_1017_10171001_139_dialog_content = "それが兵士たちの異変の原因なの…？",
  ui_story_1017_10171001_140_dialog_content = "ぬかるみの広がる方向が分かれば…\n「中心」の敵の居場所も分かるかもしれないわね…",
  ui_story_1017_10171001_141_dialog_content = "邪魔よ！",
  ui_story_1017_10171001_142_dialog_content = "ちょっと待って…どういうことなの！？",
  ui_story_1017_10171001_143_dialog_content = "この人って…君の部下？",
  ui_story_1017_10171001_144_dialog_content = "当然でしょ？殺してしまうところだったわ！",
  ui_story_1017_10171001_145_dialog_content = "暗力の影響が深刻みたいだね。\n完全に理性を失ってる…",
  ui_story_1017_10171001_146_dialog_content = "この人の状況も感知してみるよ。",
  ui_story_1017_10171001_147_dialog_content = "無理はしなくていいわ。\n危険を感じたらすぐに感知を中止するのよ。",
  ui_story_1017_10171001_148_option_content = "感知――開始――",
  ui_story_1017_10171001_149_dialog_content = "（さっきの人の時と同じ情景だ…でも、泥の流れがすごく速い…）",
  ui_story_1017_10171001_150_dialog_content = "（しかも…泥は同じ方向から流れて来てる…）",
  ui_story_1017_10171001_151_dialog_content = "（あっちは…極夜かな？）",
  ui_story_1017_10171001_152_dialog_content = "（どんよりとした空がぬかるみと一体化してるみたいだ）",
  ui_story_1017_10171001_153_dialog_content = "（間違いない…あっちに「中心」がある…）",
  ui_story_1017_10171001_154_dialog_content = "（まずい――）",
  ui_story_1017_10171001_155_dialog_content = "お前は…暗鬼だな！",
  ui_story_1017_10171001_156_dialog_content = "下がって！",
  ui_story_1017_10171001_157_dialog_content = "…ラス？この人…",
  ui_story_1017_10171001_158_dialog_content = "気を失っただけだから、心配いらないわ。",
  ui_story_1017_10171001_159_dialog_content = "ただ、もう感知は続けないほうがいいわ。\n私でさえこの部下の体内の暗力を感じられるほどよ。",
  ui_story_1017_10171001_160_dialog_content = "あっちの空を見てみなさい。どんどん暗くなっていく…",
  ui_story_1017_10171001_161_dialog_content = "…あっちだよ！君の部下の意識の中にあった泥は、\n極夜の方向から流れてきた。しかもどんどん速くなってる。",
  ui_story_1017_10171001_162_dialog_content = "あそこが「中心」だ！",
  ui_story_1017_10171001_163_dialog_content = "つまり、敵の位置が分かったということね？",
  ui_story_1017_10171001_164_dialog_content = "おそらく間違いないよ。それに暗力に長く触れてたせいか…\n周りがなんだかぼやけてるような…",
  ui_story_1017_10171001_165_dialog_content = "そうでしょうね。極夜方面の空がますます暗くなっているわ。",
  ui_story_1017_10171001_166_dialog_content = "どうやら暗力は兵士に影響を及ぼすだけじゃなく、\n環境まで変えてしまうようね。辺りに腐敗臭が漂い始めたわ。",
  ui_story_1017_10171001_167_dialog_content = "<color=#e8d9bb>ポチャン――ポチャン――</color>",
  ui_story_1017_10171001_168_dialog_content = "今、何か音がしなかった…？",
  ui_story_1017_10171001_169_dialog_content = "この音は…水が流れる音…",
  ui_story_1017_10171001_170_dialog_content = "水が流れる音…まさかトワイライトシティに\n本当に泥水が流れていってるわけじゃないよね！？",
  ui_story_1017_10171001_171_dialog_content = "しかも、極夜の方から！",
  ui_story_1017_10171001_172_dialog_content = "…「中心」の敵が近づいてきているようね…",
  ui_story_1017_10171001_173_dialog_content = "<color=#e8d9bb>ポチャン――ポチャン――</color>",
  ui_story_1017_10171001_174_dialog_content = "PlayerName、西側に暗鬼の大群が現れました。\nおよそ5秒後にあなたの感知範囲内に入ります。",
  ui_story_1017_10171001_175_dialog_content = "そんなに早く！？じゃあ…",
  ui_story_1017_10171001_176_option_content = "感知――開始――",
  ui_story_1017_10171001_177_dialog_content = "（辺り一帯真っ黒だ…こ、これは…本物のぬかるみだ！）",
  ui_story_1017_10171001_178_dialog_content = "ラス、君の部下の意識の中と全く同じ情景が見えた！\n暗鬼が泥水と一緒になって僕たちのいる方向へ向かってくるよ！",
  ui_story_1017_10171001_179_dialog_content = "え！？",
  ui_story_1017_10171001_180_dialog_content = "現状を騎士団に共有して、住民を即避難させるのよ！",
  ui_story_1017_10171001_181_dialog_content = "了解しました！",
  ui_story_1017_10171001_182_dialog_content = "偵察部隊は私と一緒に状況を把握しに来なさい。\n「エンジン7号」は後列で援護を！",
  ui_story_1017_10171001_183_dialog_content = "誰一人として私の命令なしに勝手な行動をしないように。\n身体に異変を感じたら、すぐに離脱しなさい！",
  ui_story_1017_10171001_184_dialog_content = "大元帥様！東の連隊の兵士が次々と狂暴化しています！",
  ui_story_1017_10171001_185_dialog_content = "東だって？僕が感知したのは西側だけど…",
  ui_story_1017_10171001_186_dialog_content = "どいて！",
  ui_story_1017_10171001_187_dialog_content = "こっちまで…どういうことだろう？",
  ui_story_1017_10171001_188_dialog_content = "フン！要するに囲まれたということね。",
  ui_story_1017_10171001_189_dialog_content = "PlayerName、しっかりついて来なさい！",
  ui_story_1017_10171101_1_dialog_content = "<color=#e8d9bb>少し前、啓光の実験棟では…</color>",
  ui_story_1017_10171101_2_dialog_content = "何をしているのですか？",
  ui_story_1017_10171101_3_dialog_content = "ええと、パトロールを…その…\n今日は私がこのエリアの担当なので…",
  ui_story_1017_10171101_4_dialog_content = "ここはユリシーズ教授の実験室です。\n普段からパトロールは行っていないはずですが。",
  ui_story_1017_10171101_5_dialog_content = "ええと、それは…その…",
  ui_story_1017_10171101_6_dialog_content = "誰に言われたのですか？",
  ui_story_1017_10171101_7_dialog_content = "ええと、私は…",
  ui_story_1017_10171101_8_dialog_content = "す、すみません、インゲル長官！\nウソつくべきじゃありませんでした。ただ私は…",
  ui_story_1017_10171101_9_dialog_content = "お兄ちゃんが啓光有史以来最も偉大な<color=#FFB400>実験</color>に参加できたのが、\nうらやましくって、それで…",
  ui_story_1017_10171101_10_dialog_content = "実験は成功するまで厳重に機密を保持しなければなりません。\n兵士の家族にも知る権利はありません。",
  ui_story_1017_10171101_11_dialog_content = "私、お兄ちゃんとはすごく仲が良くて、お兄ちゃんの事は何でも知ってるんです。\n信じてください、本当なんです。",
  ui_story_1017_10171101_12_dialog_content = "…",
  ui_story_1017_10171101_13_dialog_content = "お兄ちゃんが実験に参加して、ママも私も喜んでたんです！",
  ui_story_1017_10171101_14_dialog_content = "でも私は経験が足りなくて、選ばれませんでした…",
  ui_story_1017_10171101_15_dialog_content = "残念に思っているのですか？",
  ui_story_1017_10171101_16_dialog_content = "はい…",
  ui_story_1017_10171101_17_dialog_content = "これからもチャンスはあります…",
  ui_story_1017_10171101_18_dialog_content = "本当ですか？今回は選ばれなくても、\nこの先まだ啓光を照らす「明星」になれるチャンスがあるんですか？",
  ui_story_1017_10171101_19_dialog_content = "はい…",
  ui_story_1017_10171101_20_dialog_content = "ありがとうございます、インゲル長官！\n今すぐここから立ち去ります。",
  ui_story_1017_10171101_21_dialog_content = "そうしてください…今頃彼らは暗鬼と戦っているでしょう…",
  ui_story_1017_10171101_22_dialog_content = "はい。お兄ちゃんはすごく強いんです…\n暗鬼なんてお兄ちゃんの相手じゃありません！",
  ui_story_1017_10171101_23_dialog_content = "…",
  ui_story_1017_10171101_24_dialog_content = "あ、すみません。しゃべりすぎました。失礼します！",
  ui_story_1017_10171101_25_dialog_content = "啓光の未来を照らす「明星」ですか…",
  ui_story_1017_10171101_26_dialog_content = "…",
  ui_story_1017_10171101_27_dialog_content = "<size=30>教授…</size>",
  ui_story_1017_10171101_28_dialog_content = "…",
  ui_story_1017_10171101_29_dialog_content = "ユリシーズ教授？",
  ui_story_1017_10171101_30_dialog_content = "おお、来たか。調査状況はどうかな？",
  ui_story_1017_10171101_31_dialog_content = "その件でうかがったのではありません…\n別の要件がありまして。",
  ui_story_1017_10171101_32_dialog_content = "何かな？",
  ui_story_1017_10171101_33_dialog_content = "教授、アクセリアはこの間の演習でひどい重傷を負いました。",
  ui_story_1017_10171101_34_dialog_content = "相手はレインハトだったからな。\n現時点でアクセリアにとって最も手ごわい相手だった。",
  ui_story_1017_10171101_35_dialog_content = "…",
  ui_story_1017_10171101_36_dialog_content = "何か言いたいことがあるようだね？",
  ui_story_1017_10171101_37_dialog_content = "教授、アクセリアは今まで何度も重傷を負ってきました。\nそれでも今だに啓光のために戦っています。",
  ui_story_1017_10171101_38_dialog_content = "心配なのです…「啓明の星計画2.0」の後、アクセリアが…",
  ui_story_1017_10171101_39_dialog_content = "フッ、そのことなら心配には及ばない。",
  ui_story_1017_10171101_40_dialog_content = "これは2つの実験データの対比結果だ。\n見てみなさい。",
  ui_story_1017_10171101_41_dialog_content = "「啓明の星計画2.0」によって、兵士の身体機能は元の10倍に上がっている。",
  ui_story_1017_10171101_42_dialog_content = "今後さらに20倍、50倍と伸びていくだろう…",
  ui_story_1017_10171101_43_dialog_content = "アクセリアの実験結果は良好だ。\n損傷する確率も大幅に下がっている。",
  ui_story_1017_10171101_44_dialog_content = "今のアクセリアは絶頂期にあると言っていい。",
  ui_story_1017_10171101_45_dialog_content = "トワイライトシティに向かった他の兵士も皆同じだ。",
  ui_story_1017_10171101_46_dialog_content = "教授…そうだとしてもやはり、回復したばかりのアクセリアを戦場に送り出すのは…\nあまりにも…残酷ではないでしょうか…？",
  ui_story_1017_10171101_47_dialog_content = "その他の…自分は啓光の未来を照らす「明星」だと\n信じきっている兵士たちにとってもです。",
  ui_story_1017_10171101_48_dialog_content = "そうだ、現実とは残酷なのだよ。\nだが、それが啓光の軍人の責務だ。",
  ui_story_1017_10171101_49_dialog_content = "本当に…そうなのでしょうか？",
  ui_story_1017_10171101_50_dialog_content = "自分たちの力がこんな方法で得られたものだと知っても、\nそう言えるのでしょうか？",
  ui_story_1017_10171101_51_dialog_content = "極限に達した後、急激に力を失うと知れば、\n大きな衝撃を受けるでしょう。",
  ui_story_1017_10171101_52_dialog_content = "インゲル、お前の質問は情報官の職務にふさわしくない。",
  ui_story_1017_10171101_53_dialog_content = "他に用がないのなら、実験を続けさせてもらう。",
  ui_story_1017_10171101_54_dialog_content = "しかし、教授――",
  ui_story_1017_10171101_55_dialog_content = "自分の考えを話す前に、\nまずは目的が何かきちんと考えることだ。",
  ui_story_1017_10171101_56_dialog_content = "分からないようなら、お前も今の仕事をやめて、\n実験を頻繁に見に来るといい。",
  ui_story_1017_10171101_57_dialog_content = "選びに選び抜かれた実験台がここにやってくる目的は、\nただ一つ――",
  ui_story_1017_10171101_58_dialog_content = "身体の限界を越えて、暗鬼に勝ち、\n啓光と光霊を守る、それだけだ。",
  ui_story_1017_10171101_59_dialog_content = "この実験室では毎日のように光霊が犠牲になる。\nだが暗鬼に襲われ、全員が命を落とすよりはるかにマシだ。",
  ui_story_1017_10171101_60_dialog_content = "私の目的は常に実験を続け、兵器を磨き上げることだ。\nよいデータがなければ、光霊の未来はない。",
  ui_story_1017_10171101_61_dialog_content = "実験も兵器もデータも…\n教授のなさることのすべてに敬意を持っています…",
  ui_story_1017_10171101_62_dialog_content = "ですが、兵士を犠牲にすることには賛同できません。\nしかも実験に参加した結果どうなるかも知らせないまま…",
  ui_story_1017_10171101_63_dialog_content = "フッ、全員が知らなかったわけではない。",
  ui_story_1017_10171101_64_dialog_content = "目的を果たすために、あやつは犠牲になることもいとわなかった。\nお前はどうだ？",
  ui_story_1017_10171101_65_dialog_content = "啓光の今があるのは…実験の成果のおかげだけではありません…",
  ui_story_1017_10171101_66_dialog_content = "ああ――",
  ui_story_1017_10171101_67_dialog_content = "こ、この音は…",
  ui_story_1017_10171101_68_dialog_content = "実験が始まったのだ。2つの実験の違いをとくと見るがいい。",
  ui_story_1017_10171101_69_dialog_content = "（無理です…この音は…）",
  ui_story_1017_10171101_70_dialog_content = "同じ身体機能の強化でも、結果はまったく異なる。",
  ui_story_1017_10171101_71_dialog_content = "左の実験台は新しい「シード」を埋め込んだ後、\n瞬発力が高まり、かつより長い間持続できるようになった。",
  ui_story_1017_10171101_72_dialog_content = "右の実験台はほぼ暗鬼に食いつくされた。",
  ui_story_1017_10171101_73_dialog_content = "これでお前も分かっただろう？\nなぜ一切の代償をいとわずレインハトを排除しようとしたか。",
  ui_story_1017_10171101_74_dialog_content = "左の実験台はまさか…",
  ui_story_1017_10171101_75_dialog_content = "歴史や真相に対してお前がどんな考えを持っていようと、\n世界とはこういうものなのだよ。",
  ui_story_1017_10171101_76_dialog_content = "我々はこうして前に進むしかないのだ。",
  ui_story_1017_10171101_77_dialog_content = "暗潮がうごめいている今、\n我々はこうして歩みを加速せねばならんのだ。",
  ui_story_1017_10171101_X78_dialog_content = "（頭が…痛い…）",
  ui_story_1017_10171101_78_dialog_content = "教授、左側の実験台が右の部屋の暗力に\n強い反応を示しています！",
  ui_story_1017_10171101_79_dialog_content = "教授、左側の実験台が右の部屋の暗力に\n強い反応を示しています！",
  ui_story_1017_10171101_80_dialog_content = "ええ、その通りです。\n「シード」と「シード」は反応し合うのですよ。",
  ui_story_1017_10171101_81_dialog_content = "さあ、この後、彼は何をするでしょうか…",
  ui_story_1017_10171101_X82_dialog_content = "…",
  ui_story_1017_10171101_82_dialog_content = "教授、ガラスを破って、右の部屋に行こうとしています！",
  ui_story_1017_10171101_83_dialog_content = "教授、ガラスを破って、右の部屋に行こうとしています！",
  ui_story_1017_10171101_84_dialog_content = "うむ…ドアを開けようとするのではなく、\nガラスを突き破ろうとしますか。",
  ui_story_1017_10171101_85_dialog_content = "よろしい。今回強化されたのは脳ではないようですね。\n第1期「シード」の欠点を補えました。",
  ui_story_1017_10171101_86_dialog_content = "こんなやり方…暗鬼を生み出すのと何の違いがあるのですか…？",
  ui_story_1017_10171101_87_dialog_content = "暗鬼に勝つには、尋常な方法では無理なのだよ。",
  ui_story_1017_10171101_88_dialog_content = "だが、戦場の外では、彼もお前と同じ光霊の同胞だ。",
  ui_story_1017_10171101_89_dialog_content = "いいえ、啓光は暗鬼と同胞になどなりません…\nすぐに実験を中止してください。",
  ui_story_1017_10171101_90_dialog_content = "…",
  ui_story_1017_10171101_91_dialog_content = "教授、やりました。暗鬼を飲み込み始めました！",
  ui_story_1017_10171101_92_dialog_content = "ユリシーズ教授、どうか…実験を止めてください！",
  ui_story_1017_10171101_93_dialog_content = "実験は始まったばかりだ。",
  ui_story_1017_10171101_94_dialog_content = "啓光の兵士が暗鬼を食らっているのですよ！\n重大な実験手順違反です…すぐにやめてください！",
  ui_story_1017_10171101_95_dialog_content = "実験手順の説明は確か私が書いたものだったと思うが。",
  ui_story_1017_10171101_96_dialog_content = "検証と革新はあらゆる実験の目的だ。",
  ui_story_1017_10171101_97_dialog_content = "教授！実験台がこちらのガラスをたたいています！",
  ui_story_1017_10171101_98_dialog_content = "（あの殺意に満ちた眼差しは…私に向いているのですか？）",
  ui_story_1017_10171101_99_dialog_content = "どうか…実験を止めてください…",
  ui_story_1017_10171101_100_dialog_content = "教授、インゲル中佐の様子がおかしいようです！",
  ui_story_1017_10171101_101_dialog_content = "インゲル、どうかしたか？",
  ui_story_1017_10171101_102_dialog_content = "頭が…ひどく…痛むのです…",
  ui_story_1017_10171101_103_dialog_content = "戻って休むといい。",
  ui_story_1017_10171101_104_dialog_content = "記録してください。「シード」間の反応の仕組みと距離に関しては、\nさらなる検証と確認が必要だと。",
  ui_story_1017_10171101_105_dialog_content = "教授、ガラスが――",
  ui_story_1017_10171101_106_dialog_content = "護衛隊を呼んでください！",
  ui_story_1017_10171101_107_dialog_content = "大変です！教授、逃げてください――！",
  ui_story_1017_10171101_108_dialog_content = "…",
  ui_story_1017_10171201_1_dialog_content = "これ以上は進めないわ！ぬかるみの蔓延速度が速すぎる！",
  ui_story_1017_10171201_2_dialog_content = "全員散開、迅速に後退せよ！",
  ui_story_1017_10171201_3_dialog_content = "でもラスは…まだ進む気なの？",
  ui_story_1017_10171201_4_dialog_content = "この中には部下がいるのよ。\n何があろうと、見捨てるわけにはいかないわ。",
  ui_story_1017_10171201_5_dialog_content = "でも、今はトワイライトシティの半分がぬかるみに覆われて…",
  ui_story_1017_10171201_6_dialog_content = "だからこそ町全体が覆いつくされてしまう前に、\n「中心」の敵を倒さなければいけないのよ。",
  ui_story_1017_10171201_7_dialog_content = "…今の攻撃から考えると、\n「中心」の敵の移動経路はめちゃくちゃだ。",
  ui_story_1017_10171201_8_dialog_content = "フン、確かに厄介ね。暗鬼の群れに私たちを包囲させながら、\n自分はぬかるみに隠れて、あちこちから襲ってくる。",
  ui_story_1017_10171201_9_dialog_content = "ヤツを見つけるには、前進するしかないわ。",
  ui_story_1017_10171201_10_dialog_content = "ただこのままじゃ、さらに大勢の兵士が犠牲になる…",
  ui_story_1017_10171201_11_dialog_content = "彼らの犠牲は無駄にはならない。\nPlayerName、戦士を悼む必要はないわ。",
  ui_story_1017_10171201_12_dialog_content = "僕はただ…",
  ui_story_1017_10171201_13_dialog_content = "必要ないわ。全員覚悟して、ここへ来ているの。",
  ui_story_1017_10171201_14_dialog_content = "実はずっと聞きたいことがあったんだ。\n君の部隊の兵士たちは…どうして戦場に送られてきたの？",
  ui_story_1017_10171201_15_dialog_content = "…何が言いたいの？",
  ui_story_1017_10171201_16_dialog_content = "ただの推測だけど…",
  ui_story_1017_10171201_17_dialog_content = "暗力にこんな強い反応を示すってことは、\n兵士たちの身体の中には暗鬼と同じものが入ってるんだよね。",
  ui_story_1017_10171201_18_dialog_content = "さっき君の部下を感知した時のあの感覚は…",
  ui_story_1017_10171201_19_dialog_content = "僕が「シード」を埋め込まれた時に感じたのと同じだった…",
  ui_story_1017_10171201_20_dialog_content = "そうでもなければ、兵士たちが暗鬼側に投じて、\nしかも「中心」の指揮に従う理由を説明できない…",
  ui_story_1017_10171201_21_dialog_content = "トワイライトシティの兵士にこの現象は起こってないし…",
  ui_story_1017_10171201_22_dialog_content = "じゃあ、私は？",
  ui_story_1017_10171201_23_dialog_content = "うう…",
  ui_story_1017_10171201_24_dialog_content = "フッ、実は兵士が異変を起した時、\nトワイライトシティに本当は何をしに来たのかはっきり分かったの。",
  ui_story_1017_10171201_25_dialog_content = "トワイライトシティの応援じゃないの？",
  ui_story_1017_10171201_26_dialog_content = "今こそがその応援が必要な時よ。でも、援軍なんている？",
  ui_story_1017_10171201_27_dialog_content = "…",
  ui_story_1017_10171201_28_dialog_content = "救援要請に返答なし、通信も反応なし…\nこんな状況がずっと続いているわ。",
  ui_story_1017_10171201_29_dialog_content = "暗力の影響で信号が乱れてるのかも？",
  ui_story_1017_10171201_30_dialog_content = "あんたは啓光を知らないのよ。\n啓光はいつでも準備万端で戦うわ、別の意図がない限りね。",
  ui_story_1017_10171201_31_dialog_content = "今頼れるのは自分たちだけよ。",
  ui_story_1017_10171201_32_dialog_content = "ただ…私の大元帥の地位も結局はレインハトと\n同じ結果になるのだと思うと…",
  ui_story_1017_10171201_33_dialog_content = "本当に悔しいわ！",
  ui_story_1017_10171201_34_dialog_content = "ラス、僕も一緒に戦うよ…",
  ui_story_1017_10171201_35_dialog_content = "いいのよ。今は感傷的になっている場合じゃないわ。\nソラヴァンから何か見えた？",
  ui_story_1017_10171201_36_dialog_content = "前方300mの所で、巨大な暗力の塊がぬかるみの中を移動しています。",
  ui_story_1017_10171201_37_dialog_content = "「中心」の敵？それとも…",
  ui_story_1017_10171201_38_dialog_content = "暗力が密集し、周囲に広がっていることから、\n上級暗鬼と考えられます。",
  ui_story_1017_10171201_39_dialog_content = "こっちへ向かってきてるの？",
  ui_story_1017_10171201_40_dialog_content = "位置が定まらないため、移動方向と到達時間を判断できません。",
  ui_story_1017_10171201_41_dialog_content = "指揮をしている者はいる？",
  ui_story_1017_10171201_42_dialog_content = "捜索を続けます…",
  ui_story_1017_10171201_43_dialog_content = "ありがとう、ソラヴァン。",
  ui_story_1017_10171201_44_dialog_content = "あれ？いない！？",
  ui_story_1017_10171201_45_dialog_content = "どうして急に暗鬼が増えてるの！？",
  ui_story_1017_10171201_46_dialog_content = "どうだったの？PlayerName！",
  ui_story_1017_10171201_47_dialog_content = "（待って…この感覚は…）",
  ui_story_1017_10171201_48_dialog_content = "この先に上級暗鬼がいて、ぬかるみの中を移動してる！",
  ui_story_1017_10171201_49_dialog_content = "フン、ほらね。こっちが攻撃を仕掛けなくても、\n私たちが手を出すように仕向けてくるのよ！",
  ui_story_1017_10171201_50_dialog_content = "だったらいっそのこと、正々堂々戦おうじゃないの！",
  ui_story_1017_10171201_51_dialog_content = "ぬかるみの中にはおそらく無数の暗鬼が潜伏してるわ。\n攻撃準備よ！",
  ui_story_1017_10171201_52_dialog_content = "ラス、待って。ぬかるみの中は危険だよ、入っちゃダメだ！",
  ui_story_1017_10171201_53_dialog_content = "違うわ！中に入らなきゃいけないのよ！\nぬかるみに飲まれようと、必ず倒してやる！",
  ui_story_1017_10171201_54_dialog_content = "各連隊はただちに他の暗鬼を両側に誘導！",
  ui_story_1017_10171201_55_dialog_content = "「エンジン7号」は前方の暗鬼を倒して、\n私の前方に道を開けなさい！",
  ui_story_1017_10171201_56_dialog_content = "了解です！",
  ui_story_1017_10171201_57_dialog_content = "フン！ひとりよがりの大将さん。\n後ろに隠れているなんて情けないわね…",
  ui_story_1017_10171201_58_dialog_content = "大元帥様！西側に暗鬼が出現しました！",
  ui_story_1017_10171201_59_dialog_content = "大元帥様、今度は東です！",
  ui_story_1017_10171201_60_dialog_content = "左右から仕掛けた後は…",
  ui_story_1017_10171201_61_dialog_content = "ラス、足元に注意して！",
  ui_story_1017_10171201_62_dialog_content = "やはりそう来たわね。あんたの考え方は――",
  ui_story_1017_10171201_63_dialog_content = "愚か極まりないわ！",
  ui_story_1017_10171201_64_dialog_content = "大元帥様！ご、ご無事ですか！？",
  ui_story_1017_10171201_65_dialog_content = "これくらい…何でもないに…決まってるでしょ…",
  ui_story_1017_10171201_66_dialog_content = "顔色が悪いよ！急いで僕のそばへ！",
  ui_story_1017_10171201_67_dialog_content = "いいえ、攻撃は当たったわ…",
  ui_story_1017_10171201_68_dialog_content = "ものすごく速い。ぬかるみから出てきた途端、\nまたすぐに隠れちゃう…",
  ui_story_1017_10171201_69_dialog_content = "ダメージは与えられた？",
  ui_story_1017_10171201_70_dialog_content = "そうは簡単に行かないわ。アイツ、どうやら…私を…",
  ui_story_1017_10171201_71_dialog_content = "ラス、震えてるよ！",
  ui_story_1017_10171201_72_dialog_content = "そう、アイツだったのね…私を…",
  ui_story_1017_10171201_73_dialog_content = "大元帥様！「エンジン7号」が来ました。\n「エンジン7号」と共にぬかるみを抜けましょう！",
  ui_story_1017_10171201_74_dialog_content = "誰も近づかないで！",
  ui_story_1017_10171201_75_dialog_content = "このぬかるみは…アイツの領域よ。",
  ui_story_1017_10171201_76_dialog_content = "中に入らなければ…アイツは…",
  ui_story_1017_10171201_77_dialog_content = "でも、君はもう中に入ってるよ！",
  ui_story_1017_10171201_78_dialog_content = "（正気を保つのよ！正気を保って！）",
  ui_story_1017_10171201_79_dialog_content = "急いでそこから離れて、ラス！",
  ui_story_1017_10171201_80_dialog_content = "アイツが向かってくる…私は…引けない。",
  ui_story_1017_10171201_81_dialog_content = "君がやられちゃったら、トワイライトシティは終わりなんだよ！",
  ui_story_1017_10171201_82_dialog_content = "私はやられたりしない…今の私は…",
  ui_story_1017_10171201_83_dialog_content = "無尽蔵の力が…みなぎっているのよ…",
  ui_story_1017_10171201_84_dialog_content = "必ず、アイツを倒す！",
  ui_story_1017_10171201_85_dialog_content = "だったら僕が指揮するよ！",
  ui_story_1017_10171201_86_dialog_content = "下がりなさい！",
  ui_story_1017_10171201_87_dialog_content = "10時の方向は暗力が比較的薄くなってる。\nそこから相手の暗鬼の後ろに回り込める！",
  ui_story_1017_10171201_88_dialog_content = "暗鬼があんたの方へ向かったわ、下がりなさい！",
  ui_story_1017_10171201_89_dialog_content = "後方5歩の距離に暗力が弱まってる箇所がある。\n引き続き…",
  ui_story_1017_10171201_90_dialog_content = "（うっ…身体が急に…動かない…）",
  ui_story_1017_10171201_91_dialog_content = "PlayerName！",
  ui_story_1017_10171201_92_dialog_content = "（足よ、動け…！暗鬼が…たくさん押し寄せてくる…）",
  ui_story_1017_10171201_93_dialog_content = "PlayerName！？",
  ui_story_1017_10171201_94_dialog_content = "（うう…まったく動けない…）",
  ui_story_1017_10171201_95_dialog_content = "（直接ラスの意識を感知して指揮するしかない…）",
  ui_story_1017_10171301_1_dialog_content = "また1匹来たわ！貫け、雷槍よ！",
  ui_story_1017_10171301_2_dialog_content = "（戦闘が長くなればなるほど、\n身体の制御が利かなくなってくるわ…）",
  ui_story_1017_10171301_3_dialog_content = "（最初の混乱が今は殺りくの快感に変わっている…）",
  ui_story_1017_10171301_4_dialog_content = "（このままじゃ…まさか本当に兵士たちのように…）",
  ui_story_1017_10171301_5_dialog_content = "（いいえ！）",
  ui_story_1017_10171301_6_dialog_content = "（やられるわけにはいかない！まだ始まったばかりじゃない！）",
  ui_story_1017_10171301_7_dialog_content = "ちょっと、気を付けなさい！",
  ui_story_1017_10171301_8_dialog_content = "わああ――！",
  ui_story_1017_10171301_9_dialog_content = "目は覚めた？",
  ui_story_1017_10171301_10_dialog_content = "投げ飛ばされたら、誰だって目が覚めるよ！",
  ui_story_1017_10171301_11_dialog_content = "何ですって？",
  ui_story_1017_10171301_12_dialog_content = "（待って、今話してたのはPlayerNameよ…）",
  ui_story_1017_10171301_13_dialog_content = "（それなのになぜ…暗鬼だなんて思うの…？）",
  ui_story_1017_10171301_14_dialog_content = "大丈夫？",
  ui_story_1017_10171301_15_dialog_content = "何でもないわ…",
  ui_story_1017_10171301_16_dialog_content = "（PlayerNameよ、目の前にいるのはPlayerNameよ！）",
  ui_story_1017_10171301_17_dialog_content = "ラス！",
  ui_story_1017_10171301_18_dialog_content = "ええ…大丈夫よ。",
  ui_story_1017_10171301_19_dialog_content = "ぬかるみから離れるように言ったでしょ！",
  ui_story_1017_10171301_20_dialog_content = "でもさっき君は一切を顧みることなくぬかるみの中に入っていったんだ。\nあの兵士たちと同じように…",
  ui_story_1017_10171301_21_dialog_content = "…",
  ui_story_1017_10171301_22_dialog_content = "ラス？",
  ui_story_1017_10171301_23_dialog_content = "（ラスの状態がおかしい…）",
  ui_story_1017_10171301_24_dialog_content = "前方に暗鬼がいるわ。ヤツらを片付けるわよ！",
  ui_story_1017_10171301_25_dialog_content = "待って。どこに暗鬼が？",
  ui_story_1017_10171301_26_dialog_content = "貫け、雷槍よ！",
  ui_story_1017_10171301_27_dialog_content = "ラス…暗鬼なんていないよ。それは泥だ…",
  ui_story_1017_10171301_28_dialog_content = "貫け、雷槍よ！",
  ui_story_1017_10171301_29_dialog_content = "ど…どういうこと？",
  ui_story_1017_10171301_30_dialog_content = "どうやらまだ目が覚めていないようね。",
  ui_story_1017_10171301_31_dialog_content = "暗鬼がぬかるみに隠れて襲撃のチャンスを狙ってるの…？",
  ui_story_1017_10171301_32_dialog_content = "（…ラスは暗鬼の行動が読めた途端に攻撃してる。\n何だか動きが制御できてないみたいだ…）",
  ui_story_1017_10171301_33_dialog_content = "まだ私の力が残ってるうちに、きちんと指揮しなさい！",
  ui_story_1017_10171301_34_dialog_content = "分かったよ！1時の方向だ！",
  ui_story_1017_10171301_35_dialog_content = "分かったわ！",
  ui_story_1017_10171301_36_dialog_content = "ラス、1時の方向だよ！",
  ui_story_1017_10171301_37_dialog_content = "…",
  ui_story_1017_10171301_38_dialog_content = "そっちじゃない！",
  ui_story_1017_10171301_39_dialog_content = "PlayerName、ラスが暗鬼の群れの中に突進していきました。",
  ui_story_1017_10171301_40_dialog_content = "このままじゃ暗鬼に飲み込まれちゃう！！",
  ui_story_1017_10171301_41_dialog_content = "強制――感知――",
  ui_story_1017_10171301_42_dialog_content = "（ぬかるみだ…）",
  ui_story_1017_10171301_43_dialog_content = "（流れがすごく速い…しかも方向がバラバラで混乱してる）",
  ui_story_1017_10171301_44_dialog_content = "（あれ？ここに渦ができてる…）",
  ui_story_1017_10171301_45_dialog_content = "（光だ！）",
  ui_story_1017_10171301_46_dialog_content = "（ぬかるみが上に流れて…絵を描き始めた…）",
  ui_story_1017_10171301_47_dialog_content = "（ここは…ユリシーズ教授とベリサリア…\nそれからモニターに映ってるのは…）",
  ui_story_1017_10171301_48_dialog_content = "（はっきり見えないうちに消えちゃった…\nラスはここにはいない）",
  ui_story_1017_10171301_49_dialog_content = "（この先にまた光が見える！）",
  ui_story_1017_10171301_50_dialog_content = "（…レインハトさんだ！）",
  ui_story_1017_10171301_51_dialog_content = "（若い頃のレインハトさんだ…観客もいる。\n横断幕に書かれてるのは…）",
  ui_story_1017_10171301_52_dialog_content = "（「啓光大元帥最終選抜試験」…レインハトさんに負けたの…？）",
  ui_story_1017_10171301_53_dialog_content = "（え？雨…？）",
  ui_story_1017_10171301_54_dialog_content = "（ここはシェルターの中みたいだけど、雨が降ってる）",
  ui_story_1017_10171301_55_dialog_content = "（ラスにとって…この日は忘れられない1日なんだろうな…）",
  ui_story_1017_10171301_56_dialog_content = "（ここは…啓光の実験室だね…）",
  ui_story_1017_10171301_57_dialog_content = "（ユリシーズ教授と大勢の人が試験台を取り囲んでる…）",
  ui_story_1017_10171301_58_dialog_content = "（試験台の上にいるのは…）",
  ui_story_1017_10171301_59_dialog_content = "（レインハトさん？）",
  ui_story_1017_10171301_60_dialog_content = "（どうしてレインハトさんが？）",
  ui_story_1017_10171301_61_dialog_content = "（ラスじゃないの！？）",
  ui_story_1017_10171301_62_dialog_content = "（待って…試験台の横に立ってるのは\nユリシーズ教授じゃない。ラスだ！）",
  ui_story_1017_10171301_63_dialog_content = "（ラス！僕の声が聞こえる？）",
  ui_story_1017_10171301_64_dialog_content = "（…）",
  ui_story_1017_10171301_65_dialog_content = "（君は今トワイライトシティで暗鬼と戦ってるんだ！\nしっかりして！）",
  ui_story_1017_10171301_66_dialog_content = "（暗鬼…試験台に乗せられた者は全員暗鬼になる…）",
  ui_story_1017_10171301_67_dialog_content = "（敵がトワイライトシティを蹴散らそうとしてる。\n君は今全身傷だらけだよ。早く目を覚まして！）",
  ui_story_1017_10171301_68_dialog_content = "（レインハトはなぜケガをしないの？）",
  ui_story_1017_10171301_69_dialog_content = "（そうよ、だってレインハトは、暗鬼だから…）",
  ui_story_1017_10171301_70_dialog_content = "（誰だってケガはするよ！でも今君は大元帥でしょ。\n兵士たちには君が必要なんだよ！）",
  ui_story_1017_10171301_71_dialog_content = "（大元帥…）",
  ui_story_1017_10171301_72_dialog_content = "（効果があったのかな？この後は何を言えば…）",
  ui_story_1017_10171301_73_dialog_content = "（大元帥最終選抜試験だ！）",
  ui_story_1017_10171301_74_dialog_content = "（君とレインハトさんの勝負はまだ終わってないよ！\n急いで会場に戻るんだ！）",
  ui_story_1017_10171301_75_dialog_content = "（レインハト…忌々しいレインハト！）",
  ui_story_1017_10171301_76_dialog_content = "（そうだよ、レインハトさんはまだ会場にいる。\n決着をつけに行こう！）",
  ui_story_1017_10171301_77_dialog_content = "（ラス――）",
  ui_story_1017_10171301_78_dialog_content = "PlayerName、ようやく気が付きましたね。",
  ui_story_1017_10171301_79_dialog_content = "僕は大丈夫だよ。ラスは？どんな状況？",
  ui_story_1017_10171301_80_dialog_content = "意識は正常を取り戻したようです。\n再び暗鬼の制圧を始めています。",
  ui_story_1017_10171301_81_dialog_content = "よかった！",
  ui_story_1017_10171301_82_dialog_content = "さきほどのように相手の状況も分からないまま、\n強制感知を行うのは非常に危険です。",
  ui_story_1017_10171301_83_dialog_content = "分かってる…でも、緊急事態だったから、\nあれこれ考えてる余裕もなくて…",
  ui_story_1017_10171301_84_dialog_content = "君がいるから、危なくないって思ったのかも。",
  ui_story_1017_10171301_85_dialog_content = "右方向をご覧ください。\n「アイアンソーン騎士団」が守ってくれたのです。",
  ui_story_1017_10171301_86_dialog_content = "レオが来てくれたんだね！",
  ui_story_1017_10171301_87_dialog_content = "あなたがラスの意識に接続している時、\nすでに参戦していました。",
  ui_story_1017_10171301_88_dialog_content = "ありがとう、ソラヴァン！",
  ui_story_1017_10171301_89_dialog_content = "引き続きナビゲートします。",
  ui_story_1017_10171301_90_dialog_content = "貫け、雷槍よ！",
  ui_story_1017_10171301_91_dialog_content = "あんたさっき、バカなことを言ってくれたわね？",
  ui_story_1017_10171301_92_option_content = "君を助けようと思ったんだよ",
  ui_story_1017_10171301_93_dialog_content = "無事ならよかった！",
  ui_story_1017_10171301_94_dialog_content = "お節介ね。",
  ui_story_1017_10171301_95_option_content = "わざとあんなこと言ったわけじゃないんだ",
  ui_story_1017_10171301_96_dialog_content = "君の意識を取り戻したくて…",
  ui_story_1017_10171301_97_dialog_content = "むやみに他人の頭の中をのぞかないで。いいわね？",
  ui_story_1017_10171301_98_dialog_content = "いつもの話し方に戻ったね。よかった！",
  ui_story_1017_10171301_99_dialog_content = "トワイライトシティを守る任務はまだ終わってないわ。",
  ui_story_1017_10171301_100_dialog_content = "どうせ暗鬼になるなら、\nトワイライトシティを守った暗鬼になってやるわ！",
  ui_story_1017_10171301_101_dialog_content = "近衛兵団！",
  ui_story_1017_10171301_102_dialog_content = "程度は違えど、戦闘中それぞれ不調を覚えたと思う。\nでも私を信じなさい。全部一時的なものよ。",
  ui_story_1017_10171301_103_dialog_content = "精神を集中して、暗力の影響を最小限に押さえなさい！",
  ui_story_1017_10171301_104_dialog_content = "約束するわ。ついて来られなくなった兵士も全員必ず連れて帰るわ。\nそれまではあんたたちの力が必要よ。",
  ui_story_1017_10171301_105_dialog_content = "負傷者、意識のはっきりしない者は即刻引き返し、\n啓光に戻りなさい！",
  ui_story_1017_10171301_106_dialog_content = "まだ戦える者、<color=#FFB400>暗力を恐れない</color>者は、\n私に続いて「中心」へ攻め込むわよ！",
  ui_story_1017_10171301_107_dialog_content = "おーっ！！！",
  ui_story_1017_10171401_1_dialog_content = "満足した？",
  ui_story_1017_10171401_2_dialog_content = "＜まだ足りない――＞",
  ui_story_1017_10171401_3_dialog_content = "ごちそうは最後まで取って置くものよ。\nそれにしてもきれいに敷けたわ、この「カーペット」。",
  ui_story_1017_10171401_4_dialog_content = "＜すべて飲み込んでやる――＞",
  ui_story_1017_10171401_5_dialog_content = "動かないで。最後の調整をしているところなの。",
  ui_story_1017_10171401_6_dialog_content = "まったくひどい環境だわ。実験室とは比べ物にならない。\nおかげで進度が大幅に遅れてる。",
  ui_story_1017_10171401_7_dialog_content = "『光霊が1匹、終始踏ん張っています…』",
  ui_story_1017_10171401_8_dialog_content = "心配いらないわ。\nあの新任大元帥はマッドバンドルの最後のご馳走よ。",
  ui_story_1017_10171401_9_dialog_content = "＜私にすべてを――＞",
  ui_story_1017_10171401_10_dialog_content = "『その者ではなく、別の光霊です。\nそいつは暗力の影響をほとんど受けていません。』",
  ui_story_1017_10171401_11_dialog_content = "新手かしら？急いで見に行きましょう。",
  ui_story_1017_10171401_12_dialog_content = "…",
  ui_story_1017_10171401_13_dialog_content = "どれ程の相手かと思ったら、\n戦えないただのほうけ者じゃない。",
  ui_story_1017_10171401_14_dialog_content = "アクセリアは戦闘サイボーグです。\nアクセリアは戦い続けます。",
  ui_story_1017_10171401_15_dialog_content = "あら、話せるのね。だったら、これでどうかしら？",
  ui_story_1017_10171401_16_dialog_content = "…",
  ui_story_1017_10171401_17_dialog_content = "変わってるわね。暗鬼を殺さずに、何をしようというの？",
  ui_story_1017_10171401_18_dialog_content = "「アクセリアは一切の代償を顧みず、\nレインハト大元帥を倒さなければなりません」",
  ui_story_1017_10171401_19_dialog_content = "アハハ！ユリシーズったら、ずいぶんお粗末ね。\nあの男、あなたの命なんてどうでもいいんでしょうね。",
  ui_story_1017_10171401_20_dialog_content = "「アクセリアは人として、生きていきます」",
  ui_story_1017_10171401_21_dialog_content = "おしゃべりはここまでよ。\nマッドバンドル、食事の時間よ。",
  ui_story_1017_10171401_22_dialog_content = "全兵士を取り囲んだわね。よくやったわ。\nあとは好きなようにしなさい。",
  ui_story_1017_10171401_23_dialog_content = "『はっ。』",
  ui_story_1017_10171401_24_dialog_content = "…",
  ui_story_1017_10171401_25_dialog_content = "私の部下を襲うとはいい度胸ね！",
  ui_story_1017_10171401_26_dialog_content = "やっと見つけた。ぬかるみの中に飲み込まれたかと思ったよ！",
  ui_story_1017_10171401_27_dialog_content = "大元帥様、アクセリア中尉の小隊の兵士を見つけました。",
  ui_story_1017_10171401_28_dialog_content = "分かったわ。負傷者の状況を確認して。\n「中心」の敵の再度の襲撃に注意しなさい。",
  ui_story_1017_10171401_29_dialog_content = "ソラヴァン、近くにまだ兵士はいる？",
  ui_story_1017_10171401_30_dialog_content = "捜索しています…",
  ui_story_1017_10171401_31_dialog_content = "…",
  ui_story_1017_10171401_32_dialog_content = "アクセリア、なぜ暗鬼の攻撃を防ぐだけで倒さなかったの？",
  ui_story_1017_10171401_33_dialog_content = "「アクセリアは一切の代償を顧みず、\nレインハト大元帥を倒さなければなりません」",
  ui_story_1017_10171401_34_dialog_content = "ユリシーズに言われたの？",
  ui_story_1017_10171401_35_dialog_content = "「アクセリアは一切の代償を顧みず、\nレインハト大元帥を倒さなければなりません」",
  ui_story_1017_10171401_36_dialog_content = "…その任務なら完遂したわよ。\n演習でもうレインハトを倒してるわ。",
  ui_story_1017_10171401_37_dialog_content = "…",
  ui_story_1017_10171401_38_dialog_content = "見たところ暗力の深刻な影響は受けてないみたいだけど、\n状態はよくないみたいだね。",
  ui_story_1017_10171401_39_dialog_content = "アクセリア、レインハトは負けを認める前、\nあんたに何か言った？",
  ui_story_1017_10171401_40_dialog_content = "レインハト大元帥は、\nアクセリアに「人として生きて欲しい」と言いました。",
  ui_story_1017_10171401_41_dialog_content = "フン、レインハトときたら…",
  ui_story_1017_10171401_42_dialog_content = "袋の中のネズミになってるっていうのに、\nきれいごと言っちゃって。他には何か言われた？",
  ui_story_1017_10171401_43_dialog_content = "アクセリアは2つの任務を完了しなければなりません。",
  ui_story_1017_10171401_44_dialog_content = "「アクセリアは一切の代償を顧みず、\nレインハト大元帥を倒さなければなりません」",
  ui_story_1017_10171401_45_dialog_content = "「アクセリアは人として、生きていきます」",
  ui_story_1017_10171401_46_dialog_content = "…",
  ui_story_1017_10171401_47_dialog_content = "アクセリア、1つ目の任務はもう完遂したわ。\n今は2つ目の任務があんたの唯一の任務よ。",
  ui_story_1017_10171401_48_dialog_content = "唯一の任務は「アクセリアは人として、生きていく」です。",
  ui_story_1017_10171401_49_dialog_content = "その通りよ。暗鬼に勝ってこそ生きていけるの。\nあんたは啓光の戦士よ、生き残る権利があるわ。",
  ui_story_1017_10171401_50_dialog_content = "アクセリアは暗鬼に勝ち、生き残らなければいけません。",
  ui_story_1017_10171401_51_dialog_content = "アクセリアが…動いた？",
  ui_story_1017_10171401_52_dialog_content = "ひとまず危険な状態は脱したようね。\n完全に回復するにはまだ時間がかかるでしょうけど。",
  ui_story_1017_10171401_53_dialog_content = "大元帥様、アクセリア中尉の隊は暗力の影響が深刻で、\n戦闘には耐えられそうにありません。",
  ui_story_1017_10171401_54_dialog_content = "どうやら「中心」の敵の拠点は、\nここからそう遠くないようね…",
  ui_story_1017_10171401_55_dialog_content = "PlayerName、あんたとソラヴァンのおかげよ。",
  ui_story_1017_10171401_56_dialog_content = "最後にもう1つ頼みたいことがあるの。\n戦闘不能になった兵士たちを送って行ってちょうだい。",
  ui_story_1017_10171401_57_dialog_content = "今から？",
  ui_story_1017_10171401_58_dialog_content = "でも…ぬかるみに隠れた暗鬼が\nいつまた出てくるか分からないよ！？",
  ui_story_1017_10171401_59_dialog_content = "「中心」がどんどん近づいてくる！",
  ui_story_1017_10171401_60_dialog_content = "なぜだか分かる？",
  ui_story_1017_10171401_61_dialog_content = "どうして？",
  ui_story_1017_10171401_62_dialog_content = "「中心」は私を追ってくるからよ。",
  ui_story_1017_10171401_63_dialog_content = "えっ？",
  ui_story_1017_10171401_64_dialog_content = "今までどうしてもアクセリアの部隊が見つからなかったのは、\nヤツらがこの近くに拠点を置き、ぬかるみで私たちを遮断してたからよ。",
  ui_story_1017_10171401_65_dialog_content = "四方八方から襲撃を掛けてこちらの陣形をくずしたのは\n最後の攻撃に備えて時間を稼いでいたにすぎないわ。",
  ui_story_1017_10171401_66_dialog_content = "そして最後に私をここまで誘い込んだ…\nフフ、でもさすがに私に恐れをなしたかしらね。",
  ui_story_1017_10171401_67_dialog_content = "でも「中心」の敵はどうしてそんなことを？",
  ui_story_1017_10171401_68_dialog_content = "フン、私の部下を襲って、その後私を攻撃する…\nぬかるみの後ろに隠れたヤツは啓光を心底恨んでるんでしょうね。",
  ui_story_1017_10171401_69_dialog_content = "相手が誰だか知ってるの？",
  ui_story_1017_10171401_70_dialog_content = "もちろんよ。ぬかるみの「中心」を倒せば、\nヤツの隠れる所はもうないわ。",
  ui_story_1017_10171401_71_dialog_content = "前方500ｍから巨大な暗力の塊がこちらへ向かってきます。",
  ui_story_1017_10171401_72_dialog_content = "ラス、ソラヴァンが検知したんだ…",
  ui_story_1017_10171401_73_dialog_content = "足下に気を付けろ！",
  ui_story_1017_10171401_74_dialog_content = "レオ！どうして君たちがここに！？",
  ui_story_1017_10171401_75_dialog_content = "あの暗鬼はぬかるみのあちこちに姿を現してはいたが、\nその行動は常に1つの方向に向いていた。",
  ui_story_1017_10171401_76_dialog_content = "だから、問い詰めに来たってわけね？",
  ui_story_1017_10171401_77_dialog_content = "そうではない。\nトワイライトシティは町のために戦うすべての仲間を守る。",
  ui_story_1017_10171401_78_dialog_content = "あなたは兵士の状況をずっと気に掛けていた。\n信頼のおける元帥だ。",
  ui_story_1017_10171401_79_dialog_content = "この戦いは長引きすぎている。\n共に戦い、終わらせるとしよう。",
  ui_story_1017_10171401_80_dialog_content = "望むところよ。\n戦いが終わったら、私たちの勝負も忘れないでよ。",
  ui_story_1017_10171401_81_dialog_content = "もちろんだ。",
  ui_story_1017_10171401_82_dialog_content = "（まだ力は残っている…意識もはっきりしているわ…）",
  ui_story_1017_10171401_83_dialog_content = "（命を下すのはこれが最後であることを願うわ）",
  ui_story_1017_10171401_84_dialog_content = "PlayerName、100mの所まで来ています。",
  ui_story_1017_10171401_85_dialog_content = "5秒後にはあなたの感知範囲に敵が現れるでしょう。",
  ui_story_1017_10171401_86_dialog_content = "こんな近くにいるのに姿が見えないなんて…\n感知能力を使うしかない…",
  ui_story_1017_10171401_87_dialog_content = "＜ガアア――＞",
  ui_story_1017_10171401_88_dialog_content = "こ、これは…いったい…",
  ui_story_1017_10171401_89_dialog_content = "ラス！敵が口から血を吹き出しながら向かってくる…",
  ui_story_1017_10171401_90_dialog_content = "僕たちを丸のみできるくらい大きい口だ…",
  ui_story_1017_10171401_91_dialog_content = "「エンジン7号」援護して！",
  ui_story_1017_10171401_92_dialog_content = "この強風は敵の仕業なのか…？",
  ui_story_1017_10171401_93_dialog_content = "み、見ろ！ぬかるみの盛り上がった所に…",
  ui_story_1017_10171401_94_dialog_content = "＜ガア！！＞",
  ui_story_1017_10171401_95_dialog_content = "この暗力はさっきの攻撃よりも…気分が悪くなる。\n皆、気を付けて！",
  ui_story_1017_10171401_96_dialog_content = "大元帥様！ご指示を――",
  ui_story_1017_10171401_97_dialog_content = "前方の兵士たちがすでにぬかるみに巻き込まれています！",
  ui_story_1017_10171401_98_dialog_content = "…",
  ui_story_1017_10171401_99_dialog_content = "（ダメよ…私はまだ…）",
  ui_story_1017_10171401_100_dialog_content = "ラス！ぬかるみが広がってるよ！早く離れるんだ！",
  ui_story_1017_10171401_101_dialog_content = "近衛兵団――",
  ui_story_1017_10171401_102_dialog_content = "…",
  ui_story_1017_10171401_103_dialog_content = "（指示を出す声さえ…もう…）",
  ui_story_1017_10171401_104_dialog_content = "他の者は皆…ぬかるみの外へ…",
  ui_story_1017_10171401_105_dialog_content = "私から…離れなさい…",
  ui_story_1017_10171401_106_dialog_content = "皆の者！私に続いてぬかるみに突入だ！\n啓光の撤退を援護せよ！",
  ui_story_1017_10171401_107_dialog_content = "ラス大元帥、しっかりしろ！",
  ui_story_1017_10171401_108_dialog_content = "私から離れて！",
  ui_story_1017_10171401_109_dialog_content = "…",
  ui_story_1017_10171401_110_dialog_content = "ラス！でも今のその身体じゃこれ以上の無理はできないよ！",
  ui_story_1017_10171401_111_dialog_content = "騎士たち…部下たちをお願い…頼んだわ…",
  ui_story_1017_10171401_112_dialog_content = "暗鬼だろうと、他の何だろうと…\n私は絶対に…負けない…",
  ui_story_1017_10171401_113_dialog_content = "ならば…",
  ui_story_1017_10171401_114_dialog_content = "PlayerName、乗れ！",
  ui_story_1017_10171401_115_dialog_content = "（またぬかるみに入ったら、ラスは…）",
  ui_story_1017_10171401_116_dialog_content = "ラス――！忘れないで！\n君とレインハトさんとの戦いはまだ終わってないよ！",
  ui_story_1017_10171401_117_dialog_content = "！！！",
  ui_story_1017_10171401_118_dialog_content = "（精神を…集中するのよ…）",
  ui_story_1017_10171401_119_dialog_content = "（これは…）",
  ui_story_1017_10171401_120_dialog_content = "（私の…大元帥ラスの…戦いよ…）",
  ui_story_1017_10171402_1_dialog_content = "<color=#e8d9bb>トワイライトシティはすでにぬかるみに飲まれていた…</color>",
  ui_story_1017_10171402_2_dialog_content = "団長！防衛線はすでに破れ、ぬかるみがトワイライトシティに流れ込み、\n住民たちは混乱に陥っています！",
  ui_story_1017_10171402_3_dialog_content = "…啓光の大元帥もぬかるみの中だ…",
  ui_story_1017_10171402_4_dialog_content = "まずは住民たちを病院へ連れて行け。\n我々は捜索を続ける。",
  ui_story_1017_10171402_X1_dialog_content = "急げ！泥が町に流れ込んできたぞ！",
  ui_story_1017_10171402_X2_dialog_content = "どうしてこんなことに！あの子は…？\n私の子はどこ？",
  ui_story_1017_10171402_X3_dialog_content = "そんな…ジョセリンお姉ちゃんはまだ戦場なのに…",
  ui_story_1017_10171402_X4_dialog_content = "防衛線が破られ、ぬかるみがトワイライトシティに流れ込んでいる！\n住民たちは混乱状態だ！",
  ui_story_1017_10171402_X5_dialog_content = "団長はまだ町の外だ…急いで団長に知らせろ！",
  ui_story_1017_10171402_5_dialog_content = "大元帥様――",
  ui_story_1017_10171402_6_dialog_content = "ラス！ラ…",
  ui_story_1017_10171402_7_dialog_content = "PlayerName、大丈夫か？",
  ui_story_1017_10171402_8_dialog_content = "大丈夫だよ…ただ戦いが長く続いたから、\nしばらく感知能力が使えないんだ。",
  ui_story_1017_10171402_9_dialog_content = "すでにこの辺りは隅々まで探した…",
  ui_story_1017_10171402_10_dialog_content = "さっき暗鬼が倒れるまで、\nまったくラスの位置が感知できなかった…",
  ui_story_1017_10171402_11_dialog_content = "ソラヴァンが最後に見た時、ラスは敵のすぐ口元に立って、\n全身泥だらけだったらしい…",
  ui_story_1017_10171402_12_dialog_content = "僕が悪いんだ…僕がしっかりついて行かなかったから…",
  ui_story_1017_10171402_13_dialog_content = "焦点も定まらない目をして、明らかに激しく消耗してたのに、\nそのまま敵に突入していくのを見てた…",
  ui_story_1017_10171402_14_dialog_content = "しかもわざと暗鬼を僕たちとは別の方向に引き付けてくれた…",
  ui_story_1017_10171402_15_dialog_content = "お前のせいではない。\n互いに協力し合ってこそ、敵に勝てるのだ。",
  ui_story_1017_10171402_16_dialog_content = "ただ…皆を守るために、\n「エンジン7号」に我々の援護を阻止させるとは…",
  ui_story_1017_10171402_17_dialog_content = "危険すぎる行為だ…大元帥も彼女の部下も、\n己の命を顧みないにも程がある。",
  ui_story_1017_10171402_18_dialog_content = "…",
  ui_story_1017_10171402_19_dialog_content = "アクセリアは生き残りました。\nでも、ラス大元帥が見つかりません。",
  ui_story_1017_10171402_20_dialog_content = "アクセリア、君が無事ならそれでいいんだよ。",
  ui_story_1017_10171402_21_dialog_content = "ラス大元帥は啓光の戦士です。\n「啓光の戦士には生き残る権利があります」。",
  ui_story_1017_10171402_22_dialog_content = "…",
  ui_story_1017_10171402_23_dialog_content = "速度を上げて、さらに外側一帯を探してみよう。",
  ui_story_1017_10171402_24_dialog_content = "新たな敵が攻撃を仕掛けてきたら、\nラス大元帥を見つけるのは難しくなるぞ！",
  ui_story_1017_10171402_25_dialog_content = "うん！",
  ui_story_1017_10171402_26_dialog_content = "PlayerName、トワイライトシティにラスの痕跡は見つかりません。",
  ui_story_1017_10171402_27_dialog_content = "捜索時間から推算して、\nラスがすでに死亡している確率は99%です。",
  ui_story_1017_10171402_28_dialog_content = "そんな…",
  ui_story_1017_10171402_29_dialog_content = "そんなはずないよ！",
  ui_story_1017_10171402_30_dialog_content = "<size=50>ラス！！</size>",
  ui_story_1017_10171501_1_dialog_content = "（ここは…日没後のトワイライトシティ？）",
  ui_story_1017_10171501_2_dialog_content = "（でも、私1人しかいないわ…）",
  ui_story_1017_10171501_3_dialog_content = "（フッ、また遅れをとったのね。\nレインハトのヤツ、相変わらず強いわ…）",
  ui_story_1017_10171501_4_dialog_content = "（身体が…重い。まったく力が入らないわ…）",
  ui_story_1017_10171501_5_dialog_content = "（このシェルター…静かすぎて…気分が悪くなるわ…）",
  ui_story_1017_10171501_6_dialog_content = "（背負ってるものが、厄介だわ…）",
  ui_story_1017_10171501_7_dialog_content = "（レインハトに負けた後、アイツらは私に鎖をつないだ…）",
  ui_story_1017_10171501_8_dialog_content = "（これが最終決戦に負けた代償なの…？）",
  ui_story_1017_10171501_9_dialog_content = "（戦いは…まだ終わっていないのに…）",
  ui_story_1017_10171501_10_dialog_content = "（アイツに…私を倒すことはできない！）",
  ui_story_1017_10171501_11_dialog_content = "（私はやられないわ！）",
  ui_story_1017_10171501_12_dialog_content = "（再戦を申し込むわ…）",
  ui_story_1017_10171501_13_dialog_content = "（観客は皆、私の名を叫ぶ…）",
  ui_story_1017_10171501_14_dialog_content = "（私の雷槍を…軍服を…返して…）",
  ui_story_1017_10171501_15_dialog_content = "（私は…啓光の大元帥になるのよ…）",
  ui_story_1017_10171501_16_dialog_content = "（誰にも…邪魔はさせない…）",
  ui_story_1017_10171501_17_dialog_content = "数日前、啓光上層部の秘密会合では…",
  ui_story_1017_10171501_18_dialog_content = "長官、お連れしました。",
  ui_story_1017_10171501_19_dialog_content = "座って。",
  ui_story_1017_10171501_20_dialog_content = "用件だけ聞かせてちょうだい。\n任務中なの。",
  ui_story_1017_10171501_21_dialog_content = "座って。",
  ui_story_1017_10171501_22_dialog_content = "…",
  ui_story_1017_10171501_23_dialog_content = "あなたを啓光の大元帥にすると言ったら、どうする？",
  ui_story_1017_10171501_24_dialog_content = "私が？なぜ？",
  ui_story_1017_10171501_25_dialog_content = "あなたが望んでいるからよ。\n啓光連邦もあなたが必要よ。",
  ui_story_1017_10171501_26_dialog_content = "分からないわ。レインハトがいったい何をしたというの？",
  ui_story_1017_10171501_27_dialog_content = "裁判は聞いていたでしょう？あなたもいたでしょ。",
  ui_story_1017_10171501_28_dialog_content = "あれは真実じゃないわ。いったい何が目的なの？",
  ui_story_1017_10171501_29_dialog_content = "実際に見たものが真実とは限らない。\nだったら現実的になったらどう？",
  ui_story_1017_10171501_30_dialog_content = "考えてみて。あなたが大元帥になるか、\nそれとも他の人がなるか。",
  ui_story_1017_10171501_31_dialog_content = "他の3人は知っているの？",
  ui_story_1017_10171501_32_dialog_content = "決めるのはあなたよ。慎重に考えることね。",
  ui_story_1017_10171501_33_dialog_content = "…",
  ui_story_1017_10171501_34_dialog_content = "ユリシーズ、何か言う事があるんじゃないの？",
  ui_story_1017_10171501_35_dialog_content = "君は各方面とも優れた条件に恵まれています。\nただ身体の質が唯一の欠点ですね。",
  ui_story_1017_10171501_36_dialog_content = "大元帥になるのなら、私がその欠点を補ってあげましょう。",
  ui_story_1017_10171501_37_dialog_content = "…",
  ui_story_1017_10171501_38_dialog_content = "何をするつもり？",
  ui_story_1017_10171501_39_dialog_content = "心配することはありません。\nレインハトと同様にちょっとした実験に参加すればいいだけのことです。",
  ui_story_1017_10171501_40_dialog_content = "身体機能を改造し、啓光最強の戦士になるのですよ。",
  ui_story_1017_10171501_41_dialog_content = "レインハトは改造を受けていたの！？",
  ui_story_1017_10171501_42_dialog_content = "意外かしら？",
  ui_story_1017_10171501_43_dialog_content = "（レインハトが！？）",
  ui_story_1017_10171501_44_dialog_content = "（強大、不敗、越えられない高い壁…）",
  ui_story_1017_10171501_45_dialog_content = "（…全部ニセモノだったのね！）",
  ui_story_1017_10171501_46_dialog_content = "「人造陽光計画」に参加した時、彼女はまだ小さかったわ。",
  ui_story_1017_10171501_47_dialog_content = "でも真相を知った後もあなたに何も話さなかったとしても当然ね。\n誰だって自分は生まれつき強いと思いたいもの。",
  ui_story_1017_10171501_48_dialog_content = "…",
  ui_story_1017_10171501_49_dialog_content = "自分が天性の大元帥かどうか知りたいのなら、\nそれを証明する機会が必要よ。",
  ui_story_1017_10171501_50_dialog_content = "今、その機会が目の前にある。",
  ui_story_1017_10171501_51_dialog_content = "機会ですって？",
  ui_story_1017_10171501_52_dialog_content = "遅かれ早かれトワイライトシティの周りで大規模な戦争が起こるわ。\nあなたが行けば勝てると私は確信しているの。",
  ui_story_1017_10171501_53_dialog_content = "もちろん勝てるわ。ただし、私自身の方法で勝つ。",
  ui_story_1017_10171501_54_dialog_content = "答えを急ぐ必要はないわ。",
  ui_story_1017_10171501_55_dialog_content = "1つ言っておくが、ずいぶんと前に自分が言ったことを覚えていますか？",
  ui_story_1017_10171501_56_dialog_content = "最終決戦に負けたあの日、会場の端で――",
  ui_story_1017_10171501_57_dialog_content = "私が君は負けるべきではなかったと言ったら、\n君はこう答えました――",
  ui_story_1017_10171501_58_dialog_content = "身体の限界を超えることができるのなら、\nどんな代償でも払う――",
  ui_story_1017_10171501_59_dialog_content = "今、それに答えを出しましたよ。",
  ui_story_1017_10171501_60_dialog_content = "…",
  ui_story_1017_10171501_61_dialog_content = "<color=#e8d9bb>ラスはバートン、ヒイロ、キシローナに秘密会合でのことを話した</color>",
  ui_story_1017_10171501_62_dialog_content = "…",
  ui_story_1017_10171501_63_dialog_content = "委員会のタヌキどもめ、手段を選ばねえってか？",
  ui_story_1017_10171501_64_dialog_content = "ユリシーズの息のかかった者が大元帥にならないかぎり、\n転機は残されているはずです。",
  ui_story_1017_10171501_65_dialog_content = "バートン、どう思う？",
  ui_story_1017_10171501_66_dialog_content = "どうもこうもねえよ。\nレインハトのことはこのまま黙ってるつもりはねえ。",
  ui_story_1017_10171501_67_dialog_content = "誰が後釜に座るかなんざ、俺にはどうでもいいこった。",
  ui_story_1017_10171501_68_dialog_content = "いずれにせよ、レインハト以外のやつの命令を聞くつもりはねえしな。",
  ui_story_1017_10171501_69_dialog_content = "さっき呼び出されたのがあんただったら？",
  ui_story_1017_10171501_70_dialog_content = "けっ！ユリシーズごときに身体をいじらせるわけねえだろ。\nむしろ俺があいつの息の音を止めてやるぜ。",
  ui_story_1017_10171501_71_dialog_content = "レインハトの件がもし真実だったならば、\n私たちにどうこうできるものではない。",
  ui_story_1017_10171501_72_dialog_content = "今、暗面の動きがますます活発になっています。\nまもなく上層部も何らかの動きをするでしょう。",
  ui_story_1017_10171501_73_dialog_content = "大元帥の指揮がなければ、\n暗鬼の侵入後の対応は難しくなります。",
  ui_story_1017_10171501_74_dialog_content = "ラス、あなたにできますか？",
  ui_story_1017_10171501_75_dialog_content = "レインハトは大元帥だった時、何も恐れはしなかった。\n私はさらにその上をいく怖いもの知らずよ。",
  ui_story_1017_10171501_76_dialog_content = "万が一怪物になっちまったらどうするつもりだ？",
  ui_story_1017_10171501_77_dialog_content = "なら1つお願いがあるわ。\nレインハトを連れて来て、あいつの手で私を殺して。",
  ui_story_1017_10171501_78_dialog_content = "まったく…わけが分からねえな。",
  ui_story_1017_10171501_79_dialog_content = "バカなことを言うな。\n生きて帰ってくれば、当然レインハトに会える。",
  ui_story_1017_10171501_80_dialog_content = "自分で訪ねに行ってください。",
  ui_story_1017_10171501_81_dialog_content = "待って…レインハトのことは冗談で言ってるんじゃないわ。",
  ui_story_1017_10171501_82_dialog_content = "私たちの中で、それができるのはあんただけよ。",
  ui_story_1017_10171501_83_dialog_content = "つまり…",
  ui_story_1017_10171501_84_dialog_content = "その通りよ。日蝕が動けば、キシローナとバートンはすぐに戦地に戻され、待機になるでしょうね。",
  ui_story_1017_10171501_85_dialog_content = "防衛線が本当に危なくなるまで、\nあんたの援軍は最後の最後まで取っておくわ。",
  ui_story_1017_10171501_86_dialog_content = "言い換えれば、戦いが激しければ激しいほど、\nチャンスは大きいってことよ。",
  ui_story_1017_10171501_87_dialog_content = "おいおい、そんなことすれば牢屋行きか、命を落とすかのどっちかだぜ。\nラス、お前本気かよ？",
  ui_story_1017_10171501_88_dialog_content = "本気よ。他に方法はないわ。",
  ui_story_1017_10171501_89_dialog_content = "「啓明の星計画」に参加するってのは？",
  ui_story_1017_10171501_90_dialog_content = "…正直なところ、まだ決めてないわ。",
  ui_story_1017_10171501_91_dialog_content = "でも信じてちょうだい。危険な状態であればあるほど、\n私は正確な判断ができる。",
  ui_story_1017_10171501_92_dialog_content = "マジか？",
  ui_story_1017_10171501_93_dialog_content = "とにかく、あんたたちが私と戦えば、\n啓光が恥をさらすこともない。",
  ui_story_1017_10171501_94_dialog_content = "<color=#e8d9bb>次の日…</color>",
  ui_story_1017_10171501_95_dialog_content = "調子はどうですか？",
  ui_story_1017_10171501_96_dialog_content = "特に何も。",
  ui_story_1017_10171501_97_dialog_content = "すぐに意識がもうろうとしてきます。",
  ui_story_1017_10171501_98_dialog_content = "再び目を覚ました時には、この世界は君にとって、\nずっと公平なものになっているはずですよ。",
  ui_story_1017_10171501_99_dialog_content = "公平、ね…",
  ui_story_1017_10171501_100_dialog_content = "強者は弱者を踏み台にして上へとのぼり、\n弱者は世の中は不公平だと叫ぶことしかできません。",
  ui_story_1017_10171501_101_dialog_content = "多くの者が暗鬼の横行を非難しますが、\n実は自身が強くないだけのことです。",
  ui_story_1017_10171501_102_dialog_content = "君がレインハトに勝ちたいと思うのも同じことですよ。",
  ui_story_1017_10171501_103_dialog_content = "手術が終われば、君たちの対決はずっと公平なものになります。",
  ui_story_1017_10171501_104_dialog_content = "（対決が…ずっと公平なものになる…）",
  ui_story_1017_10171501_105_dialog_content = "（自分は目標のためなら、\n一切の代償もいとわないと思っていたけど）",
  ui_story_1017_10171501_106_dialog_content = "（実際に鋭利な機器が自分の身体に射し込まれてみると、\nまるで自分の手で身体をばらしているかのような気持ちになった）",
  ui_story_1017_10171501_107_dialog_content = "（野望とおごりまで一緒に粉々になっていくみたいだわ）",
  ui_story_1017_10171501_108_dialog_content = "（これまで自分のしてきたすべての選択が\n水中へ沈んでいく時のもがきのように思えてくる…）",
  ui_story_1017_10171501_109_dialog_content = "（でも暗潮は勢いよく押し寄せて、私はどんどん深みにはまっていく…）",
  ui_story_1017_10171501_110_dialog_content = "（私はまだもがき続けなきゃいけないの？\nこれが私が本当に望んでいた結果なの？）",
  ui_story_1017_10171501_111_dialog_content = "（対決はずっと公平なものに…確かにそうかもしれないわ）",
  ui_story_1017_10171501_112_dialog_content = "（でも、その公平は…）",
  ui_story_1017_10171501_113_dialog_content = "（あまりにも遅すぎたわ…）",
  ui_story_1018_10180101_1_dialog_content = "<color=#e8d9bb>暗面のある目立たない場所で…</color>",
  ui_story_1018_10180101_2_dialog_content = "隊長…さっきはあの<color=#FFB400>緑の光を放つ暗鬼</color>にやられなくて幸いでした。",
  ui_story_1018_10180101_3_dialog_content = "ここにくるまで大きな霜柱や奇怪な形のつららを見ましたが、\nまさか極夜がこんな環境だとは想像もしていませんでした…",
  ui_story_1018_10180101_4_dialog_content = "それにしても我々の任務は「ガーディアン1号」のコアを追跡することなのに、\nなぜ隠れて暗鬼を観察する必要があるんですか？",
  ui_story_1018_10180101_5_dialog_content = "シーッ！静かに！",
  ui_story_1018_10180101_6_dialog_content = "あ…さっき隊長がずいぶん興奮してたので、\n<color=#FFB400>暗鬼の本拠地</color>でも見つけたのかと…",
  ui_story_1018_10180101_7_dialog_content = "でも、ここは<color=#FFB400>平原</color>ですね。\n一定の間隔を置いて暗鬼が集まってますが…",
  ui_story_1018_10180101_8_dialog_content = "いったい何の意味があるのか、私にはまったく分かりません。",
  ui_story_1018_10180101_9_dialog_content = "ハハ、あんたの頭ん中は暗鬼と同じで単純なのね。",
  ui_story_1018_10180101_10_dialog_content = "戻ったら、私の隊員だったって触れ回らないでよ！",
  ui_story_1018_10180101_11_dialog_content = "え？それはまたどういうことです…？",
  ui_story_1018_10180101_12_dialog_content = "追跡のコツはね、こっちが主導権を握ること。\nつまり、向こうの考えを読むの。",
  ui_story_1018_10180101_13_dialog_content = "コアを持ってった暗鬼はあの手この手を使って、私らをヘンな所に足止めした。\nってことはここに来させたくないってことでしょ？",
  ui_story_1018_10180101_14_dialog_content = "つまるところ、モノを盗んだコソ泥が一番きらうのは、\n自分たちのアジトを知られることなの。",
  ui_story_1018_10180101_15_dialog_content = "ここは一見ただの平原だけど、これだけたくさんの暗鬼が見張ってるってことは、\n日蝕にとって、すごく重要な場所に決まってるわ。",
  ui_story_1018_10180101_16_dialog_content = "では…あの暗鬼の群れはいったい何の見張りを？",
  ui_story_1018_10180101_17_dialog_content = "推測が正しければ、「ガーディアン1号」のコアと同じくらい重要なモノよ。",
  ui_story_1018_10180101_18_dialog_content = "ほら見て…",
  ui_story_1018_10180101_19_dialog_content = "隊長！暗鬼が突然どよめき始めました！",
  ui_story_1018_10180101_20_dialog_content = "ほらね。「ガーディアン1号」のコアみたいに反応するでしょ？",
  ui_story_1018_10180101_21_dialog_content = "やっぱり何か大きなことを企んでるわね。",
  ui_story_1018_10180101_22_dialog_content = "つまり、「ガーディアン1号」のコアのほかに、\n意外な収穫があったということですか？",
  ui_story_1018_10180101_23_dialog_content = "ふふ、ベリサリアにサプライズを持って帰るのも\nおもしろいんじゃない？",
  ui_story_1018_10180101_24_dialog_content = "さすが隊長！偵察の達人ですね！",
  ui_story_1018_10180101_25_dialog_content = "ただ…こっちの計画が成功する前に、\n暗鬼にやられやしないか心配です…",
  ui_story_1018_10180101_26_dialog_content = "自信持ってよ。私らの乗り物は、\n暗面の環境にほとんど溶け込んでるのよ。",
  ui_story_1018_10180101_27_dialog_content = "列車の塗装には特殊な加工がしてあって、\n周りの環境に完全に溶け込むようになってるの。",
  ui_story_1018_10180101_28_dialog_content = "あんたたちを隊員に選んだのも、\n光力の気配が弱くて暗鬼に発見されにくいから。",
  ui_story_1018_10180101_29_dialog_content = "そういや、あんたたちはそのせいで\n光力術の腕を上げられないのよね…？",
  ui_story_1018_10180101_30_dialog_content = "ええ…以前直属の長官に言われました。\n私は一生運転手しかできない運命だと。",
  ui_story_1018_10180101_31_dialog_content = "ちょっと、今のはテキトーに言ったの。\n戻ったら長官に言ってやりなさい。私と暗面の奥まで入ったって。",
  ui_story_1018_10180101_32_dialog_content = "とにかく、私の経験では、\n暗面に近づけば近づくほど安全なの。",
  ui_story_1018_10180101_33_dialog_content = "隊長…以前は日蝕のメンバーだったけれど、\n今は啓光に身を投じた、なんてことありませんよね？",
  ui_story_1018_10180101_34_dialog_content = "質問が間違ってるわ。前は啓光のメンバーで、\n今は日蝕に身を投じてるんじゃないのかって聞くべきね。",
  ui_story_1018_10180101_35_dialog_content = "…",
  ui_story_1018_10180101_36_dialog_content = "あんたたちはゆっくり近づいて援護して。\n抜き足差し足でね。",
  ui_story_1018_10180101_37_dialog_content = "私は「ガーディアン1号」のコアに似たコレがいったい何なのか見てくるから。",
  ui_story_1018_10180101_38_dialog_content = "分かりました。それと隊長。\n今いる場所の座標は後に続く追跡小隊に送ったほうがいいですか？",
  ui_story_1018_10180101_39_dialog_content = "向こうが危険を脱してから、どうするか考えましょ…\nあんまり順調じゃないみたいだし。",
  ui_story_1018_10180101_40_dialog_content = "<color=#e8d9bb>白夜城朝堂</color>",
  ui_story_1018_10180101_41_dialog_content = "城主様、白夜要塞を守るためだけならば、\n援軍は何のためにトワイライトシティに向かうのですか？",
  ui_story_1018_10180101_42_dialog_content = "啓光の新しい部隊がいかにして組織されたものか、\n知っておるか？",
  ui_story_1018_10180101_43_dialog_content = "なぜ、それをお聞きになるのです？",
  ui_story_1018_10180101_44_dialog_content = "見るがよい。",
  ui_story_1018_10180101_45_dialog_content = "これは…トワイライトシティ白夜教区からの緊急書簡ですが…\n差出人が書かれていませんね。",
  ui_story_1018_10180101_46_dialog_content = "「ぬかるみがトワイライトシティの砦を破り、暗鬼が残虐を働いています。\n啓光軍と騎士団が協力し抵抗していますが、効果は乏しく…」",
  ui_story_1018_10180101_47_dialog_content = "「啓光の兵士は苦戦を強いられ、多大なる被害をこうむりました。\n大元帥は今も行方知れず…今や戦場で戦うのは騎士団のみとなっております」",
  ui_story_1018_10180101_48_dialog_content = "「病院には負傷者があふれ、物資は不足し、\n民の安全と生活はまさに風前の灯となっております…」",
  ui_story_1018_10180101_49_dialog_content = "…大元帥が行方知れずとは…なぜそのようなことが！",
  ui_story_1018_10180101_50_dialog_content = "啓光連邦とて敗戦の経験はある。\nだが、これ程の苦境に陥るのは初めてであろう。",
  ui_story_1018_10180101_51_dialog_content = "それにもかかわらず、啓光連邦の他の軍団は今だカナン城を守ったまま、\n防衛線を越えようとせぬ。",
  ui_story_1018_10180101_52_dialog_content = "要するにトワイライトシティを助ける気などないのだ。\n新たな大元帥の就任を口実に最新の軍事技術の力を検証しようとしているにすぎぬ。",
  ui_story_1018_10180101_53_dialog_content = "このままいけば、新しい部隊はこの検証の犠牲となるであろう。",
  ui_story_1018_10180101_54_dialog_content = "城主様はとうにそのことをご存じだったのですか？",
  ui_story_1018_10180101_55_dialog_content = "これも歴史の繰り返しにすぎぬ。\n啓光連邦はいつ何時たりとも初心に背いたことはないのだ。",
  ui_story_1018_10180101_56_dialog_content = "では、今前線で戦っている兵士たちはどうなるのですか？",
  ui_story_1018_10180101_57_dialog_content = "啓光のことはともかく、我が白夜城の援軍は\nトワイライトシティの民の安全を守るべきと考えます。",
  ui_story_1018_10180101_58_dialog_content = "今考えておる。",
  ui_story_1018_10180101_59_dialog_content = "…決断を伸ばし続ければ、トワイライトシティだけでなく、\n白夜城の地上領にも影響が出ます！",
  ui_story_1018_10180101_60_dialog_content = "<size=45>今考えておる</size>",
  ui_story_1018_10180101_61_dialog_content = "…",
  ui_story_1018_10180101_62_dialog_content = "城主様、シャドウマスターイスタバン様の使者が謁見を願い出ております。",
  ui_story_1018_10180101_63_dialog_content = "通せ。",
  ui_story_1018_10180101_64_dialog_content = "城主様、カレン殿下、お目にかかれて光栄でございます。\n浮空島は相変わらず閑散としているのですね。",
  ui_story_1018_10180101_65_dialog_content = "喧噪の町からやってきた使者よ、何用か？",
  ui_story_1018_10180101_66_dialog_content = "おや、使者として迎えていただけるのですね。",
  ui_story_1018_10180101_67_dialog_content = "私は主のイスタバンより託された言葉を\nお伝えしに参っただけでございます。",
  ui_story_1018_10180101_68_dialog_content = "トワイライトシティの戦いについては、\n城主様も関心をお持ちのことと存じます。",
  ui_story_1018_10180101_69_dialog_content = "ですが、援軍を派遣しながら、周囲の町の安否に関心をお持ちにならないのは、\nいかなるお考えでしょうか？",
  ui_story_1018_10180101_70_dialog_content = "イスタバンがそのように申したのか？",
  ui_story_1018_10180101_71_dialog_content = "多少…脚色を加えさせていただきました。",
  ui_story_1018_10180101_72_dialog_content = "ご存じないかと思いますが、あるトワイライトシティの客人が\n城主様を訪ねる途中、縁あってわが主と意気投合し…",
  ui_story_1018_10180101_73_dialog_content = "彼が事の経緯を一通り説明し終えた頃、\nトワイライトシティはさらに苦しい状況に陥ったようです。",
  ui_story_1018_10180101_74_dialog_content = "その客人というのはショウでは？",
  ui_story_1018_10180101_75_dialog_content = "はい、その通りです。ショウという者です。",
  ui_story_1018_10180101_76_dialog_content = "城主様、ご報告いたします。\nトワイライトシティのショウという者が謁見を願い出ています。",
  ui_story_1018_10180101_77_dialog_content = "もう到着したようですね。",
  ui_story_1018_10180101_78_dialog_content = "白夜城と城外をつなぐ交通路はすべて停止したはずだが。",
  ui_story_1018_10180101_79_dialog_content = "わが主がその気になれば、不可能なことはございませんよ。",
  ui_story_1018_10180101_80_dialog_content = "ショウという者は己の力一つで各勢力を訪ね歩き、\n啓光の後は影ノ街、影ノ街の後は白夜城にやって参りました。",
  ui_story_1018_10180101_81_dialog_content = "もし城主様が謁見を拒まれるようですと、\n次は北境、R・W砂漠へと足を運ぶでしょう…",
  ui_story_1018_10180101_82_dialog_content = "「身体は虚弱だが、目的を果たすまでは決してあきらめない強い意志を持つ。\nそれが今謁見を求める者、ショウだ」",
  ui_story_1018_10180101_83_dialog_content = "今のは主の言葉そのままでございます。",
  ui_story_1018_10180101_84_dialog_content = "トワイライトシティという厄介事にずいぶんと快く介入したようだが、\n何ゆえイスタバンは自ら参らぬのだ？",
  ui_story_1018_10180101_85_dialog_content = "私は用件をお伝えする役割のみを申し付かりました。\n詳しいことはドアの向こうにいる客人にお尋ねください。",
  ui_story_1018_10180101_86_dialog_content = "ここは明るすぎます。私は深海に戻ることにいたします。\n城主様、カレン殿下、それではごきげんよう。",
  ui_story_1018_10180101_87_dialog_content = "…",
  ui_story_1018_10180101_88_dialog_content = "ショウにお会いにならないのですか？",
  ui_story_1018_10180101_89_dialog_content = "トワイライトシティに利害を持つのは白夜城と啓光連邦のみ。\nその以外の者に干渉の権利はない。",
  ui_story_1018_10180101_90_dialog_content = "啓光連邦がすでにその意図を明らかにしたとなれば、\nトワイライトシティは白夜城で守らねばならん。",
  ui_story_1018_10180101_91_dialog_content = "余と共に出立せよ。",
  ui_story_1018_10180101_92_dialog_content = "自らトワイライトシティへ向かわれるのですか？",
  ui_story_1018_10180101_93_dialog_content = "余には啓光のごときやましい意図はない。\n啓光の光霊への冒涜は我が神殿により裁かれねばならん。",
  ui_story_1018_10180201_1_dialog_content = "<color=#e8d9bb>トワイライトシティ</color>",
  ui_story_1018_10180201_2_dialog_content = "（もうずいぶん探してるのに…）",
  ui_story_1018_10180201_3_dialog_content = "（ラス…いったいどこにいるんだ…）",
  ui_story_1018_10180201_4_dialog_content = "団長、「中心」の敵を撃破した後、\nぬかるみに乗じて湧いて出た暗鬼は全て片付けました。",
  ui_story_1018_10180201_5_dialog_content = "ぬかるみはまだ残っていますが、\nトワイライトシティはひとまず危険を脱しました。",
  ui_story_1018_10180201_6_dialog_content = "これで一段落したんでしょうか？",
  ui_story_1018_10180201_7_dialog_content = "戦場が外へと移ってきていはいるが、\n完全に終わったと言うにはまだ遠いな。",
  ui_story_1018_10180201_8_dialog_content = "PlayerName、トワイライトシティに侵入していた暗力は\n今どのくらい減ったのだ？",
  ui_story_1018_10180201_9_dialog_content = "ソラヴァンのほうでも暗力の密度の高い敵は見つかってないよ。",
  ui_story_1018_10180201_10_dialog_content = "ただ、ぬかるみがトワイライトシティを覆ったままだから、\n危険は残ってる。",
  ui_story_1018_10180201_11_dialog_content = "その通りです…ぬかるみに影響を受けた兵士たちは今病院でもひとまず状態が落ち着いていますが、\n肝心の治療法はまだ見つかっていません。",
  ui_story_1018_10180201_12_dialog_content = "このままでは厄介なことになるな…",
  ui_story_1018_10180201_13_dialog_content = "団長、トワイライトシティの民は全員\n臨時の病院に集めました。",
  ui_story_1018_10180201_14_dialog_content = "中心部に近い住民は自身の家を避難民のために提供してくれています。",
  ui_story_1018_10180201_15_dialog_content = "多くの民が被害を受けずに済んだようだ。\n皆が命をかけて戦ってくれたおかげだ。",
  ui_story_1018_10180201_16_dialog_content = "だが、トワイライトシティに留まり続けるのは得策ではない。\n住民たちを啓光防衛線近くの村に移さなくてはならん。",
  ui_story_1018_10180201_17_dialog_content = "しかし団長、今はまだ周囲の戦地も収拾しきれていない状態です。\n民を移動させるのは危険ではないでしょうか？",
  ui_story_1018_10180201_18_dialog_content = "ラス大元帥と一緒に突入した部下たちもまだぬかるみの中で、\n行方知れずのままです…",
  ui_story_1018_10180201_19_dialog_content = "先に準備をしておけ。\n戦局が明確になり次第、次の一手を考えよう。",
  ui_story_1018_10180201_20_dialog_content = "そちらの兵士に聞く。\n行方知れずの兵の数はおよそどのくらいだ？",
  ui_story_1018_10180201_21_dialog_content = "大元帥様と共に突入した部隊は2つ、\n人数にして100名を越えています…",
  ui_story_1018_10180201_22_dialog_content = "しかも、そのほとんどが…新兵です。",
  ui_story_1018_10180201_23_dialog_content = "「アイアンソーン騎士団」の約半数の兵力ではないか。",
  ui_story_1018_10180201_24_dialog_content = "団長、西側の城壁近くで数人の兵士を見つけました。\n状況が分からないので、団員も近づいてはいませんが…",
  ui_story_1018_10180201_25_dialog_content = "すぐに様子を見に行くぞ！",
  ui_story_1018_10180201_26_dialog_content = "間違いありません…大元帥様と一緒に突入した兵士です。",
  ui_story_1018_10180201_27_dialog_content = "ざっと見ただけでも、数十名が犠牲になったようです…",
  ui_story_1018_10180201_28_dialog_content = "…犠牲になった兵士たちを丁寧に兵舎へ運んでやれ。\nぬかるみの中に潜伏する敵にも十分注意するのだぞ。",
  ui_story_1018_10180201_29_dialog_content = "了解です！",
  ui_story_1018_10180201_30_dialog_content = "…",
  ui_story_1018_10180201_31_dialog_content = "もうこんなことになっちゃったの…？\nまだ挨拶もしてなかったのに…",
  ui_story_1018_10180201_32_dialog_content = "それが軍人というものだ、PlayerName。",
  ui_story_1018_10180201_33_dialog_content = "一年中戦争に明け暮れ、戦友の死を悼む時間もなく、\n次の戦場へと向かわねばならない。",
  ui_story_1018_10180201_34_dialog_content = "…",
  ui_story_1018_10180201_35_dialog_content = "レオ騎士団長、まだ息のある戦士がいます！",
  ui_story_1018_10180201_36_dialog_content = "状況は？",
  ui_story_1018_10180201_37_dialog_content = "治療すれば一時的に落ち着かせることはできます…",
  ui_story_1018_10180201_38_dialog_content = "…",
  ui_story_1018_10180201_39_dialog_content = "怖いのですか…？それとも何かお話しになりたいのですか？",
  ui_story_1018_10180201_40_dialog_content = "何か…食べてるみたいだ。",
  ui_story_1018_10180201_41_dialog_content = "ガアアア！！",
  ui_story_1018_10180201_42_dialog_content = "雷のごとく振るえ！",
  ui_story_1018_10180201_43_dialog_content = "突然…暗鬼になった！？",
  ui_story_1018_10180201_44_dialog_content = "やはり最も恐れていた事態が起きたか…",
  ui_story_1018_10180201_45_dialog_content = "ガアアア！！",
  ui_story_1018_10180201_46_dialog_content = "あちらもか？",
  ui_story_1018_10180201_47_dialog_content = "団長！犠牲になった兵士たちが…\nいえ、暗鬼が突然我々に襲いかかってきました！",
  ui_story_1018_10180201_48_dialog_content = "まずい、予想より状況が複雑なようだ。\nこのまま捜索と治療を進めるわけにはいかん！",
  ui_story_1018_10180201_49_dialog_content = "皆の者、戦闘準備！",
  ui_story_1018_10180201_50_dialog_content = "待って！レオ…",
  ui_story_1018_10180202_1_dialog_content = "この人たち全員…もう望みはないの…？",
  ui_story_1018_10180202_2_dialog_content = "…",
  ui_story_1018_10180202_3_dialog_content = "暗鬼をいたわる必要はない。",
  ui_story_1018_10180202_4_dialog_content = "かつては戦士だったとしても、\nこのまま戦場に残しておいては死傷者を増やすだけだ。",
  ui_story_1018_10180202_5_dialog_content = "啓光の兵士たちよ、ここは我々に任せ、\nトワイライトシティから早急に撤退するのだ！",
  ui_story_1018_10180202_6_dialog_content = "レオ騎士団長、啓光の兵士はまだ…\nトワイライトシティを離れるわけにはいきません。",
  ui_story_1018_10180202_7_dialog_content = "啓光の兵士は全員トワイライトシティから撤退しろ。",
  ui_story_1018_10180202_8_dialog_content = "…",
  ui_story_1018_10180202_9_dialog_content = "ならば、レオ騎士団長、説明させてください。",
  ui_story_1018_10180202_10_dialog_content = "説明を聞いてから、\n今の命を本当に実行するかご再考ください。",
  ui_story_1018_10180202_11_dialog_content = "話せ。",
  ui_story_1018_10180202_12_dialog_content = "トワイライトシティに来る前、我々近衛兵団は啓光最精鋭の兵によって組織され、\n精鋭予備隊と呼ばれていました。",
  ui_story_1018_10180202_13_dialog_content = "私の後ろにいる仲間たちも精鋭予備隊の者です。\nずっとラス大元帥様に付き従ってきました。",
  ui_story_1018_10180202_14_dialog_content = "このような戦いは経験ありませんが、\n今の今まで持ちこたえてきたことは十分我々の実力を証明していると思います。",
  ui_story_1018_10180202_15_dialog_content = "何を言いたいか分かっている。\n突然暗鬼になった新兵たちは啓光で特殊な訓練を受けた者たちなのだろう？",
  ui_story_1018_10180202_16_dialog_content = "そしてトワイライトシティに到着後、ぬかるみの影響を受けた。\nお前たちの大元帥も含めてな。",
  ui_story_1018_10180202_17_dialog_content = "その通りです…しかし、誓って申し上げます！\n戦場に出るまでこのようなことになるとは我々も予想していませんでした。",
  ui_story_1018_10180202_18_dialog_content = "これだけ多くの仲間を失い、大元帥様まで行方知れずとなり、\n皆心を痛めています。",
  ui_story_1018_10180202_19_dialog_content = "ですから、精鋭予備隊一同に代わりお願いします！\nこのまま戦場に残り、トワイライトシティを守らせてください！",
  ui_story_1018_10180202_20_dialog_content = "それが我々が受けた命令です。\n大元帥様が見つかるまで啓光の軍人として命令を遂行します。",
  ui_story_1018_10180202_21_dialog_content = "我々にもトワイライトシティを守らせてください。\n私が大元帥様に代わり指揮を執ります。",
  ui_story_1018_10180202_22_dialog_content = "団長が団長なら、部下も部下だな。",
  ui_story_1018_10180202_23_dialog_content = "敵はお前たちの同胞だぞ？",
  ui_story_1018_10180202_24_dialog_content = "彼らはトワイライトシティを破滅に導く暗鬼に変わり果てました…\n憐みはかけません。",
  ui_story_1018_10180202_25_dialog_content = "ガアアア！！",
  ui_story_1018_10180202_26_dialog_content = "団長、こちらにも数匹敵が！",
  ui_story_1018_10180202_27_dialog_content = "あ…",
  ui_story_1018_10180202_28_dialog_content = "ふん…雷のごとく振るえ！",
  ui_story_1018_10180202_29_dialog_content = "今の行動は証明になっていないな。\n端に寄っていろ、彼らはもう救いようがない。",
  ui_story_1018_10180202_30_dialog_content = "レオ騎士団長、そのように決めつけてはいけません。\nこちらに攻撃を仕掛けてこない限り、救いようがないとは言えません。",
  ui_story_1018_10180202_31_dialog_content = "そうだよ…何だか迷っているみたいだった…",
  ui_story_1018_10180202_32_dialog_content = "お前たちも今のを見ただろう？\n一瞬でも後れをとれば、攻撃の機会を与えてしまう。",
  ui_story_1018_10180202_33_dialog_content = "ですが、彼らも光霊です――",
  ui_story_1018_10180202_34_dialog_content = "ガアアア！！",
  ui_story_1018_10180202_35_dialog_content = "よく見ろ！暗鬼とどこが違うと言うのだ！？\nトワイライトシティを傷つけようとする者は皆敵だ！",
  ui_story_1018_10180202_36_dialog_content = "啓光の兵士たちよ。トワイライトシティを守りたいのなら、\n勇気を示せ！敵に容赦などいらん！",
  ui_story_1018_10180202_37_dialog_content = "それができないのならば、トワイライトシティから立ち去れ。\nお前たちの任務は終わりだ！",
  ui_story_1018_10180202_38_dialog_content = "私は――",
  ui_story_1018_10180202_39_dialog_content = "私の部下に…指図するなんて100年早いわ…",
  ui_story_1018_10180202_40_dialog_content = "暗力の影響を受けていても…まだ…死には値しない…",
  ui_story_1018_10180202_41_dialog_content = "私が必ず…",
  ui_story_1018_10180202_42_dialog_content = "レオ、ラスだよ！",
  ui_story_1018_10180202_43_dialog_content = "…",
  ui_story_1018_10180202_44_dialog_content = "だって私は…経験したのよ…",
  ui_story_1018_10180202_45_dialog_content = "大元帥様！",
  ui_story_1018_10180301_1_dialog_content = "ラス！ずいぶん探したんだよ！",
  ui_story_1018_10180301_2_dialog_content = "君が姿を現した途端…異変を起してた兵士の動きがおさまった…",
  ui_story_1018_10180301_3_dialog_content = "ぬかるみの影響で…力を制御できないだけよ…",
  ui_story_1018_10180301_4_dialog_content = "あんたたちを…傷つけようとしたわけじゃ…ないわ…",
  ui_story_1018_10180301_5_dialog_content = "…",
  ui_story_1018_10180301_6_dialog_content = "白夜に捧ぐ…大元帥様、ご無事だったのですね！",
  ui_story_1018_10180301_7_option_content = "ずいぶん衰弱してるみたいだ",
  ui_story_1018_10180301_8_dialog_content = "どこか具合の悪い所は？",
  ui_story_1018_10180301_9_dialog_content = "ぬかるみにぶつかった時に痛みがあった以外…",
  ui_story_1018_10180301_10_dialog_content = "ほかは何も覚えてないわ…",
  ui_story_1018_10180301_11_option_content = "いったい何があったの？",
  ui_story_1018_10180301_12_dialog_content = "いくら探しても見つからなかったんだよ！",
  ui_story_1018_10180301_13_dialog_content = "私にもよく分からないの…",
  ui_story_1018_10180301_14_dialog_content = "覚えているのは、ぬかるみに囲まれた途端、\n目の前が真っ暗になったことだけ…",
  ui_story_1018_10180301_15_dialog_content = "安心して…全身泥だらけになっただけだから…",
  ui_story_1018_10180301_16_dialog_content = "同じような兵士はあとどのくらいいるのかしら…",
  ui_story_1018_10180301_17_dialog_content = "実はレオがずっと兵士たちの捜索をしてくれてたんだ…",
  ui_story_1018_10180301_18_dialog_content = "よかった、君が戻ってきてくれて！",
  ui_story_1018_10180301_19_dialog_content = "ええ…",
  ui_story_1018_10180301_20_dialog_content = "言ったはずよ。たとえ暗鬼になろうと、\nトワイライトシティを守って見せるって…",
  ui_story_1018_10180301_21_dialog_content = "今…そこに私の部下も加えるわ…",
  ui_story_1018_10180301_22_dialog_content = "部下を暗鬼として倒すことは…私が許さない。",
  ui_story_1018_10180301_23_dialog_content = "…大元帥、無事で何よりだ。",
  ui_story_1018_10180301_24_dialog_content = "私は啓光の兵士を傷つけようとしたことは一度もない。\nトワイライトシティのことを考えて下した判断だ。",
  ui_story_1018_10180301_25_dialog_content = "順境にあれば敵を倒し、逆境にあれば兵を捨てる…\n悪いけど、そんな騎士道、私には受け入れられないわ…",
  ui_story_1018_10180301_26_dialog_content = "大元帥、私は…",
  ui_story_1018_10180301_27_dialog_content = "私が戻ったからには、部下の指揮は私が執る…",
  ui_story_1018_10180301_28_dialog_content = "今はあんたと議論する気力もないわ…\n出すぎた真似はしないことね…",
  ui_story_1018_10180301_29_dialog_content = "…承知した、大元帥。",
  ui_story_1018_10180301_30_dialog_content = "ラス大元帥様、大変弱っていらっしゃるようです。",
  ui_story_1018_10180301_31_dialog_content = "私と一緒に病院までいらしてください。\n治療いたします。",
  ui_story_1018_10180301_32_dialog_content = "ここは戦場よ…部下がまだ戦っているのに、\n私が離れるわけにはいかない。",
  ui_story_1018_10180301_33_dialog_content = "では、せめて…傷口を拝見させてください。\n私の馬に乗り、しばしお休みください！",
  ui_story_1018_10180301_34_dialog_content = "部下に対して、本当に責任を持つつもりなら、\nまずは自身の身体の状態を確めるべきだ。",
  ui_story_1018_10180301_35_dialog_content = "ぬかるみの中に長時間いたんだよ。無理はいけないよ。",
  ui_story_1018_10180301_36_dialog_content = "…なら、お願いするわ。ジョセリン。",
  ui_story_1018_10180301_37_dialog_content = "…白夜に捧ぐ…まさかまだ光力術をお使いになれるとは…",
  ui_story_1018_10180301_38_dialog_content = "全身傷だらけです。致命傷ではありませんが、\nすでに力がひどく弱まっています。",
  ui_story_1018_10180301_39_dialog_content = "力が弱まっている…？そうは感じないけど…",
  ui_story_1018_10180301_40_dialog_content = "かえって急速に回復してるように思うわ…",
  ui_story_1018_10180301_41_dialog_content = "そういえば、気を失っている時、\n何かの力が身体の中を駆け巡っていたわ…",
  ui_story_1018_10180301_42_dialog_content = "誰かが治療してくれているような…\n何とも表現しがたい感じだった…",
  ui_story_1018_10180301_43_dialog_content = "治療？戦場に他にも誰かいたの？",
  ui_story_1018_10180301_44_dialog_content = "おかしな話よね…でも私が今ここにいるってことは、\n可能性がないわけじゃないでしょ…",
  ui_story_1018_10180301_45_dialog_content = "ただ、部下は守りきれなかった…",
  ui_story_1018_10180301_46_dialog_content = "…大元帥様と共にぬかるみに突入した2部隊は、\nまだ見つかっていません。",
  ui_story_1018_10180301_47_dialog_content = "アクセリア隊長が隊を率いて捜索を続けていますが…",
  ui_story_1018_10180301_48_dialog_content = "もしかしたら全員…さきほどの者たちのように…",
  ui_story_1018_10180301_49_dialog_content = "私が…この私が彼らを危険にさらしたのよ…",
  ui_story_1018_10180301_50_dialog_content = "大元帥様、それは違います！\n我々が命令に背いて…",
  ui_story_1018_10180301_51_dialog_content = "大元帥様と共に前に進むことを選んだのです。\nこの新兵たちも…",
  ui_story_1018_10180301_52_dialog_content = "このような敵を前にしても、\nあなたはためらうことなく進攻し、戦局を変えました。",
  ui_story_1018_10180301_53_dialog_content = "早急に発見できれば、まだ助かるかもしれません！",
  ui_story_1018_10180301_54_dialog_content = "…",
  ui_story_1018_10180301_55_dialog_content = "…いずれにせよ、これ以上私と一緒に危険を冒させるわけにはいかない…",
  ui_story_1018_10180301_56_dialog_content = "<color=#e8d9bb>一行は戦場の西側へやってきた…</color>",
  ui_story_1018_10180301_57_dialog_content = "ぬかるみがここまで来てるなんて…\nしかも、まだ流れ続けてるみたいだ…",
  ui_story_1018_10180301_58_dialog_content = "うむ…まだ敵が襲ってくる恐れがあるな。\n兵士たちも泥に流されて、行方が分からなくなっているのだろう。",
  ui_story_1018_10180301_59_dialog_content = "そうだとしても、ぬかるみがある限り、\n戦いは終わりません。",
  ui_story_1018_10180301_60_dialog_content = "最も恐れるべき事態は…私の部下が敵に利用されることよ…",
  ui_story_1018_10180301_61_dialog_content = "部隊編成のミスが戦局を大きく変えてしまった。\n私の責任よ。",
  ui_story_1018_10180301_62_dialog_content = "大元帥様、あなたも事情を知らなかったのです。\nとにかくぬかるみに沿って捜索を続けましょう。",
  ui_story_1018_10180301_63_dialog_content = "そうね…",
  ui_story_1018_10180301_64_dialog_content = "ラス大元帥様、防衛線の西側をご覧ください――",
  ui_story_1018_10180301_65_dialog_content = "「エンジン7号」が3台あちらにあります！\nそれに…兵士たちもいるようです！",
  ui_story_1018_10180301_66_dialog_content = "エンジン7号には私の援護に回ってもらったはず…\nこんな所で見つかるなんて…",
  ui_story_1018_10180301_67_dialog_content = "辺り一帯が廃墟となっている…背後にある砦もすでに破られているようだ。\n彼らが踏ん張ってくれたおかげで守りきれたのだな…",
  ui_story_1018_10180301_68_dialog_content = "これで行方知れずの「エンジン7号」は残り1台ね。\nおそらくこの近くにあるはずよ。急いで見に行きましょう…",
  ui_story_1018_10180301_69_dialog_content = "<color=#e8d9bb>ガリガリ――ガリガリ――</color>",
  ui_story_1018_10180301_70_dialog_content = "うっ…団長、これは…",
  ui_story_1018_10180301_71_dialog_content = "…",
  ui_story_1018_10180301_72_dialog_content = "完全に破壊されています…",
  ui_story_1018_10180301_73_dialog_content = "「エンジン7号」を取り囲む兵士たちが…\n筐体を食らっています…",
  ui_story_1018_10180301_74_dialog_content = "グォォ…",
  ui_story_1018_10180301_75_dialog_content = "暗鬼と同様、食することでエネルギーを補給しているのか…？",
  ui_story_1018_10180301_76_dialog_content = "そんな…",
  ui_story_1018_10180301_77_dialog_content = "グォォ！！！",
  ui_story_1018_10180301_78_dialog_content = "…",
  ui_story_1018_10180301_79_dialog_content = "大元帥様、馬をお降りください。\n私たちの存在には気づいていないようですから、ここはお任せください。",
  ui_story_1018_10180301_80_dialog_content = "その通りだ。暗鬼の数は多くない。\n私一人で十分だ。",
  ui_story_1018_10180301_81_dialog_content = "彼らは暗鬼じゃない…私の部下よ…",
  ui_story_1018_10180301_82_dialog_content = "…何とかして抑えなきゃ…",
  ui_story_1018_10180301_83_dialog_content = "…",
  ui_story_1018_10180301_84_dialog_content = "大元帥として常に先陣に立つあなたが、\n部下を前にするとこれ程にも判断が鈍るのか？",
  ui_story_1018_10180301_85_dialog_content = "まずは抑え込むのよ…まだ助けられるかもしれない…",
  ui_story_1018_10180301_86_dialog_content = "ラスの言う通りだよ。僕がやってみる！",
  ui_story_1018_10180302_1_dialog_content = "ふぅ…落ち着いたみたいだね。",
  ui_story_1018_10180302_2_dialog_content = "この先は医療者にお任せください。\nPlayerNameさんは指揮だけなく、治療にも長けていらしたのですね。",
  ui_story_1018_10180302_3_dialog_content = "前にラスが同じような状況になった時、\nこうやったら正気を取り戻したんだ。",
  ui_story_1018_10180302_4_dialog_content = "皆自分の意識の中に深く入り込んで、\n自己制御が効かなくなってるだけなんだ。",
  ui_story_1018_10180302_5_dialog_content = "ただ…機械の筐体をたくさん食べてた兵士は…残念だった…",
  ui_story_1018_10180302_6_dialog_content = "白夜に捧ぐ…レオ騎士団長も何とか抑え込もうとしましたが…\nあなたも団長も全力を尽くしました。",
  ui_story_1018_10180302_7_dialog_content = "あの兵士はもう身体がボロボロだった。\n暗力でなんとか持ちこたえていたのだ…",
  ui_story_1018_10180302_8_dialog_content = "大元帥も大局を優先し、こういう兵士に対しては…\n胸を痛める必要はない。",
  ui_story_1018_10180302_9_dialog_content = "言われなくても分かってるわ…",
  ui_story_1018_10180302_10_dialog_content = "それはそうと、今後見つけた兵士は病院で治療するつもりか？",
  ui_story_1018_10180302_11_dialog_content = "数百名の兵士ともなれば、少なからぬ数だ。",
  ui_story_1018_10180302_12_dialog_content = "確かにそうですね…病院にはもう\n今後救助した負傷者を受け入れる余裕はありません…",
  ui_story_1018_10180302_13_dialog_content = "ですが、啓光の兵士の状態は特殊です。\n一刻も早く治療しなくてはなりません。",
  ui_story_1018_10180302_14_dialog_content = "部下がすでに準備をしている。\n部下が戻り次第、住民を中心部の町に移す。",
  ui_story_1018_10180302_15_dialog_content = "何で移動するの？馬車数台で移動するというの…？",
  ui_story_1018_10180302_16_dialog_content = "ああ、数に限りがあるが、移動手段はもう残っていない。\n徒歩での移動も考える必要があるかもしれん…",
  ui_story_1018_10180302_17_dialog_content = "徒歩で移動なんて、暗鬼に食料を与えるようなものじゃない…",
  ui_story_1018_10180302_18_dialog_content = "提案があるわ…ただ、決めるのはPlayerNameよ。",
  ui_story_1018_10180302_19_dialog_content = "実は僕もいい方法を1つ思いついたんだ…",
  ui_story_1018_10180302_20_dialog_content = "ソラヴァンだよ/ソラヴァンよ。",
  ui_story_1018_10180302_21_dialog_content = "トワイライトシティの住民を素早く避難させられるし…\n天空ノ谷は目下一番安全な所だと思う。",
  ui_story_1018_10180302_22_dialog_content = "ただ、救助した負傷者はどうするつもりなの？",
  ui_story_1018_10180302_23_dialog_content = "ぬかるみが消えるまでに…我々で考えておく。\n今は武器も持たない一般住民が最優先だ。",
  ui_story_1018_10180302_24_dialog_content = "レオ騎士団長、白夜要塞に行かせてください。",
  ui_story_1018_10180302_25_dialog_content = "これまでにも多くの教会の方々が自ら病院に残り、\n治療に当たってくださっています。",
  ui_story_1018_10180302_26_dialog_content = "救急治療の必要なけが人の受け入れを教会に頼んできます。\n大元帥様の今後の救助に支障がないよう努めなければなりません。",
  ui_story_1018_10180302_27_dialog_content = "白夜要塞か…楽観はできないだろう。",
  ui_story_1018_10180302_28_dialog_content = "だが今は避難民を守ることが最優先だ。\n何が最良の策かなど誰にも分かりはしない。止めはしない。",
  ui_story_1018_10180302_29_dialog_content = "陣営の違いは越えがたいものだとしても、\n白夜教会が光霊を拒むことはないと信じています。",
  ui_story_1018_10180302_30_dialog_content = "ただ…ラス大元帥様。\nあなたや啓光の皆さんは白夜教会でも構いませんか？",
  ui_story_1018_10180302_31_dialog_content = "私は行く必要ないわ。啓光と宗教はそもそも相いれないから。",
  ui_story_1018_10180302_32_dialog_content = "今は部下の安全が第一よ。部下たちを…頼んだわ。",
  ui_story_1018_10180302_33_dialog_content = "ラスは本当に治療しなくていいの？",
  ui_story_1018_10180302_34_dialog_content = "私はただ疲れているだけよ…\nあんたたちと話してたら、だいぶ良くなったわ。",
  ui_story_1018_10180302_35_dialog_content = "ジョセリン、馬を貸してくれるかしら？",
  ui_story_1018_10180302_36_dialog_content = "もちろん構いません！ご安心ください。\nきっと部下の皆さんに一刻も早い治療を受けさせて差し上げます。",
  ui_story_1018_10180302_37_dialog_content = "次にお会いする時には戦いが終わっていることを祈っております。\nでは、私は準備に向かいます。",
  ui_story_1018_10180302_38_dialog_content = "くれぐれも気を付けて。",
  ui_story_1018_10180302_39_dialog_content = "PlayerName、この後西側の出口で私の部下と落ち合うといい。",
  ui_story_1018_10180302_40_dialog_content = "トワイライトシティの危険が排除され次第、\n私も民の避難を手伝いに行く。",
  ui_story_1018_10180302_41_dialog_content = "ここまで色々と…コホン、感謝してるわ。\nまた会いましょう。",
  ui_story_1018_10180302_42_dialog_content = "あの…僕はまだ帰るなんて言ってないけど…",
  ui_story_1018_10180302_43_dialog_content = "ソラヴァンの自動飛行システムを使えば、\n町の人たちを安全な所に避難させられる。",
  ui_story_1018_10180302_44_dialog_content = "一緒にトワイライトシティを守るって言ったでしょ？\nこの戦いが終わるまで、僕もここを離れないよ。",
  ui_story_1018_10180302_45_dialog_content = "…PlayerName、お前の意志の強さは想像以上だな。",
  ui_story_1018_10180302_46_dialog_content = "長い間一緒に戦ってきたから、\nそう言うんじゃないかとは思っていたわ。",
  ui_story_1018_10180302_47_dialog_content = "PlayerName、トワイライトシティの西側に着陸しました。\n今の距離であれば、交信を維持できます。",
  ui_story_1018_10180302_48_dialog_content = "ソラヴァン、この後トワイライトシティの人たちを\n僕たちの家まで安全に送ってほしいんだ。",
  ui_story_1018_10180302_49_dialog_content = "目的地を設定します。\n目的地、天空ノ谷。",
  ui_story_1018_10180302_50_dialog_content = "PlayerName、くれぐれも安全に気を付けてください。",
  ui_story_1018_10180302_51_dialog_content = "うん。トワイライトシティの人たちは任せたよ！",
  ui_story_1018_10180401_1_dialog_content = "<color=#e8d9bb>暗面に向かって進む列車の中では…</color>",
  ui_story_1018_10180401_2_dialog_content = "1、2、3…ここをもう4周はしてます。\nあの方から何かご指示はないんですか？",
  ui_story_1018_10180401_3_dialog_content = "メリー、落ち着いてください。\n僕たちをここまで導いた謎も必ずや解ける時が来ます。",
  ui_story_1018_10180401_4_dialog_content = "カロン車掌はミンチの案内を本当に信じてるんでしょうか？",
  ui_story_1018_10180401_5_dialog_content = "すでに長い間一緒に行動しているのですよ。それくらいは分かっているでしょう？\nそれより…ミンチ、大丈夫ですか？",
  ui_story_1018_10180401_6_dialog_content = "さっきからずっと頭が痛いの。\n風が強いからかな…",
  ui_story_1018_10180401_7_dialog_content = "車両の中に風が吹くはずないでしょう…",
  ui_story_1018_10180401_8_dialog_content = "窓の外だよ。強風が起こる頻度が普通じゃないもん…",
  ui_story_1018_10180401_9_dialog_content = "わずかな光を頼りに見る限り、斜め後方の町は不測の事態に襲われたようですね。\nあの方がまだいらっしゃらないのもそのせいかもしれません。",
  ui_story_1018_10180401_10_dialog_content = "あの黒い物体は町だったんですね。\n暗面から伸びた黒い爪のように見えますが…",
  ui_story_1018_10180401_11_dialog_content = "はぁ。せっかく乗り心地も見た目も美しい列車に乗れたというのに、\n車窓の外にはこんな風景が広がってるなんて…",
  ui_story_1018_10180401_12_dialog_content = "カロン長官、あの3人の言ったことを本当に信じるんですか？\n出発した時からずっと休憩するようおっしゃってますが。",
  ui_story_1018_10180401_13_dialog_content = "もう3回は仮眠をとったのに、\nどうしてまだ暗面に着かないんです？",
  ui_story_1018_10180401_14_dialog_content = "我々は今任務遂行中なのだよ、バイス。\n心配はいらない。彼岸号が守ってくれる。",
  ui_story_1018_10180401_15_dialog_content = "でも長官、啓光から暗面まで、\nこんなに遠くはなかったはずです…",
  ui_story_1018_10180401_16_dialog_content = "今回の任務では依頼主から2つの確かな手がかりをもらっている。\nここはその謎を解くのに通らねばならない道なのだ。",
  ui_story_1018_10180401_17_dialog_content = "確かな手がかり？それは何ですか？",
  ui_story_1018_10180401_18_dialog_content = "1つは啓光防衛線の外にある各座標だ。\n我々の通過した場所はいずれも地図上に記載がある。",
  ui_story_1018_10180401_19_dialog_content = "つまり、決して妙な所を走っているわけではない。",
  ui_story_1018_10180401_20_dialog_content = "でも、この表示では…ずっと同じ所を走ってますよね！？",
  ui_story_1018_10180401_21_dialog_content = "シッ…遠方からの御客人を驚かしてしまったら、\n面倒な事になるぞ。",
  ui_story_1018_10180401_22_dialog_content = "あの3人のことですか？\nやはり長官もおかしいと思ってたんですね？",
  ui_story_1018_10180401_23_dialog_content = "隠し任務とでも言おうか。\n同じところを何度も走るのも任務の一部なのだよ。",
  ui_story_1018_10180401_24_dialog_content = "どこからともなく聞こえる声が私に告げているのだ。\n謎はまもなく明かされる、とね。",
  ui_story_1018_10180401_25_dialog_content = "また謎ですか…",
  ui_story_1018_10180401_26_dialog_content = "では、2つ目の手がかりとは何ですか？",
  ui_story_1018_10180401_27_dialog_content = "2つ目の手がかりは特殊な印のある地点を通過後、\n「暗面偵察隊」と通信した際の周波数だ。",
  ui_story_1018_10180401_28_dialog_content = "え？でも暗面偵察隊の位置信号はしばらく受け取ってませんよ？",
  ui_story_1018_10180401_29_dialog_content = "向こうの長官が通信機をオフにしてるんでしょうか？\nそれとも近くに電波を遮断するものでも？",
  ui_story_1018_10180401_30_dialog_content = "カロン長官…今ある情報を整理する必要があると思うのですが。\nでなければ任務を遂行できません！",
  ui_story_1018_10180401_31_dialog_content = "啓光の今の状況が心配です。",
  ui_story_1018_10180401_32_dialog_content = "その疑いを別のものに昇華させてみたらどうかしら？\n遠くから私が答えてあげれらるかもしれないわ。",
  ui_story_1018_10180401_33_dialog_content = "カロン長官、女性の声が…聞こえませんでしたか？",
  ui_story_1018_10180401_34_dialog_content = "耳元を通り過ぎていったな。",
  ui_story_1018_10180401_35_dialog_content = "ビクトリア様！",
  ui_story_1018_10180401_36_dialog_content = "ビクトリア様！ようやくいらっしゃいましたか！",
  ui_story_1018_10180401_37_dialog_content = "私のこと、覚えているかしら、啓光の車掌さん？\n他人の前では同族、もしくは…遠戚とは呼ばないほうがいいのでしょう？",
  ui_story_1018_10180401_38_dialog_content = "ビクトリア殿、おかしなことを言わないでもらいたい。\n君と3人の部下はいったい何を企んでいるのかな？",
  ui_story_1018_10180401_39_dialog_content = "ビクトリア…？ということは、3人は真理結社のメンバーなの？",
  ui_story_1018_10180401_40_dialog_content = "バイスさん、3人が旅のお邪魔をしていないかしら？",
  ui_story_1018_10180401_41_dialog_content = "それは…カロン長官に聞いて。\nずっと同じ所を走っていたのは、まさかあなたのせいなの？",
  ui_story_1018_10180401_42_dialog_content = "それだけではないわ。ただ私が加わったことで、\n真理を知る者だけを乗せた列車がようやく真の軌道に乗るの。",
  ui_story_1018_10180401_43_dialog_content = "バイスさんが今回の任務を受けたのも、\n啓光を訪れた、あの謎の客人に興味があるから…",
  ui_story_1018_10180401_44_dialog_content = "そしてトワイライトシティでいったい何が起こっているのか、\n興味があるからよね？",
  ui_story_1018_10180401_45_dialog_content = "啓光に潜入した者のことをどうして知ってるの？\nトワイライトシティで…いったい何が起こってるの…？",
  ui_story_1018_10180401_46_dialog_content = "だから、私の導きが必要なんでしょう？",
  ui_story_1018_10180401_47_dialog_content = "トワイライトシティで起こってることについては…\n空の末裔も啓光の新任大元帥もまだ生きる術をつかめていないようね。",
  ui_story_1018_10180401_48_dialog_content = "PlayerNameがトワイライトシティに！？",
  ui_story_1018_10180401_49_dialog_content = "大元帥のことは知ってたけど…\nトワイライトシティで危険な目に遭っているの…？",
  ui_story_1018_10180401_50_dialog_content = "あなたの思うトワイライトシティの状況があなたの中の彼らの状況を作り出すのよ。\n啓示が訪れるまでは、いくら心を砕こうと未知は未知のままよ。",
  ui_story_1018_10180401_51_dialog_content = "…カロン長官、今の話は本当ですか？\nPlayerNameと大元帥様は無事ですよね？",
  ui_story_1018_10180401_52_dialog_content = "…",
  ui_story_1018_10180401_53_dialog_content = "どう？ぬかるみを見に行ってみない？",
  ui_story_1018_10180401_54_dialog_content = "典籍の啓示では、このお嬢さんの運命の奇跡は…極夜に向いているけど――",
  ui_story_1018_10180401_55_dialog_content = "愛する者を忘れ、極夜に陥るものの、\n闇の刃がそれを助け、贖罪の儀式を終える。",
  ui_story_1018_10180401_56_dialog_content = "バイスさん、おめでとう。\nこの旅で真相を知ることになるわ。",
  ui_story_1018_10180401_57_dialog_content = "いったい…何のこと…？",
  ui_story_1018_10180401_58_dialog_content = "デタラメだ！この旅は運命などではない。\n啓光の軍人が果たすべき任務にすぎん。",
  ui_story_1018_10180401_59_dialog_content = "ビクトリア殿、我々の邪魔をしないでいただきたい。\nさもなければ、私も容赦しない。",
  ui_story_1018_10180401_60_dialog_content = "あら、結社のメンバーと一緒に行動していたのに、\n「空間リングゲージ」の存在を感じていなかったの？",
  ui_story_1018_10180401_61_dialog_content = "「空間リングゲージ」…同じ所を幾度も回っていたのは、\n君の仕業ではなかったというのか！？",
  ui_story_1018_10180401_62_dialog_content = "祖先の残した印もあなたの中では鈍くなってしまったようね。\nそろそろ啓示を受けるべき時よ。",
  ui_story_1018_10180401_63_dialog_content = "ある事情で、日蝕があなたたちを近づけないようにしているの。",
  ui_story_1018_10180401_64_dialog_content = "一定の距離を進むたびに「ふりだし」に戻る。\nそれが「空間リングゲージ」の力よ。",
  ui_story_1018_10180401_65_dialog_content = "「ふりだし」というのは決められた円形空間内の中心。\nあなたたちはその半径の範囲でしか動けないの。",
  ui_story_1018_10180401_66_dialog_content = "…どうしたらそんなことが？",
  ui_story_1018_10180401_67_dialog_content = "理由を追求する必要はないわ、バイスさん。\nそんなことをすれば、狂気に陥るわよ。",
  ui_story_1018_10180401_68_dialog_content = "でも私の導きがあれば、そんな状況から抜け出せる。\nここまで言っても、まだ私の同乗を拒むのかしら？車掌さん。",
  ui_story_1018_10180401_69_dialog_content = "…",
  ui_story_1018_10180401_70_dialog_content = "沈黙は許可だと理解したわ。\n加速して前進よ、車掌さん。",
  ui_story_1018_10180401_71_dialog_content = "カロン長官、よく分からないんですが、\n私たちは今、極夜の方向へ進んでるんですか？",
  ui_story_1018_10180401_72_dialog_content = "この列車はあなたの望む所を通過するのよ、バイスさん。",
  ui_story_1018_10180401_73_dialog_content = "私の望む所…？",
  ui_story_1018_10180401_74_dialog_content = "<color=#e8d9bb>ボッボーッ――！</color>",
  ui_story_1018_10180401_75_dialog_content = "踏ん張って――",
  ui_story_1018_10180401_76_dialog_content = "どうして急に強風が…？\n敵の攻撃の前触れじゃないよね…？",
  ui_story_1018_10180401_77_dialog_content = "アクセリアは部下を守ります…",
  ui_story_1018_10180401_78_dialog_content = "こんな強い風が吹いてるのに、ぬかるみはちっとも動かない…\nやはりおかしいわね…",
  ui_story_1018_10180401_79_dialog_content = "アクセリア、そっちの捜索で何か異常は見つかった？",
  ui_story_1018_10180401_80_dialog_content = "まさか「中心」の敵がまだ生きていて、\n潜伏しながら機会をうかがっているの…？",
  ui_story_1018_10180401_81_dialog_content = "<color=#e8d9bb>ブクブクブク――</color>",
  ui_story_1018_10180401_82_dialog_content = "団長、担当エリアの捜索は終わりました。\nこれから負傷者を病院に送ります。",
  ui_story_1018_10180401_83_dialog_content = "分かった。暗鬼の邪魔が入らなかったおかげで、\n予想よりもかなり順調に進んでいるな。",
  ui_story_1018_10180401_84_dialog_content = "<color=#e8d9bb>ブクブクブク――</color>",
  ui_story_1018_10180401_85_dialog_content = "アクセリア、奇妙な音が聞こえました…",
  ui_story_1018_10180401_86_dialog_content = "僕にも聞こえた。何かが水面に出てくる時の音みたいだった…",
  ui_story_1018_10180401_87_dialog_content = "グォォ…",
  ui_story_1018_10180401_88_dialog_content = "この声は…？",
  ui_story_1018_10180401_89_dialog_content = "大元帥様！大変です…担架に乗せた兵士が…",
  ui_story_1018_10180401_90_dialog_content = "どういうこと？",
  ui_story_1018_10180401_91_dialog_content = "身体に付着したぬかるみが動いている…\nまるで生き物のようだ。",
  ui_story_1018_10180401_92_dialog_content = "じゃあ、さっきの音は…",
  ui_story_1018_10180401_93_dialog_content = "うわああ――た…助けて！",
  ui_story_1018_10180401_94_dialog_content = "全員担架から離れて、私の周囲に集まりなさい！",
  ui_story_1018_10180401_95_dialog_content = "救助した時は何の問題もなかったのに…",
  ui_story_1018_10180401_96_dialog_content = "<color=#e8d9bb>ヒュ――</color>",
  ui_story_1018_10180401_97_dialog_content = "グォォ…",
  ui_story_1018_10180401_98_dialog_content = "待って…この風は…まさか襲撃なの！？",
  ui_story_1018_10180401_99_dialog_content = "急いで近くの物につかまりなさい――",
  ui_story_1018_10180401_100_dialog_content = "もう…立っていられない――",
  ui_story_1018_10180401_101_dialog_content = "PlayerName、私につかまれ！",
  ui_story_1018_10180401_102_dialog_content = "目が…まったく開かない…あ、新しい敵なの？",
  ui_story_1018_10180401_103_dialog_content = "<color=#e8d9bb>バチャン！</color>",
  ui_story_1018_10180401_104_dialog_content = "気を付けろ！ぬかるみが跳ね上がってくるぞ！",
  ui_story_1018_10180401_105_dialog_content = "ラス大元帥、後ろだ！",
  ui_story_1018_10180401_106_dialog_content = "見えたわ…ぬかるみだけじゃない…中に何かいる！",
  ui_story_1018_10180401_107_dialog_content = "グォォ！",
  ui_story_1018_10180401_108_dialog_content = "ぬかるみのなかに暗鬼の大群が潜んでるよ！",
  ui_story_1018_10180401_109_dialog_content = "やはりそうだったのね。暗鬼がぬかるみに乗って進攻してきたから、\n暗力の影響を受けた兵士も反応し始めたのね…",
  ui_story_1018_10180401_110_dialog_content = "グォォ！",
  ui_story_1018_10180401_111_dialog_content = "うわああ――た…助けて！",
  ui_story_1018_10180401_112_dialog_content = "ラス大元帥、奴らはもう正気じゃない。\n暗鬼として片付ける！",
  ui_story_1018_10180401_113_dialog_content = "違うわ…そんなことない…",
  ui_story_1018_10180401_114_dialog_content = "背後に暗鬼がいるのだ！\nこれ以上もたもたしていては全軍ぬかるみに飲まれるぞ！",
  ui_story_1018_10180401_115_dialog_content = "レオ…",
  ui_story_1018_10180401_116_dialog_content = "<color=#e8d9bb>ヒューッ、ボッボーッ――！</color>",
  ui_story_1018_10180401_117_dialog_content = "まずいわ、また来るわよ！",
  ui_story_1018_10180401_118_dialog_content = "汽笛の音も聞こえたような…",
  ui_story_1018_10180401_119_dialog_content = "カロン長官！地図の表示ではここはトワイライトシティです。",
  ui_story_1018_10180401_120_dialog_content = "ビクトリア殿、これも「空間リングゲージ」の仕業かな？\n我々がなぜここに？",
  ui_story_1018_10180401_121_dialog_content = "「空間リングゲージ」からはすでに逃れたわ。\nここへやってきたのはバイスさんの望みよ。",
  ui_story_1018_10180401_122_dialog_content = "円の半径内にちょうどトワイライトシティがあったの。",
  ui_story_1018_10180401_123_dialog_content = "このようなことが可能とは…",
  ui_story_1018_10180401_124_dialog_content = "カロン長官、前方に大勢の人が集まっています。\nPlayerNameたちじゃないでしょうか？",
  ui_story_1018_10180401_125_dialog_content = "列車の下は一面のぬかるみよ。\n中に潜む暗鬼に気を付けて。",
  ui_story_1018_10180401_126_dialog_content = "なんと汚らわしいぬかるみ、なんと汚らわしい暗鬼だ！\n彼岸号、すべてひき潰してしまえ！",
  ui_story_1018_10180401_127_dialog_content = "諸君、しっかりつかまりたまえ。\nぬかるみを貫き、前方に停車する！",
  ui_story_1018_10180401_128_dialog_content = "<color=#e8d9bb>ボッボーッ――！</color>",
  ui_story_1018_10180401_129_dialog_content = "おお！ラス大元帥ではありませぬか――",
  ui_story_1018_10180401_130_dialog_content = "大元帥就任おめでとうございます。\n遅れての参上をどうかお許しください。",
  ui_story_1018_10180401_131_dialog_content = "ラス大元帥様！PlayerName！",
  ui_story_1018_10180401_132_dialog_content = "バイス！",
  ui_story_1018_10180401_133_dialog_content = "カロン、バイス…なぜここへ！？",
  ui_story_1018_10180401_134_dialog_content = "あんたたちは任務中じゃなかったの？\nなぜトワイライトシティへ来たの？",
  ui_story_1018_10180401_135_dialog_content = "車掌さん、時間を守ってね。\nここは途中停車駅にすぎないわ。",
  ui_story_1018_10180401_136_dialog_content = "大元帥、トワイライトシティの戦局を聞きおよび、大変心配しておりました。\nですが、任務中なので長居はできません。",
  ui_story_1018_10180401_137_dialog_content = "暗鬼の群れをひき潰してくれて、助かったわ。",
  ui_story_1018_10180401_138_dialog_content = "ただ、さっきの強風は敵ではなく、\nあんたたちだったの…？",
  ui_story_1018_10180401_139_dialog_content = "ここへ来たのは決して偶然ではありませんが、詳しく説明している時間がありません。\nぬかるみはまだ長く続いていて、多くの暗鬼が潜んでいる可能性がありますぞ。",
  ui_story_1018_10180401_140_dialog_content = "ビクトリア様、強風です…\n「空間リングゲージ」が再び現れたということでしょうか…？",
  ui_story_1018_10180401_141_dialog_content = "どこまでも追いかけてくるつもりかしら…\n座って待ってなさい。私が連れ出してあげるわ。",
  ui_story_1018_10180401_142_dialog_content = "この距離だと、20秒ね。",
  ui_story_1018_10180401_143_dialog_content = "ビクトリア様、カウントダウンを始めます…",
  ui_story_1018_10180401_144_dialog_content = "バイス、ここへ来るまで危険な目には遭わなかった？",
  ui_story_1018_10180401_145_dialog_content = "トワイライトシティに比べたら…\n私たちの経験した危険なんて大したことないわ。",
  ui_story_1018_10180401_146_dialog_content = "ただ道中ビクトリアさんがずっと謎めいたことを話してて、\n何が何だかよく分からなかった…",
  ui_story_1018_10180401_147_dialog_content = "とにかく気を付けるんだよ。\n真理結社も出てきたなんて嫌な予感がする…",
  ui_story_1018_10180401_148_dialog_content = "あなたまでどうしたの？訳の分からないことを言って…",
  ui_story_1018_10180401_149_dialog_content = "ビクトリアさん、実際は私たちを助けてくれてるのよ。",
  ui_story_1018_10180401_150_dialog_content = "それもカロンの考えだっていうなら…",
  ui_story_1018_10180401_151_dialog_content = "15、14、13…",
  ui_story_1018_10180401_152_dialog_content = "10、9…",
  ui_story_1018_10180401_153_dialog_content = "…大元帥、必ずや持ちこたえるのですぞ。\n皆無事の帰還を待っています！",
  ui_story_1018_10180401_154_dialog_content = "もちろんよ。あんたも任務を完了して、\n無事に啓光に戻ってきなさい。",
  ui_story_1018_10180401_155_dialog_content = "5、4、3…",
  ui_story_1018_10180401_156_dialog_content = "僕が言ったこと覚えてる？",
  ui_story_1018_10180401_157_dialog_content = "…覚えてるわ。\n危険な目に遭ったら、あなたを呼べばいいのよね。",
  ui_story_1018_10180401_158_dialog_content = "2、1、0。",
  ui_story_1018_10180401_159_dialog_content = "それではまた会いましょう。",
  ui_story_1018_10180401_160_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1018_10180401_161_dialog_content = "皆…消えちゃった！？",
  ui_story_1018_10180401_162_dialog_content = "…不思議ね。私の光力術に関する理解を越えているわ。",
  ui_story_1018_10180401_163_dialog_content = "グォォ！",
  ui_story_1018_10180401_164_dialog_content = "大元帥様！騎士団では兵士たちを抑えきれなくなっています…",
  ui_story_1018_10180401_165_dialog_content = "もうなす術はないの…？",
  ui_story_1018_10180401_166_dialog_content = "団長、我々が立ち向かっている敵はいったい誰なのか、\n皆が疑問を持っています。",
  ui_story_1018_10180401_167_dialog_content = "大元帥の部下だ。同時に目の前のこの残忍な暗鬼たちでもある…",
  ui_story_1018_10180401_168_dialog_content = "いくら止めても、これ以上はもう譲れん。",
  ui_story_1018_10180401_169_dialog_content = "私の部下を傷つけた者はこの私が葬ってやる！",
  ui_story_1018_10180401_170_dialog_content = "騎士団よ、続け！奴らを片付ける！",
  ui_story_1018_10180401_171_dialog_content = "…はい！",
  ui_story_1018_10180401_X171_dialog_content = "突然強風が吹いてきた…敵の攻撃の前触れ…？",
  ui_story_1018_10180401_X172_dialog_content = "暗鬼の数が増えているわね。でも捜索は続けられるわ。\n何か異常は見つかった？",
  ui_story_1018_10180401_X173_dialog_content = "大元帥様、私の担当エリアの捜索には影響ありません。",
  ui_story_1018_10180401_X174_dialog_content = "大元帥、アクセリアの担当エリア内では、\n暗鬼が大量に出現しましたが、すでに片づけました。",
  ui_story_1018_10180401_X175_dialog_content = "大元帥様、レオ団長の担当するぬかるみエリアの状況が\n芳しくないようです。",
  ui_story_1018_10180401_X176_dialog_content = "分かったわ…各自十分注意するように。\nちょっと見てくるわ。",
  ui_story_1018_10180401_X177_dialog_content = "団長、負傷者は全員担架に乗せました。\nまずは病院に送り届けてきます。",
  ui_story_1018_10180401_X178_dialog_content = "うむ。兵士の状態に注意するのだぞ。ぬかるみが再び動きだし、暗鬼も増えている。\n奴らが大挙して攻撃してくる前に撤退するぞ。",
  ui_story_1018_10180401_X179_dialog_content = "はい、団長。",
  ui_story_1018_10180401_X180_dialog_content = "おかしな音が聞こえました…兵士の身体から聞こえてきます。",
  ui_story_1018_10180401_X181_dialog_content = "それ以上近づくな。ぬかるみの中から救い出した兵士たちだ。",
  ui_story_1018_10180401_X182_dialog_content = "泥が兵士たちの身体の上を流れ、\nまるで生き物かのようだが…",
  ui_story_1018_10180401_X183_dialog_content = "今はどうしたらこの泥を落とせるのか、分からないのだ…",
  ui_story_1018_10180401_X184_dialog_content = "グォォ…",
  ui_story_1018_10180401_X185_dialog_content = "グォォ…",
  ui_story_1018_10180401_X186_dialog_content = "大元帥様、負傷者たちの状況に異変です！",
  ui_story_1018_10180401_X187_dialog_content = "身体にまとわりついた泥の動きが速くなってる？",
  ui_story_1018_10180401_X188_dialog_content = "動きが速くなってる？\nだったら考えられることは…",
  ui_story_1018_10180401_X189_dialog_content = "気を付けろ！ぬかるみが跳ね上がってくるぞ！",
  ui_story_1018_10180401_X190_dialog_content = "ぬかるみだけじゃない…中に何かいるわよ！",
  ui_story_1018_10180401_X191_dialog_content = "グォォ！",
  ui_story_1018_10180401_X192_dialog_content = "やはりそうだったのね。暗鬼がぬかるみに乗って進攻してきたから、\n暗力の影響を受けた兵士にも異変が…",
  ui_story_1018_10180401_X193_dialog_content = "…騎士団第一隊、医療隊を援護、\nその他の隊は戦闘準備だ！",
  ui_story_1018_10180401_X194_dialog_content = "了解です！",
  ui_story_1018_10180401_X195_dialog_content = "<color=#e8d9bb>ヒューッ――</color>",
  ui_story_1018_10180401_X196_dialog_content = "まただわ…まさか敵襲なの！？",
  ui_story_1018_10180401_X197_dialog_content = "もう…立っていられない――",
  ui_story_1018_10180401_X198_dialog_content = "急いで近くの物につかまりなさい――",
  ui_story_1018_10180401_X199_dialog_content = "目が…まったく開かない…あ、新しい敵なの？",
  ui_story_1018_10180401_X200_dialog_content = "PlayerName、私につかまれ！",
  ui_story_1018_10180401_X201_dialog_content = "<color=#e8d9bb>ヒューッ、ボッボーッ――！</color>",
  ui_story_1018_10180401_X202_dialog_content = "PlayerName、大丈夫？",
  ui_story_1018_10180401_X203_dialog_content = "汽笛の音が…聞こえたような…",
  ui_story_1018_10180401_X204_dialog_content = "見間違いじゃないわよね！？\n土だらけになって立ってるのは…PlayerName！？",
  ui_story_1018_10180401_X205_dialog_content = "カロン長官、私たちトワイライトシティに来たんですか？\nいったいどうやって…",
  ui_story_1018_10180401_X206_dialog_content = "「空間リングゲージ」…実に面白いわ。\nでも、さらに面白いのはバイスさんの望むままにここまで列車を導けたことね。",
  ui_story_1018_10180401_X207_dialog_content = "このようなことが可能とは…",
  ui_story_1018_10180401_X208_dialog_content = "言っている意味がよく分からないけど…この先で止めてもらえるかしら？\nPlayerNameたちが危険みたい…",
  ui_story_1018_10180401_X209_dialog_content = "にごったぬかるみと群れになった暗鬼に\n今にも取り囲まれそうよ…",
  ui_story_1018_10180401_X210_dialog_content = "残念だけど、ここは目的地ではないの。\n「空間リングゲージ」を抜けるまで列車は止められないわ。",
  ui_story_1018_10180401_X211_dialog_content = "こんなに近くまで来ているのに…\nカロン長官、何かできませんか？",
  ui_story_1018_10180401_X212_dialog_content = "途中停車が無理ならば…",
  ui_story_1018_10180401_X213_dialog_content = "汚らわしいぬかるみと暗鬼をことごとくこの彼岸号で\nひき潰してしまおうではないか！諸君、しっかりつかまりたまえ！",
  ui_story_1018_10180401_X214_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1018_10180401_X215_dialog_content = "グアアア――",
  ui_story_1018_10180401_X216_dialog_content = "団長！今のは…列車ですか？\nぬかるみの中の暗鬼をほぼ消滅させてしまいました！",
  ui_story_1018_10180401_X217_dialog_content = "…啓光の科学技術のようだな。\nともかく急いで医療隊の様子を確認するのだ。",
  ui_story_1018_10180401_X218_dialog_content = "了解です！",
  ui_story_1018_10180401_X219_dialog_content = "間違いない…あれはカロンの彼岸号だ…\nバイスの姿も見えた気がする…",
  ui_story_1018_10180401_X220_dialog_content = "2人がなぜここに？しかも一瞬で立ち去ってしまったわ。",
  ui_story_1018_10180401_X221_dialog_content = "分からない…僕がトワイライトシティに来る前、\nバイスとカロンは先に任務で暗面へ発ったはずだけど…",
  ui_story_1018_10180401_X222_dialog_content = "ちょうどいい時に現れて、暗鬼まで片付けて行ってくれたわ…\n確かに何かおかしいけど…",
  ui_story_1018_10180401_X223_dialog_content = "大元帥様、ご報告いたします！\n行方不明にだった部隊がまた1隊見つかりました！",
  ui_story_1018_10180401_X224_dialog_content = "分かった、すぐ行くわ。",
  ui_story_1018_10180401_X225_dialog_content = "PlayerName、バイスたちは私たちには理解できない事に巻き込まれているのかもしれない。\nでもそれは彼ら自身で解決すべきこと。私は2人を信じているわ。",
  ui_story_1018_10180401_X226_dialog_content = "こっちもまず目の前の危機を片付けましょう。",
  ui_story_1018_10180401_X227_dialog_content = "うん。バイスたちも順調に行くことを願うよ。",
  ui_story_1018_10180401_X228_dialog_content = "（バイス、絶対に無事でいてよ）",
  ui_story_1018_10180501_1_dialog_content = "<color=#e8d9bb>列車は未知の空間の空中に停車した…</color>",
  ui_story_1018_10180501_2_dialog_content = "ミンチ！早く袖をどけてください、窒息しそうでしたよ！",
  ui_story_1018_10180501_3_dialog_content = "あれれ、見て見て！鈴が光ってるよ…\nこれって成功したってこと！？",
  ui_story_1018_10180501_4_dialog_content = "そのようですね…ねっとりとした物質がまぶたに当たっています。\nこの感覚は間違いありません。",
  ui_story_1018_10180501_5_dialog_content = "ビクトリア様、ここって…",
  ui_story_1018_10180501_6_dialog_content = "光もなく闇もない、真理のみが存在する所…我が秘境よ。",
  ui_story_1018_10180501_7_dialog_content = "おお！ひざまずき、主の御声に耳を傾けさせてください！",
  ui_story_1018_10180501_8_dialog_content = "これが真理の御声を聞く痛みなのですね。\nしっかり覚えておきます、心静かに拝聴いたします！",
  ui_story_1018_10180501_9_dialog_content = "あの…私たちにも分かる言葉で話してくれない？\nここはいったいどこなの？",
  ui_story_1018_10180501_10_dialog_content = "心配はいらないわ。「空間リングゲージ」からはもう逃れたから。",
  ui_story_1018_10180501_11_dialog_content = "つまり、私たちを助けてくれたの？",
  ui_story_1018_10180501_12_dialog_content = "すべては導きに従ったまでのこと――",
  ui_story_1018_10180501_13_dialog_content = "ビクトリア様！鮮血が「見え」ました！",
  ui_story_1018_10180501_14_dialog_content = "わ、私には生々しい言葉が「聞こえ」ました。\n耳に刺さるような痛みです！",
  ui_story_1018_10180501_15_dialog_content = "…黒の典籍が今啓示を下すなんて…",
  ui_story_1018_10180501_16_dialog_content = "文字が急速に変化しているわ。前途がかすかに姿を現し始めた…",
  ui_story_1018_10180501_17_dialog_content = "「行動の後、敗北が訪れる」",
  ui_story_1018_10180501_18_dialog_content = "これがいわゆる「日蝕はその尾を伸ばし、極光が射す時、\nかの者は帰途に就く」なのかしら？",
  ui_story_1018_10180501_19_dialog_content = "いえ、違う…文字はまだ変化している…",
  ui_story_1018_10180501_20_dialog_content = "「挫折の後、偉大なる快挙が訪れる」",
  ui_story_1018_10180501_21_dialog_content = "ということは「光霊は災難に見舞われし時、\nかの者とまみえ、極光がそれを阻む」…",
  ui_story_1018_10180501_22_dialog_content = "何の啓示かしら…",
  ui_story_1018_10180501_23_dialog_content = "ビクトリア様！粘り強い恨みが主の瞳の中を流れています…",
  ui_story_1018_10180501_24_dialog_content = "ディシス、目を閉じなさい！\nそれは主の眼差しではないわ、主に恨みはないのよ！",
  ui_story_1018_10180501_25_dialog_content = "みんな、息を止めなさい。",
  ui_story_1018_10180501_26_dialog_content = "…",
  ui_story_1018_10180501_27_dialog_content = "カロン長官！計器盤にかすかな信号反応が…",
  ui_story_1018_10180501_28_dialog_content = "「暗面探索隊」が送ってきた座標だ。\nこの位置は…地図上にはないな。",
  ui_story_1018_10180501_29_dialog_content = "そこは<color=#FFB400>真実の地</color>ではなく、\n啓示にあった「捨てられた故郷、帰途の起点」だからよ。",
  ui_story_1018_10180501_30_dialog_content = "どういう意味なの？探索隊とは合流できるの？",
  ui_story_1018_10180501_31_dialog_content = "光と闇の争いに決着のつく時がやってきたようね。\n真理の主は必ず降臨なさるわ。",
  ui_story_1018_10180501_32_dialog_content = "その瞬間を見守るためにも、\nあなたたちを目的地まで送ってあげましょう。",
  ui_story_1018_10180501_33_dialog_content = "ただし、車掌さん。あなたの助けが必要よ。",
  ui_story_1018_10180501_34_dialog_content = "…",
  ui_story_1018_10180501_35_dialog_content = "カロン長官、とても不安です…",
  ui_story_1018_10180501_36_dialog_content = "ビクトリアさんの秘境…何かに押しつぶされるような圧迫感で…\n息をするのも苦しいんです…",
  ui_story_1018_10180501_37_dialog_content = "私も…同じだ――",
  ui_story_1018_10180501_38_dialog_content = "やはり来たわね…",
  ui_story_1018_10180501_39_dialog_content = "アネモネはいったい何をしていたのでしょう？\nまだ生きてるではないですか。",
  ui_story_1018_10180501_40_dialog_content = "…誰が話してるの？",
  ui_story_1018_10180501_41_dialog_content = "あなたからは私の嫌いな匂いがします。\nですが、思い出せませんね…何の匂いだったでしょう…？",
  ui_story_1018_10180501_42_dialog_content = "汚らわしいバケモノめ！私の部下から離れるのだ！",
  ui_story_1018_10180501_43_dialog_content = "あなたに興味はありませんよ。ただこちらの金髪の女性は…\nどうやら面白いものをお持ちのようですね。",
  ui_story_1018_10180501_44_dialog_content = "罪悪の下僕は、真の知を前に震えるしかないのよ。",
  ui_story_1018_10180501_45_dialog_content = "おや、あなたたちのほうこそ震えているようですよ？\n目を閉じて何をしているのです？",
  ui_story_1018_10180501_46_dialog_content = "…鮮血を捧げます。\n真理の主よ、どうかご加護を賜りますよう。",
  ui_story_1018_10180501_47_dialog_content = "ほう、何かの儀式ですか？",
  ui_story_1018_10180501_48_dialog_content = "貴様の相手は私だ。\n正体を明かさぬ悪人よ、業火の味を思い知るがいい！",
  ui_story_1018_10180501_49_dialog_content = "信者ディシス、生けにえを捧げました。",
  ui_story_1018_10180501_50_dialog_content = "痛みをささげた者は、主が真理へとお導きになる。",
  ui_story_1018_10180501_51_dialog_content = "信者メリー、生けにえを捧げました。",
  ui_story_1018_10180501_52_dialog_content = "私がお手伝いしましょう。効率が上がりますよ。",
  ui_story_1018_10180501_53_dialog_content = "奇跡をその目に焼き付けよ！",
  ui_story_1018_10180501_54_dialog_content = "儀式はまもなく終了よ。車掌さん――",
  ui_story_1018_10180501_55_dialog_content = "カロン長官、だ、大丈夫ですか？",
  ui_story_1018_10180501_56_dialog_content = "しっかりつかまっているのだぞ！\n三途の列車が出発する！方向転換、下方向へ前進！",
  ui_story_1018_10180501_57_dialog_content = "足が…完全に宙に浮いてる！？",
  ui_story_1018_10180501_58_dialog_content = "霊獣を捧げる。主よ、謎を明らかにしたまえ。",
  ui_story_1018_10180501_59_dialog_content = "信者ミンチ、生けにえを捧げました。",
  ui_story_1018_10180501_60_dialog_content = "逃げる気ですか？",
  ui_story_1018_10180501_61_dialog_content = "主よ、どうか生けにえを受け取り、我が鮮血の力を奪い、\n深紅の真理をこの世に現したまえ！",
  ui_story_1018_10180501_62_dialog_content = "神は現れた――ファントムの領域を抜けたわよ。",
  ui_story_1018_10180501_63_dialog_content = "諸君、しっかりつかまっていたまえ――",
  ui_story_1018_10180501_64_dialog_content = "む、無理です…身体が…\nものすごいスピードで落ちていきます――",
  ui_story_1018_10180501_65_dialog_content = "暗面に向かう途中、<color=#FFB400>冥流の川</color>、\n別名<color=#FFB400>忘却の荒野</color>を通過しなければいけないわ。",
  ui_story_1018_10180501_66_dialog_content = "光が見えるまでは目を閉じていてね。\n危険に感知されてしまわないように。",
  ui_story_1018_10180501_67_dialog_content = "でも目を閉じると、\n暗鬼の群れが向かってくるのが見えるわ…",
  ui_story_1018_10180501_68_dialog_content = "それはあなたの意識の中の情景よ。\n本当の敵ではないわ。",
  ui_story_1018_10180501_69_dialog_content = "でも…啓光の…啓光の兵士が…",
  ui_story_1018_10180501_70_dialog_content = "機械に食らいついているの…",
  ui_story_1018_10180501_71_dialog_content = "兵士同士で殺し合ってる…",
  ui_story_1018_10180501_72_dialog_content = "それに…真っ黒なぬかるみが\n暗面から啓光の防衛線まで伸びているのが見えるわ…",
  ui_story_1018_10180501_73_dialog_content = "（立ち去りなさい。近づいてはいけません）",
  ui_story_1018_10180501_74_dialog_content = "（あなたは…あなたはいったい誰なの？）",
  ui_story_1018_10180501_75_dialog_content = "（立ち去りなさい。近づいてはいけません）",
  ui_story_1018_10180501_76_dialog_content = "（でも、感じる…何か奇妙な力が私を駆り立てる…）",
  ui_story_1018_10180501_77_dialog_content = "バイス？",
  ui_story_1018_10180501_78_dialog_content = "立ち去れと忠告する声が聞こえます…",
  ui_story_1018_10180501_79_dialog_content = "聞いても見てもいけないわ。\nでないと二度と目覚めることができなくなるのよ。",
  ui_story_1018_10180501_80_dialog_content = "誰だかよく分からないわ…でも…声も、鼓動も…\n間近に聞こえる…",
  ui_story_1018_10180501_81_dialog_content = "まるで…私が彼女になったかのように…",
  ui_story_1018_10180501_82_dialog_content = "それは危険が迫っている合図ね。",
  ui_story_1018_10180501_83_dialog_content = "（PlayerNameが言ってたわ。\n危険な目に遭った時は名前を呼べばいいって）",
  ui_story_1018_10180501_84_dialog_content = "（本当に聞こえるかもしれない…）",
  ui_story_1018_10180501_85_dialog_content = "（立ち去りなさい。危険です）",
  ui_story_1018_10180501_86_dialog_content = "（でも、どうにかしてあなたの正体を確めたい…）",
  ui_story_1018_10180501_87_dialog_content = "（だってこんなに誰かを近くに感じたのは初めてだもの…）",
  ui_story_1018_10180501_88_dialog_content = "（…）",
  ui_story_1018_10180501_89_dialog_content = "（…この音は…？）",
  ui_story_1018_10180501_90_dialog_content = "（バイスの鼓動だ…）",
  ui_story_1018_10180501_91_dialog_content = "（きっとバイスに危険が…）",
  ui_story_1018_10180501_92_dialog_content = "PlayerName！後ろに気を付けなさい！",
  ui_story_1018_10180601_1_dialog_content = "グォォ…",
  ui_story_1018_10180601_2_dialog_content = "大元帥様、ご命令を…頭に照準を合わせました…",
  ui_story_1018_10180601_X2_dialog_content = "銃を下ろしなさい。",
  ui_story_1018_10180601_X3_dialog_content = "しかし…そいつは第九部隊の指揮官でありながら、これだけ多くの仲間を殺し、\n今また大元帥様を手にかけようとしているのですよ！もう啓光の軍人ではありません！",
  ui_story_1018_10180601_X4_dialog_content = "やりたくてやってるわけじゃないわ。\n目を見れば分かるの…まだ意識があるわ。",
  ui_story_1018_10180601_X5_dialog_content = "大元帥様！騎士団がもう兵士たちを抑えられなくなっています…\nこのままでは私たち全員が危険です…",
  ui_story_1018_10180601_3_dialog_content = "第九部隊の指揮官ですが、これだけの数の仲間を殺したんです。\nもう啓光の軍人ではありません！",
  ui_story_1018_10180601_4_dialog_content = "目を見れば分かるのよ。まだ意識があるわ！",
  ui_story_1018_10180601_5_dialog_content = "よく見なさい、あなたの上官、大元帥よ。\n手を放しなさい！",
  ui_story_1018_10180601_6_dialog_content = "…大元帥様。",
  ui_story_1018_10180601_7_dialog_content = "本当に言葉が届くとは…",
  ui_story_1018_10180601_8_dialog_content = "啓光に一緒に帰りましょう。こんな所で死んではダメ。",
  ui_story_1018_10180601_9_dialog_content = "…",
  ui_story_1018_10180601_10_dialog_content = "彼の身体は暗力に完全に支配されている。\nこのままでは部下に首をへし折られるぞ。",
  ui_story_1018_10180601_11_dialog_content = "グォォ…",
  ui_story_1018_10180601_12_dialog_content = "（体内のエネルギーが…呼び覚まされたかのようだわ…）",
  ui_story_1018_10180601_13_dialog_content = "（部下を殺したい衝動にかられるとは…）",
  ui_story_1018_10180601_14_dialog_content = "ラス、君が前にそうなったように、\nこの人も意識の中に沈んでるんだ。だから気持ちを抑えて…",
  ui_story_1018_10180601_15_dialog_content = "感知能力を使わせてくれないかな？",
  ui_story_1018_10180601_16_dialog_content = "彼の意識がどういう状況かも分からないのよ。\nあんたが危険にさらされるかもしれないわ。",
  ui_story_1018_10180601_17_dialog_content = "でも、今はそれしか方法が…",
  ui_story_1018_10180601_18_dialog_content = "危ないと思ったら、すぐに感知を止めるよ。\nだから僕を信じて。",
  ui_story_1018_10180601_19_dialog_content = "…もしあんたを傷つけるようなら、\n私、もう迷わないわ…",
  ui_story_1018_10180601_20_dialog_content = "うん…",
  ui_story_1018_10180601_21_option_content = "感知を試す",
  ui_story_1018_10180601_22_dialog_content = "（意識の中だね…ここは…啓光のシェルターだ…）",
  ui_story_1018_10180601_23_dialog_content = "（居住区かな…洗濯物のいい匂いまで感じる…）",
  ui_story_1018_10180601_24_dialog_content = "母さん、千載一遇のチャンスなんだ！",
  ui_story_1018_10180601_25_dialog_content = "（お母さんとケンカしてるのかな…）",
  ui_story_1018_10180601_26_dialog_content = "ラス軍団長は1つの目標に何度も挑んで、\nそうやって今の地位に上りつめたんだよ！",
  ui_story_1018_10180601_27_dialog_content = "今回の育成計画を逃したら、\n大元帥になるっていう僕の夢がついえてしまう！",
  ui_story_1018_10180601_28_dialog_content = "ラス軍団長は僕の能力を認めてくれてる。\nもっと高い地位にだってのぼれるって言ってくれたんだ！",
  ui_story_1018_10180601_29_dialog_content = "将軍になって…次々と勝利をおさめて…\nあなたの父さんもそうだった。今度はあなたまで…",
  ui_story_1018_10180601_30_dialog_content = "あなたは父さんに似て、胆力もあれば知恵もある。\n母さんの一番は永遠にあなただけよ…",
  ui_story_1018_10180601_31_dialog_content = "でもね…その育成計画、とても苦しいものだって聞いたの…",
  ui_story_1018_10180601_32_dialog_content = "訓練についていけなかった場合、\nもう二度と戦場には出られないって…",
  ui_story_1018_10180601_33_dialog_content = "だから、母さんのそばにいてちょうだい。\n母さんにはもうあなたたちしかいないのよ…",
  ui_story_1018_10180601_34_dialog_content = "母さん…私はお兄ちゃんを信じる…",
  ui_story_1018_10180601_35_dialog_content = "ありがとう！だから母さんも僕を信じてくれ。\n絶対に訓練を乗り越えてみせるよ！",
  ui_story_1018_10180601_36_dialog_content = "ずっとカナン城にいても未来はない。\n軍人は戦場に出てこそ軍人だ。死など恐れはしない！",
  ui_story_1018_10180601_37_dialog_content = "ああ…そんな縁起でもないこと言わないでちょうだい…",
  ui_story_1018_10180601_38_dialog_content = "とにかく決めたんだ！",
  ui_story_1018_10180601_39_dialog_content = "（…）",
  ui_story_1018_10180601_40_dialog_content = "（お母さんが今の状況を知ったら、どう思うかな…）",
  ui_story_1018_10180601_41_dialog_content = "（あ！話を聞くのに夢中になっちゃった！）",
  ui_story_1018_10180601_42_dialog_content = "（あれ？別の場所に変わった。照明がまぶしいな…）",
  ui_story_1018_10180601_43_dialog_content = "教授、これが「啓明の星計画」の最終試験ですか？",
  ui_story_1018_10180601_44_dialog_content = "そうです。これが最後です。",
  ui_story_1018_10180601_45_dialog_content = "制約は一切ありません。唯一やるべきことは\nこれからやってくる敵に打ち勝ち、生き残ることです。",
  ui_story_1018_10180601_46_dialog_content = "（待って！早くここを離れるんだ！）",
  ui_story_1018_10180601_47_dialog_content = "（母さん？どうして来たんだ…もう決めたって言ったろ？\n止めないでくれ…）",
  ui_story_1018_10180601_48_dialog_content = "（僕をお母さんだと勘違いしてる…？だったら…）",
  ui_story_1018_10180601_49_dialog_content = "（教授の言うことを聞いちゃダメだ。計画に参加すれば、\n君は暗鬼になっちゃうんだ！お母さんはそんなこと望んでない！）",
  ui_story_1018_10180601_50_dialog_content = "（大丈夫だよ、母さん…教授が言ってた、僕には才能があるって。\n必ず合格してみせるよ）",
  ui_story_1018_10180601_51_dialog_content = "準備ができ次第、始めましょうか。",
  ui_story_1018_10180601_52_dialog_content = "（だまされてるんだよ！今君はトワイライトシティの戦場にいる！）",
  ui_story_1018_10180601_53_dialog_content = "（目の前にいるのは敵じゃない、上官のラスだ。\n早くこの部屋から出るんだ！）",
  ui_story_1018_10180601_54_dialog_content = "（ラス大元帥もいるのか？）",
  ui_story_1018_10180601_55_dialog_content = "（トワイライトシティ…行ったことがあるような…）",
  ui_story_1018_10180601_56_dialog_content = "迷っているのですか？",
  ui_story_1018_10180601_57_dialog_content = "いいえ…教授。始めてください。",
  ui_story_1018_10180601_58_dialog_content = "（お願いだよ！目を覚まして！）",
  ui_story_1018_10180601_59_dialog_content = "（母さん、見ててくれ。僕は勇敢な戦士になるんだ）",
  ui_story_1018_10180601_60_dialog_content = "グォォ！！！",
  ui_story_1018_10180601_61_dialog_content = "（待って！目を覚まして！戦っちゃいけない！）",
  ui_story_1018_10180601_62_dialog_content = "教授、暗鬼を見た途端…体中に力があふれてくる感じがします。",
  ui_story_1018_10180601_63_dialog_content = "そうです、その調子ですよ。力を感じ、力をコントロールするのです。",
  ui_story_1018_10180601_64_dialog_content = "グォォ！！！",
  ui_story_1018_10180601_65_dialog_content = "暗鬼は…死ね！",
  ui_story_1018_10180601_66_dialog_content = "（どうしよう…感知を切らなかったら、たぶん…）",
  ui_story_1018_10180601_67_dialog_content = "死ね！！",
  ui_story_1018_10180601_68_dialog_content = "グォォ！！！",
  ui_story_1018_10180601_69_dialog_content = "<color=#e8d9bb>グォォ！！</color>",
  ui_story_1018_10180601_70_dialog_content = "大変です！彼のうめき声に他の兵士も反応しているようです！",
  ui_story_1018_10180602_1_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_1018_10180602_2_dialog_content = "…",
  ui_story_1018_10180602_3_dialog_content = "大元帥様、申し訳ありません。こうするしかありませんでした。",
  ui_story_1018_10180602_4_dialog_content = "大丈夫か、PlayerName？",
  ui_story_1018_10180602_5_dialog_content = "ごめん、助けてあげられなかった…",
  ui_story_1018_10180602_6_dialog_content = "優秀な兵士だったのに…",
  ui_story_1018_10180602_7_dialog_content = "アクセリア、とても辛いです…",
  ui_story_1018_10180602_8_dialog_content = "…遠くの数名の兵士はどうするつもりだ？",
  ui_story_1018_10180602_9_dialog_content = "…",
  ui_story_1018_10180602_10_dialog_content = "自分の部下をこの手で殺すなんて、\n啓光大元帥たる資格はないわ…",
  ui_story_1018_10180602_11_dialog_content = "（いったいどうすれば…）",
  ui_story_1018_10180602_12_dialog_content = "（あんただったら、どうする？レインハト…）",
  ui_story_1018_10180602_13_dialog_content = "私がやろう――",
  ui_story_1018_10180602_14_dialog_content = "レオ…",
  ui_story_1018_10180602_15_dialog_content = "私が暴走した兵士を倒すと頑固に意見を押し通し、\n止められなかったということにすればいい。",
  ui_story_1018_10180602_16_dialog_content = "私はトワイライトシティを守るため駐留する一騎士にすぎん。\n大元帥のように陣営までは背負っていない。",
  ui_story_1018_10180602_17_dialog_content = "情に流されれば、こちらの損失は大きくなるばかりだ。\nあなたも現実に向き合うことを学べ。",
  ui_story_1018_10180602_18_dialog_content = "いいえ…私にはこんなにもたくさんの命を\n預かる器がなかったのよ…",
  ui_story_1018_10180602_19_dialog_content = "部下たちと一緒にトワイライトシティの戦いに勝つと誓ったのに…",
  ui_story_1018_10180602_20_dialog_content = "皆…私のせいで…命を落としたわ…",
  ui_story_1018_10180602_21_dialog_content = "（自分に力があれば、自分が強ければ、\nどんなことでも成し遂げられると思ってた）",
  ui_story_1018_10180602_22_dialog_content = "（強ければ、ね…アハハ…）",
  ui_story_1018_10180602_23_dialog_content = "ラス、君が今やっていることは、\n強くなることよりもずっと難しいことだと思う。",
  ui_story_1018_10180602_24_dialog_content = "…",
  ui_story_1018_10180602_25_dialog_content = "戦士とはそもそもその身を挺して危険を阻むのが務めだ。",
  ui_story_1018_10180602_26_dialog_content = "その戦士たちが危険そのものになり、\n自身の生死を選べなくなった時――",
  ui_story_1018_10180602_27_dialog_content = "代わりに選んでやることが、\n将である我々が彼らのために唯一してやれることだ…",
  ui_story_1018_10180602_28_dialog_content = "将として…",
  ui_story_1018_10180602_29_dialog_content = "（これもあんたの言う、握りしめた手を開けってことなの？\nレインハト…）",
  ui_story_1018_10180602_30_dialog_content = "あなたの部下は決して無駄死にではない。\n彼らの苦しみはまもなく終わる。",
  ui_story_1018_10180602_31_dialog_content = "待って、レオ。",
  ui_story_1018_10180602_32_dialog_content = "あんたの言う通りかもしれない…\n部下たちは…無駄死にじゃない…",
  ui_story_1018_10180602_33_dialog_content = "私も現実に向き合わなければ…",
  ui_story_1018_10180602_34_dialog_content = "このまま部下が苦しむくらいなら、\n私が、その苦しみを絶ってやるわ。",
  ui_story_1018_10180602_35_dialog_content = "大元帥様…",
  ui_story_1018_10180602_36_dialog_content = "あんたたちのかつての戦友に、最後に一言言わせてちょうだい…",
  ui_story_1018_10180602_37_dialog_content = "何があろうと大元帥様について行きます！",
  ui_story_1018_10180602_38_dialog_content = "…",
  ui_story_1018_10180602_39_dialog_content = "私の言葉が分からないとしても、\n今ここであんたたちに約束するわ――",
  ui_story_1018_10180602_40_dialog_content = "あんたたちは皆、啓光の軍人よ。\n生まれながらにして啓光軍人の栄光をまとい、暗鬼を倒す使命を負ってきた。",
  ui_story_1018_10180602_41_dialog_content = "戦場は常に死と隣合わせだと知りながら、\n恐れることなく進み続けてきた…",
  ui_story_1018_10180602_42_dialog_content = "あんたたちは、勇敢な啓光の兵士として犠牲になる…",
  ui_story_1018_10180602_43_dialog_content = "決して見捨てられたわけじゃない…",
  ui_story_1018_10180602_44_dialog_content = "あんたたちの果たせなかった使命は私たちが引き継ぎ、\nこれからも戦い続ける！",
  ui_story_1018_10180602_45_dialog_content = "グォォ…",
  ui_story_1018_10180602_46_dialog_content = "（そうよ、ラス。もうすぐ終わるわ…）",
  ui_story_1018_10180602_47_dialog_content = "あんたたちはもう肩の荷を下ろしなさい。\n勝利が訪れた時のように――",
  ui_story_1018_10180602_48_dialog_content = "永遠に戦火にまみえることのない故郷へ戻りなさい。",
  ui_story_1018_10180602_49_dialog_content = "グォォ！！！",
  ui_story_1018_10180602_50_dialog_content = "狙撃手、照準を合わせて――",
  ui_story_1018_10180602_51_dialog_content = "射撃開始！",
  ui_story_1018_10180602_52_dialog_content = "<color=#e8d9bb>バンバンバン――</color>",
  ui_story_1018_10180602_53_dialog_content = "…",
  ui_story_1018_10180602_54_dialog_content = "戦いは終わりよ。安らかに眠りなさい…",
  ui_story_1018_10180602_55_dialog_content = "…",
  ui_story_1018_10180602_56_dialog_content = "…",
  ui_story_1018_10180701_1_dialog_content = "<color=#e8d9bb>白夜要塞へ向かう道で…</color>",
  ui_story_1018_10180701_2_dialog_content = "アーチ、もうすぐ白夜要塞です。頑張れますか？",
  ui_story_1018_10180701_3_dialog_content = "うん…まだ頑張れるよ…",
  ui_story_1018_10180701_4_dialog_content = "どこか具合が悪いようですが…\n先程の拘束を脱した兵士に驚いたのですか？",
  ui_story_1018_10180701_5_dialog_content = "ジョセリンお姉ちゃん、そうじゃないの…",
  ui_story_1018_10180701_6_dialog_content = "お姉ちゃんがみんなをまもるために一生懸命なのを見てたら、\nぜんぜんこわくなくなったよ。",
  ui_story_1018_10180701_7_dialog_content = "ただ今回は…けがしてる人が多くて…\nしかも縄でしばらないとおさえられなかったから…",
  ui_story_1018_10180701_8_dialog_content = "あ、別にイヤだって言ってるわけじゃないよ！\n兵士のお兄ちゃんたちだって私たちを守るために来てくれたんだし…",
  ui_story_1018_10180701_9_dialog_content = "ただ…ジョセリンお姉ちゃんはずっとこんなのを見てるから、\nきっと大変なんだろうなって…",
  ui_story_1018_10180701_10_dialog_content = "…",
  ui_story_1018_10180701_11_dialog_content = "アーチ、私が小さかった頃のトワイライトシティは\n今よりももっと苦しかったのですよ…",
  ui_story_1018_10180701_12_dialog_content = "ジョセリンお姉ちゃんが…小さかった頃？",
  ui_story_1018_10180701_13_dialog_content = "12歳の時、トワイライトシティが暗鬼の襲撃を受け、\n両親は私を守るために命を落としました。",
  ui_story_1018_10180701_14_dialog_content = "当時住んでいた村には助けてくれる人もおらず、\n自分たちの力で生きていくしかありませんでした。",
  ui_story_1018_10180701_15_dialog_content = "私とさして年の変わらない子どもまでが武器を手に取り、戦場に出て行きました。\nそのうちの多くの子とそれ以来一度も会っていません…",
  ui_story_1018_10180701_16_dialog_content = "そのあと…どうなったの？",
  ui_story_1018_10180701_17_dialog_content = "その後暗鬼が村を襲い、私は村に残っていた子どもたちを連れてあちこち逃げ回りました。\nそんな不安な日々が何年も続きました。",
  ui_story_1018_10180701_18_dialog_content = "幸い騎士団に助けられ、兵士の方々が白夜教会の孤児院に連れて行ってくれました。\nそうして私は修道女になったのです。",
  ui_story_1018_10180701_19_dialog_content = "すごくつらい体験だったんだね…\nでも、ジョセリンお姉ちゃんはどうしてそのあとも騎士団に付いてるの？",
  ui_story_1018_10180701_20_dialog_content = "こちらから暗鬼に対抗しなければ、\nトワイライトシティの民に生きる希望はないと信じているからです。",
  ui_story_1018_10180701_21_dialog_content = "騎士団に救われ、騎士団と同じようにトワイライトシティに\n安全な暮らしをもたらしたいと思っているのです。",
  ui_story_1018_10180701_22_dialog_content = "ジョセリンお姉ちゃんは、ほんとにすごい人だなぁ！",
  ui_story_1018_10180701_23_dialog_content = "アーチ、あなたはたくさんの人を助けました。\n子どもの頃の私よりもずっと立派ですよ！",
  ui_story_1018_10180701_24_dialog_content = "ここです。あともう少し頑張りましょう。\n負傷者を中まで送れば安全です。",
  ui_story_1018_10180701_25_dialog_content = "うん！",
  ui_story_1018_10180701_26_dialog_content = "<color=#e8d9bb>ドンドン――ドンドン――</color>",
  ui_story_1018_10180701_27_dialog_content = "トワイライトシティの戦士、ジョセリンと申します。\n負傷者がいるので、どうか治療と保護をお願いいたします。",
  ui_story_1018_10180701_28_dialog_content = "主の命令だ。白夜城の者以外は中に入ることはできん。\n別の所へ行くんだな。",
  ui_story_1018_10180701_29_dialog_content = "どうか話を聞いてください。私が連れてきた負傷者の中には白夜要塞の騎士もいます。\n皆私たちの同胞です。せめて中に入れてくださいませんか？",
  ui_story_1018_10180701_30_dialog_content = "これまで「アイアンソーン騎士団」が何度も要請してきた時に言ったはずだ。\n白夜要塞の資源にも限りがある。これ以上けが人を受け入れる余裕はない。",
  ui_story_1018_10180701_31_dialog_content = "そこを何とか…",
  ui_story_1018_10180701_32_dialog_content = "<color=#e8d9bb>バタバタバタ――</color>",
  ui_story_1018_10180701_33_dialog_content = "ジョセリンお姉ちゃん！\n啓光のお兄ちゃん2人が暴れ始めたよ。",
  ui_story_1018_10180701_34_dialog_content = "また縄を脱して襲ってきたら…",
  ui_story_1018_10180701_35_dialog_content = "君たちの連れてるけが人は白夜要塞の民に危険を及ぼす恐れがあるようだな。\nであれば、なおさら中に入れるわけにはいかない！",
  ui_story_1018_10180701_36_dialog_content = "そういうことでしたら…",
  ui_story_1018_10180701_37_dialog_content = "どうか白夜教区のヨーゼフ神父にお伝えください――",
  ui_story_1018_10180701_38_dialog_content = "私、ジョセリンはトワイライトシティの「聖女」として、\n白夜教会が光霊に庇護を与えてくださることを願います、と。",
  ui_story_1018_10180701_39_dialog_content = "ヨーゼフ神父は重要な用事で城内にはいらっしゃらない。\n君の「聖女」という肩書もトワイライトシティの民が呼んでるにすぎないだろう。",
  ui_story_1018_10180701_40_dialog_content = "たとえ本当の「聖女」だったとしても、\n主の命令に背き、中に入れるわけにはいかない！",
  ui_story_1018_10180701_41_dialog_content = "光の神の民は今、厳しい苦難の中にいるのですよ。\n白夜教会は光霊がどうなっても構わないとおっしゃるのですか！？",
  ui_story_1018_10180701_42_dialog_content = "グォォ！！！",
  ui_story_1018_10180701_43_dialog_content = "そんな…へ、兵士が暗鬼になった？",
  ui_story_1018_10180701_44_dialog_content = "ジョセリンお姉ちゃん！",
  ui_story_1018_10180701_45_dialog_content = "皆さん、落ち着いてください！\nすぐに馬車から離れ、後は私にお任せください！",
  ui_story_1018_10180701_46_dialog_content = "<size=30>城門を開けてください</size>",
  ui_story_1018_10180701_47_dialog_content = "このような兵士を中に入れたら、我々は確実に自滅する…",
  ui_story_1018_10180701_48_dialog_content = "城門を開けてください。",
  ui_story_1018_10180701_49_dialog_content = "「聖女」の意向に逆らうとは、\n白夜の教義を忘れてしまったようね！",
  ui_story_1018_10180701_50_dialog_content = "アップタウン護衛隊長カレンが今ここに白夜要塞臨時城主の名をもって、\n城門を開き難民を受け入れるよう命令する！",
  ui_story_1018_10180701_51_dialog_content = "暗鬼は私に任せなさい！城門を開けるのよ！",
  ui_story_1018_10180701_52_dialog_content = "か、カレン殿下…しょ、承知いたしました！",
  ui_story_1018_10180701_53_dialog_content = "<color=#e8d9bb>ギイィ――</color>",
  ui_story_1018_10180702_1_dialog_content = "<color=#e8d9bb>天から降りし光に人々は思わずひざまずいた…</color>",
  ui_story_1018_10180702_2_dialog_content = "本物の「聖女様」が降臨なさいました！",
  ui_story_1018_10180702_3_dialog_content = "間違いありません…この聖なる光は「聖女様」のものです！",
  ui_story_1018_10180702_4_dialog_content = "光の神は修道女の言葉が偽りなき真実であることをご存じです――",
  ui_story_1018_10180702_5_dialog_content = "この聖なる光で迷いし光霊を包んであげなさい。",
  ui_story_1018_10180702_6_dialog_content = "ジョセリンお姉ちゃん！\n兵士さんたちの身体が金色に光ってるよ！",
  ui_story_1018_10180702_7_dialog_content = "不思議だ…痛みが消えていく…",
  ui_story_1018_10180702_8_dialog_content = "あ…ジョセリンお姉ちゃん…泣いてるの…？",
  ui_story_1018_10180702_9_dialog_content = "申し訳ございません…「聖女様」にお会いできて…\n取り乱してしまいました…",
  ui_story_1018_10180702_10_dialog_content = "アーチ、今の方こそ光の神の使者として、\n人の間を巡っていらっしゃる、白夜教会の「聖女様」ですよ！",
  ui_story_1018_10180702_11_dialog_content = "「聖女様」…",
  ui_story_1018_10180702_12_dialog_content = "ジョセリン――",
  ui_story_1018_10180702_13_dialog_content = "ヨーゼフ神父！白夜に捧ぐ――",
  ui_story_1018_10180702_14_dialog_content = "白夜に捧ぐ――申し訳ありません。トワイライトシティの兵士を\n大変な目に遭わせてしまいました。レオ騎士団長のほうは順調ですか？",
  ui_story_1018_10180702_15_dialog_content = "啓光の兵士と空の末裔のおかげで、\n暗鬼の数はすでに大幅に減りました。",
  ui_story_1018_10180702_16_dialog_content = "ただ、ぬかるみがまだ退いておらず、危険は残っています。\n啓光兵士の状況も芳しくなく…",
  ui_story_1018_10180702_17_dialog_content = "本当に申し訳ありません。要塞の門兵は白夜貴族の命にのみ従い、\n白夜城主様の派遣してきた援軍も要塞の防御に努めるのみです。",
  ui_story_1018_10180702_18_dialog_content = "引き続き白夜城主様に援護を求める以外、\n私は何のお力にもなれず…",
  ui_story_1018_10180702_19_dialog_content = "教会の者をトワイライトシティの応援に向かわせ、\nただひたすら白夜神殿に救援要請の手紙を書き続けています。",
  ui_story_1018_10180702_20_dialog_content = "そうだったのですか！今や聖女様もお見えになり、\n白夜教区は神の恩恵に包まれたのですね！",
  ui_story_1018_10180702_21_dialog_content = "私もこうなるとは思いもしませんでした。\n手紙を出した後、本当は白夜城へ向かおうと思っていたのです。",
  ui_story_1018_10180702_22_dialog_content = "ですが出立前、聖女様が自らいらっしゃるとのご指示があり、\nここに留まっていたのです。",
  ui_story_1018_10180702_23_dialog_content = "詳しいことはまた後程お話しましょう。\nまずは教会に行き、準備してまいります。",
  ui_story_1018_10180702_24_dialog_content = "教会の者をトワイライトシティのけが人の迎えに来させます。",
  ui_story_1018_10180702_25_dialog_content = "ヨーゼフ神父、ご協力に感謝いたします！",
  ui_story_1018_10180702_26_dialog_content = "ただ…一部のけが人の状況は少々複雑なのです。\nどうぞ十分にお気をつけください。",
  ui_story_1018_10180702_27_dialog_content = "安心してください。聖女様と共にいらした神職者の方々も\n医療に精通していらっしゃいます。きちんと診て頂けますよ。",
  ui_story_1018_10180702_28_dialog_content = "白夜に捧ぐ――",
  ui_story_1018_10180702_29_dialog_content = "白夜に捧ぐ――",
  ui_story_1018_10180702_30_dialog_content = "ふぅ――これでおそらく問題はないでしょう。\n光の神よ、永遠なれ。",
  ui_story_1018_10180702_31_dialog_content = "あ、あなたは本当に聖女様なのですか…？\n神に見捨てられたこの地に神の使いが降臨なされた！",
  ui_story_1018_10180702_32_dialog_content = "聖女様がいらっしゃれば、ぬかるみもこれ以上広がらないだろう！",
  ui_story_1018_10180702_33_dialog_content = "見てみろ。町の上空を覆っていた黒い雲はすでに聖女様によってすっかり払われている。\n暗鬼にもう逃げ場はないぞ！",
  ui_story_1018_10180702_34_dialog_content = "聖女様、ありがとうございます！",
  ui_story_1018_10180702_35_dialog_content = "お礼など必要ありません…\nそれと…聖女様と呼ぶのはおやめください…",
  ui_story_1018_10180702_36_dialog_content = "聖女様、1つお願いがございます。\n私の子どもはまだトワイライトシティで戦っているのですが…",
  ui_story_1018_10180702_37_dialog_content = "聖女様！どうか話を聞いてくだ…",
  ui_story_1018_10180702_38_dialog_content = "聖女様…",
  ui_story_1018_10180702_39_dialog_content = "み、皆さん、私のことはヒルダとお呼びください…",
  ui_story_1018_10180702_40_dialog_content = "皆さんの祈りには一つ一つ耳を傾けます…",
  ui_story_1018_10180702_41_dialog_content = "聖女様！私たちを置いていかないでください…",
  ui_story_1018_10180702_42_dialog_content = "…",
  ui_story_1018_10180702_43_dialog_content = "すべての願いにお答えになる必要はございません。",
  ui_story_1018_10180702_44_dialog_content = "ですが、初めて神殿の者以外の光霊と言葉を交わすのです…",
  ui_story_1018_10180702_45_dialog_content = "お答えになる必要はございません。",
  ui_story_1018_10180702_46_dialog_content = "…分かりました。",
  ui_story_1018_10180702_47_dialog_content = "皆さんの気持ちは聖女様が確かにお受け取りになったわ。",
  ui_story_1018_10180702_48_dialog_content = "カレンさん、ありがとうございます。\nでも実は私とても嬉しいのですよ、ふふふ…",
  ui_story_1018_10180702_49_dialog_content = "あら？あなたはどなた？\nなぜ…私のことをじっとご覧になっているのですか…？",
  ui_story_1018_10180702_50_dialog_content = "頭の上のツノ、どうしたの？",
  ui_story_1018_10180702_51_dialog_content = "無礼者――",
  ui_story_1018_10180702_52_dialog_content = "構いませんよ。",
  ui_story_1018_10180702_53_dialog_content = "これですか？実は<color=#FFB400>セントライノ</color>の物語と関係があり…",
  ui_story_1018_10180702_54_dialog_content = "セントライノ神のお話のこと？\n小さい頃からよく聞いてたよ！そのお話ではね…",
  ui_story_1018_10180702_55_dialog_content = "<color=#e8d9bb>けが人を無事教会に引き継いだ後…</color>",
  ui_story_1018_10180702_56_dialog_content = "聖女様、お初にお目にかかります。\n修道女ジョセリン、ご挨拶が遅れました。",
  ui_story_1018_10180702_57_dialog_content = "はじめまして、ジョセリンさん。ヨーゼフ神父から聞いています。\nあなたの助けとなれたのなら嬉しいのですが。",
  ui_story_1018_10180702_58_dialog_content = "お恥ずかしい限りです。私には暗鬼に傷つけられた光霊を救うことはできませんでした。\n聖女様の光が彼らを癒したのです。",
  ui_story_1018_10180702_59_dialog_content = "そうではありませんよ。\nあなたは全力を尽くし、光霊を救いました。あなたはとても善良な方です。",
  ui_story_1018_10180702_60_dialog_content = "よろしければ…ヒルダとお呼びください。ヒルダは私の名です。\nあなたには教えていただきたいことがたくさんあるのです。",
  ui_story_1018_10180702_61_dialog_content = "いけません…\nあなた様は聖女様でいらっしゃいます！",
  ui_story_1018_10180702_62_dialog_content = "ジョセリンお姉ちゃん、\n聖女様はトワイライトシティのお姉ちゃんたちと同じで優しいよ。",
  ui_story_1018_10180702_63_dialog_content = "そうですよ！アーチ、まだお話は終わっていませんでしたね。\n実はあの物語の結末は…",
  ui_story_1018_10180702_64_dialog_content = "…",
  ui_story_1018_10180702_65_dialog_content = "ジョセリン、何を考え込んでいるの？",
  ui_story_1018_10180702_66_dialog_content = "カレン殿下、少々意外だったものですから…",
  ui_story_1018_10180702_67_dialog_content = "聖女様は聖女でいらっしゃいます…にもかかわらず…\n子どものように無邪気でいらっしゃるので…",
  ui_story_1018_10180702_68_dialog_content = "実を言うと、私も初めて聖女様にお会いした時、\n世間知らずな様子に少なからず驚いたわ。",
  ui_story_1018_10180702_69_dialog_content = "今もアーチのような年頃の子とごく自然に打ち解けて、\nトワイライトシティに伝わる話にとても興味をもっていらっしゃる。",
  ui_story_1018_10180702_70_dialog_content = "聖女としての役目以外のことは、\nよくご存じないのかもしれないわ。",
  ui_story_1018_10180702_71_dialog_content = "ええ、その通りでございますね。\n私の見識不足でした。",
  ui_story_1018_10180702_72_dialog_content = "けが人はすでに教会へ引き継いだようだけど、\nあなたもここに残って治療を手伝うつもりなの？",
  ui_story_1018_10180702_73_dialog_content = "トワイライトシティの戦いはまだ終わっていません。\n戦場に戻り、戦士たちと共に戦います。",
  ui_story_1018_10180702_74_dialog_content = "ここにはヨーゼフ神父がいらっしゃるので安心です。",
  ui_story_1018_10180702_75_dialog_content = "そうね。私も白夜城の援軍を率いて、一緒に行くわ。",
  ui_story_1018_10180702_76_dialog_content = "ヒルダも参ります！まだ、時間はございますよね…？",
  ui_story_1018_10180702_77_dialog_content = "はい、聖女様。",
  ui_story_1018_10180702_78_dialog_content = "聖女様がいてくだされば、トワイライトシティは必ず危機を脱することができます。\nすぐにでも発ちましょう！",
  ui_story_1018_10180801_1_dialog_content = "<color=#e8d9bb>トワイライトシティの外では</color>",
  ui_story_1018_10180801_2_dialog_content = "『ノラ様、恐れながら、なぜあの女を助けたのですか？』",
  ui_story_1018_10180801_3_dialog_content = "『兵士たちと共にあの女も我々の仲間にするべきだったのでは？』",
  ui_story_1018_10180801_4_dialog_content = "あの女、窮地に追い込んだのに生き延びるなんて、\n実に意外な実験結果を出してくれたわ。",
  ui_story_1018_10180801_5_dialog_content = "彼女の体内にある「シード」がなぜここまで特殊なのか\n解明できれば、ここに来た甲斐もあったというものよ。",
  ui_story_1018_10180801_6_dialog_content = "『ノラ様、しばらく獲物を食っていないので歯がうずいて仕方ありません。』",
  ui_story_1018_10180801_7_dialog_content = "マッドバンドルもそろそろ回復した頃ね。\nカーペットをさらに広げる準備よ。",
  ui_story_1018_10180801_8_dialog_content = "『このまま前進するのですか？』",
  ui_story_1018_10180801_9_dialog_content = "そうよ。ただ今回はトワイライトシティを避けることにするわ。",
  ui_story_1018_10180801_10_dialog_content = "ぬかるみが啓光まで伸びれば、\nユリシーズの下にいる兵士は全員暗鬼になる…",
  ui_story_1018_10180801_11_dialog_content = "『この兵士たちをどうするおつもりですか？』",
  ui_story_1018_10180801_12_dialog_content = "マッドバンドルに防衛線まで運ばせなさい。\nもちろん、あの「芸術品」もね。",
  ui_story_1018_10180801_13_dialog_content = "ただここを離れる前に、\nあの女が私の用意したプレゼントを気に入ったか確かめるわ。",
  ui_story_1018_10180801_14_dialog_content = "アクセリア隊長、大元帥様！第九部隊が見つかりました…",
  ui_story_1018_10180801_15_dialog_content = "皆…砦付近のぬかるみの中に横たわっていました。",
  ui_story_1018_10180801_16_dialog_content = "ぬかるみが退いたので、見つけられたのですが…\nただ…もう…",
  ui_story_1018_10180801_17_dialog_content = "…",
  ui_story_1018_10180801_18_dialog_content = "連れて行ってちょうだい。",
  ui_story_1018_10180801_19_dialog_content = "今の部隊編成に組み込まれた装甲車の乗員以外、\n第九部隊の兵士は皆ここで見つかりました。",
  ui_story_1018_10180801_20_dialog_content = "それ以外の兵士は全て…「エンジン7号」の操縦士も含め、\n犠牲になりました…",
  ui_story_1018_10180801_21_dialog_content = "あの兵士はなぜ…このような死に方をしたのですか…",
  ui_story_1018_10180801_22_dialog_content = "下あごに弾の跡があるが、指は銃の引き金にかかっている。\n暴走してしまう前に自分で命を絶ったのは明らかだな…",
  ui_story_1018_10180801_23_dialog_content = "…",
  ui_story_1018_10180801_24_dialog_content = "ここにいる数名は一般兵士だろう？",
  ui_story_1018_10180801_25_dialog_content = "はい…",
  ui_story_1018_10180801_26_dialog_content = "お互いに抱き合っていますね。\nぬかるみから身を守ろうとしたのでしょうか…？",
  ui_story_1018_10180801_27_dialog_content = "なんと残酷な…ほぼ骨しか残っていないじゃないですか…",
  ui_story_1018_10180801_28_dialog_content = "…このような形で犠牲になるとは…\n実に勇敢な兵士たちだ。",
  ui_story_1018_10180801_29_dialog_content = "…先刻私は早まった判断をしたようだ。\n申し分けない。",
  ui_story_1018_10180801_30_dialog_content = "…",
  ui_story_1018_10180801_31_dialog_content = "ラス…",
  ui_story_1018_10180801_32_dialog_content = "長年辺境を守ってきたが、このような状況は初めてだ。",
  ui_story_1018_10180801_33_dialog_content = "僕たちに、何かできることはある？",
  ui_story_1018_10180801_34_dialog_content = "引き続き周囲の状況を調べ、\n負傷者を探し出そう。",
  ui_story_1018_10180801_35_dialog_content = "<color=#e8d9bb>ブクブクブク――</color>",
  ui_story_1018_10180801_36_dialog_content = "団長！兵士たちの後ろのぬかるみの様子が変です！",
  ui_story_1018_10180801_37_dialog_content = "これこそトワイライトシティが人を引き付ける理由なのかしら？",
  ui_story_1018_10180801_38_dialog_content = "ほかの何のためでもなく、\nただ真の「芸術品」のためだけに…",
  ui_story_1018_10180801_39_dialog_content = "ノラ？",
  ui_story_1018_10180801_40_dialog_content = "姿を隠していた敵はお前か？",
  ui_story_1018_10180801_41_dialog_content = "大元帥に挨拶しに来たの。戦いは痛快だったかしら？",
  ui_story_1018_10180801_42_dialog_content = "ノラ――！",
  ui_story_1018_10180801_43_dialog_content = "楽にしてなさい。あなたのその身体で、本気でやるつもり？",
  ui_story_1018_10180801_44_dialog_content = "ラス大元帥を傷つけるのは許しません！",
  ui_story_1018_10180801_45_dialog_content = "またあなたなの？ほうけ者のようだけど、\n手加減すべきじゃなさそうね。",
  ui_story_1018_10180801_46_dialog_content = "あんたが部下にしたことは、私が倍にして返してやるわ！",
  ui_story_1018_10180801_47_dialog_content = "倍にして返す？あなたの部下を全員殺したところで、\n私の損失を埋め合わせるには程遠いのよ。",
  ui_story_1018_10180801_48_dialog_content = "きっとなぜ自分が今まで持ちこたえられたかも知らないんでしょう？\n啓光はあなたに100回の死に値する程のことをしたのよ。",
  ui_story_1018_10180801_49_dialog_content = "あなたがここで苦戦しているというのに、\n啓光が終始心を動かさない理由をまさか知らないわけじゃないでしょう？",
  ui_story_1018_10180801_50_dialog_content = "無駄話はここまでよ、恥知らずめ！",
  ui_story_1018_10180801_51_dialog_content = "少しは知っているようね。だったら、あいつらは新任大元帥の\n戦い方は自らの手で部下を殺すことだって知ってる？",
  ui_story_1018_10180801_52_dialog_content = "ノラ、殺してやるわ！",
  ui_story_1018_10180801_53_dialog_content = "ラス、落ち着いて！わざと君を怒らせてるんだよ！",
  ui_story_1018_10180801_54_dialog_content = "…",
  ui_story_1018_10180801_55_dialog_content = "トワイライトシティで起こっていることはあんたの仕業だって知ってたわ。\n今日こそは逃がさないわよ！",
  ui_story_1018_10180801_56_dialog_content = "否定はしないわね。それに私は好きでやっているのよ。\nコソ泥に対する懲罰ってところかしら。",
  ui_story_1018_10180801_57_dialog_content = "芸術品はもう見たようだし、ここからが本番よ。\nしっかり目を見開いて見ていなさい！",
  ui_story_1018_10180801_58_dialog_content = "何をするつもりだ？",
  ui_story_1018_10180801_59_dialog_content = "あら？前に立ちふさがるってことは、\n私と一対一でやり合うつもり？",
  ui_story_1018_10180801_60_dialog_content = "アクセリアもいます…",
  ui_story_1018_10180801_61_dialog_content = "そうだよ、僕もいる！",
  ui_story_1018_10180801_62_dialog_content = "好きにすればいいわ。私はもう飽きたの。\nあなたたちの相手は――",
  ui_story_1018_10180801_63_dialog_content = "グォォ…",
  ui_story_1018_10180801_64_dialog_content = "今のはエンジン7号の操縦士の声だ…\n犠牲になったんじゃなかったの…？",
  ui_story_1018_10180801_65_dialog_content = "グォォ…",
  ui_story_1018_10180801_66_dialog_content = "…あんたたちが犠牲になるのは1度きりでいい…",
  ui_story_1018_10180801_67_dialog_content = "もうこれ以上…",
  ui_story_1018_10180801_68_dialog_content = "大元帥…アクセリアは大元帥の怒りを感じました…",
  ui_story_1018_10180801_69_dialog_content = "アクセリア…",
  ui_story_1018_10180801_70_dialog_content = "アクセリアは大元帥を守りたいと思っています…\nアクセリアは大元帥の体温を感じることはできません…",
  ui_story_1018_10180801_71_dialog_content = "でも、インゲルが言いました…\nアクセリアの心臓はもともとここにあったと…",
  ui_story_1018_10180801_72_dialog_content = "そこは私の身体の中にある力よりも\nずっと暖かったのだろうと思います…",
  ui_story_1018_10180801_73_dialog_content = "アクセリア…",
  ui_story_1018_10180801_74_dialog_content = "…安心して。私はあの力に乗っ取られたりはしない。",
  ui_story_1018_10180801_75_dialog_content = "団長…部隊がこちらへ向かってきます！\nどうしますか？",
  ui_story_1018_10180801_76_dialog_content = "ぬかるみが…いえ、暗力が身体の中からしみ出してくるのが肉眼でも見えるほどです。\n兵士たちの目には奇怪な光が浮かんでいます！",
  ui_story_1018_10180801_77_dialog_content = "<color=#e8d9bb>サッ――</color>",
  ui_story_1018_10180801_78_dialog_content = "貫け、雷槍よ！",
  ui_story_1018_10180801_79_dialog_content = "部下たちの魂はすでに栄誉ある場所に迎えられたのよ。\n戦い続けることは彼らへの侮辱でしかないわ。",
  ui_story_1018_10180801_80_dialog_content = "全員よく聞きなさい。兵士たちをこれ以上苦しめるわけにはいかないわ。\n彼らは私たちを守ってくれた。彼らの犠牲は無駄死にではない！",
  ui_story_1018_10180801_81_dialog_content = "大元帥、了解した。",
  ui_story_1018_10180801_82_dialog_content = "残忍で素晴らしいわ。\nだったら、残りの者を連れて行っても文句はないわよね…",
  ui_story_1018_10180801_83_dialog_content = "逃げる気！？",
  ui_story_1018_10180801_84_dialog_content = "ノラと一緒にぬかるみの中に消えたのって…",
  ui_story_1018_10180801_85_dialog_content = "アクセリアの部下です。",
  ui_story_1018_10180801_86_dialog_content = "第八部隊をアクセリアにください！",
  ui_story_1018_10180801_87_dialog_content = "アクセリア…大丈夫だよね…",
  ui_story_1018_10180801_88_dialog_content = "共に突撃していった部下たちは終始彼女についていた者たちだ。\nおそらく大丈夫だろう。",
  ui_story_1018_10180801_89_dialog_content = "ここを片付けたら、すぐに追いかけるわよ！",
  ui_story_1018_10180801_90_dialog_content = "うん！",
  ui_story_1018_10180802_1_dialog_content = "そんな身体でまだ私を追ってくるのね？",
  ui_story_1018_10180802_2_dialog_content = "アクセリアは…皆を守らなければなりません…\n皆を返してください。",
  ui_story_1018_10180802_3_dialog_content = "だったら、私を倒してみれば？",
  ui_story_1018_10180802_4_dialog_content = "アクセリアは…第八部隊を連れて帰ります！",
  ui_story_1018_10180802_5_dialog_content = "相手を倒すっていうのは、こうやるのよ！",
  ui_story_1018_10180802_6_dialog_content = "やめてください…",
  ui_story_1018_10180802_7_dialog_content = "アクセリア隊長…大丈夫ですか…？",
  ui_story_1018_10180802_8_dialog_content = "…",
  ui_story_1018_10180802_9_dialog_content = "その顔はどういうこと？ユリシーズの作ったサイボーグに心なんてないのよ。\nなぜ…苦しんでいるの？",
  ui_story_1018_10180802_10_dialog_content = "アクセリアは…心のないサイボーグではありません…",
  ui_story_1018_10180802_11_dialog_content = "強情ね。",
  ui_story_1018_10180802_12_dialog_content = "部下を傷つけないでください…苦しんでいます…",
  ui_story_1018_10180802_13_dialog_content = "こいつらにあなたの言葉が届いてると思う？",
  ui_story_1018_10180802_14_dialog_content = "アクセリア、あなたを許しません…",
  ui_story_1018_10180802_15_dialog_content = "私がこいつらを殺すのを見ている以外、\nあなたに何ができるの？",
  ui_story_1018_10180802_16_dialog_content = "『ノラ様、マッドバンドルの準備が整いました。』",
  ui_story_1018_10180802_17_dialog_content = "よくやったわ。そこまで懇願するなら、\nオモチャ用に数人残しておいてあげるわ。残りは…フフフ。",
  ui_story_1018_10180802_18_dialog_content = "アクセリア隊長、全員…ぬかるみの中に消えてしまいました…",
  ui_story_1018_10180802_19_dialog_content = "皆を…返してください…",
  ui_story_1018_10180802_20_dialog_content = "グォォ！！！",
  ui_story_1018_10180802_21_dialog_content = "アクセリア隊長、あぶない！",
  ui_story_1018_10180802_22_dialog_content = "グォォ！！！",
  ui_story_1018_10180802_23_dialog_content = "やめてください…",
  ui_story_1018_10180802_24_dialog_content = "アクセリア隊長、助けてください！",
  ui_story_1018_10180802_25_dialog_content = "グォォ！！！",
  ui_story_1018_10180802_26_dialog_content = "うっ…",
  ui_story_1018_10180802_27_dialog_content = "…あなたたちは戦闘サイボーグではありません…\n皆を殺さないでください…",
  ui_story_1018_10180802_28_dialog_content = "グォォ！！！",
  ui_story_1018_10180802_29_dialog_content = "あ――",
  ui_story_1018_10180802_30_dialog_content = "…",
  ui_story_1018_10180802_31_dialog_content = "（叫び声も…風の音も、武器の音も…全部聞こえなくなりました…）",
  ui_story_1018_10180802_32_dialog_content = "（彼はもう…死んだのですか…？）",
  ui_story_1018_10180802_33_dialog_content = "（もしかしたら…アクセリアが死んだのかもしれません…）",
  ui_story_1018_10180802_34_dialog_content = "（…）",
  ui_story_1018_10180802_35_dialog_content = "アクセリア隊長！助けてください――",
  ui_story_1018_10180802_36_dialog_content = "（身体が重い…動けません…）",
  ui_story_1018_10180802_37_dialog_content = "（早く…助けないと！）",
  ui_story_1018_10180802_38_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_1018_10180802_39_dialog_content = "（…部下の身体が地面に重くたたきつけられました…）",
  ui_story_1018_10180802_40_dialog_content = "（まるで…アクセリアの身体がたたきつけられたかのように感じます…）",
  ui_story_1018_10180802_41_dialog_content = "<color=#e8d9bb>グォォ！！</color>",
  ui_story_1018_10180802_42_dialog_content = "（部下の胸ぐらをつかんで…その身体を食べています…）",
  ui_story_1018_10180802_43_dialog_content = "（部下が血だまりの中に倒れました…）",
  ui_story_1018_10180802_44_dialog_content = "（でも、アクセリアは…自分が倒れたかのように感じます…）",
  ui_story_1018_10180802_45_dialog_content = "<color=#e8d9bb>ドン――ドン――</color>",
  ui_story_1018_10180802_46_dialog_content = "（5回、6回…）",
  ui_story_1018_10180802_47_dialog_content = "（アクセリアが倒れるのは6回目です…）",
  ui_story_1018_10180802_48_dialog_content = "（10回目…）",
  ui_story_1018_10180802_49_dialog_content = "（23回目、24回目…）",
  ui_story_1018_10180802_50_dialog_content = "（102回目…）",
  ui_story_1018_10180802_51_dialog_content = "（2000回…）",
  ui_story_1018_10180802_52_dialog_content = "（…）",
  ui_story_1018_10180802_53_dialog_content = "（11111回目…）",
  ui_story_1018_10180802_54_dialog_content = "（アクセリアはまだ倒れ続けています…）",
  ui_story_1018_10180802_55_dialog_content = "（お父さんが言っていました。アクセリアは優秀な戦闘兵器だと。\n戦闘兵器は動揺しません）",
  ui_story_1018_10180802_56_dialog_content = "（でもアクセリアは何回も倒れています…）",
  ui_story_1018_10180802_57_dialog_content = "（どうしたら止められるのか、アクセリアには分かりません…）",
  ui_story_1018_10180802_58_dialog_content = "アクセリア！",
  ui_story_1018_10180802_59_dialog_content = "（お父さんですか…？アクセリアを許してください…）",
  ui_story_1018_10180802_60_dialog_content = "アクセリア！あんたは人として生きていくんでしょ！",
  ui_story_1018_10180802_61_dialog_content = "（生きていく…アクセリアはどうすればいいのでしょうか…）",
  ui_story_1018_10180802_62_dialog_content = "（もしかしたら…アクセリアも…）",
  ui_story_1018_10180802_63_dialog_content = "グォォ…",
  ui_story_1018_10180802_64_dialog_content = "グォォ！！！",
  ui_story_1018_10180802_65_dialog_content = "雷の威力！",
  ui_story_1018_10180802_66_dialog_content = "しっかりしなさい、アクセリア！\n私の話を聞いて！",
  ui_story_1018_10180802_67_dialog_content = "ラス、これ以上先には進むな！",
  ui_story_1018_10180802_68_dialog_content = "グォォ…",
  ui_story_1018_10180802_69_dialog_content = "どうして…アクセリアまで…",
  ui_story_1018_10180802_70_dialog_content = "<color=#e8d9bb>はっ――</color>",
  ui_story_1018_10180802_71_dialog_content = "この声は…",
  ui_story_1018_10180802_72_dialog_content = "まぶしい…",
  ui_story_1018_10180802_73_dialog_content = "大元帥様、レオ騎士団長！遅れて申し訳ございません――",
  ui_story_1018_10180802_74_dialog_content = "修道女ジョセリン、聖女の光を賜りました。\n光霊たちを神の懐へと導きましょう！",
  ui_story_1018_10180802_75_dialog_content = "罪深い暗鬼が皆さんを傷つけることは二度とないでしょう！",
  ui_story_1018_10180802_76_dialog_content = "団長！ジョセリンです！それから…\nカレン殿下と白夜空騎兵です！",
  ui_story_1018_10180802_77_dialog_content = "あの光の中に立っている少女はまさか…",
  ui_story_1018_10180802_78_dialog_content = "光の民たちよ、その魂の帰る時、今だ至らず。",
  ui_story_1018_10180802_79_dialog_content = "万物に魂あり。汝、神の懐にて汚れし力を浄めたまえ。",
  ui_story_1018_10180802_80_dialog_content = "聖なる光に浴し、聖なる祈りを聞き、祝福の光を得よ。",
  ui_story_1018_10180802_81_dialog_content = "封印の力、ここに出ずる。傷病を癒し、悪念を払いたまえ。",
  ui_story_1018_10180802_82_dialog_content = "光の神は永劫にして、光の霊は永遠に。",
  ui_story_1018_10180802_83_dialog_content = "団長、兵士たちの身体が金色に光ってます！",
  ui_story_1018_10180802_84_dialog_content = "間違いない…ジョセリンが聖女様を連れてきたのだ…",
  ui_story_1018_10180802_85_dialog_content = "あの人が兵士たちを治してくれたの？",
  ui_story_1018_10180802_86_dialog_content = "ああ…聖女様は暗力の影響を取り除けるだけではない。\n普通の光霊なら聖なる光を見ただけで病や傷が治ると言われている…",
  ui_story_1018_10180802_87_dialog_content = "本当にその通りだわ…",
  ui_story_1018_10180802_88_dialog_content = "私の体内のあの力が少しずつ消えていくみたい…\n身体がとても楽になったわ…",
  ui_story_1018_10180802_89_dialog_content = "暗鬼になってしまった兵士たちも攻撃を仕掛けてきません…",
  ui_story_1018_10180802_90_dialog_content = "汝の苦痛、我ぞ知る。修養のみが汝の務めなり。",
  ui_story_1018_10180802_91_dialog_content = "白夜に捧ぐ――",
  ui_story_1018_10180802_92_dialog_content = "遅れて申し訳ございません！",
  ui_story_1018_10180802_93_dialog_content = "こんにちは…",
  ui_story_1018_10180802_94_dialog_content = "ご紹介します。こちらは白夜神殿の聖女様でいらっしゃいます。",
  ui_story_1018_10180802_95_dialog_content = "白夜神殿…これはいったい…",
  ui_story_1018_10180802_96_dialog_content = "ラス大元帥様、聖女様は兵士の治療を手伝いに来てくださったのです。",
  ui_story_1018_10180802_97_dialog_content = "先程白夜要塞にお連れした負傷者も皆、\n聖女様の治療のおかげで危険はなくなりました。",
  ui_story_1018_10180802_98_dialog_content = "聖女様が使っているのは…神の力なの？",
  ui_story_1018_10180802_99_dialog_content = "そうではございません。\nヒルダは大元帥と同じく光霊でございます。",
  ui_story_1018_10180802_100_dialog_content = "でも、どう見ても…",
  ui_story_1018_10180802_101_dialog_content = "大元帥と部下の方々がどのような目に遭われたかすでに聞き及んでおります。\nヒルダは深く心を痛め、勝手ながら治療させていただきました。お許しください。",
  ui_story_1018_10180802_102_dialog_content = "いいえ、お礼を言うべきなのは、私のほう…です…",
  ui_story_1018_10180802_103_dialog_content = "ただ、なぜ…ここへ？",
  ui_story_1018_10180802_104_dialog_content = "光霊たちが悪夢の中でささやく声を聴きました。\nその苦しみがいかほどのものか、私にはよく分かります。",
  ui_story_1018_10180802_105_dialog_content = "大元帥もかつて悪夢に悩まされておられました。\nヒルダはそのお声も聴いております。",
  ui_story_1018_10180802_106_dialog_content = "…",
  ui_story_1018_10180802_107_dialog_content = "あ、申し訳ございません…\n今は私がお話をしている場合ではございませんでした。",
  ui_story_1018_10180802_108_dialog_content = "部下のご様子を見に行って差し上げてください。\nすでに危険は脱しているはずです。",
  ui_story_1018_10180802_109_dialog_content = "ええ。改めて、心からお礼を申し上げます…",
  ui_story_1018_10180802_110_dialog_content = "さすが…聖女様は違うな…",
  ui_story_1018_10180802_111_dialog_content = "あなたの声も、聞きましたよ！",
  ui_story_1018_10180802_112_dialog_content = "え？かなり小声で話したんですが…",
  ui_story_1018_10180802_113_dialog_content = "あなた、他の皆さんとは違うようでございますね。",
  ui_story_1018_10180802_114_dialog_content = "聖女様、こちらは空の末裔です。",
  ui_story_1018_10180802_115_dialog_content = "聖女様、初めまして。PlayerNameと言います。",
  ui_story_1018_10180802_116_dialog_content = "はじめまして、PlayerNameさん。\n私のことはヒルダと呼んでください。",
  ui_story_1018_10180802_117_dialog_content = "ヒルダ…",
  ui_story_1018_10180802_118_dialog_content = "確か以前読んだ物語の主人公もヒルダという名前でした…",
  ui_story_1018_10180802_119_dialog_content = "え？本当ですか？\nでは、そのヒルダという人物はどのような方だったのですか？",
  ui_story_1018_10180802_120_dialog_content = "ヒルダは…実は動物で…",
  ui_story_1018_10180802_121_dialog_content = "ちょ、ちょっとPlayerName！聖女様がど、動物とは…",
  ui_story_1018_10180802_122_dialog_content = "でも本には本当にそう書いてあったんだよ！\nヒルダは草花を植えるのがとても好きで…",
  ui_story_1018_10180802_123_dialog_content = "ぷっ…ふふふふ。草花を植えるのが好きな動物でございますか？\nモグラでしょうか、それともキツネ？",
  ui_story_1018_10180802_124_dialog_content = "角や翼はございましたか？\n色々な所へ行ったことがあるのでしょうか…？",
  ui_story_1018_10180802_125_dialog_content = "団長、この方が白夜教会の聖女様なんですか…？",
  ui_story_1018_10180802_126_dialog_content = "ああ…",
  ui_story_1018_10180901_1_dialog_content = "<color=#e8d9bb>カナン城では</color>",
  ui_story_1018_10180901_2_dialog_content = "うむ…では、こんな記事はどうだ？",
  ui_story_1018_10180901_3_dialog_content = "トワイライトシティから戦況は芳しくないとの知らせが入り、\n兵士の家族らはこれから戦場に向かう我が子を心配している…",
  ui_story_1018_10180901_4_dialog_content = "おい、もう少し明るい記事にしろよ。\n俺たちが負けてるみたいじゃないか…",
  ui_story_1018_10180901_5_dialog_content = "だが事実だろ？いい知らせなんざ一切届いてないんだ。\nこのままじゃ記事さえ書けなくなっちまう…",
  ui_story_1018_10180901_6_dialog_content = "ヒイロ長官、今回の我々の任務はなぜトワイライトシティの応援ではなく、\n防衛線へ出兵なんですか？",
  ui_story_1018_10180901_7_dialog_content = "そういう命令です。",
  ui_story_1018_10180901_8_dialog_content = "しかし、トワイライトシティは今厳しい状況なのでは…",
  ui_story_1018_10180901_9_dialog_content = "心配や不安は飲み込んで、\n今後の危機に立ち向かう力とした方が賢明です。",
  ui_story_1018_10180901_10_dialog_content = "はい…",
  ui_story_1018_10180901_11_dialog_content = "長官、ご報告いたします。部隊の準備が整いました。",
  ui_story_1018_10180901_12_dialog_content = "参謀長が準備した戦車はどうなっていますか？",
  ui_story_1018_10180901_13_dialog_content = "すでに配置についています！",
  ui_story_1018_10180901_14_dialog_content = "出発します。",
  ui_story_1018_10180901_15_dialog_content = "了解です！",
  ui_story_1018_10180901_16_dialog_content = "第三軍団が出発したぞ！\nこれでトワイライトシティの戦局も変わるだろう――",
  ui_story_1018_10180901_17_dialog_content = "ん？トランシーバーにおかしな信号が割り込んできてないか？",
  ui_story_1018_10180901_18_dialog_content = "ああ、俺も気付いた！",
  ui_story_1018_10180901_19_dialog_content = "誰かイタズラでもしてるのか…？\n周波数を調整すればちゃんと聞こえるんだろうか…？",
  ui_story_1018_10180901_20_dialog_content = "「啓明の星計画」はユリシーズと日蝕のノラが\n共謀した陰謀であり…",
  ui_story_1018_10180901_21_dialog_content = "これは…",
  ui_story_1018_10180901_22_dialog_content = "あなたが信号を発した犯人ですか？",
  ui_story_1018_10180901_23_dialog_content = "どういう意味でしょう？",
  ui_story_1018_10180901_24_dialog_content = "一緒に整理してみましょう。",
  ui_story_1018_10180901_25_dialog_content = "あなたは初めアイゼンの密偵として大元帥に付き、\n大元帥の一挙一動を観察していました。",
  ui_story_1018_10180901_26_dialog_content = "その後、合同演習ではユリシーズの\n大元帥に濡れ衣を着せるお芝居に付き合わされました。",
  ui_story_1018_10180901_27_dialog_content = "レインハト大元帥の公開裁判で、\nついに自分が上層部の政争のコマであったことに気付き…",
  ui_story_1018_10180901_28_dialog_content = "良心の呵責にさいなまれ、私たちの行動を見てみぬふりするどころか、\n密かに協力してくれましたね。",
  ui_story_1018_10180901_29_dialog_content = "ただ、情報官が通信にここまで通じていたとは驚きです。\nあなたの上官は何もおっしゃっていないのですか？",
  ui_story_1018_10180901_30_dialog_content = "情報官の仕事は情報収集ですが、適宜情報を発信することも必要です。\n今回のことは自身の信念に従ったまでのこと、他の誰とも関係ありません。",
  ui_story_1018_10180901_31_dialog_content = "そうですか。どうやら本気のようですね。",
  ui_story_1018_10180901_32_dialog_content = "信念に従い行動するかどうかは私が他人を判断する際の基準の一つです。\nあなたの仕事ぶりは正確、かつ確固とした信念を感じます。",
  ui_story_1018_10180901_33_dialog_content = "あなたが監獄で私に言ったこと、今なら信じられます…",
  ui_story_1018_10180901_34_dialog_content = "<color=#e8d9bb>少し前、ビビアンが啓光の監獄へ3回目の面会に訪れた時…</color>",
  ui_story_1018_10180901_35_dialog_content = "厳重警戒レベルの監獄に入れるとは、\nアナトリアが提供してくれた情報に誤りはなかったようですね。",
  ui_story_1018_10180901_36_dialog_content = "ビビアン長官、これほど重大な計画の実行を\nなぜ偽証した者が提供した情報にゆだねるのですか？",
  ui_story_1018_10180901_37_dialog_content = "直観です。",
  ui_story_1018_10180901_38_dialog_content = "以前ラスはアナトリアの偽証には何か裏がありそうだと言っていました。\nそして、私たちの行動の目的を探ろうとしていたことも彼が揺らいでいる証拠です。",
  ui_story_1018_10180901_39_dialog_content = "ですから、情報提供は私たちに力を貸すという決心の表れでしょう。",
  ui_story_1018_10180901_40_dialog_content = "では…この突然現れた巡回の兵士も、\n「力を貸す」ことなのでしょうか…",
  ui_story_1018_10180901_41_dialog_content = "…",
  ui_story_1018_10180901_42_dialog_content = "ビビアン参謀長、厳重警戒レベルの監獄に入るには\n証明書を提示していただかなければなりません。",
  ui_story_1018_10180901_43_dialog_content = "あなたたちの上官に聞いてもらえますか？\n私をここに来させた上官は証明書などくれませんでしたが。",
  ui_story_1018_10180901_44_dialog_content = "あなたの直属の上官であるレインハトは今ここに収容されています。\nよくお考えになってから行動された方が賢明かと思います。",
  ui_story_1018_10180901_45_dialog_content = "長官、あの情報官に対する直感は当たらなかったようですね。",
  ui_story_1018_10180901_46_dialog_content = "私が人を見誤ったのは初めてです。",
  ui_story_1018_10180901_47_dialog_content = "しかし、計画は実行します。\n何としてもヒイロ将軍の出兵までに大元帥様を救出しなければ。",
  ui_story_1018_10180901_48_dialog_content = "これが最後のチャンスです。戦闘の準備ですよ！",
  ui_story_1018_10180901_49_dialog_content = "はい、大元帥様のために！",
  ui_story_1018_10180901_50_dialog_content = "参謀長、力づくでお通りになるつもりですか？\nならば我々も…",
  ui_story_1018_10180901_51_dialog_content = "アイタタタ――",
  ui_story_1018_10180901_52_dialog_content = "…まだ何もしていませんが…",
  ui_story_1018_10180901_53_dialog_content = "私にまかせてください。",
  ui_story_1018_10180901_54_dialog_content = "はい、長官。",
  ui_story_1018_10180901_55_dialog_content = "…アナトリア、これはどういうことですか？\n私たちをもてあそんでいるのですか？",
  ui_story_1018_10180901_56_dialog_content = "申し訳ありません。\nこういう方法でしか残っていた疑念を晴らせなかったもので。",
  ui_story_1018_10180901_57_dialog_content = "疑念とは？",
  ui_story_1018_10180901_58_dialog_content = "啓光の未来のため、あなたたちがどのような道を選び、\n目的を果たすためにどこまでやる覚悟があるのか、ということです。",
  ui_story_1018_10180901_59_dialog_content = "では、結論はでましたか？",
  ui_story_1018_10180901_60_dialog_content = "大元帥は偉大な指導者、それが観察を通して得た結論です。",
  ui_story_1018_10180901_61_dialog_content = "常に疑問を持つことは情報官の基本中の基本です。\nやみくもに信じることを私は好みません。",
  ui_story_1018_10180901_62_dialog_content = "ですが、かつて私は他人から無条件に信頼してもらいました。\nそして今、あなたたちの中にその無条件の信頼を見たのです。",
  ui_story_1018_10180901_63_dialog_content = "それこそ私の渇望する未来です。\n私はあなた方に付きます。",
  ui_story_1018_10180901_64_dialog_content = "フフ、大元帥様を背後から狙う者を信じるわけにはいきません。\nいくらあなたの演説が…素晴らしいものであっても。",
  ui_story_1018_10180901_65_dialog_content = "私を知っていただく機会はこれから先いくらでもあります。\n巡回の兵士は私の部下です。お二人はお好きなように。",
  ui_story_1018_10180901_66_dialog_content = "ならば、あなたの仲間入りを歓迎しますよ。\n命知らずの情報官さん。",
  ui_story_1018_10180901_67_dialog_content = "人目を引く行動は私には向いていません。\n影に隠れて行動することの方が慣れていますから。",
  ui_story_1018_10180901_68_dialog_content = "救出計画が成功した暁には、\n私の持っているコマが大いに役に立つでしょう。",
  ui_story_1018_10180901_69_dialog_content = "ええ、約束ですよ。",
  ui_story_1018_10180901_70_dialog_content = "<color=#e8d9bb>ジージーッ――ジジッ――</color>",
  ui_story_1018_10180901_71_dialog_content = "通信設備から…おかしな音が聞こえますね？",
  ui_story_1018_10180901_72_dialog_content = "<color=#e8d9bb>ピッ――</color>",
  ui_story_1018_10180901_73_dialog_content = "おかしいな…トランシーバーが壊れたのか？\n電波が急に乱れたぞ？",
  ui_story_1018_10180901_74_dialog_content = "俺のも同じだ…",
  ui_story_1018_10180901_75_dialog_content = "いったい…何が起こってるんだ？",
  ui_story_1018_10180901_76_dialog_content = "どうやら、委員会が動き出したようですね…",
  ui_story_1018_10180901_77_dialog_content = "参謀長、通信障害の発生と同時に\n防衛線部隊との連絡が切れてしまいました。",
  ui_story_1018_10180901_78_dialog_content = "こんな手まで使うとは…",
  ui_story_1018_10180901_79_dialog_content = "これまで啓光は電波に干渉することがあっても、\n防衛線部隊との通信を妨害したことはありませんでした…",
  ui_story_1018_10180901_80_dialog_content = "…時間がありません。\nアナトリア、十分気を付けてくださいよ。",
  ui_story_1018_10180901_81_dialog_content = "…",
  ui_story_1018_10180901_82_dialog_content = "<color=#e8d9bb>ジーッ――</color>",
  ui_story_1018_10180901_83_dialog_content = "教授、電波干渉はどうやら解決したようです。\n会議を続けてください。",
  ui_story_1018_10180901_84_dialog_content = "…",
  ui_story_1018_10180901_85_dialog_content = "先程はリスク回避のために、通信を切るしかありませんでした。",
  ui_story_1018_10180901_86_dialog_content = "これから電波の発信元も調査しなければなりません。\n完全に回復するまでもうしばらくかかるでしょう。",
  ui_story_1018_10180901_87_dialog_content = "啓光を挙げて教授の陰謀を拝見する時が近づいてきたようですね。",
  ui_story_1018_10180901_88_dialog_content = "この件はただちにアイゼンに調査させましょう。",
  ui_story_1018_10180901_89_dialog_content = "正面きってやり合うよりも、気をそらす方が安全よ。\n教授は実験の欠陥を補うのに集中した方がいいわね。",
  ui_story_1018_10180901_90_dialog_content = "どういうことです？トワイライトシティの戦局について、\n解決策でもあるのですか？",
  ui_story_1018_10180901_91_dialog_content = "解決策なんて最初からあるのよ。どれを選ぶかの問題だけ。\nそれも事態の進展具合によって変わってくるわ。",
  ui_story_1018_10180901_92_dialog_content = "一刻も早く第4期の「シード」で欠陥を補いましょう。",
  ui_story_1018_10180901_93_dialog_content = "私は経験から同じことに忍耐力を\n費やさないようにしています。",
  ui_story_1018_10180901_94_dialog_content = "「暗面偵察隊」から知らせはありましたか？",
  ui_story_1018_10180901_95_dialog_content = "「暗面偵察隊」から「ガーディアン1号」のコアを<color=#FFB400>複製した設備</color>と思われる画像が\nいくつも送られてきています。",
  ui_story_1018_10180901_96_dialog_content = "現段階で推測するに、日蝕が「ガーディアン1号」のコアを盗んだのは、\n「エンジニア」に関わる何らかの準備のためと思われます。",
  ui_story_1018_10180901_97_dialog_content = "…",
  ui_story_1018_10180901_98_dialog_content = "暗潮の危機からも10年経っているというのに、\n私たちはいったい何を成し遂げたのかしら？",
  ui_story_1018_10180901_99_dialog_content = "そのような心配は無用ですよ、鉄仮面殿。",
  ui_story_1018_10180901_100_dialog_content = "「ガーディアン1号」のことはよく知っています。\nコアが使われるまで、もうしばらく時間がかかるはずです。",
  ui_story_1018_10180901_101_dialog_content = "ついでに皆さんにお伝えしておきますが、「シード」の研究開発を加速させるため、\n今後の会議に私は出席いたしません。それでは失礼。",
  ui_story_1018_10180901_102_dialog_content = "教授、実験結果が出ました。ご覧ください。",
  ui_story_1018_10180901_103_dialog_content = "…新しいシードの戦闘データは、なぜこんなにも悪いのでしょう？",
  ui_story_1018_10180901_104_dialog_content = "教授、ベリサリア長官からの通信要請です…",
  ui_story_1018_10180901_105_dialog_content = "…受けなさい。",
  ui_story_1018_10180901_106_dialog_content = "一言忠告しておこうと思ったの。",
  ui_story_1018_10180901_107_dialog_content = "今まで全く姿を見せなかった少女まで出てきたということは、\nどれだけの損失が出たか、あなたならよく分かっているわよね。",
  ui_story_1018_10180901_108_dialog_content = "日蝕が揚々と攻め込んできているのは、暗面での行動が遅れてる証でしょう？\nあなたにとって有利な情報なのかどうかは知らないけど。",
  ui_story_1018_10180901_109_dialog_content = "何が言いたいのですか？",
  ui_story_1018_10180901_110_dialog_content = "実験を続けたいのなら、続けるといいわ。\nただ、あなたの計画はもう私にとって優先事項ではない。",
  ui_story_1018_10180901_111_dialog_content = "それじゃあね、教授。",
  ui_story_1018_10180901_112_dialog_content = "…",
  ui_story_1018_10180901_113_dialog_content = "教授…実験を…続けますか？",
  ui_story_1018_10180901_114_dialog_content = "続けるに決まっているでしょう！\nこれしきのこと何の障害にもなりません！",
  ui_story_1018_10180901_115_dialog_content = "どこか改善できるところはないのですか？\n手順？環境？計量？",
  ui_story_1018_10180901_116_dialog_content = "教授…どれも問題ではないと思います。",
  ui_story_1018_10180901_117_dialog_content = "研究の考え方そのものを見直してはいかがでしょう…",
  ui_story_1018_10180901_118_dialog_content = "私の実験はあの女の考え方と全く同じです！",
  ui_story_1018_10180901_119_dialog_content = "啓光の科学技術、ハーモナイザー、「シード」…\nこの3つがそろっているというのに、何を調整しろと？",
  ui_story_1018_10180901_120_dialog_content = "教授、今の「シード」の改良速度に問題はありません。\nしかし、改良ごとに得られる効果はごくわずかです…",
  ui_story_1018_10180901_121_dialog_content = "やはり、投薬量が守りに入りすぎていましたか…",
  ui_story_1018_10180901_122_dialog_content = "…もう時間がありません。次期「シード」では抽出物の投入量を増やします！",
  ui_story_1018_10180901_123_dialog_content = "アイゼンに再度兵士を集めろと伝えなさい。\nこれまでに淘汰された兵士にも今回は特別に実験参加を認めます。",
  ui_story_1018_10180901_124_dialog_content = "…",
  ui_story_1018_10180901_125_dialog_content = "あれ～、ユリシーズ教授の実験室って\nこんなににぎやかだったんだね？",
  ui_story_1018_10180901_126_dialog_content = "教授…",
  ui_story_1018_10180901_127_dialog_content = "何しに来たのです？",
  ui_story_1018_10180901_128_dialog_content = "そんな怖い顔しないで。あたしはただ命令を受けて、\nうちの実験室の仲間を数日貸してあげに来ただけだよ。",
  ui_story_1018_10180901_129_dialog_content = "委員会の命令ですか？",
  ui_story_1018_10180901_130_dialog_content = "あれあれ？教授は連絡もらってないの？\nうーん…それともインゲル中佐が伝え忘れちゃったのかな？",
  ui_story_1018_10180901_131_dialog_content = "教授…私の所にも命令がきました。\nガルー先輩の研究室と共に取り組めば、実験の進捗も早まるかもしれません…",
  ui_story_1018_10180901_132_dialog_content = "フン、ベリサリアが監視するためによこしただけでしょう…",
  ui_story_1018_10180901_133_dialog_content = "まあ、いい…私はあきらめませんよ。",
  ui_story_1018_10180901_134_dialog_content = "インゲル、兵の徴集はお前に任せる。\n隣にいる助手と引き継ぎしなさい。",
  ui_story_1018_10180901_135_dialog_content = "分かりました…",
  ui_story_1018_10180901_136_dialog_content = "ガルー室長、あなたの実験室の研究員は\n「啓明の星計画」について、どのくらい知っているのですか？",
  ui_story_1018_10180901_137_dialog_content = "あ、そのことなら直接聞いて。\nみんな勉強好きのいい子たちなんだよ～。",
  ui_story_1018_10180901_138_dialog_content = "ユリシーズ教授、何卒ご教示ください。",
  ui_story_1018_10180901_139_dialog_content = "インゲル中佐、さっきはうまくやってくれたね。\nユリシーズ教授は気づいてなかったみたい。",
  ui_story_1018_10180901_140_dialog_content = "ガルー先輩、ありがとうございます…\n私の立場からすれば、許されないことなのですが…",
  ui_story_1018_10180901_141_dialog_content = "教授の実験を見てからというもの、\n何もなかったふりが出来なくなってしまいました。",
  ui_story_1018_10180901_142_dialog_content = "目を閉じるたびに浮かんでくるのです。\nアクセリアが戦場で兵士と互いに…",
  ui_story_1018_10180901_143_dialog_content = "アハハ、善良な小鳥ちゃん、心配はいらないよ。\nもう十分よくやってるって。戦場のことはあたしたちに任せて。",
  ui_story_1018_10180901_144_dialog_content = "それはどういう意味でしょう？",
  ui_story_1018_10180901_145_dialog_content = "実はね、啓光のみんなもあなたと同じ心配をしてるんだ。\nだから、厳密には、あなたがあたしたちを助けてくれてるってことなんだよ。",
  ui_story_1018_10180901_146_dialog_content = "というワケで、行ってくるね。\n負傷者を連れて帰ってくるから！",
  ui_story_1018_10180901_147_dialog_content = "本当ですか？では、ガルー先輩の今回の任務も…\n委員会の命令ですか？",
  ui_story_1018_10180901_148_dialog_content = "インゲル中佐、自分で判断しなきゃダメだよ～。",
  ui_story_1018_10180901_149_dialog_content = "…",
  ui_story_1018_10180901_150_dialog_content = "ガルー先輩、もう1つお願いがあるのですが…",
  ui_story_1018_10180901_151_dialog_content = "なに？言ってみて。",
  ui_story_1018_10180901_152_dialog_content = "私も…一緒に戦場に行ってもよろしいですか？",
  ui_story_1018_10180901_153_dialog_content = "うーん…一緒に行くのは構わないよ…",
  ui_story_1018_10180901_154_dialog_content = "ただ前に見かけた時、調子が良くなかったみたいだよね？\n武器がぶつかり合う音を聞いたら、辛いんじゃないの？",
  ui_story_1018_10180901_155_dialog_content = "はい…軍人であれば、武器を手に取るのは当然ですが…",
  ui_story_1018_10180901_156_dialog_content = "独りになると、冷たい金属の音が耳元に響いて、\n冷や汗が出てくるのです…",
  ui_story_1018_10180901_157_dialog_content = "しかし、啓光には今人が必要です。私も何かしなくてはなりません。\nビビアン長官にお話ししたように…",
  ui_story_1018_10180901_158_dialog_content = "あ、ビビアンは…お～っとぉ、口を滑らすところだった。",
  ui_story_1018_10180901_159_dialog_content = "小鳥っていうのはいつか必ず自分の世界へ飛び立つものだよ。\n準備ができたら、整備場に来てね～。",
  ui_story_1018_10180901_160_dialog_content = "はい。ありがとうございます、ガルー先輩。",
  ui_story_1018_10181002_1_dialog_content = "護衛隊長、ご報告いたします。ぬかるみはほぼ消えました。\nトワイライトシティ周辺にはもう暗鬼の活動の痕跡はありません。",
  ui_story_1018_10181002_2_dialog_content = "啓光の捜索援助も完了し、\n現在ラス大元帥が部下から状況を聞いているところです。",
  ui_story_1018_10181002_3_dialog_content = "分かったわ。部隊を整え、待機していて。",
  ui_story_1018_10181002_4_dialog_content = "ぬかるみが退いて、トワイライトシティの元の姿が見えてきました…\nここはにぎやかだったのですね。",
  ui_story_1018_10181002_5_dialog_content = "はい。この辺りはもともと市場でした。\n今もかろうじて露店の並ぶ様子がうかがえます。",
  ui_story_1018_10181002_6_dialog_content = "この先に見える亀裂の入った石壁は、\nもともと花壇を囲んでいたものです。",
  ui_story_1018_10181002_7_dialog_content = "思えば、不思議な花壇でした。\nとてもたくさんの種類の花が咲いていて、しかも一年中満開だったのです。",
  ui_story_1018_10181002_8_dialog_content = "子どもたちがこの辺りでよく遊んでいました。\n私も小さい頃はよく遊んだものです。",
  ui_story_1018_10181002_9_dialog_content = "ですが今は…子どもたちの遊び場も、\n暗鬼に破壊されてしまいましたね…",
  ui_story_1018_10181002_10_dialog_content = "花は散っても、必ずや再び咲きほこる時が来ます。",
  ui_story_1018_10181002_11_dialog_content = "ジョセリンさんに守られ、子どもたちはここで幸せに暮らすでしょう。",
  ui_story_1018_10181002_12_dialog_content = "ふふふ、私には子どもたちの楽しそうな笑い声が聞こえますよ。",
  ui_story_1018_10181002_13_dialog_content = "聖女様、ありがとうございます！\nただ心配なのです…",
  ui_story_1018_10181002_14_dialog_content = "暗鬼は私たちの家だけでなく、\nトワイライトシティの人々の戦士たちに対する信頼までも壊したのではないかと…",
  ui_story_1018_10181002_15_dialog_content = "もしくは、この地が加護と安寧をもたらす所だと、\n二度と信じてはくれないのではないでしょうか。",
  ui_story_1018_10181002_16_dialog_content = "私は信じる。",
  ui_story_1018_10181002_17_dialog_content = "レオ騎士団長…？",
  ui_story_1018_10181002_18_dialog_content = "ぬかるみの下に横たわっていたのは、\n今回の戦いで犠牲になった戦士たちだ。",
  ui_story_1018_10181002_19_dialog_content = "トワイライトシティはそもそも兵士の亡骸の上に築かれた町だ。\n今回のことで人々も戦いは永遠に終わらないことを思い知ったはずだ。",
  ui_story_1018_10181002_20_dialog_content = "この地に暮らす人がいるかぎり、\nトワイライトシティを守ろうという私の信念が揺らぐことはない。",
  ui_story_1018_10181002_21_dialog_content = "これまでトワイライトシティは私にとって、\nある意味安全領域だった。",
  ui_story_1018_10181002_22_dialog_content = "この戦いがなければ、トワイライトシティを危ぶみながらも、\n相変わらず何もせず迷っているだけだったろう。",
  ui_story_1018_10181002_23_dialog_content = "今回のことで、トワイライトシティも私もあらためて\n自分と向き合うべき時が来たのだ。",
  ui_story_1018_10181002_24_dialog_content = "レオ騎士団長、今の言葉はあなたの白夜城に対する考え方が\n変わったととらえていいのかしら？",
  ui_story_1018_10181002_25_dialog_content = "そうではありません、カレン殿下。\nご期待にはそえないでしょう。",
  ui_story_1018_10181002_26_dialog_content = "ですが、ラス大元帥の行いを見て分かりました。\n当局への不満をただの反発に留めていても意味はありません。",
  ui_story_1018_10181002_27_dialog_content = "まずは変わることから始めなければ。\n己の能力を己の野望に見合うものに変えていかねばなりません。",
  ui_story_1018_10181002_28_dialog_content = "ここにいる諸君に約束しよう。\nトワイライトシティの未来は私の未来だ。",
  ui_story_1018_10181002_29_dialog_content = "これで少しは安心したか、ジョセリン？",
  ui_story_1018_10181002_30_dialog_content = "レオ騎士団長…今のお言葉、とても感動いたしました。",
  ui_story_1018_10181002_31_dialog_content = "トワイライトシティの再建は必ずや順調に行くと、\n信じることができました！",
  ui_story_1018_10181002_32_dialog_content = "実はこのところずっと考えていたことがあるのです。\n聖女様、ご教示をいただけますか？",
  ui_story_1018_10181002_33_dialog_content = "聖女様、まだやるべきことがございます。",
  ui_story_1018_10181002_34_dialog_content = "そうでしたね…ですが、最後にジョセリンさんと\nもう少しお話ししてもよろしいでしょう？",
  ui_story_1018_10181002_35_dialog_content = "ジョセリンさん、手短にお願いいたします。",
  ui_story_1018_10181002_36_dialog_content = "聖女様、私はトワイライトシティに…すべての人に恩恵をもたらす教会を建てたいのです。\n光の神を信奉しない人々も受け入れる教会です…",
  ui_story_1018_10181002_37_dialog_content = "光霊、亜人、空の末裔…\nさらには闇に身を投じる以外に道のなかった人々も…",
  ui_story_1018_10181002_38_dialog_content = "彼らは他の陣営には受け入れてもらえないでしょう。\nですが、愛と思いやりを抱く方であれば、この地で安らかな暮らしを送っていただきたいのです。",
  ui_story_1018_10181002_39_dialog_content = "トワイライトシティには黄昏だけでなく、\n光がもたらされるべきです。",
  ui_story_1018_10181002_40_dialog_content = "アストラ大陸の他の地に暮らす人々と同じように、\nこの地のすべての人に太陽や月そして星空を眺めてほしいのです。",
  ui_story_1018_10181002_41_dialog_content = "とても難しいことだとは分かっています…\nですが、まずは聖女様の庇護を賜ることができれば嬉しく存じます。",
  ui_story_1018_10181002_42_dialog_content = "ジョセリンさん、あなたは本当に敬虔で、心の広い方ですね。",
  ui_story_1018_10181002_43_dialog_content = "あなたの望む教会を建てることは光霊がこの世界の初めに北から南へと下り、\n教えを開いた苦難と同様、厳しい道となるでしょう。",
  ui_story_1018_10181002_44_dialog_content = "ですが、聖なる光は敬虔なる地をあまねく照らします。\nあなたが導くのならば、なおさらです。",
  ui_story_1018_10181002_45_dialog_content = "あなたの望むようになさるとよいでしょう。\n私も支持させていただきますよ。",
  ui_story_1018_10181002_46_dialog_content = "聖女様の教えに感謝いたします。\n教えを心に深く刻み、励んでまいります！",
  ui_story_1018_10181002_47_dialog_content = "ふぅ…どうでしたか？",
  ui_story_1018_10181002_48_dialog_content = "英知に満ちたお言葉でした。\nですが聖女様、そろそろお発ちにならなければ。",
  ui_story_1018_10181002_49_dialog_content = "ええ、そうでしたね！\nでは、この後のことは皆さんにお任せいたします。",
  ui_story_1018_10181002_50_dialog_content = "そうそう、カレンさん。トワイライトシティのことが終わったら、\n一刻も早く防衛線に向かい、城主様の軍と合流してください。",
  ui_story_1018_10181002_51_dialog_content = "城主様の軍が防衛線に！？",
  ui_story_1018_10181002_52_dialog_content = "ならば、なぜ朝堂では無関心なご様子を？",
  ui_story_1018_10181002_53_dialog_content = "ええと…城主様は「情勢に従い、利を導く」なんたらとおっしゃっていましたが、\nヒルダにはよく分かりません。",
  ui_story_1018_10181002_54_dialog_content = "城主様の軍だけではありませんよ。\n大元帥の同僚もいらしています。",
  ui_story_1018_10181002_55_dialog_content = "戦いは…終わったのではないのですか？",
  ui_story_1018_10181002_56_dialog_content = "トワイライトシティの戦いは終わりました。\n安心してください。",
  ui_story_1018_10181002_57_dialog_content = "ただ光霊の戦いは始まったばかりのようです。\n私が神殿を離れた意味もそこにあるのです。",
  ui_story_1018_10181002_58_dialog_content = "旅の途中であなた方と出会えたことをとても嬉しく思っています。\n皆さんのことは私がお守りします。",
  ui_story_1018_10181002_59_dialog_content = "光の神が汝と共にあらんことを。\n皆さんと再会できる日を心待ちにしています。",
  ui_story_1018_10181002_60_dialog_content = "光の神よ、永遠なれ――",
  ui_story_1018_10181002_61_dialog_content = "白夜に捧ぐ――",
  ui_story_1018_10181002_62_dialog_content = "…暗鬼は撤退したのではなく、啓光の防衛線へ向かったのね。\n今回の暗潮は簡単には収まりそうにないわね…",
  ui_story_1018_10181002_63_dialog_content = "あんたたちの耳にも届いたのね。",
  ui_story_1018_10181002_64_dialog_content = "ラス大元帥様…聖女様がおっしゃっていました…\n少なくともトワイライトシティはもう安全だと…",
  ui_story_1018_10181002_65_dialog_content = "啓光軍と騎士団が共に戦ったからこそ、\nトワイライトシティは災難を免れたのです！",
  ui_story_1018_10181002_66_dialog_content = "そう言ってもらえて嬉しいわ。\nでもジョセリン、慰めてくれなくていいのよ。",
  ui_story_1018_10181002_67_dialog_content = "事の次第が徐々にはっきりしてきて、\n私はむしろ喜んでいるのよ。",
  ui_story_1018_10181002_68_dialog_content = "結果だけを見れば、私たちは成功した…\nでも私にとっては大きな失敗ね…",
  ui_story_1018_10181002_69_dialog_content = "ラス大元帥、今のこの状況は\nすでに啓光単独で対応できる範囲を越えているわ。",
  ui_story_1018_10181002_70_dialog_content = "トワイライトシティの戦いが苦境に陥っていた時、\n白夜城は見て見ぬふりをしていた。",
  ui_story_1018_10181002_71_dialog_content = "今は城主の軍も防衛線に集結している。\n啓光がどう出ようと、白夜城もこれ以上見てみぬふりはしないわ。",
  ui_story_1018_10181002_72_dialog_content = "誤解しないで、カレン殿下。\n失敗したからこそ、すべてに意味があるのよ。",
  ui_story_1018_10181002_73_dialog_content = "トワイライトシティの戦い、部下の犠牲、そして上層部の計画…\nすべては私の失敗で終わらせなければならないの。",
  ui_story_1018_10181002_74_dialog_content = "そうしてこそ、啓光の未来が開けるわ。",
  ui_story_1018_10181002_75_dialog_content = "大元帥、あなたは…同僚たちと何か計画しているの？",
  ui_story_1018_10181002_76_dialog_content = "己の信じるものは私がこの手で確かめる。\n防衛線に待っている危険がどんなものであろうとね。",
  ui_story_1018_10181002_77_dialog_content = "私は啓光が第二のトワイライトシティになるのではないかと心配している…",
  ui_story_1018_10181002_78_dialog_content = "アクセリアが言っていただろう、部下がノラに連れて行かれたと。",
  ui_story_1018_10181002_79_dialog_content = "啓光を守るのは、血の通った啓光の者たちよ。\n第二のトワイライトシティにはならないわ。",
  ui_story_1018_10181002_80_dialog_content = "犠牲になった部下たちに約束したわ。\n何があろうと必ず啓光に連れ帰ると。",
  ui_story_1018_10181002_81_dialog_content = "トワイライトシティのことは後日相談させてもらうわね。\n今は全軍防衛線に向かうわ。",
  ui_story_1018_10181002_82_dialog_content = "防衛線に向かうのなら、騎士団も同行しよう。",
  ui_story_1018_10181002_83_dialog_content = "まだ敵は排除できていない。\n忘れるな、我々は共に戦う盟友だ。",
  ui_story_1018_10181002_84_dialog_content = "アハハ、トワイライトシティの盟友とはよく言ったものね。\nいいわ、忘れないわ。",
  ui_story_1018_10181002_85_dialog_content = "では、レオ騎士団長、ラス大元帥。\n差し支えなければ、白夜城の飛空艇で向かいましょう。",
  ui_story_1018_10181002_86_dialog_content = "私は遠慮させていただきます。騎士は馬で移動し、馬と共に戦います。\n飛空艇はどうもなじめません。",
  ui_story_1018_10181002_87_dialog_content = "カレン殿下、ご厚意に感謝するわ。\nでも、それは啓光の規則に反するわ。",
  ui_story_1018_10181002_88_dialog_content = "兵士たちは疲弊しきっているでしょう？\n飛空艇で少しでも休んだ方がいいわ。",
  ui_story_1018_10181002_89_dialog_content = "カレンの言う通りだよ。この後も苦しい戦いが待ってるんだ。\n今のうちに休んでおかなきゃ。",
  ui_story_1018_10181002_90_dialog_content = "この先の道中もずっと馬車に揺られ続けたら、\n重傷の兵士は持ちこたえられないかも…",
  ui_story_1018_10181002_91_dialog_content = "…あんたまで将たる者の考えるべきことが分かってきたの？",
  ui_story_1018_10181002_92_dialog_content = "トワイライトシティは本当に人を育てる所みたいね。",
  ui_story_1018_10181002_93_dialog_content = "大元帥様、ご厚意に甘えることにいたしましょうか。",
  ui_story_1018_10181002_94_dialog_content = "団長、我々も…？",
  ui_story_1018_10181002_95_dialog_content = "…",
  ui_story_1018_10181002_96_dialog_content = "一緒においでよ、レオ。",
  ui_story_1018_10181002_97_dialog_content = "共に戦う盟友なんだからモタモタしないで、騎士さん。",
  ui_story_1018_10181002_98_dialog_content = "…うむ！",
  ui_story_1018_10181101_1_dialog_content = "<color=#e8d9bb>啓光の防衛線</color>",
  ui_story_1018_10181101_2_dialog_content = "軍団長、ご報告いたします。\n東西の防衛線上に現れた騎兵は白夜城の兵と確認できました。",
  ui_story_1018_10181101_3_dialog_content = "現在東西の防衛線には暗鬼の影は見えず、\n白夜城の騎兵と我々の守備部隊が見張りを続けています。",
  ui_story_1018_10181101_4_dialog_content = "分かった。",
  ui_story_1018_10181101_5_dialog_content = "暗鬼の進攻経路に変化はあるか？",
  ui_story_1018_10181101_6_dialog_content = "いいえ。終始中部から内陸部へ垂直方向に進攻しています。\n攻撃部隊が敵方と交戦中ですが、条件が整い次第、敵部隊を突破します。",
  ui_story_1018_10181101_7_dialog_content = "今は相手の目標もまだ分かっていない。\n攻撃部隊は塹壕の外側で暗鬼を防ぐだけでいい。",
  ui_story_1018_10181101_8_dialog_content = "しかし軍団長…暗鬼の群れを一つたたいても、またすぐに別の群れが進攻してきます。\n本当にこのまま防御に徹しているだけで大丈夫でしょうか…？",
  ui_story_1018_10181101_9_dialog_content = "やつらはただ挑発しているにすぎない。\n本気で進攻しているわけではない。",
  ui_story_1018_10181101_10_dialog_content = "敵の状況が読めないうちは、軽々しく動かないことだ。",
  ui_story_1018_10181101_11_dialog_content = "防御設備の方はどうなっている？",
  ui_story_1018_10181101_12_dialog_content = "シェルター間の防御はバートン将軍が担当されています。\nヒイロ将軍の部隊はまもなく防衛線に到着するはずです。",
  ui_story_1018_10181101_13_dialog_content = "先刻の通信障害がまだ回復していないので、ご指示に従い通知を出し、\n地上戦には正面軍を配備してあります。",
  ui_story_1018_10181101_14_dialog_content = "シェルターは各自防衛に努めているので、\n防衛線の戦況には影響しません。",
  ui_story_1018_10181101_15_dialog_content = "よし。トワイライトシティからの知らせはまだか？",
  ui_story_1018_10181101_16_dialog_content = "大元帥様からの知らせはまだ来ておりません。\nただ白夜城軍の警戒態勢から見るに、トワイライトシティの戦いは終わりに近づいているようです。",
  ui_story_1018_10181101_17_dialog_content = "…予測通りだといいのだが。",
  ui_story_1018_10181101_18_dialog_content = "軍団長、防衛線の外の塹壕から突然ぬかるみが湧き出て、\n兵士が数名落ちてしまいました！",
  ui_story_1018_10181101_19_dialog_content = "暗鬼の進攻が今までより激しくなっています！",
  ui_story_1018_10181101_20_dialog_content = "塹壕だと？今までぬかるみが拡散した痕跡はなかったはずだが。",
  ui_story_1018_10181101_21_dialog_content = "はい、軍団長。ぬかるみは徐々に拡散してきたのではありません。\n突然地下から湧いて出たのです！",
  ui_story_1018_10181101_22_dialog_content = "兵士の話では、最初は泥があっただけだったらしいのですが、\nその泥が突然うずを巻き始め、どんどんと増えていったそうです。",
  ui_story_1018_10181101_23_dialog_content = "すでに周辺の砦まで広がっています！",
  ui_story_1018_10181101_24_dialog_content = "…",
  ui_story_1018_10181101_25_dialog_content = "東西の防衛線にいる白夜城の騎兵たちに情報を共有するのだ。\n守備部隊は迅速に中部に集結するように！",
  ui_story_1018_10181101_26_dialog_content = "突撃部隊は全員、即刻私の後について中部へ向かえ！",
  ui_story_1018_10181101_27_dialog_content = "了解です！",
  ui_story_1018_10181101_28_dialog_content = "こんなものが砦ですって？\n10年前からちっとも変わっていないのね。",
  ui_story_1018_10181101_29_dialog_content = "＜食べ物――＞",
  ui_story_1018_10181101_30_dialog_content = "ここへは食事しに来たんじゃないわよ。\n使えるヤツらを運んできてくれたなら、それでいいの。",
  ui_story_1018_10181101_31_dialog_content = "もうすぐ、暗面から中心部へと続く道が開けるわ。",
  ui_story_1018_10181101_32_dialog_content = "＜青い炎が燃えている――＞",
  ui_story_1018_10181101_33_dialog_content = "フフ、対応が早いわね。",
  ui_story_1018_10181101_34_dialog_content = "お前だったか。同胞に背いた裏切者め。",
  ui_story_1018_10181101_35_dialog_content = "フフ、そんなこと言える立場かしら？\nあなたも兵士を殺したこと忘れたの？",
  ui_story_1018_10181101_36_dialog_content = "恥知らずめ！\nトワイライトシティで犠牲になった兵士たちはお前の仕業か？",
  ui_story_1018_10181101_37_dialog_content = "全部じゃないわ。兵士の多くは仲間にやられたの。\nまあ、使い捨てするのは啓光のお得意でしょう？",
  ui_story_1018_10181101_38_dialog_content = "無駄話はそこまでだ。覚悟しろ！",
  ui_story_1018_10181101_39_dialog_content = "覚悟すべきはあなたでしょう？\n新任大元帥も相当苦しんだのよ。",
  ui_story_1018_10181101_40_dialog_content = "…この者たちは！？",
  ui_story_1018_10181101_41_dialog_content = "見覚えあるでしょ？\n賢い人間なら、こうなることくらいとうに分かってたはずよね。",
  ui_story_1018_10181101_42_dialog_content = "…ラスはどうしたのだ？",
  ui_story_1018_10181101_43_dialog_content = "死ぬのも時間の問題でしょうね。\nあいつが死ねば、大元帥の椅子はあなたのものよ。",
  ui_story_1018_10181101_44_dialog_content = "大元帥を侮辱する気か！",
  ui_story_1018_10181101_45_dialog_content = "グォォ！！！",
  ui_story_1018_10181101_46_dialog_content = "…",
  ui_story_1018_10181101_47_dialog_content = "どうしたの？さすがに手は出せないかしら？\n心の準備が必要なら急ぐことね。",
  ui_story_1018_10181101_48_dialog_content = "…軍団長、やつはぬかるみの中に身を隠せるようです…",
  ui_story_1018_10181101_49_dialog_content = "まさかトワイライトシティはすでに沈み、\nそのぬかるみが地下から広がってきたんでしょうか…",
  ui_story_1018_10181101_50_dialog_content = "啓光の防衛線も…ぬかるみに飲み込まれてしまうんですか？",
  ui_story_1018_10181101_51_dialog_content = "…まずは暗鬼を片付けろ。\n私は塹壕の下の状況を確める。",
  ui_story_1018_10181101_52_dialog_content = "地下から湧いて出てこられるのであれば、\n地下シェルターを直接攻撃した方が早い。",
  ui_story_1018_10181101_53_dialog_content = "動揺することはない。前線を守れ！",
  ui_story_1018_10181101_54_dialog_content = "了解しました！",
  ui_story_1018_10181101_55_dialog_content = "攻撃部隊は石壁の辺りまで退き、\n暗鬼を掃討しろ。",
  ui_story_1018_10181101_56_dialog_content = "グォォ！！！",
  ui_story_1018_10181101_57_dialog_content = "軍団長、か、彼は…啓光の兵士ですか？",
  ui_story_1018_10181101_58_dialog_content = "彼らの身体には暗力が密集し、\n暗鬼を食らい、同胞を傷つけている…",
  ui_story_1018_10181101_59_dialog_content = "やつらは暗鬼だ、容赦は無用！",
  ui_story_1018_10181101_60_dialog_content = "りょ、了解です、軍団長！",
  ui_story_1018_10181102_1_dialog_content = "<color=#e8d9bb>ゴゴゴ――</color>",
  ui_story_1018_10181102_2_dialog_content = "砲弾です！ぬかるみの拡散が止まったようです！",
  ui_story_1018_10181102_3_dialog_content = "暗鬼も同様です！",
  ui_story_1018_10181102_4_dialog_content = "軍団長、迅速かつ的確なご命令でしたね！",
  ui_story_1018_10181102_5_dialog_content = "私が下した命ではない…",
  ui_story_1018_10181102_6_dialog_content = "…砲弾はそれぞれ3カ所の砦から発射されたようです。",
  ui_story_1018_10181102_7_dialog_content = "まさか…",
  ui_story_1018_10181102_8_dialog_content = "ハハハッ、ゾクゾクするぜ！\nこんな興奮する爆音を聞いたのは久しぶりだ！",
  ui_story_1018_10181102_9_dialog_content = "目標からわずかにずれたようですが、\n期待していた効果は出たようですね。",
  ui_story_1018_10181102_10_dialog_content = "軍団長、バートン将軍とヒイロ将軍です！",
  ui_story_1018_10181102_11_dialog_content = "やはり他の軍団長たちの援護でしたか！",
  ui_story_1018_10181102_12_dialog_content = "シェルターの防御の方はうまくいってるんだ。\n防衛線の戦いをこのバートン様が逃すわけねえだろ！",
  ui_story_1018_10181102_13_dialog_content = "ここまで攻め込まれて、\n後ろで静かにしている理由はありません。",
  ui_story_1018_10181102_14_dialog_content = "2人の援護に心から感謝する。\n今のところ暗鬼の行動は我々の抑え込める範囲内に留まっている。",
  ui_story_1018_10181102_15_dialog_content = "ただ塹壕からぬかるみが湧いて出た。\nシェルターまで浸透していないかが心配だ。",
  ui_story_1018_10181102_16_dialog_content = "ここへ来るまで、そのような現象は見られませんでした。\n敵はおそらく防衛線に到着したばかりでしょう。",
  ui_story_1018_10181102_17_dialog_content = "その通りだ。防衛線の周りは俺が張ってたからな。",
  ui_story_1018_10181102_18_dialog_content = "ぬかるみはここ以前にトワイライトシティを破壊している。\nしかも今度もノラだ…",
  ui_story_1018_10181102_19_dialog_content = "どういう状況であろうと、共に立ち向かいましょう。",
  ui_story_1018_10181102_20_dialog_content = "後はラスを待つだけだ。\n計画通りに行けばいいのだが…",
  ui_story_1018_10181102_21_dialog_content = "私は信じている。",
  ui_story_1018_10181102_22_dialog_content = "…大元帥様！",
  ui_story_1018_10181102_23_dialog_content = "私もラスを信じます！",
  ui_story_1018_10181102_24_dialog_content = "参謀長まで…なぜ…？",
  ui_story_1018_10181102_25_dialog_content = "ラスの計画では、暗鬼が防衛線に攻め込んで来た場合、\n私が最後に出兵することになっていました。",
  ui_story_1018_10181102_26_dialog_content = "命令を受けた後、大元帥様は私と行動を共にする手はずでした。",
  ui_story_1018_10181102_27_dialog_content = "つまり…さっきの3発の砲弾の内、1発は大元帥様が！？",
  ui_story_1018_10181102_28_dialog_content = "<color=#FFB400>戦車を扱う</color>のは久しぶりだったが、\n腕はなまっていないようで安心した。",
  ui_story_1018_10181102_29_dialog_content = "しかし、大元帥様、どうやって監獄を…",
  ui_story_1018_10181102_30_dialog_content = "あ、忘れるところでした――",
  ui_story_1018_10181102_31_dialog_content = "ご報告いたします！\n参謀長ビビアン、脱獄任務を無事完了いたしました！",
  ui_story_1018_10181102_32_dialog_content = "まったく…",
  ui_story_1018_10181102_33_dialog_content = "大元帥様、ご報告いたします！第一軍団長キシローナ、\nご命令通り防衛線を守り、目下暗鬼の侵入を1匹たりとも許していません。",
  ui_story_1018_10181102_34_dialog_content = "第二軍団長バートンのいるところ、\n暗鬼1匹たりともシェルターに入れやしねえぜ！",
  ui_story_1018_10181102_35_dialog_content = "第三軍団長ヒイロ、最後の援護部隊として任務を完了いたしました。",
  ui_story_1018_10181102_36_dialog_content = "全員よくやった。啓光の同胞たちもご苦労だった！",
  ui_story_1018_10181102_37_dialog_content = "将軍と大元帥様が勢ぞろいするなんて、信じられません…",
  ui_story_1018_10181102_38_dialog_content = "大元帥様！",
  ui_story_1018_10181102_39_dialog_content = "おおおお！！！",
  ui_story_1018_10181201_1_dialog_content = "軍団長、塹壕内にノラの痕跡はありませんでした。",
  ui_story_1018_10181201_2_dialog_content = "現在白夜城の騎兵は依然として防衛線を守っています。\nトワイライトシティへ向かった援軍もこちらへ向かっているとのことです。",
  ui_story_1018_10181201_3_dialog_content = "分かった。援軍が現れ次第、すぐに報告しろ。",
  ui_story_1018_10181201_4_dialog_content = "どうやら白夜城は戦いに介入するつもりはないようだな。",
  ui_story_1018_10181201_5_dialog_content = "トワイライトシティの状況はまだ分かっていない。\n相談の余地はある。今心配なのはラスだ…",
  ui_story_1018_10181201_6_dialog_content = "その通りです。トワイライトシティからの知らせが途絶えてしばらくになります。",
  ui_story_1018_10181201_7_dialog_content = "私の責任です。ラスがトワイライトシティに向かってから、\nこの地を守るばかりで…",
  ui_story_1018_10181201_8_dialog_content = "攻め入れば、防衛線を破られかねず、\n防衛線内まで引けば、トワイライトシティの状況を知ることができません。",
  ui_story_1018_10181201_9_dialog_content = "さらにはぬかるみの拡散状況もまだ分からないまま、\nノラを逃がしてしまいました。",
  ui_story_1018_10181201_10_dialog_content = "お前の責任ではない。ここへ来る途中トワイライトシティの状況は聞いた。\n敵は前代未聞の攻撃を仕掛けてきた。皆くれぐれも気を付けるように。",
  ui_story_1018_10181201_11_dialog_content = "大元帥様、前方のぬかるみが動いています。\n敵が急速にこちらへ近づいてきます。",
  ui_story_1018_10181201_12_dialog_content = "まだ懲りねえってか？俺がやる！",
  ui_story_1018_10181201_13_dialog_content = "ぬかるみに気を付けろ。ノラが潜伏してる可能性があるぞ。",
  ui_story_1018_10181201_14_dialog_content = "ったくネズミみてえにチョロチョロしやがって。\nそんなんで防衛線を破る気か？",
  ui_story_1018_10181201_15_dialog_content = "豹の一撃！",
  ui_story_1018_10181201_16_dialog_content = "＜すべて飲み込んでやる――＞",
  ui_story_1018_10181201_17_dialog_content = "おお、虫ケラ、やっと出てきやがったか！",
  ui_story_1018_10181201_18_dialog_content = "＜グオオ――＞",
  ui_story_1018_10181201_19_dialog_content = "軍団長！ぬかるみから暗鬼が出現し、\n正体不明の兵士が大量に防衛線に向かって移動してきます！",
  ui_story_1018_10181201_20_dialog_content = "大元帥様、ご指示を！",
  ui_story_1018_10181201_21_dialog_content = "…",
  ui_story_1018_10181201_22_dialog_content = "命令は出さない。今この戦場は私の指揮下にはない。",
  ui_story_1018_10181201_23_dialog_content = "大元帥様…",
  ui_story_1018_10181201_24_dialog_content = "話し合っている時間はないぞ。\n私は私個人として戦いに参加する。",
  ui_story_1018_10181201_25_dialog_content = "お前たちも各自計画に従い、存分に務めを果たせ。",
  ui_story_1018_10181201_26_dialog_content = "…",
  ui_story_1018_10181201_27_dialog_content = "だったら、わざわざ運んできた砲弾を無駄にするワケにはいかねえな！\n東側砲撃手、敵に照準！",
  ui_story_1018_10181201_28_dialog_content = "西側砲撃手、敵に照準！",
  ui_story_1018_10181201_29_dialog_content = "軍団長、東西の守備部隊が集結しました。",
  ui_story_1018_10181201_30_dialog_content = "東西守備隊はぬかるみをたどりノラを捜索せよ。\n攻撃部隊は暗鬼を迎撃だ！",
  ui_story_1018_10181201_31_dialog_content = "待ってください、キシローナ…このぬかるみに覆われた暗鬼たちは…\n啓光の兵士ではないのですか…？",
  ui_story_1018_10181201_32_dialog_content = "…",
  ui_story_1018_10181201_33_dialog_content = "一部の者には…まだ意識がある。\nだが、多くはすでに完全に暗鬼となってしまった。",
  ui_story_1018_10181201_34_dialog_content = "では、どうしたら…",
  ui_story_1018_10181201_35_dialog_content = "私に任せろ。",
  ui_story_1018_10181201_36_dialog_content = "大元帥様…",
  ui_story_1018_10181201_37_dialog_content = "心配するな。望みがある限り、兵士は救う。",
  ui_story_1018_10181201_38_dialog_content = "しかし大元帥様、彼らは兵士を食らっています。\n私は先程すでに…",
  ui_story_1018_10181201_39_dialog_content = "私がお前の立場なら、同じことをするだろう。\nただ私ならやつらに食われても問題はない。",
  ui_story_1018_10181201_40_dialog_content = "引き続き部下の指揮に努めよ。\n負傷者を連れ帰る部隊もまもなく到着するだろう。",
  ui_story_1018_10181201_41_dialog_content = "はい、大元帥様。",
  ui_story_1018_10181201_42_dialog_content = "<color=#e8d9bb>ドカーン――</color>",
  ui_story_1018_10181201_43_dialog_content = "あれは…ヒイロ将軍の砲弾でしょうか。\nぬかるみに命中です！",
  ui_story_1018_10181201_44_dialog_content = "…西側砲撃手はまだ攻撃していません。",
  ui_story_1018_10181201_45_dialog_content = "こっち見るんじゃねえよ。俺でもねえ。",
  ui_story_1018_10181201_46_dialog_content = "ということは…",
  ui_story_1018_10181201_47_dialog_content = "フフ、あなたが来たところで、\nマッドバンドルを止められると思うの？",
  ui_story_1018_10181201_48_dialog_content = "トワイライトシティは、彼が潰したのよ――",
  ui_story_1018_10181201_49_dialog_content = "＜ぬかるみは防衛線を越える――＞",
  ui_story_1018_10181201_50_dialog_content = "ノラ、トワイライトシティはすでに潰したというのに、\nなぜまた防衛線を攻撃する？",
  ui_story_1018_10181201_51_dialog_content = "どうしたの？監獄に入れられたっていうのに、\nまだ啓光のことを考えているの？",
  ui_story_1018_10181201_52_dialog_content = "戦うより、大人しく城門を開いて、\nあなたを陥れたヤツらを私に任せた方がいいんじゃない？",
  ui_story_1018_10181201_53_dialog_content = "ふっ、啓光には啓光のやり方がある。\nお前たちはここまでだ。",
  ui_story_1018_10181201_54_dialog_content = "相変わらず聖人ぶった口の利き方をするのね。\nどうりで失敗するわけね。",
  ui_story_1018_10181201_55_dialog_content = "大元帥様になんてことを！",
  ui_story_1018_10181201_56_dialog_content = "イヌは黙ってなさい。ここには大元帥なんていないでしょ。",
  ui_story_1018_10181201_57_dialog_content = "大元帥がいないだと？いるではないか。",
  ui_story_1018_10181201_58_dialog_content = "<color=#e8d9bb>振動する大地から耳をつんざくような車輪の音と馬蹄の音が聞こえてきた…</color>",
  ui_story_1018_10181201_59_dialog_content = "早めに地上に降りて正解だったわ。\nやはり地上を走る方がしっくりくるわね！",
  ui_story_1018_10181201_60_dialog_content = "前方の塹壕を越えれば、敵も逃げ場を失うわ。\n戦車はぬかるみを狙って砲撃を続けなさい！",
  ui_story_1018_10181201_61_dialog_content = "ふむ、啓光の防衛線は実ににぎやかだな。\n敵はまたもや直接攻め込んで来たか。",
  ui_story_1018_10181201_62_dialog_content = "フン、望むところよ。\n包囲網の最後の鉄壁は私たちで築くのよ。",
  ui_story_1018_10181201_63_dialog_content = "アクセリアは部下を探し出します…",
  ui_story_1018_10181201_64_dialog_content = "もう回復したのか？アクセリアの身体はまるで\n啓光の戦闘機械だな…",
  ui_story_1018_10181201_65_dialog_content = "アクセリアのすごいところはひどいケガだったのに、\nケガする前の状態まで回復できることだと思うな…",
  ui_story_1018_10181201_66_dialog_content = "PlayerName、十分休んだようなら戦いを始めるわよ。\n到着点まで目の前の暗鬼を倒しながら進まなくては。",
  ui_story_1018_10181201_67_dialog_content = "うん、分かった。",
  ui_story_1018_10181201_68_dialog_content = "しっかりつかまってなさい。\nここで落伍したら、砲撃手に暗鬼として狙われるだけよ。",
  ui_story_1018_10181201_69_dialog_content = "…分かった。",
  ui_story_1018_10181201_70_dialog_content = "<color=#e8d9bb>ザッ――</color>",
  ui_story_1018_10181201_71_dialog_content = "方向転換するわ、気を付けて！",
  ui_story_1018_10181201_72_dialog_content = "エンジン7号？突然…塹壕の中から現れました！",
  ui_story_1018_10181201_73_dialog_content = "あれは…トワイライトシティで壊れた1台よ…",
  ui_story_1018_10181201_74_dialog_content = "戦闘機械まで持って来られるとは…\nどうりで兵士がごそっと消えたわけね…",
  ui_story_1018_10181201_75_dialog_content = "…グオオ…",
  ui_story_1018_10181201_76_dialog_content = "…この声は…操縦士はまだ意識があるのでしょうか？",
  ui_story_1018_10181201_77_dialog_content = "近づいてはいけない――足下から兵士が這い上がってくるぞ！",
  ui_story_1018_10181201_78_dialog_content = "ぬかるみに…いったいどれだけの兵士が…",
  ui_story_1018_10181201_79_dialog_content = "<color=#e8d9bb>ジッ――ガシャッ――ガシャッ――</color>",
  ui_story_1018_10181201_80_dialog_content = "この動き…迷ってるんだ…",
  ui_story_1018_10181201_81_dialog_content = "大元帥、中の兵士はまだ助かるかもしれません。\nアクセリアは助けたいです。",
  ui_story_1018_10181201_82_dialog_content = "あんたはもう…1度壊れてるのよ！",
  ui_story_1018_10181201_83_dialog_content = "これまでにアクセリアは何度も壊れてきました…",
  ui_story_1018_10181201_84_dialog_content = "でも、そのたびに直りました。",
  ui_story_1018_10181201_85_dialog_content = "中にいる操縦士はアクセリアの部隊の隊員です。\n隊員を守るのはアクセリアの務めです。",
  ui_story_1018_10181201_86_dialog_content = "…",
  ui_story_1018_10181201_87_dialog_content = "…グオオ…",
  ui_story_1018_10181201_88_dialog_content = "肉体がもう機械と一体化しちゃってる…\n操縦士さん、きっと辛いだろうね…",
  ui_story_1018_10181201_89_dialog_content = "アーマーはアクセリアの身体の一部です。\nだから、アクセリアには分かります。今彼は苦しんでいます。",
  ui_story_1018_10181201_90_dialog_content = "…ごめん…アクセリア…",
  ui_story_1018_10181201_91_dialog_content = "ラス、僕がアクセリアと一緒に行くよ！\n一緒にアクセリアの部下を助けてみせる！",
  ui_story_1018_10181201_92_dialog_content = "…大元帥なら、あんたたちを止めるべきなんだろうけど、\nここまで来たら…",
  ui_story_1018_10181201_93_dialog_content = "レオ、エンジン7号の注意を引いて！",
  ui_story_1018_10181201_94_dialog_content = "承知した。",
  ui_story_1018_10181201_95_dialog_content = "ラス…どうして？",
  ui_story_1018_10181201_96_dialog_content = "あんたたちだけに背負わせるわけにはいかないわ。",
  ui_story_1018_10181201_97_dialog_content = "エンジン7号はトワイライトシティで我が軍の砦の役割を担っていた。\nでも、今は私たちの前に立ちはだかっている。",
  ui_story_1018_10181201_98_dialog_content = "あんたたちを傷つけるつもりなら、\nまずは私という砦を越えるべきよ。",
  ui_story_1018_10181201_99_dialog_content = "グォォ！！！",
  ui_story_1018_10181201_100_dialog_content = "大変だ、塹壕の中から兵士たちが這い上がってくる…",
  ui_story_1018_10181201_101_dialog_content = "アクセリアの…部下たちです…",
  ui_story_1018_10181201_102_dialog_content = "私の部下を使って私を止めようとしたって、\nそうはいかないわよ！",
  ui_story_1018_10181201_103_dialog_content = "安心して行きなさい、アクセリア！\nあんたの部下を救うのよ、兵士は私に任せて！",
  ui_story_1018_10181201_104_dialog_content = "アクセリア、了解しました。",
  ui_story_1018_10181202_1_dialog_content = "こっちの兵士は皆抑えたぞ。\nまだ意識がある。",
  ui_story_1018_10181202_2_dialog_content = "こっちもよ。エンジン7号の攻撃に気を付けて。",
  ui_story_1018_10181202_3_dialog_content = "…グオオ…",
  ui_story_1018_10181202_4_dialog_content = "アクセリアには分かります。\nあなたは今とても辛い思いをしています。",
  ui_story_1018_10181202_5_dialog_content = "あなたも皆を傷つけたくはないんです…\nアクセリアには、分かります。",
  ui_story_1018_10181202_6_dialog_content = "グォォ…",
  ui_story_1018_10181202_7_dialog_content = "ゆっくりと防衛線の方へ移動していく…\nあっちには敵はいないよ。",
  ui_story_1018_10181202_8_dialog_content = "注意深く付いていくのよ！塹壕を越えたところで、\n背後から抑え込みなさい！",
  ui_story_1018_10181202_9_dialog_content = "グォォ！！！",
  ui_story_1018_10181202_10_dialog_content = "やるしかないわ！",
  ui_story_1018_10181202_11_dialog_content = "アクセリア、離れて！",
  ui_story_1018_10181202_12_dialog_content = "貫け、雷槍よ！",
  ui_story_1018_10181202_13_dialog_content = "グォォ…",
  ui_story_1018_10181202_14_dialog_content = "止まった！でも、アクセリアが――",
  ui_story_1018_10181202_15_dialog_content = "レオ、アクセリアがそっちに行ったわ！",
  ui_story_1018_10181202_16_dialog_content = "はっ――",
  ui_story_1018_10181202_17_dialog_content = "この距離なら問題ない！",
  ui_story_1018_10181202_18_dialog_content = "はっ――",
  ui_story_1018_10181202_19_dialog_content = "<color=#e8d9bb>ヒヒーン――</color>",
  ui_story_1018_10181202_20_dialog_content = "どう――",
  ui_story_1018_10181202_21_dialog_content = "相変わらず勇ましいな。トワイライトシティのレオ。",
  ui_story_1018_10181202_22_dialog_content = "あなたは…なぜここに？",
  ui_story_1018_10181202_23_dialog_content = "アクセリア、ご苦労だった。",
  ui_story_1018_10181202_24_dialog_content = "…大元帥が、アクセリアを受け止めてくれました。",
  ui_story_1018_10181202_25_dialog_content = "すでにエキシビジョンで見せた実力を越えたのだな。\nお前は実に優秀な戦士だ。",
  ui_story_1018_10181202_26_dialog_content = "アクセリアは…大元帥の言った言葉をずっと考えていました…",
  ui_story_1018_10181202_27_dialog_content = "アクセリアは大元帥に聞きたいことがあります。\n暗鬼に勝ち、啓光を守った戦士は…",
  ui_story_1018_10181202_28_dialog_content = "「人として生きて」いることになるのでしょうか？",
  ui_story_1018_10181202_29_dialog_content = "ああ、お前は見事成し遂げたぞ、アクセリア。",
  ui_story_1018_10181202_30_dialog_content = "ありがとうございます、大元帥。\nアクセリアは、引き続き戦います。",
  ui_story_1018_10181202_31_dialog_content = "戦う機会はこれから先もいくらでもある、アクセリア。\n仲間がお前を心配して迎えに来ている。",
  ui_story_1018_10181202_32_dialog_content = "アクセリア！よかった、間に合ったようですね…",
  ui_story_1018_10181202_33_dialog_content = "インゲル…",
  ui_story_1018_10181202_34_dialog_content = "ごめんなさい！私は…分かっていたのに…\nあなたをこんな目に遭わせて…ごめんなさい！",
  ui_story_1018_10181202_35_dialog_content = "アクセリアは知っています。\nインゲルはアクセリアを守りたいと思っています。",
  ui_story_1018_10181202_36_dialog_content = "アクセリアが無事で本当によかったね。だから言ったでしょ？\n善良な小鳥ちゃんは必ず報われるって！",
  ui_story_1018_10181202_37_dialog_content = "大元帥！最高科学責任者ガルー、\nインゲル中佐と一緒に啓光の兵士を迎えに来たよ！",
  ui_story_1018_10181202_38_dialog_content = "ああ、戦士たちはお前たちに任せたぞ。",
  ui_story_1018_10181202_39_dialog_content = "大元帥様、公開裁判でのことですが…\n申し訳ございませんでした。",
  ui_story_1018_10181202_40_dialog_content = "ユリシーズ教授の実験のことも…",
  ui_story_1018_10181202_41_dialog_content = "ですが、信じてください。この件について教授をこれ以上かばうつもりはありません。\n罪のない同胞が傷つくのをもう見ていられません。",
  ui_story_1018_10181202_42_dialog_content = "治療のため、まずは兵士たちを連れ、啓光に戻ることをお許しください。\n実験のことは、何とかして…",
  ui_story_1018_10181202_43_dialog_content = "お前たちは皆被害者だ。責任を感じることはない。",
  ui_story_1018_10181202_44_dialog_content = "ですが、私のせいで大元帥の地位を追われたのですよ…",
  ui_story_1018_10181202_45_dialog_content = "大元帥の地位はあんたの一言二言で奪えるものじゃないわ。",
  ui_story_1018_10181202_46_dialog_content = "私は感謝しているわ。\n1回でも大元帥になれたんだから。",
  ui_story_1018_10181202_47_dialog_content = "戻ったか、ラス。",
  ui_story_1018_10181202_48_dialog_content = "わあ～！大元帥が2人も！",
  ui_story_1018_10181202_49_dialog_content = "ラスならきっと問題ないと思っていました！",
  ui_story_1018_10181202_50_dialog_content = "なかなか大元帥らしくなってんじゃねえか。",
  ui_story_1018_10181202_51_dialog_content = "トワイライトシティの激戦を何とか乗り越えたか。",
  ui_story_1018_10181202_52_dialog_content = "防衛線でずっと待っていたのですよ。",
  ui_story_1018_10181202_53_dialog_content = "しばらく代わりに大元帥の椅子を守っていてあげる、\nそして生きて戻ってくると言ったはずよ。このラスが約束を破るわけないでしょう？",
  ui_story_1018_10181202_54_dialog_content = "大元帥様、軍団長、まさか…",
  ui_story_1018_10181202_55_dialog_content = "…",
  ui_story_1018_10181202_56_dialog_content = "ずっと一つの結果にこだわって、もがいてきたけど、\nこれでようやく分かったわ――",
  ui_story_1018_10181202_57_dialog_content = "ラス、お前には資格がある。",
  ui_story_1018_10181202_58_dialog_content = "まだ言い終わってないんだけど…",
  ui_story_1018_10181202_59_dialog_content = "お前はふさわしい。",
  ui_story_1018_10181202_60_dialog_content = "…",
  ui_story_1018_10181202_61_dialog_content = "コホン…そんなこと言って、私が喜んで受け入れると思うの？",
  ui_story_1018_10181202_62_dialog_content = "あんたに勝てなければ、安心して大元帥になんてなれないわ。",
  ui_story_1018_10181202_63_dialog_content = "戦いはまだ終わってないのよ。\nあんたがしっかり指揮しなさい。",
  ui_story_1018_10181202_64_dialog_content = "…",
  ui_story_1018_10181202_65_dialog_content = "近衛兵団長ラス、命に従い、トワイライトシティの暗鬼を撃退、\n任務を完了しました。",
  ui_story_1018_10181202_66_dialog_content = "啓光四軍団はすでに防衛線に集結を完了、\nあとは啓光大元帥の命令を待つだけです！",
  ui_story_1018_10181401_1_dialog_content = "時間は十分あったはずです。\nここに大きな穴が出来ているものとばかり思っていたのですが…",
  ui_story_1018_10181401_2_dialog_content = "どうしました？お姉様のことが惜しくなりましたか？",
  ui_story_1018_10181401_3_dialog_content = "バカなこと言わないで。そっちはうまく行ったようね。\nだから、これ以上待ちたくないだけでしょう？",
  ui_story_1018_10181401_4_dialog_content = "行きましょう。\nあなたの待ち望んだ瞬間がまもなくやってきます。",
  ui_story_1018_10181401_5_dialog_content = "そうね。ただここから離れる前に、\n1つだけ片付けておくものがあるわ。",
  ui_story_1018_10181401_6_dialog_content = "…ノラのことは私がよく知っている。実験に利がなければ、\n危険を冒してまで、これ程のことをやるわけがない。",
  ui_story_1018_10181401_7_dialog_content = "しかもヘリオスはまだカナン城にいる。\n今の状況はおそらくやつにとって予想外の結果なのだろう。",
  ui_story_1018_10181401_8_dialog_content = "つまり、ノラが啓光のシェルターに潜入したのは、\nユリシーズがノラに望むものを与えると約束したからということ…？",
  ui_story_1018_10181401_9_dialog_content = "でもユリシーズはノラには黙って、\n「シード」を手にしてすぐに「啓明の星計画」に使用した。",
  ui_story_1018_10181401_10_dialog_content = "その可能性はある。",
  ui_story_1018_10181401_11_dialog_content = "「ガーディアン1号」のコアが盗まれたのも、\nヤツらの取り引きか？",
  ui_story_1018_10181401_12_dialog_content = "日蝕の計画したことだろうが、\nユリシーズとノラの取り引きに含まれていたかどうかはまだ分からない。",
  ui_story_1018_10181401_13_dialog_content = "私はどちらかというと、「ガーディアン1号」のコアの件は、\nユリシーズの計画外だったと考えている。",
  ui_story_1018_10181401_14_dialog_content = "いくら委員会でも「啓明の星計画」のために\n「ガーディアン1号」のコアを日蝕に差し出すとは考えられない。",
  ui_story_1018_10181401_15_dialog_content = "代償が大きすぎるばかりか、「シード」を埋め込まれた兵士たちは\nたとえ今回持ちこたえられたとしても、将来戦場に再び出ることはできないのだから。",
  ui_story_1018_10181401_16_dialog_content = "今…何と言ったの？",
  ui_story_1018_10181401_17_dialog_content = "…",
  ui_story_1018_10181401_18_dialog_content = "…",
  ui_story_1018_10181401_19_dialog_content = "まさか…「シード」を…埋め込まれたのか？",
  ui_story_1018_10181401_20_dialog_content = "…それがどうしたっていうの？\n今こうして普通にしてるでしょ？",
  ui_story_1018_10181401_21_dialog_content = "…",
  ui_story_1018_10181401_22_dialog_content = "私がお前を大元帥に推したせいで、\n「シード」を埋め込まれる羽目になるとは…",
  ui_story_1018_10181401_23_dialog_content = "あんたとは関係ないわ。自分で決めたことよ。",
  ui_story_1018_10181401_24_dialog_content = "こんなことになるなら…",
  ui_story_1018_10181401_25_dialog_content = "私の「シード」がなかったら、\n彼女自身の力でここまで持ちこたえられたと思う？",
  ui_story_1018_10181401_26_dialog_content = "…ついに現れたか、ノラ。",
  ui_story_1018_10181401_27_dialog_content = "汚らわしい！",
  ui_story_1018_10181401_28_dialog_content = "ノラ！よくも私の部下を苦しめてくれたわね！\n今こそ決着をつける時よ。",
  ui_story_1018_10181401_29_dialog_content = "ラス、待って！ノラの背後のぬかるみの中に兵士がいる！",
  ui_story_1018_10181401_30_dialog_content = "グォォ…",
  ui_story_1018_10181401_31_dialog_content = "なんと陰湿な手を使うのでしょう…",
  ui_story_1018_10181401_32_dialog_content = "兵士たちを抑え込むのよ！防衛線を守ってちょうだい！\nここは私に任せて！",
  ui_story_1018_10181401_33_dialog_content = "了解！",
  ui_story_1018_10181401_34_dialog_content = "威勢がいいのね。あなたの体内の「シード」はどうして\nあなたをそこまで苦しめなかったのか、理由を知りたくないのかしら？＿",
  ui_story_1018_10181401_35_dialog_content = "それとも、ためらいもなく部下を殺して、実は痛快だった？",
  ui_story_1018_10181401_36_dialog_content = "黙れ、ノラ。啓光の兵士を苦しめたのはお前だ。",
  ui_story_1018_10181401_37_dialog_content = "…",
  ui_story_1018_10181401_38_dialog_content = "ぬかるみの中で私を助けたのは、やはりあんただったのね…",
  ui_story_1018_10181401_39_dialog_content = "部下を苦しめ…私を窮地に陥れて…\n「シード」が私の体内でどんな反応を起こすか見ようとしたのね…",
  ui_story_1018_10181401_40_dialog_content = "どうやら思っていたほど愚かではないようね。\nついでだったからユリシーズの手伝いをしてあげただけよ。彼は科学者失格ね。",
  ui_story_1018_10181401_41_dialog_content = "ノラ、日蝕がいったいお前に何を約束したというのだ？",
  ui_story_1018_10181401_42_dialog_content = "そんなこと、あなたに理解できっこないわ。\n自分にはすべてを守る力があるとでも思っているの？",
  ui_story_1018_10181401_43_dialog_content = "光霊は改造を受けたところで、\n相変わらず貧弱で頭の弱いクズでしかない。",
  ui_story_1018_10181401_44_dialog_content = "啓光の上層部に使い捨てされるくらいなら、\nあなたも早いうちに活路を探しておくといいわ。",
  ui_story_1018_10181401_45_dialog_content = "フッ、あんたなんて日蝕に身を投じた、操り人形の暗鬼でしかない。\n何をそんなに得意になっているの？",
  ui_story_1018_10181401_46_dialog_content = "自分は賢いと思いあがっているようだけど、\nそれはあんたが「人造陽光」計画に参加したからにすぎないわ。",
  ui_story_1018_10181401_47_dialog_content = "ここにいる全員が、トワイライトシティで犠牲になった兵士も皆\n自分の意志と力でここまで来たのよ。",
  ui_story_1018_10181401_48_dialog_content = "それに比べたら、あんたなんて力に屈した奴隷でしかないわ。",
  ui_story_1018_10181401_49_dialog_content = "本当に弱いのはあんたの方よ！",
  ui_story_1018_10181401_50_dialog_content = "黙りなさい！頭のおかしくなった愚か者の分際で！\n今あなたは私の「シード」のおかげで生きていられるのよ。",
  ui_story_1018_10181401_51_dialog_content = "現実世界はおとぎ話ではないわ。\n生きていくために一切の代償を惜しまず、のし上がらなければならないのよ。",
  ui_story_1018_10181401_52_dialog_content = "ゴキブリのようにあちこち逃げ回ってばかりで、\n無知な光霊は死ぬまでこの世界の真相を知ることはない。",
  ui_story_1018_10181401_53_dialog_content = "ノラ、お前にはお前の抱負があることは知っている。\nだが、他人の犠牲を代償にそれを実現することはこの私が許さない。",
  ui_story_1018_10181401_54_dialog_content = "こんなことを言うのもこれが最後だ――",
  ui_story_1018_10181401_55_dialog_content = "お前は啓光の同胞を傷つけた。啓光はお前を決して許さない。\nだが私は今大元帥ではない。ここまでにしてくれ。",
  ui_story_1018_10181401_56_dialog_content = "日蝕の言うことなど聞くな。\n日蝕に従うなど、お前の本当の意志ではないはずだ。",
  ui_story_1018_10181401_57_dialog_content = "操り人形はあなたでしょう、レインハト！\nあなたにすべての者は守れない。",
  ui_story_1018_10181401_58_dialog_content = "同情するふりは止してちょうだい。\nあなたとはとうに仲間ではないのよ。",
  ui_story_1018_10181401_59_dialog_content = "好きなだけ私を狙ってくればいいわ。\nただ、私も歩みを止めない。",
  ui_story_1018_10181401_60_dialog_content = "<color=#e8d9bb>ピカッ――</color>",
  ui_story_1018_10181401_61_dialog_content = "コホン、お別れの挨拶がお姉様への贈り物ですか？",
  ui_story_1018_10181401_62_dialog_content = "ファントムめ、食らえ！",
  ui_story_1018_10181401_63_dialog_content = "兵士たちは抑えたというのに、\nここでファントムが現れるとは。",
  ui_story_1018_10181401_64_dialog_content = "私に本当に遊んであげるつもりがあったのなら、\nあなたたちなどとうの昔に命を落としていましたよ。",
  ui_story_1018_10181401_65_dialog_content = "ノラ、それ以上おしゃべりを続けていると、\n私の気が変わってしまいますよ。",
  ui_story_1018_10181401_66_dialog_content = "日蝕につくな、ノラ。命を落とすことになるぞ。",
  ui_story_1018_10181401_67_dialog_content = "私のことに構わないで。\nレインハト、あなたこそ私に殺されないように気を付けることね。",
  ui_story_1018_10181401_68_dialog_content = "<color=#e8d9bb>ピカッ――</color>",
  ui_story_1018_10181401_69_dialog_content = "体内の「シード」がかすかに震えているわ…\n気を付けて！近くに敵がいる！",
  ui_story_1018_10181401_70_dialog_content = "＜オエッ――＞",
  ui_story_1018_10181401_71_dialog_content = "グォォ！！！",
  ui_story_1018_10181401_72_dialog_content = "ヤツが吐き出したのは…\nノラがトワイライトシティから連れ去った兵士たち…",
  ui_story_1018_10181401_73_dialog_content = "グォォ！！！",
  ui_story_1018_10181401_74_dialog_content = "こ、こいつ、もうやられたんじゃなかったのかよ！？\nまた立ちやがったぞ！",
  ui_story_1018_10181401_75_dialog_content = "ノラめ、やはり手の内を残していたか。",
  ui_story_1018_10181401_76_dialog_content = "先刻ぬかるみが塹壕にたまり、\nこのアーマーは倒された後ずっと塹壕の中にあった。",
  ui_story_1018_10181401_77_dialog_content = "ならば、今ぬかるみから再び現れた暗鬼はおそらく、\nそう簡単には倒せないだろう…",
  ui_story_1018_10181401_78_dialog_content = "じゃ、どうすんだ、大元帥？",
  ui_story_1018_10181401_79_dialog_content = "…",
  ui_story_1018_10181401_80_dialog_content = "…",
  ui_story_1018_10181401_81_dialog_content = "部下を安らかに眠らせてやれなかったのは、\n私の責任よ…",
  ui_story_1018_10181401_82_dialog_content = "だから、部下たちの身体はなんとしても私が取り返す！",
  ui_story_1018_10181401_83_dialog_content = "さっきノラにやられたばかりだよ…",
  ui_story_1018_10181401_84_dialog_content = "自分の身体のことは自分がよく分かっているわ…\nちゃんと自分を制御できる…あの力は使わない。",
  ui_story_1018_10181401_85_dialog_content = "ぬかるみの「中心」を直接たたいて、\nもう一度めちゃめちゃにしてやるわ！",
  ui_story_1018_10181401_86_dialog_content = "ラス、私も攻撃に加わろう。\n狂暴化した兵士は任せろ。",
  ui_story_1018_10181401_87_dialog_content = "防衛線は俺たちに任せとけ！",
  ui_story_1018_10181401_88_dialog_content = "そのとおりだ/任せてください！",
  ui_story_1018_10181401_89_dialog_content = "大元帥――",
  ui_story_1018_10181401_90_dialog_content = "あんたたちまで…",
  ui_story_1018_10181401_91_dialog_content = "白夜空騎兵が援護するわ。\n暗鬼があなたたちを傷つけることはない。",
  ui_story_1018_10181401_92_dialog_content = "大元帥の戦い方は良く知っている。\nトワイライトシティの騎士がぬかるみの中まで援護しよう。",
  ui_story_1018_10181401_93_dialog_content = "ラス、僕もいるよ！戦闘をサポートする！",
  ui_story_1018_10181401_94_dialog_content = "白夜に捧ぐ――各勢力が集まってできた連合軍でございますね！",
  ui_story_1018_10181401_95_dialog_content = "なら、各自行動に移るわよ！\n敵を倒した後、合流しましょう！",
  ui_story_1018_10181401_96_dialog_content = "レインハト、それでいい？",
  ui_story_1018_10181401_97_dialog_content = "何があろうと、1人として啓光の同胞を見捨てはしない！",
  ui_story_1018_10181501_1_dialog_content = "<color=#e8d9bb>パラパラパラ――</color>",
  ui_story_1018_10181501_2_dialog_content = "え？雨…？",
  ui_story_1018_10181501_3_dialog_content = "めずらしいな。",
  ui_story_1018_10181501_4_dialog_content = "大元帥様、周囲に暗鬼の痕跡はありません。",
  ui_story_1018_10181501_5_dialog_content = "白夜城の部隊は東西の防衛線に向けて、\n戦場を掃討しに行きました。",
  ui_story_1018_10181501_6_dialog_content = "俺の方も順調だ。ぬかるみが退いてきてるぞ。\n防衛線は無事だ！",
  ui_story_1018_10181501_7_dialog_content = "ラスのヤツ、やるじゃねえか！",
  ui_story_1018_10181501_8_dialog_content = "ぬかるみが退いたのは、この雨と関係があるのかな？",
  ui_story_1018_10181501_9_dialog_content = "それは考えたことなかったけど、ということは…\n本当に終わったの…？",
  ui_story_1018_10181501_10_dialog_content = "目が覚めたか、大丈夫か？",
  ui_story_1018_10181501_11_dialog_content = "ずっと目は覚めているわ。ただ考えていたのよ…\nあの時、あんたが私に言ったこと…",
  ui_story_1018_10181501_12_dialog_content = "<color=#e8d9bb>ラスがユリシーズを訪ねる前…</color>",
  ui_story_1018_10181501_13_dialog_content = "あんた、いつまでこんな所にいるつもり？",
  ui_story_1018_10181501_14_dialog_content = "ここでその話はやめよう。判決はお前も聞いたはずだ。",
  ui_story_1018_10181501_15_dialog_content = "レインハト！",
  ui_story_1018_10181501_16_dialog_content = "あんたが敵と通じてたなんてバカな話、\n私が信じるとでも思ってるの？",
  ui_story_1018_10181501_17_dialog_content = "…",
  ui_story_1018_10181501_18_dialog_content = "「人造陽光」計画に参加した時も、\n今みたいにだんまりを決め込んでたの？",
  ui_story_1018_10181501_19_dialog_content = "聞いたのだな。",
  ui_story_1018_10181501_20_dialog_content = "あんたは改造を受けたから、\n決闘で私に勝てたってこと？",
  ui_story_1018_10181501_21_dialog_content = "…",
  ui_story_1018_10181501_22_dialog_content = "答えなさいよ！",
  ui_story_1018_10181501_23_dialog_content = "多くのことがお前の思うほど単純ではない。\n啓光を思うのなら、それ以上は聞くな。",
  ui_story_1018_10181501_24_dialog_content = "啓光の大元帥たる者が――",
  ui_story_1018_10181501_25_dialog_content = "だからこそだ！私はこの結果を受け入れねばならない。",
  ui_story_1018_10181501_26_dialog_content = "…",
  ui_story_1018_10181501_27_dialog_content = "分かったら、拳をゆるめろ。\n今は私と言い争っている時ではない。",
  ui_story_1018_10181501_28_dialog_content = "…",
  ui_story_1018_10181501_29_dialog_content = "お前の未来はその掌からあふれ出てくる。",
  ui_story_1018_10181501_30_dialog_content = "ずっと握りしめていたら、何も得られない。",
  ui_story_1018_10181501_31_dialog_content = "「握りしめていたら、何も得られない」…",
  ui_story_1018_10181501_32_dialog_content = "なぜ今この言葉を思い出したのかしら…？",
  ui_story_1018_10181501_33_dialog_content = "時が来たからだ。我々は今、拳を握りしめ、\n共通の敵に立ち向かわなければならない。",
  ui_story_1018_10181501_34_dialog_content = "振りかざした拳を共通の敵に向けよう。",
  ui_story_1018_10181501_35_dialog_content = "…",
  ui_story_1018_10181501_36_dialog_content = "私を信じろ。握りしめた私の拳の力は知っているはずだ。",
  ui_story_1018_10181501_37_dialog_content = "これもあんたの計画なの…？",
  ui_story_1018_10181501_38_dialog_content = "…",
  ui_story_1018_10181501_39_dialog_content = "もう覚悟はできたってことね？\n私に思い切りやれって…",
  ui_story_1018_10181501_40_dialog_content = "…",
  ui_story_1018_10181501_41_dialog_content = "分かったわ。",
  ui_story_1018_10181501_42_dialog_content = "ひとまず代わりに大元帥の椅子を守っておいてあげるわ。",
  ui_story_1018_10181501_43_dialog_content = "でも、私がいつか必ず鉄の柵を破って、\nあんたには思う存分私の相手になってもらうわよ。",
  ui_story_1018_10181501_44_dialog_content = "それまでは共に振りかざした拳を共通の敵に向けましょ。",
  ui_story_1018_10181501_45_dialog_content = "ラス。",
  ui_story_1018_10181501_46_dialog_content = "なに？",
  ui_story_1018_10181501_47_dialog_content = "思う存分やれ。ただし、必ず生きて帰ってこい。",
  ui_story_1018_10181501_48_dialog_content = "…",
  ui_story_1018_10181501_49_dialog_content = "<color=#e8d9bb>パラパラパラ――</color>",
  ui_story_1018_10181501_50_dialog_content = "こうして私は生きて帰ってきた。\nでも兵士たちは…もう救えない、そうなのね？",
  ui_story_1018_10181501_51_dialog_content = "ここまでもっただけでも十分立派だ。",
  ui_story_1018_10181501_52_dialog_content = "彼らは皆、本物の勇士だ。\n啓光が手厚く葬ろう。",
  ui_story_1018_10181501_53_dialog_content = "トワイライトシティにいた時には守ってやれず…\n防衛線でもまた彼らを敵として倒した…",
  ui_story_1018_10181501_54_dialog_content = "失敗ね…また失敗よ…",
  ui_story_1018_10181501_55_dialog_content = "大元帥になっても…私は敗者の運命なのね。",
  ui_story_1018_10181501_56_dialog_content = "ラス、お前は敗者などではない。\n皆を率いてトワイライトシティを守り、防衛線を守ったではないか。",
  ui_story_1018_10181501_57_dialog_content = "雨が強くなってきた。戻ろう。",
  ui_story_1018_10181501_58_dialog_content = "…",
  ui_story_1018_10181501_59_dialog_content = "戻ろう。放送で今日は天気がよくないと言っていた。\nおそらく地上では今ごろ雨が降っているのだろう。",
  ui_story_1018_10181501_60_dialog_content = "<color=#e8d9bb>パラパラ――</color>",
  ui_story_1018_10181501_61_dialog_content = "フフ…レインハト…",
  ui_story_1018_10181501_62_dialog_content = "何を笑っているのだ？",
  ui_story_1018_10181501_63_dialog_content = "大元帥って常にこんな無力感に襲われるものなの…",
  ui_story_1018_10181501_64_dialog_content = "目を閉じると、トワイライトシティで犠牲になった\n兵士たちの姿が浮かんでくるようよ…",
  ui_story_1018_10181501_65_dialog_content = "暗鬼になって同胞を傷つけることを恐れ、\n自分の頭に銃弾を撃ち込むことを選んだ…",
  ui_story_1018_10181501_66_dialog_content = "アクセリアの身体はもう数えきれないくらいボロボロになっているのに、\n部下を救うために何度でも立ち上がった…",
  ui_story_1018_10181501_67_dialog_content = "そして、ほんのわずかに残っていた最後の意識で、\n啓光へ帰ろうとしたさっきのあの兵士…",
  ui_story_1018_10181501_68_dialog_content = "戦いに勝つためには、\nこんなに大きな代償を払わなきゃいけないのね…",
  ui_story_1018_10181501_69_dialog_content = "あんたはきっと…こんな経験を何度も繰り返してきたのよね…",
  ui_story_1018_10181501_70_dialog_content = "それなのに、大元帥になってからずっと、\nあんたは少しも後悔した様子を見せなかった…",
  ui_story_1018_10181501_71_dialog_content = "アクセリアを守るために降参までした…",
  ui_story_1018_10181501_72_dialog_content = "啓光の未来のために、監獄に収容され、\n濡れ衣を着せられても抗わなかったわ…",
  ui_story_1018_10181501_73_dialog_content = "…全部、レインハト…あんたにしか出来ないことよ。",
  ui_story_1018_10181501_74_dialog_content = "…",
  ui_story_1018_10181501_75_dialog_content = "大元帥とはある種の約束であり、立場であり、傘となる者だ…\n己は死することなく、他人を悼み続ける者のことだ。",
  ui_story_1018_10181501_76_dialog_content = "大元帥はまさに己の血肉でもって、同胞の命を守るのだ。",
  ui_story_1018_10181501_77_dialog_content = "お前は私にしかできないというが…ハハハ。\nそういうお前も啓光のために今の今まで踏ん張ってきたではないか。",
  ui_story_1018_10181501_78_dialog_content = "そうかしら…",
  ui_story_1018_10181501_79_dialog_content = "<color=#e8d9bb>雨が地上の泥を洗い流し、\n遠くの空に浮かぶ雲間からかすかな光が射し込んできた</color>",
  ui_story_1018_10181501_80_dialog_content = "<color=#e8d9bb>ラスの肩は華奢ながらも力強く、\nその姿は光の中でますますはっきりと、堂々とした輪郭を表した</color>",
  ui_story_1018_10181501_81_dialog_content = "でも、やっぱり私はもう大元帥にはなりたくないわ…",
  ui_story_1018_10181501_82_dialog_content = "危機の中をお前は見事大元帥の重責を担ってくれた。\nこの先は私が引き続き責任を果たす番だ。",
  ui_story_1018_10181501_83_dialog_content = "この後直面する問題も厄介だが、私を信じてくれ。\n皆のために内部に潜む敵を排除してみせる。",
  ui_story_1018_10181501_84_dialog_content = "委員会とどうやり合うつもり？",
  ui_story_1018_10181501_85_dialog_content = "おい、大元帥。兵力は俺たちが握ってるんだ。\nお前の一言であいつらの根城なんざひっくり返してやるぜ！",
  ui_story_1018_10181501_86_dialog_content = "私がここでお前たちと共に戦えたということは、\n委員会はすでに我々の行動を黙認しているということだ。",
  ui_story_1018_10181501_87_dialog_content = "やつらが「啓明の星計画」の推進を急いだのは決して、\nトワイライトシティだけが目的ではない。",
  ui_story_1018_10181501_88_dialog_content = "今や暗潮が動き出し、「ガーディアン1号」のコアが奪われた。\n日蝕の動きこそ最も厄介な問題だ。",
  ui_story_1018_10181501_89_dialog_content = "カナン城に戻ったら、\nまた言われるがまま監獄に入ったりしないでしょうね？",
  ui_story_1018_10181501_90_dialog_content = "兵士たちがこのような目に遭ったのだ。\nユリシーズも裁きは免れんだろう。",
  ui_story_1018_10181501_91_dialog_content = "何はともあれ、ベリサリアはメンツを重んじる。\n私の件は彼らが何とかするだろう。",
  ui_story_1018_10181501_92_dialog_content = "大元帥様、日蝕については、すでに2部隊が暗面に向かっています。",
  ui_story_1018_10181501_93_dialog_content = "委員会はどう考えているのか存じ上げませんが、\nカロンとバイスの部隊には、私たちの応援が必要だと考えます。",
  ui_story_1018_10181501_94_dialog_content = "そうね…少し前にわずかな時間だったけど話をしたわ。\n今あの部隊が置かれている状況は確かに楽観できない…",
  ui_story_1018_10181501_95_dialog_content = "PlayerName、あんたはどうするつもり？",
  ui_story_1018_10181501_96_dialog_content = "トワイライトシティの皆がまだ天空ノ谷に避難したままなんだ。\nまずはレオたちと一緒に避難生活の手配をしないといけない。",
  ui_story_1018_10181501_97_dialog_content = "でも実は…バイスたちのことがずっと心配で…",
  ui_story_1018_10181501_98_dialog_content = "バイスたちを危険な目に合わせたりしない。\nPlayerName、私が約束する。",
  ui_story_1018_10181501_99_dialog_content = "委員会が今後の問題にどんな対応をしようと、\nあやつらの行方は私が最優先で探し出す。",
  ui_story_1018_10181501_100_dialog_content = "だったらトワイライトシティのことは私に任せてちょうだい。\nレオとは長く一緒に戦ったことだし、あの町には啓光としてもきちんと態度を示さなきゃならないわ。",
  ui_story_1018_10181501_101_dialog_content = "うん、でも君も一刻も早く治療を受けてね…",
  ui_story_1018_10181501_102_dialog_content = "分かってるわよ。どうしても困ったら、連絡するわ。",
  ui_story_1018_10181501_103_dialog_content = "うん…僕で助けになれるなら。",
  ui_story_1018_10181501_104_dialog_content = "<color=#e8d9bb>ザッ――</color>",
  ui_story_1018_10181501_105_dialog_content = "とんだドタバタ劇…いえ、喜劇ですね。一方のユリシーズときたら、\n自ら筋書きを描いたにも関わらず、今日の会議に顔も出さないとは。",
  ui_story_1018_10181501_106_dialog_content = "いったいどう始末するおつもりで？",
  ui_story_1018_10181501_107_dialog_content = "まだ始末どうこうを話す時じゃないわ。",
  ui_story_1018_10181501_108_dialog_content = "それは冗談でおっしゃってるのですか？\n啓光大元帥の2人が兵を率い、防衛線で勝ち戦をしたのですよ？",
  ui_story_1018_10181501_109_dialog_content = "あの2人が腰を低くして、\n穏やかに交渉に応じてくれるとでもお思いですか？",
  ui_story_1018_10181501_110_dialog_content = "レインハトが啓光の監獄を抜け出したのを、\n私が知らなかったとでも？",
  ui_story_1018_10181501_111_dialog_content = "肝心要の証拠を出すにはまだ早いわ。\n今後の状況がどう動くかは彼らの態度次第よ。",
  ui_story_1018_10181501_112_dialog_content = "さすがベリサリア、\n何事もしっかり逃げ道を用意しているのですね。",
  ui_story_1018_10181501_113_dialog_content = "けれど、防衛線での戦いはアストラ大陸中が注目しています。",
  ui_story_1018_10181501_114_dialog_content = "その通りよ、大陸中が見ているわ。\n何ならもっと目を凝らして見てほしいわ。",
  ui_story_1018_10181501_115_dialog_content = "暗潮の危機が本当にやってきたら、\n各陣営はいったいどこまで戦えるのかしら？",
  ui_story_1018_10181501_116_dialog_content = "…あなたがユリシーズの計画を支持したのは、\n白夜城を引っ張り出すためだったのですか？",
  ui_story_1018_10181501_117_dialog_content = "それもあるわ。",
  ui_story_1018_10181501_118_dialog_content = "トワイライトシティにしろ防衛線にしろ、あなたたちも見たでしょう？\n私たちは暗鬼に対して依然として抑止力を持っている。",
  ui_story_1018_10181501_119_dialog_content = "そして向こうも切り札を切ってきた。",
  ui_story_1018_10181501_120_dialog_content = "あの少女のことですか？",
  ui_story_1018_10181501_121_dialog_content = "そうよ。でも最後の一枚ではないはず。",
  ui_story_1018_10181501_122_dialog_content = "なるほど。これこそあなたが見たかった「合同演習」ですか。",
  ui_story_1018_10181501_123_dialog_content = "それにしても代償が大きすぎます。\n今後どうなるか考えたことはないのですか？",
  ui_story_1018_10181501_124_dialog_content = "いい案があるなら誰でもいいわ、言ってみてちょうだい。",
  ui_story_1018_10181501_125_dialog_content = "今回も日蝕が使った武器はノラの「シード」よ。\n一方、私たちも少なくとも現段階では同じものを持っている。",
  ui_story_1018_10181501_126_dialog_content = "だから、ユリシーズを支持したの。",
  ui_story_1018_10181501_127_dialog_content = "これから先も、私たちを滅ぼしうる武器はどんなものであろうとすべて、\n掌握しておかなければいけないわ。",
  ui_story_1018_10181501_128_dialog_content = "白夜城のものであろうと、北境のものであろうと…\nさらには異端教団のものであろうとね。",
  ui_story_1018_10181501_129_dialog_content = "「ガーディアン1号」のコアが奪われたと言うのに、\n各勢力間のパワーバランスを心配しているのですか？",
  ui_story_1018_10181501_130_dialog_content = "どちらが優先かという問題じゃないわ。\n内も外も敵に囲まれているのが啓光の現状よ。",
  ui_story_1018_10181501_131_dialog_content = "当時啓光から逃げ出した「エンジニア」を非難したのは、\n白夜城だけじゃなかったわ。",
  ui_story_1018_10181501_132_dialog_content = "ここまで来たら、考え方を変えて、\n皆さんにも「エンジニア」がどんな者か見てもらおうと思うの。",
  ui_story_1018_10181501_133_dialog_content = "確信はあるのですか？",
  ui_story_1018_10181501_134_dialog_content = "「暗面偵察隊」から知らせが入ったわ。\n予想していた通りよ。",
  ui_story_1018_10181501_135_dialog_content = "「ガーディアン1号」のコアは\n「エンジニア」覚醒計画の最後のピース。",
  ui_story_1018_10181501_136_dialog_content = "防衛線での戦いが終わったなら、\nまもなく「エンジニア」が目覚める頃でしょうね。",
  ui_story_1018_10181501_137_dialog_content = "…",
  ui_story_1018_10181501_138_dialog_content = "「エンジニア」…カナン城建立以来初の、真の意味での「城主」ですね。",
  ui_story_1018_10181501_139_dialog_content = "それほど古い者がもし本当に目覚めるのだとしたら、\n少し楽しみです。",
  ui_story_1018_10181501_140_dialog_content = "フフ、私も同じよ。",
  ui_story_1018_10181501_141_dialog_content = "ジッジジッ…",
  ui_story_1018_10181501_142_dialog_content = "またで…すか…",
  ui_story_1018_10181501_143_dialog_content = "私…はあり…せん…",
  ui_story_1018_10181501_144_dialog_content = "どうやら…「エンジ…",
  ui_story_1018_10181501_145_dialog_content = "…目覚め…ようね…",
  ui_story_1019_10190101_1_dialog_content = "<color=#e8d9bb>ピピピピピ…</color>",
  ui_story_1019_10190101_2_dialog_content = "思ったとおり、シードの作用は能力増強ではなく、転換だったか…",
  ui_story_1019_10190101_3_dialog_content = "だから、シードのコアルートを複製しても、\nぬかるみの中で暗力に浸食されたというわけだ…",
  ui_story_1019_10190101_4_dialog_content = "フッ…まったく…さすがというべきか…",
  ui_story_1019_10190101_5_dialog_content = "ゴホッ、ゲホゲホ…ゴホゴホッ…",
  ui_story_1019_10190101_6_dialog_content = "近くに置いてあったはずだが…",
  ui_story_1019_10190101_7_dialog_content = "…いずれにせよ、これだけの結果が得られた。\nトワイライトシティの犠牲の見返りとしては十分だ。",
  ui_story_1019_10190101_8_dialog_content = "<color=#e8d9bb>カラン――</color>",
  ui_story_1019_10190101_9_dialog_content = "あと3粒…",
  ui_story_1019_10190101_10_dialog_content = "40年の研究者生活、<color=#FFB400>特殊遺伝子型データベース</color>の準備に20年近く費やしたが…\nやるべきことはすべて、やった。",
  ui_story_1019_10190101_11_dialog_content = "だが、なぜ…こうも満足できないのか…",
  ui_story_1019_10190101_12_dialog_content = "<color=#FFB400>ラヴィル</color>、私は実に悔しい…",
  ui_story_1019_10190101_13_dialog_content = "<color=#e8d9bb>ビュウゥ――</color>",
  ui_story_1019_10190101_14_dialog_content = "す、すごい風だ…",
  ui_story_1019_10190101_15_dialog_content = "あれ…？どうして雲の上にいるんだろう？",
  ui_story_1019_10190101_16_dialog_content = "この感じ…もしかして、また墜落する…！？",
  ui_story_1019_10190101_17_dialog_content = "大丈夫、落ち着くんだ！ソラヴァンがいる！",
  ui_story_1019_10190101_18_dialog_content = "ナビゲーター、お呼びでしょうか？",
  ui_story_1019_10190101_19_dialog_content = "今日はずいぶんと勇ましいね。いったい、どこへ向かってるの？",
  ui_story_1019_10190101_20_dialog_content = "現在、空中投下任務遂行のため、\n<color=#FFB400>塔の戦場</color>へ移動中です。",
  ui_story_1019_10190101_21_dialog_content = "…任務？任務って何？",
  ui_story_1019_10190101_22_dialog_content = "戦闘命令をお伝えします。",
  ui_story_1019_10190101_23_dialog_content = "「ナビゲーターは塔の戦場へ向かい、兵器を投下せよ」。",
  ui_story_1019_10190101_24_dialog_content = "すでに作戦高度まで降下しています。\n兵器が無事に地上へ到達できるよう、指示を出してください。",
  ui_story_1019_10190101_25_dialog_content = "ちょ、ちょっと待って…何を言ってるの！？",
  ui_story_1019_10190101_26_dialog_content = "ソラヴァン？ソラヴァン――！",
  ui_story_1019_10190101_27_dialog_content = "うわあああ――！！",
  ui_story_1019_10190101_28_dialog_content = "グオオオオオオ！！",
  ui_story_1019_10190101_29_dialog_content = "どこから暗鬼が湧いて出たの！？\nそれに…どうして暗鬼と一緒に落ちてるの！？",
  ui_story_1019_10190101_30_dialog_content = "ソラヴァン――いったいどういうこと！？",
  ui_story_1019_10190101_31_dialog_content = "兵器を確実に地上へ到達させてください。\nそれが空の末裔の使命です。",
  ui_story_1019_10190101_32_dialog_content = "グオオオオオオ！！",
  ui_story_1019_10190101_33_dialog_content = "な、何を言ってるの…？こ、こんなの、夢でしょ！？",
  ui_story_1019_10190101_34_dialog_content = "夢ではありません。",
  ui_story_1019_10190101_35_dialog_content = "現在座標は塔の戦場です。\n兵器を確実に降下させてください。",
  ui_story_1019_10190101_36_dialog_content = "塔…？ここは天空ノ谷でしょ！？\nあの塔は回帰の塔だ、それは分かるけど――",
  ui_story_1019_10190101_37_dialog_content = "地上を逃げ回ってるのは…空の末裔？それとも…",
  ui_story_1019_10190101_38_dialog_content = "いや…夢だ。これはきっと夢なんだ！\n地面に落ちれば、目が覚めるはず…",
  ui_story_1019_10190101_39_dialog_content = "…ええい、どうにでもなれ！",
  ui_story_1019_10190101_40_dialog_content = "…",
  ui_story_1019_10190101_41_dialog_content = "…あれ？まだ地面につかない…？",
  ui_story_1019_10190101_42_dialog_content = "落ちると分かって落ちるのって、時間が長く感じるんだな…",
  ui_story_1019_10190101_43_dialog_content = "<color=#e8d9bb>ドーン――！！</color>",
  ui_story_1019_10190101_44_dialog_content = "あっ――！",
  ui_story_1019_10190101_45_dialog_content = "…",
  ui_story_1019_10190101_46_dialog_content = "目が覚めたか？",
  ui_story_1019_10190101_47_dialog_content = "白夜に捧ぐ。無事に到着しましたね。",
  ui_story_1019_10190101_48_dialog_content = "レオ…ジョセリン？僕たちは…",
  ui_story_1019_10190101_49_dialog_content = "天空ノ谷へ戻ってきたのです。",
  ui_story_1019_10190101_50_dialog_content = "飛空艇の揺れで誰も立っていられなかったというのに、\nお前はずいぶんぐっすりと眠っていたな…",
  ui_story_1019_10190101_51_dialog_content = "天空ノ谷…",
  ui_story_1019_10190101_52_dialog_content = "確かに…間違いない…天空ノ谷だ…",
  ui_story_1019_10190101_53_dialog_content = "確か、トワイライトシティと啓光防衛線の戦いの後、\n白夜城の飛空艇で天空ノ谷へ戻ってくる途中だったはず…",
  ui_story_1019_10190101_54_dialog_content = "やっぱり…夢だったのか。よかった…本当によかった！",
  ui_story_1019_10190101_55_dialog_content = "何をうろつき回っている？本当に大丈夫か？",
  ui_story_1019_10190101_56_dialog_content = "大丈夫だよ…本当によかった…",
  ui_story_1019_10190101_57_dialog_content = "それにしても、あの無重力感…すごくリアルで…\nまるで現実みたいだった…",
  ui_story_1019_10190101_58_dialog_content = "夢で…本当によかった！",
  ui_story_1019_10190101_59_dialog_content = "…なぜ、抱きつく…？",
  ui_story_1019_10190101_60_dialog_content = "<color=#e8d9bb>ギュッ――</color>",
  ui_story_1019_10190101_61_dialog_content = "PlayerName、もともときれいな物でもないが、\n靴を踏むのはやめてくれないか？",
  ui_story_1019_10190101_62_dialog_content = "え？ごめん…でも、たぶん、僕は踏んでないと思うけど…",
  ui_story_1019_10190101_63_dialog_content = "キュー…キューブ…",
  ui_story_1019_10190101_64_dialog_content = "この白くて四角い物は何だ…？\nなぜ私の靴に抱きついている？",
  ui_story_1019_10190101_65_dialog_content = "ああ、キューブだよ。天空ノ谷に住んでる僕の仲間なんだ。\nでも、どうしたんだろう？酔ってるみたいだけど…",
  ui_story_1019_10190101_66_dialog_content = "キューブ…ゲフッ――",
  ui_story_1019_10190101_67_dialog_content = "おや、レオ団長！聖女様！空の末裔の兄ちゃん！",
  ui_story_1019_10190101_68_dialog_content = "やっとお戻りですか！",
  ui_story_1019_10190101_69_dialog_content = "暗鬼を見事トワイライトシティから追い出して、\nこっちへ向かってると聞いたもんで――",
  ui_story_1019_10190101_70_dialog_content = "帰ってくる戦士がたをねぎらおうと思いましてね。\n酒蔵の女房たちと一緒に、食事と果実酒を用意したんです。",
  ui_story_1019_10190101_71_dialog_content = "発酵期間は短いんですが、天空ノ谷の果物で造ったら、\n何とも特別な味に仕上がりましてね。",
  ui_story_1019_10190101_72_dialog_content = "キューブ…やっぱり、お酒を飲んでたんだね…",
  ui_story_1019_10190101_73_dialog_content = "兄ちゃん、ラス大元帥はどうしたんだい？\n姿が見えないみたいだが？",
  ui_story_1019_10190101_74_dialog_content = "ラスもひとまず大きな問題は無いです。\nでも念のため、啓光に戻って治療することになりました。",
  ui_story_1019_10190101_75_dialog_content = "そうか、無事ならいいんだ！\n全員に直接お礼ができたらよかったんだけどな。",
  ui_story_1019_10190101_76_dialog_content = "それはそうと、空の末裔の兄ちゃん。\n俺たちを受け入れてくれて、ありがとな。",
  ui_story_1019_10190101_77_dialog_content = "ここで何をしたらいいか分からなかったんでな。\n魚にエサやったり、酒を造ったり、果物の樹の害虫を退治したりして…",
  ui_story_1019_10190101_78_dialog_content = "僕は毎日部屋を掃除してたよ。木の枝にかけてあるのは、\n空の末裔と騎士のお兄ちゃんたちをお出迎えするために作ったんだ…",
  ui_story_1019_10190101_79_dialog_content = "本当に色々と、ありがとう…",
  ui_story_1019_10190101_80_dialog_content = "ほんの気持ちだよ。天空ノ谷への恩返しってところかな。",
  ui_story_1019_10190101_81_dialog_content = "お礼を言うのは僕の方です！\n天空ノ谷がこんなににぎやかになったのは初めてですし。",
  ui_story_1019_10190101_82_dialog_content = "皆さんさえよければ、天空ノ谷にずっと住んでもらっても…",
  ui_story_1019_10190101_83_dialog_content = "そんなことになれば、これからトワイライトシティで\nうまい酒が飲めなくなってしまうな。",
  ui_story_1019_10190101_84_dialog_content = "白夜に捧ぐ。PlayerNameさん。トワイライトシティのために\n力を尽くしてくださり、感謝しています。",
  ui_story_1019_10190101_85_dialog_content = "キューブ！キューブ…ゲフッ…ウプッ…",
  ui_story_1019_10190101_86_dialog_content = "<color=#e8d9bb>乾杯――！！</color>",
  ui_story_1019_10190101_87_dialog_content = "ハハハ、白夜城ではそんなことがあったのか。\nまさに孤軍奮闘だったな、軍師殿。",
  ui_story_1019_10190101_88_dialog_content = "トワイライトシティのことを思えば、大したことではありませんよ。\n結果さえ良ければ、やった甲斐もあったというものです。",
  ui_story_1019_10190101_89_dialog_content = "さすが、私が見込んだ人材だな。さあ、飲め！",
  ui_story_1019_10190101_90_dialog_content = "…",
  ui_story_1019_10190101_91_dialog_content = "どうした？\n大きな戦いの後だというのに、酒が進まないようだな。",
  ui_story_1019_10190101_92_dialog_content = "ご一緒したいところですが、飲める身体ではないので、皆さんで楽しんでください。\nそれにしても、これほどにぎやかなのは久しぶりです。",
  ui_story_1019_10190101_93_dialog_content = "そうだな。同感だ。",
  ui_story_1019_10190101_94_dialog_content = "しかし、皆こうして酒を楽しみ、笑ってはいるが…\n心の中では、今もトワイライトシティのことを思っているはずだ。",
  ui_story_1019_10190101_95_dialog_content = "ええ、やはり気がかりでしょうね。\n何の悩みもないのは、このキューブたちくらいでしょう。",
  ui_story_1019_10190101_96_dialog_content = "私は明日、トワイライトシティへ戻る。",
  ui_story_1019_10190101_97_dialog_content = "戦士として、硝煙の匂いもしない所ではよく眠れんのでな。\nこの酒を飲み終えたら、次の戦場へ戻る。",
  ui_story_1019_10190101_98_dialog_content = "<color=#e8d9bb>楽しそうな話し声と笑い声は、深夜まで続いた…</color>",
  ui_story_1019_10190101_99_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1019_10190101_100_dialog_content = "お前だったか。天空ノ谷の方は問題ないか？",
  ui_story_1019_10190101_101_dialog_content = "はい、大丈夫です…",
  ui_story_1019_10190101_102_dialog_content = "これほど遅くに連絡してくるとは、\nバイスのことが気になるのだろう？",
  ui_story_1019_10190101_103_dialog_content = "はい…バイスたちから、その後連絡はありましたか？",
  ui_story_1019_10190101_104_dialog_content = "連絡はあったが、具体的な状況については、私もよく分からない。",
  ui_story_1019_10190101_105_dialog_content = "連絡があったんですか！？",
  ui_story_1019_10190101_106_dialog_content = "カロンの率いる追跡部隊から、常に信号が届いている。\n啓光の偵察任務においては、任務が順調に進んでいる証拠だ。",
  ui_story_1019_10190101_107_dialog_content = "…でも、もしトワイライトシティみたいに、\n異常な状況に巻き込まれてたら…",
  ui_story_1019_10190101_108_dialog_content = "分かっている。今、事実確認を進めているところだ。\n安心しろ。状況が分かり次第、お前にも連絡を入れる。",
  ui_story_1019_10190101_109_dialog_content = "僕に今、何かできることはありませんか？\nトワイライトシティの戦いにも参加したんです。何かできるかもしれません。",
  ui_story_1019_10190101_110_dialog_content = "PlayerName、何もする必要はない。",
  ui_story_1019_10190101_111_dialog_content = "でも――",
  ui_story_1019_10190101_112_dialog_content = "気持ちは分かる。だが、今は啓光に来るな。",
  ui_story_1019_10190101_113_dialog_content = "「ガーディアン1号」のコアが奪取され、カナン城の防御に問題が出ていてる。\n現在は総力を挙げて対応中だ。",
  ui_story_1019_10190101_114_dialog_content = "トワイライトシティでのお前の奮闘と善意は、\nもう啓光を十分に助けた。",
  ui_story_1019_10190101_115_dialog_content = "あとのことは私に任せろ。もう遅い、早めに休め。",
  ui_story_1019_10190101_116_dialog_content = "はい…",
  ui_story_1019_10190101_117_dialog_content = "…",
  ui_story_1019_10190101_118_dialog_content = "PlayerName、バイスが心配で眠れないのですか？",
  ui_story_1019_10190101_119_dialog_content = "うん…",
  ui_story_1019_10190101_120_dialog_content = "<color=#e8d9bb>静かに20秒数えて、心拍数を計測してみてください。</color>",
  ui_story_1019_10190101_121_dialog_content = "ソラヴァン…",
  ui_story_1019_10190101_122_dialog_content = "はい、聞いています。",
  ui_story_1019_10190101_123_dialog_content = "20秒静かにしたら…本当に落ち着いたみたい。\n楽しいってどんな気分だったか、思い出せた気がする。",
  ui_story_1019_10190101_124_dialog_content = "…",
  ui_story_1019_10190101_125_dialog_content = "楽しい時の画像データを検索しました。\n子どもの頃、PlayerNameは楽しくなると、よく逆立ちをしていました。",
  ui_story_1019_10190101_126_dialog_content = "逆立ち！？",
  ui_story_1019_10190101_127_dialog_content = "ソラヴァンも逆立ちしろと言って聞きませんでした。",
  ui_story_1019_10190101_128_dialog_content = "うっ…そ、そんなこともあったかな…\nでも、今は僕も君も、逆立ちは無理だね。",
  ui_story_1019_10190101_129_dialog_content = "計算によると、私の逆立ち成功率は59%です。\n実行する場合は、安全な場所へ移動してください。",
  ui_story_1019_10190101_130_dialog_content = "え？あはは、ありがとう、ソラヴァン。\nでも…このままでいいよ。",
  ui_story_1019_10190101_131_dialog_content = "何をするでもなく、こうやってただ制御装置を眺めて、\n何の悩みもなく過ごしていたのは、どれぐらい昔の話だっただろう…",
  ui_story_1019_10190101_132_dialog_content = "私の意識モジュールが損傷した後、\nいろいろな経験をしましたね。",
  ui_story_1019_10190101_133_dialog_content = "うん。その間に何があったか、まだ話してなかったよね。\nまずは…",
  ui_story_1019_10190101_134_dialog_content = "君の残してくれた座標に従って、\n僕たちは地下シェルターで鍵を見つけたんだ…",
  ui_story_1019_10190101_135_dialog_content = "そして、座標に従って、天空ノ谷に戻ってきた。",
  ui_story_1019_10190101_136_dialog_content = "その時初めて故郷の土を踏んだんだよ。\nでも…そこにはもう、一族の姿はなかった。",
  ui_story_1019_10190101_137_dialog_content = "しかも、一番の友だちを失くしかけたんだ…",
  ui_story_1019_10190101_138_dialog_content = "それから、僕は空の末裔の先祖たちが巨像と一緒に大陸を離れて、\n気の遠くなるような長い時間のあと、再び戻ってくる情景を見たよ。",
  ui_story_1019_10190101_139_dialog_content = "いま思い出しても、長い夢を見てたみたいだ。\nご先祖様たちは、あの後どうなったんだろう…？",
  ui_story_1019_10190101_140_dialog_content = "その後、君は僕を助けるために、\n太古の戦場の中に閉じ込められてしまった…",
  ui_story_1019_10190101_141_dialog_content = "「ガイダンス」の意識データが残ってて本当に良かったよ。\nおかげで、君を目覚めさせることができた。",
  ui_story_1019_10190101_142_dialog_content = "…",
  ui_story_1019_10190101_143_dialog_content = "やはり、修復ログを確認するよりも、\nPlayerNameから直接聞く方が良いですね。",
  ui_story_1019_10190101_144_dialog_content = "なんだ、知ってたの…？話して損しちゃった。",
  ui_story_1019_10190101_145_dialog_content = "意識がない間に起こったことは、\nガルー室長が修復ログとして詳細に記録しています。",
  ui_story_1019_10190101_146_dialog_content = "空の末裔の一族を代表して合同演習に参加した時のことを、\n話してもらえませんか？",
  ui_story_1019_10190101_147_dialog_content = "ああ、合同演習ではね…",
  ui_story_1019_10190201_1_dialog_content = "<color=#e8d9bb>数日後の早朝、啓光の医療センター</color>",
  ui_story_1019_10190201_2_dialog_content = "これは…全部、俺がやったのか…",
  ui_story_1019_10190201_3_dialog_content = "す、すまない…チャンドラ先生。\n俺は…自分を制御できない…",
  ui_story_1019_10190201_4_dialog_content = "謝る必要はありません、ヘリオス大尉。",
  ui_story_1019_10190201_5_dialog_content = "適度な戦闘訓練は感情の発散にもなります。\nカウンセリングの一部ですよ。",
  ui_story_1019_10190201_6_dialog_content = "俺みたいな奴が…啓光のために、いったい何ができるっていうんだ…",
  ui_story_1019_10190201_7_dialog_content = "ヘリオス大尉、そんなことはありませんよ。",
  ui_story_1019_10190201_8_dialog_content = "大尉が記憶をたどり、教えてくださった場所の多く…\n特に暗面の情報は、啓光にとって非常に重要なものです。",
  ui_story_1019_10190201_9_dialog_content = "大尉がずっと思い出そうとしている\n人物や出来事については…",
  ui_story_1019_10190201_10_dialog_content = "私たちは通常、他人と交流する時、\n大脳の五感と感情を司る部分を使います。",
  ui_story_1019_10190201_11_dialog_content = "感情をうまくコントロールできるようになれば、\nその部分の機能も徐々に回復するでしょう。",
  ui_story_1019_10190201_12_dialog_content = "そうか…だったら、もっと努力しないとな。",
  ui_story_1019_10190201_13_dialog_content = "ああ、壊れたダミーは俺が修理するよ…\nこれからは、そちらも手伝おう。",
  ui_story_1019_10190201_14_dialog_content = "それから…こんな遅くに大きな音を立てて、起こしてしまったな…\nすまなかった…",
  ui_story_1019_10190201_15_dialog_content = "気にしないでください。これも仕事のうちですから…ふわぁ～…",
  ui_story_1019_10190201_16_dialog_content = "アハハ、それでは、今日はここまでにしましょう。",
  ui_story_1019_10190201_17_dialog_content = "何か思い出したこと、夢に出てきたことがあれば、\n引き続き、その都度記録しておいてくださいね。",
  ui_story_1019_10190201_18_dialog_content = "何に使うつもりかは分かりませんが、\nその記録は大元帥様にとって、とても重要なようですので。",
  ui_story_1019_10190201_19_dialog_content = "突然沸き上がってくる感情や、思い浮かぶ光景は、\n軽んじてはいけません。",
  ui_story_1019_10190201_20_dialog_content = "一見小さな炎の下には、\n往々にして長い間くすぶっている大きな火種があるものです。",
  ui_story_1019_10190201_21_dialog_content = "ああ。あの暗く冷たい世界でのことは、\nどんな小さなことでも忘れやしないさ。",
  ui_story_1019_10190201_22_dialog_content = "チャンドラ先生、本当にありがとう。",
  ui_story_1019_10190201_23_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1019_10190201_24_dialog_content = "あら？こんな朝早くに誰ですか…？",
  ui_story_1019_10190201_25_dialog_content = "<color=#e8d9bb>ヒュゥ…</color>",
  ui_story_1019_10190201_26_dialog_content = "『1011X。』",
  ui_story_1019_10190201_27_dialog_content = "『はい。最後の<color=#FFB400>駆動リング</color>を入手しました。』",
  ui_story_1019_10190201_28_dialog_content = "『01X11。』",
  ui_story_1019_10190201_29_dialog_content = "『どうかご覧になっていてください――』",
  ui_story_1019_10190201_30_dialog_content = "『降臨の時をお待ちしております――』",
  ui_story_1019_10190201_31_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1019_10190201_32_dialog_content = "ここは…？",
  ui_story_1019_10190201_33_dialog_content = "あの影は…誰だろう…？",
  ui_story_1019_10190201_34_dialog_content = "見てはダメ、PlayerName！",
  ui_story_1019_10190201_35_dialog_content = "待って…バイス？",
  ui_story_1019_10190201_36_dialog_content = "バイス！本当にバイスなんだね！",
  ui_story_1019_10190201_37_dialog_content = "帰って。",
  ui_story_1019_10190201_38_dialog_content = "道に迷ったの？バイス！そこは…危ない所なんでしょ？",
  ui_story_1019_10190201_39_dialog_content = "どこにいるのか教えて！すぐに助けに行くから！",
  ui_story_1019_10190201_40_dialog_content = "帰って。",
  ui_story_1019_10190201_41_dialog_content = "…",
  ui_story_1019_10190201_42_dialog_content = "どこへ帰れっていうの？バイス？",
  ui_story_1019_10190201_43_dialog_content = "帰るんだ。",
  ui_story_1019_10190201_44_dialog_content = "帰る？ここはどこ…？",
  ui_story_1019_10190201_45_dialog_content = "帰るんだ。",
  ui_story_1019_10190201_46_dialog_content = "君は誰？バイスはどこ？",
  ui_story_1019_10190201_47_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1019_10190201_48_dialog_content = "PlayerName、ここは危険よ！",
  ui_story_1019_10190201_49_dialog_content = "バイス！いったい、どこにいるの！？",
  ui_story_1019_10190201_50_dialog_content = "<color=#e8d9bb>ピーッ！ピーッ！ピーッ！</color>",
  ui_story_1019_10190201_51_dialog_content = "バイス…バイス！",
  ui_story_1019_10190201_52_dialog_content = "PlayerName、また悪い夢を見たのですか？",
  ui_story_1019_10190201_53_dialog_content = "夢か…",
  ui_story_1019_10190201_54_dialog_content = "また、夢…",
  ui_story_1019_10190201_55_dialog_content = "ソラヴァン、何かがおかしいんだ…\n天空ノ谷に戻ってきてからずっと、ヘンな夢ばかり見て…",
  ui_story_1019_10190201_56_dialog_content = "でも、夢っていうより、何かを感知してるような感じで…\n僕もうまく説明できないんだけど…",
  ui_story_1019_10190201_57_dialog_content = "心配ごとがあるせいではありませんか？\nもう何日も、夜もここで連絡を待っています。部屋で休むべきです。",
  ui_story_1019_10190201_58_dialog_content = "今、何時？",
  ui_story_1019_10190201_59_dialog_content = "あと3時間ほどで、日が昇ります。",
  ui_story_1019_10190201_60_dialog_content = "また1日過ぎちゃったね…",
  ui_story_1019_10190201_61_dialog_content = "何もできずに、ただ待つだけなんて…辛いよ…",
  ui_story_1019_10190201_62_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1019_10190201_63_dialog_content = "この音は…「ガイダンス」のデータの中にある\n古い座標の信号を検索してたんだね。",
  ui_story_1019_10190201_64_dialog_content = "確か君は…「過去からの反響」って呼んでたっけ。",
  ui_story_1019_10190201_65_dialog_content = "その通りです。",
  ui_story_1019_10190201_66_dialog_content = "「ガイダンス」は通信途絶の時まで、座標信号を発信していました。\nですが現在の大陸には、対応する場所が発見できません。",
  ui_story_1019_10190201_67_dialog_content = "環境の変化のせいかな？",
  ui_story_1019_10190201_68_dialog_content = "時の経過も原因の一つです。",
  ui_story_1019_10190201_69_dialog_content = "それでも、ずっと検索を続けてるんだね…",
  ui_story_1019_10190201_70_dialog_content = "データをすべて閲覧できれば、私の意識は元通りになります。",
  ui_story_1019_10190201_71_dialog_content = "でも、今の君はもう十分、僕の知ってるソラヴァンだよ。",
  ui_story_1019_10190201_72_dialog_content = "私とPlayerNameの意識適合度は現在、\n以前の90%までしか回復していません。",
  ui_story_1019_10190201_73_dialog_content = "そうなの…？僕には違いが分からないけど…",
  ui_story_1019_10190201_74_dialog_content = "学習を継続します。",
  ui_story_1019_10190201_75_dialog_content = "1つ聞きたいことがあるんだ…",
  ui_story_1019_10190201_76_dialog_content = "レインハトさんは、啓光のことには構うなって言ったけど、\nやっぱり心配だよ。",
  ui_story_1019_10190201_77_dialog_content = "天空ノ谷が平和なほど、焦っちゃうんだ。\nあの時感じたバイスの鼓動は…",
  ui_story_1019_10190201_78_dialog_content = "何か伝えたいことがあったに違いないんだ。\nでも、僕はそれに気づかなかった…",
  ui_story_1019_10190201_79_dialog_content = "つまり、私に何を聞きたいのですか？",
  ui_story_1019_10190201_80_dialog_content = "いや…僕は決めたよ！\nレインハトさんには来るなって言われたけど――",
  ui_story_1019_10190201_81_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1019_10190201_82_dialog_content = "え？どうして…",
  ui_story_1019_10190201_83_dialog_content = "待ちかねていた連絡ですか？",
  ui_story_1019_10190201_84_dialog_content = "うん！見て！",
  ui_story_1019_10190201_85_dialog_content = "…",
  ui_story_1019_10190201_86_dialog_content = "「啓光まで、至急」",
  ui_story_1019_10190201_87_dialog_content = "「とにかく大至急」",
  ui_story_1019_10190301_1_dialog_content = "<color=#e8d9bb>啓光の整備工場</color>",
  ui_story_1019_10190301_2_dialog_content = "あ…どこに行けばいいのか、聞くの忘れちゃった。",
  ui_story_1019_10190301_3_dialog_content = "あの、すみません――",
  ui_story_1019_10190301_4_dialog_content = "整備工場内は一般人立ち入り禁止だ。\n今すぐここから立ち去りなさい。",
  ui_story_1019_10190301_5_dialog_content = "あ、ええと…僕は一般人じゃなくて、空の――",
  ui_story_1019_10190301_6_dialog_content = "全員集合！",
  ui_story_1019_10190301_7_dialog_content = "はい――！",
  ui_story_1019_10190301_8_dialog_content = "もう一度言うぞ。今は防御システムに問題があるんだ。\nここは危険だ。すぐに立ち去るように。",
  ui_story_1019_10190301_9_dialog_content = "防御システムに問題が…？",
  ui_story_1019_10190301_10_dialog_content = "たくさんの兵士が巡回してるところを見ると、\nカナン城の防衛体制はまだ回復してないんだね…",
  ui_story_1019_10190301_11_dialog_content = "はぁっ！PlayerName、食らえ――",
  ui_story_1019_10190301_12_dialog_content = "な、何…？君は…",
  ui_story_1019_10190301_13_dialog_content = "ウソ？僕のこと、忘れたの！？",
  ui_story_1019_10190301_14_dialog_content = "あ、思い出した。君は…",
  ui_story_1019_10190301_15_option_content = "緑の少年",
  ui_story_1019_10190301_16_dialog_content = "じゃない…ショーンだね！",
  ui_story_1019_10190301_17_dialog_content = "（口が滑って、第一印象を言うところだった…）",
  ui_story_1019_10190301_18_dialog_content = "アハハ。たまにそう呼ばれることもあるけどね。",
  ui_story_1019_10190301_19_option_content = "クロウ",
  ui_story_1019_10190301_20_dialog_content = "じゃない…クロウじゃなくて、ショーンだ！",
  ui_story_1019_10190301_21_dialog_content = "うっ…クロウに比べたら、確かに存在感薄いけどさ…",
  ui_story_1019_10190301_22_option_content = "ショーン",
  ui_story_1019_10190301_23_dialog_content = "そうそう、ショーンだ…",
  ui_story_1019_10190301_24_dialog_content = "ごめんね。前と少し…雰囲気が違ったから。",
  ui_story_1019_10190301_25_dialog_content = "当然だよ。毎日訓練して、毎日強くなってるんだから！",
  ui_story_1019_10190301_26_dialog_content = "まあ、合格ってことにしてあげる。",
  ui_story_1019_10190301_27_dialog_content = "それはそうと…どうして、ここに？",
  ui_story_1019_10190301_28_dialog_content = "定期的にカナン城で検査を受けてるんだ。\n少し早く着いちゃったんだけど、まさか会えるとは思わなかったよ。",
  ui_story_1019_10190301_29_dialog_content = "早く着いたなら、どうして警備に参加して、\n対暗鬼防御に貢献しないのですか？",
  ui_story_1019_10190301_30_dialog_content = "ビビアン長官！それは…",
  ui_story_1019_10190301_31_dialog_content = "冗談です。早く用事を済ませてくださいね。\n安全にも気を付けて。",
  ui_story_1019_10190301_32_dialog_content = "はい、長官！PlayerName、それじゃ、またね！",
  ui_story_1019_10190301_33_dialog_content = "うん、またね。",
  ui_story_1019_10190301_34_dialog_content = "連絡しなければ自分から来るだろうと\n大元帥様がおっしゃっていましたが、その通りでした。",
  ui_story_1019_10190301_35_dialog_content = "僕が来ることを分かってたんですか？\nということは…",
  ui_story_1019_10190301_36_dialog_content = "当然です。あなたと巨像のアストラでの一挙一動は\nすべて把握しています。",
  ui_story_1019_10190301_37_dialog_content = "ただ、今の啓光は複雑な状況です。\n上層部は権力争いで手一杯ですから。",
  ui_story_1019_10190301_38_dialog_content = "あなたも見たでしょう？\nカナン城の防御体制はきわめて厳しい状況にあります。",
  ui_story_1019_10190301_39_dialog_content = "あ、あの…今の啓光の大元帥は…",
  ui_story_1019_10190301_40_option_content = "レインハトさんですか？",
  ui_story_1019_10190301_41_dialog_content = "もちろんです。レインハト大元帥は啓光全軍人の精神そのもの。\n誰一人として代わることのできない存在です。",
  ui_story_1019_10190301_42_option_content = "ラスですか？",
  ui_story_1019_10190301_43_dialog_content = "名目上はそうですが、ラス軍団長はすでに\n大元帥の地位をレインハト大元帥に返上すると委員会に申し出ました。",
  ui_story_1019_10190301_44_dialog_content = "しかし、誰を選んでも委員会の望む人選にならず、といって、\n軍隊を指揮する者が不在なままというわけにもいかず…",
  ui_story_1019_10190301_45_dialog_content = "そこで委員会は、大元帥様の嫌疑に関する調査を先延ばしして、\n軍と共同で啓光を管理することにしたのです。",
  ui_story_1019_10190301_46_dialog_content = "何だか、ますますややこしいことになってきてるみたいですね。",
  ui_story_1019_10190301_47_dialog_content = "ええ、その通りです。啓光の管理体制が混乱していて、\n大元帥様と連絡が取れないことも多く…",
  ui_story_1019_10190301_48_dialog_content = "どうりで、ずっと連絡がなかったわけですね。\n本当にすみません。わざわざ出迎えてもらって…",
  ui_story_1019_10190301_49_dialog_content = "それで…ラスはまだレインハト大元帥と決着をつけたがってるんですか？",
  ui_story_1019_10190301_50_dialog_content = "そうなんです。大元帥の地位に未練はないと言っているのに、\n何としても大元帥様とは決着をつけたいとのことで。",
  ui_story_1019_10190301_51_dialog_content = "ラスらしいですね…ところで、ラスの具合はどうですか？\n手術はうまくいきましたか？",
  ui_story_1019_10190301_52_dialog_content = "私も気になっていますが…今は管理体系が複雑な上に、\n「啓明の星計画」に関する事は、何をするにも難しくなっています。",
  ui_story_1019_10190301_53_dialog_content = "ですから、ラスに会おうとしても、おそらく無理でしょう。",
  ui_story_1019_10190301_54_dialog_content = "実は、今回啓光に来たのは…",
  ui_story_1019_10190301_55_dialog_content = "グア！！！",
  ui_story_1019_10190301_56_dialog_content = "参謀長！技師の話では、整備工場西側の通風孔が機能していないそうです。\nおそらく、暗鬼はそこから侵入したと思われます！",
  ui_story_1019_10190301_57_dialog_content = "一晩かかって、ようやく見つかりましたか。",
  ui_story_1019_10190301_58_dialog_content = "全員整列！技師を護衛しつつ、暗鬼を撃破します！",
  ui_story_1019_10190301_59_dialog_content = "はい！！！",
  ui_story_1019_10190301_60_dialog_content = "ちょっと…道を開けてちょうだい！",
  ui_story_1019_10190301_61_dialog_content = "参謀長！後方で…暗鬼が人を絞め殺しています！",
  ui_story_1019_10190301_62_dialog_content = "まさか…",
  ui_story_1019_10190301_63_dialog_content = "ブブブブ！",
  ui_story_1019_10190301_64_dialog_content = "人がこんなにたくさん…",
  ui_story_1019_10190301_65_dialog_content = "ブブブブ！",
  ui_story_1019_10190301_66_dialog_content = "はいはい、分かったわよ。まだ運動の時間じゃないけど…",
  ui_story_1019_10190301_67_dialog_content = "プログラム、実行準備。",
  ui_story_1019_10190301_68_dialog_content = "ブー！",
  ui_story_1019_10190301_69_dialog_content = "…どなたでしょうか？",
  ui_story_1019_10190402_1_dialog_content = "アップロード、アップロード…急いで保存しなきゃ…\nふぅ…やっぱり屋外での運動データが少なすぎるわね。",
  ui_story_1019_10190402_2_dialog_content = "科学者って、こんなふうに戦うんですね…",
  ui_story_1019_10190402_3_dialog_content = "ストップ！科学者に対する先入観まみれの形容詞を並べられる前に言っとくわ…",
  ui_story_1019_10190402_4_dialog_content = "科学者が全員、ネクラで退屈な、運動神経の悪い\nハゲ頭の本の虫だと思ったら大間違いよ。",
  ui_story_1019_10190402_5_dialog_content = "いや、そんなことは一言も…",
  ui_story_1019_10190402_6_dialog_content = "PlayerName、こちらは…？",
  ui_story_1019_10190402_7_dialog_content = "啓光最高科学者会議の、アルゴル博士です。",
  ui_story_1019_10190402_8_dialog_content = "啓光に来たのも、アルゴルさんに呼ばれたからなんですけど…\n何だか、この前会った時と感じが変わったような…",
  ui_story_1019_10190402_9_dialog_content = "最高科学者会議ですか…\nメンバーの方に実際にお会いするのは初めてです。",
  ui_story_1019_10190402_10_dialog_content = "よし、できたわ！",
  ui_story_1019_10190402_11_dialog_content = "こんにちは、空の末裔くん！それと…\nあたし、あなたのことも招待してたかしら？",
  ui_story_1019_10190402_12_dialog_content = "アルゴル博士、はじめまして。\n啓光連邦参謀長のビビアンと申します。",
  ui_story_1019_10190402_13_dialog_content = "そう…ま、せっかく来たんだし、付いてきて。",
  ui_story_1019_10190402_14_dialog_content = "アルゴル博士、先に説明させていただきますが、\n私は大元帥様より、PlayerNameの補助を仰せつかっています。",
  ui_story_1019_10190402_15_dialog_content = "まずは予定をお話しいただけませんか？\n大元帥様に報告しなければなりませんので。",
  ui_story_1019_10190402_16_dialog_content = "急に思い立って呼んだだけ。いちいちあなたの計画表に載せるようなものはないわ。\nどうしてもって言うなら、ここを使いなさい。",
  ui_story_1019_10190402_17_dialog_content = "こことは…",
  ui_story_1019_10190402_18_dialog_content = "頭。",
  ui_story_1019_10190402_19_dialog_content = "ブー！",
  ui_story_1019_10190402_20_dialog_content = "…",
  ui_story_1019_10190402_21_dialog_content = "安全のためお伺いしますが、さきほど一緒に戦っていたのは…\n通常の兵器ではありませんね？",
  ui_story_1019_10190402_22_dialog_content = "もちろん、ありきたりな兵器なんかじゃないわよ。\nブールっていって、私のペッ――",
  ui_story_1019_10190402_23_dialog_content = "ブーブー！！",
  ui_story_1019_10190402_24_dialog_content = "あ、イタタタタ――仲間、仲間よ…\n分かったから、叩くのを止めなさい！",
  ui_story_1019_10190402_25_dialog_content = "まったく…ああ～、気持ちいいわ。もう少し上をお願い…",
  ui_story_1019_10190402_26_dialog_content = "ブールって…マッサージもできるんですか？",
  ui_story_1019_10190402_27_dialog_content = "前に会った時より太ったんじゃないかって、ブールが言ってるわ。",
  ui_story_1019_10190402_28_dialog_content = "ええ…！？ブールの言ってることが分かるんですか？",
  ui_story_1019_10190402_29_dialog_content = "あなた、空の末裔でしょ？\n情報のやり取りに口を使うとは限らないって、分かってるわよね？",
  ui_story_1019_10190402_30_dialog_content = "あたしとブールの間にも、特別なコミュニケーション方法があるのよ。",
  ui_story_1019_10190402_31_dialog_content = "たとえば、ブールは今…\nあたしのアップデートした戦闘システムに満足してるらしいわ！",
  ui_story_1019_10190402_32_dialog_content = "ブー！",
  ui_story_1019_10190402_33_dialog_content = "アハハ、どういたしまして！",
  ui_story_1019_10190402_34_dialog_content = "（さっきの…僕にはどうしても、失敗に思えるんだけど…）",
  ui_story_1019_10190402_35_dialog_content = "あら？何か言った？",
  ui_story_1019_10190402_36_dialog_content = "ブー！",
  ui_story_1019_10190402_37_dialog_content = "確かに…今、小馬鹿にしたような顔したわね。",
  ui_story_1019_10190402_38_dialog_content = "心の中で思ったことまで、分かっちゃうんですか…？",
  ui_story_1019_10190402_39_dialog_content = "アハハ、そう緊張しないで。とにかく行きましょ。",
  ui_story_1019_10190402_40_dialog_content = "あ、そうだ。それで、急に僕を呼び出すなんて、\nそうとう大事なことですか？",
  ui_story_1019_10190402_41_dialog_content = "何のために呼ばれたかも知らずに来たのですか？",
  ui_story_1019_10190402_42_dialog_content = "空の末裔くんらしいじゃない。",
  ui_story_1019_10190402_43_dialog_content = "以前、ソラヴァンの意識を回復させるために、\n「ガイダンス」の人格データをコピーしたことは覚えてる？",
  ui_story_1019_10190402_44_dialog_content = "その中にあった座標に対応する位置は、\n今はもう分からなくなってたんだけど――",
  ui_story_1019_10190402_45_dialog_content = "最近啓光で極夜地帯の地図が更新されたのよ。\nその中に「ガーディアン1号」のコアの手がかりがあるかもしれないの。",
  ui_story_1019_10190402_46_dialog_content = "それだけじゃないわ。追跡部隊が発見した未知の座標についても、\n「ガイダンス」のデータ中に答えがあるかもしれないの。",
  ui_story_1019_10190402_47_dialog_content = "本当ですか！？よかった！\nそれで…僕は何をすればいいんですか？",
  ui_story_1019_10190402_48_dialog_content = "今回貸してほしいのは、あなたの感知能力ではなくて、\nソラヴァンの学習能力よ。",
  ui_story_1019_10190402_49_dialog_content = "学習能力？",
  ui_story_1019_10190402_50_dialog_content = "そう。ソラヴァンの意識が短時間で回復したのは、\n学習能力がきわめて高いから。",
  ui_story_1019_10190402_51_dialog_content = "だから、暗面の地図製作の効率を上げるために、その学習能力を貸してほしいの。\nあたしの今後の研究の着想にもつながるしね。",
  ui_story_1019_10190402_52_dialog_content = "聞いた限り…とても重大そうな仕事ですね。\nでも、力になれるのなら喜んで力になります。",
  ui_story_1019_10190402_53_dialog_content = "じゃ、さっそくソラヴァンをあたしの<color=#FFB400>端末</color>につなげてちょうだい。\nこの作業には多少時間がかかるわ。",
  ui_story_1019_10190402_54_dialog_content = "待っている間に…そうね…",
  ui_story_1019_10190402_55_dialog_content = "<color=#FFB400>端末</color>っていうのは、\n今腕にはめている、そのリストバンドでいいんですか？",
  ui_story_1019_10190402_56_dialog_content = "これはハイテクリストバンドっていうの。\nあたしはスポーツバンドって呼ぶ方が好きだけど。",
  ui_story_1019_10190402_57_dialog_content = "ちょうどトレーニングの時間ね。あなたたちも一緒にどう？",
  ui_story_1019_10190402_58_dialog_content = "まだ朝も早いですが…アルゴル博士、いつも早朝に運動されるのですか？",
  ui_story_1019_10190402_59_dialog_content = "あたしの体内時計ではそうなんだけど…",
  ui_story_1019_10190402_60_dialog_content = "じゃ、こうしましょ。さっきの戦闘をトレーニングと見なして、\n今日はこのまま仕事を始めましょ。",
  ui_story_1019_10190402_61_dialog_content = "…",
  ui_story_1019_10190402_62_dialog_content = "執事くん…ドアを開けて、\nついでに目覚ましのコーヒーを3杯用意しておいて。",
  ui_story_1019_10190402_63_dialog_content = "1号、拒否します。1号は執事ではありません。",
  ui_story_1019_10190402_64_dialog_content = "…",
  ui_story_1019_10190402_65_dialog_content = "アハ、ハハハ…た、たぶん、まだ寝ぼけてるのね…",
  ui_story_1019_10190501_1_dialog_content = "<color=#e8d9bb>アルゴルの研究室</color>",
  ui_story_1019_10190501_2_dialog_content = "あたしの研究室へようこそ――\n散らかってるけど、適当に座って。",
  ui_story_1019_10190501_3_dialog_content = "啓光に、こんな実験室があったとは…",
  ui_story_1019_10190501_4_dialog_content = "鉢植えにトレーニング機材…\nそれから、何か分かりませんがすごそうなものが有りますね。",
  ui_story_1019_10190501_5_dialog_content = "これは…ベッドですか？それともソファーですか？",
  ui_story_1019_10190501_6_dialog_content = "実際に使ってみれば、分かるわよ。\nマッサージボタンは横にあるわ。",
  ui_story_1019_10190501_7_dialog_content = "ああ…とても気持ちがいいです。眠くなってしまいます…",
  ui_story_1019_10190501_8_dialog_content = "この研究室…まったく啓光らしくないですね…",
  ui_story_1019_10190501_9_dialog_content = "その通りですね。『啓光居住環境管理条例』もまったく無視されていますし…",
  ui_story_1019_10190501_10_dialog_content = "そうかしら？ここにある物はほとんど、\n廃棄された素材を改造したものよ。",
  ui_story_1019_10190501_11_dialog_content = "生活と仕事を1部屋にまとめたの。資源の節約でしょう？",
  ui_story_1019_10190501_12_dialog_content = "それに、参謀長こそ勤務時間中にマッサージなんて、\n『啓光軍人条例』違反じゃないかしら。",
  ui_story_1019_10190501_13_dialog_content = "マ、マッサージなんて受けていません！",
  ui_story_1019_10190501_14_dialog_content = "眠くなるって言ってませんでしたっけ…？",
  ui_story_1019_10190501_15_dialog_content = "空の末裔くんも突っ立ってないで。\nそこに回転マシンがあるでしょ？",
  ui_story_1019_10190501_16_dialog_content = "あの上に10分間立ってるだけで、\n巨像を10周するより高いダイエット効果が得られるわ。",
  ui_story_1019_10190501_17_dialog_content = "運動の話は、ひとまず後にしましょう…",
  ui_story_1019_10190501_18_dialog_content = "ピピッ――",
  ui_story_1019_10190501_19_dialog_content = "お久しぶりです、空の末裔さん！",
  ui_story_1019_10190501_20_dialog_content = "あ、1号！執事くんって呼ばれてたロボットは君だったんだね。",
  ui_story_1019_10190501_21_dialog_content = "1号は、アルゴルの執事になる約束はしていません。",
  ui_story_1019_10190501_22_dialog_content = "…じゃあ、手に持ってるのは何？",
  ui_story_1019_10190501_23_dialog_content = "1号はお客様2名に目覚ましのコーヒーをお持ちしました。\nアルゴルは自分で淹れてください。",
  ui_story_1019_10190501_24_dialog_content = "え～？冷たいわね…",
  ui_story_1019_10190501_25_dialog_content = "う～ん…これはバター入りでしょうか？\n影ノ街でしか飲んだことのない味ですね。",
  ui_story_1019_10190501_26_dialog_content = "特別にブレンドしたオイルを加えました。\n参謀長の好みに合うはずです。",
  ui_story_1019_10190501_27_dialog_content = "ええ、好きな味です。",
  ui_story_1019_10190501_28_dialog_content = "僕も飲んでみよう…",
  ui_story_1019_10190501_29_dialog_content = "う～ん…緑の香りがして…想像以上においしい！",
  ui_story_1019_10190501_30_dialog_content = "天空ノ谷をイメージしました。",
  ui_story_1019_10190501_31_dialog_content = "最近アルゴルが開発した興味深いプログラム群の一つです。\n1号はそれぞれの飲食習慣にもとづき、特別なコーヒーを淹れることができます。",
  ui_story_1019_10190501_32_dialog_content = "そうなると、1号は本当に執事みたいだね。",
  ui_story_1019_10190501_33_dialog_content = "…",
  ui_story_1019_10190501_34_dialog_content = "ブーブー！",
  ui_story_1019_10190501_35_dialog_content = "これでよしっと。環境は構築できたわ。\nデータを動かすわよ！",
  ui_story_1019_10190501_36_dialog_content = "入力装置、入力装置は…どこに行ったのかしら？",
  ui_story_1019_10190501_37_dialog_content = "あ…1号、拾ってちょうだい。",
  ui_story_1019_10190501_38_dialog_content = "…",
  ui_story_1019_10190501_39_dialog_content = "…僕が拾います。",
  ui_story_1019_10190501_40_dialog_content = "あれ…？このメモ…裏面が、ピンクのハートだらけだ？",
  ui_story_1019_10190501_41_dialog_content = "…「愛しいアルゴル、数学を教えてくれないかい？」",
  ui_story_1019_10190501_42_dialog_content = "こちらは…「君の聡明さがシェルターのサーチライトのように僕を照らす」…",
  ui_story_1019_10190501_43_dialog_content = "差出人は「あててごらん」…？",
  ui_story_1019_10190501_44_dialog_content = "あ～、それ――昔もらったラブレターね。",
  ui_story_1019_10190501_45_option_content = "…キザなセリフばかりですね",
  ui_story_1019_10190501_46_option_content = "…こっちが恥ずかしくなります",
  ui_story_1019_10190501_47_dialog_content = "他人からもらったラブレターを計算用紙にするのは、\nいいことではありません。",
  ui_story_1019_10190501_48_dialog_content = "計算用紙にちょうどいいのに、もったいないでしょ…\nそれに、1枚も捨ててないんだからいいじゃない。",
  ui_story_1019_10190501_49_dialog_content = "こっちのボードを使えばいいのに…",
  ui_story_1019_10190501_50_dialog_content = "と思ったけど、すごく大きいのに…地図と…計算式…\n計算式でいっぱいですね…",
  ui_story_1019_10190501_51_dialog_content = "ふせんに書き直しの痕がたくさん残っています…\nアルゴル博士の情緒の波が分かりますね。",
  ui_story_1019_10190501_52_dialog_content = "あら、そこに刻まれたあたしの苦しみが分かる？",
  ui_story_1019_10190501_53_dialog_content = "「ガーディアン」の謎が一向に解けなくて、苦悩してたのよ。",
  ui_story_1019_10190501_54_dialog_content = "「ガーディアン」というのは、1号のことですか？",
  ui_story_1019_10190501_55_dialog_content = "違うわよ。",
  ui_story_1019_10190501_56_dialog_content = "「ガーディアン1号」は啓光科学技術システム全体の\n通常稼働と計算を担う太古の人工知能だけど――",
  ui_story_1019_10190501_57_dialog_content = "その実態は膨大な数のコンピューター・クラスターよ。\nコアがファントムに盗まれたことのカナン城への影響は見てのとおり。",
  ui_story_1019_10190501_X57_dialog_content = "で、そのコンピューター・クラスターも\n太古の科学技術「ガーディアン」を基礎に、徐々に出来上がったものなの。",
  ui_story_1019_10190501_58_dialog_content = "要するに、「ガーディアン」は「ガーディアン1号」のプロトタイプってことね。",
  ui_story_1019_10190501_59_dialog_content = "1号はそのクラスターの一部だけど、データを単独で処理できるコアを持っているし、\n中に大量の太古の情報も保存してるわ。",
  ui_story_1019_10190501_X59_dialog_content = "つまり、理論上はどのコンピューターも同じ名前だけど、\n区別するために、この子は1号っていうのよ。ね、ポストくん。",
  ui_story_1019_10190501_60_dialog_content = "1号はポストではありません。",
  ui_story_1019_10190501_61_dialog_content = "ピピピピッ。",
  ui_story_1019_10190501_62_dialog_content = "1号はアルゴルが言っていることを理解できません。",
  ui_story_1019_10190501_63_dialog_content = "どうやら1号は、光霊同士の複雑な会話情報の処理を\n学ぶ必要がありそうね。",
  ui_story_1019_10190501_64_dialog_content = "1号、分かりました。",
  ui_story_1019_10190501_65_dialog_content = "（今のって、適当にお茶を濁しただけだよね…？）",
  ui_story_1019_10190501_66_dialog_content = "とにかく、あたしの仕事は「ガーディアン」を研究して、\n「ガーディアン」を知り、新しい機能を開発すること。",
  ui_story_1019_10190501_67_dialog_content = "では、こちらのマシンはプロトタイプですか？",
  ui_story_1019_10190501_68_dialog_content = "これは<color=#FFB400>複製</color>よ。\n安全上の理由から、プロトタイプはだいぶ前に封印されたわ。",
  ui_story_1019_10190501_69_dialog_content = "それもそうですね…太古の科学技術であれば、\n相当痛んでいるでしょうから。",
  ui_story_1019_10190501_70_dialog_content = "いいえ、そうとも限らないわ。以前見たプロトタイプは…\n歴史の重厚感と高貴な雰囲気を醸し出していたわ。",
  ui_story_1019_10190501_71_dialog_content = "ここ数年、その他の関連科学技術はどれも進歩したけど、\n「ガーディアン」の研究だけは一向に大きな進展がないの…",
  ui_story_1019_10190501_72_dialog_content = "封印される前に、もう少し研究していたら…",
  ui_story_1019_10190501_73_dialog_content = "今思い出しても、悔しくて仕方ないわ！",
  ui_story_1019_10190501_74_dialog_content = "ブ～。",
  ui_story_1019_10190501_75_dialog_content = "なんてことかしら！ブールにまで笑われるなんて…",
  ui_story_1019_10190501_76_dialog_content = "ブールは今…笑ったわけじゃないと思いますけど…\n「そんなことないよ」って言ったみたいですよ。",
  ui_story_1019_10190501_77_dialog_content = "ブー！",
  ui_story_1019_10190501_78_dialog_content = "大変だわ！空の末裔くんまで、あたしより賢くなっちゃったわ！",
  ui_story_1019_10190501_79_dialog_content = "…",
  ui_story_1019_10190501_80_dialog_content = "誤解といえば…",
  ui_story_1019_10190501_81_dialog_content = "1号の意識を感知できるなら、\nブールの意識の中がどうなっているのかも見てみたら？",
  ui_story_1019_10190501_82_dialog_content = "ブーブー！！",
  ui_story_1019_10190501_83_dialog_content = "それは…今思い付いたんですか？\n後に隠れちゃいましたけど、ブールは嫌みたいですよ？",
  ui_story_1019_10190501_84_dialog_content = "ブー…",
  ui_story_1019_10190501_85_dialog_content = "今の見た？わざと恥ずかしがってるのよ。",
  ui_story_1019_10190501_86_dialog_content = "じゃあ…試してみます。",
  ui_story_1019_10190501_87_dialog_content = "ブー…",
  ui_story_1019_10190501_88_option_content = "精神感知",
  ui_story_1019_10190501_89_dialog_content = "（え？ブールはアルゴルさんの後ろに隠れた…？\nどうしてアルゴルさんしかいないんだろう…？）",
  ui_story_1019_10190501_90_dialog_content = "（感知対象を間違えたのかな？）",
  ui_story_1019_10190501_91_dialog_content = "（でも、背景に何もない…）",
  ui_story_1019_10190501_92_dialog_content = "（もしかして、アルゴルさんは光霊じゃなくてロボットなの…？\nまさか…人工知能とか！？）",
  ui_story_1019_10190501_93_dialog_content = "（いや、そんなはずはない…さっき光力で戦ってたし…\n僕は何を考えてるんだ…）",
  ui_story_1019_10190501_94_dialog_content = "（感知した意識の層が浅すぎたのかも。もっと深い層を探ろう…）",
  ui_story_1019_10190501_95_dialog_content = "（もっと深い層を…）",
  ui_story_1019_10190501_96_dialog_content = "（もっと深く…）",
  ui_story_1019_10190501_97_dialog_content = "（あれ？今のは…ブール？）",
  ui_story_1019_10190501_98_dialog_content = "（2つの感知対象間を行ったり来たりできてる！？\n不思議な感覚だな…まるで目が4つあるみたいだ…）",
  ui_story_1019_10190501_99_dialog_content = "<color=#e8d9bb>ブー！！パン――</color>",
  ui_story_1019_10190501_100_dialog_content = "あ――！",
  ui_story_1019_10190601_1_dialog_content = "ブールったら、空の末裔くんには優しいのね。",
  ui_story_1019_10190601_2_dialog_content = "心拍数、血圧…バイタルは全部正常。\n酸素化と協調性の機能も向上してるわ。",
  ui_story_1019_10190601_3_dialog_content = "「殴打」で他人の身体を鍛えるつもりですか！？",
  ui_story_1019_10190601_4_dialog_content = "これのどこが「殴打」なの？アザ1つできてないじゃない…\nそれに、今のは上級コミュニケーションなんだから。",
  ui_story_1019_10190601_5_dialog_content = "ブ～。",
  ui_story_1019_10190601_6_dialog_content = "その語気、覚えてるよ！今慰めても遅いよ…",
  ui_story_1019_10190601_7_dialog_content = "アルゴル博士、ブールとはいったいどうやって\nコミュニケーションをとっているんですか？",
  ui_story_1019_10190601_8_dialog_content = "ブールは、強度を変えて叩くことで意思を伝えてくれるのよ。\nでも、この方法、空の末裔くんはあまりなじめないみたいね。",
  ui_story_1019_10190601_9_dialog_content = "なじめないので、やめてもらえると嬉しいです…",
  ui_story_1019_10190601_10_dialog_content = "でも、今までブールはずっと友好的だったのに、\nどうしたのかしら…？",
  ui_story_1019_10190601_11_dialog_content = "うーん…さっきブールの意識が見えたことは見えたんですが…",
  ui_story_1019_10190601_12_dialog_content = "1号の意識と違って、具体的な情景は見えませんでした。",
  ui_story_1019_10190601_13_dialog_content = "それはそうでしょうね。\nブールの思考方式はコンピューターに近いの。",
  ui_story_1019_10190601_14_dialog_content = "とにかく、ブールは気性が荒くてごめんなさいね。\nでも、これで仲良くなれたでしょ？",
  ui_story_1019_10190601_15_dialog_content = "…",
  ui_story_1019_10190601_16_dialog_content = "<color=#e8d9bb>ピ――ピピッ――</color>",
  ui_story_1019_10190601_17_dialog_content = "あ、ソラヴァンのデータ内にはやっぱり、\n新しい地図上の位置に対応する座標信号があったのね。",
  ui_story_1019_10190601_18_dialog_content = "そこは一度も行ったことのない地域ですね？",
  ui_story_1019_10190601_19_dialog_content = "あら？これは、いくつも座標があるという意味ですか？",
  ui_story_1019_10190601_20_dialog_content = "同じ信号だと思うわ。波長に揺れがあったのかもしれない。",
  ui_story_1019_10190601_21_dialog_content = "カナン城の西北、およそ4000㎞ってところかしら…",
  ui_story_1019_10190601_22_dialog_content = "ふぅ…まずまずってところね。思ったほど遠くないわ。",
  ui_story_1019_10190601_23_dialog_content = "ただ、この信号は回帰の塔の発した信号よりかなり古いわ。",
  ui_story_1019_10190601_24_dialog_content = "つまり、天空ノ谷は巨像の生まれた場所じゃないってことですか…？",
  ui_story_1019_10190601_25_dialog_content = "そういうことになるわね。天空ノ谷は暗鬼がアストラ大陸に\n侵入した後に造られた前衛基地だったのかもしれないわ。",
  ui_story_1019_10190601_26_dialog_content = "巨像が生まれた場所は暗面にあるのかも。",
  ui_story_1019_10190601_27_dialog_content = "天空ノ谷はソラヴァンの故郷じゃなかったんですね…",
  ui_story_1019_10190601_28_dialog_content = "だったら、空の末裔の故郷でもないのかも…",
  ui_story_1019_10190601_29_dialog_content = "故郷がどこにあろうと、そんなこと重要じゃないわ。",
  ui_story_1019_10190601_30_dialog_content = "重要なのは、ソラヴァンは「家」の意識が芽生えた時からずっと、\n空の末裔と一緒に天空ノ谷で暮らしてたってことよ。",
  ui_story_1019_10190601_31_dialog_content = "機械生物学の視点から見れば、\n今のソラヴァンはあなたが造ったみたいなものなの。",
  ui_story_1019_10190601_32_dialog_content = "…",
  ui_story_1019_10190601_33_dialog_content = "そう気を落とさないで。ただの推測なんだから。",
  ui_story_1019_10190601_34_dialog_content = "位置を確認できたら、一緒に答えを見つけに行きましょ。",
  ui_story_1019_10190601_35_dialog_content = "とはいっても、アルゴル博士。\nどうやって暗面探索に行くんですか？",
  ui_story_1019_10190601_36_dialog_content = "ヘリオスと暗面偵察隊の提供してくれた情報のおかげで、\n暗面のことがだいぶ分かってきたの。",
  ui_story_1019_10190601_37_dialog_content = "今、専門家がその情報に基づいて地図を製作してるから、\nソラヴァンのデータがちょうど助けになるわ。",
  ui_story_1019_10190601_38_dialog_content = "専門家にいろいろ聞いてみましょ。\nどう？興味が湧いてきたんじゃないかしら？",
  ui_story_1019_10190601_39_dialog_content = "はい。",
  ui_story_1019_10190601_40_dialog_content = "<color=#e8d9bb>ピッ――</color>",
  ui_story_1019_10190601_41_dialog_content = "え？科学棟エリアに暗鬼が…？\n巡回は今、誰が担当してるの？",
  ui_story_1019_10190601_42_dialog_content = "この時間はバートン将軍が担当しているはずです。\nただ、博士はなぜ暗鬼が侵入したと分かったんですか？",
  ui_story_1019_10190601_43_dialog_content = "このリストバンドは近くの危険を感知できるのよ。\nバートンが担当なら…大丈夫ね。",
  ui_story_1019_10190601_44_dialog_content = "科学棟エリアはカナン城の重要エリアです。\n暗鬼が侵入したとなれば、カナン城の安全は…",
  ui_story_1019_10190601_45_dialog_content = "暗鬼はどこに現れたんですか？\nすぐに状況を把握し、防御の配備をします。",
  ui_story_1019_10190601_46_dialog_content = "バートンにはもう知らせたわ。",
  ui_story_1019_10190601_47_dialog_content = "危険の通知や暗鬼の分析、兵士の配備やバグの修復といったことは…\n全部、このリストバンドでできるの。",
  ui_story_1019_10190601_48_dialog_content = "しかし――",
  ui_story_1019_10190601_49_dialog_content = "大丈夫、信じてちょうだい。あなたも何もかも自分でやることないわ…\nそんなことしてたら、過労で倒れちゃうわよ。",
  ui_story_1019_10190601_50_dialog_content = "いいえ、すべて職責範囲内です。\n疲れなど感じません。",
  ui_story_1019_10190601_51_dialog_content = "いい心構えね。\nでも、目の下のクマはウソつかないってブールが言ってるわ。",
  ui_story_1019_10190601_52_dialog_content = "ブー！",
  ui_story_1019_10190601_53_dialog_content = "行きましょ。ちょうど暗鬼の出現地点を通るから、\n心配なら、ついでに様子を見てみるといいわ。",
  ui_story_1019_10190601_54_dialog_content = "ブー！",
  ui_story_1019_10190702_1_dialog_content = "まさか…科学棟エリアに本当に暗鬼が侵入するとは…",
  ui_story_1019_10190702_2_dialog_content = "でも…本当に暗鬼なんですか…？\n啓光の兵士のようにも見えますけど…",
  ui_story_1019_10190702_3_dialog_content = "バートンに聞いてみましょ。\n向こうもきっと暗鬼を片付け終わってるだろうから。",
  ui_story_1019_10190702_4_dialog_content = "小僧、なんでいやがる？\nレインハトに天空ノ谷でおとなしくしてろって言われたろ！？",
  ui_story_1019_10190702_5_dialog_content = "それは…話すと長くなるんだけど…",
  ui_story_1019_10190702_6_dialog_content = "あたしが呼んだのよ。",
  ui_story_1019_10190702_7_dialog_content = "あんたが俺に連絡してきた科学者のアルゴルだな？",
  ui_story_1019_10190702_8_dialog_content = "そうよ。暗鬼は外部から侵入したわけじゃないんでしょ？",
  ui_story_1019_10190702_9_dialog_content = "暗鬼のことは…あんたら科学者は\n余計な手出ししないでもらいてえな。",
  ui_story_1019_10190702_10_dialog_content = "トワイライトシティのことは知ってんだろ？\nユリシーズの陰謀は失敗したとはいえ、こっちは散々な目に遭ったんだ。",
  ui_story_1019_10190702_11_dialog_content = "他の科学者と一緒にしないでほしいわね。\nあたし、光霊には興味ないの。",
  ui_story_1019_10190702_12_dialog_content = "バートン将軍、アルゴル博士も好意で尋ねているんです。\nまずは暗鬼の状況を教えてください。",
  ui_story_1019_10190702_13_dialog_content = "…",
  ui_story_1019_10190702_14_dialog_content = "ったく、おかしなもんだぜ！着いた時には暗鬼なんざいねえで、\n兵士が2人、実験棟を通り過ぎようとしてただけだったんだ…",
  ui_story_1019_10190702_15_dialog_content = "それがよ、近づいた途端、\n急におかしくなったみてえに飛び掛かってきたんだよ！",
  ui_story_1019_10190702_16_dialog_content = "私たちも同じような目に遭いました。",
  ui_story_1019_10190702_17_dialog_content = "よく見りゃ「啓明の星計画」の兵士に見えなくもねえな。\nおい、小僧。お前はどう思う？",
  ui_story_1019_10190702_18_dialog_content = "さっき戦闘の指揮をしてる時に感じた暗力は普通じゃなかった…",
  ui_story_1019_10190702_19_dialog_content = "暗鬼だとすれば、防御システムに問題が発生して、\n実験用暗鬼が倉庫から逃げ出したのかもしれないわね。",
  ui_story_1019_10190702_20_dialog_content = "あり得るな。啓光の科学棟エリアには\n医療センターやブラック・アンブレラだけじゃねえ…",
  ui_story_1019_10190702_21_dialog_content = "光霊をいじくりまわしてる科学者もいるからな。",
  ui_story_1019_10190702_22_dialog_content = "ブー…",
  ui_story_1019_10190702_23_dialog_content = "だったら、なぜ直接ユリシーズに聞きに行かないの？",
  ui_story_1019_10190702_24_dialog_content = "聞けるもんなら、とっくに聞いてるさ！",
  ui_story_1019_10190702_25_dialog_content = "「啓明の星計画」の調査は一向に進まねえし、\nユリシーズの改造研究に対する委員会の態度は釈然としねえしよ！",
  ui_story_1019_10190702_26_dialog_content = "このまま先延ばしにすりゃ、\nカナン城はとんだことになるだろうよ！",
  ui_story_1019_10190702_27_dialog_content = "ユリシーズ教授はあれだけたくさんの兵士の命を犠牲にしたのに、\n啓光はどうして罪を問わないんですか？",
  ui_story_1019_10190702_28_dialog_content = "私が説明しましょう。",
  ui_story_1019_10190702_29_dialog_content = "罪を問わないのも、兵士たちに配慮してのことです。\nユリシーズ博士には負傷者の治療に協力する義務があります。",
  ui_story_1019_10190702_30_dialog_content = "関連資料もすべてユリシーズ博士の実験棟にあり、\n審問チームは現在も資料の押収および照会を行っているところです。",
  ui_story_1019_10190702_31_dialog_content = "監視を付けてはいますが、ユリシーズ博士は現在、\n比較的自由の身と言ってよいでしょう。",
  ui_story_1019_10190702_32_dialog_content = "ですから、特別な事情がない限り、\n彼の実験室には入れないんです。",
  ui_story_1019_10190702_33_dialog_content = "この暗鬼たちを証拠に、防御の穴を見つけるとかなんとかこじつけて、\nユリシーズを尋問できるんじゃないかしら？",
  ui_story_1019_10190702_34_dialog_content = "ブー！",
  ui_story_1019_10190702_35_dialog_content = "それはもう試したさ。失敗したがな。",
  ui_story_1019_10190702_36_dialog_content = "だったら、あたしの出番ね。ユリシーズの実験室に入る権限を持ってるの。\nあなたたちは助手ってことにすればいいわ。",
  ui_story_1019_10190702_37_dialog_content = "少なくとも、あたしの知る限りでは、\n暗鬼が外部からカナン城の最深層に侵入するのは不可能よ。",
  ui_story_1019_10190702_38_dialog_content = "「ガーディアン1号」のコアが盗まれたあげく、\n科学棟エリアが暗鬼の巣窟になるなんて冗談じゃないわよ。",
  ui_story_1019_10190702_39_dialog_content = "いい案だと思います。バートン将軍はどう思いますか？",
  ui_story_1019_10190702_40_dialog_content = "じゃ、試してみっか…",
  ui_story_1019_10190702_41_dialog_content = "さあ行きましょ。ただ気を付けてね。\nもし本当に倉庫から暗鬼が逃げ出したなら、この数体だけじゃないはずよ。",
  ui_story_1019_10190802_1_dialog_content = "ブーブー！！",
  ui_story_1019_10190802_2_dialog_content = "焦っちゃダメよ。今データを転送してあげるから…",
  ui_story_1019_10190802_3_dialog_content = "巡回の兵士の報告によれば、他の実験棟内にはやはり暗鬼は出現していません。\nどうやら目標は正しかったようですね。",
  ui_story_1019_10190802_4_dialog_content = "まさか、ユリシーズ教授がわざと暗鬼を逃がしたんですか？",
  ui_story_1019_10190802_5_dialog_content = "ヤツにそんな度胸はねえよ。\n啓光まるごと道連れにするほどバカじゃねえだろうしな。",
  ui_story_1019_10190802_6_dialog_content = "コホン…それは、褒め言葉でしょうか？",
  ui_story_1019_10190802_7_dialog_content = "おい、ユリシーズ。\nお前の実験室に暗鬼がいるだろ？",
  ui_story_1019_10190802_8_dialog_content = "ここは実験棟ですよ。光霊と暗鬼の研究に供するため、\n常に多くの実験用暗鬼の備えがあります。",
  ui_story_1019_10190802_9_dialog_content = "それは秘密でもありませんし、\nあなた方が心配することではありませんよ。",
  ui_story_1019_10190802_10_dialog_content = "しかし、コアが盗まれてから、実験棟の倉庫の扉にも問題が発生しています。\nこの暗鬼たちはおそらく、倉庫から逃げ出したんでしょう。",
  ui_story_1019_10190802_11_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_1019_10190802_12_dialog_content = "ただ…これは実験用暗鬼ではありませんよね？\n光霊の改造実験は、すでに続行を禁じられたたはずです。",
  ui_story_1019_10190802_13_dialog_content = "それに、改造した兵士であろうと、実験用の暗鬼であろうと…",
  ui_story_1019_10190802_14_dialog_content = "あなたの実験棟から逃げ出し、同胞たちの命を危険にさらしたとなれば、\n私たちには追及する権限があります。",
  ui_story_1019_10190802_15_dialog_content = "すでに禁じた、ですか。アハハハ…",
  ui_story_1019_10190802_16_dialog_content = "だとしても、いったい誰の許可を受けて、\n私の実験棟に入り、実験用暗鬼を倒したのですか？",
  ui_story_1019_10190802_17_dialog_content = "委員会が何をぬかそうと関係ねえ！\n俺たちの役目は暗鬼を片っ端から片付けることだ！",
  ui_story_1019_10190802_18_dialog_content = "大きな声を出せば、主張が通ると勘違いしてもらっては困りますね。\nただ、実験台を見つけたことに関しては、評価しましょう。",
  ui_story_1019_10190802_19_dialog_content = "てめえっ！",
  ui_story_1019_10190802_20_dialog_content = "ちょっとブールのシステムをチェックしてる間に、\nもうケンカが始まったの…？",
  ui_story_1019_10190802_21_dialog_content = "ユリシーズ、この人たちはあたしの助手よ。\nあなたとは関係ないわ。",
  ui_story_1019_10190802_22_dialog_content = "ちょっと失礼…",
  ui_story_1019_10190802_23_dialog_content = "ユリシーズ長官、委員会から連絡が入りました…",
  ui_story_1019_10190802_24_dialog_content = "最終審問会に遅れず参加するように、とのことです。",
  ui_story_1019_10190802_25_dialog_content = "…分かりました。",
  ui_story_1019_10190802_26_dialog_content = "（ユリシーズ教授が…僕の方を見てる…？）",
  ui_story_1019_10190802_27_dialog_content = "久しぶりですね、空の末裔君。",
  ui_story_1019_10190802_28_dialog_content = "以前会議室で会った時は、レインハトと一緒に来たのでしたね。\nアルゴルもその場にいました。",
  ui_story_1019_10190802_29_dialog_content = "…あんな退屈で、わざとらしい会議、\n今思い出しても時間のムダとしか言いようがないわ。",
  ui_story_1019_10190802_30_dialog_content = "あれから時が経ち、世界も変わりました。\n空の末裔君は、それもこれもお見通しだったのでしょう？",
  ui_story_1019_10190802_31_dialog_content = "どういう意味ですか…？",
  ui_story_1019_10190802_32_dialog_content = "ずいぶんと前から…ある変わった情景を見るようになったのですが、\nここ数年、さらに頻度を増しましてね。",
  ui_story_1019_10190802_33_dialog_content = "実に現実味のある情景で、まるで私の身体を…鼓動を…\n突き動かすかのような…",
  ui_story_1019_10190802_34_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10190802_35_dialog_content = "え？どうしたの…？",
  ui_story_1019_10190802_36_dialog_content = "鼓動？",
  ui_story_1019_10190802_37_dialog_content = "ハハ、我々は共に真実を見る目を持つ者…\nですが、その真実から私を引き離そうとする者がいるのです…",
  ui_story_1019_10190802_38_dialog_content = "そして、君から生命の謎を探る機会を奪おうとしている…\nそれはあまりにも惜しいことです。",
  ui_story_1019_10190802_39_dialog_content = "フッ…審問会の後、いったい誰が暗鬼に立ち向かえると言うのでしょうか。",
  ui_story_1019_10190802_40_dialog_content = "何をごちゃごちゃ言ってやがんだ？\nこの俺に倒せねえ敵なんかいねえよ。",
  ui_story_1019_10190802_41_dialog_content = "PlayerNameを丸め込んで、責任逃れをするつもりですね？",
  ui_story_1019_10190802_42_dialog_content = "そうではありませんよ。私はただ、アストラの空の末裔に問いたいだけです。\n生命の謎を探りたいとは思わないのかと。",
  ui_story_1019_10190802_43_dialog_content = "君にそのつもりがあるのなら、\nここで真相を見られるかもしれませんよ…",
  ui_story_1019_10190802_44_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10190802_45_dialog_content = "もうっ…何？よく分からないわ――",
  ui_story_1019_10190802_46_dialog_content = "ブール、どうしたのよ？",
  ui_story_1019_10190802_47_dialog_content = "少し様子がおかしいわ。\nこんな反応、今まで見せたことなかったのに…",
  ui_story_1019_10190802_48_dialog_content = "ハハハ。その異常の発現は、幸せの表れかもしれませんよ。",
  ui_story_1019_10190802_49_dialog_content = "幸せの表れ？",
  ui_story_1019_10190802_50_dialog_content = "悪夢が訪れた時、守ってくれる者がいるというのは、\n幸せなことでしょう？",
  ui_story_1019_10190802_51_dialog_content = "ただ、今はまだ、すべてが不確定のままですがね…",
  ui_story_1019_10190802_52_dialog_content = "なぞなぞ遊びをする時間があるなら、\n病院で診てもらった方がいいんじゃないかしら？",
  ui_story_1019_10190802_53_dialog_content = "フフ。若いとはいいものですね。",
  ui_story_1019_10190802_54_dialog_content = "空の末裔君、いかがです？\n真相を知りたいと思っていることはありませんか？",
  ui_story_1019_10190802_55_dialog_content = "（まさか…）",
  ui_story_1019_10190802_56_option_content = "（あの夢の真相を知ってるの？）",
  ui_story_1019_10190802_57_option_content = "（バイスの鼓動の真相を…？）",
  ui_story_1019_10190802_58_dialog_content = "（でも、どうしてユリシーズ教授が…）",
  ui_story_1019_10190802_59_dialog_content = "（それとも、ビビアンさんの言ったみたいに、\n僕を利用して罪を逃れようとしてるのかな？）",
  ui_story_1019_10190802_60_dialog_content = "迷っている様子を見ると、\nやはり疑問に思っていることがあるようですね？",
  ui_story_1019_10190802_61_dialog_content = "実験室で、ちょっとした「実験」を手伝っていただければ、\n答えが見つかりますよ。",
  ui_story_1019_10190802_62_dialog_content = "それだけでなく…君の限界も知ることができるでしょう。",
  ui_story_1019_10190802_63_dialog_content = "ユリシーズ博士、大元帥様から言われているはずです。\n実験は一切禁止されています！",
  ui_story_1019_10190802_64_dialog_content = "実験どころか、PlayerNameに指一本でも触れてみろ。\n俺がすぐにお前を取り押さえてやる。",
  ui_story_1019_10190802_65_dialog_content = "お二人とも誤解しないでいただきたい。\n私こそ空の末裔君の「実験」対象ですよ。",
  ui_story_1019_10190802_66_dialog_content = "好奇心に基づく仮説はいかなるものも、\n実験をもって検証しなければならない、そうでしょう？",
  ui_story_1019_10190802_67_dialog_content = "どんな実験をしたいんですか？",
  ui_story_1019_10190802_68_dialog_content = "空の末裔の能力を使い、私の夢に出てくる奇妙な情景を感知し…\nそこに君の求める答えがあるかどうか、見てほしいのです。",
  ui_story_1019_10190802_69_dialog_content = "奇妙な夢…！",
  ui_story_1019_10190802_70_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10190802_71_dialog_content = "いったいどうしたっていうの…？\n空の末裔くん、行きましょ。",
  ui_story_1019_10190802_72_dialog_content = "でも、僕は残って…",
  ui_story_1019_10190802_73_dialog_content = "PlayerName！？",
  ui_story_1019_10190802_74_dialog_content = "実験してみたいです。",
  ui_story_1019_10190802_75_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10190802_76_dialog_content = "や、やめなさいって――引っ張らないでちょうだい…",
  ui_story_1019_10190802_77_dialog_content = "ごめんなさい。まずはブールを落ち着かせるわ。",
  ui_story_1019_10190802_78_dialog_content = "安心しろ。任務外だが、俺がちゃんと見張ってる。",
  ui_story_1019_10190802_79_dialog_content = "PlayerNameの安全を守ることは、私の務めです。",
  ui_story_1019_10190802_80_dialog_content = "実験室は安全です。どうぞお入りください。",
  ui_story_1019_10190901_1_dialog_content = "空の末裔君、準備はいいですか？\nただ、始める前に1つ質問させてください。",
  ui_story_1019_10190901_2_dialog_content = "君は…「世界の果て」はどこにあると思いますか？",
  ui_story_1019_10190901_3_dialog_content = "暗潮の危機が再びやってくるとしたら、\n光霊はどのようにして闇の浸食に立ち向かうべきでしょう？",
  ui_story_1019_10190901_4_dialog_content = "それは…考えたことがありません。",
  ui_story_1019_10190901_5_dialog_content = "空の末裔はかつて、アストラ大陸からはるか彼方へ飛び立つという快挙を成し遂げました。\n空の上の未知の空間について、知りたいとは思わないのですか？",
  ui_story_1019_10190901_6_dialog_content = "それは太古の時代の空の末裔と巨像が成し遂げた奇跡です。\n今の僕とはかけ離れています。",
  ui_story_1019_10190901_7_dialog_content = "僕はごく普通の空の末裔で、足を踏み入れたことのある一番遠い場所も、\nアストラ大陸に近い東方の大陸です。",
  ui_story_1019_10190901_8_dialog_content = "フフ。誰でも恐怖で自身の想像力を縛ってしまうものです。",
  ui_story_1019_10190901_9_dialog_content = "何が言いたいんですか？",
  ui_story_1019_10190901_10_dialog_content = "すぐに分かりますよ。それでは、始めましょう。",
  ui_story_1019_10190901_11_dialog_content = "…",
  ui_story_1019_10190901_12_option_content = "精神感知",
  ui_story_1019_10190901_13_dialog_content = "ここは…北境？",
  ui_story_1019_10190901_14_dialog_content = "たくさんの氷の石柱が…刃のように空に向かってる…",
  ui_story_1019_10190901_15_dialog_content = "いや、この暗さは暗面かな…",
  ui_story_1019_10190901_16_dialog_content = "以前探索した極光遺跡でも、\n黒い岩石が冷たく暗い気配を漂わせてた。",
  ui_story_1019_10190901_17_dialog_content = "でも、極光遺跡の岩石はどっしりと地面の上にあったけど…\nここの氷の石柱は宙に浮いてる。",
  ui_story_1019_10190901_18_dialog_content = "中には光を放ちながら、上に向かって伸びてるものもある…",
  ui_story_1019_10190901_19_dialog_content = "これは…ユリシーズ教授の記憶なのかな？\nどうして、こんな所に来たんだろう？",
  ui_story_1019_10190901_20_dialog_content = "ユリシーズ教授の意識の中に、\nどうしてこんな記憶があるの？",
  ui_story_1019_10190901_21_dialog_content = "まるで忘れ去られた世界みたいだ。\n生命の気配がまったくしない…",
  ui_story_1019_10190901_22_dialog_content = "<color=#e8d9bb>ゴロゴロ――</color>",
  ui_story_1019_10190901_23_dialog_content = "何の音…！？",
  ui_story_1019_10190901_24_dialog_content = "氷の石柱が動いた！まるで何かの力に引っ張られて、集まっていくみたいだ…",
  ui_story_1019_10190901_25_dialog_content = "まさか…何かを形づくろうとしてるの？",
  ui_story_1019_10190901_26_dialog_content = "ここは、いったいどこ――",
  ui_story_1019_10190901_27_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1019_10190901_28_dialog_content = "ふぅ…",
  ui_story_1019_10190901_29_dialog_content = "どうです、空の末裔君？感想は？",
  ui_story_1019_10190901_30_dialog_content = "おい、何を見せられたんだ？",
  ui_story_1019_10190901_31_option_content = "あれは…どこですか？",
  ui_story_1019_10190901_32_dialog_content = "どこ、ですか…",
  ui_story_1019_10190901_33_option_content = "どうして、僕に見せたんです？",
  ui_story_1019_10190901_34_dialog_content = "それは…",
  ui_story_1019_10190901_35_dialog_content = "世界の果てだからです。",
  ui_story_1019_10190901_36_dialog_content = "あの場所に、暗鬼が潜み、悪魔を呼び起こそうとしているからです…",
  ui_story_1019_10190901_37_dialog_content = "悪魔…？",
  ui_story_1019_10190901_38_dialog_content = "（前に太古の戦場で聞いた「悪魔」のこと…？）",
  ui_story_1019_10190901_39_dialog_content = "でも、暗鬼なんていませんでした。\n無数の氷の石柱があっただけで…",
  ui_story_1019_10190901_40_dialog_content = "ハハハ。それは、すでに始まっているからですよ。",
  ui_story_1019_10190901_41_dialog_content = "始まってるとは…？",
  ui_story_1019_10190901_42_dialog_content = "悪魔の召喚です。",
  ui_story_1019_10190901_43_dialog_content = "…",
  ui_story_1019_10190901_44_dialog_content = "ユリシーズ、てめえ！頭でもイカれたか！\nPlayerNameから離れやがれ！",
  ui_story_1019_10190901_45_dialog_content = "参謀長、バートン軍団長、PlayerNameさんもいらっしゃいましたか…",
  ui_story_1019_10190901_46_dialog_content = "アナトリア少佐、ちょうどいい時に来ました。",
  ui_story_1019_10190901_47_dialog_content = "委員会に言われてきたのですね…",
  ui_story_1019_10190901_48_dialog_content = "はい。「啓明の星計画」に関する審問会が開かれます。\nすでにご連絡したかと思いますが。",
  ui_story_1019_10190901_49_dialog_content = "出席しますよ。ただ…",
  ui_story_1019_10190901_50_dialog_content = "委員会は、空の末裔は光霊を救う英雄だと考えているのでしょう？\nでしたら、彼にも出席していただきたいのですが。",
  ui_story_1019_10190901_51_dialog_content = "ユリシーズ博士、それは規定違反です。",
  ui_story_1019_10190901_52_dialog_content = "では、空の末裔が自由にカナン城を出入りしているのは、\n違反ではないのですか？",
  ui_story_1019_10190901_53_dialog_content = "空の末裔君、私の提案を考えてみてください。\n君が知りたがっていることの答えを、私は知っています。",
  ui_story_1019_10190901_54_dialog_content = "啓光じゅうを探しても、\n真相を知っているのは私だけかもしれませんよ。",
  ui_story_1019_10190901_55_dialog_content = "…",
  ui_story_1019_10190901_56_dialog_content = "今、あなたが一番にすべきことは何か知っていますか？\n悪魔が訪れる前に、生き残るための準備をすることです！",
  ui_story_1019_10190901_57_dialog_content = "…",
  ui_story_1019_10190901_58_dialog_content = "アナトリア少佐、ユリシーズ博士をお連れしてください。",
  ui_story_1019_10190901_59_dialog_content = "空の末裔君？",
  ui_story_1019_10190901_60_dialog_content = "…",
  ui_story_1019_10190901_61_dialog_content = "アハハハ…君が光霊を救うなど、あり得ない話ですね！\nゴホッ、ゴホゴホ…",
  ui_story_1019_10190901_62_dialog_content = "優柔油断で…弱く…志もない！\n君は…ゴホッ、ゴホゴホ…",
  ui_story_1019_10190901_63_dialog_content = "ユリシーズ長官、お待たせしました。\n私におつかまりください。",
  ui_story_1019_10190901_64_dialog_content = "必要ありません！",
  ui_story_1019_10190901_65_dialog_content = "はぁっ…",
  ui_story_1019_10190901_66_dialog_content = "（暗力？いや、待って…そうじゃない…）",
  ui_story_1019_10190901_67_dialog_content = "私は…あきらめませんよ…後悔するといい！\nゴホッ、ゴホゴホ…",
  ui_story_1019_10190901_68_dialog_content = "長官…ふるえていらっしゃいますが、本当に大丈夫ですか？",
  ui_story_1019_10190901_69_dialog_content = "大丈夫だと言っているでしょう！",
  ui_story_1019_10190901_70_dialog_content = "はぁっ！！",
  ui_story_1019_10190901_71_dialog_content = "微かな光は暗影に潜むのです。",
  ui_story_1019_10190901_72_dialog_content = "さっきと同じだ…暗鬼に似た敵…",
  ui_story_1019_10190901_73_dialog_content = "敵ではありませんよ…",
  ui_story_1019_10190901_74_dialog_content = "だったら、何なのですか！？",
  ui_story_1019_10190901_75_dialog_content = "弁解は審問会でしてください。\nPlayerName、戦闘指揮をお願いします！",
  ui_story_1019_10190901_76_dialog_content = "分かりました！",
  ui_story_1019_10190902_1_dialog_content = "バートン将軍、武器を下ろしてください！",
  ui_story_1019_10190902_2_dialog_content = "大元帥様に報告しました。すぐに別の者が到着します。\n私たちには、まず実験室を調べるようにとの命令です。",
  ui_story_1019_10190902_3_dialog_content = "ユリシーズの野郎を生かしとけってのか？こいつら俺たちばっか攻撃しやがって、\n野郎には、ちっとも攻撃仕掛けねえじゃねえか！",
  ui_story_1019_10190902_4_dialog_content = "野郎が実験棟の暗鬼を放ちでもしたら、\n啓光は終わりだ！",
  ui_story_1019_10190902_5_dialog_content = "バートン将軍、ユリシーズ博士の件はアナトリア少佐が責任者です。\n真相は必ず解明すると大元帥様もおっしゃっています。",
  ui_story_1019_10190902_6_dialog_content = "あれあれ～？人がいっぱいだね。\nあたしったら何かいいもの見逃しちゃった？",
  ui_story_1019_10190902_7_dialog_content = "あら、ボーヤもいたの。戦場で洗礼を受けて、ずいぶん大人になったのねぇ。\n匂いまで…変わったわ。",
  ui_story_1019_10190902_8_dialog_content = "…",
  ui_story_1019_10190902_9_dialog_content = "お2人が止めに入ろうと、ユリシーズ博士は私がお連れします。",
  ui_story_1019_10190902_10_dialog_content = "止めなんかしないよ。あたしたちはただ、実験室の引き継ぎに来ただけ。\nというわけで、みんな解散～。",
  ui_story_1019_10190902_11_dialog_content = "実験室を引き継ぐですと？笑止千万…",
  ui_story_1019_10190902_12_dialog_content = "最高科学者会議の主席は私です！\nあなたたちでは、一生を費やそうと、私の業績を超えることはできません！",
  ui_story_1019_10190902_13_dialog_content = "業績は高ければ高いほどいいんだよ！啓光では、知識の独占は許されないよ。\nあたしがこの資料を理解できないとでも思ってるの？",
  ui_story_1019_10190902_14_dialog_content = "ただ、悪いけど、実験室を明け渡す前に、\nコンピューターの権限を移行してね。",
  ui_story_1019_10190902_15_dialog_content = "実験用の暗鬼と生物材料は、ブラック・アンブレラで引き継がせてもらうわ。",
  ui_story_1019_10190902_16_dialog_content = "安心して。私がいる限り、\n1匹たりとも暗鬼が科学棟エリアをうろつくことはないから。",
  ui_story_1019_10190902_17_dialog_content = "空の末裔君、君は本当に知りたくないのですか！？",
  ui_story_1019_10190902_18_option_content = "知りたくありません",
  ui_story_1019_10190902_19_dialog_content = "（あの光景とユリシーズ教授が関係あるなんて…何かおかしい…）",
  ui_story_1019_10190902_20_dialog_content = "（ビビアンさんにさっき見たことを伝えなきゃ！）",
  ui_story_1019_10190902_21_option_content = "知りたいです",
  ui_story_1019_10190902_22_dialog_content = "（ユリシーズ教授はあんなものをどうして僕に見せたんだろう…？\nまさか、本当に何か伝えたいことがあるのかな？）",
  ui_story_1019_10190902_23_dialog_content = "（でも、教授の様子がおかしいし、信用できない…）",
  ui_story_1019_10190902_24_dialog_content = "審問会が終われば、何もかも明らかになるはずです。",
  ui_story_1019_10190902_25_dialog_content = "フフ…アハハハハ…",
  ui_story_1019_10190902_26_dialog_content = "これが光霊の末路ですか…生涯の心血を注いだ結果が\nあなた方のような愚か者に踏みにじられようとは。",
  ui_story_1019_10190902_27_dialog_content = "まあ、いい…仕方ありませんね…",
  ui_story_1019_10190902_28_dialog_content = "ならば、私自らすべてを明かして差し上げましょう。",
  ui_story_1019_10190902_29_dialog_content = "あなた方も歴史の証人になれるのなら、\nそれも栄誉でしょうね…",
  ui_story_1019_10190902_30_dialog_content = "ベリサリア教授に私の証人を呼ぶよう伝えてください。",
  ui_story_1019_10190902_31_dialog_content = "証人ですか？どなたのことでしょう？",
  ui_story_1019_10190902_32_dialog_content = "インゲル、アクセリア、ショーンです。\nとにかく連れて来ればいいのです。",
  ui_story_1019_10190902_33_dialog_content = "はい、長官。",
  ui_story_1019_10190902_34_dialog_content = "…",
  ui_story_1019_10190902_35_dialog_content = "PlayerName、あなたの懸念は大元帥様にも伝えてあります。\nただ今は、ユリシーズ博士を審問会に任せるしかありません。",
  ui_story_1019_10190902_36_dialog_content = "真相が明らかになるまでに、まだやらなければならない大切なことがあります。\n忘れてはいけませんよ。私たちには座標の探索という仕事が残っているんです。",
  ui_story_1019_10190902_37_dialog_content = "はい…でも、ユリシーズ教授の質問が、\n気になってしかたないんです…",
  ui_story_1019_10190902_38_dialog_content = "君は…「世界の果て」はどこにあると思いますか？",
  ui_story_1019_10190902_39_dialog_content = "暗潮の危機が再びやってくるとしたら、\n光霊はどのようにして闇の浸食に立ち向かうべきでしょう？",
  ui_story_1019_10190902_40_dialog_content = "すぅ――はぁ――",
  ui_story_1019_10190902_41_dialog_content = "きっと最近よく眠れてないせいです。何だかいつもぼうっとして、\n何か大切なものを失くした気がしてならないんです。",
  ui_story_1019_10190902_42_dialog_content = "本当に何か失くしていたとしても、あなたは道の遠さにも闇にも臆することなく、\n勇敢に探しに行くんでしょうね。",
  ui_story_1019_10190902_43_dialog_content = "しかし、啓光は違います。\n啓光は私たちの家であり、希望です。",
  ui_story_1019_10190902_44_dialog_content = "ここで、シェルターの空を見上げる時…",
  ui_story_1019_10190902_45_dialog_content = "地上には、太陽が昇っています。",
  ui_story_1019_10190902_46_dialog_content = "啓光の者にとって、シェルターを離れ、陽の光の下に立った時、\nその場所こそが最も遠い場所です。",
  ui_story_1019_10190902_47_dialog_content = "カナン城じゃ時間が目まぐるしく過ぎて、\n太陽も見えやしねえが、闇に浸食される心配はねえ。",
  ui_story_1019_10190902_48_dialog_content = "ただ、過ぎた時間の分だけ、\nどんどん地下深くに潜って行ってんだ。",
  ui_story_1019_10190902_49_dialog_content = "建設されたばかりのカナン城は、\nどんな様子だったんでしょうね…",
  ui_story_1019_10190902_50_dialog_content = "1つだけ分かってんのは、\n暗鬼がそこらじゅうにウヨウヨしてたってことだな。",
  ui_story_1019_10190902_51_dialog_content = "暗鬼の脅威から逃れて、地下で暮らすようになり、\n同時に暗鬼を消すことが俺たちの目標になった。",
  ui_story_1019_10190902_52_dialog_content = "審問が終わった頃、啓光の未来はどうなってるんだかな。",
  ui_story_1019_10190902_53_dialog_content = "…",
  ui_story_1019_10190902_54_dialog_content = "あれやこれや考えちまってんだろうが、しっかりしろよ！",
  ui_story_1019_10190902_55_dialog_content = "うん。話してたら、元気になった気がするよ。",
  ui_story_1019_10190902_56_dialog_content = "きっとアルゴル博士の言ってた「体内時計」が動き出したんでしょう。\n今ちょうど1日が始まる時間です。",
  ui_story_1019_10190902_57_dialog_content = "そうですか…",
  ui_story_1019_10190902_58_dialog_content = "じゃあ…おはようございます！ビビアンさん、バートン！",
  ui_story_1019_10190902_59_dialog_content = "おはようございます、PlayerNameさん。",
  ui_story_1019_10190902_60_dialog_content = "おう！お前たちはお前たちの仕事をしに行け。\nまったく、こんなこと早く終わらせたいもんだな。",
  ui_story_1019_10191001_1_dialog_content = "<color=#e8d9bb>啓光上層部会議室。全員が沈黙している</color>",
  ui_story_1019_10191001_2_dialog_content = "私を断罪するのではなかったのですか？\n皆さん、なぜ黙っているのです？",
  ui_story_1019_10191001_3_dialog_content = "コホン…",
  ui_story_1019_10191001_4_dialog_content = "ええ…",
  ui_story_1019_10191001_5_dialog_content = "審問会もこれで5回目ね。せっかくだから、少し形を変えて\nおしゃべりするのはどうかしら？証人も連れて来たようだし。",
  ui_story_1019_10191001_6_dialog_content = "…",
  ui_story_1019_10191001_7_dialog_content = "おしゃべりだと？これ以上いつまで引き延ばすつもりだ？\nトワイライトシティと啓光防衛線の戦いで、我が軍の決意と実力は証明したはずだ！",
  ui_story_1019_10191001_8_dialog_content = "軍事演習事件の証人ヘリオスは、まだ完全に意識を回復していないわ。\n「啓明の星計画」の兵士の状況も検査中よ。",
  ui_story_1019_10191001_9_dialog_content = "言い訳だ。確たる証拠に基づいて物を言え！",
  ui_story_1019_10191001_10_dialog_content = "その通りよ。軍事演習にしろ、「啓明の星計画」にしろ、\n当事者である私1人で、証人は十分でしょ！",
  ui_story_1019_10191001_11_dialog_content = "術後の回復は順調のようね、ラス大元帥。",
  ui_story_1019_10191001_12_dialog_content = "あなたたちの言うことは分かるわ。\nでも、ユリシーズの立場と貢献を無視するわけにもいかないの。",
  ui_story_1019_10191001_13_dialog_content = "ここまで審問会を引き延ばしておいて、まだ粘るつもり？",
  ui_story_1019_10191001_14_dialog_content = "チャンスをやる。だが、これが最後だ。",
  ui_story_1019_10191001_15_dialog_content = "レインハト？",
  ui_story_1019_10191001_16_dialog_content = "ただし、1つ条件がある。我が軍もこれ以上譲歩はしない。\n最終審判が下る前に、こちらも証人を呼ばせてもらう。",
  ui_story_1019_10191001_17_dialog_content = "その時には、確実にユリシーズを断罪してもらおう。",
  ui_story_1019_10191001_18_dialog_content = "もちろんよ。そうとなれば、時間は有効に使いましょう。\nユリシーズ、これが最後の陳述よ。何か真新しい話を聞かせて。",
  ui_story_1019_10191001_19_dialog_content = "フフ…私は…ゴホゴホッ…",
  ui_story_1019_10191001_20_dialog_content = "ユリシーズ長官、薬を――",
  ui_story_1019_10191001_21_dialog_content = "…",
  ui_story_1019_10191001_22_dialog_content = "…いや、大丈夫です。最近体調を崩していましてね。\n少し疲れているだけです。",
  ui_story_1019_10191001_23_dialog_content = "すでに申し上げたように、私は何一つ隠していません。",
  ui_story_1019_10191001_24_dialog_content = "こちらが質問していなければ、\n黙っていても、当然隠蔽とは言えないわ。",
  ui_story_1019_10191001_25_dialog_content = "ただ、これまでの研究成果とあなたが実験室を去った後も残りのメンバーで\n研究を続けられるかどうかについては、正直に話してもらいたいわね。",
  ui_story_1019_10191001_26_dialog_content = "何しろ、あなたの任務は過去から引き継いだものなんだから。\nきちんと次の世代に引き継がないとね。",
  ui_story_1019_10191001_27_dialog_content = "私があまりにも長生きしすぎだと言いたいのですか？ハハハ…",
  ui_story_1019_10191001_28_dialog_content = "晨光歴1945年に生を受け、すでに半世紀以上生きている…",
  ui_story_1019_10191001_29_dialog_content = "啓光の光霊の平均寿命から言えば、同年代の者と同様、\n私はとうに死んでいるべきでしょうね。",
  ui_story_1019_10191001_30_dialog_content = "「エンジニア」の制約により、啓光が創設以来抱えてきた難題を\n戦いしか知らない軍人たちに本当に任せていいのでしょうか？",
  ui_story_1019_10191001_31_dialog_content = "…",
  ui_story_1019_10191001_32_dialog_content = "「エンジニア」？何のことよ？",
  ui_story_1019_10191001_33_dialog_content = "レインハト、あんたはアイツが何を言っているのか分かるの？",
  ui_story_1019_10191001_34_dialog_content = "…",
  ui_story_1019_10191001_35_dialog_content = "ユリシーズ、話をそらすのはやめなさい。\n「啓明の星計画」を進めた目的はいったい何なの？",
  ui_story_1019_10191001_36_dialog_content = "光霊の生存能力を高めるため、啓光は長年光霊の改造実験を行ってきました。\nそれは皆さんもご存じのはずです。",
  ui_story_1019_10191001_37_dialog_content = "初期の身体強化実験から、現在の「啓明の星計画」に至るまでに誕生した、\nヘリオスとデニール以外の優秀な個体が今ここにそろっています。",
  ui_story_1019_10191001_38_dialog_content = "…",
  ui_story_1019_10191001_39_dialog_content = "…",
  ui_story_1019_10191001_40_dialog_content = "身体強化実験…？優秀な個体？",
  ui_story_1019_10191001_41_dialog_content = "啓光連邦の軍人の中には、戦闘力を高めたおかげで、\n他者の命を守れている者が少なくありません。",
  ui_story_1019_10191001_42_dialog_content = "身体的欠陥をもって生まれながら、改造技術によって、\n生きながらえている光霊は数知れず…",
  ui_story_1019_10191001_43_dialog_content = "先生…どうして…僕を見てるんですか…？",
  ui_story_1019_10191001_44_dialog_content = "僕がその…改造技術で生きながらえてる…光霊なんですか…？",
  ui_story_1019_10191001_45_dialog_content = "…",
  ui_story_1019_10191001_46_dialog_content = "じょ、冗談ですよね…？僕はただ定期検査に来てるだけじゃ…\n改造技術…？改造で生きながらえるって…",
  ui_story_1019_10191001_47_dialog_content = "君は普通の光霊ではないのですよ、ショーン。\n君は「啓明の星計画」の優秀な個体の1人です。",
  ui_story_1019_10191001_48_dialog_content = "…",
  ui_story_1019_10191001_49_dialog_content = "信じられませんか？君たちには分からないでしょうね。\n自分たちがいかに幸運か。",
  ui_story_1019_10191001_50_dialog_content = "戦火の絶えない時代を生きてきた私のような年代の者にとって、\n戦える者とは力なき者の生存権を奪う存在です。",
  ui_story_1019_10191001_51_dialog_content = "君たちが私と同じ立場だったら、\nどのような選択をしたのでしょう…？",
  ui_story_1019_10191001_52_dialog_content = "ユリシーズ、また何か新しいことを思いついたのかい？",
  ui_story_1019_10191001_53_dialog_content = "いつも通りだよ。",
  ui_story_1019_10191001_54_dialog_content = "遺伝子工学か、ハハハ。\nこんな名称、先輩たちはどうやって思いついたんだろうね。",
  ui_story_1019_10191001_55_dialog_content = "どうやって思いついたかなんて重要か？",
  ui_story_1019_10191001_56_dialog_content = "重要なのは、私が今それを研究してるってことだよ。",
  ui_story_1019_10191001_57_dialog_content = "「どうやって思いついたか」などという問題を考えたことはありません。\nその類の追求は往々にして、くだらない結果にしか至りませんから…",
  ui_story_1019_10191001_58_dialog_content = "カナン城は白夜城のある先遣隊によって発見されました。",
  ui_story_1019_10191001_59_dialog_content = "恐れを知らない戦士たちは暗鬼に抗う戦いの中で、壊滅的な打撃を受けました。\nしかし、白夜城は彼らを見捨てた…",
  ui_story_1019_10191001_60_dialog_content = "当初の先遣隊はその後、\n地下シェルターを拠点とする軍事連邦となりました。",
  ui_story_1019_10191001_61_dialog_content = "しかし、なぜか…ラヴィルの言葉が私の頭の中から\nどうしても離れないのです。",
  ui_story_1019_10191001_62_dialog_content = "ユリシーズ、また何か新しいことを思いついたのかい？",
  ui_story_1019_10191001_63_dialog_content = "…",
  ui_story_1019_10191001_64_dialog_content = "何をそんなに夢中になって読んでるんだい？",
  ui_story_1019_10191001_65_dialog_content = "『啓光連邦歴史年鑑』…？よくそんなものを読む暇があるね。\n急に歴史に興味でも持ったのかい？",
  ui_story_1019_10191001_66_dialog_content = "ラヴィル、啓光連邦は建立何年になる？",
  ui_story_1019_10191001_67_dialog_content = "<color=#FFB400>649年だよ</color>",
  ui_story_1019_10191001_68_dialog_content = "…よく覚えているな。",
  ui_story_1019_10191001_69_dialog_content = "当然だよ。父さんに反対されてなかったら、\n僕は母さんに励まされて、歴史学者になってたはずなんだから。",
  ui_story_1019_10191001_70_dialog_content = "それで？啓光連邦の建立年数を聞くなんて、\n僕をテストしたかったわけじゃないだろう？",
  ui_story_1019_10191001_71_dialog_content = "遺伝子工学の発展過程をたどっていたんだが、\n『啓光連邦歴史年鑑』を読むうちに、ある問題点に気づいたんだ。",
  ui_story_1019_10191001_72_dialog_content = "啓光には遺伝子工学の始まりについての記録がないんだよ。\nまるで、遺伝子改造技術がその誕生の瞬間からすでに高い水準にあったかのようにね。",
  ui_story_1019_10191001_73_dialog_content = "遺伝子工学は白夜城の技術だったとか？\n啓光が建立される前にすでにあったんじゃないのかい？",
  ui_story_1019_10191001_74_dialog_content = "もしくは…啓光の歴史は649年以上ある、とか…？",
  ui_story_1019_10191001_75_dialog_content = "あり得ないことではないね。引き続き研究してみるよ。",
  ui_story_1019_10191001_76_dialog_content = "それからというもの、私は憑りつかれたかのように、\nこの問題について調べ始めました。",
  ui_story_1019_10191001_77_dialog_content = "資料館の外が平和なのか、戦火に見舞われているのかにも\n構うことなく、ただ没頭しました。",
  ui_story_1019_10191001_78_dialog_content = "戦火の及ばない小さな資料室で、私の真実追究に影響を及ぼすものは、\n時間だけだと分かっていたからです。",
  ui_story_1019_10191001_79_dialog_content = "1日…そして、1か月と時が過ぎ…",
  ui_story_1019_10191001_80_dialog_content = "頭の中の声が私に告げました。\n実験の失敗などもう恐れることはない。歴史が答えを教えてくれる、と。",
  ui_story_1019_10191001_81_dialog_content = "そして、また1年…2年と時が過ぎ…",
  ui_story_1019_10191001_82_dialog_content = "ついにある日…",
  ui_story_1019_10191001_83_dialog_content = "ラヴィル！ラヴィル！見てくれ…\n右下隅に何と書いてある！？",
  ui_story_1019_10191001_84_dialog_content = "…「エンジニア」？",
  ui_story_1019_10191001_85_dialog_content = "いったい何のことだい？",
  ui_story_1019_10191001_86_dialog_content = "これまで読んできた資料には、遺伝子工学の起源についての記載がないか、\n簡単な説明しかされていなかった。",
  ui_story_1019_10191001_87_dialog_content = "だが、この本の、ここの記述が答えを教えてくれたんだ――",
  ui_story_1019_10191001_88_dialog_content = "「□□の助けを得て、光力過負荷の問題は解決し…」",
  ui_story_1019_10191001_89_dialog_content = "何の助けを得て？",
  ui_story_1019_10191001_90_dialog_content = "そうだ、何かの助けを得たんだよ。",
  ui_story_1019_10191001_91_dialog_content = "…「エンジニア」かな？\n君は削除された部分に「エンジニア」と書かれてたって考えてるのかい？",
  ui_story_1019_10191001_92_dialog_content = "そうだ。直感だがな。",
  ui_story_1019_10191001_93_dialog_content = "それは面白い…本文では削除したのに、\n答えを隅に残しておくなんて…",
  ui_story_1019_10191001_94_dialog_content = "だとしても、ユリシーズ。確信はあるのかい？\n同じようなことが他にもあったとか？",
  ui_story_1019_10191001_95_dialog_content = "いいや、ない…だが、難解な資料も、\n「エンジニア」という言葉を当てて読んでいけば…",
  ui_story_1019_10191001_96_dialog_content = "すっきりと意味が通るんだよ…",
  ui_story_1019_10191001_97_dialog_content = "「エンジニアの導きの下、一部の光霊が科学研究チームを組織し、\n太古の科学技術の研究を始めた」",
  ui_story_1019_10191001_98_dialog_content = "「エンジニアが科学研究チームをカナン城全体の構造の見学に連れて行き、\n一部科学技術の使用方法を教えた」",
  ui_story_1019_10191001_99_dialog_content = "ユリシーズ、君のそんなに嬉しそうな姿は初めて見たよ。",
  ui_story_1019_10191001_100_dialog_content = "引き続き調べてみる！",
  ui_story_1019_10191001_101_dialog_content = "資料室の外に絶え間なく響く砲火の音も…",
  ui_story_1019_10191001_102_dialog_content = "あともう少しで、光霊が暗鬼に打ち勝った祝いの音となる――\n私はそう信じていました。",
  ui_story_1019_10191101_1_dialog_content = "暗面の地図の製作は、どんな具合かしら？",
  ui_story_1019_10191101_2_dialog_content = "おや、アルゴル博士ではありませんか。\n実験室から息抜きにお出ましとは、実にめずらしいですね。",
  ui_story_1019_10191101_3_dialog_content = "ジョイス博士、こんにちは。",
  ui_story_1019_10191101_4_dialog_content = "どうも、こんにちは。おや？\nこちらは…空の末裔ではありませんか？",
  ui_story_1019_10191101_5_dialog_content = "ごきげんよう。",
  ui_story_1019_10191101_6_dialog_content = "アルゴルから聞いていますよ。\n君の巨像が暗面の地図のモデル構築を手伝ってくれるそうですね。心から感謝します。",
  ui_story_1019_10191101_7_dialog_content = "とんでもありません。啓光の助けになるって約束しましたし、\n僕自身にとっても意味のあることですから。",
  ui_story_1019_10191101_8_dialog_content = "ジョイス、おしゃべりはそこまでにして、意見を聞かせて。\n暗面の座標が分かったんだけど、探索できる可能性はあるかしら？",
  ui_story_1019_10191101_9_dialog_content = "暗面に関する新しいデータを入手したのですか…？\n<color=#FFB400>地形モデルシミュレーション</color>の進度に追いついてきましたね。",
  ui_story_1019_10191101_10_dialog_content = "ご存じのように、今の環境モデルは既知のエリアの連続性に基づき\n計算を行い、構築したものです。",
  ui_story_1019_10191101_11_dialog_content = "つまり、座標とカナン城の距離が離れ、かつ間に地層を異にする大陸があった場合、\nきわめて複雑な計算が必要となります。",
  ui_story_1019_10191101_12_dialog_content = "現段階では、確率の加重平均に基づき、連続と不連続の2パターンそれぞれの計算を行った上で\n既存の環境データを参照しながら推算するしかありませんね。",
  ui_story_1019_10191101_13_dialog_content = "それで？推算の結果は？",
  ui_story_1019_10191101_14_dialog_content = "ずいぶんとせっかちですね…",
  ui_story_1019_10191101_15_dialog_content = "結果だけ教えてちょうだい。",
  ui_story_1019_10191101_16_dialog_content = "分かりました…今はまだヘリオスの提供した手がかりに基づき、\n地形モデルを修正しているところですが――",
  ui_story_1019_10191101_17_dialog_content = "アストラの居住に適したエリアの外側には、厚みの異なる氷に閉ざされた湖沼が分布し、\nその上にはさらに雪が薄く積もっていることが分かっています。",
  ui_story_1019_10191101_18_dialog_content = "湖沼地帯の先には、高さが不揃いの氷塔の林があり、\n氷塔の形状も様々です…",
  ui_story_1019_10191101_19_dialog_content = "鋭い三角錐形のものもあれば、逆円錐形のものも、\nゆがんだらせん状のものもあり…",
  ui_story_1019_10191101_20_dialog_content = "余計な情報はいいわ、重点だけ話してちょうだい！",
  ui_story_1019_10191101_21_dialog_content = "ブー！ブー！ブー！",
  ui_story_1019_10191101_22_dialog_content = "あら、興味があるの？",
  ui_story_1019_10191101_23_dialog_content = "ブー！ブー！ブー！",
  ui_story_1019_10191101_24_dialog_content = "…",
  ui_story_1019_10191101_25_dialog_content = "<color=#e8d9bb>ジョイスは約15分間にわたり、話し続け…</color>",
  ui_story_1019_10191101_26_dialog_content = "…つまり、氷塔の中には空気が含まれており、温度差によって液化し、\n様々な奇怪な形の石柱や氷柱が形づくられたのです。",
  ui_story_1019_10191101_27_dialog_content = "原理はよく分かりませんが、\nおそらく白夜城の浮空技術と関係があるのでしょう。",
  ui_story_1019_10191101_28_dialog_content = "しかし、気流は凝固時、上昇する場合も、下降する場合もあるため…",
  ui_story_1019_10191101_29_dialog_content = "待ってください！今、何て言いましたか？",
  ui_story_1019_10191101_30_dialog_content = "…形状に大きな差が生まれるものと思われます。\nそれが私の結論です。",
  ui_story_1019_10191101_31_dialog_content = "「今」とはどの部分のことですか？",
  ui_story_1019_10191101_32_dialog_content = "上昇する石柱…",
  ui_story_1019_10191101_33_dialog_content = "ユリシーズ教授の意識の中で、同じようなものを見ました…",
  ui_story_1019_10191101_34_dialog_content = "見間違いじゃありません…そんな偶然…あるんでしょうか？",
  ui_story_1019_10191101_35_dialog_content = "…",
  ui_story_1019_10191101_36_dialog_content = "ジョイス、石柱のところ、もう一度話してくれる？",
  ui_story_1019_10191101_37_dialog_content = "気流は凝固時、上昇する場合も、下降する場合もあるため、\n形状に大きな差が生まれるのだろう、と言いましたが？",
  ui_story_1019_10191101_38_dialog_content = "上昇と下降といえば、以前実験をしたことがありまして…",
  ui_story_1019_10191101_39_dialog_content = "間違いありません…",
  ui_story_1019_10191101_40_dialog_content = "よく思い出してみれば、上昇する氷の石柱の中には確か、\n光るリングのようなものがはめ込まれているものもありました…",
  ui_story_1019_10191101_41_dialog_content = "「ガーディアン1号」のコアを見たっていうの？\n上昇する氷の石柱の中にコアが…？",
  ui_story_1019_10191101_42_dialog_content = "…そういうことかしら？",
  ui_story_1019_10191101_43_dialog_content = "はい！",
  ui_story_1019_10191101_44_dialog_content = "おもしろいわね…とても、おもしろいわ！",
  ui_story_1019_10191101_45_dialog_content = "あなたがユリシーズの意識の中で見たものは、暗面偵察隊が送ってきた\n「ガーディアン1号」のコアらしきものの画像とそっくりだわ。",
  ui_story_1019_10191101_46_dialog_content = "しかも、ソラヴァンのデータの中にあった座標の周囲に\n上昇する氷の石柱がある…",
  ui_story_1019_10191101_47_dialog_content = "これで合点がいったわ…信号が点滅してたのは、\n座標が複数あったからじゃなく、氷の石柱が移動してたからなのね！",
  ui_story_1019_10191101_48_dialog_content = "少し整理させてください。ユリシーズ博士はコアの在処を知っていただけでなく、\nコアは巨像の誕生した場所にある可能性が高いということですか？",
  ui_story_1019_10191101_49_dialog_content = "…それだけじゃありません。\nユリシーズ教授はバイスに何かあったかのようなことを言ってました。",
  ui_story_1019_10191101_50_dialog_content = "…",
  ui_story_1019_10191101_51_dialog_content = "どうやら、私の情報は大きな助けとなっただけではなく、\nとんでもない秘密まで暴いてしまったようですね。",
  ui_story_1019_10191101_52_dialog_content = "うーん…ユリシーズが日蝕とつながっていたとしたら…\nどう考えても、いい知らせとは言えないわね。",
  ui_story_1019_10191101_53_dialog_content = "でも、ユリシーズはシェルターを出たことがないはずよ。\nそれなのに、どうやって日蝕の企みに深く関係してたのかしら…？",
  ui_story_1019_10191101_54_dialog_content = "先日ファントムがカナン城に潜入し、ガーディアン1号のコアを盗んだのも、\nユリシーズ教授と関係があるんじゃないでしょうか？",
  ui_story_1019_10191101_55_dialog_content = "もっと大胆な可能性も考え得るわ…",
  ui_story_1019_10191101_56_dialog_content = "「ガーディアン1号」があたしのシステムの監視の目を抜けられるはずないわ。\nそんなことができるのは…",
  ui_story_1019_10191101_57_dialog_content = "「安全上の理由で封印された」プロトタイプを使った場合だけよ。",
  ui_story_1019_10191101_58_dialog_content = "…",
  ui_story_1019_10191101_59_dialog_content = "ユリシーズ博士がひそかにプロトタイプを操作していたとしたら、\n会議できちんと問いたださなければなりません。",
  ui_story_1019_10191101_60_dialog_content = "いいえ、彼の研究室に直行しましょ。",
  ui_story_1019_10191101_61_dialog_content = "推測が当たってたとすれば、ユリシーズの研究室こそ、\n今啓光で最も危険な場所だわ！",
  ui_story_1019_10191101_62_dialog_content = "…",
  ui_story_1019_10191201_1_dialog_content = "質問していいかしら？あんたたち、いったい何がしたいのよ？\n記載を削除して、歴史を隠蔽するなんて…",
  ui_story_1019_10191201_2_dialog_content = "「エンジニア」のことをいったいどれだけ隠してるの？\nそれとも、白夜城に何かやましい秘密でもあるの？",
  ui_story_1019_10191201_3_dialog_content = "今はっきりと言えるのは、「エンジニア」に関する情報は啓光にしか記録がなく、\n委員会も十分に把握しているわけじゃないってことだけね。",
  ui_story_1019_10191201_4_dialog_content = "他人をバカにするのもいい加減にして！",
  ui_story_1019_10191201_5_dialog_content = "情報を削除したのは、委員会ではありません。",
  ui_story_1019_10191201_6_dialog_content = "少なくとも、今の委員会ではありません。",
  ui_story_1019_10191201_7_dialog_content = "暗潮の危機が勃発した時、啓光上層部が「ガーディアン」の研究制限を解除していなければ、\n私も「エンジニア」の資料にたどり着くことはできなかったでしょう。",
  ui_story_1019_10191201_8_dialog_content = "「ガーディアン」…？",
  ui_story_1019_10191201_9_dialog_content = "白夜城の先遣隊がカナン城で発見した、\n太古の謎の機械のことです。",
  ui_story_1019_10191201_10_dialog_content = "後にカナン城に住んだ者たちによって、\n「ガーディアン」と名付けられました。",
  ui_story_1019_10191201_11_dialog_content = "その「ガーディアン」を今でも研究しているの？",
  ui_story_1019_10191201_12_dialog_content = "アルゴルが持っているのは、<color=#FFB400>サンドボックスで隔離した</color>複製にすぎないわ。\nプロトタイプは安全上の理由から封印されているの。",
  ui_story_1019_10191201_13_dialog_content = "もともとはそういう計画でした…",
  ui_story_1019_10191201_14_dialog_content = "ユリシーズ…何を言っているの！？",
  ui_story_1019_10191201_15_dialog_content = "フフ…私はずっと考えていたのです。\nプロトタイプの封印と「エンジニア」の情報隠蔽は何か関係があると。",
  ui_story_1019_10191201_16_dialog_content = "そして、私は見つけました。\nプロトタイプの中に保存されていた、大量の「エンジニア」の作業メモを…",
  ui_story_1019_10191201_17_dialog_content = "<color=#e8d9bb>バサッ――</color>",
  ui_story_1019_10191201_18_dialog_content = "ユリシーズ、ここにいたのか！あちこち探したんだぞ。\n戦場に行ったんじゃないかって、皆で心配してたんだ。",
  ui_story_1019_10191201_19_dialog_content = "君はもう立ち直れないんじゃないかって、皆は言ってたけど、\n僕は分かってたよ。君が挫折なんかに負けるわけがないってね。",
  ui_story_1019_10191201_20_dialog_content = "…そう、だろう…？",
  ui_story_1019_10191201_21_dialog_content = "…",
  ui_story_1019_10191201_22_dialog_content = "ユリシーズ？…どうしたんだい？どうして黙ってる？",
  ui_story_1019_10191201_23_dialog_content = "私が「エンジニア」の資料を調べていたことは覚えているね？",
  ui_story_1019_10191201_24_dialog_content = "もちろん。でも、戦争で研究環境も良くないし…\n家族を失ったばかりだから、あきらめたものとばかり…",
  ui_story_1019_10191201_25_dialog_content = "ラヴィル、信じられないだろうけど、委員会が最近開放した太古の人工知能こそ、\n「エンジニア」について調べる鍵だったんだ。",
  ui_story_1019_10191201_26_dialog_content = "あの太古の機械のことかい？確か「ガーディアン」と言ったっけ。\nあれはアルゴルが研究してるんだよね？",
  ui_story_1019_10191201_27_dialog_content = "あれはただの複製だよ。\nプロトタイプは今目の前にある。",
  ui_story_1019_10191201_28_dialog_content = "ユリシーズ！まさか、封印したプロトタイプを…\nそんなことしたら、牢獄送りだって分かってやってるのか！？",
  ui_story_1019_10191201_29_dialog_content = "だが、「エンジニア」の研究資料が見つかれば、情況は変わる…",
  ui_story_1019_10191201_30_dialog_content = "…",
  ui_story_1019_10191201_31_dialog_content = "「エンジニア」は遺伝子工学の提唱者であるだけでなく…",
  ui_story_1019_10191201_32_dialog_content = "彼の光霊実験と魔導学に関する構想、\nおよび肉体と精神の本質に関する考え方は…",
  ui_story_1019_10191201_33_dialog_content = "私の脳を強烈な電流のように刺激するんだ！\nこんなに胸が躍る感覚は初めてだよ！",
  ui_story_1019_10191201_34_dialog_content = "ユリシーズ…",
  ui_story_1019_10191201_35_dialog_content = "まずは話を最後まで聞いてくれ。",
  ui_story_1019_10191201_36_dialog_content = "彼は光霊の遺伝子の指向性編集を試しているのだが、それは…",
  ui_story_1019_10191201_37_dialog_content = "今私たちがやっている光霊の身体強化よりも数百倍優れているんだ。\nこれが何を意味するか分かるか？",
  ui_story_1019_10191201_38_dialog_content = "その「エンジニア」がいた時代は…今よりも科学技術が進んでたってことかい？",
  ui_story_1019_10191201_39_dialog_content = "ほかには？",
  ui_story_1019_10191201_40_dialog_content = "そうだなぁ…「エンジニア」こそ「ガーディアン」の所有者ってことかな。",
  ui_story_1019_10191201_41_dialog_content = "いいや、ラヴィル。そんなことは重要じゃないよ。",
  ui_story_1019_10191201_42_dialog_content = "重要なのは、彼の研究した技術を復元できれば、\n私たちはもう陽の光の見えない地下で暗鬼を避けて暮らす必要はないってことだよ！",
  ui_story_1019_10191201_43_dialog_content = "…",
  ui_story_1019_10191201_44_dialog_content = "ユリシーズ、もしそれが全部本当だったとしても…あまりにも…",
  ui_story_1019_10191201_45_dialog_content = "これほど喜ばしいことはないだろう？画期的な進歩だ、啓光の未来だよ！\n暗鬼に打ち勝ち、地上に戻るという理想がかなうんだ！",
  ui_story_1019_10191201_46_dialog_content = "君のアイオリアを一周旅行するという夢もだ！",
  ui_story_1019_10191201_47_dialog_content = "アイオリア一周…",
  ui_story_1019_10191201_48_dialog_content = "ユリシーズ、君の心の奥底には、\n誰もかないっこない勇気と力が眠ってるのは分かってた。",
  ui_story_1019_10191201_49_dialog_content = "それでも、やっぱり心配だったんだ…アハハ、立ち直ったんだね。\nよかったよ、ユリシーズ。",
  ui_story_1019_10191201_50_dialog_content = "とにかく、君が元気そうでよかった…",
  ui_story_1019_10191201_51_dialog_content = "ラヴィルがそう言った時、私はまだ気づいていませんでした。",
  ui_story_1019_10191201_52_dialog_content = "しかし、彼の顔から笑みが消え、日ごとに増す戦争の苦しみに押しつぶされてしまった頃、\n私はようやく、彼の言葉の本当の意味に気づいたのです。",
  ui_story_1019_10191201_53_dialog_content = "急がねばならないと思いました。光霊が暗鬼に消されてしまう前に、\n「エンジニア」の研究成果を再現しなければならないと。",
  ui_story_1019_10191201_54_dialog_content = "たとえ、他人や自身を顧みれなくなろうと、\nやらなければいけないと思いました。",
  ui_story_1019_10191201_55_dialog_content = "「エンジニア」のメモの中に、光霊の戦闘力を高める方法を見つけた時、\n私は初めて、研究の興奮と喜びを知ったのですから…",
  ui_story_1019_10191201_56_dialog_content = "ゲホッ…ゴホゴホッ！",
  ui_story_1019_10191201_57_dialog_content = "ユリシーズ長官、大丈夫ですか…？\n少しお休みになられては…",
  ui_story_1019_10191201_58_dialog_content = "…大丈夫です…ゴホゴホ！",
  ui_story_1019_10191201_59_dialog_content = "「エンジニア」の残した手掛かりを見つけ、その成果を再現するのに、\n10年近くの時間を費やしました…",
  ui_story_1019_10191201_60_dialog_content = "10年かかったのですよ？\n彼女たちが私の実験室を引き継いだところで、何ができるというのです？",
  ui_story_1019_10191201_61_dialog_content = "<color=#e8d9bb>ピコピコピコ――</color>",
  ui_story_1019_10191201_62_dialog_content = "ずいぶんときれいに整理してあるのねぇ。神経質ジジイのおかげで手間が省けたわ。\nあら、これは何かしら…",
  ui_story_1019_10191201_63_dialog_content = "…",
  ui_story_1019_10191201_64_dialog_content = "ちょっと、さっき最後のターンだって言ってなかったかしら？\nもう30分経ってるわよ。また、サボる気なの？",
  ui_story_1019_10191201_65_dialog_content = "うーん…手間が省けたなら、\nあとはミジャードちゃんに任せたよ、アハハ！",
  ui_story_1019_10191201_66_dialog_content = "こんなにシンプルなゲームは久しぶりだなぁ。\n唯一の欠点は動きが鈍いことかな。",
  ui_story_1019_10191201_67_dialog_content = "でも…確か啓光のコンピューターは一斉にアップデートしたはずだよね。\n漏れがあったのかな？それとも、このマシンはオジサンの私物とか？",
  ui_story_1019_10191201_68_dialog_content = "何が漏れていたんですか？",
  ui_story_1019_10191201_69_dialog_content = "あっ…こ、これは…勤務時間中に\nゲームしてたわけじゃないからね！",
  ui_story_1019_10191201_70_dialog_content = "コンピューターをいじらせて。",
  ui_story_1019_10191201_71_dialog_content = "アルゴル博士、このマシンですか？",
  ui_story_1019_10191201_72_dialog_content = "…違うわ。何か抜けてる手がかりがあるのかしら…？",
  ui_story_1019_10191201_73_dialog_content = "待ちなさい…動かないで…",
  ui_story_1019_10191201_74_dialog_content = "そ、そんなに近づいて…何してるの？",
  ui_story_1019_10191201_75_dialog_content = "近づかなきゃ分からないでしょ…",
  ui_story_1019_10191201_76_dialog_content = "ここへ来る途中、何かあった？\n何か悪いことを考えてる気配が漂ってるわねぇ…",
  ui_story_1019_10191201_77_dialog_content = "あら、あたしのことを言ってるの？それともブールかしら？",
  ui_story_1019_10191201_78_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10191201_79_dialog_content = "危険？いいえ…とても危険ですって？\nさっきユリシーズに会った時も、それが言いたかったの…？",
  ui_story_1019_10191201_80_dialog_content = "あなたたちが入ってきた時から、何かおかしな感じがしてたけど、\n今はさらに強烈な、視線みたいなものを感じるわ…",
  ui_story_1019_10191201_81_dialog_content = "ボーヤ、何か感じる？",
  ui_story_1019_10191201_82_dialog_content = "少し…",
  ui_story_1019_10191201_83_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10191201_84_dialog_content = "もうっ…ブール、言ったでしょう？首を引っ張らないで！",
  ui_story_1019_10191201_85_dialog_content = "外？扉の外に何かいるの…？",
  ui_story_1019_10191201_86_dialog_content = "大変です！すごく強い暗力が…",
  ui_story_1019_10191201_87_dialog_content = "巡回で見落とした暗鬼かしら…？\n忍び寄る棘の目をすり抜けるなんて…",
  ui_story_1019_10191201_88_dialog_content = "気を付けてください！",
  ui_story_1019_10191201_89_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_1019_10191202_1_dialog_content = "はぁっ――",
  ui_story_1019_10191202_2_dialog_content = "やっと…動かなくなった？",
  ui_story_1019_10191202_3_dialog_content = "大きいね…\nまるでゲームに出てくるラスボスだよ！",
  ui_story_1019_10191202_4_dialog_content = "でも、この暗鬼には何の印もないよ。\nいったい、どこから出てきたんだろう？",
  ui_story_1019_10191202_5_dialog_content = "倉庫内の実験用暗鬼とは違うわね。\n実験コードが付いてないもの。",
  ui_story_1019_10191202_6_dialog_content = "実験用の暗鬼なのか、それとも別の何かなのかさえ、\n分からないわ…",
  ui_story_1019_10191202_7_dialog_content = "ユリシーズの実験台じゃないですか？ラスの近衛軍団みたいな…\nこの怪物たちを使って、委員会に対抗しようとしてるんじゃ…",
  ui_story_1019_10191202_8_dialog_content = "何にせよ、味方を攻撃する武器を造る行為は、\n日蝕の利益と一致するわね。",
  ui_story_1019_10191202_9_dialog_content = "委員会の方は結論が出ましたか？",
  ui_story_1019_10191202_10_dialog_content = "大元帥様と連絡がつきません。\nおそらく審問会はまだ終わっていないのでしょう。",
  ui_story_1019_10191202_11_dialog_content = "委員会の結論を待ってる余裕はないわ。私たちだけで動きましょ。\nプロトタイプとバグを見つけることの方がユリシーズの裁きよりも重要よ。",
  ui_story_1019_10191202_12_dialog_content = "ええ。では、10分後に現状を整理することにしましょう。",
  ui_story_1019_10191202_13_dialog_content = "私は実験棟を一通り巡回して、研究員を避難させます。\n彼らも何か有用な情報を持っているかもしれません。",
  ui_story_1019_10191202_14_dialog_content = "アルゴル博士、危険情報を周辺の巡回兵に送り、増援を要請してください。",
  ui_story_1019_10191202_15_dialog_content = "あとどのくらいの暗鬼がここに潜伏しているか分かりません。\n警戒を怠ってはなりません。",
  ui_story_1019_10191202_16_dialog_content = "分かったわ。あたしは引き続きプロトタイプを探すわ。",
  ui_story_1019_10191301_1_dialog_content = "アイゼン君、どこまで話しましたか？",
  ui_story_1019_10191301_2_dialog_content = "「エンジニア」の作業記録を読み…\n興奮と喜びを覚えた、というところまでです。",
  ui_story_1019_10191301_3_dialog_content = "ああ、そうでしたね…",
  ui_story_1019_10191301_4_dialog_content = "「エンジニア」の偉大な発明を知り、私はこの上ない喜びを覚えました。\n彼は「遺伝子指向性改造」技術で、次々と超戦士を生み出したのですから！",
  ui_story_1019_10191301_5_dialog_content = "「超戦士の量産」が…その後名前を変え、\n「人造陽光計画」や「啓明の星計画」となったわけか？",
  ui_story_1019_10191301_6_dialog_content = "実験過程を再現するだけなら、大したことはありません。\n思いもよらぬ収穫は、最後の作業記録です。",
  ui_story_1019_10191301_7_dialog_content = "大量生産した超戦士の数が今から<color=#FFB400>600年</color>前のある時点で、\n突如ピーク値に達したのです。",
  ui_story_1019_10191301_8_dialog_content = "しかし、その時から「ガーディアン」はどういうわけか\n永久的にシャットダウンしてしまい…",
  ui_story_1019_10191301_9_dialog_content = "「エンジニア」の名も啓光の歴史から消えてしまいました。",
  ui_story_1019_10191301_10_dialog_content = "なぜでしょうか？",
  ui_story_1019_10191301_11_dialog_content = "…",
  ui_story_1019_10191301_12_dialog_content = "インゲル、お前はどう思う？",
  ui_story_1019_10191301_13_dialog_content = "「エンジニア」の…実験が失敗したからでしょうか？",
  ui_story_1019_10191301_14_dialog_content = "いや、実験はこのうえない成功をおさめた。",
  ui_story_1019_10191301_15_dialog_content = "啓光はついに気づいたのです…",
  ui_story_1019_10191301_16_dialog_content = "「エンジニア」が大量生産した「超戦士」こそ、\n戦場で彼らを殺りくする暗鬼だったということに。",
  ui_story_1019_10191301_17_dialog_content = "ラヴィル、私は何か思い違いをしていたのかもしれない…",
  ui_story_1019_10191301_18_dialog_content = "戦場から回収してきた暗鬼の構成成分は複雑だ。\nだが、遺伝子サンプルを取り出せる個体もあった。",
  ui_story_1019_10191301_19_dialog_content = "光霊と一部の暗鬼の遺伝子型は、\n類似度が90%以上にもなるんだ。",
  ui_story_1019_10191301_20_dialog_content = "90%以上だって？",
  ui_story_1019_10191301_21_dialog_content = "無機物を組み合わせて構成された大多数の暗鬼は、\n真の敵が戦場に投げ込んだ爆弾のようなものにすぎない。",
  ui_story_1019_10191301_22_dialog_content = "それ以外に、光霊と非常に近い個体を持つ暗鬼がいて、\nそれこそが爆弾を投げ込んでいる敵なのかもしれないんだ。",
  ui_story_1019_10191301_23_dialog_content = "同じような兵器を造り出さなければ、私たちは永遠に暗鬼に勝てない。\n爆弾を投げ込んだ敵が誰かを解明することなど、夢のまた夢になってしまう。",
  ui_story_1019_10191301_24_dialog_content = "ユリシーズ…君は…暗鬼を造る気か…？",
  ui_story_1019_10191301_25_dialog_content = "いいや。さらに上をいく兵器を造る。",
  ui_story_1019_10191301_26_dialog_content = "暗鬼でもあり、強大な光力術を有する光霊でもある存在を造り出すんだ。",
  ui_story_1019_10191301_27_dialog_content = "暗鬼と光霊の…遺伝子を組み合わせるのか！？",
  ui_story_1019_10191301_28_dialog_content = "ユリシーズ…君はどうかしてるよ…",
  ui_story_1019_10191301_29_dialog_content = "いいや、やっと分かったんだ。",
  ui_story_1019_10191301_30_dialog_content = "こうしなければ、暗鬼には勝てない。",
  ui_story_1019_10191301_31_dialog_content = "生まれもった肉体で暗鬼と戦っても、結末は――",
  ui_story_1019_10191301_32_dialog_content = "だから、自分が暗鬼になっても構わないって言うのか？",
  ui_story_1019_10191301_33_dialog_content = "違う、超越だよ！これは「エンジニア」の考え付いた天才のなせる技だ！\n彼が光霊にさらに強大な力を与えてくれる！",
  ui_story_1019_10191301_34_dialog_content = "ユリシーズ、君は自分が何を言ってるのか分かってるのかい？\n君は光霊が敵と戦う意味を否定しているんだよ？信仰に背いているんだよ！？",
  ui_story_1019_10191301_35_dialog_content = "「エンジニア」の手がかりを見つけてからというもの、\n君の研究は啓光の目指すものから遠ざかってる。",
  ui_story_1019_10191301_36_dialog_content = "考えたことはないのかい？それこそ「エンジニア」の目的かもしれないって。\n僕たちが暗鬼を生産するように、暗鬼になるように誘導してるのかもしれないって？",
  ui_story_1019_10191301_37_dialog_content = "光霊を暗鬼に変えるわけじゃない。\n光霊をさらに強い光霊にすると言ってるんだ！",
  ui_story_1019_10191301_38_dialog_content = "方法はすでに見つかった。研究はすぐに次のステージに入る。",
  ui_story_1019_10191301_39_dialog_content = "君は私を信じてくれるね？\n私の研究は夢を現実にする、光霊の運命を変えられるんだ！",
  ui_story_1019_10191301_40_dialog_content = "それは違うよ、ユリシーズ…そうじゃない…",
  ui_story_1019_10191301_41_dialog_content = "まだ1つ分かってないことがあるだろう…？",
  ui_story_1019_10191301_42_dialog_content = "「エンジニア」がすべてを造ったというなら、彼はいったい誰なんだ？\nどうして、啓光の歴史から消されたんだ？",
  ui_story_1019_10191301_43_dialog_content = "どうして、啓光に背いて…\nどうして、すべての光霊を敵に回したんだ？",
  ui_story_1019_10191301_44_dialog_content = "…",
  ui_story_1019_10191301_45_dialog_content = "「エンジニア」とは、いったい誰だ？",
  ui_story_1019_10191301_46_dialog_content = "暗鬼かもしれませんし、光霊かもしれません。\nそれとも悪魔か…あるいは…",
  ui_story_1019_10191301_47_dialog_content = "そのいずれでもないかもしれません。ゴホ…ゴホゴホッ…ゴホッ！",
  ui_story_1019_10191301_48_dialog_content = "いつまで咳をしているつもり！？今日この場を与えなかったら、\n今の話を墓場まで持って行くつもりだったの？",
  ui_story_1019_10191301_49_dialog_content = "フッ…40年にわたる苦難に満ちた探索です。\n話すには、あまりにも歴史が重すぎ、何から話せばいいのやら、分かりませんでした…",
  ui_story_1019_10191301_50_dialog_content = "皆さんには感謝しています。\n私の気概にあふれた若き日々を…ラヴィルを…思い出させてくれたのですから。",
  ui_story_1019_10191301_51_dialog_content = "ただ、「エンジニア」が誰かという問題は、\n私にとっては、もう重要ではありません。",
  ui_story_1019_10191301_52_dialog_content = "…",
  ui_story_1019_10191301_53_dialog_content = "ユリシーズ、「エンジニア」が誰か、\nあなたにとっては重要でなくても――",
  ui_story_1019_10191301_54_dialog_content = "啓光がこれからどこへ向かうかは、私にとって重要よ。",
  ui_story_1019_10191301_55_dialog_content = "理想を語る時間は、もう十分与えたわ。",
  ui_story_1019_10191301_56_dialog_content = "次は「啓明の星計画」が啓光にどんな利益をもたらすのか、\nそれを教えてちょうだい。",
  ui_story_1019_10191301_57_dialog_content = "あなたの目の前に、啓光に10年の安寧をもたらした人物と、\nこの先10年の未来を担う人物がいるでしょう？",
  ui_story_1019_10191301_58_dialog_content = "光霊が暗鬼に打ち勝つ道はただ一つです。\n光霊のしかばねを踏んで進むことになろうと、私はその道を選びます。",
  ui_story_1019_10191301_59_dialog_content = "それが私の答えです。",
  ui_story_1019_10191401_1_dialog_content = "長官…何か音がしたようですが…",
  ui_story_1019_10191401_2_dialog_content = "研究員は全員研究センターを離れるように伝えたはずです。\nどうしてまだ、ここにいるんですか？",
  ui_story_1019_10191401_3_dialog_content = "待って――あなたのこと、知ってるわ。\nユリシーズの助手ね？",
  ui_story_1019_10191401_4_dialog_content = "この実験台がどこの倉庫から出て来たか分かる？",
  ui_story_1019_10191401_5_dialog_content = "実験台ですか…博士の実験台には皆タグが付いており、\n各ロットごとに保管しています。",
  ui_story_1019_10191401_6_dialog_content = "これは…申し訳ありません。私も見たことがありません。\n博士のコンピューターの中になら記録があるはずですが…",
  ui_story_1019_10191401_7_dialog_content = "ユリシーズのコンピューターなら調べたよ。\n実験データや報告書の類しかなかったけど？",
  ui_story_1019_10191401_8_dialog_content = "だったら、どこから現れたんだろう？",
  ui_story_1019_10191401_9_dialog_content = "どれどれ…",
  ui_story_1019_10191401_10_dialog_content = "アクセスできない？まだ何か隠してるみたいね。",
  ui_story_1019_10191401_11_dialog_content = "ブール？どう思う？",
  ui_story_1019_10191401_12_dialog_content = "ブーブー！",
  ui_story_1019_10191401_13_dialog_content = "いいわ、すばらしいじゃない！",
  ui_story_1019_10191401_14_dialog_content = "助手さん、アクセスキーを入力してちょうだい。",
  ui_story_1019_10191401_15_dialog_content = "はい…",
  ui_story_1019_10191401_16_dialog_content = "<color=#e8d9bb>カチャカチャ――</color>",
  ui_story_1019_10191401_17_dialog_content = "<color=#e8d9bb>ウィーン――</color>",
  ui_story_1019_10191401_18_dialog_content = "やっぱりね！",
  ui_story_1019_10191401_19_dialog_content = "超戦士ファイル…何回バージョンアップしてるのかしら…",
  ui_story_1019_10191401_20_dialog_content = "これは…実験室では、見たことがありません…",
  ui_story_1019_10191401_21_dialog_content = "当然よ。ユリシーズ個人でやってた実験だもの！",
  ui_story_1019_10191401_22_dialog_content = "その超戦士というのは、私たちを襲撃してきた敵のことですよね？\nいったいどこに保管されているんですか？",
  ui_story_1019_10191401_23_dialog_content = "保管場所は…",
  ui_story_1019_10191401_24_dialog_content = "ブーブー！",
  ui_story_1019_10191401_25_dialog_content = "あ、あったわ！",
  ui_story_1019_10191401_26_dialog_content = "…<color=#FFB400>0号倉庫</color>？それって…",
  ui_story_1019_10191401_27_dialog_content = "カナン城に…0号倉庫なんて、ありましたか？",
  ui_story_1019_10191401_28_dialog_content = "聞いたことないよ…",
  ui_story_1019_10191401_29_dialog_content = "とうの昔に封鎖された、あの0号倉庫のことなら…",
  ui_story_1019_10191401_30_dialog_content = "ついてきて！",
  ui_story_1019_10191401_31_dialog_content = "…",
  ui_story_1019_10191401_32_dialog_content = "みんな、走るの速いよ…",
  ui_story_1019_10191401_33_dialog_content = "超戦士はもう光霊の改造どころの話じゃないの。\n量産された暗鬼なのよ！",
  ui_story_1019_10191401_34_dialog_content = "防御の穴から逃げ出したヤツらだけでも十分危険なんだから、\n急いで源から阻止しなきゃ、死ぬのを待つだけよ！",
  ui_story_1019_10191401_35_dialog_content = "<color=#e8d9bb>ガチャッ――</color>",
  ui_story_1019_10191401_36_dialog_content = "…ここが0号倉庫ですか？",
  ui_story_1019_10191401_37_dialog_content = "お、大きいですね！",
  ui_story_1019_10191401_38_dialog_content = "倉庫の扉が全部開いてる…\nエンジン7号を何台も置けそうな広さだね。",
  ui_story_1019_10191401_39_dialog_content = "薬の匂いがするわ…ここで実験をしてたのね。\nみんな気を付けて。",
  ui_story_1019_10191401_40_dialog_content = "<color=#e8d9bb>ピピッ――</color>",
  ui_story_1019_10191401_41_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10191401_42_dialog_content = "本当にあったわ…",
  ui_story_1019_10191401_43_dialog_content = "<color=#e8d9bb>ガチャン――</color>",
  ui_story_1019_10191401_44_dialog_content = "今の音は…この先の機械の上です！超戦士がいます！",
  ui_story_1019_10191401_45_dialog_content = "実験途中ってところだね…\n前にあたしたちを襲った怪物と確かに似てるよ。",
  ui_story_1019_10191401_46_dialog_content = "保管場所が見つかって幸いでした！\n皆さん、安全に注意しながら、周囲を調べてください。",
  ui_story_1019_10191401_47_dialog_content = "<color=#e8d9bb>ピピッ――</color>",
  ui_story_1019_10191401_48_dialog_content = "ハハ…ハハハハ…！",
  ui_story_1019_10191401_49_dialog_content = "ブー！ブー！ブー！",
  ui_story_1019_10191401_50_dialog_content = "アルゴル博士、ここの機械はいじらない方がいいのでは？\n何かのスイッチを入れてしまっては大変です！",
  ui_story_1019_10191401_51_dialog_content = "温度制御モニター、中断ボタン、入力装置…",
  ui_story_1019_10191401_52_dialog_content = "間違いないわ…",
  ui_story_1019_10191401_53_dialog_content = "<color=#e8d9bb>ガチャン――</color>",
  ui_story_1019_10191401_54_dialog_content = "あの超戦士、すごい音を出してるよ！\n機械から離脱しようとしてるみたい！",
  ui_story_1019_10191401_55_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10191401_56_dialog_content = "表示モニターとホスト機の筐体は変えてあるけど、\nこのオペレーションシステムとインターフェイス、コマンド画面は…",
  ui_story_1019_10191401_57_dialog_content = "安全上の理由で封印したっていうのは、\nやっぱりウソだったのね。",
  ui_story_1019_10191401_58_dialog_content = "それから、ここも…",
  ui_story_1019_10191401_59_dialog_content = "まだ動いてるわ…",
  ui_story_1019_10191401_60_dialog_content = "いったいここで何をしてたのよ…？",
  ui_story_1019_10191401_61_dialog_content = "ブブブブブ――！！",
  ui_story_1019_10191401_62_dialog_content = "ブールの動き、すごく速い！",
  ui_story_1019_10191401_63_dialog_content = "<color=#e8d9bb>ガチャン、ガチャン――！！</color>",
  ui_story_1019_10191401_64_dialog_content = "はぁあああ――",
  ui_story_1019_10191401_65_dialog_content = "大変よ。超戦士が拘束を脱したわ！",
  ui_story_1019_10191401_66_dialog_content = "アルゴル博士、ここは危険です！急いで離れましょう！",
  ui_story_1019_10191401_67_dialog_content = "…",
  ui_story_1019_10191401_68_dialog_content = "アルゴル博士！！",
  ui_story_1019_10191401_69_dialog_content = "…",
  ui_story_1019_10191401_70_dialog_content = "<color=#e8d9bb>ガチャッ――！！</color>",
  ui_story_1019_10191401_71_dialog_content = "アーマースキル！",
  ui_story_1019_10191401_72_dialog_content = "なんて広さなの！？壁じゃなくて、扉だったなんて――",
  ui_story_1019_10191401_73_dialog_content = "みんな、急いで逃げて！まだデカい怪物がいるよ！！",
  ui_story_1019_10191401_74_dialog_content = "まずは入口まで下がりましょう…\n入ってきた時は何もなかったはずなのに…！",
  ui_story_1019_10191401_75_dialog_content = "…立ち上がった姿はかなりの迫力ね。",
  ui_story_1019_10191401_76_dialog_content = "アルゴルさんが入ってきてからずっと、何かいじったまま動きません！",
  ui_story_1019_10191401_77_dialog_content = "アルゴル博士！！",
  ui_story_1019_10191401_78_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1019_10191401_79_dialog_content = "暗鬼撃退はあなたたちの専売特許でしょ。",
  ui_story_1019_10191401_80_dialog_content = "暗鬼が背後に迫ってます！\nそれがどんなに重要なものだったとしても、命あってのことです！",
  ui_story_1019_10191401_81_dialog_content = "辛酸をなめ尽くした後、あなたもきっと分かるわ。",
  ui_story_1019_10191401_82_dialog_content = "髪の毛をむしり取って…",
  ui_story_1019_10191401_83_dialog_content = "何度も指を咬んでは傷つけて…",
  ui_story_1019_10191401_84_dialog_content = "どんなに苦しめられても、\nあたしはコードと夢中で向かい合ってきたの…",
  ui_story_1019_10191401_85_dialog_content = "もう一生、このプロトタイプから離れないわ！",
  ui_story_1019_10191401_86_dialog_content = "…",
  ui_story_1019_10191401_87_dialog_content = "皆さん、アルゴル博士を守りますよ。\n戦闘準備です！",
  ui_story_1019_10191502_1_dialog_content = "ケガはありませんか？",
  ui_story_1019_10191502_2_dialog_content = "かすり傷よ、何ともないわ。",
  ui_story_1019_10191502_3_dialog_content = "血が出てるよ…ゲームの中みたいに、モンスターの毒に感染して、\nモンスターになっちゃったりしないよね？",
  ui_story_1019_10191502_4_dialog_content = "…私を何だと思ってるの？\nこのくらいの傷、ブラック・アンブレラでは普通よ…",
  ui_story_1019_10191502_5_dialog_content = "ただ、忍び寄る棘の様子が普通じゃなかったわ。\n構造もエネルギー出力も大きく変化してる。",
  ui_story_1019_10191502_6_dialog_content = "同感！でも、このモンスターたちも\n結局あたしの王座の相手じゃないよ！",
  ui_story_1019_10191502_7_dialog_content = "ユリシーズは超戦士を造って、いったい何をしたかったのかしら？\nしかも、プロトタイプはまだ何かを計算しているし…",
  ui_story_1019_10191502_8_dialog_content = "「啓明の星計画」を継続していたことから、想像はつきます…\n光霊を超戦士に取って代わらせ、光霊の生存率を上げようとしていたんでしょう。",
  ui_story_1019_10191502_9_dialog_content = "問題は…超戦士はこれで全部なんでしょうか？\nラス近衛軍団の改造光霊は100人を超えていましたが…",
  ui_story_1019_10191502_10_dialog_content = "アルゴル博士に何か分かったか聞いてみよ。\nアルゴル博士なら、超戦士の発生元と数が分かるかもしれないよ。",
  ui_story_1019_10191502_11_dialog_content = "<color=#e8d9bb>カチャカチャ――</color>",
  ui_story_1019_10191502_12_dialog_content = "ブールってボタンを回せるんですね…しかも速い！",
  ui_story_1019_10191502_13_dialog_content = "そうね…",
  ui_story_1019_10191502_14_dialog_content = "ブールがなぜいつもあたしの髪の毛をひねるのか、ようやく分かったわ。",
  ui_story_1019_10191502_15_dialog_content = "ブー！",
  ui_story_1019_10191502_16_dialog_content = "アルゴル博士、ブールはどうやってプロトタイプを操作してるの？",
  ui_story_1019_10191502_17_dialog_content = "一方が博士の頭につながってて、\nもう一方の触手で指令を実行してるとか？",
  ui_story_1019_10191502_18_dialog_content = "うーん…いい発想ね。でも、残念だけど違うわ。ブールはおそらく自分の触覚と記憶に基づいて、\nあたしのこれまでの動作をマネて、コマンドを入力してるのよ。",
  ui_story_1019_10191502_19_dialog_content = "アルゴル博士、何か分かりましたか？",
  ui_story_1019_10191502_20_dialog_content = "ここの実験途中の超戦士たちは、\n前に私たちを襲った兵士で間違いありません。",
  ui_story_1019_10191502_21_dialog_content = "超戦士は、これで全部なのでしょうか？",
  ui_story_1019_10191502_22_dialog_content = "あたしに言わせれば、封印されてないプロトタイプがあっただけで、\nもうはるかに想像を超えてるわ…",
  ui_story_1019_10191502_23_dialog_content = "超戦士のことは、システムにログインしなきゃ分からないかもね。",
  ui_story_1019_10191502_24_dialog_content = "ブールが計算している間に、倉庫を一通りよく調べて、\n他の実験台か、もしくは倉庫がないか調べたいわ。",
  ui_story_1019_10191502_25_dialog_content = "「ガーディアン1号」のコアが盗まれたことも、\nカナン城の防御に穴が開いたこともすべて、ユリシーズが関係してるわ。",
  ui_story_1019_10191502_26_dialog_content = "今すべきことは、今も動いてるこのプロトタイプに他のリスクがないかってことと…\nユリシーズがこれを使って何をしようとしてたかを調べることよ。",
  ui_story_1019_10191502_27_dialog_content = "今すぐにでも、ユリシーズを取材したいわね…",
  ui_story_1019_10191502_28_dialog_content = "安全上の理由で処分ねぇ…アハハハ…",
  ui_story_1019_10191502_29_dialog_content = "何を笑ってるんですか…？",
  ui_story_1019_10191502_30_dialog_content = "ガーディアンの研究権限が開放された後、\nあたしはユリシーズの学生として、このマシンを見に来たことがあるの。",
  ui_story_1019_10191502_31_dialog_content = "その時のユリシーズは人工知能には興味ないみたいで、適当にあしらわれたわ。\nその後、プロトタイプは安全上の理由で処分されたって聞いたから、てっきりあきらめたのかと思ってたの。",
  ui_story_1019_10191502_32_dialog_content = "それなのに、これでいったい何をしようとしてたのかしらね？",
  ui_story_1019_10191502_33_dialog_content = "研究に進展がない場合、問題はたいてい設備や時代じゃない…",
  ui_story_1019_10191502_34_dialog_content = "問題はいつも人にあるの。",
  ui_story_1019_10191502_35_dialog_content = "ブブブブブ――！！",
  ui_story_1019_10191502_36_dialog_content = "<color=#e8d9bb>ウィーン――</color>",
  ui_story_1019_10191502_37_dialog_content = "よく…やったわ…",
  ui_story_1019_10191502_38_dialog_content = "ようやく「ガーディアン」の全貌が見られるのね…",
  ui_story_1019_10191502_39_dialog_content = "リングと4本のカーソル…これって…どういう意味ですか？",
  ui_story_1019_10191502_40_dialog_content = "ログインパスワードが必要みたいね。プロトタイプを守るためなのか、\nユリシーズが警戒して設定したのか分からないけど…",
  ui_story_1019_10191502_41_dialog_content = "ログインすると…何が分かるんですか？",
  ui_story_1019_10191502_42_dialog_content = "ログインすれば、分かるわよ。",
  ui_story_1019_10191502_43_dialog_content = "ブール、コマンド、ジャンプ！",
  ui_story_1019_10191502_44_dialog_content = "ブー！",
  ui_story_1020_10200101_1_dialog_content = "<size=45>ブブブブー！！</size>",
  ui_story_1020_10200101_2_dialog_content = "パスワードの解読はブールに任せておけば、大丈夫なんですか？",
  ui_story_1020_10200101_3_dialog_content = "それにしても…ブールの作業速度は驚異的ですね。\n近くで見ると、なおさらです。",
  ui_story_1020_10200101_4_dialog_content = "あたしの推測があたったみたいね…",
  ui_story_1020_10200101_5_dialog_content = "ユリシーズの研究室に入った時も、ユリシーズ本人に対しても\nブールが異常な反応をしてたけど――",
  ui_story_1020_10200101_6_dialog_content = "きっとユリシーズとプロトタイプは、\n何か関係があるって警告してたのよ。",
  ui_story_1020_10200101_7_dialog_content = "でも…ブールはどうやってそれを知ったんでしょう？",
  ui_story_1020_10200101_8_dialog_content = "僕も不思議に思ってたんです。\nブールは初めてプロトタイプをいじるわけじゃなさそうですし…",
  ui_story_1020_10200101_9_dialog_content = "それを説明するには、ブールと出会った時の話から始めないといけないわ。",
  ui_story_1020_10200101_10_dialog_content = "プロトタイプが封印される前、あたしは他の研究員たちと一緒に、\nこの倉庫で「ガーディアン」のシステムをサンドボックスにコピーしたの。",
  ui_story_1020_10200101_11_dialog_content = "漏れがあっちゃいけないと思って、毎日遅くまで作業してたわ。\nもちろん、できるだけ長くプロトタイプに触れていたいって個人的な理由もあったけどね。",
  ui_story_1020_10200101_12_dialog_content = "マシンの出す「ウィーン」って音は、まるで子守唄みたいだった。\nでも、時どき聞こえてくる「ブブブ」って音が耳障りだった…",
  ui_story_1020_10200101_13_dialog_content = "コピーが完了して、複製を持って研究室に戻ると、\n触手だか、ケーブルだか分からないものが首に巻き付いていて…",
  ui_story_1020_10200101_14_dialog_content = "それからというもの、プロトタイプの一部が\n博士に寄生するようになったんだよ。",
  ui_story_1020_10200101_15_dialog_content = "何だか王座や忍び寄る棘に似てるわね。",
  ui_story_1020_10200101_16_dialog_content = "そうかもね。でも、あなたたちにはきっと想像もできないわ。\nブールと出会ったばかりの頃、あたしがどんな思いをしたか！",
  ui_story_1020_10200101_17_dialog_content = "この子ったら、不眠不休で部屋にあった家具を全部解体しちゃったのよ。",
  ui_story_1020_10200101_18_dialog_content = "話をしようとすると、毎回散々に叩かれて…",
  ui_story_1020_10200101_19_dialog_content = "鎖骨やら、肋骨やら、肩甲骨やら…\nブールの絡みついた箇所は、ことごとく骨折したわ…",
  ui_story_1020_10200101_20_dialog_content = "それはもう、完全に暴力事件じゃ…",
  ui_story_1020_10200101_21_dialog_content = "あたしが一生懸命トレーニングしてる理由が分かったでしょ？",
  ui_story_1020_10200101_22_dialog_content = "つまり…研究室に置いてあったトレーニングマシンは全部、\n身体を鍛えるためなんですか？",
  ui_story_1020_10200101_23_dialog_content = "それだけじゃないわ。毎日各身体指標を測って、定期的に健康診断を受けてるの…\nあたし、啓光医療センターの常連なんだから。",
  ui_story_1020_10200101_24_dialog_content = "ブールを研究するために、そこまでするんだ…",
  ui_story_1020_10200101_25_dialog_content = "さすが、研究に一生をささげたね。素晴らしいわ…",
  ui_story_1020_10200101_26_dialog_content = "というより、ブールに悪意がないのは分かってたし、\n友達って互いに適応期間が必要でしょ。",
  ui_story_1020_10200101_27_dialog_content = "本格的に研究し始めてから、\nブールがただの寄生獣じゃないってことも分かってきたしね。",
  ui_story_1020_10200101_28_dialog_content = "ブールはあたしの研究に興味を示すだけじゃなく、\nいろいろとアドバイスもしてくれるの。",
  ui_story_1020_10200101_29_dialog_content = "…プロトタイプの一部だったブールが今のブールになるまで、\nいったいどんな経験をしてきたんでしょうか…",
  ui_story_1020_10200101_30_dialog_content = "とにかく、ブールの存在に慣れた頃には、\nあたしはもう丸半年、研究室に閉じこもってたわ。",
  ui_story_1020_10200101_31_dialog_content = "あの半年間は今まで生きてきた中で、\n一番充実した、一番のびのびとしていた時間だったわ。",
  ui_story_1020_10200101_32_dialog_content = "「ロボット」、「一匹狼」、「友だちがいない」なんてあだ名やレッテルを\n貼られたのもその頃だけど、まったく気にならなかった。",
  ui_story_1020_10200101_33_dialog_content = "理解できない相手に説明したってムダだもの。\nロボットと一緒にいるほうが、自由で気楽だしね。",
  ui_story_1020_10200101_34_dialog_content = "ハハ、もちろん1号にも…だいぶ苦労させられたけど。",
  ui_story_1020_10200101_35_dialog_content = "最初は1号、その後はブールですか。\nアルゴルさんってやっぱり――",
  ui_story_1020_10200101_36_dialog_content = "変人かしら？",
  ui_story_1020_10200101_37_dialog_content = "ヘンなところもあるけど、すごく面白い人だと思います！",
  ui_story_1020_10200101_38_dialog_content = "いいのよ。変人だってことくらい自分でも分かってるから。",
  ui_story_1020_10200101_39_dialog_content = "よく分かるわぁ。私も同じようなレッテルを貼られてるから。",
  ui_story_1020_10200101_40_dialog_content = "レッテルだって悪いもんじゃないよ～。\nあたしも「ゲーム王」とか「ダンジョンキラー」とか「2周目ブラックホール」とか言われてるけど…",
  ui_story_1020_10200101_41_dialog_content = "もっとたくさん欲しいくらいだもんね！",
  ui_story_1020_10200101_42_dialog_content = "あなたのあだ名は特別でしょ。\nところで、ボーヤにはどんなあだ名があるの？",
  ui_story_1020_10200101_43_dialog_content = "僕は…特にないかな…？",
  ui_story_1020_10200101_44_dialog_content = "あ、あたし知ってるよ！「負け犬」だよね！",
  ui_story_1020_10200101_45_dialog_content = "あ…そうだった…",
  ui_story_1020_10200101_46_dialog_content = "ずっと嫌がっていたあだ名なのに、\n今日はずいぶんと素直に受け入れるんですね。",
  ui_story_1020_10200101_47_dialog_content = "いえ、ただすぐには他のあだ名が思い浮かばないだけです…",
  ui_story_1020_10200101_48_dialog_content = "それはそうと、アルゴル博士。\nこれから、どうすればいいですか？",
  ui_story_1020_10200101_49_dialog_content = "何もしなくていいわ。",
  ui_story_1020_10200101_50_dialog_content = "マシンの音を聞くかぎり、\nブールはプロトタイプ内の更新データをチェックしてるみたい。",
  ui_story_1020_10200101_51_dialog_content = "その後、ブール自身の計算ロジックを調整して、パスワードを解読するはずよ。\nただ、少し時間がかかると思うわ。",
  ui_story_1020_10200101_52_dialog_content = "でも、ログインさえできれば、\nユリシーズが何をしようとしてたのか分かるだけじゃなく…",
  ui_story_1020_10200101_53_dialog_content = "「ガーディアン」内の防御コードを使って新しいコアを構築して、\n啓光の防御の穴を埋められるはずよ。",
  ui_story_1020_10200101_54_dialog_content = "それなら安心しました！",
  ui_story_1020_10200101_55_dialog_content = "それにしても…今もプロトタイプがまだ動くなんて驚きね。\nしかも、空の末裔くんが来た後に見つかるなんて。",
  ui_story_1020_10200101_56_dialog_content = "やっぱり研究も、閉じこもってばかりじゃダメなのね。",
  ui_story_1020_10200101_57_dialog_content = "ハハ、本当に…予想外だわ。アハハハ！",
  ui_story_1020_10200101_58_dialog_content = "あの…聞いてもいいですか…？ユリシーズ教授が本当にここで、\nこっそり超戦士を造っていたなら…",
  ui_story_1020_10200101_59_dialog_content = "医療センターで兵士の治療をしている時、\n申し訳ない気持ちにはならなかったんでしょうか？",
  ui_story_1020_10200101_60_dialog_content = "プロトタイプの中に、本当にユリシーズと暗鬼の関係を示すものがあったなら、\n「申し訳ない」気持ちなんて、そもそも存在しないわ。",
  ui_story_1020_10200101_61_dialog_content = "悪事を働くことに理由はいらないの。\nそういうことをするヤツは悪事の過程に喜びを見出すものよ。",
  ui_story_1020_10200201_1_dialog_content = "あなたの目の前に、啓光に10年の安寧をもたらした人物と、\nこの先10年の未来を担う人物がいるでしょう？",
  ui_story_1020_10200201_2_dialog_content = "私の研究がもたらす利益を知りたいというのなら、\nそれが私の答えです。",
  ui_story_1020_10200201_3_dialog_content = "啓光に10年の安寧をもたらした人物…\nレインハトのことを言っているの？",
  ui_story_1020_10200201_4_dialog_content = "啓光歴代大元帥の中には、もともと強大な力を持っていた者もいましたが、\n多くの者は後天的に力を与えられたにすぎません。",
  ui_story_1020_10200201_5_dialog_content = "レインハト以前の大元帥の多くは、自身の力を制御できず…",
  ui_story_1020_10200201_6_dialog_content = "その後半生において、自ら、あるいは他人によって、\n命を終える末路をたどりました。",
  ui_story_1020_10200201_7_dialog_content = "私が生まれる以前に、類似した研究がすでに長期にわたって実施されてきました。",
  ui_story_1020_10200201_8_dialog_content = "それは啓光が決して公にしたくない過去であり、\n科学者の恥辱でもあるでしょう。",
  ui_story_1020_10200201_9_dialog_content = "この私が乳幼児期から改造を施す構想と\n<color=#FFB400>80号シェルター</color>での検証選別を提唱しなければ…",
  ui_story_1020_10200201_10_dialog_content = "レインハトのように勇敢で智略にも長けた大元帥は\n誕生しなかったでしょうね。",
  ui_story_1020_10200201_11_dialog_content = "…",
  ui_story_1020_10200201_12_dialog_content = "「人造陽光計画」に至って、啓光の科学研究はついに軌道に乗り、\nさらには、きわめて優れた成果を出せるようになりました。",
  ui_story_1020_10200201_13_dialog_content = "もちろん、その過程で犠牲者も出しました。\nしかし、我々の安寧と進歩のために、犠牲は必要なのです。",
  ui_story_1020_10200201_14_dialog_content = "つまり…<color=#FFB400>80号シェルター</color>の悲劇は「誤情報」が原因ではないと認めるのですね…？",
  ui_story_1020_10200201_15_dialog_content = "ええ、その通りです。\n一般人に研究や実験の詳細を知らせる必要はありませんからね。",
  ui_story_1020_10200201_16_dialog_content = "政治の安定を保つには、強硬な統治が必要です。\n動乱期の民にとって、倫理道徳が受ける衝撃は致命的打撃になります。",
  ui_story_1020_10200201_17_dialog_content = "倫理道徳が受ける衝撃ですと…？",
  ui_story_1020_10200201_18_dialog_content = "私の仲間が命と引き換えに得た情報も…\nあなたにとっては、ただの実験手順にすぎなかったというわけですね。",
  ui_story_1020_10200201_19_dialog_content = "<color=#e8d9bb>ドーン――！！！</color>",
  ui_story_1020_10200201_20_dialog_content = "啓光シェルター80号偵察任務の目標は何だ？",
  ui_story_1020_10200201_21_dialog_content = "成功あるのみ！！",
  ui_story_1020_10200201_22_dialog_content = "グアアッ！",
  ui_story_1020_10200201_23_dialog_content = "班長！<color=#FFB400>ピート</color>から託された情報です…\nピートは…偵察班として立派に務めを果たしました！",
  ui_story_1020_10200201_24_dialog_content = "ピート…よし！よくやったぞ！",
  ui_story_1020_10200201_25_dialog_content = "出口はすぐこの先だ！アナトリア、一気に駆け抜けるぞ！",
  ui_story_1020_10200201_26_dialog_content = "了解です！",
  ui_story_1020_10200201_27_dialog_content = "<color=#e8d9bb>ドッカーン――！！！</color>",
  ui_story_1020_10200201_28_dialog_content = "班長！",
  ui_story_1020_10200201_29_dialog_content = "情報をアナトリアに渡せ！\nお前は…それからお前たちも、全員私と共に殿を務めろ！",
  ui_story_1020_10200201_30_dialog_content = "はい！！！",
  ui_story_1020_10200201_31_dialog_content = "班長！私も――",
  ui_story_1020_10200201_32_dialog_content = "偵察隊とはどうあるべきか、忘れたか？",
  ui_story_1020_10200201_33_dialog_content = "…",
  ui_story_1020_10200201_34_dialog_content = "仲間から情報を託された時は、\n何があろうと、ただちに情報を携え、生きて帰還せよ！",
  ui_story_1020_10200201_35_dialog_content = "もちろん覚えています、班長！\nですが、私は…班長と仲間と共に生きて帰還します！",
  ui_story_1020_10200201_36_dialog_content = "グアアッ！",
  ui_story_1020_10200201_37_dialog_content = "グアア――",
  ui_story_1020_10200201_38_dialog_content = "聞こえなかったのか！？職務に私情を持ち込んではならん！\n偵察は情報がすべてだ！暗鬼も犠牲もつきものだ！",
  ui_story_1020_10200201_39_dialog_content = "さっさと行け！",
  ui_story_1020_10200201_40_dialog_content = "グア――！！！",
  ui_story_1020_10200201_41_dialog_content = "班長！！",
  ui_story_1020_10200201_42_dialog_content = "…行け！",
  ui_story_1020_10200201_43_dialog_content = "…情報を必ず持ち帰れ、アナトリア…",
  ui_story_1020_10200201_44_dialog_content = "…お前の背中は私が守る。お前は…もっと速く走れるはずだ…",
  ui_story_1020_10200201_45_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_1020_10200201_46_dialog_content = "仲間たちの命も、仲間たちが生きる意味も…\nあなたが全部消し去ったのです！",
  ui_story_1020_10200201_47_dialog_content = "80号シェルターでの検証によって、啓明の光レインハトが誕生したのですよ。\n彼らの犠牲は啓光に10年の安寧をもたらしました。",
  ui_story_1020_10200201_48_dialog_content = "だから、君や私のような者が今まで生きてこられたのです。\nそれは価値がないと？",
  ui_story_1020_10200201_49_dialog_content = "…啓光のために力を尽くす大元帥を、私は心から尊敬しています。",
  ui_story_1020_10200201_50_dialog_content = "ですが、私が今まで生きてこられたのは、\n仲間が犠牲になった真相を明らかにするという信念があったからです。",
  ui_story_1020_10200201_51_dialog_content = "私はずっと近くにいたのに、\nなぜもっと早くに気づかなかったのでしょう…",
  ui_story_1020_10200201_52_dialog_content = "大元帥、私が情報官になったのは、自分のもたらす情報で、\nより多くの兵士を戦場から生還させたかったからです。",
  ui_story_1020_10200201_53_dialog_content = "ですが、私の情報のせいで、あなたは暗鬼の包囲攻撃に遭い、\n大切な仲間を失ってしまいました。",
  ui_story_1020_10200201_54_dialog_content = "誤った情報が悲惨な結果を招いてしまいました。\n情報官として、喜んで罰を受け入れます。ただ、その前に…",
  ui_story_1020_10200201_55_dialog_content = "ユリシーズ博士の処刑を命じてください！",
  ui_story_1020_10200201_56_dialog_content = "アナトリア…",
  ui_story_1020_10200201_57_dialog_content = "私はいくらでも待ちます！\n必ずや真の原因を突き止めると、犠牲になった仲間たちに――",
  ui_story_1020_10200201_58_dialog_content = "命を賭けて誓ったのです！",
  ui_story_1020_10200201_59_dialog_content = "<color=#e8d9bb>ドン――！</color>",
  ui_story_1020_10200201_60_dialog_content = "レインハト…",
  ui_story_1020_10200201_61_dialog_content = "ベリサリア！",
  ui_story_1020_10200201_62_dialog_content = "ユリシーズがどんな立場であろうと、\n同胞たちがこのような冷酷無残な組織の中で生きることは私が許さん！",
  ui_story_1020_10200201_63_dialog_content = "今すぐ審判を下せ！さもなければ…私が審判を下そう！",
  ui_story_1020_10200201_64_dialog_content = "刀は抜かれました。",
  ui_story_1020_10200201_65_dialog_content = "雷の威力！",
  ui_story_1020_10200201_66_dialog_content = "待って――",
  ui_story_1020_10200201_67_dialog_content = "全員、武器を下ろしなさい！",
  ui_story_1020_10200201_68_dialog_content = "…",
  ui_story_1020_10200201_69_dialog_content = "私は誰も断罪する気はないわ。\nあなたたちは全員、啓光が生き残るためにそれぞれの選択をしたにすぎないのだから。",
  ui_story_1020_10200201_70_dialog_content = "だからこそ、私はユリシーズの実験を支持してきたし、\n軍が委員会を通さず、勝手に兵や軍隊を動かすのも支持してきたの。",
  ui_story_1020_10200201_71_dialog_content = "でも、対局が終われば、コマはしかるべき場所に戻らないといけないわ。",
  ui_story_1020_10200201_72_dialog_content = "対局？コマ？お前は自分を何様だと思っている！？",
  ui_story_1020_10200201_73_dialog_content = "今や啓光内部では、同胞を害する毒が幅を利かせ、\n外では、暗鬼がカナン城に迫っている…",
  ui_story_1020_10200201_74_dialog_content = "お前はそれでも、何事もないかのように座っていられるのか！？",
  ui_story_1020_10200201_75_dialog_content = "啓光が暗鬼討伐と危機探索の先頭に立つことは二度とないわ。",
  ui_story_1020_10200201_76_dialog_content = "彼らが動かないのなら、啓光も動かない。",
  ui_story_1020_10200201_77_dialog_content = "何を言っている？",
  ui_story_1020_10200201_78_dialog_content = "危機が訪れる前に、啓光が率先して攻撃に出ることも、\n自身の腕をきり落とすこともない。たとえ、それが毒を持つ腕であってもね。",
  ui_story_1020_10200201_79_dialog_content = "分かったかしら！？",
  ui_story_1020_10200201_80_dialog_content = "ハハハ…鉄仮面先生、光霊同士がけん制し合うゲームなら、\nもう十分楽しんだでしょう？",
  ui_story_1020_10200201_81_dialog_content = "こんなことを続けていれば、どんな結末を迎えるか、\n私が教えて差し上げましょうか？",
  ui_story_1020_10200201_82_dialog_content = "いずれ犠牲になるとしても、啓光は白夜城の先遣隊にはならないわ！",
  ui_story_1020_10200201_83_dialog_content = "まったく…大きな声を出さないでほしいわ。",
  ui_story_1020_10200201_84_dialog_content = "ユリシーズ、話を続けなさい。\n啓光のこの先10年の未来とは、何を指しているのかしら？",
  ui_story_1020_10200201_X84_dialog_content = "戦場で検証したい次期啓光大元帥候補者でもいるのかしら？",
  ui_story_1020_10200201_85_dialog_content = "アハハ…",
  ui_story_1020_10200201_86_dialog_content = "「啓明の星計画」の成果は1人ではありませんよ。\n啓光のこの先10年の未来とは、ショーンのことです。",
  ui_story_1020_10200201_87_dialog_content = "…",
  ui_story_1020_10200201_88_dialog_content = "…僕？",
  ui_story_1020_10200301_1_dialog_content = "<color=#e8d9bb>ピピピピピ…</color>",
  ui_story_1020_10200301_2_dialog_content = "解析にずいぶん時間がかかってますね…",
  ui_story_1020_10200301_3_dialog_content = "…",
  ui_story_1020_10200301_4_dialog_content = "あの…聞こえてますか…？",
  ui_story_1020_10200301_5_dialog_content = "ピピッ――アルゴルは待機状態に入った可能性があります。\n1号がアルゴルを起こします。",
  ui_story_1020_10200301_6_dialog_content = "1号？そんなにたくさん持って…どうしたの？",
  ui_story_1020_10200301_7_dialog_content = "これはアルゴルがよく使っているコンピューター設備です。\nコア構築の速度向上に役立つと思い、持ってきました。",
  ui_story_1020_10200301_8_dialog_content = "<color=#e8d9bb>ガッチャーン</color>",
  ui_story_1020_10200301_9_dialog_content = "あ！この音は、あたしの宝物たちね！\n1号、急いで一緒に組み立てましょ！",
  ui_story_1020_10200301_10_dialog_content = "（本当に「起きた」…）",
  ui_story_1020_10200301_11_dialog_content = "今日のアルゴルは稼働速度が遅くなっています。",
  ui_story_1020_10200301_12_dialog_content = "このマシンとあたしの間には、\n何千何万年の年代差があるのよ…",
  ui_story_1020_10200301_13_dialog_content = "そういえば、これってあなたの祖先よね。",
  ui_story_1020_10200301_14_dialog_content = "祖先には見えません。",
  ui_story_1020_10200301_15_dialog_content = "それにしても…ブールの解析スピードが想定以上に遅いわ。",
  ui_story_1020_10200301_16_dialog_content = "何度もアップデートしたから、ブールったら、\nコードの「言語」規則を忘れちゃったのかしら…",
  ui_story_1020_10200301_17_dialog_content = "自分のプロトタイプを相手に、今もまだ計算を続けてるなんて、\nいったいどれだけの情報を処理しなきゃならないのよ…",
  ui_story_1020_10200301_18_dialog_content = "アルゴルがとても焦っています。",
  ui_story_1020_10200301_19_dialog_content = "焦るに決まってるでしょ！もおおおおっ！",
  ui_story_1020_10200301_20_dialog_content = "ブールとも、あなたや空の末裔くんみたいに意思疎通ができればいいのに！\nほんの少しでも、データを見ることができれば…",
  ui_story_1020_10200301_21_dialog_content = "ここには同時に使えるコンピューターがあるっていうのに、\nあたしは何もできないわ！",
  ui_story_1020_10200301_22_dialog_content = "言葉では交流できませんでしたけど、\nブールの持ってる「情報」なら前に感知できました。",
  ui_story_1020_10200301_23_dialog_content = "ブールを感知すれば、何か使えそうな情報が見つかるかもしれません。",
  ui_story_1020_10200301_24_dialog_content = "ありがとう。でも、ブールに叩かれちゃうから、\n気持ちだけ受け取っておくわ。",
  ui_story_1020_10200301_25_dialog_content = "…でも、ブールは学習能力が高いんですよね？\n一度感知したことで、今は僕を信用してくれてるかもしれません。",
  ui_story_1020_10200301_26_dialog_content = "PlayerNameさんは賢いですね。",
  ui_story_1020_10200301_27_dialog_content = "一理あるわね…いずれにせよ、今は何もできないし、\nいっそのこと殴られた方がいいかもしれないわね。",
  ui_story_1020_10200301_28_dialog_content = "やっぱり、殴られるんですか！？",
  ui_story_1020_10200301_29_dialog_content = "あの…ブール、お願い！",
  ui_story_1020_10200301_30_option_content = "精神感知――",
  ui_story_1020_10200301_31_dialog_content = "…",
  ui_story_1020_10200301_32_dialog_content = "もう終わり…？ブールが拒否したってこと？",
  ui_story_1020_10200301_33_dialog_content = "いえ…「情報」の処理スピードが速すぎるんです！",
  ui_story_1020_10200301_34_dialog_content = "…何か使えそうな情報はあった？",
  ui_story_1020_10200301_35_dialog_content = "使えそうな情報は…",
  ui_story_1020_10200301_36_option_content = "線が見えました",
  ui_story_1020_10200301_37_dialog_content = "たくさんの線が…上から落ちてきました。",
  ui_story_1020_10200301_38_dialog_content = "でも、線じゃないかもしれません…",
  ui_story_1020_10200301_39_dialog_content = "何の情報にもなってないじゃない！",
  ui_story_1020_10200301_40_dialog_content = "ああ！あたしがプロトタイプと接続したいわ！",
  ui_story_1020_10200301_41_option_content = "数字がたくさん見えました",
  ui_story_1020_10200301_42_dialog_content = "数字が高速で動いてました！",
  ui_story_1020_10200301_43_dialog_content = "数字？「0」と「1」だけが並んでたの？何桁くらい？\n決まった順序で並んでたのかしら？",
  ui_story_1020_10200301_44_dialog_content = "どの数字もあったような…",
  ui_story_1020_10200301_45_dialog_content = "桁数と順序は…よく分かりませんでした…",
  ui_story_1020_10200301_46_option_content = "何が何だか分かりませんでした",
  ui_story_1020_10200301_47_dialog_content = "すごく速くて、よく分からないうちに終わってしまいました。",
  ui_story_1020_10200301_48_dialog_content = "もう一度試させてください！",
  ui_story_1020_10200301_49_dialog_content = "さっきので状況は分かったので、今度はちゃんと見てきます。",
  ui_story_1020_10200301_50_dialog_content = "無理しないで。あたしでも、ブールがいったい何なのか分かってないんだから。",
  ui_story_1020_10200301_51_dialog_content = "身体に異変を感じたら、すぐにやめるのよ。",
  ui_story_1020_10200301_52_dialog_content = "はい、分かりました。",
  ui_story_1020_10200301_53_dialog_content = "実は、回帰の塔が上昇してから、僕の感知能力が上がったみたいなんです。",
  ui_story_1020_10200301_54_dialog_content = "塔の上からアストラ大陸の隅々まで瞬時にとらえることができて、\nそれも自分の目ではなく、空間の目を借りることができるんです…",
  ui_story_1020_10200301_55_dialog_content = "何だか抽象的だけど、要するに塔から世界を見た時の方法なら、\nブールの「情報」が何か分かるってことね？",
  ui_story_1020_10200301_56_dialog_content = "空間の目を借りれば…",
  ui_story_1020_10200301_57_dialog_content = "とにかく、やってみます！",
  ui_story_1020_10200301_58_option_content = "精神感知――",
  ui_story_1020_10200301_59_dialog_content = "（は、速い！）",
  ui_story_1020_10200301_60_dialog_content = "（でも…何とかして付いていかなきゃ…）",
  ui_story_1020_10200301_61_dialog_content = "（うわあああ――目がチカチカする――）",
  ui_story_1020_10200301_62_dialog_content = "（違う違う！自分の目で見ちゃダメだ、空間の目を使わなきゃ…）",
  ui_story_1020_10200301_63_dialog_content = "（まずは1列に対象を絞って…）",
  ui_story_1020_10200301_64_option_content = "感知展延――",
  ui_story_1020_10200301_65_dialog_content = "（…）",
  ui_story_1020_10200301_66_dialog_content = "（間違いない。数字の列だ…）",
  ui_story_1020_10200301_67_dialog_content = "（01105745630112…2311111…0010112231…）",
  ui_story_1020_10200301_68_dialog_content = "（アルゴルさんにこの数字を伝えれば…パスワードを解読できるよね？）",
  ui_story_1020_10200301_69_dialog_content = "（でも…覚えられない…）",
  ui_story_1020_10200301_70_dialog_content = "見えました！数字の列が雨のように並んでました！",
  ui_story_1020_10200301_71_dialog_content = "わあ！パスワードは書いてあった？",
  ui_story_1020_10200301_72_dialog_content = "そんな都合のいいことあるはずないでしょ…\nただ、パスワードはその中に隠されていると思います。",
  ui_story_1020_10200301_73_dialog_content = "空の末裔くん、感知しながら、数字を読み上げることはできる？",
  ui_story_1020_10200301_74_dialog_content = "十分なデータさえあれば、別のコンピューターを使って、\n同時に解読作業を進められるかもしれないわ。",
  ui_story_1020_10200301_75_dialog_content = "今は線じゃなく、数字としてとらえるだけで精一杯で…\n感知中に読み上げるのは、たぶん無理です。",
  ui_story_1020_10200301_76_dialog_content = "それに…",
  ui_story_1020_10200301_77_dialog_content = "それに、どうしたの？",
  ui_story_1020_10200301_78_dialog_content = "あんなにたくさんの数字を記録するのは、\nアルゴルさんでも無理だと思います…",
  ui_story_1020_10200301_79_dialog_content = "あたしを信じられる？",
  ui_story_1020_10200301_80_dialog_content = "もちろん信じます。\nでも…どうして、そんなこと聞くんですか？",
  ui_story_1020_10200301_81_dialog_content = "ある仮説が浮かんだの…",
  ui_story_1020_10200301_82_dialog_content = "人格が芽生えたその瞬間から、巨像という高度に「自動化された工場」にも\n創造性と適応能力が生まれた。",
  ui_story_1020_10200301_83_dialog_content = "その創造性と適応能力こそ、あたしたちの脳のみが持ち得る能力よ。",
  ui_story_1020_10200301_84_dialog_content = "あたしたちは本来複雑な状況や問題を柔軟に処理する能力をもっている。\nでも、その創造性と適応能力がかえって…",
  ui_story_1020_10200301_85_dialog_content = "機械的な計算の「邪魔」をして、作業効率を大幅に下げてるのよ。",
  ui_story_1020_10200301_86_dialog_content = "あたしを信じて。\n一時的に創造性と適応能力を捨ててみてちょうだい。",
  ui_story_1020_10200301_87_dialog_content = "創造性と適応能力を捨てる…？どうやって…？",
  ui_story_1020_10200301_88_dialog_content = "簡単に言うと、考えることをやめて、\n脳を機械みたいに動かすの。",
  ui_story_1020_10200301_89_dialog_content = "それは…試したことはありません…",
  ui_story_1020_10200301_90_dialog_content = "キツい仕事をしなきゃいけない時によく使ってる方法よ。\nあたしも一緒にその数字を出来る限り全部記録していくわ。",
  ui_story_1020_10200301_91_dialog_content = "情報量に惑わされず、ただ過程に集中するの。\n十分な量の情報が意識を通過すれば、情報は自然と頭の中に残っていくものよ。",
  ui_story_1020_10200301_92_dialog_content = "あたしを信じてちょうだい。\nその状態になれば、時間なんて無限になるわ。",
  ui_story_1020_10200301_93_dialog_content = "過程に集中する…",
  ui_story_1020_10200301_94_dialog_content = "地面に落ちれば、目が覚めるはず…",
  ui_story_1020_10200301_95_dialog_content = "…あれ？まだ地面につかない…？",
  ui_story_1020_10200301_96_dialog_content = "落ちると分かって落ちるのって、時間が長く感じるんだな…",
  ui_story_1020_10200301_97_dialog_content = "何となく分かった気がします。",
  ui_story_1020_10200301_98_dialog_content = "何か思い出したの？",
  ui_story_1020_10200301_99_dialog_content = "正確には、空から落ちるのとは違いますけど…\nとにかく、どうすればいいのか分かりました。",
  ui_story_1020_10200301_100_option_content = "感知――もっと深く――",
  ui_story_1020_10200301_101_dialog_content = "わぁ…PlayerNameの目がものすごい速さで動いてるよ…",
  ui_story_1020_10200301_102_dialog_content = "不思議だわ。今、PlayerNameの頭の中で\n何が起こってるのか、見てみたいわね。",
  ui_story_1020_10200301_103_dialog_content = "今から空の末裔くんはあたしの助手よ。\nこれが成功したら、服をオーダーメイドしてあげるの！",
  ui_story_1020_10200301_104_dialog_content = "アルゴルは空の末裔さんと友だちになりたがっています。",
  ui_story_1020_10200301_105_dialog_content = "今来てるような服じゃなくて、1号と同じ機械の筐体をね！",
  ui_story_1020_10200301_106_dialog_content = "ピピッ――",
  ui_story_1020_10200301_107_dialog_content = "11101100…",
  ui_story_1020_10200301_108_dialog_content = "来た、来た！",
  ui_story_1020_10200301_109_dialog_content = "二進法！？",
  ui_story_1020_10200301_110_dialog_content = "010221111、022211110101…",
  ui_story_1020_10200301_111_dialog_content = "…じゃないみたいね。",
  ui_story_1020_10200301_112_dialog_content = "1号、間違いや漏れがないように、急いで録音してちょうだい。",
  ui_story_1020_10200301_113_dialog_content = "ピピッ、1号了解しました。",
  ui_story_1020_10200301_114_dialog_content = "ガルー、ビビアン、ミジャード！近くのコンピューターで一緒に作業して！\n集中するのよ、光力でサポートするわ！",
  ui_story_1020_10200301_115_dialog_content = "了解！",
  ui_story_1020_10200301_116_dialog_content = "0101157567565500101…100150115332234560101…",
  ui_story_1020_10200301_117_dialog_content = "（5列…6列…7、8、9…）",
  ui_story_1020_10200301_118_dialog_content = "（いったいどこまで続くんだろう…）",
  ui_story_1020_10200301_119_dialog_content = "（あれ…？目がチカチカしてきた？何かが…光ってるみたい…）",
  ui_story_1020_10200301_120_dialog_content = "（ダメだ…また考え始めちゃった…）",
  ui_story_1020_10200301_121_dialog_content = "（ううっ――この速度に、付いていくのは…かなり、きつい！）",
  ui_story_1020_10200401_1_dialog_content = "ユリシーズ先生、いったい…何を言ってるんですか？",
  ui_story_1020_10200401_2_dialog_content = "君とインゲル、アクセリアの3人は皆、\n「啓明の星計画」の産物です。",
  ui_story_1020_10200401_3_dialog_content = "…",
  ui_story_1020_10200401_4_dialog_content = "…",
  ui_story_1020_10200401_5_dialog_content = "「啓明の星計画」の産物って…インゲルみたいに頭が良くて、\nアクセリアみたいに暗鬼を殴り飛ばせる強い光霊のことじゃ…",
  ui_story_1020_10200401_6_dialog_content = "でも、僕にはそんな力…",
  ui_story_1020_10200401_7_dialog_content = "ショーン、君は自分で思っているよりもずっと強いのです。",
  ui_story_1020_10200401_8_dialog_content = "「強い」…そんなふうに言われるのは初めてです…",
  ui_story_1020_10200401_9_dialog_content = "アクセリア、食らえ！はぁっ――！",
  ui_story_1020_10200401_10_dialog_content = "うわああああ！",
  ui_story_1020_10200401_11_dialog_content = "…",
  ui_story_1020_10200401_12_dialog_content = "アクセリアと拳をぶつけただけでも痛いのに…\n「強い」なんて…",
  ui_story_1020_10200401_13_dialog_content = "新兵だと？ただのガキじゃないか！\nトワイライトシティはガキの来る所じゃない！",
  ui_story_1020_10200401_14_dialog_content = "…",
  ui_story_1020_10200401_15_dialog_content = "お前、カナン城でいったい何をやらかしたんだ？\nこの程度の暗鬼も倒せないくせに、何しにきた？",
  ui_story_1020_10200401_16_dialog_content = "…",
  ui_story_1020_10200401_17_dialog_content = "私にこんなことを言う資格はありませんが、\nどんなに苦しい環境でも、自分磨きを怠ってはいけませんよ。",
  ui_story_1020_10200401_18_dialog_content = "はい、長官…",
  ui_story_1020_10200401_19_dialog_content = "能力が高いと、背負う責任も大きくなるんだ。\n俺はお前より「強い」から、仕方ないよな。ハハハ！",
  ui_story_1020_10200401_20_dialog_content = "でも…ここは僕の担当エリアだよ。",
  ui_story_1020_10200401_21_dialog_content = "構わないさ。班長には俺から言っておくさ。\nこのエリアの暗鬼は「強すぎる」ってな。",
  ui_story_1020_10200401_22_dialog_content = "…",
  ui_story_1020_10200401_23_dialog_content = "ショーン、もっと速く走れ！もっと速くだ！",
  ui_story_1020_10200401_24_dialog_content = "…は、はい！",
  ui_story_1020_10200401_25_dialog_content = "ユリシーズ先生は、僕がインゲルやアクセリアと同じように強いって言ったけど…",
  ui_story_1020_10200401_26_dialog_content = "でも、どうして僕の両手は…",
  ui_story_1020_10200401_27_dialog_content = "タコだらけなんですか…？",
  ui_story_1020_10200401_28_dialog_content = "訓練でタコができるなんて…\nどう考えても、何の取り得もない証拠でしょう？",
  ui_story_1020_10200401_29_dialog_content = "手だけじゃありません…\nそこら中に、訓練で出来た傷があるんです…",
  ui_story_1020_10200401_30_dialog_content = "僕はまだ、訓練が足りないんでしょうか？",
  ui_story_1020_10200401_31_dialog_content = "ショーン…",
  ui_story_1020_10200401_32_dialog_content = "確かに、当初君をトワイライトシティへ送ったのは、\n実験初期において、君は「失敗作」だったためです。",
  ui_story_1020_10200401_33_dialog_content = "しかし、実験の初期段階では、\nさまざまな判断ミスが起こるのもごく自然なことです。",
  ui_story_1020_10200401_34_dialog_content = "「失敗作」ですか…",
  ui_story_1020_10200401_35_dialog_content = "僕はやっぱり…失敗作だったから、\nトワイライトシティに配属されたんですね…ハハ…",
  ui_story_1020_10200401_36_dialog_content = "ショーン、ユリシーズの言うことなど戯言だ。\nお前は何も悪くない。",
  ui_story_1020_10200401_37_dialog_content = "ユリシーズからすれば、私たちは全員「失敗作」よ。",
  ui_story_1020_10200401_38_dialog_content = "大元帥様…ありがとうございます。\nでも、自分で分かってるんです…僕は他のみんなとは違うって…",
  ui_story_1020_10200401_39_dialog_content = "当初トワイライトシティに配属された「失敗作」が\nなぜ啓光の未来になるのか、ご説明いただきたいですね。",
  ui_story_1020_10200401_40_dialog_content = "ユリシーズ、重点を話してちょうだい。",
  ui_story_1020_10200401_41_dialog_content = "さすが「鉄仮面」先生ですね…",
  ui_story_1020_10200401_42_dialog_content = "確かに我々はショーンの研究をあきらめました。\nしかし、暗面に近いトワイライトシティに配属になった後、彼の身体に変化が起こったのです。",
  ui_story_1020_10200401_43_dialog_content = "検証を続けた結果、ショーンの光力術は遺伝的欠陥の制限を受けているのではなく、\n暗力を吸収できることが分かったのです。",
  ui_story_1020_10200401_44_dialog_content = "吸収した暗力が光力に変換されることはありませんが、\n暗鬼と戦う中で、彼は強大な身体的バリアを獲得しました。",
  ui_story_1020_10200401_45_dialog_content = "事実、以前ペピータと共に暗面の偵察に向かった者たちにも、\nよく似た特徴が発現しています。",
  ui_story_1020_10200401_46_dialog_content = "学術的なことをお話しする必要はないでしょう。\nいずれにせよ、暗鬼に勝とうとするならば、彼らこそ光霊の希望なのです！",
  ui_story_1020_10200401_47_dialog_content = "身体強化実験の計画はすでに作成してあります。\nいくらもしないうちに、計画の産物を暗面に送り込むことができますよ。",
  ui_story_1020_10200401_48_dialog_content = "ユリシーズ、何バカなことを言っている！？\n啓光がお前の研究継続を許すと思っているのか？",
  ui_story_1020_10200401_49_dialog_content = "ショーン！君に話さなければならないことがあります――",
  ui_story_1020_10200401_50_dialog_content = "記録に書かれている生い立ちでは、啓光の軍人が暗鬼の魔の手から君を救い、\n孤児院に送ったことになっています。",
  ui_story_1020_10200401_51_dialog_content = "しかし、君を暗鬼の元へ連れて行き、命を落とすことを望んだのは、\n他ならぬ君の両親なのです！",
  ui_story_1020_10200401_52_dialog_content = "君の両親は身体的欠陥に苦しめられてきました。\nゆえに、我が子は早くにその苦しみから解放されてほしいと願ったのです。",
  ui_story_1020_10200401_53_dialog_content = "しかし、「啓明の星計画」のおかげで、\n君は生き延び、これ以上苦しむ必要もなくなりました。",
  ui_story_1020_10200401_54_dialog_content = "私がその身体を改造し、第二の命を与えたのです。\n誰もが認める「強者」になりたければ――",
  ui_story_1020_10200401_55_dialog_content = "ユリシーズ教授…何をなさるつもりですか？",
  ui_story_1020_10200401_56_dialog_content = "暗面の奥深くへと進み、暗鬼討伐の希望となりなさい。\n約束してください――",
  ui_story_1020_10200401_57_dialog_content = "トワイライトシティの一介の兵士で終わることなく、遺伝子の優位性を存分に生かして、\n日蝕内部に潜入する光霊の英雄となるのです！",
  ui_story_1020_10200401_58_dialog_content = "そうなれば…暗鬼をせん滅し、暗闇の奥に隠れている悪魔を\nその目で確かめることができるでしょう…",
  ui_story_1020_10200401_59_dialog_content = "ユリシーズ、止まれ！",
  ui_story_1020_10200401_60_dialog_content = "ショーンに近づかないでください！",
  ui_story_1020_10200401_61_dialog_content = "多くの命を犠牲にすることも惜しまず、実験を続けてきたあなたが、\n今はショーンに自分が命を救った恩人だと言う…",
  ui_story_1020_10200401_62_dialog_content = "そんな冷酷な身勝手な考えには…反吐が出ます！",
  ui_story_1020_10200401_63_dialog_content = "今や誰一人として、ショーンの命を放棄するこも、奪うことも、\n都合よく操ることもできません！",
  ui_story_1020_10200401_64_dialog_content = "誰もショーンの命を放棄するこも、奪うことも、\n都合よく操ることもできません！",
  ui_story_1020_10200401_65_dialog_content = "…インゲル、アクセリア。\nそんなにがっちり僕を囲むことないよ…ハハハ…",
  ui_story_1020_10200401_66_dialog_content = "ユリシーズ先生は、父さんと母さんはあえて僕を連れて\n暗鬼の中に突進したって言ってたけど…",
  ui_story_1020_10200401_67_dialog_content = "そんなの夢だって、ずっと自分に言い聞かせてきたんだ…",
  ui_story_1020_10200401_68_dialog_content = "あんなハッキリした情景…夢のはずないのに…ハハ…",
  ui_story_1020_10200401_69_dialog_content = "それでも「父さんと母さんは僕を救うために勇敢に戦って犠牲になった」って、\n僕はずっと自分をごまかしてきたんだ。",
  ui_story_1020_10200401_70_dialog_content = "バカみたいだけど…そうでもしなきゃ、\n前を向いて生きられない。そうでしょ？",
  ui_story_1020_10200401_71_dialog_content = "ショーン、当時何が起こったかはもう重要ではありません。",
  ui_story_1020_10200401_72_dialog_content = "あなたは今トワイライトシティの…\nいいえ、啓光の優秀な戦士なのですから！",
  ui_story_1020_10200401_73_dialog_content = "今のショーンはアクセリアと同じように、\nたくさんの暗鬼を倒せる啓光の軍人です。",
  ui_story_1020_10200401_74_dialog_content = "勝手なことを言うと、アクセリアが思うに、\nショーンは戦士になる必要も、英雄になる必要もありません…",
  ui_story_1020_10200401_75_dialog_content = "ショーンであればいいと思います。",
  ui_story_1020_10200401_76_dialog_content = "アハハハ！太古の戦争での失敗を繰り返そうというのですか？",
  ui_story_1020_10200401_77_dialog_content = "世界はあなたたちが思うほど単純ではありませんよ…\n私は日蝕の力を目の当たりにしました。光霊の活路はただ一つです。",
  ui_story_1020_10200401_78_dialog_content = "お前は同胞の命を犠牲にして研究をしてきたのだぞ！\n啓光を破滅に導き、光霊を破滅させる行為だ！",
  ui_story_1020_10200401_79_dialog_content = "ただの戦争兵器に…犠牲と破滅を語る資格があると思っているのですか？",
  ui_story_1020_10200401_80_dialog_content = "ノラが実にうらやましい…若くして、光力と暗力の秘める不思議な力に気づき、\n自身の理想を貫いてきた…",
  ui_story_1020_10200401_81_dialog_content = "一方、あなた方は感情の力のみを信じ、\n大して重要でもない犠牲ばかりを強調しています…",
  ui_story_1020_10200401_82_dialog_content = "そうした感情の縛りが、光霊が前進する足かせとなっているのです…",
  ui_story_1020_10200401_83_dialog_content = "あなた方の愚かさこそ、多くの犠牲を出す元凶だというのに…",
  ui_story_1020_10200401_84_dialog_content = "それでは光霊は死を恐れ…死を待つだけです…",
  ui_story_1020_10200401_85_dialog_content = "しかし、私は感情の奴隷になどなりません…",
  ui_story_1020_10200401_86_dialog_content = "絶対に！",
  ui_story_1020_10200401_87_dialog_content = "私は何とも思わなくなるでしょう…",
  ui_story_1020_10200401_88_dialog_content = "毎分毎秒、光霊が死んでいくことを！\n数十人死のうが、何千何万の光霊が死のうが何とも思いません！",
  ui_story_1020_10200401_89_dialog_content = "目の前にいるのは、いずれ腐乱し、白骨と化す者たち…それを踏み越えて…\n心身共に強大な光霊を造り出すのです！",
  ui_story_1020_10200401_90_dialog_content = "「進化」という言葉を…聞いたことがありますね？\n光霊は進化しなければなりません…",
  ui_story_1020_10200401_91_dialog_content = "毎分、毎秒、進化し続ける…",
  ui_story_1020_10200401_92_dialog_content = "それでこそ、我々はこの終末の世界で生き残ることができるのです。\n目を大きく見開き、強大な身体と共に…",
  ui_story_1020_10200401_93_dialog_content = "宙へと…飛んでいける…",
  ui_story_1020_10200401_94_dialog_content = "ユリシーズ長官、大丈夫ですか…？",
  ui_story_1020_10200401_95_dialog_content = "進化…何と美しい言葉でしょう…",
  ui_story_1020_10200401_96_dialog_content = "毎分、毎秒、進化し続ける…",
  ui_story_1020_10200401_97_dialog_content = "ユリシーズ長官！",
  ui_story_1020_10200401_98_dialog_content = "おかしくなったの？",
  ui_story_1020_10200401_99_dialog_content = "こうして直接目にするまで…信じられなかったが…",
  ui_story_1020_10200401_100_dialog_content = "いったいどうしたというの？",
  ui_story_1020_10200401_101_dialog_content = "これがチャンドラを証人として立てることを主張した理由だ。",
  ui_story_1020_10200401_102_dialog_content = "大元帥様、私はここにおります。",
  ui_story_1020_10200401_103_dialog_content = "ユリシーズの状況を皆に話してやれ。",
  ui_story_1020_10200401_104_dialog_content = "承知しました、大元帥様。ユリシーズ博士はカウンセリング中、\n時々今のように力のない目で、一つの方向を見つめていることがありました…",
  ui_story_1020_10200401_105_dialog_content = "ですが、しばらくすると、何事もなかったように元に戻るんです。",
  ui_story_1020_10200401_106_dialog_content = "…",
  ui_story_1020_10200401_107_dialog_content = "証人チャンドラ、続けなさい…",
  ui_story_1020_10200401_108_dialog_content = "ユリシーズ博士は10年前からカウンセリングを受けています。\nこちらが博士のカルテです。",
  ui_story_1020_10200401_109_dialog_content = "当時、私は参加していませんでしたが、カルテによれば、\n各勢力が暗鬼の大軍に襲われた時期に、博士のカウンセリングが始まっています。",
  ui_story_1020_10200401_110_dialog_content = "また、軍事演習前の数か月間、\nユリシーズ博士の受診回数が増えています。",
  ui_story_1020_10200401_111_dialog_content = "その後、ノラがX号研究院に潜入し、\nファントムがカナン城に侵入して、「ガーディアン1号」のコアを盗みました。",
  ui_story_1020_10200401_112_dialog_content = "2つの重大事件の時期とユリシーズ博士の変化が連動しています。\n日蝕と特別なつながりを持っている可能性が疑われます。",
  ui_story_1020_10200401_113_dialog_content = "…",
  ui_story_1020_10200401_114_dialog_content = "私が気になったのは、ユリシーズがカウンセリングの中で述べた奇妙な情景だ…",
  ui_story_1020_10200401_115_dialog_content = "氷柱は水が凝固したものではありません。\n巨大な石が上昇しているのです…",
  ui_story_1020_10200401_116_dialog_content = "駆動源を使い果たし、絶え間なく分裂を繰り返す…\nしかし、唯一の目が上空を見つめ続けている…",
  ui_story_1020_10200401_117_dialog_content = "上昇する氷柱、駆動源…上空を見つめる目…",
  ui_story_1020_10200401_118_dialog_content = "どれもアストラ大陸にはない情景だ。\nカナン城を一歩も出たことのない男がなぜ、それを知っている？",
  ui_story_1020_10200401_119_dialog_content = "ベリサリア、お前も疑わずにはいられんだろう？\nこんなことが偶然であるはずがない！",
  ui_story_1020_10200401_120_dialog_content = "なぜ、そんなに自信を持って言えるのかしら？",
  ui_story_1020_10200401_121_dialog_content = "証拠は？",
  ui_story_1020_10200401_122_dialog_content = "かつて暗鬼だった…暗面の奥深くにいたヘリオスの、\n回想記録にそう書いてある！",
  ui_story_1020_10200401_123_dialog_content = "委員会はヘリオスの意識が回復していないことを理由に、\n私の嫌疑を晴らすことを先延ばしにしている。",
  ui_story_1020_10200401_124_dialog_content = "だが、ユリシーズに対する告発と一致した今、\nどう説明するつもりだ？",
  ui_story_1020_10200401_125_dialog_content = "あれのことを思い出したんだけど、あなたたちはどう？",
  ui_story_1020_10200401_126_dialog_content = "あのファントムのことですか？",
  ui_story_1020_10200401_127_dialog_content = "そういうことが言いたかったのね…",
  ui_story_1020_10200401_128_dialog_content = "…",
  ui_story_1020_10200401_129_dialog_content = "私を尋問したところで、時間の無駄だ。",
  ui_story_1020_10200401_130_dialog_content = "あの御方が降臨する時、リングを持たぬ者は地をはいずり、\n恐怖と弱小さのあまり、死にゆく定めなのだ。",
  ui_story_1020_10200401_131_dialog_content = "リングとは何のことですか！？",
  ui_story_1020_10200401_132_dialog_content = "身の程知らずめ、リングを欲するとは！\nお前たちはただの畜生、盗人、寄生虫にすぎぬ！",
  ui_story_1020_10200401_133_dialog_content = "600年前、あの浮空島は私のものだったのだ！",
  ui_story_1020_10200401_134_dialog_content = "浮空島…白夜城のことを言っているの？",
  ui_story_1020_10200401_135_dialog_content = "あの御方が降臨した暁には、私にも再び栄光が訪れる。\n我が殿堂へと戻り、あの御方の懐へと帰るのだ！",
  ui_story_1020_10200401_136_dialog_content = "あなたたちは、なぜ光霊と敵対するのかしら？",
  ui_story_1020_10200401_137_dialog_content = "もちろん、光霊が際限なき搾取を働くからだ！\nあの御方の創造物を奪い、自分のものとした！",
  ui_story_1020_10200401_138_dialog_content = "だが、最後には必ず全てを取り戻す！",
  ui_story_1020_10200401_139_dialog_content = "キキキキキッ――！！！",
  ui_story_1020_10200401_140_dialog_content = "…",
  ui_story_1020_10200401_141_dialog_content = "すべての始まりは、啓光建立当初にすでに存在した、\nあの太古の機械だったのね…",
  ui_story_1020_10200401_142_dialog_content = "これが啓光の宿命なの？フフッ…ハハハ…",
  ui_story_1020_10200401_143_dialog_content = "あのマシンはどこにあるの？",
  ui_story_1020_10200401_144_dialog_content = "倉庫です。あなたの見込んだ天才が今、そこにいますよ。",
  ui_story_1020_10200401_145_dialog_content = "進化、何と美しい言葉でしょう。",
  ui_story_1020_10200401_146_dialog_content = "毎分、毎秒、進化し続ける…",
  ui_story_1020_10200401_147_dialog_content = "…",
  ui_story_1020_10200501_1_dialog_content = "…これだけ？",
  ui_story_1020_10200501_2_dialog_content = "ちゃんと照合したから、漏れはないよ。\n何か足りない？",
  ui_story_1020_10200501_3_dialog_content = "想像していたより少ないわ。この数字の列は循環してる…\nあるいは、一種の有限の文字の組み合わせかもしれないわね。",
  ui_story_1020_10200501_4_dialog_content = "それに、最初のコンピューター言語は「ガーディアン」システムを元にしてるんだから、\nどんなに変化しようと、規則は同じはず。",
  ui_story_1020_10200501_5_dialog_content = "あたしのプログラムを使えば、\nこのデータの組み合わせのロジックを解析できるはずよ。",
  ui_story_1020_10200501_6_dialog_content = "あと少しで、この数台のコンピューターとブールと一緒に\n「ガーディアン」の完全なシステムにログインできるわ！",
  ui_story_1020_10200501_7_dialog_content = "有限の文字の組み合わせなら、PlayerNameはどうしてまだ感知してるんでしょうか？\nPlayerNameは…大丈夫ですよね？",
  ui_story_1020_10200501_8_dialog_content = "そうだね。PlayerNameの髪の毛が風になびいてるみたいになってるよ…\n何かに似てるんだけど、思い出せないな。",
  ui_story_1020_10200501_9_dialog_content = "あと少し…あと少しで…",
  ui_story_1020_10200501_10_dialog_content = "ブーブー！",
  ui_story_1020_10200501_11_dialog_content = "ありがとう！",
  ui_story_1020_10200501_12_dialog_content = "あとは、順序に従って入力すれば…",
  ui_story_1020_10200501_13_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10200501_14_dialog_content = "…間違ってた？",
  ui_story_1020_10200501_15_dialog_content = "思い出した！ブールだ！あたしの負け犬の逆立った髪の毛、\nブールの触手にそっくりだよ！",
  ui_story_1020_10200501_16_dialog_content = "てことは、PlayerNameの頭の中も、ブールみたいに、\n膨大な計算能力を持つマシンになってるってことだね？",
  ui_story_1020_10200501_17_dialog_content = "アルゴル博士、PlayerNameは危険な状態じゃないでしょうか？",
  ui_story_1020_10200501_18_dialog_content = "…どんなに強力な感知能力を持っていようと、\nPlayerNameはコンピューターじゃないわ…",
  ui_story_1020_10200501_19_dialog_content = "起こしてあげ…",
  ui_story_1020_10200501_20_dialog_content = "85…X…32875…X…",
  ui_story_1020_10200501_21_dialog_content = "え！？",
  ui_story_1020_10200501_22_dialog_content = "今、何と言ったの？",
  ui_story_1020_10200501_23_dialog_content = "…「X」って言ったかしら！？",
  ui_story_1020_10200501_24_dialog_content = "数字だけじゃなかったってこと…？",
  ui_story_1020_10200501_25_dialog_content = "3292…X…4782…X…2212323293845…",
  ui_story_1020_10200501_26_dialog_content = "感電したみたいに、顔が真っ赤だよ！",
  ui_story_1020_10200501_27_dialog_content = "…12983289…X…",
  ui_story_1020_10200501_28_dialog_content = "50227833…X…",
  ui_story_1020_10200501_29_dialog_content = "この子ったら、ブールの計算速度に追いついたの…？\nこのままじゃ危険だわ…",
  ui_story_1020_10200501_30_dialog_content = "…でも、今やめさせたら、情報の取得は難しくなる…",
  ui_story_1020_10200501_31_dialog_content = "そうだわ！あたしのリストバンドを2分間、\n空の末裔くんにはめるわ。",
  ui_story_1020_10200501_32_dialog_content = "…そうすると、どうなるんですか？",
  ui_story_1020_10200501_33_dialog_content = "2分は脳細胞が高速稼働できる限界よ。\nこのリストバンドは、はめてる者の身体の状況を測定できる。",
  ui_story_1020_10200501_34_dialog_content = "情報量が身体的負荷を超えた時、\nリストバンドが警告してくれるわ。",
  ui_story_1020_10200501_35_dialog_content = "それまでに、ガルー、1号。もう一度記録するのを手伝ってちょうだい。\n2分間で、できる限り多くの有用な情報を収集するわよ！",
  ui_story_1020_10200501_36_dialog_content = "ほんの一部でも構わないわ。これが今あたしたちが得られる\n唯一のプロトタイプの深層データかもしれないんだから！",
  ui_story_1020_10200501_37_dialog_content = "任せて！",
  ui_story_1020_10200501_38_dialog_content = "1号、分かりました。",
  ui_story_1020_10200501_39_dialog_content = "ビビアンはタイムキーパーをお願い。\n2分経ったら、すぐに終了するわ。",
  ui_story_1020_10200501_40_dialog_content = "はい。",
  ui_story_1020_10200501_41_dialog_content = "ミジャード、2分経過する前にリストバンドのアラームが鳴ったら、\n空の末裔くんをここから連れ出してちょうだい。",
  ui_story_1020_10200501_42_dialog_content = "任せて！",
  ui_story_1020_10200501_43_dialog_content = "862033934…X…",
  ui_story_1020_10200501_44_dialog_content = "385782493666…X…",
  ui_story_1020_10200501_45_dialog_content = "ピピピピッ…",
  ui_story_1020_10200501_46_dialog_content = "236758423423…X…",
  ui_story_1020_10200501_47_dialog_content = "（「X」？）",
  ui_story_1020_10200501_48_dialog_content = "（チカチカしてる文字は「X」…？見間違いじゃないよね？）",
  ui_story_1020_10200501_49_dialog_content = "（うっ…どのくらい経ったのかな…？）",
  ui_story_1020_10200501_50_dialog_content = "（最初の時ほど、頭も痛くなくなった）",
  ui_story_1020_10200501_51_dialog_content = "（それにしても、「X」って、どういう意味だろう…）",
  ui_story_1020_10200501_52_dialog_content = "（ああっ…また、スピードが上がった…）",
  ui_story_1020_10200502_1_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200502_2_dialog_content = "ちょうど2分経ちました。",
  ui_story_1020_10200502_3_dialog_content = "すばらしいわ！",
  ui_story_1020_10200502_4_dialog_content = "ブブブー！ブブッ、ブブ――",
  ui_story_1020_10200502_5_dialog_content = "よし、よし…落ち着いて。",
  ui_story_1020_10200502_6_dialog_content = "それじゃ次は、この数台のマシンで手分けしながらデータ解析しましょ。\n今度こそうまく行くわ。",
  ui_story_1020_10200502_7_dialog_content = "ブー！",
  ui_story_1020_10200502_8_dialog_content = "うわあっ――",
  ui_story_1020_10200502_9_dialog_content = "PlayerName、大丈夫ですか？",
  ui_story_1020_10200502_10_dialog_content = "…うわっ！血圧、高いね！しかもSaO2が…\nあたしたちのこと、ちゃんと見えてる？",
  ui_story_1020_10200502_11_dialog_content = "み、見えてるよ…",
  ui_story_1020_10200502_12_dialog_content = "まずは座って。動いちゃダメよ。\n指の動きを目で追ってみてちょうだい。",
  ui_story_1020_10200502_13_dialog_content = "左…右…",
  ui_story_1020_10200502_14_dialog_content = "今、気分はどう？",
  ui_story_1020_10200502_15_dialog_content = "何だか、頭が…ふぅ…クラクラして…\n全身の力が抜けたみたい…",
  ui_story_1020_10200502_16_dialog_content = "吐き気はある？目がチカチカしたりしてない？",
  ui_story_1020_10200502_17_dialog_content = "それは、大丈夫そうです…",
  ui_story_1020_10200502_18_dialog_content = "これを飲んで。",
  ui_story_1020_10200502_19_dialog_content = "これは…何ですか？",
  ui_story_1020_10200502_20_dialog_content = "脳は高速稼働すると、酸欠状態になるの。\nその手のことに関しては、あたしも専門家みたいなものだから。",
  ui_story_1020_10200502_21_dialog_content = "それにしても…本当に驚きだわ。\nあなたの感知能力がここまで強大だったなんて…本当に助かったわ！",
  ui_story_1020_10200502_22_dialog_content = "自分でも驚いてます…最初は数字がどんどん流れていってしまって…\nちゃんと見ようとして、1列の数字だけをじいっと見てた時は辛かったです。",
  ui_story_1020_10200502_23_dialog_content = "その後、一つの列にこだわらず、アルゴルさんの言ったように、\n考えることをやめたら…逆に数字が自然と「入って」きたんです…",
  ui_story_1020_10200502_24_dialog_content = "それでも途中で、考え事をしてしまったんですけど…",
  ui_story_1020_10200502_25_dialog_content = "まるで、そんな僕に気づいたかのように、\n数字の流れが加速し出して…",
  ui_story_1020_10200502_26_dialog_content = "急…緩…思考…その後再度加速…完全な学習反射弓ね…",
  ui_story_1020_10200502_27_dialog_content = "でも、ちょっと待って！考えるのをやめたんでしょ？\nそれなのにちゃんと見えたの？あなた、どんな頭してるのよ…！？",
  ui_story_1020_10200502_28_dialog_content = "空の末裔くんって…まさか、本当に人工知能だったりするの？",
  ui_story_1020_10200502_29_dialog_content = "ど、どうして、そんなふうに思うんですか…？",
  ui_story_1020_10200502_30_dialog_content = "あ、そうだ…数字の中に「X」って文字が出てきましたけど、\nあれは何ですか？",
  ui_story_1020_10200502_31_dialog_content = "僕…読み間違えてませんよね？",
  ui_story_1020_10200502_32_dialog_content = "間違ってないわ…",
  ui_story_1020_10200502_33_dialog_content = "ただ…こういう肝心要の情報はブールに任せるしかないわね。\nブールも同じ太古の機械だから…",
  ui_story_1020_10200502_34_dialog_content = "アルゴルにも、なす術がありません。",
  ui_story_1020_10200502_35_dialog_content = "…まったく…太古の科学技術に後れを取るなんて…",
  ui_story_1020_10200502_36_dialog_content = "このマシンを発明したヤツは、\nいったいどんな頭してたのよ！？もしかして神様？ハハハハ！",
  ui_story_1020_10200502_37_dialog_content = "…",
  ui_story_1020_10200502_38_dialog_content = "啓光はまだ二進法を基礎にしたコンピューターで止まってるのよ。\nしかも、600年以上もね！",
  ui_story_1020_10200502_39_dialog_content = "物理的材料の恒常性にしろ、数学的な演算ロジックにしろ…\n二進法こそコンピューターの最適解だと思ってた。",
  ui_story_1020_10200502_40_dialog_content = "でも、このマシンは…最基層の言語に「0」と「1」以外の数字が出てきたわ！\nこんなの、三進法でも、四進法でもない…",
  ui_story_1020_10200502_41_dialog_content = "それに…「X」ですって？まったく理解不可能だわ…\n「X」よ、「X」！「X」って何よ！？",
  ui_story_1020_10200502_42_dialog_content = "あたしをあざ笑ってるのかしら！？アハハハ！",
  ui_story_1020_10200502_43_dialog_content = "いったいどうやったの？\nこの中で、どれだけ複雑なロジックの処理が行われてるの？",
  ui_story_1020_10200502_44_dialog_content = "太古の時代、いったい何があったの？",
  ui_story_1020_10200502_45_dialog_content = "なぜ、科学技術はすべて失われて、\n空の末裔と暗鬼と光霊だけが生き残ったの？",
  ui_story_1020_10200502_46_dialog_content = "ああ…！忘れるところだったわ…光の神もいたわね！\nそれから、真理の主も…まさか、教典の中に答えがあるとか！？",
  ui_story_1020_10200502_47_dialog_content = "フフ…アハハハハ…",
  ui_story_1020_10200502_48_dialog_content = "急にどうしたのかしら…？何だか、怖いわ…",
  ui_story_1020_10200502_49_dialog_content = "アルゴルは自分が役立たずであることに気づきました。",
  ui_story_1020_10200502_50_dialog_content = "あり得ないわ！冗談も程々にして…\n自分で言っておきながら、笑えてきちゃったわ…",
  ui_story_1020_10200502_51_dialog_content = "アハハハ…！",
  ui_story_1020_10200502_52_dialog_content = "1号、邪神だろうと、悪魔だろうと構わないわ！",
  ui_story_1020_10200502_53_dialog_content = "誰が先だとか後だとか、そんなことはどうでもいいの！\n疑問に思ったことをとうの昔に死んだヤツに任せるなんて、バカらしいったらないわ！",
  ui_story_1020_10200502_54_dialog_content = "今は謎を解けなくても、あたしはこれからも\n「ガーディアン」システムの研究と開発を続けるわよ！",
  ui_story_1020_10200502_55_dialog_content = "分かった！？",
  ui_story_1020_10200502_56_dialog_content = "1号、分かりました。色々な意味で分かりました。",
  ui_story_1020_10200502_57_dialog_content = "ブーブー！",
  ui_story_1020_10200502_58_dialog_content = "いいわよ、ブール！任せたわ！",
  ui_story_1020_10200502_59_dialog_content = "…ブブ…",
  ui_story_1020_10200502_60_dialog_content = "ついに、この時が来たんですね…",
  ui_story_1020_10200502_61_dialog_content = "BOSSステージに突入しちゃお！",
  ui_story_1020_10200502_62_dialog_content = "…",
  ui_story_1020_10200502_63_dialog_content = "これ、どういうこと？",
  ui_story_1020_10200502_64_dialog_content = "空の末裔、だね。",
  ui_story_1020_10200502_65_dialog_content = "…",
  ui_story_1020_10200502_66_dialog_content = "今、頭の中に一瞬浮かんだのは…夢？",
  ui_story_1020_10200502_67_dialog_content = "あの黒い太陽…プロトタイプと何か関係が…？",
  ui_story_1020_10200601_1_dialog_content = "夢の中で、あのリングを見たと言うんですか…？",
  ui_story_1020_10200601_2_dialog_content = "ファントムは？バイスもいましたか？",
  ui_story_1020_10200601_3_dialog_content = "はい…",
  ui_story_1020_10200601_4_dialog_content = "ユリシーズが使っていたプロトタイプは、まさか日蝕のものなんでしょうか…？\nアルゴル博士、両者は関係があると思いますか？",
  ui_story_1020_10200601_5_dialog_content = "もちろん…ハハハハ！",
  ui_story_1020_10200601_6_dialog_content = "…",
  ui_story_1020_10200601_7_dialog_content = "…なぜ、そんな顔をしてるの？",
  ui_story_1020_10200601_8_dialog_content = "これは…建立以来、啓光の存在を支えてきた太古の科学技術ですよ…",
  ui_story_1020_10200601_9_dialog_content = "もし、日蝕のものだったとしたら…危険でしょう？",
  ui_story_1020_10200601_10_dialog_content = "空の末裔、だね。",
  ui_story_1020_10200601_11_dialog_content = "（まただ…）",
  ui_story_1020_10200601_12_dialog_content = "少なくとも、見たかぎり、あたしの複製と特に違いはないわ。",
  ui_story_1020_10200601_13_dialog_content = "他に超戦士を保管している場所があったとしても、\nプロトタイプにはおそらく、情報は残ってないわ。",
  ui_story_1020_10200601_14_dialog_content = "しかし、プロトタイプの中の記号は、PlayerNameの夢と何らかの関係があるみたいですし…\n謎が解けるどころか、増えてしまいましたね…",
  ui_story_1020_10200601_15_dialog_content = "いいえ、その反対よ。\nますますハッキリしてきたわ。",
  ui_story_1020_10200601_16_dialog_content = "最初はユリシーズなんて、救いようのないただの誇大妄想癖だと思ってたけど、\nこれを見てから、見方が変わったわ。",
  ui_story_1020_10200601_17_dialog_content = "こんなにも長い間、カナン城が壊滅せずに存続してきたのは…\nユリシーズが実験を続けてきたのは…本当にただ彼が狂気に憑りつかれていたから？",
  ui_story_1020_10200601_18_dialog_content = "参謀長、ユリシーズをここに呼べるかしら？",
  ui_story_1020_10200601_19_dialog_content = "それは…おそらく委員会が承知しないと思いますが、\n大元帥様に連絡してみます…",
  ui_story_1020_10200601_20_dialog_content = "…",
  ui_story_1020_10200601_21_dialog_content = "今、このマシンを最もよく理解してるのは、ユリシーズよ。",
  ui_story_1020_10200601_22_dialog_content = "ブールがコアの構築に必要なモジュールデータを取り出せるとはいえ、\nさっきあたしたちが記録した情報は計算の補助データでしかない。",
  ui_story_1020_10200601_23_dialog_content = "プロトタイプはかつて長い間、封印されてた。\n今後、プロトタイプの研究が制限を受けないとも限らないわ。",
  ui_story_1020_10200601_24_dialog_content = "空の末裔、だね。",
  ui_story_1020_10200601_25_dialog_content = "…",
  ui_story_1020_10200601_26_dialog_content = "PlayerName？大丈夫？",
  ui_story_1020_10200601_27_dialog_content = "今…何かが一瞬見えたような気がして…",
  ui_story_1020_10200601_28_dialog_content = "何が見えたの？",
  ui_story_1020_10200601_29_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200601_30_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10200601_31_dialog_content = "ロックがかかったの！？",
  ui_story_1020_10200601_32_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200601_33_dialog_content = "ええっ？どういうこと？",
  ui_story_1020_10200601_34_dialog_content = "倉庫が揺れています…！",
  ui_story_1020_10200601_35_dialog_content = "…",
  ui_story_1020_10200601_36_dialog_content = "待って…モジュールデータは取り出せるんだから、\nロックがかかるはずないわ…",
  ui_story_1020_10200601_37_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200601_38_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200601_39_dialog_content = "さっきブールはプロトタイプの防御コードを使って、\n新しいコアを構築したんだよね？",
  ui_story_1020_10200601_40_dialog_content = "防御の穴が埋まったってことじゃないの？",
  ui_story_1020_10200601_41_dialog_content = "理論的にはそうだけど、\nいくら何でもこの揺れは大きすぎるでしょ！？",
  ui_story_1020_10200601_42_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200601_43_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200601_44_dialog_content = "つまり、この状況は…データを取り出した後、何かがあたしのコンピューターを攻撃し、\n次に防御システムを攻撃しようとしてるって考えた方がしっくりくるわ！",
  ui_story_1020_10200601_45_dialog_content = "ゲームが現実になったの？データの侵入ってこと？",
  ui_story_1020_10200601_46_dialog_content = "待って…ええっと…防御モジュールは…",
  ui_story_1020_10200601_47_dialog_content = "あなたたちは周囲の状況を調べて。\nあたしはもう一度防御モジュールを取り出してみるわ。",
  ui_story_1020_10200601_48_dialog_content = "「ガーディアン」が防御の穴を埋めるのではなく、\n瓦解させようとしているなら…",
  ui_story_1020_10200601_49_dialog_content = "シェルターが危ない…",
  ui_story_1020_10200601_50_dialog_content = "いいえ、違うわ。プロトタイプの中の、\nもしくはプロトタイプの向こう側の何かがあたしたちと争ってるのよ。",
  ui_story_1020_10200601_51_dialog_content = "…",
  ui_story_1020_10200601_52_dialog_content = "プロトタイプの中の、もしくは向こう側の何かって…誰ですか？",
  ui_story_1020_10200601_53_dialog_content = "それを知ってるのは、ユリシーズだけよ…",
  ui_story_1020_10200601_54_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10200601_55_dialog_content = "ああ、もうっ！パスがロックされたわ！",
  ui_story_1020_10200601_56_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200601_57_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1020_10200601_58_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1020_10200601_59_dialog_content = "<color=#e8d9bb>ピピピ…</color>",
  ui_story_1020_10200601_60_dialog_content = "…たくさんのメッセージが一斉に…",
  ui_story_1020_10200601_61_dialog_content = "トンネル…10号城門…アルゴル博士、状況は想像以上に深刻です！",
  ui_story_1020_10200601_62_dialog_content = "シェルターの防御施設の多くが攻撃されています！",
  ui_story_1020_10200601_63_dialog_content = "…おそらく制御装置がフリーズしたのね。\n参謀長、外はひとまず任せたわ！",
  ui_story_1020_10200601_64_dialog_content = "ブール、モジュール再起動よ！",
  ui_story_1020_10200601_65_dialog_content = "ブー！",
  ui_story_1020_10200601_66_dialog_content = "ガルー、ミジャード、実験棟へ行って制御装置を調べてください。\n特に倉庫や大型実験設備のある所を重点的にお願いします。",
  ui_story_1020_10200601_67_dialog_content = "制御装置でコントロールしていたスイッチも、\n今は手動で制御するしかありません！",
  ui_story_1020_10200601_68_dialog_content = "まずはメッセージを送ってきた人たちに状況を確認して、\nそれから大元帥様に連絡しましょう！",
  ui_story_1020_10200601_69_dialog_content = "PlayerName、あなたは感覚が鋭いので、\n何か危険を察知したら、すぐに皆に知らせてください！",
  ui_story_1020_10200601_70_dialog_content = "分かりました！",
  ui_story_1020_10200601_71_dialog_content = "（さっき一瞬見えた情景と関係があるのかな…）",
  ui_story_1020_10200601_72_dialog_content = "<color=#e8d9bb>啓光の某トンネル施工隊</color>",
  ui_story_1020_10200601_73_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200601_74_dialog_content = "シエル！シエル――！！",
  ui_story_1020_10200601_75_dialog_content = "早く出てくるんだ！",
  ui_story_1020_10200601_76_dialog_content = "え…？",
  ui_story_1020_10200601_77_dialog_content = "すごい揺れだぞ、感じないのか？\nこの先のトンネルが崩れたんだ！",
  ui_story_1020_10200601_78_dialog_content = "うーん…今はへたに動くと、かえって危険だよ…",
  ui_story_1020_10200601_79_dialog_content = "…とにかく、あたしはまずパワードスーツを起動するよ。",
  ui_story_1020_10200601_80_dialog_content = "<color=#e8d9bb>啓光医療センター</color>",
  ui_story_1020_10200601_81_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200601_82_dialog_content = "今の音は…",
  ui_story_1020_10200601_83_dialog_content = "また俺のせいで…皆に迷惑をかけたのか？",
  ui_story_1020_10200601_84_dialog_content = "…",
  ui_story_1020_10200601_85_dialog_content = "いや…違う…",
  ui_story_1020_10200601_86_dialog_content = "俺は今、ベッドに寝てるじゃないか…",
  ui_story_1020_10200601_87_dialog_content = "レインハト…俺も、啓光の役に立ちたい…",
  ui_story_1020_10200601_88_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1020_10200601_89_dialog_content = "大元帥様！やっと――！",
  ui_story_1020_10200601_90_dialog_content = "すまない。待たせてしまった。",
  ui_story_1020_10200601_91_dialog_content = "科学棟エリアのある倉庫に危険なマシンがあるのだが、\nお前たち、今どこにいるのだ？",
  ui_story_1020_10200601_92_dialog_content = "0号倉庫です。ユリシーズ博士がひそかに実験していた倉庫です！",
  ui_story_1020_10200601_93_dialog_content = "0号倉庫だと！？",
  ui_story_1020_10200601_94_dialog_content = "超戦士が保管されていただけでなく、日蝕と関係があると見られる太古のマシンもあり、\n今起こっている震動もそのマシンが原因で引き起こされたものです！",
  ui_story_1020_10200601_95_dialog_content = "まずはそこを離れろ！",
  ui_story_1020_10200601_96_dialog_content = "全員、すぐに離れるのだ！",
  ui_story_1020_10200601_97_dialog_content = "アルゴル博士…",
  ui_story_1020_10200601_98_dialog_content = "まずは制御スイッチを安定させて！防御の穴を埋めるには新しいコアが必要よ。\nでも、コアの構築には時間がかかるの！",
  ui_story_1020_10200601_99_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200601_100_dialog_content = "あ、そうだ、参謀長。\nレインハトにユリシーズを連れてくるように伝えて！",
  ui_story_1020_10200601_101_dialog_content = "<color=#e8d9bb>啓光上層部会議室</color>",
  ui_story_1020_10200601_102_dialog_content = "自動制御システムがコントロール不能に陥り、\n上層部の城門制御は機能麻痺、トンネルは崩落…",
  ui_story_1020_10200601_103_dialog_content = "これが、あなたの待ちかねていた結果なの？",
  ui_story_1020_10200601_104_dialog_content = "白夜城の動きは？",
  ui_story_1020_10200601_105_dialog_content = "何の動きもありません。",
  ui_story_1020_10200601_106_dialog_content = "…",
  ui_story_1020_10200601_107_dialog_content = "<color=#FFB400>緊急事態</color>を発令するの？",
  ui_story_1020_10200601_108_dialog_content = "まだその時ではないわ。",
  ui_story_1020_10200601_109_dialog_content = "アクセリアは…地面が揺れているように感じます。",
  ui_story_1020_10200601_110_dialog_content = "私もです…",
  ui_story_1020_10200601_111_dialog_content = "私の実験室を引き継ぐと豪語していたのに、\n何ということでしょうね？",
  ui_story_1020_10200601_112_dialog_content = "フッ…あなたたちに…何ができるというのです？",
  ui_story_1020_10200601_113_dialog_content = "お前はプロトタイプが危険であることを知っていた。\nそして何かを待っているのだな？",
  ui_story_1020_10200601_114_dialog_content = "…プロトタイプに問題が起こったの？",
  ui_story_1020_10200601_115_dialog_content = "ご自分で…歴史を読み解いてみれば、分かることです。",
  ui_story_1020_10200601_116_dialog_content = "ラス、ヒイロ。ユリシーズをしっかり見張っているのだ。\n何があっても、やつから目を離すな。",
  ui_story_1020_10200601_117_dialog_content = "先に行って状況を確認する。\nその後でユリシーズを連れてこい。",
  ui_story_1020_10200601_118_dialog_content = "承知しました。",
  ui_story_1020_10200601_119_dialog_content = "気を付けるのよ。",
  ui_story_1020_10200601_120_dialog_content = "<color=#e8d9bb>カナン城上層部</color>",
  ui_story_1020_10200601_121_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200601_122_dialog_content = "バートン軍団長！壁がはげしく揺れています。\nまるで誰かが城門をこじ開けようとしているようです！",
  ui_story_1020_10200601_123_dialog_content = "城門全部か！？",
  ui_story_1020_10200601_124_dialog_content = "いいえ、そうではありません。\n右側の破損が深刻な城門2つです。暗鬼が迫ってきています！",
  ui_story_1020_10200601_125_dialog_content = "ビビアン…あいつら、厄介なことになってんな。",
  ui_story_1020_10200601_126_dialog_content = "とにかく、城門を守れ。",
  ui_story_1020_10200601_127_dialog_content = "城門に穴が開いちまったら、大砲を突っ込んで、\nハデにお迎えしてやれ！",
  ui_story_1020_10200601_128_dialog_content = "暗鬼の吹っ飛ぶところを存分に見てやろうじゃねえか！",
  ui_story_1020_10200601_129_dialog_content = "了解しました！",
  ui_story_1020_10200601_130_dialog_content = "<color=#e8d9bb>ドカン！ゴゴゴゴ…</color>",
  ui_story_1020_10200601_131_dialog_content = "ハハハハハ！",
  ui_story_1020_10200601_132_dialog_content = "暗鬼が吹っ飛んだ！",
  ui_story_1020_10200601_133_dialog_content = "バートン軍団最強のお出ましだよ！",
  ui_story_1020_10200602_1_dialog_content = "ブブブブブ――！！",
  ui_story_1020_10200602_2_dialog_content = "…",
  ui_story_1020_10200602_3_dialog_content = "全員無事か？",
  ui_story_1020_10200602_4_dialog_content = "大元帥様！バケモノを倒してくださり、感謝いたします…",
  ui_story_1020_10200602_5_dialog_content = "すでに倒したと思っていたのですが、\nまさか、再び襲ってくるとは思いませんでした！",
  ui_story_1020_10200602_6_dialog_content = "戻ったよ！案の定、いくつかの実験室のドアのアラームが鳴ってた！",
  ui_story_1020_10200602_7_dialog_content = "ロックし直したわ。\n今は兵士たちが実験室の出入り口を守っているから大丈夫よ。",
  ui_story_1020_10200602_8_dialog_content = "ご苦労だった。",
  ui_story_1020_10200602_9_dialog_content = "PlayerName、啓光が今どれほど危険か分かっているのか？\nお前は危険に飛び込まなければ、気が済まないのか？",
  ui_story_1020_10200602_10_dialog_content = "申し訳ありません…",
  ui_story_1020_10200602_11_dialog_content = "無事ならそれでいい。それにしても、\nユリシーズがここを超戦士の製造場所にしていたとは…",
  ui_story_1020_10200602_12_dialog_content = "ビビアン、まずは状況を説明しろ。",
  ui_story_1020_10200602_13_dialog_content = "はい。まず、カナン城の防御システムに穴が開き、\n超戦士が科学棟エリアに出現、襲撃を始めました…",
  ui_story_1020_10200602_14_dialog_content = "アルゴル博士がこの場所をご存じで幸いでした。今は発見した封印されていたはずの\nプロトタイプで、防御コアの再構築を試みているところです。",
  ui_story_1020_10200602_15_dialog_content = "今は震動がおさまっているが、問題は解決したということか？",
  ui_story_1020_10200602_16_dialog_content = "ひとまず新しいパスを構築して、制御スイッチを抑えてるけど、\n次はどこに問題が起こるか分からないわ。",
  ui_story_1020_10200602_17_dialog_content = "ユリシーズは？",
  ui_story_1020_10200602_18_dialog_content = "プロトタイプの件は、やつも白状した。\nだが、まずは状況を確認してから判断しようと思ってな。",
  ui_story_1020_10200602_19_dialog_content = "ユリシーズの状態が…少々複雑でな。",
  ui_story_1020_10200602_20_dialog_content = "日蝕側は、誰が連絡役だったのかしら？\nユリシーズは何か言ってた？",
  ui_story_1020_10200602_21_dialog_content = "お前もそう考えるか。ならば、間違いないか…",
  ui_story_1020_10200602_22_dialog_content = "やつの話では、プロトタイプの中で\n「エンジニア」に関する手がかりを見つけたらしい。",
  ui_story_1020_10200602_23_dialog_content = "ユリシーズが言うには、「エンジニア」は啓光を建立した初代城主だったが、\n600年前にその痕跡が消えているという。",
  ui_story_1020_10200602_24_dialog_content = "600年以上も痕跡を消していた「エンジニア」が…\n今になってコンピューターを介し、ユリシーズとつながっている…",
  ui_story_1020_10200602_25_dialog_content = "PlayerNameみたいに、感知能力で？",
  ui_story_1020_10200602_26_dialog_content = "感知能力…？",
  ui_story_1020_10200602_27_dialog_content = "（あの一瞬浮かんだ情景は、まさか感知だったってこと…？）",
  ui_story_1020_10200602_28_dialog_content = "だけど、感知は空の末裔だけが持ってる能力なのよ…",
  ui_story_1020_10200602_29_dialog_content = "「エンジニア」が実在しているなら、理論上は高効率の回線をつなげば、\nプロトタイプを通して、ユリシーズとリアルタイムで通信することが可能よ。",
  ui_story_1020_10200602_30_dialog_content = "でも、プロトタイプにはそんなケーブルは見当たらないし、\n送受信用の装置もないわ。つまり――",
  ui_story_1020_10200602_31_dialog_content = "ピピッ――",
  ui_story_1020_10200602_32_dialog_content = "1号はアルゴルが必要としていた<color=#FFB400>コネクター</color>を持ってきました。",
  ui_story_1020_10200602_33_dialog_content = "ありがとう。",
  ui_story_1020_10200602_34_dialog_content = "たとえば…",
  ui_story_1020_10200602_35_dialog_content = "こういうケーブルがあれば、1号はあたしのコンピュータ上に現れ、\nリアルタイムで面と向かってコミュニケーションがとれるわ。",
  ui_story_1020_10200602_36_dialog_content = "こ、こんにちは。1号の顔が大きすぎる気がします…",
  ui_story_1020_10200602_37_dialog_content = "私たちが調べた時には、<color=#FFB400>ケーブル</color>の類は見つかりませんでした。\n周りは何もなくきれいで、壁にも床にも隙間のようなものは…",
  ui_story_1020_10200602_38_dialog_content = "それはおかしい。この倉庫が使われなくなった理由は、\n当時、内部に多くの古いケーブルが張り巡らされ、分離しようにも難しかったからだ。",
  ui_story_1020_10200602_39_dialog_content = "そんなことがあったの？あたしが初めてここに来た時は、\n今とほぼ同じ状態だったわよ？",
  ui_story_1020_10200602_40_dialog_content = "それ以前に、何とか処理できたということだろう。",
  ui_story_1020_10200602_41_dialog_content = "こんなに広い倉庫をよくもまあ…",
  ui_story_1020_10200602_42_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200602_43_dialog_content = "<color=#e8d9bb>バチッ――バチッ――</color>",
  ui_story_1020_10200602_44_dialog_content = "あの…アルゴル博士、ケーブルから火花が出てるみたいだけど？",
  ui_story_1020_10200602_45_dialog_content = "は？出力超過…？あり得ないわ！",
  ui_story_1020_10200602_46_dialog_content = "あらゆるデバイスが…最大出力で稼働してるってこと！？",
  ui_story_1020_10200602_47_dialog_content = "<color=#e8d9bb>バチッ――ボンッ！</color>",
  ui_story_1020_10200602_48_dialog_content = "あ…ケーブルがダメになっちゃったじゃないの！！",
  ui_story_1020_10200602_49_dialog_content = "アルゴルが怒っています。",
  ui_story_1020_10200602_50_dialog_content = "ブブブブブ――！！",
  ui_story_1020_10200602_51_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10200602_52_dialog_content = "もうっ！次から次へと！\n構築したばかりの防御モジュールがフリーズしたわ！",
  ui_story_1020_10200602_53_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200602_54_dialog_content = "<color=#e8d9bb>ウォン――</color>",
  ui_story_1020_10200602_55_dialog_content = "止まったんですか…？",
  ui_story_1020_10200602_56_dialog_content = "<color=#e8d9bb>ジージーッ――ジジッ――</color>",
  ui_story_1020_10200602_57_dialog_content = "脳！？",
  ui_story_1020_10200602_58_dialog_content = "…",
  ui_story_1020_10200602_59_dialog_content = "まさか、これが「エンジニア」なの？",
  ui_story_1020_10200602_60_dialog_content = "今一瞬見えたのが…リアルタイムの対話ですか？",
  ui_story_1020_10200602_61_dialog_content = "うーん…消えちゃったね…",
  ui_story_1020_10200602_62_dialog_content = "ブブブブブ――！！",
  ui_story_1020_10200602_63_dialog_content = "何？会話？言語を解析できるの？",
  ui_story_1020_10200602_64_dialog_content = "…ブブ…",
  ui_story_1020_10200602_65_dialog_content = "「エンジニア」は何て？",
  ui_story_1020_10200602_66_dialog_content = "…ブブ…",
  ui_story_1020_10200602_67_dialog_content = "「久しぶりだな」",
  ui_story_1020_10200602_68_dialog_content = "…ブブ…",
  ui_story_1020_10200602_69_dialog_content = "「ユリシーズ」",
  ui_story_1020_10200602_70_dialog_content = "…ブブ…",
  ui_story_1020_10200602_71_dialog_content = "「博士」",
  ui_story_1020_10200602_72_dialog_content = "…",
  ui_story_1020_10200602_73_dialog_content = "ブール！パスを変更して、もう一度モジュールを取り出して！",
  ui_story_1020_10200602_74_dialog_content = "ブー！",
  ui_story_1020_10200602_75_dialog_content = "<color=#e8d9bb>ウォン――</color>",
  ui_story_1020_10200602_76_dialog_content = "…",
  ui_story_1020_10200602_77_dialog_content = "お久ぶり…ですね…",
  ui_story_1020_10200602_78_dialog_content = "フッ…フフッ…アハハハハ…",
  ui_story_1020_10200602_79_dialog_content = "ようやく現れましたね…",
  ui_story_1020_10200602_80_dialog_content = "誰のことです？",
  ui_story_1020_10200602_81_dialog_content = "「エンジニア」です…",
  ui_story_1020_10200602_82_dialog_content = "どこにですか？",
  ui_story_1020_10200602_83_dialog_content = "アイゼン、最後の1粒を…渡してください。",
  ui_story_1020_10200602_84_dialog_content = "ユリシーズ長官…",
  ui_story_1020_10200602_85_dialog_content = "渡しなさい！",
  ui_story_1020_10200602_86_dialog_content = "<color=#e8d9bb>啓光監獄・収監室</color>",
  ui_story_1020_10200602_87_dialog_content = "『あ、あなた様なのですね…至上の主宰者様！』",
  ui_story_1020_10200602_88_dialog_content = "『忠実な僕フィジェロ、\nあなた様の降臨を謹んでお待ち申し上げておりました。』",
  ui_story_1020_10200602_89_dialog_content = "…",
  ui_story_1020_10200602_90_dialog_content = "<color=#e8d9bb>カチャッ――</color>",
  ui_story_1020_10200602_91_dialog_content = "『…』",
  ui_story_1020_10200602_92_dialog_content = "『ああ！感謝と喜びで身の震える思いでございます！\n今後あなた様の命に決して背きません！』",
  ui_story_1020_10200602_93_dialog_content = "『御恩に報いるため…』",
  ui_story_1020_10200602_94_dialog_content = "『当時失敗に終わった任務を、今度こそ命を賭けてでも、\n必ずや完遂いたします！』",
  ui_story_1020_10200701_1_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200701_2_dialog_content = "ユリシーズ、エンジニアはもう「ガーディアン1号」のコアを手に入れたでしょう？\nこれ以上何をしようとしているのかしら？",
  ui_story_1020_10200701_3_dialog_content = "このカナン城が今にも崩れようとしています。\n恐ろしくはないのですか、鉄仮面先生？",
  ui_story_1020_10200701_4_dialog_content = "すべては…啓光の根幹たるコアを日蝕に渡したのは…より多くの研究資源を手に入れ、\n自身の理想を実現するためだったということかしら？",
  ui_story_1020_10200701_5_dialog_content = "私もかつては、エンジニアがいなければ、\n今の啓光はないと信じて疑いませんでした。",
  ui_story_1020_10200701_6_dialog_content = "しかし、後に知ったのです。\n「ガーディアン1号」のコアなど、そもそも啓光の根幹ではなかったと。",
  ui_story_1020_10200701_7_dialog_content = "私こそ、啓光の根幹なのです！",
  ui_story_1020_10200701_8_dialog_content = "「ガーディアン1号」のコアを失ったくらいのことで、\nカナン城の防御システムが今のように崩壊すると思いますか？",
  ui_story_1020_10200701_9_dialog_content = "エンジニアの計画を私が教えて差し上げましょう…",
  ui_story_1020_10200701_10_dialog_content = "彼は何もかもを飲み込み、燃やし尽くし、\n強大な力で、弱小な光霊を踏みにじろうとしているのです…",
  ui_story_1020_10200701_11_dialog_content = "しかし、私はあなたたちと違い、この暗い地下の街で\n座して死を待つつもりはありません！彼に挑むのです！",
  ui_story_1020_10200701_12_dialog_content = "完全におかしくなったわ…いったい何を言っているの！？",
  ui_story_1020_10200701_13_dialog_content = "彼がどうやったか、知っていますか…？",
  ui_story_1020_10200701_14_dialog_content = "啓光を建立し、その後自身は姿を隠し、\nコアの回収と暗鬼製造の任務を愚かなファントムらに託したのですよ。",
  ui_story_1020_10200701_15_dialog_content = "そして、数百年の眠りの後、再び目を覚ましたのです。",
  ui_story_1020_10200701_16_dialog_content = "ただ、世界はすでに変わっています。\n彼もまた、私の見た資料に書かれていた彼ではありません。",
  ui_story_1020_10200701_17_dialog_content = "彼にできることを、私ができないはずがないのです。",
  ui_story_1020_10200701_18_dialog_content = "いい加減に黙りなさい！",
  ui_story_1020_10200701_19_dialog_content = "ここにいる全員が片手であんたの息の根を止められるわ。\n大人しく――",
  ui_story_1020_10200701_20_dialog_content = "何ができるといいたいの？",
  ui_story_1020_10200701_21_dialog_content = "…",
  ui_story_1020_10200701_22_dialog_content = "フッ…すべて、倉庫に準備してあります。",
  ui_story_1020_10200701_23_dialog_content = "止まりなさい！",
  ui_story_1020_10200701_24_dialog_content = "…私を止めると？",
  ui_story_1020_10200701_25_dialog_content = "ここで大人しくしていなさい。",
  ui_story_1020_10200701_26_dialog_content = "…あなたたちには…私の話が信じられないとしても、今は私だけが…",
  ui_story_1020_10200701_27_dialog_content = "もう一歩動いたら容赦しません。",
  ui_story_1020_10200701_28_dialog_content = "刀を下ろしなさい。",
  ui_story_1020_10200701_29_dialog_content = "…",
  ui_story_1020_10200701_30_dialog_content = "鉄仮面先生、私もあなたも残された時間はそう多くはありません。\nしかし啓光は…光霊は…この先もずっと存続していかねばなりません。",
  ui_story_1020_10200701_31_dialog_content = "いつかはこの日がやってくると分かっていました。\nこの世のすべての者に否定されようと、私はあきらめない！",
  ui_story_1020_10200701_32_dialog_content = "私は、私の方法であらがってみせます！",
  ui_story_1020_10200701_33_dialog_content = "あなたたちにはできなくても、私は1人でも立ち向かいます…",
  ui_story_1020_10200701_34_dialog_content = "見に行く勇気も…ありませんか？",
  ui_story_1020_10200701_35_dialog_content = "…",
  ui_story_1020_10200701_36_dialog_content = "<color=#e8d9bb>ピ――…</color>",
  ui_story_1020_10200701_37_dialog_content = "大元帥様でしょうか…？",
  ui_story_1020_10200701_38_dialog_content = "ユリシーズを連れてくるようにって…",
  ui_story_1020_10200701_39_dialog_content = "…",
  ui_story_1020_10200701_40_dialog_content = "ベリサリア、コマがなければ、対局は成り立たない。\nそうなれば、あんたもプレイヤーにはなれないわよ？",
  ui_story_1020_10200701_41_dialog_content = "何が起ころうと、レインハトならこのカナン城を守れる。\nあんたに、それができる？",
  ui_story_1020_10200701_42_dialog_content = "…",
  ui_story_1020_10200701_43_dialog_content = "ダフォディル、バレットに連絡してちょうだい。",
  ui_story_1020_10200701_44_dialog_content = "バレット博士なら、すでに控えております。",
  ui_story_1020_10200701_45_dialog_content = "決めたの？",
  ui_story_1020_10200701_46_dialog_content = "<color=#FFB400>緊急事態</color>を発令してちょうだい。",
  ui_story_1020_10200701_47_dialog_content = "元の装備を解除し、設定ルートを変更、輸送シューターを開いて、\n住民を予備のシェルターへと移動させなさい。",
  ui_story_1020_10200701_48_dialog_content = "輸送機とシューターは正常に動くし、\n住民の移動も問題ないわ。",
  ui_story_1020_10200701_49_dialog_content = "ただ、輸送シューターでの移動の安全を確保するために、\n委員会には十分な軍隊の配備をお願いしたいわね。",
  ui_story_1020_10200701_50_dialog_content = "あなたは言われたことをやっていればいいのよ。\n委員会がバックアップするわ。",
  ui_story_1020_10200701_51_dialog_content = "分かったわ。手際がいいわね。",
  ui_story_1020_10200701_52_dialog_content = "あなたたちはユリシーズを無事に倉庫に送り届けなさい。",
  ui_story_1020_10200701_53_dialog_content = "ちょっと待ちなさいよ。\n輸送機に輸送シューターって…何のことを言っているの？",
  ui_story_1020_10200701_54_dialog_content = "啓光が開発した飛行機のことよ。\nシューターは飛行機での移動用に作られた地下軌道のこと。",
  ui_story_1020_10200701_55_dialog_content = "飛行機…？",
  ui_story_1020_10200701_56_dialog_content = "列車、地上輸送車、軌道車両…啓光が持っているのは、\nそういう地面をはう交通手段だけだと思っていたのかしら？",
  ui_story_1020_10200701_57_dialog_content = "では、元の装備と想定ルートとは…何のことですか？",
  ui_story_1020_10200701_58_dialog_content = "要するに、飛行機はあの浮空島のために準備してあったのよ。\n設定ルートというのはつまり、ここと白夜城をつなぐ直通ルート。",
  ui_story_1020_10200701_59_dialog_content = "飛行機で…弾薬を運び、\n白夜城を攻撃をするつもりだったわけね！？",
  ui_story_1020_10200701_60_dialog_content = "兵器は敵の特性に応じて、選択するものでしょう？\n地上に出ようとするなら、手段を選んではいられないわ。",
  ui_story_1020_10200701_61_dialog_content = "…",
  ui_story_1020_10200701_62_dialog_content = "今、こんな形で緊急事態体制をとることになるとは\n思っていなかったけれど。",
  ui_story_1020_10200701_63_dialog_content = "少なくともこの点においては、\n私とあなたたちの利益は一致しているでしょ。",
  ui_story_1020_10200701_64_dialog_content = "ユリシーズを倉庫へ連れて行くといいわ。\n彼は今、人質のようなものね。",
  ui_story_1020_10200701_65_dialog_content = "…",
  ui_story_1020_10200701_66_dialog_content = "ハハハ…鉄仮面先生、あなたも今や不遜なゲーム好きではなくなったようですね。",
  ui_story_1020_10200701_67_dialog_content = "また…会えますね…？",
  ui_story_1020_10200701_68_dialog_content = "時と場合によるのよ。",
  ui_story_1020_10200701_69_dialog_content = "ゲームもいいけど、やるべき時はやらないとね。",
  ui_story_1020_10200701_70_dialog_content = "あなたにもそれができるのなら、また会う必要はないわ。",
  ui_story_1020_10200701_71_dialog_content = "輸送シューターを開けたというのに、\n白夜城に動きは見られませんね。",
  ui_story_1020_10200701_72_dialog_content = "ずっとこの時を待ち続けてきたというのに、\n浮空島に砲弾を放り込んでやれないなんて、残念だわ。",
  ui_story_1020_10200701_73_dialog_content = "各自仕事に戻りなさい。これからやることが山ほどあるわ。",
  ui_story_1020_10200701_74_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200701_75_dialog_content = "アクセリア、インゲル…僕たち、どうすればいいんだろう？",
  ui_story_1020_10200701_76_dialog_content = "今までと同じように行動すればいいのです。\nレインハト大元帥たちは倉庫へ向かいました。護衛しましょう。",
  ui_story_1020_10200701_77_dialog_content = "戦争兵器なのに…2人はいつでも自分が何をすべきか、\n分かってるんだね…",
  ui_story_1020_10200701_78_dialog_content = "私は物心ついた時からそうしてきました。",
  ui_story_1020_10200701_79_dialog_content = "アクセリアは最近になって、ようやく分かりました。\nショーンも必ず分かる時がきます。",
  ui_story_1020_10200701_80_dialog_content = "そんな簡単じゃないよ…僕は君たちと違って…",
  ui_story_1020_10200701_81_dialog_content = "うわぁっ――！",
  ui_story_1020_10200701_82_dialog_content = "インゲル…何するんだよ？ち、血が出ちゃったじゃないか…",
  ui_story_1020_10200701_83_dialog_content = "戦争兵器といえども、血の通った光霊です。\n違いますか？",
  ui_story_1020_10200701_84_dialog_content = "会議でのことは深く考えすぎないことです。\n何があろうと、レインハト大元帥はあなたの存在意義を否定しません。",
  ui_story_1020_10200701_85_dialog_content = "レインハト大元帥もラス大元帥も、この計画の被害者なのですよ…\nそれでも、今も自分たちの職務を果たしています。",
  ui_story_1020_10200701_86_dialog_content = "おかしなことを言うようですが…レインハト大元帥がいるおかげで、\n私は少しも恐ろしいと感じないのです。",
  ui_story_1020_10200701_87_dialog_content = "…",
  ui_story_1020_10200701_88_dialog_content = "アクセリアも、同じです…",
  ui_story_1020_10200701_89_dialog_content = "インゲル、アクセリア…",
  ui_story_1020_10200701_90_dialog_content = "さあ、行きましょう。急ぎますよ、ショーン！",
  ui_story_1020_10200701_91_dialog_content = "…うん！",
  ui_story_1020_10200701_92_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200801_1_dialog_content = "揺れが…止まった…！",
  ui_story_1020_10200801_2_dialog_content = "コアを構築できたんですか！？",
  ui_story_1020_10200801_3_dialog_content = "そんなはずないでしょ…\n計算速度が下がってるの、まだいくらも進んでないわ。",
  ui_story_1020_10200801_4_dialog_content = "あともう少し時間をちょうだい。絶対にやり遂げてみせるから！",
  ui_story_1020_10200801_5_dialog_content = "ブー！",
  ui_story_1020_10200801_6_dialog_content = "時間の無駄です…",
  ui_story_1020_10200801_7_dialog_content = "ユリシーズ、動かないでください！",
  ui_story_1020_10200801_8_dialog_content = "来たか。",
  ui_story_1020_10200801_9_dialog_content = "ベリサリアの指示よ。\nすでにカナン城の住民の移動を命じたわ。",
  ui_story_1020_10200801_10_dialog_content = "意外だな…で、アルゴル、ユリシーズ。\n次はどうする？",
  ui_story_1020_10200801_11_dialog_content = "ユリシーズ、この倉庫でこんなにたくさんの暗鬼を造ってたのは、\n「エンジニア」と取引していたからなの？",
  ui_story_1020_10200801_12_dialog_content = "単純ですね。しかし、システムにログインし、\nカナン城の制御スイッチを抑え込めたということは、あなたも確実に成長したということですね。",
  ui_story_1020_10200801_13_dialog_content = "とはいえ、あなたが自分を過大評価し、「ガーディアン」の防御データを取り出すと同時に、\n彼の攻撃にも抵抗しようとしたからこそ、こうなっているのですよ。",
  ui_story_1020_10200801_14_dialog_content = "どういう意味かしら？",
  ui_story_1020_10200801_15_dialog_content = "防御の穴を一つ一つ潰したところで無駄です。\n完全に崩壊させることなど、彼にはいともたやすいことなのですから。",
  ui_story_1020_10200801_16_dialog_content = "しかし、私がやめるように言えば…",
  ui_story_1020_10200801_17_dialog_content = "じゃ、やってみせて。",
  ui_story_1020_10200801_18_dialog_content = "私にはできません。しかし、言ったはずです。\n空の末裔ならできると。あなたたちは信じませんでしたが。",
  ui_story_1020_10200801_19_dialog_content = "僕が…？",
  ui_story_1020_10200801_20_dialog_content = "PlayerNameを巻き込むな。\nお前にどうやって「エンジニア」を止められる？",
  ui_story_1020_10200801_21_dialog_content = "止める？何も止めようとは思っていませんよ。\n私はただ何か壊されていないか、様子を見に来ただけです。",
  ui_story_1020_10200801_22_dialog_content = "ユリシーズ！話が違うじゃない！！",
  ui_story_1020_10200801_23_dialog_content = "そもそも、あなたたちとは関係のないことです…",
  ui_story_1020_10200801_24_dialog_content = "<color=#e8d9bb>ジージーッ――ジジッ――</color>",
  ui_story_1020_10200801_25_dialog_content = "また来たよ…",
  ui_story_1020_10200801_26_dialog_content = "…ブブ…",
  ui_story_1020_10200801_27_dialog_content = "「プレゼント」？",
  ui_story_1020_10200801_28_dialog_content = "…どういう意味だ？",
  ui_story_1020_10200801_29_dialog_content = "実施途中だった実験を台無しにされましたが、\nそれはいいとしましょう。",
  ui_story_1020_10200801_30_dialog_content = "ただ、私は彼にあるものを用意しているのです。",
  ui_story_1020_10200801_31_dialog_content = "確か…ここに…",
  ui_story_1020_10200801_32_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200801_33_dialog_content = "うわ――！",
  ui_story_1020_10200801_34_dialog_content = "私につかまって！",
  ui_story_1020_10200801_35_dialog_content = "ユリシーズ、いったい何をしたの！？",
  ui_story_1020_10200801_36_dialog_content = "さ、さっきよりも、揺れが激しくなっています！",
  ui_story_1020_10200801_37_dialog_content = "いいえ、揺れてるんじゃありません！…移動してるんです！",
  ui_story_1020_10200801_38_dialog_content = "しっかりと踏ん張れ――",
  ui_story_1020_10200801_39_dialog_content = "ハハハハハ…どうです！？",
  ui_story_1020_10200801_40_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200801_41_dialog_content = "光霊と暗鬼を融合した、百の敵を相手に戦う<color=#FFB400>超戦士</color>は…",
  ui_story_1020_10200801_42_dialog_content = "とうの昔にあなたの研究を超えていたのです！",
  ui_story_1020_10200801_43_dialog_content = "床の下にいるのは全部…",
  ui_story_1020_10200801_44_dialog_content = "いったい何体いるんです…？",
  ui_story_1020_10200801_45_dialog_content = "…倉庫は床の下だったのね！\nどうりで、いくら探しても見つからないわけだわ！",
  ui_story_1020_10200801_46_dialog_content = "少なくとも数百…いえ、それ以上いるわね。",
  ui_story_1020_10200801_47_dialog_content = "体中にケーブルが挿さってるね。エネルギーを供給してるみたい…",
  ui_story_1020_10200801_48_dialog_content = "ユリシーズ！",
  ui_story_1020_10200801_49_dialog_content = "<color=#e8d9bb>ドンッ――ドンッ――ドンッ――</color>",
  ui_story_1020_10200801_50_dialog_content = "大変だ…超戦士が…動き出しました！",
  ui_story_1020_10200801_51_dialog_content = "<color=#e8d9bb>ガンッ――ガンッ――</color>",
  ui_story_1020_10200801_52_dialog_content = "倉庫内のケーブルから…火花が出てるみたいだよ！",
  ui_story_1020_10200801_53_dialog_content = "施設と一体化していたケーブルは、\nずっと倉庫の下に隠されていたのか！",
  ui_story_1020_10200801_54_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200801_55_dialog_content = "ケーブルで超戦士をコントロールして、\nコンピューターで指令を送ってたってわけね…",
  ui_story_1020_10200801_56_dialog_content = "…分かったわ！ブール！",
  ui_story_1020_10200801_57_dialog_content = "ブー！",
  ui_story_1020_10200801_58_dialog_content = "どうです？気に入りましたか？",
  ui_story_1020_10200801_59_dialog_content = "10年前…20年前に…アストラ大陸を襲った暗鬼など、\n私の傑作にはかなわないでしょう？",
  ui_story_1020_10200801_60_dialog_content = "ほう？",
  ui_story_1020_10200801_61_dialog_content = "アハハハ……",
  ui_story_1020_10200801_62_dialog_content = "<color=#e8d9bb>ジージーッ――ジジッ――</color>",
  ui_story_1020_10200801_63_dialog_content = "（どうしてエンジニアに、\nユリシーズ教授の言ってることが伝わってるんだろう？）",
  ui_story_1020_10200801_64_dialog_content = "（プロトタイプを通してるの？それとも、他の方法が…？）",
  ui_story_1020_10200801_65_dialog_content = "…ブブ…",
  ui_story_1020_10200801_66_dialog_content = "「大したこと…」",
  ui_story_1020_10200801_67_dialog_content = "…ブブ…",
  ui_story_1020_10200801_68_dialog_content = "「…ないな」",
  ui_story_1020_10200801_X68_dialog_content = "（どうしてエンジニアに、\nユリシーズ教授の言ってることが伝わってるんだろう？）",
  ui_story_1020_10200801_X69_dialog_content = "（プロトタイプを通してるの？それとも、他の方法が…？）",
  ui_story_1020_10200801_69_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200801_70_dialog_content = "超戦士が立ち上がったわよ！",
  ui_story_1020_10200801_X70_dialog_content = "どうです…？アハハハハ…",
  ui_story_1020_10200801_71_dialog_content = "ヒイロ、ユリシーズをしっかり見ていろ！\n他の者は全員退がれ！",
  ui_story_1020_10200801_72_dialog_content = "分かりました！",
  ui_story_1020_10200801_73_dialog_content = "…",
  ui_story_1020_10200801_74_dialog_content = "アルゴル！！",
  ui_story_1020_10200801_75_dialog_content = "…このマシンを放っておいたら、啓光は終わりよ！",
  ui_story_1020_10200801_76_dialog_content = "どうです…？アハハハハ…",
  ui_story_1020_10200801_77_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10200801_78_dialog_content = "ユリシーズ、倉庫の扉はどうやって閉じるの？",
  ui_story_1020_10200801_79_dialog_content = "答えなさい！！",
  ui_story_1020_10200801_80_dialog_content = "あなたたちとは関係のないことです…彼らは敵ではありませんよ。\nここを離れれば、いいだけのこと…",
  ui_story_1020_10200801_81_dialog_content = "ふざけないで！！",
  ui_story_1020_10200801_82_dialog_content = "ブール、ケーブルは見つかった！？\n急いで！急いでちょうだい！",
  ui_story_1020_10200801_83_dialog_content = "ブブブブブ――！！",
  ui_story_1020_10200801_X83_dialog_content = "急いで！もっと急いで！",
  ui_story_1020_10200801_84_dialog_content = "<color=#e8d9bb>ドンッ――ドンッ――ドンッ――</color>",
  ui_story_1020_10200801_85_dialog_content = "グオオオオ――",
  ui_story_1020_10200801_86_dialog_content = "アルゴル！！",
  ui_story_1020_10200801_87_dialog_content = "…",
  ui_story_1020_10200801_88_dialog_content = "アルゴル博士は、何が何でも立ち去る気はないようですね…",
  ui_story_1020_10200801_89_dialog_content = "アルゴルさん、感知能力で助けます！",
  ui_story_1020_10200801_90_dialog_content = "いいえ、あなたたちはここを離れて！！",
  ui_story_1020_10200801_91_dialog_content = "超戦士をコントロールしてるケーブルは見つけたわ…",
  ui_story_1020_10200801_92_dialog_content = "ブブブブブ――！！",
  ui_story_1020_10200801_93_dialog_content = "データベースの同期、完了よ！あとは…",
  ui_story_1020_10200801_94_dialog_content = "急いで…もっと急ぐのよ！！",
  ui_story_1020_10200801_95_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200801_96_dialog_content = "アルゴルさん、あぶないっ！",
  ui_story_1020_10200801_97_dialog_content = "<color=#e8d9bb>ドン――！！</color>",
  ui_story_1020_10200801_98_dialog_content = "ブブ？",
  ui_story_1020_10200801_99_dialog_content = "グオオオオ――",
  ui_story_1020_10200801_100_dialog_content = "どういうこと？超戦士は…アルゴルさんを攻撃してない！？",
  ui_story_1020_10200801_101_dialog_content = "…",
  ui_story_1020_10200801_102_dialog_content = "<color=#e8d9bb>ドン――！ドン――！ドン――！</color>",
  ui_story_1020_10200801_103_dialog_content = "プロトタイプを…狙ってるの…？",
  ui_story_1020_10200801_104_dialog_content = "まさか、ユリシーズの超戦士は…",
  ui_story_1020_10200801_105_dialog_content = "アハハハハ…どうです？気に入りましたか…？",
  ui_story_1020_10200801_106_dialog_content = "さて、どうしますか…？\nあなたの暗鬼は…いったいどこでしょうね？",
  ui_story_1020_10200801_107_dialog_content = "<color=#e8d9bb>ジージーッ――ジジッ――</color>",
  ui_story_1020_10200801_108_dialog_content = "…ブブ…",
  ui_story_1020_10200801_109_dialog_content = "「ありがとう」",
  ui_story_1020_10200801_110_dialog_content = "…ありがとう？",
  ui_story_1020_10200801_111_dialog_content = "…",
  ui_story_1020_10200801_112_dialog_content = "グォォ…",
  ui_story_1020_10200801_113_dialog_content = "超戦士が…動かなくなった？",
  ui_story_1020_10200801_114_dialog_content = "何を探しているんでしょう？",
  ui_story_1020_10200801_115_dialog_content = "<color=#e8d9bb>バチッ――バチッ――</color>",
  ui_story_1020_10200801_116_dialog_content = "アルゴル博士、ケーブルからまた火花が出てるわよ！",
  ui_story_1020_10200801_117_dialog_content = "大丈夫よ…コマンドを断ち切るから…",
  ui_story_1020_10200801_118_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10200801_119_dialog_content = "あ！！この、バケモノ！！なんてバケモノなの！",
  ui_story_1020_10200801_120_dialog_content = "何をするつもりですか…？",
  ui_story_1020_10200801_121_dialog_content = "<color=#e8d9bb>バチッ――バチッ――</color>",
  ui_story_1020_10200801_122_dialog_content = "超戦士の背中を見て！！",
  ui_story_1020_10200801_123_dialog_content = "グォォ――！！！",
  ui_story_1020_10200801_124_dialog_content = "攻撃してきたわ！",
  ui_story_1020_10200801_125_dialog_content = "私の研究成果に何をする気ですか！？",
  ui_story_1020_10200801_126_dialog_content = "グォォ――！！！",
  ui_story_1020_10200801_127_dialog_content = "アルゴルさん、危ない！！",
  ui_story_1020_10200901_1_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――！</color>",
  ui_story_1020_10200901_2_dialog_content = "バートン軍団長、もう全力を尽くしました！",
  ui_story_1020_10200901_3_dialog_content = "しかし、<color=#FFB400>10号城門</color>は苦戦しています。応援が必要です！",
  ui_story_1020_10200901_4_dialog_content = "お前たちみてえな精鋭部隊が、\n実戦経験を積む絶好のチャンスを他のやつらに譲るってのか！？",
  ui_story_1020_10200901_5_dialog_content = "違います、軍団長！\n城門の震動が激しすぎ、身体がもう持ちそうにありません…",
  ui_story_1020_10200901_6_dialog_content = "10号城門か…整備工場の方だったな？",
  ui_story_1020_10200901_7_dialog_content = "まさか、小僧のソラヴァンが出しゃばって、\nあの身体で城門を抑えてるってか？",
  ui_story_1020_10200901_8_dialog_content = "巨像が城門を抑えられるんでしょうか…？",
  ui_story_1020_10200901_9_dialog_content = "できるだろうよ。やつは空の末裔の小僧を育てたんだぞ！",
  ui_story_1020_10200901_10_dialog_content = "お前ら、ついて来い！\nこの俺が鉄の塊に負けるワケにはいかねえ！",
  ui_story_1020_10200901_11_dialog_content = "軍団長！<color=#FFB400>9号城門</color>でも、激しい揺れが起こっています！\n強力な気流が地下から上層部へ抜けているようです！",
  ui_story_1020_10200901_12_dialog_content = "地下からだと！？急いで通風孔を全部調べろ！\n隅々までしっかり調べるんだ！",
  ui_story_1020_10200901_13_dialog_content = "すでに調べました！暗鬼の痕跡は見つかりませんでした！",
  ui_story_1020_10200901_14_dialog_content = "んだと？だったら、どういうことだ…？",
  ui_story_1020_10200901_15_dialog_content = "<color=#e8d9bb>9号城門付近</color>",
  ui_story_1020_10200901_16_dialog_content = "長官、失礼いたします。\nここは震動が激しいので、安全な所へお逃げください！",
  ui_story_1020_10200901_17_dialog_content = "心配ご無用です。輸送シューターが稼働しているので、\n上層部の震動がどの程度か調べにきただけです。",
  ui_story_1020_10200901_18_dialog_content = "輸送シューター、ですか…？",
  ui_story_1020_10200901_19_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200901_20_dialog_content = "大丈夫そうね。城門への影響は大したことないわ。",
  ui_story_1020_10200901_21_dialog_content = "…",
  ui_story_1020_10200901_22_dialog_content = "<color=#e8d9bb>白夜城・黎明学院</color>",
  ui_story_1020_10200901_23_dialog_content = "白夜に捧ぐ――聞きましたか？学院内の<color=#FFB400>白夜石</color>に突如異変が起こり、\n光力の乱れが続いているそうです。",
  ui_story_1020_10200901_24_dialog_content = "神父様、修道女様たちが駆け付け、\n光力術でなんとか抑えようとしていますが、収まる兆しが見えません。",
  ui_story_1020_10200901_25_dialog_content = "前にも白夜城が揺れたことがありましたね？関係あるのでしょうか？",
  ui_story_1020_10200901_26_dialog_content = "そうですね。おそらく古代遺跡がまた神秘の力と共鳴を起こしたのでしょう。",
  ui_story_1020_10200901_27_dialog_content = "トワイライトシティで極光の乱れが起こった時にも、\n同じようなことが起こりましたが、今回はさらに深刻です。",
  ui_story_1020_10200901_28_dialog_content = "<color=#e8d9bb>白夜城・朝堂</color>",
  ui_story_1020_10200901_29_dialog_content = "見るがいい！輸送シェルターはまるで地面が貪欲な口を開いたかのようではないか！\n啓光の飢えた狼めが、とうとう牙をむきおった！",
  ui_story_1020_10200901_30_dialog_content = "だが、その飢えた狼は今だ白夜城に噛みついてはおらぬ。",
  ui_story_1020_10200901_31_dialog_content = "護衛隊長、防御体制を解け。\n遺跡はすでに落ち着いた。",
  ui_story_1020_10200901_32_dialog_content = "はい。",
  ui_story_1020_10200901_33_dialog_content = "城主様、黎明学院にある光力を貯めた石が先程の震動に激しく反応しました。\n白夜城内に正体不明の力が存在しているのでしょうか？",
  ui_story_1020_10200901_34_dialog_content = "白夜に捧ぐ――カレン殿下、御心配にはおよびません。",
  ui_story_1020_10200901_35_dialog_content = "聖女様が神殿に入られた時以降、起こっていなかった現象ではございますが、\n光の神は必ずや私どもを導いてくださいます。",
  ui_story_1020_10200901_36_dialog_content = "神父よ、お主はこの度の白夜石の異変をいかに見る？",
  ui_story_1020_10200901_37_dialog_content = "教典に関連する記載がございます。\n新たな<color=#FFB400>神降</color>が出現する時、光力に乱れが生じる、と。",
  ui_story_1020_10200901_38_dialog_content = "…",
  ui_story_1020_10200901_39_dialog_content = "地下遺跡に宿る邪悪な力はかつて、この浮空島を震わせた。\n神降たる聖女様がその邪な力を払ってくださった。",
  ui_story_1020_10200901_40_dialog_content = "思えば、聖女様はもう幾年もの間、この浮空島を守ってくださっているのだな。",
  ui_story_1020_10200901_41_dialog_content = "邪な力は弱小化するものの、払うことはできません。\n白夜城も完全に清らかな島ではございません。",
  ui_story_1020_10200901_42_dialog_content = "神父様、白夜城は危険なのでしょうか？",
  ui_story_1020_10200901_43_dialog_content = "いいえ。",
  ui_story_1020_10200901_44_dialog_content = "では、啓光連邦はどうですか？",
  ui_story_1020_10200901_45_dialog_content = "彼らがまずやるべきことは自身の信仰を見つけることです。",
  ui_story_1020_10200901_46_dialog_content = "護衛隊長、啓光より届く便りに留意するように。",
  ui_story_1020_10200901_47_dialog_content = "承知いたしました、城主様。",
  ui_story_1020_10200901_48_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10200901_49_dialog_content = "アルゴル、状況はどうだ？",
  ui_story_1020_10200901_50_dialog_content = "制御装置のメッセージによれば、\nコアがもうすぐ構築できるわ。",
  ui_story_1020_10200901_51_dialog_content = "エンジニアが攻撃をしかけてこないうちに…\n頑張るのよ、ブール！",
  ui_story_1020_10200901_52_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200901_53_dialog_content = "何…？",
  ui_story_1020_10200901_54_dialog_content = "<color=#e8d9bb>ジージーッ――ジジッ――</color>",
  ui_story_1020_10200901_55_dialog_content = "…ブブ…",
  ui_story_1020_10200901_56_dialog_content = "「帰るんだ、空の末裔」",
  ui_story_1020_10200901_57_dialog_content = "空の末裔はどこにもいきませんよ！",
  ui_story_1020_10200901_58_dialog_content = "…",
  ui_story_1020_10200901_59_dialog_content = "「エンジニア」はユリシーズと話していたんじゃないのですか？\nどうしてPlayerNameのことを知っているんです？",
  ui_story_1020_10200901_60_dialog_content = "帰るんだ、空の末裔。",
  ui_story_1020_10200901_61_dialog_content = "この声…どこかで聞いたことがあるような…",
  ui_story_1020_10200901_62_dialog_content = "どこで？",
  ui_story_1020_10200901_63_dialog_content = "頭の中で…",
  ui_story_1020_10200901_64_dialog_content = "あの時頭の中に浮かんだ情景は、本当に感知だったの…？",
  ui_story_1020_10200901_65_dialog_content = "帰るんだ、空の末裔。",
  ui_story_1020_10200901_66_dialog_content = "…君は誰？",
  ui_story_1020_10200901_67_dialog_content = "君たちがエンジニアと呼ぶ者だ。",
  ui_story_1020_10200901_68_dialog_content = "君は日蝕の暗鬼で…このコンピューターを使って、\n啓光の超戦士をコントロールしてたの？",
  ui_story_1020_10200901_69_dialog_content = "いいや、違う。",
  ui_story_1020_10200901_70_dialog_content = "…君が啓光の「ガーディアン1号」のコアを盗んで、\n暗鬼をカナン城に侵入させたんだね。",
  ui_story_1020_10200901_71_dialog_content = "あれは最初から私の物だ。",
  ui_story_1020_10200901_72_dialog_content = "君もね。",
  ui_story_1020_10200901_73_dialog_content = "…僕は空の末裔だけど、アストラ大陸の天空ノ谷で生まれたんだよ。",
  ui_story_1020_10200901_74_dialog_content = "空の末裔は、どうやって生まれたのかな？",
  ui_story_1020_10200901_75_dialog_content = "君は僕に…空の末裔に何をしたの？",
  ui_story_1020_10200901_76_dialog_content = "帰るんだ、空の末裔。",
  ui_story_1020_10200901_77_dialog_content = "私と一緒に、あの崇高な使命を遂行しよう。",
  ui_story_1020_10200901_78_dialog_content = "「崇高な使命」ですか…空の末裔はどこにも行きません！！",
  ui_story_1020_10200901_79_dialog_content = "ユリシーズ、何を言っているのですか！？",
  ui_story_1020_10200901_80_dialog_content = "…",
  ui_story_1020_10200901_81_dialog_content = "ユリシーズ教授も、君を感知できるの？",
  ui_story_1020_10200901_82_dialog_content = "彼は、君とは違う。",
  ui_story_1020_10200901_83_dialog_content = "私が教えてあげよう。君が知りたがっている真相のすべてを。",
  ui_story_1020_10200901_84_dialog_content = "太古の時代の暗面の戦場、巨像の停泊地、空の末裔の故郷…",
  ui_story_1020_10200901_85_dialog_content = "そして、君が望み続けている一族の行方も。",
  ui_story_1020_10200901_86_dialog_content = "…！？",
  ui_story_1020_10200901_87_dialog_content = "<color=#e8d9bb>ピッ――ピピッ――ピピピ――</color>",
  ui_story_1020_10200901_88_dialog_content = "アルゴルのリストバンドが、危険を知らせています。",
  ui_story_1020_10200901_89_dialog_content = "整備工場ね…",
  ui_story_1020_10200901_90_dialog_content = "PlayerName、ソラヴァンがあたしのデバイスとの接続を切断しようとしてるわ！",
  ui_story_1020_10200901_91_dialog_content = "ソラヴァン…",
  ui_story_1020_10200901_92_dialog_content = "君がやったの！？",
  ui_story_1020_10200901_93_dialog_content = "君の代わりに巨像を起動したよ。",
  ui_story_1020_10200901_94_dialog_content = "ダメだ…やめて！",
  ui_story_1020_10200901_95_dialog_content = "<color=#e8d9bb>バタン――</color>",
  ui_story_1020_10200901_96_dialog_content = "PlayerName！",
  ui_story_1020_10200901_97_dialog_content = "すでに飛び出していってしまいました。",
  ui_story_1020_10200901_98_dialog_content = "ビビアン、追いかけるのだ。今外に出ては危険だ！",
  ui_story_1020_10200901_99_dialog_content = "承知しました！",
  ui_story_1020_10200901_100_dialog_content = "空の末裔はどこへも行きません！あなたの狙いは私です…",
  ui_story_1020_10200901_101_dialog_content = "ユリシーズ、これ以上勝手なマネは許しません！",
  ui_story_1020_10200901_102_dialog_content = "放しなさい！私が相手になります！",
  ui_story_1020_10200901_103_dialog_content = "<color=#e8d9bb>カチャカチャ――</color>",
  ui_story_1020_10200901_104_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10200901_105_dialog_content = "ユリシーズ、やめて！",
  ui_story_1020_10200901_106_dialog_content = "グォォ！！！",
  ui_story_1020_10200901_107_dialog_content = "何年もかかって…やり遂げたのです…",
  ui_story_1020_10200901_108_dialog_content = "これで足るでしょうか…！？",
  ui_story_1020_10200901_109_dialog_content = "足りないなら、まだたくさんありますよ！何百何千といるのです！\n暗鬼より何千倍も強い超戦士が！",
  ui_story_1020_10200901_110_dialog_content = "<color=#e8d9bb>ジージーッ――ジジッ――</color>",
  ui_story_1020_10200901_111_dialog_content = "…ブブ…",
  ui_story_1020_10200901_112_dialog_content = "「最後だ」",
  ui_story_1020_10200901_113_dialog_content = "大変だわ！ユリシーズを抑えてちょうだい！\nエンジニアが超戦士を操って攻撃してくるわ！",
  ui_story_1020_10200901_114_dialog_content = "ユリシーズは私にお任せください！",
  ui_story_1020_10200901_115_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10200901_116_dialog_content = "ああああ――！！やっとのことで構築した防御モジュールが…！！",
  ui_story_1020_10200901_117_dialog_content = "グオオォ！！！",
  ui_story_1020_10201001_1_dialog_content = "PlayerName！",
  ui_story_1020_10201001_2_dialog_content = "ここから整備工場まで距離があります。\n今、外は危険すぎます！",
  ui_story_1020_10201001_3_dialog_content = "…ソラヴァンはどこにも行かせない！",
  ui_story_1020_10201001_4_dialog_content = "あなたの指示がないのに、\nどうしてソラヴァンが勝手に起動したんですか？",
  ui_story_1020_10201001_5_dialog_content = "…",
  ui_story_1020_10201001_6_dialog_content = "見えたんです…",
  ui_story_1020_10201001_7_dialog_content = "何が…見えたんですか…？",
  ui_story_1020_10201001_8_dialog_content = "ユリシーズ教授が見た風景を、僕も見たんです…",
  ui_story_1020_10201001_9_dialog_content = "それから、声がして…「エンジニア」が僕とソラヴァンに\n「帰れ」って呼びかけてきたんです…",
  ui_story_1020_10201001_10_dialog_content = "PlayerName…",
  ui_story_1020_10201001_11_dialog_content = "やっとソラヴァンが戻ってきたのに…\nまだ戻ってきたばかりなのに…",
  ui_story_1020_10201001_12_dialog_content = "絶対…絶対、そんなことさせない！",
  ui_story_1020_10201001_13_dialog_content = "僕に何ができるだろう…僕は…",
  ui_story_1020_10201001_14_option_content = "精神感知",
  ui_story_1020_10201001_15_dialog_content = "…",
  ui_story_1020_10201001_16_option_content = "精神感知",
  ui_story_1020_10201001_17_dialog_content = "…",
  ui_story_1020_10201001_18_dialog_content = "ソラヴァンは…もういなくなっちゃったの？",
  ui_story_1020_10201001_19_dialog_content = "今日実験棟を出たあの時、何とも言えない嫌な感じがした…",
  ui_story_1020_10201001_20_dialog_content = "とてつもなく大きな天井の上に一筋の光が見えて、\nその光が僕の希望を全部奪い去っていくような…",
  ui_story_1020_10201001_21_dialog_content = "ソラヴァンが…遠くへ飛んで行ってしまう気がして…",
  ui_story_1020_10201001_22_dialog_content = "あの時は…どうしてそんなふうに感じたのか、\n分からなかった…",
  ui_story_1020_10201001_23_dialog_content = "でも、前に見た夢のことを思えば、気づくべきだったんだ…",
  ui_story_1020_10201001_24_option_content = "精神感知",
  ui_story_1020_10201001_25_dialog_content = "…",
  ui_story_1020_10201001_26_option_content = "精神感知",
  ui_story_1020_10201001_27_dialog_content = "…",
  ui_story_1020_10201001_28_option_content = "精神感知",
  ui_story_1020_10201001_29_dialog_content = "…",
  ui_story_1020_10201001_30_dialog_content = "ああああ――！！！",
  ui_story_1020_10201001_31_dialog_content = "もうやめてください、PlayerName！",
  ui_story_1020_10201001_32_dialog_content = "今日は感知能力を使い過ぎています。ひどい顔色ですよ！",
  ui_story_1020_10201001_33_dialog_content = "バイスと連絡がとれなくなって…そのうえ、ソラヴァンまで失ったら、\n僕にはもう…何も残ってない…",
  ui_story_1020_10201001_34_dialog_content = "…ソラヴァンはどこに行っちゃたんだろう？\nエンジニアは何をするつもりなの！？",
  ui_story_1020_10201001_35_dialog_content = "その問いの答えなら、私が教えてやろう――",
  ui_story_1020_10201001_36_dialog_content = "抜刀！",
  ui_story_1020_10201001_37_dialog_content = "ビビアンさん！",
  ui_story_1020_10201001_38_dialog_content = "…フィジェロ？",
  ui_story_1020_10201001_39_dialog_content = "軽すぎる。いや、甘いな…",
  ui_story_1020_10201001_40_dialog_content = "甘すぎて、思わず手を出したくなるぞ！",
  ui_story_1020_10201001_41_dialog_content = "キキキキキッ、他人が大切なものを失うのを見るというのは、\n実に気分のよいものだな。",
  ui_story_1020_10201001_42_dialog_content = "…前から…ソラヴァンがどこかへ行ってしまうって\n知ってたんだね！？",
  ui_story_1020_10201001_43_dialog_content = "私がソラヴァンに何をしたか、聞かなくていいのか？",
  ui_story_1020_10201001_44_dialog_content = "えっ…！？",
  ui_story_1020_10201001_45_dialog_content = "待ってください、PlayerName。様子がおかしいです…",
  ui_story_1020_10201001_46_dialog_content = "フィジェロは収監室に収納されて身動きもできなかったはず…\nそれが今、ここにいるというのは…",
  ui_story_1020_10201001_47_dialog_content = "信じられんだろう？これこそ、あの御方の力だ！",
  ui_story_1020_10201001_48_dialog_content = "あのような鎖、多少厄介だというにすぎん。\nだが、私を縛ったカスどもには、死の瞬間に絶望の喜びを味わせてやった。",
  ui_story_1020_10201001_49_dialog_content = "ただ、味は…空の末裔に比べると、天と地の差だったがな。",
  ui_story_1020_10201001_50_dialog_content = "キキキキッ、選ぶがいい、空の末裔。\nお前も弱々しい同胞と同様、何の役にも立たずに死にたいか――",
  ui_story_1020_10201001_51_dialog_content = "それとも、私の手土産となって、\n共にあの御方の偉大さの目撃者となるか？",
  ui_story_1020_10201001_52_dialog_content = "空の末裔は役立たずじゃない！\nエンジニアはどこにいるの！？",
  ui_story_1020_10201001_53_dialog_content = "キキキキッ！よし、どうやら後者を選んだようだな。",
  ui_story_1020_10201001_54_dialog_content = "では、お前の横にいるカスは、安心して死ぬがいい。",
  ui_story_1020_10201001_55_dialog_content = "PlayerNameには指一本触れさせません！",
  ui_story_1020_10201001_56_dialog_content = "ほう？私の暗力を味わってみたいと見えるな。\n光霊の血と引き換えに得た力だ。",
  ui_story_1020_10201001_57_dialog_content = "PlayerName！私の背後に隠れてください。",
  ui_story_1020_10201001_58_dialog_content = "そのもがき苦しむ様子、何とも滑稽だな…",
  ui_story_1020_10201001_59_dialog_content = "痛みを感じる喜びをせいぜいかみしめるがいい。\n偉大なる時代がまもなくやってくる。あの御方がお前に解脱を授けてくださるだろう。",
  ui_story_1020_10201001_60_dialog_content = "このレイヴンが――空の末裔の血を吸わせてやろう！",
  ui_story_1020_10201001_61_dialog_content = "暗鬼め！PlayerNameには手を出させないよ！",
  ui_story_1020_10201001_62_dialog_content = "間に合ってよかったです！",
  ui_story_1020_10201001_63_dialog_content = "PlayerName！ビビアン長官！ケガはありませんか？",
  ui_story_1020_10201001_64_dialog_content = "ショーン！？早くここから離れて！暗力でやられちゃうよ！",
  ui_story_1020_10201001_65_dialog_content = "分かってる！\nでも僕は今、君を守らなきゃいけないんだよ、PlayerName！",
  ui_story_1020_10201001_66_dialog_content = "今の、どうだった？がっかりさせなかったでしょ？",
  ui_story_1020_10201001_67_dialog_content = "がっかりなんて、そんな！\nショーン、君は暗力の攻撃に耐えられるんだね！",
  ui_story_1020_10201001_68_dialog_content = "当然だよ！僕はインゲルやアクセリアと同じスーパー戦士なんだから！",
  ui_story_1020_10201001_69_dialog_content = "それと同時に血の通った光霊でもあるんだ。",
  ui_story_1020_10201001_70_dialog_content = "参謀長、PlayerName。この暗鬼は僕に任せて！",
  ui_story_1020_10201001_71_dialog_content = "ショーン、気を付けてください！あいつは卑劣な手段を使います。\n私たちは後ろで他の暗鬼を片付け、援護します！",
  ui_story_1020_10201001_72_dialog_content = "うん！",
  ui_story_1020_10201001_73_dialog_content = "ほう…若僧が！甘い！",
  ui_story_1020_10201101_1_dialog_content = "カスごときが…私の邪魔をする気か？",
  ui_story_1020_10201101_2_dialog_content = "今度こそ使命を果たさねば…私は…",
  ui_story_1020_10201101_3_dialog_content = "おい、そこのモジャモジャの耳の生えた小僧…\n私の暗力が当たったというのに、ダメージがないな…",
  ui_story_1020_10201101_4_dialog_content = "だ、だったら何なの？僕は仲間を守るんだ！",
  ui_story_1020_10201101_5_dialog_content = "キキキッ、その姿からして当然か…\n純粋な獣人族は絶滅したはずだが、お前は今の今まで生き延びた。",
  ui_story_1020_10201101_6_dialog_content = "…何が言いたいんだ？",
  ui_story_1020_10201101_7_dialog_content = "私はかつて獣人族を壊滅する偉大な計画に参加したのだ。\nあの御方のために役目を果たした、この上ない栄誉の一つだ。",
  ui_story_1020_10201101_8_dialog_content = "だが、お前を見るに、あのずる賢い獣人どもは生き残るため、\n光霊と講和し、今の今まで生き延びてきたようだな。",
  ui_story_1020_10201101_9_dialog_content = "まったく…ゴキブリ同様、しぶとさだけが取り柄と言おうか！",
  ui_story_1020_10201101_10_dialog_content = "それ以上ショーンを侮辱しないで！",
  ui_story_1020_10201101_11_dialog_content = "おや？怒ったと？私を殺すか？",
  ui_story_1020_10201101_12_dialog_content = "ソラヴァンの行方は知りたくないのか？それから…\n四六時中、お前にひっついていた腰巾着の小娘のことは、どうでもいいのか？",
  ui_story_1020_10201101_13_dialog_content = "アネモネに出くわせば、\nあの小娘には無惨な末路しか残っていないだろうな。",
  ui_story_1020_10201101_14_dialog_content = "…バイスのこと？バイスがアネモネに出くわした…？\nバイスに、いったい何があったの？",
  ui_story_1020_10201101_15_dialog_content = "確か、あの時…",
  ui_story_1020_10201101_16_dialog_content = "エンジニアはどこ？ソラヴァンはどこへ行ったの？\n早く教えて！",
  ui_story_1020_10201101_17_dialog_content = "…",
  ui_story_1020_10201101_18_dialog_content = "ああ！！我が偉大なる主よ――私をお見捨てくださいますな！",
  ui_story_1020_10201101_19_dialog_content = "…",
  ui_story_1020_10201101_20_dialog_content = "誰と話しているのですか…「主」とはいったい…？",
  ui_story_1020_10201101_21_dialog_content = "たぶん、意識の中で会話してるんだよ。\nエンジニアが話しかけてきたんだ…",
  ui_story_1020_10201101_22_dialog_content = "手がかりを見つけるなら、今がチャンスかもしれない…",
  ui_story_1020_10201101_23_dialog_content = "PlayerName、何をする気ですか？",
  ui_story_1020_10201101_24_option_content = "強制感知",
  ui_story_1020_10201101_25_dialog_content = "（うわっ――く、苦しい…）",
  ui_story_1020_10201101_26_dialog_content = "（でも…そんなこと、どうでもいい！）",
  ui_story_1020_10201101_27_dialog_content = "（バイスにいったい何があったの？ソラヴァンはどこに行っちゃったの…？）",
  ui_story_1020_10201101_28_dialog_content = "（答えを、見つけなきゃ…）",
  ui_story_1020_10201101_29_dialog_content = "瘦せ細り、貧弱で、容姿も醜い。",
  ui_story_1020_10201101_30_dialog_content = "か、構いません！あなた様の印さえあれば、\n卑しい光霊と暗鬼どもは皆、私にひれ伏すでしょう。",
  ui_story_1020_10201101_31_dialog_content = "お前にひれ伏す？では、私は何だ？",
  ui_story_1020_10201101_32_dialog_content = "あなた様の威厳に私は身を震わせております。\n生涯、あなた様の翼としてお仕えさせてください！",
  ui_story_1020_10201101_33_dialog_content = "承認の証たるリングを受け入れるんだな？",
  ui_story_1020_10201101_34_dialog_content = "リング…",
  ui_story_1020_10201101_35_dialog_content = "はい、喜んで！リングはあなた様から賜る恩恵であり、私の命の意義でございます！\n高貴な者のみが得られる証でございます！",
  ui_story_1020_10201101_36_dialog_content = "謹んでお礼を申し上げます。至上の主宰者様！",
  ui_story_1020_10201101_37_dialog_content = "よろしい。",
  ui_story_1020_10201101_38_dialog_content = "私にどうか、どうか…あああああ――！！",
  ui_story_1020_10201101_39_dialog_content = "あ、頭が…頭がっ！い、痛みで割れそうだ…\nお、お助ください…至上の…主宰者様…！",
  ui_story_1020_10201101_40_dialog_content = "（これは…フィジェロの過去の記憶だ…あの声はエンジニアの声…）",
  ui_story_1020_10201101_41_dialog_content = "（日蝕のファントムは自ら進んで、リングの縛りを受け入れたのか…）",
  ui_story_1020_10201101_42_dialog_content = "（…）",
  ui_story_1020_10201101_43_dialog_content = "（それにしても、感知能力でこんなに昔の記憶まで見られるなんて…\nエンジニアの出てくる夢を見た後からだったかな？）",
  ui_story_1020_10201101_44_dialog_content = "（それとも、アルゴルさんにやり方を教えてもらって、\nブールを感知できてからかな…？）",
  ui_story_1020_10201101_45_dialog_content = "（バイスとソラヴァンの手がかりを見つけるには、\n最近の記憶まで感知を広げないと…）",
  ui_story_1020_10201101_46_option_content = "感知展延――",
  ui_story_1020_10201101_47_dialog_content = "（ううっ…この暗力は…ブールを感知した時と同じように苦しい）",
  ui_story_1020_10201101_48_dialog_content = "（でも、一度経験してるから、大丈夫だ…）",
  ui_story_1020_10201101_49_dialog_content = "（あれ…？ここは暗面かな？）",
  ui_story_1020_10201101_50_dialog_content = "（大きな穴が開いてる…亀裂がもっと先まで広がってるみたいだ…）",
  ui_story_1020_10201101_51_dialog_content = "（これがエンジニアの言ってた太古の戦争遺跡？）",
  ui_story_1020_10201101_52_dialog_content = "（いったい何があったんだろう？こんな状態になるなんて…）",
  ui_story_1020_10201101_53_dialog_content = "（周りには…巨像がいる感じはない…）",
  ui_story_1020_10201101_54_option_content = "感知展延――",
  ui_story_1020_10201101_55_dialog_content = "（これは…巨像の残骸の山？）",
  ui_story_1020_10201101_56_dialog_content = "（1隻、2隻、3隻…）",
  ui_story_1020_10201101_57_dialog_content = "（…）",
  ui_story_1020_10201101_58_dialog_content = "（ここが巨像の停泊地…？）",
  ui_story_1020_10201101_59_dialog_content = "（荒れ果てた平坦な大地…回帰の塔とは大違いだ…）",
  ui_story_1020_10201101_60_dialog_content = "（巨像に、いったい何があったの…？\nすっかり風化して、骨格しか残ってない…）",
  ui_story_1020_10201101_61_dialog_content = "（どれだけ昔の情景なんだ？生命体の気配がまったく感じられない…）",
  ui_story_1020_10201101_62_dialog_content = "（そうだ、「ガーディアン1号」のコアだ…）",
  ui_story_1020_10201101_63_dialog_content = "（ソラヴァンのデータにあった座標は何かの手がかりかもしれない…）",
  ui_story_1020_10201101_64_dialog_content = "（座標…光る柱…）",
  ui_story_1020_10201101_65_option_content = "感知展延――",
  ui_story_1020_10201101_66_dialog_content = "（ここだ！）",
  ui_story_1020_10201101_67_dialog_content = "（間違いない。前にユリシーズ教授の意識の中で見たのと同じだ…）",
  ui_story_1020_10201101_68_dialog_content = "（この光る石柱は「ガーディアン1号」のコアだね。\n今はすごくハッキリ見える…）",
  ui_story_1020_10201101_69_dialog_content = "（石柱が上に向かって移動してる…きっと上に何かあるんだ…）",
  ui_story_1020_10201101_70_dialog_content = "準備はできたか？",
  ui_story_1020_10201101_71_dialog_content = "『はい。最後の<color=#FFB400>駆動リング</color>も入手しました。』",
  ui_story_1020_10201101_72_dialog_content = "よし。",
  ui_story_1020_10201101_73_dialog_content = "どうか見ていてください――",
  ui_story_1020_10201101_74_dialog_content = "あなた様の降臨をお待ちしております――",
  ui_story_1020_10201101_75_dialog_content = "お前は…誰だ？",
  ui_story_1020_10201101_76_dialog_content = "…",
  ui_story_1020_10201101_77_dialog_content = "啓光の科学者の小娘でございます。",
  ui_story_1020_10201101_78_dialog_content = "啓光、か。",
  ui_story_1020_10201101_79_dialog_content = "あの役立たずのレイヴンも、啓光におります。",
  ui_story_1020_10201101_80_dialog_content = "啓光か。実に懐かしい響きだな。",
  ui_story_1020_10201101_81_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10201101_82_dialog_content = "（さっきのは…夢じゃなかったんだ…）",
  ui_story_1020_10201101_83_dialog_content = "（でも、前はバイスがいたのに、今回はバイスじゃなくて…ノラがいた…）",
  ui_story_1020_10201101_84_dialog_content = "（ノラの側にいたのは、ファントムかな…）",
  ui_story_1020_10201101_85_dialog_content = "あ、あなた様なのですね…至上の主宰者様！",
  ui_story_1020_10201101_86_dialog_content = "忠実な僕フィジェロ、\nあなた様の降臨を謹んでお待ち申し上げておりました。",
  ui_story_1020_10201101_87_dialog_content = "お前は何一つ成し遂げられないな。",
  ui_story_1020_10201101_88_dialog_content = "我が偉大なる主よ、私もかつては輝かしい成果を残しております！\n獣人族の壊滅を指揮したのは私です――",
  ui_story_1020_10201101_89_dialog_content = "もう何百年も前のことだろう？",
  ui_story_1020_10201101_90_dialog_content = "お前に授けた物を、私はいつでも必要な時に回収できる。",
  ui_story_1020_10201101_91_dialog_content = "そ、そんな…！そんなむごいことはなさらない、そうでしょう？\n私はあなた様が自ら作り上げた翼でございます！",
  ui_story_1020_10201101_92_dialog_content = "鎖を切ってやる。",
  ui_story_1020_10201101_93_dialog_content = "お前でも日蝕の役に立てるというのなら、\n空の末裔を私の元へ連れてこい。",
  ui_story_1020_10201101_94_dialog_content = "私には巨像を動かすだけの力がある。",
  ui_story_1020_10201101_95_dialog_content = "<color=#e8d9bb>ガチャッ――</color>",
  ui_story_1020_10201101_96_dialog_content = "…",
  ui_story_1020_10201101_97_dialog_content = "ああ！感謝と喜びで身の震える思いでございます！\n今後あなた様の命に決して背きません！",
  ui_story_1020_10201101_98_dialog_content = "（…）",
  ui_story_1020_10201101_99_dialog_content = "（エンジニアがカナン城へ来たのは、ファントムを呼び戻すため…）",
  ui_story_1020_10201101_100_dialog_content = "（そして、僕とソラヴァンを連れ去るためだったのか…）",
  ui_story_1020_10201101_101_dialog_content = "気に入ったか？",
  ui_story_1020_10201101_102_dialog_content = "ずっと…見てたの？",
  ui_story_1020_10201101_103_dialog_content = "ああ、ずっとね。",
  ui_story_1020_10201101_104_dialog_content = "君の目は私が授けたものだからね。\nあの壮観な塔の戦場を見せてあげたんだ。感謝してほしいものだね。",
  ui_story_1020_10201101_105_dialog_content = "塔の戦場…あれは、本当にあったことだってこと…！？",
  ui_story_1020_10201101_106_dialog_content = "価値があるのは、真実だけだ。",
  ui_story_1020_10201101_107_dialog_content = "あの亀裂のある場所は、かつて私の故郷だった所だ。\nだが、戦争で私も粉々に砕かれてしまった。",
  ui_story_1020_10201101_108_dialog_content = "破片を探し集め、土台をつなぎ合わせた後、心臓を再起動した。",
  ui_story_1020_10201101_109_dialog_content = "あの巨像たちは、私の偉業を成し遂げるため、コアを使い果たしたんだよ。",
  ui_story_1020_10201101_110_dialog_content = "…ソラヴァンも犠牲にするつもりなの！？\n君はこの世界を壊滅させたいの…？",
  ui_story_1020_10201101_111_dialog_content = "そんなことは望んでいないよ。",
  ui_story_1020_10201101_112_dialog_content = "君なら分かるはずだ。君は、私と同じだからね。",
  ui_story_1020_10201101_113_dialog_content = "…",
  ui_story_1020_10201101_114_dialog_content = "…ソラヴァンはどこへ行ったの？",
  ui_story_1020_10201101_115_dialog_content = "…バイスにいったい何があったの！？",
  ui_story_1020_10201101_116_dialog_content = "…",
  ui_story_1020_10201101_117_dialog_content = "（…どんどん、暗くなる…）",
  ui_story_1020_10201101_118_dialog_content = "覚えておくんだよ。光は君の両目をふさぐものだ。\n闇こそが最も誠実な色なんだ。",
  ui_story_1020_10201101_119_dialog_content = "闇を受け入れ、闇に溶け込み、闇を君の力にするんだ。",
  ui_story_1020_10201101_120_dialog_content = "やめて！",
  ui_story_1020_10201101_121_dialog_content = "闇を君の力にするんだ。",
  ui_story_1020_10201101_122_dialog_content = "僕は、そんなものいらない！",
  ui_story_1020_10201101_123_dialog_content = "（このままじゃ、本当に闇に飲み込まれちゃう…）",
  ui_story_1020_10201102_1_dialog_content = "<color=#e8d9bb>ザザーン…</color>",
  ui_story_1020_10201102_2_dialog_content = "（暗闇の中から、ピアノの音がする…）",
  ui_story_1020_10201102_3_dialog_content = "（ここは…明るいな…）",
  ui_story_1020_10201102_4_dialog_content = "（この波打つ光は湖面だよね…）",
  ui_story_1020_10201102_5_dialog_content = "（ということは、ここは北境の…オーロラ？）",
  ui_story_1020_10201102_6_dialog_content = "（あれ？あれは何だろう…？）",
  ui_story_1020_10201102_7_dialog_content = "PlayerName。",
  ui_story_1020_10201102_8_dialog_content = "ソラヴァン！？本当にソラヴァンなの？ソラヴァン――！！",
  ui_story_1020_10201102_9_dialog_content = "先程ピアノの音が聞こえたような気がしたのですが、\nまさか、あなたの声が聞けるとは思いませんでした、PlayerName。",
  ui_story_1020_10201102_10_dialog_content = "ピアノの音…？僕も聞いたよ！\n僕も君を感知できるとは思わなかったよ！",
  ui_story_1020_10201102_11_dialog_content = "ソラヴァン、今どこにいるの！？",
  ui_story_1020_10201102_12_dialog_content = "…",
  ui_story_1020_10201102_13_dialog_content = "分かりません。",
  ui_story_1020_10201102_14_dialog_content = "…",
  ui_story_1020_10201102_15_dialog_content = "あの人が君に指示を送ったんだね？",
  ui_story_1020_10201102_16_dialog_content = "…",
  ui_story_1020_10201102_17_dialog_content = "ソラヴァン、行かないで…くれない？",
  ui_story_1020_10201102_18_dialog_content = "…",
  ui_story_1020_10201102_19_dialog_content = "申し訳ありません、PlayerName。",
  ui_story_1020_10201102_20_dialog_content = "空の末裔は、その生涯をかけて、\n自由を夢見、自由を追い続けました…",
  ui_story_1020_10201102_21_dialog_content = "この短い期間に見たデータの中で、私はあなたと出会う前の、\n空の末裔と巨像の経験してきたことを知りました…",
  ui_story_1020_10201102_22_dialog_content = "空の末裔と巨像が何代にもわたり、\n縛りから抜け出そうと努力してきた歴史を知りました。",
  ui_story_1020_10201102_23_dialog_content = "そして、今回も…",
  ui_story_1020_10201102_24_dialog_content = "私は失敗したようです。",
  ui_story_1020_10201102_25_dialog_content = "ソラヴァン…行かないで…",
  ui_story_1020_10201102_26_dialog_content = "僕たち一緒に縛りから抜け出そう。ねえ、そうしようよ。",
  ui_story_1020_10201102_27_dialog_content = "…",
  ui_story_1020_10201102_28_dialog_content = "今の私はソラヴァンであり、同時に「ガイダンス」でもあります…",
  ui_story_1020_10201102_29_dialog_content = "あるいは「ローンウルフ」であり、「サーチャー」、\n「サモナー」、「オーバーテイカー」であるかもしれません…",
  ui_story_1020_10201102_30_dialog_content = "私にできることは、先輩たちと同じように全力を尽くし、\nナビゲーターを守ることです。",
  ui_story_1020_10201102_31_dialog_content = "あなたのそばで過ごし、あなたと一緒に空を馳せたことは、\n私の生涯の中で最も美しい日々でした。",
  ui_story_1020_10201102_32_dialog_content = "私がこの縛りから抜け出すことができた日には、\nきっとまた会えるはずです。",
  ui_story_1020_10201102_33_dialog_content = "ソラヴァン…",
  ui_story_1020_10201102_34_dialog_content = "いかに多くの信号を受信しようと…",
  ui_story_1020_10201102_35_dialog_content = "ソラヴァンに「心」がある限り、\nソラヴァンの「心」に届くのはPlayerNameの声だけなのですから。",
  ui_story_1020_10201102_36_dialog_content = "…",
  ui_story_1020_10201102_37_dialog_content = "ソラヴァン…",
  ui_story_1020_10201102_38_dialog_content = "ソラヴァン！？",
  ui_story_1020_10201102_39_dialog_content = "…PlayerName…",
  ui_story_1020_10201102_40_option_content = "精神感知",
  ui_story_1020_10201102_41_dialog_content = "…",
  ui_story_1020_10201102_42_option_content = "精神感知――",
  ui_story_1020_10201102_43_dialog_content = "…",
  ui_story_1020_10201102_44_option_content = "精神感知――！！！",
  ui_story_1020_10201102_45_dialog_content = "…",
  ui_story_1020_10201102_46_option_content = "精神感知――！！！",
  ui_story_1020_10201102_47_dialog_content = "PlayerName！",
  ui_story_1020_10201102_48_dialog_content = "…",
  ui_story_1020_10201102_49_dialog_content = "感知できない…",
  ui_story_1020_10201102_50_dialog_content = "まったく…感知できない――！",
  ui_story_1020_10201102_51_dialog_content = "PlayerName…やっと気がついたね。大丈夫？",
  ui_story_1020_10201102_52_dialog_content = "PlayerNameを見ていて、アクセリアは胸が痛みました。",
  ui_story_1020_10201102_53_dialog_content = "さっきはずっと独り言を言っていて、本当に心配しました。\n幸い、ショーンがフィジェロを制圧して、ようやく目を開けたんですよ。",
  ui_story_1020_10201102_54_dialog_content = "実際は、みんなで制圧したんだ！",
  ui_story_1020_10201102_55_dialog_content = "…？",
  ui_story_1020_10201102_56_dialog_content = "僕たち全員が、ただの暗力の塊になって消えていくのを見たよ…",
  ui_story_1020_10201102_57_dialog_content = "あのような暗力に耐えられるのは、ショーンだけですね。",
  ui_story_1020_10201102_58_dialog_content = "（フィジェロは…本当に倒されたんだろうか？）",
  ui_story_1020_10201102_59_dialog_content = "（果てしない闇の中に落ちそうになった時、\n聞こえて来たピアノの音と光る湖面は、何だったんだろう…）",
  ui_story_1020_10201102_60_dialog_content = "PlayerName、いったい何があったんですか？\nフィジェロを強制感知していた時、おかしな声を出していましたが…",
  ui_story_1020_10201102_61_dialog_content = "ソラヴァンを感知したんだ…",
  ui_story_1020_10201102_62_dialog_content = "ソラヴァン！？どこにいるんですか？",
  ui_story_1020_10201102_63_dialog_content = "ソラヴァンは…僕を守るために、飛んで行ってしまいました…",
  ui_story_1020_10201102_64_dialog_content = "…",
  ui_story_1020_10201102_65_dialog_content = "PlayerName、ソラヴァンのことは、後でゆっくり考えませんか？\nまずは大元帥様たちと合流しましょう。",
  ui_story_1020_10201102_66_dialog_content = "独りでここにいるのは本当に危険です。この子たち3人が駆け付けてくれなければ、\n私たちはフィジェロにやられていたかもしれません。",
  ui_story_1020_10201102_67_dialog_content = "ありがとう…",
  ui_story_1020_10201102_68_dialog_content = "行きましょう。\n危機が過ぎれば、ソラヴァンはきっと戻ってきます！",
  ui_story_1020_10201102_69_dialog_content = "はい…",
  ui_story_1020_10201102_70_dialog_content = "（エンジニア…フィジェロの意識の中で見た…）",
  ui_story_1020_10201102_71_dialog_content = "（手がかりを探すなら…）",
  ui_story_1020_10201102_72_dialog_content = "PlayerName、さっきは本当に危険だったんですよ。\nあの子たちが駆け付けてくれなかったら、私たちはおそらく今頃――",
  ui_story_1020_10201102_73_dialog_content = "分かった…！",
  ui_story_1020_10201102_74_dialog_content = "PlayerName、まずは大元帥様たちと合流しましょう！",
  ui_story_1020_10201201_1_dialog_content = "ブーブー！",
  ui_story_1020_10201201_2_dialog_content = "ブールは…今度こそ防御モジュールに問題はないって\n言ってるんだよね？",
  ui_story_1020_10201201_3_dialog_content = "おそらくね。アハ…ハハハハハ！",
  ui_story_1020_10201201_4_dialog_content = "ふぅ…指も肩も、凝っちゃったわ――",
  ui_story_1020_10201201_5_dialog_content = "皆の援護のおかげで、想定より早く完成したわ…\n脳だけで勝負する戦いがこんなに大変だとは思わなかった…",
  ui_story_1020_10201201_6_dialog_content = "この太古のマシン、本当に厄介ね！",
  ui_story_1020_10201201_7_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10201201_8_dialog_content = "は？新しいプログラムにエラーが出たっていうの…？",
  ui_story_1020_10201201_9_dialog_content = "エンジニアがどこかであたしたちを攻撃してるのかしら…\nそれとも「ガーディアン」のモジュール自体の問題なの？",
  ui_story_1020_10201201_10_dialog_content = "<size=45>ブブブブー！！</size>",
  ui_story_1020_10201201_11_dialog_content = "もっと…調べてみないと…",
  ui_story_1020_10201201_12_dialog_content = "あら？ユリシーズはどこに行ったの？取材させてちょうだい！\nユリシーズはこのマシンにいったい何をしたのよ…",
  ui_story_1020_10201201_13_dialog_content = "複雑な計算処理のできるコアが他に必要ってことかしら…？",
  ui_story_1020_10201201_14_dialog_content = "ブブ？",
  ui_story_1020_10201201_15_dialog_content = "ユリシーズは先刻何か刺激を受けたようで、\nあちらで目を閉じたまま動かなくなりました。",
  ui_story_1020_10201201_16_dialog_content = "レインハト、マシンも安定して、\n超戦士が攻撃してこなくなった今のうちに…",
  ui_story_1020_10201201_17_dialog_content = "残りの超戦士を早急に処理して、\nさっきみたいな襲撃が起こるのを防ぎましょ。",
  ui_story_1020_10201201_18_dialog_content = "私も同意見よ。それに、この超戦士たちは曲がりなりにも啓光の兵士でしょ…\nブラック・アンブレラなら治療できるかもしれない。",
  ui_story_1020_10201201_19_dialog_content = "…超戦士たちはプロトタイプによってコントロールされているようだ。\nおそらく、アルゴルがモジュールを構築し終えた後でなければ、動かせないだろう。",
  ui_story_1020_10201201_20_dialog_content = "アルゴル、現段階で我々に何ができる？",
  ui_story_1020_10201201_21_dialog_content = "この超戦士たちを処理するのは、確かに難しいわ。",
  ui_story_1020_10201201_22_dialog_content = "ケーブルがもっと深い所まで埋め込まれてるかもしれないし、\n人力で処理するなら、少なくとも半月以上かかるわね。",
  ui_story_1020_10201201_23_dialog_content = "それに、他のリスクが発現する可能性もある…\n「ガーディガン」のモジュールでコアを補強する方法は通用しないみたいだし…",
  ui_story_1020_10201201_24_dialog_content = "エンジニアと「ガーディアン」から完全に独立した防御システムを造って、\nカナン城の防御体制の穴を埋めるしかないわね！",
  ui_story_1020_10201201_25_dialog_content = "つまり、他の技術にいっさい頼らず、啓光自身の防御システムを造るってこと？\n啓光がシステムを自主開発するの？",
  ui_story_1020_10201201_26_dialog_content = "その通りよ。ただ、今はコアの計算能力が足りないわ。\nいつ来るとも知れない攻撃を防ぎながら、防御システムを構築するなんて難易度倍増よ。",
  ui_story_1020_10201201_27_dialog_content = "他のコンピューターコアが、\nあたしと同時進行でデータを処理してくれればいいんだけど…",
  ui_story_1020_10201201_28_dialog_content = "アルゴル、カナン城にある他のコンピューターを動員すれば、足りるか？",
  ui_story_1020_10201201_29_dialog_content = "今動員可能な、使われていないコンピューターなんていくらもないでしょ。\n大した足しにならないわ。",
  ui_story_1020_10201201_30_dialog_content = "使われていないコンピューターではない。\nカナン城にあるすべてのコンピューターだ。",
  ui_story_1020_10201201_31_dialog_content = "すべてのコンピューター？\nもし全部のコアの計算力を使えるなら…大きな力になるわ。",
  ui_story_1020_10201201_32_dialog_content = "ただ、そんなことをすれば、工事設備も全部稼働停止になるし、\n城門も開いて、生命維持システムも止まるわよ…",
  ui_story_1020_10201201_33_dialog_content = "たとえ1分でも、そんな重要な設備が停止したら、\nこの大きなカナン城が存続できると思う？",
  ui_story_1020_10201201_34_dialog_content = "…",
  ui_story_1020_10201201_35_dialog_content = "それに新しく構築したシステムも検証が必要なの。\n複雑な計算処理が可能なコアがなければ、結局すぐにシステムが崩壊するわ。",
  ui_story_1020_10201201_36_dialog_content = "あたしが今やってるのは、エンジニアの行動を予測して、\n彼と駆け引きしてるにすぎないの。",
  ui_story_1020_10201201_37_dialog_content = "ブー！ブー！ブー！",
  ui_story_1020_10201201_38_dialog_content = "ダメよ。",
  ui_story_1020_10201201_39_dialog_content = "ブーブー！！",
  ui_story_1020_10201201_40_dialog_content = "あなたもプロトタイプの一部でしょ。",
  ui_story_1020_10201201_41_dialog_content = "ブー！ブー！ブー！",
  ui_story_1020_10201201_42_dialog_content = "ブールは、何か方法を思いついたのか？",
  ui_story_1020_10201201_43_dialog_content = "自分がカナン城の防御システムのコアになるって言ってるのよ。",
  ui_story_1020_10201201_44_dialog_content = "ブールが…？そんなのムリでしょ？",
  ui_story_1020_10201201_45_dialog_content = "ええ。ブールはプロトタイプの一部だし、\n手の焼ける、ただの助手でしかないわ。",
  ui_story_1020_10201201_46_dialog_content = "ブーブー！！",
  ui_story_1020_10201201_47_dialog_content = "でも、ブールはかなりアルゴル博士の助けになってたよ！",
  ui_story_1020_10201201_48_dialog_content = "ブー！",
  ui_story_1020_10201201_49_dialog_content = "ピピッ――",
  ui_story_1020_10201201_50_dialog_content = "アルゴル、1号の<color=#FFB400>メンテナンス扉</color>を開けてください。",
  ui_story_1020_10201201_51_dialog_content = "1号の<color=#FFB400>コア</color>で、カナン城を守ってください。",
  ui_story_1020_10201201_52_dialog_content = "え…？",
  ui_story_1020_10201201_53_dialog_content = "1号は今から人工知能を放棄し、データ攻撃を処理する、ただの機械になります。",
  ui_story_1020_10201201_54_dialog_content = "1号、あなたにたくさんのプログラムをインストールしたのは、\n知能を放棄して、カナン城を守るただの機械にするためじゃないわ。",
  ui_story_1020_10201201_55_dialog_content = "1号は知っています。アルゴルは1号が光霊同士の複雑な会話情報を処理できるようになり、\nアルゴルの友だちになることを望んでいます。",
  ui_story_1020_10201201_56_dialog_content = "でも、今、アルゴルには1号が必要です。\n1号のコアを使って、カナン城を守ってください。",
  ui_story_1020_10201201_57_dialog_content = "ダメよ。",
  ui_story_1020_10201201_58_dialog_content = "1号のコアで、カナン城を守ってください。",
  ui_story_1020_10201201_59_dialog_content = "ダメって言ってるでしょ！！",
  ui_story_1020_10201201_60_dialog_content = "ピピッ――1号のコアで、カナン城を守ってください。",
  ui_story_1020_10201201_61_dialog_content = "ダメと言ったらダメ！",
  ui_story_1020_10201201_62_dialog_content = "ダメと言ったらダメ！",
  ui_story_1020_10201201_63_dialog_content = "…",
  ui_story_1020_10201201_64_dialog_content = "1号…あなた、いつから、そんなごまかし方を覚えたのよ…？",
  ui_story_1020_10201201_65_dialog_content = "1号は長い間考えて、ようやく分かりました。\n「ピピピピッ」、アルゴルはあの時、実は何も言っていませんでした。",
  ui_story_1020_10201201_66_dialog_content = "…",
  ui_story_1020_10201201_67_dialog_content = "そんなこと言われたら、余計に別れがたくなるじゃない。",
  ui_story_1020_10201201_68_dialog_content = "1号も分かっています。しかし、これは1号からのお願いです。\nアルゴル、1号のコアを使って、カナン城を守ってください。",
  ui_story_1020_10201201_69_dialog_content = "カナン城を守るってことが、どういうことか分かってるの？",
  ui_story_1020_10201201_70_dialog_content = "複雑な、たくさんのケーブルにつながれて、\n悪意あるデータが頭の中に侵入してくるのよ…",
  ui_story_1020_10201201_71_dialog_content = "そのデータがあなたの思考能力を封じて…\nさらには、あなたに暗鬼みたいに啓光を攻撃させようとするのよ！",
  ui_story_1020_10201201_72_dialog_content = "ただの機能移行じゃないの。創造性と適応能力を完全に放棄して、\n制御指令を実行するだけの、何千何万の門になるってことなのよ！？",
  ui_story_1020_10201201_73_dialog_content = "1号はあれこれ考えません。アルゴルは以前1号に言いました。\n思考とは光霊の特徴だと。",
  ui_story_1020_10201201_74_dialog_content = "アルゴルのような知能の高い先生がいれば、\n1号は思考を放棄し、カナン城を守ることだけに専念できます。",
  ui_story_1020_10201201_75_dialog_content = "あたしにコーヒーを淹れることさえ、嫌がってたくせに…",
  ui_story_1020_10201201_76_dialog_content = "1号は知っています。アルゴルが望んでいたのは執事ではなく、\n一緒にふざけ合える仲間です。",
  ui_story_1020_10201201_77_dialog_content = "1号にも条件があります。1号がここに住むようになったら、\nアルゴルの研究室のように、植物を置いてください。",
  ui_story_1020_10201201_78_dialog_content = "2号や3号ができた時には、1号のような筐体ではなく、\nもっと動きやすい筐体を造ってあげてください…",
  ui_story_1020_10201201_79_dialog_content = "アルゴルはいつも、1号はポストにそっくりだから、\n口に手紙を放り込みたくなると言っていました。",
  ui_story_1020_10201201_80_dialog_content = "…",
  ui_story_1020_10201201_81_dialog_content = "それと、1つアルゴルに伝えておかなければならないことがあります…",
  ui_story_1020_10201201_82_dialog_content = "1号はPlayerNameさんと感知でつながった時、\n勝手にアルゴルの知らないことをしました。",
  ui_story_1020_10201201_83_dialog_content = "…？",
  ui_story_1020_10201201_84_dialog_content = "でも、まさにあの時の感知で1号は、\nPlayerNameさんは全意識を託すことのできる相手だと分かりました。",
  ui_story_1020_10201201_85_dialog_content = "アルゴルが友だちを探しているなら、\n1号はPlayerNameさんを推薦します。",
  ui_story_1020_10201201_86_dialog_content = "…",
  ui_story_1020_10201201_87_dialog_content = "さようなら、アルゴル。",
  ui_story_1020_10201201_88_dialog_content = "1号は、アルゴルの作ってくれた新しいこの表情がとても気に入りました。",
  ui_story_1020_10201201_89_dialog_content = "ピピッ――ピピッ――ピッ――ピーッ――",
  ui_story_1020_10201201_90_dialog_content = "<color=#e8d9bb>カチャッ――</color>",
  ui_story_1020_10201201_91_dialog_content = "ブー…",
  ui_story_1020_10201201_92_dialog_content = "ピピピピッ。",
  ui_story_1020_10201201_93_dialog_content = "…",
  ui_story_1020_10201201_94_dialog_content = "大元帥、他に方法はないのかな？",
  ui_story_1020_10201201_95_dialog_content = "…",
  ui_story_1020_10201201_96_dialog_content = "これが…今考え得る唯一の方法でしょうね。\nエンジニアが初めて現れた時、実は私もそう思ってたの。",
  ui_story_1020_10201201_97_dialog_content = "アルゴル、お前にとって、ロボットはロボットではなく、\n友人なのだな。",
  ui_story_1020_10201201_98_dialog_content = "唯一のね。",
  ui_story_1020_10201201_99_dialog_content = "でも、友達をこんなふうに手に持ってるヤツがどこにいるっていうの？アハハハ…！",
  ui_story_1020_10201201_100_dialog_content = "まったく、ポストのくせに偉そうにしちゃって…",
  ui_story_1020_10201201_101_dialog_content = "身勝手なんだから…！",
  ui_story_1020_10201201_102_dialog_content = "アルゴル、コアが用意できた今、\nカナン城の「重要な設備を1分間停止する」という条件は有効か？",
  ui_story_1020_10201201_103_dialog_content = "…？",
  ui_story_1020_10201201_104_dialog_content = "カナン城のあらゆるコンピューターの計算能力を集結し、\nお前がコアの変換を完了するまで支援しよう。",
  ui_story_1020_10201201_105_dialog_content = "ブー！ブー！ブー！",
  ui_story_1020_10201201_106_dialog_content = "1分間じゃ無理だわ。",
  ui_story_1020_10201201_107_dialog_content = "ならば、10分だ！すべてのコンピューターを動員する！\nそれにより生じる空白は人力で埋めればいい。それでどうだ？",
  ui_story_1020_10201201_108_dialog_content = "それ…本気で言ってるの？",
  ui_story_1020_10201201_109_dialog_content = "もちろんだ。",
  ui_story_1020_10201201_110_dialog_content = "アルゴル、啓光の存続を支えてきたのは、改造光霊じゃないわ。",
  ui_story_1020_10201201_111_dialog_content = "その太古のマシンでもありません。",
  ui_story_1020_10201201_112_dialog_content = "その通りだ。啓光は600年以上「ガーディアン」に支えられ、\n存続してきたとユリシーズは考えているようだが…",
  ui_story_1020_10201201_113_dialog_content = "軍人こそ啓光を守ってきた厚く堅固な壁だと私は確信している。",
  ui_story_1020_10201201_114_dialog_content = "たった10分も持ちこたえられないようでは、アストラ大陸で\n啓光が存続していくことは不可能だ。危険であろうとやるしかない！",
  ui_story_1020_10201201_115_dialog_content = "お前さえ良ければ、その手に私の命も預けよう。\n私もお前を信じる友人だからだ。",
  ui_story_1020_10201201_116_dialog_content = "…",
  ui_story_1020_10201201_117_dialog_content = "私もよ。",
  ui_story_1020_10201201_118_dialog_content = "あたしもだよ！",
  ui_story_1020_10201201_119_dialog_content = "…自分を信じてくれる「友達」と、\nできもしないことに挑戦するってこういうこと？",
  ui_story_1020_10201201_120_dialog_content = "そんなの…おこちゃまのオママゴトと同じじゃないの、アハハハ！",
  ui_story_1020_10201201_121_dialog_content = "でも、やってみるわ。",
  ui_story_1020_10201201_122_dialog_content = "わーい！ゲームはやっぱり友だちとやるのが一番だよね！",
  ui_story_1020_10201201_123_dialog_content = "そうと決まれば、始めるぞ！\nヒイロ、すぐに戦時緊急全域チャネルに接続しろ。指令を出す。",
  ui_story_1020_10201201_124_dialog_content = "承知しました！",
  ui_story_1020_10201201_125_dialog_content = "<color=#e8d9bb>ピピッ――</color>",
  ui_story_1020_10201201_126_dialog_content = "大元帥様。",
  ui_story_1020_10201201_127_dialog_content = "おおっ？このチャネルは！一生使うことねえって思ってたが。",
  ui_story_1020_10201201_128_dialog_content = "今からカナン城すべてのコンピューターを緊急動員する。\nそれにより生じる空白は人力で埋める。10分間持ちこたえろ。",
  ui_story_1020_10201201_129_dialog_content = "その間のカナン城の防御はすべて私たちにかかっている。",
  ui_story_1020_10201201_130_dialog_content = "おお、やってやるぜ。指示を出せ、レインハト！",
  ui_story_1020_10201201_131_dialog_content = "地上近くの隔離層、守衛フロア、緩衝層は暗鬼の脅威にさらされることになる。\nバートン、お前は今言ったエリアを担当しろ。",
  ui_story_1020_10201201_132_dialog_content = "了解！",
  ui_story_1020_10201201_133_dialog_content = "キシローナは即刻カナン城へ戻り、外から暗鬼を攻めろ。\n施工部隊がすでに住民を移動させてるはずだ。",
  ui_story_1020_10201201_134_dialog_content = "了解。",
  ui_story_1020_10201201_135_dialog_content = "ヒイロには、農業エリア、鉱山エリア、工業エリアおよび貯蔵エリアを任せる。",
  ui_story_1020_10201201_136_dialog_content = "一部の軍人と住民が機械の稼働を維持するため、カナン城に残っている。\n随時上層部と深層部を支援させるように。",
  ui_story_1020_10201201_137_dialog_content = "承知しました。",
  ui_story_1020_10201201_138_dialog_content = "私は？",
  ui_story_1020_10201201_139_dialog_content = "科学棟エリアには実験用暗鬼が多く保管されている。\nラス、部下に暗鬼が保管されている倉庫を探させろ。何が何でも、上層部へは行かせるな。",
  ui_story_1020_10201201_140_dialog_content = "了解よ！",
  ui_story_1020_10201201_141_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10201201_142_dialog_content = "「ガーディアン」のシステムを迂回し、新しい檻を築き、\nこの地下都市に身を隠し続けようとするとは…",
  ui_story_1020_10201201_143_dialog_content = "あなたたちは、闇にすっかり慣れてしまったのですね…",
  ui_story_1020_10201201_144_dialog_content = "ユリシーズの身体が…どういうことよ…",
  ui_story_1020_10201201_145_dialog_content = "私のミスです…超戦士を倒すのに集中するあまり、\nユリシーズが手術台に上がったのに気づかなかったようです。",
  ui_story_1020_10201201_146_dialog_content = "とはいえ…この短時間で改造を終えたというのですか？",
  ui_story_1020_10201201_147_dialog_content = "…いや、改造はかなり前から、すでに始まっていたのだ。\n今さっきのことではない。",
  ui_story_1020_10201201_148_dialog_content = "防御に終わりはありません。正面から立ち向かってこそ…\nこの身体があれば、もうコアを守る必要もなくなるのです！",
  ui_story_1020_10201201_149_dialog_content = "ユリシーズ、一歩でも動けば、この刀であなたの首を落とします。",
  ui_story_1020_10201201_150_dialog_content = "待て――まずは退がれ！",
  ui_story_1020_10201201_151_dialog_content = "言ったでしょう？私は「暗面の脅威」など恐れたことはないと…",
  ui_story_1020_10201201_152_dialog_content = "彼らが皆、失敗しようとも…",
  ui_story_1020_10201201_153_dialog_content = "私が自分でやればいいだけのことです！",
  ui_story_1020_10201201_154_dialog_content = "<color=#e8d9bb>ピーッ、ピーッ――</color>",
  ui_story_1020_10201201_155_dialog_content = "…！データのオーバーロード？まさか、ユリシーズのせいかしら？",
  ui_story_1020_10201201_156_dialog_content = "…",
  ui_story_1020_10201201_157_dialog_content = "おい、レインハト。任務は続行すんのか？",
  ui_story_1020_10201201_158_dialog_content = "ブール、コマンド、ジャンプ！",
  ui_story_1020_10201201_159_dialog_content = "ブブブブ！",
  ui_story_1020_10201201_160_dialog_content = "全員、計画通りに動け。どうあってもアルゴルにコア交換を完成させる！\nここは私に任せておけ！",
  ui_story_1020_10201201_161_dialog_content = "承知しました！",
  ui_story_1020_10201201_162_dialog_content = "了解！",
  ui_story_1020_10201201_163_dialog_content = "了解だ、レインハト！",
  ui_story_1020_10201201_164_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_1020_10201201_165_dialog_content = "みんな、気をつけて！超戦士の倉庫がまた開いたわよ！",
  ui_story_1020_10201201_166_dialog_content = "ユリシーズを狙ってきたのかしら…",
  ui_story_1020_10201201_167_dialog_content = "この身体さえあれば、もうコアを守る必要などありません！",
  ui_story_1020_10201201_168_dialog_content = "愚かだわ！身体さえ強化すれば、無敵になれるとでも思ってるの…",
  ui_story_1020_10201201_169_dialog_content = "その程度の改造、エンジニアがその気になれば、\nたった1本のケーブルでコントロールできるのよ！",
  ui_story_1020_10201201_170_dialog_content = "倉庫内はケーブルだらけ…",
  ui_story_1020_10201201_171_dialog_content = "レインハト！全員倉庫から出るように言って！\nケーブルにコントロールされてしまうかもしれないわ！",
  ui_story_1020_10201201_172_dialog_content = "ここは、あなた1人がいれば十分よ。\nあたしは新しい防御システムの安全を守らなきゃならない。",
  ui_story_1020_10201201_173_dialog_content = "アルゴルの言った通りにしろ！",
  ui_story_1020_10201201_174_dialog_content = "私を何だと思ってるの？超戦士がいるっていうのに、\nあんたたち2人を残していくとでも思った？",
  ui_story_1020_10201201_175_dialog_content = "大元帥、援護するわ！",
  ui_story_1020_10201201_176_dialog_content = "あたしもだよ！",
  ui_story_1020_10201201_177_dialog_content = "超戦士は任せたわ！ユリシーズをしっかり見ててよ！",
  ui_story_1020_10201201_178_dialog_content = "ブール、接続ポートを探して！超戦士とプロトタイプの接続を切断するわ！\nそれが終わったらコアを切り換えるわよ！",
  ui_story_1020_10201201_179_dialog_content = "ブブブブ！",
  ui_story_1020_10201301_1_dialog_content = "ブーブー！",
  ui_story_1020_10201301_2_dialog_content = "やったわ…成功よ！アハハハハ！",
  ui_story_1020_10201301_3_dialog_content = "1号！あなた、やっぱりすごいわ！！",
  ui_story_1020_10201301_4_dialog_content = "ブー！",
  ui_story_1020_10201301_5_dialog_content = "大元帥様、先程大きな振動音が聞こえましたが、\nご無事ですか――",
  ui_story_1020_10201301_6_dialog_content = "シッ…今の、聞こえた？",
  ui_story_1020_10201301_7_dialog_content = "『1011X。』",
  ui_story_1020_10201301_8_dialog_content = "『01X11。』",
  ui_story_1020_10201301_9_dialog_content = "『X1010。』",
  ui_story_1020_10201301_10_dialog_content = "教授は…どうしたのでしょう？",
  ui_story_1020_10201301_11_dialog_content = "…",
  ui_story_1020_10201301_12_dialog_content = "『0111X。』",
  ui_story_1020_10201301_13_dialog_content = "『0X111。』",
  ui_story_1020_10201301_14_dialog_content = "…日蝕語か？",
  ui_story_1020_10201301_15_dialog_content = "…？？？",
  ui_story_1020_10201301_16_dialog_content = "少しぎこちないようだが、間違いない。\n暗鬼が意思疎通を図る時に使う言葉だ。",
  ui_story_1020_10201301_17_dialog_content = "…PlayerNameがフィジェロを感知していた時も、\nあんなふうに独り言を言っていました…",
  ui_story_1020_10201301_18_dialog_content = "1011X。",
  ui_story_1020_10201301_19_dialog_content = "今みたいなことですか…？",
  ui_story_1020_10201301_20_dialog_content = "待って――今何て言ったの？ゆっくり話してみて。",
  ui_story_1020_10201301_21_dialog_content = "1…0…1…1…X…",
  ui_story_1020_10201301_22_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10201301_23_dialog_content = "PlayerNameも、日蝕語が分かるんですか！？",
  ui_story_1020_10201301_24_dialog_content = "不思議なんですが…聞き取れているわけじゃないのに、\n簡単に復唱できるんです…",
  ui_story_1020_10201301_25_dialog_content = "どうりで…あなたがブールを感知した時に記録した情報と似ているわ！",
  ui_story_1020_10201301_26_dialog_content = "日蝕語とプロトタイプの言語との間には関連があったのね…",
  ui_story_1020_10201301_27_dialog_content = "大多数の暗鬼は普段何も分からない状態にあって、\n攻撃する時にだけ、統一された指令に従う――",
  ui_story_1020_10201301_28_dialog_content = "指令…言語…全部、つながってきたわね！",
  ui_story_1020_10201301_29_dialog_content = "『2355X11874…』",
  ui_story_1020_10201301_30_dialog_content = "『32456901X14361…』",
  ui_story_1020_10201301_31_dialog_content = "（ユリシーズ教授が今エンジニアと会話してるなら…）",
  ui_story_1020_10201301_32_dialog_content = "感知能力を使えば…",
  ui_story_1020_10201301_33_dialog_content = "PlayerName、何をするつもり？\nユリシーズはたくさんの人を殺してきた。当然の報いだわ！",
  ui_story_1020_10201301_34_dialog_content = "でも、これがソラヴァンとバイスの行方をつかむ唯一の方法かもしれない…",
  ui_story_1020_10201301_35_dialog_content = "PlayerName！",
  ui_story_1020_10201301_36_dialog_content = "これ以上感知能力を使ってはいけません…\nもう限界です。",
  ui_story_1020_10201301_37_dialog_content = "これが僕の限界…",
  ui_story_1020_10201301_38_dialog_content = "でも、これが僕にできる唯一のことだとしたら…",
  ui_story_1020_10201301_39_option_content = "精神感知――",
  ui_story_1020_10201301_40_dialog_content = "リングを受け入れるか、私の燃料となるか。",
  ui_story_1020_10201301_41_dialog_content = "私は決してあなたに屈しない。何度言ったら分かるのですか…",
  ui_story_1020_10201301_42_dialog_content = "姿を変えた今の私はもう、死に対する恐怖など超越しています…",
  ui_story_1020_10201301_43_dialog_content = "死者を研究し、生者を死者に変えてきた…\n私にはもう恐怖などありません。",
  ui_story_1020_10201301_44_dialog_content = "ユリシーズ、お前には常人にはない胆力がある。",
  ui_story_1020_10201301_45_dialog_content = "昔の私のようだ。",
  ui_story_1020_10201301_46_dialog_content = "フッ…ハハハハ…似ているだけですか？",
  ui_story_1020_10201301_47_dialog_content = "あの時、ラヴィルさえ去って行った…広い実験室の中で、私だけが、\n科学研究の道を選んだ者たちの初心を覚えていたのです…",
  ui_story_1020_10201301_48_dialog_content = "暗鬼が強大たる原因を突き止め、光霊が存続する方法を見つけ出す――",
  ui_story_1020_10201301_49_dialog_content = "資料の中で、あなたの名前を見つけ…あなたは私に、\n埃の積もった歴史書を開き、秘密裏に「ガーディアン」を研究させた…",
  ui_story_1020_10201301_50_dialog_content = "その時から、私には見えるようになったのです。暗鬼を製造する機械化された工場、\n巨像を操縦し、アストラ大陸を爆撃する空の末裔…",
  ui_story_1020_10201301_51_dialog_content = "そして、地下に隠れて生きる光霊たちが。",
  ui_story_1020_10201301_52_dialog_content = "青く美しい惑星だったアイオリアが炎の赤色に染まり、\nあっという間に黒く灰に包まれた死の惑星に変わってしまった…",
  ui_story_1020_10201301_53_dialog_content = "極光が空を覆い、惑星の軌道にズレが生じ…",
  ui_story_1020_10201301_54_dialog_content = "科学技術、戦争、憎悪、命…",
  ui_story_1020_10201301_55_dialog_content = "この世界のあらゆる残酷さを見せたのはあなたです。\nそして、私が恐怖を抱いたまま、力強く生きることを望んだのです。",
  ui_story_1020_10201301_56_dialog_content = "私の言ったことを覚えているかな？",
  ui_story_1020_10201301_57_dialog_content = "「暗鬼に勝ちたいなら、大胆にならなければいけない！」",
  ui_story_1020_10201301_58_dialog_content = "「もっと大胆にならなければ！」",
  ui_story_1020_10201301_59_dialog_content = "その声を聞きながら、私はよく自分が誰であるか、\n果たして過去に生きてるのか、未来に生きているのか、分からなくなりました。",
  ui_story_1020_10201301_60_dialog_content = "それだけではありません。なぜ私なのかと考えました。",
  ui_story_1020_10201301_61_dialog_content = "しかし、その恐怖を乗り越えた時、分かったのです。\n私、ユリシーズは今後何も恐れるものはなくなったと。",
  ui_story_1020_10201301_62_dialog_content = "残酷な世界も、あなたのことも。",
  ui_story_1020_10201301_63_dialog_content = "お前は確かに恐怖を克服した。\nだが、新たな恐怖が現れたろう？",
  ui_story_1020_10201301_64_dialog_content = "何のことです？",
  ui_story_1020_10201301_65_dialog_content = "見てみるか？",
  ui_story_1020_10201301_66_dialog_content = "…",
  ui_story_1020_10201301_67_dialog_content = "デニール。",
  ui_story_1020_10201301_68_dialog_content = "先生。",
  ui_story_1020_10201301_69_dialog_content = "あなたがシンポジウムで提唱した暗力術に関する推測ですが、\nとても研究価値の高いテーマですね。",
  ui_story_1020_10201301_70_dialog_content = "ありがとうございます、先生。\nでも、今の啓光では、私の研究は支持を得られないでしょう。",
  ui_story_1020_10201301_71_dialog_content = "戦争が終われば、研究資源が回収されてきます。\nそうしたら、カナン城周辺に実験室を建て、あなたは自分のやりたい研究をすればいい。",
  ui_story_1020_10201301_72_dialog_content = "…ありがとうございます、先生。",
  ui_story_1020_10201301_73_dialog_content = "デニール、進捗はどうですか？",
  ui_story_1020_10201301_74_dialog_content = "先生、私が培養したシードです。",
  ui_story_1020_10201301_75_dialog_content = "素晴らしい…とても美しいですね…",
  ui_story_1020_10201301_76_dialog_content = "このシードを我々の兵士に埋め込むことができれば…",
  ui_story_1020_10201301_77_dialog_content = "先生！これはただの研究です。\nそんなことをすれば、光霊はシードの暗力にのみこまれてしまいます。",
  ui_story_1020_10201301_78_dialog_content = "たかが光霊がのみこまれるだけのことでしょう…\n暗鬼がどうやって、この世界をのみこんだのか知っているのですか？",
  ui_story_1020_10201301_79_dialog_content = "…？",
  ui_story_1020_10201301_80_dialog_content = "デニール、あなたの研究は非常に優れています。\n時機は熟しました。光霊もついに生まれ変わる時が来たのです。",
  ui_story_1020_10201301_81_dialog_content = "…何をするつもりですか？",
  ui_story_1020_10201301_82_dialog_content = "シードを渡してください。",
  ui_story_1020_10201301_83_dialog_content = "…",
  ui_story_1020_10201301_84_dialog_content = "渡しなさい。",
  ui_story_1020_10201301_85_dialog_content = "お断りします。",
  ui_story_1020_10201301_86_dialog_content = "啓光を敵に回したいのですか？",
  ui_story_1020_10201301_87_dialog_content = "いいえ…先生。",
  ui_story_1020_10201301_88_dialog_content = "忘れてはいけません。\n私がいなければ、あなたの研究もなかったのですよ。",
  ui_story_1020_10201301_89_dialog_content = "…",
  ui_story_1020_10201301_90_dialog_content = "思い出したぞ。ノラとかいう啓光のあの小娘は、\nお前がずっとなりたいと思っていた理想像そのものだ。",
  ui_story_1020_10201301_91_dialog_content = "違います…",
  ui_story_1020_10201301_92_dialog_content = "お前の会心の作、傑作は「人造陽光計画」だったな？",
  ui_story_1020_10201301_93_dialog_content = "ユリシーズ、お前の才能を認めよう。\nその証たるリングを受け入れるんだ。",
  ui_story_1020_10201301_94_dialog_content = "あなたに認められる必要などありません。\n私は永遠に屈しない！",
  ui_story_1020_10201301_95_dialog_content = "（多くの人を犠牲にし、残酷な実験を繰り返してきたユリシーズ教授と、\nエンジニアに決して屈しようとしないユリシーズ教授…）",
  ui_story_1020_10201301_96_dialog_content = "（どうしてだろう？）",
  ui_story_1020_10201301_97_dialog_content = "意外かな、空の末裔？",
  ui_story_1020_10201301_98_dialog_content = "思った通りだ…僕が感知能力を使うと…僕が見えるんだね…",
  ui_story_1020_10201301_99_dialog_content = "どうして…？",
  ui_story_1020_10201301_100_dialog_content = "巨像が私を「見た」から、私にも君が「見える」んだよ。",
  ui_story_1020_10201301_101_dialog_content = "自我意識における「自我」とは、想像に基づく一種の参照にすぎず、\n知能といわれるものも、もう一つの知能の器となる。",
  ui_story_1020_10201301_102_dialog_content = "より高度な知能のね。",
  ui_story_1020_10201301_103_dialog_content = "太古のマシンは私の器にすぎない。\nあのファントムもそうだ。彼も、まもなくそうなる。",
  ui_story_1020_10201301_104_dialog_content = "…ユリシーズ教授、リングを受け入れちゃいけません！",
  ui_story_1020_10201301_105_dialog_content = "彼に、君の声は聞こえないよ。",
  ui_story_1020_10201301_106_dialog_content = "…",
  ui_story_1020_10201301_107_dialog_content = "必ず見つけてみせる…ソラヴァンも、バイスも！",
  ui_story_1020_10201301_108_dialog_content = "いいだろう。",
  ui_story_1020_10201301_109_dialog_content = "前に光が私たちを別空間に閉じ込めた。\nあそこなら、私が「見たい」ものがあるかもしれない。",
  ui_story_1020_10201301_110_dialog_content = "光輝く湖面…",
  ui_story_1020_10201301_111_dialog_content = "分かったでしょう？私はリングを受け入れません。\nこんな簡単に死ぬつもりもありません…",
  ui_story_1020_10201301_112_dialog_content = "そんな姿になってまで、もがいて何の意味がある？",
  ui_story_1020_10201301_113_dialog_content = "私がどんな姿になろうと構いません。\nしかし、光霊がいかにして生き延びていくべきかは、必ず皆に伝えます。",
  ui_story_1020_10201301_114_dialog_content = "この世界で、お前を理解できるのは私だけだ。\nだが、その意志を尊重しよう。",
  ui_story_1020_10201301_115_dialog_content = "何をするつもり？",
  ui_story_1020_10201301_116_dialog_content = "手助けだよ。",
  ui_story_1020_10201301_117_dialog_content = "啓光には、いつの時代も優秀な科学者がいる。",
  ui_story_1020_10201301_118_dialog_content = "プロトタイプと科学者がなくなっても、私たちは他の場所で会えるよ。\n私の座標を君は知っているはずだ。",
  ui_story_1020_10201301_119_dialog_content = "…",
  ui_story_1020_10201301_120_dialog_content = "覚えておくんだ。光には、まやかしがある。\n光が隠そうとする闇の色こそ、この世界の真実だ。",
  ui_story_1020_10201301_121_dialog_content = "闇を受け入れ、闇に溶け込み、闇を君の力にするんだ。",
  ui_story_1020_10201301_122_dialog_content = "ううっ――",
  ui_story_1020_10201301_123_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10201301_124_dialog_content = "PlayerName、頭は大丈夫？",
  ui_story_1020_10201301_125_dialog_content = "僕は大丈夫です。でも、ユリシーズ教授が…",
  ui_story_1020_10201301_126_dialog_content = "うわああああああ――！！",
  ui_story_1020_10201301_127_dialog_content = "ブブー！ブブー！ブブー！",
  ui_story_1020_10201301_128_dialog_content = "ユリシーズ教授、それ以上進んではいけません！でなければ…",
  ui_story_1020_10201301_129_dialog_content = "<color=#e8d9bb>カチャッ――</color>",
  ui_story_1020_10201301_130_dialog_content = "…",
  ui_story_1020_10201301_131_dialog_content = "撃つのか…？私がお前たちを造ったのだぞ…\nお前たちは私を理解してくれる、そうだろう？",
  ui_story_1020_10201301_132_dialog_content = "あの様子は…フィジェロと同じです！",
  ui_story_1020_10201301_133_dialog_content = "違います。",
  ui_story_1020_10201301_134_dialog_content = "ユリシーズ教授はエンジニアに屈しませんでした。\nだから、エンジニアは教授を壊そうと…教授は今、抵抗してるんです。",
  ui_story_1020_10201301_135_dialog_content = "…",
  ui_story_1020_10201301_136_dialog_content = "大元帥様、教授をどうなさいますか？",
  ui_story_1020_10201301_137_dialog_content = "…それ以上、抵抗するな、ユリシーズ！まだ分からんのか！？",
  ui_story_1020_10201301_138_dialog_content = "光霊を救い、日蝕に対抗していると思っていたのだろうが、\n知らぬ間にお前はすでに日蝕の一員となっていたのだ！",
  ui_story_1020_10201301_139_dialog_content = "伝えてください…空の末裔君…",
  ui_story_1020_10201301_140_dialog_content = "10011000…光霊はどうすれば、生き残れるか…00！",
  ui_story_1020_10201301_141_dialog_content = "命を賭してでも…12933…究極に達することでのみ…\nようやく…11012…103001111…",
  ui_story_1020_10201301_142_dialog_content = "その可能性が…",
  ui_story_1020_10201301_143_dialog_content = "01100…",
  ui_story_1020_10201301_144_dialog_content = "違います…",
  ui_story_1020_10201301_145_dialog_content = "君は特別です…君は君の方法で…運命に立ち向かい…",
  ui_story_1020_10201301_146_dialog_content = "しかし…10011001X0…それでも…",
  ui_story_1020_10201301_147_dialog_content = "ううっ…うわあああ――",
  ui_story_1020_10201301_148_dialog_content = "1001X1000…私が変えた世界が…",
  ui_story_1020_10201301_149_dialog_content = "必ずや…10102099…あなたたちの未来になるのです…1X120…",
  ui_story_1020_10201301_150_dialog_content = "ブール！",
  ui_story_1020_10201301_151_dialog_content = "ケーブルをユリシーズの身体にある管につなげて！\nポートを見つけたわ！エンジニアとの接続を切るわよ！",
  ui_story_1020_10201301_152_dialog_content = "ああああ――！",
  ui_story_1020_10201301_153_dialog_content = "もう…手遅れです…",
  ui_story_1020_10201301_154_dialog_content = "…",
  ui_story_1020_10201301_155_dialog_content = "ユリシーズはかつて啓光に貢献したとはいえ、\n今や光霊でなくなり、ましてや啓光の者ではなくなった。",
  ui_story_1020_10201301_156_dialog_content = "カナン城を幾度も危険に陥れ、同胞の命を犠牲にした。",
  ui_story_1020_10201301_157_dialog_content = "啓光大元帥の名において、ここにユリシーズの死刑を宣告する。",
  ui_story_1020_10201301_158_dialog_content = "うわああああああ――！！",
  ui_story_1020_10201301_159_dialog_content = "殺せ！",
  ui_story_1020_10201402_1_dialog_content = "私がいなくなって…あなたたちが救われるとでも…？",
  ui_story_1020_10201402_2_dialog_content = "ラヴィル、私は実に悔しい…",
  ui_story_1020_10201402_3_dialog_content = "<color=#e8d9bb>暗潮の危機・啓光戦時療養院</color>",
  ui_story_1020_10201402_4_dialog_content = "あ…ユリシーズ、久しぶりだね。",
  ui_story_1020_10201402_5_dialog_content = "ここで君に会えるとは思わなかったよ…ラヴィル…",
  ui_story_1020_10201402_6_dialog_content = "元気…だった――",
  ui_story_1020_10201402_7_dialog_content = "また何か新しいことを思いついたのかい？",
  ui_story_1020_10201402_8_dialog_content = "…",
  ui_story_1020_10201402_9_dialog_content = "また実験が失敗したんだ。<color=#FFB400>77号シェルター</color>から戻ってきたのは、\n焼け焦げた実験台数体だけだった…",
  ui_story_1020_10201402_10_dialog_content = "今日放送で昔実験室でよく聞いていた音楽が流れたんだ…\nあ…今…何か言ったかい？",
  ui_story_1020_10201402_11_dialog_content = "…",
  ui_story_1020_10201402_12_dialog_content = "そのバッチ…ずっと付けていたんだね。",
  ui_story_1020_10201402_13_dialog_content = "そうなんだ…昨日一晩中探したんだ。\nサシャが隠しちゃってね。本当にいたずらっ子で困るよ。",
  ui_story_1020_10201402_14_dialog_content = "…",
  ui_story_1020_10201402_15_dialog_content = "サシャは最近詩を作るようになったんだ。\n読み上げるから、うまくできてるかどうか聞いてみてくれないか…",
  ui_story_1020_10201402_16_dialog_content = "ラヴィル…",
  ui_story_1020_10201402_17_dialog_content = "君はもう…共に研究と実験に明け暮れ、\nエンジニアの手がかりを探していた日のことは忘れてしまったんだな。",
  ui_story_1020_10201402_18_dialog_content = "もうこの世にはいない家族のことだけを覚えている…",
  ui_story_1020_10201402_19_dialog_content = "正直なところ、嬉しく思ってるんだよ。ハハハ…",
  ui_story_1020_10201402_20_dialog_content = "もし、私が「エンジニア」の文字を見つけなかったら、\nあの情景を見なかったら…",
  ui_story_1020_10201402_21_dialog_content = "昔のように実験室で理想を語り合うことができていたら…",
  ui_story_1020_10201402_22_dialog_content = "毎日会って初めて発する言葉はきっと…",
  ui_story_1020_10201402_23_dialog_content = "ユリシーズ、また何か新しいことを思いついたのかい？",
  ui_story_1020_10201402_24_dialog_content = "…",
  ui_story_1020_10201402_25_dialog_content = "ユリシーズ。",
  ui_story_1020_10201402_26_dialog_content = "ん？",
  ui_story_1020_10201402_27_dialog_content = "信仰が崩れていくのを経験したことがあるかい？",
  ui_story_1020_10201402_28_dialog_content = "…",
  ui_story_1020_10201402_29_dialog_content = "ない。",
  ui_story_1020_10201402_30_dialog_content = "君は…",
  ui_story_1020_10201402_31_dialog_content = "信仰が崩壊するのと理想を実現する力がないのと、\nどちらがより悲しいと思う？",
  ui_story_1020_10201402_32_dialog_content = "…",
  ui_story_1020_10201402_33_dialog_content = "信仰が崩壊することと、理想を実現する力がないこと…",
  ui_story_1020_10201402_34_dialog_content = "どちらがより悲しいか？",
  ui_story_1020_10201402_35_dialog_content = "…",
  ui_story_1020_10201501_1_dialog_content = "…キャンバスみたいだよ！",
  ui_story_1020_10201501_2_dialog_content = "本当ですね…しかも、ミンチの作風ですよ。\n手あたり次第描いた後、筆を洗った水をかけたみたいです。",
  ui_story_1020_10201501_3_dialog_content = "…いずれにせよ、独特な美的感覚です。",
  ui_story_1020_10201501_4_dialog_content = "それ、どういう意味！？",
  ui_story_1020_10201501_5_dialog_content = "ビクトリア様があたしたちをここに連れて来たのは、\nあたしを笑い者にするためじゃないよ！",
  ui_story_1020_10201501_6_dialog_content = "ああ、忘れるところでした。ビクトリア様、感謝申し上げます！",
  ui_story_1020_10201501_7_dialog_content = "ビクトリア様、ありがとうございます！",
  ui_story_1020_10201501_8_dialog_content = "ビクトリア様、ありがとうございます！",
  ui_story_1020_10201501_9_dialog_content = "私ではなく、真理の主の加護のおかげよ。",
  ui_story_1020_10201501_10_dialog_content = "ここはどこですか？",
  ui_story_1020_10201501_11_dialog_content = "…",
  ui_story_1020_10201501_12_dialog_content = "<color=#FFB400>原始の河</color>は時間に左右されず、空間の縛りを受けないの。\n外の世界との唯一の違いは流動すること。",
  ui_story_1020_10201501_13_dialog_content = "このままでは、私たちの命も自身で掌握できなくなるのではないのか？",
  ui_story_1020_10201501_14_dialog_content = "なぜ、ここへ連れて来た？",
  ui_story_1020_10201501_15_dialog_content = "私たちの時空と対応する地点を見つけるために、\n真理の主を降臨させるのよ。",
  ui_story_1020_10201501_16_dialog_content = "訳の分からんことを…",
  ui_story_1020_10201501_17_dialog_content = "ビクトリアさん、私たちの暗面偵察任務はまだ終わっていないの。\nここから座標信号を送って、啓光は本当に受信できるのかしら？",
  ui_story_1020_10201501_18_dialog_content = "真理の主が告げているわ。その心があれば、自然と分かる、と。\nすべて、あなたのやり方次第よ。",
  ui_story_1020_10201501_19_dialog_content = "<color=#e8d9bb>ポチャンッ――</color>",
  ui_story_1020_10201501_20_dialog_content = "あれ？バイス、何か落としたんじゃん？",
  ui_story_1020_10201501_21_dialog_content = "あ…啓光のバッジが！",
  ui_story_1020_10201501_22_dialog_content = "ど、どうしよう…すくい上げられないわ…",
  ui_story_1020_10201501_23_dialog_content = "あら？小さなバッジが落ちただけなのに、\n河の水面が光ったようですが？",
  ui_story_1020_10201501_24_dialog_content = "荒野での時間は止まっている。\nでも、河の下には別の情景が広がっているの。",
  ui_story_1020_10201501_25_dialog_content = "湖面…？あ、ひんやりとしていて、何だか現実味がないわ。",
  ui_story_1020_10201501_26_dialog_content = "湖面…",
  ui_story_1020_10201501_27_dialog_content = "PlayerName、気がついたのね。",
  ui_story_1020_10201501_28_dialog_content = "ここは…",
  ui_story_1020_10201501_29_dialog_content = "カレン？皆も…僕は、どうしてここにいるの？",
  ui_story_1020_10201501_30_dialog_content = "何も覚えていないのか？",
  ui_story_1020_10201501_31_dialog_content = "夢の中で透明な輝く湖面を見たような…\n思い出そうとしても、思い出せません…",
  ui_story_1020_10201501_32_dialog_content = "あ、そうだ！啓光は無事ですか！？",
  ui_story_1020_10201501_33_dialog_content = "うむ。声に力があるな。どうやら問題ないらしい。",
  ui_story_1020_10201501_34_dialog_content = "3日も寝ると、やはり回復が速いですね。\n若さとはいいものです。",
  ui_story_1020_10201501_35_dialog_content = "3日も寝てたんですか！？",
  ui_story_1020_10201501_36_dialog_content = "ええ。カレン護衛隊長はもう3度もお見舞いに来てるんですよ。",
  ui_story_1020_10201501_37_dialog_content = "私はただ何度も連絡しては、\nビビアン参謀長のお仕事の邪魔になるかと思っただけで…",
  ui_story_1020_10201501_38_dialog_content = "そもそも啓光から<color=#FFB400>合同会議</color>を提案したにもかかわらず、\n日程の相談が遅れ、申し訳ない。",
  ui_story_1020_10201501_39_dialog_content = "PlayerNameも気がついたことだ。\nちょうど護衛隊長もいることだし、今日でどうだ？",
  ui_story_1020_10201501_40_dialog_content = "ええ、私は構わないわ。",
  ui_story_1020_10201501_41_dialog_content = "合同会議って…何かあったんですか？\nユリシーズ教授は…どうなりましたか？",
  ui_story_1020_10201501_42_dialog_content = "やつは死んだ。エンジニアの件もひとまず一段落着いたところだ。",
  ui_story_1020_10201501_43_dialog_content = "その後、事件のいきさつを整理してみたのだが、\nお前がユリシーズの意識の中で何を見たのか、おおかた察しはついた。",
  ui_story_1020_10201501_44_dialog_content = "やつの実験室を差し押さえたのだが、大量の作業日記が見つかってな。\nそこに多くの重要な情報が書かれていた。",
  ui_story_1020_10201501_45_dialog_content = "ただ、意外だったのは、エンジニアに長い間目を付けられていたにも関わらず、\nやつが今まで持ちこたえたことだ。",
  ui_story_1020_10201501_46_dialog_content = "しかし、大元帥様のおっしゃったように、\nユリシーズは暗面を見つめると同時に、暗面に侵食されていき…",
  ui_story_1020_10201501_47_dialog_content = "知らぬ間に日蝕の一員となっていました。",
  ui_story_1020_10201501_48_dialog_content = "ああ。今回のカナン城の危機は、\n見たこともない600年前の事件が再現されたかのようだったな。",
  ui_story_1020_10201501_49_dialog_content = "だが、皆のおかげで、カナン城を守れた。\nお前とアルゴルの功績は大きいぞ。",
  ui_story_1020_10201501_50_dialog_content = "アルゴルさんはどうしましたか？",
  ui_story_1020_10201501_51_dialog_content = "アルゴル博士もあなたのように何日も寝込んでしまうかと思っていましたが――",
  ui_story_1020_10201501_52_dialog_content = "危機が過ぎると、何事もなかったかのように、\n引き続き研究に没頭していますよ。",
  ui_story_1020_10201501_53_dialog_content = "今日はおそらく外出しているでしょう。\n1号の修復ファイルを探すとかなんとか…",
  ui_story_1020_10201501_54_dialog_content = "もう1号の修復を始めたんですか…\nアルゴルさんが外出なんて、めずらしいですね。",
  ui_story_1020_10201501_55_dialog_content = "啓光の新しい乗り物に乗れるからでしょう。",
  ui_story_1020_10201501_56_dialog_content = "啓光の新しい乗り物って…何ですか？",
  ui_story_1020_10201501_57_dialog_content = "ユリシーズは長年巨像を研究していた。\n技術者たちがその資料を基に、似たような小型の飛行機を造っていたのだ。",
  ui_story_1020_10201501_58_dialog_content = "今回の危機でも、その小型機のおかげで住民を移動させることができた。\nこれから始まる合同探索にも使われることになるだろう。",
  ui_story_1020_10201501_59_dialog_content = "…",
  ui_story_1020_10201501_60_option_content = "ユリシーズ教授…",
  ui_story_1020_10201501_61_option_content = "小型機…",
  ui_story_1020_10201501_62_dialog_content = "ユリシーズ教授の研究成果は本当に引き継がれていくんですか？",
  ui_story_1020_10201501_63_dialog_content = "お前が何を心配しているのかは、分かっている。",
  ui_story_1020_10201501_64_dialog_content = "小型機だけではない。\nショーンのような暗面探索に適した身体をもつ光霊も…",
  ui_story_1020_10201501_65_dialog_content = "すべてユリシーズの研究が元になっている。\nそれは事実だ。",
  ui_story_1020_10201501_66_dialog_content = "今回の決定は、暗潮の危機当時「ガーディアン」システムの研究権限を\n開放した時の難しさに匹敵するだろうな。",
  ui_story_1020_10201501_67_dialog_content = "最高科学者会議と各研究室の責任者を集め、\nやつの研究成果の評価および投票を行ったが…",
  ui_story_1020_10201501_68_dialog_content = "賛成と反対のいずれにも、理があった。",
  ui_story_1020_10201501_69_dialog_content = "だが、私の立場から言えば、\n啓光同胞の生存こそ最重要事項だ。",
  ui_story_1020_10201501_70_dialog_content = "大元帥さんは、反対したんですか？",
  ui_story_1020_10201501_71_dialog_content = "その反対だ。",
  ui_story_1020_10201501_72_dialog_content = "生存を守る条件の一つは、常にリスクを減らしていくことだ。\nそのためには、常にリスクの所在を知り、それを武器に変えていかなければならない。",
  ui_story_1020_10201501_73_dialog_content = "我々は敵を知らなければならない。敵を研究し、自らの限界に挑戦し続け、\n光霊によりよい生存環境をもたらすため、前に進み続けなければならない。",
  ui_story_1020_10201501_74_dialog_content = "だから、合同探索をするんですか…？\nということは、白夜城も危険な目に遭ったんですか？",
  ui_story_1020_10201501_75_dialog_content = "白夜城は危険に遭わなかったわ。\nただ、聖物の多くで光力が乱れる現象が見られて、城主様も重視なさったの。",
  ui_story_1020_10201501_76_dialog_content = "カナン城の危機を経て、委員会もようやく大陸の各陣営と共に、\n合同探索の可能性を探る気になったのだ。",
  ui_story_1020_10201501_77_dialog_content = "カレンは白夜城の合同探索隊長となる予定だ。\n今後、北境と影ノ街の特使も会議に参加する。",
  ui_story_1020_10201501_78_dialog_content = "あの…大元帥様！R・W砂漠のお騒がせ者たちも、\nどこから情報を入手したのか、参加したいと言ってきています。",
  ui_story_1020_10201501_79_dialog_content = "PlayerName、お前の考えを聞きたい。",
  ui_story_1020_10201501_80_dialog_content = "僕は…",
  ui_story_1020_10201501_81_dialog_content = "今まで僕は自分から何かをしたことはなかったように思います。\nいつも受け身で、空の末裔の残した痕跡をたどって探索を続けてきました。",
  ui_story_1020_10201501_82_dialog_content = "ソラヴァンを直す中で、\n空の末裔の残したものは必ずしもいいものばかりじゃないことを知って…",
  ui_story_1020_10201501_83_dialog_content = "僕自身がいい奴なのかさえ、分からなくなってしまいました…",
  ui_story_1020_10201501_84_dialog_content = "特にバイスとソラヴァンのことがあってからは、\n何が起ころうと、必ず希望はあるはずだって思えなくなりました。",
  ui_story_1020_10201501_85_dialog_content = "失くしてしまったものを、何としても取り戻したい…\nそういう切実な思いに駆られるんです。",
  ui_story_1020_10201501_86_dialog_content = "あ、それと…最近いつも、何だか過去を見たような、\nもしくは未来を見たような感じがするんです…",
  ui_story_1020_10201501_87_dialog_content = "そして、そこが僕の行くべき所だって感じるんです。",
  ui_story_1020_10201501_88_dialog_content = "暗面なのか、暗面よりもさらに遠い場所なのか…\nもしかしたら、たどり着けない場所なのかもしれません。",
  ui_story_1020_10201501_89_dialog_content = "「宿命」ということでしょうか？",
  ui_story_1020_10201501_90_dialog_content = "そうなんでしょうか…東方の占い師の友だちが言うには、\n僕は「運命簿に載ってない」らしいんです…",
  ui_story_1020_10201501_91_dialog_content = "空の末裔は生まれ持った縛りから抜け出すことができる…\nだから、宿命は信じません。",
  ui_story_1020_10201501_92_dialog_content = "自分の考えを持ち、勇気と知恵に満ちているようですね。\nあなたなら、失くした物を必ず取り戻せます。",
  ui_story_1020_10201501_93_dialog_content = "はい！",
  ui_story_1020_10201501_94_dialog_content = "お前がそう考えているのなら、よかった。",
  ui_story_1020_10201501_95_dialog_content = "私には啓光の大元帥として、当然啓光の優秀な軍人である\nカロン、バイス、そして彼らの隊員を取り戻す義務がある。",
  ui_story_1020_10201501_96_dialog_content = "お前さえよければ、暗面へ行き、ソラヴァンを探すのを啓光が支援しよう。",
  ui_story_1020_10201501_97_dialog_content = "ええ。今回白夜城が合同探索隊への参加を決めたのも、\nあなたの存在があったからよ。",
  ui_story_1020_10201501_98_dialog_content = "ありがとう…",
  ui_story_1020_10201501_99_dialog_content = "僕の方こそいつも皆の助けと信頼を受けてばかりで…\n合同探索には、僕も必ず参加します！",
  ui_story_1020_10201501_100_dialog_content = "ただ、いったいどこから始めるんですか？",
  ui_story_1020_10201501_101_dialog_content = "実は候補となる場所は多いのだ。",
  ui_story_1020_10201501_102_dialog_content = "それは何ですか？",
  ui_story_1020_10201501_103_dialog_content = "「ヘリオスの回想録」だ。",
  ui_story_1020_10201501_104_dialog_content = "分厚いですね…こんなにも早く完成したのですか？\nチャンドラときたら、ものすごい効率ですね。",
  ui_story_1020_10201501_105_dialog_content = "何しろ、あの長い一日には、全員が招かれざる客のおかげで、\n死に物狂いで働かされたからな。",
  ui_story_1020_10201501_106_dialog_content = "お前が無事なのを確認して、我々もようやくぐっすり眠れる。",
  ui_story_1020_10201501_107_dialog_content = "そうだわ、PlayerName。\nさっき夢で透明な輝く湖面を見たと言いましたね？",
  ui_story_1020_10201501_108_dialog_content = "はい…透明な輝く湖面と…",
  ui_story_1020_10201501_109_dialog_content = "見慣れたバッジが1つ見えたんです…",
  ui_story_1020_10201501_110_dialog_content = "あの…体験したことはありますか…？",
  ui_story_1020_10201501_111_dialog_content = "暗闇にのみ込まれそうになった時、\n突然ピアノの音が闇を引き裂いて、光が射し込んでくる感覚を…",
  ui_story_1020_10201501_112_dialog_content = "<color=#e8d9bb>ポチャンッ――</color>",
  ui_story_1020_10201501_113_dialog_content = "ねえ、みんな！どっかからピアノの音が聞こえなかった？",
  ui_story_1020_10201501_114_dialog_content = "聞こえました！",
  ui_story_1020_10201501_115_dialog_content = "え？",
  ui_story_1020_10201501_116_dialog_content = "はい…メリーが叫んだ後、聞こえなくなりましたが…",
  ui_story_1020_10201501_117_dialog_content = "真理の主、感謝するわ！",
  ui_story_1020_10201501_118_dialog_content = "バイスさん、印の地点を見つけたのね。\nあなたのやり方で、私たちを導いてちょうだい。",
  ui_story_1020_10201501_119_dialog_content = "私が？",
  ui_story_1020_10201501_120_dialog_content = "あなたと空の末裔があの巨像を起動した時、\n眠っていたこの原始の河はすでに呼び覚まされていたの。",
  ui_story_1020_10201501_121_dialog_content = "あの時、アイオリアの歴史はあなたの手によって、新しいページへと進んだのよ。",
  ui_story_1020_10201501_122_dialog_content = "もう一度、あなたのやり方で私たちを導いてちょうだい。",
  ui_story_1020_10201501_123_dialog_content = "もう一度、あなたのやり方で私たちを導いてください。",
  ui_story_1020_10201501_124_dialog_content = "…？",
  ui_story_1020_10201501_125_dialog_content = "…",
  ui_story_1020_10201501_126_dialog_content = "今のピアノの音は、まさか…",
  ui_story_1020_10201501_127_dialog_content = "この「ピアノ」にそっくりな物、これが巨像の制御装置？",
  ui_story_1020_10201501_128_dialog_content = "一緒に巨像を起動しましょう、ナビゲーター。",
  ui_story_1020_10201501_129_dialog_content = "一緒に…？バイス、君は光霊だよね、感知能力はない…",
  ui_story_1020_10201501_130_dialog_content = "でも、私はあなたの力になれる。私なら…やれるわ。",
  ui_story_1020_10201501_131_dialog_content = "…？",
  ui_story_1020_10201501_132_dialog_content = "信じて、PlayerName。私とあなたは…少し似ている所があるの。",
  ui_story_1020_10201501_133_dialog_content = "でもそれを話すと長くなっちゃうから、また今度ゆっくり話してあげるわ！",
  ui_story_1020_10201501_134_dialog_content = "どうやって「演奏」するか教えるよ。",
  ui_story_1020_10201501_135_dialog_content = "ビクトリアさんに言われて、思い出したわ…",
  ui_story_1020_10201501_136_dialog_content = "…",
  ui_story_1020_10201501_137_dialog_content = "簡単だよ、ピアノを弾くみたいにすればいいんだ。",
  ui_story_1020_10201501_138_dialog_content = "…",
  ui_story_1020_10201501_139_dialog_content = "でも楽譜がないわ。どの鍵盤を押せばいいのか、教えてくれる？",
  ui_story_1020_10201501_140_dialog_content = "…",
  ui_story_1020_10201501_141_dialog_content = "感じるわ…エネルギーの流れを。",
  ui_story_1020_10201501_142_dialog_content = "会話するみたいなものよ――巨像の言葉は、私には分からないけど。",
  ui_story_1020_10201501_143_dialog_content = "鍵盤で話すのがソラヴァンの言葉なんだよ。",
  ui_story_1020_10201501_144_dialog_content = "さあ、起動命令を完成させよう、バイス。",
  ui_story_1020_10201501_145_dialog_content = "…",
  ui_story_1020_10201501_146_dialog_content = "もし、あれが皆を導く方法だというなら、\nどうやればいいか、分かった気がするわ。",
  ui_story_1020_10201501_147_dialog_content = "ねえ、聞いて！ピアノの音だよ！",
  ui_story_1020_10201501_148_dialog_content = "この神秘の光のきらめく河こそ、主の恩恵の所在ね。",
  ui_story_1020_10201501_149_dialog_content = "主は神秘の旋律に耳を傾け、尽きることのない真理を啓示してくださる。",
  ui_story_1020_10201501_150_dialog_content = "真理の主よ、我々の探索を見守り、御降臨ください。",
  ui_story_1021_10210100_1_dialog_content = "<color=#e8d9bb>何年も前、北境の辺境にて…</color>",
  ui_story_1021_10210100_2_dialog_content = "女王陛下、あの丘の先はもう北境の外でございます。",
  ui_story_1021_10210100_3_dialog_content = "…",
  ui_story_1021_10210100_4_dialog_content = "雪原は広大だな。ここにも北境の民が暮らしているとは。",
  ui_story_1021_10210100_5_dialog_content = "先生は先に戻っていてくれ。この先は私一人の問題だ。",
  ui_story_1021_10210100_6_dialog_content = "歴代先王も、果てしなく広がる氷と雪の大地も、\n陛下の北境への貢献を忘れることはないでしょう。",
  ui_story_1021_10210100_7_dialog_content = "北境を守っているのは私ではない、北境自ら守っているのだ。",
  ui_story_1021_10210100_8_dialog_content = "私は北境の力を与えられているにすぎん。\n尽力するのは当然だ。",
  ui_story_1021_10210100_9_dialog_content = "冬の向こうへ。\n私どもは北境を守るために生まれし者です。",
  ui_story_1021_10210100_10_dialog_content = "<color=#e8d9bb>ザクッザクッ――</color>",
  ui_story_1021_10210100_11_dialog_content = "おや？雪が止んだか…",
  ui_story_1021_10210100_12_dialog_content = "この辺りのスノーシダーの森は、\n天候に恵まれることは珍しいはずだが…",
  ui_story_1021_10210100_13_dialog_content = "…えいっ！",
  ui_story_1021_10210100_14_dialog_content = "ん？",
  ui_story_1021_10210100_15_dialog_content = "あなた、よそ者ね！さっさとここから出ていけ！\nじゃないと、村のリーダーの、このティアラがゆるさないんだから！",
  ui_story_1021_10210100_16_dialog_content = "…そなた、ティアラと申すのか？",
  ui_story_1021_10210100_17_dialog_content = "え…！？どうして私の名前を…",
  ui_story_1021_10210100_18_dialog_content = "コホン…きっとぬすみ聞きしたんでしょうけど、\n雪狐の村には一歩も入らせないわ！",
  ui_story_1021_10210100_19_dialog_content = "雪狐の村の子か。両親はどうしたのだ？",
  ui_story_1021_10210100_20_dialog_content = "お父さんとお母さんは北境を守るのに忙しいの！話をそらさないで！\nいったいここへ何しに来たの！？",
  ui_story_1021_10210100_21_dialog_content = "ティアラ！ひいばあちゃんがいいものを持ってきてやったよ。",
  ui_story_1021_10210100_22_dialog_content = "わぁ、松の枝だ！いい匂い！",
  ui_story_1021_10210100_23_dialog_content = "じゃろう？じゃあどうして祭壇に行かずに、ここでお転婆してるか教えてくれるかい？",
  ui_story_1021_10210100_24_dialog_content = "あのね、大ババ様が祭壇は子どもの来るところじゃないって言ってた。",
  ui_story_1021_10210100_25_dialog_content = "あの老いぼれめ。またもうろくしとるようじゃのう。",
  ui_story_1021_10210100_26_dialog_content = "ひいばあちゃん！ティアラ、今日いいことしたんだよ！\nほら、よそ者が村に近づかないようにしたんだ！",
  ui_story_1021_10210100_27_dialog_content = "…",
  ui_story_1021_10210100_28_dialog_content = "おお！あんたはえらい子だねぇ！",
  ui_story_1021_10210100_29_dialog_content = "じゃあ、ひいばあちゃんが今から試験をしてやろう。\n「3本松の木」のお話は覚えているかい？",
  ui_story_1021_10210100_30_dialog_content = "覚えてるよ！",
  ui_story_1021_10210100_31_dialog_content = "ティアラは賢い子だ。伝説のことはもういいではないか。",
  ui_story_1021_10210100_32_dialog_content = "あたしが話してやらなきゃ皆忘れちまうだろ。\nじきにこの子も物語を受け継いでいくことになるんだからね。",
  ui_story_1021_10210100_33_dialog_content = "…",
  ui_story_1021_10210100_34_dialog_content = "ベツレヘムと申す。お会いできて嬉しく思う。",
  ui_story_1021_10210100_35_dialog_content = "先祖代々北境を守ってきてくれたことに感謝したい。\nでは、これで失礼する。",
  ui_story_1021_10210100_36_dialog_content = "…",
  ui_story_1021_10210100_37_dialog_content = "<color=#e8d9bb>ザクッザクッ――</color>",
  ui_story_1021_10210100_38_dialog_content = "灯台の光はこの地にも届くと言っておったな。",
  ui_story_1021_10210100_39_dialog_content = "…",
  ui_story_1021_10210100_40_dialog_content = "だが、雪狐の村に赤子の産声が聞こえなくなって久しい。",
  ui_story_1021_10210100_41_dialog_content = "雪狐の村は、北境に多くの護衛を授けてくれた。\n心より感謝している。",
  ui_story_1021_10210100_42_dialog_content = "この村の子らは、生まれた時から荘厳な宮殿などではなく、\nいつ暗鬼に襲われるとも知れぬ雪原の森で暮らしてきた。",
  ui_story_1021_10210100_43_dialog_content = "そして先祖たちは、一代また一代と、\n北境を守るためにその命を捧げてきた。",
  ui_story_1021_10210100_44_dialog_content = "その子を氷の宮殿へ連れていこう。",
  ui_story_1021_10210100_45_dialog_content = "北境が暗鬼に滅ぼされた時、そなたはこの地を離れ、\n他の地へ行くのか？",
  ui_story_1021_10210100_46_dialog_content = "ありえぬ。",
  ui_story_1021_10210100_47_dialog_content = "北境は我々を育み、守ってくれている。\nゆえに我々も代々この地を守っていくべきだ。",
  ui_story_1021_10210100_48_dialog_content = "どうしたことか…何故あの日の事を…",
  ui_story_1021_10210100_49_dialog_content = "陛下、辺境の天候に異常がございました。\n灯台の光にもわずかながら異変が起こっております。",
  ui_story_1021_10210100_50_dialog_content = "ふむ。やはり偶然ではなかったか…予測はしていたことだ。",
  ui_story_1021_10210100_51_dialog_content = "陛下が予見なさった通り、先頃の啓光の危機は決して単独の事件では\nなかったようでございます。拠点の建設も順調ではなく…",
  ui_story_1021_10210100_52_dialog_content = "暗面の動向を注視する必要がございます。",
  ui_story_1021_10210100_53_dialog_content = "合同探索には光霊の未来がかかっている。きわめて重要だ。\n合同会議まで幾日もない。",
  ui_story_1021_10210100_54_dialog_content = "確認しに行こう。",
  ui_story_1021_10210100_55_dialog_content = "今からでございますか？",
  ui_story_1021_10210100_56_dialog_content = "うむ。ところで、ティアラを見かけなかったか？",
  ui_story_1021_10210100_57_dialog_content = "ティアラでしたら…",
  ui_story_1021_10210100_58_dialog_content = "女王陛下…お、お出かけになるのですか？\n私もご一緒します。",
  ui_story_1021_10210100_59_dialog_content = "…",
  ui_story_1021_10210100_60_dialog_content = "独りでよい。数日間不在にするが、氷の宮殿のことはノーヴィオに任せてある。\n私の留守の間、鍛錬に励むがよい。",
  ui_story_1021_10210100_61_dialog_content = "はい、女王陛下！",
  ui_story_1021_10210100_62_dialog_content = "（何をあんなに急いでいらっしゃるんだろう…？）",
  ui_story_1021_10210100_63_dialog_content = "窓枠に残っている足跡はきれいに拭いておくのだぞ。",
  ui_story_1021_10210100_64_dialog_content = "…はい！",
  ui_story_1021_10210100_65_dialog_content = "<color=#e8d9bb>コォォ――ン</color>",
  ui_story_1021_10210100_66_dialog_content = "…",
  ui_story_1021_10210100_67_dialog_content = "やっぱり、何の応答もない…",
  ui_story_1021_10210100_68_dialog_content = "女王陛下がお出かけになってから、もう何日も経った…",
  ui_story_1021_10210100_69_dialog_content = "陛下の護衛なのにお側にいられないなんて。\n「鍛錬」しようにも、どうすればいいのか…",
  ui_story_1021_10210100_70_dialog_content = "<color=#e8d9bb>コォォ――ン</color>",
  ui_story_1021_10210100_71_dialog_content = "え…",
  ui_story_1021_10210100_72_dialog_content = "クウゥ…",
  ui_story_1021_10210100_73_dialog_content = "そんな…？",
  ui_story_1021_10210100_74_dialog_content = "クウゥ――！",
  ui_story_1021_10210100_75_dialog_content = "どうして、そんなことに…！？",
  ui_story_1021_10210100_76_dialog_content = "陛下がお出かけになる前に村に戻った時は…\n大ババ様が収穫の恵みを分けてくださったのに…",
  ui_story_1021_10210100_77_dialog_content = "でも、私は女王陛下の護衛で、勝手に持ち場を離れるのは…",
  ui_story_1021_10210100_78_dialog_content = "コオォーン――！",
  ui_story_1021_10210100_79_dialog_content = "…分かった！今すぐ一緒に戻ろう！",
  ui_story_1021_10210100_80_dialog_content = "あ！雪狐だ！",
  ui_story_1021_10210100_81_dialog_content = "アントニー先生の授業中だよ、静かにして！\n雪狐なんているわけないじゃん！",
  ui_story_1021_10210100_82_dialog_content = "ほら、よく見なよ。ウサギが飛び跳ねてるだけだよ。",
  ui_story_1021_10210100_83_dialog_content = "ホントに見たもん…\nよみかきの本に出てくる雪狐そのままだった！",
  ui_story_1021_10210100_84_dialog_content = "雪狐が町にいるなんてたしかにヘンだけど…\nアントニー先生！先生は信じてくれるでしょ？",
  ui_story_1021_10210100_85_dialog_content = "北境がまだ北境という名前ではなかった頃、雪狐と一部の光霊は仲が良く、\n一緒にこの地を守っていたと言われているんだ。",
  ui_story_1021_10210100_86_dialog_content = "じゃあ、雪狐は今も北境にいるの？",
  ui_story_1021_10210100_87_dialog_content = "いるはずだよ。雪狐は神聖な動物だからね、\n中には何百年も何千年も生きる雪狐もいると言われているんだ。",
  ui_story_1021_10210100_88_dialog_content = "何千年って…いったいどれくらい？",
  ui_story_1021_10210100_89_dialog_content = "北境で一番古いスノーシダーの木よりもお年寄りさ。\n前に話した「3本松の木」の物語は覚えているかい？",
  ui_story_1021_10210100_90_dialog_content = "おぼえてる！",
  ui_story_1021_10210100_91_dialog_content = "北境が北境になる前、3本の偉大なスノーシダーがいて、\n3本は北境を守ろうとしていたんだよね…",
  ui_story_1021_10210100_92_dialog_content = "でも、他の生き物たちにバカにされた。\nたかがスノーシダーに北境を守れるわけないって。",
  ui_story_1021_10210100_93_dialog_content = "そのあと戦争が起こって、木こりがその3本を切り倒しちゃったんだ。",
  ui_story_1021_10210100_94_dialog_content = "1本は家畜小屋…",
  ui_story_1021_10210100_95_dialog_content = "1本は木の台になって、貧しい家庭へと売られて行った…",
  ui_story_1021_10210100_96_dialog_content = "3本目のスノーシダーは誰にも必要とされず、倉庫にしまわれて、\nそれから二度と外に出されなかった。",
  ui_story_1021_10210100_97_dialog_content = "何年も経った後、通りかかったお腹の大きい女の人が\nその台で赤ちゃんを産んで…",
  ui_story_1021_10210100_98_dialog_content = "その赤ちゃんこそが、偉大な初代北境の女王だったんだよね！",
  ui_story_1021_10210100_99_dialog_content = "北境の女王は後にその貧しい家庭を救って…",
  ui_story_1021_10210100_100_dialog_content = "ボロボロになった台の前で、貧しい家庭の四兄弟は女王に誓ったんだ。\n今後代々、王室を守っていくって…",
  ui_story_1021_10210100_101_dialog_content = "その四兄弟の子孫が北境王室の護衛になってるんだよ！",
  ui_story_1021_10210100_102_dialog_content = "ええと、その…ごめんなさい、アントニー先生。\n3本目のスノーシダーは、その後どうなったんだっけ…",
  ui_story_1021_10210100_103_dialog_content = "後に、倉庫でそのスノーシダーを見つけた女王が杖を作ったんだ…",
  ui_story_1021_10210100_104_dialog_content = "その杖こそが、北境のあらゆる生き物に号令を発し、\n北境を守っている権杖だ。",
  ui_story_1021_10210100_105_dialog_content = "スノーシダーは北境の守護神なのさ。\nスノーシダーのおかげで、俺たちの故郷は代々平和で、みんな幸せに暮らせるんだよ…",
  ui_story_1021_10210100_106_dialog_content = "…",
  ui_story_1021_10210100_107_dialog_content = "そんな…！",
  ui_story_1021_10210100_108_dialog_content = "みんな…大ババ様…いったい何が…！？",
  ui_story_1021_10210100_109_dialog_content = "…",
  ui_story_1021_10210100_110_dialog_content = "<color=#e8d9bb>コオォーン――！</color>",
  ui_story_1021_10210201_1_dialog_content = "<color=#e8d9bb>アストラ合同探索委員会、臨時司令部</color>",
  ui_story_1021_10210201_2_dialog_content = "久しぶりだね、PlayerName！",
  ui_story_1021_10210201_3_dialog_content = "ウェンディ、久しぶり！相変わらず時間厳守だね！",
  ui_story_1021_10210201_4_dialog_content = "か、絡まっちゃった…このマフラー、ほんと面倒くさいな…",
  ui_story_1021_10210201_5_dialog_content = "あれ！ピープも時間どおりじゃん！\nあのタタっていう面白い後輩はどうしたの？",
  ui_story_1021_10210201_6_dialog_content = "うーん…ほんとのこと言うと、あの後輩は見込みないと思うんだよね。\nだって、一人前のクーリエには程遠いんだってば。",
  ui_story_1021_10210201_7_dialog_content = "いつも「すぐどす！今すぐ着きますぅ！」って言うけど、\nほんとはどっかで落とした手紙を拾ってるに決まってるんだってば！",
  ui_story_1021_10210201_8_dialog_content = "はぁ…でも私は先輩だし、せっかちだったり、おっちょこちょいなところも、\n時々責任感の欠如で失敗しちゃうのも、許してあげなきゃ…",
  ui_story_1021_10210201_9_dialog_content = "タタは君に似たんだね…ん？あれ？\nというより、タタじゃなくて自分のこと言ってない…？",
  ui_story_1021_10210201_10_dialog_content = "先輩として、面倒見てあげるってば！",
  ui_story_1021_10210201_11_dialog_content = "ああ、誰か私の面倒見てくんないかなぁ。休みが終わった途端、ビビアン様から\nトワイライトシティに合同探索の拠点を確認して来いって言われちゃったよ。",
  ui_story_1021_10210201_12_dialog_content = "なんでトワイライトシティなの！？あそこはちょっと休もうにも、\n風や砂には暗力が混じってるし、辺り一面暗いしさ…",
  ui_story_1021_10210201_13_dialog_content = "一日中ぼーっとしちゃって、仕事する気も起こらないじゃん…",
  ui_story_1021_10210201_14_dialog_content = "はぁ…この仕事もこれ以上ムリだな…\n来月から新しい仕事探さなきゃだ。",
  ui_story_1021_10210201_15_option_content = "あ！ビビアンさん、お久しぶりです。",
  ui_story_1021_10210201_16_dialog_content = "…！",
  ui_story_1021_10210201_17_dialog_content = "って、みんながよく言ってるけど…私はいつも励ましてあげてるんだ！\nビビアン様はよくしてくれてるでしょって！",
  ui_story_1021_10210201_18_dialog_content = "仕事の配分も合理的で、報酬もたっぷりくれる。\nいろんな任務をくれるから鍛錬にもなるし、こんないい仕事ほかにはないってね！",
  ui_story_1021_10210201_19_dialog_content = "…180°転換したね…",
  ui_story_1021_10210201_20_option_content = "暗面探索隊にようこそ。",
  ui_story_1021_10210201_21_dialog_content = "暗面！？勘弁してよ…暗面の探索に行くくらいなら、\nクーリエの仕事の方が何万倍もマシだよ。",
  ui_story_1021_10210201_22_dialog_content = "よく考えてみたら…クーリエって基本自由行動だし、配達時間も自分で決められるし、\nクビになる心配もないポッポ…",
  ui_story_1021_10210201_23_dialog_content = "だから、誘いには感謝するけど、このままテキトー…\n適任の仕事のクーリエを続けることにするよ！",
  ui_story_1021_10210201_24_dialog_content = "あはは。君がそんなこと言うなんて、\nビビアンさんから「感謝状」もらえそうだね…",
  ui_story_1021_10210201_25_dialog_content = "大元帥様、約束の時間となりましたが、\n北境の代表がまだ到着しておりません。",
  ui_story_1021_10210201_26_dialog_content = "午前中に北境より知らせが入っている。予定通り会議を始めよう。",
  ui_story_1021_10210201_27_dialog_content = "はい、承知いたしました。",
  ui_story_1021_10210201_28_dialog_content = "各陣営代表者の皆さん、アストラ大陸合同探索に関する\n第1回会議にご出席くださり、感謝いたします。",
  ui_story_1021_10210201_29_dialog_content = "私は啓光連邦参謀長、ビビアンです。\n特に異論がないようなら、さっそく会議を始めようと思います。",
  ui_story_1021_10210201_30_dialog_content = "はい、異論ありません。",
  ui_story_1021_10210201_31_dialog_content = "シャドウマスターの代理で参りました。\n私も異論ありません。",
  ui_story_1021_10210201_32_dialog_content = "うむ。先に始めるしかないようだな。",
  ui_story_1021_10210201_33_dialog_content = "では、始めるとしよう。",
  ui_story_1021_10210201_34_dialog_content = "今回このように開けた場所での開催を決定したのは、\n陽の光の下で、皆さんと共に光霊の未来を語り合いたいと思ったからです。",
  ui_story_1021_10210201_35_dialog_content = "まず初めに拠点の建設について、\nクーリエ隊の皆さんの多大なる支持と協力に感謝します。",
  ui_story_1021_10210201_36_dialog_content = "各陣営が素早く暗面探索隊の動きに対応できるよう、\nクーリエ隊は多方面にわたり、協力をしてくれます。",
  ui_story_1021_10210201_37_dialog_content = "拠点間の情報のやり取りや暗面に関する手がかりの伝達などだけでなく、\nクーリエ隊は監督と確認という重要な責務を担ってくれるでしょう。",
  ui_story_1021_10210201_38_dialog_content = "ふふん！クーリエ隊、使命は必ずやり遂げます！",
  ui_story_1021_10210201_39_dialog_content = "ではここで、啓光大元帥より合同探索の計画をご紹介し、\n皆さんのご意見をうかがいたいと思います。",
  ui_story_1021_10210201_40_dialog_content = "今回の探索経路についてだが、以前知らせにも書いたように…",
  ui_story_1021_10210201_41_dialog_content = "暗面付近に複数の<color=#FFB400>前衛拠点</color>を構築し、\n探索支援および情報収集を行いたいと思う。",
  ui_story_1021_10210201_42_dialog_content = "各陣営の地理上の分布を考慮し、アストラ北部に、\n<color=#FFB400>3拠点</color>を設置する予定だ。",
  ui_story_1021_10210201_43_dialog_content = "1か所は北西部の<color=#FFB400>トワイライトシティ</color>に築く。トワイライトシティの規模と力ならば、\n探索隊が暗面に進入するにあたり、最適な後援基地となろう。",
  ui_story_1021_10210201_44_dialog_content = "先日白夜城城主と私はトワイライトシティを共同統治することで合意した。\n今回の拠点建設はその実務措置の一つだ。",
  ui_story_1021_10210201_45_dialog_content = "トワイライトシティには戦略実行司令部を置き、\n探索隊の支援に努める。",
  ui_story_1021_10210201_46_dialog_content = "レオが当該拠点の責任者となり、\nかつ総司令部に探索隊の動向を定期的に報告する任を負う。",
  ui_story_1021_10210201_47_dialog_content = "残り2拠点は<color=#FFB400>天空ノ谷</color>と<color=#FFB400>北境</color>に置く。",
  ui_story_1021_10210201_48_dialog_content = "ただ、地下遺跡への影響を考え、天空ノ谷については、\n現在拠点建設の実行可能性を調査しているところだ。",
  ui_story_1021_10210201_49_dialog_content = "北境の拠点建設に関しては、その特殊な環境により時間がかかるだろう。\n北境の女王と確認が取れ次第、皆に報告する。",
  ui_story_1021_10210201_50_dialog_content = "最後に…",
  ui_story_1021_10210201_51_dialog_content = "暗面探索の経路と座標情報は啓光連邦の科学者アルゴルと\n優秀な情報員が共同で完成させたものだ。",
  ui_story_1021_10210201_52_dialog_content = "幾度もの検証を行い、その情報の真実性と安全性は確認済みだ。\n皆にも共有するから、どうか大切に扱い、活かしてほしい。",
  ui_story_1021_10210201_53_dialog_content = "私からは以上だ。何か質問はないか？",
  ui_story_1021_10210201_54_dialog_content = "暗面について、これほどの情報を集めたとあれば、\n啓光も多大なる代償を払ったことだろう。",
  ui_story_1021_10210201_55_dialog_content = "此度の探索は光霊の未来に関わる。だが、啓光連邦には野心家も少なくない。\nお主らは真に正しく暗面に向かう者を決められるのか？",
  ui_story_1021_10210201_56_dialog_content = "もちろんだ。我々は野心で人を測ることはしない。\n困難に打ち勝つ勇気と覚悟かあるかどうかで決める。",
  ui_story_1021_10210201_57_dialog_content = "すでに精鋭からなる<color=#FFB400>「偵察隊」</color>を暗面に展開させている。\n今後の探索の道筋を示してくれるだろう。",
  ui_story_1021_10210201_58_dialog_content = "次に探索実行顧問の<color=#FFB400>バレット</color>を紹介する。\n今回使用する飛行機は彼女のチームが開発した。",
  ui_story_1021_10210201_59_dialog_content = "それから、情報長官の<color=#FFB400>フィリス中尉</color>だ。\n生活面と通信の責任者となる。",
  ui_story_1021_10210201_60_dialog_content = "また、現在予備人員および装備の最終テスト調整を行っている。\n合同探索隊にとって、大きな後ろ盾となろう。",
  ui_story_1021_10210201_61_dialog_content = "お主らの集めた情報に基づき、白夜城も精鋭部隊を出そう。\n後に続く部隊のため、障害を取り除くとしよう。",
  ui_story_1021_10210201_62_dialog_content = "…",
  ui_story_1021_10210201_63_dialog_content = "（白夜城が精鋭部隊を…？合同探索で主導権を握ろうとしてるのかな？\nカレンはそんなこと知らなかったみたいだけど…）",
  ui_story_1021_10210201_64_dialog_content = "白夜城も皆さんと共に戦い、全面的に探索に協力しましょう。",
  ui_story_1021_10210201_65_dialog_content = "うむ。軍事物資はすでに準備してある。\n後は号令を待つだけだ。",
  ui_story_1021_10210201_66_dialog_content = "コホン…影ノ街総合商会も十分な物資を用意させてもらいました。\n商会で輸送を担当し、出発地へ送りましょう。",
  ui_story_1021_10210201_67_dialog_content = "影ノ街は、探索の経験は豊富ではありませんが、\n<color=#FFB400>探索隊</color>が1年使っても有り余るほどの物資を供給することは十分に可能です。",
  ui_story_1021_10210201_68_dialog_content = "協力に感謝する。",
  ui_story_1021_10210201_69_dialog_content = "影ノ街にとっても益のある取引ですから。",
  ui_story_1021_10210201_70_dialog_content = "具体的な出発日時については、できるだけ早く知らせるようにする。",
  ui_story_1021_10210201_71_dialog_content = "（これが「自身の強み」を活かすってことか…）",
  ui_story_1021_10210201_72_dialog_content = "PlayerName、何か言いたげだが？",
  ui_story_1021_10210201_73_dialog_content = "ええと…僕には皆さんに提供できるような物資はありませんが、\n仲間を守りたいという強い意志があります。",
  ui_story_1021_10210201_74_dialog_content = "今回の探索先はとても危険ですが、\nみんなの安全は必ず守ってみせます。",
  ui_story_1021_10210201_75_dialog_content = "僕の仲間に怪我をさせたり、離脱させたりはさせません。",
  ui_story_1021_10210201_76_dialog_content = "…",
  ui_story_1021_10210201_77_dialog_content = "（え？何かヘンなこと言っちゃったかな…？）",
  ui_story_1021_10210201_78_dialog_content = "PlayerNameさん、商会の助けが必要な時はいつでも言ってください。",
  ui_story_1021_10210201_79_dialog_content = "ありがとう、ベセル。そうさせてもらうね。",
  ui_story_1021_10210201_80_dialog_content = "話し合うべきことはすでに話し終えたようだな。\nでは、少し別の話をさせてもらおう。",
  ui_story_1021_10210201_81_dialog_content = "まだ若かりし頃、余は城主となった暁には、\n己の好きな場所へ巡視に赴きたいと望んでいた。",
  ui_story_1021_10210201_82_dialog_content = "だが、実際は白夜城の統治に明け暮れるのみで、\nもうこの歳になってしまった。",
  ui_story_1021_10210201_83_dialog_content = "城主として、余は今生のうちに若き者の目を通し、\nさらに遠くの世界を見てみたいと願い――",
  ui_story_1021_10210201_84_dialog_content = "また、一個人として、此度の探索がいかに危険なものであろうと、\nカレンにはお主らと共に新たな時代の幕開けを見てもらいたい。",
  ui_story_1021_10210201_85_dialog_content = "城主様…",
  ui_story_1021_10210201_86_dialog_content = "城主様は今回の探索が新しい時代の幕開けになると考えているんですか？",
  ui_story_1021_10210201_87_dialog_content = "むろんだ。むしろ、お主がアストラ大陸に現れ、次々と謎を解き始めた頃から、\n新たな時代は始まっていたと言った方がよかろう。",
  ui_story_1021_10210201_88_dialog_content = "我々も全力で探索を支援しよう。\nアストラ大陸の未来はお主ら若き者の手の中にあるのだからな。",
  ui_story_1021_10210201_89_dialog_content = "ロイ兄も手伝って！ひとりじゃきっついよ。",
  ui_story_1021_10210201_90_dialog_content = "年取るとくず拾いしたくなるって言うけどねェ、\nオッさんは今晩のステーキソースを何にするか考えなきゃいけないんだ。",
  ui_story_1021_10210201_91_dialog_content = "ぶあーっくしょん！",
  ui_story_1021_10210201_92_dialog_content = "この飛行機、新しいのはいいんだが、機械臭いっつーか…\n胡椒をふりまいたみたいだねェ。ぶぁっくしょん――！",
  ui_story_1021_10210201_93_dialog_content = "サメヤマさん、ほんとよく考えてるよね。今回も空の末裔たちの探索に興味もつなんてさ。\nえへへ、この飛行機ちゃんと研究しなきゃ。どっかで使えるかもしれないし！",
  ui_story_1021_10210201_94_dialog_content = "サメヤマのヤツも相変わらず、面倒を起こすのが好きだねェ…\nおい！タイニー、行くぞ！",
  ui_story_1021_10210201_95_dialog_content = "護衛隊長。まだ新しいので、匂いが残っていますがお許しください。",
  ui_story_1021_10210201_96_dialog_content = "いえ、構いません。匂いには敏感でもありませんし。",
  ui_story_1021_10210201_97_dialog_content = "今朝北境の女王から、拠点の建設を数日遅らせねばならんとの知らせが入った。\n具体的な原因は言っていなかったのだが、盟友であるがゆえあまり追及もできん。",
  ui_story_1021_10210201_98_dialog_content = "探索は各拠点との協調が重要だ。\nだが、今啓光には人手の余裕がない。",
  ui_story_1021_10210201_99_dialog_content = "そういうわけで、2人には私の代わりに使いに行ってもらいたい。",
  ui_story_1021_10210201_100_dialog_content = "ここのところ色々とあったので、\n私もしばらくの間北境には行っていませんでした。",
  ui_story_1021_10210201_101_dialog_content = "ならば、ちょどいい。PlayerNameに飛行機の操作を教わるといい。",
  ui_story_1021_10210201_102_dialog_content = "任せてください。ソラヴァンとは違いますけど…\n同じような設計になってる所も多いので――",
  ui_story_1021_10210201_103_dialog_content = "もうアストラの半分は飛べるようになりました。",
  ui_story_1021_10210201_104_dialog_content = "ではよろしく頼む。通信設備は調整済みだ。\n何かあればいつでも連絡してくれ。",
  ui_story_1021_10210201_105_dialog_content = "お気をつけて！",
  ui_story_1021_10210201_106_dialog_content = "はい！",
  ui_story_1021_10210201_107_dialog_content = "大元帥様、\nPlayerNameたちにR・Wの2人がいることを伝えましょうか？",
  ui_story_1021_10210201_108_dialog_content = "必要ない。探索中にはよくあることだ。\n自分たちで対処するだろう。",
  ui_story_1021_10210201_109_dialog_content = "それに、R・Wも今回の探索に参加すると騒いでいたろう？",
  ui_story_1021_10210301_1_dialog_content = "<color=#e8d9bb>しばらくして…</color>",
  ui_story_1021_10210301_2_dialog_content = "実際に乗るまでは、少し不安だったけれど――",
  ui_story_1021_10210301_3_dialog_content = "ずいぶんと狭いこと以外は、啓光の飛行機の乗り心地もソラヴァンとほぼ同じね。\nいつの間にか、北境も目と鼻の先の所まで来たわ。",
  ui_story_1021_10210301_4_dialog_content = "僕が大丈夫だって言ったの、納得できたでしょ？",
  ui_story_1021_10210301_5_dialog_content = "下降を始める前に、カレンも少し操縦してみる？\n離陸の時に見てたと思うけど、結構簡単なんだ。",
  ui_story_1021_10210301_6_dialog_content = "そ、そう…だったら、教えて。やってみるわ。",
  ui_story_1021_10210301_7_dialog_content = "じゃ、まずはこの制御装置の表示を…",
  ui_story_1021_10210301_8_dialog_content = "<color=#e8d9bb>グラッ！</color>",
  ui_story_1021_10210301_9_dialog_content = "わわっ！",
  ui_story_1021_10210301_10_dialog_content = "ど、どうしたの？まだ何も触っていないわよ！？",
  ui_story_1021_10210301_11_dialog_content = "だ、大丈夫だよ…おそらく気流のせいだ…",
  ui_story_1021_10210301_12_dialog_content = "この手の急降下は…操縦レバーをあげて、それから…",
  ui_story_1021_10210301_13_dialog_content = "<color=#e8d9bb>ピーッ！ピーッ！ピーッ！</color>",
  ui_story_1021_10210301_14_dialog_content = "まずい――！",
  ui_story_1021_10210301_15_dialog_content = "<color=#e8d9bb>ピーッ！ピーッ！ピーッ！</color>",
  ui_story_1021_10210301_16_dialog_content = "ロイ兄、見つけた！？なんだったら…\n堂々と出て行って、操縦させてもらおうよ。",
  ui_story_1021_10210301_17_dialog_content = "今出て行っても誤解が大きくなるだけってモンよ。\nもう少しで…ダメだ、暗すぎて力が入んねえ…",
  ui_story_1021_10210301_18_dialog_content = "明かりならあるよ！",
  ui_story_1021_10210301_19_dialog_content = "…まったくまぶしいねェ…ってか、今どこだ？",
  ui_story_1021_10210301_20_dialog_content = "R・W砂漠から最低でも数百キロは離れてるんじゃん？\n外がどんどん白くなってくるけど、まさか北境じゃないよね…",
  ui_story_1021_10210301_21_dialog_content = "んなら、気流の異常があってもおかしくねえな…",
  ui_story_1021_10210301_22_dialog_content = "チッ…俺の思ってた構造と違ぇな。\nこりゃ直しようねえかもなァ。",
  ui_story_1021_10210301_23_dialog_content = "思ってたのと違うとか言ってる場合？命がかかってんだよ！\nあたしにやらせて！",
  ui_story_1021_10210301_24_dialog_content = "…さっき、昇降舵がおかしいって言ってたよね？",
  ui_story_1021_10210301_25_dialog_content = "まあ、んなトコだ。\n啓光の飛行機にゃ伝動軸の類は一切ついてないんでねェ…",
  ui_story_1021_10210301_26_dialog_content = "…伝動軸が折れちゃってるからじゃなくて！？",
  ui_story_1021_10210301_27_dialog_content = "そうか…だったら、何か使えるモンがねえか、ポケットでも探ってみるかねェ。\nとりあえず、レンチで頑張っといてくれ。",
  ui_story_1021_10210301_28_dialog_content = "もうっ！ちょっとは危機感持ってよ！",
  ui_story_1021_10210301_29_dialog_content = "<color=#e8d9bb>ドーーーン！！！</color>",
  ui_story_1021_10210301_30_dialog_content = "きゃあ！！",
  ui_story_1021_10210301_31_dialog_content = "た、助かった！カレン、大丈夫？",
  ui_story_1021_10210301_32_dialog_content = "カレン？あ、血が…ま、まさか…カレン！！",
  ui_story_1021_10210301_33_dialog_content = "…！",
  ui_story_1021_10210301_34_dialog_content = "二度と飛行機なんて乗らないから！！",
  ui_story_1021_10210301_35_dialog_content = "（平気そうだ…）",
  ui_story_1021_10210301_36_dialog_content = "うん、そうだね…僕が悪かったよ…\n二度と乗らないことにしよう…",
  ui_story_1021_10210301_37_dialog_content = "それにしても、北境でこんな激しい気流に遭うなんて、\n予想してなかったな…",
  ui_story_1021_10210301_38_dialog_content = "…",
  ui_story_1021_10210301_39_dialog_content = "まぁ、こういうのも冒険にはつきものよね…",
  ui_story_1021_10210301_40_dialog_content = "とにかく、よかった。\n最後の最後で操縦レバーがちゃんと反応してくれて…",
  ui_story_1021_10210301_41_dialog_content = "あれ…！？尾翼がこんな角度になってたのに、\nよく無事に着陸できたなぁ…",
  ui_story_1021_10210301_42_dialog_content = "操縦技術を褒めてくれ、と言っているのかしら？",
  ui_story_1021_10210301_43_dialog_content = "いや…うーん、どう言えばいいんだろう…",
  ui_story_1021_10210301_44_dialog_content = "<color=#e8d9bb>コォォ――ン！</color>",
  ui_story_1021_10210301_45_dialog_content = "ここって…猛獣の縄張りだったりして…？\n辺り一面、血痕だらけなんだけど…",
  ui_story_1021_10210301_46_dialog_content = "確かに戦闘の痕跡があるわね。しかも新しいわ…\n氷の宮殿からはだいぶ離れているし、暗鬼かもしれない…",
  ui_story_1021_10210301_47_dialog_content = "暗鬼…ということは、ここは灯台の力が及ばない所ってことだね…",
  ui_story_1021_10210301_48_dialog_content = "灯台の力の及ばない北境の地は、あなたの想像よりもずっと広いの。\n特に北部は、暗鬼の無法地帯といってもいいわ…",
  ui_story_1021_10210301_49_dialog_content = "話には聞いていたけれど、こうして目の当たりにしてみると、想像以上に恐ろしい光景ね…",
  ui_story_1021_10210301_50_dialog_content = "…",
  ui_story_1021_10210301_51_dialog_content = "…向こうから人の声がするわ！",
  ui_story_1021_10210301_52_dialog_content = "見に行ってみよう。",
  ui_story_1021_10210301_53_dialog_content = "フンッ！",
  ui_story_1021_10210301_54_dialog_content = "おやおや、お嬢ちゃん。そんなふうににらまれても、オッさん困るんだけどねェ。\n言っただろう？ここへは仕方なく来たんだって。",
  ui_story_1021_10210301_55_dialog_content = "そんなに信じられねえってんなら、\n機内に操縦士バッジがあるから、ちょっくら取ってくるよ…",
  ui_story_1021_10210301_56_dialog_content = "ロイ兄、操縦士バッジなんてあったっけ？",
  ui_story_1021_10210301_57_dialog_content = "チッ…まったく、ガキんちょと一緒だと面倒なことばかりだねェ。\nまたバッジを失くしたか。探してきてやるよ。",
  ui_story_1021_10210301_58_dialog_content = "待ちなさい！",
  ui_story_1021_10210301_59_dialog_content = "放っておけ。",
  ui_story_1021_10210301_60_dialog_content = "大ババ様！ど、どうしてここに！？大ババ様は…",
  ui_story_1021_10210301_61_dialog_content = "心配はいらぬ。",
  ui_story_1021_10210301_62_dialog_content = "村が一晩でこんなになってしまったんだから、心配もします！\n大ババ様は黒い血を流した狐たちを見なかったんですか？",
  ui_story_1021_10210301_63_dialog_content = "そなたは戻ってくるべきではない。",
  ui_story_1021_10210301_64_dialog_content = "大ババ様はいつだって私を追い返そうとしますが…\nここは、私の故郷なんです…！",
  ui_story_1021_10210301_65_dialog_content = "…ティアラ？",
  ui_story_1021_10210301_66_dialog_content = "さあ、私が張った防壁の中で待て。",
  ui_story_1021_10210301_67_dialog_content = "申し訳ございません、私は女王陛下の護衛でありながら、\nこれでは何のためにいるのか…",
  ui_story_1021_10210301_68_dialog_content = "ですが、どうかこのティアラを置き去りにして、\nお一人で暗鬼の群れに飛び込むことはおやめください！",
  ui_story_1021_10210301_69_dialog_content = "必要とあらば、私が女王陛下に代わって突撃します！",
  ui_story_1021_10210301_70_dialog_content = "女王陛下の護衛さん…？",
  ui_story_1021_10210301_71_dialog_content = "あなたたちは…",
  ui_story_1021_10210301_72_dialog_content = "どうしてここに？いったい…何があったの？",
  ui_story_1021_10210301_73_dialog_content = "…",
  ui_story_1021_10210301_74_dialog_content = "（伝説の雪狐かな…？あの目つき、なんだか…帰れって言ってるみたい…）",
  ui_story_1021_10210301_75_dialog_content = "私たちは…女王陛下に謁見したくて来たの。\nだけど飛行機が乱気流に遭って、この近くに不時着してしまったのよ。",
  ui_story_1021_10210301_76_dialog_content = "…",
  ui_story_1021_10210301_77_dialog_content = "…お騒がせして、申し訳ありません。",
  ui_story_1021_10210301_78_dialog_content = "じゃあ、あの2人も一緒に来たの？",
  ui_story_1021_10210301_79_dialog_content = "あの2人？",
  ui_story_1021_10210301_80_dialog_content = "…あ、さっきまでいたのに！",
  ui_story_1021_10210301_81_dialog_content = "手にヘンな物を持って、身振り手振りで私の友達に話してて、\n飛行機の操縦士だとかって言ってた。",
  ui_story_1021_10210301_82_dialog_content = "飛行機には、僕とカレンしか乗ってなかったけど…",
  ui_story_1021_10210301_83_dialog_content = "ウソだ！",
  ui_story_1021_10210301_84_dialog_content = "ティアラ、まずは落ち着いてちょうだい。",
  ui_story_1021_10210301_85_dialog_content = "もしその2人があなたやお友達を傷つけたのなら、\n私もPlayerNameも、その2人を許さないわ。",
  ui_story_1021_10210301_86_dialog_content = "ただ…今ここが故郷だと言っていたわね…？",
  ui_story_1021_10210301_87_dialog_content = "…ここは北境の辺境地帯で、暗鬼が出没するから…",
  ui_story_1021_10210301_88_dialog_content = "女王陛下の命を受けて…\nこの辺りのスノーシダーの森を巡回してたんだよ。",
  ui_story_1021_10210301_89_dialog_content = "そうだったの…それなら、巡回が終わった後、\n私たちを女王陛下の所へ連れて行ってくれないかしら？",
  ui_story_1021_10210301_90_dialog_content = "僕たちだけじゃ、どうやって氷の宮殿に行くのか分からないし、\nもし暗鬼と戦うっていうなら、助けになれるよ！",
  ui_story_1021_10210301_91_dialog_content = "<color=#e8d9bb>コオォーン――！</color>",
  ui_story_1021_10210301_92_dialog_content = "ダメ！！",
  ui_story_1021_10210301_93_dialog_content = "えっと、その…氷の宮殿までは距離があるし、危険なんだ。\n早くここを離れた方がいいよ。",
  ui_story_1021_10210301_94_dialog_content = "あ…",
  ui_story_1021_10210301_95_dialog_content = "（ティアラの様子がおかしい…）",
  ui_story_1021_10210301_96_dialog_content = "ねえ、いったい何があったのか、話してくれないかな？",
  ui_story_1021_10210301_97_dialog_content = "…",
  ui_story_1021_10210301_98_dialog_content = "女王陛下に会いに行くんだよね？だったら…",
  ui_story_1021_10210301_99_dialog_content = "あのウサギの足跡をたどれば、着くはずだよ。",
  ui_story_1021_10210301_100_dialog_content = "女王陛下に会ったら、伝えといて…\n足跡はきれいに掃除します。でも、それは今ではありませんって。",
  ui_story_1021_10210301_101_dialog_content = "…",
  ui_story_1021_10210301_102_dialog_content = "行っちゃったね…",
  ui_story_1021_10210301_103_dialog_content = "まさか、本当に北境に雪狐の村があったとはね…",
  ui_story_1021_10210301_104_dialog_content = "北境に留学していた時に地元の人から聞いたんだけど…",
  ui_story_1021_10210301_105_dialog_content = "かつて北境北西部の辺境の地に、スノーシダーの森と共生する雪狐の村があったらしいの。",
  ui_story_1021_10210301_106_dialog_content = "村はスノーシダーの森とその下に眠る遺跡を守っていると。",
  ui_story_1021_10210301_107_dialog_content = "実際に見たという人がいないから、実在するのか誰にも分からないようだったけれど…\nただ、光霊を毛嫌いしているというのは本当のようね…",
  ui_story_1021_10210301_108_dialog_content = "傷ついた雪狐をかばうように立っていたティアラの姿を見た？",
  ui_story_1021_10210301_109_dialog_content = "うん…それと、あの年配の雪狐の僕らを見る目は…\nまるで長年の敵を見てるみたいだった…",
  ui_story_1021_10210301_110_dialog_content = "血痕はおそらく雪狐のものだわ。",
  ui_story_1021_10210301_111_dialog_content = "この血痕って黒かったり、赤かったり、\n見てると何だかクラクラしてくる…",
  ui_story_1021_10210301_112_dialog_content = "雪狐の中には自然の力が源となって生まれた「山の精霊」が存在していて、\n自然が暗力の侵食を受けると、彼らの身体にも異変が起こると聞いたことがあるわ。",
  ui_story_1021_10210301_113_dialog_content = "気分が悪くなったのは、血痕の中に残っている暗力のせいかもしれない。",
  ui_story_1021_10210301_114_dialog_content = "暗力…だとしたら、ティアラに頼まれた女王陛下への伝言の意味は、\n字面ほど単純じゃないってことか…",
  ui_story_1021_10210301_115_dialog_content = "これまでの状況から考えると、暗鬼が北境に侵入し、\n雪狐が被害に遭っただけでなく、拠点も破壊されたということかもしれない…",
  ui_story_1021_10210301_116_dialog_content = "だから、女王陛下は今も使いを出せず…",
  ui_story_1021_10210301_117_dialog_content = "だとすれば、ティアラが危険よ！",
  ui_story_1021_10210301_118_dialog_content = "追いかけよう！もしもの時は、僕らも手伝うんだ！",
  ui_story_1021_10210301_119_dialog_content = "血痕をたどりましょう！辺境地帯は暗鬼が多いわ。\n私たちも気を付けて行くのよ！",
  ui_story_1021_10210401_1_dialog_content = "血痕が途切れている…？それに…血痕を見過ぎたのかしら？\n頭がクラクラしてきたわ…",
  ui_story_1021_10210401_2_dialog_content = "感知能力で…手がかりを探ってみるよ…",
  ui_story_1021_10210401_3_dialog_content = "PlayerName。あなた、この間の事件以降感知能力を使っていなかったわよね。\nもう…怖くはないの？",
  ui_story_1021_10210401_4_option_content = "うーん…",
  ui_story_1021_10210401_5_dialog_content = "確かにここしばらくの間、感知能力のことを考えると、\n気持ちが落ち着かなくなるんだ…",
  ui_story_1021_10210401_6_option_content = "まだ少し怖い",
  ui_story_1021_10210401_7_dialog_content = "ここしばらくの間、感知能力のことを考えると、\n気持ちが乱れちゃうんだ…",
  ui_story_1021_10210401_8_dialog_content = "また遥か昔の光景が見えてしまうかもしれない、\nエンジニアに見られているかもしれない、って不安になるの？",
  ui_story_1021_10210401_9_dialog_content = "うん。バイスやソラヴァンに関する良くないことが見えたり、\n聞こえたりするんじゃないかってことも…",
  ui_story_1021_10210401_10_dialog_content = "あなたにとってとても衝撃的だものね。でも――",
  ui_story_1021_10210401_11_dialog_content = "でも、今言ったことを除いたら、感知能力は僕にとっての戦いの術で、\n皆を守る手段であることには変わりない。",
  ui_story_1021_10210401_12_dialog_content = "だから、どんなことがあろうと、恐怖に打ち勝って、\nもっとうまく感知能力を使えるように練習しなきゃ！",
  ui_story_1021_10210401_13_dialog_content = "カレン、ありがとう、心配してくれて。\nもう大丈夫。",
  ui_story_1021_10210401_14_dialog_content = "こんなに早く立ち直ってくれてよかったわ、PlayerName。",
  ui_story_1021_10210401_15_dialog_content = "忘れないで。私はずっと側にいる。\n感知の途中であなたに何かあったら、私も一緒に立ち向かうから。",
  ui_story_1021_10210401_16_dialog_content = "うん！",
  ui_story_1021_10210401_17_option_content = "精神感知――",
  ui_story_1021_10210401_18_dialog_content = "（がらんとした洞窟だな…）",
  ui_story_1021_10210401_19_dialog_content = "（ここの氷はだいぶ昔にできたものだね）",
  ui_story_1021_10210401_20_dialog_content = "…ありゃあ、R・Wのラリーに参戦したら、きっと優勝だろうねェ…",
  ui_story_1021_10210401_21_dialog_content = "足で四輪と張り合えるワケないじゃん。あれ？待って…\nなんかツンとする匂いがしない？",
  ui_story_1021_10210401_22_dialog_content = "（…この声…どこから聞こえてくるんだろう？）",
  ui_story_1021_10210401_23_dialog_content = "（…黒い血痕と赤い血痕…地面にあったのと同じだ！）",
  ui_story_1021_10210401_24_dialog_content = "（とりあえず、自分の意識を操ることはできるね…）",
  ui_story_1021_10210401_25_dialog_content = "（そうだ、ティアラはここに来たってことは…\nこの洞窟はスノーシダーの森の下にあるのかな…？）",
  ui_story_1021_10210401_26_dialog_content = "ものの腐った匂いだな…\nレディーゼルオイルの香りが懐かしくなってくるねェ…",
  ui_story_1021_10210401_27_dialog_content = "…早くライトを消すんだ。わけの分かんねえモンを引き付けちまったら、\n必死で寒さこらえてる甲斐もねえからな。",
  ui_story_1021_10210401_28_dialog_content = "なんで雪原を歩かずに、こんなとこでコソコソしなきゃいけないの…？\n道を聞くことさえできないよ。",
  ui_story_1021_10210401_29_dialog_content = "ロイ兄、言ってなかったっけ？\n「地下」が大嫌いだって。",
  ui_story_1021_10210401_30_dialog_content = "（どうして、この2人が！？）",
  ui_story_1021_10210401_31_dialog_content = "（ここは分かれ道が多い…2人はどこから入ってきたんだろう…？）",
  ui_story_1021_10210401_32_option_content = "感知展延――",
  ui_story_1021_10210401_33_dialog_content = "…",
  ui_story_1021_10210401_34_dialog_content = "何が見えたの？",
  ui_story_1021_10210401_35_dialog_content = "ティアラの言ってた侵入者は、\nR・Wの僕の知り合いだったみたいだ…",
  ui_story_1021_10210401_36_dialog_content = "…それと、視野を広げた時、\n蒸気みたいに膨張する暗力が見えたような…",
  ui_story_1021_10210401_37_dialog_content = "ここから、すごく近い…",
  ui_story_1021_10210401_38_dialog_content = "…！",
  ui_story_1021_10210401_39_dialog_content = "しかも洞窟の中には、雪原で見たのとまったく同じ血痕があった…\nティアラもきっとそこにいる…",
  ui_story_1021_10210401_40_dialog_content = "だったら、急ぎましょう！どの方向へ向かえばいいの？",
  ui_story_1021_10210401_41_dialog_content = "血痕はここで途絶えてる。\nだったら洞窟はこのスノーシダーの森の裏だ。ついてきて！",
  ui_story_1021_10210401_42_dialog_content = "（ティアラ、それにロイとタイニー…絶対に無事でいてよ…）",
  ui_story_1021_10210401_43_dialog_content = "<color=#e8d9bb>クウゥ…</color>",
  ui_story_1021_10210401_44_dialog_content = "古の偉大なる神よ。ティアラは永遠にあなた様をあがめるでしょう。\nあなた様が私たちを永遠に見守ってくださるように。",
  ui_story_1021_10210401_45_dialog_content = "暗黒が再び影を落とし、恐ろしい捕食者のごとく私たちの身体をむしばんでは、\nその身体に決して消すことのできない烙印を残しています。",
  ui_story_1021_10210401_46_dialog_content = "氷の宮殿では、私は女王陛下の護衛であり…",
  ui_story_1021_10210401_47_dialog_content = "ここでは、村を守ると誓った村の長です。",
  ui_story_1021_10210401_48_dialog_content = "あなた様が村を育み、その神聖なる血脈を授けてくださったことで、\nわが一族はあなた様とつながることができました。",
  ui_story_1021_10210401_49_dialog_content = "ですが、今残された者たちは、日夜苦痛に耐え、その肉体は打ち砕かれています…\n私たちは皆いつの日か、あなた様の懐に帰らねばならないことはわかっています。",
  ui_story_1021_10210401_50_dialog_content = "ただ、先祖と村があなた様の加護を賜ったように、\nもう一度その慈愛をわが一族に賜りますようお願い申し上げます。",
  ui_story_1021_10210401_51_dialog_content = "<color=#e8d9bb>コオォーン――！</color>",
  ui_story_1021_10210401_52_dialog_content = "誤ってこの地に入った光霊らが危険に見舞われておるようだが、\nわしにはもう、やつらを追い払うことはできぬ…",
  ui_story_1021_10210401_53_dialog_content = "大ババ様、これはそもそも私の務めです…",
  ui_story_1021_10210401_54_dialog_content = "ティアラ！その手に握る槍をよく見るのじゃ！\nそなたは北境の護衛…村のことはもう気に掛けるな…",
  ui_story_1021_10210401_55_dialog_content = "…ゲホッ、ゴホゴホ…",
  ui_story_1021_10210401_56_dialog_content = "大ババ様…お願いです…一族が滅びようとしている時に、\n手をこまねいているわけにはいきません…",
  ui_story_1021_10210401_57_dialog_content = "そなたは…戻ってきてはならない…",
  ui_story_1021_10210401_58_dialog_content = "私はいったい…どうすれば…",
  ui_story_1021_10210401_59_dialog_content = "<color=#e8d9bb>ポタッ――ポタッ――</color>",
  ui_story_1021_10210401_60_dialog_content = "うわっ！",
  ui_story_1021_10210401_61_dialog_content = "路面が凍った道は滑りやすいから、気を付けるのよ。\nそれにしても、おかしいわ…なぜ水滴が落ちてきているの？",
  ui_story_1021_10210401_62_dialog_content = "水たまりなら、さっきからずっとあるよ。\n今滑ったのはきっと、このなんとも耐えがたい匂いにやられちゃったせいかも…",
  ui_story_1021_10210401_63_dialog_content = "いや、待って！何か柔らかいものを踏んづけた気が…\nちょっと見てくれるかな…？",
  ui_story_1021_10210401_64_dialog_content = "雪狐…のようね…",
  ui_story_1021_10210401_65_dialog_content = "まだ…生きてる…？",
  ui_story_1021_10210401_66_dialog_content = "…",
  ui_story_1021_10210401_67_dialog_content = "た、大変だ…急に目の前が真っ白になってきた…",
  ui_story_1021_10210401_68_dialog_content = "しっかりして！この先に、何か本当に白いものがあるようよ…",
  ui_story_1021_10210401_69_dialog_content = "<color=#e8d9bb>ポタッ――ポタッ――</color>",
  ui_story_1021_10210401_70_dialog_content = "タイニー、俺の錯覚かねェ？\nこうやって歩いてるうちに、何だかお迎えが来そうな気がするんだが…",
  ui_story_1021_10210401_71_dialog_content = "どんどん暑くなってくるねェ…\nいつの間にか身体に力が入らなくなってきたぞ。",
  ui_story_1021_10210401_72_dialog_content = "だったら、この宝石を持ってて。",
  ui_story_1021_10210401_73_dialog_content = "何言ってやがんだ…タダでもらえるモンをもらわないなんて…",
  ui_story_1021_10210401_74_dialog_content = "わっ、触らないでって！ロイ兄の手、汗でベトベトなんだけど！",
  ui_story_1021_10210401_75_dialog_content = "お、おい…！急に強い光を出すんじゃねえよ…\n強い光にはな、面倒なモンがつきもんなんだよ。",
  ui_story_1021_10210401_76_dialog_content = "そこの2人！",
  ui_story_1021_10210401_77_dialog_content = "噂をすれば何とやらだねェ…",
  ui_story_1021_10210401_78_dialog_content = "こんにちは…",
  ui_story_1021_10210401_79_dialog_content = "よう、PlayerName。お前たちも宝さがしか？",
  ui_story_1021_10210401_80_dialog_content = "宝さがしですって！？\nあなたたち、何が目的で飛行機に潜んでいたの？",
  ui_story_1021_10210401_81_dialog_content = "おや、うちのお頭が申し込みを忘れちまったのかねェ。\n俺たちゃ、アストラ大陸合同探索会議のR・W代表なんだが。",
  ui_story_1021_10210401_82_dialog_content = "ただ会議ってモンはまったく退屈だねェ。\n居眠りから覚めたら、こんなトコに売り飛ばされていようとは…",
  ui_story_1021_10210401_83_dialog_content = "その大きなバッグは北境の宝石を盗むために用意したものでしょう？\n悪い事は言わないわ。元の場所に戻してきなさい！",
  ui_story_1021_10210401_84_dialog_content = "おおっ…ここは北境だったのか！ハハッ、実はオッさんR・W砂漠から出たことなくてねェ。\n宝石がどこにあるかなんて知らないなァ。",
  ui_story_1021_10210401_85_dialog_content = "ただ、さっきついでに機械を直しといたんだ。\nお礼としてこれをくれるってなら、喜んで受け取るけどねェ。",
  ui_story_1021_10210401_86_dialog_content = "あなたたち――！！",
  ui_story_1021_10210401_87_dialog_content = "カレン、待って…どういうことか、分かった気がする。",
  ui_story_1021_10210401_88_dialog_content = "この2人はR・Wでも優秀なエンジニアだよ。\n飛行機内で制御室から離れた所といえば、尾翼近くの修理室しかない。",
  ui_story_1021_10210401_89_dialog_content = "あの尾翼で飛行機が安全に不時着できたのは…\nたぶん2人が修理室に隠れてて、ついでに飛行機を修理してくれたからだよ…",
  ui_story_1021_10210401_90_dialog_content = "それは…本当なの？",
  ui_story_1021_10210401_91_dialog_content = "あの…飛行機のこと、ありがとう…",
  ui_story_1021_10210401_92_dialog_content = "いいってことよ。合同探索する仲じゃねえか。\n助け合うのが筋ってモンだろう？",
  ui_story_1021_10210401_93_dialog_content = "<color=#e8d9bb>ポタッ――ポタッ――</color>",
  ui_story_1021_10210401_94_dialog_content = "それはそうとしても、北境の宝石を持ち出すのは許されない。\n報酬は戻ってから、代わりに白夜コインをあげるわ。",
  ui_story_1021_10210401_95_dialog_content = "白夜コイン…まっ…いいか。",
  ui_story_1021_10210401_96_dialog_content = "ロイ、タイニー。この辺りは危険なんだ。\n雪狐と一緒にいた女の子がどこへ行ったか知ってる？",
  ui_story_1021_10210401_97_dialog_content = "知ってるさ。ただ何しろ足が速くってねェ。\nまったく追いつけねえときた。",
  ui_story_1021_10210401_98_dialog_content = "隠れてただけじゃん…",
  ui_story_1021_10210401_99_dialog_content = "PlayerName、この洞窟の中にはキツネの死骸がたくさんあるけど、\nあの子の連れてたキツネも大けがしてるみたいだったよ。",
  ui_story_1021_10210401_100_dialog_content = "だったら、早く見つけなきゃ…",
  ui_story_1021_10210401_101_dialog_content = "あなたたちは道が分かるようだから、案内してちょうだい。",
  ui_story_1021_10210401_102_dialog_content = "…ここはまだいいんだが、中はキツイなァ。分かれ道が多いんだよ…\n俺とタイニーも道に迷うトコだった。",
  ui_story_1021_10210401_103_dialog_content = "ロイ兄！あたしのライトが…",
  ui_story_1021_10210401_104_dialog_content = "光が弱くなったな。",
  ui_story_1021_10210401_105_dialog_content = "暗力が濃くなったってことだね…",
  ui_story_1021_10210401_106_dialog_content = "あったけえ所は好きなんだが、すまんな、PlayerName、白夜コインのお嬢ちゃん。\n俺とタイニーはここで失礼するぞ！",
  ui_story_1021_10210401_107_dialog_content = "まったく…助け合うのが当然と言った矢先に…\nさて、どちらの道へ進むべきかしら？",
  ui_story_1021_10210401_108_dialog_content = "感知能力で探ってみるよ。",
  ui_story_1021_10210401_109_option_content = "感知展延――",
  ui_story_1021_10210401_110_dialog_content = "貪…瞋…痴…それは、身と心を毒する虚無。",
  ui_story_1021_10210401_111_dialog_content = "瞋がために怒りを生じ、怒りがために病むのです。",
  ui_story_1021_10210401_112_dialog_content = "そう…そうです…",
  ui_story_1021_10210401_113_dialog_content = "傲慢が…また少し消えました…",
  ui_story_1021_10210401_114_dialog_content = "（暗鬼！？）",
  ui_story_1021_10210401_115_dialog_content = "（ハッキリは見えないけど…さっき感じた、あの感覚と同じだ…）",
  ui_story_1021_10210401_116_dialog_content = "（ヤツの周りの暗力は…うっ、頭が…力いっぱい殴られたみたいだ…）",
  ui_story_1021_10210401_117_dialog_content = "ご報告いたします――！",
  ui_story_1021_10210401_118_dialog_content = "むむ…？",
  ui_story_1021_10210401_119_dialog_content = "グアア――！",
  ui_story_1021_10210401_120_dialog_content = "（……！）",
  ui_story_1021_10210401_121_dialog_content = "…",
  ui_story_1021_10210401_122_dialog_content = "抑えなければ…抑えなければ…",
  ui_story_1021_10210401_123_dialog_content = "…あ、あの…",
  ui_story_1021_10210401_124_dialog_content = "心配しないでください。近づいて構いません。\n傷つけはしません。",
  ui_story_1021_10210401_125_dialog_content = "はい…",
  ui_story_1021_10210401_126_dialog_content = "ご報告いたします…不愉快な光霊どもが近くまで来ております…",
  ui_story_1021_10210401_127_dialog_content = "…",
  ui_story_1021_10210401_128_dialog_content = "や、やつらが…ご修行の邪魔になるかと思いまして…",
  ui_story_1021_10210401_129_dialog_content = "近くとは、どこですか？",
  ui_story_1021_10210401_130_dialog_content = "すでに砦を越えました。",
  ui_story_1021_10210401_131_dialog_content = "<color=#FFB400>雪国</color>も…ずいぶんと変わってしまったものです…",
  ui_story_1021_10210401_132_dialog_content = "変わってしまって以降、この地には戻っていませんでした。",
  ui_story_1021_10210401_133_dialog_content = "変わる…",
  ui_story_1021_10210401_134_dialog_content = "変わるとは、実に残酷な剥奪です！",
  ui_story_1021_10210401_135_dialog_content = "あ、あの…",
  ui_story_1021_10210401_136_dialog_content = "感謝します…そうです…抑えなければ…抑えなければ…",
  ui_story_1021_10210401_137_dialog_content = "<color=#e8d9bb>ポタッ――ポタッ――</color>",
  ui_story_1021_10210401_138_dialog_content = "ここの氷が融けてるのは…あの暗鬼の暗力のせいだ…",
  ui_story_1021_10210401_139_dialog_content = "PlayerName…今度は何を見たの？\nなぜ、そんな顔をしているの？",
  ui_story_1021_10210401_140_dialog_content = "今、暗鬼が見えたんだ…",
  ui_story_1021_10210401_141_dialog_content = "よく考えてみたんだが、やっぱり一緒に行こうや！",
  ui_story_1021_10210401_142_dialog_content = "よく戻ってこられたわね？",
  ui_story_1021_10210401_143_dialog_content = "PlayerName、前！急にたくさん暗鬼が現れたよ！",
  ui_story_1021_10210401_144_dialog_content = "グア――！！！",
  ui_story_1021_10210401_145_dialog_content = "カレン、危ない！",
  ui_story_1021_10210401_146_dialog_content = "あなたたちが引き寄せてきたのでしょう！？",
  ui_story_1021_10210401_147_dialog_content = "…タイニー、俺の後ろにいろ！",
  ui_story_1021_10210401_148_dialog_content = "こんな近くにいるのに…普通の暗力だ。\nさっきの膨張していく感じとは違う…",
  ui_story_1021_10210401_149_dialog_content = "PlayerName、ぼうっとしていないで、戦闘指揮をお願い！",
  ui_story_1021_10210401_150_dialog_content = "うん！",
  ui_story_1021_10210402_1_dialog_content = "氷が溶ければそれで終わりだ。",
  ui_story_1021_10210402_2_dialog_content = "全部消えちゃった！",
  ui_story_1021_10210402_3_dialog_content = "皆無事か？",
  ui_story_1021_10210402_4_dialog_content = "女王陛下！なぜこちらに！？",
  ui_story_1021_10210402_5_dialog_content = "間欠泉の辺りにいた時、そなたの光力術を感じた。",
  ui_story_1021_10210402_6_dialog_content = "<color=#e8d9bb>少し前…</color>",
  ui_story_1021_10210402_7_dialog_content = "<color=#e8d9bb>ブクブク――ブクブク――ボンッ！</color>",
  ui_story_1021_10210402_8_dialog_content = "女王陛下、あれは…",
  ui_story_1021_10210402_9_dialog_content = "境界線上にある<color=#FFB400>間欠泉</color>だ。長い間活動が止まっていたが、最近また動き出した。\nまるで時計のように、その時が来ると、北境の傷をさらけ出すのだ…",
  ui_story_1021_10210402_10_dialog_content = "あの湧き出す黒き水の中には暗力が混じっている。\n北境の樹木や建物、そして罪なき村を滅ぼした…",
  ui_story_1021_10210402_11_dialog_content = "鏡の中で私も目にいたしました。ここのところ頻繁に暗面のエネルギーに異常が見られます。\n女王陛下、どうなさるおつもりですか？",
  ui_story_1021_10210402_12_dialog_content = "次の噴出が終わり次第、中に入り、暗鬼と対するとしよう。",
  ui_story_1021_10210402_13_dialog_content = "そなたの北国の鏡には光力が満ちておる。\n私が中に入った後は、この暗力が広がらぬよう頼んだぞ。",
  ui_story_1021_10210402_14_dialog_content = "承知いたしました、女王陛下。",
  ui_story_1021_10210402_15_dialog_content = "<color=#e8d9bb>ブクブク――ブクブク――ボンッ！</color>",
  ui_story_1021_10210402_16_dialog_content = "おや…？",
  ui_story_1021_10210402_17_dialog_content = "女王陛下、なぜ眉をしかめられたのですか？",
  ui_story_1021_10210402_18_dialog_content = "よく知る光力の扱い方だ。",
  ui_story_1021_10210402_19_dialog_content = "待たずに中に入るとしよう。あとは頼んだぞ。",
  ui_story_1021_10210402_20_dialog_content = "…はい、女王陛下。",
  ui_story_1021_10210402_21_dialog_content = "あの無惨な光景は…間欠泉の噴出が原因だったのですか…",
  ui_story_1021_10210402_22_dialog_content = "大量の暗鬼も暗力をたどり集まってきた。ゆえに弱者たる雪狐たちが犠牲となった。\nそなたらも洞窟で目にしたであろう。",
  ui_story_1021_10210402_23_dialog_content = "次の噴出までに、急ぎここを離れよ。",
  ui_story_1021_10210402_24_dialog_content = "でも…さっきこの近くに強大な暗鬼の存在を感知したんです…",
  ui_story_1021_10210402_25_dialog_content = "もともとは北境の拠点の件について、お話ししに来たんですが、\n予想外のことがあって、この付近に不時着しました。",
  ui_story_1021_10210402_26_dialog_content = "その後、ケガをした雪狐を連れたティアラに会ったんですが、\n様子がおかしかったので…",
  ui_story_1021_10210402_27_dialog_content = "心配になり、ここまで追ってきたのです。\nそれはそうと…R・Wの2人はどこへいったのかしら？",
  ui_story_1021_10210402_28_dialog_content = "…",
  ui_story_1021_10210402_29_dialog_content = "女王陛下、ここは王室の守護範囲ではありません…",
  ui_story_1021_10210402_30_dialog_content = "そこで護衛のティアラを送り、この辺りの暗鬼を調査させていたということですか？",
  ui_story_1021_10210402_31_dialog_content = "「女王陛下の護衛」というのは、\nティアラが「王室の護衛」を真似て、自ら名乗っている称号です。",
  ui_story_1021_10210402_32_dialog_content = "「王室の護衛」になるには、北境を守ることの意味を理解せねばなりません。\nそして、それは北境の民にとって永遠の問いでもあるのです。",
  ui_story_1021_10210402_33_dialog_content = "ノーヴィオ閣下！",
  ui_story_1021_10210402_34_dialog_content = "カレン殿下、PlayerName様、ごきげんよう。",
  ui_story_1021_10210402_35_dialog_content = "来たか。だが、すでに承知している。",
  ui_story_1021_10210402_36_dialog_content = "陛下はティアラが氷の宮殿を離れ、\n村に戻るであろうことをすでに予見していらしたのです。",
  ui_story_1021_10210402_37_dialog_content = "やはり…ティアラは伝説の雪狐の村出身だったのですね。\nそれだけでなく…ティアラはどうやら…",
  ui_story_1021_10210402_38_dialog_content = "ティアラは雪狐の村の長です。",
  ui_story_1021_10210402_39_dialog_content = "村の長！？",
  ui_story_1021_10210402_40_dialog_content = "まさか…村にはもう…\n彼女より年上の者がいないということですか…？",
  ui_story_1021_10210402_41_dialog_content = "…",
  ui_story_1021_10210402_42_dialog_content = "あの…ティアラから伝言を頼まれたんです。\n「足跡はきれいに掃除します。でも、それは今ではありません」と…",
  ui_story_1021_10210402_43_dialog_content = "どういう意味なんでしょうか？",
  ui_story_1021_10210402_44_dialog_content = "永遠の問いだ…私も成し遂げられてはおらぬ…",
  ui_story_1021_10210402_45_dialog_content = "陛下は北境の巡視時、\nこの地をおろそかにしたことは一度もございません。",
  ui_story_1021_10210402_46_dialog_content = "私の責任だ。ノーヴィオ、皆を連れてここを離れろ。\n私はティアラを探しに行かねばならぬ。",
  ui_story_1021_10210402_47_dialog_content = "陛下、ティアラであれば、すでに見つけております。",
  ui_story_1021_10210402_48_dialog_content = "そうか。",
  ui_story_1021_10210402_49_dialog_content = "あの…！さっき感知した強烈な暗力が近づいてきます…",
  ui_story_1021_10210402_50_dialog_content = "私のことですか？",
  ui_story_1021_10210402_51_dialog_content = "…！極光の刃よ！",
  ui_story_1021_10210402_52_dialog_content = "急ぎ防壁の中へ！",
  ui_story_1021_10210402_53_dialog_content = "あなたが、傲慢にも雪国の女王を名乗っている方ですか？\nどうやら私は…多くの機会を逃したようです。",
  ui_story_1021_10210402_54_dialog_content = "…突然、こんな近くに現れるなんて…！？",
  ui_story_1021_10210402_55_dialog_content = "あなたは…",
  ui_story_1021_10210402_56_dialog_content = "<color=#FFB400>ナダス</color>がその脳みそを美酒と化し、\nあなたの同胞たちに味わわせてやることでしょう。",
  ui_story_1021_10210402_57_dialog_content = "同胞たち…？何を言ってるの？",
  ui_story_1021_10210402_58_dialog_content = "美酒に…",
  ui_story_1021_10210402_59_dialog_content = "美酒に化してあげましょう…",
  ui_story_1021_10210402_60_dialog_content = "う、ううっ…",
  ui_story_1021_10210402_61_dialog_content = "（ヤツの暗力が…女王陛下の防壁を圧倒しようとしてる…）",
  ui_story_1021_10210402_62_dialog_content = "…極寒の力よ！守りたまえ！",
  ui_story_1021_10210402_63_dialog_content = "陛下、私たちがいては戦いのお邪魔となりましょう。\n皆さまのことはお任せください。",
  ui_story_1021_10210402_64_dialog_content = "…頼んだぞ、ノーヴィオ。",
  ui_story_1021_10210402_65_dialog_content = "女王陛下、共に戦わせてください！",
  ui_story_1021_10210402_66_dialog_content = "ここを離れるのだ。命令だ。",
  ui_story_1021_10210402_67_dialog_content = "…",
  ui_story_1021_10210402_68_dialog_content = "カレン殿下、PlayerName様、私の霊杖の導きに従い、\n地上へお向かいください。",
  ui_story_1021_10210402_69_dialog_content = "導きとは、何のことですか？",
  ui_story_1021_10210402_70_dialog_content = "…",
  ui_story_1021_10210402_71_dialog_content = "ノーヴィオ閣下！",
  ui_story_1021_10210402_72_dialog_content = "安心して暗闇の中に留まっていなさい。",
  ui_story_1021_10210402_73_dialog_content = "極光の照らす北境に、暗闇など存在しない。\n極光の刃よ――！",
  ui_story_1021_10210402_74_dialog_content = "あの女子とは、比べものになりません。",
  ui_story_1021_10210402_75_dialog_content = "あんたなんかに女王陛下を語る資格はない！！",
  ui_story_1021_10210402_76_dialog_content = "<color=#e8d9bb>シュッ――！</color>",
  ui_story_1021_10210402_77_dialog_content = "ティアラ！戻るのだ――！",
  ui_story_1021_10210402_78_dialog_content = "私は女王陛下の護衛です。陛下の盾となるのが私の務めです！",
  ui_story_1021_10210402_79_dialog_content = "<color=#e8d9bb>カンッ――！</color>",
  ui_story_1021_10210402_80_dialog_content = "女王陛下には指一本触れさせない！\n陛下の護衛からの一撃だ、食らえ！",
  ui_story_1021_10210402_81_dialog_content = "傲慢な面持ちに…純白の力強い四肢…",
  ui_story_1021_10210402_82_dialog_content = "なるほど。教えていただきましょう。\nあなたのその瞳に映っているものは…何ですか？",
  ui_story_1021_10210402_83_dialog_content = "あんたを倒す覚悟だ！",
  ui_story_1021_10210402_84_dialog_content = "思い出します…",
  ui_story_1021_10210402_85_dialog_content = "あの女子は黒いスカートの裾をまくり、服を短く破って、\n兵士を指揮して、最速スピードで突撃を仕掛けてきました。",
  ui_story_1021_10210402_86_dialog_content = "目をそらすな！\n私のこの槍も最速スピードであんたの両目を潰す！",
  ui_story_1021_10210402_87_dialog_content = "なんとも魅力的な眼差しですが、遅すぎました…",
  ui_story_1021_10210402_88_dialog_content = "氷が溶ければそれで終わりだ！",
  ui_story_1021_10210402_89_dialog_content = "…女王陛下！？",
  ui_story_1021_10210402_90_dialog_content = "これはそなたの戦いではない。\n今すぐ私の放った氷をたどり、ここを離れるのだ！",
  ui_story_1021_10210402_91_dialog_content = "ですが…陛下はどうなさるのです？",
  ui_story_1021_10210402_92_dialog_content = "私も後に続く！ノーヴィオ、頼んだぞ！",
  ui_story_1021_10210402_93_dialog_content = "山河の霊杖よ、力を与えたまえ！",
  ui_story_1021_10210402_94_dialog_content = "あの…なぜやつらを殺さなかったのですか？",
  ui_story_1021_10210402_95_dialog_content = "あの狐の瞳の中に、己の怒りを見たからです…",
  ui_story_1021_10210402_96_dialog_content = "怒りは、弱さの表れです。\n私は怒りの奴隷にはならないと誓いました。",
  ui_story_1021_10210402_97_dialog_content = "雪国の女王…",
  ui_story_1021_10210402_98_dialog_content = "我が炎の中にあっても、その氷は固く、溶けることはない…",
  ui_story_1021_10210501_1_dialog_content = "…",
  ui_story_1021_10210501_2_dialog_content = "女王陛下、どうかされましたか…？\nなぜ、お止まりになるのです？",
  ui_story_1021_10210501_3_dialog_content = "暗力の影響を受け、通った道を覆う氷の層は\n元の岩石層を露わにしている…",
  ui_story_1021_10210501_4_dialog_content = "だが、ここは何ともない…しかも、何か特別な力を感じる。",
  ui_story_1021_10210501_5_dialog_content = "ノーヴィオ、私にはやることがある。\nそなたらは十分に注意して進め。",
  ui_story_1021_10210501_6_dialog_content = "ですが…女王陛下…",
  ui_story_1021_10210501_7_dialog_content = "…お伴させてください！",
  ui_story_1021_10210501_8_dialog_content = "…",
  ui_story_1021_10210501_9_dialog_content = "あなたがここへ来たのは陛下をお守りするためではなく、\n村を守るためでしょう？",
  ui_story_1021_10210501_10_dialog_content = "そ、それは…",
  ui_story_1021_10210501_11_dialog_content = "私の村は今、滅亡の危機に瀕しています。\n今や安全な場所はこの祭壇しかありません…",
  ui_story_1021_10210501_12_dialog_content = "私が感じたのは、祭壇の加護の力だったのか？",
  ui_story_1021_10210501_13_dialog_content = "陛下…祭壇へは…行ってはなりません！",
  ui_story_1021_10210501_14_dialog_content = "陛下の行く手を阻むとは！\nあなた、自分が何をしているのか分かっているの？ティアラ！",
  ui_story_1021_10210501_15_dialog_content = "…どんなに危険な場所であろうと、陛下が向かわれるのなら、私がお守りします。\nですが、祭壇だけは…",
  ui_story_1021_10210501_16_dialog_content = "申し訳ございません。お通しするわけにはまいりません！",
  ui_story_1021_10210501_17_dialog_content = "これは雪狐の村のリーダーとしての、先祖に対する誓いなのです！",
  ui_story_1021_10210501_18_dialog_content = "私を阻むのは、怨恨のためか？",
  ui_story_1021_10210501_19_dialog_content = "怨恨かどうかは…私には、よく分かりません…",
  ui_story_1021_10210501_20_dialog_content = "…",
  ui_story_1021_10210501_21_dialog_content = "村と王室との関係に疑念を持っているのならば、\n疑念が消えるよう、自身で確かめるがよい。",
  ui_story_1021_10210501_22_dialog_content = "だが今、私は祭壇に向かわねばならぬ。\nそれもこれも北境のためだ。ティアラ、私を信じてくれ。",
  ui_story_1021_10210501_23_dialog_content = "女王陛下！",
  ui_story_1021_10210501_24_dialog_content = "ティアラ、構わん。",
  ui_story_1021_10210501_25_dialog_content = "だ、誰が…話してるの？",
  ui_story_1021_10210501_26_dialog_content = "大ババ様！？ど、どうしてここに…\nそれに――",
  ui_story_1021_10210501_27_dialog_content = "構わん。",
  ui_story_1021_10210501_28_dialog_content = "お元気でいらっしゃいましたか？",
  ui_story_1021_10210501_29_dialog_content = "山の精霊殿が覚えていてくださったとはな。\nしぶとく生きておる。",
  ui_story_1021_10210501_30_dialog_content = "あの雪狐は…カレン、さっきの年配の雪狐が話してるよ！",
  ui_story_1021_10210501_31_dialog_content = "大げさな反応ね…それにしても、ずいぶんと回復したようね…",
  ui_story_1021_10210501_32_dialog_content = "声を聞くかぎり、女性のようだわ。",
  ui_story_1021_10210501_33_dialog_content = "…",
  ui_story_1021_10210501_34_dialog_content = "この者たちは北境の者ではない。\n長老を尊重し、すぐにこの地を離れるだろう。",
  ui_story_1021_10210501_35_dialog_content = "その必要はない。わしに敬意を示すべき者はもうこの世にはおらぬ。\nそなたらの示す敬意など同情にすぎぬのじゃろう。",
  ui_story_1021_10210501_36_dialog_content = "女王陛下に対し、何たる態度をとるのです！",
  ui_story_1021_10210501_37_dialog_content = "カレン、下がれ！",
  ui_story_1021_10210501_38_dialog_content = "…",
  ui_story_1021_10210501_39_dialog_content = "わしにはもう、さような気力は残っておらぬよ。\nこの老いし肉体を引きずり、ただ生きながらえておるだけじゃ。",
  ui_story_1021_10210501_40_dialog_content = "わしらとて、そなたらの王に敬意を払わなかったわけではない。\nだが、この洞窟の荒れようを見れば、答えはおのずと分かるのではないか？",
  ui_story_1021_10210501_41_dialog_content = "大ババ様、本当に女王陛下をお連れしても…",
  ui_story_1021_10210501_42_dialog_content = "ティアラよ。そなたにかようなことを背負わせたくはなかった。",
  ui_story_1021_10210501_43_dialog_content = "…",
  ui_story_1021_10210501_44_dialog_content = "長老、北境に侵入した暗鬼が近くに迫っている…",
  ui_story_1021_10210501_45_dialog_content = "微弱とはいえど、「大自然の力」の加護があれば、\n暗鬼は祭壇に近づけぬ。ついてくるがよい。",
  ui_story_1021_10210501_46_dialog_content = "…",
  ui_story_1021_10210501_47_dialog_content = "<color=#e8d9bb>クウゥ…</color>",
  ui_story_1021_10210501_48_dialog_content = "これが…ティアラの村が守ってる祭壇？",
  ui_story_1021_10210501_49_dialog_content = "まさか、洞窟の中にこんな場所があるとは…",
  ui_story_1021_10210501_50_dialog_content = "北境が建国されし時、わしらの先祖が築いた祭壇じゃ。",
  ui_story_1021_10210501_51_dialog_content = "何を…祭ってるんですか？",
  ui_story_1021_10210501_52_dialog_content = "北境を守る3本の松の木と、\nその森を守ってきた先祖たちじゃ。",
  ui_story_1021_10210501_53_dialog_content = "3本の松の木っていうのは…この3本の切り株のことですか…？",
  ui_story_1021_10210501_54_dialog_content = "北境を守らんとする志を持ちながら、伐られる運命を逃れることはできんかった。\nだが、その力が消えることもない。",
  ui_story_1021_10210501_55_dialog_content = "この3本の松の木が土から起こらんとする時、山々さえ道を譲る。\n空は松たちを忘れてはおらぬ。よって永遠に光が射し込んでくるのじゃ。",
  ui_story_1021_10210501_56_dialog_content = "この札に刻まれているのは…古代の文字かしら？",
  ui_story_1021_10210501_57_dialog_content = "何て書いてあるの？",
  ui_story_1021_10210501_58_dialog_content = "「神はこの世に平和をもたらす国王の疲れをいやす」",
  ui_story_1021_10210501_59_dialog_content = "「神の約束は、暗闇を光で満たす」",
  ui_story_1021_10210501_60_dialog_content = "「人々がその姿を目にする時、安寧と幸福が訪れる」",
  ui_story_1021_10210501_61_dialog_content = "もしかして…",
  ui_story_1021_10210501_62_dialog_content = "「3本松の木」の伝説を記した最古の碑文だ…",
  ui_story_1021_10210501_63_dialog_content = "北境に伝わる、あの伝説ですか？",
  ui_story_1021_10210501_64_dialog_content = "1本目の松の木は北境の初代女王を迎え、\n2本目の松の木は王室の護衛の忠誠を見…",
  ui_story_1021_10210501_65_dialog_content = "3本目の松の木は北境を治める女王の権杖となった…",
  ui_story_1021_10210501_66_dialog_content = "はははは…後継者らの虚栄心が透けて見える話じゃの…",
  ui_story_1021_10210501_67_dialog_content = "あやつがおらんでよかったわい。\nやつが聞いたら、そなたらは歯が折れるまで叩きのめされていたであろうの。",
  ui_story_1021_10210501_68_dialog_content = "だが、理解できぬわけでもない。王朝というものは、\n輝かしい歴史を創り上げたがるものじゃからの。",
  ui_story_1021_10210501_69_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_1021_10210501_70_dialog_content = "…！！！",
  ui_story_1021_10210501_71_dialog_content = "大ババ様――！",
  ui_story_1021_10210501_72_dialog_content = "す、すまん…邪魔しちまったな。\nおい、タイニー！お前のスポットライト、どうなってんだ？",
  ui_story_1021_10210501_73_dialog_content = "あ、あたしにも…わかんないよ…",
  ui_story_1021_10210501_74_dialog_content = "2人とも…まさかずっとそこに隠れていたの？",
  ui_story_1021_10210501_75_dialog_content = "邪な…ものか…",
  ui_story_1021_10210501_76_dialog_content = "PlayerName、早く友達にライトを消すように言って！\n大ババ様は身体が弱ってるの！",
  ui_story_1021_10210501_77_dialog_content = "タイニー！",
  ui_story_1021_10210501_78_dialog_content = "で、でも…消えないんだって！",
  ui_story_1021_10210501_79_dialog_content = "<color=#e8d9bb>ヒューッ――ヒューッ――</color>",
  ui_story_1021_10210501_80_dialog_content = "ランスから…何か力が湧いてくるかのよう…",
  ui_story_1021_10210501_81_dialog_content = "これって…どういうこと…？",
  ui_story_1021_10210501_82_dialog_content = "<color=#e8d9bb>ヒューッ――ヒューッ――</color>",
  ui_story_1021_10210501_83_dialog_content = "霊杖と祭壇が共鳴しています…",
  ui_story_1021_10210501_84_dialog_content = "…",
  ui_story_1021_10210501_85_dialog_content = "しかしながら、陛下の窮冬ノ力こそ選ばれし力のようです…",
  ui_story_1021_10210501_86_dialog_content = "…な、なに？",
  ui_story_1021_10210501_87_dialog_content = "この世界に平和をもたらす国王に付き従いたいものだ！",
  ui_story_1021_10210501_88_dialog_content = "（誰が話してるの…？）",
  ui_story_1021_10210501_89_dialog_content = "暗黒の世界に光をもたらさん！",
  ui_story_1021_10210501_90_dialog_content = "我は人々が我を目にした時、安寧と幸福を感じることができれば、満足である…",
  ui_story_1021_10210501_91_dialog_content = "ははは…まったく、お主らときたら…\n思い上がりもよいところだ…",
  ui_story_1021_10210501_92_dialog_content = "お主も同様であろう？ははは…",
  ui_story_1021_10210501_93_dialog_content = "3つの声が祭壇に響いてる…",
  ui_story_1021_10210501_94_dialog_content = "私にも聞こえたわ…",
  ui_story_1021_10210501_95_dialog_content = "今のは…神の声なの？",
  ui_story_1021_10210501_96_dialog_content = "…",
  ui_story_1021_10210501_97_dialog_content = "神が…そなたの力をお認めになった…",
  ui_story_1021_10210501_98_dialog_content = "目の前に多くの光景が流れてくる…",
  ui_story_1021_10210501_99_dialog_content = "神は自身が認める者の力を見分けることができるのじゃ…",
  ui_story_1021_10210501_100_dialog_content = "つまり…",
  ui_story_1021_10210501_101_dialog_content = "そなたの…そなたらの初代女王は…\n真に神の祝福を享けておったのか…",
  ui_story_1021_10210501_102_dialog_content = "なんと…",
  ui_story_1021_10210501_103_dialog_content = "この世を去った先祖たちも、思いもよらんかったろうの…",
  ui_story_1021_10210501_104_dialog_content = "<color=#e8d9bb>殺せ――！！</color>",
  ui_story_1021_10210501_105_dialog_content = "前に進み、約束を果たすならば、北境にお前たちの安息の地はある。",
  ui_story_1021_10210501_106_dialog_content = "だが、退がるのならば、私がその首を落とし、松の木の上にさらす。\n子孫たちは恥を背負い、生きていくことになろう。",
  ui_story_1021_10210501_107_dialog_content = "い、今のは…いったい誰の意識なの？\n感知能力は使ってないのに…",
  ui_story_1021_10210501_108_dialog_content = "私たちの位置関係は祭壇の前にいた時と変わってないわ…",
  ui_story_1021_10210501_109_dialog_content = "ここは…北境の辺境にかつて存在した強固な砦だ…",
  ui_story_1021_10210501_110_dialog_content = "その砦の位置というのは、まさか…",
  ui_story_1021_10210501_111_dialog_content = "祭壇は、砦の庭園の中に築かれた。",
  ui_story_1021_10210501_112_dialog_content = "…",
  ui_story_1021_10210501_113_dialog_content = "氷の城の者は、去れ。",
  ui_story_1021_10210501_114_dialog_content = "…",
  ui_story_1021_10210501_115_dialog_content = "…僕たちのことかな？",
  ui_story_1021_10210501_116_dialog_content = "我々の着ているものは…彼らに比べ…",
  ui_story_1021_10210501_117_dialog_content = "お前たちは神の力を奪った。\nこの先我らが加護を受けることはない。",
  ui_story_1021_10210501_118_dialog_content = "だが、神との約束を忘れることはない！",
  ui_story_1021_10210501_119_dialog_content = "たとえ、我らを育みし森の中で死すとも、\nたとえ、この理不尽な空に押しつぶされようとも…",
  ui_story_1021_10210501_120_dialog_content = "私は、私の王にのみ従う。",
  ui_story_1021_10210501_121_dialog_content = "…",
  ui_story_1021_10210501_122_dialog_content = "ローデ様…",
  ui_story_1021_10210501_123_dialog_content = "ハーゲン！王より賜りし鎧を持て。\n突撃する部下を励まさなければならん。",
  ui_story_1021_10210501_124_dialog_content = "ローデ様…鎧をつけてください。",
  ui_story_1021_10210501_125_dialog_content = "ハーゲンよ、これが最後の戦いではない。\nお前という鎧があれば、十分だ。",
  ui_story_1021_10210501_126_dialog_content = "…",
  ui_story_1021_10210501_127_dialog_content = "行くぞ、ハーゲン。",
  ui_story_1021_10210501_128_dialog_content = "どこまでもついていきます、ローデ様…",
  ui_story_1021_10210501_129_dialog_content = "…",
  ui_story_1021_10210501_130_dialog_content = "強く威厳に満ちながら、部下を心からいたわるローデ様こそ、\n次の北境の王になるものと思っておった。",
  ui_story_1021_10210501_131_dialog_content = "みなの者！我らが王のために！北境のために！行け――！",
  ui_story_1021_10210501_132_dialog_content = "殺せ――！",
  ui_story_1021_10210501_133_dialog_content = "殺せ――！",
  ui_story_1021_10210501_134_dialog_content = "<color=#e8d9bb>ヒューッ――ヒューッ――</color>",
  ui_story_1021_10210501_135_dialog_content = "消えちゃった…今のが「大自然の力」なの…？",
  ui_story_1021_10210501_136_dialog_content = "…",
  ui_story_1021_10210501_137_dialog_content = "大ババ様は、ローデ様の護衛だったんですね。",
  ui_story_1021_10210501_138_dialog_content = "ローデ様はそなたの先祖であり、\nそなたが幼き頃から誇りとしてきた同族じゃ。",
  ui_story_1021_10210501_139_dialog_content = "村は今やかような有様じゃ。わしはもう、ローデ様に合わせる顔がない。",
  ui_story_1021_10210501_140_dialog_content = "大ババ様の顔の傷は…あの時の暗鬼にやられたものですか…？",
  ui_story_1021_10210501_141_dialog_content = "残酷な戦いの日々を哀れに思うことはないぞ、ティアラ。",
  ui_story_1021_10210501_142_dialog_content = "そなたは傷痕しか見ておらぬが、暗鬼を退けた後、\nわしらはスノーシダーの森で焚火を囲み、共に祝った。",
  ui_story_1021_10210501_143_dialog_content = "どうして、話してくれなかったんですか？",
  ui_story_1021_10210501_144_dialog_content = "知れば、そなたは氷の宮殿を離れ、\n先祖に誓ったように、ここを守るのじゃろう？",
  ui_story_1021_10210501_145_dialog_content = "そなたの性分はわしがよく知っておる。\n女王の護衛になろうとも、その身体には雪狐の血が流れておる。",
  ui_story_1021_10210501_146_dialog_content = "だが、今やわしら一族は没落してしまった。\nかようなことを知ったところで、何の意味もなかろう。",
  ui_story_1021_10210501_147_dialog_content = "それに、そなたにはもう、己の王がおる。",
  ui_story_1021_10210501_148_dialog_content = "…",
  ui_story_1021_10210501_149_dialog_content = "そなたが忠誠を誓った相手は…神に認められし者だったのじゃ。\n村に残り、わしらを守る理由などなかろう？",
  ui_story_1021_10210501_150_dialog_content = "…",
  ui_story_1021_10210501_151_dialog_content = "でも…ローデ様のおっしゃっていた「神の力を奪った」とは…\nどういうことなんですか？",
  ui_story_1021_10210501_152_dialog_content = "灯台だ…",
  ui_story_1021_10210501_153_dialog_content = "灯台…？北境の灯台のことですか？",
  ui_story_1021_10210501_154_dialog_content = "「人々がその姿を目にする時、安寧と幸福が訪れる」",
  ui_story_1021_10210501_155_dialog_content = "…",
  ui_story_1021_10210501_156_dialog_content = "暗鬼を駆逐するため、北境全土を光であまねく照らそうと…",
  ui_story_1021_10210501_157_dialog_content = "王室の先人らは「大自然の力」をもつ1本の松の木を手に入れた。",
  ui_story_1021_10210501_158_dialog_content = "松の木は己の身体を折り、「炎」を受けとめる支柱となった。\nそれが北境最古の灯台だ。",
  ui_story_1021_10210501_159_dialog_content = "それからというもの、北境の大地は光で照らされるようになったが…\n松の木が守っていた森は、徐々に暗鬼に抗う力を失っていったのだ。",
  ui_story_1021_10210501_160_dialog_content = "…",
  ui_story_1021_10210501_161_dialog_content = "先刻そなたは、その光景を見たのか？",
  ui_story_1021_10210501_162_dialog_content = "そうだ。神は王室を認め、北境の灯台となることを選んだ。",
  ui_story_1021_10210501_163_dialog_content = "そうしてこそ、北境を守るという理想を実現できるからだ…",
  ui_story_1021_10210501_164_dialog_content = "さようじゃったか…",
  ui_story_1021_10210501_165_dialog_content = "ということは、王室は神の力を奪ってはいない、ということですね？",
  ui_story_1021_10210501_166_dialog_content = "…",
  ui_story_1021_10210501_167_dialog_content = "…",
  ui_story_1021_10210501_168_dialog_content = "神は北境の灯台となる前、わしらを守ってくださっていた。\nその頃はまだ、神の力はここにあった。",
  ui_story_1021_10210501_169_dialog_content = "ゆえに、先祖たちは祭壇を築き、毎日祈ることで、\n希望と信仰を神に捧げておった。",
  ui_story_1021_10210501_170_dialog_content = "極寒の冬には、松の油で灯かりを点し、\n村の安寧と繁栄を守っておったのじゃ。",
  ui_story_1021_10210501_171_dialog_content = "だが、月日の流れとは予想もせぬ事態をもたらすもの。\nある時、村は苦境に陥り、病が蔓延し、作物は枯れ果てた…",
  ui_story_1021_10210501_172_dialog_content = "松の木は伐られ、怨恨と絶望が村の空を覆ってしもうた。",
  ui_story_1021_10210501_173_dialog_content = "王はわしらを率い、日夜祭壇で祈りを捧げ、\n神のご加護を願った…",
  ui_story_1021_10210501_174_dialog_content = "だが、暗鬼は横行した。わしは無数の村人たちが生まれ、去っていくのを見てきたが、\n神はわしらの祈りに答えてはくれなんだ…",
  ui_story_1021_10210501_175_dialog_content = "そればかりか、わが一族が怨恨に囚われたまま、\n終わりを迎えるのを黙って見ていらしたのじゃ。",
  ui_story_1021_10210501_176_dialog_content = "これがわが一族の歴史じゃ。そなたが生まれるまで、\nわしも同じ結末を迎えるものとばかり思っておった…",
  ui_story_1021_10210501_177_dialog_content = "大ババ様…",
  ui_story_1021_10210501_178_dialog_content = "ティアラ、わしは長生きしすぎた。\n今や一族の歴史物語を思い出すことでしか日々を過ごせぬのじゃからの。",
  ui_story_1021_10210501_179_dialog_content = "だが、そなたは己のなすべきことを見つけ、\n生涯をかけて成し遂げると覚悟したのではないのか？",
  ui_story_1021_10210501_180_dialog_content = "大ババ様…私は村を守りたいんです。でも…\n女王陛下のこともお助けしたいんです。",
  ui_story_1021_10210501_181_dialog_content = "村と王室の間に怨恨があるのなら、何もかも話してください。\n私も一族の歴史を知り、埋め合わせができるよう精一杯努めます。",
  ui_story_1021_10210501_182_dialog_content = "でも、今は北境の安寧のため、お互いを信じましょう。\nそして一緒に侵入者の暗鬼に立ち向かいませんか？",
  ui_story_1021_10210501_183_dialog_content = "…",
  ui_story_1021_10210501_184_dialog_content = "長老、私の中にはずっと、\n「原始の浄域」に関する記憶が存在していた。",
  ui_story_1021_10210501_185_dialog_content = "先刻、目の前に流れて来た光景の中に垣間見たのだが…",
  ui_story_1021_10210501_186_dialog_content = "北境の灯台の最初の躯体は、この地に根を下ろした、\n太古の霊力によって非常に固い樹体をもったスノーシダーであった。",
  ui_story_1021_10210501_187_dialog_content = "そして、この祭壇の周囲には\n「原始の浄域」が存在しているのだな？",
  ui_story_1021_10210501_188_dialog_content = "「原始の浄域」を呼び覚まし、北境に加護をもたらそうとするならば、\nいかにすればよいか、その方法をご存じか？",
  ui_story_1021_10210501_189_dialog_content = "「原始の浄域」を呼び覚ます、か。ははは…",
  ui_story_1021_10210501_190_dialog_content = "北境の灯台の火を消し、\nこの伐られた木の根から再び3本の松を生み出せばいいのじゃ。",
  ui_story_1021_10210501_191_dialog_content = "…",
  ui_story_1021_10210501_192_dialog_content = "つまり、灯台のほか、残りの2本の松の木も\n祭壇へと戻らねばならんということだな？",
  ui_story_1021_10210501_193_dialog_content = "さようじゃ。",
  ui_story_1021_10210501_194_dialog_content = "大ババ様…今のお話は、本当ですか？",
  ui_story_1021_10210501_195_dialog_content = "…",
  ui_story_1021_10210501_196_dialog_content = "北境の灯台の火を消すなんて…そんなことをすれば、\n氷の宮殿も町の人々も…",
  ui_story_1021_10210501_197_dialog_content = "そなたはいつも「女王陛下の護衛として」と言っておるじゃろ？",
  ui_story_1021_10210501_198_dialog_content = "その女王が「原始の浄域」を呼び覚まし、わが村への借りを返そうとしておるのじゃ。\n手助けしたくはないのか？",
  ui_story_1021_10210501_199_dialog_content = "もちろん、お助けしたいと思っています。\n私は女王陛下にいつまでも付いてまいります！でも…",
  ui_story_1021_10210501_200_dialog_content = "ティアラ、顔を上げ、私を見るのだ。",
  ui_story_1021_10210501_201_dialog_content = "…",
  ui_story_1021_10210501_202_dialog_content = "信じろ。力を受け入れたのは私だ。\n当然、いかにして返すかを心得ておる。",
  ui_story_1021_10210501_203_dialog_content = "そなたは私の護衛だ。\n共に「原始の浄域」を呼び覚まし、北境を守ってもらいたい。",
  ui_story_1021_10210501_204_dialog_content = "残りの2本の松の木を探すことは、そなたに任せてよいな？",
  ui_story_1021_10210501_205_dialog_content = "女王陛下…",
  ui_story_1021_10210501_206_dialog_content = "氷と雪に覆われし北境の地のすべてを、私はこの命を賭けて守らねばならん。\nそれが我が先祖に誓った約束だ。",
  ui_story_1021_10210501_207_dialog_content = "灯台の光はここには届いていない。そなたらの故郷を滅ぼしたのは暗鬼だったとしても、\nそなたらを守れなかったのは、この私ベツレヘムなのだ。",
  ui_story_1021_10210501_208_dialog_content = "…",
  ui_story_1021_10210501_209_dialog_content = "ノーヴィオ、松の木がどこにあるのかは、知っておるな？",
  ui_story_1021_10210501_210_dialog_content = "はい、女王陛下。安心して、あの暗鬼に立ち向かってきてくださいませ。\n皆さまは私と共にまいりましょう。",
  ui_story_1021_10210501_211_dialog_content = "…",
  ui_story_1021_10210501_212_dialog_content = "大ババ様、それでは私はノーヴィオ様と共にここを離れます…",
  ui_story_1021_10210501_213_dialog_content = "そなたの灯台に従い、\nそなたはそなたの王に対する誓いを果たしてこい。",
  ui_story_1021_10210501_214_dialog_content = "はい！",
  ui_story_1021_10210601_1_dialog_content = "女王陛下は独りで暗鬼と戦いに行ったけど…\n僕たちは、本当に何も力になれないのかな？",
  ui_story_1021_10210601_2_dialog_content = "女王陛下は以前私を助けてくださった時、特殊な力を授けてくださった。\nそれなのに、お側で共に戦えないなんて…",
  ui_story_1021_10210601_3_dialog_content = "洞窟で出くわした時、あの暗鬼の力は思い知ったはずです。",
  ui_story_1021_10210601_4_dialog_content = "ティアラ、あなたが自身の探すべきものを探すことが、\n女王陛下と共に戦うことになるのです。",
  ui_story_1021_10210601_5_dialog_content = "間欠泉から噴き出している暗力は、\n今も北境の雪原を侵食し続けています…",
  ui_story_1021_10210601_6_dialog_content = "陛下が長老を訪ねに祭壇へ向かわれたのは、暗力の汚れを浄化する方法、\nつまり「原始の浄域」を呼び覚ます方法を知るためです。",
  ui_story_1021_10210601_7_dialog_content = "ノーヴィオ様、残りの2本の松はいったいどこにあるんですか？",
  ui_story_1021_10210601_8_dialog_content = "灯台のある崖とは別の場所で、\nその2本の松は北境を守っています。",
  ui_story_1021_10210601_9_dialog_content = "ずっと守り続けてきたんですか…？",
  ui_story_1021_10210601_10_dialog_content = "そうです。1本は氷の宮殿で、\nもう1本はあなたの生まれた場所で北境を守り続けています。",
  ui_story_1021_10210601_11_dialog_content = "しかし、時の流れと共に松の姿も変わってしまいました。\n「3本松の木」の伝説の中に手がかりがあるかもしれませんね。",
  ui_story_1021_10210601_12_dialog_content = "松の木の持つ「大自然の力」は普段静寂を保っていますが、\n近づけば、女王陛下があなたに授けた力が共鳴を起こすことでしょう。",
  ui_story_1021_10210601_13_dialog_content = "わかりました、ノーヴィオ様！",
  ui_story_1021_10210601_14_dialog_content = "女王陛下も長老も、「守る」ことの意義が\n命よりも大切なことをよくご存じです。",
  ui_story_1021_10210601_15_dialog_content = "ティアラ、あなたが北境の護衛として、\n「守る」という使命を立派に背負えることを願っています。",
  ui_story_1021_10210601_16_dialog_content = "はい。お任せください。ご期待に応えてみせます！",
  ui_story_1021_10210601_17_dialog_content = "ティアラ、待って！僕も一緒に行くよ！",
  ui_story_1021_10210601_18_dialog_content = "あなたが？",
  ui_story_1021_10210601_19_dialog_content = "私も手助けするわ！",
  ui_story_1021_10210601_20_dialog_content = "でも…私について来られる？\nそれとも、かついであげよっか？",
  ui_story_1021_10210601_21_dialog_content = "かつぐ…？",
  ui_story_1021_10210601_22_dialog_content = "…力になれるなら、かつがれたってかまわないよ！",
  ui_story_1021_10210601_23_dialog_content = "PlayerName様の感知能力は、大きな力になると思いますよ。",
  ui_story_1021_10210601_24_dialog_content = "そうですか…わかりました。\nではノーヴィオ様、ここはお願いします。",
  ui_story_1021_10210601_25_dialog_content = "すぐに戻ります！",
  ui_story_1021_10210601_26_dialog_content = "う、うわああ――！",
  ui_story_1021_10210601_27_dialog_content = "本当に速いですね。あっという間に見えなくなりました…",
  ui_story_1021_10210601_28_dialog_content = "暗力の混じった黒い水がすでに、\n王室の方へと広がり始めていますね…",
  ui_story_1021_10210601_29_dialog_content = "どうやら、強力な光力をもつナシリスでも、\n抑えきれないようです。",
  ui_story_1021_10210601_30_dialog_content = "ティアラたちが無事に松の木を見つけられればいいのですが…\nでなければ、村の存続が危ぶまれます…",
  ui_story_1021_10210601_31_dialog_content = "ノーヴィオ閣下、私を北境の護衛と思ってください。\n北境を守る力になりたいのです。",
  ui_story_1021_10210601_32_dialog_content = "<color=#e8d9bb>森の別の場所では</color>",
  ui_story_1021_10210601_33_dialog_content = "はぁ、こりゃ自分たちでR・Wに戻るってのはムリそうだねェ。\nPlayerNameたちと一緒に問題解決するって方が現実的だろうなァ。",
  ui_story_1021_10210601_34_dialog_content = "本気で言ってんの？",
  ui_story_1021_10210601_35_dialog_content = "なんだかんだっつって、結局はR・Wのためだろが。",
  ui_story_1021_10210601_36_dialog_content = "イブのことだって、サメヤマはずいぶんPlayerNameの世話になったしな。",
  ui_story_1021_10210601_37_dialog_content = "それだけでも、サメヤマのヤツは、\nPlayerNameが危険な目に遭えば、いつだって手助けするだろうよ。",
  ui_story_1021_10210601_38_dialog_content = "合同探索のことだって、サメヤマはとぼけたふりしてるだけさ。",
  ui_story_1021_10210601_39_dialog_content = "俺もR・Wの代わりに恩でも売って、お返ししてやろうじゃねえか。",
  ui_story_1021_10210601_40_dialog_content = "ロイ兄はやっぱすごいな！どうりでサメヤマさんがいつも、\nロイ兄を見習えっていうわけだね。勉強になったよ！",
  ui_story_1021_10210601_41_dialog_content = "さ、行くぞ。黒い水の流れに沿って進みながら、\n近くにいる暗鬼のヤツらを片付けちまうか。",
  ui_story_1021_10210601_42_dialog_content = "<color=#e8d9bb>北境の辺境地帯</color>",
  ui_story_1021_10210601_43_dialog_content = "『こ、この先には…行ってはなりません…』",
  ui_story_1021_10210601_44_dialog_content = "『この先には邪悪な灯台があり、我々の身体を粉々に引き裂くそうです。』",
  ui_story_1021_10210601_45_dialog_content = "『氷など、かゆみくらいのもの。火山も熱風に吹かれるくらいのことに過ぎません。\n邪悪な灯台もその程度です。』",
  ui_story_1021_10210601_46_dialog_content = "<color=#e8d9bb>コオォーン――！</color>",
  ui_story_1021_10210601_47_dialog_content = "『あの白い畜生どもが来ました。』",
  ui_story_1021_10210601_48_dialog_content = "『長い年月が経ち、砦も護衛もいなくなったというのに、\nあの畜生たちはまだいたのですか。』",
  ui_story_1021_10210601_49_dialog_content = "『北境とは、実に興味深い所です。』",
  ui_story_1021_10210601_50_dialog_content = "氷凍の刃よ――！",
  ui_story_1021_10210601_51_dialog_content = "北境に侵入せし者、氷の中で終わりを迎えるがいい！",
  ui_story_1021_10210601_52_dialog_content = "見逃してやったのに、わざわざ追ってくるとは。",
  ui_story_1021_10210601_53_dialog_content = "氷の壁ですか…再びこの私を氷で封じようというのですか？",
  ui_story_1021_10210601_54_dialog_content = "…<color=#FFB400>あの戦い</color>について、何を知っている？",
  ui_story_1021_10210601_55_dialog_content = "どうやら、あなたはまだ、お若いようです。",
  ui_story_1021_10210601_56_dialog_content = "『さあ、遊んであげなさい。』",
  ui_story_1021_10210601_57_dialog_content = "『承知しました！』",
  ui_story_1021_10210700_1_dialog_content = "…女王陛下の使いでやってきたんどす。\n何としても、皆はんに伝えなかあかん言われましてん。",
  ui_story_1021_10210700_2_dialog_content = "つ、つまり…こないことなんどす…",
  ui_story_1021_10210700_3_dialog_content = "暗面に足を踏み入れる前に、\n合同探索が始まったようだな。",
  ui_story_1021_10210700_4_dialog_content = "そういうことならば、我々も何としても北境の拠点を守らねばならない。\nビビアン、即刻北境へ向けて発つぞ。",
  ui_story_1021_10210700_5_dialog_content = "承知いたしました。",
  ui_story_1021_10210700_6_dialog_content = "Ms.ブラン、余と共にまいれ。",
  ui_story_1021_10210700_7_dialog_content = "はい、城主様。",
  ui_story_1021_10210700_8_dialog_content = "会長、俺たちも行くんだろ？",
  ui_story_1021_10210700_9_dialog_content = "影ノ街が行かない理由がありますか？",
  ui_story_1021_10210700_10_dialog_content = "つっても、あのやたらに標高の高い北境だろ…",
  ui_story_1021_10210700_11_dialog_content = "北境は確かに影ノ街とは違いますね。\nベセルさん、啓光の飛行機にお乗りください。",
  ui_story_1021_10210700_12_dialog_content = "ありがとうございます。",
  ui_story_1021_10210700_13_dialog_content = "ティ、ティアラ…少し歩かせてくれないかな！？\n腰がもう、痛くて仕方ないんだ…",
  ui_story_1021_10210700_14_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_1021_10210700_15_dialog_content = "本当に僕をかついで…しかも、こんなに長く走り続けるとは思わなかったよ…",
  ui_story_1021_10210700_16_dialog_content = "いいって言われたから、そうしただけだよ。\nそれとも、外の世界じゃ皆大口をたたく癖があるとか？",
  ui_story_1021_10210700_17_dialog_content = "そういうわけじゃないけど…\nてっきり、ただ言ってみただけだと思ってたから…",
  ui_story_1021_10210700_18_dialog_content = "これで君が雪狐のリーダーだって納得できたよ！",
  ui_story_1021_10210700_19_dialog_content = "ふぅ！とにかく、もう氷の宮殿が見える所まで来たね…",
  ui_story_1021_10210700_20_dialog_content = "コオォーン――！",
  ui_story_1021_10210700_21_dialog_content = "え…？どうしたの…？",
  ui_story_1021_10210700_22_dialog_content = "<color=#e8d9bb>コォォ――ン</color>",
  ui_story_1021_10210700_23_dialog_content = "答えた…！",
  ui_story_1021_10210700_24_dialog_content = "今のは狐たちと情報のやりとりをしたんだよ。",
  ui_story_1021_10210700_25_dialog_content = "…どんなことを話したの？",
  ui_story_1021_10210700_26_dialog_content = "狐たちに伝えたんだ。この近くは黒い水の影響を受けてないって。\nそしたら、ノーヴィオ様に伝えてくれるって答えた。",
  ui_story_1021_10210700_27_dialog_content = "明らかにたった一声だったけど…\nそんなたくさんの情報をやりとりしてたの？",
  ui_story_1021_10210700_28_dialog_content = "やってみるといいよ。",
  ui_story_1021_10210700_29_option_content = "僕が？僕は遠慮しとくよ…",
  ui_story_1021_10210700_30_dialog_content = "恥ずかしいってこと？",
  ui_story_1021_10210700_31_dialog_content = "そ、そんなんじゃないよ…どうしてそんなふうに思うの？",
  ui_story_1021_10210700_32_dialog_content = "氷の宮殿に入ったばかりの時、\n王室の護衛たちがよく私のマネをしてたんだ…",
  ui_story_1021_10210700_33_dialog_content = "最初はうるさいって意味なのかと思ってたけど、\nそのうち、そうじゃないってわかった。",
  ui_story_1021_10210700_34_dialog_content = "でも、別にいいんだよ。笑いたいなら笑えばいい。\n私も氷の宮殿では鳴き声をあげないように努力したし…",
  ui_story_1021_10210700_35_dialog_content = "それでも、独りで森を巡回してる時やみんな寝静まった夜なんかは、\n今みたいに狐たちと交流してるんだ。",
  ui_story_1021_10210700_36_dialog_content = "ちっとも可笑しくなんかないよ。ほら――",
  ui_story_1021_10210700_37_dialog_content = "コオォーン――！",
  ui_story_1021_10210700_38_option_content = "コオォーン――",
  ui_story_1021_10210700_39_dialog_content = "どう？",
  ui_story_1021_10210700_40_dialog_content = "…",
  ui_story_1021_10210700_41_dialog_content = "その顔…そんなに聞き苦しかったかな？",
  ui_story_1021_10210700_42_dialog_content = "ううん、考えてただけだよ。今のは「ご飯がおいしい」って意味か、「恋しい」って意味か…\nそれとも「雪が風に舞ってる」って意味か…",
  ui_story_1021_10210700_43_dialog_content = "もう1回鳴いてみて。",
  ui_story_1021_10210700_44_dialog_content = "ええと…やめておこうかな。",
  ui_story_1021_10210700_45_dialog_content = "鳴く時はね、頭を挙げて、首をしっかり伸ばさなきゃダメ。",
  ui_story_1021_10210700_46_dialog_content = "頭を挙げて…首を伸ばして…",
  ui_story_1021_10210700_47_dialog_content = "その状態で大きく口を開けて、\n言いたいことを全部一息に乗せて吐き出すんだよ！",
  ui_story_1021_10210700_48_dialog_content = "コオォーン――！",
  ui_story_1021_10210700_49_dialog_content = "<color=#e8d9bb>コォォ――ン</color>",
  ui_story_1021_10210700_50_dialog_content = "どう？うまくいったでしょ？",
  ui_story_1021_10210700_51_dialog_content = "わぁ！ちゃんと伝わったかは分からないけど、\n答えが返ってくると本当に幸せな気分になるね！",
  ui_story_1021_10210700_52_dialog_content = "あなたの祝福を享けて、狐たちもきっと喜んでるはずだよ。",
  ui_story_1021_10210700_53_dialog_content = "さあ、十分休憩もとれたみたいだし、\n一気に氷の宮殿までかついでいくよ。",
  ui_story_1021_10210700_54_dialog_content = "ちょっと！せ、せめて、前を向かせて！",
  ui_story_1021_10210700_55_dialog_content = "あれ？今日はザーリャさんもたくさん鉱石が獲れたみたいだね。",
  ui_story_1021_10210700_56_dialog_content = "女王陛下から任された初の仕事だもの。\nしっかり役目を果たさなきゃ。",
  ui_story_1021_10210700_57_dialog_content = "ザーリャさんって強大な光力術を使えるんでしょ？\n仕事もラクラクこなせちゃうんだろうなぁ！",
  ui_story_1021_10210700_58_dialog_content = "そんなことないわ…\n今でもうっかり、自分を凍らせちゃうことがあって…",
  ui_story_1021_10210700_59_dialog_content = "一部だけだからいいものの…まだまだ練習が必要よ。\nこれから女王陛下に会いに氷の宮殿へ行くから、先に行くわね。",
  ui_story_1021_10210700_60_dialog_content = "あ…女王陛下は氷の宮殿にいないって聞いたけど…",
  ui_story_1021_10210700_61_dialog_content = "<color=#e8d9bb>シュッ――！</color>",
  ui_story_1021_10210700_62_dialog_content = "えっ！？",
  ui_story_1021_10210700_63_dialog_content = "今のは…PlayerName？それからティアラも…\nなんでこんなところにいるのかしら？",
  ui_story_1021_10210700_64_dialog_content = "一通り回ったけど、君の槍に変化はないみたいだね…",
  ui_story_1021_10210700_65_dialog_content = "あまりにも長い時が経って、太古の力も眠ってしまったってこと…？",
  ui_story_1021_10210700_66_dialog_content = "ノーヴィオは伝説の中に手がかりがあるって言ってた。\n何か思い当たることはないの？",
  ui_story_1021_10210700_67_dialog_content = "氷の宮殿にある松の木は、\n「この世に平和をもたらす国王の疲れをいやしたい」と願った1本目の松かもしれない。",
  ui_story_1021_10210700_68_dialog_content = "ベツレヘムさんは普段どうやって疲れを癒してるの？",
  ui_story_1021_10210700_69_dialog_content = "陛下はあまり氷の宮殿にいらっしゃらないんだ。\n普段は寝殿か庭園、もしくはダイニングにいることが多いの。",
  ui_story_1021_10210700_70_dialog_content = "だったら、僕とほとんど変わらなさそうだね。\n眠るか、ぼうっとするか、おいしいものを食べるか…",
  ui_story_1021_10210700_71_dialog_content = "でも、女王陛下は普段そんなことはしていらっしゃらないと思うけど…",
  ui_story_1021_10210700_72_dialog_content = "何をそんなに急いでいるの？陛下に何か用？",
  ui_story_1021_10210700_73_dialog_content = "…！？その鉱石は…？",
  ui_story_1021_10210700_74_dialog_content = "別にあなたの故郷の近くから採ってきたものじゃないわ！",
  ui_story_1021_10210700_75_dialog_content = "ザーリャ、どうして君がここに？",
  ui_story_1021_10210700_76_dialog_content = "さっき私がいたのに気づかなかった？\nものすごいスピードで走ってたみたいだけど、女王陛下に急用？",
  ui_story_1021_10210700_77_dialog_content = "でも、女王陛下は今氷の宮殿にいらっしゃらないらしいわ。\nだから、知らせに来てあげたのよ。",
  ui_story_1021_10210700_78_dialog_content = "女王陛下がいないことは知ってるよ。",
  ui_story_1021_10210700_79_dialog_content = "だったら、何をしてるっていうの…？",
  ui_story_1021_10210700_80_dialog_content = "探し物だよ。",
  ui_story_1021_10210700_81_dialog_content = "探し物…？いったい何を？私も手伝うわよ。",
  ui_story_1021_10210700_82_dialog_content = "僕たちは今…女王陛下の疲れを癒せるものを探してるんだ。",
  ui_story_1021_10210700_83_dialog_content = "なんだか子どもたちが…\n伝説をもとに冒険ごっこをしてるみたいね…",
  ui_story_1021_10210700_84_dialog_content = "よくそうやって遊んでるの？",
  ui_story_1021_10210700_85_dialog_content = "そうよ。陛下の庭園にはいつだって、\n冒険ごっこを楽しんでる子どもたちがいるの。",
  ui_story_1021_10210700_86_dialog_content = "ここは女王の宮殿なのに、子どもたちが入って遊べるの？",
  ui_story_1021_10210700_87_dialog_content = "女王陛下は氷の宮殿をご自分の物と考えたことは一度もないんだよ。",
  ui_story_1021_10210700_88_dialog_content = "女王陛下は本当に勤勉でいらっしゃるの。\n思えば、お休みになっているところなんて見たことないわ…",
  ui_story_1021_10210700_89_dialog_content = "ここには椅子やソファーもあるし、庭園には、それは美しいロッキングチェアもあるけど、\n陛下は一度もお使いになったことがないのよ。",
  ui_story_1021_10210700_90_dialog_content = "だったら、疲れをいやすものは…ティアラ、こっちだよ！",
  ui_story_1021_10210700_91_dialog_content = "…",
  ui_story_1021_10210700_92_dialog_content = "あら！？槍が光ってるわ！",
  ui_story_1021_10210700_93_dialog_content = "やっぱり…思った通りだ！",
  ui_story_1021_10210700_94_dialog_content = "これは女王陛下の玉座…",
  ui_story_1021_10210700_95_dialog_content = "あなたたちが探してた物はこれ？",
  ui_story_1021_10210700_96_dialog_content = "国王の疲れを癒せるものと言ったら、玉座はまさにピッタリだよね。\nしかも国王を象徴するものだし…",
  ui_story_1021_10210700_97_dialog_content = "1本目の松は女王陛下の椅子になってたんだ…\nでも、陛下がお座りになっているところなんて見たことないけど…",
  ui_story_1021_10210700_98_dialog_content = "まさか、この玉座が松の木と関係あることをご存じだったから、\nここではお休みにならなかったのかな…？",
  ui_story_1021_10210700_99_dialog_content = "…",
  ui_story_1021_10210700_100_dialog_content = "椅子の様子が…何だかおかしいわ…！",
  ui_story_1021_10210700_101_dialog_content = "こちらが忠誠を誓いし村が送ってきた品でございます。\n陛下だけの王座――北境の女王の玉座でございます。",
  ui_story_1021_10210700_102_dialog_content = "今後、陛下はこの玉座から民たちをお治めになるのです。",
  ui_story_1021_10210700_103_dialog_content = "北境の雪原と森をすべて回るには、どのくらいの時間がかかるのだ？",
  ui_story_1021_10210700_104_dialog_content = "それは…陛下、なぜさようなご質問をなさるのでしょう？",
  ui_story_1021_10210700_105_dialog_content = "冷ややかな玉座にただ座っていても、北境を守ることはできぬ。\n私は己の行いで氷と雪に覆われた大地を余すことなく守ってみせる。",
  ui_story_1021_10210700_106_dialog_content = "雪が降り注ぎ、陛下の歩まれた道はすでに新たな道となりました。",
  ui_story_1021_10210700_107_dialog_content = "春が訪れる頃には、山も森も昨年とは姿を異にしていることでしょう。",
  ui_story_1021_10210700_108_dialog_content = "ならば、歩み続けよう。北境の大地が余すところなく\n灯台の加護を受けるその時まで、私は歩み続ける。",
  ui_story_1021_10210700_109_dialog_content = "今のは…",
  ui_story_1021_10210700_110_dialog_content = "女王陛下が即位されたばかりの頃の情景…？",
  ui_story_1021_10210700_111_dialog_content = "感知能力を使わずに見えるなんて…\nおそらく、もっと昔のことだよ…",
  ui_story_1021_10210700_112_dialog_content = "忠誠を誓った村が松の木でできた玉座を送ってきたけど、\n女王は座ろうとしなかった。",
  ui_story_1021_10210700_113_dialog_content = "そして女王陛下もその意志を継ぎ、\n生涯をかけて北境の領内を巡り続けている…",
  ui_story_1021_10210700_114_dialog_content = "ちょっとこれを見て！",
  ui_story_1021_10210700_115_dialog_content = "玉座が…小さな松の枝になっちゃったわ…",
  ui_story_1021_10210700_116_dialog_content = "これが、伝説の1本目の松みたいだね。",
  ui_story_1021_10210700_117_dialog_content = "不思議な力ね…！",
  ui_story_1021_10210700_118_dialog_content = "この松があれば、女王陛下のお力になれる…",
  ui_story_1021_10210700_119_dialog_content = "うん。じゃあ次は君の暮らしてる所だ！",
  ui_story_1021_10210700_120_dialog_content = "行くよ！",
  ui_story_1021_10210700_121_dialog_content = "ちょっと…！今度また冒険ごっこする時は、私も仲間に入れてよ！",
  ui_story_1021_10210700_122_dialog_content = "<color=#e8d9bb>こうして、北境から玉座が消えた</color>",
  ui_story_1021_10210801_1_dialog_content = "<color=#e8d9bb>ヒュウッ――</color>",
  ui_story_1021_10210801_2_dialog_content = "急に天候が悪くなったね…",
  ui_story_1021_10210801_3_dialog_content = "灯台の力が猛吹雪に阻まれちゃってる…\n陛下の方はどうなってるんだろう…",
  ui_story_1021_10210801_4_dialog_content = "君の故郷にあるっていう松について、何か手がかりはある？",
  ui_story_1021_10210801_5_dialog_content = "伝説の中に出てくる最後の松の木は「暗闇を光で満たす」…",
  ui_story_1021_10210801_6_dialog_content = "ひいばあちゃんが…確か話してくれた気がする…",
  ui_story_1021_10210801_7_dialog_content = "北境には昔、暗黒の時代があったって。\nでも神が約束をしてくださって、北境に光がもたらされた。",
  ui_story_1021_10210801_8_dialog_content = "「約束」か…ちょっとあいまいすぎるね…",
  ui_story_1021_10210801_9_dialog_content = "でも、その約束を覚えていて、それを守る人がいるかぎり、\n約束は現実に存在するんだよ。",
  ui_story_1021_10210801_10_dialog_content = "それもひいばあちゃんから聞いたことだけど…",
  ui_story_1021_10210801_11_dialog_content = "どうすればいいか、わかった気がする…",
  ui_story_1021_10210801_12_dialog_content = "ひいおばあさんはきっとその「約束」を覚えていて、守ってたはずだ。\n君の記憶の中に手がかりがあるかも…",
  ui_story_1021_10210801_13_dialog_content = "本当に？",
  ui_story_1021_10210801_14_dialog_content = "でも…ひいばあちゃんはだいぶ前に亡くなったし、\nひいばあちゃんに関する私の記憶の中に、手がかりがあるとは限らないよ…",
  ui_story_1021_10210801_15_dialog_content = "どうして？",
  ui_story_1021_10210801_16_dialog_content = "…見ればわかるよ。",
  ui_story_1021_10210801_17_dialog_content = "心配することないよ。とにかく試してみる！",
  ui_story_1021_10210801_18_option_content = "精神感知――",
  ui_story_1021_10210801_19_dialog_content = "もうよい、それ以上話すでない！",
  ui_story_1021_10210801_20_dialog_content = "もうすぐこの世を去るのじゃ。\nちいとばかり話してもよいじゃろが。",
  ui_story_1021_10210801_21_dialog_content = "ひいばあちゃん…ティアラと遊んでくれないの？",
  ui_story_1021_10210801_22_dialog_content = "ティアラ、いい子だねぇ…ひいばあちゃんと約束しておくれ。\n早く大きくなるんだよ…",
  ui_story_1021_10210801_23_dialog_content = "早く大きくなるんだよ、ティアラ…",
  ui_story_1021_10210801_24_dialog_content = "もっと早くにあんたに会いたかったよ…\n大人になったあんたを、あたしゃ見たかったよ…",
  ui_story_1021_10210801_25_dialog_content = "あと何年かしたら、あたしはずっと気に掛けてきた人に\n会いに行かなきゃならないんだ…",
  ui_story_1021_10210801_26_dialog_content = "ティアラ、ひいばあちゃんのこと覚えておいておくれ…\n村のことも…それから…",
  ui_story_1021_10210801_27_dialog_content = "他人を悲しませるようなことばかり言うでない。\n誰も覚えてはおらぬ、誰も残りはせん。",
  ui_story_1021_10210801_28_dialog_content = "ティアラ、向こうで狐たちと遊んでおいで。",
  ui_story_1021_10210801_29_dialog_content = "うわぁ…これはティアラの尻尾だ…",
  ui_story_1021_10210801_30_dialog_content = "これは…待って、自分で考えるから！ヒントはなしだよ！",
  ui_story_1021_10210801_31_dialog_content = "ティアラを二度とここに連れてくるでない。",
  ui_story_1021_10210801_32_dialog_content = "ティアラは村の子じゃ。あの子には村の栄光を教えにゃならん。\n己が先祖たちの祝福を享けて生まれたことを知ってもらわにゃならん。",
  ui_story_1021_10210801_33_dialog_content = "ティアラには村の長を継がせ、北境の護衛を輩出させるのじゃ…",
  ui_story_1021_10210801_34_dialog_content = "あの約束は、ティアラに託す。",
  ui_story_1021_10210801_35_dialog_content = "かつては心を一つにし、北へとやってきた村々もあったが、\n今やわが雪狐の村だけがこの地に残り、北の大地を守っておる。",
  ui_story_1021_10210801_36_dialog_content = "神の約束を目にする日は来ぬだろう。\nあの<color=#FFB400>石板</color>も、今や神に忘れ去られているのやもしれぬ。",
  ui_story_1021_10210801_37_dialog_content = "老いぼれめ。ティアラにそんなことを言ったら、\nあたしゃあんたを許さないよ。",
  ui_story_1021_10210801_38_dialog_content = "神が忘れるはずはない。\nティアラがいる限り、あの石板はずっと受け継がれていくのじゃ。",
  ui_story_1021_10210801_39_dialog_content = "…ティアラが知る前に、わしが石板を壊してやる。",
  ui_story_1021_10210801_40_dialog_content = "あんたは誰よりも石板を大事にしておる。\nそんなことしないことくらい、分かっておるわ。",
  ui_story_1021_10210801_41_dialog_content = "ほかに道はない。",
  ui_story_1021_10210801_42_dialog_content = "ティアラに背負わせるのは、よさぬか？あの子を見てみよ。\n普通の子と同じように無邪気に育てればよいではないか。",
  ui_story_1021_10210801_43_dialog_content = "あの子が守るのは、この村じゃ！あの冷たい王宮ではない！",
  ui_story_1021_10210801_44_dialog_content = "王室が神の力を奪ったのじゃ。恩に報いないばかりか、\n命を賭して辺境を守った護衛を侵入者と共に砦に氷で封じおった…",
  ui_story_1021_10210801_45_dialog_content = "1000年以上経ったというに…あの氷が融けたことがあるか…？",
  ui_story_1021_10210801_46_dialog_content = "かつての残酷な時代を知った時、\nティアラが今のように無邪気に楽しく暮らしていけると思うのか？",
  ui_story_1021_10210801_47_dialog_content = "約束、加護…今や残酷でしかなかろう。",
  ui_story_1021_10210801_48_dialog_content = "その残酷さがいかなるものか、そなたを見て、わしは思い知った。\nそなたは生まれてから…最後の時を迎えるまで…",
  ui_story_1021_10210801_49_dialog_content = "それ以上言うでない。ティアラは必ず、そんな残酷さとも戦える強い子に育つはずじゃ。\n先祖たちがそうじゃったようにな。",
  ui_story_1021_10210801_50_dialog_content = "…",
  ui_story_1021_10210801_51_dialog_content = "ひいばあちゃん――狐が…怖いおばあさんだって言ってたよ！\nアハハハハ…もう、くすぐったいってば！",
  ui_story_1021_10210801_52_dialog_content = "うわっ…！でも、ティアラは負けないもん！",
  ui_story_1021_10210801_53_dialog_content = "…",
  ui_story_1021_10210801_54_dialog_content = "なに？どうして、そんな顔してるの？",
  ui_story_1021_10210801_55_dialog_content = "…ひいばあちゃんと大ババ様の言い争いを見たの？",
  ui_story_1021_10210801_56_dialog_content = "うん。君が村の長を継ぐことについて、\n2人は意見が食い違ってたんだね。",
  ui_story_1021_10210801_57_dialog_content = "長老さんが君を村の長にするのを嫌がってたなんて、初めて知ったよ…",
  ui_story_1021_10210801_58_dialog_content = "そうなんだ…大ババ様はよそ者が来るのを嫌うだけじゃなく、\n私が村に戻ってくるのさえ喜ばない…",
  ui_story_1021_10210801_59_dialog_content = "大ババ様はきっと、私がリーダーになったら、\n村がこうなることをとっくに予想してたのかも…",
  ui_story_1021_10210801_60_dialog_content = "長老さんが心配してるのはそこじゃないよ。君がひいおばあさんみたいに\n恨みを抱いたまま、のびのびと楽しく生きていけないことを心配してたんだ。",
  ui_story_1021_10210801_61_dialog_content = "のびのびと楽しく…？",
  ui_story_1021_10210801_62_dialog_content = "だから、私が村への思いを断ち切れるように、\nいつも女王陛下の護衛としての務めを果たすように言ってたの…？",
  ui_story_1021_10210801_63_dialog_content = "なのに、そんな素振りはちっとも見せずに…",
  ui_story_1021_10210801_64_dialog_content = "小さい頃は、私が祭壇に行くことを禁じて…",
  ui_story_1021_10210801_65_dialog_content = "伝説を話して聞かせることもしなかった…",
  ui_story_1021_10210801_66_dialog_content = "村が危険なのに、私を追い返そうとした…",
  ui_story_1021_10210801_67_dialog_content = "長老さんは村を心から愛してる。\nでも、それよりもずっと君を大切に思ってるんだ…",
  ui_story_1021_10210801_68_dialog_content = "…",
  ui_story_1021_10210801_69_dialog_content = "だったらなおさら、雪狐のリーダーとして誓った言葉に\n背くわけにはいかない…！",
  ui_story_1021_10210801_70_dialog_content = "私は女王陛下を信じてる！\n「原始の浄域」を呼び覚ますことができれば、村はきっと助かるよ！",
  ui_story_1021_10210801_71_dialog_content = "そうなればきっと、大ババ様も私を追い出したりしないよ！",
  ui_story_1021_10210801_72_dialog_content = "うん、ティアラならできるよ！",
  ui_story_1021_10210801_73_dialog_content = "それはそうと…結局、私の記憶の中に\n松の木の手がかりはなかったんだよね？",
  ui_story_1021_10210801_74_dialog_content = "いや、長老さんたちは石板がどうのって話してた…\n神の雪狐の村に対する約束を記してあるみたいだ。",
  ui_story_1021_10210801_75_dialog_content = "石板か…",
  ui_story_1021_10210801_76_dialog_content = "ひいおばあさんが言うには、\n長老さんはその石板を誰よりも大切にしてたらしい。",
  ui_story_1021_10210801_77_dialog_content = "でも、すでに長老さんが壊しちゃってるかもしれない…",
  ui_story_1021_10210801_78_dialog_content = "…",
  ui_story_1021_10210801_79_dialog_content = "よく思い出してみて。大切にしてたなら、\nきっとしょっちゅう様子を見に行ってたはず。",
  ui_story_1021_10210801_80_dialog_content = "大ババ様がよく行く場所といえば、\n洞窟…祭壇…山…それから…",
  ui_story_1021_10210801_81_dialog_content = "もしかして…",
  ui_story_1021_10210801_82_dialog_content = "私が村を離れる前、大ババ様はいつもこの近くから、ずっと灯台を見てた。\n一日中見てることもしょっちゅうだった…",
  ui_story_1021_10210801_83_dialog_content = "でも、ここには木のほかには何もなさそうだけど…",
  ui_story_1021_10210801_84_dialog_content = "…誰？逃げる気！？",
  ui_story_1021_10210801_85_dialog_content = "ああ、お嬢ちゃんか…また捕まっちまったねェ…",
  ui_story_1021_10210801_86_dialog_content = "どうしてここに？",
  ui_story_1021_10210801_87_dialog_content = "せっかく近くの暗鬼を片付けてやったってのに、\nここのリーダーさんときたら、恩をあだで返すとはなァ。",
  ui_story_1021_10210801_88_dialog_content = "コソコソしてるやつがそんなことするはずない！\nまた宝石を盗んでたんじゃないの！？",
  ui_story_1021_10210801_89_dialog_content = "洞窟から生きて出てこられただけでもラッキーだっつーのに、\n宝石なんて盗めやしないよ。",
  ui_story_1021_10210801_90_dialog_content = "コホン…ロイ兄、もうちょっと真面目に話しなよ。",
  ui_story_1021_10210801_91_dialog_content = "R・Wも合同探索のメンバーとして、\n仲間の命を助けるんだって言ってたじゃん！",
  ui_story_1021_10210801_92_dialog_content = "だから、洞窟から出てきた後、PlayerNameたちが見つからないもんだから、\nここで出くわした暗鬼を片っ端から片付けてたんだよ！",
  ui_story_1021_10210801_93_dialog_content = "ここに来るまで、確かに暗鬼には出くわさなかった…\n本当にありがとう！",
  ui_story_1021_10210801_94_dialog_content = "それは…ここが灯台の光の届く最辺境の土地だからだよ！",
  ui_story_1021_10210801_95_dialog_content = "…そりゃあ、知らかったねェ。ここにゃ石碑もねえし…\nつってことは、俺たちは無駄にエネルギー使ったってことか？",
  ui_story_1021_10210801_96_dialog_content = "ロイ兄…あたしさっき、石碑を見た気がする…",
  ui_story_1021_10210801_97_dialog_content = "…ティアラ！もしかして、境界線の石碑っていうのが…",
  ui_story_1021_10210801_98_dialog_content = "石板かもしれない！",
  ui_story_1021_10210801_99_dialog_content = "急いで槍が石碑と共鳴するか見てみよう！",
  ui_story_1021_10210801_100_dialog_content = "大自然の力、氷の先にパワーチャージ完了！",
  ui_story_1021_10210801_101_dialog_content = "さっきもこれくらい光ってくれりゃあ、\n無駄に力使うこともなかったんだけどねェ…",
  ui_story_1021_10210801_102_dialog_content = "文字が光ってる…たぶん、スノーシダーの樹脂だよ。",
  ui_story_1021_10210801_103_dialog_content = "ひいばあちゃんが言ってたんだ。\nスノーシダーの樹脂で点した灯かりは北境の目だって。",
  ui_story_1021_10210801_104_dialog_content = "夜に見たら、きっとすごく明るいんだろうね…",
  ui_story_1021_10210801_105_dialog_content = "まさか、松の木が灯台の光の境界を示す石碑になってたとは…",
  ui_story_1021_10210801_106_dialog_content = "あれ？ど、どういうこと…？",
  ui_story_1021_10210801_107_dialog_content = "偉大なる北境の護衛たちよ。戦いは終結した。\n灯台もすでに完成している。",
  ui_story_1021_10210801_108_dialog_content = "氷に閉ざされし砦は彼の地にそびえ、辺境で犠牲になった戦士たちの勇敢さを讃え、\nその強さを示して敵を追い払う。そして同時に私に告げているのだ。",
  ui_story_1021_10210801_109_dialog_content = "私はここに約束する――",
  ui_story_1021_10210801_110_dialog_content = "この先、私の立つ場所が暗闇と光の境界線となることはない。\n灯台の光は、必ずやここまで届くであろう！",
  ui_story_1021_10210801_111_dialog_content = "そなたらの家族はこの広大な北境の地で、\n生業に励み、暮らしを享受するだろう。",
  ui_story_1021_10210801_112_dialog_content = "山河よ、どうか私の誓いの証人となり、灯台の力を授けたまえ。\n我らが北境に加護を賜らんことを！",
  ui_story_1021_10210801_113_dialog_content = "皆も神と共に、我が誓いの証人となれ。",
  ui_story_1021_10210801_114_dialog_content = "私は初代北境の女王。\n我が子孫は後世においても、必ずや北境を守る護衛となろう！",
  ui_story_1021_10210801_115_dialog_content = "私は北境を守り、我が子孫は後代においても、\n必ずや北境を守る護衛となろう！",
  ui_story_1021_10210801_116_dialog_content = "北境の初代女王って、ほんとすっごく器の大きそうな人だね…",
  ui_story_1021_10210801_117_dialog_content = "石板に書かれてた「約束」は、\n神の村に対する約束じゃなかったんだね…",
  ui_story_1021_10210801_118_dialog_content = "当時の女王陛下と辺境の護衛たちが互いに交わした約束だったんだ…",
  ui_story_1021_10210801_119_dialog_content = "だから、ご先祖様たちはずっとここで北境を守ってたんだ…\nでも、女王の約束が果たされることなく、徐々に衰退していって…",
  ui_story_1021_10210801_120_dialog_content = "そうして、王室を恨むようになったんだね…",
  ui_story_1021_10210801_121_dialog_content = "でも…灯台の光をここまで届かせるなんて、ほぼ不可能だよね…",
  ui_story_1021_10210801_122_dialog_content = "うん…でも、女王陛下は何年もずっと、\n苦労もいとわず辺境の巡回を続けていらっしゃる。",
  ui_story_1021_10210801_123_dialog_content = "だから、わかるんだ…村も王室も、誰一人として\n約束に背いてなんかないんだよ。",
  ui_story_1021_10210801_124_dialog_content = "そして今、みんなで「原始の浄域」を呼び覚まそうとしてる。\n北境を守るっていう重責を私に任せてくれた…",
  ui_story_1021_10210801_125_dialog_content = "それこそがノーヴィオ様が言ってた、\n私が知るべき己の使命なんだ！",
  ui_story_1021_10210801_126_dialog_content = "君と一緒に松の木を探して、改めて北境のことを知れた気がする。",
  ui_story_1021_10210801_127_dialog_content = "石板も玉座と同じように、元の姿に戻ろうとしてるみたいだ…",
  ui_story_1021_10210801_128_dialog_content = "2本目の松の木だね。",
  ui_story_1021_10210801_129_dialog_content = "3本目の松の木は…ベツレヘムさんは、本当に灯台を消すのかな…",
  ui_story_1021_10210801_130_dialog_content = "今はもう、女王陛下に対して何の疑念も抱いてない。\n陛下が何をなさろうと、私はお側についてお力になる！",
  ui_story_1021_10210801_131_dialog_content = "急いで松の木を持ち帰るよ！",
  ui_story_1021_10210801_132_dialog_content = "うん！",
  ui_story_1021_10210801_133_dialog_content = "それから…あんたたち…ありがとう！",
  ui_story_1021_10210801_134_dialog_content = "ハハッ、いいってことよ。",
  ui_story_1021_10210801_135_dialog_content = "ロイ兄、せっかく見つけたんだし、\nついて行って手助けしようよ。",
  ui_story_1021_10210801_136_dialog_content = "はぁ、まったくしょうがないねェ。行くぞ。",
  ui_story_1021_10210801_137_dialog_content = "<color=#e8d9bb>こうして、村と王室の誓いの石板は消えた。</color>",
  ui_story_1021_10210801_138_dialog_content = "大ババ様！ノーヴィオ様！ただ今戻りました！\n松の木を持って…",
  ui_story_1021_10210801_139_dialog_content = "祭壇にあるのは…？",
  ui_story_1021_10210801_140_dialog_content = "女王陛下の身体から取り出した「炎」の力です。\n今まさに力を凝縮し、「灯芯」になろうとしています。",
  ui_story_1021_10210801_141_dialog_content = "「灯芯」って…ということは、崖にある灯台の光は消えちゃうの？",
  ui_story_1021_10210801_142_dialog_content = "いいえ。女王陛下はとうの昔に北境の灯台の力そのものとなられました。\nこれは陛下の命の力です。",
  ui_story_1021_10210801_143_dialog_content = "命の力…ということは、陛下のお身体が弱ってしまわれるのでは？",
  ui_story_1021_10210801_144_dialog_content = "弱ってはいらっしゃいますが、\n陛下はすでに暗鬼を北境の辺境まで追いやりました…",
  ui_story_1021_10210801_145_dialog_content = "陛下がそこまでなさるとは…",
  ui_story_1021_10210801_146_dialog_content = "長い月日がかかってしまいましたが、\n陛下が約束なさった灯台はあなた方の協力のもと、まもなく完成することでしょう。",
  ui_story_1021_10210801_147_dialog_content = "今、私に何ができるんですか？",
  ui_story_1021_10210801_148_dialog_content = "持ち帰った松の枝を祭壇に置き、\nその槍の力も神にお返しするのだ。",
  ui_story_1021_10210801_149_dialog_content = "わしと共に神に祈れ…",
  ui_story_1021_10210801_150_dialog_content = "雪狐の村の長老、北境の偉大なる戦士ローデの護衛ハーゲンは今ここに、\n神のお力添えを賜りたくお祈り申し上げます。",
  ui_story_1021_10210801_151_dialog_content = "雪狐の村の長、北境の女王ベツレヘム陛下の護衛ティアラは今ここに、\n神のお力添えを賜りたくお祈り申し上げます。",
  ui_story_1021_10210801_152_dialog_content = "北境の女王はその誓いを果たしました。「灯芯」の力はあなた様から賜りましたもの。\n松の木の枝もまた、あなた様から賜りました。",
  ui_story_1021_10210801_153_dialog_content = "今、お手元にお返しします。どうか、その力をもって、\n万物の力を育み、糧をお授けください。",
  ui_story_1021_10210801_154_dialog_content = "世の転変の中を生きる北境に、\n長きにわたるご加護を賜りませんことを――",
  ui_story_1021_10210801_155_dialog_content = "山河の霊杖よ、力を与えたまえ！",
  ui_story_1021_10210801_156_dialog_content = "<color=#e8d9bb>ヒューッ――ヒューッ――！</color>",
  ui_story_1021_10210801_157_dialog_content = "…！！！",
  ui_story_1021_10210801_158_dialog_content = "3つの切り株が、一瞬で大きな…天にも届く大木になった！",
  ui_story_1021_10210801_159_dialog_content = "これが「原始の浄域」の力なの…？",
  ui_story_1021_10210801_160_dialog_content = "…",
  ui_story_1021_10210801_161_dialog_content = "槍の力は消えてない…むしろ、\nもっと強い力が湧き上がってくるのを感じるよ！",
  ui_story_1021_10210801_162_dialog_content = "稲妻みたいに光ってるものが、松の中から流れてくるエネルギーなの…？",
  ui_story_1021_10210801_163_dialog_content = "…",
  ui_story_1021_10210801_164_dialog_content = "世界の尾根の上で、先祖たちは暖かく豊かな渓流を見つけた。",
  ui_story_1021_10210801_165_dialog_content = "その渓流は天の授けし恵みのごとく、氷に閉ざされた北境を脈々と流れ、\nアストラの心臓部奥深くへと続いておる…",
  ui_story_1021_10210801_166_dialog_content = "それが「原始の浄域」の起源じゃ。渓流は生い茂るスノーシダーの森を潤し、\nわが先祖たちはこの森に根ざし、芽を出した。",
  ui_story_1021_10210801_167_dialog_content = "そして今、「原始の浄域」の加護のもと、松の木と「灯芯」の力が集まり、\n共にこの新しい「灯台」を築いたのじゃ。",
  ui_story_1021_10210801_168_dialog_content = "灯台の光は長き冬を照らし、脈々と続く雪山を越えて暗闇を払い、\n生き物の愛する大地を照らすのじゃ。",
  ui_story_1021_10210801_169_dialog_content = "そして、ティアラ。\nそなたは今、神の認める北境の護衛となったのじゃよ。",
  ui_story_1021_10210801_170_dialog_content = "神が私を…？だから、力を授かったんですね！",
  ui_story_1021_10210801_171_dialog_content = "私の手の中の氷の槍はまるで、灼熱のたいまつのようです！",
  ui_story_1021_10210801_172_dialog_content = "これから、そなたは神から賜りし力と使命を背負うことになる…",
  ui_story_1021_10210801_173_dialog_content = "ティアラ、そなたの勇気と知恵で、わしらの北境を守れ。",
  ui_story_1021_10210802_1_dialog_content = "今スノーシダーの森から立ち昇った光は、\n太古の遺跡が発したものか…？",
  ui_story_1021_10210802_2_dialog_content = "いや、待て。今この時に現れたってことは…\n何かの合図かもしれない！",
  ui_story_1021_10210802_3_dialog_content = "伝説の中の灯台は、導きと加護の役割を持っている。\nということは、北境にはいくつも灯台があったんじゃないか？",
  ui_story_1021_10210802_4_dialog_content = "いったいどんな分布だったんだ？",
  ui_story_1021_10210802_5_dialog_content = "灯台の光は、いったいどうやって\nこの大地に降り注いでたんだろう…？",
  ui_story_1021_10210802_6_dialog_content = "<color=#e8d9bb>ある人目の付かない場所では――</color>",
  ui_story_1021_10210802_7_dialog_content = "北境にはやはり、あの力が眠っていたんだね。",
  ui_story_1021_10210802_8_dialog_content = "水脈が回復したからには、すぐに海に流れ込むだろうね。",
  ui_story_1021_10210802_9_dialog_content = "私たちがこの光景を目撃したと知れば、\nビクトリア様もきっとお喜びになるわ。",
  ui_story_1021_10210802_10_dialog_content = "それでは、僕たちも出発するとしようか。",
  ui_story_1021_10210802_11_dialog_content = "<color=#e8d9bb>啓光の飛行機内では――</color>",
  ui_story_1021_10210802_12_dialog_content = "…まるで雪山から太陽が昇ったかのようですね…\nこのような光は今までに見たことがございません。",
  ui_story_1021_10210802_13_dialog_content = "光の上がった方向に向かい、加速前進だ！",
  ui_story_1021_10210802_14_dialog_content = "了解です！",
  ui_story_1021_10210901_1_dialog_content = "どうやら…新たな「灯台」が完成したようだ。",
  ui_story_1021_10210901_2_dialog_content = "女王陛下、お身体の調子はいかがですか！？\nさきほどのご様子では…",
  ui_story_1021_10210901_3_dialog_content = "もう大丈夫だ、カレン。\nこの私にも、北境にも、さらに強大な後ろ盾ができたのだからな。",
  ui_story_1021_10210901_4_dialog_content = "グアア――！",
  ui_story_1021_10210901_5_dialog_content = "『ううっ…い、痛みが…』",
  ui_story_1021_10210901_6_dialog_content = "『ひ、ひどい痛みです…！』",
  ui_story_1021_10210901_7_dialog_content = "『この感覚…思い出しました…』",
  ui_story_1021_10210901_8_dialog_content = "『ある雪の降る日、トナカイに乗った女子が現れ…』",
  ui_story_1021_10210901_9_dialog_content = "『そう…思い出しました。』",
  ui_story_1021_10210901_10_dialog_content = "『今回の修行は、来た甲斐があったようです。』",
  ui_story_1021_10210901_11_dialog_content = "氷の先にパワーチャージ完了！",
  ui_story_1021_10210901_12_dialog_content = "…",
  ui_story_1021_10210901_13_dialog_content = "グアア――！",
  ui_story_1021_10210901_14_dialog_content = "女王陛下、カレン殿下、遅れて申し訳ございません！",
  ui_story_1021_10210901_15_dialog_content = "ティアラ、今の攻撃は実に精確で力強かったわ！",
  ui_story_1021_10210901_16_dialog_content = "その槍も、あなた自身も、前よりずっと強くなったようね！",
  ui_story_1021_10210901_17_dialog_content = "大ババ様が言うには、神が認めてくださったからこそ得られた力だそうです。\n今や私も立派な女王陛下の護衛です！",
  ui_story_1021_10210901_18_dialog_content = "北境の護衛だよ！",
  ui_story_1021_10210901_19_dialog_content = "はい、北境の護衛です！",
  ui_story_1021_10210901_20_dialog_content = "私にもそなたの変化と成長が伝わってくる。\nティアラ、よくやった。",
  ui_story_1021_10210901_21_dialog_content = "そして、感謝するぞ。\n私と共に新たな灯台を築いてくれたことにな。",
  ui_story_1021_10210901_22_dialog_content = "女王陛下！氷の宮殿の玉座のことも、王室と村との間の約束も、\n今は全部わかりました。それから…",
  ui_story_1021_10210901_23_dialog_content = "それから…陛下にお話ししたいことがたくさんございます！\nですが今は…何よりも申し上げたいことがあるのです！",
  ui_story_1021_10210901_24_dialog_content = "この先、私は陛下に付いてまいります！\nもう二度とお独りで戦うようなことはさせません！",
  ui_story_1021_10210901_25_dialog_content = "「雪解け水は山河を伝い、豊かさを届ける。\n草木は命の力を、祝福されし地にもたらす…」",
  ui_story_1021_10210901_26_dialog_content = "おとなしく死ね、暗鬼め！",
  ui_story_1021_10210901_27_dialog_content = "待て、ティアラ！",
  ui_story_1021_10210901_28_dialog_content = "女王陛下…？",
  ui_story_1021_10210901_29_dialog_content = "戦いだけでなく、そなたは何故…\n北境の祝福の言葉まで知っておるのだ？",
  ui_story_1021_10210901_30_dialog_content = "あの頃の雪国は一面静まりかえっていました。",
  ui_story_1021_10210901_31_dialog_content = "空には漆黒の太陽が昇り、\nあの方も私たちの近くにいらっしゃったのに…",
  ui_story_1021_10210901_32_dialog_content = "あの女子が現れました…",
  ui_story_1021_10210901_33_dialog_content = "…",
  ui_story_1021_10210901_34_dialog_content = "北境の初代女王に会ったことがあるのか？",
  ui_story_1021_10210901_35_dialog_content = "女子は手に握った光で、この屋根を砕いてしまいました。\nそうして私たちとあの方は、永遠に離れ離れとなったのです。",
  ui_story_1021_10210901_36_dialog_content = "私は漆黒の太陽をもう一度見たいと思いました。",
  ui_story_1021_10210901_37_dialog_content = "しかし、女子の手に握られた物が、私の両目を引き裂きました。",
  ui_story_1021_10210901_38_dialog_content = "今回の修行で、私はあらゆることに思いをめぐらし…",
  ui_story_1021_10210901_39_dialog_content = "この両目に残された最後の光は、怒りではなかったと知り…",
  ui_story_1021_10210901_40_dialog_content = "怒りなどではなかったのです！",
  ui_story_1021_10210901_41_dialog_content = "あの揺れる光が、私の世界を怒りの色に染めてしまったのです！",
  ui_story_1021_10210901_42_dialog_content = "『私は氷など恐れない。炎も同じだ…』",
  ui_story_1021_10210901_43_dialog_content = "『だが、あのまたたきながら近づいてくる白いものは…\nいったい何なのだ…？』",
  ui_story_1021_10210901_44_dialog_content = "灯台だ！女王陛下の灯台だ――！",
  ui_story_1021_10210901_45_dialog_content = "女王陛下が灯台と共に助けに来てくださった！",
  ui_story_1021_10210901_46_dialog_content = "『灯台…』",
  ui_story_1021_10210901_47_dialog_content = "グアア――！",
  ui_story_1021_10210901_48_dialog_content = "すべて、思い出しました。",
  ui_story_1021_10210901_49_dialog_content = "何もかも…",
  ui_story_1021_10210901_50_dialog_content = "修行は終わりました。あなたたちのことは見逃してあげましょう。\nさあ、お逃げなさい。",
  ui_story_1021_10210901_51_dialog_content = "…",
  ui_story_1021_10210901_52_dialog_content = "残念だけど、こっちはあんたを見逃す気はないんだよ！",
  ui_story_1021_10210901_53_dialog_content = "あんたが村や狐たちにしたことを、10倍にして返してやる！",
  ui_story_1021_10210901_54_dialog_content = "逃げないのですか…ならば、こちらへいらっしゃい。",
  ui_story_1021_10210901_55_dialog_content = "ティアラ！",
  ui_story_1021_10210901_56_dialog_content = "氷の先にパワーチャージ完了！",
  ui_story_1021_10210901_57_dialog_content = "<color=#e8d9bb>ドドドド……</color>",
  ui_story_1021_10210901_58_dialog_content = "あ、暗鬼め…逃がさないよ…ゲホッ…ゴホゴホッ…",
  ui_story_1021_10210901_59_dialog_content = "ティアラ！",
  ui_story_1021_10210901_60_dialog_content = "気を付けて！君を暗面に引き込もうとしてるんだ！",
  ui_story_1021_10210901_61_dialog_content = "今のは…爆弾？",
  ui_story_1021_10210901_62_dialog_content = "PlayerName、上を見て――",
  ui_story_1021_10210901_63_dialog_content = "目標には命中しませんでしたが…\nPlayerNameたちは暗鬼の領域に進入するつもりのようです。",
  ui_story_1021_10210901_64_dialog_content = "高度を下げ、援護せよ！",
  ui_story_1021_10210901_65_dialog_content = "承知いたしました、大元帥様！",
  ui_story_1021_10210901_66_dialog_content = "会長、拠点で…戦ってるぜ！俺たちも――",
  ui_story_1021_10210901_67_dialog_content = "啓光と白夜城の軍が応援に向かうことになっています。\n余計なことはしなくてよいのです。",
  ui_story_1021_10210901_68_dialog_content = "甲板へ向かい、合同探索の旗を掲げましょう！",
  ui_story_1021_10210901_69_dialog_content = "準備完了いたしました。いつでも出陣できます。",
  ui_story_1021_10210901_70_dialog_content = "境界線に沿って暗鬼を掃討し、北境の護衛らを支援するのだ。\n主戦場はあの若者らに任せよ。",
  ui_story_1021_10210901_71_dialog_content = "はい、城主様！",
  ui_story_1021_10210901_72_dialog_content = "啓光の飛行機だ…",
  ui_story_1021_10210901_73_dialog_content = "白夜城の飛空艇も…どの陣営も関心を持ってくれているのね。",
  ui_story_1021_10210901_74_dialog_content = "でも、あの暗鬼はティアラを挑発して、\n僕たちを向こうに引き込もうとしてるみたいだ…",
  ui_story_1021_10210901_75_dialog_content = "ティアラったら、速すぎるわ！\n今にもあの「壁」を越えそうよ！",
  ui_story_1021_10210901_76_dialog_content = "「壁」を越えれば、戻ることはできない。",
  ui_story_1021_10210901_77_dialog_content = "だが、灯台の光はすでに向こうにも届いている。\nついてこい。",
  ui_story_1021_10210901_78_dialog_content = "氷で道を拓き、そなたらを山へと導こう。\nティアラと共にあの暗鬼を北境から追い出すのだ！",
  ui_story_1021_10210901_79_dialog_content = "はい！",
  ui_story_1021_10210901_80_dialog_content = "ティアラ――！",
  ui_story_1021_10210901_81_dialog_content = "僕たちを置いてかないでよ！一緒に戦うんでしょ！",
  ui_story_1021_10210901_82_dialog_content = "女王陛下、みんな…それから、2人まで…",
  ui_story_1021_10210901_83_dialog_content = "言ったじゃん、R・Wも合同探索のメンバーなんだって！",
  ui_story_1021_10210901_84_dialog_content = "そうそう。お前さんたちの習慣だと、探索を始める前に、\n気持ちを奮い立たせる決起集会みてえのをやるんだろ？",
  ui_story_1021_10210901_85_dialog_content = "決起集会とか、そういうのはよくわからないけど…",
  ui_story_1021_10210901_86_dialog_content = "北境の護衛の名に誓うよ！\nこの暗鬼どもは必ず、1匹残らず追い出してやる！",
  ui_story_1021_10210901_87_dialog_content = "知らず知らずのうちに、合同探索が第一歩を踏み出したようだな。",
  ui_story_1021_10210901_88_dialog_content = "この先は暗鬼らが「領地」と呼ぶ領域だ。\nだが、殺りくを生きる術とする暗鬼に生存の基盤などあってはならぬ！",
  ui_story_1021_10210901_89_dialog_content = "灯台の光に沿って進み、やつらの息の根をことごとく止めるぞ！",
  ui_story_1021_10210901_90_dialog_content = "ベツレヘムさんが、そんな言葉を口にするなんて…",
  ui_story_1021_10210901_91_dialog_content = "ティアラのような護衛をもてば、\n私とて影響を受けぬわけがない。",
  ui_story_1021_10210901_92_dialog_content = "互いに励まし合い、互いを想いながら、\n北境と光霊の未来を想い描き――",
  ui_story_1021_10210901_93_dialog_content = "皆が互いの灯台となりし時、そなたらの力はあらゆる恐怖を超越するだろう。",
  ui_story_1021_10210901_94_dialog_content = "…！",
  ui_story_1021_10210901_95_dialog_content = "あ！あの粉々になった石を見て！\nあの暗鬼ったら、まだ立ち去る気はないみたいだよ！",
  ui_story_1021_10210901_96_dialog_content = "ならば、消すまでだ。\n私もそなたらと共に暗面に向かって進むぞ！",
  ui_story_1021_10210901_97_dialog_content = "前進！",
  ui_story_1021_10210902_1_dialog_content = "素晴らしい。予想をはるかに超えています…",
  ui_story_1021_10210902_2_dialog_content = "境地に達するため、私は己に打ち勝たねばなりません。",
  ui_story_1021_10210902_3_dialog_content = "私はこれで失礼しますが、言っておきたいことがあります…",
  ui_story_1021_10210902_4_dialog_content = "暗闇の香りをかぎながら、私たちの世界へといらっしゃい…",
  ui_story_1021_10210902_5_dialog_content = "あなた方は屍の山となった先人らの呼びかける声を聞きながら、\n前へと進むことになるでしょう。",
  ui_story_1021_10210902_6_dialog_content = "私、王の護衛アイラが、極夜でお待ちしています。",
  ui_story_1021_10210902_7_dialog_content = "あなた方には…期待しています…",
  ui_story_1021_10211001_1_dialog_content = "暗鬼は北境から退却し、灯台の光源も安定を取り戻しました。",
  ui_story_1021_10211001_2_dialog_content = "応援部隊は戻ったのか？",
  ui_story_1021_10211001_3_dialog_content = "まだ啓光の参謀長が松の谷で、PlayerName様たちをお待ちです。",
  ui_story_1021_10211001_4_dialog_content = "拠点が完成しないまま、暗面探索が始動いたしましたね。\nしかもこのような形で始まるとは思いませんでした。",
  ui_story_1021_10211001_5_dialog_content = "あの新たな灯台があれば、暗面の奥深くに進むまで、\nひとまず加護が得られる。",
  ui_story_1021_10211001_6_dialog_content = "ということは、合同探索隊は北境より出発するのですか？",
  ui_story_1021_10211001_7_dialog_content = "さようだ。ゆえに拠点の建設を急がねばならぬ。",
  ui_story_1021_10211001_8_dialog_content = "女王陛下、お別れの挨拶にまいりました。\nこれで私たちは失礼いたします。",
  ui_story_1021_10211001_9_dialog_content = "カレンは今すぐにでも戻って飛行訓練を受けたいんです。",
  ui_story_1021_10211001_10_dialog_content = "そ、そういうわけでは…他にも準備すべきことがたくさんあり…",
  ui_story_1021_10211001_11_dialog_content = "うむ。では、急ぎ戻るがよい。\n此度のそなたらの助けに感謝するぞ。おかげで新たな灯台が完成した。",
  ui_story_1021_10211001_12_dialog_content = "それはティアラの手柄です。\nそういえば、ティアラはどうしたんですか？",
  ui_story_1021_10211001_13_dialog_content = "ほかに仕事があってな。",
  ui_story_1021_10211001_14_dialog_content = "合同探索隊の各位に伝えておいてくれ。\n拠点建設の件は心配無用だ。近いうちによい知らせを送れるであろう、と。",
  ui_story_1021_10211001_15_dialog_content = "白夜城は護衛隊を派遣し、拠点の建設をお手伝いいたします。ですが、幾日か遅れると城主が申しておりました。",
  ui_story_1021_10211001_16_dialog_content = "外に機械の専門家が2人いるので、今日にでも建設を始められますよ。",
  ui_story_1021_10211001_17_dialog_content = "確かにそうね。前々から宝石を欲しがっていたようだし、\nすでに持ち去ったものは報酬の前払いとしましょう。",
  ui_story_1021_10211001_18_dialog_content = "そんなおっきな声で言わなくても聞こえてるよ…",
  ui_story_1021_10211001_19_dialog_content = "宝石ならとっくの昔にどっかに落としちゃったよ…\nタダ働きなんかしたら、サメヤマさんに怒られちゃう…",
  ui_story_1021_10211001_20_dialog_content = "それに俺はやっぱり、熱気立ち込めるR・Wで裏方やってたいねェ。\n北境ってトコはそこらじゅう宝物ばかりだが、二度と来るのはごめんだなァ。",
  ui_story_1021_10211001_21_dialog_content = "じゃあ、一緒に探索するって話はどうするの？",
  ui_story_1021_10211001_22_dialog_content = "状況次第ってとこかねェ。\nオッさんはこれでも忙しいんだよ。",
  ui_story_1021_10211001_23_dialog_content = "このような日が来ると予見はしていたが、手の届かぬ遠い夢のようにも感じていた…\nそれが今、真になったのだな。",
  ui_story_1021_10211001_24_dialog_content = "これまでは、各陣営ともそれぞれの立場を堅持し、\n合同探索など果たせぬ言葉だけの誓いのようなものだった。",
  ui_story_1021_10211001_25_dialog_content = "それが今、仲間のごとく、互いのために前に立つ…",
  ui_story_1021_10211001_26_dialog_content = "暗面に進みし時、その仲間たちが暗黒の中で、\n力強き支えとならんことを願う。",
  ui_story_1021_10211001_27_dialog_content = "<color=#e8d9bb>松の谷近く</color>",
  ui_story_1021_10211001_28_dialog_content = "PlayerName！待って！",
  ui_story_1021_10211001_29_dialog_content = "ティアラ、どうしてここに？",
  ui_story_1021_10211001_30_dialog_content = "プレゼントを渡したいんだ。でも、つい…\n運ぶのを手伝ってくれてる人がスピードについてこれなくて…アハハハ！",
  ui_story_1021_10211001_31_dialog_content = "そのうち皆、ティアラと一緒に行動したがらなくなりそうだね…",
  ui_story_1021_10211001_32_dialog_content = "そうだ、この先どうするの？\n君には合同探索に参加してほしいって思ってるんだ。",
  ui_story_1021_10211001_33_dialog_content = "あなたは動きが敏捷で勇敢よ。\n万が一の時もきっと皆の大きな助けになるわ。",
  ui_story_1021_10211001_34_dialog_content = "誘ってもらって嬉しいけど、何か忘れてない？\n私の大切なものは、もうとっくに決まってるんだよ。",
  ui_story_1021_10211001_35_dialog_content = "今回みんなと一緒にいろんな経験をしたことで、\n私も自分がきちんと責任を果たせてないことを思い知った。",
  ui_story_1021_10211001_36_dialog_content = "これからはもっと努力して、\n責任感のある立派な北境の護衛になってみせる！",
  ui_story_1021_10211001_37_dialog_content = "だから、決めたんだ。私は北境に残って、雪狐の村のご先祖様たちと\n歴代女王陛下の偉業を引き継ぐ！",
  ui_story_1021_10211001_38_dialog_content = "ひいばあちゃんから聞けなかった物語は、\n大ババ様からきちんと教えてもらうよ。",
  ui_story_1021_10211001_39_dialog_content = "それはすごく意味のあることだと思うよ。僕も雪狐や北境の女王の偉業を覚えていたい。\n忘れないでね。僕も歴史の証人の一人だってこと。",
  ui_story_1021_10211001_40_dialog_content = "新しい物語を聞かせてもらったら、\n手紙で僕にも教えてね！",
  ui_story_1021_10211001_41_dialog_content = "いや…あの方法で――",
  ui_story_1021_10211001_42_dialog_content = "コオォーン――！",
  ui_story_1021_10211001_43_dialog_content = "コオォーン――！",
  ui_story_1021_10211001_44_dialog_content = "他人が重い荷物を運んでる時に、\nのんきに鳴き声をあげるなんて、どういうこと！？",
  ui_story_1021_10211001_45_dialog_content = "この人は…？",
  ui_story_1021_10211001_46_dialog_content = "北境で知り合った友だちだよ。ザーリャっていうんだ。",
  ui_story_1021_10211001_47_dialog_content = "ティアラと一緒にプレゼントを運んできたのって、\n君だったんだね…",
  ui_story_1021_10211001_48_dialog_content = "ティアラったら、ほんと足が速くて、\nあっという間に見えなくなっちゃうんだもの！",
  ui_story_1021_10211001_49_dialog_content = "ティアラと一緒にいたら、\n置いて行かれるのはごく普通のことだよね…",
  ui_story_1021_10211001_50_dialog_content = "そうじゃないわよ。まだ私のこと怒ってるからでしょ！？",
  ui_story_1021_10211001_51_dialog_content = "フン！そっちが狐たちに氷の結晶を放ったんだよ！",
  ui_story_1021_10211001_52_dialog_content = "あなたが教えてくれなかったのがいけないんじゃない！\n雪狐の村を訪ねると、銀白の狐たちに…手を舐められるって…！",
  ui_story_1021_10211001_53_dialog_content = "北境にはね、そんな風習ないのよ！",
  ui_story_1021_10211001_54_dialog_content = "…",
  ui_story_1021_10211001_55_dialog_content = "あの光ってる物がプレゼント？",
  ui_story_1021_10211001_56_dialog_content = "まさか、光力鉱石…？",
  ui_story_1021_10211001_57_dialog_content = "正解！この私がものすごく苦労して、\nやっとのことでティアラの故郷から運んできたのよ！",
  ui_story_1021_10211001_58_dialog_content = "こんな貴重な物、もらえないよ！",
  ui_story_1021_10211001_59_dialog_content = "どうして？私は今、雪狐のリーダーとして、\n村の恩人に鉱石をプレゼントするって言ってるんだよ…",
  ui_story_1021_10211001_60_dialog_content = "それは、大ババ様の意志でもあるんだ。",
  ui_story_1021_10211001_61_dialog_content = "女王陛下もおっしゃっていたわ。この鉱石は暗面の中で行く先を照らし、\n暗鬼を駆逐できるって。探索で大いに役立つわ。",
  ui_story_1021_10211001_62_dialog_content = "でも、この鉱石は北境の辺境を照らして、\n暗鬼を寄せ付けないためのものでしょ…",
  ui_story_1021_10211001_63_dialog_content = "…もうっ！村からのプレゼントだって言ってんの！\n私の気が変わらないうちに受け取りなよ！",
  ui_story_1021_10211001_64_dialog_content = "うっ…分かった、分かったよ。",
  ui_story_1021_10211001_65_dialog_content = "（ああ…女王陛下の護衛としてのティアラが懐かしくなってきた…）",
  ui_story_1021_10211001_66_dialog_content = "…",
  ui_story_1021_10211001_67_dialog_content = "そなたもようやく安心してティアラにやりたいことを\nやらせられるようになったようじゃな。",
  ui_story_1021_10211001_68_dialog_content = "私の護衛にならなくとも、ティアラはこの北境で己の居場所を見つけられる。",
  ui_story_1021_10211001_69_dialog_content = "だが、あの日の雪崩以来、\nそなたがあの子にとっての灯台になった。",
  ui_story_1021_10211001_70_dialog_content = "<color=#e8d9bb>村が襲われた日…</color>",
  ui_story_1021_10211001_71_dialog_content = "女王の護衛は、大変ではないか？",
  ui_story_1021_10211001_72_dialog_content = "陛下はとても強大でいらっしゃいます…危険が迫ると、陛下自ら皆を守ってくださいます。\nですから、大変だと感じたことはありません。",
  ui_story_1021_10211001_73_dialog_content = "私が危険な目に遭うたび、必ず救ってくださるんです…",
  ui_story_1021_10211001_74_dialog_content = "雪狐は恩を必ず返します。ですから、雪崩の中から助けていただいたあの時から、\n私は陛下をお守りすると誓ったんです。",
  ui_story_1021_10211001_75_dialog_content = "そなたは本当にあの者を理解しておるのか？",
  ui_story_1021_10211001_76_dialog_content = "もちろんです！女王陛下が私たちの領地へ巡回で来られた時から…\nずっと陰から陛下を見てきました…",
  ui_story_1021_10211001_77_dialog_content = "陛下の一挙一動、オーラも、その呼吸さえも…\n私はよく理解しています。",
  ui_story_1021_10211001_78_dialog_content = "村がよそ者を歓迎しないのは…わかっています。\nでも、女王陛下は違います…",
  ui_story_1021_10211001_79_dialog_content = "陛下の私を見る目は、まるで毎年必ず会いに来てくれる家族のような眼差しで…",
  ui_story_1021_10211001_80_dialog_content = "陛下がいらっしゃるたびに、村が明るく照らされ、\n私の世界もまた明るく輝くんです…",
  ui_story_1021_10211001_81_dialog_content = "ティアラ、答えは己の心の中にある。",
  ui_story_1021_10211001_82_dialog_content = "この世で、そなたの世界を明るく照らす者こそ、\nそなたの灯台じゃ。",
  ui_story_1021_10211001_83_dialog_content = "己の灯台の光をたどり、その光と熱を己の力とせよ。",
  ui_story_1021_10211001_84_dialog_content = "そなたの灯台をそなた自身が照らすことができた時、\nわが村も必ずや光に満ちあふれるだろう。",
  ui_story_1021_10211001_85_dialog_content = "…",
  ui_story_1021_10211001_86_dialog_content = "雪崩か…真実を話すつもりはないのか？",
  ui_story_1021_10211001_87_dialog_content = "話したところで、今や違いはなかろう。",
  ui_story_1021_10211001_88_dialog_content = "…",
  ui_story_1021_10211001_89_dialog_content = "だが、私から見れば、そなたもティアラの灯台だ。",
  ui_story_1021_10211001_90_dialog_content = "<color=#e8d9bb>数年前…</color>",
  ui_story_1021_10211001_91_dialog_content = "<color=#e8d9bb>ガサッ――</color>",
  ui_story_1021_10211001_92_dialog_content = "…？",
  ui_story_1021_10211001_93_dialog_content = "（あの時私に雪を投げつけた少女もいつの間にか、\nかように大きくなったか…）",
  ui_story_1021_10211001_94_dialog_content = "（この広大な森の中で独り暮らすのは、寂しかろうに）",
  ui_story_1021_10211001_95_dialog_content = "<color=#e8d9bb>サラサラ――</color>",
  ui_story_1021_10211001_96_dialog_content = "…",
  ui_story_1021_10211001_97_dialog_content = "…",
  ui_story_1021_10211001_98_dialog_content = "（なんともせっかちな子だ…）",
  ui_story_1021_10211001_99_dialog_content = "（これまでは遠くから付いてくるだけだったが、\n此度は進んで存在を明かしたか…）",
  ui_story_1021_10211001_100_dialog_content = "…",
  ui_story_1021_10211001_101_dialog_content = "毎年この季節には必ずやってくるのう。",
  ui_story_1021_10211001_102_dialog_content = "…",
  ui_story_1021_10211001_103_dialog_content = "だが、「灯台の光を届ける」という約束は、\n今だ果たせていない。",
  ui_story_1021_10211001_104_dialog_content = "…",
  ui_story_1021_10211001_105_dialog_content = "心から感謝する。\nそなたらがいなければ、北境の今の安寧はない。",
  ui_story_1021_10211001_106_dialog_content = "先祖たちはこの地に留まり、戦いの鉄槌の下に命を落としたが…",
  ui_story_1021_10211001_107_dialog_content = "それはわしら自身が決め、誇りに思っておることじゃ。\nこの先も守り続けるぞ。",
  ui_story_1021_10211001_108_dialog_content = "…",
  ui_story_1021_10211001_109_dialog_content = "ティアラを連れていくがよい。",
  ui_story_1021_10211001_110_dialog_content = "…？",
  ui_story_1021_10211001_111_dialog_content = "わしはもう長くはない。もう少し大人になれば、\nあの子も「守る」には代償を払わねばならぬと知るだろう。",
  ui_story_1021_10211001_112_dialog_content = "わしはティアラがあの子のひいばばのように、\n執念と孤独を抱きながら、この森を守ることを望まぬ。",
  ui_story_1021_10211001_113_dialog_content = "…ティアラは強情な子のようだが。",
  ui_story_1021_10211001_114_dialog_content = "だが、そなたには好奇心とあこがれを抱いておる。",
  ui_story_1021_10211001_115_dialog_content = "…",
  ui_story_1021_10211001_116_dialog_content = "<color=#e8d9bb>長老は森にむかって飛び跳ねると、\n巨大な雪の塊がティアラをめがけて転がっていった…</color>",
  ui_story_1021_10211001_117_dialog_content = "うわぁあああ――！",
  ui_story_1021_10211001_118_dialog_content = "氷が溶ければそれで終わりだ――",
  ui_story_1021_10211001_119_dialog_content = "あなたが私を救ってくださった…",
  ui_story_1021_10211001_120_dialog_content = "それに…",
  ui_story_1021_10211001_121_dialog_content = "これで、そなたの槍はより固く強くなった。",
  ui_story_1021_10211001_122_dialog_content = "あ…まぶしい光まで発してる…！",
  ui_story_1021_10211001_123_dialog_content = "まるで、灯台みたい…",
  ui_story_1021_10211001_124_dialog_content = "待って…",
  ui_story_1021_10211001_125_dialog_content = "…",
  ui_story_1021_10211001_126_dialog_content = "わ、私は、ティアラと申します！",
  ui_story_1021_10211001_127_dialog_content = "…",
  ui_story_1021_10211001_128_dialog_content = "今日から、あなた様がどこへ向かおうと、私がお守りします！\n雪狐は、必ず恩を返すのです！",
  ui_story_1021_10211001_129_dialog_content = "…",
  ui_story_1021_10211001_130_dialog_content = "北境のために尽くしてくれたこと、心より感謝する。",
  ui_story_1021_10211001_131_dialog_content = "誓いとは時として重くのしかかる。\nだが、私はこの先も歩み続ける…",
  ui_story_1021_10211001_132_dialog_content = "皆に誓おう。北境の灯台はこの地をも照らす…",
  ui_story_1021_10211001_133_dialog_content = "そして、さらなる遠方までも照らすことだろう。",
  ui_story_1022_10220100_1_dialog_content = "（ここは…どこだろう？）",
  ui_story_1022_10220100_2_dialog_content = "<color=#e8d9bb>目の前に広がる果てしない暗闇は方向感覚を鈍らせ、\n冷たさだけが、ただ伝わってくる</color>",
  ui_story_1022_10220100_3_dialog_content = "（どうして…こんな所に…？）",
  ui_story_1022_10220100_4_dialog_content = "（どんどん寒くなる…じっとしてたらダメだ、動かなきゃ！）",
  ui_story_1022_10220100_5_dialog_content = "（でも…いったいどこへ？暗くて何も見えない…あれ？\nあれは、なんだろう？）",
  ui_story_1022_10220100_6_dialog_content = "<color=#e8d9bb>はるか遠くに1点のきらめきが見えた。\nその光は、重くのしかかる暗闇と凍てつく寒さの中にありながら――</color>",
  ui_story_1022_10220100_7_dialog_content = "<color=#e8d9bb>消えることなく、むしろますます明るく輝き、\n四方をまばゆいばかりに照らしていた</color>",
  ui_story_1022_10220100_8_dialog_content = "<color=#e8d9bb>それはあたかも、極夜に太陽が昇ったかのようだった</color>",
  ui_story_1022_10220100_9_dialog_content = "（なんて豊かな光力なんだろう！しかも限りなく純粋…\nまるで誰かの眼差しが僕を導いてくれてるみたいだ…）",
  ui_story_1022_10220100_10_dialog_content = "…忘れるでしょうね。\n経過した時間やこの先もっと忘れがたい人に出会うかどうかにもよるけれど。",
  ui_story_1022_10220100_11_dialog_content = "誰？誰が話してるの？",
  ui_story_1022_10220100_12_dialog_content = "さ、寒い…寒気がする…",
  ui_story_1022_10220100_13_dialog_content = "…風邪にゃ！",
  ui_story_1022_10220100_14_dialog_content = "さ…寒い…",
  ui_story_1022_10220100_15_dialog_content = "自分から毛布をはいで寝てたにゃん。しかも下敷きにして寝ちゃうから、\nフィリスじゃ掛けてあげられなかったにゃ。",
  ui_story_1022_10220100_16_dialog_content = "風邪引きたくにゃいなら、さっさと起きるにゃん！",
  ui_story_1022_10220100_17_dialog_content = "あれ？僕…寝ちゃってた？じゃあ、さっきのは夢…",
  ui_story_1022_10220100_18_dialog_content = "うわっ、寒い…ありがとう、フィリス。起こしてくれて。",
  ui_story_1022_10220100_19_dialog_content = "お礼なんていらにゃいにゃあ。\nこれでふかふかの寝床はフィリスのものにゃ…",
  ui_story_1022_10220100_20_dialog_content = "え？ま、待って！まだ寝ないで！",
  ui_story_1022_10220100_21_dialog_content = "今いったいどういう状況？僕たち、どこにいるの？",
  ui_story_1022_10220100_22_dialog_content = "窓の外を見れば、わかるにゃ～ん。",
  ui_story_1022_10220100_23_dialog_content = "窓の外？…あ。",
  ui_story_1022_10220100_24_dialog_content = "<color=#e8d9bb>飛行機の外を見ると、粘り気のあるどろどろの液体のような闇夜が、\n天地をどこまでも覆い尽くしていた</color>",
  ui_story_1022_10220100_25_dialog_content = "<color=#e8d9bb>夢の中のあの暗闇のように</color>",
  ui_story_1022_10220100_26_dialog_content = "暗面…暗面に入ったの？",
  ui_story_1022_10220100_27_dialog_content = "そうにゃん。そのことを伝えに来たのにゃ。\nそしたらPlayerNameが縮こまって寒いって言いながら寝てたのにゃ。",
  ui_story_1022_10220100_28_dialog_content = "ゴホ、ゴホゴホッ！",
  ui_story_1022_10220100_29_dialog_content = "（…暗面に入ったから、夢でも暗闇が…？）",
  ui_story_1022_10220100_30_dialog_content = "（夢には光力の塊も出てきた…現実世界にもあるのかな…？）",
  ui_story_1022_10220100_31_option_content = "感知展延",
  ui_story_1022_10220100_32_dialog_content = "…！",
  ui_story_1022_10220100_33_dialog_content = "（あった！でも…いったい何なんだろう？）",
  ui_story_1022_10220100_34_dialog_content = "ただ…にゃんか良くにゃい感じになってきたにゃ…",
  ui_story_1022_10220100_35_dialog_content = "もともと座標は2組受信できてたにゃん。",
  ui_story_1022_10220100_36_dialog_content = "1つは啓光が少し前から派遣してた精鋭の「暗面偵察隊」の座標で、\nもう1つはカロン長官とバイスの座標にゃ。",
  ui_story_1022_10220100_37_dialog_content = "バイスに何かあったってこと！？",
  ui_story_1022_10220100_38_dialog_content = "落ち着くにゃ…といっても難しいかもしれにゃいけど。\n座標信号に異常が出てるにゃん。",
  ui_story_1022_10220100_39_dialog_content = "「暗面偵察隊」の信号がどんどん弱くにゃってるから、\nたぶん暗面の影響で通信機器に問題が起こってるにゃん。",
  ui_story_1022_10220100_40_dialog_content = "でも啓光の機器って暗面でも使えるんだよね？",
  ui_story_1022_10220100_41_dialog_content = "暗面の環境はコロコロ変わるにゃ。\n地形、天気、位置関係や暗力の分布…どれも機器に影響を与えるにゃん。",
  ui_story_1022_10220100_42_dialog_content = "そう…で、バイスたちがどうしたの？",
  ui_story_1022_10220100_43_dialog_content = "…カロン長官とバイスの座標が、\nず～っとぴょんぴょん跳ねてるにゃん。",
  ui_story_1022_10220100_44_dialog_content = "ぴょんぴょん？",
  ui_story_1022_10220100_45_dialog_content = "ネコちゃんのオモチャみたいなモノにゃん。\nあっち行ったり、こっち行ったり…フィリス、目がチカチカしちゃったにゃ。",
  ui_story_1022_10220100_46_dialog_content = "フィリスの知ってる限り、\n「彼岸号」はこんにゃ動き方しにゃいんだけど…",
  ui_story_1022_10220100_47_dialog_content = "でも信号発信機の故障でもなさそうにゃん。\nとっても不思議にゃのにゃ。",
  ui_story_1022_10220100_48_dialog_content = "それも暗面の影響…？まだ連絡はつかないの？",
  ui_story_1022_10220100_49_dialog_content = "ヒイロ長官が試してみたけど、だめだったにゃ…\n今はまたどこかへ跳んで行ってしまって行方知れずにゃん。",
  ui_story_1022_10220100_50_dialog_content = "にゃ～っ、にゃにがどうにゃってるにゃ！？謎すぎるにゃん！\nいくら真面目に情報を集めてもわからにゃいにゃ！ほんと真面目にやってるのにーいっ！",
  ui_story_1022_10220100_51_dialog_content = "…まさか…ファントムに出くわしたんじゃ…",
  ui_story_1022_10220100_52_dialog_content = "にゃ！？",
  ui_story_1022_10220100_53_dialog_content = "ファントムの力はまったくの未知でしょ？\n空間をあちこち飛び回るなんて突拍子のないこともできるかもしれない…",
  ui_story_1022_10220100_54_dialog_content = "それに、バイスには「突撃者号」を操縦する素質がある。\n巨像を狙ってるファントムからすれば、ものすごく価値のある存在じゃないかな…",
  ui_story_1022_10220100_55_dialog_content = "どうしよう！ファントムの誰かがバイスをさらって、\nあちこち飛び回っているのかもしれない…！！",
  ui_story_1022_10220100_56_dialog_content = "にゃにゃにゃっ！そ、そんにゃ…",
  ui_story_1022_10220100_57_dialog_content = "カロンと「彼岸号」が側にいる限り、\nそのような状況はまず起こらないでしょうね。",
  ui_story_1022_10220100_58_dialog_content = "ヒイロ長官！",
  ui_story_1022_10220100_59_dialog_content = "ヒイロさん、その…本当に「起こらない」んでしょうか？\n万が一って可能性は――",
  ui_story_1022_10220100_60_dialog_content = "<color=#e8d9bb>ビンッ！</color>",
  ui_story_1022_10220100_61_dialog_content = "わっ！",
  ui_story_1022_10220100_62_dialog_content = "（デコピンされた…？）",
  ui_story_1022_10220100_63_dialog_content = "「万が一」まで気にしていてもしょうがありません。",
  ui_story_1022_10220100_64_dialog_content = "出発前、感情的にならないと約束してくれましたよね？\n忘れたのですか？",
  ui_story_1022_10220100_65_dialog_content = "いえ…忘れてません。ただ…バイスが今よく分からない状況に置かれてると聞いて、つい…",
  ui_story_1022_10220100_66_dialog_content = "（ううっ、デコピン痛かったぁ…）",
  ui_story_1022_10220100_67_dialog_content = "気持ちは分かります。ですが暗面は危険に満ちているのです。\n集中してください。",
  ui_story_1022_10220100_68_dialog_content = "バイスもそのことに気づいていてくれるとよいのですが。\nあの子もあなたと同じように、危険な状況になると他人の事ばかり気に掛けますから。",
  ui_story_1022_10220100_69_dialog_content = "軍人としての鍛錬が足りませんね。",
  ui_story_1022_10220100_70_dialog_content = "あの、もしかして…ヒイロさんもバイスのことが心配なんですか？",
  ui_story_1022_10220100_71_dialog_content = "当然でしょう？",
  ui_story_1022_10220100_72_dialog_content = "バイスにカロン長官、それからガルー室長…\n心配かける子ネコちゃんばっかりにゃ。",
  ui_story_1022_10220100_73_dialog_content = "ガルー？ガルーがどうかしたの？",
  ui_story_1022_10220100_74_dialog_content = "…「突撃者号」が見つかってから、\nゲームもやらずに毎日修理に没頭してるにゃ。",
  ui_story_1022_10220100_75_dialog_content = "ガルー室長は当時「突撃者号」実験の責任者だったにゃん。\nバイスと大元帥様に顔向けができにゃいとか思ってそうにゃ。",
  ui_story_1022_10220100_76_dialog_content = "他人の心配をしている余裕はありませんよ。\n今私たちの置かれている状況は深刻です。",
  ui_story_1022_10220100_77_dialog_content = "計画では、本来この飛行機は他の2組と連携して動くはずでした。",
  ui_story_1022_10220100_78_dialog_content = "ですが、今やその2組とも行方が分からなくなっています。\n計画を変更しなければなりません。",
  ui_story_1022_10220100_79_dialog_content = "フィリスはカロン長官たちのことがすごく気ににゃるにゃ。\n合流は難しいにゃん？",
  ui_story_1022_10220100_80_dialog_content = "（最後に送られてきた座標に今から駆け付けたところで、\n着いた時にはもう別の場所へ移動してる可能性が高い…くそっ！）",
  ui_story_1022_10220100_81_dialog_content = "暗面による干渉が原因で、「偵察隊」の座標信号はもう長時間途絶えています。",
  ui_story_1022_10220100_82_dialog_content = "このまま何の目的もなく飛んでいても時間を無駄にするだけです。\n当初の目的どころか何もできないまま終わってしまいます。",
  ui_story_1022_10220100_83_dialog_content = "…暗面に…光力の塊があります。",
  ui_story_1022_10220100_84_dialog_content = "はい？",
  ui_story_1022_10220100_85_dialog_content = "得体の知れない巨大な光力の塊が…暗面の奥にあるのを感知したんです。\nたぶん極夜に限りなく近い場所だと思うんですけど…",
  ui_story_1022_10220100_86_dialog_content = "光力の塊！？にゃんと！",
  ui_story_1022_10220100_87_dialog_content = "光力の塊は暗面では非常に珍しいものです。\n他の隊もその存在に気づいて、調べに向かっているのかもしれません。",
  ui_story_1022_10220100_88_dialog_content = "合流する絶好の機会かもしれませんね…",
  ui_story_1022_10220100_89_dialog_content = "失礼します！後方の拠点から通信要請が来ています！",
  ui_story_1022_10220100_90_dialog_content = "つないでください。",
  ui_story_1022_10220100_91_dialog_content = "了解です！",
  ui_story_1022_10220100_92_dialog_content = "…あ、あ。応答願う。聞こえるか？",
  ui_story_1022_10220100_93_dialog_content = "大元帥さんですね！よかった、連絡がついて。",
  ui_story_1022_10220100_94_dialog_content = "大元帥様、はっきりと聞こえております。\nどうやら後方とは正常に通信できるようです。",
  ui_story_1022_10220100_95_dialog_content = "「暗面偵察隊」の座標はまだ分からないのか？\n暗面とは実に厄介な所だな。",
  ui_story_1022_10220100_96_dialog_content = "ヒイロ、苦労を掛ける。今回の任務はかなり厳しいものとなりそうだ。",
  ui_story_1022_10220100_97_dialog_content = "とんでもございません。暗面に探索に入った部下の状況が不明なのです。\n探し出し無事に連れ帰るのは当然の責務です。",
  ui_story_1022_10220100_98_dialog_content = "それに合同探索隊が設立されて以来、地上には白夜城の軍が駐屯しています。\n後方の心配もございません。",
  ui_story_1022_10220100_99_dialog_content = "それよりも大元帥様、委員会との話し合いは順調にいきましたか？\nまた難癖をつけてきたのではありませんか？",
  ui_story_1022_10220100_100_dialog_content = "ハハハ、やつらがもし難癖をつけてこなかったら、\nかえって私の方が自身の判断を疑ってしまう。",
  ui_story_1022_10220100_101_dialog_content = "おおかた順調といえるだろう。徐々に分かってきたことだが、\n委員会は自身の尾をかじっているヘビにすぎない。",
  ui_story_1022_10220100_102_dialog_content = "と、言いますと？",
  ui_story_1022_10220100_103_dialog_content = "ベリサリアにしろ、まだ顔を出してない連中にしろ…\nそれにそうだな…ユリシーズもその1人と言えるだろうが――",
  ui_story_1022_10220100_104_dialog_content = "やつらの目的は詰まるところ、\n科学技術で光霊の生存を確保することだ。",
  ui_story_1022_10220100_105_dialog_content = "その点は私も同感です。",
  ui_story_1022_10220100_106_dialog_content = "だが科学技術は残酷だ。委員会はその科学技術に最も近い者どもの集まり。\nしたがって受ける影響も大きい。",
  ui_story_1022_10220100_107_dialog_content = "技術を追求するうち、科学技術のもつ残酷さの化身となってしまった。",
  ui_story_1022_10220100_108_dialog_content = "効率、合理性、実用性…それらを追求するあまり、\nやつらは人間性を失い、初心にさえ背いてしまった。",
  ui_story_1022_10220100_109_dialog_content = "光霊が幸福に暮らせる世界を築かんとする初心にな。",
  ui_story_1022_10220100_110_dialog_content = "（ユリシーズ教授も最初の目的は、\n暗鬼と対抗するために光霊を強化することだった…）",
  ui_story_1022_10220100_111_dialog_content = "…効率のみを追求し、思考の入る隙さえ許さないなど、\nファントムに従う暗鬼たちと同じです。",
  ui_story_1022_10220100_112_dialog_content = "ゆえに若き世代は自分たちの道を探っているのだ。\nインゲルやショーンたちを見るがいい。",
  ui_story_1022_10220100_113_dialog_content = "私もあやつらに負けるわけにはいかない。\n今まで成し得なかったことをやり遂げなければ。",
  ui_story_1022_10220100_114_dialog_content = "大元帥さんがまだやっていないことなんてありましたっけ…",
  ui_story_1022_10220100_115_dialog_content = "ハハハ、まるで私が悪者のようにも聞こえるな！",
  ui_story_1022_10220100_116_dialog_content = "…私は大元帥として、そう多くの事は成し遂げていない。\n戦争に明け暮れ、闇に潜む危険には十分な注意を払ってこなかったのだ。",
  ui_story_1022_10220100_117_dialog_content = "委員会が啓光という大船の舵を恣意に操っているのを知りながら、\n私は前任者と同じく妥協を選んだ。",
  ui_story_1022_10220100_118_dialog_content = "大元帥様は決してそのような…",
  ui_story_1022_10220100_119_dialog_content = "そう逸るな、ヒイロ。\n私はただ自分に新しい責務を課そうとしているだけだ。",
  ui_story_1022_10220100_120_dialog_content = "今はもうこれまでとは違う――\nあの時成そうと思った改革を実行に移す。",
  ui_story_1022_10220100_121_dialog_content = "委員会の存在意義を全否定するつもりはない。\nだが、啓光を間違った方向に導いていくのを許すわけにはいかない。",
  ui_story_1022_10220100_122_dialog_content = "やつらの仮面を引きはがしてやる。\n仮面の下にまだ人の心が残っているか見てやらなければ。",
  ui_story_1022_10220100_123_dialog_content = "まだはっきりしないこともあるが、近いうちに皆にきちんと答えを示せるだろう。\nそれまで待っていてくれ。",
  ui_story_1022_10220100_124_dialog_content = "<color=#e8d9bb>一方、啓光の委員会では――</color>",
  ui_story_1022_10220100_125_dialog_content = "レインハトは一度失脚したものの、今や大元帥の座に返り咲き、\nユリシーズの人体実験も世間に知られ…",
  ui_story_1022_10220100_126_dialog_content = "浮空島用に準備してあった武器装備まで、\n公になってしまったかもしれません",
  ui_story_1022_10220100_127_dialog_content = "あなたが支持したことはすべて、\n自身の頭を貫く弾丸となって返ってきていますよ。",
  ui_story_1022_10220100_128_dialog_content = "ベリサリア博士、どう責任を取るおつもりですか？",
  ui_story_1022_10220100_129_dialog_content = "いずれも適切に対応しなければ、委員会の威信を地に落とすことになるぞ！！",
  ui_story_1022_10220100_130_dialog_content = "ここまで来て、遠回しな表現はよしましょう。",
  ui_story_1022_10220100_131_dialog_content = "責任を取って辞任し、この座を譲れと言えばいいでしょう？",
  ui_story_1022_10220100_132_dialog_content = "…不服なのか？",
  ui_story_1022_10220100_133_dialog_content = "不服どうこうの問題じゃないわ。\n今の状況でそれが必要かどうかという話よ。",
  ui_story_1022_10220100_134_dialog_content = "必要な時がくれば、いつでも辞任してあげる。\n責任と非難の罵声をすべて背負って、委員会から去ってあげるわ。",
  ui_story_1022_10220100_135_dialog_content = "私の存在意義はそこにあるのでしょう？",
  ui_story_1022_10220100_136_dialog_content = "…ふん。",
  ui_story_1022_10220100_137_dialog_content = "ただよく考えることね。\nレインハトがどんな人物か、彼女の実力と求心力がどれほど大きなものか――",
  ui_story_1022_10220100_138_dialog_content = "そして、その大元帥様の指揮に従う軍隊が今、\n委員会にどんな態度を取っているのかを。",
  ui_story_1022_10220100_139_dialog_content = "…",
  ui_story_1022_10220100_140_dialog_content = "今の啓光があるのは、当時の啓光が権威主義の下で分権制度を採ったからよ。",
  ui_story_1022_10220100_141_dialog_content = "委員会と軍隊は互いにけん制し合い、長年の競り合いと摩擦を経て、\n今日の輝かしい啓光を築いた。",
  ui_story_1022_10220100_142_dialog_content = "ただ衝突が起これば、向こうの「大元帥」が有能であればあるほど、\n局面を収めるのは難しくなる。",
  ui_story_1022_10220100_143_dialog_content = "当時軍隊との交渉役に担ぎ上げられたのはこの私。\n今回軍隊との衝突を理由に委員会を追われるのもこの私。",
  ui_story_1022_10220100_144_dialog_content = "でも――その後は？",
  ui_story_1022_10220100_145_dialog_content = "後始末は誰が引き継ぐのかしら？\n誰にその力があるのかしら？",
  ui_story_1022_10220100_146_dialog_content = "<color=#e8d9bb>会議室が一瞬にして静まり返った</color>",
  ui_story_1022_10220100_147_dialog_content = "後始末を終える前に、もう一度よく考えることね。",
  ui_story_1022_10220100_148_dialog_content = "「武力」が「理性」の制御を失ったら、この先どうなるのでしょう？",
  ui_story_1022_10220100_149_dialog_content = "だがもし再び介入すれば、本当に「戦争」が起こるのではないか。",
  ui_story_1022_10220100_150_dialog_content = "委員会はそもそも軍を牽制するためにあるのですよ。\n争いを恐れて役目に背くのですか？",
  ui_story_1022_10220100_151_dialog_content = "だが無意味な内紛は、我々の目的にとっても何の助けにもならないだろう？",
  ui_story_1022_10220100_152_dialog_content = "啓光の舵取りを一時<color=#FFB400>やつ</color>に任せること自体は受け入れられなくもない。\nだが<color=#FFB400>やつ</color>には、まだ不確定要素が残っている。",
  ui_story_1022_10220100_153_dialog_content = "これ以上の言い争いはやめましょう。\n今は一致団結して困難を乗り越える時です。",
  ui_story_1022_10220100_154_dialog_content = "一致団結だと？そんなもの、今の「啓光」にとっては不快以外の何物でもない。\nフンッ、どうせやつらのことだ。「往生際の悪い委員会め」とでも思っているのだろう。",
  ui_story_1022_10220100_155_dialog_content = "皆さん、結論は出たかしら？",
  ui_story_1022_10220100_156_dialog_content = "<color=#FFB400>我々</color>の出番ですね。",
  ui_story_1022_10220100_157_dialog_content = "…！",
  ui_story_1022_10220100_158_dialog_content = "「啓光」は分裂によって生まれはしましたが、\n分裂によって滅びることは許されません。",
  ui_story_1022_10220100_159_dialog_content = "誰が実権を握るかは重要ではありません。\n同じ轍を踏まないことこそが重要なのです。",
  ui_story_1022_10220100_160_dialog_content = "反逆は二度とあってはなりません。",
  ui_story_1022_10220201_1_dialog_content = "<color=#e8d9bb>暗面の奥深く、某所</color>",
  ui_story_1022_10220201_2_dialog_content = "隊長、どうしましょう。やはり信号が送れません。",
  ui_story_1022_10220201_3_dialog_content = "本隊とはもう連絡を取ることはできないんでしょうか…？",
  ui_story_1022_10220201_4_dialog_content = "願ったりかなったりだね。これで自由に行動できるじゃん。",
  ui_story_1022_10220201_5_dialog_content = "連絡取れる方が面倒だって。\n手綱を引かれてるも同然だし、不快で仕方ないよ。",
  ui_story_1022_10220201_6_dialog_content = "隊長、そんなこと言ってはいけません…",
  ui_story_1022_10220201_7_dialog_content = "誰が聞いてるって言うの？あの氷に耳でも付いてんの？\nそれともあっちの石？",
  ui_story_1022_10220201_8_dialog_content = "…コホン！",
  ui_story_1022_10220201_9_dialog_content = "隊長！今何かおかしな…せき込む声が聞こえたような…",
  ui_story_1022_10220201_10_option_content = "何にもおかしくないよ",
  ui_story_1022_10220201_11_dialog_content = "そうそう、普通の咳じゃん。",
  ui_story_1022_10220201_12_option_content = "「ような」なんて言わずに自信もって",
  ui_story_1022_10220201_13_dialog_content = "そうそう、わざと注意を引くために咳したんだよ。",
  ui_story_1022_10220201_14_dialog_content = "そこにいるのは誰？まさか「本隊」じゃないよね？",
  ui_story_1022_10220201_15_dialog_content = "実に冷静ですね、「暗面偵察隊」隊長ペピータ。",
  ui_story_1022_10220201_16_dialog_content = "その冷静さに免じて、先刻の発言は聞かなかったことにしましょう。\nただし今回のみです。",
  ui_story_1022_10220201_17_dialog_content = "だ、第三軍団長！",
  ui_story_1022_10220201_18_dialog_content = "ここは真っ暗にゃ～。静かだし、お昼寝にピッタリなのにゃ～。",
  ui_story_1022_10220201_19_dialog_content = "じょ…情報長官まで！",
  ui_story_1022_10220201_20_dialog_content = "…い、今…お茶をご用意いたします！",
  ui_story_1022_10220201_21_dialog_content = "は？どこにお茶があるっていうの？\n長官さんたちのせいで隊員が幻覚を見ちゃったじゃない。",
  ui_story_1022_10220201_22_dialog_content = "…",
  ui_story_1022_10220201_23_dialog_content = "そっちの咳のお兄さんは誰？なんで後ろで縮こまってるの？\n地位が一番低いとか？",
  ui_story_1022_10220201_24_dialog_content = "僕は啓光の軍人じゃないんだ。空の末裔だよ…",
  ui_story_1022_10220201_25_dialog_content = "だったら余計におかしいじゃん。\nそこの長官さんたちの部下じゃないのに、なんで金魚のフンやってるの？",
  ui_story_1022_10220201_26_dialog_content = "そういうことじゃなくて、ごく自然な流れで一緒に行動を…",
  ui_story_1022_10220201_27_dialog_content = "自然な流れで金魚のフンになったんだ。",
  ui_story_1022_10220201_28_dialog_content = "ちょっと！",
  ui_story_1022_10220201_29_dialog_content = "…おしゃべりはここまでとしましょう。ようやくのことで合流できたのです。\nまずは情報交換です。",
  ui_story_1022_10220201_30_dialog_content = "ああ…あの巨大な光力の塊の方へ向かってたら、\n途中で偶然私らを見つけたってこと？",
  ui_story_1022_10220201_31_dialog_content = "ちょっと偶然すぎない？からかってるんじゃないよね？",
  ui_story_1022_10220201_32_dialog_content = "なぜ、そのようなことをする必要が？",
  ui_story_1022_10220201_33_dialog_content = "知らないわよ。あんた本人でしょ？\n本当のことを言いたくないのか、悪さするのが趣味なのか知らないけど…",
  ui_story_1022_10220201_34_dialog_content = "悪さ？いったい何を言っているのです…",
  ui_story_1022_10220201_35_dialog_content = "今は真面目な話をしてるんだよ！",
  ui_story_1022_10220201_36_dialog_content = "PlayerName？",
  ui_story_1022_10220201_37_dialog_content = "僕もヒイロさんも大切な仲間を探しに暗面に来たんだ。",
  ui_story_1022_10220201_38_dialog_content = "光力の塊に向かって行けば、会えるんじゃないかと思ってきたけど、\nぜんぜん見つからなくて…",
  ui_story_1022_10220201_39_dialog_content = "そんな僕らに悪さなんてしてる余裕あると思う？",
  ui_story_1022_10220201_40_dialog_content = "仲間…",
  ui_story_1022_10220201_41_dialog_content = "「見つけたのが私で残念だったね」なんて言ったら、本当に怒るからね！",
  ui_story_1022_10220201_42_dialog_content = "…",
  ui_story_1022_10220201_43_dialog_content = "…",
  ui_story_1022_10220201_44_dialog_content = "ハハハハハハ！",
  ui_story_1022_10220201_45_dialog_content = "な、何がおかしいの…？",
  ui_story_1022_10220201_46_dialog_content = "アハハ、まだ本気で怒ってなかったんだ。\n本気で怒ったらどんなか、見てみたくなっちゃった。",
  ui_story_1022_10220201_47_dialog_content = "君って人は――",
  ui_story_1022_10220201_48_dialog_content = "でも見られそうにないね。だって私、そんなこと言わないし。",
  ui_story_1022_10220201_49_dialog_content = "私が誤解してた。冗談が過ぎちゃったみたいだね、ごめん。",
  ui_story_1022_10220201_50_dialog_content = "誤解…？",
  ui_story_1022_10220201_51_dialog_content = "だってあんたたち啓光でしょ？\nどうせ上の命令で何も考えず暗面に入ってきたおバカさんだろうと思ったんだ。",
  ui_story_1022_10220201_52_dialog_content = "でも実際は…「大切な仲間」のためだったんだね？\nアハハ！",
  ui_story_1022_10220201_53_dialog_content = "特にあんた、第三軍団長の前で大声出すなんて、\nいい度胸してるじゃん。",
  ui_story_1022_10220201_54_dialog_content = "あんたみたいなの好き。",
  ui_story_1022_10220201_55_dialog_content = "！？",
  ui_story_1022_10220201_56_dialog_content = "な、なななな、何を言ってるの…？",
  ui_story_1022_10220201_57_dialog_content = "私は冗談もガチっぽく言うけど、今のは本気と書いてガチと読むやつ。",
  ui_story_1022_10220201_58_dialog_content = "自分を持ってる人が好きなんだ。",
  ui_story_1022_10220201_59_dialog_content = "そんなの、誰でも持ってるでしょ…",
  ui_story_1022_10220201_60_dialog_content = "そこまでです。また話が反れていますよ。",
  ui_story_1022_10220201_61_dialog_content = "ペピータ、話をする気になったのなら、\n次はそちらの偵察状況を報告してください。",
  ui_story_1022_10220201_62_dialog_content = "暗面に入って、しばらく経ちますね？\n何か分かりましたか？",
  ui_story_1022_10220201_63_dialog_content = "「偵察状況」ねぇ…はぁ。暗面の偵察なんてホント無茶させてくれるよね。\nここじゃ何をするにも大変なのに。",
  ui_story_1022_10220201_64_dialog_content = "拠点だってそう。この壁紙なんてあちこちに落ちてた指名手配書で作ったんだよ。",
  ui_story_1022_10220201_65_dialog_content = "<color=#FFB400>それも「私の」ね</color>。",
  ui_story_1022_10220201_66_dialog_content = "君の指名手配書？まさか、「そういう」こと…じゃないよね。あはは…",
  ui_story_1022_10220201_67_dialog_content = "うーん…にゃにゃにゃ？…おかしいにゃあ。\nフィリス、夢でこの子を見たにゃ…",
  ui_story_1022_10220201_68_dialog_content = "すっごく見覚えがあるのにゃ。",
  ui_story_1022_10220201_69_dialog_content = "さっすが情報長官！",
  ui_story_1022_10220201_70_dialog_content = "<color=#e8d9bb>ドォォン！</color>",
  ui_story_1022_10220201_71_dialog_content = "PlayerName、伏せて！",
  ui_story_1022_10220201_72_dialog_content = "<color=#e8d9bb>氷の洞窟は轟音に揺さぶられ、無数の氷が落ちてきた</color>",
  ui_story_1022_10220201_73_dialog_content = "<color=#e8d9bb>混乱の中、ペピータの豪快な笑い声が響く</color>",
  ui_story_1022_10220201_74_dialog_content = "仲間を探しに行くといいよ。邪魔しないから。\nだからそっちも邪魔しないでね！",
  ui_story_1022_10220201_75_dialog_content = "にゃにゃっ？それにしても、どうして見覚えがあるのにゃ？",
  ui_story_1022_10220201_76_dialog_content = "ど、どういうこと？洞窟が急に崩れるなんて…\nそれにペピータはどこに行っちゃったの？",
  ui_story_1022_10220201_77_dialog_content = "…逃げたのでしょうね。",
  ui_story_1022_10220201_78_dialog_content = "逃げた？どうしてですか？",
  ui_story_1022_10220201_79_dialog_content = "にゃっ！思い出したにゃん！\nあの子は逃亡犯だにゃ！",
  ui_story_1022_10220201_80_dialog_content = "逃亡犯？ですが、ペピータは啓光が派遣したのですよ？\n啓光の兵士も連れています。",
  ui_story_1022_10220201_81_dialog_content = "捕まってたのにゃ。啓光の監獄に入れられてたにゃん。",
  ui_story_1022_10220201_82_dialog_content = "つまり、啓光は彼女の弱みを握り、それを使って言う事を聞かせているということですか？\nなぜそこまでして彼女を使うのです？",
  ui_story_1022_10220201_83_dialog_content = "フィリス、ペピータが捕まった理由は何だったか知っていますか？",
  ui_story_1022_10220201_84_dialog_content = "フィリスには、わからにゃいの…",
  ui_story_1022_10220201_85_dialog_content = "あの子の調査と逮捕の責任者はナミシスにゃんだけど、\n委員会と直接やりとりしてたって話だにゃ。",
  ui_story_1022_10220201_86_dialog_content = "大きな後ろ盾があるようですね。",
  ui_story_1022_10220201_87_dialog_content = "あの…ちょっといいですか？",
  ui_story_1022_10220201_88_dialog_content = "ペピータが逃亡犯で、隙を狙って逃げたっていうのは分かるんですけど、\nどうして今なんでしょうか？",
  ui_story_1022_10220201_89_dialog_content = "僕たちと合流する前から、ペピータは隊を率いて単独で偵察に当たってたわけで、\n逃げようと思ったらいつでもできましたよね？",
  ui_story_1022_10220201_90_dialog_content = "それをどうしてわざわざヒイロさんのいる時に…\nどう考えても自分から成功率を下げてますよね？",
  ui_story_1022_10220201_91_dialog_content = "確かに…",
  ui_story_1022_10220201_92_dialog_content = "今の轟音は…？いったい何が起こったのですか？\n隊長が暗鬼用の罠を爆発させたんでしょうか？暗鬼はどこです？",
  ui_story_1022_10220201_93_dialog_content = "えっと…隊長は…？",
  ui_story_1022_10220201_94_dialog_content = "にゃにゃっ！？暗鬼用の罠？",
  ui_story_1022_10220201_95_dialog_content = "は、はい…暗面に進入してからというもの、隊員たちの感覚が鈍っていて…\nそれで隊長は拠点を築くたびに様々な暗鬼用の罠を仕掛けているんです。",
  ui_story_1022_10220201_96_dialog_content = "特に「あの場所」を見つけてからは、\n隊長はことさら警戒を厳しくしているんです。",
  ui_story_1022_10220201_97_dialog_content = "あんな感じですが、隊長は私たちのことを\nすごく気に掛けてくれているんです。ハハハ…",
  ui_story_1022_10220201_98_dialog_content = "…",
  ui_story_1022_10220201_99_dialog_content = "じゃあ、今になって逃げたのはつまり…",
  ui_story_1022_10220201_100_dialog_content = "隊員を私たちに託すためだったのでしょうか？\nペピータ…何とも解せない子ですね…",
  ui_story_1022_10220201_101_dialog_content = "<color=#e8d9bb>暗面、白夜城軍駐屯地</color>",
  ui_story_1022_10220201_102_dialog_content = "ペピータ――それが今回のターゲットの名だ。",
  ui_story_1022_10220201_103_dialog_content = "このターゲットは非常に狡猾で、逃げるためなら何でもする。\n慎重に行動するように。",
  ui_story_1022_10220201_104_dialog_content = "同じ轍を踏んではならない。",
  ui_story_1022_10220201_105_dialog_content = "はい！",
  ui_story_1022_10220201_106_dialog_content = "この間は…あたしがうっかり惑わされたせいで…",
  ui_story_1022_10220201_107_dialog_content = "エリカ、自分を責めることはない。",
  ui_story_1022_10220201_108_dialog_content = "啓光の委員会はあの者と長年やり合っている。\n先を越されても仕方がない。",
  ui_story_1022_10220201_109_dialog_content = "だが今回は我々に利がある！",
  ui_story_1022_10220201_110_dialog_content = "その話、私にも詳しく聞かせてもらえるかしら？",
  ui_story_1022_10220201_111_dialog_content = "で、殿下…！",
  ui_story_1022_10220202_1_dialog_content = "お待たせしました――ご注文の「深淵からの視線」です。",
  ui_story_1022_10220202_2_dialog_content = "幻想的な色彩に罪深い香り、曲がりくねった紋様…\nそうか、これこそ邪神の呪いがかかった飲み物なんだね？",
  ui_story_1022_10220202_3_dialog_content = "う～んっ…この甘味、あたしの胃袋と心を鷲づかみだよー！\n邪神、恐るべし…",
  ui_story_1022_10220202_4_dialog_content = "地獄に引き込まれるおいしさだよー！\nもう1杯…もう1杯だけ…！",
  ui_story_1022_10220202_5_dialog_content = "アハハハ！たった1杯飲んだだけで、そんなズラズラ感想が出てくんの？\nあんた面白いねぇ。",
  ui_story_1022_10220202_6_dialog_content = "だ、誰…？どこの人ならざる者がささやいてんの？",
  ui_story_1022_10220202_7_dialog_content = "人ならざる者じゃなくて私。\nさっきから隣に座ってる客だって。",
  ui_story_1022_10220202_8_dialog_content = "あんたもコレ好きなの？趣味が似てるみたいだから、\nいくつかオススメ教えてあげてもいいよ。",
  ui_story_1022_10220202_9_dialog_content = "オススメ…うーん、たまには流されるのもいいかなー。",
  ui_story_1022_10220202_10_dialog_content = "ただし、ノンアルコール限定でー。",
  ui_story_1022_10220202_11_dialog_content = "はあ？",
  ui_story_1022_10220202_12_dialog_content = "<size=30>…シラフでソレ？あんた、大丈夫？</size>",
  ui_story_1022_10220202_13_dialog_content = "ここのメニューに詳しいんだね…\nしょっちゅう罪悪感を味わいに来てんのー？",
  ui_story_1022_10220202_14_dialog_content = "罪悪感だけじゃないよ。\n歓喜やスリル、熱狂、まやかし…全部私の人生のメニューに載ってるの。",
  ui_story_1022_10220202_15_dialog_content = "この世をメニューに見立てて俯瞰してる？\nあんたにも未知なる存在に抗う力が隠されてるかもしれないね…",
  ui_story_1022_10220202_16_dialog_content = "さあ、罪に落ちる儀式をしよー！乾杯ー！",
  ui_story_1022_10220202_17_dialog_content = "乾杯！",
  ui_story_1022_10220202_18_dialog_content = "うーっ…これも胸躍るおいしさだよ。\nあんたのオススメ、どれもおいしすぎるー。",
  ui_story_1022_10220202_19_dialog_content = "ハハ、当然だよ。",
  ui_story_1022_10220202_20_dialog_content = "それにしても、なんでノンアルコールにこだわるの？\n見たところ、聖人を気取るタイプでもなさそうだけど。",
  ui_story_1022_10220202_21_dialog_content = "実は…任務中なんだー。だから、自制しないと…",
  ui_story_1022_10220202_22_dialog_content = "へえ、さぞかし立派な仕事なんだろうね。",
  ui_story_1022_10220202_23_dialog_content = "白夜城の異端調査団…確かに立派な仕事だよね。\nこの世界にとって、すごく重要な仕事…",
  ui_story_1022_10220202_24_dialog_content = "異端調査団が影ノ街に！？",
  ui_story_1022_10220202_25_dialog_content = "影ノ街は悪魔に支配された土地なんだ。混乱と無秩序に覆われてる。\nだから「ターゲット」もここに逃げ込んだんだよ。",
  ui_story_1022_10220202_26_dialog_content = "ターゲットは白夜城の聖典を盗んで影ノ街に潜んでるんだけど、\nその足取りは謎で…",
  ui_story_1022_10220202_27_dialog_content = "（私のこと……だね）",
  ui_story_1022_10220202_28_dialog_content = "必ずとっ捕まえて聖典を取り戻さなきゃ…あれ？\n心の友、どこ行くのー？",
  ui_story_1022_10220202_29_dialog_content = "冷たいモノ飲み過ぎちゃったみたい…ちょっとお手洗いに行ってくる。",
  ui_story_1022_10220202_30_dialog_content = "…クソッ！絶好の機会だったのにまんまと逃げられるとは！",
  ui_story_1022_10220202_31_dialog_content = "心の友が凶悪逃亡犯のペピータ…？そんなはずは…",
  ui_story_1022_10220202_32_dialog_content = "急いで追うのだ！まだ間に合う！",
  ui_story_1022_10220202_33_dialog_content = "啓光にさえ先を越されなければ…",
  ui_story_1022_10220202_34_dialog_content = "（…ここまで来れば、大丈夫だよね）",
  ui_story_1022_10220202_35_dialog_content = "（木が隠れるのに最も適した場所は森。\n光霊が隠れるのに最も適した場所は――）",
  ui_story_1022_10220202_36_dialog_content = "（お葬式！）",
  ui_story_1022_10220202_37_dialog_content = "（もう穴を掘り始めてるし、あとは埋められるだけ。\nまさか棺桶の中の「死者」が私だとは思わないよね。フフフ…）",
  ui_story_1022_10220202_38_dialog_content = "いつまでそうしているつもりですか？\n自分で出てきなさい。",
  ui_story_1022_10220202_39_dialog_content = "やはりここに隠れていましたか。あなたらしいと言うべきか…",
  ui_story_1022_10220202_40_dialog_content = "よく死体と一緒に寝ていられますね？",
  ui_story_1022_10220202_41_dialog_content = "！！！",
  ui_story_1022_10220202_42_dialog_content = "（どこでしくじったの…？あ、服！）",
  ui_story_1022_10220202_43_dialog_content = "（やらかした…どこの死人が棺桶に納められる時にこんなボロを着てるっていうの…）",
  ui_story_1022_10220202_44_dialog_content = "（これからは…服に気を付けよう！）",
  ui_story_1022_10220202_45_dialog_content = "そのペピータという者が白夜城の聖典を盗んだと言うの？",
  ui_story_1022_10220202_46_dialog_content = "さようでございます、殿下。ただその者が盗んだのは本物ではないため、\n窃盗事件自体はさして重要ではございません。",
  ui_story_1022_10220202_47_dialog_content = "問題は、ペピータがそのニセの聖典を持って真理結社――\nあのアストラで最も忌々しい異端組織に身を投じたことなのです。",
  ui_story_1022_10220202_48_dialog_content = "…盗まれたのがニセモノだというなら、\n本物の聖典はいったいどこへ？",
  ui_story_1022_10220202_49_dialog_content = "それなのです…本物の聖典は何年も前に遺失しているのですが、\n様々な手がかりの示すところによれば――",
  ui_story_1022_10220202_50_dialog_content = "真理結社の手に落ちたようなのです。",
  ui_story_1022_10220202_51_dialog_content = "なるほど、分かったわ。真理結社の本拠地を知る者はおらず、\n結社のメンバーも皆一つ所に留まらない。",
  ui_story_1022_10220202_52_dialog_content = "そこにペピータが現れ、ニセの聖典を盗み、エリカとも交流があった――\n身を潜めるどころか、存在をひけらかすかのような振る舞いをしている。",
  ui_story_1022_10220202_53_dialog_content = "あなたたちはそんな彼女を切り口に真理結社を探り、\n本物の聖典を取り戻すつもりなのね。",
  ui_story_1022_10220202_54_dialog_content = "さすが殿下、ご明察でございます。\n我々の当初の計画はさようなものでございました。",
  ui_story_1022_10220202_55_dialog_content = "しかし、あの忌々しい啓光の委員会が遣わした「執行人」に先を越され、\nペピータを啓光に連れ戻されてしまい…",
  ui_story_1022_10220202_56_dialog_content = "そうすると、今回ペピータが暗面に現れたのは啓光の指示によるものということになるわね。\nだとしたら、そう簡単に手は出せないわ。",
  ui_story_1022_10220202_57_dialog_content = "殿下、どうぞご安心ください。",
  ui_story_1022_10220202_58_dialog_content = "異端調査隊の今回の行動は、城主様および啓光大元帥の許可を得ております。",
  ui_story_1022_10220202_59_dialog_content = "城主様は啓光大元帥レインハトと覚書を交わされ、我々がペピータを追跡し、\n職務を遂行することを許可なさいました。",
  ui_story_1022_10220202_60_dialog_content = "今度こそ逃げられません。",
  ui_story_1022_10220202_61_dialog_content = "…そういうことなら、私たちもひとまず啓光の暗面偵察隊と行動を共にしましょう。",
  ui_story_1022_10220202_62_dialog_content = "少し前にペピータと遭遇したそうよ。",
  ui_story_1022_10220301_1_dialog_content = "カレン！こっちだよ、早かったね！",
  ui_story_1022_10220301_2_dialog_content = "白夜城の聖典に関することだもの。\n手抜かりは許されないわ。",
  ui_story_1022_10220301_3_dialog_content = "あなたこそ大丈夫？凶悪逃亡犯と遭遇して、何か危険なことはなかった？",
  ui_story_1022_10220301_4_dialog_content = "コホン…確かに見事にからかわれちゃったけど…",
  ui_story_1022_10220301_5_dialog_content = "安心して！ずっと感知しながら来たんだ。\nペピータは絶対にこの近くにいるよ。",
  ui_story_1022_10220301_6_dialog_content = "…",
  ui_story_1022_10220301_7_dialog_content = "フィリスはペピータの率いてた隊員を連れて一度飛行機に戻ることにしたから、\n僕とヒイロさんが一緒に行動するよ。",
  ui_story_1022_10220301_8_dialog_content = "ペピータは啓光から暗面の偵察に派遣された者です。\n私には彼女およびその偵察成果を持ち帰る義務があります。",
  ui_story_1022_10220301_9_dialog_content = "それは無理だろうな。",
  ui_story_1022_10220301_10_dialog_content = "あなたは？",
  ui_story_1022_10220301_11_dialog_content = "白夜城異端調査隊の隊長よ。今の状況を説明すると――",
  ui_story_1022_10220301_12_dialog_content = "…大元帥様が白夜城の追跡行動を許可されたのですね？",
  ui_story_1022_10220301_13_dialog_content = "分かりました。身柄はそちらにお渡しします。\nただし、その前にいくつか彼女に質問をさせてください。",
  ui_story_1022_10220301_14_dialog_content = "「あの場所」を見つけた時、隊長は最初とても興奮した様子だったんですが、\n我々の安全を考慮してか、すぐにそこを離れたんです。",
  ui_story_1022_10220301_15_dialog_content = "なんだか隊長はあの奇怪な光景を初めてみるわけではなさそうでした…",
  ui_story_1022_10220301_16_dialog_content = "ペピータは何か知っていますね。",
  ui_story_1022_10220301_17_dialog_content = "フン。啓光の者は相変わらず横暴だな。\n一度だけでは飽き足らず、何度でも先を越そうとするのだからな。",
  ui_story_1022_10220301_18_dialog_content = "身柄はお渡しすると言ったはずですが――",
  ui_story_1022_10220301_19_dialog_content = "私のことをステーキか何かだとでも思ってるの？\n渡す渡さないって、本人の意思は無視？",
  ui_story_1022_10220301_20_dialog_content = "ペピータ！",
  ui_story_1022_10220301_21_dialog_content = "自分から出て来たか！？",
  ui_story_1022_10220301_22_dialog_content = "心の友！…いや、ちがう…もう惑わされない…",
  ui_story_1022_10220301_23_dialog_content = "誰が誰を惑わしたって？一緒に楽しくおしゃべりしたのは夢だったとでも？\nあれは現実で、実際楽しかったワケでしょ？",
  ui_story_1022_10220301_24_dialog_content = "自分の気持ちに正直になって、現実を見なよ、エリカ！",
  ui_story_1022_10220301_25_dialog_content = "あたしに見えているのは…虚構の中の真実…",
  ui_story_1022_10220301_26_dialog_content = "エリカをこれ以上たぶらかすな！",
  ui_story_1022_10220301_27_dialog_content = "（すばやい！）",
  ui_story_1022_10220301_28_dialog_content = "逃がさないわ！",
  ui_story_1022_10220301_29_dialog_content = "散華――寂滅！",
  ui_story_1022_10220301_30_dialog_content = "<color=#e8d9bb>怒涛の攻撃を蝶のようにかわし続けるペピータ。\n余裕綽々と言わんばかりに、時おり反撃もしている</color>",
  ui_story_1022_10220301_31_dialog_content = "<color=#e8d9bb>多勢に無勢どころか、むしろ優勢にさえ見える</color>",
  ui_story_1022_10220301_32_dialog_content = "まさか暗面の影響を受けていないの！？",
  ui_story_1022_10220301_33_dialog_content = "やっぱりフツーじゃないね…",
  ui_story_1022_10220301_34_dialog_content = "（普通の光霊なら、暗面では力が抑えられるはずなのに、\nペピータはまったく何ともなさそうだ…）",
  ui_story_1022_10220301_35_dialog_content = "アハハハ、どう？ペピータ様のすごさを思い知った？",
  ui_story_1022_10220301_36_dialog_content = "さぁ～てチュートリアルはこれで終い。\n次はラスボスペピータ様の猛攻開始だよ！",
  ui_story_1022_10220301_37_dialog_content = "ペディちゃん、ペディちゃん――大きくなぁれ！",
  ui_story_1022_10220301_38_dialog_content = "うっ…このエネルギーは…！？",
  ui_story_1022_10220301_39_dialog_content = "どうなっているのだ？突然息が苦しく…",
  ui_story_1022_10220301_40_dialog_content = "暗力が…濃くなった…",
  ui_story_1022_10220301_41_dialog_content = "（間違いない…ペピータの持ってるぬいぐるみから暗鬼の気配を感じる…\nいったいどうなってるんだろう？）",
  ui_story_1022_10220301_42_dialog_content = "大きくなぁれ！ほら、もっともっと大きくなぁれっ！",
  ui_story_1022_10220301_43_dialog_content = "<color=#e8d9bb>ペピータの高らかな笑い声と共にぬいぐるみはどんどん膨らみ、\nそのどっしりした体躯から次々に攻撃が繰り出された！</color>",
  ui_story_1022_10220301_44_dialog_content = "<color=#e8d9bb>そしてまるでその影にも実体があるかのように、\n黒く大きな闇が辺りの光霊の心と体に重くのしかかる…</color>",
  ui_story_1022_10220301_45_dialog_content = "これ以上はもう…持たないわ…！",
  ui_story_1022_10220301_46_dialog_content = "なんと奇妙な人形なのでしょう！",
  ui_story_1022_10220301_47_dialog_content = "ペディちゃんは私の<color=#FFB400>魔獣</color>なの。\n魔獣っていうからには、もちろん魔性を持ってるに決まってるじゃん。",
  ui_story_1022_10220301_48_dialog_content = "さぁ、じっくり味わって。魔獣ちゃんと遊べる時間はもう――",
  ui_story_1022_10220301_49_dialog_content = "「多くない」よ。",
  ui_story_1022_10220301_50_dialog_content = "…！",
  ui_story_1022_10220301_51_dialog_content = "あ、あれは…何？",
  ui_story_1022_10220301_52_dialog_content = "PlayerName、急にキョロキョロしてどうしたの？",
  ui_story_1022_10220301_53_dialog_content = "<color=#e8d9bb>「彼女」のご到着だ</color>",
  ui_story_1022_10220301_54_dialog_content = "何かが近づいてくる…ものすごい暗力だ…避けてっ！",
  ui_story_1022_10220301_55_dialog_content = "<color=#e8d9bb>素早く身をかわした一行の目に映ったのは、空から落ちて来る一滴の乳白色の涙</color>",
  ui_story_1022_10220301_56_dialog_content = "<color=#e8d9bb>涙はそのまま地面に落ち――</color>",
  ui_story_1022_10220301_57_dialog_content = "<color=#e8d9bb>膨大なエネルギーとともに、爆発した</color>",
  ui_story_1022_10220301_58_dialog_content = "私の友だちをいじめるとは何事です？",
  ui_story_1022_10220301_59_dialog_content = "<color=#FFB400>ウルスラ</color>、やっぱり来てくれたんだね。",
  ui_story_1022_10220301_60_dialog_content = "<color=#e8d9bb>砂ぼこりがおさまり、爆発の中心部に現れた姿にその場にいた全員が息をのんだ</color>",
  ui_story_1022_10220301_61_dialog_content = "この「波長」は…<color=#FFB400>ファントム</color>！",
  ui_story_1022_10220301_62_dialog_content = "ペピータ、貴様！異端結社に身を投じただけでは飽き足らず、\n暗鬼と結託していたのか！？",
  ui_story_1022_10220301_63_dialog_content = "濃霧に包まれているみたいで、姿形をハッキリつかめないよ…",
  ui_story_1022_10220301_64_dialog_content = "結託とは、なんという言いがかりでしょう！ペピータと私は古い友だちなのですよ。\nあなた方よりも前から知り合いなのです。そちらこそ結託ではありませんか？",
  ui_story_1022_10220301_65_dialog_content = "！？",
  ui_story_1022_10220301_66_dialog_content = "ハハハ、みんな面白い顔しちゃって！\n危険を冒して姿を現わした甲斐があったなぁ！",
  ui_story_1022_10220301_67_dialog_content = "…ファントムが来るって、分かってたの？",
  ui_story_1022_10220301_68_dialog_content = "ホントおバカさんだね。ウルスラが近くにいなかったら、\n自分から出て来たりしないよ。私そこまでバカじゃないし。",
  ui_story_1022_10220301_69_dialog_content = "二度も「もてあそばれた」気分はどう？空の末裔くん？",
  ui_story_1022_10220301_70_dialog_content = "君って人は…！",
  ui_story_1022_10220301_71_dialog_content = "ペピータ、私のあげたペディはどこですか？あの子の気配を感じたからこそ、\nわざわざ出てきたのですよ。私、いい友だちでしょう？",
  ui_story_1022_10220301_72_dialog_content = "いるよ、ほら…でも、なんで？返せって言うつもり？\nせっかく仲良くなったのに。",
  ui_story_1022_10220301_73_dialog_content = "（聞き間違いじゃないよね？今の会話、本当に「友だち」みたいだ…）",
  ui_story_1022_10220301_74_dialog_content = "ペピータ、ファントムが来れば、万事解決と思ったら大間違いよ。",
  ui_story_1022_10220301_75_dialog_content = "白夜城の聖典を盗んだ罪は許されない！",
  ui_story_1022_10220301_76_dialog_content = "盗んだ？あれはもともと真理結社のモノでしょ。",
  ui_story_1022_10220301_77_dialog_content = "何ですって！？",
  ui_story_1022_10220301_78_dialog_content = "だから、白夜城に追われる理由なんてない。",
  ui_story_1022_10220301_79_dialog_content = "啓光なんて尚のことだよ。\nこっちこそ責任を追及したいトコなんだけど。",
  ui_story_1022_10220301_80_dialog_content = "あ、でも誤解しないで。もちろん追及させてもらうから。\nうやむやにして済し崩しなんて絶対させない！",
  ui_story_1022_10220301_81_dialog_content = "…",
  ui_story_1022_10220301_82_dialog_content = "ベリサリアのおばさんは「心臓」で脅せば、\nこき使えると思ってるみたいだけど、あり得ないから。",
  ui_story_1022_10220301_83_dialog_content = "ペピータ様はこれ以上付き合う気はないよ。ハハハハ！",
  ui_story_1022_10220301_84_dialog_content = "ウルスラ、行こう。",
  ui_story_1022_10220301_85_dialog_content = "夜通し遊ぶとしますか。",
  ui_story_1022_10220301_86_dialog_content = "ペピータ…",
  ui_story_1022_10220301_87_dialog_content = "待て！",
  ui_story_1022_10220301_88_dialog_content = "まったく…うるさいですねっ！",
  ui_story_1022_10220301_89_dialog_content = "グゥアアアア――！",
  ui_story_1022_10220301_90_dialog_content = "気をつけて！",
  ui_story_1022_10220302_1_dialog_content = "（魔獣ちゃん、お行き。ビクトリア様に私の居場所を伝えて）",
  ui_story_1022_10220302_2_dialog_content = "ペピータ、何をもたもたしているのですか？\n早く行きましょう、あなたが誘ったのですよ？",
  ui_story_1022_10220302_3_dialog_content = "はいは～い、今行くって！",
  ui_story_1022_10220302_4_dialog_content = "フフフ、あの光霊の様子を見ましたか？\nやられるがまま反撃もせず、ただ怒り猛るだけの無能な者ばかり。",
  ui_story_1022_10220302_5_dialog_content = "いやいや、私がやった時の方が傑作だったよ。\n警戒が緩んでるのを狙って一気にワナを爆発させたの。",
  ui_story_1022_10220302_6_dialog_content = "それはそれはステキな光景だったよ～！",
  ui_story_1022_10220302_7_dialog_content = "そんな楽しいことになぜ私を呼ばないのです？\nズルいですよ！",
  ui_story_1022_10220302_8_dialog_content = "埋め合わせしてください！\nもっと素敵なことを思い切り楽しませてください！うわああああん！",
  ui_story_1022_10220302_9_dialog_content = "泣かないでよ。2人一緒なら、ステキなことなんていくらでもやれるじゃん？",
  ui_story_1022_10220302_10_dialog_content = "『ご報告いたします。ここから離れた所に動く「モノ」を発見しました。\n何やら逃げているようです』",
  ui_story_1022_10220302_11_dialog_content = "『あれは…ウルスラ様があの光霊に贈られた魔獣ではないか！』",
  ui_story_1022_10220302_12_dialog_content = "『あの光霊はいったい何をするつもりだ？やはり光霊は狡猾でいかん』",
  ui_story_1022_10220302_13_dialog_content = "『いかがいたしましょう？放っておきますか？』",
  ui_story_1022_10220302_14_dialog_content = "『マヌケめ！さっさと捕まえて、その魔獣をウルスラ様にお届けするのだ！』",
  ui_story_1022_10220302_15_dialog_content = "『はっ。』",
  ui_story_1022_10220302_16_dialog_content = "クソッ！！",
  ui_story_1022_10220302_17_dialog_content = "またもや逃げられるとは…ようやく追い詰めたというのに！",
  ui_story_1022_10220302_18_dialog_content = "ペピータがファントムを呼び寄せるなんて誰も思いもしませんでした。\nそう悔しがらないでください。",
  ui_story_1022_10220302_19_dialog_content = "ただ疑問は解けました。",
  ui_story_1022_10220302_20_dialog_content = "先程のファントムにはサンゴのようなものが生えていました…",
  ui_story_1022_10220302_21_dialog_content = "おそらくペピータは「あの場所」を見つけた時、ファントムが近くにいると気付いたはず。\nそれで隙を狙い、ファントムの所に身を寄せようと決めたのでしょう。",
  ui_story_1022_10220302_22_dialog_content = "なんでファントムなんかに…ファントムがなにをしてくれんの？",
  ui_story_1022_10220302_23_dialog_content = "つまり奴は完全に堕落したということだ！\nエリカ、これ以上奴に惑わされてはならん！",
  ui_story_1022_10220302_24_dialog_content = "…",
  ui_story_1022_10220302_25_dialog_content = "誰もおかしいとは思わないの？",
  ui_story_1022_10220302_26_dialog_content = "カレン、それはどういう意味？",
  ui_story_1022_10220302_27_dialog_content = "あのファントム――ウルスラは相当な実力の持ち主よ。\nけれど私たちにはあまり興味を示さなかった。",
  ui_story_1022_10220302_28_dialog_content = "ウルスラの攻撃は2回とも、ペピータを守るためだった…",
  ui_story_1022_10220302_29_option_content = "彼女の強さは友情の力ってこと！？",
  ui_story_1022_10220302_30_dialog_content = "…冗談のつもりかしら？",
  ui_story_1022_10220302_31_dialog_content = "ご、ごめん！",
  ui_story_1022_10220302_32_option_content = "2人は本当に友だちみたいだった",
  ui_story_1022_10220302_33_dialog_content = "ペピータはウルスラが来てくれるって信じてたから、\n堂々と姿を現わしたんだよね…",
  ui_story_1022_10220302_34_dialog_content = "光霊とファントムの間に、友情などあり得るのかしら？",
  ui_story_1022_10220302_35_dialog_content = "確かにウルスラの行動は理解に苦しみます。",
  ui_story_1022_10220302_36_dialog_content = "私たちに敵意はなく、かといってペピータは救った…\nなぜでしょうか？2人はいったい何をしたいのでしょう？",
  ui_story_1022_10220302_37_dialog_content = "ただ遊びたいだけなのかも。",
  ui_story_1022_10220302_38_dialog_content = "…",
  ui_story_1022_10220302_39_dialog_content = "冗談もいい加減にしろ！",
  ui_story_1022_10220302_40_dialog_content = "エリカ、光力石を持て。出発する。",
  ui_story_1022_10220302_41_dialog_content = "え！？ペピータを追うんですか？",
  ui_story_1022_10220302_42_dialog_content = "当然だ。ファントムごときに邪魔をされてたまるか。",
  ui_story_1022_10220302_43_dialog_content = "ペピータが白夜城の聖典に関する情報を持っている限り、\n私たちにそれ以外の選択肢はないの。",
  ui_story_1022_10220302_44_dialog_content = "…細かいことは捕らえてから聞きましょう。",
  ui_story_1022_10220302_45_dialog_content = "（カレンが聞きたいのは「白夜城の聖典が真理結社のものだ」って部分だよね…）",
  ui_story_1022_10220302_46_dialog_content = "（カレンの話では、ペピータは真理結社のメンバーのはずだけど…）",
  ui_story_1022_10220302_47_dialog_content = "（どうして啓光に捕まったんだろう？\nペピータが追及するって言ってた責任って何だろう？）",
  ui_story_1022_10220302_48_dialog_content = "（どんどん謎が増えていく…）",
  ui_story_1022_10220401_1_dialog_content = "ようこそ！氷原のサンゴの森へ！",
  ui_story_1022_10220401_2_dialog_content = "きれいでしょう？異様でしょう？目から鱗が落ちたのでは？\nフフフ、思う存分驚嘆の叫びをあげていいのですよ！",
  ui_story_1022_10220401_3_dialog_content = "う～ん、いいねぇ。美しく歪んでて、あんたにピッタリ！",
  ui_story_1022_10220401_4_dialog_content = "ちっとも感動していないではないですか。\nつまらないですね！",
  ui_story_1022_10220401_5_dialog_content = "ホントだよ。\nこんな不思議な光景、びっくりしたって。",
  ui_story_1022_10220401_6_dialog_content = "（ま、ちょっと前に見つけた時のコトだけど）",
  ui_story_1022_10220401_7_dialog_content = "分かってくれればいいのです。\nさぁ、面白いものはまだまだたくさんありますよ。",
  ui_story_1022_10220401_8_dialog_content = "あれ～、そんなに期待させちゃっていいの？\nガッカリさせないでよ？",
  ui_story_1022_10220401_9_dialog_content = "<color=#e8d9bb>本来なら殺風景なはずの氷原に、なぜかコケやサンゴ、美しい木々が茂り、\nまるでおとぎ話に出てくる暗黒の森のような光景が広がっている</color>",
  ui_story_1022_10220401_10_dialog_content = "<color=#e8d9bb>そのサンゴの森の中にいるのは――</color>",
  ui_story_1022_10220401_11_dialog_content = "！？",
  ui_story_1022_10220401_12_dialog_content = "（あれは…光霊？でも目に光がないし、暗鬼みたいだけど…\n見た目は暗鬼には似ても似つかない…）",
  ui_story_1022_10220401_13_dialog_content = "<color=#e8d9bb>光霊に似た生き物がサンゴの森の中で動いていた。\n呆然とした表情を浮かべ、機械的な動作で茂り過ぎたコケやサンゴの処理をしている</color>",
  ui_story_1022_10220401_14_dialog_content = "<color=#e8d9bb>美しい植物たちと対照的なその動きに、見る者は思わず鳥肌を立てるだろう</color>",
  ui_story_1022_10220401_15_dialog_content = "ウルスラ、あっちのは…？",
  ui_story_1022_10220401_16_dialog_content = "分かりませんか？サンゴですよ。",
  ui_story_1022_10220401_17_dialog_content = "そっちじゃなくて、サンゴを片付けてるヤツよ。あれは…\n光霊？暗鬼？それとも謎の生物？",
  ui_story_1022_10220401_18_dialog_content = "あ…あんなものに興味を持ってどうするのです？\nつまらないですね。",
  ui_story_1022_10220401_19_dialog_content = "光霊ではありませんよ。\n光霊の面白い所を少しも受け継いでいませんし。",
  ui_story_1022_10220401_20_dialog_content = "（「受け継いでない」ってことは…関係あるってこと？）",
  ui_story_1022_10220401_21_dialog_content = "ここに長くいて、丈夫になっただけが取り柄の者たちです。\n<color=#FFB400>私たち</color>の雑用係ですよ。",
  ui_story_1022_10220401_22_dialog_content = "何でも言う事を聞いて働く以外、役に立ちません。",
  ui_story_1022_10220401_23_dialog_content = "話も通じず、簡単に死んでしまうので、遊び相手にもなりませんしね。\n光霊の足下にも及びませんよ。",
  ui_story_1022_10220401_24_dialog_content = "（話すこともできず、ろくに戦えもしない…そういうことだよね？）",
  ui_story_1022_10220401_25_dialog_content = "彼らのことはどうでもいいでしょう。\nここの主は私ですよ、私について来てください！",
  ui_story_1022_10220401_26_dialog_content = "…",
  ui_story_1022_10220402_1_dialog_content = "ふぅ…今日の実験、やっと終わったね。",
  ui_story_1022_10220402_2_dialog_content = "最近、試験がどんどんきつくなってると思わない？",
  ui_story_1022_10220402_3_dialog_content = "うん…正直言うと、ちょっともう、ダメかも…",
  ui_story_1022_10220402_4_dialog_content = "体中痛いし、夜も悪い夢ばっかり見るし…",
  ui_story_1022_10220402_5_dialog_content = "同じだよ…",
  ui_story_1022_10220402_6_dialog_content = "やっぱりペピータはスゴイな。\n心臓が悪くて、試験も一番きついのに音を上げないんだから。",
  ui_story_1022_10220402_7_dialog_content = "これくらい、なんてことないよ～。",
  ui_story_1022_10220402_8_dialog_content = "お父さんが立ち向かってる危険に比べれば、\n私のやってることなんて寝てるだけだもん。",
  ui_story_1022_10220402_9_dialog_content = "確かペピータのパパって…暗面の探索に行ってるんだよね？",
  ui_story_1022_10220402_10_dialog_content = "そうだよ！お父さんは啓光の暗面探索隊の隊員なの。\nスッゴくリッパなおしごとなんだよ！",
  ui_story_1022_10220402_11_dialog_content = "私も大きくなったら暗面の探険に行くんだ。\nお父さんもきっと喜んでくれる。ヘヘヘ。",
  ui_story_1022_10220402_12_dialog_content = "スゴイなぁ、ペピータは。\nがんばってね、応援してるから！",
  ui_story_1022_10220402_13_dialog_content = "でも、そうすると次の面会日はパパ来ないんだね？",
  ui_story_1022_10220402_14_dialog_content = "…しかたないよ。おしごとだし…",
  ui_story_1022_10220402_15_dialog_content = "ほしいモノがあるなら、うちのママに持ってきてもらうよ！",
  ui_story_1022_10220402_16_dialog_content = "うん…ありがと。",
  ui_story_1022_10220402_17_dialog_content = "お父さん、きっと…会いに来てくれるよね。",
  ui_story_1022_10220402_18_dialog_content = "<color=#e8d9bb>数年後――</color>",
  ui_story_1022_10220402_19_dialog_content = "あの子の様子はどう？",
  ui_story_1022_10220402_20_dialog_content = "以前と同様、嫌いなものには一切手を付けず、\n好きなものは2人分を要求し――",
  ui_story_1022_10220402_21_dialog_content = "音楽をかけろとうるさく、無視をしていると、\n大声で歌を歌い出します…",
  ui_story_1022_10220402_22_dialog_content = "長いこといるのだし、あの子の好き嫌いぐらい分かっているでしょう？\n嫌いな物は出さないようにしなさい。",
  ui_story_1022_10220402_23_dialog_content = "…はい！",
  ui_story_1022_10220402_24_dialog_content = "甘やかしすぎではありませんか？\n何はどうあれ囚人であることに変わりはないのですよ。",
  ui_story_1022_10220402_25_dialog_content = "あの子の体質は特別なの。「心臓」もあの状態だし、\n栄養不足で倒れられたら、損失を被るのは私たちよ。",
  ui_story_1022_10220402_26_dialog_content = "食べ物を粗末にするのも良くないわ。",
  ui_story_1022_10220402_27_dialog_content = "…協力してくれればいいのですがね。",
  ui_story_1022_10220402_28_dialog_content = "ちょっと、どうなってんの？レコードはいつ持ってくんの？\nいつまで歌を歌わせるつもり？それとも私の歌が好きなの？",
  ui_story_1022_10220402_29_dialog_content = "まったく、もうちょっとファンサービスしてあげちゃおっかな。\nコホン！♪美しき草原～、私の故郷～♪",
  ui_story_1022_10220402_30_dialog_content = "ペピータ、あなた草原なんて見たことないでしょう？",
  ui_story_1022_10220402_31_dialog_content = "なに？またあんた？\nおばさんの顔はもう見飽きたんだけど。あっち行って。",
  ui_story_1022_10220402_32_dialog_content = "ずいぶんと嫌われたものね。\n昔実験室にいた時は、会うと喜んでくれていたのにね。",
  ui_story_1022_10220402_33_dialog_content = "他に誰も会いに来る人なんていなかったから。",
  ui_story_1022_10220402_34_dialog_content = "あんたは私に会いに来てたんじゃない。\n貴重な実験台の様子を見に来てただけでしょ。",
  ui_story_1022_10220402_35_dialog_content = "実験台の価値は確たるものであり、測定可能。",
  ui_story_1022_10220402_36_dialog_content = "でも「感情」は、たとえ「家族の愛情」であっても確たるものではないわ。\n簡単に見せかけることも偽ることもできるのよ。",
  ui_story_1022_10220402_37_dialog_content = "あなたが一番よく分かっているのではなくて？",
  ui_story_1022_10220402_38_dialog_content = "…",
  ui_story_1022_10220402_39_dialog_content = "単なる反抗期ではなく、本当に見せかけや偽りを恨んでいるのなら――",
  ui_story_1022_10220402_40_dialog_content = "私のあなたに対する態度――「実験台」を大切に思う気持ちを\n前向きにとらえるべきね。",
  ui_story_1022_10220402_41_dialog_content = "ユリシーズ、来てちょうだい。",
  ui_story_1022_10220402_42_dialog_content = "…",
  ui_story_1022_10220402_43_dialog_content = "！？その装置は…！",
  ui_story_1022_10220402_44_dialog_content = "（間違いない…あれは昔啓光の研究者が私の欠陥のある心臓を\n人工心臓に換えた時に見た装置…）",
  ui_story_1022_10220402_45_dialog_content = "（置換手術が終わって目を覚ました時、ベッドの横に置いてあった…）",
  ui_story_1022_10220402_46_dialog_content = "（あの中にきっと…私の心臓が入ってる！）",
  ui_story_1022_10220402_47_dialog_content = "この中に何が入っているか分かっているようね。",
  ui_story_1022_10220402_48_dialog_content = "…何がしたいの？",
  ui_story_1022_10220402_49_dialog_content = "簡単なことよ。あなたはその能力を活かして暗面へ行き、\n「ガーディアン1号」のコアを取り戻してきてちょうだい。",
  ui_story_1022_10220402_50_dialog_content = "成功したら、この中にあるものをあげるわ。",
  ui_story_1022_10220402_51_dialog_content = "さらに進化した技術で、その不完全な人工心臓を完全なものにしてあげてもいい。\n選ぶのはあなたよ。",
  ui_story_1022_10220402_52_dialog_content = "あんたの言いなりになると思う！？",
  ui_story_1022_10220402_53_dialog_content = "ペピータ、今言ったばかりでしょう？\n感情的になるのは賢明じゃないわ。",
  ui_story_1022_10220402_54_dialog_content = "自分がいったい何を求めているのか、\nそのためにどんな代償を払うべきかよく考えなさい。",
  ui_story_1022_10220402_55_dialog_content = "…",
  ui_story_1022_10220402_56_dialog_content = "<color=#e8d9bb>暗面、サンゴの森</color>",
  ui_story_1022_10220402_57_dialog_content = "<color=#e8d9bb>ウルスラは声を荒げながら、友人をもてなすため、暗鬼に宴席の用意を促していた</color>",
  ui_story_1022_10220402_58_dialog_content = "<color=#e8d9bb>ペピータははっとした。いつの間にか過去の回想に浸っていたようだ</color>",
  ui_story_1022_10220402_59_dialog_content = "<color=#e8d9bb>そして美しいサンゴの森を眺めながら、\n自分がなぜベリサリアとの取引をせずにここへ来たのか思い出した</color>",
  ui_story_1022_10220402_60_dialog_content = "ウルスラ。",
  ui_story_1022_10220402_61_dialog_content = "何をしているのです？赤サンゴと青サンゴを同じお皿に盛りつけるなんて、\n卑しい者はやはり趣味も卑しいですね！",
  ui_story_1022_10220402_62_dialog_content = "だから高貴な血統は貴重なのです…\nペピータ、今何か言いましたか？",
  ui_story_1022_10220402_63_dialog_content = "知り合ったばかりの頃、「心臓」の話をしたこと覚えてる？",
  ui_story_1022_10220402_64_dialog_content = "ヤツらが私の本物の心臓を奪ったっていう話――",
  ui_story_1022_10220402_65_dialog_content = "ああ、面倒ですね！あの光霊たちが不良品を移植したせいで、\nいつも「心臓」を握りつぶされるような痛みに耐えているのでしょう？",
  ui_story_1022_10220402_66_dialog_content = "あなたに関することなら、きちんと覚えていますよ…\n何をグダグダと昔話する必要があるのです？",
  ui_story_1022_10220402_67_dialog_content = "その時確か「心臓」を作れるって言ってたよね？",
  ui_story_1022_10220402_68_dialog_content = "<color=#e8d9bb>ペピータはウルスラの胸元に視線をやった。\nそこにはサンゴの枝が一定のリズムで波打つように動いていた</color>",
  ui_story_1022_10220402_69_dialog_content = "<color=#e8d9bb>ウルスラの心臓はサンゴで出来ているのだ</color>",
  ui_story_1022_10220402_70_dialog_content = "もちろんです！私には最も純粋で、最も高貴な力があるのです。",
  ui_story_1022_10220402_71_dialog_content = "サンゴで丈夫な力強い心臓を作ることなど、\nこの高貴な私からすれば息をするのと同じくらい簡単なことです。",
  ui_story_1022_10220402_72_dialog_content = "それは…いつから始められる？",
  ui_story_1022_10220402_73_dialog_content = "やっと決心がついたのですね？",
  ui_story_1022_10220402_74_dialog_content = "…フン。ただ一つ条件があります。",
  ui_story_1022_10220501_1_dialog_content = "にゃ～っ！フィリスがいない間に、\nそんなにいろんな事があったにゃ～ん？",
  ui_story_1022_10220501_2_dialog_content = "でも、こっちはいい知らせを持ってきたにゃん。\n貴重な情報が手に入ったのにゃ。",
  ui_story_1022_10220501_3_dialog_content = "ペピータに関すること！？",
  ui_story_1022_10220501_4_dialog_content = "そうにゃん。あの子については、知らないことばっかりだったにゃ。",
  ui_story_1022_10220501_5_dialog_content = "だからインゲルに連絡したにゃん。\nそうしたらインゲルがわざわざ委員会の資料を調べてくれたのにゃ。",
  ui_story_1022_10220501_6_dialog_content = "ペピータにはやはり大きな後ろ盾があるのですね。",
  ui_story_1022_10220501_7_dialog_content = "資料によると、委員会は前にも暗面偵察隊を出したことがあるにゃ…",
  ui_story_1022_10220501_8_dialog_content = "ペピータのパパもその偵察隊の一員だったにゃ。",
  ui_story_1022_10220501_9_dialog_content = "え？暗面偵察隊って世襲制なの？",
  ui_story_1022_10220501_10_dialog_content = "いいえ、そうではありません。\nただペピータとの戦いを思い出してみてください。",
  ui_story_1022_10220501_11_dialog_content = "装備を付けていないにもかかわらず、\n暗力の影響を受けずに動けていました。",
  ui_story_1022_10220501_12_dialog_content = "体質遺伝だとすれば、筋が通ります。",
  ui_story_1022_10220501_13_dialog_content = "…確かにそうですね。ペピータのお父さんも\n暗面で自由に行動できる体質だったのかもしれませんね。",
  ui_story_1022_10220501_14_dialog_content = "だとすれば、その時の偵察隊は大きな成果を上げたんじゃ…",
  ui_story_1022_10220501_15_dialog_content = "当時の偵察隊はほぼ全滅だったにゃ…",
  ui_story_1022_10220501_16_dialog_content = "全滅！？",
  ui_story_1022_10220501_17_dialog_content = "生還者はペピータのパパだけだったにゃん。",
  ui_story_1022_10220501_18_dialog_content = "体質も理由の一つにゃんだけど、\n卑怯な手を使ったかもしれにゃくて…",
  ui_story_1022_10220501_19_dialog_content = "啓光に戻ってすぐに、親権譲渡同意書にサインして、\nペピータを啓光の研究所に引き渡したのにゃ。",
  ui_story_1022_10220501_20_dialog_content = "我が子を捨てたというのですか！？",
  ui_story_1022_10220501_21_dialog_content = "それじゃ実験台にされちゃうでしょ？",
  ui_story_1022_10220501_22_dialog_content = "その通りにゃ…だからインゲルもペピータのパパは罪を犯して、\n保身のために娘を売ったって考えたのにゃ…",
  ui_story_1022_10220501_23_dialog_content = "…信じられません。",
  ui_story_1022_10220501_24_dialog_content = "啓光にそんなひどい事をする人がいるなんて…",
  ui_story_1022_10220501_25_dialog_content = "それからは暗面探索の頻度が大幅に落ちたにゃん。\nでも、ペピータに対する研究はずっと続いてたにゃ。",
  ui_story_1022_10220501_26_dialog_content = "それでペピータに十分な行動力と戦闘力を持たせるために、\n先天的に欠陥のあった心臓を人工心臓に置き換えたのにゃ。",
  ui_story_1022_10220501_27_dialog_content = "え？ペピータの心臓は人工のものなの？",
  ui_story_1022_10220501_28_dialog_content = "つまり、委員会は暗面探索計画をあきらめたのではなく、\nペピータを次期偵察隊として育てようとしていたということですね。",
  ui_story_1022_10220501_29_dialog_content = "たぶんそうにゃ。ただ…",
  ui_story_1022_10220501_30_dialog_content = "人工心臓の技術はまだ確立されてにゃいのにゃ。\nだから、たぶんペピータを実験台にするって目的もあったと思うにゃ…",
  ui_story_1022_10220501_31_dialog_content = "なんてひどいことを…ペピータが可哀想だ。",
  ui_story_1022_10220501_32_dialog_content = "後になってペピータも委員会とパパとの間に取引があったことを察して、\n激しく反発するようになったにゃ…",
  ui_story_1022_10220501_33_dialog_content = "隙を見て啓光を抜け出して、いろんにゃ所に身を寄せて、最終的には…\n真理結社の一員になったみたいだにゃん。",
  ui_story_1022_10220501_34_dialog_content = "なんか…分かった気がする…\n真理結社はペピータの最後の居場所だったんだね…",
  ui_story_1022_10220501_35_dialog_content = "もう1つ、ペピータは逃亡した後、\nこっそり啓光に戻ってるにゃ。",
  ui_story_1022_10220501_36_dialog_content = "大胆不敵ですね。目的は何だったのですか？",
  ui_story_1022_10220501_37_dialog_content = "元の心臓を取り戻すためだったみたいにゃ。",
  ui_story_1022_10220501_38_dialog_content = "もちろん、すぐに見つかって逃げたけどにゃ。",
  ui_story_1022_10220501_39_dialog_content = "啓光と白夜城の両方から追われた末、啓光に連れ戻され、\nすぐに暗面に派遣された…",
  ui_story_1022_10220501_40_dialog_content = "何と言ったらいいのか…波乱万丈そのものだね。",
  ui_story_1022_10220501_41_dialog_content = "（だからあんなふうに権威を敵視して、何にでも反発するような態度だったんだね…）",
  ui_story_1022_10220501_42_dialog_content = "今やペピータはファントムとも結託しています。",
  ui_story_1022_10220501_43_dialog_content = "フィリス、ありがとうございました。\nすぐに大元帥様に報告します。",
  ui_story_1022_10220502_1_dialog_content = "…といった状況です。\nペピータは暗面でも自由自在に動くことができ、その実力も確かです。",
  ui_story_1022_10220502_2_dialog_content = "大元帥様、この後はどうすればよろしいですか？",
  ui_story_1022_10220502_3_dialog_content = "次にまた出くわした場合、\n本当に白夜城が連行するがままにさせてよいのでしょうか？",
  ui_story_1022_10220502_4_dialog_content = "ペピータは白夜城の宝物窃盗事件の手がかりを握っている可能性が高い。",
  ui_story_1022_10220502_5_dialog_content = "啓光は今白夜城と合同探索隊として進退を共にしている。\n向こうの利益を考えないわけにはいかない。",
  ui_story_1022_10220502_6_dialog_content = "ですが――",
  ui_story_1022_10220502_7_dialog_content = "もちろん、際限なく譲歩する気もないがな。",
  ui_story_1022_10220502_8_dialog_content = "インゲルのペピータの経歴に関する報告を聞いた。\nペピータはおそらく暗面探索に突出した才能を持つ人材だろう――",
  ui_story_1022_10220502_9_dialog_content = "ゆえに、すぐに情報を白夜城城主と共有した。",
  ui_story_1022_10220502_10_dialog_content = "！！城主は…どのような反応を？",
  ui_story_1022_10220502_11_dialog_content = "ペピータは暗面で活動させておく方が監獄に押し込んでおくよりもはるかに有益だ。\n多少頭のある者なら分かることだ。",
  ui_story_1022_10220502_12_dialog_content = "ソルラドは暗君ではない。",
  ui_story_1022_10220502_13_dialog_content = "ペピータが我々に協力し、その力を存分に発揮するならば、\nすべての者がその益を受けることになる。",
  ui_story_1022_10220502_14_dialog_content = "長い目で見れば、尚さらだ。",
  ui_story_1022_10220502_15_dialog_content = "その者により多くの情報を集めさせ、これからの暗鬼との戦いで機先を制する――\nそう言いたいのだな？",
  ui_story_1022_10220502_16_dialog_content = "どうやら同じ考えのようだな。",
  ui_story_1022_10220502_17_dialog_content = "フッ…たかが盗人だろう。聖典に関する情報を話すのならば、\n白夜城もそれ以上追及はせぬ。",
  ui_story_1022_10220502_18_dialog_content = "なんと…さすがは大元帥様です！",
  ui_story_1022_10220502_19_dialog_content = "お前たちも安心して任務に励めばいい。",
  ui_story_1022_10220502_20_dialog_content = "厄介なのは白夜城よりも、むしろペピータ本人であろう？ハハハ！",
  ui_story_1022_10220502_21_dialog_content = "そんなことはございません！大元帥様が早々に交渉なさらなければ、\n白夜城はきっとペピータを監獄に送り込んでいました。",
  ui_story_1022_10220502_22_dialog_content = "…特に白夜城異端調査隊の隊長は、\n真理結社のメンバーに異様な執着を見せておりまして。",
  ui_story_1022_10220502_23_dialog_content = "なんですと？ペピータを罰しないですと！？",
  ui_story_1022_10220502_24_dialog_content = "ペピータが真理結社の者であることは、城主様もご存知のはずでございます。",
  ui_story_1022_10220502_25_dialog_content = "城主様は光霊全体の将来にわたる利益を考えておられるのよ。",
  ui_story_1022_10220502_26_dialog_content = "それに聖典調査の権限は奪われていない。",
  ui_story_1022_10220502_27_dialog_content = "それだけですか…みすみすあの者を見逃せというのですか…",
  ui_story_1022_10220502_28_dialog_content = "…あなたがどれほど真理結社を憎んでいるかは分かっているつもりよ。\nだからこそ異端調査団に入り、素晴らしい業績を残してきた。",
  ui_story_1022_10220502_29_dialog_content = "けれど、あなたの仇が本当に真理結社の者なのか、\n長い間結論が出ていないのも事実でしょう？",
  ui_story_1022_10220502_30_dialog_content = "このまま見逃すなど…いけません…ありえません…",
  ui_story_1022_10220502_31_dialog_content = "いい加減に頭を冷やしなさい！",
  ui_story_1022_10220502_32_dialog_content = "今私たちは暗面にいるのよ！感情に任せて動けば、\nあなたのみならず、仲間の命まで危険にさらすの！",
  ui_story_1022_10220502_33_dialog_content = "…申し訳ございません、殿下。私が浅はかでした…",
  ui_story_1022_10220502_34_dialog_content = "少し…頭を冷やしてまいります。",
  ui_story_1022_10220502_35_dialog_content = "…",
  ui_story_1022_10220601_1_dialog_content = "駄目だ…見逃すわけにはいかない…\nたとえ私1人でも、奴には代償を払ってもらう…",
  ui_story_1022_10220601_2_dialog_content = "真理結社など…全員あの世に行けばいいのだ！",
  ui_story_1022_10220601_3_dialog_content = "案の定、愚かな事を考えていたようね。",
  ui_story_1022_10220601_4_dialog_content = "で、殿下…！",
  ui_story_1022_10220601_5_dialog_content = "あら、それは何？",
  ui_story_1022_10220601_6_dialog_content = "これは…白夜城の神殿に保管されていた「白夜の指針」でございます。\n祝福を受けた物と共鳴を起こします。",
  ui_story_1022_10220601_7_dialog_content = "暗面に入ってからというもの、激しく反応しておりまして…",
  ui_story_1022_10220601_8_dialog_content = "近くに白夜城の失われた宝物があるのかも知れません。",
  ui_story_1022_10220601_9_dialog_content = "指針はどの方向を指しているの？\nまさかウルスラの去っていった方向を指しているのかしら？",
  ui_story_1022_10220601_10_dialog_content = "それは…",
  ui_story_1022_10220601_11_dialog_content = "あなたは、自分1人であのファントムとペピータを追い、\n同時に失くなった白夜城の宝物を取り返そうとしているのね？",
  ui_story_1022_10220601_12_dialog_content = "なんと傲慢、かつ仲間を軽視した行動かしら！",
  ui_story_1022_10220601_13_dialog_content = "たった1人でそんなことができるのなら、\nそもそも合同探索部隊など必要ないわ。",
  ui_story_1022_10220601_14_dialog_content = "言うべきかどうか迷ってたけど…\n実は同じ方向に巨大な光力の塊の存在を感知したんだ。",
  ui_story_1022_10220601_15_dialog_content = "！？",
  ui_story_1022_10220601_16_dialog_content = "ファントムは私たちにとっても敵です。\nそれ以上何も言うことはありません。",
  ui_story_1022_10220601_17_dialog_content = "クッ…フン。",
  ui_story_1022_10220601_18_dialog_content = "隊長、あたしもペピータに会いに行きたいです…\n罰するためじゃなく、助けるために。",
  ui_story_1022_10220601_19_dialog_content = "未知なる力から、世界と…友を救うことこそ異端調査の目的だって…\nあたし、そう思うんです。",
  ui_story_1022_10220601_20_dialog_content = "エリカ…お前は思っていたよりもずっと冷静で、大人なのだな。\nそれなのに私は…",
  ui_story_1022_10220601_21_dialog_content = "申し訳ございません、殿下。それから…諸君にも詫びを言う。\n個人的な感情に囚われ、理性を失っていた。",
  ui_story_1022_10220601_22_dialog_content = "ただ真理結社と聞くと…どうにもこうにも――",
  ui_story_1022_10220601_23_dialog_content = "恨みを捨てろといいたいわけじゃありません。\nそんなこと簡単にできないことは皆分かってるはずです。",
  ui_story_1022_10220601_24_dialog_content = "ただ少なくとも命は大切にしないと…\nだからこそ、こうやって探索隊を作ってお互い助け合っているんですよね？",
  ui_story_1022_10220601_25_dialog_content = "私は…",
  ui_story_1022_10220601_26_dialog_content = "一緒に行きましょう。目的地はウルスラのアジトです！",
  ui_story_1022_10220601_27_dialog_content = "<color=#e8d9bb>一行は「白夜の指針」の指し示す方向へと進んでいった。\nしばらく進んでいくと、一面に奇怪に曲がりくねった美しい植物が生えている地へとたどり着いた</color>",
  ui_story_1022_10220601_28_dialog_content = "うわぁ…ここって…",
  ui_story_1022_10220601_29_dialog_content = "魂を奪われる、幻想的な美しい光景だね…\n不吉極まりないよ…",
  ui_story_1022_10220601_30_dialog_content = "どうやら方向は間違っていなかったようですね。\n偵察隊員の話では、ペピータが見つけたのはサンゴの森だったとのことでしたから。",
  ui_story_1022_10220601_31_dialog_content = "この奇怪な植生もウルスラの影響なのかもしれません。",
  ui_story_1022_10220601_32_dialog_content = "…「<color=#FFB400>44未知区域</color>」として登録しておきましょう。",
  ui_story_1022_10220601_33_dialog_content = "PlayerName、こっちへ来てもらえるかしら？\n聞きたいことがあるの。",
  ui_story_1022_10220601_34_dialog_content = "え、何？",
  ui_story_1022_10220601_35_dialog_content = "巨大な光力の塊の存在を感知したと言っていたわね？",
  ui_story_1022_10220601_36_dialog_content = "その塊は白夜城の失くした宝物の一つだという可能性はないかしら？",
  ui_story_1022_10220601_37_dialog_content = "え！？「白夜の指針」が示してる宝物が光力の塊だっていうの？",
  ui_story_1022_10220601_38_dialog_content = "その可能性は、完全には否定できないけど、\nどうも違う気がする…",
  ui_story_1022_10220601_39_dialog_content = "ハッキリした根拠があるわけじゃなくて、ただの直感だけど…\n光力の塊には何だか…暖かい、親しみみたいなものを感じるんだよ。",
  ui_story_1022_10220601_40_dialog_content = "…そう。気にしないで、聞いてみたかっただけだから。\nさあ戻りましょう。",
  ui_story_1022_10220601_41_dialog_content = "カレン…大丈夫？何だか色々と抱え込んじゃってるんじゃ…？",
  ui_story_1022_10220601_42_dialog_content = "カレンは白夜城の代表者だから、きっと色々大変なんだよね…",
  ui_story_1022_10220601_43_dialog_content = "きっと…少し焦っているのね。最近色々あったものだから、\n何か成し遂げなくてはと急いでしまっているの。",
  ui_story_1022_10220601_44_dialog_content = "囚われた獣のように力を発揮できないのがもどかしいの。",
  ui_story_1022_10220601_45_dialog_content = "でも、あなたの言う通り、焦ってはいけないわ。",
  ui_story_1022_10220601_46_option_content = "まだ何も言ってないけど…？",
  ui_story_1022_10220601_47_dialog_content = "でも言うつもりだったのでしょう？",
  ui_story_1022_10220601_48_dialog_content = "あはは…確かにそうだけど。",
  ui_story_1022_10220601_49_option_content = "焦っちゃいけないってこともないと思う",
  ui_story_1022_10220601_50_dialog_content = "焦るのもよく分かる。だって…僕もそうだから。",
  ui_story_1022_10220601_51_dialog_content = "…ありがとう。どんな慰めの言葉よりも慰められたわ。",
  ui_story_1022_10220601_52_dialog_content = "あら？何を騒いでいるのかしら？急いで戻りましょう。",
  ui_story_1022_10220601_53_dialog_content = "不吉な気配がどんどん濃くなってる…\n邪悪な神がかつてここに降臨したんだ…",
  ui_story_1022_10220601_54_dialog_content = "し、死体！？これって…光霊の死体？",
  ui_story_1022_10220601_55_dialog_content = "でも光霊の顔立ちじゃないような…\nかといって暗鬼でもないし、どういうことだろう？",
  ui_story_1022_10220601_56_dialog_content = "…光霊に近い生物だろう。\n肉体に光力の痕跡が残っているからな。",
  ui_story_1022_10220601_57_dialog_content = "ただ光力はほぼ吸い取られてしまっている。",
  ui_story_1022_10220601_58_dialog_content = "いったい誰がそんな残酷なことを！？\nまさかそうやって殺したってことですか…？",
  ui_story_1022_10220601_59_dialog_content = "私も最初はそう思ったのだが、\n調べてみたところ、そうではないらしい。",
  ui_story_1022_10220601_60_dialog_content = "光力を吸い取られたことではなく、\n長期間光力の枯渇した状態で生きていたことが死因だったようだ。",
  ui_story_1022_10220601_61_dialog_content = "そんな…光力の枯渇した状態で光霊は生きられるんですか？",
  ui_story_1022_10220601_62_dialog_content = "死した光霊、吸い取られた光力、失われた白夜城の宝物…",
  ui_story_1022_10220601_63_dialog_content = "…クソッ！汚らわしい暗鬼め！\nいったいどこまで光霊を踏みにじれば気が済むのだ！？",
  ui_story_1022_10220601_64_dialog_content = "あなたたち光霊が「日蝕」の物を奪ったという可能性はありませんか？",
  ui_story_1022_10220601_65_dialog_content = "あなたたちが心地よく暮らしている土地さえも、もしかしたら…",
  ui_story_1022_10220601_66_dialog_content = "！！",
  ui_story_1022_10220601_67_dialog_content = "どうしたの？",
  ui_story_1022_10220601_68_dialog_content = "…いや、何でもないよ。",
  ui_story_1022_10220601_69_dialog_content = "（今かすかに声が聞こえた…錯覚…？）",
  ui_story_1022_10220701_1_dialog_content = "同時に大量に亡くなったようですね。",
  ui_story_1022_10220701_2_dialog_content = "サンゴの森の中には、おかしな金属の破片があちこちに落ちています…\nここでいったい何があったのでしょう？",
  ui_story_1022_10220701_3_dialog_content = "僕なら…分かるかもしれません。",
  ui_story_1022_10220701_4_dialog_content = "…ええ、あなたに頼るしかなさそうですね。",
  ui_story_1022_10220701_5_dialog_content = "ただし、十分に気を付けるのですよ。\n決して無理をしてはいけません。",
  ui_story_1022_10220701_6_option_content = "感知",
  ui_story_1022_10220701_7_dialog_content = "！？こ、これは…どういうこと…？",
  ui_story_1022_10220701_8_dialog_content = "<color=#e8d9bb>耳元にうなるような機械音が響く</color>",
  ui_story_1022_10220701_9_dialog_content = "<color=#e8d9bb>大地も機械の震動で微かに揺れている</color>",
  ui_story_1022_10220701_10_dialog_content = "<color=#e8d9bb>無数の奇妙な機械が天に向かってそびえたつ中に、\nゆがむように曲がりくねった美しいサンゴと植物が生えている</color>",
  ui_story_1022_10220701_11_dialog_content = "<color=#e8d9bb>それはサンゴの氷原よりもはるかにおぞましい光景だった</color>",
  ui_story_1022_10220701_12_dialog_content = "（ヒイロさんの見つけた金属の破片はこの無数の機械の残骸だったのかな…）",
  ui_story_1022_10220701_13_dialog_content = "（ここは…サンゴの森の<color=#FFB400>過去</color>？）",
  ui_story_1022_10220701_14_dialog_content = "（あっ！機械を管理してるのって…あの光霊に似た生き物だ。\nここで暮らしてたってこと？）",
  ui_story_1022_10220701_15_dialog_content = "<color=#e8d9bb>生き物の存在を意識した時、この場所の異様な静けさに気づいた</color>",
  ui_story_1022_10220701_16_dialog_content = "<color=#e8d9bb>機械のうなるような稼働音を除けば、ほぼ無音状態だ</color>",
  ui_story_1022_10220701_17_dialog_content = "（あの生き物…言葉をまったく交わしてない。無表情で動きも固いし、\n決まったことをただこなしてる感じだ）",
  ui_story_1022_10220701_18_dialog_content = "（その点はちょっと…低級暗鬼に似てるけど…\n見た目は明らかに光霊だよね？）",
  ui_story_1022_10220701_19_dialog_content = "ああ…こんなに長い時間が経ったっていうのに、\n言葉を話せるのは相変わらずこの数人だけか。",
  ui_story_1022_10220701_20_dialog_content = "（うわぁっ！ビ、ビックリした…言葉を話せるのもやっぱりいたんだね）",
  ui_story_1022_10220701_21_dialog_content = "生まれた時から、ここはそうだったろう？\n機械と思考も感情もない、言葉を話さない同類しかいない…",
  ui_story_1022_10220701_22_dialog_content = "もうどれが同類で、どれが機械だか分からなくなってきたよ。",
  ui_story_1022_10220701_23_dialog_content = "ああ、どうしてこんな暮らしを続けなきゃいけないんだ？",
  ui_story_1022_10220701_24_dialog_content = "この生気のない重苦しい場所を離れて、\n別の所へ行くことはできないのか？",
  ui_story_1022_10220701_25_dialog_content = "絶対にダメだ！",
  ui_story_1022_10220701_26_dialog_content = "若い頃、同じように言葉を話す同類が数人、協力して逃げようとしたけど…",
  ui_story_1022_10220701_27_dialog_content = "おお！？それで、その後どうなった？外の世界はどんなだった？",
  ui_story_1022_10220701_28_dialog_content = "死んだ…",
  ui_story_1022_10220701_29_dialog_content = "！？",
  ui_story_1022_10220701_30_dialog_content = "外の世界には熔炉みたいに暑い場所があって、\n逃げた同類たちは一瞬で焼けて灰になってしまったらしい。",
  ui_story_1022_10220701_31_dialog_content = "それ以来、二度とここを離れようとする者はいなかった。\n偶然外に出た者がいても、誰一人として帰って来なかった。",
  ui_story_1022_10220701_32_dialog_content = "そんな…わずかな希望さえないのか？\nここに縛りつけられたまま死んでくしかないのか？",
  ui_story_1022_10220701_33_dialog_content = "そんな…なんて残酷な…",
  ui_story_1022_10220701_34_dialog_content = "！？",
  ui_story_1022_10220701_35_dialog_content = "（わっ！急に全員こっちを見た！）",
  ui_story_1022_10220701_36_dialog_content = "あ、あはは…こんにちは…？",
  ui_story_1022_10220701_37_dialog_content = "よそ者か？うらやましいな、外の世界を見られるなんて。",
  ui_story_1022_10220701_38_dialog_content = "なんだってこんな場所に来たんだ？\nここには機械とサンゴ以外、何もありやしない。",
  ui_story_1022_10220701_39_dialog_content = "そうそう、サンゴは絶対に食べるなよ。\n食べると血の色が気味の悪い乳白色になってしまう。",
  ui_story_1022_10220701_40_dialog_content = "俺たちみたいに。",
  ui_story_1022_10220701_41_dialog_content = "<color=#e8d9bb>光霊に似た生物の顔に自虐的な笑顔が浮かんだ</color>",
  ui_story_1022_10220701_42_dialog_content = "サンゴを食べると、血が乳白色になっちゃうの…？\nそう…分かった。教えてくれてありがとう。",
  ui_story_1022_10220701_43_dialog_content = "ここにはサンゴ以外の食べ物はないの？",
  ui_story_1022_10220701_44_dialog_content = "ない。どこを探してもサンゴしかない…全部サンゴだ。\n忌々しいサンゴばかり…！",
  ui_story_1022_10220701_45_dialog_content = "ここはまるで呪いのかかった大地だ。\n毎日数えきれないコケとサンゴが生えてくるんだから。",
  ui_story_1022_10220701_46_dialog_content = "でもそのコケやサンゴをすぐに処理しないと、\n機械が正常に稼働しない。",
  ui_story_1022_10220701_47_dialog_content = "特にあの「かま」を絶対に停めるわけにはいかない。",
  ui_story_1022_10220701_48_dialog_content = "一生あの「かま」と雑草に縛られて生きていくしかない。\n尊厳などありやない…きっと呪われてるんだ…",
  ui_story_1022_10220701_49_dialog_content = "…僕以外に誰かここへ来たことはある？たとえば…暗鬼とか？",
  ui_story_1022_10220701_50_dialog_content = "ファントムが1人、時々来るよな？",
  ui_story_1022_10220701_51_dialog_content = "ああ、「ウドゥ」って名だ。",
  ui_story_1022_10220701_52_dialog_content = "ファントム！？",
  ui_story_1022_10220701_53_dialog_content = "ヤツに殺される。",
  ui_story_1022_10220701_54_dialog_content = "ヤツに殺される。",
  ui_story_1022_10220701_55_dialog_content = "ヤツに殺される。",
  ui_story_1022_10220701_56_dialog_content = "！？",
  ui_story_1022_10220701_57_dialog_content = "ある日ウドゥは、もう価値がないと判断して、俺たちを皆殺しにした。",
  ui_story_1022_10220701_58_dialog_content = "俺たちは死んで、一生ここに縛られている。",
  ui_story_1022_10220701_59_dialog_content = "一生ここに縛られている。",
  ui_story_1022_10220701_60_dialog_content = "一生ここに縛られている。",
  ui_story_1022_10220701_61_dialog_content = "…！！！",
  ui_story_1022_10220701_62_dialog_content = "PlayerName！どうしたのですか？顔色が真っ青です。",
  ui_story_1022_10220701_63_dialog_content = "死体に残ってた…生前の思いを感知したんです。",
  ui_story_1022_10220701_64_dialog_content = "…",
  ui_story_1022_10220701_65_dialog_content = "魂がまだここに残ってるってこと…？\n…やすらぎを得られますように。",
  ui_story_1022_10220701_66_dialog_content = "その「ウドゥ」という名のファントムが全員を殺したというの！？何ということを…！",
  ui_story_1022_10220701_67_dialog_content = "それに比べたら、ウルスラなんてまだ優しい方なのかも。",
  ui_story_1022_10220701_68_dialog_content = "そのような考えは危険ですよ。ファントムの本質は皆同じです。\nたやすく警戒心を解いてはなりません。",
  ui_story_1022_10220701_69_dialog_content = "ご、ごめんなさい！",
  ui_story_1022_10220701_70_dialog_content = "怒っているわけではありません。\n警戒を怠ってはならないと言いたかっただけです。",
  ui_story_1022_10220701_71_dialog_content = "感知で見たことから判断するに、\nこの場所はある種の科学技術基地だったようですが――",
  ui_story_1022_10220701_72_dialog_content = "そこで働いていたのが光霊に似た謎の生き物であり、\n彼らの監督役がファントムのウドゥということになりますね。",
  ui_story_1022_10220701_73_dialog_content = "はい…そうだと思います。",
  ui_story_1022_10220701_74_dialog_content = "大部分は感情も思考もなくて、言葉も話せなかったんですが、\nごく少数の例外もいました。",
  ui_story_1022_10220701_75_dialog_content = "主な仕事は生えてくるサンゴやコケを除去して、\n機械が正常に稼働するようにすることでした。",
  ui_story_1022_10220701_76_dialog_content = "たくさんある機械の中で一番重要なものが…\n「かま」と呼ばれてるものだったんです。",
  ui_story_1022_10220701_77_dialog_content = "なぜサンゴとコケが生えてきていたのかしら？\nウルスラと何か関係があるのでは？",
  ui_story_1022_10220701_78_dialog_content = "その可能性は否めませんね。\nウルスラのいる所には、必ずサンゴが生えるのかもしれません。",
  ui_story_1022_10220701_79_dialog_content = "ということは、ウルスラは昔から科学技術基地の近くにいたってことですよね？\nそうしたらウドゥとも何か関係があるのかも…",
  ui_story_1022_10220701_80_dialog_content = "だとすれば、ウルスラは確かに危険な存在ですね…",
  ui_story_1022_10220701_81_dialog_content = "だけどウルスラはペピータと友だちだよね。\nだったら、ペピータに手を出すことはないはず…",
  ui_story_1022_10220701_82_dialog_content = "…暗面に入ってすぐ、ペピータはサンゴの森を見つけた。\n幸運というべきか、不運というべきか…",
  ui_story_1022_10220701_83_dialog_content = "一言よろしいでしょうか？",
  ui_story_1022_10220701_84_dialog_content = "どうしたの？",
  ui_story_1022_10220701_85_dialog_content = "ここは暗面とは思えないほど、暗力が非常に希薄です。",
  ui_story_1022_10220701_86_dialog_content = "もしや「白夜の指針」が指し示す宝物は<color=#FFB400>光力石</color>と同様、\n暗力を遮断できるのではないでしょうか？",
  ui_story_1022_10220701_87_dialog_content = "…！憶測は禁物よ。急いで確かめに行きましょう。",
  ui_story_1022_10220701_88_dialog_content = "ウルスラはそう遠くまで行っていないはずです。\n警戒を怠らず進みましょう。",
  ui_story_1022_10220800_1_dialog_content = "<color=#e8d9bb>サンゴの森の奥では、ペピータがゆがみ曲がりくねった美しい景色を眺めながら\n物思いにふけっていた</color>",
  ui_story_1022_10220800_2_dialog_content = "ペピータ、「条件」のことは考えてくれましたか？",
  ui_story_1022_10220800_3_dialog_content = "…おかえり。外の様子はどう？",
  ui_story_1022_10220800_4_dialog_content = "特に何もありませんよ。虫ケラが数匹うろついていたところで、\n高貴なウルスラ様には痛くもかゆくもありません。",
  ui_story_1022_10220800_5_dialog_content = "それよりも、あなたの答えが聞きたいですね。",
  ui_story_1022_10220800_6_dialog_content = "条件を飲むなら、すぐにでもサンゴで心臓を作ってあげます。",
  ui_story_1022_10220800_7_dialog_content = "条件…「永遠にそばにいて、あんたの遊びに付き合う」ってこと？",
  ui_story_1022_10220800_8_dialog_content = "「遊びに付き合う」のではなく、「一緒に遊ぶ」です！\nあなたも私と一緒に遊びたいはず。一緒に遊んでいると楽しいでしょう？",
  ui_story_1022_10220800_9_dialog_content = "うん、楽しいよ。遊びの趣味が合うことなんてめったにないし。",
  ui_story_1022_10220800_10_dialog_content = "そうでしょう？ですから約束してください。\nすぐに心臓を作ってあげます。",
  ui_story_1022_10220800_11_dialog_content = "そうすれば、あなたの血も高貴な白に変わり、\n二度と私を苦しめることなく、永遠にそばにいられるのです。",
  ui_story_1022_10220800_12_dialog_content = "…ウルスラ。",
  ui_story_1022_10220800_13_dialog_content = "条件を飲む気になりましたか！？",
  ui_story_1022_10220800_14_dialog_content = "初めて会った時のことを覚えてる？",
  ui_story_1022_10220800_15_dialog_content = "…なぜ急にあの忌々しい過去をほじくり返すのですか？",
  ui_story_1022_10220800_16_dialog_content = "…",
  ui_story_1022_10220800_17_dialog_content = "（私…どうしちゃったの？ここは…？）",
  ui_story_1022_10220800_18_dialog_content = "グア！！",
  ui_story_1022_10220800_19_dialog_content = "ハハハ…アハハハ！その程度で私を倒せると思ってんの？\nかかってきなよ！",
  ui_story_1022_10220800_20_dialog_content = "グアアッ！",
  ui_story_1022_10220800_21_dialog_content = "うっ！「心臓」がまた痛みだした…クッ。こんな時に…！",
  ui_story_1022_10220800_22_dialog_content = "（こんな心臓でさえなければ…こんなことには…）",
  ui_story_1022_10220800_23_dialog_content = "（そうだ、思い出した。結社のみんなと暗面の探索に来てたんだった。\nつい遊び癖が出て遊んでたら、暗鬼の群れに出くわしちゃったんだ）",
  ui_story_1022_10220800_24_dialog_content = "（「心臓」が弱いせいで、全力で抵抗したけど結局つかまって…）",
  ui_story_1022_10220800_25_dialog_content = "（さすが私って感じかな。こんなふざけた死に方するなんて。ハハ、アハハハ…）",
  ui_story_1022_10220800_26_dialog_content = "…ハハハハハ！",
  ui_story_1022_10220800_27_dialog_content = "まったく…めずらしく光霊が現れ、ようやく長～い長い眠りから目覚めたというのに――",
  ui_story_1022_10220800_28_dialog_content = "急いで見にきてみれば、頭のおかしい者だったとは。",
  ui_story_1022_10220800_29_dialog_content = "誰！？",
  ui_story_1022_10220800_30_dialog_content = "まあ、よしとしましょう。\nあなたの血と心臓は――",
  ui_story_1022_10220800_31_dialog_content = "<color=#FFB400>私がいただきます</color>。",
  ui_story_1022_10220800_32_dialog_content = "<color=#e8d9bb>幼い少女の姿をした暗鬼が笑顔を浮かべると、口元に鋭い牙が見えた</color>",
  ui_story_1022_10220800_33_dialog_content = "<color=#e8d9bb>その無邪気で残酷な笑みは、見る者に悪寒を感じさせる</color>",
  ui_story_1022_10220800_34_dialog_content = "ハハハ…",
  ui_story_1022_10220800_35_dialog_content = "また笑いましたね！何を笑っているのですか？\nあなたはもう終わりなのですよ？このウルスラ様に食べられてしまうのです。",
  ui_story_1022_10220800_36_dialog_content = "あんたみたいな牙をはやした怪物に、\n頭おかしいって毛嫌いされるなんて笑えるじゃん！",
  ui_story_1022_10220800_37_dialog_content = "フン。牙は高貴な血族の証です。どうせあなたには分かりません。",
  ui_story_1022_10220800_38_dialog_content = "血族？名前だけはカッコいいけど、所詮人の生き血を吸うヤツらでしょ？",
  ui_story_1022_10220800_39_dialog_content = "この私を見下すとは何たること！\nならば、その血を一滴残らず、皮だけになるまで吸い尽くしてやります！",
  ui_story_1022_10220800_40_dialog_content = "アハハハハ！これはびっくり、驚きだね！",
  ui_story_1022_10220800_41_dialog_content = "誰からも愛されて、飲み食いにも友だちにも欠かない、このペピータ様が――",
  ui_story_1022_10220800_42_dialog_content = "血を吸い尽くされる！？\nなになに？それってひん曲がった愛情表現？",
  ui_story_1022_10220800_43_dialog_content = "何を言うのです！私の愛する者はおじい様1人だけです！",
  ui_story_1022_10220800_44_dialog_content = "その血を吸い、生涯こき使ってやります。\n二度とそのような目で私を見られないようにしてやります！",
  ui_story_1022_10220800_45_dialog_content = "こき使う…？",
  ui_story_1022_10220800_46_dialog_content = "フン。怖いですか？遠慮することはありませんよ。\n存分に恐れおののき、命乞いでもすればいいのです。",
  ui_story_1022_10220800_47_dialog_content = "うーん…それはダメ。",
  ui_story_1022_10220800_48_dialog_content = "何をするつもりです？いつの間にそれを…よしなさい！",
  ui_story_1022_10220800_49_dialog_content = "殺されてもいいけど、こき使われるのはまっぴら。",
  ui_story_1022_10220800_50_dialog_content = "<color=#FFB400>我に自由を、しからずんば死を！</color>",
  ui_story_1022_10220800_51_dialog_content = "<color=#e8d9bb>ペピータは1本のサンゴの枝を胸に突き刺すと、\n真っ赤な血が噴き出した</color>",
  ui_story_1022_10220800_52_dialog_content = "…！",
  ui_story_1022_10220800_53_dialog_content = "うわぁっ…血、血が…赤い…血が…うわああああああ！",
  ui_story_1022_10220800_54_dialog_content = "グア！！",
  ui_story_1022_10220800_55_dialog_content = "助けてください！",
  ui_story_1022_10220800_56_dialog_content = "当主様、どうかお助けください！お許しを…うわああああ！！",
  ui_story_1022_10220800_57_dialog_content = "血…忌々しい！殺すなら、血を流さないように注意しなさい！",
  ui_story_1022_10220800_58_dialog_content = "『はっ。』",
  ui_story_1022_10220800_59_dialog_content = "うわあああああ！",
  ui_story_1022_10220800_60_dialog_content = "うっ！血を流すなと言ったでしょう！\nあなたたちは私の「新しい友だち」でしょう、言う事を聞きなさい！",
  ui_story_1022_10220800_61_dialog_content = "『はい、ウルスラ様！できる限り、そのように…』",
  ui_story_1022_10220800_62_dialog_content = "口ばかりで何の訳にも立たない奴らですね…",
  ui_story_1022_10220800_63_dialog_content = "けれど我慢しなければ…私の「新たな神」は\n「真理の主」なる者よりも偉大な存在…",
  ui_story_1022_10220800_64_dialog_content = "浄めるのです！ご降臨ください、我が神よ！",
  ui_story_1022_10220800_65_dialog_content = "うう…あまりにも長く眠っていたので、忘れてしまいました…",
  ui_story_1022_10220800_66_dialog_content = "私は「日蝕」のリングを受け入れたのです。\n二度と血を必要とはしない…血など見たくもありません！",
  ui_story_1022_10220800_67_dialog_content = "血の乳を吸い、血の湯につかる楽しい子ども時代はもう終わってしまったのです…\nうっ…うわぁあああん！おじい様、おじい様――！",
  ui_story_1022_10220800_68_dialog_content = "（急にヒス起こして泣き出しちゃった…\n「おじい様」って泣き叫んでる…なんだか可哀想だな）",
  ui_story_1022_10220800_69_dialog_content = "（置いてきぼりにされたのかな。\nそのおじい様っていうのもあの男と同じでクズなんだろうな）",
  ui_story_1022_10220800_70_dialog_content = "ちょっと、あんた大丈夫？ねえったら…\n大丈夫じゃないのは私の方なんだけど。アハハハ…",
  ui_story_1022_10220800_71_dialog_content = "大丈夫に決まっています。\nこの高貴な私が大丈夫でないはずがないでしょう？",
  ui_story_1022_10220800_72_dialog_content = "うぐっ！何するの…",
  ui_story_1022_10220800_73_dialog_content = "その血で私を制しようとしても無駄です。\nち、血を見ることくらい平気です。飲むことだってできるのですから！",
  ui_story_1022_10220800_74_dialog_content = "うわっ！急に傷口をなめるって…あんたちょっと変態なんじゃ…？",
  ui_story_1022_10220800_75_dialog_content = "ううっ、く、苦しい…",
  ui_story_1022_10220800_76_dialog_content = "<color=#e8d9bb>ウルスラの目に乳白色の涙がにじんだ</color>",
  ui_story_1022_10220800_77_dialog_content = "ツラいなら近づかなきゃいいじゃん…",
  ui_story_1022_10220800_78_dialog_content = "うっ…ううう――うわあああああ！",
  ui_story_1022_10220800_79_dialog_content = "<color=#e8d9bb>突然何かの原始的な力に触れたかのように、ウルスラは身体をけいれんさせながら\n叫び声をあげ、その目からは乳白色の涙があふれ出てくる</color>",
  ui_story_1022_10220800_80_dialog_content = "こ、これ…大丈夫じゃないよね！？",
  ui_story_1022_10220800_81_dialog_content = "うわああああ！",
  ui_story_1022_10220800_82_dialog_content = "（あ、自分で自分を制御できなくなってる！？今のうちに逃げないと…\nでも…なんて運が悪いの、失血しすぎた！）",
  ui_story_1022_10220800_83_dialog_content = "ペ…ディちゃん…ペディちゃん…大きくなぁれ…！",
  ui_story_1022_10220800_84_dialog_content = "ぬいぐるみ？わぁっ…",
  ui_story_1022_10220800_85_dialog_content = "<color=#e8d9bb>ウルスラはけいれんする身体でもがきながら、灰色の人形を呼び出し、\n有無を言わせずペピータをどこへやら引きずっていった</color>",
  ui_story_1022_10220800_86_dialog_content = "<color=#e8d9bb>轟音と共に乳白色の涙が地面に落ち、\n元いた場所は爆発による砂ぼこりに包まれた</color>",
  ui_story_1022_10220800_87_dialog_content = "（助けて…くれたの？）",
  ui_story_1022_10220800_88_dialog_content = "（じゃあ…あの子は？どうなったの？爆発に巻き込まれた？\nまずい、目が開かない…我ながらずいぶん深く突き刺しちゃったなぁ…）",
  ui_story_1022_10220800_89_dialog_content = "（ああ、やっぱり…今日が命日になるの？）",
  ui_story_1022_10220800_90_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_1022_10220800_91_dialog_content = "…",
  ui_story_1022_10220800_92_dialog_content = "（「さすがは私」というべきか…まだ生きてるじゃん…）",
  ui_story_1022_10220800_93_dialog_content = "その「心臓」はどういうことですか？",
  ui_story_1022_10220800_94_dialog_content = "ウルスラ…？",
  ui_story_1022_10220800_95_dialog_content = "啓光の技術ですね？あなたの心臓ではありません。",
  ui_story_1022_10220800_96_dialog_content = "…なんで助けてくれたの？",
  ui_story_1022_10220800_97_dialog_content = "フン。「日蝕」に入れば、永遠に逆らうことのない「新しい友だち」ができると思っていたのです。",
  ui_story_1022_10220800_98_dialog_content = "けれど奴らは無能すぎます。ただの虫ケラです。\n高貴な私にはふさわしくありません。",
  ui_story_1022_10220800_99_dialog_content = "…けれど、あなたはなかなかです。",
  ui_story_1022_10220800_100_dialog_content = "<size=30>私のことも気に掛けてくれます</size>。",
  ui_story_1022_10220800_101_dialog_content = "ハハ…",
  ui_story_1022_10220800_102_dialog_content = "また笑いましたね！",
  ui_story_1022_10220800_103_dialog_content = "私のこと気に入ったってこと？",
  ui_story_1022_10220800_104_dialog_content = "いけませんか？あなたにとって栄誉なことです。\n喜びに狂い、踊り出しても構いませんよ。",
  ui_story_1022_10220800_105_dialog_content = "啓光が造った「心臓」がいかに優れたものであろうと、\nそのせいで啓光の支配を受けることになる――",
  ui_story_1022_10220800_106_dialog_content = "私なら新しい心臓を作れますよ。\nその力が私にはあるのです。",
  ui_story_1022_10220800_107_dialog_content = "あの時私がなんて答えたか覚えてる？",
  ui_story_1022_10220800_108_dialog_content = "もちろんです！「必要ない、もう少しもがいてみたい」と言って断りました。",
  ui_story_1022_10220800_109_dialog_content = "けれど、その結果どうなりましたか？\n結局大人しく私のもとへ戻ってきたでしょう？",
  ui_story_1022_10220800_110_dialog_content = "その「心臓」では何もできませんよ。",
  ui_story_1022_10220800_111_dialog_content = "そう。ホントにヒドい「心臓」だよね。",
  ui_story_1022_10220800_112_dialog_content = "<color=#e8d9bb>ずっと自分の心臓を憎んできた。「ちゃんとした心臓さえあったら」って</color>",
  ui_story_1022_10220800_113_dialog_content = "<color=#e8d9bb>強くて、健康なら誰の指図も受けずに済む。\n力の尽き果てるまで戦うこともできる。そんな心臓が欲しい</color>",
  ui_story_1022_10220800_114_dialog_content = "<color=#e8d9bb>だからウルスラが条件を出すってわかってても、ここまで来たんだ</color>",
  ui_story_1022_10220800_115_dialog_content = "<color=#e8d9bb>私を下に見るベリサリアに比べたら、ウルスラは少なくとも対等だけど…</color>",
  ui_story_1022_10220800_116_dialog_content = "<color=#e8d9bb>条件が――</color>",
  ui_story_1022_10220800_117_dialog_content = "<color=#FFB400>「永遠にそばにいる」ことだなんて</color>",
  ui_story_1022_10220800_118_dialog_content = "<color=#e8d9bb>果てしない氷原とゆがんだ美しいサンゴの森も改めて見てみると、\n今までとは違った気分になるなぁ</color>",
  ui_story_1022_10220800_119_dialog_content = "<color=#e8d9bb>これから先、これが私のすべてになるっていうの？</color>",
  ui_story_1022_10220800_120_dialog_content = "<color=#e8d9bb>…そんなのイヤ</color>",
  ui_story_1022_10220800_121_dialog_content = "<color=#e8d9bb>世界は広いのに…</color>",
  ui_story_1022_10220800_122_dialog_content = "<color=#e8d9bb>私は…まだ草原を見てない</color>",
  ui_story_1022_10220800_123_dialog_content = "私の答えは変わってない。",
  ui_story_1022_10220800_124_dialog_content = "必要ないよ、ウルスラ。",
  ui_story_1022_10220800_125_dialog_content = "やっぱり、もう少しもがいてみたい。",
  ui_story_1022_10220901_1_dialog_content = "私をからかったのですね！",
  ui_story_1022_10220901_2_dialog_content = "ごめん。あんたと一緒にいて楽しいっていうのはホントだよ。",
  ui_story_1022_10220901_3_dialog_content = "でも毎日べったりっていうのはナシにしようよ。\n「君子の交わりは淡きこと水のごとし」っていうでしょ？",
  ui_story_1022_10220901_4_dialog_content = "…",
  ui_story_1022_10220901_5_dialog_content = "連れてきなさい。",
  ui_story_1022_10220901_6_dialog_content = "『はっ。』",
  ui_story_1022_10220901_7_dialog_content = "へ？何を連れて来るの？\n私には人質にできるような親しい存在はいないはずだけど？",
  ui_story_1022_10220901_8_dialog_content = "…ペディちゃん！？ウルスラ、あんたとっくに…\nペディちゃんのこと知ってたんだね？",
  ui_story_1022_10220901_9_dialog_content = "ええ、知っていましたよ。今の今までこらえていたのです。\nこれで私がどれほどよい友だちか分かったでしょう？",
  ui_story_1022_10220901_10_dialog_content = "こんなに…よくしてあげているのに…\nなぜ一緒にいてくれないのですか！？",
  ui_story_1022_10220901_11_dialog_content = "…その質問なら、あの時もう答えたはずだよ。",
  ui_story_1022_10220901_12_dialog_content = "<color=#FFB400>我に自由を、しからずんば死を！</color>",
  ui_story_1022_10220901_13_dialog_content = "ガァ…",
  ui_story_1022_10220901_14_dialog_content = "逃がしてはなりません！",
  ui_story_1022_10220901_15_dialog_content = "『ウルスラ様の命令に従います！』",
  ui_story_1022_10220901_16_dialog_content = "グア！！",
  ui_story_1022_10220901_17_dialog_content = "その程度で？",
  ui_story_1022_10220901_18_dialog_content = "ガァ…",
  ui_story_1022_10220901_19_dialog_content = "バカな真似はよしてください。自ら死を選ぶも同然ですよ！",
  ui_story_1022_10220901_20_dialog_content = "だったら逃がしてくれればいいじゃん。",
  ui_story_1022_10220901_21_dialog_content = "グガァ…",
  ui_story_1022_10220901_22_dialog_content = "わぁ…ハハ、アハハ。\nウルスラ、あんたの部下たちって操り人形みたいで見てらんないね。",
  ui_story_1022_10220901_23_dialog_content = "私はこれで失礼するよ、バイバイ！",
  ui_story_1022_10220901_24_dialog_content = "待ちなさい！",
  ui_story_1022_10220901_25_dialog_content = "うっ…",
  ui_story_1022_10220901_26_dialog_content = "「心臓」が痛み出したのでしょう？\nそのガラクタではあなたの気持ちに肉体がついて行けません。",
  ui_story_1022_10220901_27_dialog_content = "いい加減に限界を知ることです！",
  ui_story_1022_10220901_28_dialog_content = "イヤ！",
  ui_story_1022_10220901_29_dialog_content = "うう…！",
  ui_story_1022_10220901_30_dialog_content = "全員、かかりなさい！",
  ui_story_1022_10220901_31_dialog_content = "…ジャマしないで！",
  ui_story_1022_10220901_32_dialog_content = "とうとうおかしくなりましたか？そんな激しい攻撃を繰り出しては、\n命がいくつあっても足りませんよ？",
  ui_story_1022_10220901_33_dialog_content = "このままでは私が本気を出すまでもなく、燃え尽きてしまいます！",
  ui_story_1022_10220901_34_dialog_content = "だとしても…ちゃんと「燃えた」ならそれでいい！",
  ui_story_1022_10220901_35_dialog_content = "血…？私が血を流しているのですか？",
  ui_story_1022_10220901_36_dialog_content = "なんてこと…なんということでしょう！私を傷つけるとは！\n分かりました、そんなにあの世に行きたいのなら手伝ってあげます！",
  ui_story_1022_10220901_37_dialog_content = "うぐっ――！",
  ui_story_1022_10220901_38_dialog_content = "<color=#e8d9bb>ドクンッ、ドクドクドクドクッ――</color>",
  ui_story_1022_10220901_39_dialog_content = "<color=#e8d9bb>鼓動がどんどんと速くなる</color>",
  ui_story_1022_10220901_40_dialog_content = "<color=#e8d9bb>それはもう「鼓動」ではなく、けいれんだった。\nブレーキが利かず脱線する列車のように止まらない</color>",
  ui_story_1022_10220901_41_dialog_content = "<color=#e8d9bb>次々と襲ってくる激痛が理性を引き裂いていく</color>",
  ui_story_1022_10220901_42_dialog_content = "<color=#e8d9bb>何も分からず、何も感じなくなっていく――</color>",
  ui_story_1022_10220901_43_dialog_content = "<color=#e8d9bb>唯一あの思いだけがいつ何時よりもはっきりと沸き起こる</color>",
  ui_story_1022_10220901_44_dialog_content = "ちゃんとこの命を燃やせたなら、死ぬことくらい…なんてことない。",
  ui_story_1022_10220901_45_dialog_content = "私は誰かのペットじゃない。誰にも屈しない…",
  ui_story_1022_10220901_46_dialog_content = "<color=#FFB400>私は…私だ！</color>",
  ui_story_1022_10220902_1_dialog_content = "「白夜の指針」の反応が強くなっているわ。\n宝物は近くにあるはずよ。",
  ui_story_1022_10220902_2_dialog_content = "あの…",
  ui_story_1022_10220902_3_dialog_content = "また反応が激しくなったわ。\nしっかり探すのよ。目標は小さな物かもしれない。",
  ui_story_1022_10220902_4_dialog_content = "苦労して探してた物って、案外目の前にあるかもしれませんよ…",
  ui_story_1022_10220902_5_dialog_content = "エリカ、感想の類なら後にしてちょうだい。\n今は宝物探しに集中しましょう。",
  ui_story_1022_10220902_6_dialog_content = "殿下、感想じゃありません。\n殿下の前方に神聖な光の塊があるんです。もしかして、あれ…",
  ui_story_1022_10220902_7_dialog_content = "え！？",
  ui_story_1022_10220902_8_dialog_content = "ぷっ…",
  ui_story_1022_10220902_9_dialog_content = "何を笑っているの？あなたも気づいていなかったでしょう？",
  ui_story_1022_10220902_10_dialog_content = "コホン。君も僕も指針の反応ばかり見てたからね…それはいいとして…\n本当に白夜城の失くした宝物か急いで確認しようよ。",
  ui_story_1022_10220902_11_dialog_content = "すごく純粋な光力だね…気持ちが穏やかになる。",
  ui_story_1022_10220902_12_dialog_content = "見つかったのですか！？",
  ui_story_1022_10220902_13_dialog_content = "間違いありません。この光が暗力を遮断していたのです。",
  ui_story_1022_10220902_14_dialog_content = "つまり、それが真理結社が遠い昔に失くした聖物ね。",
  ui_story_1022_10220902_15_dialog_content = "え？この声は…",
  ui_story_1022_10220902_16_dialog_content = "今日聖物は持ち主の元へ帰る。万物は皆定められた軌跡へと戻ってゆく。\n主の神秘の導きが今ここに至ったわ。",
  ui_story_1022_10220902_17_dialog_content = "何者だ？白夜城の宝物は渡さん！",
  ui_story_1022_10220902_18_dialog_content = "ビクトリア、横暴も程々にしなさい。\n聖典の件もまだ片付いていないというのに、さらに強奪を働く気なの！？",
  ui_story_1022_10220902_19_dialog_content = "ビクトリア…？ま、まさか、お前があの異端結社の頭か…",
  ui_story_1022_10220902_20_dialog_content = "フフ…真理の追究は、愚昧の地では確かに「異端」と見なされるでしょうね。",
  ui_story_1022_10220902_21_dialog_content = "この聖物はこの地の主がかつてワラーキ村から奪った物よ。\n私は一度も他人の物に触れたことはないの。",
  ui_story_1022_10220902_22_dialog_content = "私がここへたどり着いたのも、真理結社の一員であるペピータの手がかりのおかげよ。",
  ui_story_1022_10220902_23_dialog_content = "その私のどこが横暴だというのかしら、お姫様？",
  ui_story_1022_10220902_24_dialog_content = "…黙れ！！",
  ui_story_1022_10220902_25_dialog_content = "異端結社の邪なる者め！そのようなでたらめで我らが耳を汚すな…",
  ui_story_1022_10220902_26_dialog_content = "あの世へ送ってやる！！",
  ui_story_1022_10220902_27_dialog_content = "はぁ…はぁ…",
  ui_story_1022_10220902_28_dialog_content = "（サンゴ…またサンゴ…まだ森を抜けられないの？）",
  ui_story_1022_10220902_29_dialog_content = "（さっきは一瞬手を抜いてくれたけど、時間が経ってよく考えたら、\n今度こそ本気で腹を立てて追ってくるかもしれない…そうなったら終わりよ…）",
  ui_story_1022_10220902_30_dialog_content = "（あれ？誰の声？）",
  ui_story_1022_10220902_31_dialog_content = "うっ…忌々しい！異端の邪悪な力がこれほどとは…",
  ui_story_1022_10220902_32_dialog_content = "さっきから「邪悪」と何度も繰り返しているけど、\nあなた、主の信徒に何か恨みでもあるのかしら？",
  ui_story_1022_10220902_33_dialog_content = "この足音は…！",
  ui_story_1022_10220902_34_dialog_content = "エリカ…ビクトリア様！なぜここにいらっしゃるんですか？\n使いに出したペディは捕まってしまったはず…",
  ui_story_1022_10220902_35_dialog_content = "主の導きの下では、運命は己の道を見つけることができるのよ。",
  ui_story_1022_10220902_36_dialog_content = "ペピータ、やはりケガをしているのね。誰がそこまであなたを痛めつけたの？\n…あら。どうやら聞く必要はないようね。",
  ui_story_1022_10220902_37_dialog_content = "ペピータ！ここへくるまで流した血はすでに致死量に達していますよ。\nそれでもまだ逃げる気ですか？",
  ui_story_1022_10220902_38_dialog_content = "本当に怒りますよ。今すぐにここを更地にしてあげます！",
  ui_story_1022_10220902_39_dialog_content = "…！",
  ui_story_1022_10220902_40_dialog_content = "ペピータ、私の後ろへいらっしゃい。",
  ui_story_1022_10220902_41_dialog_content = "何者ですか？私の邪魔をするとは！…？あ！\nお、お前は…",
  ui_story_1022_10220902_42_dialog_content = "邪魔などしていないわ。\n私はここに立ったまま、少しも動いていないわよ。",
  ui_story_1022_10220902_43_dialog_content = "ペピータは自分の足であなたの元を離れ、ここへ来たの。",
  ui_story_1022_10220902_44_dialog_content = "ペピータをそうさせたのは他でもなく、あなたではなくて？",
  ui_story_1022_10220902_45_dialog_content = "最初から最後まで、邪魔をしているのはあなた自身でしょう。",
  ui_story_1022_10220902_46_dialog_content = "…",
  ui_story_1022_10220902_47_dialog_content = "お前は…違う、ペピータは私のものです。\nお前のものでは…",
  ui_story_1022_10220902_48_dialog_content = "真理とは奥深く神秘的なものよ。\nすぐには理解できなくて当然よ。",
  ui_story_1022_10220902_49_dialog_content = "ただし考えることもせず、愚かさや無知、残忍さを自身の印とするのなら――",
  ui_story_1022_10220902_50_dialog_content = "いつか必ず真理の光が届くことのない極夜に落ちることになるわ。",
  ui_story_1022_10220902_51_dialog_content = "私は…お前など…う、うわあああああ――！！",
  ui_story_1022_10220902_52_dialog_content = "<color=#e8d9bb>ほんの少し前まで恐ろしい勢いで迫っていたファントムが突然口をへの字にしたかと思うと逃げ出した。\n遠くから泣きながら「おじい様」と叫ぶ声が聞こえてくる</color>",
  ui_story_1022_10220902_53_dialog_content = "泣きながら…逃げちゃった…？",
  ui_story_1022_10220902_54_dialog_content = "フフ…悪い子を懲らしめるのも久しぶりだわ。\n恥ずかしいところを見せてしまったわね。",
  ui_story_1022_10220902_55_dialog_content = "あのファントムとワラーキ家との間にはちょっとした因縁があるの。\nそのうえペピータを痛めつけられたとあっては、私も抑えきれなかったわ。",
  ui_story_1022_10220902_56_dialog_content = "（またワラーキ家がらみ！？）",
  ui_story_1022_10220902_57_dialog_content = "ペピータ、傷の手当てをしましょう。",
  ui_story_1022_10220902_58_dialog_content = "このバッジ…ビクトリア様、もしかしてバッジを手がかりに、\n私を見つけてくださったんですか？",
  ui_story_1022_10220902_59_dialog_content = "そのバッジには私の術式が込められているの。\n人工心臓の力を引き出し、あなたの命とも深くつながっているものなのよ。",
  ui_story_1022_10220902_60_dialog_content = "だから、あなたが危険な目に遭えば、私にはすぐに分かる。",
  ui_story_1022_10220902_61_dialog_content = "あなたの想像通りよ、ペピータ。あなたが私をここまで導いたの。\nそして偶然にも結社の聖物を見つけることができたわ。",
  ui_story_1022_10221001_1_dialog_content = "そうだ！ビクトリア、カロンとは知り合いなんだよね？",
  ui_story_1022_10221001_2_dialog_content = "バイスがどこへ行ったか知ってる？\nどうして彼岸号の座標があちこち飛んでるの？",
  ui_story_1022_10221001_3_dialog_content = "ファントムに出くわしたりしてないよね！？",
  ui_story_1022_10221001_4_dialog_content = "そのことについては――あら？そちらの方、今度は何かしら？",
  ui_story_1022_10221001_5_dialog_content = "…！それはこちらのセリフだ。この者は白夜城の聖典を盗んだのだ。かばうつもりか？",
  ui_story_1022_10221001_6_dialog_content = "いや、そうだな。盗んだ聖典は今やお前たち結社の手中にあるはず…\n真理結社は邪悪の巣窟だ！",
  ui_story_1022_10221001_7_dialog_content = "ちょっと、あんたさっきから言いたい放題ね。",
  ui_story_1022_10221001_8_dialog_content = "双方譲らず、緊張がどんどん高まってくよ…\nあたし、どうすればいいんだろ…",
  ui_story_1022_10221001_9_dialog_content = "ペピータから聞かなかったのかしら？\n「聖典」はこの聖物と同様、もともと真理結社のものなのよ。",
  ui_story_1022_10221001_10_dialog_content = "でたらめを言うな！あれもこれも真理結社の物だと？\nアストラはお前たちが創ったとでも言うつもりか！？",
  ui_story_1022_10221001_11_dialog_content = "話が通じないのならば…剣で言う事を聞いてもらうしかないな。",
  ui_story_1022_10221001_12_dialog_content = "エリカ、行くぞ！",
  ui_story_1022_10221001_13_dialog_content = "はい！",
  ui_story_1022_10221001_14_dialog_content = "待って！",
  ui_story_1022_10221001_15_dialog_content = "…PlayerName、あなたの出る幕ではないわ。",
  ui_story_1022_10221001_16_dialog_content = "何としても、聖典の在処を聞き出さなければならないのよ。",
  ui_story_1022_10221001_17_dialog_content = "「聞き出す」なら話をすればいいでしょ？どうして武器を抜くの？\n城主様の意向を忘れたわけじゃないよね？",
  ui_story_1022_10221001_18_dialog_content = "それは…",
  ui_story_1022_10221001_19_dialog_content = "問題があるなら平和的な方法で解決しようよ。\n合同探索隊の活動に影響が出ないように…",
  ui_story_1022_10221001_20_dialog_content = "合同探索だと？君は誰と手を組んでいるのだ？",
  ui_story_1022_10221001_21_dialog_content = "！？",
  ui_story_1022_10221001_22_dialog_content = "ここへ来るまで君のことは多少なりとも信用していたのだ。\nそれが肝心な時になって異端組織側につくとは。",
  ui_story_1022_10221001_23_dialog_content = "「合同探索隊を組み、互いに協力し合う」だと？\nそんなもの、ただのきれいごとだ！",
  ui_story_1022_10221001_24_dialog_content = "どいてくれ。どかないのなら――",
  ui_story_1022_10221001_25_dialog_content = "どうするというのです？",
  ui_story_1022_10221001_26_dialog_content = "お前もか！",
  ui_story_1022_10221001_27_dialog_content = "PlayerNameは何も間違ったことは言っていません。\n暗面の探索こそ最重要事項――それが我々の大元帥と白夜城城主双方の意向です。",
  ui_story_1022_10221001_28_dialog_content = "質問があるのなら、剣を納めてからにしてください。",
  ui_story_1022_10221001_29_dialog_content = "…",
  ui_story_1022_10221001_30_dialog_content = "隊長…",
  ui_story_1022_10221001_31_dialog_content = "…異端者は…皆あの世へ行け！",
  ui_story_1022_10221002_1_dialog_content = "うっ…！はぁ…はぁ…",
  ui_story_1022_10221002_2_dialog_content = "（クッ…こいつ、強い…よりによって暗面で力をそがれてしまうとは…）",
  ui_story_1022_10221002_3_dialog_content = "に…逃がすか！",
  ui_story_1022_10221002_4_dialog_content = "主は啓示を下された。ペピータにはまだ輝かしい未来が待っているわ。",
  ui_story_1022_10221002_5_dialog_content = "私はこれで失礼するわ。真理の光の導きがあらんことを。",
  ui_story_1022_10221002_6_dialog_content = "…ふざけたことを！",
  ui_story_1022_10221002_7_dialog_content = "ビクトリア、待って！バイスはどこにいるの？まだ答えてもらってないよ！",
  ui_story_1022_10221002_8_dialog_content = "うわっ…ヒ、ヒイロさん？どうしたんですかって…うわああっ！\nと、飛んだ――",
  ui_story_1022_10221002_9_dialog_content = "静かに。飛んではいません。速く走っているだけです。",
  ui_story_1022_10221002_10_dialog_content = "これでビクトリアに追いつけるでしょう。",
  ui_story_1022_10221002_11_dialog_content = "あら？",
  ui_story_1022_10221002_12_dialog_content = "ビクトリア様、どうかされましたか？",
  ui_story_1022_10221002_13_dialog_content = "ペピータ、先に行っていてちょうだい。\nここにいると、また面倒なことに巻き込まれそうだわ。",
  ui_story_1022_10221002_14_dialog_content = "急いで。",
  ui_story_1022_10221002_15_dialog_content = "…わかりました！",
  ui_story_1022_10221002_16_dialog_content = "いました！",
  ui_story_1022_10221002_17_dialog_content = "ビクトリア、バイスの居場所を知ってるんでしょ！？",
  ui_story_1022_10221002_18_dialog_content = "焦ることはないわ。典籍の示す時さえ来れば、また会える。",
  ui_story_1022_10221002_19_dialog_content = "けれど今は…まだその時ではない。\nでは、また会いましょう。",
  ui_story_1022_10221002_20_dialog_content = "（バイスのこと、やっぱり知ってるんだ！）",
  ui_story_1022_10221002_21_option_content = "強制感知！",
  ui_story_1022_10221002_22_dialog_content = "フフ…",
  ui_story_1022_10221002_23_dialog_content = "こ、これは…",
  ui_story_1022_10221002_24_dialog_content = "<color=#e8d9bb>極夜の粘性の高い流体の中、巨大な氷の柱が空を突きさすようにそびえている</color>",
  ui_story_1022_10221002_25_dialog_content = "<color=#e8d9bb>その氷の柱の中に閉じ込められているのは――</color>",
  ui_story_1022_10221002_26_dialog_content = "…バイス！",
  ui_story_1022_10221002_27_dialog_content = "（ど、どういうこと？どうしてバイスが…）",
  ui_story_1022_10221002_28_option_content = "もう一度感知する",
  ui_story_1022_10221002_29_dialog_content = "この音色こそ真の芸術というものだ！\nまるで時空の境界線を突き抜けるようではないか！",
  ui_story_1022_10221002_30_dialog_content = "バイスさん、何をしているの？",
  ui_story_1022_10221002_31_dialog_content = "PlayerNameが危ない！このままじゃエンジニアの闇に飲み込まれてしまうわ…\nなんとかしなきゃ！",
  ui_story_1022_10221002_32_dialog_content = "ピアノの音色でPlayerNameの意識を呼び覚ますわ…",
  ui_story_1022_10221002_33_dialog_content = "エンジニアはPlayerNameを注視している。\n2人の意識は今つながっているの。",
  ui_story_1022_10221002_34_dialog_content = "下手に手を出せば、エンジニアがあなたの存在に気づくわ。",
  ui_story_1022_10221002_35_dialog_content = "でも――",
  ui_story_1022_10221002_36_dialog_content = "ビクトリア殿、情趣を解さないにも程がありはしないかな？",
  ui_story_1022_10221002_37_dialog_content = "この美しい音色を止め、我が友を暗黒の闇に捨て置けと？\n君の主とやらはそんな行為を賛美しているのかね？",
  ui_story_1022_10221002_38_dialog_content = "あら、あなたの口から主の名を聞くとは思わなかったわね。\nしかもエンジニアとやり合う準備ができているようじゃない。",
  ui_story_1022_10221002_39_dialog_content = "ついに長い反抗期を終えて、真理を胸に抱き、血脈に目覚めたのかしら？",
  ui_story_1022_10221002_40_dialog_content = "いったいどうしたらそんな結論に至るのだ！？\n私は君たちの讃える真理などにいっさい興味はない。",
  ui_story_1022_10221002_41_dialog_content = "それは残念ね。",
  ui_story_1022_10221002_42_dialog_content = "…やりました！PlayerNameが闇を抜け出しました！",
  ui_story_1022_10221002_43_dialog_content = "でも、ソラヴァンが…",
  ui_story_1022_10221002_44_dialog_content = "バイス、安心するがいい。PlayerNameはソラヴァンを見捨てはしない。\n私たちも彼を見捨てはしない。",
  ui_story_1022_10221002_45_dialog_content = "困ったわね。",
  ui_story_1022_10221002_46_dialog_content = "はて、今度は何事かな？",
  ui_story_1022_10221002_47_dialog_content = "真理結社の成員は全員真理の加護を受けている。\nけれど啓光の者たちは主に選ばれてはいない。",
  ui_story_1022_10221002_48_dialog_content = "それでも生身のまま危険に飛び込もうとするなら…\nこうするしかないわ。",
  ui_story_1022_10221002_49_dialog_content = "<color=#e8d9bb>ザザーン…</color>",
  ui_story_1022_10221002_50_dialog_content = "わっ！",
  ui_story_1022_10221002_51_dialog_content = "な、何だ！？",
  ui_story_1022_10221002_52_dialog_content = "<color=#e8d9bb>ビクトリアがさっと手を払うと、原始の河の流れが突然分かれた</color>",
  ui_story_1022_10221002_53_dialog_content = "<color=#e8d9bb>カロンとバイスは河の流れを通り抜け、まっすぐに下へと落ちていった</color>",
  ui_story_1022_10221002_54_dialog_content = "<color=#e8d9bb>耳元には神秘のささやきが響く――</color>",
  ui_story_1022_10221002_55_dialog_content = "原始の河の水を1滴でも注げば、\nどんなに強力な暗力もそれを溶かすことはできない。",
  ui_story_1022_10221002_56_dialog_content = "わあああああ…って、あら？止まった？",
  ui_story_1022_10221002_57_dialog_content = "…ここはどこ…？",
  ui_story_1022_10221002_58_dialog_content = "<color=#e8d9bb>瞬きをして改めて見てみると、そこには別の光景が広がっていた</color>",
  ui_story_1022_10221002_59_dialog_content = "<color=#e8d9bb>空は粘り気のある漆黒の闇に包まれ、微かに歪んでいる。\nまるで凸凹した分厚いガラスを通して空を仰いでいるようだ</color>",
  ui_story_1022_10221002_60_dialog_content = "<color=#e8d9bb>だがそれはガラスではなく――</color>",
  ui_story_1022_10221002_61_dialog_content = "氷？ど、どうして氷の中に閉じ込められているの！？",
  ui_story_1022_10221002_62_dialog_content = "あら？この音は…",
  ui_story_1022_10221002_63_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1022_10221002_64_dialog_content = "氷よ、砕けよ！凍てつく寒さも私のこの燃え上がる情熱を封じることなどできん！",
  ui_story_1022_10221002_65_dialog_content = "カロン長官！長官も氷の柱の中に閉じ込められたんですか？",
  ui_story_1022_10221002_66_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_1022_10221002_67_dialog_content = "<color=#e8d9bb>氷の柱が「彼岸号」の衝撃で砕け始めた</color>",
  ui_story_1022_10221002_68_dialog_content = "バイス、私の手をつかむのだ！",
  ui_story_1022_10221002_69_dialog_content = "はい！",
  ui_story_1022_10221002_70_dialog_content = "バイスさん。",
  ui_story_1022_10221002_71_dialog_content = "（今のは…錯覚かしら？ビクトリアさんに呼ばれた気がする）",
  ui_story_1022_10221002_72_dialog_content = "バイスさん、よく聞いて。",
  ui_story_1022_10221002_73_dialog_content = "PlayerNameはこれから過酷な試練を受けることになる。彼は――",
  ui_story_1022_10221002_74_dialog_content = "<color=#e8d9bb>まるで耳元で話しているかのように、ビクトリアの声は一字一句耳に入ってくる</color>",
  ui_story_1022_10221002_75_dialog_content = "！！",
  ui_story_1022_10221002_76_dialog_content = "バイス、何をしている？早くこちらへ！",
  ui_story_1022_10221002_77_dialog_content = "…",
  ui_story_1022_10221002_78_dialog_content = "カロン長官、先に行ってください。",
  ui_story_1022_10221002_79_dialog_content = "私は残ります。",
  ui_story_1022_10221002_80_dialog_content = "なにっ！？",
  ui_story_1022_10221002_81_dialog_content = "PlayerNameが私を必要としているんです…",
  ui_story_1022_10221002_82_dialog_content = "ここにいれば、きっと力になれます。",
  ui_story_1022_10221002_83_dialog_content = "<color=#FFB400>バイス</color>――！",
  ui_story_1022_10221002_84_dialog_content = "<color=#e8d9bb>僕は声をあげ、手を伸ばして、その笑顔を引き留めたかった。\nいっそのこと今すぐ彼女のそばに飛んでいきたい</color>",
  ui_story_1022_10221002_85_dialog_content = "<color=#e8d9bb>でも感知した画面はどんどん暗くなるばかりで――</color>",
  ui_story_1022_10221002_86_dialog_content = "<color=#e8d9bb>闇が深くなっていく</color>",
  ui_story_1022_10221002_87_dialog_content = "<color=#e8d9bb>まるで極夜のように</color>",
  ui_story_1022_10221002_88_dialog_content = "<color=#e8d9bb>彼女のいる所だけが光を放って――</color>",
  ui_story_1022_10221002_89_dialog_content = "<color=#e8d9bb>のしかかる闇と容赦なく襲う凍てつく寒さの中――</color>",
  ui_story_1022_10221002_90_dialog_content = "<color=#e8d9bb>光で辺りを照らし、まぶしく輝いている</color>",
  ui_story_1022_10221002_91_dialog_content = "<color=#e8d9bb>それはあたかも、極夜に太陽が昇ったかのようだった</color>",
  ui_story_1022_10221002_92_dialog_content = "（僕が感知したあの光力の塊はバイスだったのか…）",
  ui_story_1022_10221002_93_dialog_content = "（バイスがその魂で創ってくれた道しるべのおかげで、\n僕は暗闇の中でも行く先を見失わずに済んだんだ）",
  ui_story_1022_10221002_94_dialog_content = "（皆は僕をナビゲーターと呼ぶ。戦場で皆を導くことができるから）",
  ui_story_1022_10221002_95_dialog_content = "（でも、その僕を導いてくれていた光は、ずっとバイスだったんだ）",
  ui_story_1022_10221002_96_dialog_content = "（初めて会った日からずっと…）",
  ui_story_1022_10221101_1_dialog_content = "…PlayerName。",
  ui_story_1022_10221101_2_dialog_content = "PlayerName、しっかりしてください！",
  ui_story_1022_10221101_3_dialog_content = "ヒイロさん…",
  ui_story_1022_10221101_4_dialog_content = "…あ、バイス！バイスが氷の柱の中に閉じ込められているんです。\n感知したあの光力の塊はバイスだったんです！助けに行かないと！",
  ui_story_1022_10221101_5_dialog_content = "まずは水を飲んで落ち着いてください。\nゆっくり話してください。",
  ui_story_1022_10221101_6_dialog_content = "はい、ありがとうございます…",
  ui_story_1022_10221101_7_dialog_content = "それから1つお伝えすることがあります。\nビクトリアが突然姿を消しました。",
  ui_story_1022_10221101_8_dialog_content = "突然？",
  ui_story_1022_10221101_9_dialog_content = "あのビクトリアはおそらく最初から本体ではなかったのでしょう。",
  ui_story_1022_10221101_10_dialog_content = "うわあああん…おじい様、おじい様…",
  ui_story_1022_10221101_11_dialog_content = "もうイヤっ…うわああん！おじい様！なぜ私1人を残して逝ったのです？\nおじい様がいれば、<color=#FFB400>当主の長</color>にいじめられることもないのに…！",
  ui_story_1022_10221101_12_dialog_content = "おじい様…",
  ui_story_1022_10221101_13_dialog_content = "…",
  ui_story_1022_10221101_14_dialog_content = "でも、いいや…おじい様はもういない…恋しがっても無駄です。",
  ui_story_1022_10221101_15_dialog_content = "私にはペピータがいます。\nペピータは心から私を大切にしてくれます！",
  ui_story_1022_10221101_16_dialog_content = "けれど、そのペピータも当主の長に奪われてしまいました…",
  ui_story_1022_10221101_17_dialog_content = "<size=50>うわあああああん！</size>",
  ui_story_1022_10221101_18_dialog_content = "言ったでしょう？\nペピータが去ったのは、他ならぬあなた自身のせいだと。",
  ui_story_1022_10221101_19_dialog_content = "！？",
  ui_story_1022_10221101_20_dialog_content = "たまには頭を使ったらどう？\n生まれてこのかた頭を使う機会はそう多くなかったようだけど…",
  ui_story_1022_10221101_21_dialog_content = "このままサビつかせてしまってはもったいない。そうでしょう？",
  ui_story_1022_10221101_22_dialog_content = "除名された<color=#FFB400>第十三家当主の「お嬢さん」</color>。",
  ui_story_1022_10221101_23_dialog_content = "…そ、それを…よくも！",
  ui_story_1022_10221101_24_dialog_content = "愚か者め！卑しい者の血を我が孫娘に飲ませようとするとは！",
  ui_story_1022_10221101_25_dialog_content = "ウルスラには卑しさと愚かさの味が分かるのだ！\nお前たちは孫娘を殺す気か！？",
  ui_story_1022_10221101_26_dialog_content = "も、申し訳ございません！",
  ui_story_1022_10221101_27_dialog_content = "うわああん、うわああああん！",
  ui_story_1022_10221101_28_dialog_content = "よしよし、いい子だ。泣くんじゃないよ。\n私がふさわしい血畜を探してくるからね。",
  ui_story_1022_10221101_29_dialog_content = "最も甘美な血で、お前のその輝く天賦を満たしてあげよう…",
  ui_story_1022_10221101_30_dialog_content = "<color=#e8d9bb>ガシャン！テーブルに並べてあった食器がことごとく床に落ち、粉々になった</color>",
  ui_story_1022_10221101_31_dialog_content = "当主様！いかがなされましたか？\n何かお気に召さないことがございましたでしょうか？",
  ui_story_1022_10221101_32_dialog_content = "なぜです？今日の「獲物」はなぜこれっぽちなのですか！？\nおじい様が生きていたら、こんなバカにした真似はしないでしょう！？",
  ui_story_1022_10221101_33_dialog_content = "それは…平民の「消費」が速すぎますと、\n生産が途絶え、多くの者が食糧に困ることになり…",
  ui_story_1022_10221101_34_dialog_content = "食糧がないなら、ケーキを食べればいいでしょう？\nそんな些細な事まで私に言われなければできませんか？",
  ui_story_1022_10221101_35_dialog_content = "は、はい…あらためて手配いたします。",
  ui_story_1022_10221101_36_dialog_content = "逃げろ…！！",
  ui_story_1022_10221101_37_dialog_content = "ハハハハ！こうでなくては狩りは面白くありません！",
  ui_story_1022_10221101_38_dialog_content = "さあさあ、逃げてください。急いで、遠くへ逃げてください。\n心配しなくていいのですよ…",
  ui_story_1022_10221101_39_dialog_content = "一人残ら～ず探し出して、きちんと遊んであげますから。",
  ui_story_1022_10221101_40_dialog_content = "誰1人として…さみしい思いはさせませんよ。",
  ui_story_1022_10221101_41_dialog_content = "昔はよかった…誰でも私の言う事を聞いて、皆私と遊んでくれました…",
  ui_story_1022_10221101_42_dialog_content = "全部ワラーキのせいです。\n「当主の長」が…全部台無しにしたのです！",
  ui_story_1022_10221101_43_dialog_content = "お前たちが私を「日蝕」に追い込んだのですよ。一日中ただひたすら眠り、\n誰も相手にしてくれず、皆私に逆らう…",
  ui_story_1022_10221101_44_dialog_content = "それもこれも全部お前たちのせいです！",
  ui_story_1022_10221101_45_dialog_content = "また他人のせいにするのね。",
  ui_story_1022_10221101_46_dialog_content = "除名はあなた自身の残虐さと反逆が招いた結果よ。",
  ui_story_1022_10221101_47_dialog_content = "暗鬼の大軍を率いてワラーキ村に攻め込み、無数の信徒を惨殺、結社の聖物を奪った。\nワラーキの歴史上最も残虐を極めた事件だった。",
  ui_story_1022_10221101_48_dialog_content = "古い書籍で知っただけだけど、あなたの行動にはこの私も驚きと恐怖を覚えたわ…",
  ui_story_1022_10221101_49_dialog_content = "黙れ！黙れ黙れ黙れ！光霊を殺したからといって、それが何だというのです！\nお前は殺したことがないとでも？",
  ui_story_1022_10221101_50_dialog_content = "おじい様は私が楽しく遊べてさえいれば、喜んでくださった…\nそれなのに、お前たちはあれやこれやとやかましい！",
  ui_story_1022_10221101_51_dialog_content = "「当主の長」だからといって、私にあれこれ指示できると思わないでください…",
  ui_story_1022_10221101_52_dialog_content = "ちゃんとこの命を燃やせたなら、死ぬことくらい…なんてことない。",
  ui_story_1022_10221101_53_dialog_content = "私は誰かのペットじゃない。誰にも屈しない…",
  ui_story_1022_10221101_54_dialog_content = "<color=#FFB400>私は…私だ！</color>",
  ui_story_1022_10221101_55_dialog_content = "…私は私です！お前になど屈しません！",
  ui_story_1022_10221101_56_dialog_content = "ペピータの信念を間違って理解しているようね。\n彼女が知ったら、どんな顔をするかしら。",
  ui_story_1022_10221101_57_dialog_content = "ペピータの名前を口にしないでください！",
  ui_story_1022_10221101_58_dialog_content = "<color=#e8d9bb>ヒステリックな叫び声と共に濃い暗力が噴き出した</color>",
  ui_story_1022_10221101_59_dialog_content = "<color=#e8d9bb>暗力はウルスラを包み、さらにブクブクと四方にあふれ出して真っ黒な氷の層を覆い尽くした</color>",
  ui_story_1022_10221101_60_dialog_content = "<color=#e8d9bb>無数の肉の芽がうねりながら氷の層をうがち、裂けては分かれ、\n巨大な異様な形をしたサンゴの森を造り出した</color>",
  ui_story_1022_10221101_61_dialog_content = "<color=#e8d9bb>その枝は互いに絡み合い、まるで変形した血管網のようであり、\n毒に犯された筋肉のようでもあった</color>",
  ui_story_1022_10221101_62_dialog_content = "<color=#e8d9bb>ドクッ、ドクッ</color>",
  ui_story_1022_10221101_63_dialog_content = "<color=#e8d9bb>サンゴの森――その巨大な生命体は黒い霧の奥にある鼓動と同じ拍を刻んでいる</color>",
  ui_story_1022_10221101_64_dialog_content = "<color=#e8d9bb>拍を刻むたびに、粘り気のある暗力を放ち、その領域内にいるすべての光霊の命を腐らせる</color>",
  ui_story_1022_10221101_65_dialog_content = "グア――！！！",
  ui_story_1022_10221102_1_dialog_content = "<color=#e8d9bb>パリンッ…</color>",
  ui_story_1022_10221102_2_dialog_content = "<color=#e8d9bb>ウルスラの暗力の殻が砕けた。けれどビクトリアもまた代償を払っていた</color>",
  ui_story_1022_10221102_3_dialog_content = "ゲホッ、ゲホ――！",
  ui_story_1022_10221102_4_dialog_content = "ハハ、ハハハ…アハハハハ！何が当主の長です？この程度ですか。",
  ui_story_1022_10221102_5_dialog_content = "少し本気を出したら、すぐにへたってしまいましたね。",
  ui_story_1022_10221102_6_dialog_content = "けれど、それもそのはずです。私はものすご～く幼い時に血脈に目覚めたのですから。\nおじい様も私ほど天賦に恵まれた者は見たことないと言っていましたよ。",
  ui_story_1022_10221102_7_dialog_content = "おばさんはどうだったのです？\nまさか棺桶に片足突っ込んだ頃にようやく目覚めたのではないでしょうね？アハハハハ！",
  ui_story_1022_10221102_8_dialog_content = "…フフ。",
  ui_story_1022_10221102_9_dialog_content = "何がおかしいのですっ！？",
  ui_story_1022_10221102_10_dialog_content = "私は血族の長い歴史の中でも覚醒が最も早かった者なのですよ。\nそれは最も優れた天賦、最も純粋な力の証――お前は到底私に及びません。",
  ui_story_1022_10221102_11_dialog_content = "いっそのこと当主の長の座を私に譲ったらどうですか？アハハハ――",
  ui_story_1022_10221102_12_dialog_content = "<color=#e8d9bb>ウルスラの高笑いが突然とまった</color>",
  ui_story_1022_10221102_13_dialog_content = "<color=#e8d9bb>ウルスラが驚いた表情でビクトリアを見つめる視線の先では、\nビクトリアの傷が一つ一つ癒えていき、破れていた服までも元の状態に戻っていった</color>",
  ui_story_1022_10221102_14_dialog_content = "ど、どういうことです…！？",
  ui_story_1022_10221102_15_dialog_content = "聞くまでもないでしょう？あなたの天賦をもってすれば、見抜けるはずよ。",
  ui_story_1022_10221102_16_dialog_content = "…！！ま、まさか大量の力を別の所に…いったい何をしているのですか？",
  ui_story_1022_10221102_17_dialog_content = "彼らを原始の河から落としたの。\n暗面は何といっても危険でしょう？面倒を見てあげないとね。",
  ui_story_1022_10221102_18_dialog_content = "…間違った道に進みさえしなければ、あなたも主の加護を受けられていたのだけれど。",
  ui_story_1022_10221102_19_dialog_content = "私と戦いながら、他の者たちの面倒まで見ていたと…？\nあり得ません、そんなことできるはずはありません！",
  ui_story_1022_10221102_20_dialog_content = "私こそ最強なのです…最も早くに覚醒し、最も優れた天賦と最も純粋な力を持つ…\nき、きっと汚い手を使ったに違いありません！",
  ui_story_1022_10221102_21_dialog_content = "あなたが出した答えはそれだけかしら？\nどうやら本当に覚醒が<color=#FFB400>早すぎた</color>ようね。",
  ui_story_1022_10221102_22_dialog_content = "え？",
  ui_story_1022_10221102_23_dialog_content = "覚醒が早すぎたのよ。そのせいで力があまりにも純粋、単純で原始的だわ。\nあなたの力には理性による鍛錬の欠片も感じられない。",
  ui_story_1022_10221102_24_dialog_content = "ウルスラ、あなたは強い。\nけれど、それは血族の最も原始的な欲望を代表するもの――",
  ui_story_1022_10221102_25_dialog_content = "そして私はその正反対――あなたとかけ離れた所にいるの。",
  ui_story_1022_10221102_26_dialog_content = "ど、どういう意味ですか…？",
  ui_story_1022_10221102_27_dialog_content = "私は、あなたよりもずっと遅くに覚醒した。",
  ui_story_1022_10221102_28_dialog_content = "真理を悟るために、様々なものを見、考え、理解し、長い道のりを歩んできた。",
  ui_story_1022_10221102_29_dialog_content = "あなたの経験したことのない、想像もできない道のりを歩んできたのよ。",
  ui_story_1022_10221102_30_dialog_content = "私の秘法がいかに奥深く複雑か、それはもう…想像するしかでしょうね。",
  ui_story_1022_10221102_31_dialog_content = "あなたには永遠に理解できないのだから。",
  ui_story_1022_10221102_32_dialog_content = "そ、そんなはずはありません。私こそ最強なのです…！",
  ui_story_1022_10221102_33_dialog_content = "<color=#e8d9bb>どんなに叫び声をあげようと、ウルスラは恐怖を抑えることができなかった。\nウルスラは天賦に――恵まれすぎていたのだ</color>",
  ui_story_1022_10221102_34_dialog_content = "<color=#e8d9bb>彼女の心も、目も、魂もある一つの悟りによる激痛に襲われていた。その悟りとは――</color>",
  ui_story_1022_10221102_35_dialog_content = "<color=#FFB400>「法則」</color>…",
  ui_story_1022_10221102_36_dialog_content = "<color=#e8d9bb>それは真理のために、身も心もつぎ込んできた光霊がたどり着いた境地――</color>",
  ui_story_1022_10221102_37_dialog_content = "<color=#e8d9bb>原始を超越し、純粋さを超越して、ただ一心に求める心で真理に捧げた賛歌だ</color>",
  ui_story_1022_10221102_38_dialog_content = "いい答えね、ウルスラ。次はお勉強の時間よ。",
  ui_story_1022_10221102_39_dialog_content = "その目を見開いて、しっかりと見ておくのよ――私の秘法を。",
  ui_story_1022_10221102_40_dialog_content = "そしてこれは、主への捧げものでもある――",
  ui_story_1022_10221102_41_dialog_content = "うわああああああ――",
  ui_story_1022_10221102_42_dialog_content = "な、なぜです？私はとうの昔に「日蝕」の印を受けたというのに、なぜ…",
  ui_story_1022_10221102_43_dialog_content = "…光霊に戻っているのですか！？",
  ui_story_1022_10221102_44_dialog_content = "イヤ…イヤだ…死にたくない、消えたくない…",
  ui_story_1022_10221102_45_dialog_content = "やめてっ！！！",
  ui_story_1022_10221102_46_dialog_content = "実に恐ろしい秘法だな…なるほど、これこそ「救い」というわけか。",
  ui_story_1022_10221102_47_dialog_content = "君は「虚構」の物質を否定し、純粋なる「本質」を「意識」の主に捧げるというのだな？",
  ui_story_1022_10221102_48_dialog_content = "ふっ、いや違うな。恐ろしいのは君だ、ビクトリア。",
  ui_story_1022_10221102_49_dialog_content = "この私さえも利用するとは。君には恐れるものがないのか？",
  ui_story_1022_10221102_50_dialog_content = "<color=#e8d9bb>きらめく河の流れが果てなく続いている。\nこの河の中では、時間さえも意味をもたない</color>",
  ui_story_1022_10221102_51_dialog_content = "<color=#e8d9bb>隠者の目の前には、無数の過去と未来が平等に列をなし、\nそこには「並行する自身」の姿もあった</color>",
  ui_story_1022_10221102_52_dialog_content = "まぁいい…来るがいい。",
  ui_story_1022_10221102_53_dialog_content = "<color=#e8d9bb>隠者が手をたたくと、宙に隙間が生まれ、突然現れた機関車が宙を引き裂いた</color>",
  ui_story_1022_10221102_54_dialog_content = "うおおおおお――",
  ui_story_1022_10221102_55_dialog_content = "静かにしろ。私は長い間1人で過ごしてきた。\n騒がしいのは好かん。",
  ui_story_1022_10221102_56_dialog_content = "この河はいったいどうなっているのだ？そして君は誰だ？\n待て…君には会ったことがある。",
  ui_story_1022_10221102_57_dialog_content = "…まさか父の従兄弟でビクトリアの叔父…とうに他界したはずの、\n<color=#FFB400>ヴィルヘルム・ワラーキ</color>か？",
  ui_story_1022_10221102_58_dialog_content = "なんとまどろっこしい。「叔父さま」と呼べばいいものを。",
  ui_story_1022_10221102_59_dialog_content = "このような奇怪な場所で、とうに他界したはずの者に出会って、\nすぐに親しく呼び合うことこそ奇妙というものだ。",
  ui_story_1022_10221102_60_dialog_content = "…まったく。ビクトリアと同じく面倒な奴だな。",
  ui_story_1022_10221102_61_dialog_content = "何を言っている？私はあの訳の分からぬ女とは違う！",
  ui_story_1022_10221102_62_dialog_content = "兄の子の面倒を見終わったと思ったら、今度は友人の子の面倒とは。\n我が家の家紋も哺乳瓶と揺りかごに変えるべきか。",
  ui_story_1022_10221102_63_dialog_content = "君の名は覚えているぞ――カロン。\nなぜここへ来たか分かるか？",
  ui_story_1022_10221102_64_dialog_content = "君の仕業ではないのか？",
  ui_story_1022_10221102_65_dialog_content = "ビクトリアは君が私に秘法を学び、真理を悟ることを望んでいる。\n君にはその素質があると見抜いたのだ。",
  ui_story_1022_10221102_66_dialog_content = "なに！？そのことならとうの昔に断っている。興味はない。",
  ui_story_1022_10221102_67_dialog_content = "ビクトリアにそう答えた時、君は確かに興味を抱いていなかった。",
  ui_story_1022_10221102_68_dialog_content = "だが河の流れはすでに先へと進み、今君は再び河の中へ戻った。\n君はもう以前の君ではない。今の考えはどうかな？",
  ui_story_1022_10221102_69_dialog_content = "私は…",
  ui_story_1022_10221102_70_dialog_content = "<color=#e8d9bb>「もちろん変わらず興味はない」――そんな言葉がカロンののどまで出かかった</color>",
  ui_story_1022_10221102_71_dialog_content = "<color=#e8d9bb>だが、その時頭の中に氷の柱の中にいるバイスの姿が浮かんだ。\n部下は今、暗鬼のうごめく極夜の中にいるのだ</color>",
  ui_story_1022_10221102_72_dialog_content = "<color=#e8d9bb>その部下は空の末裔のために残ると言った。\n空の末裔と彼と行動を共にしている啓光の同僚たちも危険な状況に陥っているに違いない</color>",
  ui_story_1022_10221102_73_dialog_content = "<color=#e8d9bb>ならば…</color>",
  ui_story_1022_10221102_74_dialog_content = "…反抗期もそろそろ卒業すべき時が来たかもしれん。",
  ui_story_1022_10221102_75_dialog_content = "ふっ。己の反抗期に気づいているだけ、誰かさんより救いがあるな。",
  ui_story_1022_10221102_76_dialog_content = "今回はありもしない命を賭ける必要はないだろう。",
  ui_story_1022_10221200_1_dialog_content = "…",
  ui_story_1022_10221200_2_dialog_content = "（氷の洞窟…そうだ、私…最初の臨時基地に戻ってすぐに、\n力が抜けてそのまま眠りこけちゃったんだ）",
  ui_story_1022_10221200_3_dialog_content = "（ビクトリア様はたぶんウルスラを追っていったよね。私も行かなきゃ…）",
  ui_story_1022_10221200_4_dialog_content = "クッ！宝物も逃亡犯も目の前にしながら、このようなしくじりをするとは！",
  ui_story_1022_10221200_5_dialog_content = "（ええ～っ？なんでアイツが？よかった、慌てて出て行かなくて）",
  ui_story_1022_10221200_6_dialog_content = "隊長、むやみに動いちゃいけません。傷口が開きます。",
  ui_story_1022_10221200_7_dialog_content = "（エリカ…私がケガした時も、心配そうな顔してたな）",
  ui_story_1022_10221200_8_dialog_content = "エリカ、傷は大丈夫だ。\nそれよりもそこの招かざる客人よ、いったい何の用だ？",
  ui_story_1022_10221200_9_dialog_content = "お伝えしたはずです。お力添えをしにきました。",
  ui_story_1022_10221200_10_dialog_content = "（もう1人いたの…？なんの気配も感じなかった…）",
  ui_story_1022_10221200_11_dialog_content = "力添えだと？私たち全員でペピータを取り囲んでも取り逃したのだ。\n君に何ができる？",
  ui_story_1022_10221200_12_dialog_content = "（え？私のこと話してるの？）",
  ui_story_1022_10221200_13_dialog_content = "もちろん確実な方法でお力添えします。",
  ui_story_1022_10221200_14_dialog_content = "こちらを。",
  ui_story_1022_10221200_15_dialog_content = "リモコン？まさかボタンを押せば、ペピータの動きを止めることができるとでも言うのか？",
  ui_story_1022_10221200_16_dialog_content = "その通りです。",
  ui_story_1022_10221200_17_dialog_content = "…からかっているのか？",
  ui_story_1022_10221200_18_dialog_content = "いいえ、嘘は言っておりません。今リモコンとおっしゃった装置は、\nベリサリアが当時残しておいた保険です。",
  ui_story_1022_10221200_19_dialog_content = "ペピータの人工心臓をコントロールするものです。",
  ui_story_1022_10221200_20_dialog_content = "！！",
  ui_story_1022_10221200_21_dialog_content = "ペピータの心臓って…人工心臓だったの？",
  ui_story_1022_10221200_22_dialog_content = "このボタンを押せば、人工心臓はただちにその動きを止めます。\n結果どうなるかは…申し上げるまでもないでしょう。",
  ui_story_1022_10221200_23_dialog_content = "これほど確実に、永遠に「動きを止める」ことのできる方法が他にありますか？",
  ui_story_1022_10221200_24_dialog_content = "何を言っている！何が「動きを止める」だ、殺人ではないか！",
  ui_story_1022_10221200_25_dialog_content = "死者が潔白無罪であった時にのみ、この行為は「殺人」と呼べます。",
  ui_story_1022_10221200_26_dialog_content = "死者が罪人であるのなら、「処刑」です。",
  ui_story_1022_10221200_27_dialog_content = "何の違いがあるのだ…？",
  ui_story_1022_10221200_28_dialog_content = "当時ペピータが啓光に背き逃亡した時、\nベリサリアの手にはこの装置が握られていました。",
  ui_story_1022_10221200_29_dialog_content = "しかし彼女は罪人の後ろ姿が遠ざかっていくのを見つめるばかりで手を下しませんでした。\n本当に…失望させられましたね。",
  ui_story_1022_10221200_30_dialog_content = "（ベリサリア…）",
  ui_story_1022_10221200_31_dialog_content = "しかしあなたはあの名前だけの「鉄仮面」とは違うと信じています。",
  ui_story_1022_10221200_32_dialog_content = "白夜城に仇なす罪人を前にした、あなたの覚悟は正真正銘のものです。",
  ui_story_1022_10221200_33_dialog_content = "私は…",
  ui_story_1022_10221200_34_dialog_content = "ダメです！",
  ui_story_1022_10221200_35_dialog_content = "隊長、こんなやり方…間違ってます！\nペピータは確かに間違ったことをしたかもしれないけど、悪人じゃありません！",
  ui_story_1022_10221200_36_dialog_content = "あたしは心の友だから…目を見れば、わかるんです。",
  ui_story_1022_10221200_37_dialog_content = "生涯に一度も間違いを犯さない人なんているんでしょうか？神の教えにもあるでしょう？\nたとえ罪人と言えど、悔い改める機会を与えるべきだって！",
  ui_story_1022_10221200_38_dialog_content = "エリカ…！",
  ui_story_1022_10221200_39_dialog_content = "何者です！？",
  ui_story_1022_10221200_40_dialog_content = "ペピータ！？なぜここに――",
  ui_story_1022_10221200_41_dialog_content = "見間違いでしょ？いないいない、どうぞ話を続けて。",
  ui_story_1022_10221200_42_dialog_content = "…追え！",
  ui_story_1022_10221200_43_dialog_content = "ペピータ、逃げないで、止まって！",
  ui_story_1022_10221200_44_dialog_content = "あんたの上司がリモコンを捨てたら止まってあげるよ！",
  ui_story_1022_10221200_45_dialog_content = "ペピータ！あたしがそんなことさせないから、待って――",
  ui_story_1022_10221200_46_dialog_content = "そういうコトは昇進してから言いなよ。",
  ui_story_1022_10221200_47_dialog_content = "ペピータ、その先は――",
  ui_story_1022_10221200_48_dialog_content = "いくら叫んでも無駄だって。私、止まんないから…うわっ！",
  ui_story_1022_10221200_49_dialog_content = "<color=#e8d9bb>刺すような冷たい風が足下から巻き上がり、あと少しでペピータを吹き飛ばすところだった</color>",
  ui_story_1022_10221200_50_dialog_content = "<color=#e8d9bb>一歩先には、底の見えない崖が横たわっている</color>",
  ui_story_1022_10221200_51_dialog_content = "ペピータ、気を付けて！",
  ui_story_1022_10221200_52_dialog_content = "…こないで。",
  ui_story_1022_10221200_53_dialog_content = "わかった、行かない。\nだからペピータもそこを動かないで、話を聞いて。",
  ui_story_1022_10221200_54_dialog_content = "城主様があんたを罰しないって言ってくれたんだよ。\n聖典に関する手がかりを教えてくれれば、あたしが――",
  ui_story_1022_10221200_55_dialog_content = "あんたが何か保証してくれんの？それとも城主？",
  ui_story_1022_10221200_56_dialog_content = "それは…",
  ui_story_1022_10221200_57_dialog_content = "エリカ、あんたは何も保証できないでしょ？\n城主が約束を守ってくれるのを祈ることしかできないじゃん。",
  ui_story_1022_10221200_58_dialog_content = "それでもありがとう。ただごめん。\n私はあんたのトコの偉いおじさんの好意に期待しながら暮らす気はないの。",
  ui_story_1022_10221200_59_dialog_content = "<color=#FFB400>我に自由を、しからずんば死を！</color>",
  ui_story_1022_10221200_60_dialog_content = "<color=#e8d9bb>ペピータは少しの迷いもなく、崖に飛び込んだ</color>",
  ui_story_1022_10221200_61_dialog_content = "ペピータ！！",
  ui_story_1022_10221200_62_dialog_content = "<color=#e8d9bb>エリカは崖まで飛んで行ったが、そこには雲と霧が渦巻くだけで、どこにもペピータの姿はなかった</color>",
  ui_story_1022_10221200_63_dialog_content = "…",
  ui_story_1022_10221200_64_dialog_content = "最後の最後までボタンを押さず、絶好の機会をみすみす逃しましたね。",
  ui_story_1022_10221200_65_dialog_content = "2度も人を見誤るとは、私も反省が必要なようです。",
  ui_story_1022_10221200_66_dialog_content = "…エリカの言う通りだ。彼女は過ちを犯したが、死に値する者ではない…\n私は…己の私怨に囚われて人を殺めるようなことはしない！",
  ui_story_1022_10221200_67_dialog_content = "君は…いったい何者だ？",
  ui_story_1022_10221200_68_dialog_content = "覚悟はなくとも、好奇心は旺盛なようですね。\n白夜城の異端調査団も所詮この程度ということですか。",
  ui_story_1022_10221200_69_dialog_content = "あなた方は手をお引きください。",
  ui_story_1022_10221200_70_dialog_content = "この件は、啓光<color=#FFB400>「執行人」</color>組織が正式に引き継ぎます。",
  ui_story_1022_10221200_71_dialog_content = "<color=#e8d9bb>暗面の奥深くにある氷の洞窟の前では、稲妻のような火花が光っていた</color>",
  ui_story_1022_10221200_72_dialog_content = "何が起こったのだ…？なぜ…「再構成」されたのか？",
  ui_story_1022_10221200_73_dialog_content = "闇夜、凍てつく寒さ、暗力…ああ、「日蝕」よ。戻ったぞ！\n我が神よ、感謝申し上げます…",
  ui_story_1022_10221200_74_dialog_content = "神の御慈悲によって戻ってこれたことは自覚しているのですね。",
  ui_story_1022_10221200_75_dialog_content = "…",
  ui_story_1022_10221200_76_dialog_content = "フン、皆様お揃いというわけか。",
  ui_story_1022_10221200_77_dialog_content = "当然です。長い間待っていたのですよ。ただ、あなたにもう少し力があれば、\n我々もこれほど多くの無駄な時間を費やすこともなかったのですが。",
  ui_story_1022_10221200_78_dialog_content = "アスモデウス、ずいぶんと大きな口をきくな。\n私はあの方のため敵陣に突入したが、お前は何をしたというのだ？",
  ui_story_1022_10221200_79_dialog_content = "今すぐカナン城へ戻れと言われたとしても、私は二つ返事で従うぞ。",
  ui_story_1022_10221200_80_dialog_content = "その無鉄砲な勇敢さだけがあなたの強みでしょう？",
  ui_story_1022_10221200_81_dialog_content = "…どういう意味だ？",
  ui_story_1022_10221200_82_dialog_content = "それはそうと、なぜそいつがここにいるのだ？\n8大ファントムの会議に参加する資格などなかろう。",
  ui_story_1022_10221200_83_dialog_content = "…",
  ui_story_1022_10221200_84_dialog_content = "フィジェロ、知っていますか？\n「日蝕」で地位を上げるには1つの方法しかありません。",
  ui_story_1022_10221200_85_dialog_content = "新たに何者かを抜擢しようとするなら、\n必ず誰か1人古い者が消えなければならないのです。",
  ui_story_1022_10221200_86_dialog_content = "「日蝕」のファントムの席は8つ――7つでも、9つでもないのです。",
  ui_story_1022_10221200_87_dialog_content = "そ、それが何だというのだ？\n私が聞いているのは、ノラがなぜここにいるかということだ！",
  ui_story_1022_10221200_88_dialog_content = "賢者が愚か者の下につく必要はありません。\nノラの成し遂げたことはあなたのした事よりもはるかに重要です。",
  ui_story_1022_10221200_89_dialog_content = "「昇進」の<color=#FFB400>材料</color>を存分に享受するのは、\nノラに与えられて当然の褒美です。",
  ui_story_1022_10221200_90_dialog_content = "！！！",
  ui_story_1022_10221200_91_dialog_content = "ど、どういうことだ？誰だ？誰が私を縛りつけた？放せ！",
  ui_story_1022_10221200_92_dialog_content = "…こういう光景は見たくありません。先に中に入っています。",
  ui_story_1022_10221200_93_dialog_content = "フ。私もここにいる必要はありません。\nノラ、事が済んだら中へ入りなさい。会議が始まります。",
  ui_story_1022_10221200_94_dialog_content = "…",
  ui_story_1022_10221200_95_dialog_content = "…",
  ui_story_1022_10221200_96_dialog_content = "キッ、キキキキキッ！全員かかれ、奴を片付けろ！",
  ui_story_1022_10221200_97_dialog_content = "グア！！！",
  ui_story_1022_10221200_98_dialog_content = "…",
  ui_story_1022_10221200_99_dialog_content = "強くなったのか…だが、それがどうした？\nお前にその胆力が、覚悟があるのか？",
  ui_story_1022_10221200_100_dialog_content = "今日私を食うことは、将来お前も何者かに食われる運命を受け入れるということだぞ…",
  ui_story_1022_10221200_101_dialog_content = "お前よりも強く、皆からの賛美を受ける暗鬼が現れた時、\nお前はその者がのし上がるためのエサとなるのだ…",
  ui_story_1022_10221200_102_dialog_content = "その勇気があるのか？そこまで落ちれば、二度と後戻りはできないぞ？",
  ui_story_1022_10221200_103_dialog_content = "…お前にはまだ心に掛けている光霊がいるのだろう？",
  ui_story_1022_10221200_104_dialog_content = "…",
  ui_story_1022_10221200_105_dialog_content = "おしゃべりはそれでおしまい？",
  ui_story_1022_10221200_106_dialog_content = "ウルスラの…動きがありません。",
  ui_story_1022_10221200_107_dialog_content = "それでも功を立てたといえるでしょう。ウルスラが命を削ってくれたおかげで、\n私たちもようやく「あの者」の秘法を知ることができたのですから。",
  ui_story_1022_10221200_108_dialog_content = "見せ場はこれからですよ。",
  ui_story_1022_10221200_109_dialog_content = "…来ました。",
  ui_story_1022_10221200_110_dialog_content = "え？",
  ui_story_1022_10221200_111_dialog_content = "<color=#e8d9bb>薄暗がりからゆっくりと現れた姿がそこにいた者すべての視線を惹きつけた</color>",
  ui_story_1022_10221200_112_dialog_content = "…",
  ui_story_1022_10221200_113_dialog_content = "さすがは期待の新人ですね。フフフ…\nフィジェロよりもずっと有能です。",
  ui_story_1022_10221200_114_dialog_content = "いいえ、私が言ったのは…ウルスラのことです。",
  ui_story_1022_10221200_115_dialog_content = "…",
  ui_story_1022_10221200_116_dialog_content = "「<color=#FFB400>X物質</color>」を抜き取られ、心臓は消えてなくなり、\n肉体もほぼ砕け散りましたが…まだ生きています。しかもゆっくりと回復しています。",
  ui_story_1022_10221200_117_dialog_content = "それは、ウルスラが血族だったからでしょうか？\nもともと一度「本質」――不純な「<color=#FFB400>N物質</color>」に汚染されていました。",
  ui_story_1022_10221200_118_dialog_content = "だから後から注入した「虚構」が奪われようと、\nまだ生き続けることができているのですか。",
  ui_story_1022_10221200_119_dialog_content = "彼女が作り出したサンゴの枝さえ戻せば、\n「虚構」の…「<color=#FFB400>X</color>」の力は戻り、心臓が再び動き出します。",
  ui_story_1022_10221200_120_dialog_content = "<color=#e8d9bb>チチ、チチチ！チチチッ！</color>",
  ui_story_1022_10221200_121_dialog_content = "魔獣ちゃん、静かにして。もう少し寝させて…",
  ui_story_1022_10221200_122_dialog_content = "え…？魔獣ちゃん！？",
  ui_story_1022_10221200_123_dialog_content = "あんたが助けてくれたの？どうやって逃げてきたのよ？\nウルスラは…まさか、死んだの！？",
  ui_story_1022_10221200_124_dialog_content = "いやいや、落ち着け、私！魔獣ちゃんがまだ動けてるってことはウルスラは生きてる。\nでも逃げてこられたってことは、ウルスラに何かあった…",
  ui_story_1022_10221200_125_dialog_content = "…って、なんで私ウルスラの心配してんの！？",
  ui_story_1022_10221200_126_dialog_content = "ああ、生死不明のウルスラに、生き返ったペピータ…\nお騒がせ者同士、ホントお似合いだぁ。",
  ui_story_1022_10221200_127_dialog_content = "<color=#e8d9bb>チチチッ！ペディはペピータの足にまとわりつき、異常に興奮していた</color>",
  ui_story_1022_10221200_128_dialog_content = "わかったわかった。元のご主人様が心配なのね…\nえ？そうじゃない？だったら――うわっ！",
  ui_story_1022_10221200_129_dialog_content = "<color=#e8d9bb>宙に裂け目ができたかと思うと、その隙間から蒸気機関車が轟音と共に飛び出してきた</color>",
  ui_story_1022_10221200_130_dialog_content = "き、きききき…機関車！？",
  ui_story_1022_10221200_131_dialog_content = "この荒涼たる暗面において、\n客好きの車掌は取り残された光霊を決して見捨てはしない。",
  ui_story_1022_10221200_132_dialog_content = "いかがかな、お嬢さん。この華麗なる汽車に乗ってみないかね？"
}
return config
